INSERT INTO public."ConversationIntroSlot" (id, slot, question, "sortOrder", "createdAt", "updatedAt") VALUES (39, 'Tên', 'お名前は？', 0, '2026-10-16 09:16:51.792', '2026-10-16 09:16:51.792');
INSERT INTO public."ConversationIntroSlot" (id, slot, question, "sortOrder", "createdAt", "updatedAt") VALUES (40, 'Quốc tịch / quê', 'どこの国の人ですか。', 1, '2026-10-16 09:16:51.795', '2026-10-16 09:16:51.795');
INSERT INTO public."ConversationIntroSlot" (id, slot, question, "sortOrder", "createdAt", "updatedAt") VALUES (41, 'Tuổi', 'おいくつですか。', 2, '2026-10-16 09:16:51.797', '2026-10-16 09:16:51.797');
INSERT INTO public."ConversationIntroSlot" (id, slot, question, "sortOrder", "createdAt", "updatedAt") VALUES (42, 'Nghề / trường', 'お仕事は？ / 学生ですか。', 3, '2026-10-16 09:16:51.798', '2026-10-16 09:16:51.798');
INSERT INTO public."ConversationIntroSlot" (id, slot, question, "sortOrder", "createdAt", "updatedAt") VALUES (43, 'Sở thích', '趣味は何ですか。', 4, '2026-10-16 09:16:51.8', '2026-10-16 09:16:51.8');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (53, 39, 'ズンです。', 'ズンです。', 'Zun desu.', 'Tôi là Dũng.', NULL, 0, '2026-10-16 09:16:51.792', '2026-10-16 09:16:51.792');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (54, 39, 'ズンと申します。', 'ズンともうします。', 'Zun to mōshimasu.', 'Tôi tên Dũng. (khiêm)', NULL, 1, '2026-10-16 09:16:51.792', '2026-10-16 09:16:51.792');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (55, 39, '私の名前はレ・ズンです。', 'わたしのなまえはレ・ズンです。', 'Watashi no namae wa Re Zun desu.', 'Tên tôi là Lê Dũng.', NULL, 2, '2026-10-16 09:16:51.792', '2026-10-16 09:16:51.792');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (56, 40, 'ベトナム人です。', 'ベトナムじんです。', 'Betonamu-jin desu.', 'Tôi là người Việt.', NULL, 0, '2026-10-16 09:16:51.795', '2026-10-16 09:16:51.795');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (57, 40, 'ベトナムのダナンから来ました。', 'ベトナムのダナンからきました。', 'Betonamu no Danan kara kimashita.', 'Tôi đến từ Đà Nẵng, Việt Nam.', NULL, 1, '2026-10-16 09:16:51.795', '2026-10-16 09:16:51.795');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (58, 40, 'ダナンの出身です。', 'ダナンのしゅっしんです。', 'Danan no shusshin desu.', 'Tôi quê Đà Nẵng.', NULL, 2, '2026-10-16 09:16:51.795', '2026-10-16 09:16:51.795');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (59, 40, 'ダナンに住んでいます。', 'ダナンにすんでいます。', 'Danan ni sunde imasu.', 'Tôi đang sống ở Đà Nẵng.', NULL, 3, '2026-10-16 09:16:51.795', '2026-10-16 09:16:51.795');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (60, 41, '三十歳です。', 'さんじゅっさいです。', 'Sanjussai desu.', 'Tôi 30 tuổi.', NULL, 0, '2026-10-16 09:16:51.797', '2026-10-16 09:16:51.797');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (61, 41, '二十代です。', 'にじゅうだいです。', 'Nijūdai desu.', 'Tôi ngoài hai mươi.', NULL, 1, '2026-10-16 09:16:51.797', '2026-10-16 09:16:51.797');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (62, 41, '三十代です。', 'さんじゅうだいです。', 'Sanjūdai desu.', 'Tôi ngoài ba mươi.', NULL, 2, '2026-10-16 09:16:51.797', '2026-10-16 09:16:51.797');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (63, 42, 'プログラマーです。', 'プログラマーです。', 'Puroguramā desu.', 'Tôi là lập trình viên.', NULL, 0, '2026-10-16 09:16:51.798', '2026-10-16 09:16:51.798');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (64, 42, 'エンジニアです。', 'エンジニアです。', 'Enjinia desu.', 'Tôi là kỹ sư.', NULL, 1, '2026-10-16 09:16:51.798', '2026-10-16 09:16:51.798');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (65, 42, 'モバイルエンジニアです。', 'モバイルエンジニアです。', 'Mobairu enjinia desu.', 'Tôi là kỹ sư mobile.', NULL, 2, '2026-10-16 09:16:51.798', '2026-10-16 09:16:51.798');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (66, 42, '会社員です。', 'かいしゃいんです。', 'Kaishain desu.', 'Tôi là nhân viên công ty.', NULL, 3, '2026-10-16 09:16:51.798', '2026-10-16 09:16:51.798');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (67, 42, '学生です。', 'がくせいです。', 'Gakusei desu.', 'Tôi là học sinh / sinh viên.', NULL, 4, '2026-10-16 09:16:51.798', '2026-10-16 09:16:51.798');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (68, 43, '趣味はプログラミングです。', 'しゅみはプログラミングです。', 'Shumi wa puroguramingu desu.', 'Sở thích là lập trình.', NULL, 0, '2026-10-16 09:16:51.8', '2026-10-16 09:16:51.8');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (69, 43, '日本語の勉強が好きです。', 'にほんごのべんきょうがすきです。', 'Nihongo no benkyō ga suki desu.', 'Tôi thích học tiếng Nhật.', NULL, 1, '2026-10-16 09:16:51.8', '2026-10-16 09:16:51.8');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (70, 43, '趣味は読書です。', 'しゅみはどくしょです。', 'Shumi wa dokusho desu.', 'Sở thích là đọc sách.', NULL, 2, '2026-10-16 09:16:51.8', '2026-10-16 09:16:51.8');
INSERT INTO public."ConversationIntroExample" (id, "slotId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (71, 43, '映画を見るのが好きです。', 'えいがをみるのがすきです。', 'Eiga o miru no ga suki desu.', 'Tôi thích xem phim.', NULL, 3, '2026-10-16 09:16:51.8', '2026-10-16 09:16:51.8');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (44, 'はじめまして。', 'はじめまして。', 'Hajimemashite.', 'Rất vui được gặp (lần đầu).', 'Nói đầu tiên khi gặp người mới.', 0, '2026-10-16 09:16:51.784', '2026-10-16 09:16:51.784');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (45, 'レ・ティエン・ズンと申します。', 'レ・ティエン・ズンともうします。', 'Re Tien Zun to mōshimasu.', 'Tôi tên là Lê Tiến Dũng. (khiêm nhường)', 'と申します lịch sự hơn です khi tự giới thiệu tên.', 1, '2026-10-16 09:16:51.787', '2026-10-16 09:16:51.787');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (46, '三十歳です。', 'さんじゅっさいです。', 'Sanjussai desu.', 'Tôi 30 tuổi.', '歳（さい）= tuổi. 三十歳 đọc さんじゅっさい.', 2, '2026-10-16 09:16:51.787', '2026-10-16 09:16:51.787');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (47, 'ベトナムのダナンから来ました。', 'ベトナムのダナンからきました。', 'Betonamu no Danan kara kimashita.', 'Tôi đến từ Đà Nẵng, Việt Nam.', NULL, 3, '2026-10-16 09:16:51.788', '2026-10-16 09:16:51.788');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (48, 'ダナンの出身です。', 'ダナンのしゅっしんです。', 'Danan no shusshin desu.', 'Tôi quê ở Đà Nẵng.', NULL, 4, '2026-10-16 09:16:51.789', '2026-10-16 09:16:51.789');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (49, 'プログラマーです。', 'プログラマーです。', 'Puroguramā desu.', 'Tôi là lập trình viên.', 'Cũng nói エンジニアです / モバイルエンジニアです.', 5, '2026-10-16 09:16:51.789', '2026-10-16 09:16:51.789');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (50, '四年以上、アプリとウェブサイトを作っています。', 'よねんいじょう、アプリとウェブサイトをつくっています。', 'Yonen ijō, apuri to webusaito o tsukutte imasu.', 'Hơn 4 năm nay tôi làm app và website.', NULL, 6, '2026-10-16 09:16:51.79', '2026-10-16 09:16:51.79');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (51, 'スマホのアプリやバックエンドの開発が得意です。', 'スマホのアプリやバックエンドのかいはつがとくいです。', 'Sumaho no apuri ya bakkuendo no kaihatsu ga tokui desu.', 'Tôi giỏi phát triển app điện thoại và backend.', NULL, 7, '2026-10-16 09:16:51.79', '2026-10-16 09:16:51.79');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (52, '日本語を勉強しています。', 'にほんごをべんきょうしています。', 'Nihongo o benkyō shite imasu.', 'Tôi đang học tiếng Nhật.', NULL, 8, '2026-10-16 09:16:51.791', '2026-10-16 09:16:51.791');
INSERT INTO public."ConversationIntroLine" (id, ja, kana, romaji, vi, tip, "sortOrder", "createdAt", "updatedAt") VALUES (53, 'どうぞよろしくお願いします。', 'どうぞよろしくおねがいします。', 'Dōzo yoroshiku onegai shimasu.', 'Rất mong được giúp đỡ / nhờ chiếu cố.', 'Câu kết bắt buộc của 自己紹介.', 9, '2026-10-16 09:16:51.791', '2026-10-16 09:16:51.791');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (44, 'aisatsu', 'Chào hỏi', 'Chào theo thời điểm trong ngày. Buổi tối dùng こんばんは, không dùng こんにちは.', 0, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (45, 'aisatsu-meet', 'Gặp / chia tay', 'はじめまして chỉ dùng lần đầu. また後で dùng khi sẽ gặp lại trong ngày.', 1, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (46, 'thanks', 'Cảm ơn / xin lỗi', 'すみません vừa xin lỗi vừa gọi người. どういたしまして trả lời cảm ơn.', 2, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (47, 'reply', 'Đáp lại', 'わかりません khác 知りません: không hiểu vs không biết thông tin.', 3, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (48, 'ask', 'Hỏi thông tin', 'Câu hỏi N5: 何・どこ・いつ・いくら・だれ. Thêm ください khi nhờ.', 4, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (49, 'shop', 'Cửa hàng', 'ください = cho tôi. これをください vừa chỉ vừa mua.', 5, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (50, 'food', 'Ăn uống', 'いただきます trước khi ăn. ごちそうさまでした sau khi ăn xong.', 6, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
