INSERT INTO public."ConversationPhraseGroup" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (52, 'class', 'Lớp học', 'Dùng với giáo viên. 質問があります rất hay khi muốn hỏi.', 8, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
