INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (174, 44, 'こんにちは。', 'こんにちは。', 'Konnichiwa.', 'Xin chào (ban ngày).', NULL, 1, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (175, 44, 'こんばんは。', 'こんばんは。', 'Konbanwa.', 'Chào buổi tối.', NULL, 2, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (176, 44, 'おやすみなさい。', 'おやすみなさい。', 'Oyasuminasai.', 'Chúc ngủ ngon.', NULL, 3, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (177, 44, 'いってきます。', 'いってきます。', 'Itte kimasu.', 'Con đi đây. (khi ra khỏi nhà)', NULL, 4, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (178, 44, 'いってらっしゃい。', 'いってらっしゃい。', 'Itte rasshai.', 'Đi nhé, về sớm.', NULL, 5, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (179, 44, 'ただいま。', 'ただいま。', 'Tadaima.', 'Con về rồi.', NULL, 6, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (180, 44, 'おかえりなさい。', 'おかえりなさい。', 'Okaerinasai.', 'Về rồi à.', NULL, 7, '2026-10-16 09:16:51.802', '2026-10-16 09:16:51.802');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (181, 45, 'はじめまして。', 'はじめまして。', 'Hajimemashite.', 'Rất vui được gặp (lần đầu).', NULL, 0, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (182, 45, 'よろしくお願いします。', 'よろしくおねがいします。', 'Yoroshiku onegai shimasu.', 'Mong được giúp đỡ.', NULL, 1, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (183, 45, 'こちらこそ。', 'こちらこそ。', 'Kochira koso.', 'Chính tôi mới phải nói vậy.', NULL, 2, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (184, 45, 'お元気ですか。', 'おげんきですか。', 'O-genki desu ka.', 'Bạn khỏe không?', NULL, 3, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (185, 45, '元気です。', 'げんきです。', 'Genki desu.', 'Tôi khỏe.', NULL, 4, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (186, 45, 'さようなら。', 'さようなら。', 'Sayōnara.', 'Tạm biệt (lâu mới gặp lại).', NULL, 5, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (187, 45, 'じゃあ、また。', 'じゃあ、また。', 'Jā, mata.', 'Thôi, gặp lại sau.', NULL, 6, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (188, 45, 'また後で。', 'またあとで。', 'Mata ato de.', 'Gặp lại sau (trong ngày).', NULL, 7, '2026-10-16 09:16:51.804', '2026-10-16 09:16:51.804');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (189, 46, 'ありがとうございます。', 'ありがとうございます。', 'Arigatō gozaimasu.', 'Cảm ơn ạ.', NULL, 0, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (190, 46, 'どうも。', 'どうも。', 'Dōmo.', 'Cảm ơn (ngắn).', NULL, 1, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (191, 46, 'どういたしまして。', 'どういたしまして。', 'Dō itashimashite.', 'Không có gì.', NULL, 2, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (192, 46, 'すみません。', 'すみません。', 'Sumimasen.', 'Xin lỗi / làm ơn / gọi nhân viên.', NULL, 3, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (193, 46, 'ごめんなさい。', 'ごめんなさい。', 'Gomen nasai.', 'Xin lỗi (thân mật hơn).', NULL, 4, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (194, 46, '失礼します。', 'しつれいします。', 'Shitsurei shimasu.', 'Xin phép (vào / cắt ngang / về).', NULL, 5, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (195, 46, 'お先に失礼します。', 'おさきにしつれいします。', 'Osaki ni shitsurei shimasu.', 'Xin phép về trước.', NULL, 6, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (196, 46, 'お待たせしました。', 'おまたせしました。', 'Omatase shimashita.', 'Xin lỗi đã để chờ.', NULL, 7, '2026-10-16 09:16:51.806', '2026-10-16 09:16:51.806');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (197, 47, 'はい。', 'はい。', 'Hai.', 'Vâng / dạ.', NULL, 0, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (198, 47, 'いいえ。', 'いいえ。', 'Iie.', 'Không.', NULL, 1, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (199, 47, 'そうです。', 'そうです。', 'Sō desu.', 'Đúng vậy.', NULL, 2, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (200, 47, 'そうですか。', 'そうですか。', 'Sō desu ka.', 'Thế à.', NULL, 3, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (201, 47, 'わかりました。', 'わかりました。', 'Wakarimashita.', 'Tôi hiểu rồi.', NULL, 4, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (202, 47, 'わかりません。', 'わかりません。', 'Wakarimasen.', 'Tôi không hiểu.', NULL, 5, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (203, 47, 'ちょっと待ってください。', 'ちょっとまってください。', 'Chotto matte kudasai.', 'Xin chờ một chút.', NULL, 6, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (204, 47, 'もう一度お願いします。', 'もういちどおねがいします。', 'Mō ichido onegai shimasu.', 'Nhờ nói lại lần nữa.', NULL, 7, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (205, 47, 'ゆっくり話してください。', 'ゆっくりはなしてください。', 'Yukkuri hanashite kudasai.', 'Xin nói chậm giúp.', NULL, 8, '2026-10-16 09:16:51.808', '2026-10-16 09:16:51.808');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (206, 48, 'これは何ですか。', 'これはなんですか。', 'Kore wa nan desu ka.', 'Đây là cái gì?', NULL, 0, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (207, 48, 'トイレはどこですか。', 'トイレはどこですか。', 'Toire wa doko desu ka.', 'Nhà vệ sinh ở đâu?', NULL, 1, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (208, 48, '今、何時ですか。', 'いま、なんじですか。', 'Ima, nan-ji desu ka.', 'Bây giờ là mấy giờ?', NULL, 2, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (209, 48, 'いくらですか。', 'いくらですか。', 'Ikura desu ka.', 'Bao nhiêu tiền?', NULL, 3, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (210, 48, 'だれですか。', 'だれですか。', 'Dare desu ka.', 'Ai vậy?', NULL, 4, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (211, 48, 'いつですか。', 'いつですか。', 'Itsu desu ka.', 'Khi nào?', NULL, 5, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (212, 48, 'どうしますか。', 'どうしますか。', 'Dō shimasu ka.', 'Làm thế nào / chọn gì?', NULL, 6, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (213, 48, '英語が話せますか。', 'えいごがはなせますか。', 'Eigo ga hanasemasu ka.', 'Bạn nói được tiếng Anh không?', NULL, 7, '2026-10-16 09:16:51.81', '2026-10-16 09:16:51.81');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (214, 49, 'これをください。', 'これをください。', 'Kore o kudasai.', 'Cho tôi cái này.', NULL, 0, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (215, 49, '見せてください。', 'みせてください。', 'Misete kudasai.', 'Cho tôi xem với.', NULL, 1, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (216, 49, '試着できますか。', 'しちゃくできますか。', 'Shichaku dekimasu ka.', 'Có thể thử đồ không?', NULL, 2, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (217, 49, '袋をお願いします。', 'ふくろをおねがいします。', 'Fukuro o onegai shimasu.', 'Xin cho túi.', NULL, 3, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (218, 49, 'カードで払えますか。', 'カードではらえますか。', 'Kādo de haraemasu ka.', 'Trả thẻ được không?', NULL, 4, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (219, 49, 'レシートをお願いします。', 'レシートをおねがいします。', 'Reshīto o onegai shimasu.', 'Xin hóa đơn.', NULL, 5, '2026-10-16 09:16:51.811', '2026-10-16 09:16:51.811');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (220, 50, 'メニューをください。', 'メニューをください。', 'Menyū o kudasai.', 'Cho tôi thực đơn.', NULL, 0, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (221, 50, '水をください。', 'みずをください。', 'Mizu o kudasai.', 'Cho tôi nước.', NULL, 1, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (222, 50, 'おすすめは何ですか。', 'おすすめはなんですか。', 'Osusume wa nan desu ka.', 'Món nào nên thử?', NULL, 2, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (223, 50, 'これは辛いですか。', 'これはからいですか。', 'Kore wa karai desu ka.', 'Cái này có cay không?', NULL, 3, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (224, 50, 'おいしいです。', 'おいしいです。', 'Oishii desu.', 'Ngon quá.', NULL, 4, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (225, 50, 'いただきます。', 'いただきます。', 'Itadakimasu.', 'Xin phép được ăn.', NULL, 5, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (226, 50, 'ごちそうさまでした。', 'ごちそうさまでした。', 'Gochisōsama deshita.', 'Cảm ơn bữa ăn.', NULL, 6, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (227, 50, 'お会計お願いします。', 'おかいけいおねがいします。', 'O-kaikei onegai shimasu.', 'Tính tiền giúp.', NULL, 7, '2026-10-16 09:16:51.813', '2026-10-16 09:16:51.813');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (228, 51, '駅はどこですか。', 'えきはどこですか。', 'Eki wa doko desu ka.', 'Ga ở đâu?', NULL, 0, '2026-10-16 09:16:51.815', '2026-10-16 09:16:51.815');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (229, 51, 'この電車は新宿へ行きますか。', 'このでんしゃはしんじゅくへいきますか。', 'Kono densha wa Shinjuku e ikimasu ka.', 'Tàu này đi Shinjuku chứ?', NULL, 1, '2026-10-16 09:16:51.815', '2026-10-16 09:16:51.815');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (230, 51, '次は何時ですか。', 'つぎはなんじですか。', 'Tsugi wa nan-ji desu ka.', 'Chuyến sau mấy giờ?', NULL, 2, '2026-10-16 09:16:51.815', '2026-10-16 09:16:51.815');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (231, 51, '降ります。', 'おります。', 'Orimasu.', 'Tôi xuống đây. (trên tàu/bus)', NULL, 3, '2026-10-16 09:16:51.815', '2026-10-16 09:16:51.815');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (232, 51, '地図を見せてください。', 'ちずをみせてください。', 'Chizu o misete kudasai.', 'Cho tôi xem bản đồ.', NULL, 4, '2026-10-16 09:16:51.815', '2026-10-16 09:16:51.815');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (233, 51, 'まっすぐ行ってください。', 'まっすぐいってください。', 'Massugu itte kudasai.', 'Đi thẳng.', NULL, 5, '2026-10-16 09:16:51.815', '2026-10-16 09:16:51.815');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (234, 52, '質問があります。', 'しつもんがあります。', 'Shitsumon ga arimasu.', 'Tôi có câu hỏi.', NULL, 0, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (235, 52, '黒板を見てください。', 'こくばんをみてください。', 'Kokuban o mite kudasai.', 'Nhìn bảng giúp.', NULL, 1, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (236, 52, '宿題は何ですか。', 'しゅくだいはなんですか。', 'Shukudai wa nan desu ka.', 'Bài tập về nhà là gì?', NULL, 2, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (237, 52, '休みます。', 'やすみます。', 'Yasumimasu.', 'Tôi xin nghỉ.', NULL, 3, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (238, 52, '遅れます。', 'おくれます。', 'Okuremasu.', 'Tôi sẽ đến muộn.', NULL, 4, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (239, 52, '教えてください。', 'おしえてください。', 'Oshiete kudasai.', 'Xin dạy / chỉ giúp.', NULL, 5, '2026-10-16 09:16:51.816', '2026-10-16 09:16:51.816');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (240, 53, '具合が悪いです。', 'ぐあいがわるいです。', 'Guai ga warui desu.', 'Tôi thấy không khỏe.', NULL, 0, '2026-10-16 09:16:51.818', '2026-10-16 09:16:51.818');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (241, 53, '頭が痛いです。', 'あたまがいたいです。', 'Atama ga itai desu.', 'Tôi đau đầu.', NULL, 1, '2026-10-16 09:16:51.818', '2026-10-16 09:16:51.818');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (242, 53, '熱があります。', 'ねつがあります。', 'Netsu ga arimasu.', 'Tôi bị sốt.', NULL, 2, '2026-10-16 09:16:51.818', '2026-10-16 09:16:51.818');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (243, 53, '薬をください。', 'くすりをください。', 'Kusuri o kudasai.', 'Cho tôi thuốc.', NULL, 3, '2026-10-16 09:16:51.818', '2026-10-16 09:16:51.818');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (244, 53, '大丈夫です。', 'だいじょうぶです。', 'Daijōbu desu.', 'Không sao.', NULL, 4, '2026-10-16 09:16:51.818', '2026-10-16 09:16:51.818');
INSERT INTO public."ConversationPhraseItem" (id, "groupId", ja, kana, romaji, vi, note, "sortOrder", "createdAt", "updatedAt") VALUES (245, 53, 'お大事に。', 'おだいじに。', 'O-daiji ni.', 'Bảo trọng / mau khỏe.', NULL, 5, '2026-10-16 09:16:51.818', '2026-10-16 09:16:51.818');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (1, 'numbers', 'Số cơ bản', 'Hệ thập phân: 十（じゅう）= 10 · 百（ひゃく）= 100 · 千（せん）= 1.000 · 万（まん）= 10.000. Ghép số từ trái sang phải: 二十五 = 20 + 5. Một số âm đọc đặc biệt: 300 → さんびゃく, 600 → ろっぴゃく, 800 → はっぴゃく, 3.000 → さんぜん, 8.000 → はっせん.', 0, '2026-06-25 10:52:31.156', '2026-06-25 10:52:31.156');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (2, 'objects', 'Đếm đồ vật', 'Dùng khi đếm vật thể chung (～つ). Từ 1–10 dùng âm thuần Nhật, từ 11 trở đi thường dùng số Hán + こ.', 1, '2026-06-25 10:52:31.175', '2026-06-25 10:52:31.175');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (3, 'people', 'Đếm người', 'Dùng trợ từ 人（にん／り）. 1 người và 2 người đọc đặc biệt: ひとり、ふたり.', 2, '2026-06-25 10:52:31.185', '2026-06-25 10:52:31.185');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (4, 'days', 'Ngày trong tháng', 'Đọc ngày trong tháng (～日). Nhiều ngày đọc không theo quy tắc — cần học thuộc.', 3, '2026-06-25 10:52:31.199', '2026-06-25 10:52:31.199');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (5, 'months', 'Tháng', 'Tháng trong năm: số + がつ. Tháng 4 đọc しがつ, tháng 7 しちがつ, tháng 9 くがつ.', 4, '2026-06-25 10:52:31.213', '2026-06-25 10:52:31.213');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (6, 'age', 'Tuổi', 'Đếm tuổi: số + さい. 20 tuổi đọc đặc biệt はたち.', 5, '2026-06-25 10:52:31.225', '2026-06-25 10:52:31.225');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (7, 'order', 'Thứ tự', 'Diễn tả thứ hạng, vị trí: 第（だい）+ số. Ví dụ: 第一 = thứ nhất, hạng nhất.', 6, '2026-06-25 10:52:31.235', '2026-06-25 10:52:31.235');
INSERT INTO public."CounterCategory" (id, slug, label, hint, "sortOrder", "createdAt", "updatedAt") VALUES (8, 'time', 'Giờ & phút', 'Giờ: ～じ. Phút: ～ふん／ぷん (có biến âm: いっぷん, さんぷん, ろっぷん...).', 7, '2026-06-25 10:52:31.245', '2026-06-25 10:52:31.245');
