INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (8, 'gairaigo', 'Gairaigo — từ mượn tiếng Anh', 'Vì sao coffee viết コーヒー chứ không phải hiragana.', 0, '2026-07-07 09:25:17.933', '2026-07-07 09:25:17.933');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (9, 'six-core-rules', '6 quy luật chuyển âm (giáo trình hay bỏ sót)', 'Nắm 6 quy tắc này là có thể tự chuyển hầu hết từ tiếng Anh sang katakana — phần lớn sách N5 chỉ cho ví dụ mà không giải thích hệ thống.', 1, '2026-07-07 09:25:17.943', '2026-07-07 09:25:17.943');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (10, 'basic-cv', 'Bảng âm cơ bản (consonant + vowel)', 'Mỗi âm tiếng Anh thường map sang một hoặc vài kana.', 2, '2026-07-07 09:25:17.955', '2026-07-07 09:25:17.955');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (11, 'combo-reading', 'Nhóm âm ghép — cách đọc nhanh', 'Bảng tra các cụm katakana ghép nhỏ thường gặp trong từ mượn.', 3, '2026-07-07 09:25:17.961', '2026-07-07 09:25:17.961');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (12, 'english-sounds', 'Âm đặc trưng tiếng Anh → katakana', 'L/R, V, F, TH, W và các tổ hợp khó.', 4, '2026-07-07 09:25:17.969', '2026-07-07 09:25:17.969');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (14, 'common-words', 'Từ tiếng Anh thường gặp', 'Bảng tra nhanh — nghe mẫu để quen tai.', 6, '2026-07-07 09:25:17.979', '2026-07-07 09:25:17.979');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (15, 'tricky', 'Dễ nhầm — đọc không như chữ Anh', 'Một số từ nghe khác hẳn so với orthography tiếng Anh.', 7, '2026-07-07 09:25:17.985', '2026-07-07 09:25:17.985');
INSERT INTO public."EnglishKatakanaSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (13, 'long-vowel', 'Trường âm ー (chōon) — quy luật thêm đủ', 'Khi nào viết ー? Giáo trình hay chỉ cho vài ví dụ — dưới đây là đủ 7 nhóm hay gặp khi chuyển tiếng Anh → katakana.', 5, '2026-07-07 09:25:17.974', '2026-08-09 08:42:09.181');
