INSERT INTO public."EnglishKatakanaMeta" (id, intro, "createdAt", "updatedAt") VALUES (1, 'Tiếng Nhật không có đủ âm để bắt chước tiếng Anh nguyên bản. Khi mượn từ nước ngoài (gairaigo 外来語), người Nhật ghi bằng katakana theo cách nghe gần nhất với hệ âm tiếng Nhật — thường ngắn hơn, không có phụ âm cuối phức tạp, và dùng 長音 (ー) cho nguyên âm dài.', '2026-07-05 07:23:31.761', '2026-07-07 09:25:17.921');
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (14, 8, 'Gairaigo (外来語) là từ mượn từ tiếng Anh, Pháp, Đức… Katakana báo hiệu "đây không phải từ gốc Nhật".', NULL, NULL, NULL, 0);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (15, 8, 'Cách viết theo âm nghe được (音写 onsha), không theo chính tả tiếng Anh — computer và kompyuutaa cùng một dòng âm.', 'computer', 'コンピューター', 'konpyuutaa', 1);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (16, 8, 'Nhiều từ hàng ngày ở Nhật là gairaigo: ホテル, レストラン, スマホ — người Việt học N5 nên quen sớm.', NULL, NULL, NULL, 2);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (17, 9, 'Quy luật 1 — Thêm nguyên âm sau phụ âm đứng một mình: tiếng Nhật gần như chỉ có âm tiết CV (phụ âm + nguyên âm). Phụ âm cuối từ phải được "vá" bằng nguyên âm.', NULL, NULL, NULL, 0);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (18, 9, 'Kết thúc bằng t hoặc d → thêm o. Kết thúc bằng c, b, f, g, k, l, m, p, s → thêm u. Ngoại lệ: salad → サラダ (không thêm u sau d).', 'hint / mask / post', 'ヒント / マスク / ポスト', 'hinto / masuku / posuto', 1);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (19, 9, 'Quy luật 2 — Thay âm tiếng Anh không có trong tiếng Nhật bằng âm gần nhất. Đây là lý do love→ラブ, think→シンク, fan→ファン.', NULL, NULL, NULL, 2);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (21, 9, 'Quy luật 4 — Âm ngắt ッ (sokuon) khi có phụ âm "dừng" sau nguyên âm ngắn: -ck/-x/-tch, -ss/-pp/-tt, hoặc -at/-ap/-et/-ip/-op...', 'block / staff / ship', 'ブロック / スタッフ / シップ', 'burokku / sutaffu / shippu', 4);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (22, 9, 'Quy luật 5 — Katakana ghép (ャュョィェォヴ): dùng ký tự nhỏ để bắt âm ti, di, fa, tu, du, v… mà bảng 50 âm không có. Cat ngày nay là キャット, không phải カット.', 'cat / gap / duet', 'キャット / ギャップ / デュエット', 'kyatto / gyappu / dyuetto', 5);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (23, 9, 'Quy luật 6 — Tách cụm phụ âm bằng nguyên âm (thường u): tiếng Anh có st, tr, dr, spr… tiếng Nhật chèn u để mỗi mora vẫn là CV.', 'street / spring / drive', 'ストリート / スプリング / ドライブ', 'sutoriito / supuringu / doraibu', 6);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (24, 11, 'Âm ghép dùng ký tự nhỏ (ャュョァィゥェォ) để tạo âm gần tiếng Anh hơn. Đọc liền một nhịp, không tách từng kana.', NULL, NULL, NULL, 0);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (25, 11, 'Khi gặp ティ / ディ / トゥ / ドゥ, ưu tiên đọc theo cụm (ti, di, tu, du), không đọc kiểu te-i, de-i.', NULL, NULL, NULL, 1);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (20, 9, 'Quy luật 3 — Trường âm ー cho nguyên âm dài (đủ 7 nhóm): ① -ar/-er/-ir/-ur/-or → カー; ② -ee/-ea/-ai/-oa/-au/-oo → スピード; ③ -all/-al/-ol → ゴールド; ④ -w/-y → ショー/コピー; ⑤ -a-e/-o-e/-u-e → ケース/ゲーム; ⑥ -ation/-otion → ローション; ⑦ -ire/-ture → カルチャー. Xem mục «Trường âm ー» bên dưới.', 'car / speed / show / game / lotion', 'カー / スピード / ショー / ゲーム / ローション', 'kaa / supiido / shoo / geemu / rooshon', 3);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (38, 13, 'Dấu ー kéo dài nguyên âm ngay trước đó thêm một mora. Không đọc như chữ "i" riêng — コーヒー = 4 mora: コ + ー + ヒ + ー.', 'coffee', 'コーヒー', 'koohii', 0);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (39, 13, '① -ar / -er / -ir / -ur / -or → trường âm hàng ア (ー). Car → カー, curtain → カーテン, computer → コンピューター.', 'car / curtain / computer', 'カー / カーテン / コンピューター', 'kaa / kaaten / konpyuutaa', 1);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (40, 13, '② -ee- / -ea- / -ai- / -oa- / -au- / -oo- → nguyên âm dài tương ứng. Speed → スピード, coupon → クーポン, cheese → チーズ, room → ルーム.', 'speed / coupon / cheese / room', 'スピード / クーポン / チーズ / ルーム', 'supiido / kuupon / chiizu / ruumu', 2);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (41, 13, '③ -all / -al / -ol → kéo dài âm o/a. Gold → ゴールド, all → オール, ball → ボール.', 'gold / all / ball', 'ゴールド / オール / ボール', 'goorudo / ooru / booru', 3);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (42, 13, '④ Kết thúc -w / -y → kéo dài nguyên âm trước. Show → ショー, copy → コピー, snow → スノー.', 'show / copy / snow', 'ショー / コピー / スノー', 'shoo / kopii / sunoo', 4);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (43, 13, '⑤ Magic e / silent e dạng -a-e / -o-e / -u-e → nguyên âm dài. Case → ケース, game → ゲーム, note → ノート, cute → キュート.', 'case / game / note', 'ケース / ゲーム / ノート', 'keesu / geemu / nooto', 5);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (44, 13, '⑥ -ation / -otion → thường …ーション. Automation → オートメーション, lotion → ローション, station → ステーション.', 'automation / lotion / station', 'オートメーション / ローション / ステーション', 'ootomeeshon / rooshon / suteeshon', 6);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (45, 13, '⑦ -ire / -ture → …アー / …チャー (kéo dài). Fire → ファイア／ファイヤー, culture → カルチャー, future → フューチャー.', 'culture / future / fire', 'カルチャー / フューチャー / ファイヤー', 'karuchaa / fyuuchaa / faiyaa', 7);
INSERT INTO public."EnglishKatakanaPoint" (id, "sectionId", explanation, english, katakana, romaji, "sortOrder") VALUES (46, 13, 'Lưu ý: tài liệu kỹ thuật / JIS đôi khi lược ー theo "quy tắc 3 mora" (từ ≥3 mora bỏ trường âm). Học giao tiếp / JLPT thì giữ ー theo các quy luật trên.', NULL, NULL, NULL, 8);
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (9, 'Đừng đọc katakana như đọc chữ Latin — hãy nghĩ "âm Nhật hóa" của từ tiếng Anh.', 0, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (10, 'Âm L và R trong tiếng Anh thường gộp thành ラ行 (ra, ri, ru, re, ro) — ví dụ love → ラブ.', 1, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (11, 'Âm V không có trong tiếng Nhật cổ — thường dùng バ行 hoặc ヴ + nguyên âm (violet → ヴァイオレット).', 2, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (12, 'Âm TH thường thành ス hoặc テ (think → シンク, three → スリー).', 3, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (13, 'Nguyên âm dài trong tiếng Anh hay được kéo bằng ー: coffee → コーヒー, table → テーブル.', 4, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (14, 'Phụ âm cuối bị cắt hoặc thêm nguyên âm: bus → バス, bed → ベッド.', 5, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (15, 'Khi nghe podcast hay anime, nhận diện gairaigo giúp đoán nghĩa nhanh hơn từ kanji.', 6, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
INSERT INTO public."EnglishKatakanaTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (16, 'Giáo trình Minna thường chỉ liệt kê từ — 6 quy luật chuyển âm bên dưới mới giúp anh tự đoán cách viết katakana.', 7, '2026-07-07 09:25:17.926', '2026-07-07 09:25:17.926');
