INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5956, 'N + に就く / N + に就いて', 'nhậm chức ~, đảm nhận ~', 'Dùng với chức danh, vị trí công việc. 「〜について」 là về chủ đề, khác nghĩa.', 599, '2026-09-02 08:54:27.763', '2026-09-02 08:54:27.763', 'N2', 'formal', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5957, 'N + に配属される', 'được phân công về ~', NULL, 599, '2026-09-02 08:54:27.783', '2026-09-02 08:54:27.783', 'N2', 'formal', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5958, 'N + に委ねる / N + に委ねられる', 'giao phó cho ~, ủy thác cho ~', NULL, 599, '2026-09-02 08:54:27.792', '2026-09-02 08:54:27.792', 'N2', 'formal', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5959, 'N + に頼る / N + 頼りにする', 'dựa vào ~, tin cậy ~', NULL, 599, '2026-09-02 08:54:27.801', '2026-09-02 08:54:27.801', 'N2', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5960, 'N + を求める', 'yêu cầu ~, tìm kiếm ~', NULL, 599, '2026-09-02 08:54:27.81', '2026-09-02 08:54:27.81', 'N2', 'formal', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5961, 'N + に供給する / N + が供給される', 'cung cấp ~', NULL, 599, '2026-09-02 08:54:27.818', '2026-09-02 08:54:27.818', 'N2', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5962, 'N + を届ける / N + が届く', 'gửi đến ~; (thông báo) đến tai ~', NULL, 599, '2026-09-02 08:54:27.826', '2026-09-02 08:54:27.826', 'N2', 'neutral', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5963, 'N + の倍 / N + 倍に増える', 'gấp ~ lần', NULL, 599, '2026-09-02 08:54:27.833', '2026-09-02 08:54:27.833', 'N2', 'neutral', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5964, 'N + によって / N + により', 'tùy theo ~; do ~ (nguyên nhân trang trọng)', 'Nghĩa phân biệt theo ngữ cảnh: phương tiện, nguyên nhân, hoặc tùy trường hợp.', 600, '2026-09-02 08:54:27.844', '2026-09-02 08:54:27.844', 'N2', 'formal', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5965, 'N + に伴って / N + に伴い', 'cùng với ~, đi kèm theo ~', NULL, 600, '2026-09-02 08:54:27.849', '2026-09-02 08:54:27.849', 'N2', 'formal', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5966, 'N + を減らす / N + が減る', 'giảm ~', NULL, 600, '2026-09-02 08:54:27.855', '2026-09-02 08:54:27.855', 'N2', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5967, 'N + を加える / N + に加えて', 'cộng thêm ~; ngoài ~ còn ~', NULL, 600, '2026-09-02 08:54:27.864', '2026-09-02 08:54:27.864', 'N2', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5968, 'N + に占める / N + の割合を占める', 'chiếm ~ (tỷ lệ)', NULL, 600, '2026-09-02 08:54:27.874', '2026-09-02 08:54:27.874', 'N2', 'formal', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5971, 'N + を危険にさらす', 'đặt ~ vào nguy hiểm', NULL, 600, '2026-09-02 08:54:27.895', '2026-09-02 08:54:27.895', 'N2', 'formal', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5972, 'N + を宣伝する / N + が宣伝される', 'quảng bá ~, tuyên truyền ~', NULL, 601, '2026-09-02 08:54:27.901', '2026-09-02 08:54:27.901', 'N2', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5952, 'V/N + にかたくない', 'không khó để ~ (tưởng tượng/suy đoán)', 'Thành ngữ cố định, hầu như chỉ dùng với 想像/察する: 「想像にかたくない」.', 598, '2026-08-29 06:53:03.935', '2026-08-29 06:53:03.935', 'N1', 'formal', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5953, 'V(た/ている) + 手前', 'đã trót ~ (trước mặt người khác) nên đành phải ~', 'Vì thể diện / vì đã nói/làm gì đó trước mặt người khác nên buộc phải hành xử cho nhất quán.', 598, '2026-08-29 06:53:03.942', '2026-08-29 06:53:03.942', 'N1', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5954, 'V(た) + ら + それまでだ / V(ば) + それまでだ', 'nếu ~ thì coi như hết, thế là xong', 'Nhấn mạnh: một khi điều đó xảy ra thì mọi nỗ lực trở nên vô nghĩa.', 598, '2026-08-29 06:53:03.951', '2026-08-29 06:53:03.951', 'N1', 'spoken', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6011, 'N + を見据える / N + を見据えて', 'nhìn về phía ~; hướng tới ~ (tương lai)', NULL, 605, '2026-09-02 08:54:28.128', '2026-09-02 08:54:28.128', 'N1', 'formal', 7);
