INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6015, 'N + に背く / N + に背いた', 'phản bội ~, trái với ~', NULL, 606, '2026-09-02 08:54:28.145', '2026-09-02 08:54:28.145', 'N1', 'written', 3);
