INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6021, 'N + 以来 / N + 以後', 'kể từ ~', NULL, 607, '2026-09-02 08:54:28.17', '2026-09-02 08:54:28.17', 'N1', 'formal', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6023, 'N + に先立ち / N + に先立って', 'trước khi ~ (chuẩn bị trang trọng)', NULL, 607, '2026-09-02 08:54:28.177', '2026-09-02 08:54:28.177', 'N1', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6024, 'N + を機に / N + を機として', 'lấy ~ làm dịp', NULL, 607, '2026-09-02 08:54:28.18', '2026-09-02 08:54:28.18', 'N1', 'formal', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6026, 'N + の根底にある / N + が根底にある', 'nằm ở gốc rễ ~', NULL, 607, '2026-09-02 08:54:28.186', '2026-09-02 08:54:28.186', 'N1', 'formal', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6029, 'N + に浸る / N + に浸って', 'ngâm mình trong ~; đắm chìm ~', NULL, 608, '2026-09-02 08:54:28.198', '2026-09-02 08:54:28.198', 'N1', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6030, 'N + に溶け込む / N + に溶け込んで', 'hòa nhập vào ~', NULL, 608, '2026-09-02 08:54:28.202', '2026-09-02 08:54:28.202', 'N1', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6031, 'N + を純化する / N + が純化される', 'tinh luyện ~, làm tinh khiết ~', NULL, 608, '2026-09-02 08:54:28.205', '2026-09-02 08:54:28.205', 'N1', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6033, 'N + を膨張させる / N + が膨張する', 'làm phình to ~; ~ phồng lên', NULL, 608, '2026-09-02 08:54:28.212', '2026-09-02 08:54:28.212', 'N1', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6034, 'N + を緻密に / 緻密なN', 'tỉ mỉ ~, chặt chẽ ~', NULL, 608, '2026-09-02 08:54:28.215', '2026-09-02 08:54:28.215', 'N1', 'formal', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5812, 'V(từ điển/ない) + ように', 'để (làm được), sao cho ~', 'Diễn tả mục đích với động từ chỉ trạng thái/khả năng (không chủ ý): できる, わかる, 聞こえる, hoặc thể phủ định. So với 「ために」 (mục đích có chủ ý).', 552, '2026-08-29 06:52:54.065', '2026-08-29 06:52:54.065', 'N3', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5813, 'V(từ điển) + ようにする / ようになる', 'cố gắng làm ~ (thói quen) / trở nên ~ (thay đổi)', '「ようにする」: nỗ lực duy trì một thói quen. 「ようになる」: sự thay đổi dần dần về trạng thái hoặc khả năng.', 552, '2026-08-29 06:52:54.079', '2026-08-29 06:52:54.079', 'N3', 'neutral', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5814, 'N + のために / V(từ điển) + ために', 'vì, để (mục đích có chủ ý)', 'Chủ ngữ hai vế giống nhau và hành động có chủ đích. Khác 「ように」 ở chỗ động từ là động từ ý chí.', 552, '2026-08-29 06:52:54.085', '2026-08-29 06:52:54.085', 'N3', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5815, 'V(た) + おかげで / N + のおかげで', 'nhờ có ~ (kết quả tốt)', 'Chỉ nguyên nhân dẫn đến kết quả tích cực, mang sắc thái biết ơn. Trái nghĩa: 「せいで」 (kết quả xấu).', 552, '2026-08-29 06:52:54.091', '2026-08-29 06:52:54.091', 'N3', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5816, 'V(thể thường) + せいで / N + のせいで', 'tại vì ~ (kết quả xấu), do lỗi của ~', 'Quy trách nhiệm cho nguyên nhân gây hậu quả xấu. 「せいか」 = "có lẽ do ~" (không chắc chắn).', 552, '2026-08-29 06:52:54.099', '2026-08-29 06:52:54.099', 'N3', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5817, 'V/A/N(thể thường) + ば + ～ほど', 'càng ~ thì càng ~', 'Động từ: 〜ば〜ほど. Tính từ -i: 〜ければ〜いほど. Tính từ -na / danh từ: 〜なら（であれば）〜なほど.', 552, '2026-08-29 06:52:54.106', '2026-08-29 06:52:54.106', 'N3', 'neutral', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5818, 'V(た) + ら + ～た (bất ngờ)', 'khi ~ thì (phát hiện ra) ~', 'Dùng khi làm việc gì đó rồi phát hiện một sự thật bất ngờ, ngoài dự đoán. Vế sau ở thì quá khứ.', 552, '2026-08-29 06:52:54.116', '2026-08-29 06:52:54.116', 'N3', 'neutral', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5819, 'N + によって / により', 'tùy theo ~; do ~ (bị động); bằng ~', 'Nhiều nghĩa: (1) tùy vào 〜によって違う; (2) chỉ tác nhân trong câu bị động; (3) phương tiện/nguyên nhân. 「による N」 khi bổ nghĩa danh từ.', 552, '2026-08-29 06:52:54.123', '2026-08-29 06:52:54.123', 'N3', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5820, 'V/A/N(thể thường) + かもしれない', 'có thể ~, có lẽ ~', 'Mức độ chắc chắn thấp hơn 「でしょう / だろう」. Dạng lịch sự: かもしれません. Nói tắt: かも.', 552, '2026-08-29 06:52:54.133', '2026-08-29 06:52:54.133', 'N3', 'neutral', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5821, 'V(từ điển/ない) + ことにする / ことになる', 'quyết định ~ / (được) quyết định là ~', '「ことにする」: bản thân quyết định. 「ことになる」: quyết định do hoàn cảnh/người khác. 「ことになっている」: quy định, lịch trình.', 552, '2026-08-29 06:52:54.142', '2026-08-29 06:52:54.142', 'N3', 'neutral', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5822, 'V(た) + ばかり', 'vừa mới ~ xong', 'Nhấn mạnh cảm giác chủ quan rằng việc vừa xảy ra, khác 「たところ」 (khách quan về thời điểm).', 552, '2026-08-29 06:52:54.152', '2026-08-29 06:52:54.152', 'N3', 'neutral', 10);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5823, 'V(từ điển) + ところ / V(ている) + ところ / V(た) + ところ', 'sắp / đang / vừa mới làm ~', 'Diễn tả giai đoạn của hành động theo thời gian. 〜ているところ nhấn mạnh "ngay lúc này đang".', 552, '2026-08-29 06:52:54.162', '2026-08-29 06:52:54.162', 'N3', 'neutral', 11);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5824, 'V/A/N(thể thường) + そうだ (nghe nói)', 'nghe nói rằng ~', 'Truyền đạt thông tin nghe được. Không chia đuôi. Nguồn tin: 「〜によると」. Khác với 「そうだ」 dạng có vẻ (bỏ い/だ).', 553, '2026-08-29 06:52:54.721', '2026-08-29 06:52:54.721', 'N3', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5825, 'V(ます bỏ)/A + そうだ (có vẻ)', 'trông có vẻ ~, sắp ~', 'Phán đoán từ vẻ bề ngoài. いい → よさそう, ない → なさそう. Không dùng với đặc điểm nhìn rõ ràng (きれい, 赤い).', 553, '2026-08-29 06:52:54.729', '2026-08-29 06:52:54.729', 'N3', 'neutral', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5826, 'V/A/N(thể thường) + ようだ / みたいだ', 'hình như ~, có vẻ như ~ (suy đoán theo cảm nhận)', '「ようだ」 trang trọng hơn, 「みたいだ」 hội thoại. Căn cứ vào quan sát/cảm giác trực tiếp của người nói. N + のようだ / N + みたいだ.', 553, '2026-08-29 06:52:54.735', '2026-08-29 06:52:54.735', 'N3', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5827, 'V/A/N(thể thường) + らしい', 'nghe nói / hình như ~ (theo thông tin bên ngoài)', 'Suy đoán dựa trên thông tin nghe/đọc được, trách nhiệm thông tin ít hơn. N + らしい còn nghĩa "đúng chất ~" (男らしい).', 553, '2026-08-29 06:52:54.741', '2026-08-29 06:52:54.741', 'N3', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5828, 'V(て) + ある', '(đồ vật) đã được làm sẵn và giữ nguyên trạng thái', 'Tha động từ + てある: nhấn mạnh kết quả có chủ đích còn lưu lại. Khác 〜ている (tự động từ, trạng thái tự nhiên).', 553, '2026-08-29 06:52:54.755', '2026-08-29 06:52:54.755', 'N3', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5829, 'V(て) + おく', 'làm sẵn ~ để chuẩn bị / cứ để nguyên ~', 'Chuẩn bị trước cho tương lai, hoặc để mặc nguyên trạng thái. Nói tắt: 〜とく / 〜どく.', 553, '2026-08-29 06:52:54.766', '2026-08-29 06:52:54.766', 'N3', 'neutral', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5830, 'V(て) + しまう', 'lỡ ~ mất rồi / làm xong hẳn ~', 'Sắc thái tiếc nuối, hối hận, hoặc hoàn thành trọn vẹn. Nói tắt: 〜ちゃう / 〜じゃう.', 553, '2026-08-29 06:52:54.772', '2026-08-29 06:52:54.772', 'N3', 'neutral', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5831, 'V(từ điển/ない) + ことがある', 'có lúc ~, thỉnh thoảng ~', 'Diễn tả việc thỉnh thoảng xảy ra. Khác 「V(た)ことがある」 (đã từng ~ - kinh nghiệm).', 553, '2026-08-29 06:52:54.783', '2026-08-29 06:52:54.783', 'N3', 'neutral', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6977, '〜ばかりになっている', 'chỉ còn chờ …', NULL, 16301, '2026-09-26 12:15:07.612', '2026-09-26 12:15:07.612', 'N2', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5832, 'V(た) + まま / N + のまま', 'để nguyên trạng thái ~ mà ~', 'Một trạng thái được giữ nguyên trong khi hành động khác diễn ra (thường là bất thường).', 553, '2026-08-29 06:52:54.789', '2026-08-29 06:52:54.789', 'N3', 'neutral', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5833, 'V(từ điển) + につれて / にしたがって', 'càng ~ thì càng ~ (biến đổi song song)', 'Hai sự việc biến đổi cùng chiều theo thời gian. Dùng với danh từ chỉ sự biến hóa: 時間, 成長.', 553, '2026-08-29 06:52:54.799', '2026-08-29 06:52:54.799', 'N3', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5834, 'N + として', 'với tư cách là ~, coi như là ~', 'Chỉ tư cách, vai trò, danh nghĩa. 「〜としては」 nhấn mạnh, 「〜としても」 kết hợp giả định.', 553, '2026-08-29 06:52:54.805', '2026-08-29 06:52:54.805', 'N3', 'written', 10);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5835, 'V(bị động) — られる / れる', 'bị / được ~', 'Nhóm I: あ段 + れる. Nhóm II: 〜られる. する→される, くる→こられる. Có bị động trực tiếp, gián tiếp (thiệt hại), và bị động sự vật.', 554, '2026-08-29 06:52:55.371', '2026-08-29 06:52:55.371', 'N3', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5836, 'V(sai khiến) — させる / せる', 'bắt / cho phép ~ làm ~', 'Nhóm I: あ段 + せる. Nhóm II: 〜させる. Người bị sai khiến đánh dấu bằng を (tự động từ) hoặc に (tha động từ).', 554, '2026-08-29 06:52:55.385', '2026-08-29 06:52:55.385', 'N3', 'neutral', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5837, 'V(sai khiến bị động) — させられる / せられる', 'bị bắt phải ~ (miễn cưỡng)', 'Nhóm I có thể rút gọn 〜される (trừ đuôi す). Diễn tả bị ép làm điều không muốn.', 554, '2026-08-29 06:52:55.398', '2026-08-29 06:52:55.398', 'N3', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5838, 'お + V(ます bỏ) + になる / ご + N + になる', 'tôn kính ngữ (hành động của người trên)', 'Kính ngữ dạng chung. Một số động từ có dạng riêng: いらっしゃる, おっしゃる,召し上がる, ご覧になる, なさる.', 554, '2026-08-29 06:52:55.409', '2026-08-29 06:52:55.409', 'N3', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5839, 'お + V(ます bỏ) + する / いたす', 'khiêm nhường ngữ (hành động của mình hướng tới người trên)', '「いたす」 khiêm nhường hơn. Dạng riêng: 参る, 申す/申し上げる, いただく, 拝見する, 伺う.', 554, '2026-08-29 06:52:55.422', '2026-08-29 06:52:55.422', 'N3', 'formal', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5840, 'V(て) + いただけませんか / くださいませんか', 'xin ~ có thể ~ giúp tôi được không ạ?', 'Nhờ vả lịch sự. 「〜ていただけませんか」 khiêm nhường hơn 「〜てくださいませんか」. Lịch sự hơn nữa: 〜ていただけないでしょうか.', 554, '2026-08-29 06:52:55.433', '2026-08-29 06:52:55.433', 'N3', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5841, 'V(て) + くれる / もらう / あげる (授受)', 'ai đó làm cho tôi / tôi nhận được / tôi làm cho ai', 'Hệ thống cho–nhận hành động. Chú ý điểm nhìn: 〜てくれる (hướng về mình), 〜てあげる (từ mình ra), 〜てもらう (mình được lợi).', 554, '2026-08-29 06:52:55.442', '2026-08-29 06:52:55.442', 'N3', 'neutral', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5842, 'V(て) + ほしい / V(ない) でほしい', 'muốn ai đó làm / đừng làm ~', 'Nguyện vọng về hành động của người khác. Người đó đánh dấu bằng に (hoặc が). Trang trọng: 〜ていただきたい.', 554, '2026-08-29 06:52:55.452', '2026-08-29 06:52:55.452', 'N3', 'neutral', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5843, 'V(từ điển/ない) + ように言う / 伝える', 'bảo/nhắn (ai) rằng hãy ~', 'Truyền đạt gián tiếp mệnh lệnh, yêu cầu. Cũng dùng 〜ようにお願いする, 〜ように注意する.', 554, '2026-08-29 06:52:55.467', '2026-08-29 06:52:55.467', 'N3', 'neutral', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5844, 'V(受身/使役) trong văn viết trang trọng', 'kính ngữ dạng bị động — られる chỉ sự tôn kính', '「れる/られる」 còn dùng như kính ngữ nhẹ, thường trong văn nói lịch sự công sở.', 554, '2026-08-29 06:52:55.48', '2026-08-29 06:52:55.48', 'N3', 'formal', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5845, 'V/A/N(thể thường) + のに', 'mặc dù ~ nhưng (bất mãn, ngoài mong đợi)', 'Mang cảm xúc tiếc nuối, bất bình. N/Na + なのに. Không dùng để nêu ý định/mệnh lệnh ở vế sau.', 555, '2026-08-29 06:52:56.214', '2026-08-29 06:52:56.214', 'N3', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5846, 'V/A/N(thể thường) + くせに', 'mặc dù ~ vậy mà (chê trách, coi thường)', 'Giống 「のに」 nhưng sắc thái phê phán mạnh, hàm ý xem thường đối tượng. Chủ ngữ hai vế phải cùng người.', 555, '2026-08-29 06:52:56.226', '2026-08-29 06:52:56.226', 'N3', 'spoken', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5847, 'V(từ điển) + ばかりでなく / だけでなく', 'không chỉ ~ mà còn ~', 'Bổ sung thông tin. Thường đi với 「〜も」 ở vế sau. Trang trọng hơn: 〜のみならず.', 555, '2026-08-29 06:52:56.239', '2026-08-29 06:52:56.239', 'N3', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5848, 'V(từ điển/ない) + わけだ', 'hóa ra là ~, thảo nào ~', 'Rút ra kết luận hợp lý từ tình huống. Khác 「わけがない」 (không thể nào), 「わけではない」 (không hẳn là).', 555, '2026-08-29 06:52:56.251', '2026-08-29 06:52:56.251', 'N3', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5849, 'V(từ điển/ない) + わけにはいかない', 'không thể ~ được (vì lý do đạo lý/hoàn cảnh)', 'Không thể làm vì ràng buộc xã hội, tâm lý. 「Vないわけにはいかない」 = buộc phải làm.', 555, '2026-08-29 06:52:56.264', '2026-08-29 06:52:56.264', 'N3', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5850, 'V(た/ている) + ところに / ところへ / ところを', 'đúng lúc đang ~ thì ~', 'Một việc xen vào đúng thời điểm của việc khác. 「ところを」 khi vế sau là hành động tác động lên chủ thể.', 555, '2026-08-29 06:52:56.276', '2026-08-29 06:52:56.276', 'N3', 'neutral', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5851, 'V(ます bỏ) + っぱなし', 'cứ để ~ mãi (không xử lý)', 'Trạng thái bị bỏ mặc, thường tiêu cực. 出しっぱなし, つけっぱなし, 立ちっぱなし.', 555, '2026-08-29 06:52:56.287', '2026-08-29 06:52:56.287', 'N3', 'spoken', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5852, 'V(ます bỏ) + がち', 'hay bị ~, có xu hướng ~ (tiêu cực)', 'Khuynh hướng thường xuyên xảy ra, đa phần không mong muốn. 病気がち, 遠慮がち, 曇りがち.', 555, '2026-08-29 06:52:56.3', '2026-08-29 06:52:56.3', 'N3', 'neutral', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5853, 'N + っぽい / V(ます bỏ) + っぽい', 'có vẻ ~, giống ~, dễ ~', 'Cảm nhận chủ quan về tính chất. 子どもっぽい, 忘れっぽい, 白っぽい, 怒りっぽい.', 555, '2026-08-29 06:52:56.308', '2026-08-29 06:52:56.308', 'N3', 'spoken', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5854, 'V(từ điển) + 一方だ', 'ngày càng ~ (một chiều)', 'Xu hướng biến đổi liên tục theo một hướng, thường xấu đi. 「〜一方で」 = mặt khác thì (đối lập).', 555, '2026-08-29 06:52:56.316', '2026-08-29 06:52:56.316', 'N3', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5855, 'V(た) + ら / なら / と / ば (ôn 4 điều kiện)', 'nếu ~ thì ~', '「と」: quy luật tất yếu. 「ば」: điều kiện chung, không dùng ý chí ở vế sau nếu vế trước là động từ. 「たら」: linh hoạt nhất. 「なら」: dựa trên điều người kia vừa nói.', 589, '2026-08-29 06:52:56.958', '2026-08-29 06:52:56.958', 'N3', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5856, 'たとえ + V/A/N(て) + も', 'cho dù ~ đi nữa thì cũng ~', 'Nhấn mạnh sự nhượng bộ. 「たとえ」 đi kèm 「〜ても」 để làm rõ giả định.', 589, '2026-08-29 06:52:56.973', '2026-08-29 06:52:56.973', 'N3', 'neutral', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5857, 'V/A/N(thể thường) + ば + ～のに / たら + ～のに', 'giá mà ~ thì đã ~ (tiếc nuối)', 'Giả định trái thực tế kèm cảm xúc tiếc. Vế sau thường bỏ lửng: 「〜ばよかった(のに)」.', 589, '2026-08-29 06:52:56.981', '2026-08-29 06:52:56.981', 'N3', 'spoken', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5858, 'N + くらい / ぐらい', 'khoảng ~; đến mức ~', 'Chỉ mức độ ước lượng, hoặc mức độ tối thiểu/thấp ("chỉ chừng đó thôi").', 589, '2026-08-29 06:52:56.992', '2026-08-29 06:52:56.992', 'N3', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5859, 'N + ほど / V(từ điển) + ほど', 'đến mức ~; không ~ bằng ~', '「〜ほど〜ない」: so sánh, "A không bằng B". Cũng chỉ mức độ cao: 「泣きたいほど」.', 589, '2026-08-29 06:52:57.001', '2026-08-29 06:52:57.001', 'N3', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5861, 'V(ます bỏ) + ながら (đối lập)', 'tuy ~ nhưng ~', 'Ngoài nghĩa "vừa…vừa", 「ながら(も)」 còn chỉ sự đối lập. 「残念ながら」, 「知っていながら」.', 589, '2026-08-29 06:52:57.035', '2026-08-29 06:52:57.035', 'N3', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6512, 'V て くれます', '(ai đó) làm V cho tôi', NULL, 16164, '2026-09-26 06:22:23.054', '2026-09-26 06:22:23.054', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5862, 'V/A/N(thể thường) + みたいに / みたいな N', 'như là ~, giống ~', 'Bản hội thoại của 「〜のように / のような」. So sánh, ví von.', 589, '2026-08-29 06:52:57.056', '2026-08-29 06:52:57.056', 'N3', 'spoken', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5864, 'N + からいうと / からみると / からいえば', 'xét về mặt ~, từ góc độ ~', 'Nêu góc nhìn/tiêu chí để đánh giá. Gần với 「〜にとって」 nhưng thiên về "đứng ở lập trường đó mà nói".', 589, '2026-08-29 06:52:57.082', '2026-08-29 06:52:57.082', 'N3', 'neutral', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5865, 'V(た) + り + V(た) + り + する', 'nào là ~ nào là ~ (liệt kê hành động)', 'Ôn tập N4 nhưng hay ra ở N3: liệt kê không đầy đủ các hành động. Cũng dùng cho trạng thái đối lập (泣いたり笑ったり).', 589, '2026-08-29 06:52:57.095', '2026-08-29 06:52:57.095', 'N3', 'neutral', 10);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5866, 'V(た/từ điển) + とたん(に)', 'ngay khoảnh khắc ~ thì (bất ngờ)', 'Ngay lập tức xảy ra việc thứ hai, thường ngoài ý muốn. Vế sau ở quá khứ, không dùng cho ý chí/mệnh lệnh.', 556, '2026-08-29 06:52:57.796', '2026-08-29 06:52:57.796', 'N2', 'written', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5867, 'V(từ điển) + か + V(ない) + かのうちに', 'gần như đồng thời, chưa kịp ~ đã ~', 'Hai việc xảy ra sát nhau đến mức khó phân biệt trước sau.', 556, '2026-08-29 06:52:57.806', '2026-08-29 06:52:57.806', 'N2', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5868, 'V(た) + かと思うと / かと思ったら', 'vừa mới ~ đã ~ ngay (thay đổi nhanh, ngạc nhiên)', 'Người nói ngạc nhiên vì hai việc trái ngược nối tiếp quá nhanh. Không dùng cho việc của bản thân, không dùng ý chí/mệnh lệnh ở vế sau.', 556, '2026-08-29 06:52:57.817', '2026-08-29 06:52:57.817', 'N2', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5869, 'V(từ điển) + なり', 'vừa ~ là ~ ngay lập tức', 'Chủ thể làm ngay việc thứ hai (thường bất thường) ngay sau việc thứ nhất. Chủ ngữ hai vế cùng người, không phải bản thân người nói.', 556, '2026-08-29 06:52:57.831', '2026-08-29 06:52:57.831', 'N2', 'written', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5870, 'V(た) + きり / N + きり', 'kể từ khi ~ thì không ~ nữa; chỉ ~', 'Sau một việc thì trạng thái đó kéo dài, không có tiếp diễn mong đợi. 「〜きり」 còn nghĩa "chỉ có, duy nhất".', 556, '2026-08-29 06:52:57.846', '2026-08-29 06:52:57.846', 'N2', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5871, 'N + の際(に) / V(từ điển/た) + 際(に)', 'khi, dịp, lúc ~ (trang trọng)', 'Bản trang trọng của 「とき」, hay dùng trong thông báo, chỉ dẫn. 「〜に際して」 = nhân dịp/khi bắt đầu ~.', 556, '2026-08-29 06:52:57.86', '2026-08-29 06:52:57.86', 'N2', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5872, 'N + において / における N', 'tại, trong, ở ~ (bối cảnh trang trọng)', 'Chỉ nơi chốn, lĩnh vực, thời đại trong văn viết. Tương đương 「で」 nhưng trang trọng.', 556, '2026-08-29 06:52:57.874', '2026-08-29 06:52:57.874', 'N2', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5873, 'N + をはじめ(として)', 'tiêu biểu là ~, bắt đầu từ ~ và nhiều thứ khác', 'Nêu ví dụ tiêu biểu nhất trong nhóm rồi ngụ ý còn nhiều cái khác.', 556, '2026-08-29 06:52:57.889', '2026-08-29 06:52:57.889', 'N2', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5874, 'N + にわたって / にわたる N', 'suốt, trải dài ~ (thời gian/phạm vi rộng)', 'Nhấn mạnh quy mô rộng lớn về thời gian, không gian, số lần.', 556, '2026-08-29 06:52:57.903', '2026-08-29 06:52:57.903', 'N2', 'written', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5875, 'N + を通じて / を通して', 'thông qua ~; suốt trong ~', 'Chỉ phương tiện/trung gian, hoặc chỉ toàn bộ khoảng thời gian (một năm, cả đời).', 556, '2026-08-29 06:52:57.917', '2026-08-29 06:52:57.917', 'N2', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5876, 'N + に基づいて / に基づく N', 'dựa trên, căn cứ vào ~', 'Lấy điều gì làm cơ sở/nền tảng để thực hiện. Trang trọng, văn viết.', 557, '2026-08-29 06:52:58.56', '2026-08-29 06:52:58.56', 'N2', 'written', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5877, 'N + に応じて / に応じた N', 'tùy theo, tương ứng với ~', 'Thay đổi linh hoạt cho phù hợp với điều kiện/tình huống.', 557, '2026-08-29 06:52:58.574', '2026-08-29 06:52:58.574', 'N2', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5878, 'N + にとって(は)', 'đối với ~ (mà nói)', 'Nêu lập trường để đánh giá điều gì đó. Vế sau thường là tính từ đánh giá (大切, 難しい).', 557, '2026-08-29 06:52:58.585', '2026-08-29 06:52:58.585', 'N2', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5880, 'N + に対して / に対する N', 'đối với ~, hướng về ~; trái lại', 'Chỉ đối tượng của thái độ/hành động. Cũng dùng để đối chiếu hai vế tương phản.', 557, '2026-08-29 06:52:58.608', '2026-08-29 06:52:58.608', 'N2', 'written', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5881, 'N + をめぐって / をめぐる N', 'xoay quanh, liên quan đến ~ (tranh luận)', 'Chủ đề của tranh cãi, thảo luận, xung đột.', 557, '2026-08-29 06:52:58.62', '2026-08-29 06:52:58.62', 'N2', 'written', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5882, 'N + につけ(て) / V(từ điển) + につけ', 'mỗi khi ~ là lại ~ (cảm xúc tự nhiên)', 'Một kích thích luôn khơi dậy một cảm xúc/suy nghĩ. Hay đi với 見る, 聞く, 考える.', 557, '2026-08-29 06:52:58.632', '2026-08-29 06:52:58.632', 'N2', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5883, 'N + からすると / からすれば / からいって', 'xét từ ~, dựa vào ~ mà nói', 'Nêu căn cứ để phán đoán/đánh giá. 「〜からして」 = ngay cả ~ (nêu ví dụ cực đoan).', 557, '2026-08-29 06:52:58.643', '2026-08-29 06:52:58.643', 'N2', 'neutral', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5884, 'N + につき', 'do ~ (lý do, trang trọng); mỗi ~', 'Thường thấy trên biển thông báo. Nghĩa thứ hai: đơn giá "mỗi đơn vị".', 557, '2026-08-29 06:52:58.655', '2026-08-29 06:52:58.655', 'N2', 'formal', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5885, 'N + のもとで / のもとに', 'dưới sự ~, trong điều kiện ~', 'Dưới sự chỉ đạo, ảnh hưởng, điều kiện của ai/cái gì.', 557, '2026-08-29 06:52:58.666', '2026-08-29 06:52:58.666', 'N2', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5887, 'V(từ điển) + よりほかない / ほかはない', 'chỉ còn cách ~, không còn cách nào khác', 'Chỉ có một lựa chọn duy nhất. Tương đương 「〜しかない」 nhưng trang trọng hơn.', 558, '2026-08-29 06:52:59.431', '2026-08-29 06:52:59.431', 'N2', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5888, 'V(ない) + ことには', 'nếu không ~ thì (không thể ~)', 'Điều kiện tiên quyết. Vế sau luôn mang nghĩa phủ định.', 558, '2026-08-29 06:52:59.441', '2026-08-29 06:52:59.441', 'N2', 'neutral', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5889, 'V/A/N(thể thường) + どころか', 'nói gì đến ~, chứ đừng nói ~; trái lại còn ~', 'Phủ định mạnh kỳ vọng, thực tế còn ngược lại hoặc kém xa.', 558, '2026-08-29 06:52:59.452', '2026-08-29 06:52:59.452', 'N2', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5890, 'V/A/N(thể thường) + わけがない / はずがない', 'không thể nào ~, làm gì có chuyện ~', 'Phủ định khả năng một cách chắc chắn dựa trên lý lẽ. Nói tắt: わけない.', 558, '2026-08-29 06:52:59.466', '2026-08-29 06:52:59.466', 'N2', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5891, 'V/A/N(thể thường) + に違いない', 'chắc chắn là ~, nhất định ~', 'Người nói tin chắc dựa trên căn cứ. Trang trọng hơn 「はずだ」. Rất chắc: 「に決まっている」 (hội thoại).', 558, '2026-08-29 06:52:59.48', '2026-08-29 06:52:59.48', 'N2', 'written', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5892, 'N + にすぎない', 'chẳng qua chỉ là ~', 'Đánh giá thấp, coi nhẹ mức độ/tầm quan trọng của sự việc.', 558, '2026-08-29 06:52:59.493', '2026-08-29 06:52:59.493', 'N2', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5893, 'N + にほかならない', 'chính là ~, không gì khác ngoài ~', 'Khẳng định mạnh mẽ rằng đó chính xác là điều gì đó.', 558, '2026-08-29 06:52:59.506', '2026-08-29 06:52:59.506', 'N2', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5895, 'V/A/N(thể thường) + と言っても', 'tuy nói là ~ nhưng (không nhiều như tưởng)', 'Đính chính lại kỳ vọng của người nghe sau khi nêu một điều gì đó.', 558, '2026-08-29 06:52:59.531', '2026-08-29 06:52:59.531', 'N2', 'neutral', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5896, 'V/A/N(thể thường) + からには /以上(は)', 'đã ~ thì (đương nhiên phải ~)', 'Nêu tiền đề rồi rút ra kết luận về nghĩa vụ/quyết tâm. Vế sau: べきだ, なければならない, つもりだ.', 559, '2026-08-29 06:53:00.318', '2026-08-29 06:53:00.318', 'N2', 'written', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5897, 'V(た) + ところで', 'cho dù ~ đi nữa cũng (vô ích)', 'Giả định nhượng bộ, vế sau luôn tiêu cực/vô nghĩa. Thường có 「今さら」, 「いくら」.', 559, '2026-08-29 06:53:00.332', '2026-08-29 06:53:00.332', 'N2', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5898, 'V/A/N + にしろ / にせよ / にしても', 'dù ~ đi chăng nữa, cho dù là ~', 'Nhượng bộ. Dạng 「AにしろBにしろ」 = dù A hay B. 「にせよ」 trang trọng nhất.', 559, '2026-08-29 06:53:00.345', '2026-08-29 06:53:00.345', 'N2', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5899, 'V/A/N(thể thường) + わりに(は)', 'so với ~ thì lại (khác kỳ vọng)', 'Kết quả không tương xứng với tiền đề (theo hướng bất ngờ).', 559, '2026-08-29 06:53:00.359', '2026-08-29 06:53:00.359', 'N2', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5900, 'V(từ điển/ない) + べきだ / べきではない', 'nên / không nên ~ (theo lẽ phải)', 'Bổn phận, lẽ phải chung. する → すべき (hoặc するべき). Không dùng cho luật lệ cứng nhắc (dùng なければならない).', 559, '2026-08-29 06:53:00.373', '2026-08-29 06:53:00.373', 'N2', 'written', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5901, 'N + くらい / ほど + N + はない', 'không gì ~ bằng ~ (so sánh nhất)', 'Nhấn mạnh mức độ cao nhất bằng cách phủ định mọi thứ khác.', 559, '2026-08-29 06:53:00.387', '2026-08-29 06:53:00.387', 'N2', 'neutral', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5902, 'V(た) + あげく(に) / N + のあげく', 'sau khi ~ mãi, cuối cùng thì ~ (kết quả xấu)', 'Sau một quá trình dài (thường vất vả) mới đi đến kết cục không hay.', 559, '2026-08-29 06:53:00.4', '2026-08-29 06:53:00.4', 'N2', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5903, 'V(た) + 末(に) / N + の末(に)', 'sau khi ~ rốt cuộc thì ~ (kết quả trung tính/tốt)', 'Sau một quá trình cân nhắc/nỗ lực dài đi đến kết luận. Sắc thái trung tính hơn 「あげく」.', 559, '2026-08-29 06:53:00.413', '2026-08-29 06:53:00.413', 'N2', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5904, 'V(ます bỏ) +得る / 得ない', 'có thể / không thể xảy ra ~', 'Khả năng về mặt lý thuyết. 得る đọc là える hoặc うる (từ điển: うる), 得ない luôn là えない.', 559, '2026-08-29 06:53:00.424', '2026-08-29 06:53:00.424', 'N2', 'written', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5905, 'V(từ điển) + まい / V + まいか', 'quyết không ~; chẳng lẽ không ~', 'Phủ định ý chí (もう〜まい) hoặc phủ định phỏng đoán (〜ではあるまいか). Văn viết, cổ.', 559, '2026-08-29 06:53:00.435', '2026-08-29 06:53:00.435', 'N2', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5906, 'N + のみならず / V/A(thể thường) + のみならず', 'không những ~ mà còn ~', 'Bản văn viết trang trọng của 「〜だけでなく」. Vế sau thường có 「も」.', 594, '2026-08-29 06:53:01.186', '2026-08-29 06:53:01.186', 'N2', 'written', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5907, 'N + はもちろん / はもとより', 'không cần nói tới ~, đương nhiên là ~', '「〜はもとより」 trang trọng hơn 「〜はもちろん」. Cả hai nêu điều hiển nhiên rồi thêm điều đáng chú ý hơn.', 594, '2026-08-29 06:53:01.199', '2026-08-29 06:53:01.199', 'N2', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5908, 'V(た/ている) + 上で / N + の上で', 'sau khi ~ rồi (mới ~)', 'Làm việc A trước như một bước cần thiết, rồi mới làm B. Khác 「〜上に」 (hơn nữa).', 594, '2026-08-29 06:53:01.213', '2026-08-29 06:53:01.213', 'N2', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5909, 'V/A/N(thể thường) + 上に', 'không những ~ mà còn ~ (thêm vào)', 'Chồng thêm một yếu tố cùng chiều (tốt + tốt, hoặc xấu + xấu). N/Na + である上に.', 594, '2026-08-29 06:53:01.229', '2026-08-29 06:53:01.229', 'N2', 'written', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5910, 'V(từ điển/ない) + ことなく', 'mà không ~, không hề ~', 'Bản văn viết của 「〜ないで」. Nhấn mạnh một việc hoàn toàn không xảy ra.', 594, '2026-08-29 06:53:01.243', '2026-08-29 06:53:01.243', 'N2', 'written', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5911, 'V(た) + 結果 / N + の結果', 'kết quả của việc ~ là ~', 'Nêu kết cục sau một quá trình. Trung tính, hay dùng trong báo cáo.', 594, '2026-08-29 06:53:01.255', '2026-08-29 06:53:01.255', 'N2', 'written', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5912, 'V(た) + あまり(に) / N + のあまり', 'vì quá ~ nên ~', 'Cảm xúc/trạng thái quá mức dẫn đến hệ quả (thường bất thường). Hay đi với 心配, 緊張, 驚き, うれしさ.', 594, '2026-08-29 06:53:01.274', '2026-08-29 06:53:01.274', 'N2', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5914, 'V(ます bỏ) + かける / かけの N', 'đang ~ dở, làm ~ chừng', 'Hành động bắt đầu nhưng chưa xong. 読みかけの本, 食べかけ, 言いかけて やめる.', 594, '2026-08-29 06:53:01.29', '2026-08-29 06:53:01.29', 'N2', 'neutral', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5915, 'V/A/N(thể thường) + ものだ', 'vốn dĩ ~, thường thì ~ (chân lý/hồi tưởng/cảm thán)', 'Nhiều sắc thái: chân lý chung, hồi tưởng 「〜たものだ」, cảm thán, lời khuyên 「〜ものではない」.', 594, '2026-08-29 06:53:01.298', '2026-08-29 06:53:01.298', 'N2', 'neutral', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5916, 'N + をもって', 'bằng ~; kể từ ~ (mốc thời gian trang trọng)', 'Nghĩa 1: phương tiện/tiêu chuẩn (身をもって). Nghĩa 2: mốc thời gian trong thông báo chính thức.', 560, '2026-08-29 06:53:01.788', '2026-08-29 06:53:01.788', 'N1', 'formal', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5917, 'N + をよそに', 'bất chấp ~, phớt lờ ~', 'Hành động phớt lờ mối lo ngại/kỳ vọng/phản đối của người xung quanh. Sắc thái phê phán.', 560, '2026-08-29 06:53:01.797', '2026-08-29 06:53:01.797', 'N1', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5918, 'N + をおいて(ほかに~ない)', 'ngoài ~ ra thì không còn ~', 'Khẳng định đối tượng là duy nhất, không có lựa chọn thay thế.', 560, '2026-08-29 06:53:01.805', '2026-08-29 06:53:01.805', 'N1', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5920, 'N + ならでは(の)', 'chỉ có ~ mới có được (đặc trưng riêng)', 'Khen ngợi nét độc đáo mà chỉ đối tượng đó mới làm/có được.', 560, '2026-08-29 06:53:01.838', '2026-08-29 06:53:01.838', 'N1', 'written', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5921, 'V(ます bỏ) + っこない', 'làm gì có chuyện ~, không đời nào ~', 'Phủ định khả năng, khẩu ngữ mạnh. Tương đương 「〜わけがない / 〜はずがない」.', 560, '2026-08-29 06:53:01.847', '2026-08-29 06:53:01.847', 'N1', 'spoken', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5922, 'V/A/N(thể thường) + といったらない / といったらありはしない', '~ vô cùng, không thể tả nổi ~', 'Cảm thán mức độ cực đại (tốt hoặc xấu). Khẩu ngữ: 〜ったらない.', 560, '2026-08-29 06:53:01.856', '2026-08-29 06:53:01.856', 'N1', 'spoken', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6513, 'V て もらいます', 'được (ai đó) làm V cho', NULL, 16164, '2026-09-26 06:22:23.062', '2026-09-26 06:22:23.062', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7337, '〜折（に）', 'vào dịp, khi … (trang trọng)', NULL, 16404, '2026-09-26 12:15:21.446', '2026-09-26 12:15:21.446', 'N1', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5923, 'V(た) + が最後 / V(たら) + 最後', 'một khi đã ~ thì (chắc chắn hậu quả xấu)', 'Nếu làm việc đó thì nhất định sẽ dẫn đến kết cục tồi tệ, không cứu vãn.', 560, '2026-08-29 06:53:01.864', '2026-08-29 06:53:01.864', 'N1', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5924, 'N + ずくめ', 'toàn là ~, chỗ nào cũng ~', 'Toàn bộ đều là cùng một thứ. いいことずくめ, 黒ずくめ, 記録ずくめ.', 560, '2026-08-29 06:53:01.872', '2026-08-29 06:53:01.872', 'N1', 'written', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5925, 'V(ます bỏ) + そびれる', 'lỡ mất cơ hội ~, định làm mà không làm được', '「〜そびれる」: định làm nhưng lỡ dịp/không làm được. Hay gặp: 言いそびれる, 食べそびれる, 聞きそびれる, 寝そびれる.', 560, '2026-08-29 06:53:01.883', '2026-08-29 06:53:01.883', 'N1', 'neutral', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5926, 'V(た/từ điển) + が早いか', 'vừa ~ là lập tức ~', 'Gần như đồng thời, việc sau xảy ra ngay tức khắc. Văn viết, tương tự 「〜なり」, 「〜そばから」.', 561, '2026-08-29 06:53:02.649', '2026-08-29 06:53:02.649', 'N1', 'written', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5927, 'V(từ điển) + そばから', 'vừa ~ xong lại ~ ngay (lặp đi lặp lại)', 'Việc vừa làm xong thì tình trạng cũ tái diễn ngay, thường gây bực bội.', 561, '2026-08-29 06:53:02.663', '2026-08-29 06:53:02.663', 'N1', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5928, 'V/A/N(thể thường) + であれ / であろうと', 'dù là ~ đi nữa', 'Nhượng bộ trang trọng. Dạng 「たとえ〜であれ」, 「どんなN であれ」.', 561, '2026-08-29 06:53:02.678', '2026-08-29 06:53:02.678', 'N1', 'formal', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5929, 'V(よう) + が / と + V(まい) + が', 'dù ~ hay không ~ cũng mặc', 'Kết quả không đổi bất kể lựa chọn nào. 「〜(よ)うが〜まいが」.', 561, '2026-08-29 06:53:02.691', '2026-08-29 06:53:02.691', 'N1', 'written', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5930, 'N + いかんによっては / N + いかんだ', 'tùy vào ~ (mà có thể khác đi)', 'Trang trọng, văn viết/hành chính. 「〜いかんにかかわらず」 = bất kể ~ thế nào.', 561, '2026-08-29 06:53:02.703', '2026-08-29 06:53:02.703', 'N1', 'formal', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5931, 'V(ない) + くもない / ないものでもない', 'cũng không hẳn là không ~ (chấp nhận có mức độ)', 'Phủ định kép nhẹ, biểu thị sự đồng ý dè dặt hoặc khả năng có điều kiện.', 561, '2026-08-29 06:53:02.715', '2026-08-29 06:53:02.715', 'N1', 'written', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5932, 'V/A/N(thể thường) + まじ / まじき', 'không được phép ~ (điều không thể tha thứ)', '「あるまじき N」: hành vi không xứng với tư cách. Rất trang trọng, cổ.', 561, '2026-08-29 06:53:02.729', '2026-08-29 06:53:02.729', 'N1', 'formal', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5933, 'V(た) + ら + V(た) + で / V(ば) + V(た) + で', 'nếu ~ thì cũng có cái khó của ~ (dù thế nào cũng có vấn đề)', 'Dù tình huống xảy ra hay không thì đều có mặt phiền toái riêng. 「〜なら〜で」.', 561, '2026-08-29 06:53:02.742', '2026-08-29 06:53:02.742', 'N1', 'spoken', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5934, 'V(ない) + ではおかない / ずにはおかない', 'nhất định sẽ ~ cho bằng được; tất yếu gây ra ~', 'Ý chí mạnh mẽ, hoặc tác động tự nhiên tất yếu (cảm xúc). Trang trọng.', 561, '2026-08-29 06:53:02.755', '2026-08-29 06:53:02.755', 'N1', 'formal', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5935, 'V(ない) + では済まない / ずには済まない', 'không ~ thì không xong, buộc phải ~', 'Áp lực xã hội buộc phải làm gì đó, nếu không sẽ có hậu quả.', 561, '2026-08-29 06:53:02.769', '2026-08-29 06:53:02.769', 'N1', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5936, 'V(ます bỏ) + かねる / かねない', 'khó lòng ~, không thể ~ / có nguy cơ ~', '「〜かねる」: không thể làm (dù muốn), lịch sự. 「〜かねない」: có khả năng xảy ra điều xấu.', 562, '2026-08-29 06:53:03.338', '2026-08-29 06:53:03.338', 'N1', 'formal', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5937, 'V/A/N(thể thường) + とあって', 'vì là ~ (tình huống đặc biệt) nên ~', 'Do hoàn cảnh đặc biệt nên đương nhiên có kết quả tương ứng. Văn viết, tường thuật.', 562, '2026-08-29 06:53:03.344', '2026-08-29 06:53:03.344', 'N1', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5938, 'V/A/N(thể thường) + とはいえ', 'tuy nói là ~ nhưng thực tế ~', 'Nhượng bộ trang trọng, tương tự 「〜といっても」 nhưng văn viết hơn.', 562, '2026-08-29 06:53:03.352', '2026-08-29 06:53:03.352', 'N1', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5939, 'V(ます bỏ) + つ + V(ます bỏ) + つ', 'khi thì ~ khi thì ~ (hai hành động luân phiên)', 'Thành ngữ cố định: 行きつ戻りつ, 抜きつ抜かれつ, 持ちつ持たれつ. Văn viết cổ.', 562, '2026-08-29 06:53:03.358', '2026-08-29 06:53:03.358', 'N1', 'written', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5940, 'N + であれ N + であれ / N + といい N + といい', 'cả ~ lẫn ~ đều ~', '「〜といい〜といい」: nêu hai ví dụ tiêu biểu để đánh giá tổng thể.', 562, '2026-08-29 06:53:03.364', '2026-08-29 06:53:03.364', 'N1', 'written', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5941, 'V(た) + ならまだしも / N + ならまだしも', 'nếu là ~ thì còn được, đằng này ~', 'So sánh: trường hợp A còn chấp nhận được, nhưng B thì không.', 562, '2026-08-29 06:53:03.372', '2026-08-29 06:53:03.372', 'N1', 'written', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5942, 'V(た) + ところで + どうにもならない', 'có ~ đi nữa cũng chẳng ích gì', 'Kết hợp 「〜たところで」 với vế phủ định mạnh biểu thị sự bất lực.', 562, '2026-08-29 06:53:03.378', '2026-08-29 06:53:03.378', 'N1', 'written', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5943, 'V/N + にかこつけて', 'mượn cớ ~, viện cớ ~', 'Lấy một lý do làm cái cớ để làm việc mình muốn. Sắc thái phê phán.', 562, '2026-08-29 06:53:03.385', '2026-08-29 06:53:03.385', 'N1', 'written', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5944, 'V(ます bỏ) + ながらに(して) / N + ながらに', 'ở nguyên trạng thái ~ mà vẫn ~', 'Thành ngữ: 生まれながらに, 居ながらにして, 涙ながらに.', 562, '2026-08-29 06:53:03.392', '2026-08-29 06:53:03.392', 'N1', 'written', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5945, 'V/A/N(thể thường) + ゆえ(に) / N + ゆえの N', 'vì ~, do ~ (nguyên nhân trang trọng, cổ)', 'Bản văn viết/cổ của 「〜から / 〜ので」. N + (の)ゆえに.', 562, '2026-08-29 06:53:03.399', '2026-08-29 06:53:03.399', 'N1', 'formal', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5946, 'N + に至る / に至って / に至っては', 'đến tận mức ~, đến khi ~ (thì mới)', '「〜に至る」: đi đến một kết cục nghiêm trọng. 「〜に至って(初めて)」: mãi đến lúc đó mới. 「〜に至っては」: đến cả ~ (ví dụ cực đoan).', 598, '2026-08-29 06:53:03.888', '2026-08-29 06:53:03.888', 'N1', 'formal', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5947, 'N + にとどまらず', 'không dừng lại ở ~ mà còn lan sang ~', 'Phạm vi ảnh hưởng vượt ra ngoài mức ban đầu. Trang trọng.', 598, '2026-08-29 06:53:03.896', '2026-08-29 06:53:03.896', 'N1', 'written', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5948, 'N + をものともせず(に)', 'bất chấp ~, không hề nao núng trước ~', 'Vượt qua khó khăn/trở ngại lớn một cách dũng cảm. Đánh giá tích cực.', 598, '2026-08-29 06:53:03.906', '2026-08-29 06:53:03.906', 'N1', 'written', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5949, 'N + いかんによらず / N + を問わず', 'bất kể ~, không phân biệt ~', '「〜を問わず」 phổ biến hơn (経験を問わず, 年齢・性別を問わず). 「〜いかんによらず」 trang trọng, hành chính.', 598, '2026-08-29 06:53:03.912', '2026-08-29 06:53:03.912', 'N1', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5951, 'V(ます bỏ) + っぷり / V(ます bỏ) + ぶり', 'cách ~, dáng vẻ ~', 'Chỉ phong thái, cách thức làm việc gì. 飲みっぷり, 話しぶり, 仕事ぶり. 「N ぶり」 còn nghĩa "sau bao lâu".', 598, '2026-08-29 06:53:03.927', '2026-08-29 06:53:03.927', 'N1', 'spoken', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6514, 'V て いただけませんか', 'anh/chị có thể làm V giúp tôi được không? (lịch sự)', NULL, 16164, '2026-09-26 06:22:23.068', '2026-09-26 06:22:23.068', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5955, 'V/A/N(thể thường) + ずにはいられない / ないではいられない', 'không thể không ~, cầm lòng không đặng', 'Cảm xúc/thôi thúc mạnh khiến không kìm được hành động. する→せずにはいられない.', 598, '2026-08-29 06:53:03.959', '2026-08-29 06:53:03.959', 'N1', 'written', 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6515, 'V て くださいませんか', 'xin anh/chị làm V giúp được không?', NULL, 16164, '2026-09-26 06:22:23.076', '2026-09-26 06:22:23.076', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6516, 'Thể bị động（V れる／V られる）', 'bị / được V', 'Nhóm 1: う→あれる (よむ→よまれる); nhóm 2: る→られる; する→される, くる→こられる.', 16165, '2026-09-26 06:22:23.156', '2026-09-26 06:22:23.156', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6517, 'N は（người）に よって V られます', 'N được tạo ra / làm bởi …', NULL, 16165, '2026-09-26 06:22:23.167', '2026-09-26 06:22:23.167', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6518, 'Thể sai khiến（V せる／V させる）', 'bắt / cho phép (ai) làm V', 'Nhóm 1: う→あせる (いく→いかせる); nhóm 2: る→させる; する→させる, くる→こさせる.', 16165, '2026-09-26 06:22:23.184', '2026-09-26 06:22:23.184', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6519, 'V させて いただけませんか', 'xin cho phép tôi được V', NULL, 16165, '2026-09-26 06:22:23.202', '2026-09-26 06:22:23.202', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6520, 'Kính ngữ お V に なります', '(người trên) làm V — tôn kính ngữ', NULL, 16165, '2026-09-26 06:22:23.21', '2026-09-26 06:22:23.21', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6521, 'Khiêm nhường ngữ お V します', 'tôi xin làm V (cho người trên)', NULL, 16165, '2026-09-26 06:22:23.219', '2026-09-26 06:22:23.219', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7338, '〜ところを', 'trong lúc … (mà lại làm phiền)', NULL, 16404, '2026-09-26 12:15:21.454', '2026-09-26 12:15:21.454', 'N1', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6978, '〜ことなく', 'không hề …', NULL, 16302, '2026-09-26 12:15:07.69', '2026-09-26 12:15:07.69', 'N2', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6284, 'N1 は N2 です', 'N1 là N2', 'Câu khẳng định lịch sự cơ bản. は (đọc "wa") đánh dấu chủ đề.', 16080, '2026-09-26 06:05:15.005', '2026-09-26 06:05:15.005', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6285, 'N1 は N2 じゃありません／ではありません', 'N1 không phải là N2', 'Phủ định của です. じゃ dùng trong hội thoại, では trang trọng hơn.', 16080, '2026-09-26 06:05:15.029', '2026-09-26 06:05:15.029', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6286, '〜ですか', 'câu hỏi có / không', 'Thêm か cuối câu để hỏi. Trả lời: はい、そうです／いいえ、ちがいます.', 16081, '2026-09-26 06:05:15.197', '2026-09-26 06:05:15.197', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6287, 'N も', 'N cũng', 'Thay cho は／が／を khi muốn nói "cũng vậy".', 16081, '2026-09-26 06:05:15.209', '2026-09-26 06:05:15.209', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6288, 'N1 の N2', 'N2 của N1 / N2 thuộc N1', 'Nối hai danh từ: sở hữu, xuất xứ, nội dung.', 16082, '2026-09-26 06:05:15.36', '2026-09-26 06:05:15.36', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6289, 'これ／それ／あれ・この／その／あの N', 'cái này / cái đó / cái kia', 'これ・それ・あれ đứng một mình; この・その・あの phải đi kèm danh từ.', 16082, '2026-09-26 06:05:15.368', '2026-09-26 06:05:15.368', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6290, 'N を V', 'làm V với / vào N (tân ngữ)', 'を (đọc "o") đánh dấu tân ngữ trực tiếp của động từ.', 16083, '2026-09-26 06:05:15.479', '2026-09-26 06:05:15.479', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6291, 'N（địa điểm）で V', 'làm V tại N', 'で chỉ nơi diễn ra hành động.', 16084, '2026-09-26 06:05:15.643', '2026-09-26 06:05:15.643', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6292, 'N（phương tiện）で', 'bằng N (phương tiện, công cụ)', 'で chỉ phương tiện, công cụ, ngôn ngữ.', 16084, '2026-09-26 06:05:15.654', '2026-09-26 06:05:15.654', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6293, 'N（người）と', 'cùng với N', 'と chỉ người cùng làm hành động.', 16085, '2026-09-26 06:05:15.852', '2026-09-26 06:05:15.852', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6294, 'N1 と N2 ／ N1 や N2（など）', 'N1 và N2 / N1, N2… (liệt kê)', 'と liệt kê đầy đủ; や liệt kê vài ví dụ, thường kèm など.', 16085, '2026-09-26 06:05:15.859', '2026-09-26 06:05:15.859', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6295, 'なに／だれ／どこ／いつ／いくら', 'cái gì / ai / ở đâu / khi nào / bao nhiêu tiền', 'Từ để hỏi đặt vào vị trí của thông tin cần hỏi.', 16086, '2026-09-26 06:05:16.022', '2026-09-26 06:05:16.022', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6296, 'N が あります', 'có N (đồ vật, cây cối)', 'Dùng cho vật không tự chuyển động.', 16086, '2026-09-26 06:05:16.038', '2026-09-26 06:05:16.038', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6297, 'N が います', 'có N (người, động vật)', 'Dùng cho người và động vật.', 16087, '2026-09-26 06:05:16.213', '2026-09-26 06:05:16.213', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6298, 'N1（địa điểm）に N2 が あります／います', 'ở N1 có N2', 'に chỉ nơi tồn tại.', 16088, '2026-09-26 06:05:16.374', '2026-09-26 06:05:16.374', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6299, 'N1 は N2（địa điểm）に あります／います', 'N1 ở N2', 'Nói vị trí của một vật / người đã biết.', 16088, '2026-09-26 06:05:16.384', '2026-09-26 06:05:16.384', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6300, 'N の うえ／した／なか／まえ／うしろ／となり', 'trên / dưới / trong / trước / sau / bên cạnh N', 'Danh từ chỉ vị trí đứng sau の.', 16089, '2026-09-26 06:05:16.596', '2026-09-26 06:05:16.596', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6301, 'ここ／そこ／あそこ／どこ', 'chỗ này / chỗ đó / chỗ kia / chỗ nào', 'Đại từ chỉ nơi chốn; dạng lịch sự: こちら／そちら／あちら／どちら.', 16089, '2026-09-26 06:05:16.604', '2026-09-26 06:05:16.604', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6302, 'V ます／V ません', 'làm / không làm (lịch sự, hiện tại – tương lai)', NULL, 16090, '2026-09-26 06:05:16.796', '2026-09-26 06:05:16.796', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6303, 'V ました／V ませんでした', 'đã làm / đã không làm', NULL, 16090, '2026-09-26 06:05:16.813', '2026-09-26 06:05:16.813', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6304, 'N（địa điểm）へ／に いきます・きます・かえります', 'đi / đến / về N', 'へ (đọc "e") hoặc に chỉ hướng di chuyển.', 16091, '2026-09-26 06:05:16.986', '2026-09-26 06:05:16.986', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6305, 'V て います', 'đang làm V', 'Hành động đang diễn ra.', 16092, '2026-09-26 06:05:17.176', '2026-09-26 06:05:17.176', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6306, 'V て います（trạng thái, thói quen）', 'đang ở trạng thái / thường xuyên làm', 'Kết quả còn lại (けっこんして います) hoặc nghề nghiệp, thói quen.', 16092, '2026-09-26 06:05:17.184', '2026-09-26 06:05:17.184', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6307, 'V た ことが あります', 'đã từng làm V', 'Nói về kinh nghiệm.', 16093, '2026-09-26 06:05:17.335', '2026-09-26 06:05:17.335', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6308, 'V（thể từ điển）ことが できます', 'có thể làm V', NULL, 16093, '2026-09-26 06:05:17.346', '2026-09-26 06:05:17.346', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6309, 'N が できます／わかります／すきです', 'biết / hiểu / thích N (đối tượng dùng が)', 'Một số động từ, tính từ chỉ khả năng, cảm xúc dùng が cho đối tượng.', 16094, '2026-09-26 06:05:17.565', '2026-09-26 06:05:17.565', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6310, 'N に なります／A くなります', 'trở thành N / trở nên A', 'Tính từ い: い→く＋なります; tính từ な & danh từ: に＋なります.', 16094, '2026-09-26 06:05:17.58', '2026-09-26 06:05:17.58', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6311, 'A い です／A な です', 'tính từ đuôi い / đuôi な làm vị ngữ', 'Phủ định: A い → A くないです; A な → A じゃありません.', 16095, '2026-09-26 06:05:17.768', '2026-09-26 06:05:17.768', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6312, 'A い かったです／A な でした', 'tính từ ở quá khứ', 'い→かったです; な／N → でした. Phủ định quá khứ: くなかったです／じゃありませんでした.', 16096, '2026-09-26 06:05:17.933', '2026-09-26 06:05:17.933', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6313, 'A い N ／ A な N', 'tính từ bổ nghĩa cho danh từ', NULL, 16096, '2026-09-26 06:05:17.94', '2026-09-26 06:05:17.94', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6314, 'とても／あまり 〜ない', 'rất / không … lắm', 'あまり luôn đi với thể phủ định.', 16097, '2026-09-26 06:05:18.045', '2026-09-26 06:05:18.045', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6315, 'N1 は N2 より A です', 'N1 A hơn N2', NULL, 16097, '2026-09-26 06:05:18.051', '2026-09-26 06:05:18.051', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6316, 'N1 と N2 と どちらが A ですか', 'N1 và N2, cái nào A hơn?', 'Trả lời: N1 の ほうが A です.', 16098, '2026-09-26 06:05:18.168', '2026-09-26 06:05:18.168', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6317, 'N（の なか）で いちばん A', 'A nhất trong N', NULL, 16098, '2026-09-26 06:05:18.176', '2026-09-26 06:05:18.176', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6318, 'A くて／A で／N で', 'A và … (nối tính từ, danh từ)', NULL, 16099, '2026-09-26 06:05:18.305', '2026-09-26 06:05:18.305', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6319, 'N が ほしいです', 'muốn có N', NULL, 16100, '2026-09-26 06:05:18.411', '2026-09-26 06:05:18.411', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6320, 'V たいです', 'muốn làm V', 'Bỏ ます thêm たい. Đối tượng có thể dùng が hoặc を.', 16100, '2026-09-26 06:05:18.417', '2026-09-26 06:05:18.417', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6321, 'V ませんか', 'cùng làm V không? (mời, rủ)', NULL, 16101, '2026-09-26 06:05:18.557', '2026-09-26 06:05:18.557', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6322, 'V ましょう／V ましょうか', 'cùng làm V nào / tôi làm V giúp nhé?', NULL, 16101, '2026-09-26 06:05:18.564', '2026-09-26 06:05:18.564', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6323, 'N（địa điểm）へ V ます に いきます', 'đi đến N để làm V', 'Mục đích của việc di chuyển: V bỏ ます ＋ に.', 16102, '2026-09-26 06:05:18.67', '2026-09-26 06:05:18.67', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6324, 'V て ください', 'hãy làm V', NULL, 16102, '2026-09-26 06:05:18.677', '2026-09-26 06:05:18.677', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6325, 'V ないで ください', 'xin đừng làm V', NULL, 16103, '2026-09-26 06:05:18.817', '2026-09-26 06:05:18.817', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6326, 'V ても いいですか', 'làm V có được không? (xin phép)', NULL, 16104, '2026-09-26 06:05:19.022', '2026-09-26 06:05:19.022', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6327, 'V ては いけません', 'không được làm V (cấm)', NULL, 16104, '2026-09-26 06:05:19.032', '2026-09-26 06:05:19.032', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6328, 'N を ください', 'cho tôi N', NULL, 16105, '2026-09-26 06:05:19.189', '2026-09-26 06:05:19.189', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6329, 'V なければ なりません', 'phải làm V', NULL, 16105, '2026-09-26 06:05:19.21', '2026-09-26 06:05:19.21', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6522, 'いらっしゃいます／めしあがります／ごらんに なります', 'kính ngữ đặc biệt: ở/đi/đến · ăn/uống · xem', NULL, 16165, '2026-09-26 06:22:23.227', '2026-09-26 06:22:23.227', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6330, 'V なくても いいです', 'không cần làm V cũng được', NULL, 16106, '2026-09-26 06:05:19.388', '2026-09-26 06:05:19.388', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6331, '〜じ〜ふん に V', 'làm V vào lúc … giờ … phút', 'に đi với thời điểm cụ thể (giờ, ngày, tháng); không dùng với きょう, あした, まいにち…', 16106, '2026-09-26 06:05:19.396', '2026-09-26 06:05:19.396', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6332, 'N1 から N2 まで', 'từ N1 đến N2', 'Dùng cho cả thời gian và địa điểm.', 16107, '2026-09-26 06:05:19.54', '2026-09-26 06:05:19.54', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6333, 'V て、V て、V ます', 'làm V1, rồi V2, rồi V3 (trình tự)', NULL, 16108, '2026-09-26 06:05:19.752', '2026-09-26 06:05:19.752', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6334, 'V て から', 'sau khi làm V thì …', NULL, 16108, '2026-09-26 06:05:19.768', '2026-09-26 06:05:19.768', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6335, 'V る まえに／N の まえに', 'trước khi làm V / trước N', NULL, 16109, '2026-09-26 06:05:19.939', '2026-09-26 06:05:19.939', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6336, 'V た あとで／N の あとで', 'sau khi làm V / sau N', NULL, 16109, '2026-09-26 06:05:19.95', '2026-09-26 06:05:19.95', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6337, 'もう V ました／まだ V て いません', 'đã … rồi / vẫn chưa …', NULL, 16110, '2026-09-26 06:05:20.139', '2026-09-26 06:05:20.139', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6338, 'V ながら', 'vừa V1 vừa V2', 'Hành động chính đứng sau.', 16110, '2026-09-26 06:05:20.152', '2026-09-26 06:05:20.152', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6339, 'V たり V たり します', 'lúc thì V1, lúc thì V2 (liệt kê hành động)', NULL, 16111, '2026-09-26 06:05:20.295', '2026-09-26 06:05:20.295', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6340, '〜から、〜', 'vì … nên …', 'から đứng sau vế lý do.', 16112, '2026-09-26 06:05:20.447', '2026-09-26 06:05:20.447', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6341, '〜が、〜', '… nhưng …', NULL, 16112, '2026-09-26 06:05:20.458', '2026-09-26 06:05:20.458', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6342, 'どうして〜か／〜からです', 'tại sao …? / là vì …', NULL, 16113, '2026-09-26 06:05:20.594', '2026-09-26 06:05:20.594', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6343, 'そして／それから', 'và / sau đó', NULL, 16113, '2026-09-26 06:05:20.604', '2026-09-26 06:05:20.604', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6344, 'でも／しかし', 'nhưng / tuy nhiên (đầu câu)', NULL, 16114, '2026-09-26 06:05:20.75', '2026-09-26 06:05:20.75', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6345, '〜と おもいます', 'tôi nghĩ là …', 'Đứng sau thể thường.', 16114, '2026-09-26 06:05:20.759', '2026-09-26 06:05:20.759', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6346, '〜と いいます', 'nói rằng … / tên là …', NULL, 16115, '2026-09-26 06:05:20.896', '2026-09-26 06:05:20.896', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6347, 'N1 は N2 です', 'N1 là N2', 'Câu khẳng định lịch sự cơ bản. は (đọc "wa") đánh dấu chủ đề.', 16116, '2026-09-26 06:05:21.064', '2026-09-26 06:05:21.064', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6348, 'N1 は N2 じゃありません／ではありません', 'N1 không phải là N2', 'Phủ định của です. じゃ dùng trong hội thoại, では trang trọng hơn.', 16116, '2026-09-26 06:05:21.076', '2026-09-26 06:05:21.076', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6349, '〜ですか', 'câu hỏi có / không', 'Thêm か cuối câu để hỏi. Trả lời: はい、そうです／いいえ、ちがいます.', 16116, '2026-09-26 06:05:21.087', '2026-09-26 06:05:21.087', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6350, 'N も', 'N cũng', 'Thay cho は／が／を khi muốn nói "cũng vậy".', 16116, '2026-09-26 06:05:21.098', '2026-09-26 06:05:21.098', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6351, 'N1 の N2', 'N2 của N1 / N2 thuộc N1', 'Nối hai danh từ: sở hữu, xuất xứ, nội dung.', 16116, '2026-09-26 06:05:21.107', '2026-09-26 06:05:21.107', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6352, 'これ／それ／あれ・この／その／あの N', 'cái này / cái đó / cái kia', 'これ・それ・あれ đứng một mình; この・その・あの phải đi kèm danh từ.', 16116, '2026-09-26 06:05:21.117', '2026-09-26 06:05:21.117', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6353, 'N を V', 'làm V với / vào N (tân ngữ)', 'を (đọc "o") đánh dấu tân ngữ trực tiếp của động từ.', 16116, '2026-09-26 06:05:21.126', '2026-09-26 06:05:21.126', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6354, 'N（địa điểm）で V', 'làm V tại N', 'で chỉ nơi diễn ra hành động.', 16116, '2026-09-26 06:05:21.137', '2026-09-26 06:05:21.137', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6355, 'N（phương tiện）で', 'bằng N (phương tiện, công cụ)', 'で chỉ phương tiện, công cụ, ngôn ngữ.', 16117, '2026-09-26 06:05:21.718', '2026-09-26 06:05:21.718', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6356, 'N（người）と', 'cùng với N', 'と chỉ người cùng làm hành động.', 16117, '2026-09-26 06:05:21.727', '2026-09-26 06:05:21.727', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7339, '〜をおいて（ほかに〜ない）', 'ngoài … ra thì không có', NULL, 16404, '2026-09-26 12:15:21.462', '2026-09-26 12:15:21.462', 'N1', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6357, 'N1 と N2 ／ N1 や N2（など）', 'N1 và N2 / N1, N2… (liệt kê)', 'と liệt kê đầy đủ; や liệt kê vài ví dụ, thường kèm など.', 16117, '2026-09-26 06:05:21.736', '2026-09-26 06:05:21.736', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6358, 'なに／だれ／どこ／いつ／いくら', 'cái gì / ai / ở đâu / khi nào / bao nhiêu tiền', 'Từ để hỏi đặt vào vị trí của thông tin cần hỏi.', 16117, '2026-09-26 06:05:21.751', '2026-09-26 06:05:21.751', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6359, 'N が あります', 'có N (đồ vật, cây cối)', 'Dùng cho vật không tự chuyển động.', 16117, '2026-09-26 06:05:21.764', '2026-09-26 06:05:21.764', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6360, 'N が います', 'có N (người, động vật)', 'Dùng cho người và động vật.', 16117, '2026-09-26 06:05:21.78', '2026-09-26 06:05:21.78', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6361, 'N1（địa điểm）に N2 が あります／います', 'ở N1 có N2', 'に chỉ nơi tồn tại.', 16117, '2026-09-26 06:05:21.795', '2026-09-26 06:05:21.795', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6362, 'N1 は N2（địa điểm）に あります／います', 'N1 ở N2', 'Nói vị trí của một vật / người đã biết.', 16117, '2026-09-26 06:05:21.812', '2026-09-26 06:05:21.812', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6363, 'N の うえ／した／なか／まえ／うしろ／となり', 'trên / dưới / trong / trước / sau / bên cạnh N', 'Danh từ chỉ vị trí đứng sau の.', 16118, '2026-09-26 06:05:22.435', '2026-09-26 06:05:22.435', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6364, 'ここ／そこ／あそこ／どこ', 'chỗ này / chỗ đó / chỗ kia / chỗ nào', 'Đại từ chỉ nơi chốn; dạng lịch sự: こちら／そちら／あちら／どちら.', 16118, '2026-09-26 06:05:22.448', '2026-09-26 06:05:22.448', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6365, 'V ます／V ません', 'làm / không làm (lịch sự, hiện tại – tương lai)', NULL, 16118, '2026-09-26 06:05:22.461', '2026-09-26 06:05:22.461', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6366, 'V ました／V ませんでした', 'đã làm / đã không làm', NULL, 16118, '2026-09-26 06:05:22.472', '2026-09-26 06:05:22.472', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6367, 'N（địa điểm）へ／に いきます・きます・かえります', 'đi / đến / về N', 'へ (đọc "e") hoặc に chỉ hướng di chuyển.', 16118, '2026-09-26 06:05:22.483', '2026-09-26 06:05:22.483', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6368, 'V て います', 'đang làm V', 'Hành động đang diễn ra.', 16118, '2026-09-26 06:05:22.496', '2026-09-26 06:05:22.496', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6369, 'V て います（trạng thái, thói quen）', 'đang ở trạng thái / thường xuyên làm', 'Kết quả còn lại (けっこんして います) hoặc nghề nghiệp, thói quen.', 16118, '2026-09-26 06:05:22.514', '2026-09-26 06:05:22.514', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6370, 'V た ことが あります', 'đã từng làm V', 'Nói về kinh nghiệm.', 16118, '2026-09-26 06:05:22.529', '2026-09-26 06:05:22.529', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6371, 'V（thể từ điển）ことが できます', 'có thể làm V', NULL, 16119, '2026-09-26 06:05:23.353', '2026-09-26 06:05:23.353', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6372, 'N が できます／わかります／すきです', 'biết / hiểu / thích N (đối tượng dùng が)', 'Một số động từ, tính từ chỉ khả năng, cảm xúc dùng が cho đối tượng.', 16119, '2026-09-26 06:05:23.363', '2026-09-26 06:05:23.363', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6373, 'N に なります／A くなります', 'trở thành N / trở nên A', 'Tính từ い: い→く＋なります; tính từ な & danh từ: に＋なります.', 16119, '2026-09-26 06:05:23.373', '2026-09-26 06:05:23.373', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6979, '〜ほどだ（N2・mức độ cực đoan）', 'đến mức …', NULL, 16302, '2026-09-26 12:15:07.698', '2026-09-26 12:15:07.698', 'N2', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6374, 'A い です／A な です', 'tính từ đuôi い / đuôi な làm vị ngữ', 'Phủ định: A い → A くないです; A な → A じゃありません.', 16119, '2026-09-26 06:05:23.381', '2026-09-26 06:05:23.381', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6375, 'A い かったです／A な でした', 'tính từ ở quá khứ', 'い→かったです; な／N → でした. Phủ định quá khứ: くなかったです／じゃありませんでした.', 16119, '2026-09-26 06:05:23.393', '2026-09-26 06:05:23.393', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6376, 'A い N ／ A な N', 'tính từ bổ nghĩa cho danh từ', NULL, 16119, '2026-09-26 06:05:23.409', '2026-09-26 06:05:23.409', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6377, 'とても／あまり 〜ない', 'rất / không … lắm', 'あまり luôn đi với thể phủ định.', 16119, '2026-09-26 06:05:23.421', '2026-09-26 06:05:23.421', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6378, 'N1 は N2 より A です', 'N1 A hơn N2', NULL, 16119, '2026-09-26 06:05:23.432', '2026-09-26 06:05:23.432', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6379, 'N1 と N2 と どちらが A ですか', 'N1 và N2, cái nào A hơn?', 'Trả lời: N1 の ほうが A です.', 16120, '2026-09-26 06:05:24.097', '2026-09-26 06:05:24.097', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6380, 'N（の なか）で いちばん A', 'A nhất trong N', NULL, 16120, '2026-09-26 06:05:24.112', '2026-09-26 06:05:24.112', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6381, 'A くて／A で／N で', 'A và … (nối tính từ, danh từ)', NULL, 16120, '2026-09-26 06:05:24.128', '2026-09-26 06:05:24.128', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6382, 'N が ほしいです', 'muốn có N', NULL, 16120, '2026-09-26 06:05:24.139', '2026-09-26 06:05:24.139', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6383, 'V たいです', 'muốn làm V', 'Bỏ ます thêm たい. Đối tượng có thể dùng が hoặc を.', 16120, '2026-09-26 06:05:24.148', '2026-09-26 06:05:24.148', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6384, 'V ませんか', 'cùng làm V không? (mời, rủ)', NULL, 16120, '2026-09-26 06:05:24.159', '2026-09-26 06:05:24.159', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6385, 'V ましょう／V ましょうか', 'cùng làm V nào / tôi làm V giúp nhé?', NULL, 16120, '2026-09-26 06:05:24.171', '2026-09-26 06:05:24.171', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6386, 'N（địa điểm）へ V ます に いきます', 'đi đến N để làm V', 'Mục đích của việc di chuyển: V bỏ ます ＋ に.', 16120, '2026-09-26 06:05:24.182', '2026-09-26 06:05:24.182', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6387, 'V て ください', 'hãy làm V', NULL, 16121, '2026-09-26 06:05:24.772', '2026-09-26 06:05:24.772', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6388, 'V ないで ください', 'xin đừng làm V', NULL, 16121, '2026-09-26 06:05:24.807', '2026-09-26 06:05:24.807', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6389, 'V ても いいですか', 'làm V có được không? (xin phép)', NULL, 16121, '2026-09-26 06:05:24.817', '2026-09-26 06:05:24.817', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6390, 'V ては いけません', 'không được làm V (cấm)', NULL, 16121, '2026-09-26 06:05:24.824', '2026-09-26 06:05:24.824', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6391, 'N を ください', 'cho tôi N', NULL, 16121, '2026-09-26 06:05:24.841', '2026-09-26 06:05:24.841', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6392, 'V なければ なりません', 'phải làm V', NULL, 16121, '2026-09-26 06:05:24.852', '2026-09-26 06:05:24.852', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6393, 'V なくても いいです', 'không cần làm V cũng được', NULL, 16121, '2026-09-26 06:05:24.859', '2026-09-26 06:05:24.859', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6394, '〜じ〜ふん に V', 'làm V vào lúc … giờ … phút', 'に đi với thời điểm cụ thể (giờ, ngày, tháng); không dùng với きょう, あした, まいにち…', 16121, '2026-09-26 06:05:24.866', '2026-09-26 06:05:24.866', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6395, 'N1 から N2 まで', 'từ N1 đến N2', 'Dùng cho cả thời gian và địa điểm.', 16122, '2026-09-26 06:05:25.559', '2026-09-26 06:05:25.559', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6396, 'V て、V て、V ます', 'làm V1, rồi V2, rồi V3 (trình tự)', NULL, 16122, '2026-09-26 06:05:25.566', '2026-09-26 06:05:25.566', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6397, 'V て から', 'sau khi làm V thì …', NULL, 16122, '2026-09-26 06:05:25.578', '2026-09-26 06:05:25.578', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6398, 'V る まえに／N の まえに', 'trước khi làm V / trước N', NULL, 16122, '2026-09-26 06:05:25.587', '2026-09-26 06:05:25.587', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6399, 'V た あとで／N の あとで', 'sau khi làm V / sau N', NULL, 16122, '2026-09-26 06:05:25.595', '2026-09-26 06:05:25.595', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6400, 'もう V ました／まだ V て いません', 'đã … rồi / vẫn chưa …', NULL, 16122, '2026-09-26 06:05:25.602', '2026-09-26 06:05:25.602', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6401, 'V ながら', 'vừa V1 vừa V2', 'Hành động chính đứng sau.', 16122, '2026-09-26 06:05:25.609', '2026-09-26 06:05:25.609', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6402, 'V たり V たり します', 'lúc thì V1, lúc thì V2 (liệt kê hành động)', NULL, 16122, '2026-09-26 06:05:25.616', '2026-09-26 06:05:25.616', 'N5', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6403, '〜から、〜', 'vì … nên …', 'から đứng sau vế lý do.', 16123, '2026-09-26 06:05:26.229', '2026-09-26 06:05:26.229', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6404, '〜が、〜', '… nhưng …', NULL, 16123, '2026-09-26 06:05:26.235', '2026-09-26 06:05:26.235', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6405, 'どうして〜か／〜からです', 'tại sao …? / là vì …', NULL, 16123, '2026-09-26 06:05:26.241', '2026-09-26 06:05:26.241', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6406, 'そして／それから', 'và / sau đó', NULL, 16123, '2026-09-26 06:05:26.247', '2026-09-26 06:05:26.247', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6407, 'でも／しかし', 'nhưng / tuy nhiên (đầu câu)', NULL, 16123, '2026-09-26 06:05:26.253', '2026-09-26 06:05:26.253', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6408, '〜と おもいます', 'tôi nghĩ là …', 'Đứng sau thể thường.', 16123, '2026-09-26 06:05:26.26', '2026-09-26 06:05:26.26', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6409, '〜と いいます', 'nói rằng … / tên là …', NULL, 16123, '2026-09-26 06:05:26.267', '2026-09-26 06:05:26.267', 'N5', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6410, 'Thể thông thường（普通形）', 'cách nói thân mật / dùng trong mệnh đề', 'V る／V ない／V た／V なかった; A い; A な・N だ. Dùng với bạn bè và trước các mẫu như と思う, でしょう.', 16124, '2026-09-26 06:22:16.993', '2026-09-26 06:22:16.993', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6411, 'V た ほうが いい', 'nên làm V', 'Phủ định: V ない ほうが いい (không nên).', 16124, '2026-09-26 06:22:17.04', '2026-09-26 06:22:17.04', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6412, 'V（thể thông thường）N', 'mệnh đề bổ nghĩa cho danh từ', 'Chủ ngữ trong mệnh đề dùng が (hoặc の).', 16125, '2026-09-26 06:22:17.192', '2026-09-26 06:22:17.192', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6413, 'V る の が A です', 'việc V thì A (danh từ hóa bằng の)', NULL, 16125, '2026-09-26 06:22:17.197', '2026-09-26 06:22:17.197', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6414, 'V る の を わすれました', 'quên làm V', NULL, 16126, '2026-09-26 06:22:17.33', '2026-09-26 06:22:17.33', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6415, 'V た／V ない まま', 'để nguyên trạng thái …', NULL, 16126, '2026-09-26 06:22:17.341', '2026-09-26 06:22:17.341', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6416, 'V て しまいました', 'lỡ làm V / đã làm xong V', 'Diễn tả hối tiếc, hoặc hoàn tất. Hội thoại: 〜ちゃった.', 16127, '2026-09-26 06:22:17.497', '2026-09-26 06:22:17.497', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6417, 'V て おきます', 'làm V sẵn / trước', NULL, 16127, '2026-09-26 06:22:17.509', '2026-09-26 06:22:17.509', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6418, 'V て あります', 'đã được V sẵn (trạng thái do ai đó làm)', NULL, 16128, '2026-09-26 06:22:17.683', '2026-09-26 06:22:17.683', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6419, 'Thể khả năng（V れる／V られる）', 'có thể làm V', 'Nhóm 1: う→える (よむ→よめる); nhóm 2: る→られる; する→できる, くる→こられる.', 16128, '2026-09-26 06:22:17.694', '2026-09-26 06:22:17.694', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6420, 'みえます／きこえます', 'nhìn thấy được / nghe thấy được (tự nhiên)', NULL, 16129, '2026-09-26 06:22:17.864', '2026-09-26 06:22:17.864', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6421, 'V る ように なります', 'trở nên có thể V / bắt đầu (thói quen)', NULL, 16129, '2026-09-26 06:22:17.875', '2026-09-26 06:22:17.875', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6422, 'V る ように します', 'cố gắng (tạo thói quen) làm V', NULL, 16130, '2026-09-26 06:22:18.022', '2026-09-26 06:22:18.022', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6423, 'A く／A に／N に します', 'làm cho … / quyết định chọn N', NULL, 16130, '2026-09-26 06:22:18.032', '2026-09-26 06:22:18.032', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6424, 'V る ことに なりました', 'đã được quyết định là V (không phải do mình)', NULL, 16131, '2026-09-26 06:22:18.191', '2026-09-26 06:22:18.191', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6425, 'V る ことに しました', 'tôi đã quyết định V', NULL, 16131, '2026-09-26 06:22:18.203', '2026-09-26 06:22:18.203', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6426, 'V る ことに して います', 'tôi có quy tắc / thói quen V', NULL, 16132, '2026-09-26 06:22:18.343', '2026-09-26 06:22:18.343', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6980, '〜際（に）', 'khi, nhân dịp … (trang trọng)', NULL, 16303, '2026-09-26 12:15:07.799', '2026-09-26 12:15:07.799', 'N2', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6427, 'Thể ý chí（V よう）', 'nào cùng V (thân mật)', 'Nhóm 1: う→おう (いく→いこう); nhóm 2: る→よう; する→しよう, くる→こよう.', 16132, '2026-09-26 06:22:18.35', '2026-09-26 06:22:18.35', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6428, 'V よう と おもって います', 'tôi đang định V', NULL, 16133, '2026-09-26 06:22:18.472', '2026-09-26 06:22:18.472', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6429, 'V る つもりです', 'dự định V', 'Phủ định: V ない つもりです.', 16133, '2026-09-26 06:22:18.484', '2026-09-26 06:22:18.484', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6430, 'V る／N の よていです', 'theo kế hoạch sẽ V', NULL, 16134, '2026-09-26 06:22:18.672', '2026-09-26 06:22:18.672', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6431, 'V た ばかりです', 'vừa mới V xong', NULL, 16134, '2026-09-26 06:22:18.693', '2026-09-26 06:22:18.693', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6432, 'V る ところです／V て いる ところです／V た ところです', 'sắp V / đang V / vừa V xong', NULL, 16135, '2026-09-26 06:22:18.841', '2026-09-26 06:22:18.841', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6433, 'V たら どうですか', 'làm V thử xem sao? (khuyên)', NULL, 16136, '2026-09-26 06:22:18.953', '2026-09-26 06:22:18.953', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6434, '〜たら', 'nếu … thì / sau khi … thì', NULL, 16136, '2026-09-26 06:22:18.959', '2026-09-26 06:22:18.959', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6435, '〜ば／〜なければ', 'nếu … thì (điều kiện giả định)', 'V: う→えば (いく→いけば); A い→ければ; A な・N→なら.', 16137, '2026-09-26 06:22:19.045', '2026-09-26 06:22:19.045', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6436, '〜と、〜', 'hễ … thì (kết quả tất yếu)', NULL, 16137, '2026-09-26 06:22:19.051', '2026-09-26 06:22:19.051', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6437, 'N なら', 'nếu là N thì …', NULL, 16138, '2026-09-26 06:22:19.142', '2026-09-26 06:22:19.142', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6438, '〜ても', 'dù … cũng', NULL, 16138, '2026-09-26 06:22:19.15', '2026-09-26 06:22:19.15', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6439, 'V ば V る ほど', 'càng V càng …', NULL, 16139, '2026-09-26 06:22:19.303', '2026-09-26 06:22:19.303', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6440, '〜か どうか', 'có … hay không', NULL, 16139, '2026-09-26 06:22:19.309', '2026-09-26 06:22:19.309', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6441, 'あげます／くれます／もらいます', 'cho (người khác) / (ai đó) cho tôi / nhận', NULL, 16140, '2026-09-26 06:22:19.468', '2026-09-26 06:22:19.468', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6442, 'V て あげます', 'làm V cho (người khác)', NULL, 16140, '2026-09-26 06:22:19.481', '2026-09-26 06:22:19.481', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6443, 'V て くれます', '(ai đó) làm V cho tôi', NULL, 16141, '2026-09-26 06:22:19.663', '2026-09-26 06:22:19.663', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6444, 'V て もらいます', 'được (ai đó) làm V cho', NULL, 16141, '2026-09-26 06:22:19.674', '2026-09-26 06:22:19.674', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6445, 'V て いただけませんか', 'anh/chị có thể làm V giúp tôi được không? (lịch sự)', NULL, 16142, '2026-09-26 06:22:19.864', '2026-09-26 06:22:19.864', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6446, 'V て くださいませんか', 'xin anh/chị làm V giúp được không?', NULL, 16142, '2026-09-26 06:22:19.876', '2026-09-26 06:22:19.876', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6447, 'Thể bị động（V れる／V られる）', 'bị / được V', 'Nhóm 1: う→あれる (よむ→よまれる); nhóm 2: る→られる; する→される, くる→こられる.', 16143, '2026-09-26 06:22:20.032', '2026-09-26 06:22:20.032', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6448, 'N は（người）に よって V られます', 'N được tạo ra / làm bởi …', NULL, 16143, '2026-09-26 06:22:20.038', '2026-09-26 06:22:20.038', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6449, 'Thể sai khiến（V せる／V させる）', 'bắt / cho phép (ai) làm V', 'Nhóm 1: う→あせる (いく→いかせる); nhóm 2: る→させる; する→させる, くる→こさせる.', 16144, '2026-09-26 06:22:20.168', '2026-09-26 06:22:20.168', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6450, 'V させて いただけませんか', 'xin cho phép tôi được V', NULL, 16144, '2026-09-26 06:22:20.181', '2026-09-26 06:22:20.181', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6451, 'Kính ngữ お V に なります', '(người trên) làm V — tôn kính ngữ', NULL, 16145, '2026-09-26 06:22:20.332', '2026-09-26 06:22:20.332', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6452, 'Khiêm nhường ngữ お V します', 'tôi xin làm V (cho người trên)', NULL, 16145, '2026-09-26 06:22:20.338', '2026-09-26 06:22:20.338', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6453, 'いらっしゃいます／めしあがります／ごらんに なります', 'kính ngữ đặc biệt: ở/đi/đến · ăn/uống · xem', NULL, 16146, '2026-09-26 06:22:20.481', '2026-09-26 06:22:20.481', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6454, 'まいります／いただきます／はいけんします', 'khiêm nhường ngữ đặc biệt: đi/đến · ăn/nhận · xem', NULL, 16146, '2026-09-26 06:22:20.488', '2026-09-26 06:22:20.488', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6455, '〜でしょう／〜だろう', 'có lẽ … (dự đoán)', NULL, 16147, '2026-09-26 06:22:20.604', '2026-09-26 06:22:20.604', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6456, '〜かもしれません', 'có thể là … (khả năng thấp hơn でしょう)', NULL, 16148, '2026-09-26 06:22:20.696', '2026-09-26 06:22:20.696', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6457, '〜はずです', 'chắc chắn là … (theo lý mà nói)', NULL, 16148, '2026-09-26 06:22:20.702', '2026-09-26 06:22:20.702', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6458, 'V ます／A そうです（dáng vẻ）', 'trông có vẻ … / sắp …', 'Dựa trên quan sát trực tiếp. いい→よさそう, ない→なさそう.', 16149, '2026-09-26 06:22:20.795', '2026-09-26 06:22:20.795', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6459, 'Thể thông thường ＋ そうです（truyền đạt）', 'nghe nói là …', NULL, 16149, '2026-09-26 06:22:20.801', '2026-09-26 06:22:20.801', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6460, '〜ようです／〜みたいです', 'hình như … (phán đoán)', NULL, 16150, '2026-09-26 06:22:20.937', '2026-09-26 06:22:20.937', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6461, '〜らしいです', 'nghe đâu … / có vẻ (thông tin gián tiếp)', NULL, 16150, '2026-09-26 06:22:20.951', '2026-09-26 06:22:20.951', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6462, 'N1 と いう N2', 'N2 có tên là N1', NULL, 16151, '2026-09-26 06:22:21.095', '2026-09-26 06:22:21.095', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6463, '〜と いって いました／〜と つたえて ください', '(ai đó) đã nói là … / nhắn giúp là …', NULL, 16151, '2026-09-26 06:22:21.102', '2026-09-26 06:22:21.102', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6464, 'V る ために／N の ために', 'để V / vì N (mục đích có chủ ý)', NULL, 16152, '2026-09-26 06:22:21.202', '2026-09-26 06:22:21.202', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6465, 'V る／V ない ように', 'để (có thể) V / để không V', 'Đi với động từ không chủ ý, thể khả năng hoặc phủ định.', 16152, '2026-09-26 06:22:21.207', '2026-09-26 06:22:21.207', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6466, 'V ます すぎます／A すぎます', 'quá …', NULL, 16153, '2026-09-26 06:22:21.313', '2026-09-26 06:22:21.313', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6467, 'V ます やすいです／にくいです', 'dễ V / khó V', NULL, 16153, '2026-09-26 06:22:21.319', '2026-09-26 06:22:21.319', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6468, 'N1 は N2 が A です', 'N1 thì N2 (bộ phận) A', NULL, 16154, '2026-09-26 06:22:21.452', '2026-09-26 06:22:21.452', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6469, 'N ばかり／V て ばかり います', 'toàn là N / chỉ toàn V', NULL, 16154, '2026-09-26 06:22:21.466', '2026-09-26 06:22:21.466', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6470, 'N しか 〜ない', 'chỉ có N (nhấn mạnh ít)', NULL, 16155, '2026-09-26 06:22:21.667', '2026-09-26 06:22:21.667', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6471, 'Số lượng ＋ も', 'những … (nhấn mạnh nhiều)', NULL, 16155, '2026-09-26 06:22:21.681', '2026-09-26 06:22:21.681', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6472, 'V ても いい です／V なくても かまいません', 'V cũng được / không V cũng không sao', NULL, 16156, '2026-09-26 06:22:21.862', '2026-09-26 06:22:21.862', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6473, '〜し、〜し', 'vừa … lại vừa … (liệt kê lý do)', NULL, 16156, '2026-09-26 06:22:21.873', '2026-09-26 06:22:21.873', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6474, '〜ので', 'vì … nên (khách quan, lịch sự)', NULL, 16157, '2026-09-26 06:22:22.038', '2026-09-26 06:22:22.038', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6475, '〜のに', 'vậy mà … / mặc dù … (bất mãn)', NULL, 16157, '2026-09-26 06:22:22.049', '2026-09-26 06:22:22.049', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6476, 'V た とき／V る とき', 'khi … (quan hệ thời gian trước/sau)', 'V る とき: lúc hành động chưa xong; V た とき: sau khi đã xong.', 16158, '2026-09-26 06:22:22.233', '2026-09-26 06:22:22.233', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6477, 'V ながら（hai hành động song song）', 'vừa … vừa … (hai việc cùng lúc lâu dài)', NULL, 16158, '2026-09-26 06:22:22.246', '2026-09-26 06:22:22.246', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6478, 'V ば いいです', 'chỉ cần V là được', NULL, 16159, '2026-09-26 06:22:22.421', '2026-09-26 06:22:22.421', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6981, '〜に際して', 'nhân dịp, khi bắt đầu …', NULL, 16303, '2026-09-26 12:15:07.804', '2026-09-26 12:15:07.804', 'N2', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6982, '〜次第（ngay khi）', 'ngay sau khi … thì', NULL, 16303, '2026-09-26 12:15:07.809', '2026-09-26 12:15:07.809', 'N2', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6479, 'Thể thông thường（普通形）', 'cách nói thân mật / dùng trong mệnh đề', 'V る／V ない／V た／V なかった; A い; A な・N だ. Dùng với bạn bè và trước các mẫu như と思う, でしょう.', 16160, '2026-09-26 06:22:22.505', '2026-09-26 06:22:22.505', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6480, 'V た ほうが いい', 'nên làm V', 'Phủ định: V ない ほうが いい (không nên).', 16160, '2026-09-26 06:22:22.51', '2026-09-26 06:22:22.51', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6481, 'V（thể thông thường）N', 'mệnh đề bổ nghĩa cho danh từ', 'Chủ ngữ trong mệnh đề dùng が (hoặc の).', 16160, '2026-09-26 06:22:22.516', '2026-09-26 06:22:22.516', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6482, 'V る の が A です', 'việc V thì A (danh từ hóa bằng の)', NULL, 16160, '2026-09-26 06:22:22.522', '2026-09-26 06:22:22.522', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6483, 'V る の を わすれました', 'quên làm V', NULL, 16160, '2026-09-26 06:22:22.528', '2026-09-26 06:22:22.528', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6484, 'V た／V ない まま', 'để nguyên trạng thái …', NULL, 16160, '2026-09-26 06:22:22.534', '2026-09-26 06:22:22.534', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6485, 'V て しまいました', 'lỡ làm V / đã làm xong V', 'Diễn tả hối tiếc, hoặc hoàn tất. Hội thoại: 〜ちゃった.', 16160, '2026-09-26 06:22:22.54', '2026-09-26 06:22:22.54', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6486, 'V て おきます', 'làm V sẵn / trước', NULL, 16160, '2026-09-26 06:22:22.546', '2026-09-26 06:22:22.546', 'N4', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6487, 'V て あります', 'đã được V sẵn (trạng thái do ai đó làm)', NULL, 16160, '2026-09-26 06:22:22.552', '2026-09-26 06:22:22.552', 'N4', NULL, 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6488, 'Thể khả năng（V れる／V られる）', 'có thể làm V', 'Nhóm 1: う→える (よむ→よめる); nhóm 2: る→られる; する→できる, くる→こられる.', 16161, '2026-09-26 06:22:22.618', '2026-09-26 06:22:22.618', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6489, 'みえます／きこえます', 'nhìn thấy được / nghe thấy được (tự nhiên)', NULL, 16161, '2026-09-26 06:22:22.626', '2026-09-26 06:22:22.626', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6490, 'V る ように なります', 'trở nên có thể V / bắt đầu (thói quen)', NULL, 16161, '2026-09-26 06:22:22.636', '2026-09-26 06:22:22.636', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6491, 'V る ように します', 'cố gắng (tạo thói quen) làm V', NULL, 16161, '2026-09-26 06:22:22.645', '2026-09-26 06:22:22.645', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6492, 'A く／A に／N に します', 'làm cho … / quyết định chọn N', NULL, 16161, '2026-09-26 06:22:22.654', '2026-09-26 06:22:22.654', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6493, 'V る ことに なりました', 'đã được quyết định là V (không phải do mình)', NULL, 16161, '2026-09-26 06:22:22.663', '2026-09-26 06:22:22.663', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6494, 'V る ことに しました', 'tôi đã quyết định V', NULL, 16161, '2026-09-26 06:22:22.672', '2026-09-26 06:22:22.672', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6495, 'V る ことに して います', 'tôi có quy tắc / thói quen V', NULL, 16161, '2026-09-26 06:22:22.68', '2026-09-26 06:22:22.68', 'N4', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6496, 'Thể ý chí（V よう）', 'nào cùng V (thân mật)', 'Nhóm 1: う→おう (いく→いこう); nhóm 2: る→よう; する→しよう, くる→こよう.', 16162, '2026-09-26 06:22:22.757', '2026-09-26 06:22:22.757', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6497, 'V よう と おもって います', 'tôi đang định V', NULL, 16162, '2026-09-26 06:22:22.763', '2026-09-26 06:22:22.763', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6498, 'V る つもりです', 'dự định V', 'Phủ định: V ない つもりです.', 16162, '2026-09-26 06:22:22.772', '2026-09-26 06:22:22.772', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6499, 'V る／N の よていです', 'theo kế hoạch sẽ V', NULL, 16162, '2026-09-26 06:22:22.778', '2026-09-26 06:22:22.778', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6500, 'V た ばかりです', 'vừa mới V xong', NULL, 16162, '2026-09-26 06:22:22.784', '2026-09-26 06:22:22.784', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6501, 'V る ところです／V て いる ところです／V た ところです', 'sắp V / đang V / vừa V xong', NULL, 16162, '2026-09-26 06:22:22.79', '2026-09-26 06:22:22.79', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6502, 'V たら どうですか', 'làm V thử xem sao? (khuyên)', NULL, 16162, '2026-09-26 06:22:22.799', '2026-09-26 06:22:22.799', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6503, '〜たら', 'nếu … thì / sau khi … thì', NULL, 16163, '2026-09-26 06:22:22.878', '2026-09-26 06:22:22.878', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6504, '〜ば／〜なければ', 'nếu … thì (điều kiện giả định)', 'V: う→えば (いく→いけば); A い→ければ; A な・N→なら.', 16163, '2026-09-26 06:22:22.884', '2026-09-26 06:22:22.884', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6505, '〜と、〜', 'hễ … thì (kết quả tất yếu)', NULL, 16163, '2026-09-26 06:22:22.892', '2026-09-26 06:22:22.892', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6506, 'N なら', 'nếu là N thì …', NULL, 16163, '2026-09-26 06:22:22.904', '2026-09-26 06:22:22.904', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6507, '〜ても', 'dù … cũng', NULL, 16163, '2026-09-26 06:22:22.915', '2026-09-26 06:22:22.915', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6508, 'V ば V る ほど', 'càng V càng …', NULL, 16163, '2026-09-26 06:22:22.927', '2026-09-26 06:22:22.927', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6509, '〜か どうか', 'có … hay không', NULL, 16163, '2026-09-26 06:22:22.938', '2026-09-26 06:22:22.938', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6510, 'あげます／くれます／もらいます', 'cho (người khác) / (ai đó) cho tôi / nhận', NULL, 16164, '2026-09-26 06:22:23.03', '2026-09-26 06:22:23.03', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6511, 'V て あげます', 'làm V cho (người khác)', NULL, 16164, '2026-09-26 06:22:23.038', '2026-09-26 06:22:23.038', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6523, 'まいります／いただきます／はいけんします', 'khiêm nhường ngữ đặc biệt: đi/đến · ăn/nhận · xem', NULL, 16165, '2026-09-26 06:22:23.24', '2026-09-26 06:22:23.24', 'N4', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6524, '〜でしょう／〜だろう', 'có lẽ … (dự đoán)', NULL, 16166, '2026-09-26 06:22:23.317', '2026-09-26 06:22:23.317', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6525, '〜かもしれません', 'có thể là … (khả năng thấp hơn でしょう)', NULL, 16166, '2026-09-26 06:22:23.329', '2026-09-26 06:22:23.329', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6526, '〜はずです', 'chắc chắn là … (theo lý mà nói)', NULL, 16166, '2026-09-26 06:22:23.337', '2026-09-26 06:22:23.337', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6527, 'V ます／A そうです（dáng vẻ）', 'trông có vẻ … / sắp …', 'Dựa trên quan sát trực tiếp. いい→よさそう, ない→なさそう.', 16166, '2026-09-26 06:22:23.344', '2026-09-26 06:22:23.344', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6528, 'Thể thông thường ＋ そうです（truyền đạt）', 'nghe nói là …', NULL, 16166, '2026-09-26 06:22:23.354', '2026-09-26 06:22:23.354', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6529, '〜ようです／〜みたいです', 'hình như … (phán đoán)', NULL, 16166, '2026-09-26 06:22:23.363', '2026-09-26 06:22:23.363', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6530, '〜らしいです', 'nghe đâu … / có vẻ (thông tin gián tiếp)', NULL, 16166, '2026-09-26 06:22:23.374', '2026-09-26 06:22:23.374', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6531, 'N1 と いう N2', 'N2 có tên là N1', NULL, 16166, '2026-09-26 06:22:23.386', '2026-09-26 06:22:23.386', 'N4', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6532, '〜と いって いました／〜と つたえて ください', '(ai đó) đã nói là … / nhắn giúp là …', NULL, 16166, '2026-09-26 06:22:23.403', '2026-09-26 06:22:23.403', 'N4', NULL, 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6533, 'V る ために／N の ために', 'để V / vì N (mục đích có chủ ý)', NULL, 16167, '2026-09-26 06:22:23.534', '2026-09-26 06:22:23.534', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6534, 'V る／V ない ように', 'để (có thể) V / để không V', 'Đi với động từ không chủ ý, thể khả năng hoặc phủ định.', 16167, '2026-09-26 06:22:23.546', '2026-09-26 06:22:23.546', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6535, 'V ます すぎます／A すぎます', 'quá …', NULL, 16167, '2026-09-26 06:22:23.557', '2026-09-26 06:22:23.557', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6536, 'V ます やすいです／にくいです', 'dễ V / khó V', NULL, 16167, '2026-09-26 06:22:23.568', '2026-09-26 06:22:23.568', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6537, 'N1 は N2 が A です', 'N1 thì N2 (bộ phận) A', NULL, 16167, '2026-09-26 06:22:23.58', '2026-09-26 06:22:23.58', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6538, 'N ばかり／V て ばかり います', 'toàn là N / chỉ toàn V', NULL, 16167, '2026-09-26 06:22:23.591', '2026-09-26 06:22:23.591', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6539, 'N しか 〜ない', 'chỉ có N (nhấn mạnh ít)', NULL, 16167, '2026-09-26 06:22:23.603', '2026-09-26 06:22:23.603', 'N4', NULL, 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6540, 'Số lượng ＋ も', 'những … (nhấn mạnh nhiều)', NULL, 16167, '2026-09-26 06:22:23.613', '2026-09-26 06:22:23.613', 'N4', NULL, 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6541, 'V ても いい です／V なくても かまいません', 'V cũng được / không V cũng không sao', NULL, 16167, '2026-09-26 06:22:23.623', '2026-09-26 06:22:23.623', 'N4', NULL, 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6542, '〜し、〜し', 'vừa … lại vừa … (liệt kê lý do)', NULL, 16167, '2026-09-26 06:22:23.633', '2026-09-26 06:22:23.633', 'N4', NULL, 9);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6543, '〜ので', 'vì … nên (khách quan, lịch sự)', NULL, 16168, '2026-09-26 06:22:23.764', '2026-09-26 06:22:23.764', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6544, '〜のに', 'vậy mà … / mặc dù … (bất mãn)', NULL, 16168, '2026-09-26 06:22:23.778', '2026-09-26 06:22:23.778', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6545, 'V た とき／V る とき', 'khi … (quan hệ thời gian trước/sau)', 'V る とき: lúc hành động chưa xong; V た とき: sau khi đã xong.', 16168, '2026-09-26 06:22:23.791', '2026-09-26 06:22:23.791', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6546, 'V ながら（hai hành động song song）', 'vừa … vừa … (hai việc cùng lúc lâu dài)', NULL, 16168, '2026-09-26 06:22:23.802', '2026-09-26 06:22:23.802', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6547, 'V ば いいです', 'chỉ cần V là được', NULL, 16168, '2026-09-26 06:22:23.815', '2026-09-26 06:22:23.815', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6548, 'Thể thông thường（普通形）', 'cách nói thân mật / dùng trong mệnh đề', 'V る／V ない／V た／V なかった; A い; A な・N だ. Dùng với bạn bè và trước các mẫu như と思う, でしょう.', 16181, '2026-09-26 06:22:27.239', '2026-09-26 06:22:27.239', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6549, 'V た ほうが いい', 'nên làm V', 'Phủ định: V ない ほうが いい (không nên).', 16181, '2026-09-26 06:22:27.246', '2026-09-26 06:22:27.246', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6550, 'V（thể thông thường）N', 'mệnh đề bổ nghĩa cho danh từ', 'Chủ ngữ trong mệnh đề dùng が (hoặc の).', 16181, '2026-09-26 06:22:27.253', '2026-09-26 06:22:27.253', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6551, 'V る の が A です', 'việc V thì A (danh từ hóa bằng の)', NULL, 16181, '2026-09-26 06:22:27.259', '2026-09-26 06:22:27.259', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6552, 'V る の を わすれました', 'quên làm V', NULL, 16181, '2026-09-26 06:22:27.265', '2026-09-26 06:22:27.265', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6553, 'V た／V ない まま', 'để nguyên trạng thái …', NULL, 16181, '2026-09-26 06:22:27.271', '2026-09-26 06:22:27.271', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6554, 'V て しまいました', 'lỡ làm V / đã làm xong V', 'Diễn tả hối tiếc, hoặc hoàn tất. Hội thoại: 〜ちゃった.', 16182, '2026-09-26 06:22:27.639', '2026-09-26 06:22:27.639', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6555, 'V て おきます', 'làm V sẵn / trước', NULL, 16182, '2026-09-26 06:22:27.65', '2026-09-26 06:22:27.65', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6556, 'V て あります', 'đã được V sẵn (trạng thái do ai đó làm)', NULL, 16182, '2026-09-26 06:22:27.661', '2026-09-26 06:22:27.661', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6557, 'Thể khả năng（V れる／V られる）', 'có thể làm V', 'Nhóm 1: う→える (よむ→よめる); nhóm 2: る→られる; する→できる, くる→こられる.', 16182, '2026-09-26 06:22:27.671', '2026-09-26 06:22:27.671', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6558, 'みえます／きこえます', 'nhìn thấy được / nghe thấy được (tự nhiên)', NULL, 16182, '2026-09-26 06:22:27.682', '2026-09-26 06:22:27.682', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6559, 'V る ように なります', 'trở nên có thể V / bắt đầu (thói quen)', NULL, 16182, '2026-09-26 06:22:27.691', '2026-09-26 06:22:27.691', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6560, 'V る ように します', 'cố gắng (tạo thói quen) làm V', NULL, 16183, '2026-09-26 06:22:27.93', '2026-09-26 06:22:27.93', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6561, 'A く／A に／N に します', 'làm cho … / quyết định chọn N', NULL, 16183, '2026-09-26 06:22:27.936', '2026-09-26 06:22:27.936', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6562, 'V る ことに なりました', 'đã được quyết định là V (không phải do mình)', NULL, 16183, '2026-09-26 06:22:27.942', '2026-09-26 06:22:27.942', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6563, 'V る ことに しました', 'tôi đã quyết định V', NULL, 16183, '2026-09-26 06:22:27.948', '2026-09-26 06:22:27.948', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6564, 'V る ことに して います', 'tôi có quy tắc / thói quen V', NULL, 16183, '2026-09-26 06:22:27.954', '2026-09-26 06:22:27.954', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6565, 'Thể ý chí（V よう）', 'nào cùng V (thân mật)', 'Nhóm 1: う→おう (いく→いこう); nhóm 2: る→よう; する→しよう, くる→こよう.', 16183, '2026-09-26 06:22:27.962', '2026-09-26 06:22:27.962', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6566, 'V よう と おもって います', 'tôi đang định V', NULL, 16184, '2026-09-26 06:22:28.204', '2026-09-26 06:22:28.204', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6567, 'V る つもりです', 'dự định V', 'Phủ định: V ない つもりです.', 16184, '2026-09-26 06:22:28.212', '2026-09-26 06:22:28.212', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6568, 'V る／N の よていです', 'theo kế hoạch sẽ V', NULL, 16184, '2026-09-26 06:22:28.219', '2026-09-26 06:22:28.219', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6569, 'V た ばかりです', 'vừa mới V xong', NULL, 16184, '2026-09-26 06:22:28.226', '2026-09-26 06:22:28.226', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6570, 'V る ところです／V て いる ところです／V た ところです', 'sắp V / đang V / vừa V xong', NULL, 16184, '2026-09-26 06:22:28.234', '2026-09-26 06:22:28.234', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6571, 'V たら どうですか', 'làm V thử xem sao? (khuyên)', NULL, 16185, '2026-09-26 06:22:28.51', '2026-09-26 06:22:28.51', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6572, '〜たら', 'nếu … thì / sau khi … thì', NULL, 16185, '2026-09-26 06:22:28.518', '2026-09-26 06:22:28.518', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6573, '〜ば／〜なければ', 'nếu … thì (điều kiện giả định)', 'V: う→えば (いく→いけば); A い→ければ; A な・N→なら.', 16185, '2026-09-26 06:22:28.528', '2026-09-26 06:22:28.528', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6574, '〜と、〜', 'hễ … thì (kết quả tất yếu)', NULL, 16185, '2026-09-26 06:22:28.536', '2026-09-26 06:22:28.536', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6575, 'N なら', 'nếu là N thì …', NULL, 16185, '2026-09-26 06:22:28.544', '2026-09-26 06:22:28.544', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6576, '〜ても', 'dù … cũng', NULL, 16185, '2026-09-26 06:22:28.551', '2026-09-26 06:22:28.551', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6577, 'V ば V る ほど', 'càng V càng …', NULL, 16186, '2026-09-26 06:22:28.909', '2026-09-26 06:22:28.909', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6578, '〜か どうか', 'có … hay không', NULL, 16186, '2026-09-26 06:22:28.916', '2026-09-26 06:22:28.916', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6579, 'あげます／くれます／もらいます', 'cho (người khác) / (ai đó) cho tôi / nhận', NULL, 16186, '2026-09-26 06:22:28.923', '2026-09-26 06:22:28.923', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6580, 'V て あげます', 'làm V cho (người khác)', NULL, 16186, '2026-09-26 06:22:28.93', '2026-09-26 06:22:28.93', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6581, 'V て くれます', '(ai đó) làm V cho tôi', NULL, 16186, '2026-09-26 06:22:28.936', '2026-09-26 06:22:28.936', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6582, 'V て もらいます', 'được (ai đó) làm V cho', NULL, 16186, '2026-09-26 06:22:28.942', '2026-09-26 06:22:28.942', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6583, 'V て いただけませんか', 'anh/chị có thể làm V giúp tôi được không? (lịch sự)', NULL, 16187, '2026-09-26 06:22:29.212', '2026-09-26 06:22:29.212', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6584, 'V て くださいませんか', 'xin anh/chị làm V giúp được không?', NULL, 16187, '2026-09-26 06:22:29.222', '2026-09-26 06:22:29.222', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6585, 'Thể bị động（V れる／V られる）', 'bị / được V', 'Nhóm 1: う→あれる (よむ→よまれる); nhóm 2: る→られる; する→される, くる→こられる.', 16187, '2026-09-26 06:22:29.23', '2026-09-26 06:22:29.23', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6586, 'N は（người）に よって V られます', 'N được tạo ra / làm bởi …', NULL, 16187, '2026-09-26 06:22:29.238', '2026-09-26 06:22:29.238', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6587, 'Thể sai khiến（V せる／V させる）', 'bắt / cho phép (ai) làm V', 'Nhóm 1: う→あせる (いく→いかせる); nhóm 2: る→させる; する→させる, くる→こさせる.', 16187, '2026-09-26 06:22:29.245', '2026-09-26 06:22:29.245', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6588, 'V させて いただけませんか', 'xin cho phép tôi được V', NULL, 16187, '2026-09-26 06:22:29.253', '2026-09-26 06:22:29.253', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6589, 'Kính ngữ お V に なります', '(người trên) làm V — tôn kính ngữ', NULL, 16188, '2026-09-26 06:22:29.58', '2026-09-26 06:22:29.58', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6590, 'Khiêm nhường ngữ お V します', 'tôi xin làm V (cho người trên)', NULL, 16188, '2026-09-26 06:22:29.591', '2026-09-26 06:22:29.591', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6591, 'いらっしゃいます／めしあがります／ごらんに なります', 'kính ngữ đặc biệt: ở/đi/đến · ăn/uống · xem', NULL, 16188, '2026-09-26 06:22:29.603', '2026-09-26 06:22:29.603', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6592, 'まいります／いただきます／はいけんします', 'khiêm nhường ngữ đặc biệt: đi/đến · ăn/nhận · xem', NULL, 16188, '2026-09-26 06:22:29.614', '2026-09-26 06:22:29.614', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6593, '〜でしょう／〜だろう', 'có lẽ … (dự đoán)', NULL, 16188, '2026-09-26 06:22:29.624', '2026-09-26 06:22:29.624', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6594, '〜かもしれません', 'có thể là … (khả năng thấp hơn でしょう)', NULL, 16189, '2026-09-26 06:22:30.024', '2026-09-26 06:22:30.024', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6595, '〜はずです', 'chắc chắn là … (theo lý mà nói)', NULL, 16189, '2026-09-26 06:22:30.035', '2026-09-26 06:22:30.035', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6596, 'V ます／A そうです（dáng vẻ）', 'trông có vẻ … / sắp …', 'Dựa trên quan sát trực tiếp. いい→よさそう, ない→なさそう.', 16189, '2026-09-26 06:22:30.046', '2026-09-26 06:22:30.046', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6597, 'Thể thông thường ＋ そうです（truyền đạt）', 'nghe nói là …', NULL, 16189, '2026-09-26 06:22:30.058', '2026-09-26 06:22:30.058', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6598, '〜ようです／〜みたいです', 'hình như … (phán đoán)', NULL, 16189, '2026-09-26 06:22:30.068', '2026-09-26 06:22:30.068', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6599, '〜らしいです', 'nghe đâu … / có vẻ (thông tin gián tiếp)', NULL, 16189, '2026-09-26 06:22:30.079', '2026-09-26 06:22:30.079', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6600, 'N1 と いう N2', 'N2 có tên là N1', NULL, 16190, '2026-09-26 06:22:30.397', '2026-09-26 06:22:30.397', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6601, '〜と いって いました／〜と つたえて ください', '(ai đó) đã nói là … / nhắn giúp là …', NULL, 16190, '2026-09-26 06:22:30.406', '2026-09-26 06:22:30.406', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6602, 'V る ために／N の ために', 'để V / vì N (mục đích có chủ ý)', NULL, 16190, '2026-09-26 06:22:30.415', '2026-09-26 06:22:30.415', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6603, 'V る／V ない ように', 'để (có thể) V / để không V', 'Đi với động từ không chủ ý, thể khả năng hoặc phủ định.', 16190, '2026-09-26 06:22:30.424', '2026-09-26 06:22:30.424', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6604, 'V ます すぎます／A すぎます', 'quá …', NULL, 16190, '2026-09-26 06:22:30.434', '2026-09-26 06:22:30.434', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6605, 'V ます やすいです／にくいです', 'dễ V / khó V', NULL, 16190, '2026-09-26 06:22:30.444', '2026-09-26 06:22:30.444', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6606, 'N1 は N2 が A です', 'N1 thì N2 (bộ phận) A', NULL, 16191, '2026-09-26 06:22:30.837', '2026-09-26 06:22:30.837', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6607, 'N ばかり／V て ばかり います', 'toàn là N / chỉ toàn V', NULL, 16191, '2026-09-26 06:22:30.85', '2026-09-26 06:22:30.85', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6608, 'N しか 〜ない', 'chỉ có N (nhấn mạnh ít)', NULL, 16191, '2026-09-26 06:22:30.862', '2026-09-26 06:22:30.862', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6609, 'Số lượng ＋ も', 'những … (nhấn mạnh nhiều)', NULL, 16191, '2026-09-26 06:22:30.875', '2026-09-26 06:22:30.875', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6610, 'V ても いい です／V なくても かまいません', 'V cũng được / không V cũng không sao', NULL, 16191, '2026-09-26 06:22:30.886', '2026-09-26 06:22:30.886', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6611, '〜し、〜し', 'vừa … lại vừa … (liệt kê lý do)', NULL, 16191, '2026-09-26 06:22:30.898', '2026-09-26 06:22:30.898', 'N4', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6612, '〜ので', 'vì … nên (khách quan, lịch sự)', NULL, 16192, '2026-09-26 06:22:31.227', '2026-09-26 06:22:31.227', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6613, '〜のに', 'vậy mà … / mặc dù … (bất mãn)', NULL, 16192, '2026-09-26 06:22:31.238', '2026-09-26 06:22:31.238', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6614, 'V た とき／V る とき', 'khi … (quan hệ thời gian trước/sau)', 'V る とき: lúc hành động chưa xong; V た とき: sau khi đã xong.', 16192, '2026-09-26 06:22:31.249', '2026-09-26 06:22:31.249', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6615, 'V ながら（hai hành động song song）', 'vừa … vừa … (hai việc cùng lúc lâu dài)', NULL, 16192, '2026-09-26 06:22:31.259', '2026-09-26 06:22:31.259', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6616, 'V ば いいです', 'chỉ cần V là được', NULL, 16192, '2026-09-26 06:22:31.271', '2026-09-26 06:22:31.271', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6617, '〜せいで／〜せいだ', 'tại vì … (nguyên nhân xấu)', NULL, 16193, '2026-09-26 12:14:57.064', '2026-09-26 12:14:57.064', 'N3', NULL, 0);
