INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7624, 'N1 は N2 です', 'N1 là N2', 'は (đọc là wa) đánh dấu chủ đề của câu; です đặt cuối câu khẳng định, thể hiện sự lịch sự.', 1, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7625, 'N1 は N2 じゃ（では） ありません', 'N1 không phải là N2', 'Phủ định của です. じゃ ありません dùng trong hội thoại, では ありません trang trọng hơn.', 1, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7626, 'S ＋ か', 'câu hỏi (có / không)', 'Thêm か vào cuối câu và lên giọng để tạo câu hỏi. Trả lời: はい、そうです／いいえ、ちがいます.', 1, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7627, 'N も', 'N cũng', 'も thay cho は khi thông tin giống với điều vừa được nói đến.', 1, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7628, 'N1 の N2', 'N2 thuộc N1', 'の nối hai danh từ. Ở bài này N1 là tổ chức, nhóm mà N2 trực thuộc.', 1, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7629, '～さん', 'anh / chị / ông / bà ~', 'Gắn sau tên người khác để thể hiện sự tôn trọng. Không dùng cho tên của chính mình. Với trẻ nhỏ dùng ～ちゃん.', 1, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7630, 'これ／それ／あれ', 'cái này / cái đó / cái kia', 'Đại từ chỉ định, đứng một mình như danh từ. これ: gần người nói; それ: gần người nghe; あれ: xa cả hai.', 2, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7631, 'この／その／あの ＋ N', 'N này / N đó / N kia', 'Luôn đi kèm danh từ phía sau, không đứng một mình.', 2, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7632, 'そうです／ちがいます', 'đúng vậy / không phải', 'Trả lời câu hỏi có / không với câu danh từ.', 2, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7633, 'S1 か、S2 か', 'S1 hay là S2?', 'Câu hỏi lựa chọn; trả lời bằng chính lựa chọn, không dùng はい／いいえ.', 2, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7634, 'N1 の N2（nội dung / sở hữu）', 'N2 về N1 / N2 của N1', 'の chỉ nội dung hoặc sở hữu. Có thể lược N2 khi đã rõ: これは わたしのです.', 2, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7635, 'そうですか', 'Thế à / Ra vậy', 'Đáp lại khi nhận được thông tin mới, đọc xuống giọng.', 2, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7636, 'ここ／そこ／あそこ は N（địa điểm）です', 'chỗ này / đó / kia là N', 'Đại từ chỉ nơi chốn, cùng quy tắc khoảng cách với これ／それ／あれ.', 3, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7637, 'N は どこですか', 'N ở đâu?', 'Hỏi vị trí. Cách hỏi lịch sự hơn: どちらですか.', 3, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7638, 'こちら／そちら／あちら／どちら', 'phía này / đó / kia / nào (lịch sự)', 'Cách nói lịch sự của ここ／そこ／あそこ／どこ; cũng dùng để hỏi đất nước, công ty, trường của người nghe.', 3, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7639, 'どこの N', 'N của nước nào / hãng nào', 'Hỏi xuất xứ, nơi sản xuất của đồ vật.', 3, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7640, 'N は いくらですか', 'N giá bao nhiêu?', 'Hỏi giá tiền.', 3, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7641, '今 ～時～分です', 'bây giờ là ~ giờ ~ phút', '時 (じ) chỉ giờ, 分 (ふん／ぷん) chỉ phút. Hỏi: 今 何時ですか.', 4, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7642, 'V ます／V ません／V ました／V ませんでした', 'chia thì của động từ thể lịch sự', 'ます: hiện tại, tương lai, thói quen; ません: phủ định; ました: quá khứ; ませんでした: phủ định quá khứ.', 4, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7643, 'N（thời gian）に V', 'làm V vào lúc N', 'に đi với thời điểm có con số (giờ, ngày, tháng, năm) và thứ trong tuần; không dùng với きょう, あした, 毎日…', 4, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7644, 'N1 から N2 まで', 'từ N1 đến N2', 'Dùng cho cả thời gian và địa điểm; có thể dùng riêng から hoặc まで.', 4, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7645, 'N1 と N2', 'N1 và N2', 'と nối hai danh từ (liệt kê đầy đủ).', 4, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7646, '～ね', '~ nhỉ (mong người nghe đồng cảm)', 'Đặt cuối câu khi người nói muốn người nghe đồng tình hoặc xác nhận.', 4, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7647, 'N（địa điểm）へ 行きます／来ます／帰ります', 'đi / đến / về N', 'へ (đọc là e) chỉ hướng di chuyển.', 5, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7648, 'どこ［へ］も 行きません', 'không đi đâu cả', 'Từ để hỏi + も + động từ phủ định = phủ định hoàn toàn.', 5, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7649, 'N（phương tiện）で 行きます', 'đi bằng N', 'で chỉ phương tiện di chuyển. Đi bộ: 歩いて 行きます (không dùng で).', 5, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7650, 'N（người / động vật）と V', 'làm V cùng với N', 'と chỉ đối tượng cùng thực hiện hành động. Một mình: ひとりで.', 5, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7651, 'いつ', 'khi nào', 'Từ để hỏi thời gian; không đi kèm に.', 5, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7652, '～よ', '~ đấy (cho biết điều người nghe chưa biết)', 'Đặt cuối câu để truyền đạt thông tin mới hoặc nhấn mạnh ý kiến của người nói.', 5, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7653, 'N を V（tha động từ）', 'làm V (tác động lên N)', 'を (đọc là o) đánh dấu tân ngữ trực tiếp.', 6, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7654, 'N を します', 'làm / chơi N', 'します đi với nhiều danh từ chỉ hoạt động: サッカー, 宿題, パーティー…', 6, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7655, '何を しますか', 'làm gì?', 'Hỏi về hoạt động. 何も ＋ phủ định = không ~ gì cả.', 6, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7656, 'N（địa điểm）で V', 'làm V ở N', 'で chỉ nơi diễn ra hành động.', 6, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7657, 'V ませんか', 'cùng V không? (mời, rủ)', 'Lời mời lịch sự, tôn trọng ý muốn của người nghe.', 6, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7658, 'V ましょう', 'cùng V nào', 'Đề nghị tích cực, hoặc hưởng ứng lời mời.', 6, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7659, 'N（công cụ / phương tiện）で V', 'làm V bằng N', 'で chỉ công cụ, phương tiện, ngôn ngữ.', 7, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7660, '「từ / câu」は ～語で 何ですか', '~ trong tiếng ~ là gì?', 'Hỏi cách nói một từ hoặc câu bằng ngôn ngữ khác.', 7, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7661, 'N1（người）に N2 を あげます', 'tặng / cho N1 cái N2', 'Cùng mẫu với 貸します, 教えます, 送ります, 電話を かけます.', 7, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7662, 'N1（người）に N2 を もらいます', 'nhận N2 từ N1', 'Có thể thay に bằng から. Cùng mẫu với 借ります, 習います.', 7, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7663, 'もう V ました', 'đã V rồi', 'Hỏi việc đã hoàn thành chưa. Trả lời phủ định: いいえ、まだです.', 7, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7664, 'N は なA［な］です／いA です', 'N thì (tính từ)', 'Tính từ な bỏ な rồi thêm です; tính từ い giữ nguyên + です. Phủ định: なA じゃ ありません; いA bỏ い + くないです (いい → よくないです).', 8, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7665, 'なA な N／いA N', 'tính từ bổ nghĩa cho danh từ', 'Tính từ な giữ な khi đứng trước danh từ; tính từ い đứng trực tiếp trước danh từ.', 8, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7666, 'とても／あまり', 'rất / không ~ lắm', 'とても đi với khẳng định; あまり luôn đi với phủ định.', 8, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7667, 'N は どうですか／N1 は どんな N2 ですか', 'N thế nào? / N1 là N2 như thế nào?', 'どう hỏi cảm nhận; どんな đứng trước danh từ để hỏi tính chất.', 8, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7668, 'S1 が、S2', 'S1 nhưng S2', 'が nối hai mệnh đề có ý nghĩa tương phản.', 8, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7669, 'どれ', 'cái nào (trong ba thứ trở lên)', 'Yêu cầu người nghe chọn một trong nhiều thứ.', 8, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7670, 'N が あります／わかります', 'có / hiểu N', 'Đối tượng của あります (sở hữu) và わかります dùng が.', 9, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7671, 'N が 好きです／嫌いです／上手です／下手です', 'thích / ghét / giỏi / kém N', 'Đối tượng của tính từ chỉ sở thích, năng lực dùng が.', 9, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7672, 'どんな N', 'N gì / loại N nào', 'Hỏi để người nghe nêu cụ thể một thứ trong nhóm.', 9, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7673, 'よく／だいたい／たくさん／少し／あまり／全然', 'phó từ chỉ mức độ, số lượng', 'Đặt trước động từ. あまり và 全然 luôn đi với phủ định.', 9, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7674, '～から、～', 'vì ~ nên ~', 'から đứng sau vế chỉ lý do.', 9, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7675, 'どうして ～か', 'tại sao ~?', 'Hỏi lý do; câu trả lời kết thúc bằng ～から.', 9, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7676, 'N が あります／います', 'có N', 'あります dùng cho đồ vật, cây cối; います dùng cho người, động vật.', 10, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7677, 'N1（địa điểm）に N2 が あります／います', 'ở N1 có N2', 'に chỉ nơi tồn tại.', 10, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7678, 'N1 は N2（địa điểm）に あります／います', 'N1 ở N2', 'Nói vị trí của người, vật đã được nhắc đến. Có thể nói gọn: N1 は N2 です.', 10, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7679, 'N1 の 上／下／前／後ろ／中／となり…', 'vị trí so với N1', 'Danh từ chỉ vị trí đứng sau の.', 10, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7680, 'N1 や N2（など）', 'N1, N2… (liệt kê tiêu biểu)', 'と liệt kê đầy đủ; や chỉ nêu vài ví dụ tiêu biểu, thường kèm など.', 10, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7681, 'Số đếm: ～つ／～人／～台／～枚／～回', 'trợ từ đếm', 'Đặt sau số: つ (đồ vật chung, đến 10), 人 (người: ひとり, ふたり), 台 (máy móc, xe), 枚 (vật mỏng), 回 (số lần).', 11, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7682, 'Khoảng thời gian ＋ に ～回', '~ lần trong (khoảng thời gian)', 'Diễn tả tần suất.', 11, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7683, 'どのくらい ～か／～ぐらい', 'mất bao lâu? / khoảng ~', 'どのくらい hỏi khoảng thời gian, số lượng; ぐらい／くらい đứng sau số lượng nghĩa là "khoảng".', 11, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7684, 'だけ', 'chỉ', 'Đứng sau danh từ, số lượng để giới hạn.', 11, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7685, 'N／なA でした／じゃ ありませんでした', 'quá khứ của câu danh từ, tính từ な', 'Khẳng định: でした; phủ định: じゃ（では） ありませんでした.', 12, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7686, 'いA → ～かったです／～くなかったです', 'quá khứ của tính từ い', 'Bỏ い thêm かったです; phủ định: くなかったです. いい → よかったです.', 12, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7687, 'N1 は N2 より A です', 'N1 A hơn N2', 'より đánh dấu đối tượng được so sánh.', 12, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7688, 'N1 と N2 と どちらが A ですか／N1 の ほうが A です', 'N1 và N2, cái nào A hơn?', 'Hỏi so sánh giữa hai thứ; trả lời bằng ～の ほうが.', 12, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7689, 'N1［の 中］で 何／どこ／だれ／いつ が いちばん A ですか', 'trong N1, cái gì / ở đâu / ai / khi nào A nhất?', 'So sánh nhất trong một phạm vi.', 12, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7690, 'N が ほしいです', 'muốn có N', 'Chỉ dùng cho mong muốn của người nói, hoặc để hỏi người nghe.', 13, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7691, 'V（ます bỏ）たいです', 'muốn làm V', 'Đối tượng có thể dùng を hoặc が. Phủ định: たくないです.', 13, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7692, 'N（địa điểm）へ V（ます bỏ）／N に 行きます', 'đi đến N để làm V', 'Chỉ mục đích của việc đi / đến / về.', 13, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7693, 'どこか／何か', 'đâu đó / cái gì đó', 'Có thể lược へ, を phía sau.', 13, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7694, 'Thể て của động từ', 'cách chia thể て', 'Nhóm I: い・ち・り → って; み・び・に → んで; き → いて (ngoại lệ 行きます → 行って); ぎ → いで; し → して. Nhóm II: bỏ ます + て. Nhóm III: して, 来て.', 14, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7695, 'V て ください', 'hãy V / xin vui lòng V', 'Yêu cầu, nhờ vả, chỉ dẫn một cách lịch sự.', 14, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7696, 'V て います（đang diễn ra）', 'đang V', 'Hành động đang diễn ra tại thời điểm nói.', 14, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7697, 'V（ます bỏ）ましょうか', 'để tôi V giúp nhé?', 'Người nói đề nghị làm giúp người nghe.', 14, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7698, 'V て も いいですか', 'V có được không? (xin phép)', 'Trả lời: ええ、いいですよ／すみません、ちょっと…', 15, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7699, 'V て は いけません', 'không được V', 'Biểu thị sự cấm đoán.', 15, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7700, 'V て います（trạng thái kết quả）', 'đã V và trạng thái vẫn còn', 'Dùng với 結婚します, 持ちます, 住みます, 知ります… Phủ định của 知って います là 知りません.', 15, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7701, 'V て います（nghề nghiệp, công việc thường xuyên）', 'làm V (thường xuyên, lâu dài)', 'Diễn tả nghề nghiệp, hoạt động diễn ra lặp lại trong thời gian dài.', 15, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7702, 'V て、V て、～', 'V1 rồi V2 rồi ~ (trình tự)', 'Nối các hành động theo thứ tự; thì của cả câu do động từ cuối quyết định.', 16, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7703, 'いA（～くて）／なA・N（～で）、～', 'nối tính từ, danh từ', 'Tính từ い: bỏ い + くて; tính từ な và danh từ: + で.', 16, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7704, 'V1 て から、V2', 'sau khi V1 thì V2', 'Nhấn mạnh V2 diễn ra sau khi V1 kết thúc.', 16, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7705, 'N1 は N2 が A です', 'N1 thì N2 (bộ phận, đặc điểm) A', 'Miêu tả một đặc điểm của chủ đề N1.', 16, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7706, 'どうやって', 'bằng cách nào / làm thế nào', 'Hỏi cách thức, đường đi.', 16, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7707, 'どの N', 'N nào', 'Đứng trước danh từ để hỏi chọn một trong nhiều thứ.', 16, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7708, 'Thể ない của động từ', 'cách chia thể ない', 'Nhóm I: đổi âm cuối hàng い sang hàng あ + ない (書きます → 書かない; 買います → 買わない). Nhóm II: bỏ ます + ない. Nhóm III: しない, 来ない.', 17, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7709, 'V ないで ください', 'xin đừng V', 'Yêu cầu hoặc khuyên người khác không làm gì.', 17, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7710, 'V なければ なりません', 'phải V', 'Diễn tả nghĩa vụ, việc bắt buộc phải làm.', 17, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7711, 'V なくても いいです', 'không V cũng được', 'Diễn tả việc không cần thiết phải làm.', 17, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7712, 'N（tân ngữ）は', 'đưa tân ngữ lên làm chủ đề', 'Thay を bằng は và đưa tân ngữ lên đầu câu để nhấn mạnh nó như chủ đề.', 17, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7713, 'N（thời gian）までに V', 'V trước N (hạn chót)', 'までに chỉ thời hạn cuối cùng; khác まで (liên tục cho đến).', 17, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7714, 'Thể từ điển của động từ', 'dạng nguyên thể', 'Nhóm I: đổi âm cuối hàng い sang hàng う (書きます → 書く). Nhóm II: bỏ ます + る. Nhóm III: する, 来る.', 18, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7715, 'N／V る こと が できます', 'có thể V / biết N', 'Diễn tả năng lực hoặc khả năng do hoàn cảnh cho phép.', 18, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7716, 'わたしの 趣味は N／V る こと です', 'sở thích của tôi là ~', 'Dùng danh từ hoặc V る こと để nói cụ thể về sở thích.', 18, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7717, 'V1 る／N の／khoảng thời gian ＋ まえに、V2', 'trước khi V1 thì V2', 'V1 luôn ở thể từ điển dù V2 ở quá khứ.', 18, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7718, 'なかなか ＋ phủ định', 'mãi mà không ~ / không dễ ~', 'Diễn tả việc khó thực hiện, không như mong đợi.', 18, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7719, 'ぜひ', 'nhất định, rất (mong muốn)', 'Đi với ～たいです, ～て ください để nhấn mạnh mong muốn, lời mời.', 18, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7720, 'Thể た của động từ', 'cách chia thể た', 'Chia giống thể て, chỉ đổi て → た, で → だ.', 19, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7721, 'V た ことが あります', 'đã từng V', 'Nói về kinh nghiệm trong quá khứ.', 19, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7722, 'V たり、V たり します', 'nào là V1, nào là V2', 'Liệt kê vài hành động tiêu biểu trong nhiều hành động.', 19, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7723, 'いA（～く）／なA・N（～に） なります', 'trở nên ~', 'Diễn tả sự thay đổi trạng thái.', 19, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7724, 'Thể thông thường（普通体）', 'cách nói thân mật', 'V thể từ điển / ない / た / なかった; いA; なA・N ＋ だ. Dùng với bạn thân, gia đình.', 20, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7725, 'Câu hỏi ở thể thông thường', 'bỏ か, lên giọng cuối câu', 'Câu hỏi danh từ, tính từ な thường bỏ だ. Trả lời: うん (có), ううん (không).', 20, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7726, '～けど', '~ nhưng (thân mật)', 'Dạng thân mật của が (nhưng) trong hội thoại.', 20, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7727, 'Thể thông thường ＋ と 思います', 'tôi nghĩ là ~', 'Diễn tả phỏng đoán hoặc ý kiến của người nói.', 21, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7728, 'N に ついて どう 思いますか', 'bạn nghĩ thế nào về N?', 'Hỏi ý kiến của người nghe.', 21, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7729, '「câu」／thể thông thường ＋ と 言います', 'nói rằng ~', 'Trích dẫn trực tiếp bằng 「」 hoặc gián tiếp bằng thể thông thường.', 21, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7730, 'Thể thông thường ＋ でしょう？', '~ phải không? (xác nhận)', 'Lên giọng ở cuối để mong người nghe đồng tình. なA, N bỏ だ.', 21, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7731, 'N1（địa điểm）で N2（sự kiện）が あります', 'ở N1 diễn ra N2', 'あります ở đây nghĩa là tổ chức, diễn ra (tiệc, trận đấu, lễ hội…).', 21, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7732, 'Mệnh đề bổ nghĩa cho danh từ', 'V／A（thể thông thường）＋ N', 'Mệnh đề đặt trước danh từ để bổ nghĩa, động từ ở thể thông thường.', 22, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7733, 'N が V ＋ N（chủ ngữ trong mệnh đề）', 'chủ ngữ của mệnh đề bổ nghĩa dùng が', 'Trong mệnh đề bổ nghĩa cho danh từ, chủ ngữ được đánh dấu bằng が (không dùng は).', 22, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7734, 'V る 時間／約束／用事', 'thời gian để V / hẹn V / việc phải V', 'Động từ thể từ điển bổ nghĩa cho 時間, 約束, 用事.', 22, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7735, '～とき、～', 'khi ~', 'V る／V ない／いA／なA な／N の ＋ とき.', 23, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7736, 'V る とき／V た とき', 'khi (chưa xong) / khi (đã xong)', 'V る とき: hành động ở vế sau xảy ra trước khi V hoàn tất; V た とき: sau khi V đã hoàn tất.', 23, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7737, 'V る ＋ と、～', 'hễ V thì ~ (kết quả tất yếu)', 'Vế sau là kết quả tự nhiên; không dùng ý chí, mệnh lệnh, nhờ vả.', 23, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7738, 'N（địa điểm）を V（di chuyển）', 'đi qua / đi trong N', 'を chỉ nơi đi qua với động từ di chuyển: 渡ります, 歩きます, 曲がります, 散歩します.', 23, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7739, 'くれます', '(ai đó) cho tôi', 'Người nhận là người nói hoặc người thuộc nhóm của người nói.', 24, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7740, 'V て あげます', 'làm V cho (người khác)', 'Thể hiện thiện ý. Tránh dùng trực tiếp với người trên vì có thể bị coi là kể ơn.', 24, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7741, 'V て もらいます', 'được (ai đó) V cho', 'Người nhận hành động là chủ ngữ, thể hiện lòng biết ơn.', 24, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7742, 'V て くれます', '(ai đó) V cho tôi', 'Người làm hành động là chủ ngữ, người nhận là người nói.', 24, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7743, 'Thể thông thường quá khứ ＋ ら、～', 'nếu ~ thì ~', 'Giả định điều kiện: V た ＋ ら, いA かったら, なA・N だったら.', 25, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7744, 'V たら、～（sau khi）', 'khi V xong thì ~', 'Dùng cho việc chắc chắn sẽ xảy ra; vế sau diễn ra sau khi V hoàn tất.', 25, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7745, 'V て／いA くて／なA・N で ＋ も', 'dù ~ cũng ~', 'Điều kiện ngược: kết quả không như dự đoán từ vế trước.', 25, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7746, 'もし／いくら', 'nếu như / dù bao nhiêu đi nữa', 'もし nhấn mạnh giả định trong câu ～たら; いくら nhấn mạnh mức độ trong câu ～ても.', 25, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N5', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7747, 'Thể thông thường ＋ んです', 'giải thích / hỏi lý do (nhấn mạnh)', 'V, いA thể thông thường ＋ んです; なA・N ＋ なんです. Dùng để xác nhận điều nghe/thấy, hỏi nguyên nhân hoặc giải thích lý do.', 26, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7748, '～んですが、V て いただけませんか', '~ nên phiền anh/chị V giúp được không ạ?', 'Nêu hoàn cảnh bằng ～んですが rồi nhờ vả lịch sự.', 26, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7749, '～んですが、từ để hỏi ＋ V たら いいですか', '~ vậy nên làm thế nào thì được?', 'Nêu hoàn cảnh rồi xin lời khuyên.', 26, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7750, 'Động từ thể khả năng', 'có thể V', 'Nhóm I: đổi âm cuối hàng い sang hàng え ＋ る (書く → 書ける). Nhóm II: ＋ られる (食べる → 食べられる). する → できる, 来る → 来られる. Tân ngữ thường chuyển を → が.', 27, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7751, '見えます／聞こえます', 'nhìn thấy / nghe thấy (tự nhiên)', 'Đối tượng tự lọt vào mắt, tai; khác 見られます／聞けます (có điều kiện để xem, nghe).', 27, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7752, 'できます（hoàn thành, xuất hiện）', 'được làm xong / mọc lên', 'できます còn có nghĩa là được xây dựng, hoàn thành.', 27, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7753, 'N しか ＋ phủ định', 'chỉ (nhấn mạnh ít)', 'しか luôn đi với động từ phủ định, mang sắc thái "ít, không đủ".', 27, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7754, 'N は（đối chiếu）', 'nhấn mạnh sự tương phản', 'は dùng để đối chiếu hai sự việc.', 27, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7755, 'V1（ます bỏ）ながら V2', 'vừa V1 vừa V2', 'V2 là hành động chính. Cũng dùng cho hai việc song song trong thời gian dài.', 28, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7756, 'V て います（thói quen）', 'thường xuyên V', 'Diễn tả hành động lặp lại thành thói quen. Thói quen trong quá khứ: V て いました.', 28, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7757, 'Thể thông thường ＋ し、～', 'vừa ~ lại vừa ~ / vì ~ và vì ~', 'Liệt kê nhiều đặc điểm hoặc nhiều lý do.', 28, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7758, 'それで', 'vì vậy, vì thế', 'Liên từ nối kết quả với lý do vừa nêu.', 28, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7759, 'V て います（trạng thái kết quả, tự động từ）', '~ đang ở trạng thái…', 'Miêu tả trạng thái trước mắt là kết quả của một sự thay đổi.', 29, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7760, 'V て しまいました／しまいます', 'đã V xong hết / lỡ V mất', 'Nhấn mạnh sự hoàn tất của hành động, hoặc sự tiếc nuối khi lỡ làm.', 29, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7761, 'N1 に N2 が V て あります', 'N2 đã được V sẵn ở N1', 'Tha động từ ＋ て あります: trạng thái là kết quả của hành động có chủ đích do ai đó làm.', 30, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7762, 'N2 は N1 に V て あります', 'N2 thì được V ở N1', 'Đưa N2 lên làm chủ đề để nói vị trí của nó.', 30, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7763, 'V て おきます', 'V sẵn / V trước để chuẩn bị; cứ để nguyên', 'Làm trước để chuẩn bị, làm để xử lý xong, hoặc giữ nguyên trạng thái.', 30, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7764, 'まだ ＋ khẳng định', 'vẫn còn', 'まだ đi với câu khẳng định nghĩa là trạng thái vẫn tiếp diễn.', 30, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7765, 'Thể ý chí（V よう／V おう）', 'cùng V nào (thân mật)', 'Nhóm I: đổi âm cuối hàng い sang hàng お ＋ う (行く → 行こう). Nhóm II: ＋ よう. する → しよう, 来る → 来よう. Là dạng thân mật của ～ましょう.', 31, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7766, 'V よう と 思って います', 'định V', 'Diễn tả ý định đã có từ trước và vẫn đang giữ.', 31, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7767, 'V る／V ない つもりです', 'dự định V / không V', 'Ý định chắc chắn hơn ～ようと 思って います.', 31, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7768, 'V る／N の 予定です', 'theo kế hoạch sẽ ~', 'Nói về kế hoạch, lịch trình đã định.', 31, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7769, 'まだ V て いません', 'vẫn chưa V', 'Việc lẽ ra đã xảy ra hoặc đã làm nhưng chưa thực hiện.', 31, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7770, 'V た／V ない ほうが いいです', 'nên / không nên V', 'Đưa ra lời khuyên.', 32, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7771, 'Thể thông thường ＋ でしょう', 'chắc là ~ (dự đoán)', 'なA, N bỏ だ. Thường đi với たぶん, きっと.', 32, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7772, 'Thể thông thường ＋ かもしれません', 'có lẽ ~ (khả năng thấp hơn でしょう)', 'Diễn tả khả năng có thể xảy ra. なA, N bỏ だ.', 32, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7773, 'Số lượng ＋ で', 'trong vòng / với (mức giới hạn)', 'で chỉ giới hạn về thời gian, tiền bạc, số lượng.', 32, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7774, 'Thể mệnh lệnh／thể cấm chỉ', 'hãy V! / cấm V!', 'Mệnh lệnh: nhóm I đổi âm cuối hàng い sang hàng え (行け); nhóm II ＋ ろ (食べろ); しろ, 来い. Cấm chỉ: thể từ điển ＋ な. Dùng khi ra lệnh gấp, cổ vũ, biển báo.', 33, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7775, 'X と 読みます／X と 書いて あります', 'đọc là X / có viết là X', 'と đánh dấu nội dung được đọc hoặc được viết.', 33, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7776, 'X は Y と いう 意味です', 'X có nghĩa là Y', 'Giải thích ý nghĩa của từ, ký hiệu.', 33, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7777, '「S」／thể thông thường ＋ と 言って いました', '(ai đó) đã nói là ~ (truyền lời)', 'Truyền đạt lại lời của người thứ ba.', 33, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7778, 'Thể thông thường ＋ と 伝えて いただけませんか', 'nhắn giúp là ~ được không ạ?', 'Nhờ người khác chuyển lời một cách lịch sự.', 33, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7779, 'V1 た／N の とおりに、V2', 'V2 đúng như V1 / theo N', 'Làm theo đúng như đã thấy, đã nghe, đã chỉ dẫn.', 34, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7780, 'V1 た／N の あとで、V2', 'sau khi V1 / sau N thì V2', 'V1 luôn ở thể た.', 34, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7781, 'V1 て／V1 ないで V2', 'V2 trong trạng thái (không) V1', 'Diễn tả cách thức, trạng thái đi kèm hành động chính.', 34, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7782, 'V1 ないで、V2', 'không V1 mà V2 (thay vào đó)', 'Chọn làm V2 thay vì V1.', 34, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7783, 'Thể điều kiện ば', 'nếu ~ thì ~', 'Nhóm I: đổi âm cuối hàng い sang hàng え ＋ ば (行けば). Nhóm II: ＋ れば. すれば, 来れば. いA: bỏ い ＋ ければ. なA, N: ～なら.', 35, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7784, 'N なら、～', 'nếu là N thì ~', 'Lấy điều người nghe vừa nói làm chủ đề rồi đưa ra thông tin, lời khuyên.', 35, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7785, 'Từ để hỏi ＋ V ば いいですか', 'nên làm ~ thì được?', 'Xin chỉ dẫn, lời khuyên.', 35, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7786, '～ば ～ほど', 'càng ~ càng ~', 'Lặp lại cùng một từ: V ば V る ほど; いA ければ いA ほど.', 35, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7787, 'V1 る／V1 ない ように、V2', 'V2 để (đạt được trạng thái) V1', 'V1 là động từ không chủ ý (thể khả năng, 見える, わかる…) hoặc thể ない.', 36, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7788, 'V る ように なります', 'trở nên có thể V / bắt đầu V', 'Diễn tả sự thay đổi dần về năng lực hoặc thói quen.', 36, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7789, 'V る／V ない ように します', 'cố gắng V / cố gắng không V', 'Nỗ lực duy trì thói quen. ～ように して ください: hãy cố gắng ~.', 36, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7790, 'N1（người）は N2 に V られます', 'N1 bị / được N2 V (bị động trực tiếp)', 'Chia bị động: nhóm I đổi âm cuối hàng い sang hàng あ ＋ れる (呼ぶ → 呼ばれる); nhóm II ＋ られる; される, 来られる.', 37, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7791, 'N1 は N2 に N3 を V られます', 'N1 bị N2 V (đồ vật, bộ phận của N1)', 'Bị động gián tiếp, thường mang nghĩa bị thiệt hại.', 37, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7792, 'N（vật / sự kiện）が／は V られます', 'N được V (không nêu người làm)', 'Dùng khi không cần hoặc không thể nêu chủ thể hành động.', 37, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7793, 'N1 は N2（người）に よって V られます', 'N1 được (tạo ra) bởi N2', 'Dùng với động từ sáng tạo, phát minh: 書く, 発明する, 発見する, 設計する…', 37, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7794, 'N から／N で つくられます', 'được làm từ / bằng N', 'から: nguyên liệu đã biến đổi, khó nhận ra; で: chất liệu còn nhìn thấy được.', 37, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7795, 'V る の は A です', 'việc V thì A', 'の danh từ hóa động từ để làm chủ đề.', 38, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7796, 'V る の が A です', 'thích / giỏi / nhanh… (việc) V', 'A là các tính từ chỉ sở thích, năng lực: 好き, 嫌い, 上手, 下手, 速い, 遅い…', 38, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7797, 'V る の を 忘れました', 'quên (làm) V', 'の danh từ hóa hành động làm tân ngữ của 忘れる.', 38, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7798, 'Thể thông thường ＋ の を 知って いますか', 'bạn có biết (việc) ~ không?', 'Hỏi người nghe có biết một sự việc không. Nếu chưa biết: 知りませんでした.', 38, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7799, 'Thể thông thường ＋ の は N です', 'cái / điều ~ là N (nhấn mạnh)', 'Đưa thông tin muốn nhấn mạnh xuống cuối câu.', 38, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7800, 'V て／V なくて／いA くて／なA で、～（nguyên nhân）', 'vì ~ nên ~', 'Vế sau thường là cảm xúc (びっくりする, 安心する, 困る…) hoặc trạng thái, khả năng; không dùng ý chí, mệnh lệnh.', 39, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7801, 'N で（nguyên nhân）', 'do N', 'N là sự kiện, hiện tượng: 事故, 地震, 病気, 火事…', 39, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7802, 'Thể thông thường ＋ ので、～', 'vì ~ nên ~ (khách quan, lịch sự)', 'なA, N ＋ なので. Mềm mỏng hơn から, hay dùng khi xin phép, giải thích.', 39, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7803, 'Từ để hỏi ＋ thể thông thường ＋ か、～', '(lồng câu hỏi có từ để hỏi vào câu)', 'なA, N bỏ だ.', 40, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7804, 'Thể thông thường ＋ か どうか、～', 'có ~ hay không', 'Lồng câu hỏi có / không vào câu. なA, N bỏ だ.', 40, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7805, 'V て みます', 'thử V', 'Làm thử để biết kết quả.', 40, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7806, 'いA（～い）→ ～さ', 'danh từ hóa tính từ い', 'Bỏ い thêm さ để chỉ mức độ: 高さ, 長さ, 重さ, 大きさ…', 40, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7807, 'いただきます／くださいます／やります', 'nhận (khiêm nhường) / cho (tôn kính) / cho (người dưới)', 'いただきます là khiêm nhường của もらいます; くださいます là tôn kính của くれます; やります dùng khi cho người dưới, động vật, cây cối.', 41, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7808, 'V て いただきます', 'được (người trên) V cho', 'Khiêm nhường của ～て もらいます.', 41, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7809, 'V て くださいます', '(người trên) V cho tôi', 'Tôn kính của ～て くれます.', 41, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7810, 'V て やります', 'V cho (người dưới, động vật)', 'Dùng với người có vị trí thấp hơn, con cái, động vật.', 41, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7811, 'V て くださいませんか', 'xin anh/chị V giúp được không ạ?', 'Nhờ vả lịch sự hơn ～て ください.', 41, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7812, 'V る／N の ＋ ために、～', 'để ~ / vì ~ (mục đích có chủ ý)', 'Động từ trước ために là động từ ý chí (khác ように). N の ために còn nghĩa "vì lợi ích của N".', 42, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7813, 'V る の／N ＋ に 使います／便利です／かかります', 'dùng để / tiện cho / mất (thời gian, tiền) để ~', 'の に／N に chỉ mục đích, công dụng.', 42, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7814, 'V（ます bỏ）そうです', 'có vẻ sắp V', 'Phán đoán điều sắp xảy ra dựa trên quan sát.', 43, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7815, 'いA（bỏ い）／なA ＋ そうです', 'trông có vẻ ~', 'いい → よさそう, ない → なさそう. Không dùng với tính từ nhìn là biết ngay (きれい, 赤い…).', 43, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7816, 'V て 来ます', 'đi V rồi quay lại', 'Đi đến đâu đó làm việc gì rồi trở về chỗ cũ.', 43, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7817, 'V（ます bỏ）／いA（bỏ い）／なA ＋ すぎます', 'quá ~', 'Diễn tả mức độ vượt quá, thường mang nghĩa không tốt.', 44, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7818, 'V（ます bỏ）＋ やすいです／にくいです', 'dễ V / khó V', 'Chia như tính từ い.', 44, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7819, 'N を いA（～く）／なA（～に）／N に します', 'làm cho N trở nên ~', 'Tác động có chủ ý để thay đổi trạng thái (khác ～なります là tự thay đổi).', 44, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7820, 'N に します（chọn, quyết định）', 'chọn N / quyết định N', 'Diễn tả sự lựa chọn, quyết định.', 44, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7821, '～場合は、～', 'trong trường hợp ~ thì ~', 'V る／V ない／V た, いA, なA な, N の ＋ 場合は. Hay dùng trong hướng dẫn, quy định.', 45, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7822, 'Thể thông thường ＋ のに、～', 'vậy mà ~ / mặc dù ~ (trái kỳ vọng)', 'Thể hiện sự bất ngờ, bất mãn. なA, N ＋ なのに.', 45, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7823, 'V る／V て いる／V た ＋ ところです', 'sắp / đang / vừa mới V', 'Nhấn mạnh thời điểm của hành động: ngay trước, đang giữa chừng, hoặc vừa kết thúc.', 46, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7824, 'V た ばかりです', 'vừa mới V (theo cảm nhận)', 'Người nói cảm thấy thời gian trôi qua chưa lâu, dù thực tế có thể đã khá lâu.', 46, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7825, 'Thể thông thường ＋ はずです', 'chắc chắn là ~ (theo căn cứ)', 'Phán đoán chắc chắn dựa trên căn cứ. なA な／N の ＋ はずです.', 46, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7826, 'Thể thông thường ＋ そうです（truyền đạt）', 'nghe nói ~', 'Truyền lại thông tin nghe được; nguồn tin: ～に よると. なA, N ＋ だそうです.', 47, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7827, 'Thể thông thường ＋ ようです', 'hình như ~ (phán đoán qua quan sát)', 'Phán đoán dựa trên tình huống, cảm nhận. なA な／N の ＋ ようです.', 47, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7828, '声／音／におい／味 が します', 'nghe thấy tiếng / ngửi thấy mùi / có vị', 'Diễn tả cảm nhận bằng giác quan.', 47, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7829, 'N（người）を V（tự động từ）させます', 'bắt / cho N làm V', 'Chia sai khiến: nhóm I đổi âm cuối hàng い sang hàng あ ＋ せる (行く → 行かせる); nhóm II ＋ させる; させる, 来させる. Với tự động từ, người làm dùng を.', 48, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7830, 'N1（người）に N2 を V（tha động từ）させます', 'bắt / cho N1 làm V (với N2)', 'Với tha động từ, người làm dùng に, tân ngữ vẫn dùng を.', 48, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7831, 'V させて いただけませんか', 'xin cho phép tôi V được không ạ?', 'Xin phép một cách rất lịch sự.', 48, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7832, 'V れます／V られます（tôn kính）', '(người trên) làm V', 'Tôn kính ngữ có hình thức giống thể bị động.', 49, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7833, 'お V（ます bỏ）に なります', '(người trên) làm V', 'Không dùng với động từ chỉ có một âm tiết trước ます (見ます, います) và động từ dạng N ＋ します.', 49, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7834, 'Động từ tôn kính đặc biệt', 'いらっしゃいます／召し上がります／おっしゃいます／ご覧に なります／なさいます', 'いらっしゃいます (いる・行く・来る), 召し上がります (食べる・飲む), おっしゃいます (言う), ご覧に なります (見る), なさいます (する), ご存じです (知って いる).', 49, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7835, 'お V（ます bỏ）／ご N ＋ ください', 'xin mời ~ (tôn kính của ～て ください)', 'Lời mời, yêu cầu rất lịch sự.', 49, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7836, 'お V（ます bỏ）します／ご N します', 'tôi xin làm V (khiêm nhường)', 'Hạ thấp hành động của mình khi hành động đó liên quan đến người trên.', 50, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7837, 'Động từ khiêm nhường đặc biệt', '参ります／おります／申します／いたします／拝見します／伺います', '参ります (行く・来る), おります (いる), 申します (言う), いたします (する), いただきます (食べる・もらう), 拝見します (見る), 伺います (聞く・訪ねる), 存じます (知る).', 50, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (7838, '～で ございます／～ございます', 'là / có (cách nói lịch sự trang trọng)', 'ございます là dạng lịch sự của あります; で ございます là dạng lịch sự của です.', 50, '2026-10-05 14:43:05.185', '2026-10-05 14:43:05.185', 'N4', NULL, 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5860, 'V(て) + ばかりいる / N + ばかり', 'toàn là ~, cứ ~ suốt', '「〜てばかりいる」: chỉ làm mỗi việc đó (chê trách). 「〜たばかり」 (vừa mới) đã học ở Bài 1.', 589, '2026-08-29 06:52:57.015', '2026-10-05 14:43:05.185', 'N3', 'spoken', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5863, 'V(意向形) + にも + V(可能形・ない)', 'dù muốn ~ cũng không ~ được', 'Muốn làm nhưng hoàn cảnh không cho phép. 「行こうにも行けない」.', 589, '2026-08-29 06:52:57.068', '2026-10-05 14:43:05.185', 'N3', 'written', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5879, 'N + にかけては', 'về mặt ~, xét về ~ thì (giỏi nhất)', '「〜にかけては」 dùng để khen ai đó xuất sắc trong một lĩnh vực.', 557, '2026-08-29 06:52:58.596', '2026-10-05 14:43:05.185', 'N2', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5886, 'V(ない) + ざるを得ない', 'buộc phải ~, không thể không ~', 'する → せざるを得ない. Bị hoàn cảnh ép buộc, dù không muốn. Trang trọng, văn viết.', 558, '2026-08-29 06:52:59.424', '2026-10-05 14:43:05.185', 'N2', 'written', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5894, 'Số lượng + からある / からする / からの + N', 'tận, những ~ (nhấn mạnh số lượng lớn)', '「〜からある」 (khối lượng/kích thước), 「〜からする」 (giá tiền), 「〜からいる」 (số người).', 558, '2026-08-29 06:52:59.518', '2026-10-05 14:43:05.185', 'N2', 'written', 8);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5913, 'V(ます bỏ) + ようがない', 'không có cách nào để ~', 'Không có phương tiện/cách thức để thực hiện. 「連絡しようがない」, 「どうしようもない」.', 594, '2026-08-29 06:53:01.282', '2026-10-05 14:43:05.185', 'N2', 'neutral', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5919, 'N + たる(もの)', 'là ~ thì (phải có tư cách xứng đáng)', 'Nhấn mạnh trách nhiệm/phẩm chất đi kèm với một địa vị. Cổ, trang trọng.', 560, '2026-08-29 06:53:01.827', '2026-10-05 14:43:05.185', 'N1', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5950, 'N + はさておき', 'khoan bàn tới ~, gác ~ sang một bên', 'Tạm gác chủ đề này để nói sang chuyện khác (quan trọng/cấp bách hơn).', 598, '2026-08-29 06:53:03.919', '2026-10-05 14:43:05.185', 'N1', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5969, 'N + によると / N + によれば', 'theo ~ (nguồn thông tin)', NULL, 600, '2026-09-02 08:54:27.883', '2026-10-05 14:43:05.185', 'N2', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5982, 'N + を裁判で争う / N + が裁判にかけられる', 'tranh tụng ~ tại tòa; ~ bị đưa ra xét xử', NULL, 602, '2026-09-02 08:54:27.967', '2026-10-05 14:43:05.185', 'N2', 'formal', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5987, 'N + と契約する / 契約を結ぶ', 'ký hợp đồng ~', NULL, 602, '2026-09-02 08:54:28.001', '2026-10-05 14:43:05.185', 'N2', 'formal', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5993, 'N + を改める / N + を改めて', 'sửa đổi ~; (改めて) một lần nữa', NULL, 603, '2026-09-02 08:54:28.046', '2026-10-05 14:43:05.185', 'N2', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5995, 'N + が共通している / 共通の + N', 'có chung ~', NULL, 603, '2026-09-02 08:54:28.055', '2026-10-05 14:43:05.185', 'N2', 'formal', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (5999, 'N + に迫られる / N + が迫る', 'bị ~ thúc ép; (thời hạn) cận kề', NULL, 604, '2026-09-02 08:54:28.077', '2026-10-05 14:43:05.185', 'N1', 'formal', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6000, '余すところなく + V', 'trọn vẹn, không bỏ sót chỗ nào', NULL, 604, '2026-09-02 08:54:28.083', '2026-10-05 14:43:05.185', 'N1', 'formal', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6013, '誠意をもって + V', 'bằng thành ý, một cách chân thành', NULL, 606, '2026-09-02 08:54:28.138', '2026-10-05 14:43:05.185', 'N1', 'formal', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6022, 'V(た) + 末に / N + の末(に)', 'cuối cùng sau ~ thì ~', NULL, 607, '2026-09-02 08:54:28.173', '2026-10-05 14:43:05.185', 'N1', 'formal', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6025, '即時に + V / 即時の + N', 'ngay lập tức, tức thì', NULL, 607, '2026-09-02 08:54:28.183', '2026-10-05 14:43:05.185', 'N1', 'formal', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6028, 'N + を覆す / N + が覆される', 'lật đổ ~, lật ngược ~', NULL, 608, '2026-09-02 08:54:28.195', '2026-10-05 14:43:05.185', 'N1', 'formal', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6092, 'V(た) + ほうがいい', 'nên ~', NULL, 692, '2026-09-02 09:13:28.398', '2026-10-05 14:43:05.185', 'N5', 'neutral', 5);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6164, 'V(ば) + いいのに', 'giá mà ~ thì tốt', NULL, 705, '2026-09-02 09:13:28.948', '2026-10-05 14:43:05.185', 'N3', 'neutral', 6);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6165, 'V/A/N(普通形) + もの / もん', 'vì ~ mà (biện minh, thân mật)', NULL, 705, '2026-09-02 09:13:28.954', '2026-10-05 14:43:05.185', 'N3', 'spoken', 7);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6166, 'V/A/N(普通形) + ものだ', 'đương nhiên ~; thói quen xưa', NULL, 706, '2026-09-02 09:13:28.966', '2026-10-05 14:43:05.185', 'N3', 'neutral', 0);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6167, 'V(辞書形) + ものではない', 'không nên ~', NULL, 706, '2026-09-02 09:13:28.976', '2026-10-05 14:43:05.185', 'N3', 'formal', 1);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6168, 'V(辞書形) + ものか / もんか', 'quyết không ~, làm gì có chuyện ~', NULL, 706, '2026-09-02 09:13:28.983', '2026-10-05 14:43:05.185', 'N3', 'spoken', 2);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6169, 'V(辞書形 / ない) + ことだ', 'nên ~ (lời khuyên)', NULL, 706, '2026-09-02 09:13:28.989', '2026-10-05 14:43:05.185', 'N3', 'neutral', 3);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6170, 'Từ để hỏi + V/A(普通形) + ことか', 'biết bao ~!', NULL, 706, '2026-09-02 09:13:28.995', '2026-10-05 14:43:05.185', 'N3', 'neutral', 4);
INSERT INTO public."Grammar" (id, pattern, meaning, explanation, "lessonId", "createdAt", "updatedAt", "jlptLevel", "formalityLevel", "sortOrder") VALUES (6171, 'V(辞書形) + ことはない', 'không cần ~', NULL, 706, '2026-09-02 09:13:29.002', '2026-10-05 14:43:05.185', 'N3', 'neutral', 5);
