INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15283, '家に帰ったら、誰もいなかった。', 'Ie ni kaettara, dare mo inakatta.', NULL, 'Về đến nhà thì chẳng có ai.', 5818, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15530, '今さら後悔したところで、どうにもならない。', 'Imasara kōkai shita tokoro de, dō ni mo naranai.', NULL, 'Giờ có hối hận thì cũng chẳng thay đổi được gì.', 5942, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15270, '後ろの人にも聞こえるように、大きい声で話してください。', 'Ushiro no hito ni mo kikoeru yō ni, ōkii koe de hanashite kudasai.', NULL, 'Hãy nói to để người phía sau cũng nghe được.', 5812, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15271, '忘れないように、手帳に書いておきます。', 'Wasurenai yō ni, techō ni kaite okimasu.', NULL, 'Tôi ghi vào sổ tay để khỏi quên.', 5812, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15272, '毎日野菜を食べるようにしています。', 'Mainichi yasai o taberu yō ni shite imasu.', NULL, 'Tôi đang cố gắng ngày nào cũng ăn rau.', 5813, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15273, '練習して、泳げるようになりました。', 'Renshū shite, oyogeru yō ni narimashita.', NULL, 'Nhờ luyện tập, tôi đã bơi được.', 5813, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15274, '留学のために、お金を貯めています。', 'Ryūgaku no tame ni, okane o tamete imasu.', NULL, 'Tôi đang để dành tiền để đi du học.', 5814, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15275, '家族のために働いています。', 'Kazoku no tame ni hataraite imasu.', NULL, 'Tôi làm việc vì gia đình.', 5814, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15276, '先生のおかげで合格できました。', 'Sensei no okage de gōkaku dekimashita.', NULL, 'Nhờ có thầy mà em đã đỗ.', 5815, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15277, '道が空いていたおかげで、早く着いた。', 'Michi ga suite ita okage de, hayaku tsuita.', NULL, 'Nhờ đường vắng nên tôi đến sớm.', 5815, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15278, '寝坊したせいで、電車に乗り遅れた。', 'Nebō shita sei de, densha ni noriokureta.', NULL, 'Vì ngủ quên nên tôi lỡ tàu.', 5816, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15279, '雨のせいで試合が中止になった。', 'Ame no sei de shiai ga chūshi ni natta.', NULL, 'Vì mưa nên trận đấu bị hủy.', 5816, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15280, '考えれば考えるほど、わからなくなる。', 'Kangaereba kangaeru hodo, wakaranaku naru.', NULL, 'Càng nghĩ càng không hiểu.', 5817, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15281, '値段が高ければ高いほど、品質がいいとは限らない。', 'Nedan ga takakereba takai hodo, hinshitsu ga ii to wa kagiranai.', NULL, 'Giá càng cao không hẳn chất lượng càng tốt.', 5817, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15282, '窓を開けたら、雪が降っていた。', 'Mado o aketara, yuki ga futte ita.', NULL, 'Mở cửa sổ ra thì thấy tuyết đang rơi.', 5818, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15284, '習慣は国によって違います。', 'Shūkan wa kuni ni yotte chigaimasu.', NULL, 'Phong tục khác nhau tùy theo mỗi nước.', 5819, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15285, 'この橋は100年前に建設されました。地震によって壊れました。', 'Kono hashi wa hyaku-nen mae ni kensetsu saremashita. Jishin ni yotte kowaremashita.', NULL, 'Cây cầu này xây 100 năm trước. Nó bị hỏng do động đất.', 5819, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15286, '午後から雨が降るかもしれない。', 'Gogo kara ame ga furu kamo shirenai.', NULL, 'Có thể chiều nay trời mưa.', 5820, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15287, '彼はもう帰ったかもしれません。', 'Kare wa mō kaetta kamo shiremasen.', NULL, 'Có lẽ anh ấy đã về rồi.', 5820, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15288, '来月から日本語を習うことにしました。', 'Raigetsu kara nihongo o narau koto ni shimashita.', NULL, 'Tôi quyết định từ tháng sau sẽ học tiếng Nhật.', 5821, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15289, '4月に大阪へ転勤することになりました。', 'Shi-gatsu ni Ōsaka e tenkin suru koto ni narimashita.', NULL, 'Tháng 4 tôi được chuyển công tác đến Osaka.', 5821, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15290, '日本に来たばかりで、まだ何もわかりません。', 'Nihon ni kita bakari de, mada nani mo wakarimasen.', NULL, 'Tôi vừa mới đến Nhật nên chưa biết gì cả.', 5822, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15558, '彼は来月、新しい部署に就く。', 'Kare wa raigetsu, atarashii busho ni tsuku.', NULL, 'Tháng sau anh ấy nhậm chức ở phòng ban mới.', 5956, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15560, '入社後、営業部に配属された。', 'Nyūsha go, eigyōbu ni haizoku sareta.', NULL, 'Sau khi vào công ty, tôi được phân về phòng kinh doanh.', 5957, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15561, '彼女は海外支店に配属されることになった。', 'Kanojo wa kaigai shiten ni haizoku sareru koto ni natta.', NULL, 'Cô ấy sẽ được phân công sang chi nhánh nước ngoài.', 5957, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15562, '最終判断は委員会に委ねられた。', 'Saishū handan wa iinkai ni yudanerareta.', NULL, 'Quyết định cuối cùng được giao cho ủy ban.', 5958, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15563, '子供の将来は本人に委ねるべきだ。', 'Kodomo no shōrai wa honnin ni yudaneru beki da.', NULL, 'Tương lai con cái nên để bản thân quyết định.', 5958, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15564, '彼は親の援助に頼らず、学費を稼いだ。', 'Kare wa oya no enjo ni tayorazu, gakuhi o kaseida.', NULL, 'Anh ấy kiếm học phí mà không dựa vào sự giúp đỡ của bố mẹ.', 5959, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15565, '彼女は頼りになる先輩だ。', 'Kanojo wa tayori ni naru senpai da.', NULL, 'Cô ấy là senpai đáng tin cậy.', 5959, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15567, '彼は理解を求めたが、得られなかった。', 'Kare wa rikai o motometa ga, erarenakatta.', NULL, 'Anh ấy mong được thấu hiểu nhưng không được.', 5960, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15568, 'この地域には十分な水が供給されていない。', 'Kono chiiki ni wa jūbun na mizu ga kyōkyū sarete inai.', NULL, 'Khu vực này không được cung cấp đủ nước.', 5961, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15569, '電力会社が都市部に電気を供給する。', 'Denryoku gaisha ga toshibu ni denki o kyōkyū suru.', NULL, 'Công ty điện lực cung cấp điện cho khu đô thị.', 5961, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15570, '荷物を指定の住所に届けてください。', 'Nimotsu o shitei no jūsho ni todokete kudasai.', NULL, 'Hãy giao hàng đến địa chỉ đã chỉ định.', 5962, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15571, '彼の死の知らせが家族に届いた。', 'Kare no shi no shirase ga kazoku ni todoita.', NULL, 'Tin anh ấy mất đã đến tai gia đình.', 5962, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15572, '売上は去年の三倍になった。', 'Uriage wa kyonen no sanbai ni natta.', NULL, 'Doanh thu gấp ba lần năm ngoái.', 5963, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15573, '人口が十年で二倍に増えた。', 'Jinkō ga jūnen de nibai ni fueta.', NULL, 'Dân số tăng gấp đôi trong mười năm.', 5963, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15574, '人によって考え方は違う。', 'Hito ni yotte kangaekata wa chigau.', NULL, 'Tùy người mà cách suy nghĩ khác nhau.', 5964, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15575, '台風により、多くの家が被害を受けた。', 'Taifū ni yori, ōku no ie ga higai o uketa.', NULL, 'Do bão, nhiều nhà bị thiệt hại.', 5964, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15576, '経済成長に伴って、環境問題も深刻化した。', 'Keizai seichō ni tomonatte, kankyō mondai mo shinkokuka shita.', NULL, 'Cùng với tăng trưởng kinh tế, vấn đề môi trường cũng nghiêm trọng hơn.', 5965, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15577, '制度改正に伴い、手続きが変わる。', 'Seido kaisei ni tomonai, tetsuzuki ga kawaru.', NULL, 'Theo cải cách thể chế, thủ tục sẽ thay đổi.', 5965, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15578, 'ゴミの量を減らす努力が必要だ。', 'Gomi no ryō o herasu doryoku ga hitsuyō da.', NULL, 'Cần nỗ lực giảm lượng rác.', 5966, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15579, '出生率が年々減っている。', 'Shusshōritsu ga nennen hette iru.', NULL, 'Tỷ lệ sinh giảm dần theo năm.', 5966, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15580, '塩を少し加えてください。', 'Shio o sukoshi kuwaete kudasai.', NULL, 'Hãy thêm một chút muối.', 5967, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15581, '雨に加えて、風も強くなった。', 'Ame ni kuwaete, kaze mo tsuyoku natta.', NULL, 'Ngoài mưa, gió cũng mạnh lên.', 5967, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15582, 'この国の輸出の半分を車が占めている。', 'Kono kuni no yushutsu no hanbun o kuruma ga shimete iru.', NULL, 'Ô tô chiếm một nửa xuất khẩu của nước này.', 5968, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15583, '若者が人口の三割を占める。', 'Wakamono ga jinkō no sanwari o shimeru.', NULL, 'Giới trẻ chiếm ba phần mười dân số.', 5968, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15584, '調査によると、満足度は80％だった。', 'Chōsa ni yoru to, manzokudo wa hachijū pāsento datta.', NULL, 'Theo khảo sát, mức hài lòng là 80%.', 5969, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15588, '乱開発は生態系を危険にさらす。', 'Rankaihatsu wa seitaikei o kiken ni sarasu.', NULL, 'Khai thác bừa bãi đặt hệ sinh thái vào nguy hiểm.', 5971, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15590, '新商品がテレビで宣伝されている。', 'Shin shōhin ga terebi de senden sarete iru.', NULL, 'Sản phẩm mới đang được quảng cáo trên TV.', 5972, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15591, '彼は自分の本を宣伝するために講演した。', 'Kare wa jibun no hon o senden suru tame ni kōen shita.', NULL, 'Anh ấy thuyết trình để quảng bá cuốn sách của mình.', 5972, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15592, '結果は来週公表される予定だ。', 'Kekka wa raishū kōhyō sareru yotei da.', NULL, 'Kết quả dự kiến được công bố tuần sau.', 5973, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15593, '政府が新しい方針を公表した。', 'Seifu ga atarashii hōshin o kōhyō shita.', NULL, 'Chính phủ đã công bố phương châm mới.', 5973, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15594, '記事が新聞に掲載された。', 'Kiji ga shinbun ni keisai sareta.', NULL, 'Bài báo được đăng trên báo.', 5974, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15595, '求人情報をサイトに掲載する。', 'Kyūjin jōhō o saito ni keisai suru.', NULL, 'Đăng tin tuyển dụng lên website.', 5974, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15596, '彼は秘密を漏らしてしまった。', 'Kare wa himitsu o morashite shimatta.', NULL, 'Anh ấy lỡ tiết lộ bí mật.', 5975, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15597, '計画の内容がメディアに漏れた。', 'Keikaku no naiyō ga media ni moreta.', NULL, 'Nội dung kế hoạch bị lộ ra truyền thông.', 5975, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15598, '記者が不正を暴露した。', 'Kisha ga fusei o bakuro shita.', NULL, 'Phóng viên vạch trần hành vi gian lận.', 5976, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15599, 'スキャンダルが暴露され、辞任を余儀なくされた。', 'Sukyandaru ga bakuro sare, jinin o yoginaku sareta.', NULL, 'Vụ bê bối bị phơi bày, buộc phải từ chức.', 5976, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15601, '彼の論文は教育制度について論じている。', 'Kare no ronbun wa kyōiku seido ni tsuite ronjite iru.', NULL, 'Luận văn của anh ấy bàn về chế độ giáo dục.', 5977, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15602, 'その政策は野党から批判された。', 'Sono seisaku wa yatō kara hihan sareta.', NULL, 'Chính sách đó bị phe đối lập phê phán.', 5978, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15603, '彼は自分の行動を後から批判した。', 'Kare wa jibun no kōdō o ato kara hihan shita.', NULL, 'Sau đó anh ấy phê phán hành động của chính mình.', 5978, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15604, '彼は天才と称されている。', 'Kare wa tensai to shō sarete iru.', NULL, 'Anh ấy được coi là thiên tài.', 5979, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15605, 'この地域は「小京都」と呼ばれる。', 'Kono chiiki wa "Shō-Kyōto" to yobareru.', NULL, 'Vùng này được gọi là "Kyoto thu nhỏ".', 5979, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15606, '彼は交通規則に違反した。', 'Kare wa kōtsū kisoku ni ihan shita.', NULL, 'Anh ấy vi phạm luật giao thông.', 5980, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15607, 'その行為は法律に反する。', 'Sono kōi wa hōritsu ni hansuru.', NULL, 'Hành vi đó trái với pháp luật.', 5980, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15608, '被害者が加害者を訴えた。', 'Higaisha ga kagaisha o uttaeta.', NULL, 'Nạn nhân đã kiện người gây hại.', 5981, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15609, '検察は彼を起訴した。', 'Kensatsu wa kare o kiso shita.', NULL, 'Viện kiểm sát đã truy tố anh ta.', 5981, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15612, '被告の無罪が証明された。', 'Hikoku no muzai ga shōmei sareta.', NULL, 'Sự vô tội của bị cáo đã được chứng minh.', 5983, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15614, '弁護士が依頼人を弁護した。', 'Bengoshi ga irainin o bengo shita.', NULL, 'Luật sư đã biện hộ cho thân chủ.', 5984, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15615, '彼は自分の考えを熱心に弁護した。', 'Kare wa jibun no kangae o nesshin ni bengo shita.', NULL, 'Anh ấy nhiệt tình bảo vệ quan điểm của mình.', 5984, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15616, '会社は被害者に損害を補償した。', 'Kaisha wa higaisha ni songai o hoshō shita.', NULL, 'Công ty bồi thường thiệt hại cho nạn nhân.', 5985, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15617, '事故に対して保険会社が賠償した。', 'Jiko ni taishite hoken gaisha ga baishō shita.', NULL, 'Công ty bảo hiểm đã bồi thường vụ tai nạn.', 5985, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15618, '人間の忍耐にも限界がある。', 'Ningen no nintai ni mo genkai ga aru.', NULL, 'Sự kiên nhẫn của con người cũng có giới hạn.', 5986, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15619, '予算には限界があるので、全部は買えない。', 'Yosan ni wa genkai ga aru node, zenbu wa kaenai.', NULL, 'Ngân sách có hạn nên không mua hết được.', 5986, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15620, '来月から新しい会社と契約する。', 'Raigetsu kara atarashii kaisha to keiyaku suru.', NULL, 'Từ tháng sau ký hợp đồng với công ty mới.', 5987, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15621, '賃貸契約を結んだ。', 'Chintai keiyaku o musunda.', NULL, 'Đã ký hợp đồng thuê nhà.', 5987, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15622, 'この本は文学に分類される。', 'Kono hon wa bungaku ni bunrui sareru.', NULL, 'Cuốn sách này được phân loại vào văn học.', 5988, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15623, '商品は三つのカテゴリーに区分される。', 'Shōhin wa mittsu no kategorī ni kubun sareru.', NULL, 'Sản phẩm được chia thành ba danh mục.', 5988, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15624, 'この地域の特徴として、雪が多い。', 'Kono chiiki no tokuchō to shite, yuki ga ōi.', NULL, 'Đặc trưng của vùng này là tuyết nhiều.', 5989, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15630, '資料を整理してから会議に出た。', 'Shiryō o seiri shite kara kaigi ni deta.', NULL, 'Sắp xếp tài liệu rồi mới đi họp.', 5992, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15631, '部屋が整理されて気持ちがいい。', 'Heya ga seiri sarete kimochi ga ii.', NULL, 'Phòng được dọn gọn nên thấy thoải mái.', 5992, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15632, '生活習慣を改める必要がある。', 'Seikatsu shūkan o aratameru hitsuyō ga aru.', NULL, 'Cần thay đổi thói quen sinh hoạt.', 5993, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15959, '彼のせいで失敗した。', 'Kare no sei de shippai shita.', NULL, 'Vì anh ấy mà thất bại.', 6156, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15634, '社会の構造が変化している。', 'Shakai no kōzō ga henka shite iru.', NULL, 'Cấu trúc xã hội đang thay đổi.', 5994, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15635, 'この建物は独特の構造をしている。', 'Kono tatemono wa dokutoku no kōzō o shite iru.', NULL, 'Tòa nhà này có cấu trúc độc đáo.', 5994, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15637, 'これらの言語は語源が共通している。', 'Korera no gengo wa gogen ga kyōtsū shite iru.', NULL, 'Các ngôn ngữ này có chung nguồn gốc từ.', 5995, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15639, '経営不振により、リストラを余儀なくされた。', 'Keiei fushin ni yori, risutora o yoginaku sareta.', NULL, 'Do kinh doanh suy thoái buộc phải cắt giảm nhân sự.', 5996, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15640, '彼の努力は称賛に足る。', 'Kare no doryoku wa shōsan ni taru.', NULL, 'Nỗ lực của anh ấy đáng được ca ngợi.', 5997, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15641, 'その証拠は信用に足りない。', 'Sono shōko wa shinyō ni tarinai.', NULL, 'Bằng chứng đó không đáng tin.', 5997, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15642, '今の技術をもってしても、解決は難しい。', 'Ima no gijutsu o motte shite mo, kaiketsu wa muzukashii.', NULL, 'Dù có công nghệ hiện tại cũng khó giải quyết.', 5998, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15643, '全力をもってしても、及ばなかった。', 'Zenryoku o motte shite mo, oyobanakatta.', NULL, 'Dù dốc toàn lực cũng không sánh kịp.', 5998, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15644, '締め切りが迫っている。', 'Shimekiri ga sematte iru.', NULL, 'Hạn chót đang cận kề.', 5999, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15648, '余剰金を設備投資に充てる。', 'Yojōkin o setsubi tōshi ni ateru.', NULL, 'Dành tiền dư cho đầu tư thiết bị.', 6001, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15649, '寄付金は被災地の復興に充当される。', 'Kifukin wa hisaichi no fukkō ni jūtō sareru.', NULL, 'Tiền quyên góp được dùng cho tái thiết vùng thiên tai.', 6001, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15652, '時間を余して観光も楽しんだ。', 'Jikan o amashite kankō mo tanoshinda.', NULL, 'Còn dư thời gian nên cũng đi tham quan.', 6003, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15654, '消費者から見れば、値段が重要だ。', 'Shōhisha kara mireba, nedan ga jūyō da.', NULL, 'Xét từ phía người tiêu dùng, giá cả quan trọng.', 6004, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15655, '歴史から見ると、繰り返されている。', 'Rekishi kara miru to, kurikaesarete iru.', NULL, 'Nhìn từ lịch sử thì điều này lặp lại.', 6004, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15656, '事実に基づいて判断する。', 'Jijitsu ni motozuite handan suru.', NULL, 'Phán đoán dựa trên sự thật.', 6005, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15657, '法律に基づき、処分が下された。', 'Hōritsu ni motozuki, shobun ga kudasareta.', NULL, 'Dựa trên pháp luật, hình phạt được ban hành.', 6005, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15659, '前回の結果を踏まえ、対策を練る。', 'Zenkai no kekka o fumae, taisaku o neru.', NULL, 'Căn cứ kết quả lần trước, lập biện pháp.', 6006, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15661, '双方の合意を前提に交渉する。', 'Sōhō no gōi o zentei ni kōshō suru.', NULL, 'Đàm phán trên tiền đề hai bên đồng ý.', 6007, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15662, '現場の実情に即した対応が必要だ。', 'Genba no jitsujō ni sokushita taiō ga hitsuyō da.', NULL, 'Cần ứng phó phù hợp thực tế hiện trường.', 6008, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15663, '時代に即して制度を見直す。', 'Jidai ni sokushite seido o minaosu.', NULL, 'Xem xét lại thể chế cho phù hợp thời đại.', 6008, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15664, '各方面を総合すれば、計画は実行可能だ。', 'Kaku hōmen o sōgō sureba, keikaku wa jikkō kanō da.', NULL, 'Tổng hợp các mặt thì kế hoạch khả thi.', 6009, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15665, 'データを総合すると、傾向が見えてくる。', 'Dēta o sōgō suru to, keikō ga miete kuru.', NULL, 'Tổng hợp dữ liệu thì thấy xu hướng.', 6009, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15668, '将来を見据えて、スキルを身につける。', 'Shōrai o misuete, sukiru o mi ni tsukeru.', NULL, 'Hướng tới tương lai, trau dồi kỹ năng.', 6011, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15669, '彼は常に目標を見据えている。', 'Kare wa tsune ni mokuhyō o misuete iru.', NULL, 'Anh ấy luôn hướng về mục tiêu.', 6011, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15670, 'この国では自然を尊ぶ。', 'Kono kuni de wa shizen o tōtobu.', NULL, 'Ở đất nước này người ta tôn trọng thiên nhiên.', 6012, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15671, '伝統を尊ぶ考え方。', 'Dentō o tōtobu kangaekata.', NULL, 'Quan niệm tôn trọng truyền thống.', 6012, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15672, '誠意をもって対応した。', 'Seii o motte taiō shita.', NULL, 'Đã ứng xử với thành ý.', 6013, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15673, '誠意をもってお詫び申し上げます。', 'Seii o motte owabi mōshiagemasu.', NULL, 'Xin được xin lỗi chân thành.', 6013, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15676, '信念に背く行為は許されない。', 'Shinnen ni somuku kōi wa yurusarenai.', NULL, 'Hành vi phản bội niềm tin không được tha thứ.', 6015, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15677, '期待に背いた結果になった。', 'Kitai ni somuita kekka ni natta.', NULL, 'Kết quả đã phụ lòng kỳ vọng.', 6015, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15679, '周囲の目を顧みない。', 'Shūi no me o kaeriminai.', NULL, 'Không màng ánh mắt xung quanh.', 6016, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15680, '多数派に同調する必要はない。', 'Tasūha ni dōchō suru hitsuyō wa nai.', NULL, 'Không cần đồng điệu với đa số.', 6017, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15681, '世論に同調した政策。', 'Yoron ni dōchō shita seisaku.', NULL, 'Chính sách theo dư luận.', 6017, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15683, '見た目を異にしているが、中身は同じだ。', 'Mitame o koto ni shite iru ga, nakami wa onaji da.', NULL, 'Bề ngoài khác nhưng bên trong giống nhau.', 6018, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15686, '長い歳月を経て、再会した。', 'Nagai saigetsu o hete, saikai shita.', NULL, 'Sau nhiều năm tháng, chúng tôi gặp lại.', 6020, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15687, '議論を経て、結論に達した。', 'Giron o hete, ketsuron ni tasshita.', NULL, 'Qua tranh luận, đã đi đến kết luận.', 6020, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15688, '入学以来、一度も欠席していない。', 'Nyūgaku irai, ichido mo kesseki shite inai.', NULL, 'Kể từ khi nhập học chưa vắng lần nào.', 6021, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15690, '悩んだ末に、転職を決意した。', 'Nayanda sue ni, tenshoku o ketsui shita.', NULL, 'Sau khi băn khoăn, quyết định chuyển việc.', 6022, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15691, '長い議論の末、案が可決された。', 'Nagai giron no sue, an ga kaketsu sareta.', NULL, 'Sau tranh luận dài, đề án được thông qua.', 6022, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15692, '会議に先立ち、資料を配布した。', 'Kaigi ni sakidachi, shiryō o haifu shita.', NULL, 'Trước cuộc họp, đã phát tài liệu.', 6023, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15693, '出発に先立って、点検を行う。', 'Shuppatsu ni sakidatte, tenken o okonau.', NULL, 'Trước khi khởi hành, tiến hành kiểm tra.', 6023, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15694, '転勤を機に、家族で引っ越した。', 'Tenkin o ki ni, kazoku de hikkoshita.', NULL, 'Nhân dịp chuyển công tác, cả nhà chuyển nhà.', 6024, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15695, '記念日を機に、新しいプロジェクトを始める。', 'Kinenbi o ki to shite, atarashii purojekuto o hajimeru.', NULL, 'Nhân ngày kỷ niệm, bắt đầu dự án mới.', 6024, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15696, '問題が発覚し、即時に対応した。', 'Mondai ga hakkaku shi, sokuji ni taiō shita.', NULL, 'Vấn đề phát hiện ra, ứng phó ngay.', 6025, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15697, '即時の報告が求められる。', 'Sokuji no hōkoku ga motomerareru.', NULL, 'Yêu cầu báo cáo tức thì.', 6025, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15698, 'その問題の根底にあるのは貧困だ。', 'Sono mondai no kontei ni aru no wa hinkon da.', NULL, 'Nằm ở gốc rễ vấn đề đó là nghèo đói.', 6026, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15699, '不信感が根底にある。', 'Fushinkan ga kontei ni aru.', NULL, 'Sự không tin tưởng nằm ở gốc rễ.', 6026, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15702, '政権が覆された。', 'Seiken ga kutsugaesareta.', NULL, 'Chính quyền bị lật đổ.', 6028, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15704, '温泉に浸って疲れを癒す。', 'Onsen ni hitatte tsukare o iyasu.', NULL, 'Ngâm mình trong suối nước nóng để xả mệt.', 6029, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15705, '研究に浸っている。', 'Kenkyū ni hitatte iru.', NULL, 'Đang đắm chìm nghiên cứu.', 6029, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15707, '新入生がクラスに溶け込むのに時間がかかる。', 'Shinnyūsei ga kurasu ni tokekomu no ni jikan ga kakaru.', NULL, 'Tân sinh viên mất thời gian hòa nhập lớp.', 6030, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15708, '技術により水が純化される。', 'Gijutsu ni yori mizu ga junka sareru.', NULL, 'Nhờ công nghệ nước được tinh lọc.', 6031, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15709, '思想を純化しようとする試み。', 'Shisō o junka shiyō to suru kokoromi.', NULL, 'Nỗ lực tinh luyện tư tưởng.', 6031, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15712, '予算が膨張した。', 'Yosan ga bōchō shita.', NULL, 'Ngân sách phình to.', 6033, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15714, '緻密な計画を立てた。', 'Chimitsu na keikaku o tateta.', NULL, 'Đã lập kế hoạch tỉ mỉ.', 6034, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15715, 'データを緻密に分析する。', 'Dēta o chimitsu ni bunseki suru.', NULL, 'Phân tích dữ liệu chặt chẽ.', 6034, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15742, '早く帰りたいんです。', 'Hayaku kaeritain desu.', NULL, 'Tôi muốn về sớm (vì lý do nào đó).', 6048, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15743, 'もっと勉強したいんです。', 'Motto benkyō shitain desu.', NULL, 'Tôi muốn học thêm.', 6048, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15747, '予約する必要があります。', 'Yoyaku suru hitsuyō ga arimasu.', NULL, 'Cần phải đặt trước.', 6050, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15756, 'ご飯を食べた後で、散歩します。', 'Gohan o tabeta ato de, sanpo shimasu.', NULL, 'Sau khi ăn cơm tôi đi dạo.', 6055, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15757, '仕事が終わった後で、飲みに行きます。', 'Shigoto ga owatta ato de, nomi ni ikimasu.', NULL, 'Sau khi tan làm tôi đi uống.', 6055, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15762, '音楽を聞くのが好きです。', 'Ongaku o kiku no ga suki desu.', NULL, 'Tôi thích nghe nhạc.', 6058, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15763, '旅行するのが好きです。', 'Ryokō suru no ga suki desu.', NULL, 'Tôi thích đi du lịch.', 6058, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15764, '早起きするのは大変です。', 'Hayaoki suru no wa taihen desu.', NULL, 'Dậy sớm thì vất vả.', 6059, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15765, '日本語を勉強するのは楽しいです。', 'Nihongo o benkyō suru no wa tanoshii desu.', NULL, 'Học tiếng Nhật thì vui.', 6059, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15746, '毎日運動する必要があります。', 'Mainichi undō suru hitsuyō ga arimasu.', NULL, 'Cần phải vận động mỗi ngày.', 6050, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15788, '千円しかありません。', 'Sen en shika arimasen.', NULL, 'Chỉ có nghìn yên.', 6071, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15789, '一人しか来ませんでした。', 'Hitori shika kimasen deshita.', NULL, 'Chỉ có một người đến.', 6071, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15794, '日本の文化について勉強しています。', 'Nihon no bunka ni tsuite benkyō shite imasu.', NULL, 'Tôi đang học về văn hóa Nhật.', 6074, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15795, 'この問題について話しましょう。', 'Kono mondai ni tsuite hanashimashō.', NULL, 'Hãy nói về vấn đề này.', 6074, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15798, '富士山という山が有名です。', 'Fujisan to iu yama ga yūmei desu.', NULL, 'Núi tên là Fuji nổi tiếng.', 6076, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15799, '田中さんという人に会いました。', 'Tanaka-san to iu hito ni aimashita.', NULL, 'Tôi gặp người tên Tanaka.', 6076, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15804, '明日は雪が降るそうです。', 'Ashita wa yuki ga furu sō desu.', NULL, 'Nghe nói mai có tuyết.', 6079, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15805, '彼は結婚したそうです。', 'Kare wa kekkon shita sō desu.', NULL, 'Nghe nói anh ấy đã kết hôn.', 6079, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15806, '雨が降りそうです。', 'Ame ga furisō desu.', NULL, 'Trông có vẻ sắp mưa.', 6080, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15807, 'おいしそうです。', 'Oishisō desu.', NULL, 'Trông có vẻ ngon.', 6080, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15808, '彼は忙しいらしい。', 'Kare wa isogashii rashii.', NULL, 'Hình như anh ấy bận.', 6081, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15809, '試験は難しかったらしい。', 'Shiken wa muzukashikatta rashii.', NULL, 'Hình như bài thi khó.', 6081, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15291, 'さっき昼ごはんを食べたばかりです。', 'Sakki hirugohan o tabeta bakari desu.', NULL, 'Tôi vừa mới ăn trưa xong.', 5822, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15292, '今から出かけるところです。', 'Ima kara dekakeru tokoro desu.', NULL, 'Tôi đang chuẩn bị ra ngoài đây.', 5823, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15293, 'ちょうど今、駅に着いたところです。', 'Chōdo ima, eki ni tsuita tokoro desu.', NULL, 'Tôi vừa mới đến ga xong.', 5823, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15810, '彼は疲れたようだ。', 'Kare wa tsukareta yō da.', NULL, 'Anh ấy dường như mệt.', 6082, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15811, '雨が降るみたいです。', 'Ame ga furu mitai desu.', NULL, 'Dường như sắp mưa.', 6082, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15812, '早く起きれば、間に合います。', 'Hayaku okireba, maniaimasu.', NULL, 'Nếu dậy sớm thì kịp.', 6083, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15813, '安ければ、買います。', 'Yasukereba, kaimasu.', NULL, 'Nếu rẻ thì mua.', 6083, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15820, '一度やってみてください。', 'Ichido yatte mite kudasai.', NULL, 'Hãy thử làm một lần.', 6087, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15821, 'この料理を食べてみました。', 'Kono ryōri o tabete mimashita.', NULL, 'Tôi đã thử ăn món này.', 6087, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15777, '早く起きました。', 'Hayaku okimashita.', NULL, 'Tôi đã dậy sớm.', 6065, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15824, '来年、留学しようと思っています。', 'Rainen, ryūgaku shiyō to omotte imasu.', NULL, 'Tôi định đi du học năm sau.', 6089, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15825, '週末は海に行こうと思っています。', 'Shūmatsu wa umi ni ikō to omotte imasu.', NULL, 'Cuối tuần tôi định đi biển.', 6089, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15826, '毎日運動することにしました。', 'Mainichi undō suru koto ni shimashita.', NULL, 'Tôi quyết định tập thể dục mỗi ngày.', 6090, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15827, 'タバコをやめることにします。', 'Tabako o yameru koto ni shimasu.', NULL, 'Tôi quyết định bỏ thuốc.', 6090, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15294, '天気予報によると、明日は台風が来るそうだ。', 'Tenki yohō ni yoru to, ashita wa taifū ga kuru sō da.', NULL, 'Theo dự báo thời tiết, nghe nói mai bão đến.', 5824, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15295, '田中さんは来月結婚するそうです。', 'Tanaka-san wa raigetsu kekkon suru sō desu.', NULL, 'Nghe nói anh Tanaka tháng sau cưới.', 5824, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15296, 'このケーキ、おいしそうですね。', 'Kono kēki, oishisō desu ne.', NULL, 'Cái bánh này trông ngon nhỉ.', 5825, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15297, '今にも雨が降りそうだ。', 'Ima ni mo ame ga furisō da.', NULL, 'Trời như sắp mưa đến nơi.', 5825, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15298, '電気が消えている。田中さんはもう帰ったようだ。', 'Denki ga kiete iru. Tanaka-san wa mō kaetta yō da.', NULL, 'Đèn tắt rồi. Hình như anh Tanaka đã về.', 5826, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15299, '彼女は疲れているみたいだ。', 'Kanojo wa tsukarete iru mitai da.', NULL, 'Cô ấy trông có vẻ mệt.', 5826, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15300, 'ニュースによると、その事故でけが人はいなかったらしい。', 'Nyūsu ni yoru to, sono jiko de keganin wa inakatta rashii.', NULL, 'Theo tin tức, hình như vụ tai nạn đó không có ai bị thương.', 5827, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15301, '今日の彼はいつもより元気らしい。', 'Kyō no kare wa itsumo yori genki rashii.', NULL, 'Hôm nay anh ấy có vẻ khỏe hơn mọi ngày.', 5827, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15302, '壁に地図が貼ってあります。', 'Kabe ni chizu ga hatte arimasu.', NULL, 'Trên tường có dán bản đồ (ai đó đã dán sẵn).', 5828, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15303, '旅行の準備はもうしてあります。', 'Ryokō no junbi wa mō shite arimasu.', NULL, 'Việc chuẩn bị cho chuyến đi đã làm xong sẵn rồi.', 5828, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15304, '客が来る前に、部屋を掃除しておきます。', 'Kyaku ga kuru mae ni, heya o sōji shite okimasu.', NULL, 'Trước khi khách đến, tôi dọn phòng sẵn.', 5829, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15305, 'その資料はそこに置いておいてください。', 'Sono shiryō wa soko ni oite oite kudasai.', NULL, 'Cứ để tài liệu đó ở đấy giúp tôi.', 5829, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15306, '電車に傘を忘れてしまった。', 'Densha ni kasa o wasurete shimatta.', NULL, 'Tôi lỡ để quên ô trên tàu mất rồi.', 5830, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15307, 'その本は一日で読んでしまいました。', 'Sono hon wa ichinichi de yonde shimaimashita.', NULL, 'Cuốn sách đó tôi đọc hết trong một ngày.', 5830, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15308, 'たまに朝ごはんを食べないことがある。', 'Tama ni asagohan o tabenai koto ga aru.', NULL, 'Thỉnh thoảng tôi cũng có hôm không ăn sáng.', 5831, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15309, '仕事で日本へ行くことがあります。', 'Shigoto de Nihon e iku koto ga arimasu.', NULL, 'Có lúc tôi đi Nhật vì công việc.', 5831, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15310, 'エアコンをつけたまま出かけてしまった。', 'Eakon o tsuketa mama dekakete shimatta.', NULL, 'Tôi ra ngoài mà quên tắt điều hòa.', 5832, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15311, '靴のまま入らないでください。', 'Kutsu no mama hairanaide kudasai.', NULL, 'Xin đừng đi nguyên giày vào.', 5832, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15312, '時間がたつにつれて、痛みは消えていった。', 'Jikan ga tatsu ni tsurete, itami wa kiete itta.', NULL, 'Thời gian trôi qua thì cơn đau cũng dần biến mất.', 5833, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15313, '山を登るにしたがって、気温が下がってきた。', 'Yama o noboru ni shitagatte, kion ga sagatte kita.', NULL, 'Càng lên núi thì nhiệt độ càng giảm.', 5833, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15314, '彼は医者として、また作家としても有名だ。', 'Kare wa isha to shite, mata sakka to shite mo yūmei da.', NULL, 'Anh ấy nổi tiếng với tư cách bác sĩ, và cả nhà văn nữa.', 5834, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15315, '留学生として日本に来ました。', 'Ryūgakusei to shite Nihon ni kimashita.', NULL, 'Tôi đến Nhật với tư cách du học sinh.', 5834, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15316, '弟にケーキを食べられた。', 'Otōto ni kēki o taberareta.', NULL, 'Bị em trai ăn mất cái bánh.', 5835, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15317, 'この寺は300年前に建てられました。', 'Kono tera wa sanbyaku-nen mae ni tateraremashita.', NULL, 'Ngôi chùa này được xây dựng 300 năm trước.', 5835, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15318, '母は妹に部屋を掃除させた。', 'Haha wa imōto ni heya o sōji saseta.', NULL, 'Mẹ bắt em gái dọn phòng.', 5836, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15319, '子どもを公園で遊ばせた。', 'Kodomo o kōen de asobaseta.', NULL, 'Tôi cho bọn trẻ chơi ở công viên.', 5836, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15320, '子どものとき、毎日ピアノを練習させられた。', 'Kodomo no toki, mainichi piano o renshū saserareta.', NULL, 'Hồi nhỏ tôi bị bắt tập piano mỗi ngày.', 5837, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15321, '飲み会で歌を歌わされた。', 'Nomikai de uta o utawasareta.', NULL, 'Ở buổi nhậu tôi bị ép hát.', 5837, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15322, '社長はもうお帰りになりました。', 'Shachō wa mō okaeri ni narimashita.', NULL, 'Giám đốc đã về rồi ạ.', 5838, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15323, '先生はこの本をお読みになりましたか。', 'Sensei wa kono hon o oyomi ni narimashita ka.', NULL, 'Thầy đã đọc cuốn sách này chưa ạ?', 5838, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15324, 'お荷物をお持ちします。', 'Onimotsu o omochi shimasu.', NULL, 'Để tôi xách hành lý giúp ạ.', 5839, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15325, '後ほどこちらからご連絡いたします。', 'Nochihodo kochira kara gorenraku itashimasu.', NULL, 'Lát nữa chúng tôi sẽ liên lạc lại ạ.', 5839, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15326, 'すみません、写真を撮っていただけませんか。', 'Sumimasen, shashin o totte itadakemasen ka.', NULL, 'Xin lỗi, anh/chị chụp ảnh giúp tôi được không ạ?', 5840, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15327, 'もう少し詳しく説明していただけないでしょうか。', 'Mō sukoshi kuwashiku setsumei shite itadakenai deshō ka.', NULL, 'Anh/chị có thể giải thích kỹ hơn một chút được không ạ?', 5840, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15328, '友達が引っ越しを手伝ってくれた。', 'Tomodachi ga hikkoshi o tetsudatte kureta.', NULL, 'Bạn tôi đã giúp tôi chuyển nhà.', 5841, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15329, '先生に作文を直してもらった。', 'Sensei ni sakubun o naoshite moratta.', NULL, 'Tôi được thầy sửa bài văn cho.', 5841, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15330, '君にもっと自信を持ってほしい。', 'Kimi ni motto jishin o motte hoshii.', NULL, 'Tôi muốn cậu tự tin hơn.', 5842, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15331, 'ここではタバコを吸わないでほしい。', 'Koko de wa tabako o suwanaide hoshii.', NULL, 'Tôi mong đừng hút thuốc ở đây.', 5842, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15332, '田中さんに、後で電話するように伝えてください。', 'Tanaka-san ni, ato de denwa suru yō ni tsutaete kudasai.', NULL, 'Nhắn anh Tanaka lát nữa gọi điện giúp tôi nhé.', 5843, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15333, '医者に、お酒を飲まないように言われた。', 'Isha ni, osake o nomanai yō ni iwareta.', NULL, 'Bác sĩ dặn tôi đừng uống rượu.', 5843, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15334, '部長はもう出発されました。', 'Buchō wa mō shuppatsu saremashita.', NULL, 'Trưởng phòng đã khởi hành rồi ạ.', 5844, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15335, '社長はゴルフをされますか。', 'Shachō wa gorufu o saremasu ka.', NULL, 'Giám đốc có chơi golf không ạ?', 5844, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15336, '約束したのに、彼は来なかった。', 'Yakusoku shita noni, kare wa konakatta.', NULL, 'Đã hẹn rồi mà anh ấy không đến.', 5845, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15337, '日曜日なのに、仕事をしなければならない。', 'Nichiyōbi nanoni, shigoto o shinakereba naranai.', NULL, 'Chủ nhật rồi mà vẫn phải đi làm.', 5845, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15338, '知っているくせに、教えてくれない。', 'Shitte iru kuse ni, oshiete kurenai.', NULL, 'Rõ ràng biết mà không chịu chỉ.', 5846, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15339, '子どものくせに、生意気なことを言うな。', 'Kodomo no kuse ni, namaiki na koto o iu na.', NULL, 'Con nít mà bày đặt nói năng hỗn.', 5846, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15340, '彼は英語だけでなく、フランス語も話せる。', 'Kare wa eigo dake de naku, furansugo mo hanaseru.', NULL, 'Anh ấy không chỉ nói được tiếng Anh mà cả tiếng Pháp.', 5847, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15341, 'この店は安いばかりでなく、味もいい。', 'Kono mise wa yasui bakari de naku, aji mo ii.', NULL, 'Quán này không chỉ rẻ mà còn ngon.', 5847, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15342, '3年も日本にいたのか。日本語が上手なわけだ。', 'San-nen mo Nihon ni ita no ka. Nihongo ga jōzu na wake da.', NULL, 'Ở Nhật những 3 năm à. Thảo nào tiếng Nhật giỏi.', 5848, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15343, '窓が開いている。寒いわけだ。', 'Mado ga aite iru. Samui wake da.', NULL, 'Cửa sổ mở kìa. Thảo nào lạnh.', 5848, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15344, '大事な会議だから、休むわけにはいかない。', 'Daiji na kaigi da kara, yasumu wake ni wa ikanai.', NULL, 'Cuộc họp quan trọng nên không thể nghỉ được.', 5849, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15345, '約束したから、行かないわけにはいかない。', 'Yakusoku shita kara, ikanai wake ni wa ikanai.', NULL, 'Đã hứa rồi nên không đi không được.', 5849, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15346, '出かけようとしたところに、電話がかかってきた。', 'Dekakeyō to shita tokoro ni, denwa ga kakatte kita.', NULL, 'Đúng lúc định ra ngoài thì có điện thoại.', 5850, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15347, 'サボっているところを先生に見られた。', 'Sabotte iru tokoro o sensei ni mirareta.', NULL, 'Đang trốn việc thì bị thầy bắt gặp.', 5850, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15348, '水を出しっぱなしにしないで。', 'Mizu o dashippanashi ni shinaide.', NULL, 'Đừng để nước chảy mãi thế.', 5851, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15349, '電車で1時間立ちっぱなしだった。', 'Densha de ichi-jikan tachippanashi datta.', NULL, 'Tôi đứng suốt 1 tiếng trên tàu.', 5851, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15350, '最近、残業が続いて疲れがちだ。', 'Saikin, zangyō ga tsuzuite tsukaregachi da.', NULL, 'Dạo này tăng ca liên tục nên hay mệt.', 5852, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15351, '彼は約束を忘れがちだ。', 'Kare wa yakusoku o wasuregachi da.', NULL, 'Anh ấy hay quên hẹn.', 5852, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15352, 'この色は少し安っぽく見える。', 'Kono iro wa sukoshi yasuppoku mieru.', NULL, 'Màu này trông hơi rẻ tiền.', 5853, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15353, '年を取って、忘れっぽくなった。', 'Toshi o totte, wasureppoku natta.', NULL, 'Có tuổi rồi nên đâm ra hay quên.', 5853, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15354, '物価は上がる一方だ。', 'Bukka wa agaru ippō da.', NULL, 'Vật giá cứ tăng mãi.', 5854, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15355, '田舎の人口は減る一方だ。', 'Inaka no jinkō wa heru ippō da.', NULL, 'Dân số vùng quê ngày càng giảm.', 5854, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15356, '春になると、桜が咲きます。', 'Haru ni naru to, sakura ga sakimasu.', NULL, 'Cứ đến mùa xuân là hoa anh đào nở.', 5855, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15357, '日本へ行くなら、京都がおすすめです。', 'Nihon e iku nara, Kyōto ga osusume desu.', NULL, 'Nếu (định) đi Nhật thì tôi khuyên nên đến Kyoto.', 5855, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15358, 'たとえ雨が降っても、行きます。', 'Tatoe ame ga futte mo, ikimasu.', NULL, 'Cho dù trời mưa tôi cũng đi.', 5856, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15359, 'たとえ高くても、必要なら買う。', 'Tatoe takakute mo, hitsuyō nara kau.', NULL, 'Dù có đắt, nếu cần thì tôi vẫn mua.', 5856, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15360, 'もっと早く出れば、間に合ったのに。', 'Motto hayaku dereba, maniatta noni.', NULL, 'Giá mà ra sớm hơn thì đã kịp rồi.', 5857, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15361, '言ってくれたらよかったのに。', 'Itte kuretara yokatta noni.', NULL, 'Giá mà cậu nói với tớ thì tốt biết mấy.', 5857, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15362, '駅まで歩いて10分くらいです。', 'Eki made aruite juppun kurai desu.', NULL, 'Đi bộ đến ga khoảng 10 phút.', 5858, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15363, '自分の部屋くらい自分で掃除しなさい。', 'Jibun no heya kurai jibun de sōji shinasai.', NULL, 'Ít nhất là phòng của mình thì tự dọn đi.', 5858, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15364, '今日は昨日ほど寒くない。', 'Kyō wa kinō hodo samukunai.', NULL, 'Hôm nay không lạnh bằng hôm qua.', 5859, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15365, '足が痛くて、歩けないほどだ。', 'Ashi ga itakute, arukenai hodo da.', NULL, 'Chân đau đến mức không đi nổi.', 5859, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15366, '弟はゲームをしてばかりいる。', 'Otōto wa gēmu o shite bakari iru.', NULL, 'Em trai tôi cứ chơi game suốt.', 5860, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15367, '文句ばかり言わないで、手伝ってよ。', 'Monku bakari iwanaide, tetsudatte yo.', NULL, 'Đừng có than suốt, phụ tớ đi.', 5860, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15368, '狭いながらも、楽しい我が家だ。', 'Semai nagara mo, tanoshii wagaya da.', NULL, 'Tuy chật nhưng là mái nhà vui vẻ của tôi.', 5861, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15369, '残念ながら、今回は不合格でした。', 'Zannen nagara, konkai wa fugōkaku deshita.', NULL, 'Tiếc là lần này không đỗ.', 5861, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15370, '彼は子どもみたいに泣いた。', 'Kare wa kodomo mitai ni naita.', NULL, 'Anh ấy khóc như một đứa trẻ.', 5862, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15371, 'あなたみたいな人になりたい。', 'Anata mitai na hito ni naritai.', NULL, 'Tôi muốn trở thành người như bạn.', 5862, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15372, 'お金がなくて、旅行しようにもできない。', 'Okane ga nakute, ryokō shiyō ni mo dekinai.', NULL, 'Không có tiền nên muốn đi du lịch cũng không được.', 5863, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15373, '道が混んでいて、急ごうにも急げない。', 'Michi ga konde ite, isogō ni mo isogenai.', NULL, 'Đường tắc nên muốn vội cũng không vội được.', 5863, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15374, '経験からいうと、この方法が一番いい。', 'Keiken kara iu to, kono hōhō ga ichiban ii.', NULL, 'Xét theo kinh nghiệm thì cách này là tốt nhất.', 5864, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15375, '親からみると、子どもはいつまでも子どもだ。', 'Oya kara miru to, kodomo wa itsu made mo kodomo da.', NULL, 'Dưới góc nhìn của cha mẹ, con cái mãi vẫn là con nít.', 5864, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15376, '休みの日は、本を読んだり映画を見たりします。', 'Yasumi no hi wa, hon o yondari eiga o mitari shimasu.', NULL, 'Ngày nghỉ tôi nào là đọc sách nào là xem phim.', 5865, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15377, '値段が上がったり下がったりしている。', 'Nedan ga agattari sagattari shite iru.', NULL, 'Giá cứ lúc lên lúc xuống.', 5865, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15378, 'ドアを開けたとたん、猫が飛び出してきた。', 'Doa o aketa totan, neko ga tobidashite kita.', NULL, 'Vừa mở cửa ra thì con mèo lao vụt ra.', 5866, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15379, '立ち上がったとたんに、めまいがした。', 'Tachiagatta totan ni, memai ga shita.', NULL, 'Vừa đứng dậy thì chóng mặt.', 5866, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15380, 'ベルが鳴るか鳴らないかのうちに、彼は教室を出て行った。', 'Beru ga naru ka naranai ka no uchi ni, kare wa kyōshitsu o dete itta.', NULL, 'Chuông gần như chưa reo anh ấy đã ra khỏi lớp.', 5867, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15381, '横になるかならないかのうちに、眠ってしまった。', 'Yoko ni naru ka naranai ka no uchi ni, nemutte shimatta.', NULL, 'Vừa đặt lưng xuống là ngủ luôn.', 5867, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15382, '赤ちゃんは泣いていたかと思うと、もう笑っている。', 'Akachan wa naite ita ka to omou to, mō waratte iru.', NULL, 'Em bé vừa còn khóc đã cười ngay.', 5868, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15383, '空が暗くなったかと思ったら、大粒の雨が降ってきた。', 'Sora ga kuraku natta ka to omottara, ōtsubu no ame ga futte kita.', NULL, 'Trời vừa tối sầm lại đã đổ mưa hạt to.', 5868, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15384, '彼は家に帰るなり、部屋に閉じこもった。', 'Kare wa ie ni kaeru nari, heya ni tojikomotta.', NULL, 'Vừa về đến nhà là anh ta nhốt mình trong phòng.', 5869, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15385, '知らせを聞くなり、彼女は泣き出した。', 'Shirase o kiku nari, kanojo wa nakidashita.', NULL, 'Vừa nghe tin là cô ấy òa khóc.', 5869, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15386, '彼とは10年前に会ったきり、連絡がない。', 'Kare to wa jū-nen mae ni atta kiri, renraku ga nai.', NULL, 'Gặp anh ấy 10 năm trước rồi từ đó bặt tin.', 5870, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15387, '二人きりで話したい。', 'Futari kiri de hanashitai.', NULL, 'Tôi muốn nói chuyện chỉ hai người thôi.', 5870, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15388, 'ご来店の際は、会員証をお持ちください。', 'Goraiten no sai wa, kaiin-shō o omochi kudasai.', NULL, 'Khi đến cửa hàng, xin mang theo thẻ hội viên.', 5871, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15389, '契約更新の際に、書類が必要です。', 'Keiyaku kōshin no sai ni, shorui ga hitsuyō desu.', NULL, 'Khi gia hạn hợp đồng cần có giấy tờ.', 5871, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15390, '会議は本社において行われます。', 'Kaigi wa honsha ni oite okonawaremasu.', NULL, 'Cuộc họp được tổ chức tại trụ sở chính.', 5872, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15391, '現代社会における情報の役割は大きい。', 'Gendai shakai ni okeru jōhō no yakuwari wa ōkii.', NULL, 'Vai trò của thông tin trong xã hội hiện đại là rất lớn.', 5872, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15392, '日本には、京都をはじめ、歴史的な都市が多い。', 'Nihon ni wa, Kyōto o hajime, rekishi-teki na toshi ga ōi.', NULL, 'Ở Nhật, tiêu biểu như Kyoto, có nhiều thành phố lịch sử.', 5873, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15393, '社長をはじめとして、全社員が式に出席した。', 'Shachō o hajime to shite, zen shain ga shiki ni shusseki shita.', NULL, 'Từ giám đốc trở đi, toàn thể nhân viên dự lễ.', 5873, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15394, '工事は3年にわたって続いた。', 'Kōji wa san-nen ni watatte tsuzuita.', NULL, 'Công trình kéo dài suốt 3 năm.', 5874, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15395, '広い範囲にわたる調査が行われた。', 'Hiroi han''i ni wataru chōsa ga okonawareta.', NULL, 'Một cuộc điều tra trên phạm vi rộng đã được tiến hành.', 5874, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15396, '友人を通じて彼女と知り合った。', 'Yūjin o tsūjite kanojo to shiriatta.', NULL, 'Tôi quen cô ấy qua một người bạn.', 5875, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15397, 'この地方は一年を通して雨が多い。', 'Kono chihō wa ichi-nen o tōshite ame ga ōi.', NULL, 'Vùng này mưa nhiều quanh năm.', 5875, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15398, 'この映画は実話に基づいて作られた。', 'Kono eiga wa jitsuwa ni motozuite tsukurareta.', NULL, 'Bộ phim này được làm dựa trên chuyện có thật.', 5876, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15399, '規則に基づいて処理します。', 'Kisoku ni motozuite shori shimasu.', NULL, 'Chúng tôi xử lý căn cứ theo quy định.', 5876, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15400, '収入に応じて税金を払う。', 'Shūnyū ni ōjite zeikin o harau.', NULL, 'Nộp thuế tùy theo thu nhập.', 5877, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15401, 'お客様のご要望に応じたサービスを提供します。', 'Okyakusama no goyōbō ni ōjita sābisu o teikyō shimasu.', NULL, 'Chúng tôi cung cấp dịch vụ theo yêu cầu của khách.', 5877, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15402, '私にとって家族が一番大切だ。', 'Watashi ni totte kazoku ga ichiban taisetsu da.', NULL, 'Đối với tôi, gia đình là quan trọng nhất.', 5878, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15403, '外国人にとって漢字は難しい。', 'Gaikokujin ni totte kanji wa muzukashii.', NULL, 'Với người nước ngoài, chữ Hán rất khó.', 5878, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15404, '料理にかけては、彼の右に出る者はいない。', 'Ryōri ni kakete wa, kare no migi ni deru mono wa inai.', NULL, 'Về nấu ăn thì không ai qua được anh ấy.', 5879, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15405, '記憶力にかけては自信がある。', 'Kioku-ryoku ni kakete wa jishin ga aru.', NULL, 'Về trí nhớ thì tôi tự tin.', 5879, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15406, '目上の人に対して失礼な態度を取ってはいけない。', 'Meue no hito ni taishite shitsurei na taido o totte wa ikenai.', NULL, 'Không được có thái độ vô lễ với người trên.', 5880, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15407, '兄は文系なのに対して、弟は理系だ。', 'Ani wa bunkei na no ni taishite, otōto wa rikei da.', NULL, 'Anh học khối xã hội, còn em thì học khối tự nhiên.', 5880, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15408, '遺産をめぐって兄弟が争っている。', 'Isan o megutte kyōdai ga arasotte iru.', NULL, 'Anh em tranh chấp nhau vì di sản.', 5881, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15409, '新しい制度をめぐる議論が続いている。', 'Atarashii seido o meguru giron ga tsuzuite iru.', NULL, 'Cuộc tranh luận xoay quanh chế độ mới vẫn tiếp diễn.', 5881, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15410, 'この歌を聞くにつけ、故郷を思い出す。', 'Kono uta o kiku ni tsuke, kokyō o omoidasu.', NULL, 'Mỗi lần nghe bài này là tôi lại nhớ quê.', 5882, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15411, '何かにつけて彼は文句を言う。', 'Nani ka ni tsukete kare wa monku o iu.', NULL, 'Hễ có chuyện gì là anh ta lại than phiền.', 5882, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15412, 'あの様子からすると、試験はうまくいかなかったようだ。', 'Ano yōsu kara suru to, shiken wa umaku ikanakatta yō da.', NULL, 'Nhìn bộ dạng đó thì có vẻ thi không tốt.', 5883, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15413, '経験からいって、この計画は難しい。', 'Keiken kara itte, kono keikaku wa muzukashii.', NULL, 'Theo kinh nghiệm thì kế hoạch này khó.', 5883, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15414, '工事中につき、通行止めです。', 'Kōji-chū ni tsuki, tsūkōdome desu.', NULL, 'Do đang thi công nên cấm lưu thông.', 5884, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15415, 'お一人様につき、二つまでです。', 'Ohitorisama ni tsuki, futatsu made desu.', NULL, 'Mỗi người tối đa hai phần.', 5884, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15416, '田中教授のもとで研究している。', 'Tanaka kyōju no moto de kenkyū shite iru.', NULL, 'Tôi đang nghiên cứu dưới sự hướng dẫn của giáo sư Tanaka.', 5885, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15417, '親の同意のもとに契約した。', 'Oya no dōi no moto ni keiyaku shita.', NULL, 'Tôi ký hợp đồng với sự đồng ý của bố mẹ.', 5885, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15418, '台風のため、旅行を中止せざるを得なかった。', 'Taifū no tame, ryokō o chūshi sezaru o enakatta.', NULL, 'Vì bão nên buộc phải hủy chuyến đi.', 5886, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15419, '証拠がある以上、認めざるを得ない。', 'Shōko ga aru ijō, mitomezaru o enai.', NULL, 'Đã có bằng chứng thì không thể không thừa nhận.', 5886, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15420, '終電がないから、歩いて帰るよりほかない。', 'Shūden ga nai kara, aruite kaeru yori hoka nai.', NULL, 'Hết tàu cuối rồi nên chỉ còn cách đi bộ về.', 5887, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15421, 'こうなったら、あきらめるほかはない。', 'Kō nattara, akirameru hoka wa nai.', NULL, 'Đến nước này thì chỉ còn cách từ bỏ.', 5887, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15422, '実際に見てみないことには、何とも言えない。', 'Jissai ni mite minai koto ni wa, nantomo ienai.', NULL, 'Chưa tận mắt xem thì chưa thể nói gì.', 5888, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15423, '健康でないことには、いい仕事はできない。', 'Kenkō de nai koto ni wa, ii shigoto wa dekinai.', NULL, 'Không khỏe mạnh thì không làm việc tốt được.', 5888, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15424, '貯金どころか、借金がある。', 'Chokin dokoro ka, shakkin ga aru.', NULL, 'Nói gì tiết kiệm, tôi còn đang nợ.', 5889, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15425, '謝るどころか、彼は怒り出した。', 'Ayamaru dokoro ka, kare wa okoridashita.', NULL, 'Không những không xin lỗi, anh ta còn nổi cáu.', 5889, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15426, 'あんなに練習したんだから、負けるわけがない。', 'Anna ni renshū shita n da kara, makeru wake ga nai.', NULL, 'Luyện tập đến thế thì không thể thua được.', 5890, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15427, '彼がそんなうそをつくはずがない。', 'Kare ga sonna uso o tsuku hazu ga nai.', NULL, 'Anh ấy làm gì có chuyện nói dối như vậy.', 5890, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15428, '電気がついている。誰か家にいるに違いない。', 'Denki ga tsuite iru. Dare ka ie ni iru ni chigainai.', NULL, 'Đèn đang bật. Chắc chắn có người ở nhà.', 5891, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15429, 'これだけ売れているのだから、いい商品に違いない。', 'Kore dake urete iru no da kara, ii shōhin ni chigainai.', NULL, 'Bán chạy thế này thì chắc chắn là hàng tốt.', 5891, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15430, 'それは言い訳にすぎない。', 'Sore wa iiwake ni suginai.', NULL, 'Cái đó chẳng qua chỉ là lời bào chữa.', 5892, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15431, '私は事実を述べたにすぎない。', 'Watashi wa jijitsu o nobeta ni suginai.', NULL, 'Tôi chỉ nêu sự thật mà thôi.', 5892, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15432, '成功したのは努力の結果にほかならない。', 'Seikō shita no wa doryoku no kekka ni hoka naranai.', NULL, 'Thành công chính là kết quả của nỗ lực chứ không gì khác.', 5893, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15433, 'これは彼の責任にほかならない。', 'Kore wa kare no sekinin ni hoka naranai.', NULL, 'Đây chính là trách nhiệm của anh ta.', 5893, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15434, '20キロからあるスーツケースを運んだ。', 'Nijukkiro kara aru sūtsukēsu o hakonda.', NULL, 'Tôi khiêng cái vali nặng tới 20 cân.', 5894, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15435, '会場には1万人からの人が集まった。', 'Kaijō ni wa ichiman-nin kara no hito ga atsumatta.', NULL, 'Có tới cả vạn người tụ họp ở hội trường.', 5894, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15436, '料理ができると言っても、卵焼きぐらいだ。', 'Ryōri ga dekiru to itte mo, tamagoyaki gurai da.', NULL, 'Nói là biết nấu ăn chứ chỉ mỗi trứng chiên thôi.', 5895, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15437, '旅行と言っても、日帰りです。', 'Ryokō to itte mo, higaeri desu.', NULL, 'Gọi là đi du lịch chứ đi về trong ngày.', 5895, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15438, '引き受けたからには、最後までやる。', 'Hikiuketa kara ni wa, saigo made yaru.', NULL, 'Đã nhận rồi thì làm đến cùng.', 5896, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15439, '留学する以上は、その国の言葉を身につけたい。', 'Ryūgaku suru ijō wa, sono kuni no kotoba o mi ni tsuketai.', NULL, 'Đã đi du học thì muốn thạo ngôn ngữ nước đó.', 5896, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15440, '今から急いだところで、間に合わない。', 'Ima kara isoida tokoro de, ma ni awanai.', NULL, 'Giờ có vội cũng không kịp.', 5897, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15441, '謝ったところで、許してもらえないだろう。', 'Ayamatta tokoro de, yurushite moraenai darō.', NULL, 'Có xin lỗi thì chắc cũng không được tha.', 5897, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15442, '行くにしろ行かないにしろ、早く決めてください。', 'Iku ni shiro ikanai ni shiro, hayaku kimete kudasai.', NULL, 'Dù đi hay không thì cũng quyết định nhanh giúp.', 5898, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15443, '冗談にせよ、そんなことを言うべきではない。', 'Jōdan ni seyo, sonna koto o iu beki de wa nai.', NULL, 'Cho dù là đùa thì cũng không nên nói vậy.', 5898, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15444, 'この店は値段のわりにおいしい。', 'Kono mise wa nedan no wari ni oishii.', NULL, 'Quán này so với giá thì ngon đấy.', 5899, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15445, '彼は年のわりに若く見える。', 'Kare wa toshi no wari ni wakaku mieru.', NULL, 'Anh ấy trông trẻ hơn so với tuổi.', 5899, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15446, '約束は守るべきだ。', 'Yakusoku wa mamoru beki da.', NULL, 'Đã hứa thì nên giữ lời.', 5900, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15447, '人の悪口を言うべきではない。', 'Hito no waruguchi o iu beki de wa nai.', NULL, 'Không nên nói xấu người khác.', 5900, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15448, '家族を失うことほど悲しいことはない。', 'Kazoku o ushinau koto hodo kanashii koto wa nai.', NULL, 'Không gì buồn bằng mất đi người thân.', 5901, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15449, '今日ぐらい暑い日はない。', 'Kyō gurai atsui hi wa nai.', NULL, 'Không có ngày nào nóng như hôm nay.', 5901, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15450, 'さんざん迷ったあげく、何も買わなかった。', 'Sanzan mayotta ageku, nani mo kawanakatta.', NULL, 'Phân vân mãi, cuối cùng chẳng mua gì.', 5902, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15451, '口論のあげく、彼は部屋を出て行った。', 'Kōron no ageku, kare wa heya o dete itta.', NULL, 'Sau một hồi cãi vã, anh ta bỏ ra khỏi phòng.', 5902, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15452, 'よく考えた末に、留学を決めた。', 'Yoku kangaeta sue ni, ryūgaku o kimeta.', NULL, 'Sau khi suy nghĩ kỹ, tôi quyết định đi du học.', 5903, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15453, '長い交渉の末、契約が成立した。', 'Nagai kōshō no sue, keiyaku ga seiritsu shita.', NULL, 'Sau đàm phán dài, hợp đồng đã được ký kết.', 5903, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15456, 'あんな店には二度と行くまい。', 'Anna mise ni wa nido to iku mai.', NULL, 'Tôi sẽ không bao giờ đến quán đó nữa.', 5905, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15457, '彼はもう来ないのではあるまいか。', 'Kare wa mō konai no de wa aru mai ka.', NULL, 'Chẳng lẽ anh ấy sẽ không đến nữa sao?', 5905, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15458, 'この薬は頭痛のみならず、肩こりにも効く。', 'Kono kusuri wa zutsū nomi narazu, katakori ni mo kiku.', NULL, 'Thuốc này không chỉ trị đau đầu mà còn trị mỏi vai.', 5906, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15459, '国内のみならず、海外でも有名だ。', 'Kokunai nomi narazu, kaigai de mo yūmei da.', NULL, 'Không chỉ trong nước mà ở nước ngoài cũng nổi tiếng.', 5906, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15460, '彼は英語はもちろん、中国語も話せる。', 'Kare wa eigo wa mochiron, chūgokugo mo hanaseru.', NULL, 'Anh ấy tiếng Anh khỏi nói, tiếng Trung cũng nói được.', 5907, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15461, '準備不足はもとより、当日の天候も悪かった。', 'Junbi busoku wa motoyori, tōjitsu no tenkō mo warukatta.', NULL, 'Chuẩn bị thiếu đã đành, thời tiết hôm đó cũng xấu.', 5907, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15462, '内容をよく確認した上で、サインしてください。', 'Naiyō o yoku kakunin shita ue de, sain shite kudasai.', NULL, 'Sau khi kiểm tra kỹ nội dung rồi hãy ký.', 5908, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15463, '家族と相談の上で、お返事します。', 'Kazoku to sōdan no ue de, ohenji shimasu.', NULL, 'Tôi sẽ trả lời sau khi bàn với gia đình.', 5908, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15464, 'この部屋は狭い上に、日当たりも悪い。', 'Kono heya wa semai ue ni, hiatari mo warui.', NULL, 'Phòng này vừa chật lại vừa thiếu nắng.', 5909, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15465, '彼女は美人な上に頭もいい。', 'Kanojo wa bijin na ue ni atama mo ii.', NULL, 'Cô ấy vừa xinh lại vừa thông minh.', 5909, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15466, '彼は一日も休むことなく働き続けた。', 'Kare wa ichinichi mo yasumu koto naku hataraki tsuzuketa.', NULL, 'Anh ấy làm việc không nghỉ một ngày nào.', 5910, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15467, '最後まであきらめることなく戦った。', 'Saigo made akirameru koto naku tatakatta.', NULL, 'Đã chiến đấu đến cùng mà không hề bỏ cuộc.', 5910, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15468, 'よく話し合った結果、留学を延期することにした。', 'Yoku hanashiatta kekka, ryūgaku o enki suru koto ni shita.', NULL, 'Sau khi bàn kỹ, chúng tôi quyết định hoãn du học.', 5911, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15469, '調査の結果、原因が明らかになった。', 'Chōsa no kekka, gen''in ga akiraka ni natta.', NULL, 'Kết quả điều tra đã làm rõ nguyên nhân.', 5911, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15470, '緊張のあまり、声が出なかった。', 'Kinchō no amari, koe ga denakatta.', NULL, 'Vì quá hồi hộp nên không thốt nên lời.', 5912, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15471, '働きすぎたあまり、体を壊した。', 'Hatarakisugita amari, karada o kowashita.', NULL, 'Vì làm việc quá sức nên đổ bệnh.', 5912, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15472, '電話番号がわからないので、連絡しようがない。', 'Denwa bangō ga wakaranai node, renraku shiyō ga nai.', NULL, 'Không biết số điện thoại nên không có cách nào liên lạc.', 5913, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15473, 'こうなってはもうどうしようもない。', 'Kō natte wa mō dō shiyō mo nai.', NULL, 'Đến nước này thì hết cách rồi.', 5913, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15474, '読みかけの本が机の上にある。', 'Yomikake no hon ga tsukue no ue ni aru.', NULL, 'Trên bàn có cuốn sách đang đọc dở.', 5914, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15475, '彼は何か言いかけて、やめた。', 'Kare wa nani ka iikakete, yameta.', NULL, 'Anh ấy định nói gì đó rồi lại thôi.', 5914, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15476, '若いころは、よく徹夜したものだ。', 'Wakai koro wa, yoku tetsuya shita mono da.', NULL, 'Hồi trẻ tôi hay thức trắng đêm lắm.', 5915, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15477, '人の悪口を言うものではない。', 'Hito no waruguchi o iu mono de wa nai.', NULL, 'Không nên nói xấu người khác.', 5915, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15478, '本日をもって、当店は閉店いたします。', 'Honjitsu o motte, tōten wa heiten itashimasu.', NULL, 'Kể từ hôm nay, cửa hàng chúng tôi đóng cửa.', 5916, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15479, '成功は努力をもってのみ得られる。', 'Seikō wa doryoku o motte nomi erareru.', NULL, 'Thành công chỉ có được bằng nỗ lực.', 5916, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15480, '親の心配をよそに、彼は世界一周の旅に出た。', 'Oya no shinpai o yoso ni, kare wa sekai isshū no tabi ni deta.', NULL, 'Bất chấp nỗi lo của bố mẹ, anh ấy lên đường vòng quanh thế giới.', 5917, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15481, '住民の反対をよそに、工事が始まった。', 'Jūmin no hantai o yoso ni, kōji ga hajimatta.', NULL, 'Phớt lờ sự phản đối của dân, công trình vẫn khởi công.', 5917, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15482, 'この仕事を任せられるのは、彼をおいてほかにいない。', 'Kono shigoto o makaserareru no wa, kare o oite hoka ni inai.', NULL, 'Người có thể giao việc này thì ngoài anh ấy ra không còn ai.', 5918, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15483, '今をおいて、チャンスはない。', 'Ima o oite, chansu wa nai.', NULL, 'Ngoài lúc này ra thì không còn cơ hội nào.', 5918, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15484, '政治家たる者、国民の声に耳を傾けるべきだ。', 'Seijika taru mono, kokumin no koe ni mimi o katamukeru beki da.', NULL, 'Đã là chính trị gia thì phải lắng nghe tiếng nói của dân.', 5919, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15485, '指導者たる者が、そんな弱音を吐いてはいけない。', 'Shidōsha taru mono ga, sonna yowane o haite wa ikenai.', NULL, 'Người lãnh đạo thì không được thốt ra lời yếu đuối như thế.', 5919, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15486, 'これはこの町ならではの味だ。', 'Kore wa kono machi naradewa no aji da.', NULL, 'Đây là hương vị chỉ riêng thị trấn này mới có.', 5920, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15487, 'プロならではの技術に驚いた。', 'Puro naradewa no gijutsu ni odoroita.', NULL, 'Tôi kinh ngạc trước kỹ thuật chỉ dân chuyên nghiệp mới có.', 5920, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15488, 'そんな難しい問題、わかりっこないよ。', 'Sonna muzukashii mondai, wakarikkonai yo.', NULL, 'Bài khó thế thì làm sao mà hiểu được.', 5921, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15489, '今から行っても間に合いっこない。', 'Ima kara itte mo maniaikkonai.', NULL, 'Giờ đi thì không đời nào kịp.', 5921, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15490, '毎日同じ作業の繰り返しで、退屈といったらない。', 'Mainichi onaji sagyō no kurikaeshi de, taikutsu to ittara nai.', NULL, 'Ngày nào cũng lặp lại công việc y hệt, chán không tả nổi.', 5922, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15491, '初めて富士山を見たときの感動といったらなかった。', 'Hajimete Fujisan o mita toki no kandō to ittara nakatta.', NULL, 'Nỗi xúc động khi lần đầu thấy núi Phú Sĩ thật khó tả.', 5922, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15492, '彼にお金を貸したが最後、返ってこない。', 'Kare ni okane o kashita ga saigo, kaette konai.', NULL, 'Một khi đã cho anh ta mượn tiền là không đòi lại được.', 5923, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15493, 'この秘密を知られたら最後、私の立場はない。', 'Kono himitsu o shirararetara saigo, watashi no tachiba wa nai.', NULL, 'Bí mật này mà bị lộ thì tôi hết đường.', 5923, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15494, '今年はいいことずくめの一年だった。', 'Kotoshi wa ii koto zukume no ichinen datta.', NULL, 'Năm nay là một năm toàn chuyện tốt.', 5924, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15495, '黒ずくめの服装の男が立っていた。', 'Kuro zukume no fukusō no otoko ga tatte ita.', NULL, 'Một người đàn ông ăn mặc toàn đồ đen đứng đó.', 5924, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15496, '忙しくて、昼ご飯を食べそびれた。', 'Isogashikute, hirugohan o tabesobireta.', NULL, 'Bận quá nên lỡ mất bữa trưa.', 5925, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15497, 'お礼を言いそびれてしまった。', 'Orei o iisobirete shimatta.', NULL, 'Tôi lỡ mất dịp nói lời cảm ơn.', 5925, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15498, 'ベルが鳴るが早いか、生徒たちは教室を飛び出した。', 'Beru ga naru ga hayai ka, seito-tachi wa kyōshitsu o tobidashita.', NULL, 'Chuông vừa reo là học sinh lao ra khỏi lớp.', 5926, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15499, '横になるが早いか、いびきをかき始めた。', 'Yoko ni naru ga hayai ka, ibiki o kakihajimeta.', NULL, 'Vừa nằm xuống là bắt đầu ngáy.', 5926, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15500, '片付けるそばから、子どもが散らかす。', 'Katazukeru soba kara, kodomo ga chirakasu.', NULL, 'Vừa dọn xong là bọn trẻ lại bày bừa.', 5927, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15501, '習うそばから忘れてしまう。', 'Narau soba kara wasurete shimau.', NULL, 'Vừa học xong đã quên ngay.', 5927, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15502, 'どんな理由であれ、暴力は許されない。', 'Donna riyū de are, bōryoku wa yurusarenai.', NULL, 'Dù lý do gì đi nữa, bạo lực là không thể chấp nhận.', 5928, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15503, 'たとえ子どもであれ、責任は取るべきだ。', 'Tatoe kodomo de are, sekinin wa toru beki da.', NULL, 'Cho dù là trẻ con thì cũng phải chịu trách nhiệm.', 5928, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15504, '君が信じようが信じまいが、これは事実だ。', 'Kimi ga shinjiyō ga shinjimai ga, kore wa jijitsu da.', NULL, 'Cậu tin hay không thì đây vẫn là sự thật.', 5929, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15505, '雨が降ろうが、試合は行われる。', 'Ame ga furō ga, shiai wa okonawareru.', NULL, 'Dù có mưa thì trận đấu vẫn diễn ra.', 5929, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15506, '結果いかんによっては、計画を見直す必要がある。', 'Kekka ikan ni yotte wa, keikaku o minaosu hitsuyō ga aru.', NULL, 'Tùy vào kết quả mà có thể phải xem lại kế hoạch.', 5930, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15507, '理由のいかんにかかわらず、遅刻は認めない。', 'Riyū no ikan ni kakawarazu, chikoku wa mitomenai.', NULL, 'Bất kể lý do gì, đi muộn là không chấp nhận.', 5930, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15508, '条件によっては、引き受けないものでもない。', 'Jōken ni yotte wa, hikiukenai mono demo nai.', NULL, 'Tùy điều kiện, cũng không phải là không nhận.', 5931, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15509, '彼の気持ちもわからなくもない。', 'Kare no kimochi mo wakaranaku mo nai.', NULL, 'Tâm trạng của anh ấy tôi cũng không phải không hiểu.', 5931, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15510, 'それは教師にあるまじき行為だ。', 'Sore wa kyōshi ni aru majiki kōi da.', NULL, 'Đó là hành vi không thể chấp nhận ở một giáo viên.', 5932, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15511, '許すまじき犯罪だ。', 'Yurusu majiki hanzai da.', NULL, 'Đây là tội ác không thể dung thứ.', 5932, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15512, 'お金がないと困るが、あればあったで使ってしまう。', 'Okane ga nai to komaru ga, areba atta de tsukatte shimau.', NULL, 'Không tiền thì khổ, mà có tiền thì lại tiêu hết.', 5933, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15513, '暇なら暇で、何をすればいいか困る。', 'Hima nara hima de, nani o sureba ii ka komaru.', NULL, 'Rảnh thì lại chẳng biết làm gì cho hết.', 5933, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15514, '真相を明らかにせずにはおかない。', 'Shinsō o akiraka ni sezu ni wa okanai.', NULL, 'Nhất định phải làm rõ sự thật cho bằng được.', 5934, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16544, 'ははは おとうとに へやを そうじさせました。', 'haha wa otouto ni heya o souji sasemashita.', NULL, 'Mẹ bắt em trai dọn phòng.', 6449, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15515, 'この映画は見る者を感動させずにはおかない。', 'Kono eiga wa miru mono o kandō sasezu ni wa okanai.', NULL, 'Bộ phim này chắc chắn khiến người xem xúc động.', 5934, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15516, 'これだけ迷惑をかけたのだから、謝らないでは済まない。', 'Kore dake meiwaku o kaketa no da kara, ayamaranai de wa sumanai.', NULL, 'Gây phiền hà đến mức này thì không xin lỗi không xong.', 5935, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15517, '弁償せずには済まないだろう。', 'Benshō sezu ni wa sumanai darō.', NULL, 'Chắc là không bồi thường thì không xong đâu.', 5935, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15518, 'その件については、私では判断しかねます。', 'Sono ken ni tsuite wa, watashi de wa handan shikanemasu.', NULL, 'Về việc đó, tôi khó mà tự quyết định được.', 5936, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15519, 'そんな無理をすると、体を壊しかねない。', 'Sonna muri o suru to, karada o kowashikanenai.', NULL, 'Làm quá sức thế thì có nguy cơ đổ bệnh.', 5936, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15520, '連休とあって、どの観光地も混んでいる。', 'Renkyū to atte, dono kankōchi mo konde iru.', NULL, 'Vì là kỳ nghỉ dài nên khu du lịch nào cũng đông.', 5937, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15521, '有名歌手が来るとあって、会場は満員だ。', 'Yūmei kashu ga kuru to atte, kaijō wa man''in da.', NULL, 'Vì có ca sĩ nổi tiếng đến nên hội trường chật kín.', 5937, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15522, '春とはいえ、まだ朝晩は冷える。', 'Haru to wa ie, mada asaban wa hieru.', NULL, 'Tuy là mùa xuân nhưng sáng tối vẫn lạnh.', 5938, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15523, '仕事とはいえ、休日まで働くのはつらい。', 'Shigoto to wa ie, kyūjitsu made hataraku no wa tsurai.', NULL, 'Dù là công việc nhưng làm cả ngày nghỉ thì mệt.', 5938, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15524, '二人の走者は抜きつ抜かれつの接戦を演じた。', 'Futari no sōsha wa nukitsu nukaretsu no sessen o enjita.', NULL, 'Hai vận động viên rượt đuổi nhau sát nút, khi vượt khi bị vượt.', 5939, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15525, '人は互いに持ちつ持たれつで生きている。', 'Hito wa tagai ni mochitsu motaretsu de ikite iru.', NULL, 'Con người sống nương tựa, giúp đỡ lẫn nhau.', 5939, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15526, '色といいデザインといい、この服は気に入った。', 'Iro to ii dezain to ii, kono fuku wa ki ni itta.', NULL, 'Cả màu lẫn kiểu dáng, bộ đồ này tôi đều ưng.', 5940, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15527, '味といい量といい、この店は満足だ。', 'Aji to ii ryō to ii, kono mise wa manzoku da.', NULL, 'Cả vị lẫn lượng, quán này tôi đều hài lòng.', 5940, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15528, '一度ならまだしも、三度も遅刻するとは。', 'Ichido nara madashimo, sando mo chikoku suru to wa.', NULL, 'Một lần thì còn được, đằng này muộn tận ba lần.', 5941, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15529, '子どもならまだしも、大人がそんなことを言うなんて。', 'Kodomo nara madashimo, otona ga sonna koto o iu nante.', NULL, 'Trẻ con thì còn được, người lớn mà nói thế à.', 5941, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15531, '一人で悩んだところで、解決しない。', 'Hitori de nayanda tokoro de, kaiketsu shinai.', NULL, 'Một mình ôm phiền muộn thì cũng không giải quyết được.', 5942, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15532, '出張にかこつけて、観光を楽しんだ。', 'Shutchō ni kakotsukete, kankō o tanoshinda.', NULL, 'Mượn cớ đi công tác để đi chơi.', 5943, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15533, '病気にかこつけて、集まりを欠席した。', 'Byōki ni kakotsukete, atsumari o kesseki shita.', NULL, 'Viện cớ ốm để vắng mặt buổi họp mặt.', 5943, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15534, 'インターネットで、家に居ながらにして買い物ができる。', 'Intānetto de, ie ni inagara ni shite kaimono ga dekiru.', NULL, 'Nhờ Internet, ngồi ở nhà vẫn mua sắm được.', 5944, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15535, '彼女は涙ながらに当時のことを語った。', 'Kanojo wa namida nagara ni tōji no koto o katatta.', NULL, 'Cô ấy vừa khóc vừa kể lại chuyện hồi đó.', 5944, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15536, '経験が浅いゆえに、判断を誤った。', 'Keiken ga asai yue ni, handan o ayamatta.', NULL, 'Vì thiếu kinh nghiệm nên đã phán đoán sai.', 5945, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15537, '若さゆえの過ちだった。', 'Wakasa yue no ayamachi datta.', NULL, 'Đó là lỗi lầm do sự trẻ người non dạ.', 5945, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15538, '両社は合併するに至った。', 'Ryōsha wa gappei suru ni itatta.', NULL, 'Hai công ty đã đi đến chỗ sáp nhập.', 5946, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15539, '事故が起きるに至って、ようやく対策が取られた。', 'Jiko ga okiru ni itatte, yōyaku taisaku ga torareta.', NULL, 'Mãi đến khi xảy ra tai nạn mới có biện pháp.', 5946, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15540, '被害は一地域にとどまらず、全国に広がった。', 'Higai wa ichi chiiki ni todomarazu, zenkoku ni hirogatta.', NULL, 'Thiệt hại không dừng ở một vùng mà lan ra cả nước.', 5947, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15541, '彼の関心は音楽にとどまらず、美術にも及ぶ。', 'Kare no kanshin wa ongaku ni todomarazu, bijutsu ni mo oyobu.', NULL, 'Mối quan tâm của anh ấy không chỉ ở âm nhạc mà cả mỹ thuật.', 5947, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15542, '悪天候をものともせず、登山を続けた。', 'Akutenkō o mono to mo sezu, tozan o tsuzuketa.', NULL, 'Bất chấp thời tiết xấu, họ vẫn tiếp tục leo núi.', 5948, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15543, '周囲の批判をものともせず、彼は信念を貫いた。', 'Shūi no hihan o mono to mo sezu, kare wa shinnen o tsuranuita.', NULL, 'Bất chấp chỉ trích xung quanh, anh giữ vững niềm tin.', 5948, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15544, '経験の有無を問わず、応募できます。', 'Keiken no umu o towazu, ōbo dekimasu.', NULL, 'Có kinh nghiệm hay không đều có thể ứng tuyển.', 5949, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15545, '理由のいかんによらず、返金はできません。', 'Riyū no ikan ni yorazu, henkin wa dekimasen.', NULL, 'Bất kể lý do gì cũng không hoàn tiền.', 5949, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15548, '彼の思い切った決断ぶりに感心した。', 'Kare no omoikitta ketsudan buri ni kanshin shita.', NULL, 'Tôi khâm phục cách anh ấy ra quyết định dứt khoát.', 5951, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15549, '十年ぶりに故郷に帰った。', 'Jū-nen buri ni kokyō ni kaetta.', NULL, 'Sau 10 năm tôi mới về quê.', 5951, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15550, '遺族の悲しみは想像にかたくない。', 'Izoku no kanashimi wa sōzō ni katakunai.', NULL, 'Không khó để hình dung nỗi đau của thân nhân.', 5952, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15551, '当時の苦労は察するにかたくない。', 'Tōji no kurō wa sassuru ni katakunai.', NULL, 'Không khó để thấu hiểu nỗi vất vả khi đó.', 5952, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15552, 'できると言った手前、今さらやめられない。', 'Dekiru to itta temae, imasara yamerarenai.', NULL, 'Đã trót nói là làm được nên giờ không bỏ được.', 5953, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15553, '後輩の前で失敗した手前、格好がつかない。', 'Kōhai no mae de shippai shita temae, kakkō ga tsukanai.', NULL, 'Trót thất bại trước mặt đàn em nên mất mặt.', 5953, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15554, 'どんなに貯金しても、病気になればそれまでだ。', 'Donna ni chokin shite mo, byōki ni nareba sore made da.', NULL, 'Có để dành bao nhiêu, đổ bệnh một cái là hết.', 5954, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15555, '規則だと言われればそれまでだ。', 'Kisoku da to iwarereba sore made da.', NULL, 'Người ta bảo đó là quy định thì cũng chịu.', 5954, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16545, 'こどもを こうえんで あそばせました。', 'kodomo o kouen de asobasemashita.', NULL, 'Tôi cho con chơi ở công viên.', 6449, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15556, 'あの映画を見ると、泣かずにはいられない。', 'Ano eiga o miru to, nakazu ni wa irarenai.', NULL, 'Xem bộ phim đó là không cầm được nước mắt.', 5955, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15557, '彼の勇気に感心せずにはいられなかった。', 'Kare no yūki ni kanshin sezu ni wa irarenakatta.', NULL, 'Tôi không thể không khâm phục lòng dũng cảm của anh ấy.', 5955, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15828, '夜、遅くまで起きていることがあります。', 'Yoru, osoku made okite iru koto ga arimasu.', NULL, 'Đôi khi tôi thức khuya.', 6091, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15829, '映画を見に行くことがあります。', 'Eiga o mi ni iku koto ga arimasu.', NULL, 'Đôi khi tôi đi xem phim.', 6091, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15830, 'もっと野菜を食べたほうがいいです。', 'Motto yasai o tabeta hō ga ii desu.', NULL, 'Nên ăn nhiều rau hơn.', 6092, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15831, '早く寝たほうがいい。', 'Hayaku neta hō ga ii.', NULL, 'Nên ngủ sớm.', 6092, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15832, '大学を卒業したら、働くつもりです。', 'Daigaku o sotsugyō shitara, hataraku tsumori desu.', NULL, 'Sau khi tốt nghiệp đại học tôi dự định làm việc.', 6093, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15833, '来月、引っ越すつもりです。', 'Raigetsu, hikkosu tsumori desu.', NULL, 'Tháng sau tôi dự định chuyển nhà.', 6093, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15834, 'この本は読みやすいです。', 'Kono hon wa yomiyasui desu.', NULL, 'Sách này dễ đọc.', 6094, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15835, 'この字は覚えにくい。', 'Kono ji wa oboenikui.', NULL, 'Chữ này khó nhớ.', 6094, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15836, '音楽を聞きながら、勉強します。', 'Ongaku o kikinagara, benkyō shimasu.', NULL, 'Vừa nghe nhạc vừa học.', 6095, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15837, '歩きながら、電話しました。', 'Arukinagara, denwa shimashita.', NULL, 'Vừa đi bộ vừa gọi điện.', 6095, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15838, '健康のために、運動しています。', 'Kenkō no tame ni, undō shite imasu.', NULL, 'Vì sức khỏe tôi tập thể dục.', 6096, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15839, '試験に合格するために、勉強します。', 'Shiken ni gōkaku suru tame ni, benkyō shimasu.', NULL, 'Để thi đỗ tôi học.', 6096, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15840, '彼が来るかどうか、わかりません。', 'Kare ga kuru ka dō ka, wakarimasen.', NULL, 'Không biết anh ấy có đến không.', 6097, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15841, 'この方法が正しいかどうか確認します。', 'Kono hōhō ga tadashii ka dō ka kakunin shimasu.', NULL, 'Kiểm tra xem cách này đúng không.', 6097, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15842, '先生がお話しになりました。', 'Sensei ga ohanashi ni narimashita.', NULL, 'Thầy đã nói (kính ngữ).', 6098, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15843, '社長がお見えになりました。', 'Shachō ga omie ni narimashita.', NULL, 'Giám đốc đã đến (kính ngữ).', 6098, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15852, '上司に残業させられました。', 'Jōshi ni zangyō saseraremashita.', NULL, 'Bị sếp bắt làm thêm giờ.', 6103, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15853, '毎日、運動させられています。', 'Mainichi, undō saserarete imasu.', NULL, 'Mỗi ngày bị bắt tập thể dục.', 6103, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15858, 'だんだん暖かくなってきました。', 'Dandan atatakaku natte kimashita.', NULL, 'Dần ấm lên.', 6106, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15859, 'これから忙しくなっていきます。', 'Kore kara isogashiku natte ikimasu.', NULL, 'Từ giờ sẽ bận dần.', 6106, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15866, 'この書類に署名してください。', 'Kono shorui ni shomei shite kudasai.', NULL, 'Hãy ký vào giấy tờ này.', 6110, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15867, 'もう少し待ってください。', 'Mō sukoshi matte kudasai.', NULL, 'Hãy đợi thêm chút.', 6110, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15870, '富士山に登ったことがあります。', 'Fujisan ni nobotta koto ga arimasu.', NULL, 'Tôi đã từng leo Fuji.', 6112, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15871, '一度も行ったことがない。', 'Ichido mo itta koto ga nai.', NULL, 'Chưa từng đi lần nào.', 6112, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15872, 'もっと勉強すればよかった。', 'Motto benkyō sureba yokatta.', NULL, 'Đáng lẽ nên học nhiều hơn.', 6113, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15873, '傘を持って行けばよかった。', 'Kasa o motte ikeba yokatta.', NULL, 'Đáng lẽ nên mang ô.', 6113, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15882, '約束は守るべきだ。', 'Yakusoku wa mamoru beki da.', NULL, 'Nên giữ lời hứa.', 6118, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15883, 'もっと環境を考えるべきです。', 'Motto kankyō o kangaeru beki desu.', NULL, 'Nên quan tâm môi trường hơn.', 6118, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15886, '嫌いなわけではありません。', 'Kirai na wake dewa arimasen.', NULL, 'Không hẳn là ghét.', 6120, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15887, '行きたくないわけではない。', 'Ikitakunai wake dewa nai.', NULL, 'Không phải là không muốn đi.', 6120, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15888, 'そんなことがあるわけがない。', 'Sonna koto ga aru wake ga nai.', NULL, 'Không thể có chuyện đó.', 6121, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15889, '彼が嘘をつくわけがない。', 'Kare ga uso o tsuku wake ga nai.', NULL, 'Anh ấy không thể nói dối.', 6121, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15894, '高いけれど、買いました。', 'Takai keredo, kaimashita.', NULL, 'Tuy đắt nhưng đã mua.', 6124, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15895, '行きたいけど、時間がない。', 'Ikitai kedo, jikan ga nai.', NULL, 'Muốn đi nhưng không có thời gian.', 6124, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15900, '暇だったら、手伝ってください。', 'Hima dattara, tetsudatte kudasai.', NULL, 'Nếu rảnh hãy giúp.', 6127, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15901, '着いたら、電話してください。', 'Tsuitara, denwa shite kudasai.', NULL, 'Khi đến hãy gọi điện.', 6127, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15902, '何を言っても、聞いてくれない。', 'Nani o itte mo, kiite kurenai.', NULL, 'Dù nói gì cũng không nghe.', 6128, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15903, '何回行っても、覚えられない。', 'Nankai itte mo, oboerarenai.', NULL, 'Dù đi bao lần cũng không nhớ.', 6128, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15911, '子供が泣き出した。', 'Kodomo ga nakidashita.', NULL, 'Đứa trẻ bắt đầu khóc.', 6132, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15912, '三時間走り続けました。', 'Sanjikan hashiritsuzukemashita.', NULL, 'Chạy liên tục ba tiếng.', 6133, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15913, '勉強し続けてください。', 'Benkyō shitsuzukete kudasai.', NULL, 'Hãy tiếp tục học.', 6133, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15914, '書き直してください。', 'Kakinaoshite kudasai.', NULL, 'Hãy viết lại.', 6134, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15915, '考え直す必要がある。', 'Kangaenaosu hitsuyō ga aru.', NULL, 'Cần suy nghĩ lại.', 6134, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15916, '本を読み切りました。', 'Hon o yomikirimashita.', NULL, 'Đọc hết sách.', 6135, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15917, '使い切ってください。', 'Tsukaikitte kudasai.', NULL, 'Hãy dùng hết.', 6135, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15918, '食べ切れませんでした。', 'Tabekiremasen deshita.', NULL, 'Không ăn hết được.', 6136, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15922, 'お客様に対して丁寧に対応します。', 'Okyakusama ni taishite teinei ni taiō shimasu.', NULL, 'Đối xử lịch sự với khách.', 6138, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15923, '子供に対して厳しすぎる。', 'Kodomo ni taishite kibishisugiru.', NULL, 'Quá nghiêm với trẻ.', 6138, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15924, '私にとって家族が一番大切です。', 'Watashi ni totte kazoku ga ichiban taisetsu desu.', NULL, 'Đối với tôi gia đình quan trọng nhất.', 6139, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15925, '彼にとっては問題ない。', 'Kare ni totte wa mondai nai.', NULL, 'Đối với anh ấy không sao.', 6139, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15930, '環境問題について考えましょう。', 'Kankyō mondai ni tsuite kangaemashō.', NULL, 'Hãy suy nghĩ về vấn đề môi trường.', 6142, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15932, 'この件に関して質問があります。', 'Kono ken ni kanshite shitsumon ga arimasu.', NULL, 'Có câu hỏi liên quan việc này.', 6143, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15933, '契約に関して相談したい。', 'Keiyaku ni kanshite sōdan shitai.', NULL, 'Muốn trao đổi về hợp đồng.', 6143, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15934, 'バスの代わりに、電車で行きます。', 'Basu no kawari ni, densha de ikimasu.', NULL, 'Thay vì xe buýt đi bằng tàu.', 6144, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15935, '彼の代わりに行きます。', 'Kare no kawari ni ikimasu.', NULL, 'Tôi đi thay anh ấy.', 6144, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15936, '到着次第、連絡します。', 'Tōchaku shidai, renraku shimasu.', NULL, 'Ngay khi đến sẽ liên lạc.', 6145, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15937, '準備ができ次第、始めます。', 'Junbi ga dekishidai, hajimemasu.', NULL, 'Chuẩn bị xong sẽ bắt đầu.', 6145, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15938, 'この料理の作り方を教えてください。', 'Kono ryōri no tsukurikata o oshiete kudasai.', NULL, 'Hãy dạy cách nấu món này.', 6146, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15939, '使い方がわかりません。', 'Tsukaikata ga wakarimasen.', NULL, 'Không biết cách dùng.', 6146, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15942, '子供が公園に行きたがっています。', 'Kodomo ga kōen ni ikitagatte imasu.', NULL, 'Con muốn đi công viên.', 6148, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15943, '彼女は新しい服を買いたがっている。', 'Kanojo wa atarashii fuku o kaitagatte iru.', NULL, 'Cô ấy muốn mua quần áo mới.', 6148, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15944, '雨は降りそうにない。', 'Ame wa furisō ni nai.', NULL, 'Không có vẻ sẽ mưa.', 6149, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15945, '成功しそうにない。', 'Seikō shisō ni nai.', NULL, 'Không có vẻ sẽ thành công.', 6149, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15946, 'ドアを開けっぱなしにしないで。', 'Doa o akeppanashi ni shinaide.', NULL, 'Đừng để cửa mở mãi.', 6150, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15947, 'テレビをつけっぱなしで寝た。', 'Terebi o tsukeppanashi de neta.', NULL, 'Ngủ quên bật TV.', 6150, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15948, 'ゲームをやりまくった。', 'Gēmu o yarimakutta.', NULL, 'Chơi game suốt.', 6151, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15949, '文句を言いまくる。', 'Monku o iimakuru.', NULL, 'Cằn nhằn suốt.', 6151, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15950, '食事の最中に電話が鳴った。', 'Shokuji no saichū ni denwa ga natta.', NULL, 'Ngay lúc đang ăn chuông reo.', 6152, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15952, '若いうちに、たくさん旅行したほうがいい。', 'Wakai uchi ni, takusan ryokō shita hō ga ii.', NULL, 'Nên đi du lịch nhiều khi còn trẻ.', 6153, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15953, '明るいうちに帰りましょう。', 'Akarui uchi ni kaerimashō.', NULL, 'Về khi còn sáng.', 6153, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15954, 'シャワーを浴びているあいだに、配達が来た。', 'Shawā o abite iru aida ni, haitatsu ga kita.', NULL, 'Lúc đang tắm thì giao hàng đến.', 6154, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15955, '出かけているあいだに、盗まれた。', 'Dekakete iru aida ni, nusumareta.', NULL, 'Lúc ra ngoài thì bị trộm.', 6154, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15956, '先生のおかげで、合格できました。', 'Sensei no okage de, gōkaku dekimashita.', NULL, 'Nhờ thầy mà đỗ.', 6155, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15957, '天気のおかげで、楽しめた。', 'Tenki no okage de, tanoshimeta.', NULL, 'Nhờ thời tiết đẹp mà vui.', 6155, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15958, '寝坊したせいで、遅刻した。', 'Nebō shita sei de, chikoku shita.', NULL, 'Vì ngủ quên mà đi trễ.', 6156, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15960, '知っているくせに、教えてくれない。', 'Shitte iru kuse ni, oshiete kurenai.', NULL, 'Biết mà không chịu dạy.', 6157, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15961, '約束したくせに、来ない。', 'Yakusoku shita kuse ni, konai.', NULL, 'Hứa rồi mà không đến.', 6157, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15979, '昔はよくこの店に来たものだ。', 'Mukashi wa yoku kono mise ni kita mono da.', NULL, 'Ngày xưa hay ghé quán này.', 6166, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15980, '人の悪口を言うものではない。', 'Hito no waruguchi o iu mono dewa nai.', NULL, 'Không nên nói xấu người khác.', 6167, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15981, 'そんなに無理をするものではありません。', 'Sonna ni muri o suru mono dewa arimasen.', NULL, 'Không nên gượng như vậy.', 6167, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15984, 'もっと睡眠をとることだ。', 'Motto suimin o toru koto da.', NULL, 'Nên ngủ đủ.', 6169, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15985, '一度専門家に相談することだ。', 'Ichido senmonka ni sōdan suru koto da.', NULL, 'Nên hỏi chuyên gia một lần.', 6169, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15988, '心配することはありません。', 'Shinpai suru koto wa arimasen.', NULL, 'Không cần lo.', 6171, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15989, 'そんなに怒ることはない。', 'Sonna ni okoru koto wa nai.', NULL, 'Không cần tức như vậy.', 6171, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15995, '彼が嘘をつくわけがない。', 'Kare ga uso o tsuku wake ga nai.', NULL, 'Anh ấy không thể nói dối.', 6174, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15998, '行きたくないわけではない。', 'Ikitakunai wake dewa nai.', NULL, 'Không phải là không muốn đi.', 6176, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15999, '反対するわけではありません。', 'Hantai suru wake dewa arimasen.', NULL, 'Không hẳn là phản đối.', 6176, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16000, '高いからといって美味しいとは限らない。', 'Takai kara to itte oishii to wa kagiranai.', NULL, 'Đắt chưa chắc ngon.', 6177, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16001, '努力すれば必ず成功するとは限らない。', 'Doryoku sureba kanarazu seikō suru to wa kagiranai.', NULL, 'Cố gắng chưa chắc thành công.', 6177, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16005, '便利な一方で、ストレスも増えた。', 'Benri na ippō de, sutoresu mo fueta.', NULL, 'Tiện lợi nhưng stress cũng tăng.', 6179, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16006, '会議の最中に停電した。', 'Kaigi no saichū ni teiden shita.', NULL, 'Giữa cuộc họp mất điện.', 6180, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16007, '食事の最中に知らせが来た。', 'Shokuji no saichū ni shirase ga kita.', NULL, 'Đang ăn thì có tin.', 6180, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16008, 'お越しいただいた際に、資料をお渡しします。', 'Okoshi itadaita sai ni, shiryō o owatashi shimasu.', NULL, 'Khi quý vị đến tôi sẽ giao tài liệu.', 6181, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16011, '明るいうちに帰ろう。', 'Akarui uchi ni kaerō.', NULL, 'Về khi còn sáng.', 6182, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16012, 'この歌を聞くたびに、故郷を思い出す。', 'Kono uta o kiku tabi ni, kokyō o omoidasu.', NULL, 'Mỗi lần nghe bài này nhớ quê.', 6183, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16013, '会うたびに元気そうだ。', 'Au tabi ni genki sō da.', NULL, 'Mỗi lần gặp trông đều khỏe.', 6183, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16014, '読みかけの本がある。', 'Yomikake no hon ga aru.', NULL, 'Có sách đọc dở.', 6184, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16015, '書きかけのレポートを仕上げた。', 'Kakikake no repōto o shiageta.', NULL, 'Hoàn thành báo cáo viết dở.', 6184, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16016, 'そんな高い山、登りっこない。', 'Sonna takai yama, noborikkonai.', NULL, 'Núi cao thế không leo nổi.', 6185, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16017, '勝てっこない。', 'Kattekkonai.', NULL, 'Không thể thắng.', 6185, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16021, '賛成しかねる点もある。', 'Sansei shikaneru ten mo aru.', NULL, 'Cũng có điểm khó đồng ý.', 6187, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16022, 'このままでは事故を起こしかねない。', 'Kono mama dewa jiko o okoshikanenai.', NULL, 'Cứ thế này có thể gây tai nạn.', 6188, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16024, '全部食べきった。', 'Zenbu tabekitta.', NULL, 'Ăn hết sạch.', 6189, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16025, '信じきれない。', 'Shinjikirenai.', NULL, 'Không thể tin hết.', 6189, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16029, '考え抜いて決めた。', 'Kangaenuite kimeta.', NULL, 'Suy nghĩ kỹ rồi quyết định.', 6191, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16030, '助け合いましょう。', 'Tasukeaimashō.', NULL, 'Hãy giúp nhau.', 6192, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16032, '書き直す時間がない。', 'Kakinaosu jikan ga nai.', NULL, 'Không có thời gian viết lại.', 6193, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16033, 'やり直したい。', 'Yarinaoshitai.', NULL, 'Muốn làm lại.', 6193, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16038, '雨が降り始めた。', 'Ame ga furihajimeta.', NULL, 'Trời bắt đầu mưa.', 6196, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16039, '彼女は泣き始めた。', 'Kanojo wa nakihajimeta.', NULL, 'Cô ấy bắt đầu khóc.', 6196, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16043, '彼が来ないに決まっている。', 'Kare ga konai ni kimatte iru.', NULL, 'Chắc chắn anh ấy không đến.', 6198, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16044, '安いものが悪いとも限らない。', 'Yasui mono ga warui to mo kagiranai.', NULL, 'Đồ rẻ chưa chắc xấu.', 6199, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16045, '経験があれば成功するとも限らない。', 'Keiken ga areba seikō suru to mo kagiranai.', NULL, 'Có kinh nghiệm chưa chắc thành công.', 6199, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16052, '見ただけで判断するのは早計だ。', 'Mita dake de handan suru no wa sōkei da.', NULL, 'Chỉ nhìn mà phán đoán là vội.', 6203, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16053, '待っているだけでは解決しない。', 'Matte iru dake dewa kaiketsu shinai.', NULL, 'Chỉ chờ thì không giải quyết được.', 6203, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16056, '準備から実行に至るまで、すべて確認した。', 'Junbi kara jikkō ni itaru made, subete kakunin shita.', NULL, 'Từ chuẩn bị đến thực hiện đều đã kiểm tra.', 6205, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16062, '開店に際して、セールを行う。', 'Kaiten ni saishite, sēru o okonau.', NULL, 'Nhân dịp khai trương sẽ giảm giá.', 6208, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16063, '卒業に際して、感謝の言葉を述べた。', 'Sotsugyō ni saishite, kansha no kotoba o nobeta.', NULL, 'Nhân dịp tốt nghiệp đã bày tỏ lòng biết ơn.', 6208, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16066, '方針に沿って進める。', 'Hōshin ni sotte susumeru.', NULL, 'Tiến hành theo phương châm.', 6210, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16023, '信頼を失いかねない。', 'Shinrai o ushinaikanenai.', NULL, 'Có thể mất lòng tin.', 6188, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16067, '川に沿って道が続いている。', 'Kawa ni sotte michi ga tsuzuite iru.', NULL, 'Đường chạy dọc theo sông.', 6210, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16070, '経済成長に伴って、生活水準も上がった。', 'Keizai seichō ni tomonatte, seikatsu suijun mo agatta.', NULL, 'Cùng tăng trưởng kinh tế, mức sống cũng lên.', 6212, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16071, '制度変更に伴い、手続きも変わる。', 'Seido henkō ni tomonai, tetsuzuki mo kawaru.', NULL, 'Theo thay đổi chế độ, thủ tục cũng đổi.', 6212, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16079, '同情を禁じ得ない状況だ。', 'Dōjō o kinjienai jōkyō da.', NULL, 'Tình huống không thể không thương cảm.', 6216, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16086, '東京公演を皮切りに、全国ツアーが始まる。', 'Tōkyō kōen o kawakiri ni, zenkoku tsuā ga hajimaru.', NULL, 'Bắt đầu từ Tokyo, tour toàn quốc khởi động.', 6220, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16087, 'この商品を皮切りに、新ラインを展開する。', 'Kono shōhin o kawakiri ni, shin rain o tenkai suru.', NULL, 'Bắt đầu từ sản phẩm này mở rộng dòng mới.', 6220, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16090, '事故を契機に、安全対策が強化された。', 'Jiko o keiki ni, anzen taisaku ga kyōka sareta.', NULL, 'Nhân tai nạn biện pháp an toàn được tăng cường.', 6222, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16091, '出産を契機に、仕事の見直しをした。', 'Shussan o keiki ni, shigoto no minaoshi o shita.', NULL, 'Nhân sinh con xem lại công việc.', 6222, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16102, '再会できて嬉しい限りだ。', 'Saikai dekite ureshii kagiri da.', NULL, 'Gặp lại được vô cùng vui.', 6228, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16108, '立入禁止。関係者以外入るべからず。', 'Tachiiri kinshi. Kankeisha igai hairu bekarazu.', NULL, 'Cấm vào. Người không liên quan không được vào.', 6231, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16109, '他人を見下すべからず。', 'Tajin o mikudasu bekarazu.', NULL, 'Không được coi thường người khác.', 6231, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16110, '成功すべく、日夜努力している。', 'Seikō subeku, nichiya doryoku shite iru.', NULL, 'Để thành công ngày đêm nỗ lực.', 6232, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16111, '問題を解決すべく、調査を開始した。', 'Mondai o kaiketsu subeku, chōsa o kaishi shita.', NULL, 'Để giải quyết vấn đề bắt đầu điều tra.', 6232, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16112, '許すべからざる行為だ。', 'Yurusu bekarazaru kōi da.', NULL, 'Hành vi không thể tha thứ.', 6233, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16118, '値上げせざるを得ない状況だ。', 'Neage sezaru o enai jōkyō da.', NULL, 'Tình huống buộc phải tăng giá.', 6236, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16119, '認めざるを得ない。', 'Mitomezaru o enai.', NULL, 'Buộc phải thừa nhận.', 6236, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16124, '会いたくてたまらない。', 'Aitakute tamaranai.', NULL, 'Nhớ muốn gặp không chịu nổi.', 6239, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16125, '暑くてたまらない。', 'Atsukute tamaranai.', NULL, 'Nóng không chịu nổi.', 6239, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16126, '結果が気になってならない。', 'Kekka ga ki ni natte naranai.', NULL, 'Rất lo kết quả.', 6240, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16128, '眠くて仕方がない。', 'Nemukute shikata ga nai.', NULL, 'Buồn ngủ vô cùng.', 6241, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16129, '嬉しくて仕方がない。', 'Ureshikute shikata ga nai.', NULL, 'Vui vô cùng.', 6241, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16130, '努力すれば成功して当然だ。', 'Doryoku sureba seikō shite tōzen da.', NULL, 'Cố gắng thì thành công là đương nhiên.', 6242, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16131, '約束を破れば、信用を失って当然だ。', 'Yakusoku o yabureba, shinyō o ushinatte tōzen da.', NULL, 'Phá lời hứa mất lòng tin là đương nhiên.', 6242, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16138, '結婚してからというもの、生活が変わった。', 'Kekkon shite kara to iu mono, seikatsu ga kawatta.', NULL, 'Kể từ khi cưới cuộc sống thay đổi.', 6246, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16140, '留学して以来、考え方が変わった。', 'Ryūgaku shite irai, kangaekata ga kawatta.', NULL, 'Kể từ du học cách nghĩ thay đổi.', 6247, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16142, '確認してからでないと、進められない。', 'Kakunin shite kara denai to, susumerarenai.', NULL, 'Phải xác nhận trước mới tiến hành được.', 6248, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16143, '許可を得てからでないと、使用できない。', 'Kyoka o ete kara denai to, shiyō dekinai.', NULL, 'Phải được phép trước mới dùng được.', 6248, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16146, '健康があってこそ、幸せだ。', 'Kenkō ga atte koso, shiawase da.', NULL, 'Chỉ khi có sức khỏe mới hạnh phúc.', 6250, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16147, '努力してこそ、成果が出る。', 'Doryoku shite koso, seika ga deru.', NULL, 'Chỉ khi nỗ lực mới có thành quả.', 6250, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16149, 'そんなことを言っては、誤解される。', 'Sonna koto o itte wa, gokai sareru.', NULL, 'Nói vậy sẽ bị hiểu lầm.', 6251, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16152, '約束を破ってはならない。', 'Yakusoku o yabutte wa naranai.', NULL, 'Không được phá lời hứa.', 6253, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16153, '人を見下してはならない。', 'Hito o mikudashite wa naranai.', NULL, 'Không được coi thường người khác.', 6253, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16160, '謝って済むことではない。', 'Ayamatte sumu koto dewa nai.', NULL, 'Không phải xin lỗi là xong.', 6257, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16161, '説明して済む問題ではない。', 'Setsumei shite sumu mondai dewa nai.', NULL, 'Không phải giải thích là giải quyết được.', 6257, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16162, 'メールして済ませた。', 'Mēru shite sumaseta.', NULL, 'Nhắn mail là xong.', 6258, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16163, '謝れば済む話だ。', 'Ayamareba sumu hanashi da.', NULL, 'Xin lỗi là xong chuyện.', 6258, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16166, '成功は努力の結果にほかならない。', 'Seikō wa doryoku no kekka ni hoka naranai.', NULL, 'Thành công không gì khác ngoài kết quả nỗ lực.', 6260, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16167, 'それは偶然にほかならない。', 'Sore wa gūzen ni hoka naranai.', NULL, 'Đó không gì khác ngoài ngẫu nhiên.', 6260, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16170, '噂にすぎない。', 'Uwasa ni suginai.', NULL, 'Chỉ là tin đồn.', 6262, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16171, '彼の意見は参考程度にすぎない。', 'Kare no iken wa sankō teido ni suginai.', NULL, 'Ý kiến anh ấy chỉ mang tính tham khảo.', 6262, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16175, '計画通りに進んでいるに相違ない。', 'Keikaku dōri ni susunde iru ni sōi nai.', NULL, 'Chắc chắn đang tiến đúng kế hoạch.', 6264, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16186, '行くにせよ行かないにせよ、連絡してほしい。', 'Iku ni seyo ikanai ni seyo, renraku shite hoshii.', NULL, 'Dù đi hay không hãy liên lạc.', 6270, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16187, '賛成にしろ反対にしろ、意見を聞きたい。', 'Sansei ni shiro hantai ni shiro, iken o kikitai.', NULL, 'Dù đồng ý hay phản đối tôi muốn nghe ý kiến.', 6270, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16214, 'わたしは がくせいです。', 'watashi wa gakusei desu.', NULL, 'Tôi là học sinh.', 6284, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16215, 'これは にほんごの ほんです。', 'kore wa nihongo no hon desu.', NULL, 'Đây là sách tiếng Nhật.', 6284, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16216, 'わたしは せんせいじゃありません。', 'watashi wa sensei ja arimasen.', NULL, 'Tôi không phải là giáo viên.', 6285, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16217, 'あれは わたしの かさではありません。', 'are wa watashi no kasa de wa arimasen.', NULL, 'Cái kia không phải ô của tôi.', 6285, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16218, 'たなかさんは かいしゃいんですか。', 'tanaka-san wa kaishain desu ka.', NULL, 'Anh Tanaka là nhân viên công ty phải không?', 6286, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16219, 'これは あなたの ですか。', 'kore wa anata no desu ka.', NULL, 'Cái này là của bạn phải không?', 6286, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16220, 'わたしも ベトナムじんです。', 'watashi mo betonamujin desu.', NULL, 'Tôi cũng là người Việt Nam.', 6287, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16221, 'コーヒーも のみます。', 'koohii mo nomimasu.', NULL, 'Tôi cũng uống cà phê.', 6287, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16222, 'これは わたしの かばんです。', 'kore wa watashi no kaban desu.', NULL, 'Đây là cặp của tôi.', 6288, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16223, 'にほんの くるまは たかいです。', 'nihon no kuruma wa takai desu.', NULL, 'Xe ô tô của Nhật thì đắt.', 6288, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16224, 'それは なんですか。', 'sore wa nan desu ka.', NULL, 'Cái đó là cái gì?', 6289, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16225, 'この とけいは いくらですか。', 'kono tokei wa ikura desu ka.', NULL, 'Cái đồng hồ này bao nhiêu tiền?', 6289, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16226, 'まいあさ パンを たべます。', 'maiasa pan o tabemasu.', NULL, 'Sáng nào tôi cũng ăn bánh mì.', 6290, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16227, 'テレビを みます。', 'terebi o mimasu.', NULL, 'Tôi xem tivi.', 6290, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16228, 'としょかんで べんきょうします。', 'toshokan de benkyou shimasu.', NULL, 'Tôi học ở thư viện.', 6291, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16229, 'どこで ひるごはんを たべますか。', 'doko de hirugohan o tabemasu ka.', NULL, 'Bạn ăn trưa ở đâu?', 6291, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16230, 'バスで がっこうへ いきます。', 'basu de gakkou e ikimasu.', NULL, 'Tôi đi đến trường bằng xe buýt.', 6292, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16231, 'はしで ごはんを たべます。', 'hashi de gohan o tabemasu.', NULL, 'Tôi ăn cơm bằng đũa.', 6292, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16232, 'ともだちと えいがを みました。', 'tomodachi to eiga o mimashita.', NULL, 'Tôi đã xem phim cùng bạn.', 6293, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16233, 'かぞくと きょうとへ いきます。', 'kazoku to kyouto e ikimasu.', NULL, 'Tôi đi Kyoto cùng gia đình.', 6293, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16234, 'パンと たまごを かいました。', 'pan to tamago o kaimashita.', NULL, 'Tôi đã mua bánh mì và trứng.', 6294, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16235, 'つくえの うえに ほんや ノートなどが あります。', 'tsukue no ue ni hon ya nooto nado ga arimasu.', NULL, 'Trên bàn có sách, vở v.v.', 6294, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16236, 'あの ひとは だれですか。', 'ano hito wa dare desu ka.', NULL, 'Người kia là ai?', 6295, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16237, 'たんじょうびは いつですか。', 'tanjoubi wa itsu desu ka.', NULL, 'Sinh nhật bạn là khi nào?', 6295, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16238, 'へやに テレビが あります。', 'heya ni terebi ga arimasu.', NULL, 'Trong phòng có tivi.', 6296, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16239, 'あした テストが あります。', 'ashita tesuto ga arimasu.', NULL, 'Ngày mai có bài kiểm tra.', 6296, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16240, 'にわに ねこが います。', 'niwa ni neko ga imasu.', NULL, 'Trong vườn có con mèo.', 6297, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16241, 'わたしは きょうだいが ふたり います。', 'watashi wa kyoudai ga futari imasu.', NULL, 'Tôi có hai anh chị em.', 6297, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16242, 'えきの まえに ぎんこうが あります。', 'eki no mae ni ginkou ga arimasu.', NULL, 'Trước nhà ga có ngân hàng.', 6298, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16243, 'きょうしつに がくせいが います。', 'kyoushitsu ni gakusei ga imasu.', NULL, 'Trong lớp học có học sinh.', 6298, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16244, 'トイレは どこに ありますか。', 'toire wa doko ni arimasu ka.', NULL, 'Nhà vệ sinh ở đâu?', 6299, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16245, 'ははは だいどころに います。', 'haha wa daidokoro ni imasu.', NULL, 'Mẹ tôi ở trong bếp.', 6299, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16246, 'かぎは つくえの したに あります。', 'kagi wa tsukue no shita ni arimasu.', NULL, 'Chìa khóa ở dưới bàn.', 6300, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16247, 'ゆうびんきょくは びょういんの となりです。', 'yuubinkyoku wa byouin no tonari desu.', NULL, 'Bưu điện ở cạnh bệnh viện.', 6300, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16248, 'ここは しょくどうです。', 'koko wa shokudou desu.', NULL, 'Đây là nhà ăn.', 6301, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16249, 'エレベーターは あそこです。', 'erebeetaa wa asoko desu.', NULL, 'Thang máy ở đằng kia.', 6301, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16250, 'まいにち にほんごを べんきょうします。', 'mainichi nihongo o benkyou shimasu.', NULL, 'Hằng ngày tôi học tiếng Nhật.', 6302, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16251, 'にちようびは はたらきません。', 'nichiyoubi wa hatarakimasen.', NULL, 'Chủ nhật tôi không làm việc.', 6302, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16252, 'きのう てがみを かきました。', 'kinou tegami o kakimashita.', NULL, 'Hôm qua tôi đã viết thư.', 6303, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16253, 'けさ あさごはんを たべませんでした。', 'kesa asagohan o tabemasendeshita.', NULL, 'Sáng nay tôi đã không ăn sáng.', 6303, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16254, 'らいしゅう とうきょうへ いきます。', 'raishuu toukyou e ikimasu.', NULL, 'Tuần sau tôi đi Tokyo.', 6304, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16255, 'なんじに うちへ かえりますか。', 'nanji ni uchi e kaerimasu ka.', NULL, 'Mấy giờ bạn về nhà?', 6304, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16256, 'いま あめが ふって います。', 'ima ame ga futte imasu.', NULL, 'Bây giờ trời đang mưa.', 6305, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16257, 'おとうとは へやで ねて います。', 'otouto wa heya de nete imasu.', NULL, 'Em trai đang ngủ trong phòng.', 6305, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16258, 'あねは けっこんして います。', 'ane wa kekkon shite imasu.', NULL, 'Chị tôi đã kết hôn.', 6306, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16259, 'ちちは ぎんこうで はたらいて います。', 'chichi wa ginkou de hataraite imasu.', NULL, 'Bố tôi làm việc ở ngân hàng.', 6306, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16260, 'ふじさんに のぼった ことが あります。', 'fujisan ni nobotta koto ga arimasu.', NULL, 'Tôi đã từng leo núi Phú Sĩ.', 6307, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16261, 'すしを たべた ことが ありますか。', 'sushi o tabeta koto ga arimasu ka.', NULL, 'Bạn đã từng ăn sushi chưa?', 6307, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16262, 'わたしは ピアノを ひく ことが できます。', 'watashi wa piano o hiku koto ga dekimasu.', NULL, 'Tôi có thể chơi piano.', 6308, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16263, 'ここで カードで はらう ことが できますか。', 'koko de kaado de harau koto ga dekimasu ka.', NULL, 'Ở đây có thể trả bằng thẻ không?', 6308, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16264, 'リンさんは にほんごが よく わかります。', 'rin-san wa nihongo ga yoku wakarimasu.', NULL, 'Chị Linh hiểu tiếng Nhật rất rõ.', 6309, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16265, 'わたしは サッカーが すきです。', 'watashi wa sakkaa ga suki desu.', NULL, 'Tôi thích bóng đá.', 6309, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16266, 'はるに なりました。', 'haru ni narimashita.', NULL, 'Đã sang xuân rồi.', 6310, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16267, 'だんだん さむく なります。', 'dandan samuku narimasu.', NULL, 'Trời dần dần lạnh đi.', 6310, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16268, 'この りんごは おいしいです。', 'kono ringo wa oishii desu.', NULL, 'Quả táo này ngon.', 6311, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16269, 'この まちは しずかです。', 'kono machi wa shizuka desu.', NULL, 'Thị trấn này yên tĩnh.', 6311, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16270, 'きのうは あつかったです。', 'kinou wa atsukatta desu.', NULL, 'Hôm qua trời nóng.', 6312, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16271, 'パーティーは にぎやかでした。', 'paatii wa nigiyaka deshita.', NULL, 'Bữa tiệc rất náo nhiệt.', 6312, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16272, 'あかい かばんを かいました。', 'akai kaban o kaimashita.', NULL, 'Tôi đã mua cái cặp màu đỏ.', 6313, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16273, 'きれいな こうえんですね。', 'kirei na kouen desu ne.', NULL, 'Công viên đẹp nhỉ.', 6313, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16274, 'この えいがは とても おもしろいです。', 'kono eiga wa totemo omoshiroi desu.', NULL, 'Bộ phim này rất hay.', 6314, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16275, 'きょうは あまり さむくないです。', 'kyou wa amari samukunai desu.', NULL, 'Hôm nay không lạnh lắm.', 6314, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16276, 'でんしゃは バスより はやいです。', 'densha wa basu yori hayai desu.', NULL, 'Tàu điện nhanh hơn xe buýt.', 6315, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16277, 'きょうは きのうより あたたかいです。', 'kyou wa kinou yori atatakai desu.', NULL, 'Hôm nay ấm hơn hôm qua.', 6315, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16278, 'いぬと ねこと どちらが すきですか。', 'inu to neko to dochira ga suki desu ka.', NULL, 'Chó và mèo, bạn thích con nào hơn?', 6316, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16279, 'ねこの ほうが すきです。', 'neko no hou ga suki desu.', NULL, 'Tôi thích mèo hơn.', 6316, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16280, 'くだものの なかで いちごが いちばん すきです。', 'kudamono no naka de ichigo ga ichiban suki desu.', NULL, 'Trong các loại quả, tôi thích dâu nhất.', 6317, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16281, 'クラスで だれが いちばん せが たかいですか。', 'kurasu de dare ga ichiban se ga takai desu ka.', NULL, 'Trong lớp ai cao nhất?', 6317, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16282, 'この へやは ひろくて あかるいです。', 'kono heya wa hirokute akarui desu.', NULL, 'Căn phòng này rộng và sáng.', 6318, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16283, 'やまださんは しんせつで おもしろい ひとです。', 'yamada-san wa shinsetsu de omoshiroi hito desu.', NULL, 'Anh Yamada là người tốt bụng và thú vị.', 6318, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16284, 'あたらしい パソコンが ほしいです。', 'atarashii pasokon ga hoshii desu.', NULL, 'Tôi muốn có máy tính mới.', 6319, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16285, 'いま なにが いちばん ほしいですか。', 'ima nani ga ichiban hoshii desu ka.', NULL, 'Bây giờ bạn muốn có gì nhất?', 6319, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16286, 'にほんへ いきたいです。', 'nihon e ikitai desu.', NULL, 'Tôi muốn đi Nhật.', 6320, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16287, 'つめたい みずが のみたいです。', 'tsumetai mizu ga nomitai desu.', NULL, 'Tôi muốn uống nước lạnh.', 6320, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16288, 'いっしょに えいがを みませんか。', 'issho ni eiga o mimasen ka.', NULL, 'Cùng đi xem phim không?', 6321, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16289, 'こんど テニスを しませんか。', 'kondo tenisu o shimasen ka.', NULL, 'Lần tới cùng chơi tennis không?', 6321, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16290, 'ちょっと やすみましょう。', 'chotto yasumimashou.', NULL, 'Nghỉ một chút nào.', 6322, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16291, 'にもつを もちましょうか。', 'nimotsu o mochimashou ka.', NULL, 'Để tôi xách hành lý giúp nhé?', 6322, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16292, 'デパートへ くつを かいに いきます。', 'depaato e kutsu o kai ni ikimasu.', NULL, 'Tôi đến bách hóa để mua giày.', 6323, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16293, 'こうえんへ さんぽに いきました。', 'kouen e sanpo ni ikimashita.', NULL, 'Tôi đã ra công viên đi dạo.', 6323, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16294, 'ここに なまえを かいて ください。', 'koko ni namae o kaite kudasai.', NULL, 'Hãy viết tên vào đây.', 6324, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16295, 'もう いちど いって ください。', 'mou ichido itte kudasai.', NULL, 'Xin hãy nói lại một lần nữa.', 6324, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16296, 'ここで しゃしんを とらないで ください。', 'koko de shashin o toranaide kudasai.', NULL, 'Xin đừng chụp ảnh ở đây.', 6325, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16297, 'しんぱいしないで ください。', 'shinpai shinaide kudasai.', NULL, 'Xin đừng lo lắng.', 6325, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16298, 'まどを あけても いいですか。', 'mado o aketemo ii desu ka.', NULL, 'Tôi mở cửa sổ có được không?', 6326, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16299, 'この ペンを つかっても いいですか。', 'kono pen o tsukattemo ii desu ka.', NULL, 'Tôi dùng cây bút này được không?', 6326, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16300, 'ここで タバコを すっては いけません。', 'koko de tabako o sutte wa ikemasen.', NULL, 'Không được hút thuốc ở đây.', 6327, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16301, 'じゅぎょうちゅうに ねては いけません。', 'jugyouchuu ni nete wa ikemasen.', NULL, 'Không được ngủ trong giờ học.', 6327, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16302, 'この シャツを ください。', 'kono shatsu o kudasai.', NULL, 'Cho tôi cái áo sơ mi này.', 6328, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16303, 'みずを ふたつ ください。', 'mizu o futatsu kudasai.', NULL, 'Cho tôi hai cốc nước.', 6328, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16304, 'あしたまでに レポートを ださなければ なりません。', 'ashita made ni repooto o dasanakereba narimasen.', NULL, 'Tôi phải nộp báo cáo trước ngày mai.', 6329, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16305, 'まいにち くすりを のまなければ なりません。', 'mainichi kusuri o nomanakereba narimasen.', NULL, 'Hằng ngày tôi phải uống thuốc.', 6329, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16306, 'あしたは こなくても いいです。', 'ashita wa konakutemo ii desu.', NULL, 'Ngày mai bạn không cần đến cũng được.', 6330, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16307, 'くつを ぬがなくても いいですよ。', 'kutsu o nuganakutemo ii desu yo.', NULL, 'Không cần cởi giày đâu.', 6330, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16308, 'まいあさ 6じに おきます。', 'maiasa rokuji ni okimasu.', NULL, 'Sáng nào tôi cũng dậy lúc 6 giờ.', 6331, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16309, 'じゅぎょうは 9じ はんに はじまります。', 'jugyou wa kuji han ni hajimarimasu.', NULL, 'Giờ học bắt đầu lúc 9 rưỡi.', 6331, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16310, 'ぎんこうは 9じから 3じまでです。', 'ginkou wa kuji kara sanji made desu.', NULL, 'Ngân hàng làm việc từ 9 giờ đến 3 giờ.', 6332, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16311, 'うちから えきまで あるいて 10ぷんです。', 'uchi kara eki made aruite juppun desu.', NULL, 'Từ nhà đến ga đi bộ mất 10 phút.', 6332, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16312, 'あさ おきて、かおを あらって、ごはんを たべます。', 'asa okite, kao o aratte, gohan o tabemasu.', NULL, 'Buổi sáng tôi dậy, rửa mặt rồi ăn cơm.', 6333, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16313, 'デパートへ いって、かいものを しました。', 'depaato e itte, kaimono o shimashita.', NULL, 'Tôi đến bách hóa rồi mua sắm.', 6333, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16314, 'しゅくだいを して から、テレビを みます。', 'shukudai o shite kara, terebi o mimasu.', NULL, 'Làm bài tập xong rồi tôi mới xem tivi.', 6334, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16315, 'てを あらって から、たべて ください。', 'te o aratte kara, tabete kudasai.', NULL, 'Hãy rửa tay rồi mới ăn.', 6334, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16316, 'ねる まえに はを みがきます。', 'neru mae ni ha o migakimasu.', NULL, 'Trước khi ngủ tôi đánh răng.', 6335, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16317, 'しょくじの まえに てを あらいます。', 'shokuji no mae ni te o araimasu.', NULL, 'Trước bữa ăn tôi rửa tay.', 6335, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16318, 'しごとが おわった あとで、のみに いきます。', 'shigoto ga owatta ato de, nomi ni ikimasu.', NULL, 'Sau khi xong việc tôi đi uống.', 6336, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16319, 'じゅぎょうの あとで、せんせいに ききます。', 'jugyou no ato de, sensei ni kikimasu.', NULL, 'Sau giờ học tôi sẽ hỏi thầy.', 6336, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16320, 'もう ひるごはんを たべましたか。', 'mou hirugohan o tabemashita ka.', NULL, 'Bạn đã ăn trưa chưa?', 6337, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16321, 'いいえ、まだ たべて いません。', 'iie, mada tabete imasen.', NULL, 'Chưa, tôi vẫn chưa ăn.', 6337, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16322, 'おんがくを ききながら べんきょうします。', 'ongaku o kikinagara benkyou shimasu.', NULL, 'Tôi vừa nghe nhạc vừa học.', 6338, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16323, 'あるきながら でんわしないで ください。', 'arukinagara denwa shinaide kudasai.', NULL, 'Đừng vừa đi vừa gọi điện thoại.', 6338, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16324, 'やすみの ひは そうじしたり せんたくしたり します。', 'yasumi no hi wa souji shitari sentaku shitari shimasu.', NULL, 'Ngày nghỉ tôi lúc dọn dẹp, lúc giặt giũ.', 6339, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16325, 'にちようびは ほんを よんだり えいがを みたり しました。', 'nichiyoubi wa hon o yondari eiga o mitari shimashita.', NULL, 'Chủ nhật tôi đọc sách, xem phim v.v.', 6339, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16326, 'じかんが ありませんから、タクシーで いきます。', 'jikan ga arimasen kara, takushii de ikimasu.', NULL, 'Vì không có thời gian nên tôi đi taxi.', 6340, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16327, 'あめですから、うちに います。', 'ame desu kara, uchi ni imasu.', NULL, 'Vì trời mưa nên tôi ở nhà.', 6340, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16328, 'にほんごは むずかしいですが、おもしろいです。', 'nihongo wa muzukashii desu ga, omoshiroi desu.', NULL, 'Tiếng Nhật khó nhưng thú vị.', 6341, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16329, 'すみませんが、ちょっと てつだって ください。', 'sumimasen ga, chotto tetsudatte kudasai.', NULL, 'Xin lỗi nhưng giúp tôi một chút nhé.', 6341, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16330, 'どうして きのう やすみましたか。', 'doushite kinou yasumimashita ka.', NULL, 'Tại sao hôm qua bạn nghỉ?', 6342, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16331, 'ねつが あったからです。', 'netsu ga atta kara desu.', NULL, 'Là vì tôi bị sốt.', 6342, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16332, 'この みせは やすいです。そして おいしいです。', 'kono mise wa yasui desu. soshite oishii desu.', NULL, 'Quán này rẻ. Và lại ngon.', 6343, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16333, 'かいものを しました。それから ばんごはんを つくりました。', 'kaimono o shimashita. sorekara bangohan o tsukurimashita.', NULL, 'Tôi đi mua sắm. Sau đó nấu bữa tối.', 6343, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16334, 'この くつは すてきです。でも、たかいです。', 'kono kutsu wa suteki desu. demo, takai desu.', NULL, 'Đôi giày này đẹp. Nhưng đắt.', 6344, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16388, 'わたしは ピアノを ひく ことが できます。', 'watashi wa piano o hiku koto ga dekimasu.', NULL, 'Tôi có thể chơi piano.', 6371, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16335, 'よく べんきょうしました。しかし、しけんは むずかしかったです。', 'yoku benkyou shimashita. shikashi, shiken wa muzukashikatta desu.', NULL, 'Tôi đã học kỹ. Tuy nhiên bài thi khó.', 6344, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16336, 'あしたは はれると おもいます。', 'ashita wa hareru to omoimasu.', NULL, 'Tôi nghĩ mai trời sẽ nắng.', 6345, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16337, 'この ほんは おもしろいと おもいます。', 'kono hon wa omoshiroi to omoimasu.', NULL, 'Tôi nghĩ cuốn sách này hay.', 6345, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16338, '「ありがとう」は ベトナムごで なんと いいますか。', '"arigatou" wa betonamugo de nan to iimasu ka.', NULL, '"Arigatou" tiếng Việt nói thế nào?', 6346, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16339, 'わたしは リンと いいます。', 'watashi wa rin to iimasu.', NULL, 'Tôi tên là Linh.', 6346, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16340, 'わたしは がくせいです。', 'watashi wa gakusei desu.', NULL, 'Tôi là học sinh.', 6347, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16341, 'これは にほんごの ほんです。', 'kore wa nihongo no hon desu.', NULL, 'Đây là sách tiếng Nhật.', 6347, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16342, 'わたしは せんせいじゃありません。', 'watashi wa sensei ja arimasen.', NULL, 'Tôi không phải là giáo viên.', 6348, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16343, 'あれは わたしの かさではありません。', 'are wa watashi no kasa de wa arimasen.', NULL, 'Cái kia không phải ô của tôi.', 6348, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16344, 'たなかさんは かいしゃいんですか。', 'tanaka-san wa kaishain desu ka.', NULL, 'Anh Tanaka là nhân viên công ty phải không?', 6349, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16345, 'これは あなたの ですか。', 'kore wa anata no desu ka.', NULL, 'Cái này là của bạn phải không?', 6349, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16346, 'わたしも ベトナムじんです。', 'watashi mo betonamujin desu.', NULL, 'Tôi cũng là người Việt Nam.', 6350, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16347, 'コーヒーも のみます。', 'koohii mo nomimasu.', NULL, 'Tôi cũng uống cà phê.', 6350, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16348, 'これは わたしの かばんです。', 'kore wa watashi no kaban desu.', NULL, 'Đây là cặp của tôi.', 6351, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16349, 'にほんの くるまは たかいです。', 'nihon no kuruma wa takai desu.', NULL, 'Xe ô tô của Nhật thì đắt.', 6351, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16350, 'それは なんですか。', 'sore wa nan desu ka.', NULL, 'Cái đó là cái gì?', 6352, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16351, 'この とけいは いくらですか。', 'kono tokei wa ikura desu ka.', NULL, 'Cái đồng hồ này bao nhiêu tiền?', 6352, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16352, 'まいあさ パンを たべます。', 'maiasa pan o tabemasu.', NULL, 'Sáng nào tôi cũng ăn bánh mì.', 6353, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16353, 'テレビを みます。', 'terebi o mimasu.', NULL, 'Tôi xem tivi.', 6353, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16354, 'としょかんで べんきょうします。', 'toshokan de benkyou shimasu.', NULL, 'Tôi học ở thư viện.', 6354, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16355, 'どこで ひるごはんを たべますか。', 'doko de hirugohan o tabemasu ka.', NULL, 'Bạn ăn trưa ở đâu?', 6354, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16356, 'バスで がっこうへ いきます。', 'basu de gakkou e ikimasu.', NULL, 'Tôi đi đến trường bằng xe buýt.', 6355, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16357, 'はしで ごはんを たべます。', 'hashi de gohan o tabemasu.', NULL, 'Tôi ăn cơm bằng đũa.', 6355, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16358, 'ともだちと えいがを みました。', 'tomodachi to eiga o mimashita.', NULL, 'Tôi đã xem phim cùng bạn.', 6356, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16359, 'かぞくと きょうとへ いきます。', 'kazoku to kyouto e ikimasu.', NULL, 'Tôi đi Kyoto cùng gia đình.', 6356, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16360, 'パンと たまごを かいました。', 'pan to tamago o kaimashita.', NULL, 'Tôi đã mua bánh mì và trứng.', 6357, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16361, 'つくえの うえに ほんや ノートなどが あります。', 'tsukue no ue ni hon ya nooto nado ga arimasu.', NULL, 'Trên bàn có sách, vở v.v.', 6357, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16362, 'あの ひとは だれですか。', 'ano hito wa dare desu ka.', NULL, 'Người kia là ai?', 6358, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16363, 'たんじょうびは いつですか。', 'tanjoubi wa itsu desu ka.', NULL, 'Sinh nhật bạn là khi nào?', 6358, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16364, 'へやに テレビが あります。', 'heya ni terebi ga arimasu.', NULL, 'Trong phòng có tivi.', 6359, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16365, 'あした テストが あります。', 'ashita tesuto ga arimasu.', NULL, 'Ngày mai có bài kiểm tra.', 6359, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16366, 'にわに ねこが います。', 'niwa ni neko ga imasu.', NULL, 'Trong vườn có con mèo.', 6360, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16367, 'わたしは きょうだいが ふたり います。', 'watashi wa kyoudai ga futari imasu.', NULL, 'Tôi có hai anh chị em.', 6360, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16368, 'えきの まえに ぎんこうが あります。', 'eki no mae ni ginkou ga arimasu.', NULL, 'Trước nhà ga có ngân hàng.', 6361, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16369, 'きょうしつに がくせいが います。', 'kyoushitsu ni gakusei ga imasu.', NULL, 'Trong lớp học có học sinh.', 6361, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16370, 'トイレは どこに ありますか。', 'toire wa doko ni arimasu ka.', NULL, 'Nhà vệ sinh ở đâu?', 6362, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16371, 'ははは だいどころに います。', 'haha wa daidokoro ni imasu.', NULL, 'Mẹ tôi ở trong bếp.', 6362, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16372, 'かぎは つくえの したに あります。', 'kagi wa tsukue no shita ni arimasu.', NULL, 'Chìa khóa ở dưới bàn.', 6363, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16373, 'ゆうびんきょくは びょういんの となりです。', 'yuubinkyoku wa byouin no tonari desu.', NULL, 'Bưu điện ở cạnh bệnh viện.', 6363, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16374, 'ここは しょくどうです。', 'koko wa shokudou desu.', NULL, 'Đây là nhà ăn.', 6364, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16375, 'エレベーターは あそこです。', 'erebeetaa wa asoko desu.', NULL, 'Thang máy ở đằng kia.', 6364, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16376, 'まいにち にほんごを べんきょうします。', 'mainichi nihongo o benkyou shimasu.', NULL, 'Hằng ngày tôi học tiếng Nhật.', 6365, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16377, 'にちようびは はたらきません。', 'nichiyoubi wa hatarakimasen.', NULL, 'Chủ nhật tôi không làm việc.', 6365, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16378, 'きのう てがみを かきました。', 'kinou tegami o kakimashita.', NULL, 'Hôm qua tôi đã viết thư.', 6366, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16379, 'けさ あさごはんを たべませんでした。', 'kesa asagohan o tabemasendeshita.', NULL, 'Sáng nay tôi đã không ăn sáng.', 6366, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16380, 'らいしゅう とうきょうへ いきます。', 'raishuu toukyou e ikimasu.', NULL, 'Tuần sau tôi đi Tokyo.', 6367, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16381, 'なんじに うちへ かえりますか。', 'nanji ni uchi e kaerimasu ka.', NULL, 'Mấy giờ bạn về nhà?', 6367, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16382, 'いま あめが ふって います。', 'ima ame ga futte imasu.', NULL, 'Bây giờ trời đang mưa.', 6368, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16383, 'おとうとは へやで ねて います。', 'otouto wa heya de nete imasu.', NULL, 'Em trai đang ngủ trong phòng.', 6368, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16384, 'あねは けっこんして います。', 'ane wa kekkon shite imasu.', NULL, 'Chị tôi đã kết hôn.', 6369, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16385, 'ちちは ぎんこうで はたらいて います。', 'chichi wa ginkou de hataraite imasu.', NULL, 'Bố tôi làm việc ở ngân hàng.', 6369, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16386, 'ふじさんに のぼった ことが あります。', 'fujisan ni nobotta koto ga arimasu.', NULL, 'Tôi đã từng leo núi Phú Sĩ.', 6370, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16387, 'すしを たべた ことが ありますか。', 'sushi o tabeta koto ga arimasu ka.', NULL, 'Bạn đã từng ăn sushi chưa?', 6370, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16389, 'ここで カードで はらう ことが できますか。', 'koko de kaado de harau koto ga dekimasu ka.', NULL, 'Ở đây có thể trả bằng thẻ không?', 6371, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16390, 'リンさんは にほんごが よく わかります。', 'rin-san wa nihongo ga yoku wakarimasu.', NULL, 'Chị Linh hiểu tiếng Nhật rất rõ.', 6372, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16391, 'わたしは サッカーが すきです。', 'watashi wa sakkaa ga suki desu.', NULL, 'Tôi thích bóng đá.', 6372, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16392, 'はるに なりました。', 'haru ni narimashita.', NULL, 'Đã sang xuân rồi.', 6373, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16393, 'だんだん さむく なります。', 'dandan samuku narimasu.', NULL, 'Trời dần dần lạnh đi.', 6373, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16394, 'この りんごは おいしいです。', 'kono ringo wa oishii desu.', NULL, 'Quả táo này ngon.', 6374, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16395, 'この まちは しずかです。', 'kono machi wa shizuka desu.', NULL, 'Thị trấn này yên tĩnh.', 6374, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16396, 'きのうは あつかったです。', 'kinou wa atsukatta desu.', NULL, 'Hôm qua trời nóng.', 6375, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16397, 'パーティーは にぎやかでした。', 'paatii wa nigiyaka deshita.', NULL, 'Bữa tiệc rất náo nhiệt.', 6375, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16398, 'あかい かばんを かいました。', 'akai kaban o kaimashita.', NULL, 'Tôi đã mua cái cặp màu đỏ.', 6376, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16399, 'きれいな こうえんですね。', 'kirei na kouen desu ne.', NULL, 'Công viên đẹp nhỉ.', 6376, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16400, 'この えいがは とても おもしろいです。', 'kono eiga wa totemo omoshiroi desu.', NULL, 'Bộ phim này rất hay.', 6377, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16401, 'きょうは あまり さむくないです。', 'kyou wa amari samukunai desu.', NULL, 'Hôm nay không lạnh lắm.', 6377, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16402, 'でんしゃは バスより はやいです。', 'densha wa basu yori hayai desu.', NULL, 'Tàu điện nhanh hơn xe buýt.', 6378, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16403, 'きょうは きのうより あたたかいです。', 'kyou wa kinou yori atatakai desu.', NULL, 'Hôm nay ấm hơn hôm qua.', 6378, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16404, 'いぬと ねこと どちらが すきですか。', 'inu to neko to dochira ga suki desu ka.', NULL, 'Chó và mèo, bạn thích con nào hơn?', 6379, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16405, 'ねこの ほうが すきです。', 'neko no hou ga suki desu.', NULL, 'Tôi thích mèo hơn.', 6379, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16406, 'くだものの なかで いちごが いちばん すきです。', 'kudamono no naka de ichigo ga ichiban suki desu.', NULL, 'Trong các loại quả, tôi thích dâu nhất.', 6380, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16407, 'クラスで だれが いちばん せが たかいですか。', 'kurasu de dare ga ichiban se ga takai desu ka.', NULL, 'Trong lớp ai cao nhất?', 6380, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16408, 'この へやは ひろくて あかるいです。', 'kono heya wa hirokute akarui desu.', NULL, 'Căn phòng này rộng và sáng.', 6381, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16409, 'やまださんは しんせつで おもしろい ひとです。', 'yamada-san wa shinsetsu de omoshiroi hito desu.', NULL, 'Anh Yamada là người tốt bụng và thú vị.', 6381, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16410, 'あたらしい パソコンが ほしいです。', 'atarashii pasokon ga hoshii desu.', NULL, 'Tôi muốn có máy tính mới.', 6382, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16411, 'いま なにが いちばん ほしいですか。', 'ima nani ga ichiban hoshii desu ka.', NULL, 'Bây giờ bạn muốn có gì nhất?', 6382, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16412, 'にほんへ いきたいです。', 'nihon e ikitai desu.', NULL, 'Tôi muốn đi Nhật.', 6383, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16413, 'つめたい みずが のみたいです。', 'tsumetai mizu ga nomitai desu.', NULL, 'Tôi muốn uống nước lạnh.', 6383, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16414, 'いっしょに えいがを みませんか。', 'issho ni eiga o mimasen ka.', NULL, 'Cùng đi xem phim không?', 6384, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16415, 'こんど テニスを しませんか。', 'kondo tenisu o shimasen ka.', NULL, 'Lần tới cùng chơi tennis không?', 6384, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16416, 'ちょっと やすみましょう。', 'chotto yasumimashou.', NULL, 'Nghỉ một chút nào.', 6385, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16417, 'にもつを もちましょうか。', 'nimotsu o mochimashou ka.', NULL, 'Để tôi xách hành lý giúp nhé?', 6385, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16418, 'デパートへ くつを かいに いきます。', 'depaato e kutsu o kai ni ikimasu.', NULL, 'Tôi đến bách hóa để mua giày.', 6386, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16419, 'こうえんへ さんぽに いきました。', 'kouen e sanpo ni ikimashita.', NULL, 'Tôi đã ra công viên đi dạo.', 6386, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16420, 'ここに なまえを かいて ください。', 'koko ni namae o kaite kudasai.', NULL, 'Hãy viết tên vào đây.', 6387, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16421, 'もう いちど いって ください。', 'mou ichido itte kudasai.', NULL, 'Xin hãy nói lại một lần nữa.', 6387, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16422, 'ここで しゃしんを とらないで ください。', 'koko de shashin o toranaide kudasai.', NULL, 'Xin đừng chụp ảnh ở đây.', 6388, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16423, 'しんぱいしないで ください。', 'shinpai shinaide kudasai.', NULL, 'Xin đừng lo lắng.', 6388, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16424, 'まどを あけても いいですか。', 'mado o aketemo ii desu ka.', NULL, 'Tôi mở cửa sổ có được không?', 6389, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16425, 'この ペンを つかっても いいですか。', 'kono pen o tsukattemo ii desu ka.', NULL, 'Tôi dùng cây bút này được không?', 6389, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16426, 'ここで タバコを すっては いけません。', 'koko de tabako o sutte wa ikemasen.', NULL, 'Không được hút thuốc ở đây.', 6390, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16427, 'じゅぎょうちゅうに ねては いけません。', 'jugyouchuu ni nete wa ikemasen.', NULL, 'Không được ngủ trong giờ học.', 6390, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16428, 'この シャツを ください。', 'kono shatsu o kudasai.', NULL, 'Cho tôi cái áo sơ mi này.', 6391, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16429, 'みずを ふたつ ください。', 'mizu o futatsu kudasai.', NULL, 'Cho tôi hai cốc nước.', 6391, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16430, 'あしたまでに レポートを ださなければ なりません。', 'ashita made ni repooto o dasanakereba narimasen.', NULL, 'Tôi phải nộp báo cáo trước ngày mai.', 6392, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16431, 'まいにち くすりを のまなければ なりません。', 'mainichi kusuri o nomanakereba narimasen.', NULL, 'Hằng ngày tôi phải uống thuốc.', 6392, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16432, 'あしたは こなくても いいです。', 'ashita wa konakutemo ii desu.', NULL, 'Ngày mai bạn không cần đến cũng được.', 6393, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16433, 'くつを ぬがなくても いいですよ。', 'kutsu o nuganakutemo ii desu yo.', NULL, 'Không cần cởi giày đâu.', 6393, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16434, 'まいあさ 6じに おきます。', 'maiasa rokuji ni okimasu.', NULL, 'Sáng nào tôi cũng dậy lúc 6 giờ.', 6394, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16435, 'じゅぎょうは 9じ はんに はじまります。', 'jugyou wa kuji han ni hajimarimasu.', NULL, 'Giờ học bắt đầu lúc 9 rưỡi.', 6394, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16436, 'ぎんこうは 9じから 3じまでです。', 'ginkou wa kuji kara sanji made desu.', NULL, 'Ngân hàng làm việc từ 9 giờ đến 3 giờ.', 6395, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16437, 'うちから えきまで あるいて 10ぷんです。', 'uchi kara eki made aruite juppun desu.', NULL, 'Từ nhà đến ga đi bộ mất 10 phút.', 6395, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16438, 'あさ おきて、かおを あらって、ごはんを たべます。', 'asa okite, kao o aratte, gohan o tabemasu.', NULL, 'Buổi sáng tôi dậy, rửa mặt rồi ăn cơm.', 6396, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16439, 'デパートへ いって、かいものを しました。', 'depaato e itte, kaimono o shimashita.', NULL, 'Tôi đến bách hóa rồi mua sắm.', 6396, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16440, 'しゅくだいを して から、テレビを みます。', 'shukudai o shite kara, terebi o mimasu.', NULL, 'Làm bài tập xong rồi tôi mới xem tivi.', 6397, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16441, 'てを あらって から、たべて ください。', 'te o aratte kara, tabete kudasai.', NULL, 'Hãy rửa tay rồi mới ăn.', 6397, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16442, 'ねる まえに はを みがきます。', 'neru mae ni ha o migakimasu.', NULL, 'Trước khi ngủ tôi đánh răng.', 6398, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16443, 'しょくじの まえに てを あらいます。', 'shokuji no mae ni te o araimasu.', NULL, 'Trước bữa ăn tôi rửa tay.', 6398, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16444, 'しごとが おわった あとで、のみに いきます。', 'shigoto ga owatta ato de, nomi ni ikimasu.', NULL, 'Sau khi xong việc tôi đi uống.', 6399, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16445, 'じゅぎょうの あとで、せんせいに ききます。', 'jugyou no ato de, sensei ni kikimasu.', NULL, 'Sau giờ học tôi sẽ hỏi thầy.', 6399, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16446, 'もう ひるごはんを たべましたか。', 'mou hirugohan o tabemashita ka.', NULL, 'Bạn đã ăn trưa chưa?', 6400, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16447, 'いいえ、まだ たべて いません。', 'iie, mada tabete imasen.', NULL, 'Chưa, tôi vẫn chưa ăn.', 6400, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16448, 'おんがくを ききながら べんきょうします。', 'ongaku o kikinagara benkyou shimasu.', NULL, 'Tôi vừa nghe nhạc vừa học.', 6401, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16449, 'あるきながら でんわしないで ください。', 'arukinagara denwa shinaide kudasai.', NULL, 'Đừng vừa đi vừa gọi điện thoại.', 6401, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16450, 'やすみの ひは そうじしたり せんたくしたり します。', 'yasumi no hi wa souji shitari sentaku shitari shimasu.', NULL, 'Ngày nghỉ tôi lúc dọn dẹp, lúc giặt giũ.', 6402, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16451, 'にちようびは ほんを よんだり えいがを みたり しました。', 'nichiyoubi wa hon o yondari eiga o mitari shimashita.', NULL, 'Chủ nhật tôi đọc sách, xem phim v.v.', 6402, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16452, 'じかんが ありませんから、タクシーで いきます。', 'jikan ga arimasen kara, takushii de ikimasu.', NULL, 'Vì không có thời gian nên tôi đi taxi.', 6403, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16453, 'あめですから、うちに います。', 'ame desu kara, uchi ni imasu.', NULL, 'Vì trời mưa nên tôi ở nhà.', 6403, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16454, 'にほんごは むずかしいですが、おもしろいです。', 'nihongo wa muzukashii desu ga, omoshiroi desu.', NULL, 'Tiếng Nhật khó nhưng thú vị.', 6404, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16455, 'すみませんが、ちょっと てつだって ください。', 'sumimasen ga, chotto tetsudatte kudasai.', NULL, 'Xin lỗi nhưng giúp tôi một chút nhé.', 6404, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16456, 'どうして きのう やすみましたか。', 'doushite kinou yasumimashita ka.', NULL, 'Tại sao hôm qua bạn nghỉ?', 6405, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16457, 'ねつが あったからです。', 'netsu ga atta kara desu.', NULL, 'Là vì tôi bị sốt.', 6405, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16458, 'この みせは やすいです。そして おいしいです。', 'kono mise wa yasui desu. soshite oishii desu.', NULL, 'Quán này rẻ. Và lại ngon.', 6406, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16459, 'かいものを しました。それから ばんごはんを つくりました。', 'kaimono o shimashita. sorekara bangohan o tsukurimashita.', NULL, 'Tôi đi mua sắm. Sau đó nấu bữa tối.', 6406, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16460, 'この くつは すてきです。でも、たかいです。', 'kono kutsu wa suteki desu. demo, takai desu.', NULL, 'Đôi giày này đẹp. Nhưng đắt.', 6407, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16461, 'よく べんきょうしました。しかし、しけんは むずかしかったです。', 'yoku benkyou shimashita. shikashi, shiken wa muzukashikatta desu.', NULL, 'Tôi đã học kỹ. Tuy nhiên bài thi khó.', 6407, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16462, 'あしたは はれると おもいます。', 'ashita wa hareru to omoimasu.', NULL, 'Tôi nghĩ mai trời sẽ nắng.', 6408, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16463, 'この ほんは おもしろいと おもいます。', 'kono hon wa omoshiroi to omoimasu.', NULL, 'Tôi nghĩ cuốn sách này hay.', 6408, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16464, '「ありがとう」は ベトナムごで なんと いいますか。', '"arigatou" wa betonamugo de nan to iimasu ka.', NULL, '"Arigatou" tiếng Việt nói thế nào?', 6409, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16465, 'わたしは リンと いいます。', 'watashi wa rin to iimasu.', NULL, 'Tôi tên là Linh.', 6409, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16466, 'あした、うちに いる？', 'ashita, uchi ni iru?', NULL, 'Mai cậu có ở nhà không?', 6410, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16467, 'きのうは いそがしかった。', 'kinou wa isogashikatta.', NULL, 'Hôm qua bận lắm.', 6410, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16468, 'ねつが あるなら、はやく ねた ほうが いいですよ。', 'netsu ga aru nara, hayaku neta hou ga ii desu yo.', NULL, 'Nếu bị sốt thì nên ngủ sớm đấy.', 6411, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16469, 'よる おそく コーヒーを のまない ほうが いいです。', 'yoru osoku koohii o nomanai hou ga ii desu.', NULL, 'Không nên uống cà phê vào đêm khuya.', 6411, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16470, 'これは ははが つくった ケーキです。', 'kore wa haha ga tsukutta keeki desu.', NULL, 'Đây là bánh mẹ tôi làm.', 6412, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16471, 'めがねを かけて いる ひとが やまださんです。', 'megane o kakete iru hito ga yamada-san desu.', NULL, 'Người đeo kính là anh Yamada.', 6412, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16472, 'わたしは えを かくのが すきです。', 'watashi wa e o kaku no ga suki desu.', NULL, 'Tôi thích vẽ tranh.', 6413, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16473, 'ひとりで りょこうするのは たのしいです。', 'hitori de ryokou suru no wa tanoshii desu.', NULL, 'Đi du lịch một mình thì vui.', 6413, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16474, 'でんきを けすのを わすれました。', 'denki o kesu no o wasuremashita.', NULL, 'Tôi quên tắt đèn.', 6414, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16475, 'しゅくだいを だすのを わすれないで ください。', 'shukudai o dasu no o wasurenaide kudasai.', NULL, 'Đừng quên nộp bài tập.', 6414, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16476, 'エアコンを つけた まま ねて しまいました。', 'eakon o tsuketa mama nete shimaimashita.', NULL, 'Tôi lỡ ngủ mà để nguyên điều hòa.', 6415, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16477, 'くつを はいた まま へやに はいらないで ください。', 'kutsu o haita mama heya ni hairanaide kudasai.', NULL, 'Đừng đi nguyên giày vào phòng.', 6415, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16478, 'でんしゃに かさを わすれて しまいました。', 'densha ni kasa o wasurete shimaimashita.', NULL, 'Tôi lỡ để quên ô trên tàu.', 6416, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16479, 'この ほんは もう よんで しまいました。', 'kono hon wa mou yonde shimaimashita.', NULL, 'Tôi đã đọc hết cuốn sách này rồi.', 6416, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16480, 'パーティーの まえに のみものを かって おきます。', 'paatii no mae ni nomimono o katte okimasu.', NULL, 'Trước bữa tiệc tôi mua sẵn đồ uống.', 6417, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16481, 'つかった あとで、もとの ところに もどして おいて ください。', 'tsukatta ato de, moto no tokoro ni modoshite oite kudasai.', NULL, 'Dùng xong hãy để lại chỗ cũ.', 6417, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16482, 'まどが あけて あります。', 'mado ga akete arimasu.', NULL, 'Cửa sổ đã được mở sẵn.', 6418, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16483, 'カレンダーに よていが かいて あります。', 'karendaa ni yotei ga kaite arimasu.', NULL, 'Lịch trình đã được ghi trên lịch.', 6418, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16484, 'わたしは かんじが 300 ぐらい よめます。', 'watashi wa kanji ga sanbyaku gurai yomemasu.', NULL, 'Tôi đọc được khoảng 300 chữ Hán.', 6419, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16485, 'あしたは こられますか。', 'ashita wa koraremasu ka.', NULL, 'Ngày mai bạn đến được không?', 6419, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16486, 'まどから ふじさんが みえます。', 'mado kara fujisan ga miemasu.', NULL, 'Từ cửa sổ nhìn thấy núi Phú Sĩ.', 6420, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16487, 'となりの へやから ピアノの おとが きこえます。', 'tonari no heya kara piano no oto ga kikoemasu.', NULL, 'Nghe thấy tiếng piano từ phòng bên.', 6420, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16488, 'にほんごが すこし はなせる ように なりました。', 'nihongo ga sukoshi hanaseru you ni narimashita.', NULL, 'Tôi đã nói được một chút tiếng Nhật.', 6421, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16489, 'まいあさ ジョギングする ように なりました。', 'maiasa jogingu suru you ni narimashita.', NULL, 'Tôi đã bắt đầu chạy bộ mỗi sáng.', 6421, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16490, 'やさいを たくさん たべる ように して います。', 'yasai o takusan taberu you ni shite imasu.', NULL, 'Tôi cố gắng ăn nhiều rau.', 6422, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16491, 'じゅぎょうに おくれない ように します。', 'jugyou ni okurenai you ni shimasu.', NULL, 'Tôi sẽ cố không đến lớp muộn.', 6422, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16492, 'へやを あたたかく しました。', 'heya o atatakaku shimashita.', NULL, 'Tôi làm cho căn phòng ấm lên.', 6423, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16493, 'のみものは コーヒーに します。', 'nomimono wa koohii ni shimasu.', NULL, 'Đồ uống thì tôi chọn cà phê.', 6423, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16494, 'らいげつ おおさかに てんきんする ことに なりました。', 'raigetsu oosaka ni tenkin suru koto ni narimashita.', NULL, 'Tháng sau tôi được điều chuyển về Osaka.', 6424, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16495, 'しあいは ちゅうしする ことに なりました。', 'shiai wa chuushi suru koto ni narimashita.', NULL, 'Trận đấu đã được quyết định hủy.', 6424, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16496, 'なつやすみに ベトナムへ かえる ことに しました。', 'natsuyasumi ni betonamu e kaeru koto ni shimashita.', NULL, 'Tôi quyết định về Việt Nam vào kỳ nghỉ hè.', 6425, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16497, 'あしたから タバコを やめる ことに しました。', 'ashita kara tabako o yameru koto ni shimashita.', NULL, 'Tôi quyết định bỏ thuốc lá từ ngày mai.', 6425, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16498, 'ねる まえに にっきを かく ことに して います。', 'neru mae ni nikki o kaku koto ni shite imasu.', NULL, 'Tôi có thói quen viết nhật ký trước khi ngủ.', 6426, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16499, 'しゅうまつは しごとの メールを みない ことに して います。', 'shuumatsu wa shigoto no meeru o minai koto ni shite imasu.', NULL, 'Cuối tuần tôi có nguyên tắc không xem email công việc.', 6426, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16500, 'すこし やすもう。', 'sukoshi yasumou.', NULL, 'Nghỉ một chút đi.', 6427, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16501, 'いっしょに かえろう。', 'issho ni kaerou.', NULL, 'Cùng về nào.', 6427, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16502, 'らいねん だいがくいんに はいろうと おもって います。', 'rainen daigakuin ni hairou to omotte imasu.', NULL, 'Tôi đang định năm sau vào cao học.', 6428, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16503, 'こんばん はやく ねようと おもって います。', 'konban hayaku neyou to omotte imasu.', NULL, 'Tối nay tôi định ngủ sớm.', 6428, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16504, 'なつやすみは アルバイトを する つもりです。', 'natsuyasumi wa arubaito o suru tsumori desu.', NULL, 'Kỳ nghỉ hè tôi dự định làm thêm.', 6429, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16505, 'もう あの みせには いかない つもりです。', 'mou ano mise ni wa ikanai tsumori desu.', NULL, 'Tôi định không đến quán đó nữa.', 6429, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16506, 'かいぎは 3じに おわる よていです。', 'kaigi wa sanji ni owaru yotei desu.', NULL, 'Cuộc họp dự kiến kết thúc lúc 3 giờ.', 6430, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16507, 'らいしゅうから しゅっちょうの よていです。', 'raishuu kara shucchou no yotei desu.', NULL, 'Theo kế hoạch tôi đi công tác từ tuần sau.', 6430, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16508, 'にほんに きた ばかりです。', 'nihon ni kita bakari desu.', NULL, 'Tôi vừa mới đến Nhật.', 6431, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16509, 'さっき ひるごはんを たべた ばかりです。', 'sakki hirugohan o tabeta bakari desu.', NULL, 'Tôi vừa ăn trưa xong lúc nãy.', 6431, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16510, 'いまから でかける ところです。', 'ima kara dekakeru tokoro desu.', NULL, 'Tôi đang chuẩn bị ra ngoài.', 6432, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16511, 'いま しりょうを よんで いる ところです。', 'ima shiryou o yonde iru tokoro desu.', NULL, 'Bây giờ tôi đang đọc tài liệu.', 6432, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16512, 'つかれたら、すこし やすんだら どうですか。', 'tsukaretara, sukoshi yasundara dou desu ka.', NULL, 'Nếu mệt thì nghỉ một chút xem sao?', 6433, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16513, 'せんせいに そうだんしたら どうですか。', 'sensei ni soudan shitara dou desu ka.', NULL, 'Thử hỏi ý kiến thầy xem sao?', 6433, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16514, 'あめが ふったら、しあいは ありません。', 'ame ga futtara, shiai wa arimasen.', NULL, 'Nếu trời mưa thì không có trận đấu.', 6434, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16515, 'うちに ついたら、でんわして ください。', 'uchi ni tsuitara, denwa shite kudasai.', NULL, 'Về đến nhà thì gọi điện cho tôi nhé.', 6434, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16516, 'この ボタンを おせば、きっぷが でます。', 'kono botan o oseba, kippu ga demasu.', NULL, 'Nếu bấm nút này thì vé sẽ ra.', 6435, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16517, 'やすければ、かいたいです。', 'yasukereba, kaitai desu.', NULL, 'Nếu rẻ thì tôi muốn mua.', 6435, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16518, 'この かどを みぎに まがると、えきが あります。', 'kono kado o migi ni magaru to, eki ga arimasu.', NULL, 'Rẽ phải ở góc này thì sẽ thấy nhà ga.', 6436, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16519, 'はるに なると、さくらが さきます。', 'haru ni naru to, sakura ga sakimasu.', NULL, 'Hễ đến mùa xuân là hoa anh đào nở.', 6436, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16520, 'にほんりょうりなら、すしが いちばん すきです。', 'nihon ryouri nara, sushi ga ichiban suki desu.', NULL, 'Nếu là món Nhật thì tôi thích sushi nhất.', 6437, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16521, 'パソコンを かうなら、あの みせが やすいですよ。', 'pasokon o kau nara, ano mise ga yasui desu yo.', NULL, 'Nếu mua máy tính thì cửa hàng kia rẻ đấy.', 6437, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16522, 'あめが ふっても、しごとに いきます。', 'ame ga futte mo, shigoto ni ikimasu.', NULL, 'Dù trời mưa tôi vẫn đi làm.', 6438, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16523, 'いくら かんがえても、わかりません。', 'ikura kangaete mo, wakarimasen.', NULL, 'Nghĩ bao nhiêu cũng không hiểu.', 6438, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16524, 'にほんごは べんきょうすれば するほど おもしろく なります。', 'nihongo wa benkyou sureba suru hodo omoshiroku narimasu.', NULL, 'Tiếng Nhật càng học càng thấy thú vị.', 6439, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16525, 'やさいは あたらしければ あたらしいほど おいしいです。', 'yasai wa atarashikereba atarashii hodo oishii desu.', NULL, 'Rau càng tươi càng ngon.', 6439, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16526, 'かれが くるか どうか わかりません。', 'kare ga kuru ka dou ka wakarimasen.', NULL, 'Tôi không biết anh ấy có đến hay không.', 6440, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16616, 'でんしゃに かさを わすれて しまいました。', 'densha ni kasa o wasurete shimaimashita.', NULL, 'Tôi lỡ để quên ô trên tàu.', 6485, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16527, 'この くすりが きくか どうか ためして みます。', 'kono kusuri ga kiku ka dou ka tameshite mimasu.', NULL, 'Tôi sẽ thử xem thuốc này có hiệu quả không.', 6440, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16528, 'ともだちが わたしに ほんを くれました。', 'tomodachi ga watashi ni hon o kuremashita.', NULL, 'Bạn tôi đã cho tôi cuốn sách.', 6441, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16529, 'わたしは あねに とけいを もらいました。', 'watashi wa ane ni tokei o moraimashita.', NULL, 'Tôi nhận được đồng hồ từ chị gái.', 6441, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16530, 'いもうとに えほんを よんで あげました。', 'imouto ni ehon o yonde agemashita.', NULL, 'Tôi đọc truyện tranh cho em gái.', 6442, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19005, 'りんごを 4つ 買いました。', 'Ringo o yottsu kaimashita.', NULL, 'Tôi đã mua 4 quả táo.', 7681, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16531, 'おばあさんの にもつを もって あげました。', 'obaasan no nimotsu o motte agemashita.', NULL, 'Tôi xách đồ giúp bà cụ.', 6442, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16532, 'どうりょうが しごとを てつだって くれました。', 'douryou ga shigoto o tetsudatte kuremashita.', NULL, 'Đồng nghiệp đã giúp tôi làm việc.', 6443, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16533, 'ははが べんとうを つくって くれます。', 'haha ga bentou o tsukutte kuremasu.', NULL, 'Mẹ làm cơm hộp cho tôi.', 6443, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16534, 'せんせいに さくぶんを なおして もらいました。', 'sensei ni sakubun o naoshite moraimashita.', NULL, 'Tôi được thầy sửa bài văn cho.', 6444, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16535, 'ともだちに えきまで おくって もらいました。', 'tomodachi ni eki made okutte moraimashita.', NULL, 'Tôi được bạn đưa ra ga.', 6444, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16536, 'すみません、しゃしんを とって いただけませんか。', 'sumimasen, shashin o totte itadakemasen ka.', NULL, 'Xin lỗi, anh chụp giúp tôi tấm ảnh được không?', 6445, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16537, 'もう すこし ゆっくり はなして いただけませんか。', 'mou sukoshi yukkuri hanashite itadakemasen ka.', NULL, 'Anh có thể nói chậm hơn một chút được không?', 6445, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16538, 'この ことばの いみを おしえて くださいませんか。', 'kono kotoba no imi o oshiete kudasaimasen ka.', NULL, 'Xin chỉ cho tôi nghĩa của từ này được không?', 6446, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16539, 'あした もう いちど きて くださいませんか。', 'ashita mou ichido kite kudasaimasen ka.', NULL, 'Mai anh đến thêm một lần được không?', 6446, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16540, 'わたしは せんせいに ほめられました。', 'watashi wa sensei ni homeraremashita.', NULL, 'Tôi được thầy khen.', 6447, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16541, 'おとうとに ケーキを たべられました。', 'otouto ni keeki o taberaremashita.', NULL, 'Tôi bị em trai ăn mất bánh.', 6447, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16543, '「源氏物語」は むらさきしきぶに よって かかれました。', '"genji monogatari" wa murasaki shikibu ni yotte kakaremashita.', NULL, '"Truyện Genji" được viết bởi Murasaki Shikibu.', 6448, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16546, 'きょうは はやく かえらせて いただけませんか。', 'kyou wa hayaku kaerasete itadakemasen ka.', NULL, 'Hôm nay cho phép tôi về sớm được không?', 6450, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16547, 'この しりょうを コピーさせて いただけませんか。', 'kono shiryou o kopii sasete itadakemasen ka.', NULL, 'Cho tôi photo tài liệu này được không?', 6450, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16548, 'しゃちょうは もう おかえりに なりました。', 'shachou wa mou okaeri ni narimashita.', NULL, 'Giám đốc đã về rồi ạ.', 6451, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16549, 'この ほんを およみに なりましたか。', 'kono hon o oyomi ni narimashita ka.', NULL, 'Ngài đã đọc cuốn sách này chưa ạ?', 6451, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16550, 'にもつを おもちします。', 'nimotsu o omochi shimasu.', NULL, 'Để tôi xách hành lý giúp ạ.', 6452, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16551, 'あとで おでんわします。', 'ato de odenwa shimasu.', NULL, 'Lát nữa tôi sẽ gọi điện ạ.', 6452, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16552, 'せんせいは けんきゅうしつに いらっしゃいます。', 'sensei wa kenkyuushitsu ni irasshaimasu.', NULL, 'Thầy đang ở phòng nghiên cứu ạ.', 6453, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16553, 'どうぞ めしあがって ください。', 'douzo meshiagatte kudasai.', NULL, 'Xin mời dùng bữa ạ.', 6453, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16554, 'あした 10じに まいります。', 'ashita juuji ni mairimasu.', NULL, 'Ngày mai tôi sẽ đến lúc 10 giờ ạ.', 6454, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16555, 'しりょうを はいけんしました。', 'shiryou o haiken shimashita.', NULL, 'Tôi đã xem tài liệu ạ.', 6454, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16556, 'あしたは あめが ふるでしょう。', 'ashita wa ame ga furu deshou.', NULL, 'Ngày mai có lẽ trời mưa.', 6455, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16557, 'かれは たぶん しらないだろう。', 'kare wa tabun shiranai darou.', NULL, 'Chắc anh ấy không biết đâu.', 6455, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16558, 'ごごから ゆきが ふるかもしれません。', 'gogo kara yuki ga furu kamoshiremasen.', NULL, 'Có thể chiều nay tuyết rơi.', 6456, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16559, 'その はなしは うそかもしれません。', 'sono hanashi wa uso kamoshiremasen.', NULL, 'Câu chuyện đó có thể là nói dối.', 6456, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16560, 'かれは もう ついて いる はずです。', 'kare wa mou tsuite iru hazu desu.', NULL, 'Anh ấy chắc chắn đã đến nơi rồi.', 6457, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16561, 'あの レストランは きょう やすみの はずです。', 'ano resutoran wa kyou yasumi no hazu desu.', NULL, 'Nhà hàng đó hôm nay chắc là nghỉ.', 6457, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16562, 'この ケーキは おいしそうですね。', 'kono keeki wa oishisou desu ne.', NULL, 'Cái bánh này trông ngon nhỉ.', 6458, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16563, 'いまにも あめが ふりそうです。', 'imanimo ame ga furisou desu.', NULL, 'Trời sắp mưa đến nơi.', 6458, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16564, 'てんきよほうに よると、あしたは さむく なるそうです。', 'tenki yohou ni yoru to, ashita wa samuku naru sou desu.', NULL, 'Theo dự báo thời tiết, nghe nói mai trời lạnh.', 6459, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16565, 'たなかさんは らいげつ けっこんするそうです。', 'tanaka-san wa raigetsu kekkon suru sou desu.', NULL, 'Nghe nói tháng sau anh Tanaka cưới.', 6459, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16566, 'だれも いない ようです。', 'daremo inai you desu.', NULL, 'Hình như không có ai.', 6460, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16567, 'かぜを ひいたみたいです。', 'kaze o hiita mitai desu.', NULL, 'Hình như tôi bị cảm rồi.', 6460, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16568, 'あの みせは らいしゅう しまるらしいです。', 'ano mise wa raishuu shimaru rashii desu.', NULL, 'Nghe đâu cửa hàng đó tuần sau đóng cửa.', 6461, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16569, 'やまださんは ねこが すきらしいです。', 'yamada-san wa neko ga suki rashii desu.', NULL, 'Có vẻ anh Yamada thích mèo.', 6461, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16570, '「さくら」という レストランを しって いますか。', '"sakura" to iu resutoran o shitte imasu ka.', NULL, 'Bạn có biết nhà hàng tên "Sakura" không?', 6462, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16571, 'これは おりがみと いう あそびです。', 'kore wa origami to iu asobi desu.', NULL, 'Đây là trò chơi gọi là origami.', 6462, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16572, 'リンさんは すこし おくれると いって いました。', 'rin-san wa sukoshi okureru to itte imashita.', NULL, 'Chị Linh nói là sẽ đến muộn một chút.', 6463, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16573, 'あしたの かいぎは 2じからだと つたえて ください。', 'ashita no kaigi wa niji kara da to tsutaete kudasai.', NULL, 'Nhắn giúp là cuộc họp mai bắt đầu từ 2 giờ.', 6463, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16574, 'いえを かう ために ちょきんして います。', 'ie o kau tame ni chokin shite imasu.', NULL, 'Tôi đang tiết kiệm để mua nhà.', 6464, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16575, 'けんこうの ために まいにち あるきます。', 'kenkou no tame ni mainichi arukimasu.', NULL, 'Vì sức khỏe, hằng ngày tôi đi bộ.', 6464, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16576, 'うしろの ひとにも きこえる ように おおきい こえで はなします。', 'ushiro no hito ni mo kikoeru you ni ookii koe de hanashimasu.', NULL, 'Tôi nói to để người phía sau cũng nghe thấy.', 6465, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16577, 'かぜを ひかない ように あたたかく して ください。', 'kaze o hikanai you ni atatakaku shite kudasai.', NULL, 'Hãy giữ ấm để không bị cảm.', 6465, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16578, 'ゆうべ のみすぎました。', 'yuube nomisugimashita.', NULL, 'Tối qua tôi uống quá nhiều.', 6466, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16579, 'この もんだいは むずかしすぎます。', 'kono mondai wa muzukashisugimasu.', NULL, 'Câu hỏi này khó quá.', 6466, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16580, 'この ペンは かきやすいです。', 'kono pen wa kakiyasui desu.', NULL, 'Cây bút này dễ viết.', 6467, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16581, 'この くすりは のみにくいです。', 'kono kusuri wa nominikui desu.', NULL, 'Thuốc này khó uống.', 6467, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16582, 'ぞうは はなが ながいです。', 'zou wa hana ga nagai desu.', NULL, 'Con voi có cái vòi dài.', 6468, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16583, 'この まちは こうつうが べんりです。', 'kono machi wa koutsuu ga benri desu.', NULL, 'Thị trấn này giao thông thuận tiện.', 6468, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16584, 'おとうとは ゲームばかり して います。', 'otouto wa geemu bakari shite imasu.', NULL, 'Em trai tôi chỉ toàn chơi game.', 6469, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16585, 'かれは あそんで ばかり いて、ぜんぜん べんきょうしません。', 'kare wa asonde bakari ite, zenzen benkyou shimasen.', NULL, 'Anh ta chỉ toàn chơi, chẳng học gì cả.', 6469, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16586, 'さいふに 500えんしか ありません。', 'saifu ni gohyakuen shika arimasen.', NULL, 'Trong ví chỉ có 500 yên.', 6470, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16587, 'にほんごは すこししか はなせません。', 'nihongo wa sukoshi shika hanasemasen.', NULL, 'Tôi chỉ nói được chút ít tiếng Nhật.', 6470, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16588, 'きのうは 10じかんも ねました。', 'kinou wa juujikan mo nemashita.', NULL, 'Hôm qua tôi ngủ tới 10 tiếng.', 6471, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16589, 'この かばんは 5まんえんも しました。', 'kono kaban wa goman en mo shimashita.', NULL, 'Cái túi này đắt tới 50.000 yên.', 6471, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16590, 'ペンで かいても いいです。', 'pen de kaite mo ii desu.', NULL, 'Viết bằng bút mực cũng được.', 6472, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16591, 'いそがしければ、こなくても かまいません。', 'isogashikereba, konakute mo kamaimasen.', NULL, 'Nếu bận thì không đến cũng không sao.', 6472, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16592, 'この アパートは えきに ちかいし、やすいし、いいですね。', 'kono apaato wa eki ni chikai shi, yasui shi, ii desu ne.', NULL, 'Căn hộ này vừa gần ga lại rẻ, tốt nhỉ.', 6473, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16593, 'きょうは ねつも あるし、あたまも いたいし、やすみます。', 'kyou wa netsu mo aru shi, atama mo itai shi, yasumimasu.', NULL, 'Hôm nay vừa sốt vừa đau đầu nên tôi nghỉ.', 6473, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16594, 'でんしゃが おくれたので、ちこくしました。', 'densha ga okureta node, chikoku shimashita.', NULL, 'Vì tàu trễ nên tôi đến muộn.', 6474, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16595, 'あしたは しけんなので、こんばんは べんきょうします。', 'ashita wa shiken na node, konban wa benkyou shimasu.', NULL, 'Vì mai thi nên tối nay tôi học.', 6474, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16596, 'いっしょうけんめい べんきょうしたのに、ごうかくできませんでした。', 'isshoukenmei benkyou shita noni, goukaku dekimasen deshita.', NULL, 'Học chăm chỉ vậy mà vẫn không đỗ.', 6475, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16597, 'やくそくしたのに、かれは こなかった。', 'yakusoku shita noni, kare wa konakatta.', NULL, 'Đã hứa rồi vậy mà anh ta không đến.', 6475, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16598, 'にほんへ いく とき、かばんを かいました。', 'nihon e iku toki, kaban o kaimashita.', NULL, 'Khi (trước lúc) đi Nhật, tôi đã mua cặp.', 6476, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16599, 'にほんへ いった とき、かばんを かいました。', 'nihon e itta toki, kaban o kaimashita.', NULL, 'Khi (đã) sang Nhật, tôi đã mua cặp.', 6476, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16600, 'アルバイトを しながら だいがくに かよって います。', 'arubaito o shinagara daigaku ni kayotte imasu.', NULL, 'Tôi vừa làm thêm vừa đi học đại học.', 6477, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16601, 'はたらきながら こどもを そだてて います。', 'hatarakinagara kodomo o sodatete imasu.', NULL, 'Tôi vừa làm việc vừa nuôi con.', 6477, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16602, 'どう すれば いいですか。', 'dou sureba ii desu ka.', NULL, 'Tôi nên làm thế nào thì được?', 6478, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16603, 'ここに なまえを かけば いいです。', 'koko ni namae o kakeba ii desu.', NULL, 'Chỉ cần viết tên vào đây là được.', 6478, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16604, 'あした、うちに いる？', 'ashita, uchi ni iru?', NULL, 'Mai cậu có ở nhà không?', 6479, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16605, 'きのうは いそがしかった。', 'kinou wa isogashikatta.', NULL, 'Hôm qua bận lắm.', 6479, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16606, 'ねつが あるなら、はやく ねた ほうが いいですよ。', 'netsu ga aru nara, hayaku neta hou ga ii desu yo.', NULL, 'Nếu bị sốt thì nên ngủ sớm đấy.', 6480, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16607, 'よる おそく コーヒーを のまない ほうが いいです。', 'yoru osoku koohii o nomanai hou ga ii desu.', NULL, 'Không nên uống cà phê vào đêm khuya.', 6480, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16608, 'これは ははが つくった ケーキです。', 'kore wa haha ga tsukutta keeki desu.', NULL, 'Đây là bánh mẹ tôi làm.', 6481, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16609, 'めがねを かけて いる ひとが やまださんです。', 'megane o kakete iru hito ga yamada-san desu.', NULL, 'Người đeo kính là anh Yamada.', 6481, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16610, 'わたしは えを かくのが すきです。', 'watashi wa e o kaku no ga suki desu.', NULL, 'Tôi thích vẽ tranh.', 6482, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16611, 'ひとりで りょこうするのは たのしいです。', 'hitori de ryokou suru no wa tanoshii desu.', NULL, 'Đi du lịch một mình thì vui.', 6482, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16612, 'でんきを けすのを わすれました。', 'denki o kesu no o wasuremashita.', NULL, 'Tôi quên tắt đèn.', 6483, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16613, 'しゅくだいを だすのを わすれないで ください。', 'shukudai o dasu no o wasurenaide kudasai.', NULL, 'Đừng quên nộp bài tập.', 6483, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16614, 'エアコンを つけた まま ねて しまいました。', 'eakon o tsuketa mama nete shimaimashita.', NULL, 'Tôi lỡ ngủ mà để nguyên điều hòa.', 6484, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16615, 'くつを はいた まま へやに はいらないで ください。', 'kutsu o haita mama heya ni hairanaide kudasai.', NULL, 'Đừng đi nguyên giày vào phòng.', 6484, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16617, 'この ほんは もう よんで しまいました。', 'kono hon wa mou yonde shimaimashita.', NULL, 'Tôi đã đọc hết cuốn sách này rồi.', 6485, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16618, 'パーティーの まえに のみものを かって おきます。', 'paatii no mae ni nomimono o katte okimasu.', NULL, 'Trước bữa tiệc tôi mua sẵn đồ uống.', 6486, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16619, 'つかった あとで、もとの ところに もどして おいて ください。', 'tsukatta ato de, moto no tokoro ni modoshite oite kudasai.', NULL, 'Dùng xong hãy để lại chỗ cũ.', 6486, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16620, 'まどが あけて あります。', 'mado ga akete arimasu.', NULL, 'Cửa sổ đã được mở sẵn.', 6487, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16621, 'カレンダーに よていが かいて あります。', 'karendaa ni yotei ga kaite arimasu.', NULL, 'Lịch trình đã được ghi trên lịch.', 6487, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16622, 'わたしは かんじが 300 ぐらい よめます。', 'watashi wa kanji ga sanbyaku gurai yomemasu.', NULL, 'Tôi đọc được khoảng 300 chữ Hán.', 6488, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16623, 'あしたは こられますか。', 'ashita wa koraremasu ka.', NULL, 'Ngày mai bạn đến được không?', 6488, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16624, 'まどから ふじさんが みえます。', 'mado kara fujisan ga miemasu.', NULL, 'Từ cửa sổ nhìn thấy núi Phú Sĩ.', 6489, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16625, 'となりの へやから ピアノの おとが きこえます。', 'tonari no heya kara piano no oto ga kikoemasu.', NULL, 'Nghe thấy tiếng piano từ phòng bên.', 6489, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16626, 'にほんごが すこし はなせる ように なりました。', 'nihongo ga sukoshi hanaseru you ni narimashita.', NULL, 'Tôi đã nói được một chút tiếng Nhật.', 6490, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16627, 'まいあさ ジョギングする ように なりました。', 'maiasa jogingu suru you ni narimashita.', NULL, 'Tôi đã bắt đầu chạy bộ mỗi sáng.', 6490, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16628, 'やさいを たくさん たべる ように して います。', 'yasai o takusan taberu you ni shite imasu.', NULL, 'Tôi cố gắng ăn nhiều rau.', 6491, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16629, 'じゅぎょうに おくれない ように します。', 'jugyou ni okurenai you ni shimasu.', NULL, 'Tôi sẽ cố không đến lớp muộn.', 6491, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16630, 'へやを あたたかく しました。', 'heya o atatakaku shimashita.', NULL, 'Tôi làm cho căn phòng ấm lên.', 6492, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16631, 'のみものは コーヒーに します。', 'nomimono wa koohii ni shimasu.', NULL, 'Đồ uống thì tôi chọn cà phê.', 6492, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16632, 'らいげつ おおさかに てんきんする ことに なりました。', 'raigetsu oosaka ni tenkin suru koto ni narimashita.', NULL, 'Tháng sau tôi được điều chuyển về Osaka.', 6493, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16633, 'しあいは ちゅうしする ことに なりました。', 'shiai wa chuushi suru koto ni narimashita.', NULL, 'Trận đấu đã được quyết định hủy.', 6493, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16634, 'なつやすみに ベトナムへ かえる ことに しました。', 'natsuyasumi ni betonamu e kaeru koto ni shimashita.', NULL, 'Tôi quyết định về Việt Nam vào kỳ nghỉ hè.', 6494, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16635, 'あしたから タバコを やめる ことに しました。', 'ashita kara tabako o yameru koto ni shimashita.', NULL, 'Tôi quyết định bỏ thuốc lá từ ngày mai.', 6494, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16636, 'ねる まえに にっきを かく ことに して います。', 'neru mae ni nikki o kaku koto ni shite imasu.', NULL, 'Tôi có thói quen viết nhật ký trước khi ngủ.', 6495, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16637, 'しゅうまつは しごとの メールを みない ことに して います。', 'shuumatsu wa shigoto no meeru o minai koto ni shite imasu.', NULL, 'Cuối tuần tôi có nguyên tắc không xem email công việc.', 6495, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16638, 'すこし やすもう。', 'sukoshi yasumou.', NULL, 'Nghỉ một chút đi.', 6496, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16639, 'いっしょに かえろう。', 'issho ni kaerou.', NULL, 'Cùng về nào.', 6496, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16640, 'らいねん だいがくいんに はいろうと おもって います。', 'rainen daigakuin ni hairou to omotte imasu.', NULL, 'Tôi đang định năm sau vào cao học.', 6497, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16641, 'こんばん はやく ねようと おもって います。', 'konban hayaku neyou to omotte imasu.', NULL, 'Tối nay tôi định ngủ sớm.', 6497, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16642, 'なつやすみは アルバイトを する つもりです。', 'natsuyasumi wa arubaito o suru tsumori desu.', NULL, 'Kỳ nghỉ hè tôi dự định làm thêm.', 6498, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16643, 'もう あの みせには いかない つもりです。', 'mou ano mise ni wa ikanai tsumori desu.', NULL, 'Tôi định không đến quán đó nữa.', 6498, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16644, 'かいぎは 3じに おわる よていです。', 'kaigi wa sanji ni owaru yotei desu.', NULL, 'Cuộc họp dự kiến kết thúc lúc 3 giờ.', 6499, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16645, 'らいしゅうから しゅっちょうの よていです。', 'raishuu kara shucchou no yotei desu.', NULL, 'Theo kế hoạch tôi đi công tác từ tuần sau.', 6499, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16646, 'にほんに きた ばかりです。', 'nihon ni kita bakari desu.', NULL, 'Tôi vừa mới đến Nhật.', 6500, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16647, 'さっき ひるごはんを たべた ばかりです。', 'sakki hirugohan o tabeta bakari desu.', NULL, 'Tôi vừa ăn trưa xong lúc nãy.', 6500, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16648, 'いまから でかける ところです。', 'ima kara dekakeru tokoro desu.', NULL, 'Tôi đang chuẩn bị ra ngoài.', 6501, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16649, 'いま しりょうを よんで いる ところです。', 'ima shiryou o yonde iru tokoro desu.', NULL, 'Bây giờ tôi đang đọc tài liệu.', 6501, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16650, 'つかれたら、すこし やすんだら どうですか。', 'tsukaretara, sukoshi yasundara dou desu ka.', NULL, 'Nếu mệt thì nghỉ một chút xem sao?', 6502, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16651, 'せんせいに そうだんしたら どうですか。', 'sensei ni soudan shitara dou desu ka.', NULL, 'Thử hỏi ý kiến thầy xem sao?', 6502, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16652, 'あめが ふったら、しあいは ありません。', 'ame ga futtara, shiai wa arimasen.', NULL, 'Nếu trời mưa thì không có trận đấu.', 6503, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16653, 'うちに ついたら、でんわして ください。', 'uchi ni tsuitara, denwa shite kudasai.', NULL, 'Về đến nhà thì gọi điện cho tôi nhé.', 6503, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16654, 'この ボタンを おせば、きっぷが でます。', 'kono botan o oseba, kippu ga demasu.', NULL, 'Nếu bấm nút này thì vé sẽ ra.', 6504, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16655, 'やすければ、かいたいです。', 'yasukereba, kaitai desu.', NULL, 'Nếu rẻ thì tôi muốn mua.', 6504, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16656, 'この かどを みぎに まがると、えきが あります。', 'kono kado o migi ni magaru to, eki ga arimasu.', NULL, 'Rẽ phải ở góc này thì sẽ thấy nhà ga.', 6505, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16657, 'はるに なると、さくらが さきます。', 'haru ni naru to, sakura ga sakimasu.', NULL, 'Hễ đến mùa xuân là hoa anh đào nở.', 6505, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16658, 'にほんりょうりなら、すしが いちばん すきです。', 'nihon ryouri nara, sushi ga ichiban suki desu.', NULL, 'Nếu là món Nhật thì tôi thích sushi nhất.', 6506, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16659, 'パソコンを かうなら、あの みせが やすいですよ。', 'pasokon o kau nara, ano mise ga yasui desu yo.', NULL, 'Nếu mua máy tính thì cửa hàng kia rẻ đấy.', 6506, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16660, 'あめが ふっても、しごとに いきます。', 'ame ga futte mo, shigoto ni ikimasu.', NULL, 'Dù trời mưa tôi vẫn đi làm.', 6507, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16661, 'いくら かんがえても、わかりません。', 'ikura kangaete mo, wakarimasen.', NULL, 'Nghĩ bao nhiêu cũng không hiểu.', 6507, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16662, 'にほんごは べんきょうすれば するほど おもしろく なります。', 'nihongo wa benkyou sureba suru hodo omoshiroku narimasu.', NULL, 'Tiếng Nhật càng học càng thấy thú vị.', 6508, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16663, 'やさいは あたらしければ あたらしいほど おいしいです。', 'yasai wa atarashikereba atarashii hodo oishii desu.', NULL, 'Rau càng tươi càng ngon.', 6508, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16664, 'かれが くるか どうか わかりません。', 'kare ga kuru ka dou ka wakarimasen.', NULL, 'Tôi không biết anh ấy có đến hay không.', 6509, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16665, 'この くすりが きくか どうか ためして みます。', 'kono kusuri ga kiku ka dou ka tameshite mimasu.', NULL, 'Tôi sẽ thử xem thuốc này có hiệu quả không.', 6509, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16666, 'ともだちが わたしに ほんを くれました。', 'tomodachi ga watashi ni hon o kuremashita.', NULL, 'Bạn tôi đã cho tôi cuốn sách.', 6510, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16667, 'わたしは あねに とけいを もらいました。', 'watashi wa ane ni tokei o moraimashita.', NULL, 'Tôi nhận được đồng hồ từ chị gái.', 6510, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16668, 'いもうとに えほんを よんで あげました。', 'imouto ni ehon o yonde agemashita.', NULL, 'Tôi đọc truyện tranh cho em gái.', 6511, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16669, 'おばあさんの にもつを もって あげました。', 'obaasan no nimotsu o motte agemashita.', NULL, 'Tôi xách đồ giúp bà cụ.', 6511, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16670, 'どうりょうが しごとを てつだって くれました。', 'douryou ga shigoto o tetsudatte kuremashita.', NULL, 'Đồng nghiệp đã giúp tôi làm việc.', 6512, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16671, 'ははが べんとうを つくって くれます。', 'haha ga bentou o tsukutte kuremasu.', NULL, 'Mẹ làm cơm hộp cho tôi.', 6512, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16672, 'せんせいに さくぶんを なおして もらいました。', 'sensei ni sakubun o naoshite moraimashita.', NULL, 'Tôi được thầy sửa bài văn cho.', 6513, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16673, 'ともだちに えきまで おくって もらいました。', 'tomodachi ni eki made okutte moraimashita.', NULL, 'Tôi được bạn đưa ra ga.', 6513, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16674, 'すみません、しゃしんを とって いただけませんか。', 'sumimasen, shashin o totte itadakemasen ka.', NULL, 'Xin lỗi, anh chụp giúp tôi tấm ảnh được không?', 6514, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16675, 'もう すこし ゆっくり はなして いただけませんか。', 'mou sukoshi yukkuri hanashite itadakemasen ka.', NULL, 'Anh có thể nói chậm hơn một chút được không?', 6514, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16676, 'この ことばの いみを おしえて くださいませんか。', 'kono kotoba no imi o oshiete kudasaimasen ka.', NULL, 'Xin chỉ cho tôi nghĩa của từ này được không?', 6515, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16677, 'あした もう いちど きて くださいませんか。', 'ashita mou ichido kite kudasaimasen ka.', NULL, 'Mai anh đến thêm một lần được không?', 6515, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16678, 'わたしは せんせいに ほめられました。', 'watashi wa sensei ni homeraremashita.', NULL, 'Tôi được thầy khen.', 6516, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16679, 'おとうとに ケーキを たべられました。', 'otouto ni keeki o taberaremashita.', NULL, 'Tôi bị em trai ăn mất bánh.', 6516, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16681, '「源氏物語」は むらさきしきぶに よって かかれました。', '"genji monogatari" wa murasaki shikibu ni yotte kakaremashita.', NULL, '"Truyện Genji" được viết bởi Murasaki Shikibu.', 6517, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16682, 'ははは おとうとに へやを そうじさせました。', 'haha wa otouto ni heya o souji sasemashita.', NULL, 'Mẹ bắt em trai dọn phòng.', 6518, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16683, 'こどもを こうえんで あそばせました。', 'kodomo o kouen de asobasemashita.', NULL, 'Tôi cho con chơi ở công viên.', 6518, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16684, 'きょうは はやく かえらせて いただけませんか。', 'kyou wa hayaku kaerasete itadakemasen ka.', NULL, 'Hôm nay cho phép tôi về sớm được không?', 6519, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16685, 'この しりょうを コピーさせて いただけませんか。', 'kono shiryou o kopii sasete itadakemasen ka.', NULL, 'Cho tôi photo tài liệu này được không?', 6519, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16686, 'しゃちょうは もう おかえりに なりました。', 'shachou wa mou okaeri ni narimashita.', NULL, 'Giám đốc đã về rồi ạ.', 6520, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16687, 'この ほんを およみに なりましたか。', 'kono hon o oyomi ni narimashita ka.', NULL, 'Ngài đã đọc cuốn sách này chưa ạ?', 6520, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16688, 'にもつを おもちします。', 'nimotsu o omochi shimasu.', NULL, 'Để tôi xách hành lý giúp ạ.', 6521, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16689, 'あとで おでんわします。', 'ato de odenwa shimasu.', NULL, 'Lát nữa tôi sẽ gọi điện ạ.', 6521, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16690, 'せんせいは けんきゅうしつに いらっしゃいます。', 'sensei wa kenkyuushitsu ni irasshaimasu.', NULL, 'Thầy đang ở phòng nghiên cứu ạ.', 6522, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16691, 'どうぞ めしあがって ください。', 'douzo meshiagatte kudasai.', NULL, 'Xin mời dùng bữa ạ.', 6522, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16692, 'あした 10じに まいります。', 'ashita juuji ni mairimasu.', NULL, 'Ngày mai tôi sẽ đến lúc 10 giờ ạ.', 6523, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16693, 'しりょうを はいけんしました。', 'shiryou o haiken shimashita.', NULL, 'Tôi đã xem tài liệu ạ.', 6523, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16694, 'あしたは あめが ふるでしょう。', 'ashita wa ame ga furu deshou.', NULL, 'Ngày mai có lẽ trời mưa.', 6524, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16695, 'かれは たぶん しらないだろう。', 'kare wa tabun shiranai darou.', NULL, 'Chắc anh ấy không biết đâu.', 6524, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16696, 'ごごから ゆきが ふるかもしれません。', 'gogo kara yuki ga furu kamoshiremasen.', NULL, 'Có thể chiều nay tuyết rơi.', 6525, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16697, 'その はなしは うそかもしれません。', 'sono hanashi wa uso kamoshiremasen.', NULL, 'Câu chuyện đó có thể là nói dối.', 6525, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16698, 'かれは もう ついて いる はずです。', 'kare wa mou tsuite iru hazu desu.', NULL, 'Anh ấy chắc chắn đã đến nơi rồi.', 6526, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16699, 'あの レストランは きょう やすみの はずです。', 'ano resutoran wa kyou yasumi no hazu desu.', NULL, 'Nhà hàng đó hôm nay chắc là nghỉ.', 6526, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16700, 'この ケーキは おいしそうですね。', 'kono keeki wa oishisou desu ne.', NULL, 'Cái bánh này trông ngon nhỉ.', 6527, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16701, 'いまにも あめが ふりそうです。', 'imanimo ame ga furisou desu.', NULL, 'Trời sắp mưa đến nơi.', 6527, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16702, 'てんきよほうに よると、あしたは さむく なるそうです。', 'tenki yohou ni yoru to, ashita wa samuku naru sou desu.', NULL, 'Theo dự báo thời tiết, nghe nói mai trời lạnh.', 6528, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16703, 'たなかさんは らいげつ けっこんするそうです。', 'tanaka-san wa raigetsu kekkon suru sou desu.', NULL, 'Nghe nói tháng sau anh Tanaka cưới.', 6528, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16704, 'だれも いない ようです。', 'daremo inai you desu.', NULL, 'Hình như không có ai.', 6529, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16705, 'かぜを ひいたみたいです。', 'kaze o hiita mitai desu.', NULL, 'Hình như tôi bị cảm rồi.', 6529, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16706, 'あの みせは らいしゅう しまるらしいです。', 'ano mise wa raishuu shimaru rashii desu.', NULL, 'Nghe đâu cửa hàng đó tuần sau đóng cửa.', 6530, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16707, 'やまださんは ねこが すきらしいです。', 'yamada-san wa neko ga suki rashii desu.', NULL, 'Có vẻ anh Yamada thích mèo.', 6530, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16708, '「さくら」という レストランを しって いますか。', '"sakura" to iu resutoran o shitte imasu ka.', NULL, 'Bạn có biết nhà hàng tên "Sakura" không?', 6531, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16709, 'これは おりがみと いう あそびです。', 'kore wa origami to iu asobi desu.', NULL, 'Đây là trò chơi gọi là origami.', 6531, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16710, 'リンさんは すこし おくれると いって いました。', 'rin-san wa sukoshi okureru to itte imashita.', NULL, 'Chị Linh nói là sẽ đến muộn một chút.', 6532, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16711, 'あしたの かいぎは 2じからだと つたえて ください。', 'ashita no kaigi wa niji kara da to tsutaete kudasai.', NULL, 'Nhắn giúp là cuộc họp mai bắt đầu từ 2 giờ.', 6532, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16712, 'いえを かう ために ちょきんして います。', 'ie o kau tame ni chokin shite imasu.', NULL, 'Tôi đang tiết kiệm để mua nhà.', 6533, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16713, 'けんこうの ために まいにち あるきます。', 'kenkou no tame ni mainichi arukimasu.', NULL, 'Vì sức khỏe, hằng ngày tôi đi bộ.', 6533, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16714, 'うしろの ひとにも きこえる ように おおきい こえで はなします。', 'ushiro no hito ni mo kikoeru you ni ookii koe de hanashimasu.', NULL, 'Tôi nói to để người phía sau cũng nghe thấy.', 6534, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16715, 'かぜを ひかない ように あたたかく して ください。', 'kaze o hikanai you ni atatakaku shite kudasai.', NULL, 'Hãy giữ ấm để không bị cảm.', 6534, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16716, 'ゆうべ のみすぎました。', 'yuube nomisugimashita.', NULL, 'Tối qua tôi uống quá nhiều.', 6535, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16717, 'この もんだいは むずかしすぎます。', 'kono mondai wa muzukashisugimasu.', NULL, 'Câu hỏi này khó quá.', 6535, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16718, 'この ペンは かきやすいです。', 'kono pen wa kakiyasui desu.', NULL, 'Cây bút này dễ viết.', 6536, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16719, 'この くすりは のみにくいです。', 'kono kusuri wa nominikui desu.', NULL, 'Thuốc này khó uống.', 6536, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16720, 'ぞうは はなが ながいです。', 'zou wa hana ga nagai desu.', NULL, 'Con voi có cái vòi dài.', 6537, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16721, 'この まちは こうつうが べんりです。', 'kono machi wa koutsuu ga benri desu.', NULL, 'Thị trấn này giao thông thuận tiện.', 6537, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16722, 'おとうとは ゲームばかり して います。', 'otouto wa geemu bakari shite imasu.', NULL, 'Em trai tôi chỉ toàn chơi game.', 6538, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16723, 'かれは あそんで ばかり いて、ぜんぜん べんきょうしません。', 'kare wa asonde bakari ite, zenzen benkyou shimasen.', NULL, 'Anh ta chỉ toàn chơi, chẳng học gì cả.', 6538, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16724, 'さいふに 500えんしか ありません。', 'saifu ni gohyakuen shika arimasen.', NULL, 'Trong ví chỉ có 500 yên.', 6539, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16725, 'にほんごは すこししか はなせません。', 'nihongo wa sukoshi shika hanasemasen.', NULL, 'Tôi chỉ nói được chút ít tiếng Nhật.', 6539, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16726, 'きのうは 10じかんも ねました。', 'kinou wa juujikan mo nemashita.', NULL, 'Hôm qua tôi ngủ tới 10 tiếng.', 6540, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16727, 'この かばんは 5まんえんも しました。', 'kono kaban wa goman en mo shimashita.', NULL, 'Cái túi này đắt tới 50.000 yên.', 6540, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16728, 'ペンで かいても いいです。', 'pen de kaite mo ii desu.', NULL, 'Viết bằng bút mực cũng được.', 6541, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16729, 'いそがしければ、こなくても かまいません。', 'isogashikereba, konakute mo kamaimasen.', NULL, 'Nếu bận thì không đến cũng không sao.', 6541, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16730, 'この アパートは えきに ちかいし、やすいし、いいですね。', 'kono apaato wa eki ni chikai shi, yasui shi, ii desu ne.', NULL, 'Căn hộ này vừa gần ga lại rẻ, tốt nhỉ.', 6542, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16731, 'きょうは ねつも あるし、あたまも いたいし、やすみます。', 'kyou wa netsu mo aru shi, atama mo itai shi, yasumimasu.', NULL, 'Hôm nay vừa sốt vừa đau đầu nên tôi nghỉ.', 6542, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16732, 'でんしゃが おくれたので、ちこくしました。', 'densha ga okureta node, chikoku shimashita.', NULL, 'Vì tàu trễ nên tôi đến muộn.', 6543, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16733, 'あしたは しけんなので、こんばんは べんきょうします。', 'ashita wa shiken na node, konban wa benkyou shimasu.', NULL, 'Vì mai thi nên tối nay tôi học.', 6543, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16734, 'いっしょうけんめい べんきょうしたのに、ごうかくできませんでした。', 'isshoukenmei benkyou shita noni, goukaku dekimasen deshita.', NULL, 'Học chăm chỉ vậy mà vẫn không đỗ.', 6544, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16735, 'やくそくしたのに、かれは こなかった。', 'yakusoku shita noni, kare wa konakatta.', NULL, 'Đã hứa rồi vậy mà anh ta không đến.', 6544, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16736, 'にほんへ いく とき、かばんを かいました。', 'nihon e iku toki, kaban o kaimashita.', NULL, 'Khi (trước lúc) đi Nhật, tôi đã mua cặp.', 6545, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16737, 'にほんへ いった とき、かばんを かいました。', 'nihon e itta toki, kaban o kaimashita.', NULL, 'Khi (đã) sang Nhật, tôi đã mua cặp.', 6545, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16738, 'アルバイトを しながら だいがくに かよって います。', 'arubaito o shinagara daigaku ni kayotte imasu.', NULL, 'Tôi vừa làm thêm vừa đi học đại học.', 6546, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16739, 'はたらきながら こどもを そだてて います。', 'hatarakinagara kodomo o sodatete imasu.', NULL, 'Tôi vừa làm việc vừa nuôi con.', 6546, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16740, 'どう すれば いいですか。', 'dou sureba ii desu ka.', NULL, 'Tôi nên làm thế nào thì được?', 6547, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16741, 'ここに なまえを かけば いいです。', 'koko ni namae o kakeba ii desu.', NULL, 'Chỉ cần viết tên vào đây là được.', 6547, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16742, 'あした、うちに いる？', 'ashita, uchi ni iru?', NULL, 'Mai cậu có ở nhà không?', 6548, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16743, 'きのうは いそがしかった。', 'kinou wa isogashikatta.', NULL, 'Hôm qua bận lắm.', 6548, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16744, 'ねつが あるなら、はやく ねた ほうが いいですよ。', 'netsu ga aru nara, hayaku neta hou ga ii desu yo.', NULL, 'Nếu bị sốt thì nên ngủ sớm đấy.', 6549, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16745, 'よる おそく コーヒーを のまない ほうが いいです。', 'yoru osoku koohii o nomanai hou ga ii desu.', NULL, 'Không nên uống cà phê vào đêm khuya.', 6549, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16746, 'これは ははが つくった ケーキです。', 'kore wa haha ga tsukutta keeki desu.', NULL, 'Đây là bánh mẹ tôi làm.', 6550, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16747, 'めがねを かけて いる ひとが やまださんです。', 'megane o kakete iru hito ga yamada-san desu.', NULL, 'Người đeo kính là anh Yamada.', 6550, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16748, 'わたしは えを かくのが すきです。', 'watashi wa e o kaku no ga suki desu.', NULL, 'Tôi thích vẽ tranh.', 6551, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16749, 'ひとりで りょこうするのは たのしいです。', 'hitori de ryokou suru no wa tanoshii desu.', NULL, 'Đi du lịch một mình thì vui.', 6551, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16750, 'でんきを けすのを わすれました。', 'denki o kesu no o wasuremashita.', NULL, 'Tôi quên tắt đèn.', 6552, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16751, 'しゅくだいを だすのを わすれないで ください。', 'shukudai o dasu no o wasurenaide kudasai.', NULL, 'Đừng quên nộp bài tập.', 6552, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16752, 'エアコンを つけた まま ねて しまいました。', 'eakon o tsuketa mama nete shimaimashita.', NULL, 'Tôi lỡ ngủ mà để nguyên điều hòa.', 6553, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16753, 'くつを はいた まま へやに はいらないで ください。', 'kutsu o haita mama heya ni hairanaide kudasai.', NULL, 'Đừng đi nguyên giày vào phòng.', 6553, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16754, 'でんしゃに かさを わすれて しまいました。', 'densha ni kasa o wasurete shimaimashita.', NULL, 'Tôi lỡ để quên ô trên tàu.', 6554, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16755, 'この ほんは もう よんで しまいました。', 'kono hon wa mou yonde shimaimashita.', NULL, 'Tôi đã đọc hết cuốn sách này rồi.', 6554, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16756, 'パーティーの まえに のみものを かって おきます。', 'paatii no mae ni nomimono o katte okimasu.', NULL, 'Trước bữa tiệc tôi mua sẵn đồ uống.', 6555, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16757, 'つかった あとで、もとの ところに もどして おいて ください。', 'tsukatta ato de, moto no tokoro ni modoshite oite kudasai.', NULL, 'Dùng xong hãy để lại chỗ cũ.', 6555, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16758, 'まどが あけて あります。', 'mado ga akete arimasu.', NULL, 'Cửa sổ đã được mở sẵn.', 6556, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16759, 'カレンダーに よていが かいて あります。', 'karendaa ni yotei ga kaite arimasu.', NULL, 'Lịch trình đã được ghi trên lịch.', 6556, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16760, 'わたしは かんじが 300 ぐらい よめます。', 'watashi wa kanji ga sanbyaku gurai yomemasu.', NULL, 'Tôi đọc được khoảng 300 chữ Hán.', 6557, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16761, 'あしたは こられますか。', 'ashita wa koraremasu ka.', NULL, 'Ngày mai bạn đến được không?', 6557, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16762, 'まどから ふじさんが みえます。', 'mado kara fujisan ga miemasu.', NULL, 'Từ cửa sổ nhìn thấy núi Phú Sĩ.', 6558, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16763, 'となりの へやから ピアノの おとが きこえます。', 'tonari no heya kara piano no oto ga kikoemasu.', NULL, 'Nghe thấy tiếng piano từ phòng bên.', 6558, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16764, 'にほんごが すこし はなせる ように なりました。', 'nihongo ga sukoshi hanaseru you ni narimashita.', NULL, 'Tôi đã nói được một chút tiếng Nhật.', 6559, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16765, 'まいあさ ジョギングする ように なりました。', 'maiasa jogingu suru you ni narimashita.', NULL, 'Tôi đã bắt đầu chạy bộ mỗi sáng.', 6559, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16766, 'やさいを たくさん たべる ように して います。', 'yasai o takusan taberu you ni shite imasu.', NULL, 'Tôi cố gắng ăn nhiều rau.', 6560, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16767, 'じゅぎょうに おくれない ように します。', 'jugyou ni okurenai you ni shimasu.', NULL, 'Tôi sẽ cố không đến lớp muộn.', 6560, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16768, 'へやを あたたかく しました。', 'heya o atatakaku shimashita.', NULL, 'Tôi làm cho căn phòng ấm lên.', 6561, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16769, 'のみものは コーヒーに します。', 'nomimono wa koohii ni shimasu.', NULL, 'Đồ uống thì tôi chọn cà phê.', 6561, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16770, 'らいげつ おおさかに てんきんする ことに なりました。', 'raigetsu oosaka ni tenkin suru koto ni narimashita.', NULL, 'Tháng sau tôi được điều chuyển về Osaka.', 6562, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16771, 'しあいは ちゅうしする ことに なりました。', 'shiai wa chuushi suru koto ni narimashita.', NULL, 'Trận đấu đã được quyết định hủy.', 6562, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16772, 'なつやすみに ベトナムへ かえる ことに しました。', 'natsuyasumi ni betonamu e kaeru koto ni shimashita.', NULL, 'Tôi quyết định về Việt Nam vào kỳ nghỉ hè.', 6563, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16773, 'あしたから タバコを やめる ことに しました。', 'ashita kara tabako o yameru koto ni shimashita.', NULL, 'Tôi quyết định bỏ thuốc lá từ ngày mai.', 6563, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16774, 'ねる まえに にっきを かく ことに して います。', 'neru mae ni nikki o kaku koto ni shite imasu.', NULL, 'Tôi có thói quen viết nhật ký trước khi ngủ.', 6564, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16775, 'しゅうまつは しごとの メールを みない ことに して います。', 'shuumatsu wa shigoto no meeru o minai koto ni shite imasu.', NULL, 'Cuối tuần tôi có nguyên tắc không xem email công việc.', 6564, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16776, 'すこし やすもう。', 'sukoshi yasumou.', NULL, 'Nghỉ một chút đi.', 6565, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16777, 'いっしょに かえろう。', 'issho ni kaerou.', NULL, 'Cùng về nào.', 6565, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16778, 'らいねん だいがくいんに はいろうと おもって います。', 'rainen daigakuin ni hairou to omotte imasu.', NULL, 'Tôi đang định năm sau vào cao học.', 6566, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16779, 'こんばん はやく ねようと おもって います。', 'konban hayaku neyou to omotte imasu.', NULL, 'Tối nay tôi định ngủ sớm.', 6566, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16780, 'なつやすみは アルバイトを する つもりです。', 'natsuyasumi wa arubaito o suru tsumori desu.', NULL, 'Kỳ nghỉ hè tôi dự định làm thêm.', 6567, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16781, 'もう あの みせには いかない つもりです。', 'mou ano mise ni wa ikanai tsumori desu.', NULL, 'Tôi định không đến quán đó nữa.', 6567, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16782, 'かいぎは 3じに おわる よていです。', 'kaigi wa sanji ni owaru yotei desu.', NULL, 'Cuộc họp dự kiến kết thúc lúc 3 giờ.', 6568, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16783, 'らいしゅうから しゅっちょうの よていです。', 'raishuu kara shucchou no yotei desu.', NULL, 'Theo kế hoạch tôi đi công tác từ tuần sau.', 6568, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16784, 'にほんに きた ばかりです。', 'nihon ni kita bakari desu.', NULL, 'Tôi vừa mới đến Nhật.', 6569, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16785, 'さっき ひるごはんを たべた ばかりです。', 'sakki hirugohan o tabeta bakari desu.', NULL, 'Tôi vừa ăn trưa xong lúc nãy.', 6569, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16786, 'いまから でかける ところです。', 'ima kara dekakeru tokoro desu.', NULL, 'Tôi đang chuẩn bị ra ngoài.', 6570, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16787, 'いま しりょうを よんで いる ところです。', 'ima shiryou o yonde iru tokoro desu.', NULL, 'Bây giờ tôi đang đọc tài liệu.', 6570, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16788, 'つかれたら、すこし やすんだら どうですか。', 'tsukaretara, sukoshi yasundara dou desu ka.', NULL, 'Nếu mệt thì nghỉ một chút xem sao?', 6571, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16789, 'せんせいに そうだんしたら どうですか。', 'sensei ni soudan shitara dou desu ka.', NULL, 'Thử hỏi ý kiến thầy xem sao?', 6571, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16790, 'あめが ふったら、しあいは ありません。', 'ame ga futtara, shiai wa arimasen.', NULL, 'Nếu trời mưa thì không có trận đấu.', 6572, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16791, 'うちに ついたら、でんわして ください。', 'uchi ni tsuitara, denwa shite kudasai.', NULL, 'Về đến nhà thì gọi điện cho tôi nhé.', 6572, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16792, 'この ボタンを おせば、きっぷが でます。', 'kono botan o oseba, kippu ga demasu.', NULL, 'Nếu bấm nút này thì vé sẽ ra.', 6573, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16793, 'やすければ、かいたいです。', 'yasukereba, kaitai desu.', NULL, 'Nếu rẻ thì tôi muốn mua.', 6573, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16794, 'この かどを みぎに まがると、えきが あります。', 'kono kado o migi ni magaru to, eki ga arimasu.', NULL, 'Rẽ phải ở góc này thì sẽ thấy nhà ga.', 6574, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16795, 'はるに なると、さくらが さきます。', 'haru ni naru to, sakura ga sakimasu.', NULL, 'Hễ đến mùa xuân là hoa anh đào nở.', 6574, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16796, 'にほんりょうりなら、すしが いちばん すきです。', 'nihon ryouri nara, sushi ga ichiban suki desu.', NULL, 'Nếu là món Nhật thì tôi thích sushi nhất.', 6575, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16797, 'パソコンを かうなら、あの みせが やすいですよ。', 'pasokon o kau nara, ano mise ga yasui desu yo.', NULL, 'Nếu mua máy tính thì cửa hàng kia rẻ đấy.', 6575, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16798, 'あめが ふっても、しごとに いきます。', 'ame ga futte mo, shigoto ni ikimasu.', NULL, 'Dù trời mưa tôi vẫn đi làm.', 6576, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16799, 'いくら かんがえても、わかりません。', 'ikura kangaete mo, wakarimasen.', NULL, 'Nghĩ bao nhiêu cũng không hiểu.', 6576, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16800, 'にほんごは べんきょうすれば するほど おもしろく なります。', 'nihongo wa benkyou sureba suru hodo omoshiroku narimasu.', NULL, 'Tiếng Nhật càng học càng thấy thú vị.', 6577, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16801, 'やさいは あたらしければ あたらしいほど おいしいです。', 'yasai wa atarashikereba atarashii hodo oishii desu.', NULL, 'Rau càng tươi càng ngon.', 6577, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16802, 'かれが くるか どうか わかりません。', 'kare ga kuru ka dou ka wakarimasen.', NULL, 'Tôi không biết anh ấy có đến hay không.', 6578, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16803, 'この くすりが きくか どうか ためして みます。', 'kono kusuri ga kiku ka dou ka tameshite mimasu.', NULL, 'Tôi sẽ thử xem thuốc này có hiệu quả không.', 6578, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16804, 'ともだちが わたしに ほんを くれました。', 'tomodachi ga watashi ni hon o kuremashita.', NULL, 'Bạn tôi đã cho tôi cuốn sách.', 6579, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16805, 'わたしは あねに とけいを もらいました。', 'watashi wa ane ni tokei o moraimashita.', NULL, 'Tôi nhận được đồng hồ từ chị gái.', 6579, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16806, 'いもうとに えほんを よんで あげました。', 'imouto ni ehon o yonde agemashita.', NULL, 'Tôi đọc truyện tranh cho em gái.', 6580, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16807, 'おばあさんの にもつを もって あげました。', 'obaasan no nimotsu o motte agemashita.', NULL, 'Tôi xách đồ giúp bà cụ.', 6580, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16808, 'どうりょうが しごとを てつだって くれました。', 'douryou ga shigoto o tetsudatte kuremashita.', NULL, 'Đồng nghiệp đã giúp tôi làm việc.', 6581, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16809, 'ははが べんとうを つくって くれます。', 'haha ga bentou o tsukutte kuremasu.', NULL, 'Mẹ làm cơm hộp cho tôi.', 6581, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16810, 'せんせいに さくぶんを なおして もらいました。', 'sensei ni sakubun o naoshite moraimashita.', NULL, 'Tôi được thầy sửa bài văn cho.', 6582, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16811, 'ともだちに えきまで おくって もらいました。', 'tomodachi ni eki made okutte moraimashita.', NULL, 'Tôi được bạn đưa ra ga.', 6582, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16812, 'すみません、しゃしんを とって いただけませんか。', 'sumimasen, shashin o totte itadakemasen ka.', NULL, 'Xin lỗi, anh chụp giúp tôi tấm ảnh được không?', 6583, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16813, 'もう すこし ゆっくり はなして いただけませんか。', 'mou sukoshi yukkuri hanashite itadakemasen ka.', NULL, 'Anh có thể nói chậm hơn một chút được không?', 6583, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16814, 'この ことばの いみを おしえて くださいませんか。', 'kono kotoba no imi o oshiete kudasaimasen ka.', NULL, 'Xin chỉ cho tôi nghĩa của từ này được không?', 6584, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16815, 'あした もう いちど きて くださいませんか。', 'ashita mou ichido kite kudasaimasen ka.', NULL, 'Mai anh đến thêm một lần được không?', 6584, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16816, 'わたしは せんせいに ほめられました。', 'watashi wa sensei ni homeraremashita.', NULL, 'Tôi được thầy khen.', 6585, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16817, 'おとうとに ケーキを たべられました。', 'otouto ni keeki o taberaremashita.', NULL, 'Tôi bị em trai ăn mất bánh.', 6585, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16819, '「源氏物語」は むらさきしきぶに よって かかれました。', '"genji monogatari" wa murasaki shikibu ni yotte kakaremashita.', NULL, '"Truyện Genji" được viết bởi Murasaki Shikibu.', 6586, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16820, 'ははは おとうとに へやを そうじさせました。', 'haha wa otouto ni heya o souji sasemashita.', NULL, 'Mẹ bắt em trai dọn phòng.', 6587, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16821, 'こどもを こうえんで あそばせました。', 'kodomo o kouen de asobasemashita.', NULL, 'Tôi cho con chơi ở công viên.', 6587, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16822, 'きょうは はやく かえらせて いただけませんか。', 'kyou wa hayaku kaerasete itadakemasen ka.', NULL, 'Hôm nay cho phép tôi về sớm được không?', 6588, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16823, 'この しりょうを コピーさせて いただけませんか。', 'kono shiryou o kopii sasete itadakemasen ka.', NULL, 'Cho tôi photo tài liệu này được không?', 6588, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16824, 'しゃちょうは もう おかえりに なりました。', 'shachou wa mou okaeri ni narimashita.', NULL, 'Giám đốc đã về rồi ạ.', 6589, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16825, 'この ほんを およみに なりましたか。', 'kono hon o oyomi ni narimashita ka.', NULL, 'Ngài đã đọc cuốn sách này chưa ạ?', 6589, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16826, 'にもつを おもちします。', 'nimotsu o omochi shimasu.', NULL, 'Để tôi xách hành lý giúp ạ.', 6590, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16827, 'あとで おでんわします。', 'ato de odenwa shimasu.', NULL, 'Lát nữa tôi sẽ gọi điện ạ.', 6590, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16828, 'せんせいは けんきゅうしつに いらっしゃいます。', 'sensei wa kenkyuushitsu ni irasshaimasu.', NULL, 'Thầy đang ở phòng nghiên cứu ạ.', 6591, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16829, 'どうぞ めしあがって ください。', 'douzo meshiagatte kudasai.', NULL, 'Xin mời dùng bữa ạ.', 6591, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16830, 'あした 10じに まいります。', 'ashita juuji ni mairimasu.', NULL, 'Ngày mai tôi sẽ đến lúc 10 giờ ạ.', 6592, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16831, 'しりょうを はいけんしました。', 'shiryou o haiken shimashita.', NULL, 'Tôi đã xem tài liệu ạ.', 6592, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16832, 'あしたは あめが ふるでしょう。', 'ashita wa ame ga furu deshou.', NULL, 'Ngày mai có lẽ trời mưa.', 6593, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16833, 'かれは たぶん しらないだろう。', 'kare wa tabun shiranai darou.', NULL, 'Chắc anh ấy không biết đâu.', 6593, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16834, 'ごごから ゆきが ふるかもしれません。', 'gogo kara yuki ga furu kamoshiremasen.', NULL, 'Có thể chiều nay tuyết rơi.', 6594, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16835, 'その はなしは うそかもしれません。', 'sono hanashi wa uso kamoshiremasen.', NULL, 'Câu chuyện đó có thể là nói dối.', 6594, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16836, 'かれは もう ついて いる はずです。', 'kare wa mou tsuite iru hazu desu.', NULL, 'Anh ấy chắc chắn đã đến nơi rồi.', 6595, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16837, 'あの レストランは きょう やすみの はずです。', 'ano resutoran wa kyou yasumi no hazu desu.', NULL, 'Nhà hàng đó hôm nay chắc là nghỉ.', 6595, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16838, 'この ケーキは おいしそうですね。', 'kono keeki wa oishisou desu ne.', NULL, 'Cái bánh này trông ngon nhỉ.', 6596, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16839, 'いまにも あめが ふりそうです。', 'imanimo ame ga furisou desu.', NULL, 'Trời sắp mưa đến nơi.', 6596, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16840, 'てんきよほうに よると、あしたは さむく なるそうです。', 'tenki yohou ni yoru to, ashita wa samuku naru sou desu.', NULL, 'Theo dự báo thời tiết, nghe nói mai trời lạnh.', 6597, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16841, 'たなかさんは らいげつ けっこんするそうです。', 'tanaka-san wa raigetsu kekkon suru sou desu.', NULL, 'Nghe nói tháng sau anh Tanaka cưới.', 6597, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16842, 'だれも いない ようです。', 'daremo inai you desu.', NULL, 'Hình như không có ai.', 6598, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16843, 'かぜを ひいたみたいです。', 'kaze o hiita mitai desu.', NULL, 'Hình như tôi bị cảm rồi.', 6598, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16844, 'あの みせは らいしゅう しまるらしいです。', 'ano mise wa raishuu shimaru rashii desu.', NULL, 'Nghe đâu cửa hàng đó tuần sau đóng cửa.', 6599, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16845, 'やまださんは ねこが すきらしいです。', 'yamada-san wa neko ga suki rashii desu.', NULL, 'Có vẻ anh Yamada thích mèo.', 6599, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16846, '「さくら」という レストランを しって いますか。', '"sakura" to iu resutoran o shitte imasu ka.', NULL, 'Bạn có biết nhà hàng tên "Sakura" không?', 6600, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16847, 'これは おりがみと いう あそびです。', 'kore wa origami to iu asobi desu.', NULL, 'Đây là trò chơi gọi là origami.', 6600, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16848, 'リンさんは すこし おくれると いって いました。', 'rin-san wa sukoshi okureru to itte imashita.', NULL, 'Chị Linh nói là sẽ đến muộn một chút.', 6601, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16849, 'あしたの かいぎは 2じからだと つたえて ください。', 'ashita no kaigi wa niji kara da to tsutaete kudasai.', NULL, 'Nhắn giúp là cuộc họp mai bắt đầu từ 2 giờ.', 6601, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16850, 'いえを かう ために ちょきんして います。', 'ie o kau tame ni chokin shite imasu.', NULL, 'Tôi đang tiết kiệm để mua nhà.', 6602, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16851, 'けんこうの ために まいにち あるきます。', 'kenkou no tame ni mainichi arukimasu.', NULL, 'Vì sức khỏe, hằng ngày tôi đi bộ.', 6602, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16852, 'うしろの ひとにも きこえる ように おおきい こえで はなします。', 'ushiro no hito ni mo kikoeru you ni ookii koe de hanashimasu.', NULL, 'Tôi nói to để người phía sau cũng nghe thấy.', 6603, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16853, 'かぜを ひかない ように あたたかく して ください。', 'kaze o hikanai you ni atatakaku shite kudasai.', NULL, 'Hãy giữ ấm để không bị cảm.', 6603, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16854, 'ゆうべ のみすぎました。', 'yuube nomisugimashita.', NULL, 'Tối qua tôi uống quá nhiều.', 6604, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16855, 'この もんだいは むずかしすぎます。', 'kono mondai wa muzukashisugimasu.', NULL, 'Câu hỏi này khó quá.', 6604, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16856, 'この ペンは かきやすいです。', 'kono pen wa kakiyasui desu.', NULL, 'Cây bút này dễ viết.', 6605, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16857, 'この くすりは のみにくいです。', 'kono kusuri wa nominikui desu.', NULL, 'Thuốc này khó uống.', 6605, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16858, 'ぞうは はなが ながいです。', 'zou wa hana ga nagai desu.', NULL, 'Con voi có cái vòi dài.', 6606, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17392, 'かれは ねて いる ふりを して いる。', 'kare wa nete iru furi o shite iru.', NULL, 'Anh ấy đang giả vờ ngủ.', 6873, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16859, 'この まちは こうつうが べんりです。', 'kono machi wa koutsuu ga benri desu.', NULL, 'Thị trấn này giao thông thuận tiện.', 6606, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16860, 'おとうとは ゲームばかり して います。', 'otouto wa geemu bakari shite imasu.', NULL, 'Em trai tôi chỉ toàn chơi game.', 6607, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16861, 'かれは あそんで ばかり いて、ぜんぜん べんきょうしません。', 'kare wa asonde bakari ite, zenzen benkyou shimasen.', NULL, 'Anh ta chỉ toàn chơi, chẳng học gì cả.', 6607, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16862, 'さいふに 500えんしか ありません。', 'saifu ni gohyakuen shika arimasen.', NULL, 'Trong ví chỉ có 500 yên.', 6608, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16863, 'にほんごは すこししか はなせません。', 'nihongo wa sukoshi shika hanasemasen.', NULL, 'Tôi chỉ nói được chút ít tiếng Nhật.', 6608, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16864, 'きのうは 10じかんも ねました。', 'kinou wa juujikan mo nemashita.', NULL, 'Hôm qua tôi ngủ tới 10 tiếng.', 6609, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16865, 'この かばんは 5まんえんも しました。', 'kono kaban wa goman en mo shimashita.', NULL, 'Cái túi này đắt tới 50.000 yên.', 6609, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16866, 'ペンで かいても いいです。', 'pen de kaite mo ii desu.', NULL, 'Viết bằng bút mực cũng được.', 6610, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16867, 'いそがしければ、こなくても かまいません。', 'isogashikereba, konakute mo kamaimasen.', NULL, 'Nếu bận thì không đến cũng không sao.', 6610, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16868, 'この アパートは えきに ちかいし、やすいし、いいですね。', 'kono apaato wa eki ni chikai shi, yasui shi, ii desu ne.', NULL, 'Căn hộ này vừa gần ga lại rẻ, tốt nhỉ.', 6611, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16869, 'きょうは ねつも あるし、あたまも いたいし、やすみます。', 'kyou wa netsu mo aru shi, atama mo itai shi, yasumimasu.', NULL, 'Hôm nay vừa sốt vừa đau đầu nên tôi nghỉ.', 6611, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16870, 'でんしゃが おくれたので、ちこくしました。', 'densha ga okureta node, chikoku shimashita.', NULL, 'Vì tàu trễ nên tôi đến muộn.', 6612, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16871, 'あしたは しけんなので、こんばんは べんきょうします。', 'ashita wa shiken na node, konban wa benkyou shimasu.', NULL, 'Vì mai thi nên tối nay tôi học.', 6612, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16872, 'いっしょうけんめい べんきょうしたのに、ごうかくできませんでした。', 'isshoukenmei benkyou shita noni, goukaku dekimasen deshita.', NULL, 'Học chăm chỉ vậy mà vẫn không đỗ.', 6613, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16873, 'やくそくしたのに、かれは こなかった。', 'yakusoku shita noni, kare wa konakatta.', NULL, 'Đã hứa rồi vậy mà anh ta không đến.', 6613, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16874, 'にほんへ いく とき、かばんを かいました。', 'nihon e iku toki, kaban o kaimashita.', NULL, 'Khi (trước lúc) đi Nhật, tôi đã mua cặp.', 6614, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16875, 'にほんへ いった とき、かばんを かいました。', 'nihon e itta toki, kaban o kaimashita.', NULL, 'Khi (đã) sang Nhật, tôi đã mua cặp.', 6614, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16876, 'アルバイトを しながら だいがくに かよって います。', 'arubaito o shinagara daigaku ni kayotte imasu.', NULL, 'Tôi vừa làm thêm vừa đi học đại học.', 6615, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16877, 'はたらきながら こどもを そだてて います。', 'hatarakinagara kodomo o sodatete imasu.', NULL, 'Tôi vừa làm việc vừa nuôi con.', 6615, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16878, 'どう すれば いいですか。', 'dou sureba ii desu ka.', NULL, 'Tôi nên làm thế nào thì được?', 6616, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16879, 'ここに なまえを かけば いいです。', 'koko ni namae o kakeba ii desu.', NULL, 'Chỉ cần viết tên vào đây là được.', 6616, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16880, 'ねぼうした せいで、でんしゃに のりおくれた。', 'nebou shita sei de, densha ni noriokureta.', NULL, 'Tại ngủ quên nên tôi lỡ tàu.', 6617, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16881, 'あめの せいで、しあいが ちゅうしに なった。', 'ame no sei de, shiai ga chuushi ni natta.', NULL, 'Tại mưa nên trận đấu bị hủy.', 6617, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16882, 'せんせいの おかげで、ごうかくできました。', 'sensei no okage de, goukaku dekimashita.', NULL, 'Nhờ thầy mà tôi đã đỗ.', 6618, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16883, 'くすりを のんだ おかげで、ねつが さがった。', 'kusuri o nonda okage de, netsu ga sagatta.', NULL, 'Nhờ uống thuốc mà hạ sốt.', 6618, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16884, 'じしんに よって、おおくの いえが たおれた。', 'jishin ni yotte, ooku no ie ga taoreta.', NULL, 'Do động đất, nhiều ngôi nhà bị đổ.', 6619, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16885, 'ふちゅういに よる じこが ふえて いる。', 'fuchuui ni yoru jiko ga fuete iru.', NULL, 'Tai nạn do bất cẩn đang tăng lên.', 6619, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16886, 'おおゆきの ため、でんしゃが とまって います。', 'ooyuki no tame, densha ga tomatte imasu.', NULL, 'Vì tuyết lớn nên tàu đang ngừng chạy.', 6620, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16887, 'こうじちゅうの ため、この みちは とおれません。', 'koujichuu no tame, kono michi wa tooremasen.', NULL, 'Vì đang thi công nên không đi qua đường này được.', 6620, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16888, 'あなたの ことを しんぱいして いる から こそ、ちゅういするのです。', 'anata no koto o shinpai shite iru kara koso, chuui suru no desu.', NULL, 'Chính vì lo cho bạn nên tôi mới nhắc nhở.', 6621, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16889, 'むずかしい から こそ、やる かちが ある。', 'muzukashii kara koso, yaru kachi ga aru.', NULL, 'Chính vì khó nên mới đáng làm.', 6621, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16890, 'わすれない ように、メモして おきます。', 'wasurenai you ni, memo shite okimasu.', NULL, 'Tôi ghi chú lại để khỏi quên.', 6622, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16891, 'だれでも わかる ように、やさしく せつめいした。', 'daredemo wakaru you ni, yasashiku setsumei shita.', NULL, 'Tôi giải thích dễ hiểu để ai cũng hiểu được.', 6622, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16892, 'かたちが にて いる ことから、この なまえが ついた。', 'katachi ga nite iru koto kara, kono namae ga tsuita.', NULL, 'Vì hình dạng giống nên mới có tên này.', 6623, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16893, 'へやの でんきが ついて いる ことから、かれは いえに いると わかった。', 'heya no denki ga tsuite iru koto kara, kare wa ie ni iru to wakatta.', NULL, 'Từ việc đèn phòng đang bật, tôi biết anh ấy ở nhà.', 6623, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16894, '10ねんも にほんに すんで いたのか。にほんごが じょうずな わけだ。', 'juunen mo nihon ni sunde ita no ka. nihongo ga jouzu na wake da.', NULL, 'Sống ở Nhật tận 10 năm à. Thảo nào tiếng Nhật giỏi.', 6624, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16895, 'エアコンが こわれて いる。あつい わけだ。', 'eakon ga kowarete iru. atsui wake da.', NULL, 'Điều hòa hỏng rồi. Thảo nào nóng.', 6624, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16896, 'もう すこしで くるまに ひかれる ところだった。', 'mou sukoshi de kuruma ni hikareru tokoro datta.', NULL, 'Suýt nữa thì bị xe tông.', 6625, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16897, 'めざましが なかったら、ちこくする ところだった。', 'mezamashi ga nakattara, chikoku suru tokoro datta.', NULL, 'Nếu không có đồng hồ báo thức thì suýt muộn rồi.', 6625, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16898, 'いま べんきょうしないと、あとで こまる ことに なる。', 'ima benkyou shinai to, ato de komaru koto ni naru.', NULL, 'Bây giờ không học thì sau này sẽ khổ.', 6626, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16899, 'しゅうに 3かい かよえば、ひとつきで 12かい いく ことに なる。', 'shuu ni sankai kayoeba, hitotsuki de juunikai iku koto ni naru.', NULL, 'Tuần đi 3 lần thì một tháng sẽ đi 12 lần.', 6626, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16900, 'パスワードを わすれた ばかりに、ひどい めに あった。', 'pasuwaado o wasureta bakari ni, hidoi me ni atta.', NULL, 'Chỉ vì quên mật khẩu mà gặp rắc rối to.', 6627, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16901, 'よけいな ことを いった ばかりに、けんかに なった。', 'yokei na koto o itta bakari ni, kenka ni natta.', NULL, 'Chỉ vì nói điều thừa thãi mà thành cãi nhau.', 6627, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16902, 'もう おとななのだから、じぶんで きめなさい。', 'mou otona na no da kara, jibun de kimenasai.', NULL, 'Đã là người lớn rồi thì tự quyết định đi.', 6628, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16903, 'やくそくしたのだから、まもらなければ ならない。', 'yakusoku shita no da kara, mamoranakereba naranai.', NULL, 'Đã hứa rồi thì phải giữ lời.', 6628, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16904, 'わかい うちに、いろいろな くにへ いきたい。', 'wakai uchi ni, iroiro na kuni e ikitai.', NULL, 'Tôi muốn đi nhiều nước khi còn trẻ.', 6629, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16905, 'あつい うちに、どうぞ めしあがって ください。', 'atsui uchi ni, douzo meshiagatte kudasai.', NULL, 'Xin mời ăn khi còn nóng.', 6629, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16906, 'あめが ふらない うちに、かえりましょう。', 'ame ga furanai uchi ni, kaerimashou.', NULL, 'Về thôi trước khi trời mưa.', 6630, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16907, 'わすれない うちに、メモして おこう。', 'wasurenai uchi ni, memo shite okou.', NULL, 'Ghi lại trước khi quên thôi.', 6630, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16908, 'かいぎの さいちゅうに、でんわが なった。', 'kaigi no saichuu ni, denwa ga natta.', NULL, 'Đúng lúc đang họp thì điện thoại reo.', 6631, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16909, 'しょくじを して いる さいちゅうに、じしんが あった。', 'shokuji o shite iru saichuu ni, jishin ga atta.', NULL, 'Đúng lúc đang ăn thì có động đất.', 6631, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16910, 'いえを でた とたん、あめが ふりだした。', 'ie o deta totan, ame ga furidashita.', NULL, 'Vừa ra khỏi nhà thì trời đổ mưa.', 6632, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16911, 'ベッドに はいった とたんに、ねて しまった。', 'beddo ni haitta totan ni, nete shimatta.', NULL, 'Vừa lên giường là ngủ luôn.', 6632, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16912, 'にほんに きて いらい、いちども かえって いない。', 'nihon ni kite irai, ichido mo kaette inai.', NULL, 'Kể từ khi sang Nhật, tôi chưa về lần nào.', 6633, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16913, 'そつぎょうして いらい、かれに あって いない。', 'sotsugyou shite irai, kare ni atte inai.', NULL, 'Từ khi tốt nghiệp tôi chưa gặp anh ấy.', 6633, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16914, 'びょうきに なって はじめて、けんこうの たいせつさが わかった。', 'byouki ni natte hajimete, kenkou no taisetsusa ga wakatta.', NULL, 'Phải đến khi ốm mới hiểu sức khỏe quý giá.', 6634, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16915, 'ひとりで くらして はじめて、おやの ありがたさを かんじた。', 'hitori de kurashite hajimete, oya no arigatasa o kanjita.', NULL, 'Phải sống một mình mới thấy biết ơn cha mẹ.', 6634, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16916, 'でかけようと した ところに、ともだちが きた。', 'dekakeyou to shita tokoro ni, tomodachi ga kita.', NULL, 'Đúng lúc định ra ngoài thì bạn đến.', 6635, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16917, 'こまって いる ところへ、せんぱいが たすけて くれた。', 'komatte iru tokoro e, senpai ga tasukete kureta.', NULL, 'Đúng lúc đang khó thì đàn anh giúp.', 6635, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16918, 'この うたを きく たびに、こきょうを おもいだす。', 'kono uta o kiku tabi ni, kokyou o omoidasu.', NULL, 'Mỗi lần nghe bài hát này, tôi lại nhớ quê.', 6636, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16919, 'りょこうの たびに、おみやげを かって くる。', 'ryokou no tabi ni, omiyage o katte kuru.', NULL, 'Mỗi lần đi du lịch, tôi đều mua quà về.', 6636, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17770, 'ことしは いい こと ずくめだった。', 'kotoshi wa ii koto zukume datta.', NULL, 'Năm nay toàn chuyện tốt đẹp.', 7062, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16920, 'かいものの ついでに、ゆうびんきょくに よった。', 'kaimono no tsuide ni, yuubinkyoku ni yotta.', NULL, 'Nhân tiện đi mua sắm, tôi ghé bưu điện.', 6637, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16921, 'さんぽに いく ついでに、ごみを だして きて。', 'sanpo ni iku tsuide ni, gomi o dashite kite.', NULL, 'Tiện đi dạo thì đổ rác giúp nhé.', 6637, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16922, 'しゅくだいを おえて からでないと、あそびに いっては だめ。', 'shukudai o oete kara de nai to, asobi ni itte wa dame.', NULL, 'Chưa làm xong bài tập thì không được đi chơi.', 6638, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16923, 'じっさいに みて からでなければ、きめられない。', 'jissai ni mite kara de nakereba, kimerarenai.', NULL, 'Chưa xem tận mắt thì không quyết định được.', 6638, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16924, 'かれとは きょねん あった きり、れんらくが ない。', 'kare to wa kyonen atta kiri, renraku ga nai.', NULL, 'Gặp anh ấy năm ngoái rồi thôi, không liên lạc nữa.', 6639, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16925, 'むすこは あさ でかけた きり、まだ かえって こない。', 'musuko wa asa dekaketa kiri, mada kaette konai.', NULL, 'Con trai đi từ sáng đến giờ vẫn chưa về.', 6639, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16926, 'もし 1おくえん あたった としたら、なにに つかいますか。', 'moshi ichiokuen atatta to shitara, nani ni tsukaimasu ka.', NULL, 'Giả sử trúng 100 triệu yên thì bạn tiêu vào gì?', 6640, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16927, 'この はなしが ほんとうだ とすれば、たいへんな ことだ。', 'kono hanashi ga hontou da to sureba, taihen na koto da.', NULL, 'Nếu chuyện này là thật thì nghiêm trọng đấy.', 6640, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16928, 'じかん さえ あれば、もっと べんきょうできるのに。', 'jikan sae areba, motto benkyou dekiru noni.', NULL, 'Chỉ cần có thời gian là học được nhiều hơn.', 6641, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16929, 'この くすりを のみ さえ すれば、なおりますよ。', 'kono kusuri o nomi sae sureba, naorimasu yo.', NULL, 'Chỉ cần uống thuốc này là khỏi.', 6641, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16930, 'れんしゅうしない かぎり、じょうずに ならない。', 'renshuu shinai kagiri, jouzu ni naranai.', NULL, 'Chừng nào chưa luyện tập thì không giỏi được.', 6642, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16931, 'あめが ふらない かぎり、しあいは おこなわれます。', 'ame ga furanai kagiri, shiai wa okonawaremasu.', NULL, 'Trừ khi trời mưa, trận đấu vẫn diễn ra.', 6642, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16932, 'たとえ はんたいされても、わたしは やります。', 'tatoe hantai saretemo, watashi wa yarimasu.', NULL, 'Cho dù bị phản đối, tôi vẫn làm.', 6643, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16933, 'たとえ たかくても、ほしい ものは かう。', 'tatoe takakutemo, hoshii mono wa kau.', NULL, 'Dù có đắt tôi vẫn mua thứ mình muốn.', 6643, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16934, 'いまから いった としても、まにあわないだろう。', 'ima kara itta to shitemo, maniawanai darou.', NULL, 'Dù bây giờ đi thì chắc cũng không kịp.', 6644, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16935, 'しっぱいした としても、こうかいしない。', 'shippai shita to shitemo, koukai shinai.', NULL, 'Dù có thất bại, tôi cũng không hối hận.', 6644, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16936, 'しらない くせに、しって いる ふりを する。', 'shiranai kuse ni, shitte iru furi o suru.', NULL, 'Không biết vậy mà cứ làm như biết.', 6645, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16937, 'じぶんは やらない くせに、ひとには もんくを いう。', 'jibun wa yaranai kuse ni, hito ni wa monku o iu.', NULL, 'Bản thân không làm vậy mà lại chê người khác.', 6645, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16938, 'いそがしければ、あした でも かまいません。', 'isogashikereba, ashita demo kamaimasen.', NULL, 'Nếu bận thì mai cũng không sao.', 6646, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16939, 'ここに すわっても かまいませんか。', 'koko ni suwattemo kamaimasen ka.', NULL, 'Tôi ngồi đây có sao không?', 6646, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16940, 'もっと はやく いえを でれば よかった。', 'motto hayaku ie o dereba yokatta.', NULL, 'Giá mà ra khỏi nhà sớm hơn.', 6647, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16941, 'あんな こと、いわなければ よかった。', 'anna koto, iwanakereba yokatta.', NULL, 'Giá mà đừng nói điều như thế.', 6647, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16942, 'できる ものなら、むかしに もどりたい。', 'dekiru mono nara, mukashi ni modoritai.', NULL, 'Nếu có thể, tôi muốn quay về ngày xưa.', 6648, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16943, 'いける ものなら、いますぐ いきたい。', 'ikeru mono nara, ima sugu ikitai.', NULL, 'Nếu đi được thì tôi muốn đi ngay.', 6648, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16944, 'じっさいに やって みない ことには、わからない。', 'jissai ni yatte minai koto ni wa, wakaranai.', NULL, 'Không làm thử thì không biết được.', 6649, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16945, 'おかねが ない ことには、なにも はじめられない。', 'okane ga nai koto ni wa, nani mo hajimerarenai.', NULL, 'Không có tiền thì chẳng bắt đầu được gì.', 6649, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16946, 'あめが ふっても ふらなくても、いきます。', 'ame ga futtemo furanakutemo, ikimasu.', NULL, 'Dù mưa hay không, tôi vẫn đi.', 6650, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16947, 'すきでも すきじゃなくても、たべなさい。', 'suki demo suki ja nakutemo, tabenasai.', NULL, 'Thích hay không thì cũng ăn đi.', 6650, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16948, 'なきたい ほど つかれた。', 'nakitai hodo tsukareta.', NULL, 'Mệt đến mức muốn khóc.', 6651, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16949, 'しんじられない くらい きれいな けしきだった。', 'shinjirarenai kurai kirei na keshiki datta.', NULL, 'Phong cảnh đẹp đến mức không thể tin nổi.', 6651, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16950, 'ことしは きょねん ほど あつくない。', 'kotoshi wa kyonen hodo atsukunai.', NULL, 'Năm nay không nóng bằng năm ngoái.', 6652, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16951, 'かれ ほど まじめな ひとは いない。', 'kare hodo majime na hito wa inai.', NULL, 'Không ai nghiêm túc bằng anh ấy.', 6652, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16952, 'とかいに くらべて、いなかは くらしやすい。', 'tokai ni kurabete, inaka wa kurashiyasui.', NULL, 'So với thành phố, nông thôn dễ sống hơn.', 6653, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16953, 'きょねんに くらべて、きゃくが ふえた。', 'kyonen ni kurabete, kyaku ga fueta.', NULL, 'So với năm ngoái, khách đã tăng lên.', 6653, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16954, 'できる だけ はやく へんじを ください。', 'dekiru dake hayaku henji o kudasai.', NULL, 'Hãy trả lời sớm nhất có thể.', 6654, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16955, 'すきな だけ たべて いいですよ。', 'suki na dake tabete ii desu yo.', NULL, 'Ăn bao nhiêu tùy thích nhé.', 6654, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16956, 'バスが ないから、あるいて いく ほかない。', 'basu ga nai kara, aruite iku hoka nai.', NULL, 'Không có xe buýt nên chỉ còn cách đi bộ.', 6655, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16957, 'やくそくした いじょう、やる しか ない。', 'yakusoku shita ijou, yaru shika nai.', NULL, 'Đã hứa rồi thì chỉ còn cách làm thôi.', 6655, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16958, 'いそいで いる ときに かぎって、でんしゃが おくれる。', 'isoide iru toki ni kagitte, densha ga okureru.', NULL, 'Cứ lúc vội là tàu lại trễ.', 6656, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16959, 'うちの こに かぎって、そんな ことは しない。', 'uchi no ko ni kagitte, sonna koto wa shinai.', NULL, 'Riêng con nhà tôi thì không làm chuyện đó đâu.', 6656, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16960, 'かれは えいご ばかりか、フランスごも はなせる。', 'kare wa eigo bakari ka, furansugo mo hanaseru.', NULL, 'Anh ấy không chỉ nói tiếng Anh mà cả tiếng Pháp.', 6657, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16961, 'この みせは やすい ばかりでなく、おいしい。', 'kono mise wa yasui bakari de naku, oishii.', NULL, 'Quán này không những rẻ mà còn ngon.', 6657, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16962, 'なつやすみ ほど たのしい ものは ない。', 'natsuyasumi hodo tanoshii mono wa nai.', NULL, 'Không có gì vui bằng kỳ nghỉ hè.', 6658, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16963, 'けんこう ほど たいせつな ものは ない。', 'kenkou hodo taisetsu na mono wa nai.', NULL, 'Không có gì quý bằng sức khỏe.', 6658, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16964, 'としを とる ほど、じかんが はやく かんじる。', 'toshi o toru hodo, jikan ga hayaku kanjiru.', NULL, 'Càng có tuổi càng thấy thời gian trôi nhanh.', 6659, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16965, 'かんがえる ほど わからなく なる。', 'kangaeru hodo wakaranaku naru.', NULL, 'Càng nghĩ càng không hiểu.', 6659, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16966, 'わたしに とって、かぞくが いちばん たいせつだ。', 'watashi ni totte, kazoku ga ichiban taisetsu da.', NULL, 'Đối với tôi, gia đình là quan trọng nhất.', 6660, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16967, 'がくせいに とって、この ほんは たかすぎる。', 'gakusei ni totte, kono hon wa takasugiru.', NULL, 'Đối với sinh viên, cuốn sách này quá đắt.', 6660, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16968, 'にほんの れきしに ついて しらべて います。', 'nihon no rekishi ni tsuite shirabete imasu.', NULL, 'Tôi đang tìm hiểu về lịch sử Nhật Bản.', 6661, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16969, 'その けんに ついては、あとで はなしましょう。', 'sono ken ni tsuite wa, ato de hanashimashou.', NULL, 'Về việc đó, lát nữa ta bàn nhé.', 6661, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16970, 'せんせいの しつもんに たいして、だれも こたえなかった。', 'sensei no shitsumon ni taishite, daremo kotaenakatta.', NULL, 'Không ai trả lời câu hỏi của thầy.', 6662, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16971, 'あには かっぱつなのに たいして、おとうとは おとなしい。', 'ani wa kappatsu na no ni taishite, otouto wa otonashii.', NULL, 'Trái với anh trai năng động, em trai hiền lành.', 6662, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16972, 'かれは りゅうがくせいとして にほんに きた。', 'kare wa ryuugakusei to shite nihon ni kita.', NULL, 'Anh ấy đến Nhật với tư cách du học sinh.', 6663, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16973, 'しゅみとして ギターを ひいて います。', 'shumi to shite gitaa o hiite imasu.', NULL, 'Tôi chơi guitar như một sở thích.', 6663, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16974, 'あの ひとは はんにんに ちがいない。', 'ano hito wa hannin ni chigainai.', NULL, 'Người đó chắc chắn là thủ phạm.', 6664, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16975, 'かれの ことだから、また おくれるに ちがいない。', 'kare no koto da kara, mata okureru ni chigainai.', NULL, 'Anh ta mà, chắc chắn lại đến muộn.', 6664, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16976, 'かれが そんな ことを いう はずが ない。', 'kare ga sonna koto o iu hazu ga nai.', NULL, 'Anh ấy không thể nào nói điều đó.', 6665, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16977, 'こんな かんたんな もんだいが できない はずが ない。', 'konna kantan na mondai ga dekinai hazu ga nai.', NULL, 'Không thể nào không làm được bài dễ thế này.', 6665, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16978, '1しゅうかんで ペラペラに なる わけが ない。', 'isshuukan de perapera ni naru wake ga nai.', NULL, 'Làm gì có chuyện một tuần mà nói trôi chảy.', 6666, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16979, 'あんなに れんしゅうしたのだから、まける わけが ない。', 'anna ni renshuu shita no da kara, makeru wake ga nai.', NULL, 'Luyện tập nhiều thế rồi, làm gì có chuyện thua.', 6666, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16980, 'にくが きらいな わけでは ないが、あまり たべない。', 'niku ga kirai na wake de wa nai ga, amari tabenai.', NULL, 'Không hẳn ghét thịt, nhưng tôi ít ăn.', 6667, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16981, 'いつも ひまな わけでは ない。', 'itsumo hima na wake de wa nai.', NULL, 'Không phải lúc nào cũng rảnh.', 6667, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16982, 'だいじな かいぎが あるので、やすむ わけには いかない。', 'daiji na kaigi ga aru node, yasumu wake ni wa ikanai.', NULL, 'Có cuộc họp quan trọng nên không thể nghỉ.', 6668, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16983, 'ともだちの ひみつを はなす わけには いかない。', 'tomodachi no himitsu o hanasu wake ni wa ikanai.', NULL, 'Không thể kể bí mật của bạn được.', 6668, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16984, 'がくせいは もっと べんきょうする べきだ。', 'gakusei wa motto benkyou suru beki da.', NULL, 'Học sinh nên học nhiều hơn.', 6669, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16985, 'ひとの わるくちを いう べきでは ない。', 'hito no warukuchi o iu beki de wa nai.', NULL, 'Không nên nói xấu người khác.', 6669, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16986, 'そんなに しんぱいする ことは ないよ。', 'sonna ni shinpai suru koto wa nai yo.', NULL, 'Không cần phải lo lắng thế đâu.', 6670, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16987, 'わざわざ くる ことは ありません。', 'wazawaza kuru koto wa arimasen.', NULL, 'Không cần phải cất công đến đâu.', 6670, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16988, 'きょうは はるらしい あたたかい ひだ。', 'kyou wa haru rashii atatakai hi da.', NULL, 'Hôm nay là ngày ấm áp đúng chất mùa xuân.', 6671, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16989, 'かれは おとこらしい ひとだ。', 'kare wa otoko rashii hito da.', NULL, 'Anh ấy là người rất đàn ông.', 6671, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16990, 'かれは おこりっぽい。', 'kare wa okorippoi.', NULL, 'Anh ta dễ nổi nóng.', 6672, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16991, 'この ふくは こどもっぽい。', 'kono fuku wa kodomoppoi.', NULL, 'Bộ quần áo này trông trẻ con.', 6672, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16992, 'ちきゅうの きおんは あがりつつ ある。', 'chikyuu no kion wa agaritsutsu aru.', NULL, 'Nhiệt độ trái đất đang dần tăng lên.', 6673, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16993, 'この まちの じんこうは へりつつ ある。', 'kono machi no jinkou wa heritsutsu aru.', NULL, 'Dân số thị trấn này đang giảm dần.', 6673, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16994, 'ぶっかは あがる いっぽうだ。', 'bukka wa agaru ippou da.', NULL, 'Vật giá ngày càng tăng.', 6674, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16995, 'かれの びょうきは わるく なる いっぽうだ。', 'kare no byouki wa waruku naru ippou da.', NULL, 'Bệnh của anh ấy ngày càng xấu đi.', 6674, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16996, 'ふゆは かぜを ひきがちだ。', 'fuyu wa kaze o hikigachi da.', NULL, 'Mùa đông hay bị cảm.', 6675, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16997, 'いそがしいと、しょくじが ふきそくに なりがちだ。', 'isogashii to, shokuji ga fukisoku ni narigachi da.', NULL, 'Khi bận, bữa ăn thường dễ thất thường.', 6675, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16998, 'すこし かぜぎみなので、きょうは はやく ねます。', 'sukoshi kazegimi na node, kyou wa hayaku nemasu.', NULL, 'Hơi có dấu hiệu cảm nên hôm nay tôi ngủ sớm.', 6676, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16999, 'さいきん つかれぎみだ。', 'saikin tsukaregimi da.', NULL, 'Dạo này hơi mệt mỏi.', 6676, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17000, 'でんきを つけっぱなしで ねて しまった。', 'denki o tsukeppanashi de nete shimatta.', NULL, 'Tôi ngủ quên mà để đèn bật suốt.', 6677, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17001, 'きょうは いちにちじゅう たちっぱなしだった。', 'kyou wa ichinichijuu tachippanashi datta.', NULL, 'Hôm nay đứng suốt cả ngày.', 6677, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18425, 'あせ まみれで はたらいた。', 'ase mamire de hataraita.', NULL, 'Làm việc mồ hôi nhễ nhại.', 7389, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17003, 'スマホで なんでも できる ように なった。', 'sumaho de nandemo dekiru you ni natta.', NULL, 'Giờ đây có thể làm mọi thứ bằng điện thoại.', 6678, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17004, 'ねようと した とき、でんわが なった。', 'neyou to shita toki, denwa ga natta.', NULL, 'Khi định đi ngủ thì điện thoại reo.', 6679, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17005, 'ドアを あけようと したが、あかなかった。', 'doa o akeyou to shita ga, akanakatta.', NULL, 'Tôi định mở cửa nhưng không mở được.', 6679, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17006, 'よみかけの ほんが つくえの うえに ある。', 'yomikake no hon ga tsukue no ue ni aru.', NULL, 'Cuốn sách đọc dở nằm trên bàn.', 6680, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17007, 'なにか いいかけて、やめた。', 'nanika iikakete, yameta.', NULL, 'Định nói gì đó rồi thôi.', 6680, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17008, 'あかちゃんが きゅうに なきだした。', 'akachan ga kyuu ni nakidashita.', NULL, 'Em bé đột nhiên khóc òa.', 6681, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17009, 'あめが ふりだした。', 'ame ga furidashita.', NULL, 'Trời bắt đầu mưa.', 6681, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17010, 'この ほんは いちにちで よみきった。', 'kono hon wa ichinichi de yomikitta.', NULL, 'Tôi đọc hết cuốn sách này trong một ngày.', 6682, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17011, 'りょうが おおくて、たべきれない。', 'ryou ga ookute, tabekirenai.', NULL, 'Nhiều quá, ăn không hết.', 6682, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17012, 'あさから ずっと あめが ふりつづけて いる。', 'asa kara zutto ame ga furitsuzukete iru.', NULL, 'Mưa liên tục từ sáng.', 6683, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17013, 'ゆめを もちつづける ことが たいせつだ。', 'yume o mochitsuzukeru koto ga taisetsu da.', NULL, 'Tiếp tục giữ ước mơ là điều quan trọng.', 6683, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17014, 'あしたの しけんは ちゅうしだ と いう ことだ。', 'ashita no shiken wa chuushi da to iu koto da.', NULL, 'Nghe nói bài thi ngày mai bị hủy.', 6684, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17015, 'つまり、ことしは けっこんしない と いう ことですね。', 'tsumari, kotoshi wa kekkon shinai to iu koto desu ne.', NULL, 'Tức là năm nay anh không kết hôn nhỉ.', 6684, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17016, 'たなかさん、らいげつ けっこんする とか。', 'tanaka-san, raigetsu kekkon suru toka.', NULL, 'Nghe đâu anh Tanaka tháng sau cưới.', 6685, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17017, 'あの みせ、もう しまった とか きいたよ。', 'ano mise, mou shimatta toka kiita yo.', NULL, 'Nghe bảo quán đó đóng cửa rồi.', 6685, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17018, 'あした やすみだって。', 'ashita yasumi datte.', NULL, 'Nghe bảo mai được nghỉ đấy.', 6686, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17019, '「すし」って なんですか。', '"sushi" tte nan desu ka.', NULL, '"Sushi" là gì vậy?', 6686, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17020, 'ニュースに よると、たいふうが ちかづいて いる。', 'nyuusu ni yoru to, taifuu ga chikazuite iru.', NULL, 'Theo tin tức, bão đang đến gần.', 6687, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17021, 'ちょうさに よれば、わかものの 7わりが スマホを もって いる。', 'chousa ni yoreba, wakamono no nanawari ga sumaho o motte iru.', NULL, 'Theo khảo sát, 70% người trẻ có điện thoại thông minh.', 6687, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17022, 'この おてらは 1000ねんまえに たてられた と いわれて いる。', 'kono otera wa sennen mae ni taterareta to iwarete iru.', NULL, 'Người ta nói ngôi chùa này được xây 1000 năm trước.', 6688, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17393, 'きこえない ふりを しないで。', 'kikoenai furi o shinaide.', NULL, 'Đừng giả vờ không nghe thấy.', 6873, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17023, 'みどりちゃは けんこうに いい と いわれて いる。', 'midoricha wa kenkou ni ii to iwarete iru.', NULL, 'Người ta nói trà xanh tốt cho sức khỏe.', 6688, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17024, 'せんせいに しゅくだいを だす ように いわれた。', 'sensei ni shukudai o dasu you ni iwareta.', NULL, 'Tôi bị thầy bảo nộp bài tập.', 6689, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17025, 'ははに はやく かえる ように たのまれた。', 'haha ni hayaku kaeru you ni tanomareta.', NULL, 'Mẹ nhờ tôi về sớm.', 6689, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17026, 'ゆめみたいな はなしだ。', 'yume mitai na hanashi da.', NULL, 'Chuyện như trong mơ vậy.', 6690, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17027, 'こどもみたいに はしゃいで いる。', 'kodomo mitai ni hashaide iru.', NULL, 'Đang vui đùa như trẻ con.', 6690, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17028, 'かれは なにも なかった かのように わらって いた。', 'kare wa nani mo nakatta ka no you ni waratte ita.', NULL, 'Anh ta cười như thể không có chuyện gì.', 6691, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17029, 'まるで なつに なった かのような あつさだ。', 'marude natsu ni natta ka no you na atsusa da.', NULL, 'Nóng như thể đã sang hè.', 6691, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17030, 'この みずうみは まるで かがみの ようだ。', 'kono mizuumi wa marude kagami no you da.', NULL, 'Cái hồ này cứ như một tấm gương.', 6692, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17031, 'まるで ほんものの ような にせものだ。', 'marude honmono no you na nisemono da.', NULL, 'Đồ giả mà cứ như đồ thật.', 6692, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17032, 'かれは ねて いる ふりを して いる。', 'kare wa nete iru furi o shite iru.', NULL, 'Anh ấy đang giả vờ ngủ.', 6693, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17033, 'きこえない ふりを しないで。', 'kikoenai furi o shinaide.', NULL, 'Đừng giả vờ không nghe thấy.', 6693, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17034, 'この アパートは ひろい うえに、やちんも やすい。', 'kono apaato wa hiroi ue ni, yachin mo yasui.', NULL, 'Căn hộ này đã rộng lại còn rẻ.', 6694, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17035, 'みちに まよった うえに、あめまで ふって きた。', 'michi ni mayotta ue ni, ame made futte kita.', NULL, 'Đã lạc đường lại còn mưa nữa.', 6694, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17036, 'かのじょは うたが じょうずな だけでなく、ダンスも うまい。', 'kanojo wa uta ga jouzu na dake de naku, dansu mo umai.', NULL, 'Cô ấy không chỉ hát hay mà còn nhảy giỏi.', 6695, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17037, 'べんきょう だけでなく、スポーツも がんばって いる。', 'benkyou dake de naku, supootsu mo ganbatte iru.', NULL, 'Không chỉ học mà còn chăm thể thao.', 6695, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17038, 'ぶちょうの かわりに、わたしが かいぎに でた。', 'buchou no kawari ni, watashi ga kaigi ni deta.', NULL, 'Tôi dự họp thay trưởng phòng.', 6696, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17039, 'えいごを おしえて もらう かわりに、にほんごを おしえた。', 'eigo o oshiete morau kawari ni, nihongo o oshieta.', NULL, 'Đổi lại việc được dạy tiếng Anh, tôi dạy tiếng Nhật.', 6696, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17040, 'せまい ながらも、じぶんの いえが ほしい。', 'semai nagara mo, jibun no ie ga hoshii.', NULL, 'Dù chật nhưng tôi muốn có nhà riêng.', 6697, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17041, 'わかって いながらも、また おなじ しっぱいを した。', 'wakatte inagara mo, mata onaji shippai o shita.', NULL, 'Dù biết nhưng vẫn mắc lại lỗi cũ.', 6697, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17042, 'ちちに かわって、わたしが ごあいさつします。', 'chichi ni kawatte, watashi ga goaisatsu shimasu.', NULL, 'Thay mặt bố, tôi xin phát biểu.', 6698, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17043, 'にんげんに かわって、ロボットが はたらく じだいだ。', 'ningen ni kawatte, robotto ga hataraku jidai da.', NULL, 'Thời đại robot làm việc thay con người.', 6698, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17044, 'とうきょうを はじめ、おおきい まちは ひとが おおい。', 'toukyou o hajime, ookii machi wa hito ga ooi.', NULL, 'Các thành phố lớn, tiêu biểu là Tokyo, rất đông người.', 6699, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17084, 'わかい うちに、いろいろな くにへ いきたい。', 'wakai uchi ni, iroiro na kuni e ikitai.', NULL, 'Tôi muốn đi nhiều nước khi còn trẻ.', 6719, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17045, 'しゃちょうを はじめ、しゃいん ぜんいんが さんかした。', 'shachou o hajime, shain zen''in ga sanka shita.', NULL, 'Từ giám đốc đến toàn bộ nhân viên đều tham gia.', 6699, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17046, 'わたしなんか、とても かないません。', 'watashi nanka, totemo kanaimasen.', NULL, 'Người như tôi thì không sánh được đâu.', 6700, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17047, 'おばけなど いる わけが ない。', 'obake nado iru wake ga nai.', NULL, 'Làm gì có ma quỷ.', 6700, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17048, 'ざんねんな ことに、しあいに まけて しまった。', 'zannen na koto ni, shiai ni makete shimatta.', NULL, 'Thật đáng tiếc là đã thua trận.', 6701, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17049, 'おどろいた ことに、かれは 10かこくごが はなせる。', 'odoroita koto ni, kare wa jukkakokugo ga hanaseru.', NULL, 'Ngạc nhiên thay, anh ấy nói được 10 thứ tiếng.', 6701, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17050, 'じょうきょうは わるく なる ばかりだ。', 'joukyou wa waruku naru bakari da.', NULL, 'Tình hình chỉ ngày càng xấu đi.', 6702, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17051, 'じゅんびは できて いて、あとは はじめる ばかりだ。', 'junbi wa dekite ite, ato wa hajimeru bakari da.', NULL, 'Đã chuẩn bị xong, giờ chỉ còn bắt đầu.', 6702, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17052, 'ベルが なるか ならないかの うちに、せいとは きょうしつを でた。', 'beru ga naru ka naranai ka no uchi ni, seito wa kyoushitsu o deta.', NULL, 'Chuông vừa reo là học sinh đã ra khỏi lớp.', 6703, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17053, 'すわるか すわらないかの うちに、ねて しまった。', 'suwaru ka suwaranai ka no uchi ni, nete shimatta.', NULL, 'Vừa ngồi xuống là ngủ mất.', 6703, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17054, 'だって、しらなかったんだもの。', 'datte, shiranakatta n da mono.', NULL, 'Vì em không biết mà.', 6704, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17055, 'いきたくないよ。つかれて いるもん。', 'ikitakunai yo. tsukarete iru mon.', NULL, 'Không muốn đi đâu. Mệt mà.', 6704, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17056, 'じかんが たつのは はやい ものだ。', 'jikan ga tatsu no wa hayai mono da.', NULL, 'Thời gian trôi thật nhanh.', 6705, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17057, 'こどもの ころ、よく この かわで あそんだ ものだ。', 'kodomo no koro, yoku kono kawa de asonda mono da.', NULL, 'Hồi nhỏ tôi hay chơi ở con sông này.', 6705, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17058, 'かぜを なおしたいなら、よく ねる ことだ。', 'kaze o naoshitai nara, yoku neru koto da.', NULL, 'Muốn khỏi cảm thì nên ngủ nhiều.', 6706, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17059, 'じょうずに なりたければ、まいにち れんしゅうする ことだ。', 'jouzu ni naritakereba, mainichi renshuu suru koto da.', NULL, 'Muốn giỏi thì nên luyện tập hằng ngày.', 6706, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17060, 'ねぼうした せいで、でんしゃに のりおくれた。', 'nebou shita sei de, densha ni noriokureta.', NULL, 'Tại ngủ quên nên tôi lỡ tàu.', 6707, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17061, 'あめの せいで、しあいが ちゅうしに なった。', 'ame no sei de, shiai ga chuushi ni natta.', NULL, 'Tại mưa nên trận đấu bị hủy.', 6707, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17062, 'せんせいの おかげで、ごうかくできました。', 'sensei no okage de, goukaku dekimashita.', NULL, 'Nhờ thầy mà tôi đã đỗ.', 6708, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17063, 'くすりを のんだ おかげで、ねつが さがった。', 'kusuri o nonda okage de, netsu ga sagatta.', NULL, 'Nhờ uống thuốc mà hạ sốt.', 6708, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17064, 'じしんに よって、おおくの いえが たおれた。', 'jishin ni yotte, ooku no ie ga taoreta.', NULL, 'Do động đất, nhiều ngôi nhà bị đổ.', 6709, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17065, 'ふちゅういに よる じこが ふえて いる。', 'fuchuui ni yoru jiko ga fuete iru.', NULL, 'Tai nạn do bất cẩn đang tăng lên.', 6709, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17066, 'おおゆきの ため、でんしゃが とまって います。', 'ooyuki no tame, densha ga tomatte imasu.', NULL, 'Vì tuyết lớn nên tàu đang ngừng chạy.', 6710, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17067, 'こうじちゅうの ため、この みちは とおれません。', 'koujichuu no tame, kono michi wa tooremasen.', NULL, 'Vì đang thi công nên không đi qua đường này được.', 6710, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17068, 'あなたの ことを しんぱいして いる から こそ、ちゅういするのです。', 'anata no koto o shinpai shite iru kara koso, chuui suru no desu.', NULL, 'Chính vì lo cho bạn nên tôi mới nhắc nhở.', 6711, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17069, 'むずかしい から こそ、やる かちが ある。', 'muzukashii kara koso, yaru kachi ga aru.', NULL, 'Chính vì khó nên mới đáng làm.', 6711, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17070, 'わすれない ように、メモして おきます。', 'wasurenai you ni, memo shite okimasu.', NULL, 'Tôi ghi chú lại để khỏi quên.', 6712, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17071, 'だれでも わかる ように、やさしく せつめいした。', 'daredemo wakaru you ni, yasashiku setsumei shita.', NULL, 'Tôi giải thích dễ hiểu để ai cũng hiểu được.', 6712, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17072, 'かたちが にて いる ことから、この なまえが ついた。', 'katachi ga nite iru koto kara, kono namae ga tsuita.', NULL, 'Vì hình dạng giống nên mới có tên này.', 6713, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17073, 'へやの でんきが ついて いる ことから、かれは いえに いると わかった。', 'heya no denki ga tsuite iru koto kara, kare wa ie ni iru to wakatta.', NULL, 'Từ việc đèn phòng đang bật, tôi biết anh ấy ở nhà.', 6713, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17074, '10ねんも にほんに すんで いたのか。にほんごが じょうずな わけだ。', 'juunen mo nihon ni sunde ita no ka. nihongo ga jouzu na wake da.', NULL, 'Sống ở Nhật tận 10 năm à. Thảo nào tiếng Nhật giỏi.', 6714, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17075, 'エアコンが こわれて いる。あつい わけだ。', 'eakon ga kowarete iru. atsui wake da.', NULL, 'Điều hòa hỏng rồi. Thảo nào nóng.', 6714, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17076, 'もう すこしで くるまに ひかれる ところだった。', 'mou sukoshi de kuruma ni hikareru tokoro datta.', NULL, 'Suýt nữa thì bị xe tông.', 6715, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17077, 'めざましが なかったら、ちこくする ところだった。', 'mezamashi ga nakattara, chikoku suru tokoro datta.', NULL, 'Nếu không có đồng hồ báo thức thì suýt muộn rồi.', 6715, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17078, 'いま べんきょうしないと、あとで こまる ことに なる。', 'ima benkyou shinai to, ato de komaru koto ni naru.', NULL, 'Bây giờ không học thì sau này sẽ khổ.', 6716, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17079, 'しゅうに 3かい かよえば、ひとつきで 12かい いく ことに なる。', 'shuu ni sankai kayoeba, hitotsuki de juunikai iku koto ni naru.', NULL, 'Tuần đi 3 lần thì một tháng sẽ đi 12 lần.', 6716, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17080, 'パスワードを わすれた ばかりに、ひどい めに あった。', 'pasuwaado o wasureta bakari ni, hidoi me ni atta.', NULL, 'Chỉ vì quên mật khẩu mà gặp rắc rối to.', 6717, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17081, 'よけいな ことを いった ばかりに、けんかに なった。', 'yokei na koto o itta bakari ni, kenka ni natta.', NULL, 'Chỉ vì nói điều thừa thãi mà thành cãi nhau.', 6717, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17082, 'もう おとななのだから、じぶんで きめなさい。', 'mou otona na no da kara, jibun de kimenasai.', NULL, 'Đã là người lớn rồi thì tự quyết định đi.', 6718, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17083, 'やくそくしたのだから、まもらなければ ならない。', 'yakusoku shita no da kara, mamoranakereba naranai.', NULL, 'Đã hứa rồi thì phải giữ lời.', 6718, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17085, 'あつい うちに、どうぞ めしあがって ください。', 'atsui uchi ni, douzo meshiagatte kudasai.', NULL, 'Xin mời ăn khi còn nóng.', 6719, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17086, 'あめが ふらない うちに、かえりましょう。', 'ame ga furanai uchi ni, kaerimashou.', NULL, 'Về thôi trước khi trời mưa.', 6720, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17087, 'わすれない うちに、メモして おこう。', 'wasurenai uchi ni, memo shite okou.', NULL, 'Ghi lại trước khi quên thôi.', 6720, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17088, 'かいぎの さいちゅうに、でんわが なった。', 'kaigi no saichuu ni, denwa ga natta.', NULL, 'Đúng lúc đang họp thì điện thoại reo.', 6721, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17089, 'しょくじを して いる さいちゅうに、じしんが あった。', 'shokuji o shite iru saichuu ni, jishin ga atta.', NULL, 'Đúng lúc đang ăn thì có động đất.', 6721, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17090, 'いえを でた とたん、あめが ふりだした。', 'ie o deta totan, ame ga furidashita.', NULL, 'Vừa ra khỏi nhà thì trời đổ mưa.', 6722, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17091, 'ベッドに はいった とたんに、ねて しまった。', 'beddo ni haitta totan ni, nete shimatta.', NULL, 'Vừa lên giường là ngủ luôn.', 6722, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17092, 'にほんに きて いらい、いちども かえって いない。', 'nihon ni kite irai, ichido mo kaette inai.', NULL, 'Kể từ khi sang Nhật, tôi chưa về lần nào.', 6723, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17093, 'そつぎょうして いらい、かれに あって いない。', 'sotsugyou shite irai, kare ni atte inai.', NULL, 'Từ khi tốt nghiệp tôi chưa gặp anh ấy.', 6723, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17094, 'びょうきに なって はじめて、けんこうの たいせつさが わかった。', 'byouki ni natte hajimete, kenkou no taisetsusa ga wakatta.', NULL, 'Phải đến khi ốm mới hiểu sức khỏe quý giá.', 6724, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17095, 'ひとりで くらして はじめて、おやの ありがたさを かんじた。', 'hitori de kurashite hajimete, oya no arigatasa o kanjita.', NULL, 'Phải sống một mình mới thấy biết ơn cha mẹ.', 6724, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17096, 'でかけようと した ところに、ともだちが きた。', 'dekakeyou to shita tokoro ni, tomodachi ga kita.', NULL, 'Đúng lúc định ra ngoài thì bạn đến.', 6725, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17097, 'こまって いる ところへ、せんぱいが たすけて くれた。', 'komatte iru tokoro e, senpai ga tasukete kureta.', NULL, 'Đúng lúc đang khó thì đàn anh giúp.', 6725, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17098, 'この うたを きく たびに、こきょうを おもいだす。', 'kono uta o kiku tabi ni, kokyou o omoidasu.', NULL, 'Mỗi lần nghe bài hát này, tôi lại nhớ quê.', 6726, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17099, 'りょこうの たびに、おみやげを かって くる。', 'ryokou no tabi ni, omiyage o katte kuru.', NULL, 'Mỗi lần đi du lịch, tôi đều mua quà về.', 6726, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17100, 'かいものの ついでに、ゆうびんきょくに よった。', 'kaimono no tsuide ni, yuubinkyoku ni yotta.', NULL, 'Nhân tiện đi mua sắm, tôi ghé bưu điện.', 6727, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17101, 'さんぽに いく ついでに、ごみを だして きて。', 'sanpo ni iku tsuide ni, gomi o dashite kite.', NULL, 'Tiện đi dạo thì đổ rác giúp nhé.', 6727, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17102, 'しゅくだいを おえて からでないと、あそびに いっては だめ。', 'shukudai o oete kara de nai to, asobi ni itte wa dame.', NULL, 'Chưa làm xong bài tập thì không được đi chơi.', 6728, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17103, 'じっさいに みて からでなければ、きめられない。', 'jissai ni mite kara de nakereba, kimerarenai.', NULL, 'Chưa xem tận mắt thì không quyết định được.', 6728, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17104, 'かれとは きょねん あった きり、れんらくが ない。', 'kare to wa kyonen atta kiri, renraku ga nai.', NULL, 'Gặp anh ấy năm ngoái rồi thôi, không liên lạc nữa.', 6729, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17105, 'むすこは あさ でかけた きり、まだ かえって こない。', 'musuko wa asa dekaketa kiri, mada kaette konai.', NULL, 'Con trai đi từ sáng đến giờ vẫn chưa về.', 6729, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17106, 'もし 1おくえん あたった としたら、なにに つかいますか。', 'moshi ichiokuen atatta to shitara, nani ni tsukaimasu ka.', NULL, 'Giả sử trúng 100 triệu yên thì bạn tiêu vào gì?', 6730, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17107, 'この はなしが ほんとうだ とすれば、たいへんな ことだ。', 'kono hanashi ga hontou da to sureba, taihen na koto da.', NULL, 'Nếu chuyện này là thật thì nghiêm trọng đấy.', 6730, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17108, 'じかん さえ あれば、もっと べんきょうできるのに。', 'jikan sae areba, motto benkyou dekiru noni.', NULL, 'Chỉ cần có thời gian là học được nhiều hơn.', 6731, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17109, 'この くすりを のみ さえ すれば、なおりますよ。', 'kono kusuri o nomi sae sureba, naorimasu yo.', NULL, 'Chỉ cần uống thuốc này là khỏi.', 6731, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17110, 'れんしゅうしない かぎり、じょうずに ならない。', 'renshuu shinai kagiri, jouzu ni naranai.', NULL, 'Chừng nào chưa luyện tập thì không giỏi được.', 6732, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17111, 'あめが ふらない かぎり、しあいは おこなわれます。', 'ame ga furanai kagiri, shiai wa okonawaremasu.', NULL, 'Trừ khi trời mưa, trận đấu vẫn diễn ra.', 6732, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17112, 'たとえ はんたいされても、わたしは やります。', 'tatoe hantai saretemo, watashi wa yarimasu.', NULL, 'Cho dù bị phản đối, tôi vẫn làm.', 6733, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17113, 'たとえ たかくても、ほしい ものは かう。', 'tatoe takakutemo, hoshii mono wa kau.', NULL, 'Dù có đắt tôi vẫn mua thứ mình muốn.', 6733, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17114, 'いまから いった としても、まにあわないだろう。', 'ima kara itta to shitemo, maniawanai darou.', NULL, 'Dù bây giờ đi thì chắc cũng không kịp.', 6734, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17115, 'しっぱいした としても、こうかいしない。', 'shippai shita to shitemo, koukai shinai.', NULL, 'Dù có thất bại, tôi cũng không hối hận.', 6734, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17116, 'しらない くせに、しって いる ふりを する。', 'shiranai kuse ni, shitte iru furi o suru.', NULL, 'Không biết vậy mà cứ làm như biết.', 6735, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17117, 'じぶんは やらない くせに、ひとには もんくを いう。', 'jibun wa yaranai kuse ni, hito ni wa monku o iu.', NULL, 'Bản thân không làm vậy mà lại chê người khác.', 6735, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17118, 'いそがしければ、あした でも かまいません。', 'isogashikereba, ashita demo kamaimasen.', NULL, 'Nếu bận thì mai cũng không sao.', 6736, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17119, 'ここに すわっても かまいませんか。', 'koko ni suwattemo kamaimasen ka.', NULL, 'Tôi ngồi đây có sao không?', 6736, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17120, 'もっと はやく いえを でれば よかった。', 'motto hayaku ie o dereba yokatta.', NULL, 'Giá mà ra khỏi nhà sớm hơn.', 6737, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17121, 'あんな こと、いわなければ よかった。', 'anna koto, iwanakereba yokatta.', NULL, 'Giá mà đừng nói điều như thế.', 6737, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17122, 'できる ものなら、むかしに もどりたい。', 'dekiru mono nara, mukashi ni modoritai.', NULL, 'Nếu có thể, tôi muốn quay về ngày xưa.', 6738, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17123, 'いける ものなら、いますぐ いきたい。', 'ikeru mono nara, ima sugu ikitai.', NULL, 'Nếu đi được thì tôi muốn đi ngay.', 6738, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17415, 'いきたくないよ。つかれて いるもん。', 'ikitakunai yo. tsukarete iru mon.', NULL, 'Không muốn đi đâu. Mệt mà.', 6884, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17124, 'じっさいに やって みない ことには、わからない。', 'jissai ni yatte minai koto ni wa, wakaranai.', NULL, 'Không làm thử thì không biết được.', 6739, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17125, 'おかねが ない ことには、なにも はじめられない。', 'okane ga nai koto ni wa, nani mo hajimerarenai.', NULL, 'Không có tiền thì chẳng bắt đầu được gì.', 6739, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19089, '25歳に なりました。', 'Nijūgo-sai ni narimashita.', NULL, 'Tôi đã 25 tuổi.', 7723, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17126, 'あめが ふっても ふらなくても、いきます。', 'ame ga futtemo furanakutemo, ikimasu.', NULL, 'Dù mưa hay không, tôi vẫn đi.', 6740, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17127, 'すきでも すきじゃなくても、たべなさい。', 'suki demo suki ja nakutemo, tabenasai.', NULL, 'Thích hay không thì cũng ăn đi.', 6740, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17128, 'なきたい ほど つかれた。', 'nakitai hodo tsukareta.', NULL, 'Mệt đến mức muốn khóc.', 6741, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17129, 'しんじられない くらい きれいな けしきだった。', 'shinjirarenai kurai kirei na keshiki datta.', NULL, 'Phong cảnh đẹp đến mức không thể tin nổi.', 6741, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17130, 'ことしは きょねん ほど あつくない。', 'kotoshi wa kyonen hodo atsukunai.', NULL, 'Năm nay không nóng bằng năm ngoái.', 6742, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17131, 'かれ ほど まじめな ひとは いない。', 'kare hodo majime na hito wa inai.', NULL, 'Không ai nghiêm túc bằng anh ấy.', 6742, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17132, 'とかいに くらべて、いなかは くらしやすい。', 'tokai ni kurabete, inaka wa kurashiyasui.', NULL, 'So với thành phố, nông thôn dễ sống hơn.', 6743, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17133, 'きょねんに くらべて、きゃくが ふえた。', 'kyonen ni kurabete, kyaku ga fueta.', NULL, 'So với năm ngoái, khách đã tăng lên.', 6743, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17134, 'できる だけ はやく へんじを ください。', 'dekiru dake hayaku henji o kudasai.', NULL, 'Hãy trả lời sớm nhất có thể.', 6744, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17135, 'すきな だけ たべて いいですよ。', 'suki na dake tabete ii desu yo.', NULL, 'Ăn bao nhiêu tùy thích nhé.', 6744, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17136, 'バスが ないから、あるいて いく ほかない。', 'basu ga nai kara, aruite iku hoka nai.', NULL, 'Không có xe buýt nên chỉ còn cách đi bộ.', 6745, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17137, 'やくそくした いじょう、やる しか ない。', 'yakusoku shita ijou, yaru shika nai.', NULL, 'Đã hứa rồi thì chỉ còn cách làm thôi.', 6745, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17138, 'いそいで いる ときに かぎって、でんしゃが おくれる。', 'isoide iru toki ni kagitte, densha ga okureru.', NULL, 'Cứ lúc vội là tàu lại trễ.', 6746, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17139, 'うちの こに かぎって、そんな ことは しない。', 'uchi no ko ni kagitte, sonna koto wa shinai.', NULL, 'Riêng con nhà tôi thì không làm chuyện đó đâu.', 6746, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17140, 'かれは えいご ばかりか、フランスごも はなせる。', 'kare wa eigo bakari ka, furansugo mo hanaseru.', NULL, 'Anh ấy không chỉ nói tiếng Anh mà cả tiếng Pháp.', 6747, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17141, 'この みせは やすい ばかりでなく、おいしい。', 'kono mise wa yasui bakari de naku, oishii.', NULL, 'Quán này không những rẻ mà còn ngon.', 6747, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17142, 'なつやすみ ほど たのしい ものは ない。', 'natsuyasumi hodo tanoshii mono wa nai.', NULL, 'Không có gì vui bằng kỳ nghỉ hè.', 6748, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17143, 'けんこう ほど たいせつな ものは ない。', 'kenkou hodo taisetsu na mono wa nai.', NULL, 'Không có gì quý bằng sức khỏe.', 6748, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17144, 'としを とる ほど、じかんが はやく かんじる。', 'toshi o toru hodo, jikan ga hayaku kanjiru.', NULL, 'Càng có tuổi càng thấy thời gian trôi nhanh.', 6749, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17145, 'かんがえる ほど わからなく なる。', 'kangaeru hodo wakaranaku naru.', NULL, 'Càng nghĩ càng không hiểu.', 6749, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17146, 'わたしに とって、かぞくが いちばん たいせつだ。', 'watashi ni totte, kazoku ga ichiban taisetsu da.', NULL, 'Đối với tôi, gia đình là quan trọng nhất.', 6750, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17147, 'がくせいに とって、この ほんは たかすぎる。', 'gakusei ni totte, kono hon wa takasugiru.', NULL, 'Đối với sinh viên, cuốn sách này quá đắt.', 6750, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17148, 'にほんの れきしに ついて しらべて います。', 'nihon no rekishi ni tsuite shirabete imasu.', NULL, 'Tôi đang tìm hiểu về lịch sử Nhật Bản.', 6751, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17149, 'その けんに ついては、あとで はなしましょう。', 'sono ken ni tsuite wa, ato de hanashimashou.', NULL, 'Về việc đó, lát nữa ta bàn nhé.', 6751, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17150, 'せんせいの しつもんに たいして、だれも こたえなかった。', 'sensei no shitsumon ni taishite, daremo kotaenakatta.', NULL, 'Không ai trả lời câu hỏi của thầy.', 6752, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17151, 'あには かっぱつなのに たいして、おとうとは おとなしい。', 'ani wa kappatsu na no ni taishite, otouto wa otonashii.', NULL, 'Trái với anh trai năng động, em trai hiền lành.', 6752, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17152, 'かれは りゅうがくせいとして にほんに きた。', 'kare wa ryuugakusei to shite nihon ni kita.', NULL, 'Anh ấy đến Nhật với tư cách du học sinh.', 6753, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17153, 'しゅみとして ギターを ひいて います。', 'shumi to shite gitaa o hiite imasu.', NULL, 'Tôi chơi guitar như một sở thích.', 6753, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17154, 'あの ひとは はんにんに ちがいない。', 'ano hito wa hannin ni chigainai.', NULL, 'Người đó chắc chắn là thủ phạm.', 6754, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17155, 'かれの ことだから、また おくれるに ちがいない。', 'kare no koto da kara, mata okureru ni chigainai.', NULL, 'Anh ta mà, chắc chắn lại đến muộn.', 6754, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17156, 'かれが そんな ことを いう はずが ない。', 'kare ga sonna koto o iu hazu ga nai.', NULL, 'Anh ấy không thể nào nói điều đó.', 6755, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17157, 'こんな かんたんな もんだいが できない はずが ない。', 'konna kantan na mondai ga dekinai hazu ga nai.', NULL, 'Không thể nào không làm được bài dễ thế này.', 6755, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17158, '1しゅうかんで ペラペラに なる わけが ない。', 'isshuukan de perapera ni naru wake ga nai.', NULL, 'Làm gì có chuyện một tuần mà nói trôi chảy.', 6756, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17159, 'あんなに れんしゅうしたのだから、まける わけが ない。', 'anna ni renshuu shita no da kara, makeru wake ga nai.', NULL, 'Luyện tập nhiều thế rồi, làm gì có chuyện thua.', 6756, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17160, 'にくが きらいな わけでは ないが、あまり たべない。', 'niku ga kirai na wake de wa nai ga, amari tabenai.', NULL, 'Không hẳn ghét thịt, nhưng tôi ít ăn.', 6757, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17161, 'いつも ひまな わけでは ない。', 'itsumo hima na wake de wa nai.', NULL, 'Không phải lúc nào cũng rảnh.', 6757, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17162, 'だいじな かいぎが あるので、やすむ わけには いかない。', 'daiji na kaigi ga aru node, yasumu wake ni wa ikanai.', NULL, 'Có cuộc họp quan trọng nên không thể nghỉ.', 6758, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17163, 'ともだちの ひみつを はなす わけには いかない。', 'tomodachi no himitsu o hanasu wake ni wa ikanai.', NULL, 'Không thể kể bí mật của bạn được.', 6758, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17164, 'がくせいは もっと べんきょうする べきだ。', 'gakusei wa motto benkyou suru beki da.', NULL, 'Học sinh nên học nhiều hơn.', 6759, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17165, 'ひとの わるくちを いう べきでは ない。', 'hito no warukuchi o iu beki de wa nai.', NULL, 'Không nên nói xấu người khác.', 6759, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17166, 'そんなに しんぱいする ことは ないよ。', 'sonna ni shinpai suru koto wa nai yo.', NULL, 'Không cần phải lo lắng thế đâu.', 6760, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17167, 'わざわざ くる ことは ありません。', 'wazawaza kuru koto wa arimasen.', NULL, 'Không cần phải cất công đến đâu.', 6760, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17168, 'きょうは はるらしい あたたかい ひだ。', 'kyou wa haru rashii atatakai hi da.', NULL, 'Hôm nay là ngày ấm áp đúng chất mùa xuân.', 6761, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17169, 'かれは おとこらしい ひとだ。', 'kare wa otoko rashii hito da.', NULL, 'Anh ấy là người rất đàn ông.', 6761, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17170, 'かれは おこりっぽい。', 'kare wa okorippoi.', NULL, 'Anh ta dễ nổi nóng.', 6762, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17171, 'この ふくは こどもっぽい。', 'kono fuku wa kodomoppoi.', NULL, 'Bộ quần áo này trông trẻ con.', 6762, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17172, 'ちきゅうの きおんは あがりつつ ある。', 'chikyuu no kion wa agaritsutsu aru.', NULL, 'Nhiệt độ trái đất đang dần tăng lên.', 6763, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17173, 'この まちの じんこうは へりつつ ある。', 'kono machi no jinkou wa heritsutsu aru.', NULL, 'Dân số thị trấn này đang giảm dần.', 6763, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17174, 'ぶっかは あがる いっぽうだ。', 'bukka wa agaru ippou da.', NULL, 'Vật giá ngày càng tăng.', 6764, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17175, 'かれの びょうきは わるく なる いっぽうだ。', 'kare no byouki wa waruku naru ippou da.', NULL, 'Bệnh của anh ấy ngày càng xấu đi.', 6764, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17176, 'ふゆは かぜを ひきがちだ。', 'fuyu wa kaze o hikigachi da.', NULL, 'Mùa đông hay bị cảm.', 6765, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17177, 'いそがしいと、しょくじが ふきそくに なりがちだ。', 'isogashii to, shokuji ga fukisoku ni narigachi da.', NULL, 'Khi bận, bữa ăn thường dễ thất thường.', 6765, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17178, 'すこし かぜぎみなので、きょうは はやく ねます。', 'sukoshi kazegimi na node, kyou wa hayaku nemasu.', NULL, 'Hơi có dấu hiệu cảm nên hôm nay tôi ngủ sớm.', 6766, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17179, 'さいきん つかれぎみだ。', 'saikin tsukaregimi da.', NULL, 'Dạo này hơi mệt mỏi.', 6766, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17180, 'でんきを つけっぱなしで ねて しまった。', 'denki o tsukeppanashi de nete shimatta.', NULL, 'Tôi ngủ quên mà để đèn bật suốt.', 6767, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17181, 'きょうは いちにちじゅう たちっぱなしだった。', 'kyou wa ichinichijuu tachippanashi datta.', NULL, 'Hôm nay đứng suốt cả ngày.', 6767, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17183, 'スマホで なんでも できる ように なった。', 'sumaho de nandemo dekiru you ni natta.', NULL, 'Giờ đây có thể làm mọi thứ bằng điện thoại.', 6768, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17184, 'ねようと した とき、でんわが なった。', 'neyou to shita toki, denwa ga natta.', NULL, 'Khi định đi ngủ thì điện thoại reo.', 6769, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17185, 'ドアを あけようと したが、あかなかった。', 'doa o akeyou to shita ga, akanakatta.', NULL, 'Tôi định mở cửa nhưng không mở được.', 6769, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17186, 'よみかけの ほんが つくえの うえに ある。', 'yomikake no hon ga tsukue no ue ni aru.', NULL, 'Cuốn sách đọc dở nằm trên bàn.', 6770, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17187, 'なにか いいかけて、やめた。', 'nanika iikakete, yameta.', NULL, 'Định nói gì đó rồi thôi.', 6770, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17188, 'あかちゃんが きゅうに なきだした。', 'akachan ga kyuu ni nakidashita.', NULL, 'Em bé đột nhiên khóc òa.', 6771, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17189, 'あめが ふりだした。', 'ame ga furidashita.', NULL, 'Trời bắt đầu mưa.', 6771, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17190, 'この ほんは いちにちで よみきった。', 'kono hon wa ichinichi de yomikitta.', NULL, 'Tôi đọc hết cuốn sách này trong một ngày.', 6772, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17191, 'りょうが おおくて、たべきれない。', 'ryou ga ookute, tabekirenai.', NULL, 'Nhiều quá, ăn không hết.', 6772, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17192, 'あさから ずっと あめが ふりつづけて いる。', 'asa kara zutto ame ga furitsuzukete iru.', NULL, 'Mưa liên tục từ sáng.', 6773, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17193, 'ゆめを もちつづける ことが たいせつだ。', 'yume o mochitsuzukeru koto ga taisetsu da.', NULL, 'Tiếp tục giữ ước mơ là điều quan trọng.', 6773, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17194, 'あしたの しけんは ちゅうしだ と いう ことだ。', 'ashita no shiken wa chuushi da to iu koto da.', NULL, 'Nghe nói bài thi ngày mai bị hủy.', 6774, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17195, 'つまり、ことしは けっこんしない と いう ことですね。', 'tsumari, kotoshi wa kekkon shinai to iu koto desu ne.', NULL, 'Tức là năm nay anh không kết hôn nhỉ.', 6774, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17196, 'たなかさん、らいげつ けっこんする とか。', 'tanaka-san, raigetsu kekkon suru toka.', NULL, 'Nghe đâu anh Tanaka tháng sau cưới.', 6775, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17197, 'あの みせ、もう しまった とか きいたよ。', 'ano mise, mou shimatta toka kiita yo.', NULL, 'Nghe bảo quán đó đóng cửa rồi.', 6775, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17198, 'あした やすみだって。', 'ashita yasumi datte.', NULL, 'Nghe bảo mai được nghỉ đấy.', 6776, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17199, '「すし」って なんですか。', '"sushi" tte nan desu ka.', NULL, '"Sushi" là gì vậy?', 6776, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17200, 'ニュースに よると、たいふうが ちかづいて いる。', 'nyuusu ni yoru to, taifuu ga chikazuite iru.', NULL, 'Theo tin tức, bão đang đến gần.', 6777, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17201, 'ちょうさに よれば、わかものの 7わりが スマホを もって いる。', 'chousa ni yoreba, wakamono no nanawari ga sumaho o motte iru.', NULL, 'Theo khảo sát, 70% người trẻ có điện thoại thông minh.', 6777, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17202, 'この おてらは 1000ねんまえに たてられた と いわれて いる。', 'kono otera wa sennen mae ni taterareta to iwarete iru.', NULL, 'Người ta nói ngôi chùa này được xây 1000 năm trước.', 6778, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17203, 'みどりちゃは けんこうに いい と いわれて いる。', 'midoricha wa kenkou ni ii to iwarete iru.', NULL, 'Người ta nói trà xanh tốt cho sức khỏe.', 6778, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17204, 'せんせいに しゅくだいを だす ように いわれた。', 'sensei ni shukudai o dasu you ni iwareta.', NULL, 'Tôi bị thầy bảo nộp bài tập.', 6779, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17205, 'ははに はやく かえる ように たのまれた。', 'haha ni hayaku kaeru you ni tanomareta.', NULL, 'Mẹ nhờ tôi về sớm.', 6779, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17206, 'ゆめみたいな はなしだ。', 'yume mitai na hanashi da.', NULL, 'Chuyện như trong mơ vậy.', 6780, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17207, 'こどもみたいに はしゃいで いる。', 'kodomo mitai ni hashaide iru.', NULL, 'Đang vui đùa như trẻ con.', 6780, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17208, 'かれは なにも なかった かのように わらって いた。', 'kare wa nani mo nakatta ka no you ni waratte ita.', NULL, 'Anh ta cười như thể không có chuyện gì.', 6781, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17209, 'まるで なつに なった かのような あつさだ。', 'marude natsu ni natta ka no you na atsusa da.', NULL, 'Nóng như thể đã sang hè.', 6781, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17210, 'この みずうみは まるで かがみの ようだ。', 'kono mizuumi wa marude kagami no you da.', NULL, 'Cái hồ này cứ như một tấm gương.', 6782, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17211, 'まるで ほんものの ような にせものだ。', 'marude honmono no you na nisemono da.', NULL, 'Đồ giả mà cứ như đồ thật.', 6782, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17212, 'かれは ねて いる ふりを して いる。', 'kare wa nete iru furi o shite iru.', NULL, 'Anh ấy đang giả vờ ngủ.', 6783, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17213, 'きこえない ふりを しないで。', 'kikoenai furi o shinaide.', NULL, 'Đừng giả vờ không nghe thấy.', 6783, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17214, 'この アパートは ひろい うえに、やちんも やすい。', 'kono apaato wa hiroi ue ni, yachin mo yasui.', NULL, 'Căn hộ này đã rộng lại còn rẻ.', 6784, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17215, 'みちに まよった うえに、あめまで ふって きた。', 'michi ni mayotta ue ni, ame made futte kita.', NULL, 'Đã lạc đường lại còn mưa nữa.', 6784, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17216, 'かのじょは うたが じょうずな だけでなく、ダンスも うまい。', 'kanojo wa uta ga jouzu na dake de naku, dansu mo umai.', NULL, 'Cô ấy không chỉ hát hay mà còn nhảy giỏi.', 6785, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17217, 'べんきょう だけでなく、スポーツも がんばって いる。', 'benkyou dake de naku, supootsu mo ganbatte iru.', NULL, 'Không chỉ học mà còn chăm thể thao.', 6785, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17218, 'ぶちょうの かわりに、わたしが かいぎに でた。', 'buchou no kawari ni, watashi ga kaigi ni deta.', NULL, 'Tôi dự họp thay trưởng phòng.', 6786, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17219, 'えいごを おしえて もらう かわりに、にほんごを おしえた。', 'eigo o oshiete morau kawari ni, nihongo o oshieta.', NULL, 'Đổi lại việc được dạy tiếng Anh, tôi dạy tiếng Nhật.', 6786, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17220, 'せまい ながらも、じぶんの いえが ほしい。', 'semai nagara mo, jibun no ie ga hoshii.', NULL, 'Dù chật nhưng tôi muốn có nhà riêng.', 6787, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17221, 'わかって いながらも、また おなじ しっぱいを した。', 'wakatte inagara mo, mata onaji shippai o shita.', NULL, 'Dù biết nhưng vẫn mắc lại lỗi cũ.', 6787, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17222, 'ちちに かわって、わたしが ごあいさつします。', 'chichi ni kawatte, watashi ga goaisatsu shimasu.', NULL, 'Thay mặt bố, tôi xin phát biểu.', 6788, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17223, 'にんげんに かわって、ロボットが はたらく じだいだ。', 'ningen ni kawatte, robotto ga hataraku jidai da.', NULL, 'Thời đại robot làm việc thay con người.', 6788, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17224, 'とうきょうを はじめ、おおきい まちは ひとが おおい。', 'toukyou o hajime, ookii machi wa hito ga ooi.', NULL, 'Các thành phố lớn, tiêu biểu là Tokyo, rất đông người.', 6789, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17225, 'しゃちょうを はじめ、しゃいん ぜんいんが さんかした。', 'shachou o hajime, shain zen''in ga sanka shita.', NULL, 'Từ giám đốc đến toàn bộ nhân viên đều tham gia.', 6789, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17226, 'わたしなんか、とても かないません。', 'watashi nanka, totemo kanaimasen.', NULL, 'Người như tôi thì không sánh được đâu.', 6790, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17227, 'おばけなど いる わけが ない。', 'obake nado iru wake ga nai.', NULL, 'Làm gì có ma quỷ.', 6790, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17228, 'ざんねんな ことに、しあいに まけて しまった。', 'zannen na koto ni, shiai ni makete shimatta.', NULL, 'Thật đáng tiếc là đã thua trận.', 6791, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17229, 'おどろいた ことに、かれは 10かこくごが はなせる。', 'odoroita koto ni, kare wa jukkakokugo ga hanaseru.', NULL, 'Ngạc nhiên thay, anh ấy nói được 10 thứ tiếng.', 6791, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17230, 'じょうきょうは わるく なる ばかりだ。', 'joukyou wa waruku naru bakari da.', NULL, 'Tình hình chỉ ngày càng xấu đi.', 6792, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17231, 'じゅんびは できて いて、あとは はじめる ばかりだ。', 'junbi wa dekite ite, ato wa hajimeru bakari da.', NULL, 'Đã chuẩn bị xong, giờ chỉ còn bắt đầu.', 6792, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17232, 'ベルが なるか ならないかの うちに、せいとは きょうしつを でた。', 'beru ga naru ka naranai ka no uchi ni, seito wa kyoushitsu o deta.', NULL, 'Chuông vừa reo là học sinh đã ra khỏi lớp.', 6793, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17233, 'すわるか すわらないかの うちに、ねて しまった。', 'suwaru ka suwaranai ka no uchi ni, nete shimatta.', NULL, 'Vừa ngồi xuống là ngủ mất.', 6793, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17234, 'だって、しらなかったんだもの。', 'datte, shiranakatta n da mono.', NULL, 'Vì em không biết mà.', 6794, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17235, 'いきたくないよ。つかれて いるもん。', 'ikitakunai yo. tsukarete iru mon.', NULL, 'Không muốn đi đâu. Mệt mà.', 6794, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17236, 'じかんが たつのは はやい ものだ。', 'jikan ga tatsu no wa hayai mono da.', NULL, 'Thời gian trôi thật nhanh.', 6795, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17237, 'こどもの ころ、よく この かわで あそんだ ものだ。', 'kodomo no koro, yoku kono kawa de asonda mono da.', NULL, 'Hồi nhỏ tôi hay chơi ở con sông này.', 6795, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17238, 'かぜを なおしたいなら、よく ねる ことだ。', 'kaze o naoshitai nara, yoku neru koto da.', NULL, 'Muốn khỏi cảm thì nên ngủ nhiều.', 6796, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17239, 'じょうずに なりたければ、まいにち れんしゅうする ことだ。', 'jouzu ni naritakereba, mainichi renshuu suru koto da.', NULL, 'Muốn giỏi thì nên luyện tập hằng ngày.', 6796, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17240, 'ねぼうした せいで、でんしゃに のりおくれた。', 'nebou shita sei de, densha ni noriokureta.', NULL, 'Tại ngủ quên nên tôi lỡ tàu.', 6797, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17241, 'あめの せいで、しあいが ちゅうしに なった。', 'ame no sei de, shiai ga chuushi ni natta.', NULL, 'Tại mưa nên trận đấu bị hủy.', 6797, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17242, 'せんせいの おかげで、ごうかくできました。', 'sensei no okage de, goukaku dekimashita.', NULL, 'Nhờ thầy mà tôi đã đỗ.', 6798, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17243, 'くすりを のんだ おかげで、ねつが さがった。', 'kusuri o nonda okage de, netsu ga sagatta.', NULL, 'Nhờ uống thuốc mà hạ sốt.', 6798, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17244, 'じしんに よって、おおくの いえが たおれた。', 'jishin ni yotte, ooku no ie ga taoreta.', NULL, 'Do động đất, nhiều ngôi nhà bị đổ.', 6799, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17245, 'ふちゅういに よる じこが ふえて いる。', 'fuchuui ni yoru jiko ga fuete iru.', NULL, 'Tai nạn do bất cẩn đang tăng lên.', 6799, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17246, 'おおゆきの ため、でんしゃが とまって います。', 'ooyuki no tame, densha ga tomatte imasu.', NULL, 'Vì tuyết lớn nên tàu đang ngừng chạy.', 6800, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17247, 'こうじちゅうの ため、この みちは とおれません。', 'koujichuu no tame, kono michi wa tooremasen.', NULL, 'Vì đang thi công nên không đi qua đường này được.', 6800, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17248, 'あなたの ことを しんぱいして いる から こそ、ちゅういするのです。', 'anata no koto o shinpai shite iru kara koso, chuui suru no desu.', NULL, 'Chính vì lo cho bạn nên tôi mới nhắc nhở.', 6801, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17249, 'むずかしい から こそ、やる かちが ある。', 'muzukashii kara koso, yaru kachi ga aru.', NULL, 'Chính vì khó nên mới đáng làm.', 6801, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17250, 'わすれない ように、メモして おきます。', 'wasurenai you ni, memo shite okimasu.', NULL, 'Tôi ghi chú lại để khỏi quên.', 6802, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17251, 'だれでも わかる ように、やさしく せつめいした。', 'daredemo wakaru you ni, yasashiku setsumei shita.', NULL, 'Tôi giải thích dễ hiểu để ai cũng hiểu được.', 6802, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17252, 'かたちが にて いる ことから、この なまえが ついた。', 'katachi ga nite iru koto kara, kono namae ga tsuita.', NULL, 'Vì hình dạng giống nên mới có tên này.', 6803, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17253, 'へやの でんきが ついて いる ことから、かれは いえに いると わかった。', 'heya no denki ga tsuite iru koto kara, kare wa ie ni iru to wakatta.', NULL, 'Từ việc đèn phòng đang bật, tôi biết anh ấy ở nhà.', 6803, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17254, '10ねんも にほんに すんで いたのか。にほんごが じょうずな わけだ。', 'juunen mo nihon ni sunde ita no ka. nihongo ga jouzu na wake da.', NULL, 'Sống ở Nhật tận 10 năm à. Thảo nào tiếng Nhật giỏi.', 6804, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17255, 'エアコンが こわれて いる。あつい わけだ。', 'eakon ga kowarete iru. atsui wake da.', NULL, 'Điều hòa hỏng rồi. Thảo nào nóng.', 6804, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17256, 'もう すこしで くるまに ひかれる ところだった。', 'mou sukoshi de kuruma ni hikareru tokoro datta.', NULL, 'Suýt nữa thì bị xe tông.', 6805, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17257, 'めざましが なかったら、ちこくする ところだった。', 'mezamashi ga nakattara, chikoku suru tokoro datta.', NULL, 'Nếu không có đồng hồ báo thức thì suýt muộn rồi.', 6805, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17258, 'いま べんきょうしないと、あとで こまる ことに なる。', 'ima benkyou shinai to, ato de komaru koto ni naru.', NULL, 'Bây giờ không học thì sau này sẽ khổ.', 6806, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17259, 'しゅうに 3かい かよえば、ひとつきで 12かい いく ことに なる。', 'shuu ni sankai kayoeba, hitotsuki de juunikai iku koto ni naru.', NULL, 'Tuần đi 3 lần thì một tháng sẽ đi 12 lần.', 6806, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17260, 'パスワードを わすれた ばかりに、ひどい めに あった。', 'pasuwaado o wasureta bakari ni, hidoi me ni atta.', NULL, 'Chỉ vì quên mật khẩu mà gặp rắc rối to.', 6807, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17261, 'よけいな ことを いった ばかりに、けんかに なった。', 'yokei na koto o itta bakari ni, kenka ni natta.', NULL, 'Chỉ vì nói điều thừa thãi mà thành cãi nhau.', 6807, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17262, 'もう おとななのだから、じぶんで きめなさい。', 'mou otona na no da kara, jibun de kimenasai.', NULL, 'Đã là người lớn rồi thì tự quyết định đi.', 6808, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17263, 'やくそくしたのだから、まもらなければ ならない。', 'yakusoku shita no da kara, mamoranakereba naranai.', NULL, 'Đã hứa rồi thì phải giữ lời.', 6808, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17264, 'わかい うちに、いろいろな くにへ いきたい。', 'wakai uchi ni, iroiro na kuni e ikitai.', NULL, 'Tôi muốn đi nhiều nước khi còn trẻ.', 6809, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17265, 'あつい うちに、どうぞ めしあがって ください。', 'atsui uchi ni, douzo meshiagatte kudasai.', NULL, 'Xin mời ăn khi còn nóng.', 6809, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17266, 'あめが ふらない うちに、かえりましょう。', 'ame ga furanai uchi ni, kaerimashou.', NULL, 'Về thôi trước khi trời mưa.', 6810, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17267, 'わすれない うちに、メモして おこう。', 'wasurenai uchi ni, memo shite okou.', NULL, 'Ghi lại trước khi quên thôi.', 6810, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17268, 'かいぎの さいちゅうに、でんわが なった。', 'kaigi no saichuu ni, denwa ga natta.', NULL, 'Đúng lúc đang họp thì điện thoại reo.', 6811, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17269, 'しょくじを して いる さいちゅうに、じしんが あった。', 'shokuji o shite iru saichuu ni, jishin ga atta.', NULL, 'Đúng lúc đang ăn thì có động đất.', 6811, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17270, 'いえを でた とたん、あめが ふりだした。', 'ie o deta totan, ame ga furidashita.', NULL, 'Vừa ra khỏi nhà thì trời đổ mưa.', 6812, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17271, 'ベッドに はいった とたんに、ねて しまった。', 'beddo ni haitta totan ni, nete shimatta.', NULL, 'Vừa lên giường là ngủ luôn.', 6812, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17272, 'にほんに きて いらい、いちども かえって いない。', 'nihon ni kite irai, ichido mo kaette inai.', NULL, 'Kể từ khi sang Nhật, tôi chưa về lần nào.', 6813, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17273, 'そつぎょうして いらい、かれに あって いない。', 'sotsugyou shite irai, kare ni atte inai.', NULL, 'Từ khi tốt nghiệp tôi chưa gặp anh ấy.', 6813, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17274, 'びょうきに なって はじめて、けんこうの たいせつさが わかった。', 'byouki ni natte hajimete, kenkou no taisetsusa ga wakatta.', NULL, 'Phải đến khi ốm mới hiểu sức khỏe quý giá.', 6814, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17275, 'ひとりで くらして はじめて、おやの ありがたさを かんじた。', 'hitori de kurashite hajimete, oya no arigatasa o kanjita.', NULL, 'Phải sống một mình mới thấy biết ơn cha mẹ.', 6814, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17276, 'でかけようと した ところに、ともだちが きた。', 'dekakeyou to shita tokoro ni, tomodachi ga kita.', NULL, 'Đúng lúc định ra ngoài thì bạn đến.', 6815, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17277, 'こまって いる ところへ、せんぱいが たすけて くれた。', 'komatte iru tokoro e, senpai ga tasukete kureta.', NULL, 'Đúng lúc đang khó thì đàn anh giúp.', 6815, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17278, 'この うたを きく たびに、こきょうを おもいだす。', 'kono uta o kiku tabi ni, kokyou o omoidasu.', NULL, 'Mỗi lần nghe bài hát này, tôi lại nhớ quê.', 6816, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17279, 'りょこうの たびに、おみやげを かって くる。', 'ryokou no tabi ni, omiyage o katte kuru.', NULL, 'Mỗi lần đi du lịch, tôi đều mua quà về.', 6816, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17280, 'かいものの ついでに、ゆうびんきょくに よった。', 'kaimono no tsuide ni, yuubinkyoku ni yotta.', NULL, 'Nhân tiện đi mua sắm, tôi ghé bưu điện.', 6817, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17281, 'さんぽに いく ついでに、ごみを だして きて。', 'sanpo ni iku tsuide ni, gomi o dashite kite.', NULL, 'Tiện đi dạo thì đổ rác giúp nhé.', 6817, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17282, 'しゅくだいを おえて からでないと、あそびに いっては だめ。', 'shukudai o oete kara de nai to, asobi ni itte wa dame.', NULL, 'Chưa làm xong bài tập thì không được đi chơi.', 6818, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17283, 'じっさいに みて からでなければ、きめられない。', 'jissai ni mite kara de nakereba, kimerarenai.', NULL, 'Chưa xem tận mắt thì không quyết định được.', 6818, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17284, 'かれとは きょねん あった きり、れんらくが ない。', 'kare to wa kyonen atta kiri, renraku ga nai.', NULL, 'Gặp anh ấy năm ngoái rồi thôi, không liên lạc nữa.', 6819, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17285, 'むすこは あさ でかけた きり、まだ かえって こない。', 'musuko wa asa dekaketa kiri, mada kaette konai.', NULL, 'Con trai đi từ sáng đến giờ vẫn chưa về.', 6819, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17286, 'もし 1おくえん あたった としたら、なにに つかいますか。', 'moshi ichiokuen atatta to shitara, nani ni tsukaimasu ka.', NULL, 'Giả sử trúng 100 triệu yên thì bạn tiêu vào gì?', 6820, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17287, 'この はなしが ほんとうだ とすれば、たいへんな ことだ。', 'kono hanashi ga hontou da to sureba, taihen na koto da.', NULL, 'Nếu chuyện này là thật thì nghiêm trọng đấy.', 6820, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17416, 'じかんが たつのは はやい ものだ。', 'jikan ga tatsu no wa hayai mono da.', NULL, 'Thời gian trôi thật nhanh.', 6885, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17288, 'じかん さえ あれば、もっと べんきょうできるのに。', 'jikan sae areba, motto benkyou dekiru noni.', NULL, 'Chỉ cần có thời gian là học được nhiều hơn.', 6821, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17289, 'この くすりを のみ さえ すれば、なおりますよ。', 'kono kusuri o nomi sae sureba, naorimasu yo.', NULL, 'Chỉ cần uống thuốc này là khỏi.', 6821, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17290, 'れんしゅうしない かぎり、じょうずに ならない。', 'renshuu shinai kagiri, jouzu ni naranai.', NULL, 'Chừng nào chưa luyện tập thì không giỏi được.', 6822, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17291, 'あめが ふらない かぎり、しあいは おこなわれます。', 'ame ga furanai kagiri, shiai wa okonawaremasu.', NULL, 'Trừ khi trời mưa, trận đấu vẫn diễn ra.', 6822, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17292, 'たとえ はんたいされても、わたしは やります。', 'tatoe hantai saretemo, watashi wa yarimasu.', NULL, 'Cho dù bị phản đối, tôi vẫn làm.', 6823, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17293, 'たとえ たかくても、ほしい ものは かう。', 'tatoe takakutemo, hoshii mono wa kau.', NULL, 'Dù có đắt tôi vẫn mua thứ mình muốn.', 6823, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17294, 'いまから いった としても、まにあわないだろう。', 'ima kara itta to shitemo, maniawanai darou.', NULL, 'Dù bây giờ đi thì chắc cũng không kịp.', 6824, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17295, 'しっぱいした としても、こうかいしない。', 'shippai shita to shitemo, koukai shinai.', NULL, 'Dù có thất bại, tôi cũng không hối hận.', 6824, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17296, 'しらない くせに、しって いる ふりを する。', 'shiranai kuse ni, shitte iru furi o suru.', NULL, 'Không biết vậy mà cứ làm như biết.', 6825, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17297, 'じぶんは やらない くせに、ひとには もんくを いう。', 'jibun wa yaranai kuse ni, hito ni wa monku o iu.', NULL, 'Bản thân không làm vậy mà lại chê người khác.', 6825, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17298, 'いそがしければ、あした でも かまいません。', 'isogashikereba, ashita demo kamaimasen.', NULL, 'Nếu bận thì mai cũng không sao.', 6826, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17299, 'ここに すわっても かまいませんか。', 'koko ni suwattemo kamaimasen ka.', NULL, 'Tôi ngồi đây có sao không?', 6826, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17300, 'もっと はやく いえを でれば よかった。', 'motto hayaku ie o dereba yokatta.', NULL, 'Giá mà ra khỏi nhà sớm hơn.', 6827, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17301, 'あんな こと、いわなければ よかった。', 'anna koto, iwanakereba yokatta.', NULL, 'Giá mà đừng nói điều như thế.', 6827, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17302, 'できる ものなら、むかしに もどりたい。', 'dekiru mono nara, mukashi ni modoritai.', NULL, 'Nếu có thể, tôi muốn quay về ngày xưa.', 6828, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17303, 'いける ものなら、いますぐ いきたい。', 'ikeru mono nara, ima sugu ikitai.', NULL, 'Nếu đi được thì tôi muốn đi ngay.', 6828, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17304, 'じっさいに やって みない ことには、わからない。', 'jissai ni yatte minai koto ni wa, wakaranai.', NULL, 'Không làm thử thì không biết được.', 6829, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17305, 'おかねが ない ことには、なにも はじめられない。', 'okane ga nai koto ni wa, nani mo hajimerarenai.', NULL, 'Không có tiền thì chẳng bắt đầu được gì.', 6829, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17306, 'あめが ふっても ふらなくても、いきます。', 'ame ga futtemo furanakutemo, ikimasu.', NULL, 'Dù mưa hay không, tôi vẫn đi.', 6830, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17307, 'すきでも すきじゃなくても、たべなさい。', 'suki demo suki ja nakutemo, tabenasai.', NULL, 'Thích hay không thì cũng ăn đi.', 6830, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17308, 'なきたい ほど つかれた。', 'nakitai hodo tsukareta.', NULL, 'Mệt đến mức muốn khóc.', 6831, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17309, 'しんじられない くらい きれいな けしきだった。', 'shinjirarenai kurai kirei na keshiki datta.', NULL, 'Phong cảnh đẹp đến mức không thể tin nổi.', 6831, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17310, 'ことしは きょねん ほど あつくない。', 'kotoshi wa kyonen hodo atsukunai.', NULL, 'Năm nay không nóng bằng năm ngoái.', 6832, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17311, 'かれ ほど まじめな ひとは いない。', 'kare hodo majime na hito wa inai.', NULL, 'Không ai nghiêm túc bằng anh ấy.', 6832, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17312, 'とかいに くらべて、いなかは くらしやすい。', 'tokai ni kurabete, inaka wa kurashiyasui.', NULL, 'So với thành phố, nông thôn dễ sống hơn.', 6833, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17313, 'きょねんに くらべて、きゃくが ふえた。', 'kyonen ni kurabete, kyaku ga fueta.', NULL, 'So với năm ngoái, khách đã tăng lên.', 6833, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17314, 'できる だけ はやく へんじを ください。', 'dekiru dake hayaku henji o kudasai.', NULL, 'Hãy trả lời sớm nhất có thể.', 6834, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17315, 'すきな だけ たべて いいですよ。', 'suki na dake tabete ii desu yo.', NULL, 'Ăn bao nhiêu tùy thích nhé.', 6834, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17316, 'バスが ないから、あるいて いく ほかない。', 'basu ga nai kara, aruite iku hoka nai.', NULL, 'Không có xe buýt nên chỉ còn cách đi bộ.', 6835, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17317, 'やくそくした いじょう、やる しか ない。', 'yakusoku shita ijou, yaru shika nai.', NULL, 'Đã hứa rồi thì chỉ còn cách làm thôi.', 6835, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17318, 'いそいで いる ときに かぎって、でんしゃが おくれる。', 'isoide iru toki ni kagitte, densha ga okureru.', NULL, 'Cứ lúc vội là tàu lại trễ.', 6836, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17319, 'うちの こに かぎって、そんな ことは しない。', 'uchi no ko ni kagitte, sonna koto wa shinai.', NULL, 'Riêng con nhà tôi thì không làm chuyện đó đâu.', 6836, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17320, 'かれは えいご ばかりか、フランスごも はなせる。', 'kare wa eigo bakari ka, furansugo mo hanaseru.', NULL, 'Anh ấy không chỉ nói tiếng Anh mà cả tiếng Pháp.', 6837, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17321, 'この みせは やすい ばかりでなく、おいしい。', 'kono mise wa yasui bakari de naku, oishii.', NULL, 'Quán này không những rẻ mà còn ngon.', 6837, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17322, 'なつやすみ ほど たのしい ものは ない。', 'natsuyasumi hodo tanoshii mono wa nai.', NULL, 'Không có gì vui bằng kỳ nghỉ hè.', 6838, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17323, 'けんこう ほど たいせつな ものは ない。', 'kenkou hodo taisetsu na mono wa nai.', NULL, 'Không có gì quý bằng sức khỏe.', 6838, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17324, 'としを とる ほど、じかんが はやく かんじる。', 'toshi o toru hodo, jikan ga hayaku kanjiru.', NULL, 'Càng có tuổi càng thấy thời gian trôi nhanh.', 6839, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17325, 'かんがえる ほど わからなく なる。', 'kangaeru hodo wakaranaku naru.', NULL, 'Càng nghĩ càng không hiểu.', 6839, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17326, 'わたしに とって、かぞくが いちばん たいせつだ。', 'watashi ni totte, kazoku ga ichiban taisetsu da.', NULL, 'Đối với tôi, gia đình là quan trọng nhất.', 6840, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17327, 'がくせいに とって、この ほんは たかすぎる。', 'gakusei ni totte, kono hon wa takasugiru.', NULL, 'Đối với sinh viên, cuốn sách này quá đắt.', 6840, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17328, 'にほんの れきしに ついて しらべて います。', 'nihon no rekishi ni tsuite shirabete imasu.', NULL, 'Tôi đang tìm hiểu về lịch sử Nhật Bản.', 6841, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17329, 'その けんに ついては、あとで はなしましょう。', 'sono ken ni tsuite wa, ato de hanashimashou.', NULL, 'Về việc đó, lát nữa ta bàn nhé.', 6841, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17330, 'せんせいの しつもんに たいして、だれも こたえなかった。', 'sensei no shitsumon ni taishite, daremo kotaenakatta.', NULL, 'Không ai trả lời câu hỏi của thầy.', 6842, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17331, 'あには かっぱつなのに たいして、おとうとは おとなしい。', 'ani wa kappatsu na no ni taishite, otouto wa otonashii.', NULL, 'Trái với anh trai năng động, em trai hiền lành.', 6842, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17332, 'かれは りゅうがくせいとして にほんに きた。', 'kare wa ryuugakusei to shite nihon ni kita.', NULL, 'Anh ấy đến Nhật với tư cách du học sinh.', 6843, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17333, 'しゅみとして ギターを ひいて います。', 'shumi to shite gitaa o hiite imasu.', NULL, 'Tôi chơi guitar như một sở thích.', 6843, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17334, 'あの ひとは はんにんに ちがいない。', 'ano hito wa hannin ni chigainai.', NULL, 'Người đó chắc chắn là thủ phạm.', 6844, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17335, 'かれの ことだから、また おくれるに ちがいない。', 'kare no koto da kara, mata okureru ni chigainai.', NULL, 'Anh ta mà, chắc chắn lại đến muộn.', 6844, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17336, 'かれが そんな ことを いう はずが ない。', 'kare ga sonna koto o iu hazu ga nai.', NULL, 'Anh ấy không thể nào nói điều đó.', 6845, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17337, 'こんな かんたんな もんだいが できない はずが ない。', 'konna kantan na mondai ga dekinai hazu ga nai.', NULL, 'Không thể nào không làm được bài dễ thế này.', 6845, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17338, '1しゅうかんで ペラペラに なる わけが ない。', 'isshuukan de perapera ni naru wake ga nai.', NULL, 'Làm gì có chuyện một tuần mà nói trôi chảy.', 6846, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17339, 'あんなに れんしゅうしたのだから、まける わけが ない。', 'anna ni renshuu shita no da kara, makeru wake ga nai.', NULL, 'Luyện tập nhiều thế rồi, làm gì có chuyện thua.', 6846, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17340, 'にくが きらいな わけでは ないが、あまり たべない。', 'niku ga kirai na wake de wa nai ga, amari tabenai.', NULL, 'Không hẳn ghét thịt, nhưng tôi ít ăn.', 6847, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17341, 'いつも ひまな わけでは ない。', 'itsumo hima na wake de wa nai.', NULL, 'Không phải lúc nào cũng rảnh.', 6847, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17342, 'だいじな かいぎが あるので、やすむ わけには いかない。', 'daiji na kaigi ga aru node, yasumu wake ni wa ikanai.', NULL, 'Có cuộc họp quan trọng nên không thể nghỉ.', 6848, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17343, 'ともだちの ひみつを はなす わけには いかない。', 'tomodachi no himitsu o hanasu wake ni wa ikanai.', NULL, 'Không thể kể bí mật của bạn được.', 6848, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17344, 'がくせいは もっと べんきょうする べきだ。', 'gakusei wa motto benkyou suru beki da.', NULL, 'Học sinh nên học nhiều hơn.', 6849, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17345, 'ひとの わるくちを いう べきでは ない。', 'hito no warukuchi o iu beki de wa nai.', NULL, 'Không nên nói xấu người khác.', 6849, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17346, 'そんなに しんぱいする ことは ないよ。', 'sonna ni shinpai suru koto wa nai yo.', NULL, 'Không cần phải lo lắng thế đâu.', 6850, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17347, 'わざわざ くる ことは ありません。', 'wazawaza kuru koto wa arimasen.', NULL, 'Không cần phải cất công đến đâu.', 6850, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17348, 'きょうは はるらしい あたたかい ひだ。', 'kyou wa haru rashii atatakai hi da.', NULL, 'Hôm nay là ngày ấm áp đúng chất mùa xuân.', 6851, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17349, 'かれは おとこらしい ひとだ。', 'kare wa otoko rashii hito da.', NULL, 'Anh ấy là người rất đàn ông.', 6851, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17350, 'かれは おこりっぽい。', 'kare wa okorippoi.', NULL, 'Anh ta dễ nổi nóng.', 6852, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17351, 'この ふくは こどもっぽい。', 'kono fuku wa kodomoppoi.', NULL, 'Bộ quần áo này trông trẻ con.', 6852, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17352, 'ちきゅうの きおんは あがりつつ ある。', 'chikyuu no kion wa agaritsutsu aru.', NULL, 'Nhiệt độ trái đất đang dần tăng lên.', 6853, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17353, 'この まちの じんこうは へりつつ ある。', 'kono machi no jinkou wa heritsutsu aru.', NULL, 'Dân số thị trấn này đang giảm dần.', 6853, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17354, 'ぶっかは あがる いっぽうだ。', 'bukka wa agaru ippou da.', NULL, 'Vật giá ngày càng tăng.', 6854, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17355, 'かれの びょうきは わるく なる いっぽうだ。', 'kare no byouki wa waruku naru ippou da.', NULL, 'Bệnh của anh ấy ngày càng xấu đi.', 6854, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17356, 'ふゆは かぜを ひきがちだ。', 'fuyu wa kaze o hikigachi da.', NULL, 'Mùa đông hay bị cảm.', 6855, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17357, 'いそがしいと、しょくじが ふきそくに なりがちだ。', 'isogashii to, shokuji ga fukisoku ni narigachi da.', NULL, 'Khi bận, bữa ăn thường dễ thất thường.', 6855, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17358, 'すこし かぜぎみなので、きょうは はやく ねます。', 'sukoshi kazegimi na node, kyou wa hayaku nemasu.', NULL, 'Hơi có dấu hiệu cảm nên hôm nay tôi ngủ sớm.', 6856, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17359, 'さいきん つかれぎみだ。', 'saikin tsukaregimi da.', NULL, 'Dạo này hơi mệt mỏi.', 6856, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17360, 'でんきを つけっぱなしで ねて しまった。', 'denki o tsukeppanashi de nete shimatta.', NULL, 'Tôi ngủ quên mà để đèn bật suốt.', 6857, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17361, 'きょうは いちにちじゅう たちっぱなしだった。', 'kyou wa ichinichijuu tachippanashi datta.', NULL, 'Hôm nay đứng suốt cả ngày.', 6857, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17363, 'スマホで なんでも できる ように なった。', 'sumaho de nandemo dekiru you ni natta.', NULL, 'Giờ đây có thể làm mọi thứ bằng điện thoại.', 6858, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17364, 'ねようと した とき、でんわが なった。', 'neyou to shita toki, denwa ga natta.', NULL, 'Khi định đi ngủ thì điện thoại reo.', 6859, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17365, 'ドアを あけようと したが、あかなかった。', 'doa o akeyou to shita ga, akanakatta.', NULL, 'Tôi định mở cửa nhưng không mở được.', 6859, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17366, 'よみかけの ほんが つくえの うえに ある。', 'yomikake no hon ga tsukue no ue ni aru.', NULL, 'Cuốn sách đọc dở nằm trên bàn.', 6860, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17367, 'なにか いいかけて、やめた。', 'nanika iikakete, yameta.', NULL, 'Định nói gì đó rồi thôi.', 6860, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17368, 'あかちゃんが きゅうに なきだした。', 'akachan ga kyuu ni nakidashita.', NULL, 'Em bé đột nhiên khóc òa.', 6861, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17369, 'あめが ふりだした。', 'ame ga furidashita.', NULL, 'Trời bắt đầu mưa.', 6861, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17370, 'この ほんは いちにちで よみきった。', 'kono hon wa ichinichi de yomikitta.', NULL, 'Tôi đọc hết cuốn sách này trong một ngày.', 6862, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17371, 'りょうが おおくて、たべきれない。', 'ryou ga ookute, tabekirenai.', NULL, 'Nhiều quá, ăn không hết.', 6862, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17372, 'あさから ずっと あめが ふりつづけて いる。', 'asa kara zutto ame ga furitsuzukete iru.', NULL, 'Mưa liên tục từ sáng.', 6863, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17373, 'ゆめを もちつづける ことが たいせつだ。', 'yume o mochitsuzukeru koto ga taisetsu da.', NULL, 'Tiếp tục giữ ước mơ là điều quan trọng.', 6863, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17374, 'あしたの しけんは ちゅうしだ と いう ことだ。', 'ashita no shiken wa chuushi da to iu koto da.', NULL, 'Nghe nói bài thi ngày mai bị hủy.', 6864, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17375, 'つまり、ことしは けっこんしない と いう ことですね。', 'tsumari, kotoshi wa kekkon shinai to iu koto desu ne.', NULL, 'Tức là năm nay anh không kết hôn nhỉ.', 6864, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17376, 'たなかさん、らいげつ けっこんする とか。', 'tanaka-san, raigetsu kekkon suru toka.', NULL, 'Nghe đâu anh Tanaka tháng sau cưới.', 6865, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17377, 'あの みせ、もう しまった とか きいたよ。', 'ano mise, mou shimatta toka kiita yo.', NULL, 'Nghe bảo quán đó đóng cửa rồi.', 6865, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17378, 'あした やすみだって。', 'ashita yasumi datte.', NULL, 'Nghe bảo mai được nghỉ đấy.', 6866, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17379, '「すし」って なんですか。', '"sushi" tte nan desu ka.', NULL, '"Sushi" là gì vậy?', 6866, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17380, 'ニュースに よると、たいふうが ちかづいて いる。', 'nyuusu ni yoru to, taifuu ga chikazuite iru.', NULL, 'Theo tin tức, bão đang đến gần.', 6867, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17381, 'ちょうさに よれば、わかものの 7わりが スマホを もって いる。', 'chousa ni yoreba, wakamono no nanawari ga sumaho o motte iru.', NULL, 'Theo khảo sát, 70% người trẻ có điện thoại thông minh.', 6867, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17382, 'この おてらは 1000ねんまえに たてられた と いわれて いる。', 'kono otera wa sennen mae ni taterareta to iwarete iru.', NULL, 'Người ta nói ngôi chùa này được xây 1000 năm trước.', 6868, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17383, 'みどりちゃは けんこうに いい と いわれて いる。', 'midoricha wa kenkou ni ii to iwarete iru.', NULL, 'Người ta nói trà xanh tốt cho sức khỏe.', 6868, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17384, 'せんせいに しゅくだいを だす ように いわれた。', 'sensei ni shukudai o dasu you ni iwareta.', NULL, 'Tôi bị thầy bảo nộp bài tập.', 6869, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17385, 'ははに はやく かえる ように たのまれた。', 'haha ni hayaku kaeru you ni tanomareta.', NULL, 'Mẹ nhờ tôi về sớm.', 6869, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17386, 'ゆめみたいな はなしだ。', 'yume mitai na hanashi da.', NULL, 'Chuyện như trong mơ vậy.', 6870, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17387, 'こどもみたいに はしゃいで いる。', 'kodomo mitai ni hashaide iru.', NULL, 'Đang vui đùa như trẻ con.', 6870, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17388, 'かれは なにも なかった かのように わらって いた。', 'kare wa nani mo nakatta ka no you ni waratte ita.', NULL, 'Anh ta cười như thể không có chuyện gì.', 6871, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17389, 'まるで なつに なった かのような あつさだ。', 'marude natsu ni natta ka no you na atsusa da.', NULL, 'Nóng như thể đã sang hè.', 6871, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17390, 'この みずうみは まるで かがみの ようだ。', 'kono mizuumi wa marude kagami no you da.', NULL, 'Cái hồ này cứ như một tấm gương.', 6872, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17391, 'まるで ほんものの ような にせものだ。', 'marude honmono no you na nisemono da.', NULL, 'Đồ giả mà cứ như đồ thật.', 6872, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17394, 'この アパートは ひろい うえに、やちんも やすい。', 'kono apaato wa hiroi ue ni, yachin mo yasui.', NULL, 'Căn hộ này đã rộng lại còn rẻ.', 6874, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17395, 'みちに まよった うえに、あめまで ふって きた。', 'michi ni mayotta ue ni, ame made futte kita.', NULL, 'Đã lạc đường lại còn mưa nữa.', 6874, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17396, 'かのじょは うたが じょうずな だけでなく、ダンスも うまい。', 'kanojo wa uta ga jouzu na dake de naku, dansu mo umai.', NULL, 'Cô ấy không chỉ hát hay mà còn nhảy giỏi.', 6875, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17397, 'べんきょう だけでなく、スポーツも がんばって いる。', 'benkyou dake de naku, supootsu mo ganbatte iru.', NULL, 'Không chỉ học mà còn chăm thể thao.', 6875, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17398, 'ぶちょうの かわりに、わたしが かいぎに でた。', 'buchou no kawari ni, watashi ga kaigi ni deta.', NULL, 'Tôi dự họp thay trưởng phòng.', 6876, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17399, 'えいごを おしえて もらう かわりに、にほんごを おしえた。', 'eigo o oshiete morau kawari ni, nihongo o oshieta.', NULL, 'Đổi lại việc được dạy tiếng Anh, tôi dạy tiếng Nhật.', 6876, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17400, 'せまい ながらも、じぶんの いえが ほしい。', 'semai nagara mo, jibun no ie ga hoshii.', NULL, 'Dù chật nhưng tôi muốn có nhà riêng.', 6877, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17401, 'わかって いながらも、また おなじ しっぱいを した。', 'wakatte inagara mo, mata onaji shippai o shita.', NULL, 'Dù biết nhưng vẫn mắc lại lỗi cũ.', 6877, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17402, 'ちちに かわって、わたしが ごあいさつします。', 'chichi ni kawatte, watashi ga goaisatsu shimasu.', NULL, 'Thay mặt bố, tôi xin phát biểu.', 6878, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17403, 'にんげんに かわって、ロボットが はたらく じだいだ。', 'ningen ni kawatte, robotto ga hataraku jidai da.', NULL, 'Thời đại robot làm việc thay con người.', 6878, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17404, 'とうきょうを はじめ、おおきい まちは ひとが おおい。', 'toukyou o hajime, ookii machi wa hito ga ooi.', NULL, 'Các thành phố lớn, tiêu biểu là Tokyo, rất đông người.', 6879, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17405, 'しゃちょうを はじめ、しゃいん ぜんいんが さんかした。', 'shachou o hajime, shain zen''in ga sanka shita.', NULL, 'Từ giám đốc đến toàn bộ nhân viên đều tham gia.', 6879, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17406, 'わたしなんか、とても かないません。', 'watashi nanka, totemo kanaimasen.', NULL, 'Người như tôi thì không sánh được đâu.', 6880, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17407, 'おばけなど いる わけが ない。', 'obake nado iru wake ga nai.', NULL, 'Làm gì có ma quỷ.', 6880, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17408, 'ざんねんな ことに、しあいに まけて しまった。', 'zannen na koto ni, shiai ni makete shimatta.', NULL, 'Thật đáng tiếc là đã thua trận.', 6881, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17409, 'おどろいた ことに、かれは 10かこくごが はなせる。', 'odoroita koto ni, kare wa jukkakokugo ga hanaseru.', NULL, 'Ngạc nhiên thay, anh ấy nói được 10 thứ tiếng.', 6881, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17410, 'じょうきょうは わるく なる ばかりだ。', 'joukyou wa waruku naru bakari da.', NULL, 'Tình hình chỉ ngày càng xấu đi.', 6882, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17411, 'じゅんびは できて いて、あとは はじめる ばかりだ。', 'junbi wa dekite ite, ato wa hajimeru bakari da.', NULL, 'Đã chuẩn bị xong, giờ chỉ còn bắt đầu.', 6882, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17412, 'ベルが なるか ならないかの うちに、せいとは きょうしつを でた。', 'beru ga naru ka naranai ka no uchi ni, seito wa kyoushitsu o deta.', NULL, 'Chuông vừa reo là học sinh đã ra khỏi lớp.', 6883, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17413, 'すわるか すわらないかの うちに、ねて しまった。', 'suwaru ka suwaranai ka no uchi ni, nete shimatta.', NULL, 'Vừa ngồi xuống là ngủ mất.', 6883, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17414, 'だって、しらなかったんだもの。', 'datte, shiranakatta n da mono.', NULL, 'Vì em không biết mà.', 6884, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17417, 'こどもの ころ、よく この かわで あそんだ ものだ。', 'kodomo no koro, yoku kono kawa de asonda mono da.', NULL, 'Hồi nhỏ tôi hay chơi ở con sông này.', 6885, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17418, 'かぜを なおしたいなら、よく ねる ことだ。', 'kaze o naoshitai nara, yoku neru koto da.', NULL, 'Muốn khỏi cảm thì nên ngủ nhiều.', 6886, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19090, 'あした 東京へ 行く。', 'Ashita Tōkyō e iku.', NULL, 'Mai tớ đi Tokyo.', 7724, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17419, 'じょうずに なりたければ、まいにち れんしゅうする ことだ。', 'jouzu ni naritakereba, mainichi renshuu suru koto da.', NULL, 'Muốn giỏi thì nên luyện tập hằng ngày.', 6886, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17420, 'おかえりの さいは、わすれものに ごちゅういください。', 'okaeri no sai wa, wasuremono ni gochuui kudasai.', NULL, 'Khi ra về, xin chú ý đừng để quên đồ.', 6887, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17421, 'にほんへ いった さいに、ふじさんに のぼった。', 'nihon e itta sai ni, fujisan ni nobotta.', NULL, 'Nhân dịp sang Nhật, tôi đã leo núi Phú Sĩ.', 6887, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17422, 'にゅうがくに さいして、せつめいかいが おこなわれた。', 'nyuugaku ni saishite, setsumeikai ga okonawareta.', NULL, 'Nhân dịp nhập học, buổi giới thiệu đã được tổ chức.', 6888, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17423, 'けいやくに さいして、いくつか かくにんしたい ことが ある。', 'keiyaku ni saishite, ikutsuka kakunin shitai koto ga aru.', NULL, 'Khi ký hợp đồng, tôi muốn xác nhận vài điều.', 6888, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17424, 'しりょうが とどき しだい、おおくりします。', 'shiryou ga todoki shidai, ookuri shimasu.', NULL, 'Ngay khi tài liệu đến, tôi sẽ gửi đi.', 6889, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17425, 'じゅんびが でき しだい、しゅっぱつしましょう。', 'junbi ga deki shidai, shuppatsu shimashou.', NULL, 'Chuẩn bị xong là xuất phát nhé.', 6889, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17426, 'はれたかと おもったら、また ふりだした。', 'hareta ka to omottara, mata furidashita.', NULL, 'Vừa tưởng tạnh thì lại mưa tiếp.', 6890, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17427, 'こどもは かえって きたかと おもうと、すぐ あそびに でかけた。', 'kodomo wa kaette kita ka to omou to, sugu asobi ni dekaketa.', NULL, 'Con vừa về đã lại đi chơi ngay.', 6890, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17428, 'としを とるに つれて、からだが よわく なる。', 'toshi o toru ni tsurete, karada ga yowaku naru.', NULL, 'Càng có tuổi, cơ thể càng yếu đi.', 6891, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17429, 'じかんが たつに つれて、かなしみも うすれた。', 'jikan ga tatsu ni tsurete, kanashimi mo usureta.', NULL, 'Thời gian trôi đi, nỗi buồn cũng nhạt dần.', 6891, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17430, 'やまを のぼるに したがって、きおんが さがる。', 'yama o noboru ni shitagatte, kion ga sagaru.', NULL, 'Càng leo lên núi, nhiệt độ càng giảm.', 6892, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17431, 'せんせいの しじに したがって ください。', 'sensei no shiji ni shitagatte kudasai.', NULL, 'Hãy làm theo chỉ thị của thầy.', 6892, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17432, 'けいざいの はってんと ともに、せいかつが ゆたかに なった。', 'keizai no hatten to tomo ni, seikatsu ga yutaka ni natta.', NULL, 'Cùng với sự phát triển kinh tế, đời sống sung túc hơn.', 6893, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17433, 'かぞくと ともに しょうがつを すごした。', 'kazoku to tomo ni shougatsu o sugoshita.', NULL, 'Tôi đón Tết cùng gia đình.', 6893, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17434, 'ながい はなしあいの すえに、けつろんが でた。', 'nagai hanashiai no sue ni, ketsuron ga deta.', NULL, 'Sau một hồi bàn bạc dài, đã có kết luận.', 6894, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17435, 'なやんだ すえ、かいしゃを やめる ことに した。', 'nayanda sue, kaisha o yameru koto ni shita.', NULL, 'Sau khi đắn đo, tôi quyết định nghỉ việc.', 6894, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17436, 'さんざん まよった あげく、なにも かわなかった。', 'sanzan mayotta ageku, nani mo kawanakatta.', NULL, 'Đắn đo mãi rốt cuộc chẳng mua gì.', 6895, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17437, 'けんかした あげくに、わかれて しまった。', 'kenka shita ageku ni, wakarete shimatta.', NULL, 'Cãi nhau mãi rồi rốt cuộc chia tay.', 6895, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17438, 'よく かんがえた うえで、へんじします。', 'yoku kangaeta ue de, henji shimasu.', NULL, 'Tôi sẽ suy nghĩ kỹ rồi mới trả lời.', 6896, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17439, 'りょうしんと そうだんの うえ、きめました。', 'ryoushin to soudan no ue, kimemashita.', NULL, 'Sau khi bàn với bố mẹ, tôi đã quyết định.', 6896, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17440, 'いぬを かいはじめて からと いう もの、まいあさ さんぽして いる。', 'inu o kaihajimete kara to iu mono, maiasa sanpo shite iru.', NULL, 'Kể từ khi nuôi chó, sáng nào tôi cũng đi dạo.', 6897, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17441, 'かのじょに あって からと いう もの、かれは かわった。', 'kanojo ni atte kara to iu mono, kare wa kawatta.', NULL, 'Từ khi gặp cô ấy, anh ta thay đổi hẳn.', 6897, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17442, 'しんせいかつを はじめるに あたって、けいかくを たてた。', 'shinseikatsu o hajimeru ni atatte, keikaku o tateta.', NULL, 'Khi bắt đầu cuộc sống mới, tôi đã lập kế hoạch.', 6898, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17443, 'かいかいに あたり、ひとこと ごあいさつ もうしあげます。', 'kaikai ni atari, hitokoto goaisatsu moushiagemasu.', NULL, 'Nhân dịp khai mạc, tôi xin có đôi lời.', 6898, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17444, 'データに もとづいて、けいかくを たてる。', 'deeta ni motozuite, keikaku o tateru.', NULL, 'Lập kế hoạch dựa trên dữ liệu.', 6899, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17445, 'じじつに もとづいた えいがです。', 'jijitsu ni motozuita eiga desu.', NULL, 'Đây là bộ phim dựa trên sự thật.', 6899, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17446, 'この しょうせつは さっかの たいけんを もとに かかれた。', 'kono shousetsu wa sakka no taiken o moto ni kakareta.', NULL, 'Cuốn tiểu thuyết này được viết dựa trên trải nghiệm của tác giả.', 6900, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17447, 'アンケートの けっかを もとに して、しょうひんを かいぜんした。', 'ankeeto no kekka o moto ni shite, shouhin o kaizen shita.', NULL, 'Cải tiến sản phẩm dựa trên kết quả khảo sát.', 6900, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17448, 'かわに そって、さくらが さいて いる。', 'kawa ni sotte, sakura ga saite iru.', NULL, 'Hoa anh đào nở dọc bờ sông.', 6901, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17449, 'マニュアルに そって さぎょうを すすめて ください。', 'manyuaru ni sotte sagyou o susumete kudasai.', NULL, 'Hãy tiến hành công việc theo sổ hướng dẫn.', 6901, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17450, 'レベルに おうじて、クラスを わけます。', 'reberu ni oujite, kurasu o wakemasu.', NULL, 'Chia lớp tùy theo trình độ.', 6902, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17451, 'きゃくの ようぼうに おうじた サービスを ていきょうする。', 'kyaku no youbou ni oujita saabisu o teikyou suru.', NULL, 'Cung cấp dịch vụ đáp ứng yêu cầu khách hàng.', 6902, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17452, 'あたらしい ほうりつを めぐって、ぎろんが つづいて いる。', 'atarashii houritsu o megutte, giron ga tsuzuite iru.', NULL, 'Tranh luận quanh luật mới vẫn tiếp diễn.', 6903, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17453, 'いさんを めぐる あらそいが おきた。', 'isan o meguru arasoi ga okita.', NULL, 'Đã xảy ra tranh chấp quanh tài sản thừa kế.', 6903, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17454, 'この まつりは わかものを ちゅうしんに にんきが ある。', 'kono matsuri wa wakamono o chuushin ni ninki ga aru.', NULL, 'Lễ hội này được ưa chuộng, chủ yếu trong giới trẻ.', 6904, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17455, 'えきを ちゅうしんに して、まちが ひろがって いる。', 'eki o chuushin ni shite, machi ga hirogatte iru.', NULL, 'Thị trấn trải rộng lấy nhà ga làm trung tâm.', 6904, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17456, 'かいぎは 3じかんに わたって つづいた。', 'kaigi wa sanjikan ni watatte tsuzuita.', NULL, 'Cuộc họp kéo dài suốt 3 tiếng.', 6905, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17457, 'ぜんこくに わたる ちょうさが おこなわれた。', 'zenkoku ni wataru chousa ga okonawareta.', NULL, 'Cuộc khảo sát khắp cả nước đã được tiến hành.', 6905, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17458, 'ともだちを つうじて、かのじょと しりあった。', 'tomodachi o tsuujite, kanojo to shiriatta.', NULL, 'Tôi quen cô ấy thông qua bạn bè.', 6906, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17459, 'この ちほうは いちねんを とおして あたたかい。', 'kono chihou wa ichinen o tooshite atatakai.', NULL, 'Vùng này ấm áp quanh năm.', 6906, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17460, 'この けんに かんして、ごいけんを おきかせください。', 'kono ken ni kanshite, goiken o okikase kudasai.', NULL, 'Xin cho biết ý kiến về việc này.', 6907, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17461, 'かんきょうもんだいに かんする ろんぶんを かいた。', 'kankyou mondai ni kansuru ronbun o kaita.', NULL, 'Tôi đã viết luận văn về vấn đề môi trường.', 6907, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17462, 'りゅうがくを きっかけに、にほんの ぶんかに きょうみを もった。', 'ryuugaku o kikkake ni, nihon no bunka ni kyoumi o motta.', NULL, 'Nhân chuyến du học, tôi bắt đầu thích văn hóa Nhật.', 6908, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17463, 'びょうきを きっかけに、タバコを やめた。', 'byouki o kikkake ni, tabako o yameta.', NULL, 'Nhân lần ốm, tôi đã bỏ thuốc lá.', 6908, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17464, 'りょうりに かけては、かれに かなう ひとは いない。', 'ryouri ni kakete wa, kare ni kanau hito wa inai.', NULL, 'Về nấu ăn thì không ai bằng anh ấy.', 6909, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17465, 'はしる ことに かけては、じしんが ある。', 'hashiru koto ni kakete wa, jishin ga aru.', NULL, 'Về chạy thì tôi tự tin.', 6909, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17466, 'この ゲームは こども に かぎらず、おとなにも にんきだ。', 'kono geemu wa kodomo ni kagirazu, otona ni mo ninki da.', NULL, 'Trò chơi này không chỉ trẻ em mà người lớn cũng thích.', 6910, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17467, 'にちようびに かぎらず、へいじつも あいて います。', 'nichiyoubi ni kagirazu, heijitsu mo aite imasu.', NULL, 'Không chỉ Chủ nhật, ngày thường cũng mở cửa.', 6910, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17468, 'きょうに かぎり、ぜんぴん はんがくです。', 'kyou ni kagiri, zenpin hangaku desu.', NULL, 'Chỉ riêng hôm nay, mọi sản phẩm giảm nửa giá.', 6911, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17469, 'よやくした かたに かぎり、にゅうじょうできます。', 'yoyaku shita kata ni kagiri, nyuujou dekimasu.', NULL, 'Chỉ người đã đặt trước mới được vào.', 6911, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17470, 'いきて いる かぎり、あなたを わすれない。', 'ikite iru kagiri, anata o wasurenai.', NULL, 'Chừng nào còn sống, tôi không quên bạn.', 6912, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17471, 'わたしの しって いる かぎり、かれは しょうじきな ひとだ。', 'watashi no shitte iru kagiri, kare wa shoujiki na hito da.', NULL, 'Theo như tôi biết, anh ấy là người thật thà.', 6912, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17472, 'この もんだいは にほん のみならず、せかいの もんだいだ。', 'kono mondai wa nihon nominarazu, sekai no mondai da.', NULL, 'Vấn đề này không chỉ của Nhật mà của cả thế giới.', 6913, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17473, 'かれは がくせい のみならず、せんせいからも しんらいされて いる。', 'kare wa gakusei nominarazu, sensei kara mo shinrai sarete iru.', NULL, 'Anh ấy được cả học sinh lẫn giáo viên tin tưởng.', 6913, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17474, 'この みせは あじは もちろん、サービスも いい。', 'kono mise wa aji wa mochiron, saabisu mo ii.', NULL, 'Quán này vị thì khỏi nói, phục vụ cũng tốt.', 6914, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17475, 'にちようびは もちろん、へいじつも こんで いる。', 'nichiyoubi wa mochiron, heijitsu mo konde iru.', NULL, 'Chủ nhật thì đương nhiên, ngày thường cũng đông.', 6914, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17476, 'ねだんは ともかく、デザインが きに いらない。', 'nedan wa tomokaku, dezain ga ki ni iranai.', NULL, 'Giá cả thì tạm gác, tôi không thích thiết kế.', 6915, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17477, 'けっかは ともかく、さいごまで がんばった ことが たいせつだ。', 'kekka wa tomokaku, saigo made ganbatta koto ga taisetsu da.', NULL, 'Kết quả thế nào không bàn, cố gắng đến cùng mới quan trọng.', 6915, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17478, 'ねんれいを とわず、だれでも さんかできます。', 'nenrei o towazu, daredemo sanka dekimasu.', NULL, 'Bất kể tuổi tác, ai cũng có thể tham gia.', 6916, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17479, 'この しごとは けいけんの うむを とわない。', 'kono shigoto wa keiken no umu o towanai.', NULL, 'Công việc này không kể có kinh nghiệm hay không.', 6916, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17480, 'てんきに かかわらず、しあいは おこなわれます。', 'tenki ni kakawarazu, shiai wa okonawaremasu.', NULL, 'Bất kể thời tiết, trận đấu vẫn diễn ra.', 6917, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17481, 'さんかする しないに かかわらず、へんじを ください。', 'sanka suru shinai ni kakawarazu, henji o kudasai.', NULL, 'Dù tham gia hay không, xin hãy phản hồi.', 6917, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17482, 'かれは ひとめも かまわず、ないた。', 'kare wa hitome mo kamawazu, naita.', NULL, 'Anh ấy khóc chẳng để ý ánh mắt người khác.', 6918, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17483, 'ふくが ぬれるのも かまわず、あめの なかを はしった。', 'fuku ga nureru no mo kamawazu, ame no naka o hashitta.', NULL, 'Mặc kệ quần áo ướt, tôi chạy trong mưa.', 6918, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17484, 'じょうだんは さておき、ほんだいに はいりましょう。', 'joudan wa sateoki, hondai ni hairimashou.', NULL, 'Đùa thì để sau, vào vấn đề chính thôi.', 6919, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17485, 'ひようの もんだいは さておき、まず けいかくを たてよう。', 'hiyou no mondai wa sateoki, mazu keikaku o tateyou.', NULL, 'Chuyện chi phí để sau, trước hết lập kế hoạch đã.', 6919, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17486, 'さすが プロだけ あって、うまいね。', 'sasuga puro dake atte, umai ne.', NULL, 'Quả là dân chuyên nghiệp, giỏi thật.', 6920, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17487, '10ねん すんで いた だけ あって、この まちに くわしい。', 'juunen sunde ita dake atte, kono machi ni kuwashii.', NULL, 'Đã sống 10 năm nên quả rành thị trấn này.', 6920, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17488, 'やると きめた からには、さいごまで やる。', 'yaru to kimeta kara ni wa, saigo made yaru.', NULL, 'Một khi đã quyết làm thì làm đến cùng.', 6921, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17489, 'やくそくした いじょう、まもらなければ ならない。', 'yakusoku shita ijou, mamoranakereba naranai.', NULL, 'Đã hứa thì phải giữ lời.', 6921, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17490, 'きたいして いた だけに、ざんねんだ。', 'kitai shite ita dake ni, zannen da.', NULL, 'Chính vì đã kỳ vọng nên càng tiếc.', 6922, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17491, 'かんこうちだけに、ひとが おおい。', 'kankouchi dake ni, hito ga ooi.', NULL, 'Vì là điểm du lịch nên càng đông người.', 6922, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17492, 'でんしゃが おくれた ものだから、ちこくして しまいました。', 'densha ga okureta mono da kara, chikoku shite shimaimashita.', NULL, 'Vì tàu trễ nên tôi đến muộn.', 6923, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17493, 'あまりに おいしい ものだから、たべすぎて しまった。', 'amari ni oishii mono da kara, tabesugite shimatta.', NULL, 'Ngon quá nên tôi ăn quá nhiều.', 6923, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17494, 'しんぱいの あまり、ねむれなかった。', 'shinpai no amari, nemurenakatta.', NULL, 'Vì quá lo lắng nên không ngủ được.', 6924, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17495, 'よろこびの あまり、なきだした。', 'yorokobi no amari, nakidashita.', NULL, 'Vui quá nên bật khóc.', 6924, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17496, 'まじめな かれの ことだから、やくそくは まもるだろう。', 'majime na kare no koto da kara, yakusoku wa mamoru darou.', NULL, 'Anh ấy nghiêm túc nên chắc sẽ giữ lời.', 6925, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17497, 'あの ひとの ことだから、また わすれて いるよ。', 'ano hito no koto da kara, mata wasurete iru yo.', NULL, 'Người đó mà, chắc lại quên rồi.', 6925, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17498, 'おかねが ある からと いって、しあわせとは かぎらない。', 'okane ga aru kara to itte, shiawase to wa kagiranai.', NULL, 'Có tiền chưa chắc đã hạnh phúc.', 6926, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17499, 'にほんじんだ からと いって、けいごが じょうずとは かぎらない。', 'nihonjin da kara to itte, keigo ga jouzu to wa kagiranai.', NULL, 'Là người Nhật chưa chắc đã giỏi kính ngữ.', 6926, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17500, 'ねぶそくの せいか、あたまが いたい。', 'nebusoku no sei ka, atama ga itai.', NULL, 'Có lẽ do thiếu ngủ nên đau đầu.', 6927, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17501, 'としの せいか、つかれやすく なった。', 'toshi no sei ka, tsukareyasuku natta.', NULL, 'Có lẽ do tuổi tác nên dễ mệt hơn.', 6927, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17502, 'この はしは かたちが にじに にて いる ことから、にじばしと よばれて いる。', 'kono hashi wa katachi ga niji ni nite iru koto kara, nijibashi to yobarete iru.', NULL, 'Cây cầu có hình giống cầu vồng nên được gọi là cầu Cầu Vồng.', 6928, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17503, 'あしあとが ある ことから、だれかが はいったと わかった。', 'ashiato ga aru koto kara, dareka ga haitta to wakatta.', NULL, 'Từ dấu chân, biết là có người đã vào.', 6928, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17504, 'ひとりで さんにんぶん はたらいて いる わけだから、つかれるのも とうぜんだ。', 'hitori de sanninbun hataraite iru wake da kara, tsukareru no mo touzen da.', NULL, 'Một mình làm việc của ba người thì mệt là đương nhiên.', 6929, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17505, 'もう きめた わけだから、まよう ひつようは ない。', 'mou kimeta wake da kara, mayou hitsuyou wa nai.', NULL, 'Đã quyết rồi thì không cần đắn đo.', 6929, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17506, 'はなしあった けっか、けいかくを へんこうする ことに なった。', 'hanashiatta kekka, keikaku o henkou suru koto ni natta.', NULL, 'Kết quả bàn bạc là đổi kế hoạch.', 6930, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17507, 'ちょうさの けっか、げんいんが わかった。', 'chousa no kekka, gen''in ga wakatta.', NULL, 'Kết quả điều tra đã tìm ra nguyên nhân.', 6930, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17508, 'この りょうでは 10じいこう、おんがくを ひかない ことに なって いる。', 'kono ryou de wa juuji ikou, ongaku o hikanai koto ni natte iru.', NULL, 'Ở ký túc xá này quy định sau 10 giờ không chơi nhạc.', 6931, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17509, 'しゅっきんしたら、タイムカードを おす ことに なって います。', 'shukkin shitara, taimukaado o osu koto ni natte imasu.', NULL, 'Theo quy định, đi làm thì phải bấm thẻ chấm công.', 6931, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17510, 'それは うわさに すぎない。', 'sore wa uwasa ni suginai.', NULL, 'Đó chỉ là tin đồn mà thôi.', 6932, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17511, 'わたしは ただの がくせいに すぎません。', 'watashi wa tada no gakusei ni sugimasen.', NULL, 'Tôi chỉ là một sinh viên bình thường.', 6932, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17512, 'そんな はなし、うそに きまって いる。', 'sonna hanashi, uso ni kimatte iru.', NULL, 'Chuyện như thế chắc chắn là nói dối.', 6933, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17513, 'いまから いっても まにあわないに きまって いる。', 'ima kara itte mo maniawanai ni kimatte iru.', NULL, 'Bây giờ đi thì chắc chắn không kịp.', 6933, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17514, 'かれが はんにんで ある ことに そういない。', 'kare ga hannin de aru koto ni soui nai.', NULL, 'Chắc chắn anh ta là thủ phạm.', 6934, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17515, 'この えは ゆうめいな がかの さくひんに そういない。', 'kono e wa yuumei na gaka no sakuhin ni soui nai.', NULL, 'Bức tranh này hẳn là tác phẩm của họa sĩ nổi tiếng.', 6934, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17516, 'あんな みせ、にどと いく ものか。', 'anna mise, nido to iku mono ka.', NULL, 'Quán như thế, còn lâu tôi mới quay lại.', 6935, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17517, 'まけて たまるもんか。', 'makete tamaru mon ka.', NULL, 'Không đời nào tôi chịu thua.', 6935, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17518, 'そんな むずかしい もんだい、わかりっこない。', 'sonna muzukashii mondai, wakarikkonai.', NULL, 'Bài khó thế sao mà hiểu nổi.', 6936, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17519, 'いまから はしっても、まにあいっこない。', 'ima kara hashitte mo, maniaikkonai.', NULL, 'Giờ chạy cũng không đời nào kịp.', 6936, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17520, 'れんらくさきが わからないので、れんらくの しようが ない。', 'renrakusaki ga wakaranai node, renraku no shiyou ga nai.', NULL, 'Không biết địa chỉ liên lạc nên không có cách nào liên lạc.', 6937, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17521, 'こわれて しまって、なおしようが ない。', 'kowarete shimatte, naoshiyou ga nai.', NULL, 'Hỏng mất rồi, không cách nào sửa được.', 6937, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17522, 'たいふうが くるので、りょこうを ちゅうしせざるを えない。', 'taifuu ga kuru node, ryokou o chuushi sezaru o enai.', NULL, 'Bão đến nên buộc phải hủy chuyến đi.', 6938, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17523, 'しゃちょうの めいれいなら、したがわざるを えない。', 'shachou no meirei nara, shitagawazaru o enai.', NULL, 'Lệnh giám đốc thì buộc phải tuân theo.', 6938, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17524, 'この ままでは じこに なりかねない。', 'kono mama de wa jiko ni narikanenai.', NULL, 'Cứ thế này thì có thể xảy ra tai nạn.', 6939, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17525, 'かれなら そんな ことも いいかねない。', 'kare nara sonna koto mo iikanenai.', NULL, 'Anh ta thì có khi nói ra điều đó lắm.', 6939, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17526, 'その ごようぼうには おこたえ しかねます。', 'sono goyoubou ni wa okotae shikanemasu.', NULL, 'Chúng tôi khó đáp ứng yêu cầu đó.', 6940, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17527, 'かれの いけんには さんせいしかねる。', 'kare no iken ni wa sansei shikaneru.', NULL, 'Tôi khó mà tán thành ý kiến của anh ấy.', 6940, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17528, 'かれが うそを ついたとは しんじがたい。', 'kare ga uso o tsuita to wa shinjigatai.', NULL, 'Khó tin rằng anh ấy đã nói dối.', 6941, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17529, 'この おもいでは わすれがたい。', 'kono omoide wa wasuregatai.', NULL, 'Kỷ niệm này khó mà quên.', 6941, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17530, 'だれにでも ありうる しっぱいだ。', 'dare ni demo ariuru shippai da.', NULL, 'Đó là thất bại ai cũng có thể mắc.', 6942, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17531, 'そんな ことは ありえない。', 'sonna koto wa arienai.', NULL, 'Chuyện đó không thể có.', 6942, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17532, 'せいこうしたのは どりょくの けっかに ほかならない。', 'seikou shita no wa doryoku no kekka ni hoka naranai.', NULL, 'Thành công chính là kết quả của nỗ lực.', 6943, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17533, 'この しっぱいは けいかくの あまさに ほかならない。', 'kono shippai wa keikaku no amasa ni hoka naranai.', NULL, 'Thất bại này không gì khác ngoài kế hoạch sơ sài.', 6943, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17534, 'ながく べんきょうすれば いい と いう ものでは ない。', 'nagaku benkyou sureba ii to iu mono de wa nai.', NULL, 'Không phải cứ học lâu là tốt.', 6944, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17535, 'やすければ うれる と いう ものでは ない。', 'yasukereba ureru to iu mono de wa nai.', NULL, 'Không phải cứ rẻ là bán được.', 6944, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17536, 'くるまの めんきょは ある ものの、ほとんど うんてんしない。', 'kuruma no menkyo wa aru mono no, hotondo unten shinai.', NULL, 'Có bằng lái nhưng tôi hầu như không lái.', 6945, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17537, 'やくそくした ものの、いけるか どうか わからない。', 'yakusoku shita mono no, ikeru ka dou ka wakaranai.', NULL, 'Đã hứa nhưng không biết có đi được không.', 6945, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17538, 'あめに も かかわらず、おおぜいの ひとが あつまった。', 'ame ni mo kakawarazu, oozei no hito ga atsumatta.', NULL, 'Mặc dù mưa, rất nhiều người đã tập trung.', 6946, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17539, 'どりょくしたに も かかわらず、しっぱいした。', 'doryoku shita ni mo kakawarazu, shippai shita.', NULL, 'Dù đã nỗ lực vẫn thất bại.', 6946, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17540, 'わるいと しりつつ、うそを ついて しまった。', 'warui to shiritsutsu, uso o tsuite shimatta.', NULL, 'Biết là sai mà vẫn nói dối.', 6947, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17541, 'けしきを たのしみつつ、さんぽした。', 'keshiki o tanoshimitsutsu, sanpo shita.', NULL, 'Vừa ngắm cảnh vừa đi dạo.', 6947, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17542, 'とかいは べんりな はんめん、ストレスも おおい。', 'tokai wa benri na hanmen, sutoresu mo ooi.', NULL, 'Thành phố tiện lợi, mặt khác cũng nhiều áp lực.', 6948, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17543, 'この くすりは よく きく はんめん、ふくさようも ある。', 'kono kusuri wa yoku kiku hanmen, fukusayou mo aru.', NULL, 'Thuốc này hiệu quả, nhưng cũng có tác dụng phụ.', 6948, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17544, 'しごとを する いっぽうで、だいがくいんにも かよって いる。', 'shigoto o suru ippou de, daigakuin ni mo kayotte iru.', NULL, 'Vừa đi làm, mặt khác vẫn học cao học.', 6949, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17545, 'とかいの じんこうは ふえる いっぽうで、いなかは へって いる。', 'tokai no jinkou wa fueru ippou de, inaka wa hette iru.', NULL, 'Dân số đô thị tăng trong khi nông thôn giảm.', 6949, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17546, 'よそうに はんして、しあいに まけた。', 'yosou ni hanshite, shiai ni maketa.', NULL, 'Trái với dự đoán, chúng tôi thua trận.', 6950, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17547, 'おやの きたいに はんして、かれは だいがくを やめた。', 'oya no kitai ni hanshite, kare wa daigaku o yameta.', NULL, 'Trái với kỳ vọng của bố mẹ, anh ấy bỏ đại học.', 6950, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17548, 'やすむ どころか、ねる じかんも ない。', 'yasumu dokoroka, neru jikan mo nai.', NULL, 'Nói gì đến nghỉ, đến thời gian ngủ cũng không có.', 6951, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17549, 'くすりを のんだが、よく なる どころか わるく なった。', 'kusuri o nonda ga, yoku naru dokoroka waruku natta.', NULL, 'Uống thuốc rồi mà chẳng đỡ, trái lại còn tệ hơn.', 6951, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17551, 'かれは ともだち と いうより かぞくの ような ものだ。', 'kare wa tomodachi to iu yori kazoku no you na mono da.', NULL, 'Anh ấy giống gia đình hơn là bạn bè.', 6952, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17552, 'いまさら あやまった ところで、ゆるして もらえないだろう。', 'imasara ayamatta tokoro de, yurushite moraenai darou.', NULL, 'Bây giờ có xin lỗi thì cũng chẳng được tha thứ.', 6953, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17553, 'いくら いった ところで、かれは きかない。', 'ikura itta tokoro de, kare wa kikanai.', NULL, 'Có nói bao nhiêu thì anh ta cũng không nghe.', 6953, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17554, 'いそがしい にしても、れんらくくらい できたはずだ。', 'isogashii ni shite mo, renraku kurai dekita hazu da.', NULL, 'Dù bận đi nữa thì ít ra cũng liên lạc được.', 6954, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17555, 'いく にしろ いかない にしろ、へんじを して ください。', 'iku ni shiro ikanai ni shiro, henji o shite kudasai.', NULL, 'Đi hay không đi thì cũng hãy trả lời.', 6954, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17556, 'ざんねん ながら、こんかいは みおくる ことに しました。', 'zannen nagara, konkai wa miokuru koto ni shimashita.', NULL, 'Rất tiếc, lần này chúng tôi quyết định không tham gia.', 6955, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17557, 'こども ながら、しっかりした かんがえを もって いる。', 'kodomo nagara, shikkari shita kangae o motte iru.', NULL, 'Tuy là trẻ con nhưng suy nghĩ rất chín chắn.', 6955, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17558, 'この みせは ねだんの わりに おいしい。', 'kono mise wa nedan no wari ni oishii.', NULL, 'Quán này so với giá thì khá ngon.', 6956, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17559, 'かれは としの わりに わかく みえる。', 'kare wa toshi no wari ni wakaku mieru.', NULL, 'So với tuổi, anh ấy trông trẻ.', 6956, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17560, 'あの えいがを みたら、なかずには いられない。', 'ano eiga o mitara, nakazu ni wa irarenai.', NULL, 'Xem bộ phim đó thì không thể không khóc.', 6957, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17561, 'かのじょの ことを しんぱいせずには いられない。', 'kanojo no koto o shinpai sezu ni wa irarenai.', NULL, 'Tôi không thể không lo cho cô ấy.', 6957, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17562, 'のどが かわいて たまらない。', 'nodo ga kawaite tamaranai.', NULL, 'Khát không chịu nổi.', 6958, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17563, 'こきょうの かぞくに あいたくて たまらない。', 'kokyou no kazoku ni aitakute tamaranai.', NULL, 'Nhớ gia đình ở quê vô cùng.', 6958, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17564, 'むすこの ことが しんぱいで ならない。', 'musuko no koto ga shinpai de naranai.', NULL, 'Tôi lo cho con trai không sao chịu được.', 6959, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17565, 'だれかに みられて いる ような きが して ならない。', 'dareka ni mirarete iru you na ki ga shite naranai.', NULL, 'Cứ có cảm giác như bị ai đó nhìn.', 6959, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17566, 'あたまが いたくて しょうがない。', 'atama ga itakute shouganai.', NULL, 'Đau đầu hết sức.', 6960, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17567, 'ひまで しかたが ない。', 'hima de shikata ga nai.', NULL, 'Rảnh rỗi chán không chịu được.', 6960, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17568, 'あなたに あえて、どんなに うれしい ことか。', 'anata ni aete, donna ni ureshii koto ka.', NULL, 'Được gặp bạn tôi vui biết bao!', 6961, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17569, 'なんど ちゅういした ことか。', 'nando chuui shita koto ka.', NULL, 'Đã nhắc nhở bao nhiêu lần rồi!', 6961, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17570, 'つかれた ときは ねるに かぎる。', 'tsukareta toki wa neru ni kagiru.', NULL, 'Khi mệt thì ngủ là nhất.', 6962, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17571, 'なつは つめたい ビールに かぎる。', 'natsu wa tsumetai biiru ni kagiru.', NULL, 'Mùa hè thì bia lạnh là nhất.', 6962, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17572, 'じぶんで やって こそ、ほんとうに わかる。', 'jibun de yatte koso, hontou ni wakaru.', NULL, 'Chỉ khi tự làm mới thật sự hiểu.', 6963, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17573, 'たがいに たすけあって こそ、なかまだ。', 'tagai ni tasukeatte koso, nakama da.', NULL, 'Có giúp đỡ nhau mới là đồng đội.', 6963, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19091, '毎日 忙しい。', 'Mainichi isogashii.', NULL, 'Ngày nào cũng bận.', 7724, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17574, 'いそがしくて、しょくじを する じかん さえ ない。', 'isogashikute, shokuji o suru jikan sae nai.', NULL, 'Bận đến mức ngay cả thời gian ăn cũng không có.', 6964, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17575, 'この かんじは せんせい すら よめなかった。', 'kono kanji wa sensei sura yomenakatta.', NULL, 'Chữ Hán này ngay cả thầy cũng không đọc được.', 6964, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17576, 'かれが けっこんする なんて、しんじられない。', 'kare ga kekkon suru nante, shinjirarenai.', NULL, 'Anh ta mà kết hôn ư, không thể tin nổi.', 6965, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17577, 'べんきょう なんか したくない。', 'benkyou nanka shitakunai.', NULL, 'Học hành gì chứ, chẳng muốn.', 6965, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17578, 'あんな ひとに たのむ くらいなら、じぶんで やる。', 'anna hito ni tanomu kurai nara, jibun de yaru.', NULL, 'Nếu phải nhờ người như thế thì thà tự làm.', 6966, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17579, 'とちゅうで やめる くらいなら、はじめから やらない ほうが いい。', 'tochuu de yameru kurai nara, hajime kara yaranai hou ga ii.', NULL, 'Nếu bỏ giữa chừng thì thà đừng làm từ đầu.', 6966, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17580, 'なんとしても こんどの しけんに ごうかくしたい。', 'nan to shite mo kondo no shiken ni goukaku shitai.', NULL, 'Bằng mọi giá tôi muốn đỗ kỳ thi lần này.', 6967, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17581, 'ぜひ いちど おあいしたいです。', 'zehi ichido oai shitai desu.', NULL, 'Nhất định tôi muốn gặp anh một lần.', 6967, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17582, 'この さくぶんは まちがい だらけだ。', 'kono sakubun wa machigai darake da.', NULL, 'Bài văn này toàn là lỗi.', 6968, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17583, 'どろ だらけの くつで はいらないで。', 'doro darake no kutsu de hairanaide.', NULL, 'Đừng đi giày lấm bùn vào.', 6968, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17584, 'ことしは いい こと ずくめだった。', 'kotoshi wa ii koto zukume datta.', NULL, 'Năm nay toàn chuyện tốt đẹp.', 6969, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17585, 'かのじょは くろ ずくめの ふくを きて いた。', 'kanojo wa kuro zukume no fuku o kite ita.', NULL, 'Cô ấy mặc toàn đồ đen.', 6969, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17586, 'かのじょは さびし げに わらった。', 'kanojo wa sabishi ge ni waratta.', NULL, 'Cô ấy cười có vẻ buồn.', 6970, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17587, 'こどもたちは たのし げに あそんで いる。', 'kodomotachi wa tanoshi ge ni asonde iru.', NULL, 'Bọn trẻ đang chơi có vẻ vui.', 6970, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17588, 'この コースは しょしんしゃ むきです。', 'kono koosu wa shoshinsha muki desu.', NULL, 'Khóa này phù hợp người mới.', 6971, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17589, 'これは こども むけの ばんぐみだ。', 'kore wa kodomo muke no bangumi da.', NULL, 'Đây là chương trình dành cho trẻ em.', 6971, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17590, 'せいこうするか どうかは どりょく しだいだ。', 'seikou suru ka dou ka wa doryoku shidai da.', NULL, 'Thành công hay không tùy vào nỗ lực.', 6972, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17591, 'てんき しだいで、よていを かえる。', 'tenki shidai de, yotei o kaeru.', NULL, 'Tùy thời tiết mà đổi kế hoạch.', 6972, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17592, 'じんこうの ぞうかに ともなって、じゅうたくが ふそくした。', 'jinkou no zouka ni tomonatte, juutaku ga fusoku shita.', NULL, 'Cùng với dân số tăng, nhà ở trở nên thiếu.', 6973, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17593, 'ぎじゅつの しんぽに ともない、せいかつが かわった。', 'gijutsu no shinpo ni tomonai, seikatsu ga kawatta.', NULL, 'Kéo theo tiến bộ kỹ thuật, cuộc sống thay đổi.', 6973, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17594, 'ごみの りょうは ふえる いっぽうだ。', 'gomi no ryou wa fueru ippou da.', NULL, 'Lượng rác cứ ngày càng tăng.', 6974, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17595, 'かれとの きょりは ひらく いっぽうだった。', 'kare to no kyori wa hiraku ippou datta.', NULL, 'Khoảng cách với anh ấy ngày càng xa.', 6974, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17596, 'あさごはん ぬきで かいしゃに いった。', 'asagohan nuki de kaisha ni itta.', NULL, 'Tôi đi làm mà không ăn sáng.', 6975, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17597, 'じょうだんは ぬきに して、まじめに はなそう。', 'joudan wa nuki ni shite, majime ni hanasou.', NULL, 'Bỏ đùa sang bên, nói chuyện nghiêm túc nào.', 6975, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17598, 'この ドアは ひとが ちかづくと あく ように なって いる。', 'kono doa wa hito ga chikazuku to aku you ni natte iru.', NULL, 'Cửa này được thiết kế để mở khi có người lại gần.', 6976, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17599, 'ボタンを おすと、おゆが でる ように なって います。', 'botan o osu to, oyu ga deru you ni natte imasu.', NULL, 'Bấm nút là nước nóng chảy ra.', 6976, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17600, 'にもつは まとめて、あとは でかける ばかりに なって いる。', 'nimotsu wa matomete, ato wa dekakeru bakari ni natte iru.', NULL, 'Hành lý đã gói xong, chỉ còn chờ đi.', 6977, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17601, 'りょうりは あとは たべる ばかりだ。', 'ryouri wa ato wa taberu bakari da.', NULL, 'Món ăn giờ chỉ còn ăn thôi.', 6977, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17602, 'かれは やすむ ことなく はたらきつづけた。', 'kare wa yasumu koto naku hatarakitsuzuketa.', NULL, 'Anh ấy làm việc liên tục không hề nghỉ.', 6978, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17603, 'あきらめる ことなく、さいごまで がんばった。', 'akirameru koto naku, saigo made ganbatta.', NULL, 'Không hề bỏ cuộc, cố gắng đến cùng.', 6978, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17604, 'あしが いたくて、あるけない ほどだ。', 'ashi ga itakute, arukenai hodo da.', NULL, 'Chân đau đến mức không đi được.', 6979, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17605, 'この せつめいは こどもでも わかる ほど かんたんだ。', 'kono setsumei wa kodomo demo wakaru hodo kantan da.', NULL, 'Lời giải thích đơn giản đến mức trẻ con cũng hiểu.', 6979, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17606, 'おかえりの さいは、わすれものに ごちゅういください。', 'okaeri no sai wa, wasuremono ni gochuui kudasai.', NULL, 'Khi ra về, xin chú ý đừng để quên đồ.', 6980, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17607, 'にほんへ いった さいに、ふじさんに のぼった。', 'nihon e itta sai ni, fujisan ni nobotta.', NULL, 'Nhân dịp sang Nhật, tôi đã leo núi Phú Sĩ.', 6980, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17608, 'にゅうがくに さいして、せつめいかいが おこなわれた。', 'nyuugaku ni saishite, setsumeikai ga okonawareta.', NULL, 'Nhân dịp nhập học, buổi giới thiệu đã được tổ chức.', 6981, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17609, 'けいやくに さいして、いくつか かくにんしたい ことが ある。', 'keiyaku ni saishite, ikutsuka kakunin shitai koto ga aru.', NULL, 'Khi ký hợp đồng, tôi muốn xác nhận vài điều.', 6981, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17610, 'しりょうが とどき しだい、おおくりします。', 'shiryou ga todoki shidai, ookuri shimasu.', NULL, 'Ngay khi tài liệu đến, tôi sẽ gửi đi.', 6982, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17611, 'じゅんびが でき しだい、しゅっぱつしましょう。', 'junbi ga deki shidai, shuppatsu shimashou.', NULL, 'Chuẩn bị xong là xuất phát nhé.', 6982, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17612, 'はれたかと おもったら、また ふりだした。', 'hareta ka to omottara, mata furidashita.', NULL, 'Vừa tưởng tạnh thì lại mưa tiếp.', 6983, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17651, 'はしる ことに かけては、じしんが ある。', 'hashiru koto ni kakete wa, jishin ga aru.', NULL, 'Về chạy thì tôi tự tin.', 7002, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17613, 'こどもは かえって きたかと おもうと、すぐ あそびに でかけた。', 'kodomo wa kaette kita ka to omou to, sugu asobi ni dekaketa.', NULL, 'Con vừa về đã lại đi chơi ngay.', 6983, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17614, 'としを とるに つれて、からだが よわく なる。', 'toshi o toru ni tsurete, karada ga yowaku naru.', NULL, 'Càng có tuổi, cơ thể càng yếu đi.', 6984, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17615, 'じかんが たつに つれて、かなしみも うすれた。', 'jikan ga tatsu ni tsurete, kanashimi mo usureta.', NULL, 'Thời gian trôi đi, nỗi buồn cũng nhạt dần.', 6984, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17616, 'やまを のぼるに したがって、きおんが さがる。', 'yama o noboru ni shitagatte, kion ga sagaru.', NULL, 'Càng leo lên núi, nhiệt độ càng giảm.', 6985, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17617, 'せんせいの しじに したがって ください。', 'sensei no shiji ni shitagatte kudasai.', NULL, 'Hãy làm theo chỉ thị của thầy.', 6985, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17618, 'けいざいの はってんと ともに、せいかつが ゆたかに なった。', 'keizai no hatten to tomo ni, seikatsu ga yutaka ni natta.', NULL, 'Cùng với sự phát triển kinh tế, đời sống sung túc hơn.', 6986, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17619, 'かぞくと ともに しょうがつを すごした。', 'kazoku to tomo ni shougatsu o sugoshita.', NULL, 'Tôi đón Tết cùng gia đình.', 6986, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17620, 'ながい はなしあいの すえに、けつろんが でた。', 'nagai hanashiai no sue ni, ketsuron ga deta.', NULL, 'Sau một hồi bàn bạc dài, đã có kết luận.', 6987, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17621, 'なやんだ すえ、かいしゃを やめる ことに した。', 'nayanda sue, kaisha o yameru koto ni shita.', NULL, 'Sau khi đắn đo, tôi quyết định nghỉ việc.', 6987, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17622, 'さんざん まよった あげく、なにも かわなかった。', 'sanzan mayotta ageku, nani mo kawanakatta.', NULL, 'Đắn đo mãi rốt cuộc chẳng mua gì.', 6988, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17623, 'けんかした あげくに、わかれて しまった。', 'kenka shita ageku ni, wakarete shimatta.', NULL, 'Cãi nhau mãi rồi rốt cuộc chia tay.', 6988, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17624, 'よく かんがえた うえで、へんじします。', 'yoku kangaeta ue de, henji shimasu.', NULL, 'Tôi sẽ suy nghĩ kỹ rồi mới trả lời.', 6989, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17625, 'りょうしんと そうだんの うえ、きめました。', 'ryoushin to soudan no ue, kimemashita.', NULL, 'Sau khi bàn với bố mẹ, tôi đã quyết định.', 6989, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17626, 'いぬを かいはじめて からと いう もの、まいあさ さんぽして いる。', 'inu o kaihajimete kara to iu mono, maiasa sanpo shite iru.', NULL, 'Kể từ khi nuôi chó, sáng nào tôi cũng đi dạo.', 6990, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17627, 'かのじょに あって からと いう もの、かれは かわった。', 'kanojo ni atte kara to iu mono, kare wa kawatta.', NULL, 'Từ khi gặp cô ấy, anh ta thay đổi hẳn.', 6990, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17628, 'しんせいかつを はじめるに あたって、けいかくを たてた。', 'shinseikatsu o hajimeru ni atatte, keikaku o tateta.', NULL, 'Khi bắt đầu cuộc sống mới, tôi đã lập kế hoạch.', 6991, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16542, 'この えは ピカソに よって かかれました。', 'kono e wa pikaso ni yotte kakaremashita.', NULL, 'Bức tranh này được vẽ bởi Picasso.', 6448, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17629, 'かいかいに あたり、ひとこと ごあいさつ もうしあげます。', 'kaikai ni atari, hitokoto goaisatsu moushiagemasu.', NULL, 'Nhân dịp khai mạc, tôi xin có đôi lời.', 6991, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17630, 'データに もとづいて、けいかくを たてる。', 'deeta ni motozuite, keikaku o tateru.', NULL, 'Lập kế hoạch dựa trên dữ liệu.', 6992, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17631, 'じじつに もとづいた えいがです。', 'jijitsu ni motozuita eiga desu.', NULL, 'Đây là bộ phim dựa trên sự thật.', 6992, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17632, 'この しょうせつは さっかの たいけんを もとに かかれた。', 'kono shousetsu wa sakka no taiken o moto ni kakareta.', NULL, 'Cuốn tiểu thuyết này được viết dựa trên trải nghiệm của tác giả.', 6993, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17633, 'アンケートの けっかを もとに して、しょうひんを かいぜんした。', 'ankeeto no kekka o moto ni shite, shouhin o kaizen shita.', NULL, 'Cải tiến sản phẩm dựa trên kết quả khảo sát.', 6993, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17634, 'かわに そって、さくらが さいて いる。', 'kawa ni sotte, sakura ga saite iru.', NULL, 'Hoa anh đào nở dọc bờ sông.', 6994, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17635, 'マニュアルに そって さぎょうを すすめて ください。', 'manyuaru ni sotte sagyou o susumete kudasai.', NULL, 'Hãy tiến hành công việc theo sổ hướng dẫn.', 6994, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17636, 'レベルに おうじて、クラスを わけます。', 'reberu ni oujite, kurasu o wakemasu.', NULL, 'Chia lớp tùy theo trình độ.', 6995, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17637, 'きゃくの ようぼうに おうじた サービスを ていきょうする。', 'kyaku no youbou ni oujita saabisu o teikyou suru.', NULL, 'Cung cấp dịch vụ đáp ứng yêu cầu khách hàng.', 6995, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17638, 'あたらしい ほうりつを めぐって、ぎろんが つづいて いる。', 'atarashii houritsu o megutte, giron ga tsuzuite iru.', NULL, 'Tranh luận quanh luật mới vẫn tiếp diễn.', 6996, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17639, 'いさんを めぐる あらそいが おきた。', 'isan o meguru arasoi ga okita.', NULL, 'Đã xảy ra tranh chấp quanh tài sản thừa kế.', 6996, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17640, 'この まつりは わかものを ちゅうしんに にんきが ある。', 'kono matsuri wa wakamono o chuushin ni ninki ga aru.', NULL, 'Lễ hội này được ưa chuộng, chủ yếu trong giới trẻ.', 6997, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17641, 'えきを ちゅうしんに して、まちが ひろがって いる。', 'eki o chuushin ni shite, machi ga hirogatte iru.', NULL, 'Thị trấn trải rộng lấy nhà ga làm trung tâm.', 6997, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17642, 'かいぎは 3じかんに わたって つづいた。', 'kaigi wa sanjikan ni watatte tsuzuita.', NULL, 'Cuộc họp kéo dài suốt 3 tiếng.', 6998, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17643, 'ぜんこくに わたる ちょうさが おこなわれた。', 'zenkoku ni wataru chousa ga okonawareta.', NULL, 'Cuộc khảo sát khắp cả nước đã được tiến hành.', 6998, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17644, 'ともだちを つうじて、かのじょと しりあった。', 'tomodachi o tsuujite, kanojo to shiriatta.', NULL, 'Tôi quen cô ấy thông qua bạn bè.', 6999, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17645, 'この ちほうは いちねんを とおして あたたかい。', 'kono chihou wa ichinen o tooshite atatakai.', NULL, 'Vùng này ấm áp quanh năm.', 6999, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17646, 'この けんに かんして、ごいけんを おきかせください。', 'kono ken ni kanshite, goiken o okikase kudasai.', NULL, 'Xin cho biết ý kiến về việc này.', 7000, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17647, 'かんきょうもんだいに かんする ろんぶんを かいた。', 'kankyou mondai ni kansuru ronbun o kaita.', NULL, 'Tôi đã viết luận văn về vấn đề môi trường.', 7000, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17648, 'りゅうがくを きっかけに、にほんの ぶんかに きょうみを もった。', 'ryuugaku o kikkake ni, nihon no bunka ni kyoumi o motta.', NULL, 'Nhân chuyến du học, tôi bắt đầu thích văn hóa Nhật.', 7001, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17649, 'びょうきを きっかけに、タバコを やめた。', 'byouki o kikkake ni, tabako o yameta.', NULL, 'Nhân lần ốm, tôi đã bỏ thuốc lá.', 7001, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17650, 'りょうりに かけては、かれに かなう ひとは いない。', 'ryouri ni kakete wa, kare ni kanau hito wa inai.', NULL, 'Về nấu ăn thì không ai bằng anh ấy.', 7002, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17652, 'この ゲームは こども に かぎらず、おとなにも にんきだ。', 'kono geemu wa kodomo ni kagirazu, otona ni mo ninki da.', NULL, 'Trò chơi này không chỉ trẻ em mà người lớn cũng thích.', 7003, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17653, 'にちようびに かぎらず、へいじつも あいて います。', 'nichiyoubi ni kagirazu, heijitsu mo aite imasu.', NULL, 'Không chỉ Chủ nhật, ngày thường cũng mở cửa.', 7003, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17654, 'きょうに かぎり、ぜんぴん はんがくです。', 'kyou ni kagiri, zenpin hangaku desu.', NULL, 'Chỉ riêng hôm nay, mọi sản phẩm giảm nửa giá.', 7004, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17655, 'よやくした かたに かぎり、にゅうじょうできます。', 'yoyaku shita kata ni kagiri, nyuujou dekimasu.', NULL, 'Chỉ người đã đặt trước mới được vào.', 7004, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17656, 'いきて いる かぎり、あなたを わすれない。', 'ikite iru kagiri, anata o wasurenai.', NULL, 'Chừng nào còn sống, tôi không quên bạn.', 7005, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17657, 'わたしの しって いる かぎり、かれは しょうじきな ひとだ。', 'watashi no shitte iru kagiri, kare wa shoujiki na hito da.', NULL, 'Theo như tôi biết, anh ấy là người thật thà.', 7005, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17658, 'この もんだいは にほん のみならず、せかいの もんだいだ。', 'kono mondai wa nihon nominarazu, sekai no mondai da.', NULL, 'Vấn đề này không chỉ của Nhật mà của cả thế giới.', 7006, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17659, 'かれは がくせい のみならず、せんせいからも しんらいされて いる。', 'kare wa gakusei nominarazu, sensei kara mo shinrai sarete iru.', NULL, 'Anh ấy được cả học sinh lẫn giáo viên tin tưởng.', 7006, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17660, 'この みせは あじは もちろん、サービスも いい。', 'kono mise wa aji wa mochiron, saabisu mo ii.', NULL, 'Quán này vị thì khỏi nói, phục vụ cũng tốt.', 7007, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17661, 'にちようびは もちろん、へいじつも こんで いる。', 'nichiyoubi wa mochiron, heijitsu mo konde iru.', NULL, 'Chủ nhật thì đương nhiên, ngày thường cũng đông.', 7007, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17662, 'ねだんは ともかく、デザインが きに いらない。', 'nedan wa tomokaku, dezain ga ki ni iranai.', NULL, 'Giá cả thì tạm gác, tôi không thích thiết kế.', 7008, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17663, 'けっかは ともかく、さいごまで がんばった ことが たいせつだ。', 'kekka wa tomokaku, saigo made ganbatta koto ga taisetsu da.', NULL, 'Kết quả thế nào không bàn, cố gắng đến cùng mới quan trọng.', 7008, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17664, 'ねんれいを とわず、だれでも さんかできます。', 'nenrei o towazu, daredemo sanka dekimasu.', NULL, 'Bất kể tuổi tác, ai cũng có thể tham gia.', 7009, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17665, 'この しごとは けいけんの うむを とわない。', 'kono shigoto wa keiken no umu o towanai.', NULL, 'Công việc này không kể có kinh nghiệm hay không.', 7009, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17666, 'てんきに かかわらず、しあいは おこなわれます。', 'tenki ni kakawarazu, shiai wa okonawaremasu.', NULL, 'Bất kể thời tiết, trận đấu vẫn diễn ra.', 7010, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17667, 'さんかする しないに かかわらず、へんじを ください。', 'sanka suru shinai ni kakawarazu, henji o kudasai.', NULL, 'Dù tham gia hay không, xin hãy phản hồi.', 7010, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17668, 'かれは ひとめも かまわず、ないた。', 'kare wa hitome mo kamawazu, naita.', NULL, 'Anh ấy khóc chẳng để ý ánh mắt người khác.', 7011, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17669, 'ふくが ぬれるのも かまわず、あめの なかを はしった。', 'fuku ga nureru no mo kamawazu, ame no naka o hashitta.', NULL, 'Mặc kệ quần áo ướt, tôi chạy trong mưa.', 7011, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17670, 'じょうだんは さておき、ほんだいに はいりましょう。', 'joudan wa sateoki, hondai ni hairimashou.', NULL, 'Đùa thì để sau, vào vấn đề chính thôi.', 7012, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17671, 'ひようの もんだいは さておき、まず けいかくを たてよう。', 'hiyou no mondai wa sateoki, mazu keikaku o tateyou.', NULL, 'Chuyện chi phí để sau, trước hết lập kế hoạch đã.', 7012, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17672, 'さすが プロだけ あって、うまいね。', 'sasuga puro dake atte, umai ne.', NULL, 'Quả là dân chuyên nghiệp, giỏi thật.', 7013, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17673, '10ねん すんで いた だけ あって、この まちに くわしい。', 'juunen sunde ita dake atte, kono machi ni kuwashii.', NULL, 'Đã sống 10 năm nên quả rành thị trấn này.', 7013, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17674, 'やると きめた からには、さいごまで やる。', 'yaru to kimeta kara ni wa, saigo made yaru.', NULL, 'Một khi đã quyết làm thì làm đến cùng.', 7014, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17675, 'やくそくした いじょう、まもらなければ ならない。', 'yakusoku shita ijou, mamoranakereba naranai.', NULL, 'Đã hứa thì phải giữ lời.', 7014, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17676, 'きたいして いた だけに、ざんねんだ。', 'kitai shite ita dake ni, zannen da.', NULL, 'Chính vì đã kỳ vọng nên càng tiếc.', 7015, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17677, 'かんこうちだけに、ひとが おおい。', 'kankouchi dake ni, hito ga ooi.', NULL, 'Vì là điểm du lịch nên càng đông người.', 7015, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17678, 'でんしゃが おくれた ものだから、ちこくして しまいました。', 'densha ga okureta mono da kara, chikoku shite shimaimashita.', NULL, 'Vì tàu trễ nên tôi đến muộn.', 7016, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17679, 'あまりに おいしい ものだから、たべすぎて しまった。', 'amari ni oishii mono da kara, tabesugite shimatta.', NULL, 'Ngon quá nên tôi ăn quá nhiều.', 7016, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17680, 'しんぱいの あまり、ねむれなかった。', 'shinpai no amari, nemurenakatta.', NULL, 'Vì quá lo lắng nên không ngủ được.', 7017, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17681, 'よろこびの あまり、なきだした。', 'yorokobi no amari, nakidashita.', NULL, 'Vui quá nên bật khóc.', 7017, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17682, 'まじめな かれの ことだから、やくそくは まもるだろう。', 'majime na kare no koto da kara, yakusoku wa mamoru darou.', NULL, 'Anh ấy nghiêm túc nên chắc sẽ giữ lời.', 7018, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17683, 'あの ひとの ことだから、また わすれて いるよ。', 'ano hito no koto da kara, mata wasurete iru yo.', NULL, 'Người đó mà, chắc lại quên rồi.', 7018, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17684, 'おかねが ある からと いって、しあわせとは かぎらない。', 'okane ga aru kara to itte, shiawase to wa kagiranai.', NULL, 'Có tiền chưa chắc đã hạnh phúc.', 7019, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17685, 'にほんじんだ からと いって、けいごが じょうずとは かぎらない。', 'nihonjin da kara to itte, keigo ga jouzu to wa kagiranai.', NULL, 'Là người Nhật chưa chắc đã giỏi kính ngữ.', 7019, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17686, 'ねぶそくの せいか、あたまが いたい。', 'nebusoku no sei ka, atama ga itai.', NULL, 'Có lẽ do thiếu ngủ nên đau đầu.', 7020, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17687, 'としの せいか、つかれやすく なった。', 'toshi no sei ka, tsukareyasuku natta.', NULL, 'Có lẽ do tuổi tác nên dễ mệt hơn.', 7020, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17688, 'この はしは かたちが にじに にて いる ことから、にじばしと よばれて いる。', 'kono hashi wa katachi ga niji ni nite iru koto kara, nijibashi to yobarete iru.', NULL, 'Cây cầu có hình giống cầu vồng nên được gọi là cầu Cầu Vồng.', 7021, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19092, 'きのう 雨だった。', 'Kinō ame datta.', NULL, 'Hôm qua trời mưa.', 7724, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17689, 'あしあとが ある ことから、だれかが はいったと わかった。', 'ashiato ga aru koto kara, dareka ga haitta to wakatta.', NULL, 'Từ dấu chân, biết là có người đã vào.', 7021, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17690, 'ひとりで さんにんぶん はたらいて いる わけだから、つかれるのも とうぜんだ。', 'hitori de sanninbun hataraite iru wake da kara, tsukareru no mo touzen da.', NULL, 'Một mình làm việc của ba người thì mệt là đương nhiên.', 7022, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17691, 'もう きめた わけだから、まよう ひつようは ない。', 'mou kimeta wake da kara, mayou hitsuyou wa nai.', NULL, 'Đã quyết rồi thì không cần đắn đo.', 7022, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17692, 'はなしあった けっか、けいかくを へんこうする ことに なった。', 'hanashiatta kekka, keikaku o henkou suru koto ni natta.', NULL, 'Kết quả bàn bạc là đổi kế hoạch.', 7023, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17693, 'ちょうさの けっか、げんいんが わかった。', 'chousa no kekka, gen''in ga wakatta.', NULL, 'Kết quả điều tra đã tìm ra nguyên nhân.', 7023, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17694, 'この りょうでは 10じいこう、おんがくを ひかない ことに なって いる。', 'kono ryou de wa juuji ikou, ongaku o hikanai koto ni natte iru.', NULL, 'Ở ký túc xá này quy định sau 10 giờ không chơi nhạc.', 7024, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17695, 'しゅっきんしたら、タイムカードを おす ことに なって います。', 'shukkin shitara, taimukaado o osu koto ni natte imasu.', NULL, 'Theo quy định, đi làm thì phải bấm thẻ chấm công.', 7024, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17696, 'それは うわさに すぎない。', 'sore wa uwasa ni suginai.', NULL, 'Đó chỉ là tin đồn mà thôi.', 7025, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17697, 'わたしは ただの がくせいに すぎません。', 'watashi wa tada no gakusei ni sugimasen.', NULL, 'Tôi chỉ là một sinh viên bình thường.', 7025, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17698, 'そんな はなし、うそに きまって いる。', 'sonna hanashi, uso ni kimatte iru.', NULL, 'Chuyện như thế chắc chắn là nói dối.', 7026, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17699, 'いまから いっても まにあわないに きまって いる。', 'ima kara itte mo maniawanai ni kimatte iru.', NULL, 'Bây giờ đi thì chắc chắn không kịp.', 7026, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17700, 'かれが はんにんで ある ことに そういない。', 'kare ga hannin de aru koto ni soui nai.', NULL, 'Chắc chắn anh ta là thủ phạm.', 7027, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17701, 'この えは ゆうめいな がかの さくひんに そういない。', 'kono e wa yuumei na gaka no sakuhin ni soui nai.', NULL, 'Bức tranh này hẳn là tác phẩm của họa sĩ nổi tiếng.', 7027, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17702, 'あんな みせ、にどと いく ものか。', 'anna mise, nido to iku mono ka.', NULL, 'Quán như thế, còn lâu tôi mới quay lại.', 7028, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17703, 'まけて たまるもんか。', 'makete tamaru mon ka.', NULL, 'Không đời nào tôi chịu thua.', 7028, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17704, 'そんな むずかしい もんだい、わかりっこない。', 'sonna muzukashii mondai, wakarikkonai.', NULL, 'Bài khó thế sao mà hiểu nổi.', 7029, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17705, 'いまから はしっても、まにあいっこない。', 'ima kara hashitte mo, maniaikkonai.', NULL, 'Giờ chạy cũng không đời nào kịp.', 7029, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17706, 'れんらくさきが わからないので、れんらくの しようが ない。', 'renrakusaki ga wakaranai node, renraku no shiyou ga nai.', NULL, 'Không biết địa chỉ liên lạc nên không có cách nào liên lạc.', 7030, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17707, 'こわれて しまって、なおしようが ない。', 'kowarete shimatte, naoshiyou ga nai.', NULL, 'Hỏng mất rồi, không cách nào sửa được.', 7030, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17708, 'たいふうが くるので、りょこうを ちゅうしせざるを えない。', 'taifuu ga kuru node, ryokou o chuushi sezaru o enai.', NULL, 'Bão đến nên buộc phải hủy chuyến đi.', 7031, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17709, 'しゃちょうの めいれいなら、したがわざるを えない。', 'shachou no meirei nara, shitagawazaru o enai.', NULL, 'Lệnh giám đốc thì buộc phải tuân theo.', 7031, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17710, 'この ままでは じこに なりかねない。', 'kono mama de wa jiko ni narikanenai.', NULL, 'Cứ thế này thì có thể xảy ra tai nạn.', 7032, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17711, 'かれなら そんな ことも いいかねない。', 'kare nara sonna koto mo iikanenai.', NULL, 'Anh ta thì có khi nói ra điều đó lắm.', 7032, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17712, 'その ごようぼうには おこたえ しかねます。', 'sono goyoubou ni wa okotae shikanemasu.', NULL, 'Chúng tôi khó đáp ứng yêu cầu đó.', 7033, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17713, 'かれの いけんには さんせいしかねる。', 'kare no iken ni wa sansei shikaneru.', NULL, 'Tôi khó mà tán thành ý kiến của anh ấy.', 7033, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17714, 'かれが うそを ついたとは しんじがたい。', 'kare ga uso o tsuita to wa shinjigatai.', NULL, 'Khó tin rằng anh ấy đã nói dối.', 7034, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17715, 'この おもいでは わすれがたい。', 'kono omoide wa wasuregatai.', NULL, 'Kỷ niệm này khó mà quên.', 7034, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17716, 'だれにでも ありうる しっぱいだ。', 'dare ni demo ariuru shippai da.', NULL, 'Đó là thất bại ai cũng có thể mắc.', 7035, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17717, 'そんな ことは ありえない。', 'sonna koto wa arienai.', NULL, 'Chuyện đó không thể có.', 7035, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17718, 'せいこうしたのは どりょくの けっかに ほかならない。', 'seikou shita no wa doryoku no kekka ni hoka naranai.', NULL, 'Thành công chính là kết quả của nỗ lực.', 7036, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17719, 'この しっぱいは けいかくの あまさに ほかならない。', 'kono shippai wa keikaku no amasa ni hoka naranai.', NULL, 'Thất bại này không gì khác ngoài kế hoạch sơ sài.', 7036, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17720, 'ながく べんきょうすれば いい と いう ものでは ない。', 'nagaku benkyou sureba ii to iu mono de wa nai.', NULL, 'Không phải cứ học lâu là tốt.', 7037, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17721, 'やすければ うれる と いう ものでは ない。', 'yasukereba ureru to iu mono de wa nai.', NULL, 'Không phải cứ rẻ là bán được.', 7037, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17722, 'くるまの めんきょは ある ものの、ほとんど うんてんしない。', 'kuruma no menkyo wa aru mono no, hotondo unten shinai.', NULL, 'Có bằng lái nhưng tôi hầu như không lái.', 7038, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17723, 'やくそくした ものの、いけるか どうか わからない。', 'yakusoku shita mono no, ikeru ka dou ka wakaranai.', NULL, 'Đã hứa nhưng không biết có đi được không.', 7038, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17724, 'あめに も かかわらず、おおぜいの ひとが あつまった。', 'ame ni mo kakawarazu, oozei no hito ga atsumatta.', NULL, 'Mặc dù mưa, rất nhiều người đã tập trung.', 7039, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17725, 'どりょくしたに も かかわらず、しっぱいした。', 'doryoku shita ni mo kakawarazu, shippai shita.', NULL, 'Dù đã nỗ lực vẫn thất bại.', 7039, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17726, 'わるいと しりつつ、うそを ついて しまった。', 'warui to shiritsutsu, uso o tsuite shimatta.', NULL, 'Biết là sai mà vẫn nói dối.', 7040, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17727, 'けしきを たのしみつつ、さんぽした。', 'keshiki o tanoshimitsutsu, sanpo shita.', NULL, 'Vừa ngắm cảnh vừa đi dạo.', 7040, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17728, 'とかいは べんりな はんめん、ストレスも おおい。', 'tokai wa benri na hanmen, sutoresu mo ooi.', NULL, 'Thành phố tiện lợi, mặt khác cũng nhiều áp lực.', 7041, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17729, 'この くすりは よく きく はんめん、ふくさようも ある。', 'kono kusuri wa yoku kiku hanmen, fukusayou mo aru.', NULL, 'Thuốc này hiệu quả, nhưng cũng có tác dụng phụ.', 7041, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17730, 'しごとを する いっぽうで、だいがくいんにも かよって いる。', 'shigoto o suru ippou de, daigakuin ni mo kayotte iru.', NULL, 'Vừa đi làm, mặt khác vẫn học cao học.', 7042, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17731, 'とかいの じんこうは ふえる いっぽうで、いなかは へって いる。', 'tokai no jinkou wa fueru ippou de, inaka wa hette iru.', NULL, 'Dân số đô thị tăng trong khi nông thôn giảm.', 7042, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17732, 'よそうに はんして、しあいに まけた。', 'yosou ni hanshite, shiai ni maketa.', NULL, 'Trái với dự đoán, chúng tôi thua trận.', 7043, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17733, 'おやの きたいに はんして、かれは だいがくを やめた。', 'oya no kitai ni hanshite, kare wa daigaku o yameta.', NULL, 'Trái với kỳ vọng của bố mẹ, anh ấy bỏ đại học.', 7043, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17734, 'やすむ どころか、ねる じかんも ない。', 'yasumu dokoroka, neru jikan mo nai.', NULL, 'Nói gì đến nghỉ, đến thời gian ngủ cũng không có.', 7044, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17735, 'くすりを のんだが、よく なる どころか わるく なった。', 'kusuri o nonda ga, yoku naru dokoroka waruku natta.', NULL, 'Uống thuốc rồi mà chẳng đỡ, trái lại còn tệ hơn.', 7044, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17737, 'かれは ともだち と いうより かぞくの ような ものだ。', 'kare wa tomodachi to iu yori kazoku no you na mono da.', NULL, 'Anh ấy giống gia đình hơn là bạn bè.', 7045, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17738, 'いまさら あやまった ところで、ゆるして もらえないだろう。', 'imasara ayamatta tokoro de, yurushite moraenai darou.', NULL, 'Bây giờ có xin lỗi thì cũng chẳng được tha thứ.', 7046, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17739, 'いくら いった ところで、かれは きかない。', 'ikura itta tokoro de, kare wa kikanai.', NULL, 'Có nói bao nhiêu thì anh ta cũng không nghe.', 7046, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17740, 'いそがしい にしても、れんらくくらい できたはずだ。', 'isogashii ni shite mo, renraku kurai dekita hazu da.', NULL, 'Dù bận đi nữa thì ít ra cũng liên lạc được.', 7047, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17741, 'いく にしろ いかない にしろ、へんじを して ください。', 'iku ni shiro ikanai ni shiro, henji o shite kudasai.', NULL, 'Đi hay không đi thì cũng hãy trả lời.', 7047, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17742, 'ざんねん ながら、こんかいは みおくる ことに しました。', 'zannen nagara, konkai wa miokuru koto ni shimashita.', NULL, 'Rất tiếc, lần này chúng tôi quyết định không tham gia.', 7048, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17743, 'こども ながら、しっかりした かんがえを もって いる。', 'kodomo nagara, shikkari shita kangae o motte iru.', NULL, 'Tuy là trẻ con nhưng suy nghĩ rất chín chắn.', 7048, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17744, 'この みせは ねだんの わりに おいしい。', 'kono mise wa nedan no wari ni oishii.', NULL, 'Quán này so với giá thì khá ngon.', 7049, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17745, 'かれは としの わりに わかく みえる。', 'kare wa toshi no wari ni wakaku mieru.', NULL, 'So với tuổi, anh ấy trông trẻ.', 7049, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17746, 'あの えいがを みたら、なかずには いられない。', 'ano eiga o mitara, nakazu ni wa irarenai.', NULL, 'Xem bộ phim đó thì không thể không khóc.', 7050, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17747, 'かのじょの ことを しんぱいせずには いられない。', 'kanojo no koto o shinpai sezu ni wa irarenai.', NULL, 'Tôi không thể không lo cho cô ấy.', 7050, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17748, 'のどが かわいて たまらない。', 'nodo ga kawaite tamaranai.', NULL, 'Khát không chịu nổi.', 7051, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17749, 'こきょうの かぞくに あいたくて たまらない。', 'kokyou no kazoku ni aitakute tamaranai.', NULL, 'Nhớ gia đình ở quê vô cùng.', 7051, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17750, 'むすこの ことが しんぱいで ならない。', 'musuko no koto ga shinpai de naranai.', NULL, 'Tôi lo cho con trai không sao chịu được.', 7052, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17751, 'だれかに みられて いる ような きが して ならない。', 'dareka ni mirarete iru you na ki ga shite naranai.', NULL, 'Cứ có cảm giác như bị ai đó nhìn.', 7052, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17752, 'あたまが いたくて しょうがない。', 'atama ga itakute shouganai.', NULL, 'Đau đầu hết sức.', 7053, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17753, 'ひまで しかたが ない。', 'hima de shikata ga nai.', NULL, 'Rảnh rỗi chán không chịu được.', 7053, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17754, 'あなたに あえて、どんなに うれしい ことか。', 'anata ni aete, donna ni ureshii koto ka.', NULL, 'Được gặp bạn tôi vui biết bao!', 7054, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17755, 'なんど ちゅういした ことか。', 'nando chuui shita koto ka.', NULL, 'Đã nhắc nhở bao nhiêu lần rồi!', 7054, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17756, 'つかれた ときは ねるに かぎる。', 'tsukareta toki wa neru ni kagiru.', NULL, 'Khi mệt thì ngủ là nhất.', 7055, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17757, 'なつは つめたい ビールに かぎる。', 'natsu wa tsumetai biiru ni kagiru.', NULL, 'Mùa hè thì bia lạnh là nhất.', 7055, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17758, 'じぶんで やって こそ、ほんとうに わかる。', 'jibun de yatte koso, hontou ni wakaru.', NULL, 'Chỉ khi tự làm mới thật sự hiểu.', 7056, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17759, 'たがいに たすけあって こそ、なかまだ。', 'tagai ni tasukeatte koso, nakama da.', NULL, 'Có giúp đỡ nhau mới là đồng đội.', 7056, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17760, 'いそがしくて、しょくじを する じかん さえ ない。', 'isogashikute, shokuji o suru jikan sae nai.', NULL, 'Bận đến mức ngay cả thời gian ăn cũng không có.', 7057, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17761, 'この かんじは せんせい すら よめなかった。', 'kono kanji wa sensei sura yomenakatta.', NULL, 'Chữ Hán này ngay cả thầy cũng không đọc được.', 7057, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17762, 'かれが けっこんする なんて、しんじられない。', 'kare ga kekkon suru nante, shinjirarenai.', NULL, 'Anh ta mà kết hôn ư, không thể tin nổi.', 7058, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17763, 'べんきょう なんか したくない。', 'benkyou nanka shitakunai.', NULL, 'Học hành gì chứ, chẳng muốn.', 7058, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17764, 'あんな ひとに たのむ くらいなら、じぶんで やる。', 'anna hito ni tanomu kurai nara, jibun de yaru.', NULL, 'Nếu phải nhờ người như thế thì thà tự làm.', 7059, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17765, 'とちゅうで やめる くらいなら、はじめから やらない ほうが いい。', 'tochuu de yameru kurai nara, hajime kara yaranai hou ga ii.', NULL, 'Nếu bỏ giữa chừng thì thà đừng làm từ đầu.', 7059, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17766, 'なんとしても こんどの しけんに ごうかくしたい。', 'nan to shite mo kondo no shiken ni goukaku shitai.', NULL, 'Bằng mọi giá tôi muốn đỗ kỳ thi lần này.', 7060, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17767, 'ぜひ いちど おあいしたいです。', 'zehi ichido oai shitai desu.', NULL, 'Nhất định tôi muốn gặp anh một lần.', 7060, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17768, 'この さくぶんは まちがい だらけだ。', 'kono sakubun wa machigai darake da.', NULL, 'Bài văn này toàn là lỗi.', 7061, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17769, 'どろ だらけの くつで はいらないで。', 'doro darake no kutsu de hairanaide.', NULL, 'Đừng đi giày lấm bùn vào.', 7061, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17771, 'かのじょは くろ ずくめの ふくを きて いた。', 'kanojo wa kuro zukume no fuku o kite ita.', NULL, 'Cô ấy mặc toàn đồ đen.', 7062, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17772, 'かのじょは さびし げに わらった。', 'kanojo wa sabishi ge ni waratta.', NULL, 'Cô ấy cười có vẻ buồn.', 7063, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17773, 'こどもたちは たのし げに あそんで いる。', 'kodomotachi wa tanoshi ge ni asonde iru.', NULL, 'Bọn trẻ đang chơi có vẻ vui.', 7063, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17774, 'この コースは しょしんしゃ むきです。', 'kono koosu wa shoshinsha muki desu.', NULL, 'Khóa này phù hợp người mới.', 7064, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17775, 'これは こども むけの ばんぐみだ。', 'kore wa kodomo muke no bangumi da.', NULL, 'Đây là chương trình dành cho trẻ em.', 7064, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17776, 'せいこうするか どうかは どりょく しだいだ。', 'seikou suru ka dou ka wa doryoku shidai da.', NULL, 'Thành công hay không tùy vào nỗ lực.', 7065, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17777, 'てんき しだいで、よていを かえる。', 'tenki shidai de, yotei o kaeru.', NULL, 'Tùy thời tiết mà đổi kế hoạch.', 7065, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17778, 'じんこうの ぞうかに ともなって、じゅうたくが ふそくした。', 'jinkou no zouka ni tomonatte, juutaku ga fusoku shita.', NULL, 'Cùng với dân số tăng, nhà ở trở nên thiếu.', 7066, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17779, 'ぎじゅつの しんぽに ともない、せいかつが かわった。', 'gijutsu no shinpo ni tomonai, seikatsu ga kawatta.', NULL, 'Kéo theo tiến bộ kỹ thuật, cuộc sống thay đổi.', 7066, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17780, 'ごみの りょうは ふえる いっぽうだ。', 'gomi no ryou wa fueru ippou da.', NULL, 'Lượng rác cứ ngày càng tăng.', 7067, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17781, 'かれとの きょりは ひらく いっぽうだった。', 'kare to no kyori wa hiraku ippou datta.', NULL, 'Khoảng cách với anh ấy ngày càng xa.', 7067, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17782, 'あさごはん ぬきで かいしゃに いった。', 'asagohan nuki de kaisha ni itta.', NULL, 'Tôi đi làm mà không ăn sáng.', 7068, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17783, 'じょうだんは ぬきに して、まじめに はなそう。', 'joudan wa nuki ni shite, majime ni hanasou.', NULL, 'Bỏ đùa sang bên, nói chuyện nghiêm túc nào.', 7068, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17784, 'この ドアは ひとが ちかづくと あく ように なって いる。', 'kono doa wa hito ga chikazuku to aku you ni natte iru.', NULL, 'Cửa này được thiết kế để mở khi có người lại gần.', 7069, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17785, 'ボタンを おすと、おゆが でる ように なって います。', 'botan o osu to, oyu ga deru you ni natte imasu.', NULL, 'Bấm nút là nước nóng chảy ra.', 7069, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17786, 'にもつは まとめて、あとは でかける ばかりに なって いる。', 'nimotsu wa matomete, ato wa dekakeru bakari ni natte iru.', NULL, 'Hành lý đã gói xong, chỉ còn chờ đi.', 7070, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17787, 'りょうりは あとは たべる ばかりだ。', 'ryouri wa ato wa taberu bakari da.', NULL, 'Món ăn giờ chỉ còn ăn thôi.', 7070, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17788, 'かれは やすむ ことなく はたらきつづけた。', 'kare wa yasumu koto naku hatarakitsuzuketa.', NULL, 'Anh ấy làm việc liên tục không hề nghỉ.', 7071, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17789, 'あきらめる ことなく、さいごまで がんばった。', 'akirameru koto naku, saigo made ganbatta.', NULL, 'Không hề bỏ cuộc, cố gắng đến cùng.', 7071, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17790, 'あしが いたくて、あるけない ほどだ。', 'ashi ga itakute, arukenai hodo da.', NULL, 'Chân đau đến mức không đi được.', 7072, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17791, 'この せつめいは こどもでも わかる ほど かんたんだ。', 'kono setsumei wa kodomo demo wakaru hodo kantan da.', NULL, 'Lời giải thích đơn giản đến mức trẻ con cũng hiểu.', 7072, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17792, 'おかえりの さいは、わすれものに ごちゅういください。', 'okaeri no sai wa, wasuremono ni gochuui kudasai.', NULL, 'Khi ra về, xin chú ý đừng để quên đồ.', 7073, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17793, 'にほんへ いった さいに、ふじさんに のぼった。', 'nihon e itta sai ni, fujisan ni nobotta.', NULL, 'Nhân dịp sang Nhật, tôi đã leo núi Phú Sĩ.', 7073, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17794, 'にゅうがくに さいして、せつめいかいが おこなわれた。', 'nyuugaku ni saishite, setsumeikai ga okonawareta.', NULL, 'Nhân dịp nhập học, buổi giới thiệu đã được tổ chức.', 7074, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17795, 'けいやくに さいして、いくつか かくにんしたい ことが ある。', 'keiyaku ni saishite, ikutsuka kakunin shitai koto ga aru.', NULL, 'Khi ký hợp đồng, tôi muốn xác nhận vài điều.', 7074, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17796, 'しりょうが とどき しだい、おおくりします。', 'shiryou ga todoki shidai, ookuri shimasu.', NULL, 'Ngay khi tài liệu đến, tôi sẽ gửi đi.', 7075, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17797, 'じゅんびが でき しだい、しゅっぱつしましょう。', 'junbi ga deki shidai, shuppatsu shimashou.', NULL, 'Chuẩn bị xong là xuất phát nhé.', 7075, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17798, 'はれたかと おもったら、また ふりだした。', 'hareta ka to omottara, mata furidashita.', NULL, 'Vừa tưởng tạnh thì lại mưa tiếp.', 7076, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17799, 'こどもは かえって きたかと おもうと、すぐ あそびに でかけた。', 'kodomo wa kaette kita ka to omou to, sugu asobi ni dekaketa.', NULL, 'Con vừa về đã lại đi chơi ngay.', 7076, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17800, 'としを とるに つれて、からだが よわく なる。', 'toshi o toru ni tsurete, karada ga yowaku naru.', NULL, 'Càng có tuổi, cơ thể càng yếu đi.', 7077, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17801, 'じかんが たつに つれて、かなしみも うすれた。', 'jikan ga tatsu ni tsurete, kanashimi mo usureta.', NULL, 'Thời gian trôi đi, nỗi buồn cũng nhạt dần.', 7077, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17802, 'やまを のぼるに したがって、きおんが さがる。', 'yama o noboru ni shitagatte, kion ga sagaru.', NULL, 'Càng leo lên núi, nhiệt độ càng giảm.', 7078, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17803, 'せんせいの しじに したがって ください。', 'sensei no shiji ni shitagatte kudasai.', NULL, 'Hãy làm theo chỉ thị của thầy.', 7078, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17804, 'けいざいの はってんと ともに、せいかつが ゆたかに なった。', 'keizai no hatten to tomo ni, seikatsu ga yutaka ni natta.', NULL, 'Cùng với sự phát triển kinh tế, đời sống sung túc hơn.', 7079, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17805, 'かぞくと ともに しょうがつを すごした。', 'kazoku to tomo ni shougatsu o sugoshita.', NULL, 'Tôi đón Tết cùng gia đình.', 7079, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17806, 'ながい はなしあいの すえに、けつろんが でた。', 'nagai hanashiai no sue ni, ketsuron ga deta.', NULL, 'Sau một hồi bàn bạc dài, đã có kết luận.', 7080, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17807, 'なやんだ すえ、かいしゃを やめる ことに した。', 'nayanda sue, kaisha o yameru koto ni shita.', NULL, 'Sau khi đắn đo, tôi quyết định nghỉ việc.', 7080, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17808, 'さんざん まよった あげく、なにも かわなかった。', 'sanzan mayotta ageku, nani mo kawanakatta.', NULL, 'Đắn đo mãi rốt cuộc chẳng mua gì.', 7081, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17809, 'けんかした あげくに、わかれて しまった。', 'kenka shita ageku ni, wakarete shimatta.', NULL, 'Cãi nhau mãi rồi rốt cuộc chia tay.', 7081, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17810, 'よく かんがえた うえで、へんじします。', 'yoku kangaeta ue de, henji shimasu.', NULL, 'Tôi sẽ suy nghĩ kỹ rồi mới trả lời.', 7082, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17811, 'りょうしんと そうだんの うえ、きめました。', 'ryoushin to soudan no ue, kimemashita.', NULL, 'Sau khi bàn với bố mẹ, tôi đã quyết định.', 7082, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17812, 'いぬを かいはじめて からと いう もの、まいあさ さんぽして いる。', 'inu o kaihajimete kara to iu mono, maiasa sanpo shite iru.', NULL, 'Kể từ khi nuôi chó, sáng nào tôi cũng đi dạo.', 7083, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17813, 'かのじょに あって からと いう もの、かれは かわった。', 'kanojo ni atte kara to iu mono, kare wa kawatta.', NULL, 'Từ khi gặp cô ấy, anh ta thay đổi hẳn.', 7083, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17814, 'しんせいかつを はじめるに あたって、けいかくを たてた。', 'shinseikatsu o hajimeru ni atatte, keikaku o tateta.', NULL, 'Khi bắt đầu cuộc sống mới, tôi đã lập kế hoạch.', 7084, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17815, 'かいかいに あたり、ひとこと ごあいさつ もうしあげます。', 'kaikai ni atari, hitokoto goaisatsu moushiagemasu.', NULL, 'Nhân dịp khai mạc, tôi xin có đôi lời.', 7084, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17816, 'データに もとづいて、けいかくを たてる。', 'deeta ni motozuite, keikaku o tateru.', NULL, 'Lập kế hoạch dựa trên dữ liệu.', 7085, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17817, 'じじつに もとづいた えいがです。', 'jijitsu ni motozuita eiga desu.', NULL, 'Đây là bộ phim dựa trên sự thật.', 7085, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17818, 'この しょうせつは さっかの たいけんを もとに かかれた。', 'kono shousetsu wa sakka no taiken o moto ni kakareta.', NULL, 'Cuốn tiểu thuyết này được viết dựa trên trải nghiệm của tác giả.', 7086, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17819, 'アンケートの けっかを もとに して、しょうひんを かいぜんした。', 'ankeeto no kekka o moto ni shite, shouhin o kaizen shita.', NULL, 'Cải tiến sản phẩm dựa trên kết quả khảo sát.', 7086, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17820, 'かわに そって、さくらが さいて いる。', 'kawa ni sotte, sakura ga saite iru.', NULL, 'Hoa anh đào nở dọc bờ sông.', 7087, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17821, 'マニュアルに そって さぎょうを すすめて ください。', 'manyuaru ni sotte sagyou o susumete kudasai.', NULL, 'Hãy tiến hành công việc theo sổ hướng dẫn.', 7087, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17822, 'レベルに おうじて、クラスを わけます。', 'reberu ni oujite, kurasu o wakemasu.', NULL, 'Chia lớp tùy theo trình độ.', 7088, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17823, 'きゃくの ようぼうに おうじた サービスを ていきょうする。', 'kyaku no youbou ni oujita saabisu o teikyou suru.', NULL, 'Cung cấp dịch vụ đáp ứng yêu cầu khách hàng.', 7088, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17824, 'あたらしい ほうりつを めぐって、ぎろんが つづいて いる。', 'atarashii houritsu o megutte, giron ga tsuzuite iru.', NULL, 'Tranh luận quanh luật mới vẫn tiếp diễn.', 7089, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17825, 'いさんを めぐる あらそいが おきた。', 'isan o meguru arasoi ga okita.', NULL, 'Đã xảy ra tranh chấp quanh tài sản thừa kế.', 7089, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17826, 'この まつりは わかものを ちゅうしんに にんきが ある。', 'kono matsuri wa wakamono o chuushin ni ninki ga aru.', NULL, 'Lễ hội này được ưa chuộng, chủ yếu trong giới trẻ.', 7090, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17827, 'えきを ちゅうしんに して、まちが ひろがって いる。', 'eki o chuushin ni shite, machi ga hirogatte iru.', NULL, 'Thị trấn trải rộng lấy nhà ga làm trung tâm.', 7090, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17828, 'かいぎは 3じかんに わたって つづいた。', 'kaigi wa sanjikan ni watatte tsuzuita.', NULL, 'Cuộc họp kéo dài suốt 3 tiếng.', 7091, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17829, 'ぜんこくに わたる ちょうさが おこなわれた。', 'zenkoku ni wataru chousa ga okonawareta.', NULL, 'Cuộc khảo sát khắp cả nước đã được tiến hành.', 7091, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17830, 'ともだちを つうじて、かのじょと しりあった。', 'tomodachi o tsuujite, kanojo to shiriatta.', NULL, 'Tôi quen cô ấy thông qua bạn bè.', 7092, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17831, 'この ちほうは いちねんを とおして あたたかい。', 'kono chihou wa ichinen o tooshite atatakai.', NULL, 'Vùng này ấm áp quanh năm.', 7092, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17832, 'この けんに かんして、ごいけんを おきかせください。', 'kono ken ni kanshite, goiken o okikase kudasai.', NULL, 'Xin cho biết ý kiến về việc này.', 7093, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17833, 'かんきょうもんだいに かんする ろんぶんを かいた。', 'kankyou mondai ni kansuru ronbun o kaita.', NULL, 'Tôi đã viết luận văn về vấn đề môi trường.', 7093, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17834, 'りゅうがくを きっかけに、にほんの ぶんかに きょうみを もった。', 'ryuugaku o kikkake ni, nihon no bunka ni kyoumi o motta.', NULL, 'Nhân chuyến du học, tôi bắt đầu thích văn hóa Nhật.', 7094, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17835, 'びょうきを きっかけに、タバコを やめた。', 'byouki o kikkake ni, tabako o yameta.', NULL, 'Nhân lần ốm, tôi đã bỏ thuốc lá.', 7094, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17836, 'りょうりに かけては、かれに かなう ひとは いない。', 'ryouri ni kakete wa, kare ni kanau hito wa inai.', NULL, 'Về nấu ăn thì không ai bằng anh ấy.', 7095, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17837, 'はしる ことに かけては、じしんが ある。', 'hashiru koto ni kakete wa, jishin ga aru.', NULL, 'Về chạy thì tôi tự tin.', 7095, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17838, 'この ゲームは こども に かぎらず、おとなにも にんきだ。', 'kono geemu wa kodomo ni kagirazu, otona ni mo ninki da.', NULL, 'Trò chơi này không chỉ trẻ em mà người lớn cũng thích.', 7096, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17839, 'にちようびに かぎらず、へいじつも あいて います。', 'nichiyoubi ni kagirazu, heijitsu mo aite imasu.', NULL, 'Không chỉ Chủ nhật, ngày thường cũng mở cửa.', 7096, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17840, 'きょうに かぎり、ぜんぴん はんがくです。', 'kyou ni kagiri, zenpin hangaku desu.', NULL, 'Chỉ riêng hôm nay, mọi sản phẩm giảm nửa giá.', 7097, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17841, 'よやくした かたに かぎり、にゅうじょうできます。', 'yoyaku shita kata ni kagiri, nyuujou dekimasu.', NULL, 'Chỉ người đã đặt trước mới được vào.', 7097, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17842, 'いきて いる かぎり、あなたを わすれない。', 'ikite iru kagiri, anata o wasurenai.', NULL, 'Chừng nào còn sống, tôi không quên bạn.', 7098, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17843, 'わたしの しって いる かぎり、かれは しょうじきな ひとだ。', 'watashi no shitte iru kagiri, kare wa shoujiki na hito da.', NULL, 'Theo như tôi biết, anh ấy là người thật thà.', 7098, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17844, 'この もんだいは にほん のみならず、せかいの もんだいだ。', 'kono mondai wa nihon nominarazu, sekai no mondai da.', NULL, 'Vấn đề này không chỉ của Nhật mà của cả thế giới.', 7099, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17845, 'かれは がくせい のみならず、せんせいからも しんらいされて いる。', 'kare wa gakusei nominarazu, sensei kara mo shinrai sarete iru.', NULL, 'Anh ấy được cả học sinh lẫn giáo viên tin tưởng.', 7099, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17846, 'この みせは あじは もちろん、サービスも いい。', 'kono mise wa aji wa mochiron, saabisu mo ii.', NULL, 'Quán này vị thì khỏi nói, phục vụ cũng tốt.', 7100, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17847, 'にちようびは もちろん、へいじつも こんで いる。', 'nichiyoubi wa mochiron, heijitsu mo konde iru.', NULL, 'Chủ nhật thì đương nhiên, ngày thường cũng đông.', 7100, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17848, 'ねだんは ともかく、デザインが きに いらない。', 'nedan wa tomokaku, dezain ga ki ni iranai.', NULL, 'Giá cả thì tạm gác, tôi không thích thiết kế.', 7101, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17849, 'けっかは ともかく、さいごまで がんばった ことが たいせつだ。', 'kekka wa tomokaku, saigo made ganbatta koto ga taisetsu da.', NULL, 'Kết quả thế nào không bàn, cố gắng đến cùng mới quan trọng.', 7101, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17850, 'ねんれいを とわず、だれでも さんかできます。', 'nenrei o towazu, daredemo sanka dekimasu.', NULL, 'Bất kể tuổi tác, ai cũng có thể tham gia.', 7102, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17851, 'この しごとは けいけんの うむを とわない。', 'kono shigoto wa keiken no umu o towanai.', NULL, 'Công việc này không kể có kinh nghiệm hay không.', 7102, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17852, 'てんきに かかわらず、しあいは おこなわれます。', 'tenki ni kakawarazu, shiai wa okonawaremasu.', NULL, 'Bất kể thời tiết, trận đấu vẫn diễn ra.', 7103, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17853, 'さんかする しないに かかわらず、へんじを ください。', 'sanka suru shinai ni kakawarazu, henji o kudasai.', NULL, 'Dù tham gia hay không, xin hãy phản hồi.', 7103, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17854, 'かれは ひとめも かまわず、ないた。', 'kare wa hitome mo kamawazu, naita.', NULL, 'Anh ấy khóc chẳng để ý ánh mắt người khác.', 7104, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17855, 'ふくが ぬれるのも かまわず、あめの なかを はしった。', 'fuku ga nureru no mo kamawazu, ame no naka o hashitta.', NULL, 'Mặc kệ quần áo ướt, tôi chạy trong mưa.', 7104, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17856, 'じょうだんは さておき、ほんだいに はいりましょう。', 'joudan wa sateoki, hondai ni hairimashou.', NULL, 'Đùa thì để sau, vào vấn đề chính thôi.', 7105, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17857, 'ひようの もんだいは さておき、まず けいかくを たてよう。', 'hiyou no mondai wa sateoki, mazu keikaku o tateyou.', NULL, 'Chuyện chi phí để sau, trước hết lập kế hoạch đã.', 7105, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17858, 'さすが プロだけ あって、うまいね。', 'sasuga puro dake atte, umai ne.', NULL, 'Quả là dân chuyên nghiệp, giỏi thật.', 7106, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17859, '10ねん すんで いた だけ あって、この まちに くわしい。', 'juunen sunde ita dake atte, kono machi ni kuwashii.', NULL, 'Đã sống 10 năm nên quả rành thị trấn này.', 7106, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17860, 'やると きめた からには、さいごまで やる。', 'yaru to kimeta kara ni wa, saigo made yaru.', NULL, 'Một khi đã quyết làm thì làm đến cùng.', 7107, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17861, 'やくそくした いじょう、まもらなければ ならない。', 'yakusoku shita ijou, mamoranakereba naranai.', NULL, 'Đã hứa thì phải giữ lời.', 7107, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17862, 'きたいして いた だけに、ざんねんだ。', 'kitai shite ita dake ni, zannen da.', NULL, 'Chính vì đã kỳ vọng nên càng tiếc.', 7108, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17863, 'かんこうちだけに、ひとが おおい。', 'kankouchi dake ni, hito ga ooi.', NULL, 'Vì là điểm du lịch nên càng đông người.', 7108, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17864, 'でんしゃが おくれた ものだから、ちこくして しまいました。', 'densha ga okureta mono da kara, chikoku shite shimaimashita.', NULL, 'Vì tàu trễ nên tôi đến muộn.', 7109, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17865, 'あまりに おいしい ものだから、たべすぎて しまった。', 'amari ni oishii mono da kara, tabesugite shimatta.', NULL, 'Ngon quá nên tôi ăn quá nhiều.', 7109, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17866, 'しんぱいの あまり、ねむれなかった。', 'shinpai no amari, nemurenakatta.', NULL, 'Vì quá lo lắng nên không ngủ được.', 7110, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17867, 'よろこびの あまり、なきだした。', 'yorokobi no amari, nakidashita.', NULL, 'Vui quá nên bật khóc.', 7110, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17868, 'まじめな かれの ことだから、やくそくは まもるだろう。', 'majime na kare no koto da kara, yakusoku wa mamoru darou.', NULL, 'Anh ấy nghiêm túc nên chắc sẽ giữ lời.', 7111, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17869, 'あの ひとの ことだから、また わすれて いるよ。', 'ano hito no koto da kara, mata wasurete iru yo.', NULL, 'Người đó mà, chắc lại quên rồi.', 7111, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17870, 'おかねが ある からと いって、しあわせとは かぎらない。', 'okane ga aru kara to itte, shiawase to wa kagiranai.', NULL, 'Có tiền chưa chắc đã hạnh phúc.', 7112, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17871, 'にほんじんだ からと いって、けいごが じょうずとは かぎらない。', 'nihonjin da kara to itte, keigo ga jouzu to wa kagiranai.', NULL, 'Là người Nhật chưa chắc đã giỏi kính ngữ.', 7112, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17872, 'ねぶそくの せいか、あたまが いたい。', 'nebusoku no sei ka, atama ga itai.', NULL, 'Có lẽ do thiếu ngủ nên đau đầu.', 7113, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17873, 'としの せいか、つかれやすく なった。', 'toshi no sei ka, tsukareyasuku natta.', NULL, 'Có lẽ do tuổi tác nên dễ mệt hơn.', 7113, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17874, 'この はしは かたちが にじに にて いる ことから、にじばしと よばれて いる。', 'kono hashi wa katachi ga niji ni nite iru koto kara, nijibashi to yobarete iru.', NULL, 'Cây cầu có hình giống cầu vồng nên được gọi là cầu Cầu Vồng.', 7114, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17875, 'あしあとが ある ことから、だれかが はいったと わかった。', 'ashiato ga aru koto kara, dareka ga haitta to wakatta.', NULL, 'Từ dấu chân, biết là có người đã vào.', 7114, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17876, 'ひとりで さんにんぶん はたらいて いる わけだから、つかれるのも とうぜんだ。', 'hitori de sanninbun hataraite iru wake da kara, tsukareru no mo touzen da.', NULL, 'Một mình làm việc của ba người thì mệt là đương nhiên.', 7115, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17877, 'もう きめた わけだから、まよう ひつようは ない。', 'mou kimeta wake da kara, mayou hitsuyou wa nai.', NULL, 'Đã quyết rồi thì không cần đắn đo.', 7115, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17878, 'はなしあった けっか、けいかくを へんこうする ことに なった。', 'hanashiatta kekka, keikaku o henkou suru koto ni natta.', NULL, 'Kết quả bàn bạc là đổi kế hoạch.', 7116, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17879, 'ちょうさの けっか、げんいんが わかった。', 'chousa no kekka, gen''in ga wakatta.', NULL, 'Kết quả điều tra đã tìm ra nguyên nhân.', 7116, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17880, 'この りょうでは 10じいこう、おんがくを ひかない ことに なって いる。', 'kono ryou de wa juuji ikou, ongaku o hikanai koto ni natte iru.', NULL, 'Ở ký túc xá này quy định sau 10 giờ không chơi nhạc.', 7117, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17881, 'しゅっきんしたら、タイムカードを おす ことに なって います。', 'shukkin shitara, taimukaado o osu koto ni natte imasu.', NULL, 'Theo quy định, đi làm thì phải bấm thẻ chấm công.', 7117, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17882, 'それは うわさに すぎない。', 'sore wa uwasa ni suginai.', NULL, 'Đó chỉ là tin đồn mà thôi.', 7118, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17883, 'わたしは ただの がくせいに すぎません。', 'watashi wa tada no gakusei ni sugimasen.', NULL, 'Tôi chỉ là một sinh viên bình thường.', 7118, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17884, 'そんな はなし、うそに きまって いる。', 'sonna hanashi, uso ni kimatte iru.', NULL, 'Chuyện như thế chắc chắn là nói dối.', 7119, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17885, 'いまから いっても まにあわないに きまって いる。', 'ima kara itte mo maniawanai ni kimatte iru.', NULL, 'Bây giờ đi thì chắc chắn không kịp.', 7119, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17886, 'かれが はんにんで ある ことに そういない。', 'kare ga hannin de aru koto ni soui nai.', NULL, 'Chắc chắn anh ta là thủ phạm.', 7120, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17887, 'この えは ゆうめいな がかの さくひんに そういない。', 'kono e wa yuumei na gaka no sakuhin ni soui nai.', NULL, 'Bức tranh này hẳn là tác phẩm của họa sĩ nổi tiếng.', 7120, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17888, 'あんな みせ、にどと いく ものか。', 'anna mise, nido to iku mono ka.', NULL, 'Quán như thế, còn lâu tôi mới quay lại.', 7121, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17889, 'まけて たまるもんか。', 'makete tamaru mon ka.', NULL, 'Không đời nào tôi chịu thua.', 7121, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17890, 'そんな むずかしい もんだい、わかりっこない。', 'sonna muzukashii mondai, wakarikkonai.', NULL, 'Bài khó thế sao mà hiểu nổi.', 7122, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17891, 'いまから はしっても、まにあいっこない。', 'ima kara hashitte mo, maniaikkonai.', NULL, 'Giờ chạy cũng không đời nào kịp.', 7122, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17892, 'れんらくさきが わからないので、れんらくの しようが ない。', 'renrakusaki ga wakaranai node, renraku no shiyou ga nai.', NULL, 'Không biết địa chỉ liên lạc nên không có cách nào liên lạc.', 7123, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17893, 'こわれて しまって、なおしようが ない。', 'kowarete shimatte, naoshiyou ga nai.', NULL, 'Hỏng mất rồi, không cách nào sửa được.', 7123, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17894, 'たいふうが くるので、りょこうを ちゅうしせざるを えない。', 'taifuu ga kuru node, ryokou o chuushi sezaru o enai.', NULL, 'Bão đến nên buộc phải hủy chuyến đi.', 7124, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17895, 'しゃちょうの めいれいなら、したがわざるを えない。', 'shachou no meirei nara, shitagawazaru o enai.', NULL, 'Lệnh giám đốc thì buộc phải tuân theo.', 7124, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17896, 'この ままでは じこに なりかねない。', 'kono mama de wa jiko ni narikanenai.', NULL, 'Cứ thế này thì có thể xảy ra tai nạn.', 7125, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17897, 'かれなら そんな ことも いいかねない。', 'kare nara sonna koto mo iikanenai.', NULL, 'Anh ta thì có khi nói ra điều đó lắm.', 7125, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17898, 'その ごようぼうには おこたえ しかねます。', 'sono goyoubou ni wa okotae shikanemasu.', NULL, 'Chúng tôi khó đáp ứng yêu cầu đó.', 7126, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17899, 'かれの いけんには さんせいしかねる。', 'kare no iken ni wa sansei shikaneru.', NULL, 'Tôi khó mà tán thành ý kiến của anh ấy.', 7126, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17900, 'かれが うそを ついたとは しんじがたい。', 'kare ga uso o tsuita to wa shinjigatai.', NULL, 'Khó tin rằng anh ấy đã nói dối.', 7127, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17901, 'この おもいでは わすれがたい。', 'kono omoide wa wasuregatai.', NULL, 'Kỷ niệm này khó mà quên.', 7127, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17902, 'だれにでも ありうる しっぱいだ。', 'dare ni demo ariuru shippai da.', NULL, 'Đó là thất bại ai cũng có thể mắc.', 7128, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17903, 'そんな ことは ありえない。', 'sonna koto wa arienai.', NULL, 'Chuyện đó không thể có.', 7128, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17904, 'せいこうしたのは どりょくの けっかに ほかならない。', 'seikou shita no wa doryoku no kekka ni hoka naranai.', NULL, 'Thành công chính là kết quả của nỗ lực.', 7129, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17905, 'この しっぱいは けいかくの あまさに ほかならない。', 'kono shippai wa keikaku no amasa ni hoka naranai.', NULL, 'Thất bại này không gì khác ngoài kế hoạch sơ sài.', 7129, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17906, 'ながく べんきょうすれば いい と いう ものでは ない。', 'nagaku benkyou sureba ii to iu mono de wa nai.', NULL, 'Không phải cứ học lâu là tốt.', 7130, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17907, 'やすければ うれる と いう ものでは ない。', 'yasukereba ureru to iu mono de wa nai.', NULL, 'Không phải cứ rẻ là bán được.', 7130, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17908, 'くるまの めんきょは ある ものの、ほとんど うんてんしない。', 'kuruma no menkyo wa aru mono no, hotondo unten shinai.', NULL, 'Có bằng lái nhưng tôi hầu như không lái.', 7131, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17909, 'やくそくした ものの、いけるか どうか わからない。', 'yakusoku shita mono no, ikeru ka dou ka wakaranai.', NULL, 'Đã hứa nhưng không biết có đi được không.', 7131, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17910, 'あめに も かかわらず、おおぜいの ひとが あつまった。', 'ame ni mo kakawarazu, oozei no hito ga atsumatta.', NULL, 'Mặc dù mưa, rất nhiều người đã tập trung.', 7132, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17911, 'どりょくしたに も かかわらず、しっぱいした。', 'doryoku shita ni mo kakawarazu, shippai shita.', NULL, 'Dù đã nỗ lực vẫn thất bại.', 7132, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17912, 'わるいと しりつつ、うそを ついて しまった。', 'warui to shiritsutsu, uso o tsuite shimatta.', NULL, 'Biết là sai mà vẫn nói dối.', 7133, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17913, 'けしきを たのしみつつ、さんぽした。', 'keshiki o tanoshimitsutsu, sanpo shita.', NULL, 'Vừa ngắm cảnh vừa đi dạo.', 7133, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17914, 'とかいは べんりな はんめん、ストレスも おおい。', 'tokai wa benri na hanmen, sutoresu mo ooi.', NULL, 'Thành phố tiện lợi, mặt khác cũng nhiều áp lực.', 7134, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17915, 'この くすりは よく きく はんめん、ふくさようも ある。', 'kono kusuri wa yoku kiku hanmen, fukusayou mo aru.', NULL, 'Thuốc này hiệu quả, nhưng cũng có tác dụng phụ.', 7134, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17916, 'しごとを する いっぽうで、だいがくいんにも かよって いる。', 'shigoto o suru ippou de, daigakuin ni mo kayotte iru.', NULL, 'Vừa đi làm, mặt khác vẫn học cao học.', 7135, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17917, 'とかいの じんこうは ふえる いっぽうで、いなかは へって いる。', 'tokai no jinkou wa fueru ippou de, inaka wa hette iru.', NULL, 'Dân số đô thị tăng trong khi nông thôn giảm.', 7135, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17918, 'よそうに はんして、しあいに まけた。', 'yosou ni hanshite, shiai ni maketa.', NULL, 'Trái với dự đoán, chúng tôi thua trận.', 7136, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17919, 'おやの きたいに はんして、かれは だいがくを やめた。', 'oya no kitai ni hanshite, kare wa daigaku o yameta.', NULL, 'Trái với kỳ vọng của bố mẹ, anh ấy bỏ đại học.', 7136, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17920, 'やすむ どころか、ねる じかんも ない。', 'yasumu dokoroka, neru jikan mo nai.', NULL, 'Nói gì đến nghỉ, đến thời gian ngủ cũng không có.', 7137, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17921, 'くすりを のんだが、よく なる どころか わるく なった。', 'kusuri o nonda ga, yoku naru dokoroka waruku natta.', NULL, 'Uống thuốc rồi mà chẳng đỡ, trái lại còn tệ hơn.', 7137, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17923, 'かれは ともだち と いうより かぞくの ような ものだ。', 'kare wa tomodachi to iu yori kazoku no you na mono da.', NULL, 'Anh ấy giống gia đình hơn là bạn bè.', 7138, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17924, 'いまさら あやまった ところで、ゆるして もらえないだろう。', 'imasara ayamatta tokoro de, yurushite moraenai darou.', NULL, 'Bây giờ có xin lỗi thì cũng chẳng được tha thứ.', 7139, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17925, 'いくら いった ところで、かれは きかない。', 'ikura itta tokoro de, kare wa kikanai.', NULL, 'Có nói bao nhiêu thì anh ta cũng không nghe.', 7139, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17926, 'いそがしい にしても、れんらくくらい できたはずだ。', 'isogashii ni shite mo, renraku kurai dekita hazu da.', NULL, 'Dù bận đi nữa thì ít ra cũng liên lạc được.', 7140, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17927, 'いく にしろ いかない にしろ、へんじを して ください。', 'iku ni shiro ikanai ni shiro, henji o shite kudasai.', NULL, 'Đi hay không đi thì cũng hãy trả lời.', 7140, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17928, 'ざんねん ながら、こんかいは みおくる ことに しました。', 'zannen nagara, konkai wa miokuru koto ni shimashita.', NULL, 'Rất tiếc, lần này chúng tôi quyết định không tham gia.', 7141, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17929, 'こども ながら、しっかりした かんがえを もって いる。', 'kodomo nagara, shikkari shita kangae o motte iru.', NULL, 'Tuy là trẻ con nhưng suy nghĩ rất chín chắn.', 7141, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17930, 'この みせは ねだんの わりに おいしい。', 'kono mise wa nedan no wari ni oishii.', NULL, 'Quán này so với giá thì khá ngon.', 7142, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17931, 'かれは としの わりに わかく みえる。', 'kare wa toshi no wari ni wakaku mieru.', NULL, 'So với tuổi, anh ấy trông trẻ.', 7142, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17932, 'あの えいがを みたら、なかずには いられない。', 'ano eiga o mitara, nakazu ni wa irarenai.', NULL, 'Xem bộ phim đó thì không thể không khóc.', 7143, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17933, 'かのじょの ことを しんぱいせずには いられない。', 'kanojo no koto o shinpai sezu ni wa irarenai.', NULL, 'Tôi không thể không lo cho cô ấy.', 7143, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17934, 'のどが かわいて たまらない。', 'nodo ga kawaite tamaranai.', NULL, 'Khát không chịu nổi.', 7144, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17935, 'こきょうの かぞくに あいたくて たまらない。', 'kokyou no kazoku ni aitakute tamaranai.', NULL, 'Nhớ gia đình ở quê vô cùng.', 7144, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17936, 'むすこの ことが しんぱいで ならない。', 'musuko no koto ga shinpai de naranai.', NULL, 'Tôi lo cho con trai không sao chịu được.', 7145, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17937, 'だれかに みられて いる ような きが して ならない。', 'dareka ni mirarete iru you na ki ga shite naranai.', NULL, 'Cứ có cảm giác như bị ai đó nhìn.', 7145, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17938, 'あたまが いたくて しょうがない。', 'atama ga itakute shouganai.', NULL, 'Đau đầu hết sức.', 7146, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17939, 'ひまで しかたが ない。', 'hima de shikata ga nai.', NULL, 'Rảnh rỗi chán không chịu được.', 7146, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17940, 'あなたに あえて、どんなに うれしい ことか。', 'anata ni aete, donna ni ureshii koto ka.', NULL, 'Được gặp bạn tôi vui biết bao!', 7147, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17941, 'なんど ちゅういした ことか。', 'nando chuui shita koto ka.', NULL, 'Đã nhắc nhở bao nhiêu lần rồi!', 7147, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17942, 'つかれた ときは ねるに かぎる。', 'tsukareta toki wa neru ni kagiru.', NULL, 'Khi mệt thì ngủ là nhất.', 7148, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17943, 'なつは つめたい ビールに かぎる。', 'natsu wa tsumetai biiru ni kagiru.', NULL, 'Mùa hè thì bia lạnh là nhất.', 7148, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17944, 'じぶんで やって こそ、ほんとうに わかる。', 'jibun de yatte koso, hontou ni wakaru.', NULL, 'Chỉ khi tự làm mới thật sự hiểu.', 7149, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17945, 'たがいに たすけあって こそ、なかまだ。', 'tagai ni tasukeatte koso, nakama da.', NULL, 'Có giúp đỡ nhau mới là đồng đội.', 7149, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17946, 'いそがしくて、しょくじを する じかん さえ ない。', 'isogashikute, shokuji o suru jikan sae nai.', NULL, 'Bận đến mức ngay cả thời gian ăn cũng không có.', 7150, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17947, 'この かんじは せんせい すら よめなかった。', 'kono kanji wa sensei sura yomenakatta.', NULL, 'Chữ Hán này ngay cả thầy cũng không đọc được.', 7150, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17948, 'かれが けっこんする なんて、しんじられない。', 'kare ga kekkon suru nante, shinjirarenai.', NULL, 'Anh ta mà kết hôn ư, không thể tin nổi.', 7151, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17949, 'べんきょう なんか したくない。', 'benkyou nanka shitakunai.', NULL, 'Học hành gì chứ, chẳng muốn.', 7151, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17950, 'あんな ひとに たのむ くらいなら、じぶんで やる。', 'anna hito ni tanomu kurai nara, jibun de yaru.', NULL, 'Nếu phải nhờ người như thế thì thà tự làm.', 7152, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17951, 'とちゅうで やめる くらいなら、はじめから やらない ほうが いい。', 'tochuu de yameru kurai nara, hajime kara yaranai hou ga ii.', NULL, 'Nếu bỏ giữa chừng thì thà đừng làm từ đầu.', 7152, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17952, 'なんとしても こんどの しけんに ごうかくしたい。', 'nan to shite mo kondo no shiken ni goukaku shitai.', NULL, 'Bằng mọi giá tôi muốn đỗ kỳ thi lần này.', 7153, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17953, 'ぜひ いちど おあいしたいです。', 'zehi ichido oai shitai desu.', NULL, 'Nhất định tôi muốn gặp anh một lần.', 7153, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17954, 'この さくぶんは まちがい だらけだ。', 'kono sakubun wa machigai darake da.', NULL, 'Bài văn này toàn là lỗi.', 7154, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17955, 'どろ だらけの くつで はいらないで。', 'doro darake no kutsu de hairanaide.', NULL, 'Đừng đi giày lấm bùn vào.', 7154, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17956, 'ことしは いい こと ずくめだった。', 'kotoshi wa ii koto zukume datta.', NULL, 'Năm nay toàn chuyện tốt đẹp.', 7155, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17957, 'かのじょは くろ ずくめの ふくを きて いた。', 'kanojo wa kuro zukume no fuku o kite ita.', NULL, 'Cô ấy mặc toàn đồ đen.', 7155, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17958, 'かのじょは さびし げに わらった。', 'kanojo wa sabishi ge ni waratta.', NULL, 'Cô ấy cười có vẻ buồn.', 7156, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17959, 'こどもたちは たのし げに あそんで いる。', 'kodomotachi wa tanoshi ge ni asonde iru.', NULL, 'Bọn trẻ đang chơi có vẻ vui.', 7156, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17960, 'この コースは しょしんしゃ むきです。', 'kono koosu wa shoshinsha muki desu.', NULL, 'Khóa này phù hợp người mới.', 7157, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17961, 'これは こども むけの ばんぐみだ。', 'kore wa kodomo muke no bangumi da.', NULL, 'Đây là chương trình dành cho trẻ em.', 7157, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17962, 'せいこうするか どうかは どりょく しだいだ。', 'seikou suru ka dou ka wa doryoku shidai da.', NULL, 'Thành công hay không tùy vào nỗ lực.', 7158, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17963, 'てんき しだいで、よていを かえる。', 'tenki shidai de, yotei o kaeru.', NULL, 'Tùy thời tiết mà đổi kế hoạch.', 7158, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17964, 'じんこうの ぞうかに ともなって、じゅうたくが ふそくした。', 'jinkou no zouka ni tomonatte, juutaku ga fusoku shita.', NULL, 'Cùng với dân số tăng, nhà ở trở nên thiếu.', 7159, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17965, 'ぎじゅつの しんぽに ともない、せいかつが かわった。', 'gijutsu no shinpo ni tomonai, seikatsu ga kawatta.', NULL, 'Kéo theo tiến bộ kỹ thuật, cuộc sống thay đổi.', 7159, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17966, 'ごみの りょうは ふえる いっぽうだ。', 'gomi no ryou wa fueru ippou da.', NULL, 'Lượng rác cứ ngày càng tăng.', 7160, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17967, 'かれとの きょりは ひらく いっぽうだった。', 'kare to no kyori wa hiraku ippou datta.', NULL, 'Khoảng cách với anh ấy ngày càng xa.', 7160, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17968, 'あさごはん ぬきで かいしゃに いった。', 'asagohan nuki de kaisha ni itta.', NULL, 'Tôi đi làm mà không ăn sáng.', 7161, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17969, 'じょうだんは ぬきに して、まじめに はなそう。', 'joudan wa nuki ni shite, majime ni hanasou.', NULL, 'Bỏ đùa sang bên, nói chuyện nghiêm túc nào.', 7161, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17970, 'この ドアは ひとが ちかづくと あく ように なって いる。', 'kono doa wa hito ga chikazuku to aku you ni natte iru.', NULL, 'Cửa này được thiết kế để mở khi có người lại gần.', 7162, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17971, 'ボタンを おすと、おゆが でる ように なって います。', 'botan o osu to, oyu ga deru you ni natte imasu.', NULL, 'Bấm nút là nước nóng chảy ra.', 7162, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17972, 'にもつは まとめて、あとは でかける ばかりに なって いる。', 'nimotsu wa matomete, ato wa dekakeru bakari ni natte iru.', NULL, 'Hành lý đã gói xong, chỉ còn chờ đi.', 7163, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17973, 'りょうりは あとは たべる ばかりだ。', 'ryouri wa ato wa taberu bakari da.', NULL, 'Món ăn giờ chỉ còn ăn thôi.', 7163, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17974, 'かれは やすむ ことなく はたらきつづけた。', 'kare wa yasumu koto naku hatarakitsuzuketa.', NULL, 'Anh ấy làm việc liên tục không hề nghỉ.', 7164, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17975, 'あきらめる ことなく、さいごまで がんばった。', 'akirameru koto naku, saigo made ganbatta.', NULL, 'Không hề bỏ cuộc, cố gắng đến cùng.', 7164, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17976, 'あしが いたくて、あるけない ほどだ。', 'ashi ga itakute, arukenai hodo da.', NULL, 'Chân đau đến mức không đi được.', 7165, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17977, 'この せつめいは こどもでも わかる ほど かんたんだ。', 'kono setsumei wa kodomo demo wakaru hodo kantan da.', NULL, 'Lời giải thích đơn giản đến mức trẻ con cũng hiểu.', 7165, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17978, 'ベルが なるや いなや、がくせいたちは きょうしつを とびだした。', 'beru ga naru ya ina ya, gakuseitachi wa kyoushitsu o tobidashita.', NULL, 'Chuông vừa reo, học sinh đã lao ra khỏi lớp.', 7166, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17979, 'かれは いえに つくや、ベッドに たおれこんだ。', 'kare wa ie ni tsuku ya, beddo ni taorekonda.', NULL, 'Vừa về đến nhà, anh ấy đã đổ vật xuống giường.', 7166, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17980, 'こどもは かばんを おくが はやいか、あそびに でかけた。', 'kodomo wa kaban o oku ga hayai ka, asobi ni dekaketa.', NULL, 'Đứa trẻ vừa đặt cặp xuống là đã đi chơi.', 7167, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17981, 'しょうひんが ならぶが はやいか、うりきれた。', 'shouhin ga narabu ga hayai ka, urikireta.', NULL, 'Hàng vừa bày ra đã bán hết.', 7167, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17982, 'かのじょは わたしの かおを みるなり、なきだした。', 'kanojo wa watashi no kao o miru nari, nakidashita.', NULL, 'Cô ấy vừa nhìn thấy mặt tôi liền bật khóc.', 7168, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17983, 'ちちは でんわを きるなり、でかけて いった。', 'chichi wa denwa o kiru nari, dekakete itta.', NULL, 'Bố vừa cúp máy là đi ra ngoài ngay.', 7168, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17984, 'かたづける そばから、こどもが ちらかす。', 'katazukeru soba kara, kodomo ga chirakasu.', NULL, 'Vừa dọn xong là bọn trẻ lại bày bừa.', 7169, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17985, 'ならった そばから わすれて しまう。', 'naratta soba kara wasurete shimau.', NULL, 'Vừa học xong đã quên ngay.', 7169, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16680, 'この えは ピカソに よって かかれました。', 'kono e wa pikaso ni yotte kakaremashita.', NULL, 'Bức tranh này được vẽ bởi Picasso.', 6517, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17986, 'とうきょうこうえんを かわきりに、ぜんこくツアーが はじまった。', 'toukyou kouen o kawakiri ni, zenkoku tsuaa ga hajimatta.', NULL, 'Khởi đầu bằng buổi diễn ở Tokyo, tour toàn quốc bắt đầu.', 7170, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17987, 'かれの はつげんを かわきりに、つぎつぎと いけんが でた。', 'kare no hatsugen o kawakiri ni, tsugitsugi to iken ga deta.', NULL, 'Bắt đầu từ phát biểu của anh ấy, ý kiến liên tục được đưa ra.', 7170, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17988, 'しにんが でるに いたって、やっと たいさくが とられた。', 'shinin ga deru ni itatte, yatto taisaku ga torareta.', NULL, 'Đến khi có người chết thì mới có biện pháp.', 7171, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17989, 'じたいが ここに いたっては、もう どうしようも ない。', 'jitai ga koko ni itatte wa, mou doushiyou mo nai.', NULL, 'Sự việc đến nước này thì không còn cách nào.', 7171, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17990, 'こんげつを かぎりに、この みせは へいてんします。', 'kongetsu o kagiri ni, kono mise wa heiten shimasu.', NULL, 'Hết tháng này, cửa hàng sẽ đóng cửa.', 7172, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17991, 'きょうを かぎりに タバコを やめる。', 'kyou o kagiri ni tabako o yameru.', NULL, 'Từ hôm nay tôi bỏ thuốc lá.', 7172, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17992, 'うまれて このかた、びょうきを した ことが ない。', 'umarete kono kata, byouki o shita koto ga nai.', NULL, 'Từ khi sinh ra đến nay chưa từng ốm.', 7173, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17993, 'にほんに きて このかた、いちども かえって いない。', 'nihon ni kite kono kata, ichido mo kaette inai.', NULL, 'Từ khi sang Nhật đến nay chưa về lần nào.', 7173, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17994, 'こんなんな じょうきょうに あって、かれは おちついて いた。', 'konnan na joukyou ni atte, kare wa ochitsuite ita.', NULL, 'Trong hoàn cảnh khó khăn, anh ấy vẫn bình tĩnh.', 7174, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17995, 'じょうほうかしゃかいに あって、プライバシーの ほごは じゅうようだ。', 'jouhouka shakai ni atte, puraibashii no hogo wa juuyou da.', NULL, 'Trong xã hội thông tin, bảo vệ quyền riêng tư là quan trọng.', 7174, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17996, 'こんど おあいした おりに、くわしく おはなしします。', 'kondo oai shita ori ni, kuwashiku ohanashi shimasu.', NULL, 'Dịp gặp lần tới tôi sẽ nói chi tiết.', 7175, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17997, 'おちかくに おこしの おりは、ぜひ おたちよりください。', 'ochikaku ni okoshi no ori wa, zehi otachiyori kudasai.', NULL, 'Khi đến gần đây, xin hãy ghé chơi.', 7175, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17998, 'おいそがしい ところを、ありがとうございます。', 'oisogashii tokoro o, arigatou gozaimasu.', NULL, 'Cảm ơn anh đã dành thời gian dù đang bận.', 7176, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (17999, 'おやすみの ところを おじゃまして すみません。', 'oyasumi no tokoro o ojama shite sumimasen.', NULL, 'Xin lỗi đã làm phiền lúc anh đang nghỉ.', 7176, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18000, 'この しごとを まかせられるのは、かれを おいて ほかに いない。', 'kono shigoto o makaserareru no wa, kare o oite hoka ni inai.', NULL, 'Ngoài anh ấy ra không ai được giao việc này.', 7177, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18001, 'リーダーは かのじょを おいて ほかに かんがえられない。', 'riidaa wa kanojo o oite hoka ni kangaerarenai.', NULL, 'Ngoài cô ấy không thể nghĩ ra ai làm trưởng nhóm.', 7177, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18002, 'これは この ちほう ならではの あじだ。', 'kore wa kono chihou nara de wa no aji da.', NULL, 'Đây là hương vị chỉ vùng này mới có.', 7178, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18003, 'こども ならではの はっそうに おどろいた。', 'kodomo nara de wa no hassou ni odoroita.', NULL, 'Tôi bất ngờ với ý tưởng chỉ trẻ con mới có.', 7178, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18004, 'この びょうきは おとな に とどまらず、こどもにも ひろがって いる。', 'kono byouki wa otona ni todomarazu, kodomo ni mo hirogatte iru.', NULL, 'Căn bệnh không chỉ ở người lớn mà lan sang cả trẻ em.', 7179, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18041, 'あめ であれ ゆき であれ、しゅっぱつする。', 'ame de are yuki de are, shuppatsu suru.', NULL, 'Dù mưa hay tuyết cũng xuất phát.', 7197, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18005, 'かれの かつどうは こくない に とどまらず、かいがいにも およぶ。', 'kare no katsudou wa kokunai ni todomarazu, kaigai ni mo oyobu.', NULL, 'Hoạt động của anh ấy không chỉ trong nước mà cả nước ngoài.', 7179, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18006, 'ほんじつを もって、うけつけを しゅうりょうします。', 'honjitsu o motte, uketsuke o shuuryou shimasu.', NULL, 'Kể từ hôm nay chúng tôi ngừng tiếp nhận.', 7180, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18007, 'しけんの けっかは しょめんを もって おしらせします。', 'shiken no kekka wa shomen o motte oshirase shimasu.', NULL, 'Kết quả thi sẽ được thông báo bằng văn bản.', 7180, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18008, 'じじつに そくして はなして ください。', 'jijitsu ni sokushite hanashite kudasai.', NULL, 'Hãy nói bám sát sự thật.', 7181, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18009, 'げんばの じょうきょうに そくした たいさくが ひつようだ。', 'genba no joukyou ni sokushita taisaku ga hitsuyou da.', NULL, 'Cần biện pháp phù hợp với tình hình thực tế.', 7181, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18010, 'これは いのちに かかわる もんだいだ。', 'kore wa inochi ni kakawaru mondai da.', NULL, 'Đây là vấn đề liên quan đến tính mạng.', 7182, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18011, 'かいしゃの しんようにも かかわる ことだ。', 'kaisha no shin''you ni mo kakawaru koto da.', NULL, 'Việc này ảnh hưởng cả uy tín công ty.', 7182, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18012, 'にちようびを のぞいて、まいにち えいぎょうして います。', 'nichiyoubi o nozoite, mainichi eigyou shite imasu.', NULL, 'Mở cửa hằng ngày trừ Chủ nhật.', 7183, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18013, 'いちぶを のぞいて、ほとんど さんせいした。', 'ichibu o nozoite, hotondo sansei shita.', NULL, 'Trừ một số ít, hầu hết đều tán thành.', 7183, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18014, 'みなさんの きょうりょく なくして、せいこうは ありえません。', 'minasan no kyouryoku nakushite, seikou wa ariemasen.', NULL, 'Không có sự hợp tác của mọi người thì không thể thành công.', 7184, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18015, 'ことわり なしに へやに はいらないで。', 'kotowari nashi ni heya ni hairanaide.', NULL, 'Đừng vào phòng mà không xin phép.', 7184, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18016, 'いっしゅん たりとも ゆだんできない。', 'isshun taritomo yudan dekinai.', NULL, 'Không thể lơ là dù chỉ một khoảnh khắc.', 7185, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18017, 'いちえん たりとも むだに しない。', 'ichien taritomo muda ni shinai.', NULL, 'Không lãng phí dù chỉ một yên.', 7185, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18018, 'だいがくせい とも なると、じぶんで かんがえて こうどうすべきだ。', 'daigakusei tomo naru to, jibun de kangaete koudou subeki da.', NULL, 'Đã là sinh viên thì nên tự suy nghĩ mà hành động.', 7186, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18019, 'しゃちょう とも なれば、いそがしいのも とうぜんだ。', 'shachou tomo nareba, isogashii no mo touzen da.', NULL, 'Đã là giám đốc thì bận là đương nhiên.', 7186, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18020, 'こどもの ため とあれば、どんな くろうも いとわない。', 'kodomo no tame to areba, donna kurou mo itowanai.', NULL, 'Nếu vì con thì vất vả thế nào cũng không ngại.', 7187, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18021, 'しゃちょうの めいれい とあれば、しかたが ない。', 'shachou no meirei to areba, shikata ga nai.', NULL, 'Nếu là lệnh giám đốc thì đành chịu.', 7187, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18022, 'ちちに くちごたえ しようものなら、たいへんな ことに なる。', 'chichi ni kuchigotae shiyou mono nara, taihen na koto ni naru.', NULL, 'Nếu lỡ cãi lại bố thì to chuyện.', 7188, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18023, 'しめきりに おくれようものなら、しごとを うしなう。', 'shimekiri ni okureyou mono nara, shigoto o ushinau.', NULL, 'Nếu lỡ trễ hạn thì mất việc.', 7188, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18024, 'まいにち とは いわないまでも、しゅうに いちどは れんらくして。', 'mainichi to wa iwanai made mo, shuu ni ichido wa renraku shite.', NULL, 'Không đến mức mỗi ngày thì ít nhất tuần một lần hãy liên lạc.', 7189, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18025, 'ゆうしょう できないまでも、いい しあいを したい。', 'yuushou dekinai made mo, ii shiai o shitai.', NULL, 'Dù không vô địch thì ít nhất muốn đấu hay.', 7189, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18026, 'こども ならいざしらず、おとなが そんな ことを するとは。', 'kodomo nara iza shirazu, otona ga sonna koto o suru to wa.', NULL, 'Trẻ con thì đành, đằng này người lớn lại làm thế.', 7190, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18027, 'しらなかった ならいざしらず、しって いて やったのは ゆるせない。', 'shiranakatta nara iza shirazu, shitte ite yatta no wa yurusenai.', NULL, 'Không biết thì còn được, biết mà vẫn làm thì không thể tha.', 7190, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18028, 'かれは ねむったら さいご、なにが あっても おきない。', 'kare wa nemuttara saigo, nani ga atte mo okinai.', NULL, 'Anh ấy một khi đã ngủ thì có chuyện gì cũng không dậy.', 7191, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18029, 'この ばしょを しられたが さいご、にげられない。', 'kono basho o shirareta ga saigo, nigerarenai.', NULL, 'Một khi bị biết chỗ này thì không trốn được.', 7191, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18030, 'かんがえ ように よっては、しっぱいも いい けいけんだ。', 'kangae you ni yotte wa, shippai mo ii keiken da.', NULL, 'Tùy cách nghĩ, thất bại cũng là kinh nghiệm tốt.', 7192, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18031, 'この ことばは とり ように よっては しつれいに きこえる。', 'kono kotoba wa tori you ni yotte wa shitsurei ni kikoeru.', NULL, 'Tùy cách hiểu, câu này nghe có vẻ vô lễ.', 7192, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18034, 'かれの はなしが ほんとう と すれば、けいかくを みなおす ひつようが ある。', 'kare no hanashi ga hontou to sureba, keikaku o minaosu hitsuyou ga aru.', NULL, 'Nếu lời anh ấy là thật thì cần xem lại kế hoạch.', 7194, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18035, 'いま しゅっぱつする と すれば、ゆうがたには つく。', 'ima shuppatsu suru to sureba, yuugata ni wa tsuku.', NULL, 'Nếu xuất phát bây giờ thì chiều tối sẽ đến.', 7194, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18036, 'せんもんか と いえども、まちがえる ことは ある。', 'senmonka to iedomo, machigaeru koto wa aru.', NULL, 'Dù là chuyên gia cũng có lúc sai.', 7195, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18037, 'こども と いえども、ルールは まもるべきだ。', 'kodomo to iedomo, ruuru wa mamoru beki da.', NULL, 'Dù là trẻ con cũng phải giữ luật.', 7195, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18038, 'はる とは いえ、まだ さむい ひが つづく。', 'haru to wa ie, mada samui hi ga tsuzuku.', NULL, 'Tuy nói là xuân nhưng vẫn còn những ngày lạnh.', 7196, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18039, 'しごと とは いえ、かぞくと はなれるのは つらい。', 'shigoto to wa ie, kazoku to hanareru no wa tsurai.', NULL, 'Tuy là vì công việc nhưng xa gia đình thật khổ.', 7196, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18040, 'どんな りゆう であれ、ぼうりょくは ゆるされない。', 'donna riyuu de are, bouryoku wa yurusarenai.', NULL, 'Dù lý do gì, bạo lực không được chấp nhận.', 7197, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18042, 'さんせい にせよ はんたい にせよ、いけんを のべて ください。', 'sansei ni seyo hantai ni seyo, iken o nobete kudasai.', NULL, 'Tán thành hay phản đối, xin hãy nêu ý kiến.', 7198, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18043, 'いずれ にせよ、れんらくします。', 'izure ni seyo, renraku shimasu.', NULL, 'Dù sao đi nữa tôi cũng sẽ liên lạc.', 7198, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18044, 'いって くれれば てつだった ものを。', 'itte kurereba tetsudatta mono o.', NULL, 'Giá mà nói với tôi thì tôi đã giúp rồi.', 7199, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18045, 'はやく びょういんに いけば よかった ものを。', 'hayaku byouin ni ikeba yokatta mono o.', NULL, 'Giá mà đi viện sớm thì tốt rồi.', 7199, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18046, 'はれる と おもいきや、ごごから あめに なった。', 'hareru to omoikiya, gogo kara ame ni natta.', NULL, 'Cứ tưởng trời nắng, hóa ra chiều lại mưa.', 7200, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18047, 'かんたんな しけん と おもいきや、むずかしかった。', 'kantan na shiken to omoikiya, muzukashikatta.', NULL, 'Tưởng đề dễ, hóa ra lại khó.', 7200, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18048, 'インターネットで いえに いながらにして かいものが できる。', 'intaanetto de ie ni inagara ni shite kaimono ga dekiru.', NULL, 'Nhờ Internet có thể mua sắm ngay tại nhà.', 7201, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18049, 'かのじょは なみだ ながらに じじょうを はなした。', 'kanojo wa namida nagara ni jijou o hanashita.', NULL, 'Cô ấy vừa rơi nước mắt vừa kể sự tình.', 7201, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18050, 'こども ではあるまいし、じぶんで かんがえなさい。', 'kodomo de wa arumai shi, jibun de kangaenasai.', NULL, 'Có phải trẻ con đâu, tự suy nghĩ đi.', 7202, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18051, 'えいえんに わかれる わけ ではあるまいし、なかないで。', 'eien ni wakareru wake de wa arumai shi, nakanaide.', NULL, 'Có phải chia tay mãi mãi đâu, đừng khóc.', 7202, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18052, 'いくら ねがった とて、むりな ものは むりだ。', 'ikura negatta tote, muri na mono wa muri da.', NULL, 'Dù có mong mỏi bao nhiêu, không thể vẫn là không thể.', 7203, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18053, 'わたし とて、かなしくない わけでは ない。', 'watashi tote, kanashikunai wake de wa nai.', NULL, 'Ngay cả tôi cũng đâu phải không buồn.', 7203, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18054, 'かれの たいどは しつれい きわまりない。', 'kare no taido wa shitsurei kiwamarinai.', NULL, 'Thái độ của anh ta cực kỳ vô lễ.', 7204, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18055, 'この どうろは きけん きわまる。', 'kono douro wa kiken kiwamaru.', NULL, 'Con đường này cực kỳ nguy hiểm.', 7204, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18056, 'この ような しょうを いただき、こうえいの きわみです。', 'kono you na shou o itadaki, kouei no kiwami desu.', NULL, 'Được nhận giải thưởng này là vinh dự tột bậc.', 7205, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18057, 'あの しっぱいは ひあいの きわみだった。', 'ano shippai wa hiai no kiwami datta.', NULL, 'Thất bại đó là nỗi đau tột cùng.', 7205, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18058, 'おほめの ことばを いただき、こうえいの いたりです。', 'ohome no kotoba o itadaki, kouei no itari desu.', NULL, 'Được khen ngợi, tôi vô cùng vinh dự.', 7206, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18059, 'わかげの いたりで、ばかな ことを した。', 'wakage no itari de, baka na koto o shita.', NULL, 'Vì bồng bột tuổi trẻ nên đã làm điều ngốc nghếch.', 7206, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18060, 'いう までも なく、けんこうが いちばん たいせつだ。', 'iu made mo naku, kenkou ga ichiban taisetsu da.', NULL, 'Khỏi phải nói, sức khỏe là quan trọng nhất.', 7207, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18061, 'この ていどの けがなら、びょういんに いく までも ない。', 'kono teido no kega nara, byouin ni iku made mo nai.', NULL, 'Vết thương cỡ này thì không cần đến viện.', 7207, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18062, 'かぞくの かなしみは そうぞうに かたくない。', 'kazoku no kanashimi wa souzou ni katakunai.', NULL, 'Nỗi đau của gia đình không khó để tưởng tượng.', 7208, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18063, 'かれの くろうは さっするに かたくない。', 'kare no kurou wa sassuru ni katakunai.', NULL, 'Không khó để hình dung nỗi vất vả của anh ấy.', 7208, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18064, 'その ばんぐみは みるに たえない。', 'sono bangumi wa miru ni taenai.', NULL, 'Chương trình đó không đáng để xem.', 7209, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18065, 'この さくひんは おとなの かんしょうにも たえる。', 'kono sakuhin wa otona no kanshou ni mo taeru.', NULL, 'Tác phẩm này đáng để người lớn thưởng thức.', 7209, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18066, 'かれは しんらいするに たる ひとだ。', 'kare wa shinrai suru ni taru hito da.', NULL, 'Anh ấy là người đáng tin cậy.', 7210, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18067, 'はなすに たりない ことだ。', 'hanasu ni tarinai koto da.', NULL, 'Chuyện không đáng để nói.', 7210, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18068, 'みなさまの ごけんこうを ねがって やみません。', 'minasama no gokenkou o negatte yamimasen.', NULL, 'Luôn cầu chúc mọi người mạnh khỏe.', 7211, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18069, 'かれの せいこうを いのって やまない。', 'kare no seikou o inotte yamanai.', NULL, 'Tôi luôn cầu mong anh ấy thành công.', 7211, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18070, 'あの ときの はずかしさ と いったら なかった。', 'ano toki no hazukashisa to ittara nakatta.', NULL, 'Lúc đó xấu hổ không kể xiết.', 7212, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18071, 'やまの うえからの けしきの うつくしさ と いったら ない。', 'yama no ue kara no keshiki no utsukushisa to ittara nai.', NULL, 'Cảnh từ trên núi đẹp không tả nổi.', 7212, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18072, 'じしんの ことは かんがえる だに おそろしい。', 'jishin no koto wa kangaeru dani osoroshii.', NULL, 'Chỉ nghĩ đến động đất thôi đã sợ.', 7213, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18073, 'ゆめに だに おもわなかった。', 'yume ni dani omowanakatta.', NULL, 'Ngay cả trong mơ cũng không nghĩ tới.', 7213, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18074, 'じこに あったが、けがを しなかった だけ ましだ。', 'jiko ni atta ga, kega o shinakatta dake mashi da.', NULL, 'Bị tai nạn nhưng còn may là không bị thương.', 7214, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18075, 'きゅうりょうは やすいが、しごとが ある だけ ましだ。', 'kyuuryou wa yasui ga, shigoto ga aru dake mashi da.', NULL, 'Lương thấp nhưng còn may là có việc.', 7214, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18076, 'しばふに たちいる べからず。', 'shibafu ni tachiiru bekarazu.', NULL, 'Cấm giẫm lên cỏ.', 7215, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18077, 'それは けっして ゆるす べからざる こういだ。', 'sore wa kesshite yurusu bekarazaru koui da.', NULL, 'Đó là hành vi tuyệt đối không thể tha thứ.', 7215, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18078, 'きょうし に あるまじき こういだ。', 'kyoushi ni aru majiki koui da.', NULL, 'Đó là hành vi không thể có ở một giáo viên.', 7216, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18079, 'ひととして ゆるす まじき ことだ。', 'hito to shite yurusu majiki koto da.', NULL, 'Là con người thì không thể tha thứ việc đó.', 7216, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18080, 'だめなら、もう いちど やる までだ。', 'dame nara, mou ichido yaru made da.', NULL, 'Không được thì làm lại lần nữa thôi.', 7217, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18081, 'ほんとうの ことを いった までのことだ。', 'hontou no koto o itta made no koto da.', NULL, 'Tôi chỉ nói sự thật mà thôi.', 7217, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18426, 'だんだん はるめいて きた。', 'dandan harumeite kita.', NULL, 'Trời dần mang dáng vẻ mùa xuân.', 7390, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18082, 'いくら ちょきんしても、しんで しまえば それまでだ。', 'ikura chokin shite mo, shinde shimaeba sore made da.', NULL, 'Tiết kiệm bao nhiêu thì chết rồi cũng hết.', 7218, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18083, 'どんなに いい けいかくでも、じっこうしなければ それまでだ。', 'donna ni ii keikaku demo, jikkou shinakereba sore made da.', NULL, 'Kế hoạch hay mấy mà không thực hiện thì cũng vô ích.', 7218, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18084, 'ひさいしゃの はなしに なみだを きんじえない。', 'hisaisha no hanashi ni namida o kinjienai.', NULL, 'Nghe chuyện nạn nhân không cầm được nước mắt.', 7219, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18085, 'この けっていには いきどおりを きんじえない。', 'kono kettei ni wa ikidoori o kinjienai.', NULL, 'Không kìm được phẫn nộ trước quyết định này.', 7219, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18086, 'かれの えんぜつは ひとびとを かんどうさせずには おかない。', 'kare no enzetsu wa hitobito o kandou sasezu ni wa okanai.', NULL, 'Bài diễn văn của anh ấy chắc chắn làm mọi người cảm động.', 7220, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18087, 'はんにんを つかまえずには おかない。', 'hannin o tsukamaezu ni wa okanai.', NULL, 'Nhất định phải bắt được thủ phạm.', 7220, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18088, 'ひとに めいわくを かけたのだから、あやまらずには すまない。', 'hito ni meiwaku o kaketa no da kara, ayamarazu ni wa sumanai.', NULL, 'Đã làm phiền người khác thì không thể không xin lỗi.', 7221, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18089, 'この ままでは せきにんを とらないでは すまない。', 'kono mama de wa sekinin o toranai de wa sumanai.', NULL, 'Cứ thế này thì không thể không chịu trách nhiệm.', 7221, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18090, 'この ていどの ことで おどろくには あたらない。', 'kono teido no koto de odoroku ni wa ataranai.', NULL, 'Chuyện cỡ này không đáng để ngạc nhiên.', 7222, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18091, 'かれを せめるには あたらない。', 'kare o semeru ni wa ataranai.', NULL, 'Không đáng để trách anh ấy.', 7222, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18092, 'おかねは ある に こした ことは ない。', 'okane wa aru ni koshita koto wa nai.', NULL, 'Có tiền thì vẫn là tốt nhất.', 7223, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18093, 'ようじんする に こした ことは ない。', 'youjin suru ni koshita koto wa nai.', NULL, 'Cẩn thận vẫn là hơn.', 7223, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18094, 'かれは ものごとを おおげさに いう きらいが ある。', 'kare wa monogoto o oogesa ni iu kirai ga aru.', NULL, 'Anh ta có tật hay nói phóng đại.', 7224, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18095, 'さいきんの わかものは けいたいに たよる きらいが ある。', 'saikin no wakamono wa keitai ni tayoru kirai ga aru.', NULL, 'Giới trẻ gần đây có xu hướng phụ thuộc điện thoại.', 7224, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18096, 'かれは なまけて ばかりで、ついには かいしゃを くびに なる しまつだ。', 'kare wa namakete bakari de, tsui ni wa kaisha o kubi ni naru shimatsu da.', NULL, 'Anh ta lười mãi, rốt cuộc bị đuổi việc.', 7225, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18097, 'ちゅういしても きかず、けがを する しまつだ。', 'chuui shite mo kikazu, kega o suru shimatsu da.', NULL, 'Nhắc mà không nghe, cuối cùng bị thương.', 7225, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18098, 'しけんに ごうかくす べく、まいにち べんきょうして いる。', 'shiken ni goukaku su beku, mainichi benkyou shite iru.', NULL, 'Để đỗ kỳ thi, tôi học mỗi ngày.', 7226, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18099, 'もんだいを かいけつす べく、かいぎが ひらかれた。', 'mondai o kaiketsu su beku, kaigi ga hirakareta.', NULL, 'Cuộc họp được mở để giải quyết vấn đề.', 7226, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18100, 'こどもたちは どろ まみれに なって あそんだ。', 'kodomotachi wa doro mamire ni natte asonda.', NULL, 'Bọn trẻ chơi lấm lem bùn đất.', 7227, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18101, 'あせ まみれで はたらいた。', 'ase mamire de hataraita.', NULL, 'Làm việc mồ hôi nhễ nhại.', 7227, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18102, 'だんだん はるめいて きた。', 'dandan harumeite kita.', NULL, 'Trời dần mang dáng vẻ mùa xuân.', 7228, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18103, 'かれは ひにくめいた ことを いった。', 'kare wa hinikumeita koto o itta.', NULL, 'Anh ấy nói điều nghe có vẻ mỉa mai.', 7228, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18104, 'かのじょは いつも じょうひんぶって いる。', 'kanojo wa itsumo jouhinbutte iru.', NULL, 'Cô ấy lúc nào cũng làm ra vẻ thanh lịch.', 7229, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18105, 'えらぶる ひとは きらわれる。', 'eraburu hito wa kirawareru.', NULL, 'Người ra vẻ ta đây bị ghét.', 7229, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18106, 'かれは もう かえれ と ばかりに、ドアを あけた。', 'kare wa mou kaere to bakari ni, doa o aketa.', NULL, 'Anh ta mở cửa như muốn bảo "về đi".', 7230, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18107, 'いまが チャンス と ばかりに、みんなが かいに はしった。', 'ima ga chansu to bakari ni, minna ga kai ni hashitta.', NULL, 'Mọi người lao đi mua như thể "cơ hội là đây".', 7230, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18108, 'かのじょは なきださん ばかりの かおを して いた。', 'kanojo wa nakidasan bakari no kao o shite ita.', NULL, 'Cô ấy có vẻ mặt như sắp khóc.', 7231, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18109, 'われん ばかりの はくしゅが おこった。', 'waren bakari no hakushu ga okotta.', NULL, 'Tiếng vỗ tay vang dội như muốn vỡ tung.', 7231, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18110, 'みる とも なく テレビを みて いた。', 'miru tomo naku terebi o mite ita.', NULL, 'Tôi nhìn tivi một cách vô định.', 7232, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18111, 'どこから とも なく おんがくが きこえて きた。', 'doko kara tomo naku ongaku ga kikoete kita.', NULL, 'Không biết từ đâu vọng lại tiếng nhạc.', 7232, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18112, 'おれい かたがた、ごあいさつに うかがいました。', 'orei katagata, goaisatsu ni ukagaimashita.', NULL, 'Tôi đến chào hỏi, nhân tiện cảm ơn.', 7233, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18113, 'さんぽ かたがた、ほんやに よった。', 'sanpo katagata, hon''ya ni yotta.', NULL, 'Nhân tiện đi dạo, tôi ghé hiệu sách.', 7233, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18114, 'かいもの がてら、こうえんを さんぽした。', 'kaimono gatera, kouen o sanpo shita.', NULL, 'Tiện đi mua sắm, tôi đi dạo công viên.', 7234, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18115, 'えきまで おくり がてら、はなしを した。', 'eki made okuri gatera, hanashi o shita.', NULL, 'Tiện tiễn ra ga, tôi nói chuyện với anh ấy.', 7234, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18116, 'いそがしくて、けっきょく かのじょに あわず じまいだった。', 'isogashikute, kekkyoku kanojo ni awazu jimai datta.', NULL, 'Bận quá rốt cuộc đã không gặp được cô ấy.', 7235, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18117, 'かった ほんを よまず じまいで すてた。', 'katta hon o yomazu jimai de suteta.', NULL, 'Sách đã mua rốt cuộc không đọc mà vứt đi.', 7235, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18118, 'ふたりは おいつ おわれつ の レースを した。', 'futari wa oitsu owaretsu no reesu o shita.', NULL, 'Hai người đua nhau lúc đuổi lúc bị đuổi.', 7236, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18119, 'ゆきつ もどりつ しながら かんがえた。', 'yukitsu modoritsu shinagara kangaeta.', NULL, 'Đi tới đi lui mà suy nghĩ.', 7236, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18120, 'わたし なりに いっしょうけんめい がんばった。', 'watashi nari ni isshoukenmei ganbatta.', NULL, 'Tôi đã cố gắng hết sức theo cách của mình.', 7237, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18121, 'こども なりに かんがえた けっかだ。', 'kodomo nari ni kangaeta kekka da.', NULL, 'Đó là kết quả trẻ con tự suy nghĩ theo cách của nó.', 7237, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18122, 'まずしさ ゆえに、がっこうに いけない こどもが いる。', 'mazushisa yue ni, gakkou ni ikenai kodomo ga iru.', NULL, 'Vì nghèo mà có những đứa trẻ không được đến trường.', 7238, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18123, 'わかさ ゆえの あやまちだった。', 'wakasa yue no ayamachi datta.', NULL, 'Đó là lỗi lầm do tuổi trẻ.', 7238, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18124, 'あいして いれば こそ、きびしく するのだ。', 'aishite ireba koso, kibishiku suru no da.', NULL, 'Chính vì thương nên mới nghiêm khắc.', 7239, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18125, 'けんこう で あれば こそ、はたらける。', 'kenkou de areba koso, hatarakeru.', NULL, 'Chính vì khỏe mạnh mới làm việc được.', 7239, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18126, 'れんきゅう とあって、かんこうちは こんで いる。', 'renkyuu to atte, kankouchi wa konde iru.', NULL, 'Vì là kỳ nghỉ dài nên điểm du lịch đông nghịt.', 7240, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18127, 'ゆうめいな かしゅが くる とあって、かいじょうは まんいんだ。', 'yuumei na kashu ga kuru to atte, kaijou wa man''in da.', NULL, 'Vì ca sĩ nổi tiếng đến nên hội trường chật kín.', 7240, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18128, 'あめも やんだ ことだし、そろそろ でかけようか。', 'ame mo yanda koto da shi, sorosoro dekakeyou ka.', NULL, 'Mưa cũng tạnh rồi, sắp đi thôi nhỉ.', 7241, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18129, 'みんな そろった ことだし、はじめましょう。', 'minna sorotta koto da shi, hajimemashou.', NULL, 'Mọi người đã đủ, bắt đầu thôi.', 7241, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18130, 'ゆめを かなえ んがため、かれは くにを でた。', 'yume o kanae nga tame, kare wa kuni o deta.', NULL, 'Để thực hiện ước mơ, anh ấy rời quê hương.', 7242, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18131, 'いきん がために はたらく。', 'ikin ga tame ni hataraku.', NULL, 'Làm việc để mà sống.', 7242, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18132, 'たいふうの ため、しあいは ちゅうしを よぎなく された。', 'taifuu no tame, shiai wa chuushi o yoginaku sareta.', NULL, 'Vì bão mà trận đấu buộc phải hủy.', 7243, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18133, 'けがで いんたいを よぎなく された。', 'kega de intai o yoginaku sareta.', NULL, 'Vì chấn thương mà buộc phải giải nghệ.', 7243, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18134, 'ちいさな くいちがいが、おおきな じけんに いたった。', 'chiisa na kuichigai ga, ookina jiken ni itatta.', NULL, 'Sai lệch nhỏ đã dẫn đến vụ việc lớn.', 7244, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18135, 'こどもから おとしよりに いたるまで、だれもが たのしめる。', 'kodomo kara otoshiyori ni itaru made, daremo ga tanoshimeru.', NULL, 'Từ trẻ em đến người già, ai cũng có thể vui chơi.', 7244, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18136, 'けいかくは ずさんで、けっきょく しっぱいに おわった。', 'keikaku wa zusan de, kekkyoku shippai ni owatta.', NULL, 'Kế hoạch cẩu thả, rốt cuộc kết thúc bằng thất bại.', 7245, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18137, 'はなしあいは まとまらず、けんかわかれに おわった。', 'hanashiai wa matomarazu, kenkawakare ni owatta.', NULL, 'Bàn bạc không đi đến đâu, kết cục chia tay trong cãi vã.', 7245, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18138, 'だいがくきょうじゅ とも あろう ひとが、そんな まちがいを するとは。', 'daigaku kyouju tomo arou hito ga, sonna machigai o suru to wa.', NULL, 'Một giáo sư đại học mà lại mắc lỗi như vậy.', 7246, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18139, 'けいさつかん とも あろう ものが はんざいを おかすなんて。', 'keisatsukan tomo arou mono ga hanzai o okasu nante.', NULL, 'Là cảnh sát mà lại phạm tội.', 7246, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18140, 'ベルが なるや いなや、がくせいたちは きょうしつを とびだした。', 'beru ga naru ya ina ya, gakuseitachi wa kyoushitsu o tobidashita.', NULL, 'Chuông vừa reo, học sinh đã lao ra khỏi lớp.', 7247, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18141, 'かれは いえに つくや、ベッドに たおれこんだ。', 'kare wa ie ni tsuku ya, beddo ni taorekonda.', NULL, 'Vừa về đến nhà, anh ấy đã đổ vật xuống giường.', 7247, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18142, 'こどもは かばんを おくが はやいか、あそびに でかけた。', 'kodomo wa kaban o oku ga hayai ka, asobi ni dekaketa.', NULL, 'Đứa trẻ vừa đặt cặp xuống là đã đi chơi.', 7248, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18143, 'しょうひんが ならぶが はやいか、うりきれた。', 'shouhin ga narabu ga hayai ka, urikireta.', NULL, 'Hàng vừa bày ra đã bán hết.', 7248, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18144, 'かのじょは わたしの かおを みるなり、なきだした。', 'kanojo wa watashi no kao o miru nari, nakidashita.', NULL, 'Cô ấy vừa nhìn thấy mặt tôi liền bật khóc.', 7249, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18145, 'ちちは でんわを きるなり、でかけて いった。', 'chichi wa denwa o kiru nari, dekakete itta.', NULL, 'Bố vừa cúp máy là đi ra ngoài ngay.', 7249, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18146, 'かたづける そばから、こどもが ちらかす。', 'katazukeru soba kara, kodomo ga chirakasu.', NULL, 'Vừa dọn xong là bọn trẻ lại bày bừa.', 7250, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18147, 'ならった そばから わすれて しまう。', 'naratta soba kara wasurete shimau.', NULL, 'Vừa học xong đã quên ngay.', 7250, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18148, 'とうきょうこうえんを かわきりに、ぜんこくツアーが はじまった。', 'toukyou kouen o kawakiri ni, zenkoku tsuaa ga hajimatta.', NULL, 'Khởi đầu bằng buổi diễn ở Tokyo, tour toàn quốc bắt đầu.', 7251, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18149, 'かれの はつげんを かわきりに、つぎつぎと いけんが でた。', 'kare no hatsugen o kawakiri ni, tsugitsugi to iken ga deta.', NULL, 'Bắt đầu từ phát biểu của anh ấy, ý kiến liên tục được đưa ra.', 7251, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18150, 'しにんが でるに いたって、やっと たいさくが とられた。', 'shinin ga deru ni itatte, yatto taisaku ga torareta.', NULL, 'Đến khi có người chết thì mới có biện pháp.', 7252, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18151, 'じたいが ここに いたっては、もう どうしようも ない。', 'jitai ga koko ni itatte wa, mou doushiyou mo nai.', NULL, 'Sự việc đến nước này thì không còn cách nào.', 7252, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18152, 'こんげつを かぎりに、この みせは へいてんします。', 'kongetsu o kagiri ni, kono mise wa heiten shimasu.', NULL, 'Hết tháng này, cửa hàng sẽ đóng cửa.', 7253, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18153, 'きょうを かぎりに タバコを やめる。', 'kyou o kagiri ni tabako o yameru.', NULL, 'Từ hôm nay tôi bỏ thuốc lá.', 7253, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18154, 'うまれて このかた、びょうきを した ことが ない。', 'umarete kono kata, byouki o shita koto ga nai.', NULL, 'Từ khi sinh ra đến nay chưa từng ốm.', 7254, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18155, 'にほんに きて このかた、いちども かえって いない。', 'nihon ni kite kono kata, ichido mo kaette inai.', NULL, 'Từ khi sang Nhật đến nay chưa về lần nào.', 7254, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18156, 'こんなんな じょうきょうに あって、かれは おちついて いた。', 'konnan na joukyou ni atte, kare wa ochitsuite ita.', NULL, 'Trong hoàn cảnh khó khăn, anh ấy vẫn bình tĩnh.', 7255, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18157, 'じょうほうかしゃかいに あって、プライバシーの ほごは じゅうようだ。', 'jouhouka shakai ni atte, puraibashii no hogo wa juuyou da.', NULL, 'Trong xã hội thông tin, bảo vệ quyền riêng tư là quan trọng.', 7255, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18158, 'こんど おあいした おりに、くわしく おはなしします。', 'kondo oai shita ori ni, kuwashiku ohanashi shimasu.', NULL, 'Dịp gặp lần tới tôi sẽ nói chi tiết.', 7256, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18159, 'おちかくに おこしの おりは、ぜひ おたちよりください。', 'ochikaku ni okoshi no ori wa, zehi otachiyori kudasai.', NULL, 'Khi đến gần đây, xin hãy ghé chơi.', 7256, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18160, 'おいそがしい ところを、ありがとうございます。', 'oisogashii tokoro o, arigatou gozaimasu.', NULL, 'Cảm ơn anh đã dành thời gian dù đang bận.', 7257, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18161, 'おやすみの ところを おじゃまして すみません。', 'oyasumi no tokoro o ojama shite sumimasen.', NULL, 'Xin lỗi đã làm phiền lúc anh đang nghỉ.', 7257, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18162, 'この しごとを まかせられるのは、かれを おいて ほかに いない。', 'kono shigoto o makaserareru no wa, kare o oite hoka ni inai.', NULL, 'Ngoài anh ấy ra không ai được giao việc này.', 7258, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18163, 'リーダーは かのじょを おいて ほかに かんがえられない。', 'riidaa wa kanojo o oite hoka ni kangaerarenai.', NULL, 'Ngoài cô ấy không thể nghĩ ra ai làm trưởng nhóm.', 7258, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18164, 'これは この ちほう ならではの あじだ。', 'kore wa kono chihou nara de wa no aji da.', NULL, 'Đây là hương vị chỉ vùng này mới có.', 7259, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18165, 'こども ならではの はっそうに おどろいた。', 'kodomo nara de wa no hassou ni odoroita.', NULL, 'Tôi bất ngờ với ý tưởng chỉ trẻ con mới có.', 7259, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18166, 'この びょうきは おとな に とどまらず、こどもにも ひろがって いる。', 'kono byouki wa otona ni todomarazu, kodomo ni mo hirogatte iru.', NULL, 'Căn bệnh không chỉ ở người lớn mà lan sang cả trẻ em.', 7260, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18167, 'かれの かつどうは こくない に とどまらず、かいがいにも およぶ。', 'kare no katsudou wa kokunai ni todomarazu, kaigai ni mo oyobu.', NULL, 'Hoạt động của anh ấy không chỉ trong nước mà cả nước ngoài.', 7260, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18168, 'ほんじつを もって、うけつけを しゅうりょうします。', 'honjitsu o motte, uketsuke o shuuryou shimasu.', NULL, 'Kể từ hôm nay chúng tôi ngừng tiếp nhận.', 7261, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18169, 'しけんの けっかは しょめんを もって おしらせします。', 'shiken no kekka wa shomen o motte oshirase shimasu.', NULL, 'Kết quả thi sẽ được thông báo bằng văn bản.', 7261, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18170, 'じじつに そくして はなして ください。', 'jijitsu ni sokushite hanashite kudasai.', NULL, 'Hãy nói bám sát sự thật.', 7262, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18171, 'げんばの じょうきょうに そくした たいさくが ひつようだ。', 'genba no joukyou ni sokushita taisaku ga hitsuyou da.', NULL, 'Cần biện pháp phù hợp với tình hình thực tế.', 7262, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18172, 'これは いのちに かかわる もんだいだ。', 'kore wa inochi ni kakawaru mondai da.', NULL, 'Đây là vấn đề liên quan đến tính mạng.', 7263, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18173, 'かいしゃの しんようにも かかわる ことだ。', 'kaisha no shin''you ni mo kakawaru koto da.', NULL, 'Việc này ảnh hưởng cả uy tín công ty.', 7263, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18174, 'にちようびを のぞいて、まいにち えいぎょうして います。', 'nichiyoubi o nozoite, mainichi eigyou shite imasu.', NULL, 'Mở cửa hằng ngày trừ Chủ nhật.', 7264, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18175, 'いちぶを のぞいて、ほとんど さんせいした。', 'ichibu o nozoite, hotondo sansei shita.', NULL, 'Trừ một số ít, hầu hết đều tán thành.', 7264, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18176, 'みなさんの きょうりょく なくして、せいこうは ありえません。', 'minasan no kyouryoku nakushite, seikou wa ariemasen.', NULL, 'Không có sự hợp tác của mọi người thì không thể thành công.', 7265, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18177, 'ことわり なしに へやに はいらないで。', 'kotowari nashi ni heya ni hairanaide.', NULL, 'Đừng vào phòng mà không xin phép.', 7265, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18178, 'いっしゅん たりとも ゆだんできない。', 'isshun taritomo yudan dekinai.', NULL, 'Không thể lơ là dù chỉ một khoảnh khắc.', 7266, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18179, 'いちえん たりとも むだに しない。', 'ichien taritomo muda ni shinai.', NULL, 'Không lãng phí dù chỉ một yên.', 7266, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18180, 'だいがくせい とも なると、じぶんで かんがえて こうどうすべきだ。', 'daigakusei tomo naru to, jibun de kangaete koudou subeki da.', NULL, 'Đã là sinh viên thì nên tự suy nghĩ mà hành động.', 7267, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18181, 'しゃちょう とも なれば、いそがしいのも とうぜんだ。', 'shachou tomo nareba, isogashii no mo touzen da.', NULL, 'Đã là giám đốc thì bận là đương nhiên.', 7267, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18182, 'こどもの ため とあれば、どんな くろうも いとわない。', 'kodomo no tame to areba, donna kurou mo itowanai.', NULL, 'Nếu vì con thì vất vả thế nào cũng không ngại.', 7268, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18183, 'しゃちょうの めいれい とあれば、しかたが ない。', 'shachou no meirei to areba, shikata ga nai.', NULL, 'Nếu là lệnh giám đốc thì đành chịu.', 7268, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18184, 'ちちに くちごたえ しようものなら、たいへんな ことに なる。', 'chichi ni kuchigotae shiyou mono nara, taihen na koto ni naru.', NULL, 'Nếu lỡ cãi lại bố thì to chuyện.', 7269, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18185, 'しめきりに おくれようものなら、しごとを うしなう。', 'shimekiri ni okureyou mono nara, shigoto o ushinau.', NULL, 'Nếu lỡ trễ hạn thì mất việc.', 7269, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18186, 'まいにち とは いわないまでも、しゅうに いちどは れんらくして。', 'mainichi to wa iwanai made mo, shuu ni ichido wa renraku shite.', NULL, 'Không đến mức mỗi ngày thì ít nhất tuần một lần hãy liên lạc.', 7270, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18187, 'ゆうしょう できないまでも、いい しあいを したい。', 'yuushou dekinai made mo, ii shiai o shitai.', NULL, 'Dù không vô địch thì ít nhất muốn đấu hay.', 7270, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18188, 'こども ならいざしらず、おとなが そんな ことを するとは。', 'kodomo nara iza shirazu, otona ga sonna koto o suru to wa.', NULL, 'Trẻ con thì đành, đằng này người lớn lại làm thế.', 7271, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18189, 'しらなかった ならいざしらず、しって いて やったのは ゆるせない。', 'shiranakatta nara iza shirazu, shitte ite yatta no wa yurusenai.', NULL, 'Không biết thì còn được, biết mà vẫn làm thì không thể tha.', 7271, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18190, 'かれは ねむったら さいご、なにが あっても おきない。', 'kare wa nemuttara saigo, nani ga atte mo okinai.', NULL, 'Anh ấy một khi đã ngủ thì có chuyện gì cũng không dậy.', 7272, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18191, 'この ばしょを しられたが さいご、にげられない。', 'kono basho o shirareta ga saigo, nigerarenai.', NULL, 'Một khi bị biết chỗ này thì không trốn được.', 7272, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18192, 'かんがえ ように よっては、しっぱいも いい けいけんだ。', 'kangae you ni yotte wa, shippai mo ii keiken da.', NULL, 'Tùy cách nghĩ, thất bại cũng là kinh nghiệm tốt.', 7273, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18193, 'この ことばは とり ように よっては しつれいに きこえる。', 'kono kotoba wa tori you ni yotte wa shitsurei ni kikoeru.', NULL, 'Tùy cách hiểu, câu này nghe có vẻ vô lễ.', 7273, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18196, 'かれの はなしが ほんとう と すれば、けいかくを みなおす ひつようが ある。', 'kare no hanashi ga hontou to sureba, keikaku o minaosu hitsuyou ga aru.', NULL, 'Nếu lời anh ấy là thật thì cần xem lại kế hoạch.', 7275, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18197, 'いま しゅっぱつする と すれば、ゆうがたには つく。', 'ima shuppatsu suru to sureba, yuugata ni wa tsuku.', NULL, 'Nếu xuất phát bây giờ thì chiều tối sẽ đến.', 7275, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18198, 'せんもんか と いえども、まちがえる ことは ある。', 'senmonka to iedomo, machigaeru koto wa aru.', NULL, 'Dù là chuyên gia cũng có lúc sai.', 7276, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18199, 'こども と いえども、ルールは まもるべきだ。', 'kodomo to iedomo, ruuru wa mamoru beki da.', NULL, 'Dù là trẻ con cũng phải giữ luật.', 7276, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18200, 'はる とは いえ、まだ さむい ひが つづく。', 'haru to wa ie, mada samui hi ga tsuzuku.', NULL, 'Tuy nói là xuân nhưng vẫn còn những ngày lạnh.', 7277, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18201, 'しごと とは いえ、かぞくと はなれるのは つらい。', 'shigoto to wa ie, kazoku to hanareru no wa tsurai.', NULL, 'Tuy là vì công việc nhưng xa gia đình thật khổ.', 7277, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18202, 'どんな りゆう であれ、ぼうりょくは ゆるされない。', 'donna riyuu de are, bouryoku wa yurusarenai.', NULL, 'Dù lý do gì, bạo lực không được chấp nhận.', 7278, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18203, 'あめ であれ ゆき であれ、しゅっぱつする。', 'ame de are yuki de are, shuppatsu suru.', NULL, 'Dù mưa hay tuyết cũng xuất phát.', 7278, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18204, 'さんせい にせよ はんたい にせよ、いけんを のべて ください。', 'sansei ni seyo hantai ni seyo, iken o nobete kudasai.', NULL, 'Tán thành hay phản đối, xin hãy nêu ý kiến.', 7279, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18205, 'いずれ にせよ、れんらくします。', 'izure ni seyo, renraku shimasu.', NULL, 'Dù sao đi nữa tôi cũng sẽ liên lạc.', 7279, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18206, 'いって くれれば てつだった ものを。', 'itte kurereba tetsudatta mono o.', NULL, 'Giá mà nói với tôi thì tôi đã giúp rồi.', 7280, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18207, 'はやく びょういんに いけば よかった ものを。', 'hayaku byouin ni ikeba yokatta mono o.', NULL, 'Giá mà đi viện sớm thì tốt rồi.', 7280, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18208, 'はれる と おもいきや、ごごから あめに なった。', 'hareru to omoikiya, gogo kara ame ni natta.', NULL, 'Cứ tưởng trời nắng, hóa ra chiều lại mưa.', 7281, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18209, 'かんたんな しけん と おもいきや、むずかしかった。', 'kantan na shiken to omoikiya, muzukashikatta.', NULL, 'Tưởng đề dễ, hóa ra lại khó.', 7281, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18210, 'インターネットで いえに いながらにして かいものが できる。', 'intaanetto de ie ni inagara ni shite kaimono ga dekiru.', NULL, 'Nhờ Internet có thể mua sắm ngay tại nhà.', 7282, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18211, 'かのじょは なみだ ながらに じじょうを はなした。', 'kanojo wa namida nagara ni jijou o hanashita.', NULL, 'Cô ấy vừa rơi nước mắt vừa kể sự tình.', 7282, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18212, 'こども ではあるまいし、じぶんで かんがえなさい。', 'kodomo de wa arumai shi, jibun de kangaenasai.', NULL, 'Có phải trẻ con đâu, tự suy nghĩ đi.', 7283, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18213, 'えいえんに わかれる わけ ではあるまいし、なかないで。', 'eien ni wakareru wake de wa arumai shi, nakanaide.', NULL, 'Có phải chia tay mãi mãi đâu, đừng khóc.', 7283, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18214, 'いくら ねがった とて、むりな ものは むりだ。', 'ikura negatta tote, muri na mono wa muri da.', NULL, 'Dù có mong mỏi bao nhiêu, không thể vẫn là không thể.', 7284, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18215, 'わたし とて、かなしくない わけでは ない。', 'watashi tote, kanashikunai wake de wa nai.', NULL, 'Ngay cả tôi cũng đâu phải không buồn.', 7284, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18216, 'かれの たいどは しつれい きわまりない。', 'kare no taido wa shitsurei kiwamarinai.', NULL, 'Thái độ của anh ta cực kỳ vô lễ.', 7285, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18217, 'この どうろは きけん きわまる。', 'kono douro wa kiken kiwamaru.', NULL, 'Con đường này cực kỳ nguy hiểm.', 7285, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18218, 'この ような しょうを いただき、こうえいの きわみです。', 'kono you na shou o itadaki, kouei no kiwami desu.', NULL, 'Được nhận giải thưởng này là vinh dự tột bậc.', 7286, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18219, 'あの しっぱいは ひあいの きわみだった。', 'ano shippai wa hiai no kiwami datta.', NULL, 'Thất bại đó là nỗi đau tột cùng.', 7286, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18220, 'おほめの ことばを いただき、こうえいの いたりです。', 'ohome no kotoba o itadaki, kouei no itari desu.', NULL, 'Được khen ngợi, tôi vô cùng vinh dự.', 7287, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18221, 'わかげの いたりで、ばかな ことを した。', 'wakage no itari de, baka na koto o shita.', NULL, 'Vì bồng bột tuổi trẻ nên đã làm điều ngốc nghếch.', 7287, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18222, 'いう までも なく、けんこうが いちばん たいせつだ。', 'iu made mo naku, kenkou ga ichiban taisetsu da.', NULL, 'Khỏi phải nói, sức khỏe là quan trọng nhất.', 7288, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18223, 'この ていどの けがなら、びょういんに いく までも ない。', 'kono teido no kega nara, byouin ni iku made mo nai.', NULL, 'Vết thương cỡ này thì không cần đến viện.', 7288, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18224, 'かぞくの かなしみは そうぞうに かたくない。', 'kazoku no kanashimi wa souzou ni katakunai.', NULL, 'Nỗi đau của gia đình không khó để tưởng tượng.', 7289, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18225, 'かれの くろうは さっするに かたくない。', 'kare no kurou wa sassuru ni katakunai.', NULL, 'Không khó để hình dung nỗi vất vả của anh ấy.', 7289, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18226, 'その ばんぐみは みるに たえない。', 'sono bangumi wa miru ni taenai.', NULL, 'Chương trình đó không đáng để xem.', 7290, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18227, 'この さくひんは おとなの かんしょうにも たえる。', 'kono sakuhin wa otona no kanshou ni mo taeru.', NULL, 'Tác phẩm này đáng để người lớn thưởng thức.', 7290, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18228, 'かれは しんらいするに たる ひとだ。', 'kare wa shinrai suru ni taru hito da.', NULL, 'Anh ấy là người đáng tin cậy.', 7291, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18229, 'はなすに たりない ことだ。', 'hanasu ni tarinai koto da.', NULL, 'Chuyện không đáng để nói.', 7291, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18230, 'みなさまの ごけんこうを ねがって やみません。', 'minasama no gokenkou o negatte yamimasen.', NULL, 'Luôn cầu chúc mọi người mạnh khỏe.', 7292, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18231, 'かれの せいこうを いのって やまない。', 'kare no seikou o inotte yamanai.', NULL, 'Tôi luôn cầu mong anh ấy thành công.', 7292, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18232, 'あの ときの はずかしさ と いったら なかった。', 'ano toki no hazukashisa to ittara nakatta.', NULL, 'Lúc đó xấu hổ không kể xiết.', 7293, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18233, 'やまの うえからの けしきの うつくしさ と いったら ない。', 'yama no ue kara no keshiki no utsukushisa to ittara nai.', NULL, 'Cảnh từ trên núi đẹp không tả nổi.', 7293, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18234, 'じしんの ことは かんがえる だに おそろしい。', 'jishin no koto wa kangaeru dani osoroshii.', NULL, 'Chỉ nghĩ đến động đất thôi đã sợ.', 7294, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18235, 'ゆめに だに おもわなかった。', 'yume ni dani omowanakatta.', NULL, 'Ngay cả trong mơ cũng không nghĩ tới.', 7294, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18236, 'じこに あったが、けがを しなかった だけ ましだ。', 'jiko ni atta ga, kega o shinakatta dake mashi da.', NULL, 'Bị tai nạn nhưng còn may là không bị thương.', 7295, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18237, 'きゅうりょうは やすいが、しごとが ある だけ ましだ。', 'kyuuryou wa yasui ga, shigoto ga aru dake mashi da.', NULL, 'Lương thấp nhưng còn may là có việc.', 7295, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18238, 'しばふに たちいる べからず。', 'shibafu ni tachiiru bekarazu.', NULL, 'Cấm giẫm lên cỏ.', 7296, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18239, 'それは けっして ゆるす べからざる こういだ。', 'sore wa kesshite yurusu bekarazaru koui da.', NULL, 'Đó là hành vi tuyệt đối không thể tha thứ.', 7296, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18240, 'きょうし に あるまじき こういだ。', 'kyoushi ni aru majiki koui da.', NULL, 'Đó là hành vi không thể có ở một giáo viên.', 7297, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18241, 'ひととして ゆるす まじき ことだ。', 'hito to shite yurusu majiki koto da.', NULL, 'Là con người thì không thể tha thứ việc đó.', 7297, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18242, 'だめなら、もう いちど やる までだ。', 'dame nara, mou ichido yaru made da.', NULL, 'Không được thì làm lại lần nữa thôi.', 7298, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18243, 'ほんとうの ことを いった までのことだ。', 'hontou no koto o itta made no koto da.', NULL, 'Tôi chỉ nói sự thật mà thôi.', 7298, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18244, 'いくら ちょきんしても、しんで しまえば それまでだ。', 'ikura chokin shite mo, shinde shimaeba sore made da.', NULL, 'Tiết kiệm bao nhiêu thì chết rồi cũng hết.', 7299, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18245, 'どんなに いい けいかくでも、じっこうしなければ それまでだ。', 'donna ni ii keikaku demo, jikkou shinakereba sore made da.', NULL, 'Kế hoạch hay mấy mà không thực hiện thì cũng vô ích.', 7299, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18246, 'ひさいしゃの はなしに なみだを きんじえない。', 'hisaisha no hanashi ni namida o kinjienai.', NULL, 'Nghe chuyện nạn nhân không cầm được nước mắt.', 7300, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18247, 'この けっていには いきどおりを きんじえない。', 'kono kettei ni wa ikidoori o kinjienai.', NULL, 'Không kìm được phẫn nộ trước quyết định này.', 7300, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18248, 'かれの えんぜつは ひとびとを かんどうさせずには おかない。', 'kare no enzetsu wa hitobito o kandou sasezu ni wa okanai.', NULL, 'Bài diễn văn của anh ấy chắc chắn làm mọi người cảm động.', 7301, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18249, 'はんにんを つかまえずには おかない。', 'hannin o tsukamaezu ni wa okanai.', NULL, 'Nhất định phải bắt được thủ phạm.', 7301, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18250, 'ひとに めいわくを かけたのだから、あやまらずには すまない。', 'hito ni meiwaku o kaketa no da kara, ayamarazu ni wa sumanai.', NULL, 'Đã làm phiền người khác thì không thể không xin lỗi.', 7302, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18251, 'この ままでは せきにんを とらないでは すまない。', 'kono mama de wa sekinin o toranai de wa sumanai.', NULL, 'Cứ thế này thì không thể không chịu trách nhiệm.', 7302, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18252, 'この ていどの ことで おどろくには あたらない。', 'kono teido no koto de odoroku ni wa ataranai.', NULL, 'Chuyện cỡ này không đáng để ngạc nhiên.', 7303, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18253, 'かれを せめるには あたらない。', 'kare o semeru ni wa ataranai.', NULL, 'Không đáng để trách anh ấy.', 7303, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18254, 'おかねは ある に こした ことは ない。', 'okane wa aru ni koshita koto wa nai.', NULL, 'Có tiền thì vẫn là tốt nhất.', 7304, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18255, 'ようじんする に こした ことは ない。', 'youjin suru ni koshita koto wa nai.', NULL, 'Cẩn thận vẫn là hơn.', 7304, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18256, 'かれは ものごとを おおげさに いう きらいが ある。', 'kare wa monogoto o oogesa ni iu kirai ga aru.', NULL, 'Anh ta có tật hay nói phóng đại.', 7305, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18257, 'さいきんの わかものは けいたいに たよる きらいが ある。', 'saikin no wakamono wa keitai ni tayoru kirai ga aru.', NULL, 'Giới trẻ gần đây có xu hướng phụ thuộc điện thoại.', 7305, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18258, 'かれは なまけて ばかりで、ついには かいしゃを くびに なる しまつだ。', 'kare wa namakete bakari de, tsui ni wa kaisha o kubi ni naru shimatsu da.', NULL, 'Anh ta lười mãi, rốt cuộc bị đuổi việc.', 7306, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18259, 'ちゅういしても きかず、けがを する しまつだ。', 'chuui shite mo kikazu, kega o suru shimatsu da.', NULL, 'Nhắc mà không nghe, cuối cùng bị thương.', 7306, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18260, 'しけんに ごうかくす べく、まいにち べんきょうして いる。', 'shiken ni goukaku su beku, mainichi benkyou shite iru.', NULL, 'Để đỗ kỳ thi, tôi học mỗi ngày.', 7307, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18261, 'もんだいを かいけつす べく、かいぎが ひらかれた。', 'mondai o kaiketsu su beku, kaigi ga hirakareta.', NULL, 'Cuộc họp được mở để giải quyết vấn đề.', 7307, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18262, 'こどもたちは どろ まみれに なって あそんだ。', 'kodomotachi wa doro mamire ni natte asonda.', NULL, 'Bọn trẻ chơi lấm lem bùn đất.', 7308, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18263, 'あせ まみれで はたらいた。', 'ase mamire de hataraita.', NULL, 'Làm việc mồ hôi nhễ nhại.', 7308, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18264, 'だんだん はるめいて きた。', 'dandan harumeite kita.', NULL, 'Trời dần mang dáng vẻ mùa xuân.', 7309, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18265, 'かれは ひにくめいた ことを いった。', 'kare wa hinikumeita koto o itta.', NULL, 'Anh ấy nói điều nghe có vẻ mỉa mai.', 7309, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18266, 'かのじょは いつも じょうひんぶって いる。', 'kanojo wa itsumo jouhinbutte iru.', NULL, 'Cô ấy lúc nào cũng làm ra vẻ thanh lịch.', 7310, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18267, 'えらぶる ひとは きらわれる。', 'eraburu hito wa kirawareru.', NULL, 'Người ra vẻ ta đây bị ghét.', 7310, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18268, 'かれは もう かえれ と ばかりに、ドアを あけた。', 'kare wa mou kaere to bakari ni, doa o aketa.', NULL, 'Anh ta mở cửa như muốn bảo "về đi".', 7311, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18269, 'いまが チャンス と ばかりに、みんなが かいに はしった。', 'ima ga chansu to bakari ni, minna ga kai ni hashitta.', NULL, 'Mọi người lao đi mua như thể "cơ hội là đây".', 7311, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18270, 'かのじょは なきださん ばかりの かおを して いた。', 'kanojo wa nakidasan bakari no kao o shite ita.', NULL, 'Cô ấy có vẻ mặt như sắp khóc.', 7312, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18271, 'われん ばかりの はくしゅが おこった。', 'waren bakari no hakushu ga okotta.', NULL, 'Tiếng vỗ tay vang dội như muốn vỡ tung.', 7312, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18272, 'みる とも なく テレビを みて いた。', 'miru tomo naku terebi o mite ita.', NULL, 'Tôi nhìn tivi một cách vô định.', 7313, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18273, 'どこから とも なく おんがくが きこえて きた。', 'doko kara tomo naku ongaku ga kikoete kita.', NULL, 'Không biết từ đâu vọng lại tiếng nhạc.', 7313, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18274, 'おれい かたがた、ごあいさつに うかがいました。', 'orei katagata, goaisatsu ni ukagaimashita.', NULL, 'Tôi đến chào hỏi, nhân tiện cảm ơn.', 7314, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18275, 'さんぽ かたがた、ほんやに よった。', 'sanpo katagata, hon''ya ni yotta.', NULL, 'Nhân tiện đi dạo, tôi ghé hiệu sách.', 7314, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18276, 'かいもの がてら、こうえんを さんぽした。', 'kaimono gatera, kouen o sanpo shita.', NULL, 'Tiện đi mua sắm, tôi đi dạo công viên.', 7315, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18277, 'えきまで おくり がてら、はなしを した。', 'eki made okuri gatera, hanashi o shita.', NULL, 'Tiện tiễn ra ga, tôi nói chuyện với anh ấy.', 7315, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18278, 'いそがしくて、けっきょく かのじょに あわず じまいだった。', 'isogashikute, kekkyoku kanojo ni awazu jimai datta.', NULL, 'Bận quá rốt cuộc đã không gặp được cô ấy.', 7316, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18279, 'かった ほんを よまず じまいで すてた。', 'katta hon o yomazu jimai de suteta.', NULL, 'Sách đã mua rốt cuộc không đọc mà vứt đi.', 7316, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18280, 'ふたりは おいつ おわれつ の レースを した。', 'futari wa oitsu owaretsu no reesu o shita.', NULL, 'Hai người đua nhau lúc đuổi lúc bị đuổi.', 7317, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18281, 'ゆきつ もどりつ しながら かんがえた。', 'yukitsu modoritsu shinagara kangaeta.', NULL, 'Đi tới đi lui mà suy nghĩ.', 7317, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18282, 'わたし なりに いっしょうけんめい がんばった。', 'watashi nari ni isshoukenmei ganbatta.', NULL, 'Tôi đã cố gắng hết sức theo cách của mình.', 7318, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18283, 'こども なりに かんがえた けっかだ。', 'kodomo nari ni kangaeta kekka da.', NULL, 'Đó là kết quả trẻ con tự suy nghĩ theo cách của nó.', 7318, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18284, 'まずしさ ゆえに、がっこうに いけない こどもが いる。', 'mazushisa yue ni, gakkou ni ikenai kodomo ga iru.', NULL, 'Vì nghèo mà có những đứa trẻ không được đến trường.', 7319, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18285, 'わかさ ゆえの あやまちだった。', 'wakasa yue no ayamachi datta.', NULL, 'Đó là lỗi lầm do tuổi trẻ.', 7319, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18286, 'あいして いれば こそ、きびしく するのだ。', 'aishite ireba koso, kibishiku suru no da.', NULL, 'Chính vì thương nên mới nghiêm khắc.', 7320, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18287, 'けんこう で あれば こそ、はたらける。', 'kenkou de areba koso, hatarakeru.', NULL, 'Chính vì khỏe mạnh mới làm việc được.', 7320, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18288, 'れんきゅう とあって、かんこうちは こんで いる。', 'renkyuu to atte, kankouchi wa konde iru.', NULL, 'Vì là kỳ nghỉ dài nên điểm du lịch đông nghịt.', 7321, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18289, 'ゆうめいな かしゅが くる とあって、かいじょうは まんいんだ。', 'yuumei na kashu ga kuru to atte, kaijou wa man''in da.', NULL, 'Vì ca sĩ nổi tiếng đến nên hội trường chật kín.', 7321, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18290, 'あめも やんだ ことだし、そろそろ でかけようか。', 'ame mo yanda koto da shi, sorosoro dekakeyou ka.', NULL, 'Mưa cũng tạnh rồi, sắp đi thôi nhỉ.', 7322, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18291, 'みんな そろった ことだし、はじめましょう。', 'minna sorotta koto da shi, hajimemashou.', NULL, 'Mọi người đã đủ, bắt đầu thôi.', 7322, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18292, 'ゆめを かなえ んがため、かれは くにを でた。', 'yume o kanae nga tame, kare wa kuni o deta.', NULL, 'Để thực hiện ước mơ, anh ấy rời quê hương.', 7323, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18293, 'いきん がために はたらく。', 'ikin ga tame ni hataraku.', NULL, 'Làm việc để mà sống.', 7323, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18294, 'たいふうの ため、しあいは ちゅうしを よぎなく された。', 'taifuu no tame, shiai wa chuushi o yoginaku sareta.', NULL, 'Vì bão mà trận đấu buộc phải hủy.', 7324, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18295, 'けがで いんたいを よぎなく された。', 'kega de intai o yoginaku sareta.', NULL, 'Vì chấn thương mà buộc phải giải nghệ.', 7324, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18296, 'ちいさな くいちがいが、おおきな じけんに いたった。', 'chiisa na kuichigai ga, ookina jiken ni itatta.', NULL, 'Sai lệch nhỏ đã dẫn đến vụ việc lớn.', 7325, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18297, 'こどもから おとしよりに いたるまで、だれもが たのしめる。', 'kodomo kara otoshiyori ni itaru made, daremo ga tanoshimeru.', NULL, 'Từ trẻ em đến người già, ai cũng có thể vui chơi.', 7325, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18298, 'けいかくは ずさんで、けっきょく しっぱいに おわった。', 'keikaku wa zusan de, kekkyoku shippai ni owatta.', NULL, 'Kế hoạch cẩu thả, rốt cuộc kết thúc bằng thất bại.', 7326, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18299, 'はなしあいは まとまらず、けんかわかれに おわった。', 'hanashiai wa matomarazu, kenkawakare ni owatta.', NULL, 'Bàn bạc không đi đến đâu, kết cục chia tay trong cãi vã.', 7326, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18300, 'だいがくきょうじゅ とも あろう ひとが、そんな まちがいを するとは。', 'daigaku kyouju tomo arou hito ga, sonna machigai o suru to wa.', NULL, 'Một giáo sư đại học mà lại mắc lỗi như vậy.', 7327, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18301, 'けいさつかん とも あろう ものが はんざいを おかすなんて。', 'keisatsukan tomo arou mono ga hanzai o okasu nante.', NULL, 'Là cảnh sát mà lại phạm tội.', 7327, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18302, 'ベルが なるや いなや、がくせいたちは きょうしつを とびだした。', 'beru ga naru ya ina ya, gakuseitachi wa kyoushitsu o tobidashita.', NULL, 'Chuông vừa reo, học sinh đã lao ra khỏi lớp.', 7328, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18303, 'かれは いえに つくや、ベッドに たおれこんだ。', 'kare wa ie ni tsuku ya, beddo ni taorekonda.', NULL, 'Vừa về đến nhà, anh ấy đã đổ vật xuống giường.', 7328, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18304, 'こどもは かばんを おくが はやいか、あそびに でかけた。', 'kodomo wa kaban o oku ga hayai ka, asobi ni dekaketa.', NULL, 'Đứa trẻ vừa đặt cặp xuống là đã đi chơi.', 7329, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18305, 'しょうひんが ならぶが はやいか、うりきれた。', 'shouhin ga narabu ga hayai ka, urikireta.', NULL, 'Hàng vừa bày ra đã bán hết.', 7329, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18306, 'かのじょは わたしの かおを みるなり、なきだした。', 'kanojo wa watashi no kao o miru nari, nakidashita.', NULL, 'Cô ấy vừa nhìn thấy mặt tôi liền bật khóc.', 7330, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18307, 'ちちは でんわを きるなり、でかけて いった。', 'chichi wa denwa o kiru nari, dekakete itta.', NULL, 'Bố vừa cúp máy là đi ra ngoài ngay.', 7330, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18308, 'かたづける そばから、こどもが ちらかす。', 'katazukeru soba kara, kodomo ga chirakasu.', NULL, 'Vừa dọn xong là bọn trẻ lại bày bừa.', 7331, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18309, 'ならった そばから わすれて しまう。', 'naratta soba kara wasurete shimau.', NULL, 'Vừa học xong đã quên ngay.', 7331, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18310, 'とうきょうこうえんを かわきりに、ぜんこくツアーが はじまった。', 'toukyou kouen o kawakiri ni, zenkoku tsuaa ga hajimatta.', NULL, 'Khởi đầu bằng buổi diễn ở Tokyo, tour toàn quốc bắt đầu.', 7332, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18311, 'かれの はつげんを かわきりに、つぎつぎと いけんが でた。', 'kare no hatsugen o kawakiri ni, tsugitsugi to iken ga deta.', NULL, 'Bắt đầu từ phát biểu của anh ấy, ý kiến liên tục được đưa ra.', 7332, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18312, 'しにんが でるに いたって、やっと たいさくが とられた。', 'shinin ga deru ni itatte, yatto taisaku ga torareta.', NULL, 'Đến khi có người chết thì mới có biện pháp.', 7333, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18313, 'じたいが ここに いたっては、もう どうしようも ない。', 'jitai ga koko ni itatte wa, mou doushiyou mo nai.', NULL, 'Sự việc đến nước này thì không còn cách nào.', 7333, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18314, 'こんげつを かぎりに、この みせは へいてんします。', 'kongetsu o kagiri ni, kono mise wa heiten shimasu.', NULL, 'Hết tháng này, cửa hàng sẽ đóng cửa.', 7334, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18315, 'きょうを かぎりに タバコを やめる。', 'kyou o kagiri ni tabako o yameru.', NULL, 'Từ hôm nay tôi bỏ thuốc lá.', 7334, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18316, 'うまれて このかた、びょうきを した ことが ない。', 'umarete kono kata, byouki o shita koto ga nai.', NULL, 'Từ khi sinh ra đến nay chưa từng ốm.', 7335, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18317, 'にほんに きて このかた、いちども かえって いない。', 'nihon ni kite kono kata, ichido mo kaette inai.', NULL, 'Từ khi sang Nhật đến nay chưa về lần nào.', 7335, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18318, 'こんなんな じょうきょうに あって、かれは おちついて いた。', 'konnan na joukyou ni atte, kare wa ochitsuite ita.', NULL, 'Trong hoàn cảnh khó khăn, anh ấy vẫn bình tĩnh.', 7336, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18319, 'じょうほうかしゃかいに あって、プライバシーの ほごは じゅうようだ。', 'jouhouka shakai ni atte, puraibashii no hogo wa juuyou da.', NULL, 'Trong xã hội thông tin, bảo vệ quyền riêng tư là quan trọng.', 7336, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18320, 'こんど おあいした おりに、くわしく おはなしします。', 'kondo oai shita ori ni, kuwashiku ohanashi shimasu.', NULL, 'Dịp gặp lần tới tôi sẽ nói chi tiết.', 7337, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18321, 'おちかくに おこしの おりは、ぜひ おたちよりください。', 'ochikaku ni okoshi no ori wa, zehi otachiyori kudasai.', NULL, 'Khi đến gần đây, xin hãy ghé chơi.', 7337, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18322, 'おいそがしい ところを、ありがとうございます。', 'oisogashii tokoro o, arigatou gozaimasu.', NULL, 'Cảm ơn anh đã dành thời gian dù đang bận.', 7338, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18323, 'おやすみの ところを おじゃまして すみません。', 'oyasumi no tokoro o ojama shite sumimasen.', NULL, 'Xin lỗi đã làm phiền lúc anh đang nghỉ.', 7338, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18324, 'この しごとを まかせられるのは、かれを おいて ほかに いない。', 'kono shigoto o makaserareru no wa, kare o oite hoka ni inai.', NULL, 'Ngoài anh ấy ra không ai được giao việc này.', 7339, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18325, 'リーダーは かのじょを おいて ほかに かんがえられない。', 'riidaa wa kanojo o oite hoka ni kangaerarenai.', NULL, 'Ngoài cô ấy không thể nghĩ ra ai làm trưởng nhóm.', 7339, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18326, 'これは この ちほう ならではの あじだ。', 'kore wa kono chihou nara de wa no aji da.', NULL, 'Đây là hương vị chỉ vùng này mới có.', 7340, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18327, 'こども ならではの はっそうに おどろいた。', 'kodomo nara de wa no hassou ni odoroita.', NULL, 'Tôi bất ngờ với ý tưởng chỉ trẻ con mới có.', 7340, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18328, 'この びょうきは おとな に とどまらず、こどもにも ひろがって いる。', 'kono byouki wa otona ni todomarazu, kodomo ni mo hirogatte iru.', NULL, 'Căn bệnh không chỉ ở người lớn mà lan sang cả trẻ em.', 7341, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18329, 'かれの かつどうは こくない に とどまらず、かいがいにも およぶ。', 'kare no katsudou wa kokunai ni todomarazu, kaigai ni mo oyobu.', NULL, 'Hoạt động của anh ấy không chỉ trong nước mà cả nước ngoài.', 7341, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18330, 'ほんじつを もって、うけつけを しゅうりょうします。', 'honjitsu o motte, uketsuke o shuuryou shimasu.', NULL, 'Kể từ hôm nay chúng tôi ngừng tiếp nhận.', 7342, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18331, 'しけんの けっかは しょめんを もって おしらせします。', 'shiken no kekka wa shomen o motte oshirase shimasu.', NULL, 'Kết quả thi sẽ được thông báo bằng văn bản.', 7342, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18332, 'じじつに そくして はなして ください。', 'jijitsu ni sokushite hanashite kudasai.', NULL, 'Hãy nói bám sát sự thật.', 7343, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18333, 'げんばの じょうきょうに そくした たいさくが ひつようだ。', 'genba no joukyou ni sokushita taisaku ga hitsuyou da.', NULL, 'Cần biện pháp phù hợp với tình hình thực tế.', 7343, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18334, 'これは いのちに かかわる もんだいだ。', 'kore wa inochi ni kakawaru mondai da.', NULL, 'Đây là vấn đề liên quan đến tính mạng.', 7344, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18335, 'かいしゃの しんようにも かかわる ことだ。', 'kaisha no shin''you ni mo kakawaru koto da.', NULL, 'Việc này ảnh hưởng cả uy tín công ty.', 7344, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18336, 'にちようびを のぞいて、まいにち えいぎょうして います。', 'nichiyoubi o nozoite, mainichi eigyou shite imasu.', NULL, 'Mở cửa hằng ngày trừ Chủ nhật.', 7345, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18337, 'いちぶを のぞいて、ほとんど さんせいした。', 'ichibu o nozoite, hotondo sansei shita.', NULL, 'Trừ một số ít, hầu hết đều tán thành.', 7345, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18338, 'みなさんの きょうりょく なくして、せいこうは ありえません。', 'minasan no kyouryoku nakushite, seikou wa ariemasen.', NULL, 'Không có sự hợp tác của mọi người thì không thể thành công.', 7346, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18339, 'ことわり なしに へやに はいらないで。', 'kotowari nashi ni heya ni hairanaide.', NULL, 'Đừng vào phòng mà không xin phép.', 7346, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18340, 'いっしゅん たりとも ゆだんできない。', 'isshun taritomo yudan dekinai.', NULL, 'Không thể lơ là dù chỉ một khoảnh khắc.', 7347, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18341, 'いちえん たりとも むだに しない。', 'ichien taritomo muda ni shinai.', NULL, 'Không lãng phí dù chỉ một yên.', 7347, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18342, 'だいがくせい とも なると、じぶんで かんがえて こうどうすべきだ。', 'daigakusei tomo naru to, jibun de kangaete koudou subeki da.', NULL, 'Đã là sinh viên thì nên tự suy nghĩ mà hành động.', 7348, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18343, 'しゃちょう とも なれば、いそがしいのも とうぜんだ。', 'shachou tomo nareba, isogashii no mo touzen da.', NULL, 'Đã là giám đốc thì bận là đương nhiên.', 7348, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18344, 'こどもの ため とあれば、どんな くろうも いとわない。', 'kodomo no tame to areba, donna kurou mo itowanai.', NULL, 'Nếu vì con thì vất vả thế nào cũng không ngại.', 7349, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18345, 'しゃちょうの めいれい とあれば、しかたが ない。', 'shachou no meirei to areba, shikata ga nai.', NULL, 'Nếu là lệnh giám đốc thì đành chịu.', 7349, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18346, 'ちちに くちごたえ しようものなら、たいへんな ことに なる。', 'chichi ni kuchigotae shiyou mono nara, taihen na koto ni naru.', NULL, 'Nếu lỡ cãi lại bố thì to chuyện.', 7350, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18347, 'しめきりに おくれようものなら、しごとを うしなう。', 'shimekiri ni okureyou mono nara, shigoto o ushinau.', NULL, 'Nếu lỡ trễ hạn thì mất việc.', 7350, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18424, 'こどもたちは どろ まみれに なって あそんだ。', 'kodomotachi wa doro mamire ni natte asonda.', NULL, 'Bọn trẻ chơi lấm lem bùn đất.', 7389, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18348, 'まいにち とは いわないまでも、しゅうに いちどは れんらくして。', 'mainichi to wa iwanai made mo, shuu ni ichido wa renraku shite.', NULL, 'Không đến mức mỗi ngày thì ít nhất tuần một lần hãy liên lạc.', 7351, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18349, 'ゆうしょう できないまでも、いい しあいを したい。', 'yuushou dekinai made mo, ii shiai o shitai.', NULL, 'Dù không vô địch thì ít nhất muốn đấu hay.', 7351, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18350, 'こども ならいざしらず、おとなが そんな ことを するとは。', 'kodomo nara iza shirazu, otona ga sonna koto o suru to wa.', NULL, 'Trẻ con thì đành, đằng này người lớn lại làm thế.', 7352, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18351, 'しらなかった ならいざしらず、しって いて やったのは ゆるせない。', 'shiranakatta nara iza shirazu, shitte ite yatta no wa yurusenai.', NULL, 'Không biết thì còn được, biết mà vẫn làm thì không thể tha.', 7352, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18352, 'かれは ねむったら さいご、なにが あっても おきない。', 'kare wa nemuttara saigo, nani ga atte mo okinai.', NULL, 'Anh ấy một khi đã ngủ thì có chuyện gì cũng không dậy.', 7353, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18353, 'この ばしょを しられたが さいご、にげられない。', 'kono basho o shirareta ga saigo, nigerarenai.', NULL, 'Một khi bị biết chỗ này thì không trốn được.', 7353, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18354, 'かんがえ ように よっては、しっぱいも いい けいけんだ。', 'kangae you ni yotte wa, shippai mo ii keiken da.', NULL, 'Tùy cách nghĩ, thất bại cũng là kinh nghiệm tốt.', 7354, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18355, 'この ことばは とり ように よっては しつれいに きこえる。', 'kono kotoba wa tori you ni yotte wa shitsurei ni kikoeru.', NULL, 'Tùy cách hiểu, câu này nghe có vẻ vô lễ.', 7354, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18358, 'かれの はなしが ほんとう と すれば、けいかくを みなおす ひつようが ある。', 'kare no hanashi ga hontou to sureba, keikaku o minaosu hitsuyou ga aru.', NULL, 'Nếu lời anh ấy là thật thì cần xem lại kế hoạch.', 7356, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18359, 'いま しゅっぱつする と すれば、ゆうがたには つく。', 'ima shuppatsu suru to sureba, yuugata ni wa tsuku.', NULL, 'Nếu xuất phát bây giờ thì chiều tối sẽ đến.', 7356, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18360, 'せんもんか と いえども、まちがえる ことは ある。', 'senmonka to iedomo, machigaeru koto wa aru.', NULL, 'Dù là chuyên gia cũng có lúc sai.', 7357, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18361, 'こども と いえども、ルールは まもるべきだ。', 'kodomo to iedomo, ruuru wa mamoru beki da.', NULL, 'Dù là trẻ con cũng phải giữ luật.', 7357, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18362, 'はる とは いえ、まだ さむい ひが つづく。', 'haru to wa ie, mada samui hi ga tsuzuku.', NULL, 'Tuy nói là xuân nhưng vẫn còn những ngày lạnh.', 7358, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18363, 'しごと とは いえ、かぞくと はなれるのは つらい。', 'shigoto to wa ie, kazoku to hanareru no wa tsurai.', NULL, 'Tuy là vì công việc nhưng xa gia đình thật khổ.', 7358, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18364, 'どんな りゆう であれ、ぼうりょくは ゆるされない。', 'donna riyuu de are, bouryoku wa yurusarenai.', NULL, 'Dù lý do gì, bạo lực không được chấp nhận.', 7359, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18365, 'あめ であれ ゆき であれ、しゅっぱつする。', 'ame de are yuki de are, shuppatsu suru.', NULL, 'Dù mưa hay tuyết cũng xuất phát.', 7359, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18366, 'さんせい にせよ はんたい にせよ、いけんを のべて ください。', 'sansei ni seyo hantai ni seyo, iken o nobete kudasai.', NULL, 'Tán thành hay phản đối, xin hãy nêu ý kiến.', 7360, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18367, 'いずれ にせよ、れんらくします。', 'izure ni seyo, renraku shimasu.', NULL, 'Dù sao đi nữa tôi cũng sẽ liên lạc.', 7360, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18368, 'いって くれれば てつだった ものを。', 'itte kurereba tetsudatta mono o.', NULL, 'Giá mà nói với tôi thì tôi đã giúp rồi.', 7361, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18369, 'はやく びょういんに いけば よかった ものを。', 'hayaku byouin ni ikeba yokatta mono o.', NULL, 'Giá mà đi viện sớm thì tốt rồi.', 7361, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18370, 'はれる と おもいきや、ごごから あめに なった。', 'hareru to omoikiya, gogo kara ame ni natta.', NULL, 'Cứ tưởng trời nắng, hóa ra chiều lại mưa.', 7362, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18371, 'かんたんな しけん と おもいきや、むずかしかった。', 'kantan na shiken to omoikiya, muzukashikatta.', NULL, 'Tưởng đề dễ, hóa ra lại khó.', 7362, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18372, 'インターネットで いえに いながらにして かいものが できる。', 'intaanetto de ie ni inagara ni shite kaimono ga dekiru.', NULL, 'Nhờ Internet có thể mua sắm ngay tại nhà.', 7363, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18373, 'かのじょは なみだ ながらに じじょうを はなした。', 'kanojo wa namida nagara ni jijou o hanashita.', NULL, 'Cô ấy vừa rơi nước mắt vừa kể sự tình.', 7363, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18374, 'こども ではあるまいし、じぶんで かんがえなさい。', 'kodomo de wa arumai shi, jibun de kangaenasai.', NULL, 'Có phải trẻ con đâu, tự suy nghĩ đi.', 7364, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18375, 'えいえんに わかれる わけ ではあるまいし、なかないで。', 'eien ni wakareru wake de wa arumai shi, nakanaide.', NULL, 'Có phải chia tay mãi mãi đâu, đừng khóc.', 7364, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18376, 'いくら ねがった とて、むりな ものは むりだ。', 'ikura negatta tote, muri na mono wa muri da.', NULL, 'Dù có mong mỏi bao nhiêu, không thể vẫn là không thể.', 7365, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18377, 'わたし とて、かなしくない わけでは ない。', 'watashi tote, kanashikunai wake de wa nai.', NULL, 'Ngay cả tôi cũng đâu phải không buồn.', 7365, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18378, 'かれの たいどは しつれい きわまりない。', 'kare no taido wa shitsurei kiwamarinai.', NULL, 'Thái độ của anh ta cực kỳ vô lễ.', 7366, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18379, 'この どうろは きけん きわまる。', 'kono douro wa kiken kiwamaru.', NULL, 'Con đường này cực kỳ nguy hiểm.', 7366, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18380, 'この ような しょうを いただき、こうえいの きわみです。', 'kono you na shou o itadaki, kouei no kiwami desu.', NULL, 'Được nhận giải thưởng này là vinh dự tột bậc.', 7367, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18381, 'あの しっぱいは ひあいの きわみだった。', 'ano shippai wa hiai no kiwami datta.', NULL, 'Thất bại đó là nỗi đau tột cùng.', 7367, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18382, 'おほめの ことばを いただき、こうえいの いたりです。', 'ohome no kotoba o itadaki, kouei no itari desu.', NULL, 'Được khen ngợi, tôi vô cùng vinh dự.', 7368, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18383, 'わかげの いたりで、ばかな ことを した。', 'wakage no itari de, baka na koto o shita.', NULL, 'Vì bồng bột tuổi trẻ nên đã làm điều ngốc nghếch.', 7368, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18384, 'いう までも なく、けんこうが いちばん たいせつだ。', 'iu made mo naku, kenkou ga ichiban taisetsu da.', NULL, 'Khỏi phải nói, sức khỏe là quan trọng nhất.', 7369, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18385, 'この ていどの けがなら、びょういんに いく までも ない。', 'kono teido no kega nara, byouin ni iku made mo nai.', NULL, 'Vết thương cỡ này thì không cần đến viện.', 7369, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18386, 'かぞくの かなしみは そうぞうに かたくない。', 'kazoku no kanashimi wa souzou ni katakunai.', NULL, 'Nỗi đau của gia đình không khó để tưởng tượng.', 7370, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18387, 'かれの くろうは さっするに かたくない。', 'kare no kurou wa sassuru ni katakunai.', NULL, 'Không khó để hình dung nỗi vất vả của anh ấy.', 7370, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18388, 'その ばんぐみは みるに たえない。', 'sono bangumi wa miru ni taenai.', NULL, 'Chương trình đó không đáng để xem.', 7371, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18389, 'この さくひんは おとなの かんしょうにも たえる。', 'kono sakuhin wa otona no kanshou ni mo taeru.', NULL, 'Tác phẩm này đáng để người lớn thưởng thức.', 7371, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18390, 'かれは しんらいするに たる ひとだ。', 'kare wa shinrai suru ni taru hito da.', NULL, 'Anh ấy là người đáng tin cậy.', 7372, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18391, 'はなすに たりない ことだ。', 'hanasu ni tarinai koto da.', NULL, 'Chuyện không đáng để nói.', 7372, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18392, 'みなさまの ごけんこうを ねがって やみません。', 'minasama no gokenkou o negatte yamimasen.', NULL, 'Luôn cầu chúc mọi người mạnh khỏe.', 7373, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18393, 'かれの せいこうを いのって やまない。', 'kare no seikou o inotte yamanai.', NULL, 'Tôi luôn cầu mong anh ấy thành công.', 7373, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18394, 'あの ときの はずかしさ と いったら なかった。', 'ano toki no hazukashisa to ittara nakatta.', NULL, 'Lúc đó xấu hổ không kể xiết.', 7374, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18395, 'やまの うえからの けしきの うつくしさ と いったら ない。', 'yama no ue kara no keshiki no utsukushisa to ittara nai.', NULL, 'Cảnh từ trên núi đẹp không tả nổi.', 7374, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18396, 'じしんの ことは かんがえる だに おそろしい。', 'jishin no koto wa kangaeru dani osoroshii.', NULL, 'Chỉ nghĩ đến động đất thôi đã sợ.', 7375, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18397, 'ゆめに だに おもわなかった。', 'yume ni dani omowanakatta.', NULL, 'Ngay cả trong mơ cũng không nghĩ tới.', 7375, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18398, 'じこに あったが、けがを しなかった だけ ましだ。', 'jiko ni atta ga, kega o shinakatta dake mashi da.', NULL, 'Bị tai nạn nhưng còn may là không bị thương.', 7376, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18399, 'きゅうりょうは やすいが、しごとが ある だけ ましだ。', 'kyuuryou wa yasui ga, shigoto ga aru dake mashi da.', NULL, 'Lương thấp nhưng còn may là có việc.', 7376, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18400, 'しばふに たちいる べからず。', 'shibafu ni tachiiru bekarazu.', NULL, 'Cấm giẫm lên cỏ.', 7377, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18401, 'それは けっして ゆるす べからざる こういだ。', 'sore wa kesshite yurusu bekarazaru koui da.', NULL, 'Đó là hành vi tuyệt đối không thể tha thứ.', 7377, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18402, 'きょうし に あるまじき こういだ。', 'kyoushi ni aru majiki koui da.', NULL, 'Đó là hành vi không thể có ở một giáo viên.', 7378, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18403, 'ひととして ゆるす まじき ことだ。', 'hito to shite yurusu majiki koto da.', NULL, 'Là con người thì không thể tha thứ việc đó.', 7378, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18404, 'だめなら、もう いちど やる までだ。', 'dame nara, mou ichido yaru made da.', NULL, 'Không được thì làm lại lần nữa thôi.', 7379, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18405, 'ほんとうの ことを いった までのことだ。', 'hontou no koto o itta made no koto da.', NULL, 'Tôi chỉ nói sự thật mà thôi.', 7379, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18406, 'いくら ちょきんしても、しんで しまえば それまでだ。', 'ikura chokin shite mo, shinde shimaeba sore made da.', NULL, 'Tiết kiệm bao nhiêu thì chết rồi cũng hết.', 7380, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18407, 'どんなに いい けいかくでも、じっこうしなければ それまでだ。', 'donna ni ii keikaku demo, jikkou shinakereba sore made da.', NULL, 'Kế hoạch hay mấy mà không thực hiện thì cũng vô ích.', 7380, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18408, 'ひさいしゃの はなしに なみだを きんじえない。', 'hisaisha no hanashi ni namida o kinjienai.', NULL, 'Nghe chuyện nạn nhân không cầm được nước mắt.', 7381, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18409, 'この けっていには いきどおりを きんじえない。', 'kono kettei ni wa ikidoori o kinjienai.', NULL, 'Không kìm được phẫn nộ trước quyết định này.', 7381, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18410, 'かれの えんぜつは ひとびとを かんどうさせずには おかない。', 'kare no enzetsu wa hitobito o kandou sasezu ni wa okanai.', NULL, 'Bài diễn văn của anh ấy chắc chắn làm mọi người cảm động.', 7382, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18411, 'はんにんを つかまえずには おかない。', 'hannin o tsukamaezu ni wa okanai.', NULL, 'Nhất định phải bắt được thủ phạm.', 7382, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18412, 'ひとに めいわくを かけたのだから、あやまらずには すまない。', 'hito ni meiwaku o kaketa no da kara, ayamarazu ni wa sumanai.', NULL, 'Đã làm phiền người khác thì không thể không xin lỗi.', 7383, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18413, 'この ままでは せきにんを とらないでは すまない。', 'kono mama de wa sekinin o toranai de wa sumanai.', NULL, 'Cứ thế này thì không thể không chịu trách nhiệm.', 7383, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18414, 'この ていどの ことで おどろくには あたらない。', 'kono teido no koto de odoroku ni wa ataranai.', NULL, 'Chuyện cỡ này không đáng để ngạc nhiên.', 7384, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18415, 'かれを せめるには あたらない。', 'kare o semeru ni wa ataranai.', NULL, 'Không đáng để trách anh ấy.', 7384, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18416, 'おかねは ある に こした ことは ない。', 'okane wa aru ni koshita koto wa nai.', NULL, 'Có tiền thì vẫn là tốt nhất.', 7385, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18417, 'ようじんする に こした ことは ない。', 'youjin suru ni koshita koto wa nai.', NULL, 'Cẩn thận vẫn là hơn.', 7385, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18418, 'かれは ものごとを おおげさに いう きらいが ある。', 'kare wa monogoto o oogesa ni iu kirai ga aru.', NULL, 'Anh ta có tật hay nói phóng đại.', 7386, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18419, 'さいきんの わかものは けいたいに たよる きらいが ある。', 'saikin no wakamono wa keitai ni tayoru kirai ga aru.', NULL, 'Giới trẻ gần đây có xu hướng phụ thuộc điện thoại.', 7386, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18420, 'かれは なまけて ばかりで、ついには かいしゃを くびに なる しまつだ。', 'kare wa namakete bakari de, tsui ni wa kaisha o kubi ni naru shimatsu da.', NULL, 'Anh ta lười mãi, rốt cuộc bị đuổi việc.', 7387, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18421, 'ちゅういしても きかず、けがを する しまつだ。', 'chuui shite mo kikazu, kega o suru shimatsu da.', NULL, 'Nhắc mà không nghe, cuối cùng bị thương.', 7387, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18422, 'しけんに ごうかくす べく、まいにち べんきょうして いる。', 'shiken ni goukaku su beku, mainichi benkyou shite iru.', NULL, 'Để đỗ kỳ thi, tôi học mỗi ngày.', 7388, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18423, 'もんだいを かいけつす べく、かいぎが ひらかれた。', 'mondai o kaiketsu su beku, kaigi ga hirakareta.', NULL, 'Cuộc họp được mở để giải quyết vấn đề.', 7388, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18427, 'かれは ひにくめいた ことを いった。', 'kare wa hinikumeita koto o itta.', NULL, 'Anh ấy nói điều nghe có vẻ mỉa mai.', 7390, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18428, 'かのじょは いつも じょうひんぶって いる。', 'kanojo wa itsumo jouhinbutte iru.', NULL, 'Cô ấy lúc nào cũng làm ra vẻ thanh lịch.', 7391, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18429, 'えらぶる ひとは きらわれる。', 'eraburu hito wa kirawareru.', NULL, 'Người ra vẻ ta đây bị ghét.', 7391, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18430, 'かれは もう かえれ と ばかりに、ドアを あけた。', 'kare wa mou kaere to bakari ni, doa o aketa.', NULL, 'Anh ta mở cửa như muốn bảo "về đi".', 7392, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18431, 'いまが チャンス と ばかりに、みんなが かいに はしった。', 'ima ga chansu to bakari ni, minna ga kai ni hashitta.', NULL, 'Mọi người lao đi mua như thể "cơ hội là đây".', 7392, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18432, 'かのじょは なきださん ばかりの かおを して いた。', 'kanojo wa nakidasan bakari no kao o shite ita.', NULL, 'Cô ấy có vẻ mặt như sắp khóc.', 7393, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18433, 'われん ばかりの はくしゅが おこった。', 'waren bakari no hakushu ga okotta.', NULL, 'Tiếng vỗ tay vang dội như muốn vỡ tung.', 7393, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18434, 'みる とも なく テレビを みて いた。', 'miru tomo naku terebi o mite ita.', NULL, 'Tôi nhìn tivi một cách vô định.', 7394, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18435, 'どこから とも なく おんがくが きこえて きた。', 'doko kara tomo naku ongaku ga kikoete kita.', NULL, 'Không biết từ đâu vọng lại tiếng nhạc.', 7394, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18436, 'おれい かたがた、ごあいさつに うかがいました。', 'orei katagata, goaisatsu ni ukagaimashita.', NULL, 'Tôi đến chào hỏi, nhân tiện cảm ơn.', 7395, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18437, 'さんぽ かたがた、ほんやに よった。', 'sanpo katagata, hon''ya ni yotta.', NULL, 'Nhân tiện đi dạo, tôi ghé hiệu sách.', 7395, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18438, 'かいもの がてら、こうえんを さんぽした。', 'kaimono gatera, kouen o sanpo shita.', NULL, 'Tiện đi mua sắm, tôi đi dạo công viên.', 7396, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18439, 'えきまで おくり がてら、はなしを した。', 'eki made okuri gatera, hanashi o shita.', NULL, 'Tiện tiễn ra ga, tôi nói chuyện với anh ấy.', 7396, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18440, 'いそがしくて、けっきょく かのじょに あわず じまいだった。', 'isogashikute, kekkyoku kanojo ni awazu jimai datta.', NULL, 'Bận quá rốt cuộc đã không gặp được cô ấy.', 7397, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18441, 'かった ほんを よまず じまいで すてた。', 'katta hon o yomazu jimai de suteta.', NULL, 'Sách đã mua rốt cuộc không đọc mà vứt đi.', 7397, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18442, 'ふたりは おいつ おわれつ の レースを した。', 'futari wa oitsu owaretsu no reesu o shita.', NULL, 'Hai người đua nhau lúc đuổi lúc bị đuổi.', 7398, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18443, 'ゆきつ もどりつ しながら かんがえた。', 'yukitsu modoritsu shinagara kangaeta.', NULL, 'Đi tới đi lui mà suy nghĩ.', 7398, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18444, 'わたし なりに いっしょうけんめい がんばった。', 'watashi nari ni isshoukenmei ganbatta.', NULL, 'Tôi đã cố gắng hết sức theo cách của mình.', 7399, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18445, 'こども なりに かんがえた けっかだ。', 'kodomo nari ni kangaeta kekka da.', NULL, 'Đó là kết quả trẻ con tự suy nghĩ theo cách của nó.', 7399, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18446, 'まずしさ ゆえに、がっこうに いけない こどもが いる。', 'mazushisa yue ni, gakkou ni ikenai kodomo ga iru.', NULL, 'Vì nghèo mà có những đứa trẻ không được đến trường.', 7400, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18447, 'わかさ ゆえの あやまちだった。', 'wakasa yue no ayamachi datta.', NULL, 'Đó là lỗi lầm do tuổi trẻ.', 7400, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18448, 'あいして いれば こそ、きびしく するのだ。', 'aishite ireba koso, kibishiku suru no da.', NULL, 'Chính vì thương nên mới nghiêm khắc.', 7401, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18449, 'けんこう で あれば こそ、はたらける。', 'kenkou de areba koso, hatarakeru.', NULL, 'Chính vì khỏe mạnh mới làm việc được.', 7401, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18450, 'れんきゅう とあって、かんこうちは こんで いる。', 'renkyuu to atte, kankouchi wa konde iru.', NULL, 'Vì là kỳ nghỉ dài nên điểm du lịch đông nghịt.', 7402, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16818, 'この えは ピカソに よって かかれました。', 'kono e wa pikaso ni yotte kakaremashita.', NULL, 'Bức tranh này được vẽ bởi Picasso.', 6586, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18451, 'ゆうめいな かしゅが くる とあって、かいじょうは まんいんだ。', 'yuumei na kashu ga kuru to atte, kaijou wa man''in da.', NULL, 'Vì ca sĩ nổi tiếng đến nên hội trường chật kín.', 7402, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18452, 'あめも やんだ ことだし、そろそろ でかけようか。', 'ame mo yanda koto da shi, sorosoro dekakeyou ka.', NULL, 'Mưa cũng tạnh rồi, sắp đi thôi nhỉ.', 7403, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18453, 'みんな そろった ことだし、はじめましょう。', 'minna sorotta koto da shi, hajimemashou.', NULL, 'Mọi người đã đủ, bắt đầu thôi.', 7403, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18454, 'ゆめを かなえ んがため、かれは くにを でた。', 'yume o kanae nga tame, kare wa kuni o deta.', NULL, 'Để thực hiện ước mơ, anh ấy rời quê hương.', 7404, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18455, 'いきん がために はたらく。', 'ikin ga tame ni hataraku.', NULL, 'Làm việc để mà sống.', 7404, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18456, 'たいふうの ため、しあいは ちゅうしを よぎなく された。', 'taifuu no tame, shiai wa chuushi o yoginaku sareta.', NULL, 'Vì bão mà trận đấu buộc phải hủy.', 7405, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18457, 'けがで いんたいを よぎなく された。', 'kega de intai o yoginaku sareta.', NULL, 'Vì chấn thương mà buộc phải giải nghệ.', 7405, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18458, 'ちいさな くいちがいが、おおきな じけんに いたった。', 'chiisa na kuichigai ga, ookina jiken ni itatta.', NULL, 'Sai lệch nhỏ đã dẫn đến vụ việc lớn.', 7406, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18459, 'こどもから おとしよりに いたるまで、だれもが たのしめる。', 'kodomo kara otoshiyori ni itaru made, daremo ga tanoshimeru.', NULL, 'Từ trẻ em đến người già, ai cũng có thể vui chơi.', 7406, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18460, 'けいかくは ずさんで、けっきょく しっぱいに おわった。', 'keikaku wa zusan de, kekkyoku shippai ni owatta.', NULL, 'Kế hoạch cẩu thả, rốt cuộc kết thúc bằng thất bại.', 7407, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18461, 'はなしあいは まとまらず、けんかわかれに おわった。', 'hanashiai wa matomarazu, kenkawakare ni owatta.', NULL, 'Bàn bạc không đi đến đâu, kết cục chia tay trong cãi vã.', 7407, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18462, 'だいがくきょうじゅ とも あろう ひとが、そんな まちがいを するとは。', 'daigaku kyouju tomo arou hito ga, sonna machigai o suru to wa.', NULL, 'Một giáo sư đại học mà lại mắc lỗi như vậy.', 7408, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18463, 'けいさつかん とも あろう ものが はんざいを おかすなんて。', 'keisatsukan tomo arou mono ga hanzai o okasu nante.', NULL, 'Là cảnh sát mà lại phạm tội.', 7408, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18902, 'わたしは マイク・ミラーです。', 'Watashi wa Maiku Mirā desu.', NULL, 'Tôi là Mike Miller.', 7624, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18903, 'サントスさんは ブラジル人です。', 'Santosu-san wa Burajiru-jin desu.', NULL, 'Anh Santos là người Brazil.', 7624, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18904, 'サントスさんは 学生じゃ ありません。', 'Santosu-san wa gakusei ja arimasen.', NULL, 'Anh Santos không phải là sinh viên.', 7625, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18905, 'わたしは 先生では ありません。', 'Watashi wa sensei de wa arimasen.', NULL, 'Tôi không phải là giáo viên.', 7625, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18906, 'ミラーさんは アメリカ人ですか。…はい、アメリカ人です。', 'Mirā-san wa Amerika-jin desu ka. … Hai, Amerika-jin desu.', NULL, 'Anh Miller là người Mỹ phải không? … Vâng, tôi là người Mỹ.', 7626, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18907, 'あの 方は どなたですか。…ワットさんです。', 'Ano kata wa donata desu ka. … Watto-san desu.', NULL, 'Vị kia là ai vậy? … Là anh Watt.', 7626, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18908, 'ミラーさんは 会社員です。グプタさんも 会社員です。', 'Mirā-san wa kaishain desu. Guputa-san mo kaishain desu.', NULL, 'Anh Miller là nhân viên công ty. Anh Gupta cũng là nhân viên công ty.', 7627, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18909, 'わたしも 学生です。', 'Watashi mo gakusei desu.', NULL, 'Tôi cũng là sinh viên.', 7627, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18910, 'ミラーさんは IMCの 社員です。', 'Mirā-san wa Ai-emu-shī no shain desu.', NULL, 'Anh Miller là nhân viên công ty IMC.', 7628, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18911, 'わたしは さくら大学の 学生です。', 'Watashi wa Sakura Daigaku no gakusei desu.', NULL, 'Tôi là sinh viên Đại học Sakura.', 7628, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18912, 'あの 方は 木村さんです。', 'Ano kata wa Kimura-san desu.', NULL, 'Vị kia là chị Kimura.', 7629, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18913, 'テレサちゃんは 何歳ですか。…9歳です。', 'Teresa-chan wa nan-sai desu ka. … Kyū-sai desu.', NULL, 'Bé Teresa mấy tuổi? … 9 tuổi.', 7629, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18914, 'これは 辞書です。', 'Kore wa jisho desu.', NULL, 'Đây là cuốn từ điển.', 7630, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18915, 'それは わたしの 傘です。', 'Sore wa watashi no kasa desu.', NULL, 'Đó là cái ô của tôi.', 7630, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18916, 'この 本は わたしのです。', 'Kono hon wa watashi no desu.', NULL, 'Quyển sách này là của tôi.', 7631, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18917, 'あの 方は どなたですか。', 'Ano kata wa donata desu ka.', NULL, 'Vị kia là ai vậy?', 7631, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18918, 'それは テレホンカードですか。…はい、そうです。', 'Sore wa terehon kādo desu ka. … Hai, sō desu.', NULL, 'Đó là thẻ điện thoại phải không? … Vâng, đúng vậy.', 7632, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18919, 'これは ボールペンですか。…いいえ、ちがいます。シャープペンシルです。', 'Kore wa bōrupen desu ka. … Iie, chigaimasu. Shāpu penshiru desu.', NULL, 'Đây là bút bi phải không? … Không, không phải. Là bút chì kim.', 7632, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18920, 'これは 「9」ですか、「7」ですか。…「9」です。', 'Kore wa "kyū" desu ka, "nana" desu ka. … "Kyū" desu.', NULL, 'Đây là số 9 hay số 7? … Là số 9.', 7633, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18921, 'これは コンピューターの 本です。', 'Kore wa konpyūtā no hon desu.', NULL, 'Đây là sách về máy tính.', 7634, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18922, 'あれは だれの かばんですか。…佐藤さんのです。', 'Are wa dare no kaban desu ka. … Satō-san no desu.', NULL, 'Kia là cặp của ai? … Của chị Sato.', 7634, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18923, 'この 傘は あなたのですか。…いいえ、シュミットさんのです。…そうですか。', 'Kono kasa wa anata no desu ka. … Iie, Shumitto-san no desu. … Sō desu ka.', NULL, 'Cái ô này là của bạn à? … Không, của anh Schmidt. … Thế à.', 7635, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18924, 'ここは 食堂です。', 'Koko wa shokudō desu.', NULL, 'Đây là nhà ăn.', 7636, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18925, 'エレベーターは あそこです。', 'Erebētā wa asoko desu.', NULL, 'Thang máy ở đằng kia.', 7636, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18926, 'トイレは どこですか。…あそこです。', 'Toire wa doko desu ka. … Asoko desu.', NULL, 'Nhà vệ sinh ở đâu? … Ở đằng kia.', 7637, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18927, '電話は どちらですか。…2階です。', 'Denwa wa dochira desu ka. … Ni-kai desu.', NULL, 'Điện thoại ở đâu ạ? … Ở tầng 2.', 7637, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18928, 'お国は どちらですか。…アメリカです。', 'O-kuni wa dochira desu ka. … Amerika desu.', NULL, 'Anh đến từ nước nào ạ? … Từ Mỹ.', 7638, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18929, '会社は どちらですか。…IMCです。', 'Kaisha wa dochira desu ka. … Ai-emu-shī desu.', NULL, 'Anh làm ở công ty nào ạ? … Công ty IMC.', 7638, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18930, 'これは どこの 時計ですか。…日本の 時計です。', 'Kore wa doko no tokei desu ka. … Nihon no tokei desu.', NULL, 'Đây là đồng hồ của nước nào? … Đồng hồ Nhật.', 7639, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18931, 'それは どこの コンピューターですか。…パワー電気の コンピューターです。', 'Sore wa doko no konpyūtā desu ka. … Pawā Denki no konpyūtā desu.', NULL, 'Đó là máy tính của hãng nào? … Máy tính của hãng Power Denki.', 7639, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18932, 'この ネクタイは いくらですか。…1,500円です。', 'Kono nekutai wa ikura desu ka. … Sen-gohyaku-en desu.', NULL, 'Cái cà vạt này bao nhiêu tiền? … 1.500 yên.', 7640, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18933, 'すみません、これは いくらですか。…3,800円です。', 'Sumimasen, kore wa ikura desu ka. … Sanzen-happyaku-en desu.', NULL, 'Xin lỗi, cái này giá bao nhiêu? … 3.800 yên.', 7640, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18934, '今 何時ですか。…7時10分です。', 'Ima nan-ji desu ka. … Shichi-ji juppun desu.', NULL, 'Bây giờ là mấy giờ? … 7 giờ 10 phút.', 7641, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18935, 'ニューヨークは 今 午前4時です。', 'Nyūyōku wa ima gozen yo-ji desu.', NULL, 'Ở New York bây giờ là 4 giờ sáng.', 7641, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18936, '毎朝 6時に 起きます。', 'Maiasa roku-ji ni okimasu.', NULL, 'Sáng nào tôi cũng dậy lúc 6 giờ.', 7642, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18937, 'きのう 勉強しませんでした。', 'Kinō benkyō shimasen deshita.', NULL, 'Hôm qua tôi đã không học.', 7642, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18938, '6時半に 起きます。', 'Roku-ji han ni okimasu.', NULL, 'Tôi dậy lúc 6 rưỡi.', 7643, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18939, '日曜日に 休みます。', 'Nichiyōbi ni yasumimasu.', NULL, 'Chủ nhật tôi nghỉ.', 7643, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18940, '9時から 5時まで 働きます。', 'Ku-ji kara go-ji made hatarakimasu.', NULL, 'Tôi làm việc từ 9 giờ đến 5 giờ.', 7644, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18941, '銀行は 9時から 3時までです。', 'Ginkō wa ku-ji kara san-ji made desu.', NULL, 'Ngân hàng mở cửa từ 9 giờ đến 3 giờ.', 7644, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18942, '銀行の 休みは 土曜日と 日曜日です。', 'Ginkō no yasumi wa doyōbi to nichiyōbi desu.', NULL, 'Ngân hàng nghỉ thứ Bảy và Chủ nhật.', 7645, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18943, '毎日 10時まで 勉強します。…大変ですね。', 'Mainichi jū-ji made benkyō shimasu. … Taihen desu ne.', NULL, 'Ngày nào tôi cũng học đến 10 giờ. … Vất vả nhỉ.', 7646, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18944, '京都へ 行きます。', 'Kyōto e ikimasu.', NULL, 'Tôi đi Kyoto.', 7647, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18945, 'きのう うちへ 帰りませんでした。', 'Kinō uchi e kaerimasen deshita.', NULL, 'Hôm qua tôi đã không về nhà.', 7647, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18946, 'きのう どこも 行きませんでした。', 'Kinō doko mo ikimasen deshita.', NULL, 'Hôm qua tôi không đi đâu cả.', 7648, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18947, '電車で 行きます。', 'Densha de ikimasu.', NULL, 'Tôi đi bằng tàu điện.', 7649, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18948, '駅から 歩いて 帰りました。', 'Eki kara aruite kaerimashita.', NULL, 'Tôi đã đi bộ từ ga về.', 7649, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18949, '家族と 日本へ 来ました。', 'Kazoku to Nihon e kimashita.', NULL, 'Tôi đã đến Nhật cùng gia đình.', 7650, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18950, '一人で 東京へ 行きます。', 'Hitori de Tōkyō e ikimasu.', NULL, 'Tôi đi Tokyo một mình.', 7650, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18951, 'いつ 日本へ 来ましたか。…3月25日に 来ました。', 'Itsu Nihon e kimashita ka. … San-gatsu nijūgo-nichi ni kimashita.', NULL, 'Bạn đến Nhật khi nào? … Tôi đến ngày 25 tháng 3.', 7651, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18952, 'この 電車は 甲子園へ 行きますか。…いいえ、行きません。次の 「普通」ですよ。', 'Kono densha wa Kōshien e ikimasu ka. … Iie, ikimasen. Tsugi no "futsū" desu yo.', NULL, 'Tàu này có đi Koshien không? … Không đâu. Chuyến tàu thường tiếp theo cơ.', 7652, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18953, 'ジュースを 飲みます。', 'Jūsu o nomimasu.', NULL, 'Tôi uống nước hoa quả.', 7653, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18954, '毎朝 新聞を 読みます。', 'Maiasa shinbun o yomimasu.', NULL, 'Sáng nào tôi cũng đọc báo.', 7653, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18955, 'サッカーを します。', 'Sakkā o shimasu.', NULL, 'Tôi chơi bóng đá.', 7654, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18956, '友達と パーティーを します。', 'Tomodachi to pātī o shimasu.', NULL, 'Tôi tổ chức tiệc với bạn bè.', 7654, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18957, '日曜日 何を しますか。…京都へ 行きます。', 'Nichiyōbi nani o shimasu ka. … Kyōto e ikimasu.', NULL, 'Chủ nhật bạn làm gì? … Tôi đi Kyoto.', 7655, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18958, 'けさ 何も 食べませんでした。', 'Kesa nani mo tabemasen deshita.', NULL, 'Sáng nay tôi không ăn gì cả.', 7655, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18959, '駅で 新聞を 買います。', 'Eki de shinbun o kaimasu.', NULL, 'Tôi mua báo ở nhà ga.', 7656, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18960, 'どこで その かばんを 買いましたか。…デパートで 買いました。', 'Doko de sono kaban o kaimashita ka. … Depāto de kaimashita.', NULL, 'Bạn mua cái cặp đó ở đâu? … Tôi mua ở cửa hàng bách hóa.', 7656, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18961, 'いっしょに 京都へ 行きませんか。…ええ、いいですね。', 'Issho ni Kyōto e ikimasen ka. … Ē, ii desu ne.', NULL, 'Cùng đi Kyoto không? … Ừ, hay đấy.', 7657, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18962, 'ちょっと 休みましょう。', 'Chotto yasumimashō.', NULL, 'Nghỉ một chút nào.', 7658, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18963, 'ロビーで 会いましょう。', 'Robī de aimashō.', NULL, 'Gặp nhau ở sảnh nhé.', 7658, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18964, 'はしで 食べます。', 'Hashi de tabemasu.', NULL, 'Tôi ăn bằng đũa.', 7659, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18965, '日本語で レポートを 書きます。', 'Nihongo de repōto o kakimasu.', NULL, 'Tôi viết báo cáo bằng tiếng Nhật.', 7659, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18966, '「ありがとう」は 英語で 何ですか。…「Thank you」です。', '"Arigatō" wa Eigo de nan desu ka. … "Thank you" desu.', NULL, '"Arigatou" tiếng Anh là gì? … Là "Thank you".', 7660, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18967, '木村さんに 花を あげました。', 'Kimura-san ni hana o agemashita.', NULL, 'Tôi đã tặng hoa cho chị Kimura.', 7661, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18968, 'イーさんに 本を 貸しました。', 'Ī-san ni hon o kashimashita.', NULL, 'Tôi đã cho anh Lee mượn sách.', 7661, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18969, '木村さんは 山田さんに 花を もらいました。', 'Kimura-san wa Yamada-san ni hana o moraimashita.', NULL, 'Chị Kimura đã nhận hoa từ anh Yamada.', 7662, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18970, 'カリナさんに CDを 借りました。', 'Karina-san ni shī-dī o karimashita.', NULL, 'Tôi đã mượn đĩa CD của chị Karina.', 7662, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18971, 'もう 荷物を 送りましたか。…はい、もう 送りました。', 'Mō nimotsu o okurimashita ka. … Hai, mō okurimashita.', NULL, 'Bạn đã gửi hành lý chưa? … Rồi, tôi gửi rồi.', 7663, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18972, 'もう 昼ごはんを 食べましたか。…いいえ、まだです。', 'Mō hirugohan o tabemashita ka. … Iie, mada desu.', NULL, 'Bạn ăn trưa chưa? … Chưa.', 7663, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18973, 'ワット先生は 親切です。', 'Watto-sensei wa shinsetsu desu.', NULL, 'Thầy Watt rất tử tế.', 7664, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18974, '富士山は 高いです。', 'Fujisan wa takai desu.', NULL, 'Núi Phú Sĩ cao.', 7664, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18975, 'この 本は おもしろくないです。', 'Kono hon wa omoshirokunai desu.', NULL, 'Quyển sách này không hay.', 7664, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18976, 'ワット先生は 親切な 先生です。', 'Watto-sensei wa shinsetsu na sensei desu.', NULL, 'Thầy Watt là giáo viên tử tế.', 7665, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18977, '富士山は 高い 山です。', 'Fujisan wa takai yama desu.', NULL, 'Núi Phú Sĩ là ngọn núi cao.', 7665, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18978, '北京は とても 寒いです。', 'Pekin wa totemo samui desu.', NULL, 'Bắc Kinh rất lạnh.', 7666, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18979, 'この 映画は あまり おもしろくないです。', 'Kono eiga wa amari omoshirokunai desu.', NULL, 'Bộ phim này không hay lắm.', 7666, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18980, '日本の 生活は どうですか。…楽しいです。', 'Nihon no seikatsu wa dō desu ka. … Tanoshii desu.', NULL, 'Cuộc sống ở Nhật thế nào? … Vui lắm.', 7667, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18981, '奈良は どんな 町ですか。…古い 町です。', 'Nara wa donna machi desu ka. … Furui machi desu.', NULL, 'Nara là thành phố thế nào? … Là thành phố cổ.', 7667, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18982, '日本の 食べ物は おいしいですが、高いです。', 'Nihon no tabemono wa oishii desu ga, takai desu.', NULL, 'Đồ ăn Nhật ngon nhưng đắt.', 7668, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18983, 'ミラーさんの 傘は どれですか。…あの 青い 傘です。', 'Mirā-san no kasa wa dore desu ka. … Ano aoi kasa desu.', NULL, 'Ô của anh Miller là cái nào? … Là cái ô màu xanh kia.', 7669, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18984, 'わたしは 車が あります。', 'Watashi wa kuruma ga arimasu.', NULL, 'Tôi có ô tô.', 7670, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18985, 'わたしは 日本語が わかります。', 'Watashi wa Nihongo ga wakarimasu.', NULL, 'Tôi hiểu tiếng Nhật.', 7670, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18986, 'わたしは イタリア料理が 好きです。', 'Watashi wa Itaria ryōri ga suki desu.', NULL, 'Tôi thích món Ý.', 7671, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18987, 'マリアさんは ダンスが 上手です。', 'Maria-san wa dansu ga jōzu desu.', NULL, 'Chị Maria nhảy giỏi.', 7671, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18988, 'どんな スポーツが 好きですか。…サッカーが 好きです。', 'Donna supōtsu ga suki desu ka. … Sakkā ga suki desu.', NULL, 'Bạn thích môn thể thao nào? … Tôi thích bóng đá.', 7672, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18989, '英語が よく わかります。', 'Eigo ga yoku wakarimasu.', NULL, 'Tôi hiểu tiếng Anh rõ.', 7673, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18990, '韓国語が 全然 わかりません。', 'Kankokugo ga zenzen wakarimasen.', NULL, 'Tôi hoàn toàn không hiểu tiếng Hàn.', 7673, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18991, 'お金が たくさん あります。', 'Okane ga takusan arimasu.', NULL, 'Tôi có nhiều tiền.', 7673, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18992, '時間が ありませんから、新聞を 読みません。', 'Jikan ga arimasen kara, shinbun o yomimasen.', NULL, 'Vì không có thời gian nên tôi không đọc báo.', 7674, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18993, 'どうして 朝 新聞を 読みませんか。…時間が ありませんから。', 'Dōshite asa shinbun o yomimasen ka. … Jikan ga arimasen kara.', NULL, 'Tại sao buổi sáng bạn không đọc báo? … Vì không có thời gian.', 7675, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18994, 'どうして きのう 早く 帰りましたか。…用事が ありましたから。', 'Dōshite kinō hayaku kaerimashita ka. … Yōji ga arimashita kara.', NULL, 'Tại sao hôm qua bạn về sớm? … Vì tôi có việc bận.', 7675, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18995, 'コンピューターが あります。', 'Konpyūtā ga arimasu.', NULL, 'Có máy vi tính.', 7676, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18996, '男の 人が います。', 'Otoko no hito ga imasu.', NULL, 'Có người đàn ông.', 7676, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18997, 'わたしの 部屋に 机が あります。', 'Watashi no heya ni tsukue ga arimasu.', NULL, 'Trong phòng tôi có cái bàn.', 7677, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18998, '公園に 子どもが います。', 'Kōen ni kodomo ga imasu.', NULL, 'Trong công viên có trẻ con.', 7677, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (18999, '東京ディズニーランドは 千葉県に あります。', 'Tōkyō Dizunīrando wa Chiba-ken ni arimasu.', NULL, 'Tokyo Disneyland ở tỉnh Chiba.', 7678, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19000, 'ミラーさんは 事務所に います。', 'Mirā-san wa jimusho ni imasu.', NULL, 'Anh Miller ở văn phòng.', 7678, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19001, '机の 上に 写真が あります。', 'Tsukue no ue ni shashin ga arimasu.', NULL, 'Trên bàn có bức ảnh.', 7679, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19002, '郵便局は 銀行の となりです。', 'Yūbinkyoku wa ginkō no tonari desu.', NULL, 'Bưu điện ở bên cạnh ngân hàng.', 7679, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19003, '箱の 中に 手紙や 写真が あります。', 'Hako no naka ni tegami ya shashin ga arimasu.', NULL, 'Trong hộp có thư, ảnh…', 7680, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19004, '冷蔵庫に 卵や 牛乳などが あります。', 'Reizōko ni tamago ya gyūnyū nado ga arimasu.', NULL, 'Trong tủ lạnh có trứng, sữa v.v.', 7680, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19006, '外国人の 学生が 2人 います。', 'Gaikokujin no gakusei ga futari imasu.', NULL, 'Có 2 sinh viên nước ngoài.', 7681, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19007, '封筒を 3枚 ください。', 'Fūtō o san-mai kudasai.', NULL, 'Cho tôi 3 cái phong bì.', 7681, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19008, '1か月に 2回 映画を 見ます。', 'Ikkagetsu ni ni-kai eiga o mimasu.', NULL, 'Một tháng tôi xem phim 2 lần.', 7682, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19009, '1週間に 3回 テニスを します。', 'Isshūkan ni san-kai tenisu o shimasu.', NULL, 'Một tuần tôi chơi tennis 3 lần.', 7682, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19010, '東京から 大阪まで 新幹線で どのくらい かかりますか。…2時間半 かかります。', 'Tōkyō kara Ōsaka made Shinkansen de dono kurai kakarimasu ka. … Ni-jikan han kakarimasu.', NULL, 'Từ Tokyo đến Osaka bằng Shinkansen mất bao lâu? … Mất 2 tiếng rưỡi.', 7683, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19011, '学校に 先生が 30人ぐらい います。', 'Gakkō ni sensei ga sanjū-nin gurai imasu.', NULL, 'Ở trường có khoảng 30 giáo viên.', 7683, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19012, '休みは 日曜日だけです。', 'Yasumi wa nichiyōbi dake desu.', NULL, 'Ngày nghỉ chỉ có Chủ nhật.', 7684, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19013, 'パワー電気に 外国人の 社員が 1人だけ います。', 'Pawā Denki ni gaikokujin no shain ga hitori dake imasu.', NULL, 'Ở công ty Power Denki chỉ có 1 nhân viên người nước ngoài.', 7684, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19014, 'きのうは 雨でした。', 'Kinō wa ame deshita.', NULL, 'Hôm qua trời mưa.', 7685, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19015, '試験は 簡単じゃ ありませんでした。', 'Shiken wa kantan ja arimasen deshita.', NULL, 'Bài thi không dễ.', 7685, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19016, 'きのうは 暑かったです。', 'Kinō wa atsukatta desu.', NULL, 'Hôm qua trời nóng.', 7686, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19017, 'パーティーは あまり 楽しくなかったです。', 'Pātī wa amari tanoshikunakatta desu.', NULL, 'Bữa tiệc không vui lắm.', 7686, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19018, 'この 車は あの 車より 大きいです。', 'Kono kuruma wa ano kuruma yori ōkii desu.', NULL, 'Chiếc xe này to hơn chiếc xe kia.', 7687, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19019, '東京は 大阪より 人が 多いです。', 'Tōkyō wa Ōsaka yori hito ga ōi desu.', NULL, 'Tokyo đông người hơn Osaka.', 7687, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19020, 'サッカーと 野球と どちらが おもしろいですか。…サッカーの ほうが おもしろいです。', 'Sakkā to yakyū to dochira ga omoshiroi desu ka. … Sakkā no hō ga omoshiroi desu.', NULL, 'Bóng đá và bóng chày, môn nào thú vị hơn? … Bóng đá thú vị hơn.', 7688, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19021, '日本料理［の 中］で 何が いちばん おいしいですか。…てんぷらが いちばん おいしいです。', 'Nihon ryōri [no naka] de nani ga ichiban oishii desu ka. … Tenpura ga ichiban oishii desu.', NULL, 'Trong các món Nhật, món nào ngon nhất? … Tempura ngon nhất.', 7689, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19022, '1年で いつが いちばん 寒いですか。…2月が いちばん 寒いです。', 'Ichinen de itsu ga ichiban samui desu ka. … Ni-gatsu ga ichiban samui desu.', NULL, 'Trong một năm, khi nào lạnh nhất? … Tháng 2 lạnh nhất.', 7689, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19023, 'わたしは 友達が ほしいです。', 'Watashi wa tomodachi ga hoshii desu.', NULL, 'Tôi muốn có bạn.', 7690, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19024, '今 何が いちばん ほしいですか。…車が ほしいです。', 'Ima nani ga ichiban hoshii desu ka. … Kuruma ga hoshii desu.', NULL, 'Bây giờ bạn muốn có gì nhất? … Tôi muốn có ô tô.', 7690, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19025, 'わたしは 沖縄へ 行きたいです。', 'Watashi wa Okinawa e ikitai desu.', NULL, 'Tôi muốn đi Okinawa.', 7691, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19026, 'おなかが 痛いですから、何も 食べたくないです。', 'Onaka ga itai desu kara, nani mo tabetakunai desu.', NULL, 'Vì đau bụng nên tôi không muốn ăn gì cả.', 7691, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19027, '神戸へ インド料理を 食べに 行きます。', 'Kōbe e Indo ryōri o tabe ni ikimasu.', NULL, 'Tôi đi Kobe để ăn món Ấn Độ.', 7692, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19028, '京都へ 花見に 行きます。', 'Kyōto e hanami ni ikimasu.', NULL, 'Tôi đi Kyoto để ngắm hoa.', 7692, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19029, '冬休みは どこか［へ］ 行きましたか。…はい、北海道へ スキーに 行きました。', 'Fuyuyasumi wa dokoka [e] ikimashita ka. … Hai, Hokkaidō e sukī ni ikimashita.', NULL, 'Kỳ nghỉ đông bạn có đi đâu không? … Có, tôi đi Hokkaido trượt tuyết.', 7693, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19030, 'のどが かわきましたから、何か 飲みたいです。', 'Nodo ga kawakimashita kara, nanika nomitai desu.', NULL, 'Vì khát nên tôi muốn uống gì đó.', 7693, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19031, '書きます → 書いて、飲みます → 飲んで、待ちます → 待って', 'Kakimasu → kaite, nomimasu → nonde, machimasu → matte', NULL, 'viết, uống, đợi (thể て)', 7694, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19032, '食べます → 食べて、します → して、来ます → 来て', 'Tabemasu → tabete, shimasu → shite, kimasu → kite', NULL, 'ăn, làm, đến (thể て)', 7694, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19033, 'すみませんが、この 漢字の 読み方を 教えて ください。', 'Sumimasen ga, kono kanji no yomikata o oshiete kudasai.', NULL, 'Xin lỗi, hãy chỉ cho tôi cách đọc chữ Hán này.', 7695, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19034, 'ここに 住所と 名前を 書いて ください。', 'Koko ni jūsho to namae o kaite kudasai.', NULL, 'Hãy viết địa chỉ và tên vào đây.', 7695, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19035, 'ミラーさんは 今 電話を かけて います。', 'Mirā-san wa ima denwa o kakete imasu.', NULL, 'Anh Miller bây giờ đang gọi điện thoại.', 7696, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19036, '今 雨が 降って いますか。…はい、降って います。', 'Ima ame ga futte imasu ka. … Hai, futte imasu.', NULL, 'Bây giờ trời có đang mưa không? … Có, đang mưa.', 7696, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19037, '暑いですね。窓を 開けましょうか。…すみません。お願いします。', 'Atsui desu ne. Mado o akemashō ka. … Sumimasen. Onegai shimasu.', NULL, 'Nóng nhỉ. Để tôi mở cửa sổ nhé? … Cảm ơn. Nhờ anh.', 7697, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19038, '傘を 貸しましょうか。', 'Kasa o kashimashō ka.', NULL, 'Tôi cho bạn mượn ô nhé?', 7697, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19039, '写真を 撮っても いいですか。', 'Shashin o tottemo ii desu ka.', NULL, 'Tôi chụp ảnh có được không?', 7698, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19040, 'この 本を 借りても いいですか。…ええ、いいですよ。どうぞ。', 'Kono hon o karitemo ii desu ka. … Ē, ii desu yo. Dōzo.', NULL, 'Tôi mượn quyển sách này được không? … Ừ, được chứ. Cứ tự nhiên.', 7698, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19041, 'ここで たばこを 吸っては いけません。', 'Koko de tabako o sutte wa ikemasen.', NULL, 'Không được hút thuốc ở đây.', 7699, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19042, '先生、ここで 遊んでも いいですか。…いいえ、いけません。', 'Sensei, koko de asondemo ii desu ka. … Iie, ikemasen.', NULL, 'Thầy ơi, chơi ở đây được không ạ? … Không, không được.', 7699, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19043, 'わたしは 結婚して います。', 'Watashi wa kekkon shite imasu.', NULL, 'Tôi đã kết hôn.', 7700, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19044, 'マリアさんは 大阪に 住んで います。', 'Maria-san wa Ōsaka ni sunde imasu.', NULL, 'Chị Maria sống ở Osaka.', 7700, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19045, '田中さんの 電話番号を 知って いますか。…いいえ、知りません。', 'Tanaka-san no denwa bangō o shitte imasu ka. … Iie, shirimasen.', NULL, 'Bạn có biết số điện thoại của anh Tanaka không? … Không, tôi không biết.', 7700, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19046, 'IMCは コンピューターソフトを 作って います。', 'Ai-emu-shī wa konpyūtā sofuto o tsukutte imasu.', NULL, 'Công ty IMC sản xuất phần mềm máy tính.', 7701, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19047, '妹は 大学で 勉強して います。', 'Imōto wa daigaku de benkyō shite imasu.', NULL, 'Em gái tôi đang học đại học.', 7701, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19048, '朝 ジョギングを して、シャワーを 浴びて、会社へ 行きます。', 'Asa jogingu o shite, shawā o abite, kaisha e ikimasu.', NULL, 'Buổi sáng tôi chạy bộ, tắm rồi đi làm.', 7702, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19049, '神戸へ 行って、映画を 見て、お茶を 飲みました。', 'Kōbe e itte, eiga o mite, ocha o nomimashita.', NULL, 'Tôi đã đi Kobe, xem phim rồi uống trà.', 7702, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19050, 'ミラーさんは 若くて、元気です。', 'Mirā-san wa wakakute, genki desu.', NULL, 'Anh Miller trẻ và khỏe mạnh.', 7703, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19051, '奈良は 静かで、きれいな 町です。', 'Nara wa shizuka de, kirei na machi desu.', NULL, 'Nara là thành phố yên tĩnh và đẹp.', 7703, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19052, 'カリナさんは インドネシア人で、富士大学の 留学生です。', 'Karina-san wa Indoneshia-jin de, Fuji Daigaku no ryūgakusei desu.', NULL, 'Chị Karina là người Indonesia, là du học sinh Đại học Fuji.', 7703, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19053, '仕事が 終わって から、泳ぎに 行きます。', 'Shigoto ga owatte kara, oyogi ni ikimasu.', NULL, 'Sau khi xong việc, tôi đi bơi.', 7704, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19054, '毎晩 シャワーを 浴びて から、寝ます。', 'Maiban shawā o abite kara, nemasu.', NULL, 'Tối nào tôi cũng tắm xong rồi mới ngủ.', 7704, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19055, '大阪は 食べ物が おいしいです。', 'Ōsaka wa tabemono ga oishii desu.', NULL, 'Osaka đồ ăn ngon.', 7705, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19056, 'マリアさんは 髪が 長いです。', 'Maria-san wa kami ga nagai desu.', NULL, 'Chị Maria tóc dài.', 7705, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19057, '大学まで どうやって 行きますか。…京都駅から 16番の バスに 乗って、大学前で 降ります。', 'Daigaku made dōyatte ikimasu ka. … Kyōto-eki kara jūroku-ban no basu ni notte, Daigaku-mae de orimasu.', NULL, 'Đến trường đại học đi bằng cách nào? … Từ ga Kyoto đi xe buýt số 16, xuống ở bến Daigaku-mae.', 7706, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19058, 'ミラーさんは どの 人ですか。…あの 背が 高くて、髪が 黒い 人です。', 'Mirā-san wa dono hito desu ka. … Ano se ga takakute, kami ga kuroi hito desu.', NULL, 'Anh Miller là người nào? … Là người cao, tóc đen kia.', 7707, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19059, '行きます → 行かない、食べます → 食べない、します → しない', 'Ikimasu → ikanai, tabemasu → tabenai, shimasu → shinai', NULL, 'đi, ăn, làm (thể ない)', 7708, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19060, 'ここで 写真を 撮らないで ください。', 'Koko de shashin o toranaide kudasai.', NULL, 'Xin đừng chụp ảnh ở đây.', 7709, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19061, 'わたしは 元気ですから、心配しないで ください。', 'Watashi wa genki desu kara, shinpai shinaide kudasai.', NULL, 'Tôi khỏe nên xin đừng lo lắng.', 7709, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19062, '薬を 飲まなければ なりません。', 'Kusuri o nomanakereba narimasen.', NULL, 'Tôi phải uống thuốc.', 7710, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19063, '毎日 日本語を 勉強しなければ なりません。', 'Mainichi Nihongo o benkyō shinakereba narimasen.', NULL, 'Hằng ngày tôi phải học tiếng Nhật.', 7710, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19064, 'あした 来なくても いいです。', 'Ashita konakutemo ii desu.', NULL, 'Ngày mai không đến cũng được.', 7711, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19065, '名前を 書かなくても いいです。', 'Namae o kakanakutemo ii desu.', NULL, 'Không cần viết tên cũng được.', 7711, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19066, '荷物は ここに 置かないで ください。', 'Nimotsu wa koko ni okanaide kudasai.', NULL, 'Hành lý thì xin đừng để ở đây.', 7712, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19067, '昼ごはんは 会社の 食堂で 食べます。', 'Hirugohan wa kaisha no shokudō de tabemasu.', NULL, 'Bữa trưa thì tôi ăn ở nhà ăn công ty.', 7712, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19068, '会議は 5時までに 終わります。', 'Kaigi wa go-ji made ni owarimasu.', NULL, 'Cuộc họp sẽ kết thúc trước 5 giờ.', 7713, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19069, '土曜日までに 本を 返さなければ なりません。', 'Doyōbi made ni hon o kaesanakereba narimasen.', NULL, 'Tôi phải trả sách trước thứ Bảy.', 7713, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19070, '書きます → 書く、見ます → 見る、来ます → 来る', 'Kakimasu → kaku, mimasu → miru, kimasu → kuru', NULL, 'viết, xem, đến (thể từ điển)', 7714, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19071, 'ミラーさんは 漢字を 読む ことが できます。', 'Mirā-san wa kanji o yomu koto ga dekimasu.', NULL, 'Anh Miller có thể đọc chữ Hán.', 7715, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19072, 'カードで 払う ことが できます。', 'Kādo de harau koto ga dekimasu.', NULL, 'Có thể trả bằng thẻ.', 7715, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19073, 'ミラーさんは 日本語が できます。', 'Mirā-san wa Nihongo ga dekimasu.', NULL, 'Anh Miller biết tiếng Nhật.', 7715, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19074, 'わたしの 趣味は 音楽です。', 'Watashi no shumi wa ongaku desu.', NULL, 'Sở thích của tôi là âm nhạc.', 7716, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19075, 'わたしの 趣味は 音楽を 聞く ことです。', 'Watashi no shumi wa ongaku o kiku koto desu.', NULL, 'Sở thích của tôi là nghe nhạc.', 7716, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19076, '寝る まえに、本を 読みます。', 'Neru mae ni, hon o yomimasu.', NULL, 'Trước khi ngủ tôi đọc sách.', 7717, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19077, '食事の まえに、手を 洗います。', 'Shokuji no mae ni, te o araimasu.', NULL, 'Trước bữa ăn tôi rửa tay.', 7717, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19078, '田中さんは 1時間まえに 出かけました。', 'Tanaka-san wa ichi-jikan mae ni dekakemashita.', NULL, 'Anh Tanaka đã ra ngoài cách đây 1 tiếng.', 7717, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19079, '日本では なかなか 馬を 見る ことが できません。', 'Nihon de wa nakanaka uma o miru koto ga dekimasen.', NULL, 'Ở Nhật khó mà nhìn thấy ngựa.', 7718, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19080, 'ぜひ 北海道へ 行きたいです。', 'Zehi Hokkaidō e ikitai desu.', NULL, 'Tôi rất muốn đi Hokkaido.', 7719, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19081, 'ぜひ 遊びに 来て ください。', 'Zehi asobi ni kite kudasai.', NULL, 'Nhất định hãy đến chơi nhé.', 7719, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19082, '書いて → 書いた、飲んで → 飲んだ、来て → 来た', 'Kaite → kaita, nonde → nonda, kite → kita', NULL, 'viết, uống, đến (thể た)', 7720, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19083, '馬に 乗った ことが あります。', 'Uma ni notta koto ga arimasu.', NULL, 'Tôi đã từng cưỡi ngựa.', 7721, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19084, '北海道へ 行った ことが ありますか。…いいえ、一度も ありません。', 'Hokkaidō e itta koto ga arimasu ka. … Iie, ichido mo arimasen.', NULL, 'Bạn đã từng đi Hokkaido chưa? … Chưa, chưa lần nào.', 7721, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19085, '日曜日は テニスを したり、映画を 見たり します。', 'Nichiyōbi wa tenisu o shitari, eiga o mitari shimasu.', NULL, 'Chủ nhật tôi chơi tennis, xem phim v.v.', 7722, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19086, '夏休みは 泳いだり、山に 登ったり しました。', 'Natsuyasumi wa oyoidari, yama ni nobottari shimashita.', NULL, 'Kỳ nghỉ hè tôi đã bơi, leo núi v.v.', 7722, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19087, '寒く なりました。', 'Samuku narimashita.', NULL, 'Trời đã trở lạnh.', 7723, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19088, '元気に なりました。', 'Genki ni narimashita.', NULL, 'Tôi đã khỏe lại.', 7723, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19093, 'コーヒー、飲む？…うん、飲む。', 'Kōhī, nomu? … Un, nomu.', NULL, 'Uống cà phê không? … Ừ, uống.', 7725, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19094, 'あした ひま？…ううん、ひまじゃ ない。', 'Ashita hima? … Uun, hima ja nai.', NULL, 'Mai rảnh không? … Không, không rảnh.', 7725, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19095, 'その カレーライス、おいしい？…うん、辛いけど、おいしい。', 'Sono karē raisu, oishii? … Un, karai kedo, oishii.', NULL, 'Cơm cà ri đó ngon không? … Ừ, cay nhưng ngon.', 7726, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19096, 'あした 雨が 降ると 思います。', 'Ashita ame ga furu to omoimasu.', NULL, 'Tôi nghĩ ngày mai trời sẽ mưa.', 7727, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19097, 'ミラーさんは もう 帰ったと 思います。', 'Mirā-san wa mō kaetta to omoimasu.', NULL, 'Tôi nghĩ anh Miller đã về rồi.', 7727, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19098, '日本は 物価が 高いと 思います。', 'Nihon wa bukka ga takai to omoimasu.', NULL, 'Tôi nghĩ vật giá ở Nhật cao.', 7727, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19099, '新しい 空港に ついて どう 思いますか。…きれいですが、ちょっと 交通が 不便だと 思います。', 'Atarashii kūkō ni tsuite dō omoimasu ka. … Kirei desu ga, chotto kōtsū ga fuben da to omoimasu.', NULL, 'Bạn nghĩ thế nào về sân bay mới? … Đẹp nhưng tôi nghĩ giao thông hơi bất tiện.', 7728, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19100, '寝る まえに、「お休みなさい」と 言います。', 'Neru mae ni, "Oyasuminasai" to iimasu.', NULL, 'Trước khi ngủ, người ta nói "Oyasuminasai".', 7729, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19101, 'ミラーさんは 来週 東京へ 出張すると 言いました。', 'Mirā-san wa raishū Tōkyō e shutchō suru to iimashita.', NULL, 'Anh Miller nói tuần sau sẽ đi công tác Tokyo.', 7729, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19102, 'あした パーティーに 行くでしょう？…ええ、行きます。', 'Ashita pātī ni iku deshō? … Ē, ikimasu.', NULL, 'Mai bạn đi dự tiệc chứ? … Vâng, tôi đi.', 7730, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19103, '北海道は 寒かったでしょう？…いいえ、そんなに 寒くなかったです。', 'Hokkaidō wa samukatta deshō? … Iie, sonna ni samukunakatta desu.', NULL, 'Hokkaido lạnh lắm phải không? … Không, không lạnh lắm.', 7730, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19104, '東京で 日本と ブラジルの サッカーの 試合が あります。', 'Tōkyō de Nihon to Burajiru no sakkā no shiai ga arimasu.', NULL, 'Ở Tokyo có trận bóng đá giữa Nhật Bản và Brazil.', 7731, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19105, 'これは ミラーさんが 住んで いる うちです。', 'Kore wa Mirā-san ga sunde iru uchi desu.', NULL, 'Đây là ngôi nhà anh Miller đang sống.', 7732, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19106, '京都へ 行かない 人は ここに 集まって ください。', 'Kyōto e ikanai hito wa koko ni atsumatte kudasai.', NULL, 'Những ai không đi Kyoto hãy tập trung ở đây.', 7732, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19107, 'あの 眼鏡を かけて いる 人は だれですか。', 'Ano megane o kakete iru hito wa dare desu ka.', NULL, 'Người đeo kính kia là ai vậy?', 7732, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19108, 'これは ミラーさんが 作った ケーキです。', 'Kore wa Mirā-san ga tsukutta kēki desu.', NULL, 'Đây là cái bánh anh Miller làm.', 7733, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19109, 'わたしは カリナさんが かいた 絵が 好きです。', 'Watashi wa Karina-san ga kaita e ga suki desu.', NULL, 'Tôi thích bức tranh chị Karina vẽ.', 7733, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19110, 'わたしは 朝ごはんを 食べる 時間が ありません。', 'Watashi wa asagohan o taberu jikan ga arimasen.', NULL, 'Tôi không có thời gian ăn sáng.', 7734, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19111, 'きょうは 友達と 映画を 見る 約束が あります。', 'Kyō wa tomodachi to eiga o miru yakusoku ga arimasu.', NULL, 'Hôm nay tôi có hẹn đi xem phim với bạn.', 7734, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19112, '図書館で 本を 借りる とき、カードが 要ります。', 'Toshokan de hon o kariru toki, kādo ga irimasu.', NULL, 'Khi mượn sách ở thư viện thì cần thẻ.', 7735, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19113, '暇な とき、うちへ 遊びに 来ませんか。', 'Hima na toki, uchi e asobi ni kimasen ka.', NULL, 'Khi rảnh, bạn đến nhà tôi chơi không?', 7735, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19114, '子どもの とき、よく 川で 泳ぎました。', 'Kodomo no toki, yoku kawa de oyogimashita.', NULL, 'Hồi nhỏ tôi hay bơi ở sông.', 7735, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19115, '国へ 帰る とき、かばんを 買いました。', 'Kuni e kaeru toki, kaban o kaimashita.', NULL, 'Khi chuẩn bị về nước, tôi đã mua cặp (trước khi về).', 7736, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19116, '国へ 帰った とき、かばんを 買いました。', 'Kuni e kaetta toki, kaban o kaimashita.', NULL, 'Khi về đến nước, tôi đã mua cặp (ở quê nhà).', 7736, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19117, 'この ボタンを 押すと、お釣りが 出ます。', 'Kono botan o osu to, otsuri ga demasu.', NULL, 'Hễ ấn nút này thì tiền thừa sẽ ra.', 7737, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19118, 'これを 回すと、音が 大きく なります。', 'Kore o mawasu to, oto ga ōkiku narimasu.', NULL, 'Vặn cái này thì âm thanh to lên.', 7737, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19119, '右へ 曲がると、郵便局が あります。', 'Migi e magaru to, yūbinkyoku ga arimasu.', NULL, 'Rẽ phải thì có bưu điện.', 7737, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19120, '公園を 散歩します。', 'Kōen o sanpo shimasu.', NULL, 'Tôi đi dạo trong công viên.', 7738, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19121, '道を 渡ります。', 'Michi o watarimasu.', NULL, 'Tôi băng qua đường.', 7738, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19122, '交差点を 右へ 曲がります。', 'Kōsaten o migi e magarimasu.', NULL, 'Rẽ phải ở ngã tư.', 7738, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19123, '佐藤さんは わたしに クリスマスカードを くれました。', 'Satō-san wa watashi ni kurisumasu kādo o kuremashita.', NULL, 'Chị Sato đã gửi cho tôi thiệp Giáng sinh.', 7739, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19124, '母が この セーターを くれました。', 'Haha ga kono sētā o kuremashita.', NULL, 'Mẹ đã cho tôi cái áo len này.', 7739, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19125, 'わたしは 木村さんに 本を 貸して あげました。', 'Watashi wa Kimura-san ni hon o kashite agemashita.', NULL, 'Tôi đã cho chị Kimura mượn sách.', 7740, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19126, '妹に 写真を 見せて あげました。', 'Imōto ni shashin o misete agemashita.', NULL, 'Tôi đã cho em gái xem ảnh.', 7740, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19127, 'わたしは 山田さんに 図書館の 電話番号を 教えて もらいました。', 'Watashi wa Yamada-san ni toshokan no denwa bangō o oshiete moraimashita.', NULL, 'Tôi được anh Yamada cho biết số điện thoại thư viện.', 7741, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19128, '友達に 引っ越しを 手伝って もらいました。', 'Tomodachi ni hikkoshi o tetsudatte moraimashita.', NULL, 'Tôi được bạn giúp chuyển nhà.', 7741, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19129, '母は ［わたしに］ セーターを 送って くれました。', 'Haha wa [watashi ni] sētā o okutte kuremashita.', NULL, 'Mẹ đã gửi cho tôi cái áo len.', 7742, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19130, '佐藤さんが 駅まで 車で 送って くれました。', 'Satō-san ga eki made kuruma de okutte kuremashita.', NULL, 'Chị Sato đã đưa tôi ra ga bằng ô tô.', 7742, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19131, 'お金が あったら、旅行します。', 'Okane ga attara, ryokō shimasu.', NULL, 'Nếu có tiền tôi sẽ đi du lịch.', 7743, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19132, '時間が なかったら、テレビを 見ません。', 'Jikan ga nakattara, terebi o mimasen.', NULL, 'Nếu không có thời gian thì tôi không xem tivi.', 7743, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19133, '雨だったら、出かけません。', 'Ame dattara, dekakemasen.', NULL, 'Nếu trời mưa thì tôi không ra ngoài.', 7743, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19134, '10時に なったら、出かけましょう。', 'Jū-ji ni nattara, dekakemashō.', NULL, 'Đến 10 giờ thì ta ra ngoài nhé.', 7744, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19135, 'うちへ 帰ったら、すぐ シャワーを 浴びます。', 'Uchi e kaettara, sugu shawā o abimasu.', NULL, 'Về đến nhà là tôi tắm ngay.', 7744, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19136, '雨が 降っても、洗濯します。', 'Ame ga futtemo, sentaku shimasu.', NULL, 'Dù trời mưa tôi vẫn giặt đồ.', 7745, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19137, '安くても、わたしは グループ旅行が 嫌いです。', 'Yasukutemo, watashi wa gurūpu ryokō ga kirai desu.', NULL, 'Dù rẻ, tôi vẫn ghét du lịch theo đoàn.', 7745, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19138, '日曜日でも、働きます。', 'Nichiyōbi demo, hatarakimasu.', NULL, 'Dù là Chủ nhật tôi vẫn làm việc.', 7745, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19139, 'もし 1億円 あったら、いろいろな 国を 旅行したいです。', 'Moshi ichioku-en attara, iroiro na kuni o ryokō shitai desu.', NULL, 'Nếu có 100 triệu yên, tôi muốn du lịch nhiều nước.', 7746, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19140, 'いくら 考えても、わかりません。', 'Ikura kangaetemo, wakarimasen.', NULL, 'Nghĩ bao nhiêu cũng không hiểu.', 7746, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19141, '渡辺さんは 時々 大阪弁を 使いますね。大阪に 住んで いたんですか。…ええ、15歳まで 大阪に 住んで いました。', 'Watanabe-san wa tokidoki Ōsaka-ben o tsukaimasu ne. Ōsaka ni sunde itan desu ka. … Ē, jūgo-sai made Ōsaka ni sunde imashita.', NULL, 'Chị Watanabe thỉnh thoảng dùng tiếng Osaka nhỉ. Chị từng sống ở Osaka à? … Vâng, tôi sống ở Osaka đến năm 15 tuổi.', 7747, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19142, 'どうして 遅れたんですか。…バスが 来なかったんです。', 'Dōshite okuretan desu ka. … Basu ga konakattan desu.', NULL, 'Sao bạn đến muộn vậy? … Vì xe buýt không đến.', 7747, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19143, '日本語で 手紙を 書いたんですが、ちょっと 見て いただけませんか。', 'Nihongo de tegami o kaitan desu ga, chotto mite itadakemasen ka.', NULL, 'Tôi đã viết thư bằng tiếng Nhật, anh xem giúp một chút được không ạ?', 7748, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19144, '図書館へ 行きたいんですが、地図を 書いて いただけませんか。', 'Toshokan e ikitain desu ga, chizu o kaite itadakemasen ka.', NULL, 'Tôi muốn đến thư viện, anh vẽ giúp tôi bản đồ được không ạ?', 7748, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19145, '日本語が 上手に なりたいんですが、どう したら いいですか。', 'Nihongo ga jōzu ni naritain desu ga, dō shitara ii desu ka.', NULL, 'Tôi muốn giỏi tiếng Nhật, nên làm thế nào thì được?', 7749, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19146, 'ごみを 出したいんですが、どこに 出したら いいですか。', 'Gomi o dashitain desu ga, doko ni dashitara ii desu ka.', NULL, 'Tôi muốn đổ rác, đổ ở đâu thì được?', 7749, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19147, 'わたしは 日本語が 少し 話せます。', 'Watashi wa Nihongo ga sukoshi hanasemasu.', NULL, 'Tôi nói được một ít tiếng Nhật.', 7750, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19148, '1人で 着物が 着られますか。', 'Hitori de kimono ga kiraremasu ka.', NULL, 'Bạn có thể tự mặc kimono không?', 7750, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19149, '新幹線から 富士山が 見えます。', 'Shinkansen kara Fujisan ga miemasu.', NULL, 'Từ tàu Shinkansen nhìn thấy núi Phú Sĩ.', 7751, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19150, 'ラジオの 音が 聞こえます。', 'Rajio no oto ga kikoemasu.', NULL, 'Nghe thấy tiếng radio.', 7751, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19151, '新宿で 今 黒沢の 映画が 見られます。', 'Shinjuku de ima Kurosawa no eiga ga miraremasu.', NULL, 'Ở Shinjuku bây giờ có thể xem phim của Kurosawa.', 7751, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19152, '駅の 前に 大きい スーパーが できました。', 'Eki no mae ni ōkii sūpā ga dekimashita.', NULL, 'Trước nhà ga đã mọc lên một siêu thị lớn.', 7752, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19153, '時計の 修理は いつ できますか。', 'Tokei no shūri wa itsu dekimasu ka.', NULL, 'Khi nào sửa xong đồng hồ ạ?', 7752, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19154, 'ローマ字しか 書けません。', 'Rōmaji shika kakemasen.', NULL, 'Tôi chỉ viết được chữ La-tinh.', 7753, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19155, '財布に 500円しか ありません。', 'Saifu ni gohyaku-en shika arimasen.', NULL, 'Trong ví chỉ có 500 yên.', 7753, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19156, 'ワインは 飲みますが、ビールは 飲みません。', 'Wain wa nomimasu ga, bīru wa nomimasen.', NULL, 'Rượu vang thì tôi uống nhưng bia thì không.', 7754, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19157, 'きのうは 山が 見えましたが、きょうは 見えません。', 'Kinō wa yama ga miemashita ga, kyō wa miemasen.', NULL, 'Hôm qua thì nhìn thấy núi nhưng hôm nay thì không.', 7754, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19158, '音楽を 聞きながら 食事します。', 'Ongaku o kikinagara shokuji shimasu.', NULL, 'Tôi vừa nghe nhạc vừa ăn.', 7755, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19159, '働きながら 日本語を 勉強して います。', 'Hatarakinagara Nihongo o benkyō shite imasu.', NULL, 'Tôi vừa đi làm vừa học tiếng Nhật.', 7755, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19160, '毎朝 ジョギングを して います。', 'Maiasa jogingu o shite imasu.', NULL, 'Sáng nào tôi cũng chạy bộ.', 7756, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19161, '子どもの とき、毎晩 8時に 寝て いました。', 'Kodomo no toki, maiban hachi-ji ni nete imashita.', NULL, 'Hồi nhỏ, tối nào tôi cũng ngủ lúc 8 giờ.', 7756, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19162, '鈴木さんは ピアノも 弾けるし、歌も 歌えるし、ダンスも できます。', 'Suzuki-san wa piano mo hikeru shi, uta mo utaeru shi, dansu mo dekimasu.', NULL, 'Anh Suzuki vừa chơi được piano, vừa hát được, lại còn nhảy được.', 7757, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19163, 'この 店は 安いし、おいしいし、よく 来ます。', 'Kono mise wa yasui shi, oishii shi, yoku kimasu.', NULL, 'Quán này vừa rẻ lại ngon nên tôi hay đến.', 7757, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19164, 'この レストランは 値段も 安いし、味も いいんです。…それで 人が 多いんですね。', 'Kono resutoran wa nedan mo yasui shi, aji mo iin desu. … Sorede hito ga ōin desu ne.', NULL, 'Nhà hàng này giá rẻ, vị lại ngon. … Vì vậy mà đông khách nhỉ.', 7758, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19165, '窓が 割れて います。', 'Mado ga warete imasu.', NULL, 'Cửa sổ đang bị vỡ.', 7759, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19166, '電気が ついて います。', 'Denki ga tsuite imasu.', NULL, 'Đèn đang bật.', 7759, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19167, 'この 時計は 壊れて います。', 'Kono tokei wa kowarete imasu.', NULL, 'Cái đồng hồ này bị hỏng.', 7759, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19168, 'シュミットさんが 持って 来た ワインは みんなで 飲んで しまいました。', 'Shumitto-san ga motte kita wain wa minna de nonde shimaimashita.', NULL, 'Chai rượu anh Schmidt mang đến thì mọi người đã uống hết rồi.', 7760, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19169, '電車に 傘を 忘れて しまいました。', 'Densha ni kasa o wasurete shimaimashita.', NULL, 'Tôi lỡ để quên ô trên tàu điện mất rồi.', 7760, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19170, '昼ごはんまでに レポートを 書いて しまいます。', 'Hirugohan made ni repōto o kaite shimaimasu.', NULL, 'Trước bữa trưa tôi sẽ viết xong báo cáo.', 7760, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19171, '机の 上に メモが 置いて あります。', 'Tsukue no ue ni memo ga oite arimasu.', NULL, 'Trên bàn có để sẵn mẩu ghi chú.', 7761, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19172, 'カレンダーに 今月の 予定が 書いて あります。', 'Karendā ni kongetsu no yotei ga kaite arimasu.', NULL, 'Kế hoạch tháng này được ghi trên lịch.', 7761, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19173, 'メモは どこですか。…［メモは］ 机の 上に 置いて あります。', 'Memo wa doko desu ka. … [Memo wa] tsukue no ue ni oite arimasu.', NULL, 'Mẩu ghi chú ở đâu? … Được để trên bàn.', 7762, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19174, '旅行の まえに、切符を 買って おきます。', 'Ryokō no mae ni, kippu o katte okimasu.', NULL, 'Trước chuyến du lịch, tôi mua vé sẵn.', 7763, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19175, 'はさみを 使ったら、元の 所に 戻して おいて ください。', 'Hasami o tsukattara, moto no tokoro ni modoshite oite kudasai.', NULL, 'Dùng kéo xong thì hãy để lại chỗ cũ.', 7763, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19176, 'あした 会議が ありますから、いすは この ままに して おいて ください。', 'Ashita kaigi ga arimasu kara, isu wa kono mama ni shite oite kudasai.', NULL, 'Mai có họp nên hãy cứ để ghế nguyên như thế này.', 7763, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19177, 'まだ 雨が 降って います。', 'Mada ame ga futte imasu.', NULL, 'Trời vẫn còn đang mưa.', 7764, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19178, '道具を 片づけましょうか。…まだ 使って いますから、その ままに して おいて ください。', 'Dōgu o katazukemashō ka. … Mada tsukatte imasu kara, sono mama ni shite oite kudasai.', NULL, 'Tôi dọn dụng cụ nhé? … Tôi vẫn đang dùng nên cứ để nguyên đó.', 7764, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19179, 'ちょっと 休もうか。', 'Chotto yasumō ka.', NULL, 'Nghỉ một chút nhé?', 7765, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19180, '手伝おうか。', 'Tetsudaō ka.', NULL, 'Để tớ giúp nhé?', 7765, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19181, '週末は 海へ 行こうと 思って います。', 'Shūmatsu wa umi e ikō to omotte imasu.', NULL, 'Cuối tuần tôi định đi biển.', 7766, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19182, '今から 銀行へ 行こうと 思います。', 'Ima kara ginkō e ikō to omoimasu.', NULL, 'Bây giờ tôi định đi ngân hàng.', 7766, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19183, '国へ 帰っても、柔道を 続ける つもりです。', 'Kuni e kaettemo, jūdō o tsuzukeru tsumori desu.', NULL, 'Dù về nước tôi vẫn định tiếp tục học judo.', 7767, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19184, 'あしたからは たばこを 吸わない つもりです。', 'Ashita kara wa tabako o suwanai tsumori desu.', NULL, 'Từ mai tôi định không hút thuốc nữa.', 7767, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19185, '7月の 終わりに ドイツへ 出張する 予定です。', 'Shichi-gatsu no owari ni Doitsu e shutchō suru yotei desu.', NULL, 'Theo kế hoạch cuối tháng 7 tôi sẽ đi công tác Đức.', 7768, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19186, '旅行は 1週間ぐらいの 予定です。', 'Ryokō wa isshūkan gurai no yotei desu.', NULL, 'Chuyến du lịch dự kiến khoảng 1 tuần.', 7768, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19187, '銀行は まだ 開いて いません。', 'Ginkō wa mada aite imasen.', NULL, 'Ngân hàng vẫn chưa mở cửa.', 7769, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19188, 'レポートは もう 書きましたか。…いいえ、まだ 書いて いません。', 'Repōto wa mō kakimashita ka. … Iie, mada kaite imasen.', NULL, 'Bạn viết báo cáo chưa? … Chưa, tôi vẫn chưa viết.', 7769, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19189, '毎日 運動した ほうが いいです。', 'Mainichi undō shita hō ga ii desu.', NULL, 'Nên vận động mỗi ngày.', 7770, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19190, '熱が あるんです。…じゃ、おふろに 入らない ほうが いいですよ。', 'Netsu ga arun desu. … Ja, ofuro ni hairanai hō ga ii desu yo.', NULL, 'Tôi bị sốt. … Vậy thì không nên tắm bồn đâu.', 7770, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19191, 'あしたは 雨が 降るでしょう。', 'Ashita wa ame ga furu deshō.', NULL, 'Ngày mai có lẽ trời mưa.', 7771, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19192, 'タワポンさんは 合格するでしょうか。…きっと 合格するでしょう。', 'Tawapon-san wa gōkaku suru deshō ka. … Kitto gōkaku suru deshō.', NULL, 'Anh Thawaphon liệu có đỗ không? … Chắc chắn sẽ đỗ thôi.', 7771, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19193, '約束の 時間に 間に合わないかもしれません。', 'Yakusoku no jikan ni maniawanai kamo shiremasen.', NULL, 'Có lẽ tôi không kịp giờ hẹn.', 7772, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19194, '午後から 雪が 降るかもしれません。', 'Gogo kara yuki ga furu kamo shiremasen.', NULL, 'Có thể từ chiều tuyết sẽ rơi.', 7772, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19195, '駅まで 30分で 行けますか。', 'Eki made sanjuppun de ikemasu ka.', NULL, 'Đến ga trong vòng 30 phút có được không?', 7773, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19196, '3万円で ビデオが 買えますか。', 'Sanman-en de bideo ga kaemasu ka.', NULL, 'Với 30.000 yên có mua được máy video không?', 7773, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19197, '急げ。', 'Isoge.', NULL, 'Nhanh lên!', 7774, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19198, '頑張れ。', 'Ganbare.', NULL, 'Cố lên!', 7774, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19199, '触るな。', 'Sawaru na.', NULL, 'Không được chạm vào!', 7774, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19200, 'あの 漢字は 何と 読むんですか。…「きんえん」と 読みます。', 'Ano kanji wa nan to yomun desu ka. … "Kin''en" to yomimasu.', NULL, 'Chữ Hán kia đọc là gì vậy? … Đọc là "kin''en".', 7775, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19201, 'あそこに 「止まれ」と 書いて あります。', 'Asoko ni "Tomare" to kaite arimasu.', NULL, 'Ở đằng kia có viết là "Dừng lại".', 7775, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19202, '「立入禁止」は 入るな と いう 意味です。', '"Tachiiri kinshi" wa hairu na to iu imi desu.', NULL, '"Tachiiri kinshi" có nghĩa là cấm vào.', 7776, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19203, 'この マークは どういう 意味ですか。…洗濯機で 洗えると いう 意味です。', 'Kono māku wa dōiu imi desu ka. … Sentakuki de araeru to iu imi desu.', NULL, 'Ký hiệu này có nghĩa là gì? … Có nghĩa là có thể giặt bằng máy giặt.', 7776, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19204, '田中さんは 「あした 休みます」と 言って いました。', 'Tanaka-san wa "Ashita yasumimasu" to itte imashita.', NULL, 'Anh Tanaka đã nói là "Mai tôi nghỉ".', 7777, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19205, '田中さんは あした 休むと 言って いました。', 'Tanaka-san wa ashita yasumu to itte imashita.', NULL, 'Anh Tanaka nói là mai anh ấy nghỉ.', 7777, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19206, 'ワンさんに 「あとで 電話を ください」と 伝えて いただけませんか。', 'Wan-san ni "Ato de denwa o kudasai" to tsutaete itadakemasen ka.', NULL, 'Anh nhắn giúp anh Wang là "Lát nữa gọi điện cho tôi" được không ạ?', 7778, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19207, 'すみませんが、渡辺さんに あしたの パーティーは 6時からだと 伝えて いただけませんか。', 'Sumimasen ga, Watanabe-san ni ashita no pātī wa roku-ji kara da to tsutaete itadakemasen ka.', NULL, 'Xin lỗi, anh nhắn giúp chị Watanabe là bữa tiệc ngày mai bắt đầu từ 6 giờ được không ạ?', 7778, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19208, 'わたしが やった とおりに、やって ください。', 'Watashi ga yatta tōri ni, yatte kudasai.', NULL, 'Hãy làm đúng như tôi đã làm.', 7779, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19209, '線の とおりに、紙を 切って ください。', 'Sen no tōri ni, kami o kitte kudasai.', NULL, 'Hãy cắt giấy theo đường kẻ.', 7779, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19210, '新しいのを 買った あとで、なくした 時計が 見つかりました。', 'Atarashii no o katta ato de, nakushita tokei ga mitsukarimashita.', NULL, 'Sau khi mua cái mới thì lại tìm thấy cái đồng hồ đã mất.', 7780, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19211, '仕事の あとで、飲みに 行きませんか。', 'Shigoto no ato de, nomi ni ikimasen ka.', NULL, 'Sau giờ làm, đi uống không?', 7780, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19212, 'しょうゆを つけて 食べます。', 'Shōyu o tsukete tabemasu.', NULL, 'Chấm xì dầu rồi ăn.', 7781, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19213, 'しょうゆを つけないで 食べます。', 'Shōyu o tsukenaide tabemasu.', NULL, 'Ăn mà không chấm xì dầu.', 7781, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19214, '日曜日は どこも 行かないで、うちで ゆっくり 休みます。', 'Nichiyōbi wa doko mo ikanaide, uchi de yukkuri yasumimasu.', NULL, 'Chủ nhật tôi không đi đâu mà nghỉ ngơi thong thả ở nhà.', 7782, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19215, 'ボタンを 押せば、窓が 開きます。', 'Botan o oseba, mado ga akimasu.', NULL, 'Nếu ấn nút thì cửa sổ mở.', 7783, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19216, '天気が よければ、向こうに 島が 見えます。', 'Tenki ga yokereba, mukō ni shima ga miemasu.', NULL, 'Nếu trời đẹp thì nhìn thấy hòn đảo phía bên kia.', 7783, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19217, '安ければ、買います。', 'Yasukereba, kaimasu.', NULL, 'Nếu rẻ thì tôi mua.', 7783, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19218, '温泉に 行きたいんですが、どこか いい 所 ありませんか。…温泉なら、白馬が いいですよ。', 'Onsen ni ikitain desu ga, dokoka ii tokoro arimasen ka. … Onsen nara, Hakuba ga ii desu yo.', NULL, 'Tôi muốn đi suối nước nóng, có chỗ nào hay không? … Suối nước nóng thì Hakuba hay đấy.', 7784, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19219, '本を 借りたいんですが、どう すれば いいですか。', 'Hon o karitain desu ga, dō sureba ii desu ka.', NULL, 'Tôi muốn mượn sách, nên làm thế nào?', 7785, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19220, 'どこで 切符を 買えば いいですか。', 'Doko de kippu o kaeba ii desu ka.', NULL, 'Mua vé ở đâu thì được?', 7785, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19221, 'パソコンは 使えば 使うほど、便利に なります。', 'Pasokon wa tsukaeba tsukau hodo, benri ni narimasu.', NULL, 'Máy tính càng dùng càng thấy tiện.', 7786, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19222, '野菜は 新しければ 新しいほど おいしいです。', 'Yasai wa atarashikereba atarashii hodo oishii desu.', NULL, 'Rau càng tươi càng ngon.', 7786, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19223, '速く 泳げる ように、毎日 練習して います。', 'Hayaku oyogeru yō ni, mainichi renshū shite imasu.', NULL, 'Tôi luyện tập hằng ngày để có thể bơi nhanh.', 7787, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19224, '忘れない ように、メモして ください。', 'Wasurenai yō ni, memo shite kudasai.', NULL, 'Hãy ghi chú lại để không quên.', 7787, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19225, '毎日 練習すれば、泳げる ように なります。', 'Mainichi renshū sureba, oyogeru yō ni narimasu.', NULL, 'Nếu luyện tập hằng ngày thì sẽ bơi được.', 7788, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19226, 'やっと 自転車に 乗れる ように なりました。', 'Yatto jitensha ni noreru yō ni narimashita.', NULL, 'Cuối cùng tôi cũng đã đi được xe đạp.', 7788, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19227, '毎日 運動して、何でも 食べる ように して います。', 'Mainichi undō shite, nandemo taberu yō ni shite imasu.', NULL, 'Tôi cố gắng vận động hằng ngày và ăn mọi thứ.', 7789, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19228, '遅れない ように して ください。', 'Okurenai yō ni shite kudasai.', NULL, 'Hãy cố gắng đừng đến muộn.', 7789, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19229, 'わたしは 先生に 褒められました。', 'Watashi wa sensei ni homeraremashita.', NULL, 'Tôi được thầy khen.', 7790, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19230, 'わたしは 母に 買い物を 頼まれました。', 'Watashi wa haha ni kaimono o tanomaremashita.', NULL, 'Tôi bị mẹ nhờ đi mua đồ.', 7790, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19231, 'わたしは 弟に パソコンを 壊されました。', 'Watashi wa otōto ni pasokon o kowasaremashita.', NULL, 'Tôi bị em trai làm hỏng máy tính.', 7791, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19232, 'わたしは 犬に 手を かまれました。', 'Watashi wa inu ni te o kamaremashita.', NULL, 'Tôi bị chó cắn vào tay.', 7791, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19233, '大阪で 展覧会が 開かれました。', 'Ōsaka de tenrankai ga hirakaremashita.', NULL, 'Ở Osaka đã diễn ra một cuộc triển lãm.', 7792, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19234, 'この お寺は 600年前に 建てられました。', 'Kono otera wa roppyaku-nen mae ni tateraremashita.', NULL, 'Ngôi chùa này được xây cách đây 600 năm.', 7792, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19235, '「源氏物語」は 紫式部に よって 書かれました。', '"Genji Monogatari" wa Murasaki Shikibu ni yotte kakaremashita.', NULL, '"Truyện Genji" được viết bởi Murasaki Shikibu.', 7793, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19236, '電話は ベルに よって 発明されました。', 'Denwa wa Beru ni yotte hatsumei saremashita.', NULL, 'Điện thoại được Bell phát minh.', 7793, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19237, 'ビールは 麦から 造られます。', 'Bīru wa mugi kara tsukuraremasu.', NULL, 'Bia được làm từ lúa mạch.', 7794, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19238, '昔 日本の 家は 木で 造られました。', 'Mukashi Nihon no ie wa ki de tsukuraremashita.', NULL, 'Ngày xưa nhà ở Nhật được làm bằng gỗ.', 7794, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19239, 'テニスを するのは おもしろいです。', 'Tenisu o suru no wa omoshiroi desu.', NULL, 'Chơi tennis thì thú vị.', 7795, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19240, '1人で 夜 遅く 歩くのは 危ないです。', 'Hitori de yoru osoku aruku no wa abunai desu.', NULL, 'Đi bộ một mình vào đêm khuya thì nguy hiểm.', 7795, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19241, 'わたしは 花を 育てるのが 好きです。', 'Watashi wa hana o sodateru no ga suki desu.', NULL, 'Tôi thích trồng hoa.', 7796, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19242, '東京の 人は 歩くのが 速いです。', 'Tōkyō no hito wa aruku no ga hayai desu.', NULL, 'Người Tokyo đi bộ nhanh.', 7796, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19243, '鍵を かけるのを 忘れました。', 'Kagi o kakeru no o wasuremashita.', NULL, 'Tôi quên khóa cửa.', 7797, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19244, '牛乳を 買うのを 忘れました。', 'Gyūnyū o kau no o wasuremashita.', NULL, 'Tôi quên mua sữa.', 7797, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19245, '鈴木さんが 来月 結婚するのを 知って いますか。…いいえ、知りませんでした。', 'Suzuki-san ga raigetsu kekkon suru no o shitte imasu ka. … Iie, shirimasen deshita.', NULL, 'Bạn có biết anh Suzuki tháng sau kết hôn không? … Không, tôi không biết.', 7798, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19246, 'わたしが 生まれたのは 北海道の 小さい 町です。', 'Watashi ga umareta no wa Hokkaidō no chiisai machi desu.', NULL, 'Nơi tôi sinh ra là một thị trấn nhỏ ở Hokkaido.', 7799, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19247, '1年で いちばん 忙しいのは 12月です。', 'Ichinen de ichiban isogashii no wa jūni-gatsu desu.', NULL, 'Thời điểm bận nhất trong năm là tháng 12.', 7799, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19248, 'ニュースを 聞いて、びっくりしました。', 'Nyūsu o kiite, bikkuri shimashita.', NULL, 'Nghe tin tức, tôi đã giật mình.', 7800, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19249, '家族に 会えなくて、寂しいです。', 'Kazoku ni aenakute, sabishii desu.', NULL, 'Không gặp được gia đình nên tôi buồn.', 7800, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19250, '話が 複雑で、よく わかりませんでした。', 'Hanashi ga fukuzatsu de, yoku wakarimasen deshita.', NULL, 'Câu chuyện phức tạp nên tôi không hiểu rõ.', 7800, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19251, '地震で ビルが 倒れました。', 'Jishin de biru ga taoremashita.', NULL, 'Tòa nhà bị đổ do động đất.', 7801, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19252, '病気で 会社を 休みました。', 'Byōki de kaisha o yasumimashita.', NULL, 'Tôi nghỉ làm vì ốm.', 7801, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19253, '日本語が わからないので、英語で 話して いただけませんか。', 'Nihongo ga wakaranai node, Eigo de hanashite itadakemasen ka.', NULL, 'Vì tôi không hiểu tiếng Nhật nên anh nói bằng tiếng Anh được không ạ?', 7802, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15454, 'そんなことは起こり得ない。', 'Sonna koto wa okorienai.', NULL, 'Chuyện như thế không thể xảy ra.', 5904, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19254, '用事が あるので、お先に 失礼します。', 'Yōji ga aru node, osaki ni shitsurei shimasu.', NULL, 'Vì có việc bận nên tôi xin phép về trước.', 7802, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19255, 'JL107便は 何時に 着くか、調べて ください。', 'Jei-eru hyaku-nana-bin wa nan-ji ni tsuku ka, shirabete kudasai.', NULL, 'Hãy tra xem chuyến bay JL107 mấy giờ đến.', 7803, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19256, '結婚の お祝いは 何が いいか、話して います。', 'Kekkon no oiwai wa nani ga ii ka, hanashite imasu.', NULL, 'Chúng tôi đang bàn xem quà cưới nên tặng gì.', 7803, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19257, '忘年会に 出席するか どうか、20日までに 返事を ください。', 'Bōnenkai ni shusseki suru ka dō ka, hatsuka made ni henji o kudasai.', NULL, 'Hãy trả lời trước ngày 20 xem có dự tiệc cuối năm hay không.', 7804, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19258, 'その 話は 本当か どうか、わかりません。', 'Sono hanashi wa hontō ka dō ka, wakarimasen.', NULL, 'Tôi không biết câu chuyện đó có thật hay không.', 7804, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19259, 'もう 一度 考えて みます。', 'Mō ichido kangaete mimasu.', NULL, 'Tôi sẽ thử suy nghĩ lại một lần nữa.', 7805, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19260, 'この ズボンを はいて みても いいですか。', 'Kono zubon o haite mitemo ii desu ka.', NULL, 'Tôi mặc thử cái quần này được không?', 7805, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19261, '山の 高さは どうやって 測るか、知って いますか。', 'Yama no takasa wa dōyatte hakaru ka, shitte imasu ka.', NULL, 'Bạn có biết đo chiều cao của núi bằng cách nào không?', 7806, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19262, '新しい 橋の 長さは 3,911メートルです。', 'Atarashii hashi no nagasa wa sanzen-kyūhyaku-jūichi mētoru desu.', NULL, 'Chiều dài cây cầu mới là 3.911 mét.', 7806, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19263, 'わたしは 社長に お土産を いただきました。', 'Watashi wa shachō ni omiyage o itadakimashita.', NULL, 'Tôi đã nhận quà từ giám đốc.', 7807, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19264, '社長が わたしに お土産を くださいました。', 'Shachō ga watashi ni omiyage o kudasaimashita.', NULL, 'Giám đốc đã cho tôi quà.', 7807, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19265, 'わたしは 花に 水を やりました。', 'Watashi wa hana ni mizu o yarimashita.', NULL, 'Tôi đã tưới nước cho hoa.', 7807, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19266, 'わたしは 課長に 手紙の 間違いを 直して いただきました。', 'Watashi wa kachō ni tegami no machigai o naoshite itadakimashita.', NULL, 'Tôi được trưởng phòng sửa giúp lỗi trong thư.', 7808, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19267, '部長の 奥さんは ［わたしに］ お茶を 教えて くださいました。', 'Buchō no okusan wa [watashi ni] ocha o oshiete kudasaimashita.', NULL, 'Vợ của trưởng phòng đã dạy trà đạo cho tôi.', 7809, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19268, 'わたしは 息子に 紙飛行機を 作って やりました。', 'Watashi wa musuko ni kamihikōki o tsukutte yarimashita.', NULL, 'Tôi đã làm máy bay giấy cho con trai.', 7810, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19269, 'わたしは 犬を 散歩に 連れて 行って やりました。', 'Watashi wa inu o sanpo ni tsurete itte yarimashita.', NULL, 'Tôi đã dắt chó đi dạo.', 7810, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19270, 'コンサートの チケットを 予約して くださいませんか。', 'Konsāto no chiketto o yoyaku shite kudasaimasen ka.', NULL, 'Anh có thể đặt giúp tôi vé buổi hòa nhạc được không ạ?', 7811, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19271, '自分の 店を 持つ ために、貯金して います。', 'Jibun no mise o motsu tame ni, chokin shite imasu.', NULL, 'Tôi đang tiết kiệm để có cửa hàng riêng.', 7812, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19272, '健康の ために、毎朝 走って います。', 'Kenkō no tame ni, maiasa hashitte imasu.', NULL, 'Vì sức khỏe, sáng nào tôi cũng chạy bộ.', 7812, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19273, '家族の ために、うちを 建てます。', 'Kazoku no tame ni, uchi o tatemasu.', NULL, 'Tôi xây nhà vì gia đình.', 7812, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19274, 'この はさみは 花を 切るのに 使います。', 'Kono hasami wa hana o kiru no ni tsukaimasu.', NULL, 'Cái kéo này dùng để cắt hoa.', 7813, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19275, 'この かばんは 大きくて、旅行に 便利です。', 'Kono kaban wa ōkikute, ryokō ni benri desu.', NULL, 'Cái túi này to nên tiện cho việc đi du lịch.', 7813, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19276, '電話番号を 調べるのに 時間が かかりました。', 'Denwa bangō o shiraberu no ni jikan ga kakarimashita.', NULL, 'Tôi mất thời gian để tra số điện thoại.', 7813, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19277, '今にも 雨が 降りそうです。', 'Imanimo ame ga furisō desu.', NULL, 'Trời như sắp mưa đến nơi.', 7814, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19278, 'もうすぐ 桜が 咲きそうです。', 'Mōsugu sakura ga sakisō desu.', NULL, 'Hoa anh đào sắp nở rồi.', 7814, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19279, 'これから 寒く なりそうです。', 'Korekara samuku narisō desu.', NULL, 'Từ giờ có vẻ trời sẽ lạnh.', 7814, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19280, 'この 料理は 辛そうです。', 'Kono ryōri wa karasō desu.', NULL, 'Món này trông có vẻ cay.', 7815, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19281, '彼女は 頭が よさそうです。', 'Kanojo wa atama ga yosasō desu.', NULL, 'Cô ấy trông có vẻ thông minh.', 7815, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19282, 'ミラーさんは うれしそうです。', 'Mirā-san wa ureshisō desu.', NULL, 'Anh Miller trông có vẻ vui.', 7815, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19283, 'ちょっと たばこを 買って 来ます。', 'Chotto tabako o katte kimasu.', NULL, 'Tôi đi mua thuốc lá một chút rồi về.', 7816, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19284, 'スーパーで 牛乳を 買って 来ます。', 'Sūpā de gyūnyū o katte kimasu.', NULL, 'Tôi đi siêu thị mua sữa rồi về.', 7816, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19285, '台所から コップを 取って 来ます。', 'Daidokoro kara koppu o totte kimasu.', NULL, 'Tôi vào bếp lấy cái cốc.', 7816, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19286, 'ゆうべ お酒を 飲みすぎました。', 'Yūbe osake o nomisugimashita.', NULL, 'Tối qua tôi uống rượu quá nhiều.', 7817, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19287, 'この セーターは 大きすぎます。', 'Kono sētā wa ōkisugimasu.', NULL, 'Cái áo len này to quá.', 7817, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19288, 'この 問題は 簡単すぎます。', 'Kono mondai wa kantansugimasu.', NULL, 'Câu hỏi này dễ quá.', 7817, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19289, 'この パソコンは 使いやすいです。', 'Kono pasokon wa tsukaiyasui desu.', NULL, 'Máy tính này dễ sử dụng.', 7818, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19290, '東京は 住みにくいです。', 'Tōkyō wa suminikui desu.', NULL, 'Tokyo khó sống.', 7818, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19291, '白い シャツは 汚れやすいです。', 'Shiroi shatsu wa yogoreyasui desu.', NULL, 'Áo sơ mi trắng dễ bẩn.', 7818, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19292, '音を 大きく します。', 'Oto o ōkiku shimasu.', NULL, 'Tôi vặn to âm thanh.', 7819, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19293, '部屋を きれいに します。', 'Heya o kirei ni shimasu.', NULL, 'Tôi dọn phòng sạch sẽ.', 7819, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19294, '髪を 短く しました。', 'Kami o mijikaku shimashita.', NULL, 'Tôi đã cắt tóc ngắn.', 7819, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19295, '部屋は シングルに しますか、ツインに しますか。', 'Heya wa shinguru ni shimasu ka, tsuin ni shimasu ka.', NULL, 'Quý khách chọn phòng đơn hay phòng đôi?', 7820, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19296, '会議は あしたに します。', 'Kaigi wa ashita ni shimasu.', NULL, 'Cuộc họp quyết định để ngày mai.', 7820, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19297, '会議に 間に合わない 場合は、連絡して ください。', 'Kaigi ni maniawanai baai wa, renraku shite kudasai.', NULL, 'Trường hợp không kịp cuộc họp thì hãy liên lạc.', 7821, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19298, '火事の 場合は、エレベーターを 使わないで ください。', 'Kaji no baai wa, erebētā o tsukawanaide kudasai.', NULL, 'Trong trường hợp hỏa hoạn, xin đừng dùng thang máy.', 7821, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19299, '領収書が 必要な 場合は、言って ください。', 'Ryōshūsho ga hitsuyō na baai wa, itte kudasai.', NULL, 'Trường hợp cần hóa đơn thì xin hãy nói.', 7821, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19300, '約束を したのに、彼女は 来ませんでした。', 'Yakusoku o shita noni, kanojo wa kimasen deshita.', NULL, 'Đã hẹn rồi vậy mà cô ấy không đến.', 7822, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19301, 'きょうは 日曜日なのに、働かなければ なりません。', 'Kyō wa nichiyōbi na noni, hatarakanakereba narimasen.', NULL, 'Hôm nay là Chủ nhật vậy mà tôi phải làm việc.', 7822, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19302, 'これから 昼ごはんを 食べる ところです。', 'Korekara hirugohan o taberu tokoro desu.', NULL, 'Tôi sắp ăn trưa.', 7823, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19303, '今 故障の 原因を 調べて いる ところです。', 'Ima koshō no gen''in o shirabete iru tokoro desu.', NULL, 'Bây giờ tôi đang tìm nguyên nhân hỏng hóc.', 7823, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19304, 'たった今 バスが 出た ところです。', 'Tatta ima basu ga deta tokoro desu.', NULL, 'Xe buýt vừa mới chạy.', 7823, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19305, '木村さんは 先月 この 会社に 入った ばかりです。', 'Kimura-san wa sengetsu kono kaisha ni haitta bakari desu.', NULL, 'Chị Kimura mới vào công ty này tháng trước.', 7824, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19306, 'この 時計は 買った ばかりなのに、もう 壊れて しまいました。', 'Kono tokei wa katta bakari na noni, mō kowarete shimaimashita.', NULL, 'Cái đồng hồ này vừa mới mua vậy mà đã hỏng mất rồi.', 7824, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19307, 'ミラーさんは きょう 来る はずです。きのう 電話が ありましたから。', 'Mirā-san wa kyō kuru hazu desu. Kinō denwa ga arimashita kara.', NULL, 'Anh Miller chắc chắn hôm nay sẽ đến. Vì hôm qua anh ấy đã gọi điện.', 7825, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19308, '彼は 3年間 日本に いたから、日本語が 上手な はずです。', 'Kare wa sannenkan Nihon ni ita kara, Nihongo ga jōzu na hazu desu.', NULL, 'Anh ấy đã ở Nhật 3 năm nên chắc chắn giỏi tiếng Nhật.', 7825, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19309, '天気予報に よると、あしたは 寒く なるそうです。', 'Tenki yohō ni yoru to, ashita wa samuku naru sō desu.', NULL, 'Theo dự báo thời tiết, nghe nói mai trời sẽ lạnh.', 7826, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19310, 'クララさんは 子どもの とき、フランスに 住んで いたそうです。', 'Kurara-san wa kodomo no toki, Furansu ni sunde ita sō desu.', NULL, 'Nghe nói hồi nhỏ chị Klara sống ở Pháp.', 7826, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19311, '人が 大勢 集まって いますね。…事故のようですね。パトカーと 救急車が 来て いますよ。', 'Hito ga ōzei atsumatte imasu ne. … Jiko no yō desu ne. Patokā to kyūkyūsha ga kite imasu yo.', NULL, 'Nhiều người tụ tập nhỉ. … Hình như là tai nạn. Xe cảnh sát và xe cứu thương đang đến kìa.', 7827, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19312, '隣の 部屋に だれか いる ようです。', 'Tonari no heya ni dareka iru yō desu.', NULL, 'Hình như có ai đó ở phòng bên cạnh.', 7827, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19313, 'にぎやかな 声が しますね。', 'Nigiyaka na koe ga shimasu ne.', NULL, 'Có tiếng ồn ào nhỉ.', 7828, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19314, 'この 料理は 変な 味が します。', 'Kono ryōri wa hen na aji ga shimasu.', NULL, 'Món này có vị lạ.', 7828, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19315, 'いい においが します。', 'Ii nioi ga shimasu.', NULL, 'Có mùi thơm.', 7828, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19316, '部長は ミラーさんを アメリカへ 出張させます。', 'Buchō wa Mirā-san o Amerika e shutchō sasemasu.', NULL, 'Trưởng phòng cho anh Miller đi công tác Mỹ.', 7829, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19317, 'わたしは 娘を 自由に 遊ばせました。', 'Watashi wa musume o jiyū ni asobasemashita.', NULL, 'Tôi cho con gái chơi tự do.', 7829, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19318, '母は 子どもに 野菜を 食べさせました。', 'Haha wa kodomo ni yasai o tabesasemashita.', NULL, 'Mẹ bắt con ăn rau.', 7830, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19319, '先生は 学生に 作文を 書かせました。', 'Sensei wa gakusei ni sakubun o kakasemashita.', NULL, 'Thầy giáo bắt học sinh viết bài văn.', 7830, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19320, '気分が 悪いので、早く 帰らせて いただけませんか。', 'Kibun ga warui node, hayaku kaerasete itadakemasen ka.', NULL, 'Vì tôi thấy không khỏe nên cho phép tôi về sớm được không ạ?', 7831, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19321, 'この 資料を コピーさせて いただけませんか。', 'Kono shiryō o kopī sasete itadakemasen ka.', NULL, 'Cho phép tôi photo tài liệu này được không ạ?', 7831, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19322, '中村さんは 7時に 来られます。', 'Nakamura-san wa shichi-ji ni koraremasu.', NULL, 'Ông Nakamura sẽ đến lúc 7 giờ.', 7832, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19323, '社長は もう 帰られました。', 'Shachō wa mō kaeraremashita.', NULL, 'Giám đốc đã về rồi ạ.', 7832, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19324, '社長は もう お帰りに なりました。', 'Shachō wa mō okaeri ni narimashita.', NULL, 'Giám đốc đã về rồi ạ.', 7833, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19325, '先生は この 本を お読みに なりましたか。', 'Sensei wa kono hon o oyomi ni narimashita ka.', NULL, 'Thầy đã đọc cuốn sách này chưa ạ?', 7833, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19326, '社長は どちらに いらっしゃいますか。', 'Shachō wa dochira ni irasshaimasu ka.', NULL, 'Giám đốc đang ở đâu ạ?', 7834, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19327, '先生は 何を 召し上がりますか。', 'Sensei wa nani o meshiagarimasu ka.', NULL, 'Thầy dùng món gì ạ?', 7834, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19328, 'この 写真を ご覧に なりましたか。', 'Kono shashin o goran ni narimashita ka.', NULL, 'Ngài đã xem bức ảnh này chưa ạ?', 7834, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19329, 'どうぞ お入り ください。', 'Dōzo ohairi kudasai.', NULL, 'Xin mời vào.', 7835, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19330, '少々 お待ち ください。', 'Shōshō omachi kudasai.', NULL, 'Xin vui lòng chờ một chút.', 7835, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19331, 'こちらに ご記入 ください。', 'Kochira ni gokinyū kudasai.', NULL, 'Xin vui lòng điền vào đây.', 7835, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19332, '重そうですね。お持ちしましょうか。', 'Omosō desu ne. Omochi shimashō ka.', NULL, 'Trông nặng nhỉ. Để tôi xách giúp nhé?', 7836, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19333, 'わたしが 社長に スケジュールを ご連絡します。', 'Watashi ga shachō ni sukejūru o gorenraku shimasu.', NULL, 'Tôi sẽ thông báo lịch trình cho giám đốc.', 7836, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19334, '江戸東京博物館へ ご案内します。', 'Edo-Tōkyō Hakubutsukan e goannai shimasu.', NULL, 'Tôi xin dẫn quý vị đến Bảo tàng Edo-Tokyo.', 7836, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19335, 'あした 3時に 参ります。', 'Ashita san-ji ni mairimasu.', NULL, 'Ngày mai tôi sẽ đến lúc 3 giờ.', 7837, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19336, 'ミラーと 申します。', 'Mirā to mōshimasu.', NULL, 'Tôi tên là Miller.', 7837, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19337, '家族の 写真を 拝見しました。', 'Kazoku no shashin o haiken shimashita.', NULL, 'Tôi đã xem ảnh gia đình ngài.', 7837, NULL, 2);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19338, '電話は 階段の 横に ございます。', 'Denwa wa kaidan no yoko ni gozaimasu.', NULL, 'Điện thoại ở bên cạnh cầu thang ạ.', 7838, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (19339, 'こちらは IMCの 松本で ございます。', 'Kochira wa Ai-emu-shī no Matsumoto de gozaimasu.', NULL, 'Tôi là Matsumoto của công ty IMC ạ.', 7838, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15455, '誰にでも間違いはあり得る。', 'Dare ni demo machigai wa ariuru.', NULL, 'Ai cũng có thể mắc lỗi.', 5904, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15546, '冗談はさておき、本題に入りましょう。', 'Jōdan wa sateoki, hondai ni hairimashō.', NULL, 'Đùa vậy đủ rồi, ta vào vấn đề chính nào.', 5950, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15547, '結果はさておき、よく頑張ったと思う。', 'Kekka wa sateoki, yoku ganbatta to omou.', NULL, 'Kết quả tạm gác lại, tôi thấy cậu đã rất cố gắng.', 5950, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15559, '彼が社長に就いてから、経営方針が変わった。', 'Kare ga shachō ni tsuite kara, keiei hōshin ga kawatta.', NULL, 'Kể từ khi anh ấy lên chức giám đốc, phương châm kinh doanh đã thay đổi.', 5956, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15566, '企業は即戦力を求めている。', 'Kigyō wa sokusenryoku o motomete iru.', NULL, 'Doanh nghiệp đang tìm người có thể làm ngay.', 5960, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15585, '天気予報によれば、明日は雨が降るそうだ。', 'Tenki yohō ni yoreba, ashita wa ame ga furu sō da.', NULL, 'Theo dự báo thời tiết, nghe nói mai trời sẽ mưa.', 5969, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15589, 'その行為は国民の安全を危険にさらした。', 'Sono kōi wa kokumin no anzen o kiken ni sarashita.', NULL, 'Hành vi đó đặt an toàn của dân vào nguy hiểm.', 5971, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15600, '環境問題について論じ合った。', 'Kankyō mondai ni tsuite ronjiatta.', NULL, 'Chúng tôi đã bàn luận về vấn đề môi trường.', 5977, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15610, '容疑者は裁判にかけられた。', 'Yōgisha wa saiban ni kakerareta.', NULL, 'Nghi phạm đã bị đưa ra xét xử.', 5982, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15611, '両社は特許を裁判で争った。', 'Ryōsha wa tokkyo o saiban de arasotta.', NULL, 'Hai công ty đã tranh tụng về bằng sáng chế tại tòa.', 5982, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15613, '科学的方法で仮説を証明する。', 'Kagakuteki hōhō de kasetsu o shōmei suru.', NULL, 'Chứng minh giả thuyết bằng phương pháp khoa học.', 5983, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15625, '彼の話し方は特徴的だ。', 'Kare no hanashikata wa tokuchōteki da.', NULL, 'Cách nói chuyện của anh ấy rất đặc trưng.', 5989, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15626, '彼の役職は部長に相当する。', 'Kare no yakushoku wa buchō ni sōtō suru.', NULL, 'Chức vụ của anh ấy tương đương trưởng phòng.', 5990, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15627, '日本の高校3年生は、ベトナムの12年生に相当する。', 'Nihon no kōkō sannensei wa, Betonamu no jūni-nensei ni sōtō suru.', NULL, 'Học sinh năm 3 cấp ba ở Nhật tương đương lớp 12 ở Việt Nam.', 5990, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15628, '見え方は人によって異なる。', 'Miekata wa hito ni yotte kotonaru.', NULL, 'Cách nhìn khác nhau tùy người.', 5991, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15629, '制度は国により異なる。', 'Seido wa kuni ni yori kotonaru.', NULL, 'Thể chế khác nhau tùy quốc gia.', 5991, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15633, '改めてお礼を申し上げます。', 'Aratamete orei o mōshiagemasu.', NULL, 'Xin được một lần nữa cảm ơn.', 5993, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15636, '二人には共通の趣味がある。', 'Futari ni wa kyōtsū no shumi ga aru.', NULL, 'Hai người có chung sở thích.', 5995, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15638, '台風のため、出発の延期を余儀なくされた。', 'Taifū no tame, shuppatsu no enki o yoginaku sareta.', NULL, 'Vì bão nên buộc phải hoãn khởi hành.', 5996, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15645, '必要に迫られて、英語を勉強し始めた。', 'Hitsuyō ni semararete, eigo o benkyō shihajimeta.', NULL, 'Bị nhu cầu thúc ép nên tôi bắt đầu học tiếng Anh.', 5999, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15646, 'この本は日本の魅力を余すところなく伝えている。', 'Kono hon wa Nihon no miryoku o amasu tokoro naku tsutaete iru.', NULL, 'Cuốn sách này truyền tải trọn vẹn sức hấp dẫn của Nhật Bản.', 6000, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15647, '彼は持てる力を余すところなく発揮した。', 'Kare wa moteru chikara o amasu tokoro naku hakki shita.', NULL, 'Anh ấy đã phát huy trọn vẹn sức lực của mình.', 6000, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15650, 'この地域は医療資源に乏しい。', 'Kono chiiki wa iryō shigen ni toboshii.', NULL, 'Vùng này thiếu nguồn lực y tế.', 6002, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15651, '彼の説明は具体性に乏しかった。', 'Kare no setsumei wa gutaisei ni toboshikatta.', NULL, 'Lời giải thích của anh ấy thiếu tính cụ thể.', 6002, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15653, '試験時間を10分余して解き終えた。', 'Shiken jikan o juppun amashite tokioeta.', NULL, 'Tôi làm xong bài thi mà còn dư 10 phút.', 6003, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15658, '現状を踏まえて、計画を修正した。', 'Genjō o fumaete, keikaku o shūsei shita.', NULL, 'Căn cứ hiện trạng, đã sửa kế hoạch.', 6006, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15660, '成長を前提に、人員を増やす。', 'Seichō o zentei ni, jin''in o fuyasu.', NULL, 'Lấy tăng trưởng làm tiền đề, tăng nhân sự.', 6007, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15666, '彼の表情から、不安を推察した。', 'Kare no hyōjō kara, fuan o suisatsu shita.', NULL, 'Từ biểu cảm anh ấy, tôi suy đoán sự lo lắng.', 6010, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15667, '背景には政治的理由が推察される。', 'Haikei ni wa seijiteki riyū ga suisatsu sareru.', NULL, 'Có thể suy đoán phía sau là lý do chính trị.', 6010, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15674, '彼は無関心を装った。', 'Kare wa mukanshin o yosootta.', NULL, 'Anh ấy giả vờ không quan tâm.', 6014, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15675, '平静を装って、話を続けた。', 'Heisei o yosootte, hanashi o tsuzuketa.', NULL, 'Giả vờ bình tĩnh, tôi tiếp tục câu chuyện.', 6014, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15678, '危険を顧みず、前進した。', 'Kiken o kaerimizu, zenshin shita.', NULL, 'Bất chấp nguy hiểm, họ tiến lên phía trước.', 6016, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15682, '従来の方法とは異なるアプローチ。', 'Jūrai no hōhō to wa kotonaru apurōchi.', NULL, 'Cách tiếp cận khác với phương pháp truyền thống.', 6018, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15689, '改革以後、状況が改善した。', 'Kaikaku igo, jōkyō ga kaizen shita.', NULL, 'Sau cải cách, tình hình được cải thiện.', 6021, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15703, '新しい証拠が判決を覆した。', 'Atarashii shōko ga hanketsu o kutsugaeshita.', NULL, 'Bằng chứng mới đã lật ngược phán quyết.', 6028, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15706, '彼は現地の文化に溶け込んだ。', 'Kare wa genchi no bunka ni tokekonda.', NULL, 'Anh ấy hòa nhập văn hóa địa phương.', 6030, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15713, '都市が急速に膨張している。', 'Toshi ga kyūsoku ni bōchō shite iru.', NULL, 'Đô thị đang phình to nhanh chóng.', 6033, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15776, 'きれいに書いてください。', 'Kirei ni kaite kudasai.', NULL, 'Hãy viết cho đẹp.', 6065, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15796, '天気予報によると、明日は雨だそうです。', 'Tenki yohō ni yoru to, ashita wa ame da sō desu.', NULL, 'Theo dự báo thời tiết, nghe nói mai trời mưa.', 6075, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15797, '新聞によると、昨日大きな地震があったそうです。', 'Shinbun ni yoru to, kinō ōkina jishin ga atta sō desu.', NULL, 'Theo báo, hôm qua đã có một trận động đất lớn.', 6075, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15910, '急に雨が降り出した。', 'Kyū ni ame ga furidashita.', NULL, 'Đột nhiên trời bắt đầu mưa.', 6132, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15919, '一人では運び切れない。', 'Hitori de wa hakobikirenai.', NULL, 'Một mình thì không chở hết được.', 6136, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15931, '日本の歴史について調べています。', 'Nihon no rekishi ni tsuite shirabete imasu.', NULL, 'Tôi đang tìm hiểu về lịch sử Nhật Bản.', 6142, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15951, '話している最中に、電話が鳴った。', 'Hanashite iru saichū ni, denwa ga natta.', NULL, 'Đang nói chuyện giữa chừng thì điện thoại reo.', 6152, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15974, 'もっと時間があればいいのに。', 'Motto jikan ga areba ii noni.', NULL, 'Giá mà có thêm thời gian thì tốt.', 6164, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15975, '雨が降らなければいいのに。', 'Ame ga furanakereba ii noni.', NULL, 'Giá mà trời đừng mưa thì tốt.', 6164, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15976, 'だって、忙しいんだもの。', 'Datte, isogashii n da mono.', NULL, 'Thì tại bận mà.', 6165, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15977, '子供だもの、仕方ない。', 'Kodomo da mono, shikata nai.', NULL, 'Nó còn là trẻ con mà, đành chịu thôi.', 6165, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15978, '子供は元気なものだ。', 'Kodomo wa genki na mono da.', NULL, 'Trẻ con thì vốn hiếu động mà.', 6166, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15982, 'そんなこと、信じるものか。', 'Sonna koto, shinjiru mono ka.', NULL, 'Chuyện đó ai mà tin chứ.', 6168, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15983, '負けるもんか。', 'Makeru mon ka.', NULL, 'Tôi không đời nào chịu thua đâu.', 6168, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15986, 'どれほど嬉しかったことか。', 'Dore hodo ureshikatta koto ka.', NULL, 'Tôi đã vui biết bao!', 6170, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15987, '何度困ったことか。', 'Nando komatta koto ka.', NULL, 'Không biết đã bao nhiêu lần khổ sở!', 6170, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15990, '謝ったからといって許されたことにはならない。', 'Ayamatta kara to itte yurusareta koto ni wa naranai.', NULL, 'Xin lỗi rồi không có nghĩa là đã được tha thứ.', 6172, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15991, '書いただけで完成したことにはならない。', 'Kaita dake de kansei shita koto ni wa naranai.', NULL, 'Chỉ viết ra thôi không có nghĩa là đã hoàn thành.', 6172, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (15994, 'そんな高いものは買えるわけがない。', 'Sonna takai mono wa kaeru wake ga nai.', NULL, 'Đồ đắt như thế thì làm sao mà mua nổi.', 6174, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16004, '都市化が進む一方で、過疎化も進んでいる。', 'Toshika ga susumu ippō de, kasoka mo susunde iru.', NULL, 'Đô thị hóa tiến triển, mặt khác tình trạng nông thôn thưa dân cũng gia tăng.', 6179, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16009, '海外に行く際には、保険に入ってください。', 'Kaigai ni iku sai ni wa, hoken ni haitte kudasai.', NULL, 'Khi đi nước ngoài hãy mua bảo hiểm.', 6181, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16010, '忘れないうちに書き留めておこう。', 'Wasurenai uchi ni kakitomete okō.', NULL, 'Hãy ghi lại trước khi quên.', 6182, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16018, '想像し得る範囲内だ。', 'Sōzō shiuru han''inai da.', NULL, 'Trong phạm vi có thể tưởng tượng.', 6186, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16019, 'そんなことは起こり得ない。', 'Sonna koto wa okorienai.', NULL, 'Chuyện đó không thể xảy ra.', 6186, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16020, 'そのご提案はお受けしかねます。', 'Sono goteian wa oukeshikanemasu.', NULL, 'Khó mà chấp nhận đề xuất đó.', 6187, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16028, '彼は最後まで戦い抜いた。', 'Kare wa saigo made tatakainuita.', NULL, 'Anh ấy chiến đấu đến cùng.', 6191, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16031, '二人は顔を見合わせて笑った。', 'Futari wa kao o miawasete waratta.', NULL, 'Hai người nhìn nhau rồi cười.', 6192, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16034, '最後まで走り通した。', 'Saigo made hashiritōshita.', NULL, 'Chạy suốt đến cuối.', 6194, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16035, '彼は言い通すタイプだ。', 'Kare wa iitōsu taipu da.', NULL, 'Anh ấy kiểu cứ khăng khăng nói cho bằng được.', 6194, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16036, '資源を使い尽くしてしまった。', 'Shigen o tsukaitsukushite shimatta.', NULL, 'Tài nguyên đã bị dùng cạn kiệt.', 6195, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16037, 'この気持ちは言葉では言い尽くせない。', 'Kono kimochi wa kotoba de wa iitsukusenai.', NULL, 'Cảm xúc này không thể nói hết bằng lời.', 6195, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16042, 'そんなの勝つに決まってる。', 'Sonna no katsu ni kimatteru.', NULL, 'Thế thì chắc chắn thắng rồi.', 6198, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16046, 'やってみないものでもない。', 'Yatte minai mono demo nai.', NULL, 'Cũng không phải là không thử.', 6200, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16047, '彼なら解決できないものでもない。', 'Kare nara kaiketsu dekinai mono demo nai.', NULL, 'Nếu là anh ấy thì không phải là không giải quyết được.', 6200, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16050, '弟はゲームばかりして、ついには学校を休む始末だ。', 'Otōto wa gēmu bakari shite, tsui ni wa gakkō o yasumu shimatsu da.', NULL, 'Em trai suốt ngày chơi game, rốt cuộc đến mức nghỉ cả học.', 6202, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16051, '彼は飲みすぎて、道で寝てしまう始末だった。', 'Kare wa nomisugite, michi de nete shimau shimatsu datta.', NULL, 'Anh ta uống quá nhiều, đến nỗi ngủ luôn ngoài đường.', 6202, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16057, '細部に至るまで配慮されている。', 'Saibu ni itaru made hairyo sarete iru.', NULL, 'Được chăm chút đến từng chi tiết.', 6205, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16078, 'その光景には驚きを禁じ得ない。', 'Sono kōkei ni wa odoroki o kinjienai.', NULL, 'Không thể không ngạc nhiên trước cảnh đó.', 6216, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16100, 'その態度は失礼極まりない。', 'Sono taido wa shitsurei kiwamarinai.', NULL, 'Thái độ đó cực kỳ thất lễ.', 6227, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16101, '危険極まりない行為だ。', 'Kiken kiwamarinai kōi da.', NULL, 'Hành vi cực kỳ nguy hiểm.', 6227, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16103, '期待外れで残念な限りだ。', 'Kitai hazure de zannen na kagiri da.', NULL, 'Không như mong đợi, thật tiếc vô cùng.', 6228, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16106, '彼は遅刻ばかりして、ついには無断で欠勤する始末だ。', 'Kare wa chikoku bakari shite, tsui ni wa mudan de kekkin suru shimatsu da.', NULL, 'Anh ta toàn đi muộn, rốt cuộc còn nghỉ làm không xin phép.', 6230, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16107, '息子は勉強もせず、親に嘘までつく始末だ。', 'Musuko wa benkyō mo sezu, oya ni uso made tsuku shimatsu da.', NULL, 'Con trai chẳng học hành, đến nỗi còn nói dối cả bố mẹ.', 6230, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16113, '彼はチームにとって欠くべからざる存在だ。', 'Kare wa chīmu ni totte kakubekarazaru sonzai da.', NULL, 'Anh ấy là người không thể thiếu đối với đội.', 6233, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16116, '尋常ならざる事態が発生した。', 'Jinjō narazaru jitai ga hassei shita.', NULL, 'Đã xảy ra một tình huống bất thường.', 6235, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16117, 'それは容易ならざる問題だ。', 'Sore wa yōi narazaru mondai da.', NULL, 'Đó là một vấn đề không hề đơn giản.', 6235, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16127, '彼の安否が心配でならない。', 'Kare no anpi ga shinpai de naranai.', NULL, 'Tôi lo cho sự an nguy của anh ấy không yên.', 6240, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16139, '引っ越してからというもの、会えなくなった。', 'Hikkoshite kara to iu mono, aenaku natta.', NULL, 'Kể từ khi chuyển nhà, chúng tôi không gặp được nhau nữa.', 6246, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16141, '事故に遭って以来、慎重になった。', 'Jiko ni atte irai, shinchō ni natta.', NULL, 'Kể từ tai nạn trở nên thận trọng.', 6247, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16148, 'そんなに働いては、体を壊しますよ。', 'Sonna ni hataraite wa, karada o kowashimasu yo.', NULL, 'Làm việc kiểu đó thì sẽ hỏng người đấy.', 6251, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16150, 'いつまでも悲しんではいられない。', 'Itsumade mo kanashinde wa irarenai.', NULL, 'Không thể cứ buồn mãi được.', 6252, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16151, 'これ以上待ってはいられない。', 'Kore ijō matte wa irarenai.', NULL, 'Không thể chờ thêm được nữa.', 6252, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16154, '借金してまで買う必要はない。', 'Shakkin shite made kau hitsuyō wa nai.', NULL, 'Không cần đến mức phải vay nợ để mua.', 6254, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16155, '嘘をついてまで守りたいものはない。', 'Uso o tsuite made mamoritai mono wa nai.', NULL, 'Không có gì đáng để phải nói dối mà giữ lấy.', 6254, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16156, '徹夜してでも、明日までに終わらせたい。', 'Tetsuya shite demo, ashita made ni owarasetai.', NULL, 'Dù phải thức trắng đêm, tôi cũng muốn xong trước ngày mai.', 6255, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16157, '借金してでも、この夢を実現させたい。', 'Shakkin shite demo, kono yume o jitsugen sasetai.', NULL, 'Dù phải vay nợ, tôi cũng muốn thực hiện ước mơ này.', 6255, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16158, '待っていては始まらない。', 'Matte ite wa hajimaranai.', NULL, 'Chỉ ngồi chờ thì chẳng giải quyết được gì.', 6256, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16159, '言うだけでは始まらない。', 'Iu dake dewa hajimaranai.', NULL, 'Chỉ nói suông thì chẳng đi đến đâu.', 6256, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16164, '早めに予約するに越したことはない。', 'Hayame ni yoyaku suru ni koshita koto wa nai.', NULL, 'Đặt chỗ sớm vẫn là tốt nhất.', 6259, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16165, '健康に越したことはない。', 'Kenkō ni koshita koto wa nai.', NULL, 'Không gì bằng sức khỏe.', 6259, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16174, '彼の勝利に相違ない。', 'Kare no shōri ni sōi nai.', NULL, 'Đó chắc chắn là chiến thắng của anh ấy.', 6264, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16180, '彼女は75歳にして、初めてパソコンを習い始めた。', 'Kanojo wa nanajūgo-sai ni shite, hajimete pasokon o naraihajimeta.', NULL, 'Ở tuổi 75, bà ấy lần đầu tiên bắt đầu học máy tính.', 6267, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16181, '彼は医者にして作家でもある。', 'Kare wa isha ni shite sakka demo aru.', NULL, 'Ông ấy vừa là bác sĩ vừa là nhà văn.', 6267, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16182, '経験者にして初めて分かる苦労だ。', 'Keikensha ni shite hajimete wakaru kurō da.', NULL, 'Đó là nỗi vất vả chỉ người từng trải mới hiểu.', 6268, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16183, '一流の職人にして初めて作れる作品だ。', 'Ichiryū no shokunin ni shite hajimete tsukureru sakuhin da.', NULL, 'Đây là tác phẩm chỉ nghệ nhân hàng đầu mới làm ra được.', 6268, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16188, '社長にしたところで、この問題は解決できないだろう。', 'Shachō ni shita tokoro de, kono mondai wa kaiketsu dekinai darō.', NULL, 'Ngay cả giám đốc thì chắc cũng không giải quyết được vấn đề này.', 6271, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16189, '私にしたところで、詳しいことは知らない。', 'Watashi ni shita tokoro de, kuwashii koto wa shiranai.', NULL, 'Ngay cả tôi cũng không biết chi tiết.', 6271, NULL, 1);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16192, '調べたところが、新しい事実が判明した。', 'Shirabeta tokoro ga, atarashii jijitsu ga hanmei shita.', NULL, 'Điều tra thì phát hiện ra sự thật mới.', 6273, NULL, 0);
INSERT INTO public."Example" (id, jp, romaji, en, vi, "grammarId", "audioUrl", "sortOrder") VALUES (16193, '急いで駅まで走ったところが、電車はもう出た後だった。', 'Isoide eki made hashitta tokoro ga, densha wa mō deta ato datta.', NULL, 'Vội chạy ra ga thì tàu đã chạy mất rồi.', 6273, NULL, 1);
