INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11516, 'Câu 「天気予報によると、明日は台風が来るそうだ。」 có nghĩa là gì?', 'Theo dự báo thời tiết, nghe nói mai bão đến.', 553, '2026-08-29 06:52:55.194', '2026-08-29 06:52:55.194', 'MULTIPLE_CHOICE', NULL, NULL, 2, 30);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11517, 'Câu 「このケーキ、おいしそうですね。」 có nghĩa là gì?', 'Cái bánh này trông ngon nhỉ.', 553, '2026-08-29 06:52:55.201', '2026-08-29 06:52:55.201', 'MULTIPLE_CHOICE', NULL, NULL, 2, 31);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11518, 'Câu 「電気が消えている。田中さんはもう帰ったようだ。」 có nghĩa là gì?', 'Đèn tắt rồi. Hình như anh Tanaka đã về.', 553, '2026-08-29 06:52:55.208', '2026-08-29 06:52:55.208', 'MULTIPLE_CHOICE', NULL, NULL, 2, 32);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11519, 'Câu 「ニュースによると、その事故でけが人はいなかったらしい。」 có nghĩa là gì?', 'Theo tin tức, hình như vụ tai nạn đó không có ai bị thương.', 553, '2026-08-29 06:52:55.215', '2026-08-29 06:52:55.215', 'MULTIPLE_CHOICE', NULL, NULL, 2, 33);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11520, 'Câu 「壁に地図が貼ってあります。」 có nghĩa là gì?', 'Trên tường có dán bản đồ (ai đó đã dán sẵn).', 553, '2026-08-29 06:52:55.226', '2026-08-29 06:52:55.226', 'MULTIPLE_CHOICE', NULL, NULL, 2, 34);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11521, 'Câu 「客が来る前に、部屋を掃除しておきます。」 có nghĩa là gì?', 'Trước khi khách đến, tôi dọn phòng sẵn.', 553, '2026-08-29 06:52:55.238', '2026-08-29 06:52:55.238', 'MULTIPLE_CHOICE', NULL, NULL, 2, 35);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11522, 'Câu 「電車に傘を忘れてしまった。」 có nghĩa là gì?', 'Tôi lỡ để quên ô trên tàu mất rồi.', 553, '2026-08-29 06:52:55.252', '2026-08-29 06:52:55.252', 'MULTIPLE_CHOICE', NULL, NULL, 2, 36);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11523, 'Câu 「たまに朝ごはんを食べないことがある。」 có nghĩa là gì?', 'Thỉnh thoảng tôi cũng có hôm không ăn sáng.', 553, '2026-08-29 06:52:55.265', '2026-08-29 06:52:55.265', 'MULTIPLE_CHOICE', NULL, NULL, 2, 37);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11524, 'Câu 「エアコンをつけたまま出かけてしまった。」 có nghĩa là gì?', 'Tôi ra ngoài mà quên tắt điều hòa.', 553, '2026-08-29 06:52:55.278', '2026-08-29 06:52:55.278', 'MULTIPLE_CHOICE', NULL, NULL, 2, 38);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11525, 'Câu 「時間がたつにつれて、痛みは消えていった。」 có nghĩa là gì?', 'Thời gian trôi qua thì cơn đau cũng dần biến mất.', 553, '2026-08-29 06:52:55.292', '2026-08-29 06:52:55.292', 'MULTIPLE_CHOICE', NULL, NULL, 2, 39);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11526, 'Câu 「彼は医者として、また作家としても有名だ。」 có nghĩa là gì?', 'Anh ấy nổi tiếng với tư cách bác sĩ, và cả nhà văn nữa.', 553, '2026-08-29 06:52:55.306', '2026-08-29 06:52:55.306', 'MULTIPLE_CHOICE', NULL, NULL, 2, 40);
