INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11756, 'Câu 「実際に見てみないことには、何とも言えない。」 có nghĩa là gì?', 'Chưa tận mắt xem thì chưa thể nói gì.', 558, '2026-08-29 06:53:00.164', '2026-08-29 06:53:00.164', 'MULTIPLE_CHOICE', NULL, NULL, 3, 32);
