INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11758, 'Câu 「あんなに練習したんだから、負けるわけがない。」 có nghĩa là gì?', 'Luyện tập đến thế thì không thể thua được.', 558, '2026-08-29 06:53:00.189', '2026-08-29 06:53:00.189', 'MULTIPLE_CHOICE', NULL, NULL, 3, 34);
