INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (11870, 'Câu 「この仕事を任せられるのは、彼をおいてほかにいない。」 có nghĩa là gì?', 'Người có thể giao việc này thì ngoài anh ấy ra không còn ai.', 560, '2026-08-29 06:53:02.494', '2026-08-29 06:53:02.494', 'MULTIPLE_CHOICE', NULL, NULL, 4, 32);
