INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19663, 'Câu 「ねぼうした せいで、でんしゃに のりおくれた。」 có nghĩa là gì?', 'Tại ngủ quên nên tôi lỡ tàu.', 16229, '2026-09-26 12:14:59.753', '2026-09-26 12:14:59.753', 'MULTIPLE_CHOICE', NULL, NULL, 3, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19664, 'Câu 「せんせいの おかげで、ごうかくできました。」 có nghĩa là gì?', 'Nhờ thầy mà tôi đã đỗ.', 16229, '2026-09-26 12:14:59.758', '2026-09-26 12:14:59.758', 'MULTIPLE_CHOICE', NULL, NULL, 3, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19665, 'Câu 「じしんに よって、おおくの いえが たおれた。」 có nghĩa là gì?', 'Do động đất, nhiều ngôi nhà bị đổ.', 16229, '2026-09-26 12:14:59.762', '2026-09-26 12:14:59.762', 'MULTIPLE_CHOICE', NULL, NULL, 3, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19666, 'Câu 「おおゆきの ため、でんしゃが とまって います。」 có nghĩa là gì?', 'Vì tuyết lớn nên tàu đang ngừng chạy.', 16229, '2026-09-26 12:14:59.767', '2026-09-26 12:14:59.767', 'MULTIPLE_CHOICE', NULL, NULL, 3, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19667, 'Câu 「あなたの ことを しんぱいして いる から こそ、ちゅういするのです。」 có nghĩa là gì?', 'Chính vì lo cho bạn nên tôi mới nhắc nhở.', 16229, '2026-09-26 12:14:59.772', '2026-09-26 12:14:59.772', 'MULTIPLE_CHOICE', NULL, NULL, 3, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19668, 'Câu 「わすれない ように、メモして おきます。」 có nghĩa là gì?', 'Tôi ghi chú lại để khỏi quên.', 16229, '2026-09-26 12:14:59.776', '2026-09-26 12:14:59.776', 'MULTIPLE_CHOICE', NULL, NULL, 3, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19669, 'Câu 「かたちが にて いる ことから、この なまえが ついた。」 có nghĩa là gì?', 'Vì hình dạng giống nên mới có tên này.', 16229, '2026-09-26 12:14:59.781', '2026-09-26 12:14:59.781', 'MULTIPLE_CHOICE', NULL, NULL, 3, 6);
