INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19676, 'Câu 「あめが ふらない うちに、かえりましょう。」 có nghĩa là gì?', 'Về thôi trước khi trời mưa.', 16231, '2026-09-26 12:14:59.874', '2026-09-26 12:14:59.874', 'MULTIPLE_CHOICE', NULL, NULL, 3, 1);
