INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19683, 'Câu 「かいものの ついでに、ゆうびんきょくに よった。」 có nghĩa là gì?', 'Nhân tiện đi mua sắm, tôi ghé bưu điện.', 16231, '2026-09-26 12:14:59.911', '2026-09-26 12:14:59.911', 'MULTIPLE_CHOICE', NULL, NULL, 3, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19684, 'Câu 「しゅくだいを おえて からでないと、あそびに いっては だめ。」 có nghĩa là gì?', 'Chưa làm xong bài tập thì không được đi chơi.', 16231, '2026-09-26 12:14:59.918', '2026-09-26 12:14:59.918', 'MULTIPLE_CHOICE', NULL, NULL, 3, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19685, 'Câu 「かれとは きょねん あった きり、れんらくが ない。」 có nghĩa là gì?', 'Gặp anh ấy năm ngoái rồi thôi, không liên lạc nữa.', 16232, '2026-09-26 12:14:59.934', '2026-09-26 12:14:59.934', 'MULTIPLE_CHOICE', NULL, NULL, 3, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19686, 'Câu 「もし 1おくえん あたった としたら、なにに つかいますか。」 có nghĩa là gì?', 'Giả sử trúng 100 triệu yên thì bạn tiêu vào gì?', 16233, '2026-09-26 12:15:00.013', '2026-09-26 12:15:00.013', 'MULTIPLE_CHOICE', NULL, NULL, 3, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19687, 'Câu 「じかん さえ あれば、もっと べんきょうできるのに。」 có nghĩa là gì?', 'Chỉ cần có thời gian là học được nhiều hơn.', 16233, '2026-09-26 12:15:00.019', '2026-09-26 12:15:00.019', 'MULTIPLE_CHOICE', NULL, NULL, 3, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19688, 'Câu 「れんしゅうしない かぎり、じょうずに ならない。」 có nghĩa là gì?', 'Chừng nào chưa luyện tập thì không giỏi được.', 16233, '2026-09-26 12:15:00.025', '2026-09-26 12:15:00.025', 'MULTIPLE_CHOICE', NULL, NULL, 3, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19689, 'Câu 「たとえ はんたいされても、わたしは やります。」 có nghĩa là gì?', 'Cho dù bị phản đối, tôi vẫn làm.', 16233, '2026-09-26 12:15:00.031', '2026-09-26 12:15:00.031', 'MULTIPLE_CHOICE', NULL, NULL, 3, 3);
