INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (19693, 'Câu 「もっと はやく いえを でれば よかった。」 có nghĩa là gì?', 'Giá mà ra khỏi nhà sớm hơn.', 16233, '2026-09-26 12:15:00.062', '2026-09-26 12:15:00.062', 'MULTIPLE_CHOICE', NULL, NULL, 3, 7);
