INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20143, 'Câu 「ねぼうした せいで、でんしゃに のりおくれた。」 có nghĩa là gì?', 'Tại ngủ quên nên tôi lỡ tàu.', 16255, '2026-09-26 12:15:02.688', '2026-09-26 12:15:02.688', 'MULTIPLE_CHOICE', NULL, NULL, 3, 30);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20144, 'Câu 「せんせいの おかげで、ごうかくできました。」 có nghĩa là gì?', 'Nhờ thầy mà tôi đã đỗ.', 16255, '2026-09-26 12:15:02.696', '2026-09-26 12:15:02.696', 'MULTIPLE_CHOICE', NULL, NULL, 3, 31);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20145, 'Câu 「じしんに よって、おおくの いえが たおれた。」 có nghĩa là gì?', 'Do động đất, nhiều ngôi nhà bị đổ.', 16255, '2026-09-26 12:15:02.708', '2026-09-26 12:15:02.708', 'MULTIPLE_CHOICE', NULL, NULL, 3, 32);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20146, 'Câu 「おおゆきの ため、でんしゃが とまって います。」 có nghĩa là gì?', 'Vì tuyết lớn nên tàu đang ngừng chạy.', 16255, '2026-09-26 12:15:02.717', '2026-09-26 12:15:02.717', 'MULTIPLE_CHOICE', NULL, NULL, 3, 33);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20147, 'Câu 「あなたの ことを しんぱいして いる から こそ、ちゅういするのです。」 có nghĩa là gì?', 'Chính vì lo cho bạn nên tôi mới nhắc nhở.', 16255, '2026-09-26 12:15:02.721', '2026-09-26 12:15:02.721', 'MULTIPLE_CHOICE', NULL, NULL, 3, 34);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20148, 'Câu 「わすれない ように、メモして おきます。」 có nghĩa là gì?', 'Tôi ghi chú lại để khỏi quên.', 16255, '2026-09-26 12:15:02.725', '2026-09-26 12:15:02.725', 'MULTIPLE_CHOICE', NULL, NULL, 3, 35);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20149, 'Câu 「かたちが にて いる ことから、この なまえが ついた。」 có nghĩa là gì?', 'Vì hình dạng giống nên mới có tên này.', 16255, '2026-09-26 12:15:02.728', '2026-09-26 12:15:02.728', 'MULTIPLE_CHOICE', NULL, NULL, 3, 36);
