INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20368, 'Câu 「せんせいの しつもんに たいして、だれも こたえなかった。」 có nghĩa là gì?', 'Không ai trả lời câu hỏi của thầy.', 16261, '2026-09-26 12:15:04.128', '2026-09-26 12:15:04.128', 'MULTIPLE_CHOICE', NULL, NULL, 3, 30);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20369, 'Câu 「かれは りゅうがくせいとして にほんに きた。」 có nghĩa là gì?', 'Anh ấy đến Nhật với tư cách du học sinh.', 16261, '2026-09-26 12:15:04.133', '2026-09-26 12:15:04.133', 'MULTIPLE_CHOICE', NULL, NULL, 3, 31);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20370, 'Câu 「あの ひとは はんにんに ちがいない。」 có nghĩa là gì?', 'Người đó chắc chắn là thủ phạm.', 16261, '2026-09-26 12:15:04.138', '2026-09-26 12:15:04.138', 'MULTIPLE_CHOICE', NULL, NULL, 3, 32);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20371, 'Câu 「かれが そんな ことを いう はずが ない。」 có nghĩa là gì?', 'Anh ấy không thể nào nói điều đó.', 16261, '2026-09-26 12:15:04.144', '2026-09-26 12:15:04.144', 'MULTIPLE_CHOICE', NULL, NULL, 3, 33);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20372, 'Câu 「1しゅうかんで ペラペラに なる わけが ない。」 có nghĩa là gì?', 'Làm gì có chuyện một tuần mà nói trôi chảy.', 16261, '2026-09-26 12:15:04.149', '2026-09-26 12:15:04.149', 'MULTIPLE_CHOICE', NULL, NULL, 3, 34);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20373, 'Câu 「にくが きらいな わけでは ないが、あまり たべない。」 có nghĩa là gì?', 'Không hẳn ghét thịt, nhưng tôi ít ăn.', 16261, '2026-09-26 12:15:04.153', '2026-09-26 12:15:04.153', 'MULTIPLE_CHOICE', NULL, NULL, 3, 35);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20374, 'Câu 「だいじな かいぎが あるので、やすむ わけには いかない。」 có nghĩa là gì?', 'Có cuộc họp quan trọng nên không thể nghỉ.', 16261, '2026-09-26 12:15:04.157', '2026-09-26 12:15:04.157', 'MULTIPLE_CHOICE', NULL, NULL, 3, 36);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (20375, 'Câu 「がくせいは もっと べんきょうする べきだ。」 có nghĩa là gì?', 'Học sinh nên học nhiều hơn.', 16261, '2026-09-26 12:15:04.161', '2026-09-26 12:15:04.161', 'MULTIPLE_CHOICE', NULL, NULL, 3, 37);
