INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21025, 'Câu 「よく かんがえた うえで、へんじします。」 có nghĩa là gì?', 'Tôi sẽ suy nghĩ kỹ rồi mới trả lời.', 16303, '2026-09-26 12:15:07.871', '2026-09-26 12:15:07.871', 'MULTIPLE_CHOICE', NULL, NULL, 4, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21026, 'Câu 「いぬを かいはじめて からと いう もの、まいあさ さんぽして いる。」 có nghĩa là gì?', 'Kể từ khi nuôi chó, sáng nào tôi cũng đi dạo.', 16304, '2026-09-26 12:15:07.883', '2026-09-26 12:15:07.883', 'MULTIPLE_CHOICE', NULL, NULL, 4, 0);
