INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21029, 'Câu 「この しょうせつは さっかの たいけんを もとに かかれた。」 có nghĩa là gì?', 'Cuốn tiểu thuyết này được viết dựa trên trải nghiệm của tác giả.', 16305, '2026-09-26 12:15:07.931', '2026-09-26 12:15:07.931', 'MULTIPLE_CHOICE', NULL, NULL, 4, 1);
