INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21031, 'Câu 「レベルに おうじて、クラスを わけます。」 có nghĩa là gì?', 'Chia lớp tùy theo trình độ.', 16305, '2026-09-26 12:15:07.938', '2026-09-26 12:15:07.938', 'MULTIPLE_CHOICE', NULL, NULL, 4, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21032, 'Câu 「あたらしい ほうりつを めぐって、ぎろんが つづいて いる。」 có nghĩa là gì?', 'Tranh luận quanh luật mới vẫn tiếp diễn.', 16305, '2026-09-26 12:15:07.942', '2026-09-26 12:15:07.942', 'MULTIPLE_CHOICE', NULL, NULL, 4, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21033, 'Câu 「この まつりは わかものを ちゅうしんに にんきが ある。」 có nghĩa là gì?', 'Lễ hội này được ưa chuộng, chủ yếu trong giới trẻ.', 16305, '2026-09-26 12:15:07.945', '2026-09-26 12:15:07.945', 'MULTIPLE_CHOICE', NULL, NULL, 4, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21034, 'Câu 「かいぎは 3じかんに わたって つづいた。」 có nghĩa là gì?', 'Cuộc họp kéo dài suốt 3 tiếng.', 16305, '2026-09-26 12:15:07.948', '2026-09-26 12:15:07.948', 'MULTIPLE_CHOICE', NULL, NULL, 4, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21035, 'Câu 「ともだちを つうじて、かのじょと しりあった。」 có nghĩa là gì?', 'Tôi quen cô ấy thông qua bạn bè.', 16305, '2026-09-26 12:15:07.952', '2026-09-26 12:15:07.952', 'MULTIPLE_CHOICE', NULL, NULL, 4, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21036, 'Câu 「この けんに かんして、ごいけんを おきかせください。」 có nghĩa là gì?', 'Xin cho biết ý kiến về việc này.', 16305, '2026-09-26 12:15:07.955', '2026-09-26 12:15:07.955', 'MULTIPLE_CHOICE', NULL, NULL, 4, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21037, 'Câu 「りゅうがくを きっかけに、にほんの ぶんかに きょうみを もった。」 có nghĩa là gì?', 'Nhân chuyến du học, tôi bắt đầu thích văn hóa Nhật.', 16305, '2026-09-26 12:15:07.958', '2026-09-26 12:15:07.958', 'MULTIPLE_CHOICE', NULL, NULL, 4, 9);
