INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21039, 'Câu 「この ゲームは こども に かぎらず、おとなにも にんきだ。」 có nghĩa là gì?', 'Trò chơi này không chỉ trẻ em mà người lớn cũng thích.', 16307, '2026-09-26 12:15:08.005', '2026-09-26 12:15:08.005', 'MULTIPLE_CHOICE', NULL, NULL, 4, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21040, 'Câu 「きょうに かぎり、ぜんぴん はんがくです。」 có nghĩa là gì?', 'Chỉ riêng hôm nay, mọi sản phẩm giảm nửa giá.', 16307, '2026-09-26 12:15:08.008', '2026-09-26 12:15:08.008', 'MULTIPLE_CHOICE', NULL, NULL, 4, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21041, 'Câu 「いきて いる かぎり、あなたを わすれない。」 có nghĩa là gì?', 'Chừng nào còn sống, tôi không quên bạn.', 16307, '2026-09-26 12:15:08.011', '2026-09-26 12:15:08.011', 'MULTIPLE_CHOICE', NULL, NULL, 4, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21042, 'Câu 「この もんだいは にほん のみならず、せかいの もんだいだ。」 có nghĩa là gì?', 'Vấn đề này không chỉ của Nhật mà của cả thế giới.', 16307, '2026-09-26 12:15:08.015', '2026-09-26 12:15:08.015', 'MULTIPLE_CHOICE', NULL, NULL, 4, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21043, 'Câu 「この みせは あじは もちろん、サービスも いい。」 có nghĩa là gì?', 'Quán này vị thì khỏi nói, phục vụ cũng tốt.', 16307, '2026-09-26 12:15:08.019', '2026-09-26 12:15:08.019', 'MULTIPLE_CHOICE', NULL, NULL, 4, 4);
