INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21057, 'Câu 「この はしは かたちが にじに にて いる ことから、にじばしと よばれて いる。」 có nghĩa là gì?', 'Cây cầu có hình giống cầu vồng nên được gọi là cầu Cầu Vồng.', 16309, '2026-09-26 12:15:08.113', '2026-09-26 12:15:08.113', 'MULTIPLE_CHOICE', NULL, NULL, 4, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21058, 'Câu 「ひとりで さんにんぶん はたらいて いる わけだから、つかれるのも とうぜんだ。」 có nghĩa là gì?', 'Một mình làm việc của ba người thì mệt là đương nhiên.', 16309, '2026-09-26 12:15:08.118', '2026-09-26 12:15:08.118', 'MULTIPLE_CHOICE', NULL, NULL, 4, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21059, 'Câu 「はなしあった けっか、けいかくを へんこうする ことに なった。」 có nghĩa là gì?', 'Kết quả bàn bạc là đổi kế hoạch.', 16309, '2026-09-26 12:15:08.122', '2026-09-26 12:15:08.122', 'MULTIPLE_CHOICE', NULL, NULL, 4, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21060, 'Câu 「この りょうでは 10じいこう、おんがくを ひかない ことに なって いる。」 có nghĩa là gì?', 'Ở ký túc xá này quy định sau 10 giờ không chơi nhạc.', 16310, '2026-09-26 12:15:08.13', '2026-09-26 12:15:08.13', 'MULTIPLE_CHOICE', NULL, NULL, 4, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21061, 'Câu 「それは うわさに すぎない。」 có nghĩa là gì?', 'Đó chỉ là tin đồn mà thôi.', 16311, '2026-09-26 12:15:08.169', '2026-09-26 12:15:08.169', 'MULTIPLE_CHOICE', NULL, NULL, 4, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21062, 'Câu 「そんな はなし、うそに きまって いる。」 có nghĩa là gì?', 'Chuyện như thế chắc chắn là nói dối.', 16311, '2026-09-26 12:15:08.172', '2026-09-26 12:15:08.172', 'MULTIPLE_CHOICE', NULL, NULL, 4, 1);
