INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21064, 'Câu 「あんな みせ、にどと いく ものか。」 có nghĩa là gì?', 'Quán như thế, còn lâu tôi mới quay lại.', 16311, '2026-09-26 12:15:08.179', '2026-09-26 12:15:08.179', 'MULTIPLE_CHOICE', NULL, NULL, 4, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21065, 'Câu 「そんな むずかしい もんだい、わかりっこない。」 có nghĩa là gì?', 'Bài khó thế sao mà hiểu nổi.', 16311, '2026-09-26 12:15:08.182', '2026-09-26 12:15:08.182', 'MULTIPLE_CHOICE', NULL, NULL, 4, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21066, 'Câu 「れんらくさきが わからないので、れんらくの しようが ない。」 có nghĩa là gì?', 'Không biết địa chỉ liên lạc nên không có cách nào liên lạc.', 16311, '2026-09-26 12:15:08.186', '2026-09-26 12:15:08.186', 'MULTIPLE_CHOICE', NULL, NULL, 4, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21067, 'Câu 「たいふうが くるので、りょこうを ちゅうしせざるを えない。」 có nghĩa là gì?', 'Bão đến nên buộc phải hủy chuyến đi.', 16311, '2026-09-26 12:15:08.19', '2026-09-26 12:15:08.19', 'MULTIPLE_CHOICE', NULL, NULL, 4, 6);
