INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21613, 'Câu 「きょうに かぎり、ぜんぴん はんがくです。」 có nghĩa là gì?', 'Chỉ riêng hôm nay, mọi sản phẩm giảm nửa giá.', 16334, '2026-09-26 12:15:11.748', '2026-09-26 12:15:11.748', 'MULTIPLE_CHOICE', NULL, NULL, 4, 30);
