INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21617, 'Câu 「ねだんは ともかく、デザインが きに いらない。」 có nghĩa là gì?', 'Giá cả thì tạm gác, tôi không thích thiết kế.', 16334, '2026-09-26 12:15:11.778', '2026-09-26 12:15:11.778', 'MULTIPLE_CHOICE', NULL, NULL, 4, 34);
