INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21650, 'Câu 「かれは ひとめも かまわず、ないた。」 có nghĩa là gì?', 'Anh ấy khóc chẳng để ý ánh mắt người khác.', 16335, '2026-09-26 12:15:12.051', '2026-09-26 12:15:12.051', 'MULTIPLE_CHOICE', NULL, NULL, 4, 30);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21651, 'Câu 「じょうだんは さておき、ほんだいに はいりましょう。」 có nghĩa là gì?', 'Đùa thì để sau, vào vấn đề chính thôi.', 16335, '2026-09-26 12:15:12.054', '2026-09-26 12:15:12.054', 'MULTIPLE_CHOICE', NULL, NULL, 4, 31);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21652, 'Câu 「さすが プロだけ あって、うまいね。」 có nghĩa là gì?', 'Quả là dân chuyên nghiệp, giỏi thật.', 16335, '2026-09-26 12:15:12.058', '2026-09-26 12:15:12.058', 'MULTIPLE_CHOICE', NULL, NULL, 4, 32);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21653, 'Câu 「やると きめた からには、さいごまで やる。」 có nghĩa là gì?', 'Một khi đã quyết làm thì làm đến cùng.', 16335, '2026-09-26 12:15:12.061', '2026-09-26 12:15:12.061', 'MULTIPLE_CHOICE', NULL, NULL, 4, 33);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21654, 'Câu 「きたいして いた だけに、ざんねんだ。」 có nghĩa là gì?', 'Chính vì đã kỳ vọng nên càng tiếc.', 16335, '2026-09-26 12:15:12.065', '2026-09-26 12:15:12.065', 'MULTIPLE_CHOICE', NULL, NULL, 4, 34);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (21655, 'Câu 「でんしゃが おくれた ものだから、ちこくして しまいました。」 có nghĩa là gì?', 'Vì tàu trễ nên tôi đến muộn.', 16335, '2026-09-26 12:15:12.069', '2026-09-26 12:15:12.069', 'MULTIPLE_CHOICE', NULL, NULL, 4, 35);
