INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22361, 'Câu 「けいかくは ずさんで、けっきょく しっぱいに おわった。」 có nghĩa là gì?', 'Kế hoạch cẩu thả, rốt cuộc kết thúc bằng thất bại.', 16378, '2026-09-26 12:15:17.109', '2026-09-26 12:15:17.109', 'MULTIPLE_CHOICE', NULL, NULL, 5, 10);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22362, 'Câu 「だいがくきょうじゅ とも あろう ひとが、そんな まちがいを するとは。」 có nghĩa là gì?', 'Một giáo sư đại học mà lại mắc lỗi như vậy.', 16378, '2026-09-26 12:15:17.113', '2026-09-26 12:15:17.113', 'MULTIPLE_CHOICE', NULL, NULL, 5, 11);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22363, 'Câu 「ベルが なるや いなや、がくせいたちは きょうしつを とびだした。」 có nghĩa là gì?', 'Chuông vừa reo, học sinh đã lao ra khỏi lớp.', 16379, '2026-09-26 12:15:17.214', '2026-09-26 12:15:17.214', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22364, 'Câu 「こどもは かばんを おくが はやいか、あそびに でかけた。」 có nghĩa là gì?', 'Đứa trẻ vừa đặt cặp xuống là đã đi chơi.', 16379, '2026-09-26 12:15:17.221', '2026-09-26 12:15:17.221', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22365, 'Câu 「かのじょは わたしの かおを みるなり、なきだした。」 có nghĩa là gì?', 'Cô ấy vừa nhìn thấy mặt tôi liền bật khóc.', 16379, '2026-09-26 12:15:17.228', '2026-09-26 12:15:17.228', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22366, 'Câu 「かたづける そばから、こどもが ちらかす。」 có nghĩa là gì?', 'Vừa dọn xong là bọn trẻ lại bày bừa.', 16379, '2026-09-26 12:15:17.233', '2026-09-26 12:15:17.233', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22367, 'Câu 「とうきょうこうえんを かわきりに、ぜんこくツアーが はじまった。」 có nghĩa là gì?', 'Khởi đầu bằng buổi diễn ở Tokyo, tour toàn quốc bắt đầu.', 16379, '2026-09-26 12:15:17.239', '2026-09-26 12:15:17.239', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22368, 'Câu 「しにんが でるに いたって、やっと たいさくが とられた。」 có nghĩa là gì?', 'Đến khi có người chết thì mới có biện pháp.', 16379, '2026-09-26 12:15:17.248', '2026-09-26 12:15:17.248', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22369, 'Câu 「こんげつを かぎりに、この みせは へいてんします。」 có nghĩa là gì?', 'Hết tháng này, cửa hàng sẽ đóng cửa.', 16379, '2026-09-26 12:15:17.256', '2026-09-26 12:15:17.256', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22370, 'Câu 「うまれて このかた、びょうきを した ことが ない。」 có nghĩa là gì?', 'Từ khi sinh ra đến nay chưa từng ốm.', 16379, '2026-09-26 12:15:17.265', '2026-09-26 12:15:17.265', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22371, 'Câu 「こんなんな じょうきょうに あって、かれは おちついて いた。」 có nghĩa là gì?', 'Trong hoàn cảnh khó khăn, anh ấy vẫn bình tĩnh.', 16379, '2026-09-26 12:15:17.274', '2026-09-26 12:15:17.274', 'MULTIPLE_CHOICE', NULL, NULL, 5, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22372, 'Câu 「こんど おあいした おりに、くわしく おはなしします。」 có nghĩa là gì?', 'Dịp gặp lần tới tôi sẽ nói chi tiết.', 16379, '2026-09-26 12:15:17.283', '2026-09-26 12:15:17.283', 'MULTIPLE_CHOICE', NULL, NULL, 5, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22373, 'Câu 「おいそがしい ところを、ありがとうございます。」 có nghĩa là gì?', 'Cảm ơn anh đã dành thời gian dù đang bận.', 16380, '2026-09-26 12:15:17.304', '2026-09-26 12:15:17.304', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22374, 'Câu 「この しごとを まかせられるのは、かれを おいて ほかに いない。」 có nghĩa là gì?', 'Ngoài anh ấy ra không ai được giao việc này.', 16381, '2026-09-26 12:15:17.404', '2026-09-26 12:15:17.404', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22375, 'Câu 「これは この ちほう ならではの あじだ。」 có nghĩa là gì?', 'Đây là hương vị chỉ vùng này mới có.', 16381, '2026-09-26 12:15:17.414', '2026-09-26 12:15:17.414', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22376, 'Câu 「この びょうきは おとな に とどまらず、こどもにも ひろがって いる。」 có nghĩa là gì?', 'Căn bệnh không chỉ ở người lớn mà lan sang cả trẻ em.', 16381, '2026-09-26 12:15:17.424', '2026-09-26 12:15:17.424', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22377, 'Câu 「ほんじつを もって、うけつけを しゅうりょうします。」 có nghĩa là gì?', 'Kể từ hôm nay chúng tôi ngừng tiếp nhận.', 16381, '2026-09-26 12:15:17.432', '2026-09-26 12:15:17.432', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22378, 'Câu 「じじつに そくして はなして ください。」 có nghĩa là gì?', 'Hãy nói bám sát sự thật.', 16381, '2026-09-26 12:15:17.44', '2026-09-26 12:15:17.44', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22379, 'Câu 「これは いのちに かかわる もんだいだ。」 có nghĩa là gì?', 'Đây là vấn đề liên quan đến tính mạng.', 16381, '2026-09-26 12:15:17.448', '2026-09-26 12:15:17.448', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22380, 'Câu 「にちようびを のぞいて、まいにち えいぎょうして います。」 có nghĩa là gì?', 'Mở cửa hằng ngày trừ Chủ nhật.', 16381, '2026-09-26 12:15:17.457', '2026-09-26 12:15:17.457', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22381, 'Câu 「みなさんの きょうりょく なくして、せいこうは ありえません。」 có nghĩa là gì?', 'Không có sự hợp tác của mọi người thì không thể thành công.', 16381, '2026-09-26 12:15:17.468', '2026-09-26 12:15:17.468', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22382, 'Câu 「いっしゅん たりとも ゆだんできない。」 có nghĩa là gì?', 'Không thể lơ là dù chỉ một khoảnh khắc.', 16381, '2026-09-26 12:15:17.479', '2026-09-26 12:15:17.479', 'MULTIPLE_CHOICE', NULL, NULL, 5, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22383, 'Câu 「だいがくせい とも なると、じぶんで かんがえて こうどうすべきだ。」 có nghĩa là gì?', 'Đã là sinh viên thì nên tự suy nghĩ mà hành động.', 16381, '2026-09-26 12:15:17.489', '2026-09-26 12:15:17.489', 'MULTIPLE_CHOICE', NULL, NULL, 5, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22384, 'Câu 「こどもの ため とあれば、どんな くろうも いとわない。」 có nghĩa là gì?', 'Nếu vì con thì vất vả thế nào cũng không ngại.', 16382, '2026-09-26 12:15:17.578', '2026-09-26 12:15:17.578', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22385, 'Câu 「ちちに くちごたえ しようものなら、たいへんな ことに なる。」 có nghĩa là gì?', 'Nếu lỡ cãi lại bố thì to chuyện.', 16382, '2026-09-26 12:15:17.584', '2026-09-26 12:15:17.584', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22386, 'Câu 「まいにち とは いわないまでも、しゅうに いちどは れんらくして。」 có nghĩa là gì?', 'Không đến mức mỗi ngày thì ít nhất tuần một lần hãy liên lạc.', 16382, '2026-09-26 12:15:17.591', '2026-09-26 12:15:17.591', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22387, 'Câu 「こども ならいざしらず、おとなが そんな ことを するとは。」 có nghĩa là gì?', 'Trẻ con thì đành, đằng này người lớn lại làm thế.', 16382, '2026-09-26 12:15:17.597', '2026-09-26 12:15:17.597', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22388, 'Câu 「かれは ねむったら さいご、なにが あっても おきない。」 có nghĩa là gì?', 'Anh ấy một khi đã ngủ thì có chuyện gì cũng không dậy.', 16382, '2026-09-26 12:15:17.603', '2026-09-26 12:15:17.603', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22389, 'Câu 「かんがえ ように よっては、しっぱいも いい けいけんだ。」 có nghĩa là gì?', 'Tùy cách nghĩ, thất bại cũng là kinh nghiệm tốt.', 16382, '2026-09-26 12:15:17.608', '2026-09-26 12:15:17.608', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22390, 'Câu 「あいじょう なくしては、こそだては できない。」 có nghĩa là gì?', 'Không có tình yêu thì không thể nuôi dạy con.', 16382, '2026-09-26 12:15:17.614', '2026-09-26 12:15:17.614', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22391, 'Câu 「かれの はなしが ほんとう と すれば、けいかくを みなおす ひつようが ある。」 có nghĩa là gì?', 'Nếu lời anh ấy là thật thì cần xem lại kế hoạch.', 16382, '2026-09-26 12:15:17.619', '2026-09-26 12:15:17.619', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22392, 'Câu 「せんもんか と いえども、まちがえる ことは ある。」 có nghĩa là gì?', 'Dù là chuyên gia cũng có lúc sai.', 16383, '2026-09-26 12:15:17.669', '2026-09-26 12:15:17.669', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22393, 'Câu 「はる とは いえ、まだ さむい ひが つづく。」 có nghĩa là gì?', 'Tuy nói là xuân nhưng vẫn còn những ngày lạnh.', 16383, '2026-09-26 12:15:17.672', '2026-09-26 12:15:17.672', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22394, 'Câu 「どんな りゆう であれ、ぼうりょくは ゆるされない。」 có nghĩa là gì?', 'Dù lý do gì, bạo lực không được chấp nhận.', 16383, '2026-09-26 12:15:17.677', '2026-09-26 12:15:17.677', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22395, 'Câu 「さんせい にせよ はんたい にせよ、いけんを のべて ください。」 có nghĩa là gì?', 'Tán thành hay phản đối, xin hãy nêu ý kiến.', 16383, '2026-09-26 12:15:17.681', '2026-09-26 12:15:17.681', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22396, 'Câu 「いって くれれば てつだった ものを。」 có nghĩa là gì?', 'Giá mà nói với tôi thì tôi đã giúp rồi.', 16383, '2026-09-26 12:15:17.691', '2026-09-26 12:15:17.691', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22397, 'Câu 「はれる と おもいきや、ごごから あめに なった。」 có nghĩa là gì?', 'Cứ tưởng trời nắng, hóa ra chiều lại mưa.', 16383, '2026-09-26 12:15:17.699', '2026-09-26 12:15:17.699', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22398, 'Câu 「インターネットで いえに いながらにして かいものが できる。」 có nghĩa là gì?', 'Nhờ Internet có thể mua sắm ngay tại nhà.', 16383, '2026-09-26 12:15:17.714', '2026-09-26 12:15:17.714', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22399, 'Câu 「こども ではあるまいし、じぶんで かんがえなさい。」 có nghĩa là gì?', 'Có phải trẻ con đâu, tự suy nghĩ đi.', 16383, '2026-09-26 12:15:17.725', '2026-09-26 12:15:17.725', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22400, 'Câu 「いくら ねがった とて、むりな ものは むりだ。」 có nghĩa là gì?', 'Dù có mong mỏi bao nhiêu, không thể vẫn là không thể.', 16383, '2026-09-26 12:15:17.734', '2026-09-26 12:15:17.734', 'MULTIPLE_CHOICE', NULL, NULL, 5, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22401, 'Câu 「かれの たいどは しつれい きわまりない。」 có nghĩa là gì?', 'Thái độ của anh ta cực kỳ vô lễ.', 16384, '2026-09-26 12:15:17.843', '2026-09-26 12:15:17.843', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22402, 'Câu 「この ような しょうを いただき、こうえいの きわみです。」 có nghĩa là gì?', 'Được nhận giải thưởng này là vinh dự tột bậc.', 16384, '2026-09-26 12:15:17.852', '2026-09-26 12:15:17.852', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22403, 'Câu 「おほめの ことばを いただき、こうえいの いたりです。」 có nghĩa là gì?', 'Được khen ngợi, tôi vô cùng vinh dự.', 16384, '2026-09-26 12:15:17.86', '2026-09-26 12:15:17.86', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22404, 'Câu 「いう までも なく、けんこうが いちばん たいせつだ。」 có nghĩa là gì?', 'Khỏi phải nói, sức khỏe là quan trọng nhất.', 16384, '2026-09-26 12:15:17.867', '2026-09-26 12:15:17.867', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22405, 'Câu 「かぞくの かなしみは そうぞうに かたくない。」 có nghĩa là gì?', 'Nỗi đau của gia đình không khó để tưởng tượng.', 16384, '2026-09-26 12:15:17.873', '2026-09-26 12:15:17.873', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22406, 'Câu 「その ばんぐみは みるに たえない。」 có nghĩa là gì?', 'Chương trình đó không đáng để xem.', 16384, '2026-09-26 12:15:17.88', '2026-09-26 12:15:17.88', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22407, 'Câu 「かれは しんらいするに たる ひとだ。」 có nghĩa là gì?', 'Anh ấy là người đáng tin cậy.', 16384, '2026-09-26 12:15:17.886', '2026-09-26 12:15:17.886', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22408, 'Câu 「みなさまの ごけんこうを ねがって やみません。」 có nghĩa là gì?', 'Luôn cầu chúc mọi người mạnh khỏe.', 16384, '2026-09-26 12:15:17.892', '2026-09-26 12:15:17.892', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22409, 'Câu 「あの ときの はずかしさ と いったら なかった。」 có nghĩa là gì?', 'Lúc đó xấu hổ không kể xiết.', 16384, '2026-09-26 12:15:17.9', '2026-09-26 12:15:17.9', 'MULTIPLE_CHOICE', NULL, NULL, 5, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22410, 'Câu 「じしんの ことは かんがえる だに おそろしい。」 có nghĩa là gì?', 'Chỉ nghĩ đến động đất thôi đã sợ.', 16384, '2026-09-26 12:15:17.906', '2026-09-26 12:15:17.906', 'MULTIPLE_CHOICE', NULL, NULL, 5, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22411, 'Câu 「じこに あったが、けがを しなかった だけ ましだ。」 có nghĩa là gì?', 'Bị tai nạn nhưng còn may là không bị thương.', 16385, '2026-09-26 12:15:17.923', '2026-09-26 12:15:17.923', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22412, 'Câu 「しばふに たちいる べからず。」 có nghĩa là gì?', 'Cấm giẫm lên cỏ.', 16386, '2026-09-26 12:15:18.015', '2026-09-26 12:15:18.015', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22413, 'Câu 「きょうし に あるまじき こういだ。」 có nghĩa là gì?', 'Đó là hành vi không thể có ở một giáo viên.', 16386, '2026-09-26 12:15:18.021', '2026-09-26 12:15:18.021', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22414, 'Câu 「だめなら、もう いちど やる までだ。」 có nghĩa là gì?', 'Không được thì làm lại lần nữa thôi.', 16386, '2026-09-26 12:15:18.027', '2026-09-26 12:15:18.027', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22415, 'Câu 「いくら ちょきんしても、しんで しまえば それまでだ。」 có nghĩa là gì?', 'Tiết kiệm bao nhiêu thì chết rồi cũng hết.', 16386, '2026-09-26 12:15:18.034', '2026-09-26 12:15:18.034', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22416, 'Câu 「ひさいしゃの はなしに なみだを きんじえない。」 có nghĩa là gì?', 'Nghe chuyện nạn nhân không cầm được nước mắt.', 16386, '2026-09-26 12:15:18.041', '2026-09-26 12:15:18.041', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22417, 'Câu 「かれの えんぜつは ひとびとを かんどうさせずには おかない。」 có nghĩa là gì?', 'Bài diễn văn của anh ấy chắc chắn làm mọi người cảm động.', 16386, '2026-09-26 12:15:18.049', '2026-09-26 12:15:18.049', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22418, 'Câu 「ひとに めいわくを かけたのだから、あやまらずには すまない。」 có nghĩa là gì?', 'Đã làm phiền người khác thì không thể không xin lỗi.', 16386, '2026-09-26 12:15:18.055', '2026-09-26 12:15:18.055', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22419, 'Câu 「この ていどの ことで おどろくには あたらない。」 có nghĩa là gì?', 'Chuyện cỡ này không đáng để ngạc nhiên.', 16386, '2026-09-26 12:15:18.063', '2026-09-26 12:15:18.063', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22420, 'Câu 「おかねは ある に こした ことは ない。」 có nghĩa là gì?', 'Có tiền thì vẫn là tốt nhất.', 16386, '2026-09-26 12:15:18.069', '2026-09-26 12:15:18.069', 'MULTIPLE_CHOICE', NULL, NULL, 5, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22421, 'Câu 「かれは ものごとを おおげさに いう きらいが ある。」 có nghĩa là gì?', 'Anh ta có tật hay nói phóng đại.', 16386, '2026-09-26 12:15:18.075', '2026-09-26 12:15:18.075', 'MULTIPLE_CHOICE', NULL, NULL, 5, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22422, 'Câu 「かれは なまけて ばかりで、ついには かいしゃを くびに なる しまつだ。」 có nghĩa là gì?', 'Anh ta lười mãi, rốt cuộc bị đuổi việc.', 16387, '2026-09-26 12:15:18.094', '2026-09-26 12:15:18.094', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22423, 'Câu 「しけんに ごうかくす べく、まいにち べんきょうして いる。」 có nghĩa là gì?', 'Để đỗ kỳ thi, tôi học mỗi ngày.', 16387, '2026-09-26 12:15:18.103', '2026-09-26 12:15:18.103', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22424, 'Câu 「こどもたちは どろ まみれに なって あそんだ。」 có nghĩa là gì?', 'Bọn trẻ chơi lấm lem bùn đất.', 16388, '2026-09-26 12:15:18.172', '2026-09-26 12:15:18.172', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22425, 'Câu 「だんだん はるめいて きた。」 có nghĩa là gì?', 'Trời dần mang dáng vẻ mùa xuân.', 16388, '2026-09-26 12:15:18.178', '2026-09-26 12:15:18.178', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22426, 'Câu 「かのじょは いつも じょうひんぶって いる。」 có nghĩa là gì?', 'Cô ấy lúc nào cũng làm ra vẻ thanh lịch.', 16388, '2026-09-26 12:15:18.184', '2026-09-26 12:15:18.184', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22427, 'Câu 「かれは もう かえれ と ばかりに、ドアを あけた。」 có nghĩa là gì?', 'Anh ta mở cửa như muốn bảo "về đi".', 16388, '2026-09-26 12:15:18.191', '2026-09-26 12:15:18.191', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22428, 'Câu 「かのじょは なきださん ばかりの かおを して いた。」 có nghĩa là gì?', 'Cô ấy có vẻ mặt như sắp khóc.', 16388, '2026-09-26 12:15:18.199', '2026-09-26 12:15:18.199', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22429, 'Câu 「みる とも なく テレビを みて いた。」 có nghĩa là gì?', 'Tôi nhìn tivi một cách vô định.', 16388, '2026-09-26 12:15:18.204', '2026-09-26 12:15:18.204', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22430, 'Câu 「おれい かたがた、ごあいさつに うかがいました。」 có nghĩa là gì?', 'Tôi đến chào hỏi, nhân tiện cảm ơn.', 16388, '2026-09-26 12:15:18.209', '2026-09-26 12:15:18.209', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22431, 'Câu 「かいもの がてら、こうえんを さんぽした。」 có nghĩa là gì?', 'Tiện đi mua sắm, tôi đi dạo công viên.', 16388, '2026-09-26 12:15:18.215', '2026-09-26 12:15:18.215', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22432, 'Câu 「いそがしくて、けっきょく かのじょに あわず じまいだった。」 có nghĩa là gì?', 'Bận quá rốt cuộc đã không gặp được cô ấy.', 16388, '2026-09-26 12:15:18.221', '2026-09-26 12:15:18.221', 'MULTIPLE_CHOICE', NULL, NULL, 5, 8);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22433, 'Câu 「ふたりは おいつ おわれつ の レースを した。」 có nghĩa là gì?', 'Hai người đua nhau lúc đuổi lúc bị đuổi.', 16388, '2026-09-26 12:15:18.226', '2026-09-26 12:15:18.226', 'MULTIPLE_CHOICE', NULL, NULL, 5, 9);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22483, '「もっぱら」 nghĩa là gì?', 'chủ yếu, toàn là', 16391, '2026-09-26 12:15:18.635', '2026-09-26 12:15:18.635', 'MULTIPLE_CHOICE', NULL, NULL, 5, 39);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22434, 'Câu 「わたし なりに いっしょうけんめい がんばった。」 có nghĩa là gì?', 'Tôi đã cố gắng hết sức theo cách của mình.', 16389, '2026-09-26 12:15:18.239', '2026-09-26 12:15:18.239', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22435, 'Câu 「まずしさ ゆえに、がっこうに いけない こどもが いる。」 có nghĩa là gì?', 'Vì nghèo mà có những đứa trẻ không được đến trường.', 16390, '2026-09-26 12:15:18.292', '2026-09-26 12:15:18.292', 'MULTIPLE_CHOICE', NULL, NULL, 5, 0);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22436, 'Câu 「あいして いれば こそ、きびしく するのだ。」 có nghĩa là gì?', 'Chính vì thương nên mới nghiêm khắc.', 16390, '2026-09-26 12:15:18.297', '2026-09-26 12:15:18.297', 'MULTIPLE_CHOICE', NULL, NULL, 5, 1);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22437, 'Câu 「れんきゅう とあって、かんこうちは こんで いる。」 có nghĩa là gì?', 'Vì là kỳ nghỉ dài nên điểm du lịch đông nghịt.', 16390, '2026-09-26 12:15:18.304', '2026-09-26 12:15:18.304', 'MULTIPLE_CHOICE', NULL, NULL, 5, 2);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22438, 'Câu 「あめも やんだ ことだし、そろそろ でかけようか。」 có nghĩa là gì?', 'Mưa cũng tạnh rồi, sắp đi thôi nhỉ.', 16390, '2026-09-26 12:15:18.311', '2026-09-26 12:15:18.311', 'MULTIPLE_CHOICE', NULL, NULL, 5, 3);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22439, 'Câu 「ゆめを かなえ んがため、かれは くにを でた。」 có nghĩa là gì?', 'Để thực hiện ước mơ, anh ấy rời quê hương.', 16390, '2026-09-26 12:15:18.323', '2026-09-26 12:15:18.323', 'MULTIPLE_CHOICE', NULL, NULL, 5, 4);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22440, 'Câu 「たいふうの ため、しあいは ちゅうしを よぎなく された。」 có nghĩa là gì?', 'Vì bão mà trận đấu buộc phải hủy.', 16390, '2026-09-26 12:15:18.333', '2026-09-26 12:15:18.333', 'MULTIPLE_CHOICE', NULL, NULL, 5, 5);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22441, 'Câu 「ちいさな くいちがいが、おおきな じけんに いたった。」 có nghĩa là gì?', 'Sai lệch nhỏ đã dẫn đến vụ việc lớn.', 16390, '2026-09-26 12:15:18.34', '2026-09-26 12:15:18.34', 'MULTIPLE_CHOICE', NULL, NULL, 5, 6);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (22442, 'Câu 「けいかくは ずさんで、けっきょく しっぱいに おわった。」 có nghĩa là gì?', 'Kế hoạch cẩu thả, rốt cuộc kết thúc bằng thất bại.', 16390, '2026-09-26 12:15:18.347', '2026-09-26 12:15:18.347', 'MULTIPLE_CHOICE', NULL, NULL, 5, 7);
