INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (23018, 'Câu 「はれる と おもいきや、ごごから あめに なった。」 có nghĩa là gì?', 'Cứ tưởng trời nắng, hóa ra chiều lại mưa.', 16408, '2026-09-26 12:15:22.977', '2026-09-26 12:15:22.977', 'MULTIPLE_CHOICE', NULL, NULL, 5, 30);
