INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (23020, 'Câu 「こども ではあるまいし、じぶんで かんがえなさい。」 có nghĩa là gì?', 'Có phải trẻ con đâu, tự suy nghĩ đi.', 16408, '2026-09-26 12:15:22.999', '2026-09-26 12:15:22.999', 'MULTIPLE_CHOICE', NULL, NULL, 5, 32);
