INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (23022, 'Câu 「かれの たいどは しつれい きわまりない。」 có nghĩa là gì?', 'Thái độ của anh ta cực kỳ vô lễ.', 16408, '2026-09-26 12:15:23.015', '2026-09-26 12:15:23.015', 'MULTIPLE_CHOICE', NULL, NULL, 5, 34);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (23023, 'Câu 「この ような しょうを いただき、こうえいの きわみです。」 có nghĩa là gì?', 'Được nhận giải thưởng này là vinh dự tột bậc.', 16408, '2026-09-26 12:15:23.021', '2026-09-26 12:15:23.021', 'MULTIPLE_CHOICE', NULL, NULL, 5, 35);
INSERT INTO public."Exercise" (id, question, answer, "lessonId", "createdAt", "updatedAt", type, explanation, "audioUrl", difficulty, "sortOrder") VALUES (23024, 'Câu 「おほめの ことばを いただき、こうえいの いたりです。」 có nghĩa là gì?', 'Được khen ngợi, tôi vô cùng vinh dự.', 16408, '2026-09-26 12:15:23.028', '2026-09-26 12:15:23.028', 'MULTIPLE_CHOICE', NULL, NULL, 5, 36);
