INSERT INTO public."ExerciseOption" (id, "exerciseId", text, "sortOrder", "isCorrect") VALUES (12200, 13300, 'Trường hợp 2: Những động từ như「答える、しゃべる、言う、質問する、反対する、発言する」 là những tự động từ thực hiện hành vi có hướng đến 1 đối tượng nào đó nhưng có nhiều khi dùng trợ từ 「に」 thay cho trợ từ「を」', 3, false);
