INSERT INTO public."ExerciseOption" (id, "exerciseId", text, "sortOrder", "isCorrect") VALUES (12210, 13303, '(Tôi là chủ thể của câu nhưng đối tượng thực hiện hành động chơi là con gái tôi) 2.2. Trường hợp #1: đối với “tha động từ” (他動詞) Câu trúc: ~に ~を V(さ)せる Cách dùng: biến đổi tha động từ sang thể 「使役(しえき)」 để tạo ra 1 động từ mới mang nghĩa sai khiến, mệnh lệnh yêu cầu ai đó làm gì. Trong kiểu câu này, người thực hiệnhành động, động tác sẽ đi với trợ từ 「に」, còn tân ngữ (đối tượng tác động của động từ) vẫn được xác định bởi trợ từ 「を」. – Kiểu câu này còn được gọi tên là kiểu câu 「に-使役文」(câu sai khiến với trợ từ', 1, false);
