INSERT INTO public."JlptRoadmapLevel" (id, "externalKey", label, badge, color, duration, "vocabTarget", "kanjiTarget", "passScore", summary, "sortOrder", "createdAt", "updatedAt", "grammarTarget", "vocabIncrement", "kanjiIncrement", "grammarIncrement") VALUES (4, 'n2', 'JLPT N2', 'Trung cao cấp', '#f97316', '9–12 tháng (sau N3)', '~6.000 từ (gồm N5–N3)', '~1.000 chữ (gồm N5–N3)', '90/180 điểm', 'N2 là cấp độ trung cao — đủ để làm việc, đọc báo đơn giản, hiểu hội thoại hàng ngày và văn viết thông thường.', 3, '2026-09-02 09:48:36.185', '2026-09-02 09:48:36.185', '~500 mẫu (gồm N5–N3)', '+2.250 từ mới', '+350 chữ mới', '+150 mẫu mới');
INSERT INTO public."JlptRoadmapLevel" (id, "externalKey", label, badge, color, duration, "vocabTarget", "kanjiTarget", "passScore", summary, "sortOrder", "createdAt", "updatedAt", "grammarTarget", "vocabIncrement", "kanjiIncrement", "grammarIncrement") VALUES (5, 'n1', 'JLPT N1', 'Cao cấp', '#ef4444', '12–18 tháng (sau N2)', '~9.700 từ (gồm N5–N2)', '~2.136 chữ (gồm N5–N2)', '100/180 điểm', 'N1 là cấp cao nhất — hiểu tin tức, văn học, hội thoại trang trọng; đủ để học tập và làm việc chuyên sâu bằng tiếng Nhật.', 4, '2026-09-02 09:48:36.232', '2026-09-02 09:48:36.232', '~650 mẫu (gồm N5–N2)', '+3.700 từ mới', '+1.136 chữ mới', '+150 mẫu mới');
INSERT INTO public."JlptRoadmapLevel" (id, "externalKey", label, badge, color, duration, "vocabTarget", "kanjiTarget", "passScore", summary, "sortOrder", "createdAt", "updatedAt", "grammarTarget", "vocabIncrement", "kanjiIncrement", "grammarIncrement") VALUES (1, 'n5', 'JLPT N5', 'Sơ cấp', '#22c55e', '4–6 tháng', '~800 từ', '~100 chữ', '80/180 điểm', 'N5 là cấp độ đầu tiên — đủ để giao tiếp cơ bản, giới thiệu bản thân, mua sắm, hỏi đường đơn giản.', 0, '2026-06-25 10:52:31.299', '2026-06-25 10:52:31.299', '~80 mẫu', '', '', '');
INSERT INTO public."JlptRoadmapLevel" (id, "externalKey", label, badge, color, duration, "vocabTarget", "kanjiTarget", "passScore", summary, "sortOrder", "createdAt", "updatedAt", "grammarTarget", "vocabIncrement", "kanjiIncrement", "grammarIncrement") VALUES (2, 'n4', 'JLPT N4', 'Sơ cấp cao', '#3b82f6', '4–6 tháng (sau N5)', '~1.500 từ (gồm N5)', '~300 chữ (gồm N5)', '90/180 điểm', 'N4 mở rộng giao tiếp hàng ngày — nói về kinh nghiệm, lịch trình, ý kiến đơn giản, đọc tin ngắn.', 1, '2026-06-25 10:52:31.379', '2026-06-25 10:52:31.379', '~170 mẫu (gồm N5)', '+700 từ mới', '+200 chữ mới', '+90 mẫu mới');
INSERT INTO public."JlptRoadmapLevel" (id, "externalKey", label, badge, color, duration, "vocabTarget", "kanjiTarget", "passScore", summary, "sortOrder", "createdAt", "updatedAt", "grammarTarget", "vocabIncrement", "kanjiIncrement", "grammarIncrement") VALUES (3, 'n3', 'JLPT N3', 'Trung cấp', '#a855f7', '6–9 tháng (sau N4)', '~3.750 từ (gồm N5–N4)', '~650 chữ (gồm N5–N4)', '95/180 điểm', 'N3 là cầu nối trung cấp — hiểu tin tức, hội thoại công việc, văn viết không quá trang trọng.', 2, '2026-06-25 10:52:31.426', '2026-06-25 10:52:31.426', '~350 mẫu (gồm N5–N4)', '+2.250 từ mới', '+350 chữ mới', '+180 mẫu mới');
