INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (518, '六', 'LỤC', 'ろく', 'む-つ', '6', '中国（ちゅうごく）の人（ひと）は、６をこうやって表（あらわ）します', 'Người Trung Quốc biểu thị số 6 bằng cách như vầy.', '/media/kanji/kanji512/bai1/six.jpg', 6, 34, '2026-06-25 09:21:59.932', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (519, '七', 'THẤT', 'しち', 'し,なな, なな-つ, なの, しっ, な, ひち', '7', '2たす５は７です', '2 cộng 5 bằng 7.', '/media/kanji/kanji512/bai1/seven.jpg', 7, 34, '2026-06-25 09:21:59.964', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (520, '八', 'BÁT', 'はち', 'や、や-つ', '8', 'カタカナの「ハチ」は［八（はち）］です', 'Nó là chữ「ハ」 trong từ katakana「ハチ」(số 8).', '/media/kanji/kanji512/bai1/eight.jpg', 8, 34, '2026-06-25 09:22:00.002', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (521, '九', 'CỬU', 'きゅう, く', 'ここの-つ', '9', '10回（かい）腕（うで）立（た）て伏（ふ）せができますか。「７，８，９…だめだ」', '”Bạn có thể hít đất 10 lần không?”', '/media/kanji/kanji512/bai1/nine.jpg', 9, 34, '2026-06-25 09:22:00.043', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (522, '十', 'THẬP', 'じゅう, じ, とお', NULL, 'mười', '常（じょう）本（ほん）を束（たば）ねましょう', 'Chúng ta hãy bó 10 que lại.', '/media/kanji/kanji512/bai1/ten.jpg', 10, 34, '2026-06-25 09:22:00.089', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (523, '百', 'BÁCH', 'ひゃく, もも', NULL, 'trăm, bách niên', '100を90度（ど）右（みぎ）へ回転（かいてん）すると、［百（ひゃく）］のようになります', 'Xoay số ”100 ” 90 độ về bên phải thì nó sẽ trở thành chữ 「百」', '/media/kanji/kanji512/bai1/hundred.jpg', 11, 34, '2026-06-25 09:22:00.132', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (524, '千', 'THIÊN', 'せん, ち', NULL, 'nghìn, nhiều, thiên lí', '十（じゅう）に［ノ］を足（た）して、もっと多（おお）い、［千（せん）］になりました', 'Cộng nét 「ノ」vào số 10「十」 ta sẽ có một số lớn hơn rất nhiều, số 1000', '/media/kanji/kanji512/bai1/thousand.jpg', 12, 34, '2026-06-25 09:22:00.172', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (525, '万', 'VẠN', 'まん, ばん, →萬［萬', NULL, 'vạn, nhiều, vạn vật', '一万（いちまん）は5桁（けた）の数字（すうじ）です', 'Số 10.000 là số có 5 chữ số.', '/media/kanji/kanji512/bai1/ten_thousand.jpg', 13, 34, '2026-06-25 09:22:00.21', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (526, '円', 'VIÊN', 'えん', 'つぶら,まる-い, まる, まど, まど-か, まろ-やか, のぶ, まどか, みつ', 'viên mãn, tiền Yên', '円（えん）の形（かたち）です', 'Hình dạng của hình tròn', '/media/kanji/kanji512/bai1/yen_circle.jpg', 14, 34, '2026-06-25 09:22:00.239', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (527, '口', 'KHẨU', 'こう, く, くち', NULL, 'miệng, nhân khẩu, khẩu ngữ', '口（くち）の形（かたち）です', 'Hình dạng của cái miệng', '/media/kanji/kanji512/bai1/mouth.jpg', 15, 34, '2026-06-25 09:22:00.255', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (528, '目', 'MỤC', 'もく, ぼく, め', NULL, 'mắt, hạng mục, mục lục', '目（め）の形（かたち）です', 'Hình dạng của con mắt', '/media/kanji/kanji512/bai1/eye.jpg', 16, 34, '2026-06-25 09:22:00.271', '2026-09-02 08:51:28.661', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (540, '寺', 'TỰ', 'じ, てら', NULL, 'chùa', 'ほら、土（つち）の上（うえ）にお寺（てら）があります', 'Nhìn này, có ngôi chùa trên mặt đất kìa!', '/media/kanji/kanji512/bai2/temple.jpg', 12, 35, '2026-06-25 09:22:00.594', '2026-09-02 08:51:28.669', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (541, '時', 'THỜI', 'じ, とき', NULL, 'thời gian', '昔（むかし）、人々（ひとびと）はお寺（てら）の鐘（かね）を鳴（な）らして、時間（じかん）を知（し）らせました', 'Ngày xưa, người ta rung chuông chùa để báo giờ.', '/media/kanji/kanji512/bai2/time.jpg', 13, 35, '2026-06-25 09:22:00.61', '2026-09-02 08:51:28.669', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (542, '半', 'BÁN', 'はん', 'なか-ば', 'bán cầu, bán nguyệt', '三本（さんぼん）の線（せん）を半分（はんぶん）に切（き）りましょう。あれ、最初（さいしょ）の線（せん）しか切（き）れません', 'Hãy cắt 3 đường ra làm đôi.', '/media/kanji/kanji512/bai2/half.jpg', 14, 35, '2026-06-25 09:22:00.632', '2026-09-02 08:51:28.669', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (543, '刀', 'ĐAO', 'とう, かたな', NULL, 'cái đao', '刀（かたな）の形（かたち）です', 'Hình dạng của con dao', '/media/kanji/kanji512/bai2/sword.jpg', 15, 35, '2026-06-25 09:22:00.648', '2026-09-02 08:51:28.669', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (544, '分', 'PHÂN', 'ぶん, ふん, ぶ', 'わ-ける', 'phân số, phân chia', '刀（かたな）で半分（はんぶん）に切（き）りましょう', 'Hãy chia nó ra phân nửa bằng con dao!', '/media/kanji/kanji512/bai2/minute_to_divide.jpg', 16, 35, '2026-06-25 09:22:00.657', '2026-09-02 08:51:28.669', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (545, '上', 'THƯỢNG', 'じょう, しょう', 'あおい,うえ, -うえ, うわ-, かみ, あ-げる, -あ-げる, あ-がる, -あ-がる, あ-がり, -あ-がり, のぼ-る, のぼ-り, のぼ-せる, のぼ-す, よ-す, あげ, い, か,', 'thượng tầng, thượng đẳng', 'ここが線（せん）より上（うえ）です', 'chổ này là phía trên đường thẳng', '/media/kanji/kanji512/bai3/up.jpg', 1, 36, '2026-06-25 09:22:00.68', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (546, '下', 'HẠ', 'か, げ', 'した、さ-げる、くだ-る、もと', 'dưới, hạ đẳng', 'ここが線（せん）より下（した）です', 'chổ này là phía dưới đường thẳng', '/media/kanji/kanji512/bai3/down.jpg', 2, 36, '2026-06-25 09:22:00.699', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
