INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (554, '午', 'NGỌ', 'ご, うま', NULL, 'chính ngọ', 'この漢字（かんじ）には、［十（じゅう）」と［二（に）」が入（はい）っています。十二時（じゅうにじ）は正午（しょうご）です', 'Chữ hán này gồm có số 10「十」 và số 2「二」. 12 giờ là buổi trưa.', '/media/kanji/kanji512/bai3/noon.jpg', 10, 36, '2026-06-25 09:22:00.924', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (555, '門', 'MÔN', 'もん, かど', NULL, 'cửa, nhập môn, môn đồ, bộ môn', '門（もん）の形（かたち）です', 'Hình dạng cánh cổng', '/media/kanji/kanji512/bai3/gate.jpg', 11, 36, '2026-06-25 09:22:00.941', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (556, '間', 'GIAN', 'かん, けん, あいだ, ま', NULL, 'trung gian, không gian', '門（もん）の間（あいだ）にお日様（ひさま）が見（み）えます', 'Ta có thể thấy mặt trời giữa hai cánh cổng.', '/media/kanji/kanji512/bai3/between.jpg', 12, 36, '2026-06-25 09:22:00.964', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (557, '東', 'ĐÔNG', 'とう, ひがし', NULL, 'phía đông', '日（ひ）は東（ひがし）から昇（のぼ）ります。木（き）の後（うし）ろにお日様（ひさま）が見（み）えます', 'Mặt trời mọc ở hướng đông. Ta có thể nhìn thấy mặt trời phía sau ngọn cây.', '/media/kanji/kanji512/bai3/east.jpg', 13, 36, '2026-06-25 09:22:00.986', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (558, '西', 'TÂY', 'せい, さい, にし', NULL, 'phương tây', '四（よっ）つの方角（ほうがく）の一（ひと）つが西（にし）です', 'Một （一）trong 4 （四）hướng là hướng Tây.', '/media/kanji/kanji512/bai3/west.jpg', 14, 36, '2026-06-25 09:22:01.008', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (559, '南', 'NAM', 'なん, な, みなみ', NULL, 'phương nam', '二（ふた）つの植物（しょくぶつ）は南（みなみ）向（む）きの庭（にわ）で育（そだ）っています', '2 cây mọc trong vườn quay về hướng nam.', '/media/kanji/kanji512/bai3/south.jpg', 15, 36, '2026-06-25 09:22:01.034', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (560, '北', 'BẮC', 'ほく, きた', NULL, 'phương bắc', '北（きた）は寒（さむ）いので、二人（ふたり）ほ人（ひと）が背中（せなか）を合（あ）わせて座（すわ）っています', 'Vì phía bắc trời lạnh nên 2 người ngồi đâu lưng lại với nhau.', '/media/kanji/kanji512/bai3/north.jpg', 16, 36, '2026-06-25 09:22:01.053', '2026-09-02 08:51:28.673', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (572, '年', 'NIÊN', 'ねん, ね, とし', NULL, 'năm, niên đại', '米（こめ）の収穫（しゅうかく）までに一年（いちねん）かかります', 'Mất một năm để thu hoạch lúa.', '/media/kanji/kanji512/bai4/year.jpg', 12, 37, '2026-06-25 09:22:01.306', '2026-09-02 08:51:28.678', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (573, '去', 'KHỨ', 'きょ, こ', 'さ-る', 'quá khứ, trừ khử', '過去（かこ）に生（い）きていた私（わたし）、今（いま）は土（つち）の中（なか）です', 'Tôi là người đã sống trong quá khứ, bây giờ tôi ở trong lòng đất.', '/media/kanji/kanji512/bai4/past_toleave.jpg', 13, 37, '2026-06-25 09:22:01.334', '2026-09-02 08:51:28.678', NULL, 'N5', NULL, NULL, NULL);
