INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (575, '王', 'VƯƠNG', 'うう', NULL, 'vương giả', '王様（おうさま）が立（た）っています', 'Đức Vua đang đứng.', '/media/kanji/kanji512/bai4/king.jpg', 15, 37, '2026-06-25 09:22:01.362', '2026-09-02 08:51:28.678', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (576, '国', 'QUỐC', 'こく, くに', NULL, 'nước, quốc gia, quốc ca', '宝石（ほうせき）を持（も）った王（おう）が国（くに）を支配（しはい）します', 'Nhà vua nắm giữ ngọc bảo trị vì đất nước.', '/media/kanji/kanji512/bai4/country.jpg', 16, 37, '2026-06-25 09:22:01.387', '2026-09-02 08:51:28.678', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (581, '良', 'LƯƠNG', 'りょう', 'よ-い', 'tốt, lương tâm, lương tri', '誰（だれ）でもおなかがいっぱいの時（とき）は気分（きぶん）がいいです', 'Bất kỳ ai cũng có tinh thần tốt khi no bụng.', '/media/kanji/kanji512/bai5/good_well.jpg', 5, 38, '2026-06-25 09:22:01.486', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (582, '食', 'THỰC', 'しょく, じき', 'た-べる、く-う', 'ẩm thực, thực đường', '家（いえ）でするいいこと、それは食（た）べることです', 'Điều làm tôi cảm thấy thoải mái là việc ăn ở nhà.', '/media/kanji/kanji512/bai5/eat.jpg', 6, 38, '2026-06-25 09:22:01.494', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (583, '飲', 'ẨM', 'いん', 'の-む', 'ẩm thực', '大（おお）きな口（くち）を開（あ）けて、食（た）べたり飲（の）んだりします', 'Mở to miệng để ăn và uống.', '/media/kanji/kanji512/bai5/drink.jpg', 7, 38, '2026-06-25 09:22:01.51', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (584, '会', 'HỘI', 'かい, え', 'あ-う', 'hội họp, đại hội', 'あなたと私（わたし）、二人（ふたり）が家（いえ）の中（なか）で会（あ）います', '2（二） chúng ta sẽ gặp trong một ngôi nhà.', '/media/kanji/kanji512/bai5/to_meet.jpg', 8, 38, '2026-06-25 09:22:01.526', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (585, '耳', 'NHĨ', 'じ, みみ', NULL, 'tai', '耳（みみ）の形（かたち）です', 'Hình dạng của cái tai.', '/media/kanji/kanji512/bai5/ear.jpg', 9, 38, '2026-06-25 09:22:01.553', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (586, '聞', 'VĂN', 'ぶん, もん', 'き-く', 'nghe, tân văn (báo)', '門（もん）の所（ところ）で耳（みみ）をそばだてて聞（き）いています', 'Ai đó đang ghé tai vào cổng để nghe ngóng.', '/media/kanji/kanji512/bai5/listen.jpg', 10, 38, '2026-06-25 09:22:01.564', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (587, '言', 'NGÔN', 'げん, ごん', 'い-う、こと', 'ngôn ngữ, ngôn luận, phát ngôn', '口（くち）を使（つか）って何（なに）か言（い）います', 'Nói điều gì đó bằng miệng.', '/media/kanji/kanji512/bai5/say.jpg', 11, 38, '2026-06-25 09:22:01.572', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (588, '話', 'THOẠI', 'わ', 'はなし、はな-す', 'nói chuyện, đối thoại, giai thoại', '何千（なんぜん）もの単語（たんご）を使（つか）って話（はな）します', 'Mọi người sử dụng hàng ngàn từ vựng để nói chuyện.', '/media/kanji/kanji512/bai5/speak.jpg', 12, 38, '2026-06-25 09:22:01.595', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (590, '待', 'ĐÃI', 'たい', 'ま-つ', 'đợi, đối đãi', 'お寺（てら）の前（まえ）の道（みち）で待（ま）っています', 'Tôi đợi bạn trên con đường ở trước chùa.', '/media/kanji/kanji512/bai5/wait.jpg', 14, 38, '2026-06-25 09:22:01.632', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (591, '周', 'CHU', 'しゅう', 'まわ-り', 'chu vi, chu biên', '食（た）べたものは土（つち）に返（かえ）ります。すべてのものは循環（じゅんかん）します', 'Những thứ mình đã ăn sẽ trở về với đất. Mọi vật đều tuần hoàn.', '/media/kanji/kanji512/bai5/go_around.jpg', 15, 38, '2026-06-25 09:22:01.64', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (592, '週', 'CHU', 'しゅう', NULL, 'tuần', 'この道（みち）を一周（いっしゅう）するのに一週間（いっしゅうかん）かかります', 'Mất 1 tuần để đi vòng quanh con đường này.', '/media/kanji/kanji512/bai5/week.jpg', 16, 38, '2026-06-25 09:22:01.654', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (598, '古', 'CỔ', 'こ', 'ふる-い', 'cũ, cổ điển, đồ cổ', '同（おな）じ話（はなし）を十回（じゅうかい）聞（き）くと、その話（はなし）は古（ふる）くなります', 'Khi ta nghe cùng một câu chuyện 10 （十）lần thì câu chuyện đó sẽ trở nên cũ đi.', '/media/kanji/kanji512/bai6/old.jpg', 6, 39, '2026-06-25 09:22:01.768', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (599, '元', 'NGUYÊN', 'げん, がん, もと', NULL, 'gốc', '二人（ふたり）で走（はし）れば、もっと元気（げんき）になります', 'Nếu 2 người chạy cùng nhau thì họ sẽ trở nên khoẻ mạnh hơn.', '/media/kanji/kanji512/bai6/origin.jpg', 7, 39, '2026-06-25 09:22:01.793', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (600, '気', 'KHÍ', 'き, け', NULL, 'không khí, khí chất, khí khái, khí phách', '息（いき）を強（つよ）く吐（は）きすぎると、「気（き）」が出（で）てくるかもしれません', 'Nếu bạn thở ra quá mạnh thì không chừng tinh thần bạn sẽ xuất hiện.', '/media/kanji/kanji512/bai6/spirit.jpg', 8, 39, '2026-06-25 09:22:01.823', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (601, '多', 'ĐA', 'た', 'おお-い', 'đa số', '「タ」がたくさんあります', 'Có nhiều chữ「タ」', '/media/kanji/kanji512/bai6/many_much.jpg', 9, 39, '2026-06-25 09:22:01.846', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (602, '少', 'THIẾU, THIỂU', 'しょう', 'すく-ない、すこ-し', 'thiếu niên; thiểu số', '小（ちい）さいものを分（わ）けると、少（すこ）ししかもらえます', 'Khi bạn phân chia một vật nhỏ, bạn chỉ có thể nhận được một ít.', '/media/kanji/kanji512/bai6/little.jpg', 10, 39, '2026-06-25 09:22:01.874', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (603, '広', 'QUẢNG', 'こう', 'ひろ-い］ →廣［廣', 'quảng trường, quảng đại', '私（わたし）の家（うち）です。広（ひろ）いでしょう', '”Đây là nhà của tôi. Nó rộng phải không?”', '/media/kanji/kanji512/bai6/spacious.jpg', 11, 39, '2026-06-25 09:22:01.896', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (604, '早', 'TẢO', 'そう, さ', 'はや-い', 'sớm, tảo hôn', '日曜日（にちようび）に十時（じゅうじ）に起（お）きるのは早（はや）すぎます', 'Việc dậy lúc 10 giờ vào ngày chủ nhật là quá sớm.', '/media/kanji/kanji512/bai6/early.jpg', 12, 39, '2026-06-25 09:22:01.917', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
