INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (606, '明', 'MINH', 'めい, みょう', 'あか-るい、あき-らか', 'quang minh, minh tinh', '「日（ひ）」と「月（つき）」を合（あ）わせれば、明（あか）るくなります', 'Nếu kết hợp mặt trời 「日」và mặt trăng 「月」lại với nhau trời sẽ trở nên sáng hơn.', '/media/kanji/kanji512/bai6/bright.jpg', 14, 39, '2026-06-25 09:22:01.968', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (607, '好', 'HẢO, HIẾU', 'こう', 'この-む、す-く', 'hữu hảo; hiếu sắc', 'その女（おんな）の人（ひと）は子（こ）どもが好（す）きです', 'Người nữ ấy thích trẻ con.', '/media/kanji/kanji512/bai6/like.jpg', 15, 39, '2026-06-25 09:22:01.992', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (608, '友', 'HỮU', 'ゆう, とも', NULL, 'bạn hữu, hữu hảo', '友達（ともだち）は互（たが）いに手（て）助（だす）けします', 'Bạn bè đưa tay giúp đỡ lẫn nhau.', '/media/kanji/kanji512/bai6/friend.jpg', 16, 39, '2026-06-25 09:22:02.002', '2026-09-02 08:51:28.689', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (621, '店', 'ĐIẾM', 'てん, みせ', NULL, 'cửa hàng, tửu điếm', '店先（みせさき）の台（だい）に、トマトが積（つ）んであります', 'Cà chua được chất trên gian hàng trước cửa tiệm.', '/media/kanji/kanji512/bai7/shop.jpg', 13, 40, '2026-06-25 09:22:02.281', '2026-09-02 08:51:28.694', NULL, 'N5', NULL, NULL, NULL);
