INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (733, '英', 'ANH', 'えい, はなぶさ', NULL, 'anh hùng, anh tú, anh tuấn', '真（ま）ん中（なか）の人（ひと）が英雄（えいゆう）です。草（くさ）の根（ね）運動（うんどう）から生（う）まれました', 'Người ở chính giữa là anh hùng. Đã được sinh ra từ sự chuyển động của cội rễ cỏ cây.', '/media/kanji/kanji512/bai14/english_excellent.jpg', 13, 47, '2026-06-25 09:22:04.924', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (734, '質', 'CHẤT', 'しつ, しち, ち, たち', NULL, 'vật chất, phẩm chất, khí chất', '大（おお）きい貝（かい）を2本（ほん）のおので割（わ）り、その質（しつ）を調（しら）べます', 'Làm vỡ vỏ sò lớn bằng rìu và kiểm tra chất lượng của nó.', '/media/kanji/kanji512/bai14/quality.jpg', 14, 47, '2026-06-25 09:22:04.944', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (735, '問', 'VẤN', 'もん', 'と-う', 'vấn đáp, chất vấn, vấn đề', '門（もん）のところで質問（しつもん）します', 'Tôi đã hỏi bên cánh cổng.', '/media/kanji/kanji512/bai14/question.jpg', 15, 47, '2026-06-25 09:22:04.961', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (736, '説', 'THUYẾT', 'せつ, ぜい', 'と-く', 'tiểu thuyết, học thuyết, lí thuyết', 'お兄（にい）さんが説明（せつめい）しています', 'Anh trai đang giải thích.', '/media/kanji/kanji512/bai14/explain.jpg', 16, 47, '2026-06-25 09:22:04.982', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
