INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (741, '寒', 'HÀN', 'かん', 'さ,さむ-い, さん', 'lạnh', '寒（さむ）い日（ひ）に、雪（ゆき）の上（うえ）に足跡（あしあと）を残（のこ）してあなたの家（いえ）まで来（き）ました', 'Vào những ngày lạnh giá, tôi đến nhà bạn và để lại những dấu chân trên tuyết.', '/media/kanji/kanji512/bai15/cold.jpg', 5, 48, '2026-06-25 09:22:05.093', '2026-09-02 08:51:28.757', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (742, '重', 'TRỌNG, TRÙNG', 'じゅう, ちょう', 'おも-い、かさ-なる', 'trọng lượng; trùng phùng', '1000冊（さつ）の本（ほん）は重（おも）いです', 'Một ngàn quyển sách （千）sẽ rất nặng.', '/media/kanji/kanji512/bai15/heavy.jpg', 6, 48, '2026-06-25 09:22:05.116', '2026-09-02 08:51:28.757', NULL, 'N4', NULL, NULL, NULL);
