INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (912, '党', 'ĐẢNG', 'とう', NULL, 'đảng phái', '兄（あに）は政党（せいとう）に入（はい）りました', 'Anh trai tôi （兄）gia nhập vào chính đảng.', '/media/kanji/kanji512/bai25/political_party.jpg', 16, 58, '2026-06-25 09:22:08.846', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (916, '暖', 'NOÃN', 'だん', 'あたた-か', 'ấm', '友達（ともだち）と手（て）を合（あ）わせると、暖（あたた）かいです', 'Chắp tay cùng bạn bè ta sẽ thấy ấm áp.', '/media/kanji/kanji512/bai26/warm.jpg', 4, 59, '2026-06-25 09:22:08.936', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (917, '涼', 'LƯƠNG', 'りょう', 'すず-しい', 'mát', '雨（あめ）が降（ふ）って京（きょう）の都（みやこ）が涼（すず）しくなりました', 'Mưa xuống làm mát thủ đô.', '/media/kanji/kanji512/bai26/cool.jpg', 5, 59, '2026-06-25 09:22:08.953', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (918, '静', 'TĨNH', 'せい, じょう', 'しず-か', 'bình tĩnh, trấn tĩnh', '争（あらそ）いが終（お）わると、空（そら）は青（あお）く、その場所（ばしょ）は静（しず）かになりました', 'Xung đột kết thúc, bầu trời trong xanh và nơi chốn trở nên tĩnh lặng.', '/media/kanji/kanji512/bai26/quiet.jpg', 6, 59, '2026-06-25 09:22:08.964', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (919, '公', 'CÔNG', 'こう, おおやけ', NULL, 'công cộng, công thức, công tước', '公衆（こうしゅう）のために働（はたら）くのは大変（たいへん）です', 'Làm việc vì công chúng rất vất vả.', '/media/kanji/kanji512/bai26/public.jpg', 7, 59, '2026-06-25 09:22:08.975', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (920, '園', 'VIÊN', 'えん, その', NULL, 'vườn, điền viên, hoa viên, công viên', '土曜日（どようび）に公園（こうえん）に踊（おど）りに行（い）きます', 'Thứ bảy đi công viên nhảy múa.', '/media/kanji/kanji512/bai26/park.jpg', 8, 59, '2026-06-25 09:22:09', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (922, '連', 'LIÊN', 'れん', 'つら-なる、つ-れる', 'liên tục, liên lạc', '目的（もくてき）地（ち）につながる道（みち）を運転（うんてん）していきました', 'Lái xe trên con đường nối với nơi đến.', '/media/kanji/kanji512/bai26/link.jpg', 10, 59, '2026-06-25 09:22:09.039', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
