INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (964, '成', 'THÀNH', 'せい, じょう', 'な-す', 'thành tựu, hoàn thành, trở thành', '武器（ぶき）を使（つか）って、その使命（しめい）を成（な）し遂（と）げました', 'Tôi hoàn thành sứ mệnh bằng việc sử dụng vũ khí.', '/media/kanji/kanji512/bai29/accomplished.jpg', 4, 62, '2026-06-25 09:22:10.459', '2026-09-02 08:51:28.869', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (965, '絶', 'TUYỆT', 'ぜつ', 'た-える', 'đoạn tuyệt, tuyệt diệu', 'この色（いろ）の糸（いと）は、もう作（つく）られていません', 'Chỉ màu （色）này không được sản xuất nữa.', '/media/kanji/kanji512/bai29/discontinue.jpg', 5, 62, '2026-06-25 09:22:10.496', '2026-09-02 08:51:28.869', NULL, 'N3', NULL, NULL, NULL);
