INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (1008, '直', 'TRỰC', 'ちょく, じき', 'ただ-ちに、なお-す', 'trực tiếp, chính trực', '「ほら、壊（こわ）れているよ」「直（なお）そう」', '”Nhìn kìa, nó bị hư đấy!” ”Chúng ta hãy sửa nó đi!”', '/media/kanji/kanji512/bai31/fix_direct.jpg', 16, 64, '2026-06-25 09:22:11.806', '2026-09-02 08:51:28.886', NULL, 'N3', NULL, NULL, NULL);
