INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (578, '行', 'HÀNH, HÀNG', 'こう, ぎょう, あん', 'い-く、ゆ-く、おこな-う', 'thực hành, lữ hành; ngân hàng', 'この角（かど）でどこに行（い）くか決（き）めてください', 'Tại góc đường này bạn hãy quyết định là sẽ đi đâu.', '/media/kanji/kanji512/bai5/to_go.jpg', 2, 38, '2026-06-25 09:22:01.439', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
