INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (580, '来', 'LAI', 'らい', 'く-る、きた-る', 'đến, tương lai, vị lai', '十月（じゅうがつ）が来（く）ると米（こめ）が収穫（しゅうかく）できます', 'Đến tháng 10 thì có thể thu hoạch lúa.', '/media/kanji/kanji512/bai5/come.jpg', 4, 38, '2026-06-25 09:22:01.474', '2026-09-02 08:51:28.683', NULL, 'N5', NULL, NULL, NULL);
