INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (641, '春', 'XUÂN', 'しゅん, はる', NULL, 'mùa xuân, thanh xuân', '春（はる）は来（き）ました。三人（さんにん）の人（ひと）がお日様（ひさま）を見（み）ています', 'Mùa xuân đến rồi. Ba người đang người ngắm mặt trời.', '/media/kanji/kanji512/bai9/spring.jpg', 1, 42, '2026-06-25 09:22:02.62', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (642, '夏', 'HẠ', 'か, げ, なつ', NULL, 'mùa hè', '夏（なつ）は暑（あつ）いので、人（ひと）が日陰（ひかげ）でぐったりしています', 'Vì mùa hè quá nóng, nên con người mệt lử dưới bóng râm.', '/media/kanji/kanji512/bai9/summer.jpg', 2, 42, '2026-06-25 09:22:02.636', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (643, '秋', 'THU', 'しゅう, あき, とき', NULL, 'mùa thu', '秋（あき）になると、稲（いね）が実（みの）り、葉（は）は日（ひ）の色（いろ）になります', 'Thu đến, lúa đơm bông, lá cây chuyển sang màu của lửa.', '/media/kanji/kanji512/bai9/autumn.jpg', 3, 42, '2026-06-25 09:22:02.654', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (644, '冬', 'ĐÔNG', 'とう, ふゆ', NULL, 'mùa đông', '冬（ふゆ）は氷（こおり）の上（うえ）を歩（ある）くと滑（すべ）ります', 'Sẽ rất trơn trượt khi đi trên băng vào mùa đông.', '/media/kanji/kanji512/bai9/winter.jpg', 4, 42, '2026-06-25 09:22:02.674', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (645, '朝', 'TRIỀU', 'ちょう, あさ', NULL, 'buổi sáng, triều đình', '十月（じゅうがつ）十日（とおか）の朝（あさ）です', 'Buổi sáng ngày 10 tháng 10.', '/media/kanji/kanji512/bai9/morning.jpg', 5, 42, '2026-06-25 09:22:02.693', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (646, '昼', 'TRÚ', 'ちゅう, ひる', NULL, 'buổi trưa', '昼（ひる）、日（ひ）が高（たか）くなると、日（ひ）よけをつるします', 'Khi mặt trời lên cao vào buổi trưa chúng ta sẽ treo những tấm bạt che nắng lên.', '/media/kanji/kanji512/bai9/daytime.jpg', 6, 42, '2026-06-25 09:22:02.714', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (647, '夕', 'TỊCH', 'せき, ゆう, ゆうべ', NULL, 'tịch dương', '夕方（ゆうがた）、月（つき）と鳥（とり）が見（み）えます', 'Vào xế chiều bạn sẽ thấy mặt trăng và chim chóc.', '/media/kanji/kanji512/bai9/early_evening.jpg', 7, 42, '2026-06-25 09:22:02.728', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (648, '方', 'PHƯƠNG', 'ほう, かた', NULL, 'phương hướng, phương pháp', '旗（はた）のある方（ほう）へ行（い）ってください', 'Vui lòng đi theo hướng của lá cờ.', '/media/kanji/kanji512/bai9/direction_person.jpg', 8, 42, '2026-06-25 09:22:02.752', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (649, '晩', 'VÃN', 'ばん', NULL, 'buổi tối', '晩（ばん）にならないうちに、急（いそ）いで家（いえ）に帰（かえ）ります', 'Hối hả về nhà trong lúc trời chưa tối.', '/media/kanji/kanji512/bai9/evening.jpg', 9, 42, '2026-06-25 09:22:02.774', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (650, '夜', 'DẠ', 'や, よ, よる', NULL, 'ban đêm, dạ cảnh, dạ quang', '夜（よる）、帽子（ぼうし）をかぶった人（ひと）が月（つき）と雲（くも）を見（み）ています', 'Buổi tối, một người đội mũ ngắm trăng và mây.', '/media/kanji/kanji512/bai9/night.jpg', 10, 42, '2026-06-25 09:22:02.793', '2026-09-02 08:51:28.708', NULL, 'N5', NULL, NULL, NULL);
