INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (689, '音', 'ÂM', 'おん, いん, おと, ね', NULL, 'âm thanh, phát âm', '日（ひ）が昇（のぼ）ると、人々（ひとびと）は立（た）ち上（あ）がって音（おと）をたてます', 'Khi mặt trời lên, mọi người đứng dậy và phát ra âm thanh.', '/media/kanji/kanji512/bai12/sound.jpg', 1, 45, '2026-06-25 09:22:03.769', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (690, '楽', 'LẠC, NHẠC', 'がく, らく', 'たの-しい', 'an lạc, lạc thú, âm nhạc', '木（き）の上（うえ）の白（しろ）い太鼓（たいこ）をたたいて楽（たの）しもう', 'Hãy thưởng thức gõ cái trống màu trắng trên cái giá đỡ gỗ!', '/media/kanji/kanji512/bai12/fun_comfortable.jpg', 2, 45, '2026-06-25 09:22:03.813', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (691, '歌', 'CA', 'か', 'うた、うた-う', 'ca dao, ca khúc', '大（おお）きい口（くち）を開（あ）けてみんなで歌（うた）っています', 'Tất cả mọi người đang mở to miệng hát.', '/media/kanji/kanji512/bai12/sing.jpg', 3, 45, '2026-06-25 09:22:03.824', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (692, '自', 'TỰ', 'じ, し', 'みずか-ら、おの-ずから', 'tự do, tự kỉ, tự thân', '日本（にほん）では、鼻（はな）を指（ゆび）さして自分（じぶん）のことを表（あらわ）します', 'Ở Nhật người ta ám chỉ "bản thân" bằng cách chỉ vào mũi của mình.', '/media/kanji/kanji512/bai12/self.jpg', 4, 45, '2026-06-25 09:22:03.856', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (693, '転', 'CHUYỂN', 'てん', 'ころ-ぶ', 'chuyển động', '車（くるま）から転（ころ）がり落（お）ちました', 'Tôi đã bị ngã nhào ra khỏi xe hơi.', '/media/kanji/kanji512/bai12/roll_over.jpg', 5, 45, '2026-06-25 09:22:03.899', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (694, '乗', 'THỪA', 'じょう', 'の-る', 'lên xe', '木（き）の上（うえ）に立（た）って、枝（えだ）に乗（の）ろうとしています', 'Một người đang đứng trên cây và định leo lên cành cây.', '/media/kanji/kanji512/bai12/get%20on.jpg', 6, 45, '2026-06-25 09:22:03.918', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (695, '写', 'TẢ', 'しゃ', 'うつ-す', 'miêu tả', '帽子（ぼうし）をかぶった男性（だんせい）の写真（しゃしん）です', 'Tấm hình của người đàn ông đội mũ.', '/media/kanji/kanji512/bai12/photograph.jpg', 7, 45, '2026-06-25 09:22:03.949', '2026-09-02 08:51:28.733', NULL, 'N4', NULL, NULL, NULL);
