INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (722, '室', 'THẤT', 'しつ, むろ', NULL, 'phòng, giáo thất', '土曜日（どようび）はいつも室内（しつない）にいます', 'Thứ bảy nào tôi cũng ở trong phòng của tôi.', '/media/kanji/kanji512/bai14/room.jpg', 2, 47, '2026-06-25 09:22:04.653', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (723, '羽', 'VŨ', 'う, はね', NULL, 'lông vũ', '羽（はね）の形（かたち）です', 'Hình dạng của đôi cánh.', '/media/kanji/kanji512/bai14/wing.jpg', 3, 47, '2026-06-25 09:22:04.685', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (724, '習', 'TẬP', 'しゅう', 'なら-う', 'học tập', '鳥（とり）は白（しろ）い建物（たてもの）の上（うえ）で羽（はね）を動（うご）かして、飛（と）び方（かた）を習（なら）います', 'Trên toà nhà màu trắng, những con chim vỗ cánh tập bay.', '/media/kanji/kanji512/bai14/learn.jpg', 4, 47, '2026-06-25 09:22:04.706', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (725, '漢', 'HÁN', 'かん', NULL, 'hảo hán', '中国（ちゅうごく）人（じん）の夫（おっと）が草（くさ）を頭（あたま）の上（うえ）に載（の）せて川（かわ）を渡（わた）っています', 'Ông chồng người Trung Quốc chất cỏ lên đầu rồi băng qua sông.', '/media/kanji/kanji512/bai14/chinese.jpg', 5, 47, '2026-06-25 09:22:04.736', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (726, '字', 'TỰ', 'じ, あざ', NULL, 'chữ, văn tự', '子（こ）どもは家（いえ）の中（なか）で字（じ）を習（なら）います', 'Đứa trẻ học chữ ở trường.', '/media/kanji/kanji512/bai14/letter_character.jpg', 6, 47, '2026-06-25 09:22:04.756', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (727, '式', 'THỨC', 'しき', NULL, 'hình thức, phương thức, công thức', '私（わたし）の結婚式（けっこんしき）です', 'Đây là lễ cưới của tôi.', '/media/kanji/kanji512/bai14/ceremony_style.jpg', 7, 47, '2026-06-25 09:22:04.793', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (728, '試', 'THÍ', 'し', 'こころ-みる', 'thí nghiệm, thí điểm', '式（しき）で：「この人（ひと）を一生（いっしょう）愛（あい）しますか」 「やってみます」', 'Tại buổi lễ: ”Con sẽ yêu người này đến hết cuộc đời không?”', '/media/kanji/kanji512/bai14/try.jpg', 8, 47, '2026-06-25 09:22:04.815', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (729, '験', 'NGHIỆM', 'けん, げん', 'ため-す、しるし、げん', 'thí nghiệm, hiệu nghiệm, kinh nghiệm', '山（やま）に登（のぼ）る前（まえ）に、馬（うま）を調（しら）べます', 'Ta sẽ kiểm tra con ngựa trước khi leo núi.', '/media/kanji/kanji512/bai14/examine.jpg', 9, 47, '2026-06-25 09:22:04.828', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (730, '宿', 'TÚC', 'しゅく', 'やど-る、やど', 'tá túc, kí túc xá', 'この宿（やど）は百人（ひゃくにん）泊（と）まれます', 'Nhà trọ này có thể cho 100 khách trọ lại.', '/media/kanji/kanji512/bai14/inn.jpg', 10, 47, '2026-06-25 09:22:04.851', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (731, '題', 'ĐỀ', 'だい', NULL, 'đề tài, đề mục, chủ đề', '記者（きしゃ）は頭（あたま）と足（あし）を使（つか）って題材（だいざい）を探（さが）します', 'Nhà báo sử dụng đầu và chân để tìm kiếm đề tài.', '/media/kanji/kanji512/bai14/topic.jpg', 11, 47, '2026-06-25 09:22:04.866', '2026-09-02 08:51:28.749', NULL, 'N4', NULL, NULL, NULL);
