INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (769, '医', 'Y', 'い', NULL, 'y học, y viện', '医者（いしゃ）が屋（や）で傷（きず）着（つ）いた患者（かんじゃ）を治（なお）します', 'Bác sĩ chữa trị cho bệnh nhân bị thương do trúng tên.', '/media/kanji/kanji512/bai17/doctor_medicine.jpg', 1, 50, '2026-06-25 09:22:05.648', '2026-09-02 08:51:28.773', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (770, '始', 'THỦY', 'し', 'はじ-め', 'ban đầu, khai thủy, nguyên thủy', '台（だい）の上（うえ）でスピーチを始（はじ）めると、女（おんな）の人（ひと）が聞（き）きました', 'Khi tôi bắt đầu bài diễn thuyết trên bục, người phụ nữ đã lắng nghe.', '/media/kanji/kanji512/bai17/begin.jpg', 2, 50, '2026-06-25 09:22:05.669', '2026-09-02 08:51:28.773', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (771, '終', 'CHUNG', 'しゅう', 'お-わる、つい-に', 'chung kết, chung liễu', '私（わたし）たちの関係（かんけい）は糸（いと）のように長（なが）く続（つづ）きましたが、冬（ふゆ）に終（お）わりました', 'Mối quan hệ của chúng tôi kéo dài như sợi chỉ nhưng đã kết thúc vào mùa đông rồi.', '/media/kanji/kanji512/bai17/end.jpg', 3, 50, '2026-06-25 09:22:05.68', '2026-09-02 08:51:28.773', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (772, '石', 'THẠCH', 'せき, しゃく, こく, いし', NULL, 'đá, thạch anh, bảo thạch', '崖（がけ）と石（いし）の形（かたち）です', 'Hình dạng của một vách đá dốc đứng và một hòn đá.', '/media/kanji/kanji512/bai17/stone.jpg', 4, 50, '2026-06-25 09:22:05.697', '2026-09-02 08:51:28.773', NULL, 'N4', NULL, NULL, NULL);
