INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (801, '頭', 'ĐẦU', 'とう, ず, と, あたま, かしら', NULL, 'đầu não', '豆（まめ）みたいな頭（あたま）でしょ', 'Đầu của tôi trông giống hạt đậu.', '/media/kanji/kanji512/bai19/head.jpg', 1, 52, '2026-06-25 09:22:06.398', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (802, '顔', 'NHAN', 'がん, かお', NULL, 'nhan sắc, hồng nhan', '頭（あたま）から帽子（ぼうし）を取（と）ると、頭（あたま）の傷（きず）が見（み）えます', 'Khi gỡ nón ra khỏi đầu thì thấy các vết xước trên mặt.', '/media/kanji/kanji512/bai19/face.jpg', 2, 52, '2026-06-25 09:22:06.429', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (803, '声', 'THANH', 'せい, しょう', 'こえ, こわ-', 'âm thanh, thanh điệu', 'さむらいが戸（と）のところで「エロ」と声（こえ）を出（だ）している', 'Võ sĩ đạo （士）cất giọng phát ra âm thanh 「コエ」ở bên cửa.', '/media/kanji/kanji512/bai19/voice.jpg', 3, 52, '2026-06-25 09:22:06.444', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (804, '特', 'ĐẶC', 'とく', NULL, 'đặc biệt, đặc công', 'ヒンズー今日（きょう）の寺院（じいん）では、牛（うし）は特別（とくべつ）な動物（どうぶつ）です', 'Bò là một con vật đặc biệt ở đền thờ của đạo Hindu.', '/media/kanji/kanji512/bai19/special.jpg', 4, 52, '2026-06-25 09:22:06.464', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (805, '別', 'BIỆT', 'べつ', 'わか-れる', 'biệt li, đặc biệt, tạm biệt', '包丁（ほうちょう）で肉（にく）を一万（いちまん）切（き）れに分（わ）けました', 'Chia thịt ra thành 10.000 miếng bằng dao.', '/media/kanji/kanji512/bai19/separate.jpg', 5, 52, '2026-06-25 09:22:06.477', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
