INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (807, '合', 'HỢP', 'ごう, が, か', 'あ-う', 'thích hợp, hội họp, hợp lí', '箱（はこ）と二（ふた）は合（あ）っています', 'Cái hộp và nắp của nó vừa vặn với nhau.', '/media/kanji/kanji512/bai19/fit.jpg', 7, 52, '2026-06-25 09:22:06.499', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
