INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (851, '怒', 'NỘ', 'ど', 'いか-る、おこ-る', 'thịnh nộ', '怒（おこ）った女（おんな）の人（ひと）にたたかれました', 'Tôi đã bị người phụ nữ nổi giận đánh.', '/media/kanji/kanji512/bai22/angry.jpg', 3, 55, '2026-06-25 09:22:07.387', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (852, '幸', 'HẠNH', 'こう', 'さいわ-い、しあわ-せ、さち', 'hạnh phúc, hạnh vận', '土（つち）の下（した）に円（えん）（￥）をたくさん持（も）っていて、幸（しあわ）せです', 'Vì tôi có nhiều tiền yên （￥）ở dưới đất nên tôi rất hạnh phúc.', '/media/kanji/kanji512/bai22/happy.jpg', 4, 55, '2026-06-25 09:22:07.389', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (853, '悲', 'BI', 'ひ', 'かな-しい', 'sầu bi, bi quan', '彼（かれ）が刑務所（けいむしょ）に入（はい）っているので、私（わたし）の心（こころ）は悲（かな）しいです', 'Vì anh ấy đang ở trong nhà giam nên trái tim tôi rất đau khổ.', '/media/kanji/kanji512/bai22/sad.jpg', 5, 55, '2026-06-25 09:22:07.399', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (854, '苦', 'KHỔ', 'く', 'くる-しい、にが-い', 'khổ cực, cùng khổ', '古（ふる）い草（くさ）を食（た）べたら、苦（くる）しくなります', 'Nếu ăn cỏ cũ sẽ bị đau.', '/media/kanji/kanji512/bai22/to_suffer.jpg', 6, 55, '2026-06-25 09:22:07.406', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (855, '痛', 'THỐNG', 'つう', 'いた-い', 'thống khổ', '痛（いた）みを感（かん）じながら、病院（びょういん）のさくを越（こ）えます', 'Vừa cảm nhận nỗi đau, vừa vượt qua hàng rào của bệnh viện.', '/media/kanji/kanji512/bai22/pain.jpg', 7, 55, '2026-06-25 09:22:07.423', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (856, '恥', 'SỈ', 'ち', 'はじ、はじ-る', 'sỉ nhục', '自分（じぶん）の心（こころ）の声（こえ）に耳（みみ）を傾（かたむ）けないなんて、恥（は）ずべきことです', 'Thật đáng xấu hổ nếu bạn không lắng nghe nhịp đập con tim mình.', '/media/kanji/kanji512/bai22/shame.jpg', 8, 55, '2026-06-25 09:22:07.44', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (857, '配', 'PHỐI', 'はい', 'くば-る', 'phân phối, chi phối, phối ngẫu', 'ひざまずいてお酒（さけ）を配（くば）っています', 'Quỳ gối đưa rượu.', '/media/kanji/kanji512/bai22/to_deliver.jpg', 9, 55, '2026-06-25 09:22:07.452', '2026-09-02 08:51:28.813', NULL, 'N3', NULL, NULL, NULL);
