INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (882, '部', 'BỘ', 'ぶ', NULL, 'bộ môn, bộ phận', 'バス停（てい）のところに、人（ひと）が立（た）っています', 'Một người đang đứng trong khu vực trạm chờ xe buýt.', '/media/kanji/kanji512/bai24/section.jpg', 2, 57, '2026-06-25 09:22:08.013', '2026-09-02 08:51:28.831', NULL, 'N3', NULL, NULL, NULL);
