INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (897, '平', 'BÌNH', 'へい, びょう', 'たい-ら、ひら', 'hòa bình, bình đẳng, trung bình, bình thường', '今（いま）、シーソーは水平（すいへい）です', 'Bập bênh đang ngang bằng.', '/media/kanji/kanji512/bai25/flat_calm.jpg', 1, 58, '2026-06-25 09:22:08.363', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (898, '和', 'HÒA', 'わ, お', 'やわ-らぐ、なご-む', 'hòa bình, tổng hòa, điều hòa', '和食（わしょく）にはご飯（はん）が付（つ）いてきます', 'Đồ ăn Nhật đi kèm với cơm.', '/media/kanji/kanji512/bai25/peace.jpg', 2, 58, '2026-06-25 09:22:08.398', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (899, '戦', 'CHIẾN', 'せん', 'いくさ、たたか-う］ →戰［單', 'chiến tranh, chiến đấu', '戦争（せんそう）ではいろいろな武器（ぶき）が使（つか）われます', 'Nhiều loại vũ khí được sử dụng trong chiến tranh.', '/media/kanji/kanji512/bai25/war.jpg', 3, 58, '2026-06-25 09:22:08.435', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (900, '争', 'TRANH', 'そう', 'あらそ-う］ 競争(きょうそう)→爭［爭', 'đấu tranh, chiến tranh, tranh luận, cạnh tranh', 'その人（ひと）は武器（ぶき）を手（て）に持（も）ち、争（あらそ）いに備（そな）えています', 'Người đó cầm vũ khí trong tay chuẩn bị đánh nhau.', '/media/kanji/kanji512/bai25/conflict.jpg', 4, 58, '2026-06-25 09:22:08.473', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (901, '政', 'CHÍNH', 'せい, しょう, まつりごと', NULL, 'chính phủ, chính sách, hành chính', '政府（せいふ）は正（ただ）しいことをするべきです', 'Chính phủ nên thực thi những điều đúng đắn（正）.', '/media/kanji/kanji512/bai25/government.jpg', 5, 58, '2026-06-25 09:22:08.492', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (902, '治', 'TRỊ', 'ち, じ', 'おさ-める', 'cai trị, trị an, trị bệnh', '私（わたし）は海岸（かいがん）地帯（ちたい）を納（おさ）めています', 'Tôi quản lý vùng ven biển.', '/media/kanji/kanji512/bai25/to_govern_cure.jpg', 6, 58, '2026-06-25 09:22:08.532', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (903, '経', 'KINH', 'けい, きょう', 'へ-る、た-つ', 'kinh tế, sách kinh, kinh độ', '土（つち）を耕（たがや）したり、糸（いと）を紡（つむ）いだりして、長（なが）い時間（じかん）が経（た）ってしまいました', 'Khi thì cày đất, khi thì kéo sợi, thời gian khá dài đã trôi qua.', '/media/kanji/kanji512/bai25/to_pass_through.jpg', 7, 58, '2026-06-25 09:22:08.55', '2026-09-02 08:51:28.838', NULL, 'N3', NULL, NULL, NULL);
