INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (929, '吉', 'CÁT', 'きち, きつ', NULL, 'tốt lành, cát tường', '侍（さむらい）が「幸運（こううん）を祈（いの）る」と叫（さけ）びます', 'Võ sĩ đạo hét to: ”Chúc may mắn!”', '/media/kanji/kanji512/bai27/goodluck.jpg', 1, 60, '2026-06-25 09:22:09.344', '2026-09-02 08:51:28.853', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (930, '結', 'KẾT', 'けつ', 'むす-ぶ、ゆ-う', 'đoàn kết, kết thúc', '糸（いと）を結（むす）んで、幸運（こううん）のお守（まも）りを作（つく）りました', 'Kết chỉ làm bùa may mắn.', '/media/kanji/kanji512/bai27/to_tie.jpg', 2, 60, '2026-06-25 09:22:09.376', '2026-09-02 08:51:28.853', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (931, '婚', 'HÔN', 'こん', NULL, 'kết hôn, hôn nhân', '女（おんな）の人（ひと）は結婚（けっこん）後（ご）、姓（せい）を変（か）えました', 'Phụ nữ đổi họ sau khi kết hôn.', '/media/kanji/kanji512/bai27/marriage.jpg', 3, 60, '2026-06-25 09:22:09.402', '2026-09-02 08:51:28.853', NULL, 'N3', NULL, NULL, NULL);
