INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (933, '供', 'CUNG', 'きょう, く', 'そな-える、とも', 'cung cấp, cung phụng', '一緒（いっしょ）にあなたを助（たす）けます', 'Cùng nhau giúp đỡ bạn.', '/media/kanji/kanji512/bai27/offer.jpg', 5, 60, '2026-06-25 09:22:09.476', '2026-09-02 08:51:28.853', NULL, 'N3', NULL, NULL, NULL);
