INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (945, '取', 'THỦ', 'しゅ', 'と-る', 'lấy, nhận', '私（わたし）の耳（みみ）を取（と）らないでください', 'Đừng kéo tai tôi!', '/media/kanji/kanji512/bai28/take.jpg', 1, 61, '2026-06-25 09:22:09.819', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (946, '最', 'TỐI', 'さい', NULL, 'nhất (tối cao, tối đa)', '太陽（たいよう）を手（て）に取（と）ることは最（もっと）も難（むずか）しいことです', 'Bắt lấy ánh mặt trời là điều khó khăn nhất.', '/media/kanji/kanji512/bai28/utmost.jpg', 2, 61, '2026-06-25 09:22:09.826', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (947, '初', 'SƠ', 'しょ', 'し,はじ-め, はじ-めて, はつ, はつ-, うい-, -そ-める, -ぞ-め, はっ', 'sơ cấp', '着物（きもの）を作（つく）るときは、はじめに布（ぬの）を刀（かたな）で切（き）ります', 'Khi làm kimono thì trước tiên sẽ cắt vải bằng dao.', '/media/kanji/kanji512/bai28/first.jpg', 3, 61, '2026-06-25 09:22:09.873', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (948, '番', 'PHIÊN', 'ばん', NULL, 'thứ tự, phiên hiệu', '順番（じゅんばん）に田（た）んぼの米（こめ）を収穫（しゅうかく）します', 'Thay phiên nhau gặt lúa trên đồng.', '/media/kanji/kanji512/bai28/turn.jpg', 4, 61, '2026-06-25 09:22:09.909', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (949, '歳', 'TUẾ', 'さい, せい, とし', NULL, 'tuổi, năm, tuế nguyệt', '私（わたし）が何歳（なんさい）か聞（き）くのはやめてください', 'Hãy thôi hỏi tôi bao nhiêu tuổi!', '/media/kanji/kanji512/bai28/age.jpg', 5, 61, '2026-06-25 09:22:09.967', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (950, '枚', 'MAI', 'まい', NULL, 'tờ', '木（き）から紙（かみ）を一枚（いちまい）作（つく）りました', 'Tôi đã làm một mảnh giấy từ cây.', '/media/kanji/kanji512/bai28/sheet_of.jpg', 6, 61, '2026-06-25 09:22:10.014', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (951, '冊', 'SÁCH', 'さつ, さく', NULL, 'quyển sách', '紙（かみ）を束（たば）ねて、一冊（いっさつ）の本（ほん）を作（つく）ります', 'Bó các tờ giấy làm thành một quyển sách.', '/media/kanji/kanji512/bai28/counter%20for%20books.jpg', 7, 61, '2026-06-25 09:22:10.032', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (952, '億', 'ỨC', 'おく', NULL, 'trăm triệu', '一億人（いちおくにん）の人（ひと）はそれぞれ番（つが）う意志（いし）があります', 'Một trăm triệu người có ý chí （意）khác nhau của riêng từng người.', '/media/kanji/kanji512/bai28/hundred_million.jpg', 8, 61, '2026-06-25 09:22:10.063', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (961, '勝', 'THẮNG', 'しょう', 'か-つ、まさ-る', 'thắng lợi, thắng cảnh', '勝（か）ったのは火曜日（かようび）ではなく月曜日（げつようび）です', 'Ngày thắng là thứ hai（月）, không phải thứ ba.', '/media/kanji/kanji512/bai29/won.jpg', 1, 62, '2026-06-25 09:22:10.383', '2026-09-02 08:51:28.869', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (962, '負', 'PHỤ', 'ふ', 'ま-ける, ま-かす, お-う', 'âm, mang, phụ thương, phụ trách', '負（ま）けた人（ひと）がお金（かね）を払（はら）います', 'Người thua sẽ trả tiền.', '/media/kanji/kanji512/bai29/defeat.jpg', 2, 62, '2026-06-25 09:22:10.41', '2026-09-02 08:51:28.869', NULL, 'N3', NULL, NULL, NULL);
