INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (921, '込', NULL, NULL, 'こ-む, こ-める', 'vào trong; đông đúc; bao gồm (chữ do Nhật tạo, không có âm Hán-Việt)', 'たくさんの人（ひと）が入（はい）っていきます。中（なか）はきっと込（こ）んでいるでしょう', 'Nhiều người đang đi vào. Chắc bên trong đông đúc lắm.', '/media/kanji/kanji512/bai26/crowd.jpg', 9, 59, '2026-06-25 09:22:09.033', '2026-09-02 08:51:28.846', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (959, '々', NULL, NULL, NULL, 'dấu lặp lại chữ Hán đứng trước (vd 人々, 時々) — không phải chữ Hán', 'これは繰（く）り返（かえ）しを表（あらわ）します', 'Ký hiệu này biểu thị sự lặp lại.', '/media/kanji/kanji512/bai28/symbol_of_repetition.jpg', 15, 61, '2026-06-25 09:22:10.311', '2026-09-02 08:51:28.861', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (786, '官', 'QUAN', 'かん', NULL, 'quan chức, cơ quan', '太（ふと）った役人（やくにん）が家（いえ）の中（なか）にいます', 'Một quan chức mập đang ở trong nhà.', '/media/kanji/kanji512/bai18/government_offical.jpg', 2, 51, '2026-06-25 09:22:06.008', '2026-09-02 08:51:28.78', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (808, '答', 'ĐÁP', 'とう', 'こた-える', 'trả lời, đáp án', '私（わたし）たちの声（こえ）はこの竹（たけ）の箱（はこ）とふたのように合（あ）いました', 'Câu trả lời của chúng tôi rất khớp giống như cái hộp tre và nắp của nó.', '/media/kanji/kanji512/bai19/answer.jpg', 8, 52, '2026-06-25 09:22:06.516', '2026-09-02 08:51:28.788', NULL, 'N4', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (941, '祖', 'TỔ', 'そ', NULL, 'tổ tiên', '先祖（せんぞ）の墓（はか）へ行（い）ってお供（そな）えをします', 'Đi đến mộ tổ tiên cúng kiến.', '/media/kanji/kanji512/bai27/ancestor.jpg', 13, 60, '2026-06-25 09:22:09.706', '2026-09-02 08:51:28.853', NULL, 'N3', NULL, NULL, NULL);
INSERT INTO public."KanjiEntry" (id, "character", "hanViet", onyomi, kunyomi, "meaningVi", "mnemonicJp", "mnemonicVi", "imageUrl", "sortOrder", "lessonId", "createdAt", "updatedAt", "meaningEn", "jlptLevel", "strokeCount", frequency, grade) VALUES (872, '練', 'LUYỆN', 'れん', 'ね-る', 'rèn luyện, luyện tập', '東洋（とうよう）で、私（わたし）を紡（つむ）ぐ練習（れんしゅう）をしました', 'Tôi đã luyện kéo sợi ở Đông Dương.', '/media/kanji/kanji512/bai23/elaborate.jpg', 8, 56, '2026-06-25 09:22:07.701', '2026-09-02 08:51:28.821', NULL, 'N3', NULL, NULL, NULL);
