INSERT INTO public."MindMapLevel" (id, kind, level, title, summary, accent, branches, "sortOrder", "createdAt", "updatedAt") VALUES (1, 'GRAMMAR', 'N5', 'Nền tảng giao tiếp', 'Câu đơn, trợ từ cơ bản, tính từ, thì hiện tại/quá khứ, nghi vấn.', '#22c55e', '[{"id": "n5-particles", "hint": "は・が・を・に・で・へ・と・も・の", "label": "Trợ từ cơ bản", "labelJa": "助詞", "patterns": [{"meaning": "A là B", "pattern": "N は N です", "lessonNumber": 1}, {"meaning": "có (vật / người, động vật)", "pattern": "N が あります／います", "lessonNumber": 10}, {"meaning": "làm gì bằng / tại nơi", "pattern": "N で V", "lessonNumber": 7}, {"meaning": "đi đến đâu", "pattern": "N に 行きます", "lessonNumber": 5}]}, {"id": "n5-copula", "label": "Câu danh từ & lịch sự", "labelJa": "です／ます", "patterns": [{"meaning": "là / không phải là", "pattern": "〜です／〜ではありません", "lessonNumber": 1}, {"meaning": "thể lịch sự động từ", "pattern": "Vます／Vません／Vました", "lessonNumber": 6}, {"meaning": "xin hãy ~", "pattern": "〜ください", "lessonNumber": 14}]}, {"id": "n5-adj", "label": "Tính từ", "labelJa": "い／な形容詞", "patterns": [{"meaning": "tính từ đuôi い", "pattern": "い-adj + です", "lessonNumber": 8}, {"meaning": "tính từ đuôi な", "pattern": "な-adj + です", "lessonNumber": 8}, {"meaning": "tính từ bổ nghĩa động từ", "pattern": "Adj + く／に + V", "lessonNumber": 8}]}, {"id": "n5-question", "label": "Nghi vấn & nghi từ", "labelJa": "疑問", "patterns": [{"meaning": "câu hỏi có/không", "pattern": "〜か", "lessonNumber": 2}, {"meaning": "nghi từ cơ bản", "pattern": "何／どこ／だれ／いつ", "lessonNumber": 2}, {"meaning": "cái nào", "pattern": "どの＋N／どれ", "lessonNumber": 9}]}, {"id": "n5-time", "label": "Thời gian & số đếm", "labelJa": "時・数", "patterns": [{"meaning": "làm lúc mấy giờ", "pattern": "〜時に V", "lessonNumber": 4}, {"meaning": "từ … đến …", "pattern": "〜から〜まで", "lessonNumber": 4}, {"meaning": "cùng làm nhé", "pattern": "〜ましょう", "lessonNumber": 6}]}, {"id": "n5-want", "label": "Ý muốn & sở thích", "labelJa": "ほしい・たい", "patterns": [{"meaning": "muốn làm ~", "pattern": "Vたいです", "lessonNumber": 13}, {"meaning": "muốn có ~", "pattern": "N が ほしいです", "lessonNumber": 13}, {"meaning": "thích / không thích", "pattern": "N が 好き／きらいです", "lessonNumber": 12}]}]', 0, '2026-09-26 12:22:36.865', '2026-09-26 12:22:36.865');
INSERT INTO public."MindMapLevel" (id, kind, level, title, summary, accent, branches, "sortOrder", "createdAt", "updatedAt") VALUES (2, 'GRAMMAR', 'N4', 'Mở rộng câu & thể động từ', 'Thể て／た, khả năng, điều kiện đơn, cho nhận, ý định.', '#14b8a6', '[{"id": "n4-te", "label": "Thể て", "labelJa": "て形", "patterns": [{"meaning": "nối hành động liên tiếp", "pattern": "Vて、Vて…", "lessonNumber": 14}, {"meaning": "đang / trạng thái", "pattern": "Vています", "lessonNumber": 14}, {"meaning": "xin hãy / được phép", "pattern": "Vてください／Vてもいい", "lessonNumber": 15}, {"meaning": "không được ~", "pattern": "Vてはいけません", "lessonNumber": 15}]}, {"id": "n4-ta", "label": "Thể た & trải nghiệm", "labelJa": "た形", "patterns": [{"meaning": "đã từng ~", "pattern": "Vたことがあります", "lessonNumber": 19}, {"meaning": "nên ~", "pattern": "Vたほうがいい", "lessonNumber": 20}, {"meaning": "làm A, làm B (ví dụ)", "pattern": "Vたり Vたりする", "lessonNumber": 19}]}, {"id": "n4-potential", "label": "Khả năng", "labelJa": "可能形", "patterns": [{"meaning": "có thể làm ~", "pattern": "V可能形", "lessonNumber": 27}, {"meaning": "biết làm / có thể", "pattern": "N が できます", "lessonNumber": 18}]}, {"id": "n4-if", "label": "Điều kiện đơn", "labelJa": "たら・と・ば", "patterns": [{"meaning": "nếu / khi (たら)", "pattern": "Vた／い-adj＋かったら", "lessonNumber": 25}, {"meaning": "hễ ~ thì (tự nhiên)", "pattern": "V辞書形＋と", "lessonNumber": 23}, {"meaning": "nếu (giả định)", "pattern": "Vば／Adj＋ければ", "lessonNumber": 25}]}, {"id": "n4-give", "label": "Cho · nhận", "labelJa": "あげ・くれ・もらい", "patterns": [{"meaning": "làm giúp / được làm giúp", "pattern": "Vてあげる／くれる／もらう", "lessonNumber": 24}, {"meaning": "cho / nhận", "pattern": "N を あげます／もらいます", "lessonNumber": 7}]}, {"id": "n4-intent", "label": "Ý định & suy đoán", "labelJa": "つもり・そう", "patterns": [{"meaning": "dự định ~", "pattern": "V辞書形＋つもりです", "lessonNumber": 18}, {"meaning": "trông có vẻ ~", "pattern": "V／Adj＋そうです", "lessonNumber": 20}, {"meaning": "tôi nghĩ rằng ~", "pattern": "〜と思います", "lessonNumber": 21}]}]', 1, '2026-09-26 12:22:36.872', '2026-09-26 12:22:36.872');
INSERT INTO public."MindMapLevel" (id, kind, level, title, summary, accent, branches, "sortOrder", "createdAt", "updatedAt") VALUES (3, 'GRAMMAR', 'N3', 'Logic câu phức & kính ngữ nhập môn', 'Mục đích, truyền đạt, bị động, sai khiến, liên từ nâng cao.', '#3b82f6', '[{"id": "n3-purpose", "label": "Nguyên nhân · mục đích", "labelJa": "原因・目的", "patterns": [{"meaning": "để (sao cho) ~", "pattern": "Vるように", "lessonNumber": 301}, {"meaning": "cố gắng / trở nên ~", "pattern": "Vようにする／なる", "lessonNumber": 301}, {"meaning": "để / vì (có chủ ý)", "pattern": "N／Vために", "lessonNumber": 301}, {"meaning": "nhờ / vì (xấu)", "pattern": "〜おかげで／せいで", "lessonNumber": 301}]}, {"id": "n3-hearsay", "label": "Truyền đạt · phỏng đoán", "labelJa": "伝聞・推量", "patterns": [{"meaning": "nghe nói ~", "pattern": "〜そうです（伝聞）", "lessonNumber": 302}, {"meaning": "hình như ~", "pattern": "〜ようです／みたいです", "lessonNumber": 302}, {"meaning": "có vẻ / nghe đồn", "pattern": "〜らしい", "lessonNumber": 302}]}, {"id": "n3-voice", "label": "Bị động · sai khiến · kính ngữ", "labelJa": "受身・使役・敬語", "patterns": [{"meaning": "bị động", "pattern": "Vられる（受身）", "lessonNumber": 303}, {"meaning": "sai khiến", "pattern": "Vさせる（使役）", "lessonNumber": 303}, {"meaning": "kính ngữ cơ bản", "pattern": "お／ご〜になる・する", "lessonNumber": 303}]}, {"id": "n3-connect", "label": "Liên từ nâng cao", "labelJa": "接続", "patterns": [{"meaning": "thế mà / dù", "pattern": "〜のに", "lessonNumber": 304}, {"meaning": "không chỉ … mà còn", "pattern": "〜ばかりでなく", "lessonNumber": 304}, {"meaning": "quyết định / được quyết", "pattern": "〜ことにする／なる", "lessonNumber": 304}]}, {"id": "n3-degree", "label": "Giả định · so sánh · mức độ", "labelJa": "仮定・比較", "patterns": [{"meaning": "càng … càng", "pattern": "〜ば〜ほど", "lessonNumber": 305}, {"meaning": "đến mức ~", "pattern": "〜くらい／ほど", "lessonNumber": 305}, {"meaning": "dù cho ~", "pattern": "〜としても", "lessonNumber": 305}]}]', 2, '2026-09-26 12:22:36.877', '2026-09-26 12:22:36.877');
INSERT INTO public."MindMapLevel" (id, kind, level, title, summary, accent, branches, "sortOrder", "createdAt", "updatedAt") VALUES (4, 'GRAMMAR', 'N2', 'Sắc thái & lập luận', 'Thời điểm tinh tế, căn cứ, nhấn mạnh, nhượng bộ, đánh giá.', '#f59e0b', '[{"id": "n2-timing", "label": "Thời điểm · đồng thời", "labelJa": "時点・同時", "patterns": [{"meaning": "đúng lúc đang ~", "pattern": "〜最中に／ところだ", "lessonNumber": 401}, {"meaning": "ngay khi ~ thì", "pattern": "〜次第", "lessonNumber": 401}, {"meaning": "vừa … thì ngay", "pattern": "〜とたん（に）", "lessonNumber": 401}]}, {"id": "n2-basis", "label": "Căn cứ · lập trường", "labelJa": "根拠・立場", "patterns": [{"meaning": "tùy / theo nguồn", "pattern": "〜によって／よると", "lessonNumber": 402}, {"meaning": "dựa trên ~", "pattern": "〜をもとに（して）", "lessonNumber": 402}, {"meaning": "liên quan đến ~", "pattern": "〜に関して／について", "lessonNumber": 402}]}, {"id": "n2-focus", "label": "Nhấn mạnh · hạn định", "labelJa": "強調・限定", "patterns": [{"meaning": "chỉ … thôi (phủ định)", "pattern": "〜しか〜ない", "lessonNumber": 403}, {"meaning": "chỉ toàn là ~", "pattern": "〜ばかりだ／だけだ", "lessonNumber": 403}, {"meaning": "đáng lẽ / lời khuyên", "pattern": "〜ものだ／ことだ", "lessonNumber": 403}]}, {"id": "n2-concession", "label": "Điều kiện · nhượng bộ", "labelJa": "条件・譲歩", "patterns": [{"meaning": "bất chấp ~", "pattern": "〜にもかかわらず", "lessonNumber": 404}, {"meaning": "dù là … đi nữa", "pattern": "〜にしても／にしろ", "lessonNumber": 404}, {"meaning": "nếu không … thì không", "pattern": "〜ないことには", "lessonNumber": 404}]}, {"id": "n2-result", "label": "Hệ quả · cảm thán", "labelJa": "結果・感慨", "patterns": [{"meaning": "cuối cùng (thường xấu)", "pattern": "〜あげく（に）", "lessonNumber": 405}, {"meaning": "đâu có … mà còn", "pattern": "〜どころか", "lessonNumber": 405}, {"meaning": "đương nhiên / chắc phải", "pattern": "〜わけだ／はずだ", "lessonNumber": 405}]}]', 3, '2026-09-26 12:22:36.881', '2026-09-26 12:22:36.881');
INSERT INTO public."MindMapLevel" (id, kind, level, title, summary, accent, branches, "sortOrder", "createdAt", "updatedAt") VALUES (5, 'GRAMMAR', 'N1', 'Văn viết & sắc thái tinh tế', 'Nhấn mạnh văn chương, logic phức, cảm xúc, phạm vi thái độ.', '#ef4444', '[{"id": "n1-written", "label": "Nhấn mạnh văn viết", "labelJa": "書き言葉", "patterns": [{"meaning": "như sắp / gần như", "pattern": "〜んばかりに", "lessonNumber": 501}, {"meaning": "vừa … đã ngay", "pattern": "〜が早いか", "lessonNumber": 501}, {"meaning": "không chủ đích ~", "pattern": "〜ともなく／ともなしに", "lessonNumber": 501}]}, {"id": "n1-logic", "label": "Quan hệ logic · nhượng bộ", "labelJa": "論理・譲歩", "patterns": [{"meaning": "dù A hay B", "pattern": "〜であれ〜であれ", "lessonNumber": 502}, {"meaning": "dù nói là ~", "pattern": "〜といえども", "lessonNumber": 502}, {"meaning": "không có … thì không", "pattern": "〜なくして（は）", "lessonNumber": 502}]}, {"id": "n1-emotion", "label": "Cảm xúc · đánh giá", "labelJa": "感情・評価", "patterns": [{"meaning": "mong mãi không thôi", "pattern": "〜てやまない", "lessonNumber": 503}, {"meaning": "cực kỳ ~", "pattern": "〜極まりない／の極み", "lessonNumber": 503}, {"meaning": "không thể không ~", "pattern": "〜ずにはいられない", "lessonNumber": 503}]}, {"id": "n1-scope", "label": "Giới hạn · thái độ", "labelJa": "範囲・態度", "patterns": [{"meaning": "cho đến tận ~", "pattern": "〜に至るまで", "lessonNumber": 504}, {"meaning": "bằng / lấy mốc ~", "pattern": "〜をもって", "lessonNumber": 504}, {"meaning": "bất chấp / mặc kệ", "pattern": "〜をよそに", "lessonNumber": 504}]}]', 4, '2026-09-26 12:22:36.885', '2026-09-26 12:22:36.885');
INSERT INTO public."MindMapLevel" (id, kind, level, title, summary, accent, branches, "sortOrder", "createdAt", "updatedAt") VALUES (6, 'VOCAB', 'N5', 'Đời sống cơ bản', '~800 từ · chào hỏi, gia đình, ăn uống, thời gian, trường lớp.', '#22c55e', '[{"id": "v-n5-greet", "label": "Chào hỏi · lịch sự", "labelJa": "あいさつ", "patterns": [{"meaning": "xin chào", "pattern": "こんにちは", "lessonNumber": 1}, {"meaning": "cảm ơn", "pattern": "ありがとうございます", "lessonNumber": 1}, {"meaning": "xin lỗi / làm ơn", "pattern": "すみません", "lessonNumber": 2}]}, {"id": "v-n5-family", "label": "Gia đình · người", "labelJa": "家族", "patterns": [{"meaning": "gia đình", "pattern": "家族", "lessonNumber": 4}, {"meaning": "bạn bè", "pattern": "友達", "lessonNumber": 5}, {"meaning": "thầy/cô", "pattern": "先生", "lessonNumber": 1}]}, {"id": "v-n5-food", "label": "Ăn uống", "labelJa": "食べ物", "patterns": [{"meaning": "cơm / bữa ăn", "pattern": "ご飯", "lessonNumber": 7}, {"meaning": "nước", "pattern": "水", "lessonNumber": 7}, {"meaning": "ăn / uống", "pattern": "食べる／飲む", "lessonNumber": 6}]}, {"id": "v-n5-time", "label": "Thời gian", "labelJa": "時間", "patterns": [{"meaning": "hôm nay / mai / hôm qua", "pattern": "今日／明日／昨日", "lessonNumber": 4}, {"meaning": "bây giờ", "pattern": "今", "lessonNumber": 3}, {"meaning": "giờ / phút", "pattern": "時／分", "lessonNumber": 4}]}, {"id": "v-n5-place", "label": "Nơi chốn", "labelJa": "場所", "patterns": [{"meaning": "trường học", "pattern": "学校", "lessonNumber": 5}, {"meaning": "nhà ga", "pattern": "駅", "lessonNumber": 10}, {"meaning": "nhà", "pattern": "家", "lessonNumber": 5}]}, {"id": "v-n5-action", "label": "Động từ hàng ngày", "labelJa": "動詞", "patterns": [{"meaning": "đi / đến / về", "pattern": "行く／来る／帰る", "lessonNumber": 5}, {"meaning": "xem / nghe", "pattern": "見る／聞く", "lessonNumber": 6}, {"meaning": "làm", "pattern": "する", "lessonNumber": 6}]}]', 0, '2026-09-26 12:22:36.889', '2026-09-26 12:22:36.889');
