INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (7, 9, 'grammar', 'multiple_choice', '昨日、雨が＿＿ので、出かけませんでした。', '降った', NULL, NULL, 6, '2026-09-13 05:31:48.832', '2026-09-13 05:31:48.832', NULL);
