INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (21, 10, 'reading', 'multiple_choice', '【文章】田中さんは毎日会社まで自転車で行きます。電車より時間はかかりますが、運動になるので続けています。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (22, 10, 'reading', 'multiple_choice', '【文章】この店のラーメンはとても人気があります。特に週末は、開店前から並んでいる人がたくさんいます。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (23, 10, 'reading', 'multiple_choice', '【文章】山田さんは来月、大阪に引っ越します。新しい仕事のためです。友達はみんな寂しがっています。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (24, 10, 'listening', 'listening', '何に誘っていますか。', '映画を見ること', '今度の日曜日、一緒に映画を見に行きませんか。', NULL, 11, '2026-09-13 05:31:48.913', '2026-09-13 05:31:48.913', NULL);
