INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (35, 11, 'reading', 'multiple_choice', '【文章】最近、スマートフォンで健康を管理するアプリが人気だ。歩いた歩数や睡眠時間が自動的に記録され、グラフで確認できる。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (36, 11, 'reading', 'multiple_choice', '【文章】会社の近くに新しいカフェができた。値段は少し高いが、静かで仕事がしやすいと評判だ。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (37, 11, 'reading', 'multiple_choice', '【文章】田中先生は学生に「間違えることを恐れないでください」といつも言っている。失敗から学ぶことが多いからだ。
