INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (40, 11, 'listening', 'listening', '何をするように言っていますか。', '迂回すること', '駅前の道路は工事中なので、迂回してください。', NULL, 13, '2026-09-13 05:31:48.954', '2026-09-13 05:31:48.954', NULL);
