INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (49, 12, 'reading', 'multiple_choice', '【文章】在宅勤務が広がったことで、通勤時間が減り、自分の時間を持てるようになったという声が多い。一方で、同僚とのコミュニケーション不足を感じる人もいる。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (50, 12, 'reading', 'multiple_choice', '【文章】高齢化が進む日本では、介護の担い手不足が深刻な問題となっている。外国人労働者の受け入れを拡大する動きも出てきている。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (51, 12, 'reading', 'multiple_choice', '【文章】食品の値上げが続く中、消費者は少しでも安い店を求めてスーパーをはしごするようになっている。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (52, 12, 'listening', 'listening', '何を伝えていますか。', '後で連絡し直すこと', '恐れ入りますが、担当者が席を外しておりますので、後ほど折り返しご連絡させていただきます。', NULL, 11, '2026-09-13 05:31:48.999', '2026-09-13 05:31:48.999', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (53, 12, 'listening', 'listening', '報告はいつ行われますか。', '来週の会議で', 'このデータについては、来週の会議で改めて詳しくご報告いたします。', NULL, 12, '2026-09-13 05:31:48.999', '2026-09-13 05:31:48.999', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (54, 12, 'listening', 'listening', '何を伝えていますか。', '席が空いていないこと', '申し訳ございませんが、只今満席となっております。', NULL, 13, '2026-09-13 05:31:48.999', '2026-09-13 05:31:48.999', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (55, 13, 'vocab', 'multiple_choice', '「顕著」の読み方はどれですか。', 'けんちょ', NULL, NULL, 0, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (56, 13, 'vocab', 'multiple_choice', '「妥当」の読み方はどれですか。', 'だとう', NULL, NULL, 1, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (57, 13, 'vocab', 'multiple_choice', '「著しい」の意味は何ですか。', 'rõ rệt, đáng kể', NULL, NULL, 2, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (58, 13, 'vocab', 'multiple_choice', '「潔く」の意味は何ですか。', 'dứt khoát, không do dự', NULL, NULL, 3, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (59, 13, 'grammar', 'multiple_choice', '彼の実力から＿＿、この結果は当然だと言える。', 'すれば', NULL, NULL, 4, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (60, 13, 'grammar', 'multiple_choice', '締め切りが迫っている＿＿、彼は落ち着いて作業を進めている。', 'にもかかわらず', NULL, NULL, 5, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (61, 13, 'grammar', 'multiple_choice', '一度失敗した＿＿諦める必要はない。', 'からといって', NULL, NULL, 6, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (62, 13, 'grammar', 'multiple_choice', '彼女は疲れている＿＿、笑顔を絶やさなかった。', 'ながらも', NULL, NULL, 7, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (63, 13, 'reading', 'multiple_choice', '【文章】効率化が進む現代社会において、あえて手間をかけることの価値が見直されつつある。時間をかけて作られたものには、機械的な生産にはない魅力があるからだ。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (64, 13, 'reading', 'multiple_choice', '【文章】言葉は時代とともに変化するものであり、変化そのものを一概に否定するのは適切ではないという意見がある。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (65, 13, 'reading', 'multiple_choice', '【文章】AIの発展により、創造性は人間だけのものではなくなりつつあるという見方がある一方、問いを立てる力は依然として人間に残されているという指摘もある。
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (66, 13, 'listening', 'listening', '何を伝えていますか。', '感謝の気持ち', 'この度は、格別のご配慮を賜り、誠にありがとうございました。', NULL, 11, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (67, 13, 'listening', 'listening', '何を伝えていますか。', '開催を中止すること', '諸般の事情により、開催を見合わせることといたしました。', NULL, 12, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
INSERT INTO public."MockExamQuestion" (id, "templateId", "sectionId", type, question, "correctAnswer", "audioText", "audioUrl", "sortOrder", "createdAt", "updatedAt", "imageUrl") VALUES (68, 13, 'listening', 'listening', '何をお願いしていますか。', 'もう少し待つこと', '恐縮ですが、今しばらくお待ちいただけますでしょうか。', NULL, 13, '2026-09-13 05:31:49.041', '2026-09-13 05:31:49.041', NULL);
