INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (30, 'vowels', 'Năm nguyên âm あ・い・う・え・お', 'Nền tảng của mọi âm tiếng Nhật.', 0, '2026-08-09 09:00:18.492', '2026-08-09 09:00:18.492');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (31, 'mora', 'Mora — nhịp phát âm', 'Tiếng Nhật đếm theo mora, không phải âm tiết.', 1, '2026-08-09 09:00:18.514', '2026-08-09 09:00:18.514');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (32, 'yoon', 'Âm ghép きゃ・しゅ・ちょ…', 'Ghép âm i-row + や・ゆ・よ nhỏ.', 2, '2026-08-09 09:00:18.526', '2026-08-09 09:00:18.526');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (33, 'sokuon', 'Âm đôi っ (sokuon)', 'Dấu nhỏ — tạo khoảng dừng / phụ âm kép.', 3, '2026-08-09 09:00:18.541', '2026-08-09 09:00:18.541');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (34, 'long-vowel', 'Trường âm (chōon / 長音)', 'Kéo dài nguyên âm gấp đôi — đổi nghĩa nếu đọc sai. Hiragana có quy luật viết theo hàng; katakana dùng dấu ー.', 4, '2026-08-09 09:00:18.554', '2026-08-09 09:00:18.554');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (35, 'dakuten', 'Âm đục が・ざ & yếu ぱ', 'Dấu ゛ (dakuten) và ゜ (handakuten).', 5, '2026-08-09 09:00:18.568', '2026-08-09 09:00:18.568');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (36, 'special', 'Âm đặc biệt: ら・ふ・つ・ん', 'Hay sai với người Việt.', 6, '2026-08-09 09:00:18.584', '2026-08-09 09:00:18.584');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (37, 'n-assimilation', 'Âm ん — biến thể phát âm', 'ん không phát âm một kiểu cố định: khẩu hình và vị trí lưỡi đổi theo âm ngay sau nó.', 7, '2026-08-09 09:00:18.598', '2026-08-09 09:00:18.598');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (38, 'pitch', 'Pitch accent (âm cao–thấp)', 'Cùng kana nhưng cao độ khác → nghĩa khác (ít gặp N5).', 8, '2026-08-09 09:00:18.615', '2026-08-09 09:00:18.615');
INSERT INTO public."PronunciationRuleSection" (id, slug, title, summary, "sortOrder", "createdAt", "updatedAt") VALUES (39, 'practice', 'Luyện trên app', 'Cách dùng tab Phát âm hiệu quả.', 9, '2026-08-09 09:00:18.624', '2026-08-09 09:00:18.624');
