INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (103, 34, 'おにいさん', 'oniisan', 'anh trai', 'い段 + い', 1);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (104, 34, 'ゆうき', 'yuuki', 'dũng khí', 'う段 + う', 2);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (105, 34, 'せんせい', 'sensei', 'thầy/cô', 'え段 + い', 3);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (106, 34, 'おねえさん', 'oneesan', 'chị gái', 'え段 + え (ngoại lệ)', 4);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (107, 34, 'ありがとう', 'arigatou', 'cảm ơn', 'お段 + う', 5);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (108, 34, 'おおきい', 'ookii', 'to, lớn', 'お段 + お (ngoại lệ)', 6);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (109, 34, 'コーヒー', 'koohii', 'cà phê', 'katakana ー', 7);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (110, 34, 'おばさん', 'obasan', 'cô, dì (ngắn)', NULL, 8);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (111, 34, 'おばあさん', 'obaasan', 'bà (dài)', NULL, 9);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (112, 35, 'かぎ', 'kagi', 'chìa khóa', NULL, 0);
