INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (114, 35, 'じかん', 'jikan', 'thời gian', NULL, 2);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (115, 36, 'ふろ', 'furo', 'bồn tắm', NULL, 0);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (116, 36, 'つき', 'tsuki', 'mặt trăng', NULL, 1);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (117, 36, 'せんせい', 'sensei', 'thầy/cô', NULL, 2);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (118, 37, 'あんぱん', 'am-pan', 'bánh nhân đậu đỏ', '[m] trước P', 0);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (119, 37, '日本橋', 'ni-hom-ba-shi', 'Nihonbashi', '[m] trước B', 1);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (120, 37, 'さんま', 'sam-ma', 'cá thu đao', '[m] trước M', 2);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (121, 37, '乾杯', 'kam-pai', 'cạn ly', '[m] trước P (không phải [n])', 3);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (122, 37, '反対', 'han-tai', 'phản đối', '[n] trước T', 4);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (123, 37, '案内', 'an-nai', 'hướng dẫn', '[n] trước N', 5);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (124, 37, '連絡', 'ren-ra-ku', 'liên lạc', '[n] trước R', 6);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (125, 37, '天気', 'teng-ki', 'thời tiết', '[ŋ] trước K', 7);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (126, 37, '漫画', 'mang-ga', 'truyện tranh', '[ŋ] trước G', 8);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (127, 37, '銀行', 'ging-kou', 'ngân hàng', '[ŋ] trước K', 9);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (128, 37, '本', 'hon', 'sách', '[ɴ] cuối từ', 10);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (129, 37, '恋愛', 'ren-ai', 'tình yêu', '[ɴ] trước nguyên âm あ', 11);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (130, 38, 'はし', 'hashi', 'đũa / cầu', 'Pitch khác nhau', 0);
INSERT INTO public."PronunciationRuleExample" (id, "sectionId", japanese, romaji, meaning, note, "sortOrder") VALUES (131, 38, 'いま', 'ima', 'bây giờ / phòng', NULL, 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (80, 30, NULL, 'あ い う え お', 'a i u e o', 'Năm nguyên âm thuần. Mỗi âm một mora, độ dài ổn định. う môi tròn nhẹ, không phải "u" mím chặt.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (81, 30, 'Bảng kana', NULL, NULL, 'Hiragana dùng cho từ gốc Nhật; katakana cho từ mượn. Cùng âm, khác cách viết.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (82, 31, NULL, NULL, NULL, 'Mỗi kana (trừ っ, ん đặc biệt) thường = 1 mora. きょう (kyo) = 3 mora: き + ょ + う.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (83, 31, NULL, NULL, NULL, 'Nói đều nhịp, không nhấn mạnh từng âm tiết như tiếng Việt. Thời lượng mỗi mora gần bằng nhau.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (84, 32, NULL, 'きゃ きゅ きょ', 'kya kyu kyo', 'Ghép trong một mora — không đọc "ki-ya" tách đôi.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (85, 32, NULL, 'しゃ しゅ しょ', 'sha shu sho', 'Âm sh — môi tròn, lưỡi nâng. Không đọc "si-ya".', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (86, 32, NULL, 'ちゃ ちゅ ちょ', 'cha chu cho', 'Gần "chi" + y nhỏ; khác với しゃ (sh).', 2);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (87, 33, NULL, 'っ', NULL, 'Không phát âm riêng — tạm dừng rồi phát âm phụ âm kế tiếp mạnh hơn (kk, pp, tt…).', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (88, 33, NULL, NULL, NULL, 'Ví dụ がっこう: dừng nhẹ trước こ, như "gak-kou" chứ không "gatsukou".', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (89, 34, NULL, NULL, NULL, 'Trường âm = 1 mora kéo dài thêm 1 mora. おばさん (cô) vs おばあさん (bà); ゆき (tuyết) vs ゆうき (dũng khí).', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (90, 34, 'Hiragana — hàng あ', 'あ段 + あ', 'aa', 'Thêm あ sau mora hàng あ. VD: おかあさん, おばあさん.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (91, 34, 'Hiragana — hàng い', 'い段 + い', 'ii', 'Thêm い sau mora hàng い. VD: おにいさん, おじいさん.', 2);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (92, 34, 'Hiragana — hàng う', 'う段 + う', 'uu', 'Thêm う sau mora hàng う. VD: ゆうき, ゆうめい, ぎゅうにゅう.', 3);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (93, 34, 'Hiragana — hàng え', 'え段 + い (mặc định)', 'ei ≈ ē', 'Phần lớn viết え段 + い và đọc kéo dài ē: せんせい, とけい, えいが. Ngoại lệ nhỏ viết + え: おねえさん, ええ (vâng).', 4);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (94, 34, 'Hiragana — hàng お', 'お段 + う (mặc định)', 'ou ≈ ō', 'Phần lớn viết お段 + う và đọc kéo dài ō: ありがとう, おとうさん, こうこう. Ngoại lệ viết + お: おおきい, おおい, とおい, こおり, とおる…', 5);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (95, 34, 'Katakana', 'ー', 'chōonpu', 'Katakana (và hầu hết gairaigo) dùng dấu ー sau nguyên âm/âm ghép: コーヒー, ビール, タクシー. Không dùng ー trong hiragana thường.', 6);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (96, 34, NULL, NULL, NULL, 'Âm ghép cũng kéo dài: きょう (kyō), しょうがっこう (shōgakkō). Đừng tách thành き + よう.', 7);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (97, 35, NULL, 'か → が', NULL, 'Thêm rung thanh hầu — ga, không phải ka.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (98, 35, NULL, 'は → ば / ぱ', NULL, 'ば đục; ぱ yếu (p gần b). は đọc "wa" khi là trợ từ.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (99, 35, NULL, 'ざ じ ず ぜ ぞ', NULL, 'じ ≈ "ji", ず ≈ "zu" — không giống "di", "du" tiếng Việt.', 2);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (100, 36, NULL, 'らりるれろ', 'ra ri ru re ro', 'Một âm r lẫn l — lưỡi chạm vòm, không lắc.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (101, 36, NULL, 'ふ', 'fu', 'Thổi nhẹ qua môi, gần "hu".', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (102, 36, NULL, 'つ', 'tsu', 'Âm xát nhẹ, một mora duy nhất.', 2);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (103, 36, NULL, 'ん', 'n', 'Âm mũi — khẩu hình đổi theo âm sau (xem mục «Âm ん — biến thể phát âm»). Cuối từ không thêm nguyên âm.', 3);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (104, 37, '[m] — mím môi', 'ん → [m]', NULL, 'Khi ん đứng trước hàng M / P / B (ま・ぱ・ば…). Vì các âm này cần mím môi, ん tự chuyển thành /m/.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (105, 37, '[n] — đầu lưỡi chạm vòm lợi', 'ん → [n]', NULL, 'Khi ん đứng trước hàng T / D / N / R / Z (た・だ・な・ら・ざ…). Lưỡi chạm vòm lợi trên như âm n tiếng Việt.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (106, 37, '[ŋ] — như «ng» tiếng Việt', 'ん → [ŋ]', NULL, 'Khi ん đứng trước hàng K / G (か・き・く… / が・ぎ…). Phát âm gần «ng» trong «ngân», «mang».', 2);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (107, 37, '[ɴ] — mũi / thoát hơi', 'ん → [ɴ]', NULL, 'Khi ん ở cuối từ, hoặc đứng trước nguyên âm (あいうえお), hàng Y/W (や・ゆ・よ・わ), và hàng gió S/H (さ・は…). Mở khẩu hình, hơi thoát qua mũi — không chạm hẳn lưỡi lên vòm miệng.', 3);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (108, 37, 'Mẹo nhớ', NULL, NULL, 'Chuẩn bị khẩu hình cho âm tiếp theo: trước P/B/M → M; trước K/G → NG; trước T/D/N → N. Không cần thuộc ký hiệu IPA.', 4);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (109, 38, NULL, NULL, NULL, 'Tiếng Nhật dùng cao độ mora, không nhấn trọng âm như tiếng Anh. Mỗi từ có kiểu lên–xuống riêng.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (110, 38, NULL, NULL, NULL, 'N5: nghe mẫu và bắt chước. は trợ từ thường thấp; một số từ danh từ cao ở mora đầu.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (111, 39, NULL, NULL, NULL, 'Tab Kana: luyện từng âm hiragana/katakana. Bật "Phát âm mẫu khi chuyển thẻ" để nghe ngay.', 0);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (112, 39, NULL, NULL, NULL, 'Tab Từ vựng Minna: luyện theo bài. Ghi âm → nghe lại → so với mẫu.', 1);
INSERT INTO public."PronunciationRulePoint" (id, "sectionId", label, japanese, romaji, explanation, "sortOrder") VALUES (113, 39, NULL, NULL, NULL, 'Lật thẻ xem gợi ý romaji/nghĩa. Lặp lại âm khó (ら, つ, っ, ん biến thể, trường âm) mỗi ngày.', 2);
INSERT INTO public."PronunciationRuleTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (19, 'Giữ miệng mở vừa phải; âm あ gần âm "a" ngắn, không kéo dài như "a" trong "ba".', 0, '2026-08-09 09:00:18.475', '2026-08-09 09:00:18.475');
INSERT INTO public."PronunciationRuleTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (20, 'Âm ら hàng r không lắc lưỡi — lưỡi chạm vòm miệng nhẹ rồi buông.', 1, '2026-08-09 09:00:18.475', '2026-08-09 09:00:18.475');
INSERT INTO public."PronunciationRuleTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (21, 'Âm ふ/フ gần "hu" thổi nhẹ, không phải "ph" hay "f" cứng như tiếng Anh.', 2, '2026-08-09 09:00:18.475', '2026-08-09 09:00:18.475');
INSERT INTO public."PronunciationRuleTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (22, 'Âm つ nhỏ, sát răng — không phát âm như "ts" tách rời hai âm.', 3, '2026-08-09 09:00:18.475', '2026-08-09 09:00:18.475');
INSERT INTO public."PronunciationRuleTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (23, 'Âm ん thay đổi khẩu hình theo âm sau: trước M/P/B → [m]; T/D/N/R/Z → [n]; K/G → [ŋ]; cuối từ / trước nguyên âm → mũi [ɴ].', 4, '2026-08-09 09:00:18.475', '2026-08-09 09:00:18.475');
INSERT INTO public."PronunciationRuleTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (24, 'Kéo dài nguyên âm (おばあさん) khác hẳn nguyên âm ngắn (おばさん). Hiragana: あ→あ, い→い, う→う, え→い, お→う (có ngoại lệ ええ / おお).', 5, '2026-08-09 09:00:18.475', '2026-08-09 09:00:18.475');
INSERT INTO public."PronunciationRulesMeta" (id, intro, "createdAt", "updatedAt") VALUES (1, 'Tiếng Nhật có khoảng 46 âm cơ bản (mora). Mỗi chữ hiragana/katakana thường tương ứng một mora — phát âm đều, không nhấn âm tiết như tiếng Việt.', '2026-06-28 09:04:53.515', '2026-08-09 09:00:18.453');
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (1, 'たなかさんのメール', 'やまださんへ
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (2, '天気予報', 'きょうの天気予報です。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (3, 'レストランで', 'すみません。メニューをください。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (4, '学校のお知らせ', 'みなさんへ
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (5, '服を買う', '店員：いらっしゃいませ。何をお探しですか。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (6, 'わたしの家族', 'はじめまして。わたしはサトウです。家族を紹介します。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (7, '京都への旅行', '来月、友達と京都へ旅行に行く予定です。新幹線で行きます。ホテルは駅の近くに予約しました。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (8, 'アルバイトの面接', 'コンビニでアルバイトの面接を受けました。店長に自己紹介をして、週に何日働けるか聞かれました。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (9, '健康のために', '最近、パソコンの前に長時間座っている人が増えています。健康のために、一時間に一度は立ってストレッチをしましょう。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (10, '引っ越しの準備', '来月末、東京から大阪へ引っ越すことになりました。新しいアパートは会社から徒歩十五分の場所です。部屋は二部屋あって、日当たりもいいです。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (11, '文化祭のお知らせ', '十一月三日と四日に、学校で文化祭を行います。入場は無料ですが、各クラスの出店では食べ物や飲み物を販売します。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (12, '会議の変更について', '各位
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (54, '祖母の手紙', '先週、祖母から手紙が届いた。祖母は携帯電話を使わないので、いつも手紙で近況を知らせてくれる。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (55, '天気予報の見方', '天気予報は、テレビやスマートフォンのアプリで簡単に見ることができる。多くの人が「明日は傘が必要か」を確認するために天気予報を見ているだろう。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (56, 'テレワークのメリットとデメリット', '新型コロナウイルスの流行をきっかけに、テレワークを導入する会社が増えた。テレワークとは、会社に行かずに自宅などで仕事をする働き方のことである。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (57, 'SNSとの付き合い方', 'SNSが普及したことで、遠くに住む友人とも簡単に連絡を取り合えるようになった。写真や近況をすぐに共有できるのは、SNSの大きな魅力だろう。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (58, '日本のコンビニと食品ロス', '日本では、まだ食べられるのに捨てられてしまう食品、いわゆる「食品ロス」が大きな問題になっている。その中でも、コンビニで廃棄される弁当やおにぎりの量は少なくない。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (59, '転職を考えた理由', '私は今の会社に5年間勤めているが、最近、転職を考えるようになった。仕事の内容自体には不満はない。むしろ、任される仕事も増え、やりがいを感じることも多い。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (60, 'キャッシュレス決済の広がり', '近年、現金を使わずに支払いができる「キャッシュレス決済」が急速に広まっている。スマートフォンのアプリやカードを使えば、財布を出さなくても買い物ができる。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (61, '「察する文化」について', '日本語には、「言わなくても分かってほしい」という気持ちを表す場面が多いと言われる。これは、相手の気持ちを言葉にしなくても読み取る、いわゆる「察する文化」と関係があるようだ。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (62, '地域猫活動とは', '最近、「地域猫」という言葉を耳にすることが増えた。地域猫とは、特定の飼い主を持たないが、地域の住民が協力して世話をしている猫のことである。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (63, '「便利さ」の代償', '私たちの生活は、この数十年で驚くほど便利になった。スマートフォン一つで、買い物も、支払いも、情報収集もできる。かつては何日もかかっていたことが、今では数分で済んでしまう。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (64, '言葉の変化をどう見るか', '「最近の若者の言葉遣いは乱れている」という声を耳にすることがある。しかし、言葉というものは、時代とともに変化し続けるものであり、ある時代の「正しい」言葉が、別の時代には「乱れた」言葉に見えるというのは、いつの時代にも繰り返されてきたことである。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (65, '「待つ」ことの意味', '現代社会では、あらゆることが「速さ」を基準に評価されがちだ。検索すれば一瞬で答えが出て、注文すれば翌日には荷物が届く。そんな時代に生きていると、「待つ」という行為は、単なる時間の無駄であるかのように感じられてしまう。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (66, '少子高齢化と地方の未来', '日本の多くの地方都市では、若い世代が仕事を求めて都市部へ流出し、高齢化と人口減少が同時に進んでいる。このままでは、地域の医療や交通など、生活を支える基盤そのものが維持できなくなる地域も出てくるだろうと言われている。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (67, 'AIと創造性', '人工知能(AI)が絵を描いたり、文章を書いたりする時代になった。こうした技術の進歩を目の当たりにすると、「創造性は人間だけのものではなくなるのではないか」という声が聞かれるようになった。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (68, '「無駄」の効用', '効率化が叫ばれる時代において、「無駄」という言葉はしばしば否定的な意味で使われる。会議の無駄、時間の無駄、お金の無駄。できることなら、すべての無駄を排除したいと考える人は少なくないだろう。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (69, '「わかりやすさ」の功罪', 'テレビや本、インターネットの記事など、あらゆる情報が「わかりやすさ」を求められる時代になった。複雑な問題も、短い時間で、簡単な言葉で説明されることが好まれる。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (40, '図書館からのお知らせ', '市立図書館をご利用のみなさまへ
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (41, '習慣を変えるということ', '新しい年になると、「今年こそ運動を続けよう」「毎日日記を書こう」と決める人が多い。しかし、そのほとんどが1か月もたたないうちにやめてしまうそうだ。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (42, '同僚へのメール', '件名：明日の会議の資料について
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (43, '「ながら作業」の落とし穴', '音楽を聴きながら勉強する、テレビを見ながら食事をする。こうした「ながら作業」は、時間を有効に使っているように見える。しかし、近年の研究は、それが必ずしも効率的ではないことを示している。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (44, '社内アンケートのお願い', '社員のみなさまへ
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (45, '道具と人間', '便利な道具が増えるたびに、私たちは何かを得ると同時に、何かを失っているのかもしれない。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (53, 'アルバイト募集', 'アルバイト募集のお知らせ
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (46, '「わかりやすさ」をめぐって', '近年、あらゆる場面で「わかりやすさ」が求められる。行政の文書も、ニュース解説も、学術書ですら、平易であることが美徳とされ、難解なものは敬遠される傾向にある。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (47, '助成金審査結果の通知', '令和6年度 地域文化振興助成金 審査結果について
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (48, '沈黙という応答', '会話において、沈黙はしばしば気まずいものとして扱われる。間が空くと、私たちは反射的に何かを言おうとし、その場を埋めようとする。しかし、沈黙は本当に「何もない」状態なのだろうか。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (49, '駅前の工事について', '市役所からのお知らせ
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (50, '引っ越しをして分かったこと', '先月、一人暮らしを始めるために引っ越しをした。実家にいたときは、料理も洗濯も掃除も、全部母がやってくれていた。だから、自分で全部やらなければならなくなって、はじめは本当に大変だった。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (51, 'コンビニの新しいサービス', '最近、多くのコンビニで新しいサービスが始まっている。それは、店で買った食品をその場で温めて、店内の席で食べられるというサービスだ。
INSERT INTO public."ReadingPassage" (id, title, content, "jlptLevel", source, "estimatedMin", "sortOrder", "createdAt", "updatedAt") VALUES (52, 'スマートフォンと読書', '私は電車の中で本を読むのが好きだ。しかし、最近は本を読んでいる人より、スマートフォンを見ている人のほうがずっと多い。
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (1, 1, 'たなかさんは何をしようとしていますか。', '土曜日に映画を見る', '「いっしょにえいがを見ませんか」と誘っています。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (2, 1, '映画は何時からですか。', '午後2時', '本文に「午後二時からです」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (3, 1, 'ごはんは誰が払いますか。', 'たなかさん', '「わたしのおごりです」＝たなかさんが払います。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (4, 2, '午前中の天気はどうですか。', '晴れ', '「午前中は晴れです」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (5, 2, '夜はどうなりますか。', '雨が降る', '「夜は雨がふるでしょう」と予報されています。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (6, 2, '何を持っていくべきですか。', '傘', '「傘を持っていってください」と書いてあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (7, 3, '何を注文しましたか。', 'ラーメンと餃子', '「ラーメンを一つと、餃子を二つ」と注文しています。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (8, 3, '飲み物は何ですか。', 'お茶', '「飲み物はお茶でいいです」と言っています。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (9, 3, 'お会計はいくらですか。', '1200円', '最後に「お会計は千二百円です」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (10, 4, '月曜日は何の授業がありますか。', '体育', '「月曜日は体育の授業があります」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (11, 4, '月曜日に何を持ってきますか。', '運動靴と水筒', '「運動靴と水筒を持ってきてください」と書いてあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (12, 4, '水曜日はどうなりますか。', '図書館が休み', '「水曜日は図書館が休みです」とお知らせされています。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (13, 5, 'きむらさんは何を探していますか。', '青いシャツ', '「青いシャツを探しています」と言っています。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (14, 5, 'セールの値段はいくらですか。', '2800円', '「セールで二千八百円です」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (15, 5, 'どうやって払いますか。', 'クレジットカード', '「クレジットカードで払えますか」と聞いています。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (16, 6, '父は何をしていますか。', '会社員', '「父は会社員です」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (17, 6, '母はどこで働いていますか。', '病院', '母は看護師で「病院で働いています」。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (18, 6, 'サトウさんは何が好きですか。', 'サッカー', '「サッカーが好きです」と書いてあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (19, 7, 'どうやって京都へ行きますか。', '新幹線', '「新幹線で行きます」と書いてあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (20, 7, '二日目に行きたい場所はどこですか。', '嵐山と天龍寺', '二日目は「嵐山で竹林を歩いて、天龍寺にも行きたい」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (21, 7, '特に食べたいものは何ですか。', '湯豆腐と抹茶スイーツ', '「湯豆腐と抹茶のスイーツを食べたい」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (22, 7, '一人の予算はいくらぐらいですか。', '3万円', '「一人三万円ぐらいです」と書いてあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (23, 8, 'どこで面接を受けましたか。', 'コンビニ', '最初の文に「コンビニでアルバイトの面接」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (24, 8, '働ける日はいつですか。', '火・木の午後と土曜終日', '火曜・木曜の午後と土曜の終日と答えています。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (25, 8, '時給はいくらですか。', '1100円', '「時給は千一百円」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (26, 8, 'いつから働き始めますか。', '来週の月曜日', '最後に「来週の月曜日から働き始める」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (27, 9, 'パソコンの前で長時間座る人に何を勧めていますか。', '一時間に一度立ってストレッチ', '「一時間に一度は立ってストレッチをしましょう」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (28, 9, '食事について何と言っていますか。', '野菜と果物を毎日食べる', '「野菜と果物を毎日食べて」と勧めています。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (29, 9, '大人は何時間寝るのが理想的ですか。', '7〜8時間', '「七時間から八時間寝ることが理想的」と書いてあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (30, 9, 'よく眠るために何をしない方がいいですか。', '寝る前にスマホを見る', '「寝る前にスマホを見ないようにすると、よく眠れる」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (31, 10, 'どこからどこへ引っ越しますか。', '東京から大阪へ', '「東京から大阪へ引っ越す」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (32, 10, '新しいアパートは会社からどのくらいですか。', '徒歩15分', '「会社から徒歩十五分の場所」と書いてあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (33, 10, '引っ越しの日はいつですか。', '3月10日', '「引っ越しの日は三月十日です」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (34, 10, '何をしなければなりませんか。', '銀行と市役所に届け出', '「銀行と市役所に届け出をしなければなりません」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (35, 11, '文化祭はいつですか。', '11月3日と4日', '「十一月三日と四日に」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (36, 11, '二年生は何を販売しますか。', 'たこ焼きとフルーツジュース', '二年生は「たこ焼きとフルーツジュースを用意しています」。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (37, 11, '迷ったら誰に聞けばいいですか。', '赤いリボンのスタッフ', '「赤いリボンをつけたスタッフに聞いてください」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (38, 11, '雨天の場合はどうなりますか。', '屋外イベントが中止になることがある', '「一部の屋外イベントが中止になることがあります」と書いてあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (39, 12, '会議が変更された理由は何ですか。', '資料の準備が間に合わない', '「資料の準備が間に合わないため」と理由が書いてあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (40, 12, '新しい会議の日はいつですか。', '再来週の火曜日', '「再来週の火曜日に変更」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (41, 12, '会議室はどこですか。', '三階のB室', 'A室ではなくB室を使用すると書いてあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (147, 40, '図書館が休みになるのはなぜですか。', 'システムを新しくするため', '「システムが新しくなります。それにともない、下記の期間は休館いたします」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (148, 40, '休館中にできることは何ですか。', '本を返却ポストに返すこと', '「休館中も本の返却はできます。入口の横にある返却ポストをご利用ください」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (149, 40, 'CDやDVDはどうすればいいですか。', '休館が終わってからカウンターに持っていく', '「ポストには入れないでください。休館明けに直接カウンターへお持ちください」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (150, 40, '新しいシステムになると、何ができるようになりますか。', '家からいつでも本を予約できる', '「インターネットから本の予約ができるようになります。…24時間いつでも予約が可能です」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (151, 41, '新しい年の目標が続かない人はどのくらいいますか。', 'ほとんどの人', '「そのほとんどが1か月もたたないうちにやめてしまう」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (152, 41, '専門家は、目標が続かない理由は何だと言っていますか。', '目標が高すぎるから', '「多くの人は最初から高すぎる目標を立ててしまうからだ」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (153, 41, '筆者は、続けるためにどうすればいいと言っていますか。', '目標を小さくする', '「続けるコツは、目標を小さくすることだ」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (154, 41, 'この文章で筆者が一番言いたいことは何ですか。', '完璧でなくてもいいから、やめないことが大切だ', '最後に「大切なのは『完璧にやること』ではなく『やめないこと』なのである」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (155, 42, '田中さんは資料の何を直しますか。', '古くなっているデータ', '「去年のデータが古いままになっていました。私のほうで新しい数字に直しておきます」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (156, 42, '田中さんは木村さんに何をお願いしていますか。', '「今後の計画」のページを今日中に送ること', '「『今後の計画』のページだけ、今日中にメールで送っていただけないでしょうか」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (157, 42, '明日の会議について、正しいものはどれですか。', '会議室が502号室に変わった', '「会議室がいつもの301号室から502号室に変わりました」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (158, 43, '「ながら作業」について、最近の研究は何を示していますか。', '必ずしも効率的ではない', '「近年の研究は、それが必ずしも効率的ではないことを示している」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (159, 43, '「ながら作業」で時間とエネルギーが失われるのはなぜですか。', '脳が二つの作業を行き来するから', '「脳は二つの作業を高速で行き来しているだけ…この切り替えのたびに、わずかだが時間とエネルギーが失われる」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (160, 43, '筆者によると、問題が少ない「ながら作業」はどれですか。', '歩きながら考えごとをすること', '「体が慣れた単純な作業、たとえば歩くこと…なら、頭を使う作業と組み合わせても問題は少ない」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (161, 43, 'この文章で筆者が最も言いたいことは何ですか。', '大事な仕事は一つのことに集中して行うほうがよい', '最後に「一つのことだけに集中する時間を作ったほうがいい。…それが結局は一番の近道なのだ」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (162, 44, 'このアンケートの目的は何ですか。', '働き方の制度を見直すため', '「結果は今後の制度の見直しに役立てます」、目的は「働きやすい職場をつくるため」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (163, 44, 'アンケートについて、正しいものはどれですか。', '名前を書かずに回答する', '「回答は無記名ですので、率直なご意見をお書きください」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (164, 44, '期間中に回答できない人はどうすればいいですか。', '総務部に相談する', '「期間中に回答が難しい方は、総務部までご相談ください」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (165, 44, '紙で提出する場合、いつまでに出さなければなりませんか。', '6月17日まで', '「6月17日を過ぎての提出は受け付けられません」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (166, 45, 'カーナビが普及して、人々はどうなったと筆者は言っていますか。', '地図を読むのが苦手になった', '「カーナビゲーションが普及してから、地図を読むのが苦手になったという人は多い」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (167, 45, '道具が増えることの良い面として、筆者が挙げているのは何ですか。', 'より創造的な仕事に時間を使えること', '「人間はより創造的な仕事に時間を使えるようになったとも言える」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (168, 45, '文字が生まれたときのことを筆者が挙げているのはなぜですか。', '道具への心配は昔からあったことを示すため', '新しい道具に対する不安は今に始まったことではない、という例として挙げています。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (169, 45, '筆者が最も心配しているのはどんなことですか。', '道具に頼りきって、いざというとき何もできなくなること', '「道具に頼りきってしまい、いざというときに自分では何もできなくなること」が問題だと述べています。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (170, 46, '筆者は「わかりやすく伝える努力」そのものをどう見ていますか。', '否定されるべきものではないと考えている', '「わかりやすく伝える努力そのものは、もちろん否定されるべきものではない」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (171, 46, '無理に「わかりやすく」すると何が起こると筆者は言っていますか。', '本質が含まれる部分が切り落とされることがある', '「必ずどこかが切り落とされる。切り落とされた部分にこそ、本質が潜んでいることも少なくない」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (172, 46, '「わかりやすい説明」を受け取ったときの問題点は何だと筆者は述べていますか。', '自分で考えずに、与えられた枠組みを受け入れてしまう', '「提供された枠組みをそのまま受け入れたにすぎず、自分の頭で考えた結果ではない」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (173, 46, '筆者が最も重要だと考えている力は何ですか。', 'すぐに答えを求めず、複雑さに耐える力', '最後に「すぐに答えを求めず、その複雑さに耐える力ではないだろうか」と述べています。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (174, 47, 'この通知は何を知らせるものですか。', '助成金の申請が採択されなかったこと', '「貴団体の申請につきましては、採択に至らなかったことをご通知申し上げます」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (175, 47, '本年度の選考で特に重視されたのは何ですか。', '地域への効果と事業を続けられるかどうか', '「地域への波及効果および事業の継続性を特に重視して選考を行いました」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (176, 47, 'この団体の企画は、どのように評価されましたか。', '着眼点は高く評価されたが、実施体制の具体性が足りなかった', '「着眼点において高く評価されたものの、実施体制の具体性という点で…一歩及ばなかった」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (177, 47, '審査員の講評がほしい場合、どうすればいいですか。', '窓口に連絡すると書面で送ってもらえる', '「審査員からの講評を希望される場合は、下記窓口までご連絡ください。書面にてお送りいたします」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (178, 48, '会話中に間が空くと、人はどうしがちだと筆者は述べていますか。', '反射的に何かを言ってその場を埋めようとする', '「私たちは反射的に何かを言おうとし、その場を埋めようとする」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (179, 48, '即座に返ってくる言葉について、筆者はどう考えていますか。', 'あらかじめ用意された中身の薄いものであることが多い', '「即座に返ってくる言葉のほうが、あらかじめ用意された、中身の薄いものであることが多い」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (180, 48, '人の話を聴く技術を学んだ人が「最も難しい」と言うのは何ですか。', '相手が言葉に詰まったとき、黙って待つこと', '「最も難しいのは…相手が言葉に詰まったときに、こちらも黙って待つことだ」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (181, 48, 'この文章における「沈黙」の説明として、筆者の考えに最も近いものはどれですか。', '相手の言葉を時間をかけて受け止めようとする積極的な応答', '最後の段落で「沈黙は…一つの積極的な応答でありうる」「時間をかけて受け止める用意がある、という…メッセージ」と述べています。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (216, 57, '筆者は、SNSに投稿される内容についてどう述べているか。', '生活のほんの一部にすぎない', '「SNSに投稿される内容は、その人の生活のほんの一部にすぎない」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (217, 57, '筆者が伝えたいことは何か。', 'SNSの内容が生活の一部だと分かれば付き合い方が楽になる', '「そのことを頭に入れておくだけでも、SNSとの付き合い方は少し楽になるのではないだろうか」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (218, 58, '「食品ロス」とは何か。', 'まだ食べられるのに捨てられてしまう食品', '「まだ食べられるのに捨てられてしまう食品、いわゆる『食品ロス』」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (219, 58, 'これまで多くのコンビニが目指してきたことは何か。', '商品が棚いっぱいに並んでいる状態', '「常に商品が棚いっぱいに並んでいる状態を目指してきた」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (220, 58, '最近増えている取り組みは何か。', '賞味期限が近い商品を値引きして販売すること', '「賞味期限が近い商品を値引きして販売したり」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (221, 58, 'このような取り組みによってどうなると述べられているか。', '食品ロスを減らしながら客にも喜ばれる', '「食品ロスを減らしながら、客にも喜ばれる仕組みが少しずつ広がっている」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (222, 59, '筆者は今の仕事の内容についてどう感じているか。', '不満はなく、やりがいを感じることも多い', '「仕事の内容自体には不満はない。むしろ…やりがいを感じることも多い」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (223, 59, '転職を考えるきっかけは何だったか。', '後輩が半年で転職したこと', '「去年入社した後輩が、半年で転職していったことだった」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (224, 59, '後輩は何と言っていたか。', 'この先の自分が想像できない', '「『ここにいても、この先の自分が想像できない』と言っていた」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (225, 59, '筆者は自分を振り返って、どう感じているか。', '5年前と比べて大きく成長した実感がない', '「5年前と比べて、大きく成長したという実感がない」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (226, 60, 'キャッシュレス決済とは何か。', '現金を使わずに支払いができる方法', '「現金を使わずに支払いができる『キャッシュレス決済』」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (227, 60, '支払いが早く終わることの他に、どんな利点があるか。', '家計簿をつけやすくなること', '「いつ何を買ったか記録が残るため、家計簿をつけやすくなる」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (228, 60, 'キャッシュレス決済の不安な点は何か。', '電池切れやネットワークの問題で使えなくなること', '「電池が切れたりネットワークに問題があったりすると使えなくなるという不安もある」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (229, 60, '筆者はキャッシュレス決済をどう利用するべきだと考えているか。', '便利さと注意点を理解した上で上手に利用する', '「便利さと注意点の両方を理解した上で、上手に利用することが大切である」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (230, 61, '「察する文化」とはどのような文化か。', '相手の気持ちを言葉にしなくても読み取る文化', '「相手の気持ちを言葉にしなくても読み取る、いわゆる『察する文化』」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (231, 61, '「察する」ことがうまくいく相手として挙げられているのはどんな人か。', '家族や長年の友人', '「家族や長年の友人など、お互いをよく知っている間柄では」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (232, 61, '「察する」ことに頼りすぎるとどうなる可能性があるか。', '誤解が生まれやすい', '「同じことを求めてしまうと、誤解が生まれやすい」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (233, 61, '筆者はこれから何が大切になると考えているか。', '必要なことは言葉できちんと伝える力', '「必要なことは言葉できちんと伝える力も、同じくらい大切になっていく」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (234, 62, '「地域猫」とはどのような猫か。', '特定の飼い主を持たないが地域住民が世話をしている猫', '「特定の飼い主を持たないが、地域の住民が協力して世話をしている猫」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (235, 62, '地域猫活動で重要とされている活動は何か。', '獣医で手術を受けさせ数が増えないようにすること', '「これ以上数が増えないように、獣医で手術を受けさせることが重要な活動の一つ」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (236, 62, '手術を受けた猫にはどんな特徴があるか。', '耳の先が少し切られている', '「手術を受けた猫は、耳の先が少し切られており」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (237, 62, '地域猫活動に対してどんな声があるか。', 'エサやりが近所迷惑になるのではという反対の声', '「『エサやりが近所迷惑になるのでは』といった反対の声もある」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (238, 63, '筆者は、便利さを追求してきた結果について何を懸念しているか。', '人と人との小さなやり取りが失われつつあること', '「人と人との小さなやり取りが失われつつあるように思えてならない」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (182, 49, '工事はいつまで続きますか。', '6月30日まで', '「工事の期間は4月1日から6月30日までです」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (183, 49, 'バス停はどうなりますか。', '少し北側に移動する', '「駅前のバス停は少し北側に移動します」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (184, 49, '駐車場について正しいのはどれですか。', '工事期間中は無料で使える', '「駐車場の利用料金は工事期間中、無料になります」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (185, 49, '朝8時から10時に何がありますか。', '大きな音が出る作業がある', '「朝8時から10時までは大きな音が出る作業を行う予定です」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (186, 50, '実家にいたとき、家事は誰がしていたか。', '母', '「料理も洗濯も掃除も、全部母がやってくれていた」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (187, 50, '引っ越し後、特に大変だったことは何か。', '料理', '「特に困ったのは料理だ」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (188, 50, '最近、この人はどう感じているか。', '自分で作った料理を食べるのが楽しみだ', '「最近は自分で作った料理を食べるのが楽しみになった」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (189, 50, '引っ越しをする前、この人は一人暮らしについてどう思っていたか。', '自由でいいと思っていた', '「引っ越しをする前は、一人暮らしは自由でいいと思っていた」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (190, 51, '新しいサービスとは何か。', '買った食品を店内で温めて食べられること', '「店で買った食品をその場で温めて、店内の席で食べられるというサービスだ」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (191, 51, 'これまでの問題点は何だったか。', '弁当が家や職場に着くまでに冷めてしまうこと', '「家や職場に着くまでに冷めてしまうことが多かった」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (192, 51, 'このサービスは誰に人気があるか。', '一人で昼食をとる会社員や学生', '「一人で昼食をとる会社員や、時間があまりない学生に人気がある」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (193, 51, 'このサービスの利点は何か。', 'レストランより安く早く食事ができる', '「レストランに入るより安く、早く食事ができるからだ」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (194, 52, '筆者は電車の中で何をするのが好きか。', '本を読むこと', '「私は電車の中で本を読むのが好きだ」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (195, 52, '最近、電車の中で多いのはどんな人か。', 'スマートフォンを見ている人', '「本を読んでいる人より、スマートフォンを見ている人のほうがずっと多い」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (196, 52, '読書にはどんな効果があると言われているか。', '想像力を育てたり言葉を覚えたりする効果', '「想像力を育てたり、知らない言葉を覚えたりする効果があると言われている」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (197, 52, '筆者が最も伝えたいことは何か。', 'たまには本を読む時間を作ったほうがいい', '「たまには本を開いて、じっくり文章を読む時間を作ってもいいのではないだろうか」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (198, 53, '仕事内容は何か。', 'レジと商品を並べること', '「仕事内容は、レジと商品の並べ方です」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (199, 53, '経験がない人はどうすればいいか。', '丁寧に教えてもらえるので心配しなくていい', '「経験がなくても大丈夫です。丁寧に教えます」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (200, 53, '週に何日から働けるか。', '週2日から', '「週2日から働けます」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (201, 53, '応募するにはどうすればいいか。', '履歴書を持って店に行くか電話をする', '「履歴書を持って店まで来てください。電話での問い合わせも受け付けています」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (202, 54, '祖母はどうやって近況を知らせるか。', '手紙で', '「祖母は携帯電話を使わないので、いつも手紙で近況を知らせてくれる」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (203, 54, '手紙には何が書かれていたか。', '庭の野菜のことや近所の出来事', '「庭で育てている野菜のことや、近所の人との出来事」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (204, 54, '手紙の最後には何と書いてあったか。', '体に気をつけて、勉強も頑張ってね', '「最後には『体に気をつけて、勉強も頑張ってね』と書いてあった」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (205, 54, '筆者はこれからどうしようと思っているか。', '祖母に手紙を書いて返事をする', '「今度は私も、祖母に手紙を書いて返事をしようと思う」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (206, 55, '多くの人は何のために天気予報を見るか。', '傘が必要かどうか確認するため', '「『明日は傘が必要か』を確認するために天気予報を見ている」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (207, 55, '降水確率とは何か。', '雨が降る可能性を表した数字', '「これは、雨が降る可能性を表した数字で」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (208, 55, '「降水確率60%」とはどういう意味か。', '同じ天気の日が100回あれば60回くらい雨が降るという意味', '「同じような天気の日が100回あったら、そのうち60回くらい雨が降るという意味である」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (209, 55, '降水確率が低いときはどうすればいいか。', '心配なら傘を持っていくと安心', '「心配なときは傘を持っていくと安心だろう」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (210, 56, 'テレワークとは何か。', '会社に行かずに自宅などで仕事をする働き方', '「テレワークとは、会社に行かずに自宅などで仕事をする働き方のことである」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (211, 56, 'テレワークの大きなメリットは何か。', '通勤時間がなくなること', '「テレワークの大きなメリットは、通勤時間がなくなることだ」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (212, 56, 'テレワークのデメリットとして挙げられているのは何か。', '孤独を感じたり相談しにくくなったりすること', '「ちょっとした相談がしにくくなったり、孤独を感じたりする人もいる」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (213, 56, '仕事とプライベートの区別がつきにくくなると、どうなると言われているか。', 'かえって長時間働いてしまう', '「かえって長時間働いてしまうという問題も指摘されている」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (214, 57, 'SNSの魅力として挙げられているのは何か。', '遠くの友人と簡単に連絡を取り合えること', '「遠くに住む友人とも簡単に連絡を取り合えるようになった」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (215, 57, '一部の人がSNSを見て感じることは何か。', '自分の生活と比べて落ち込むこと', '「他人の投稿を見て自分と比べてしまい、落ち込むという人も少なくない」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (239, 63, '「地図アプリに頼りきりになった」例として挙げられているのはどんな変化か。', '道に迷ったときに人に尋ねる機会が減ったこと', '「道に迷ったときに人に尋ねる機会は減り、地図アプリに頼りきりになった」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (240, 63, '筆者は便利さについてどのような立場をとっているか。', '便利さ自体は否定しないが、あえて手間をかける価値も見直すべきだ', '「便利さそのものを否定するつもりはない。ただ…見直してみる必要がある」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (241, 63, 'この文章全体のテーマとして最も適切なのはどれか。', '便利さの裏にある失われつつあるものについての考察', '文章全体が、便利さの進歩とその代償について論じています。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (242, 64, '「最近の若者の言葉遣いは乱れている」という意見について、筆者はどう考えているか。', '言葉はいつの時代も変化し続けるものだと考えている', '「言葉というものは、時代とともに変化し続けるものであり」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (243, 64, '公的な場や文章について、筆者はどう述べているか。', '一定の規範を守ることが求められ、使い分けを教える意義がある', '「一定の規範を守ることが求められる。その意味で…意義がある」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (244, 64, '言葉が変化する理由について、筆者はどう考えているか。', '使う人々の生活や価値観が変化しているから', '「それを使う人々の生活や価値観が変化しているからにほかならない」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (245, 64, '筆者が最も伝えたいことは何か。', '言葉の変化がなぜ起きているのかを考えることが建設的だ', '「なぜそのような変化が起きているのかを考えることのほうが、よほど建設的ではないだろうか」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (246, 65, '現代社会について、筆者はどう述べているか。', 'あらゆることが「速さ」を基準に評価されがちだ', '「あらゆることが『速さ』を基準に評価されがちだ」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (247, 65, '「待つ」という行為は、現代においてどのように感じられがちか。', '単なる時間の無駄であるかのように感じられる', '「単なる時間の無駄であるかのように感じられてしまう」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (248, 65, '筆者が「待つことの中にある豊かさ」の例として挙げているのは何か。', '手紙の返事を何日も待った経験', '「手紙の返事を何日も待った経験がある世代には…実感として分かるはずだ」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (249, 65, '筆者が最も伝えたいことは何か。', '待つ時間の中で何を得られるか考える価値がある', '「その時間の中で何を得られるかを、一度考えてみる価値はあるだろう」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (250, 66, '多くの地方都市で同時に進んでいる問題は何か。', '高齢化と人口減少', '「高齢化と人口減少が同時に進んでいる」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (251, 66, '一部の地方自治体が進めている取り組みとして挙げられているのは何か。', '移住者への支援やテレワークを活用した働き方の提案', '「移住者への支援や、テレワークを活用した働き方の提案など」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (252, 66, '都市部から移住する人が増えている理由として挙げられているのは何か。', '自然の豊かさや生活コストの低さ', '「自然の豊かさや生活コストの低さに魅力を感じ」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (253, 66, '筆者が地方の未来を語る上で重要だと考えているのはどんな視点か。', '少ない人口でも持続可能な仕組みをどう作るかという視点', '「少ない人口でも持続可能な仕組みをどう作るかという視点ではないだろうか」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (254, 67, 'AIの進歩によって聞かれるようになった声は何か。', '創造性は人間だけのものではなくなるのではないかという声', '「『創造性は人間だけのものではなくなるのではないか』という声が聞かれるようになった」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (255, 67, 'AIが持つとされる一種の「創造性」とはどのようなものか。', '膨大なデータから人間には思いつかない組み合わせを生み出すこと', '「膨大なデータをもとに、人間には思いつかないような組み合わせを生み出すことができる」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (256, 67, '筆者は、依然として人間の役割だとしているのは何か。', '問いを立て、作りたいという意味を与えること', '「何もないところから問いを立て、なぜそれを作りたいのかという意味を与えるのは、依然として人間の役割である」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (257, 67, '筆者はAIの登場をどうとらえているか。', '人間らしい創造性とは何かを問い直させるもの', '「人間らしい創造性とは何かを、改めて私たちに問い直させているのではないだろうか」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (258, 68, '「無駄」という言葉は、効率化が叫ばれる時代においてどう使われがちか。', '否定的な意味で使われる', '「『無駄』という言葉はしばしば否定的な意味で使われる」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (259, 68, '筆者が挙げている「無駄が役に立った」例は何か。', '目的もなく歩いた散歩の途中で新しいアイデアを思いついたこと', '「目的もなく歩いた散歩の途中で新しいアイデアを思いついたり」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (260, 68, 'すべてを効率だけで測ろうとすると、どうなる可能性があるか。', '無駄から生まれる思いがけない発見まで切り捨ててしまう', '「こうした『無駄』から生まれる思いがけない発見までも切り捨ててしまいかねない」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (261, 68, '筆者が最も伝えたいことは何か。', '無駄の中に次に繋がる何かが潜んでいることを忘れないでいたい', '「無駄の中にこそ、次に繋がる何かが潜んでいることも、忘れずにいたいものである」とあります。', 4);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (262, 69, '現代の情報に求められがちなことは何か。', 'わかりやすさ', '「あらゆる情報が『わかりやすさ』を求められる時代になった」とあります。', 1);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (263, 69, 'わかりやすい説明の利点として挙げられているのは何か。', '多くの人に情報を届けられること', '「多くの人に情報を届けられるという利点がある」とあります。', 2);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (264, 69, '物事を単純化しすぎると、どんな危険があるか。', '複雑な問題が簡単に白黒つけられるもののように見えてしまう', '「本来複雑であるはずの問題が、あたかも簡単に白黒つけられるものであるかのように見えてしまう危険もある」とあります。', 3);
INSERT INTO public."ReadingQuestion" (id, "passageId", question, answer, explanation, "sortOrder") VALUES (265, 69, '筆者が読者に持っておいてほしいと述べている意識は何か。', 'わかりやすい説明の裏に単純化しきれない部分が残されているかもしれないという意識', '「その裏には単純化しきれない部分が残されているかもしれないという意識を、常に持っておく必要がある」とあります。', 4);
