INSERT INTO public."RoleplayScene" (id, slug, title, "titleJa", "desc", "sortOrder", "createdAt", "updatedAt") VALUES (1, 'cafe', 'Quán cà phê', '喫茶店', 'Gọi đồ uống và thanh toán.', 0, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayScene" (id, slug, title, "titleJa", "desc", "sortOrder", "createdAt", "updatedAt") VALUES (2, 'intro', 'Tự giới thiệu', '自己紹介', 'Gặp người mới, nói tên và quốc tịch.', 1, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayScene" (id, slug, title, "titleJa", "desc", "sortOrder", "createdAt", "updatedAt") VALUES (3, 'station', 'Hỏi đường ở ga', '駅で道を聞く', 'Hỏi nhà vệ sinh và cửa soát vé.', 2, '2026-08-28 01:42:34.292', '2026-08-28 01:42:34.292');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1, 1, '店員', 'いらっしゃいませ。', 'Xin mời vào ạ.', 0, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2, 1, 'あなた', 'コーヒーを一つください。', 'Cho tôi một cà phê.', 1, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3, 1, '店員', 'はい。こちらでお待ちください。', 'Vâng. Xin chờ ở đây ạ.', 2, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4, 1, '店員', 'お待たせしました。コーヒーです。', 'Xin lỗi đã để chờ. Đây là cà phê.', 3, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5, 1, 'あなた', 'いくらですか。', 'Bao nhiêu tiền?', 4, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6, 1, '店員', '四百円です。', '400 yên ạ.', 5, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7, 1, 'あなた', 'はい。どうも。', 'Vâng. Cảm ơn.', 6, '2026-08-28 01:42:34.262', '2026-08-28 01:42:34.262');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8, 2, '先生', '自己紹介をお願いします。', 'Mời tự giới thiệu.', 0, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9, 2, 'あなた', 'はじめまして。ズンと申します。', 'Rất vui được gặp. Tôi tên Dũng.', 1, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10, 2, 'あなた', 'ベトナムから来ました。大学生です。', 'Tôi đến từ Việt Nam. Tôi là sinh viên.', 2, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11, 2, 'あなた', '趣味は音楽を聞くことです。', 'Sở thích là nghe nhạc.', 3, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12, 2, 'あなた', 'どうぞよろしくお願いします。', 'Rất mong được giúp đỡ.', 4, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13, 2, '先生', 'ズンさん、よろしくお願いします。', 'Dũng, rất mong được giúp đỡ.', 5, '2026-08-28 01:42:34.282', '2026-08-28 01:42:34.282');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (14, 3, 'あなた', 'すみません。トイレはどこですか。', 'Xin lỗi, nhà vệ sinh ở đâu?', 0, '2026-08-28 01:42:34.292', '2026-08-28 01:42:34.292');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (15, 3, '駅員', 'あそこで右へ行ってください。', 'Đi bên phải chỗ kia.', 1, '2026-08-28 01:42:34.292', '2026-08-28 01:42:34.292');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (16, 3, 'あなた', '改札はどこですか。', 'Cửa soát vé ở đâu?', 2, '2026-08-28 01:42:34.292', '2026-08-28 01:42:34.292');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (17, 3, '駅員', 'まっすぐ行ってください。', 'Đi thẳng ạ.', 3, '2026-08-28 01:42:34.292', '2026-08-28 01:42:34.292');
INSERT INTO public."RoleplayLine" (id, "sceneId", role, ja, vi, "sortOrder", "createdAt", "updatedAt") VALUES (18, 3, 'あなた', 'ありがとうございます。', 'Cảm ơn ạ.', 4, '2026-08-28 01:42:34.292', '2026-08-28 01:42:34.292');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (1, 'Học đều mỗi ngày 30–60 phút tốt hơn học dồn cuối tuần.', 0, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (2, 'Luôn học từ vựng kèm ngữ cảnh câu — dùng tab Ngữ pháp + Từ vựng trong app.', 1, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (3, 'Kanji: học theo bài KLL, bổ sung Sō-Matome Kanji N5 trước kỳ thi.', 2, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (4, 'Minna + 新日本語の基礎 song song — giáo trình + bài tập củng cố đọc viết.', 3, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (5, '4–6 tuần trước thi: 新完全マスター + Sō-Matome; riêng Choukai & Dokkai làm đề có giờ.', 4, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (6, 'Trước kỳ thi 1 tháng: chuyển sang làm đề, không học từ mới quá nhiều.', 5, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."StudyTip" (id, text, "sortOrder", "createdAt", "updatedAt") VALUES (7, 'Đăng ký thi sớm tại VJCC / trung tâm ủy quyền — kỳ thi 7 và 12 hàng năm.', 6, '2026-06-25 10:52:31.29', '2026-06-25 10:52:31.29');
INSERT INTO public."TextbookSeries" (id, code, name, "nameJa", publisher, url, blurb, icon, "planLevels", "audioMatch", "sortOrder", "createdAt", "updatedAt") VALUES (1, 'MINNA', 'Minna no Nihongo', 'みんなの日本語', 'スリーエーネットワーク', 'https://www.3anet.co.jp/np/list.html?q=%E3%81%BF%E3%82%93%E3%81%AA%E3%81%AE%E6%97%A5%E6%9C%AC%E8%AA%9E', 'Giáo trình chính: sơ cấp I (bài 1–25 ≈ N5), sơ cấp II (bài 26–50 ≈ N4), trung cấp I/II (≈ N3/N2). Bài 1–50 có sẵn trong app.', 'み', '{N5,N4}', 'minna|みんなの日本語', 0, '2026-09-26 12:22:34.267', '2026-09-26 12:22:34.267');
INSERT INTO public."TextbookSeries" (id, code, name, "nameJa", publisher, url, blurb, icon, "planLevels", "audioMatch", "sortOrder", "createdAt", "updatedAt") VALUES (2, 'SOUMATOME', 'Sou Matome', '日本語総まとめ', 'アスク出版', 'https://ask-books.com/somatome/', 'Lịch 6 tuần × 7 ngày, ~2 trang/ngày — hợp để ôn nhanh trước kỳ thi.', '総', '{N5,N4,N3,N2,N1}', 'soumatome|sou\s*-?\s*matome|総まとめ', 1, '2026-09-26 12:22:34.278', '2026-09-26 12:22:34.278');
INSERT INTO public."TextbookSeries" (id, code, name, "nameJa", publisher, url, blurb, icon, "planLevels", "audioMatch", "sortOrder", "createdAt", "updatedAt") VALUES (3, 'SHINKANZEN', 'Shinkanzen Master', '新完全マスター', 'スリーエーネットワーク', 'https://www.3anet.co.jp/np/list.html?series_id=4', 'Giải thích kỹ, nhiều bài luyện — học sâu từng kỹ năng. Có từ N4 (không có N5).', '新', '{N4,N3,N2,N1}', 'shin\s*-?\s*kanzen|新完全', 2, '2026-09-26 12:22:34.286', '2026-09-26 12:22:34.286');
INSERT INTO public."TextbookSeries" (id, code, name, "nameJa", publisher, url, blurb, icon, "planLevels", "audioMatch", "sortOrder", "createdAt", "updatedAt") VALUES (4, 'TRY', 'TRY!', '日本語能力試験 文法から伸ばす日本語', 'アスク出版 / ABK', 'https://ask-books.com/jlpt-try/', 'Học ngữ pháp qua ngữ cảnh hội thoại/đoạn văn; audio miễn phí, list từ vựng tải về.', 'T', '{N5,N4,N3,N2,N1}', '\btry\b', 3, '2026-09-26 12:22:34.293', '2026-09-26 12:22:34.293');
