INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1, 30667, '旅行の目的は何ですか。', 'りょこうのもくてきはなんですか。', 'Mục đích chuyến đi là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2, 43969, '健康のために、たばこをやめました。', 'けんこうの ために、たばこを やめました。', 'Vì sức khỏe, tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3, 30669, '努力の結果、合格した。', 'どりょくのけっか、ごうかくした。', 'Nhờ nỗ lực, tôi đã đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4, 30672, '夏休みの計画を立てた。', 'なつやすみのけいかくをたてた。', 'Tôi đã lập kế hoạch cho kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5, 30676, '失敗を恐れないでください。', 'しっぱいをおそれないでください。', 'Đừng sợ thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6, 30675, '新しい計画は大成功でした。', 'あたらしい けいかくは だいせいこう でした。', 'Kế hoạch mới đã thành công rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7, 37910, '雨のあとで、空に虹が出た。', 'あめの あとで、そらに にじが でた。', 'Sau cơn mưa, cầu vồng hiện trên bầu trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8, 43249, '私はベトナム人です。', 'わたしは ベトナムじん です。', 'Tôi là người Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9, 31278, 'テーブルに皿を並べてください。', 'テーブルに さらを ならべて ください。', 'Hãy xếp đĩa lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10, 38389, 'この町は人が少ないです。', 'この まちは ひとが すくない です。', 'Thị trấn này ít người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11, 31303, '窓を開けてください。', 'まどを あけて ください。', 'Hãy mở cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12, 31306, '寝る前に電気を消します。', 'ねる まえに でんきを けします。', 'Trước khi ngủ tôi tắt đèn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13, 31289, 'この部屋は天井が高いです。', 'この へやは てんじょうが たかい です。', 'Căn phòng này trần cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (14, 38353, 'マッチでろうそくに火をつけました。', 'マッチで ろうそくに ひを つけました。', 'Tôi dùng diêm thắp nến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (15, 31274, '三時におやつを食べます。', 'さんじに おやつを たべます。', 'Ba giờ tôi ăn bữa phụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (16, 31277, '茶碗にご飯を入れます。', 'ちゃわんに ごはんを いれます。', 'Tôi xới cơm vào bát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (17, 38327, 'お皿を洗いました。', 'おさらを あらいました。', 'Tôi đã rửa đĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (18, 37907, '明日は晴れでしょう。', 'あしたは はれ でしょう。', 'Ngày mai có lẽ trời nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (19, 37911, '窓から光が入ります。', 'まどから ひかりが はいります。', 'Ánh sáng chiếu vào qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (20, 38354, '駅はここから五百メートルです。', 'えきは ここから ごひゃく メートル です。', 'Ga cách đây năm trăm mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (21, 38399, '二月はとても寒いです。', 'にがつは とても さむい です。', 'Tháng hai rất lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (22, 38417, '今朝の気温は零度でした。', 'けさの きおんは れいど でした。', 'Sáng nay nhiệt độ là không độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (23, 31292, '毎朝、公園を歩きます。', 'まいあさ、こうえんを あるきます。', 'Sáng nào tôi cũng đi bộ trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (24, 31294, '空を鳥が飛んでいます。', 'そらを とりが とんで います。', 'Chim đang bay trên trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (25, 31295, '日曜日、山に登りました。', 'にちようび、やまに のぼりました。', 'Chủ nhật tôi đã leo núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (26, 31301, '授業は九時に始まります。', 'じゅぎょうは くじに はじまります。', 'Giờ học bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (27, 31307, '傘を持っていますか。', 'かさを もって いますか。', 'Bạn có mang ô không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (28, 31309, 'すみません、その本を取ってください。', 'すみません、その ほんを とって ください。', 'Xin lỗi, lấy giúp tôi cuốn sách đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (29, 37684, '毎朝、犬と散歩します。', 'まいあさ、いぬと さんぽ します。', 'Sáng nào tôi cũng đi dạo với chó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (30, 37688, 'バスが駅の前に止まりました。', 'バスが えきの まえに とまりました。', 'Xe buýt đã dừng trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (31, 41973, '駅から徒歩五分です。', 'えきから とほ ごふん です。', 'Đi bộ năm phút từ ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (32, 30709, '彼は最近、様子がおかしい。', 'かれは さいきん、ようすが おかしい。', 'Dạo này anh ấy có vẻ lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (33, 30713, 'あなたの気持ちはよくわかります。', 'あなたの きもちは よく わかります。', 'Tôi rất hiểu cảm xúc của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (34, 30715, '映画を見た感想を聞かせてください。', 'えいがを みた かんそうを きかせて ください。', 'Hãy cho tôi nghe cảm nhận sau khi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (35, 30708, '今日は体の調子がいい。', 'きょうはからだのちょうしがいい。', 'Hôm nay cơ thể tôi khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (36, 30716, '彼の第一印象はよかった。', 'かれのだいいちいんしょうはよかった。', 'Ấn tượng đầu về anh ấy rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (37, 30718, '試験は予想より難しかった。', 'しけんは よそうより むずかしかった。', 'Bài thi khó hơn tôi dự đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (38, 30720, '子供のころの記憶はあまりありません。', 'こどもの ころの きおくは あまり ありません。', 'Tôi không còn nhớ nhiều về thời thơ ấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (39, 43250, 'あなたのお名前は?', 'あなたの おなまえは?', 'Tên bạn là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (40, 38408, '八百屋で野菜を買いました。', 'やおやで やさいを かいました。', 'Tôi mua rau ở cửa hàng rau quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (41, 37903, '仕事は六時に終わります。', 'しごとは ろくじに おわります。', 'Công việc kết thúc lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (42, 38383, '質問がありますか。', 'しつもんが ありますか。', 'Có câu hỏi nào không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (43, 38403, 'お年はおいくつですか。', 'おとしは おいくつ ですか。', 'Ông bao nhiêu tuổi ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (44, 37691, '時計が壊れました。', 'とけいが こわれました。', 'Đồng hồ bị hỏng rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (409, 43418, 'このカメラは高いです。', 'この カメラは たかい です。', 'Chiếc máy ảnh này đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (45, 38385, '毎朝七時に家を出ます。', 'まいあさ しちじに いえを でます。', 'Sáng nào tôi cũng ra khỏi nhà lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (46, 37682, '紫の花がきれいです。', 'むらさきの はなが きれい です。', 'Bông hoa màu tím rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (47, 38391, '図書館では静かにしてください。', 'としょかんでは しずかに して ください。', 'Ở thư viện xin hãy giữ yên lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (48, 38397, '家族はとても大切です。', 'かぞくは とても たいせつ です。', 'Gia đình rất quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (49, 38411, '駅の近くは便利です。', 'えきの ちかくは べんり です。', 'Gần ga thì tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (50, 38321, 'あの人は誰ですか。', 'あの ひとは だれ ですか。', 'Người kia là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (51, 38323, 'コーヒーはいかがですか。', 'コーヒーは いかが ですか。', 'Anh dùng cà phê nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (52, 38394, '駅の前に大きな木があります。', 'えきの まえに おおきな きが あります。', 'Trước ga có một cái cây to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (53, 31297, '駅でバスに乗ります。', 'えきで バスに のります。', 'Tôi lên xe buýt ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (54, 31298, 'あの角を右へ曲がってください。', 'あの かどを みぎへ まがって ください。', 'Hãy rẽ phải ở góc kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (55, 37687, '信号が青になってから渡ります。', 'しんごうが あおに なってから わたります。', 'Đèn xanh rồi mới sang đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (56, 37904, '国から荷物が届きました。', 'くにから にもつが とどきました。', 'Bưu kiện từ quê nhà đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (57, 37906, 'その人の名前を知っています。', 'その ひとの なまえを しって います。', 'Tôi biết tên người đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (58, 38358, '父は古いレコードを聞くのが好きです。', 'ちちは ふるい レコードを きくのが すき です。', 'Bố tôi thích nghe đĩa hát cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (59, 38381, '次の駅で降ります。', 'つぎの えきで おります。', 'Tôi xuống ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (60, 38410, 'この辺に銀行はありますか。', 'この へんに ぎんこうは ありますか。', 'Quanh đây có ngân hàng không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (61, 37945, '後輩の面倒を見ています。', 'こうはいの めんどうを みて います。', 'Tôi đang kèm cặp đàn em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (62, 38549, '庭の草を取りました。', 'にわの くさを とりました。', 'Tôi nhổ cỏ trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (63, 37933, 'この写真を見ると、懐かしいです。', 'この しゃしんを みると、なつかしい です。', 'Nhìn bức ảnh này thấy hoài niệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (64, 37935, 'その映画を見て、感動しました。', 'その えいがを みて、かんどう しました。', 'Xem bộ phim đó tôi rất cảm động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (65, 37937, '試合を見て、みんな興奮しました。', 'しあいを みて、みんな こうふん しました。', 'Xem trận đấu, ai cũng phấn khích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (66, 26984, '誰ですか。', 'だれですか。', 'Ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (67, 37946, '駅で小学校の同級生に会った。', 'えきで しょうがっこうの どうきゅうせいに あった。', 'Tôi gặp bạn cùng lớp tiểu học ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (68, 37920, '大阪まで片道一万四千円かかる。', 'おおさかまで かたみち いちまん よんせんえん かかる。', 'Vé một chiều đến Osaka mất mười bốn nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (69, 37982, '大雨で洪水が起きた。', 'おおあめで こうずいが おきた。', 'Mưa lớn đã gây ra lũ lụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (70, 43251, 'あの人は日本人です。', 'あの ひとは にほんじん です。', 'Người kia là người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (71, 27268, '私は肉より魚が好きです。', 'わたしは にくより さかなが すき です。', 'Tôi thích cá hơn thịt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (72, 27271, '水をください。', 'みずを ください。', 'Cho tôi xin nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (73, 27307, 'レストランへ行きます。', 'レストランへいきます。', 'Tôi đi đến nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (74, 37939, '会議の資料を印刷しました。', 'かいぎの しりょうを いんさつ しました。', 'Tôi đã in tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (75, 37940, 'ここに署名してください。', 'ここに しょめい して ください。', 'Xin hãy ký tên vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (76, 27329, 'ホッチキスで書類をとめます。', 'ホッチキスで しょるいを とめます。', 'Tôi dập ghim tài liệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (77, 38380, 'わからない字は字引で調べます。', 'わからない じは じびきで しらべます。', 'Chữ nào không biết tôi tra từ điển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (78, 38413, '父の誕生日に万年筆をあげました。', 'ちちの たんじょうびに まんねんひつを あげました。', 'Sinh nhật bố, tôi tặng bố cây bút máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (79, 37942, '四月に大学に入学します。', 'しがつに だいがくに にゅうがく します。', 'Tháng tư tôi nhập học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (80, 37948, '卒業式で泣いてしまいました。', 'そつぎょうしきで ないて しまいました。', 'Tôi đã khóc ở lễ tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (81, 37949, '入学式は四月一日です。', 'にゅうがくしきは しがつ ついたち です。', 'Lễ nhập học vào ngày mùng một tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (82, 37956, '駅の近くに引っ越しました。', 'えきの ちかくに ひっこしました。', 'Tôi đã chuyển đến gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (83, 38422, 'アルコールは飲めません。', 'アルコールは のめません。', 'Tôi không uống được rượu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (84, 38439, '毎朝サラダを食べます。', 'まいあさ サラダを たべます。', 'Sáng nào tôi cũng ăn salad.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (85, 37924, '空港でドルを円に両替しました。', 'くうこうで ドルを えんに りょうがえ しました。', 'Tôi đổi đô la sang yên ở sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (86, 38546, '西洋の文化に興味があります。', 'せいようの ぶんかに きょうみが あります。', 'Tôi quan tâm đến văn hóa phương Tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (87, 38560, '毎朝この道を通ります。', 'まいあさ この みちを とおります。', 'Sáng nào tôi cũng đi qua con đường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (533, 26972, 'さくらちゃんはかわいいです。', NULL, 'Bé Sakura dễ thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (88, 37985, '地震のときは、公園に避難します。', 'じしんの ときは、こうえんに ひなん します。', 'Khi động đất thì sơ tán ra công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (89, 38424, 'おなかがいっぱいです。', 'おなかが いっぱい です。', 'Tôi no căng bụng rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (90, 27544, 'コーヒーを二つお願いします。', 'コーヒーを ふたつ おねがい します。', 'Cho tôi hai cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (91, 38569, 'この店は値段が二倍です。', 'この みせは ねだんが にばい です。', 'Cửa hàng này giá gấp đôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (92, 30813, 'その瞬間、全員が息をのんだ。', 'そのしゅんかん、ぜんいんがいきをのんだ。', 'Khoảnh khắc đó, tất cả nín thở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (93, 37712, '雨は一週間続きました。', 'あめは いっしゅうかん つづきました。', 'Mưa kéo dài một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (94, 37714, '去年と比べると、今年は暑いです。', 'きょねんと くらべると、ことしは あつい です。', 'So với năm ngoái thì năm nay nóng hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (95, 37950, '音楽に合わせて踊りました。', 'おんがくに あわせて おどりました。', 'Chúng tôi nhảy theo điệu nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (96, 37952, 'もう一度、時間を確認してください。', 'もう いちど、じかんを かくにん して ください。', 'Hãy xác nhận lại thời gian một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (97, 30821, '提出期限は明日です。', 'ていしゅつきげんはあすです。', 'Hạn nộp là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (98, 37954, '子どもがコップを倒しました。', 'こどもが コップを たおしました。', 'Đứa trẻ làm đổ cái cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (99, 38494, '洗濯物がよく乾きました。', 'せんたくものが よく かわきました。', 'Đồ giặt đã khô ráo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (100, 38503, '仕事が見つかりました。', 'しごとが みつかりました。', 'Tôi đã tìm được việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (101, 38507, '夜空に星が光っています。', 'よぞらに ほしが ひかって います。', 'Sao đang lấp lánh trên bầu trời đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (102, 30795, '奨学金を申し込みたい。', 'しょうがくきんをもうしこみたい。', 'Tôi muốn xin học bổng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (103, 38552, 'パソコンで手紙を打ちました。', 'パソコンで てがみを うちました。', 'Tôi đánh máy lá thư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (104, 38579, '警察が泥棒を捕まえました。', 'けいさつが どろぼうを つかまえました。', 'Cảnh sát đã bắt được kẻ trộm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (105, 30797, 'まず一階の受付で名前を言ってください。', 'まず いっかいの うけつけで なまえを いって ください。', 'Trước tiên hãy báo tên ở quầy lễ tân tầng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (106, 30833, '飛行機は予定通りに到着した。', 'ひこうきは よていどおりに とうちゃく した。', 'Máy bay đã đến đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (107, 30816, '当時、私はまだ学生だった。', 'とうじ、わたしは まだ がくせい だった。', 'Hồi ấy tôi vẫn còn là sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (108, 30818, '会議の最中に電話が鳴った。', 'かいぎの さいちゅうに でんわが なった。', 'Đang giữa cuộc họp thì điện thoại reo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (109, 30820, 'セールの期間は一週間です。', 'セールの きかんは いっしゅうかん です。', 'Thời gian giảm giá là một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (110, 30824, '台風でコンサートが中止になった。', 'たいふうで コンサートが ちゅうしに なった。', 'Buổi hòa nhạc bị hủy vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (111, 30827, 'ボランティア活動に参加したい。', 'ボランティア かつどうに さんか したい。', 'Tôi muốn tham gia hoạt động tình nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (112, 30828, '友達の結婚式に出席した。', 'ともだちの けっこんしきに しゅっせき した。', 'Tôi đã dự đám cưới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (113, 30830, '寝坊して、会社に遅刻した。', 'ねぼう して、かいしゃに ちこく した。', 'Ngủ quên nên tôi đi làm muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (114, 30832, '明日、取引先を訪問する予定です。', 'あした、とりひきさきを ほうもん する よてい です。', 'Ngày mai tôi dự định đến thăm đối tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (115, 43253, '受付に女の人がいます。', 'うけつけに おんなの ひとが います。', 'Ở quầy lễ tân có một người phụ nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (116, 43988, '隣の部屋から子どもの声が聞こえます。', 'となりの へやから こどもの こえが きこえます。', 'Nghe thấy tiếng trẻ con từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (117, 37719, 'この辞書はとても役に立ちます。', 'この じしょは とても やくに たちます。', 'Cuốn từ điển này rất có ích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (118, 37974, 'この公園は静かです。', 'この こうえんは しずか です。', 'Công viên này yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (119, 30839, '彼はめったに怒らない。', 'かれはめったにおこらない。', 'Anh ấy hiếm khi tức giận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (120, 30846, 'その条件なら受け入れられる。', 'そのじょうけんならうけいれられる。', 'Điều kiện đó thì tôi chấp nhận được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (121, 30857, '最近、晩婚化の傾向がある。', 'さいきん、ばんこんかのけいこうがある。', 'Gần đây có xu hướng kết hôn muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (122, 30873, '痛みを我慢した。', 'いたみをがまんした。', 'Tôi đã chịu đựng cơn đau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (123, 30866, 'この村の人口は減少している。', 'この むらの じんこうは げんしょう して いる。', 'Dân số làng này đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (124, 30835, '毎日電車で通勤しています。', 'まいにち でんしゃで つうきん して います。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (125, 30865, '外国人観光客が増加している。', 'がいこくじん かんこうきゃくが ぞうか して いる。', 'Khách du lịch nước ngoài đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (126, 30872, '両親は私の留学に反対した。', 'りょうしんは わたしの りゅうがくに はんたい した。', 'Bố mẹ phản đối việc tôi đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (127, 30879, '毎日料理をするのは面倒だ。', 'まいにち りょうりを するのは めんどうだ。', 'Ngày nào cũng nấu ăn thật phiền phức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (165, 43260, '兄は東京で働いています。', 'あには とうきょうで はたらいて います。', 'Anh trai tôi làm việc ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (128, 30837, 'たびたびご迷惑をおかけして、すみません。', 'たびたび ごめいわくを おかけ して、すみません。', 'Xin lỗi vì đã nhiều lần làm phiền anh chị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (129, 30841, 'いきなり後ろから声をかけられて、驚いた。', 'いきなり うしろから こえを かけられて、おどろいた。', 'Bất ngờ bị gọi từ phía sau, tôi giật mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (130, 30843, '合格の基準は六十点以上です。', 'ごうかくの きじゅんは ろくじってん いじょう です。', 'Tiêu chuẩn đỗ là từ 60 điểm trở lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (131, 30848, '環境の観点から、この計画には問題がある。', 'かんきょうの かんてんから、この けいかくには もんだいが ある。', 'Xét từ quan điểm môi trường, kế hoạch này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (132, 30851, '審判の判定に不満を持つ選手もいた。', 'しんぱんの はんていに ふまんを もつ せんしゅも いた。', 'Có cầu thủ không hài lòng với phán định của trọng tài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (133, 30854, '事件に関連するニュースを集めた。', 'じけんに かんれん する ニュースを あつめた。', 'Tôi thu thập các tin tức liên quan đến vụ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (134, 30856, '会議の内容をメモしておいてください。', 'かいぎの ないようを メモ して おいて ください。', 'Hãy ghi lại nội dung cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (135, 30860, '一日一時間程度、運動している。', 'いちにち いちじかん ていど、うんどう して いる。', 'Mỗi ngày tôi tập thể dục khoảng một tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (136, 30862, 'このクラスは女性の割合が高い。', 'この クラスは じょせいの わりあいが たかい。', 'Lớp này tỷ lệ nữ cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (137, 30864, '全部で合計いくらですか。', 'ぜんぶで ごうけい いくら ですか。', 'Tổng cộng tất cả là bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (138, 30869, '二人には共通の趣味がある。', 'ふたりには きょうつうの しゅみが ある。', 'Hai người có sở thích chung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (139, 30870, '国と国の相互理解が大切だ。', 'くにと くにの そうご りかいが たいせつだ。', 'Sự hiểu biết lẫn nhau giữa các nước là quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (140, 30878, '両親は私を育てるのに苦労した。', 'りょうしんは わたしを そだてるのに くろう した。', 'Bố mẹ đã vất vả nuôi tôi khôn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (141, 27457, 'ご主人はお元気ですか。', 'ごしゅじんは おげんき ですか。', 'Chồng chị có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (142, 30880, 'ご迷惑をおかけしました。', 'ごめいわくをおかけしました。', 'Tôi đã làm phiền quý vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (143, 37976, '彼女はとても優秀です。', 'かのじょは とても ゆうしゅう です。', 'Cô ấy rất xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (144, 37981, 'この部屋はとてもきれいです。', 'この へやは とても きれい です。', 'Căn phòng này rất sạch sẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (145, 30890, 'まさか彼が来るとは思わなかった。', 'まさかかれがくるとはおもわなかった。', 'Không ngờ anh ấy lại đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (146, 30904, '前向きに検討します。', 'まえむきにけんとうします。', 'Chúng tôi sẽ cân nhắc tích cực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (147, 30886, '料理が余ったので、近所に分けた。', 'りょうりが あまったので、きんじょに わけた。', 'Đồ ăn còn thừa nên tôi chia cho hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (148, 30910, '理科の授業で実験をした。', 'りかの じゅぎょうで じっけんを した。', 'Trong giờ khoa học chúng tôi làm thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (149, 30882, '参加者は二十人に限ります。', 'さんかしゃは にじゅうにんに かぎります。', 'Số người tham gia giới hạn ở hai mươi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (150, 30885, '最近、睡眠不足が続いている。', 'さいきん、すいみん ぶそくが つづいて いる。', 'Gần đây tôi liên tục bị thiếu ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (151, 30888, '時間は十分にあるので、急がなくてもいい。', 'じかんは じゅうぶんに あるので、いそがなくても いい。', 'Thời gian còn đủ nên không cần vội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (152, 30892, '忙しくても、せめて朝ご飯は食べなさい。', 'いそがしくても、せめて あさごはんは たべなさい。', 'Dù bận, ít nhất cũng phải ăn sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (153, 30895, 'あいにく、部長は外出しております。', 'あいにく、ぶちょうは がいしゅつ して おります。', 'Rất tiếc, trưởng phòng đang ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (154, 30897, 'いくら練習しても、上手にならない。', 'いくら れんしゅう しても、じょうずに ならない。', 'Dù luyện tập bao nhiêu cũng không giỏi lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (155, 30899, '薬を飲んだら、かえって具合が悪くなった。', 'くすりを のんだら、かえって ぐあいが わるく なった。', 'Uống thuốc vào lại còn thấy mệt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (156, 30901, '彼が料理上手なのは意外だった。', 'かれが りょうり じょうず なのは いがい だった。', 'Anh ấy nấu ăn giỏi là điều bất ngờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (157, 30905, '予算を考慮して、計画を立てた。', 'よさんを こうりょ して、けいかくを たてた。', 'Tôi lập kế hoạch có cân nhắc đến ngân sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (158, 30908, '夏休みに朝顔の観察日記をつけた。', 'なつやすみに あさがおの かんさつ にっきを つけた。', 'Kỳ nghỉ hè tôi viết nhật ký quan sát hoa bìm bìm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (159, 30911, '身分を証明するものを持っていますか。', 'みぶんを しょうめい する ものを もって いますか。', 'Bạn có giấy tờ chứng minh nhân thân không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (160, 30913, '彼の話は事実と違う。', 'かれの はなしは じじつと ちがう。', 'Câu chuyện của anh ta khác với sự thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (161, 30916, 'この問題の背景には少子化がある。', 'この もんだいの はいけいには しょうしかが ある。', 'Đằng sau vấn đề này là tình trạng giảm sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (162, 30917, '結婚を前提に付き合っている。', 'けっこんを ぜんていに つきあって いる。', 'Chúng tôi hẹn hò với tiền đề là sẽ kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (163, 43256, '父は銀行員です。', 'ちちは ぎんこういん です。', 'Bố tôi là nhân viên ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (164, 43259, 'お母さんは何歳ですか。', 'おかあさんは なんさい ですか。', 'Mẹ bạn bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (166, 27766, '新しい服を買いました。', 'あたらしい ふくを かいました。', 'Tôi đã mua quần áo mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (167, 27811, '頭が痛いです。', 'あたまが いたい です。', 'Tôi bị đau đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (168, 38554, 'これは大事な書類です。', 'これは だいじな しょるい です。', 'Đây là tài liệu quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (169, 30922, '彼の話には矛盾がある。', 'かれのはなしにはむじゅんがある。', 'Lời anh ta có mâu thuẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (170, 38567, '今日は特別な日です。', 'きょうは とくべつな ひ です。', 'Hôm nay là một ngày đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (171, 38576, 'この問題は複雑です。', 'この もんだいは ふくざつ です。', 'Vấn đề này phức tạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (172, 38581, '無理をしないでください。', 'むりを しないで ください。', 'Đừng làm quá sức nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (173, 38545, '日本ではサッカーも盛んです。', 'にほんでは サッカーも さかん です。', 'Ở Nhật bóng đá cũng phát triển mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (174, 37703, 'この店はいろいろな種類のパンがあります。', 'この みせは いろいろな しゅるいの パンが あります。', 'Tiệm này có nhiều loại bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (175, 37706, 'この車の欠点は高いことです。', 'この くるまの けってんは たかい こと です。', 'Khuyết điểm của chiếc xe này là đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (176, 38553, '母の代わりに私が行きます。', 'ははの かわりに わたしが いきます。', 'Tôi sẽ đi thay mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (177, 38584, '遅れた訳を教えてください。', 'おくれた わけを おしえて ください。', 'Hãy cho tôi biết lý do đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (178, 37700, '我々の目標は優勝です。', 'われわれの もくひょうは ゆうしょう です。', 'Mục tiêu của chúng ta là vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (179, 30933, 'この薬はすぐに効果が出た。', 'この くすりは すぐに こうかが でた。', 'Thuốc này có hiệu quả ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (180, 30920, '話の要点をまとめてください。', 'はなしの ようてんを まとめて ください。', 'Hãy tóm tắt các điểm chính của câu chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (181, 37740, 'なるべく野菜を食べるようにしています。', 'なるべく やさいを たべる ように して います。', 'Tôi cố gắng ăn nhiều rau nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (182, 30959, '問題の本質を見抜く。', 'もんだいのほんしつをみぬく。', 'Nhìn thấu bản chất vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (183, 30923, '何か疑問があれば、聞いてください。', 'なにか ぎもんが あれば、きいて ください。', 'Nếu có thắc mắc gì, hãy hỏi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (184, 30927, '政府の政策は多くの人から批判された。', 'せいふの せいさくは おおくの ひとから ひはん された。', 'Chính sách của chính phủ bị nhiều người phê phán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (185, 30930, '曖昧な返事をしないで、はっきり言ってください。', 'あいまいな へんじを しないで、はっきり いって ください。', 'Đừng trả lời mập mờ, hãy nói rõ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (186, 30932, '場面に合った適切な言葉を選ぼう。', 'ばめんに あった てきせつな ことばを えらぼう。', 'Hãy chọn từ ngữ thích hợp với hoàn cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (187, 30960, '売り上げが減った要因を調べている。', 'うりあげが へった よういんを しらべて いる。', 'Chúng tôi đang tìm hiểu nhân tố khiến doanh thu giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (188, 27076, '昼ごはんは食堂で食べます。', 'ひるごはんは しょくどうで たべます。', 'Tôi ăn trưa ở nhà ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (189, 43262, '弟は大学生です。', 'おとうとは だいがくせい です。', 'Em trai tôi là sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (190, 37742, '家に着いたら、すぐに電話します。', 'いえに ついたら、すぐに でんわ します。', 'Về đến nhà tôi sẽ gọi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (191, 37744, 'できれば、あした来てください。', 'できれば、あした きて ください。', 'Nếu có thể thì mai hãy đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (192, 38423, 'あんな人になりたいです。', 'あんな ひとに なりたい です。', 'Tôi muốn trở thành người như thế kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (193, 30961, 'その主張には科学的な根拠がない。', 'その しゅちょうには かがくてきな こんきょが ない。', 'Lập luận đó không có căn cứ khoa học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (194, 30963, '会社の理念に共感して入社した。', 'かいしゃの りねんに きょうかん して にゅうしゃ した。', 'Tôi vào công ty vì đồng cảm với triết lý của nó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (195, 38429, '夏のお祭りで盆踊りを見ました。', 'なつの おまつりで ぼんおどりを みました。', 'Ở lễ hội mùa hè tôi đã xem múa Bon odori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (196, 38555, '病気はだいぶよくなりました。', 'びょうきは だいぶ よく なりました。', 'Bệnh đã đỡ nhiều rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (197, 38570, '彼らは同じ会社の人です。', 'かれらは おなじ かいしゃの ひと です。', 'Họ là người cùng công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (198, 38561, '川で魚を釣りました。', 'かわで さかなを つりました。', 'Tôi câu cá ở sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (199, 38565, '自転車を盗まれました。', 'じてんしゃを ぬすまれました。', 'Tôi bị trộm mất xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (200, 30989, '政府は省エネを推進している。', 'せいふは しょうエネを すいしん して いる。', 'Chính phủ đang thúc đẩy tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (201, 30671, '今年の目標は日本語能力試験に合格することです。', 'ことしの もくひょうは にほんごのうりょくしけんに ごうかくする ことです。', 'Mục tiêu năm nay là đỗ kỳ thi năng lực tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (202, 30987, '状況を正確に把握する。', 'じょうきょうをせいかくにはあくする。', 'Nắm bắt chính xác tình hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (203, 30991, 'この薬は痛みを抑制する効果がある。', 'この くすりは いたみを よくせい する こうかが ある。', 'Thuốc này có tác dụng ức chế cơn đau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (204, 30997, '健康を維持するために毎日歩いている。', 'けんこうを いじ する ために まいにち あるいて いる。', 'Tôi đi bộ mỗi ngày để duy trì sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (242, 31051, '我慢にも限度がある。', 'がまんにも げんどが ある。', 'Sự chịu đựng cũng có giới hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (205, 31003, '職場の環境を改善する必要がある。', 'しょくばの かんきょうを かいぜん する ひつようが ある。', 'Cần cải thiện môi trường làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (206, 30996, 'スマホが急速に普及した。', 'スマホがきゅうそくにふきゅうした。', 'Điện thoại thông minh phổ cập nhanh chóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (207, 31005, '問題が起きたら、すぐに対処してください。', 'もんだいが おきたら、すぐに たいしょ して ください。', 'Nếu xảy ra vấn đề, hãy ứng phó ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (208, 39126, '日本では十八歳で成人になる。', 'にほんでは じゅうはっさいで せいじんに なる。', 'Ở Nhật, 18 tuổi là thành người lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (209, 39439, '大学時代の友人と食事をした。', 'だいがく じだいの ゆうじんと しょくじを した。', 'Tôi đi ăn với người bạn thời đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (210, 42863, '彼はサッカー部のキャプテンだ。', 'かれは サッカーぶの キャプテンだ。', 'Cậu ấy là đội trưởng câu lạc bộ bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (211, 30998, '継続は力なり。', 'けいぞくは ちからなり。', 'Kiên trì là sức mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (212, 30967, '酒を飲むと、彼はつい本音を言ってしまう。', 'さけを のむと、かれは つい ほんねを いって しまう。', 'Hễ uống rượu là anh ta buột miệng nói thật lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (213, 30973, '交渉では双方が少しずつ譲歩した。', 'こうしょうでは そうほうが すこしずつ じょうほ した。', 'Trong đàm phán, hai bên đều nhượng bộ từng chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (214, 31008, '週末までに課題を出さなければならない。', 'しゅうまつまでに かだいを ださなければ ならない。', 'Tôi phải nộp bài tập trước cuối tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (215, 38498, 'この業界は競争が激しい。', 'この ぎょうかいは きょうそうが はげしい。', 'Ngành này cạnh tranh gay gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (216, 31000, 'この路線のバスは来月で廃止される。', 'この ろせんの バスは らいげつで はいし される。', 'Tuyến xe buýt này sẽ bị bãi bỏ từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (217, 30971, '専門家の間でも見解が分かれている。', 'せんもんかの あいだでも けんかいが わかれて いる。', 'Ngay giữa các chuyên gia cũng có quan điểm khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (218, 30974, '両社は話し合いの末、合意に達した。', 'りょうしゃは はなしあいの すえ、ごういに たっした。', 'Sau khi bàn bạc, hai công ty đã đạt được đồng thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (219, 43263, '妹は高校生です。', 'いもうとは こうこうせい です。', 'Em gái tôi là học sinh cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (220, 31011, '私たちは科学技術の恩恵を受けている。', 'わたしたちは かがく ぎじゅつの おんけいを うけて いる。', 'Chúng ta đang hưởng lợi ích từ khoa học kỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (221, 31013, '仕事と育児を両立する。', 'しごとといくじをりょうりつする。', 'Cân bằng cả công việc lẫn nuôi con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (222, 31014, '新しいビジネスの形を模索している。', 'あたらしい ビジネスの かたちを もさく して いる。', 'Chúng tôi đang mò mẫm tìm mô hình kinh doanh mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (223, 31018, '別れた恋人にまだ未練がある。', 'わかれた こいびとに まだ みれんが ある。', 'Tôi vẫn còn lưu luyến người yêu cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (224, 31021, '仕事と家庭の間で葛藤している。', 'しごとと かていの あいだで かっとう して いる。', 'Tôi đang giằng xé giữa công việc và gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (225, 31025, '無事の知らせに安堵した。', 'ぶじのしらせにあんどした。', 'Tôi nhẹ nhõm khi nghe tin bình an.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (226, 31049, '常識の枠を超える発想。', 'じょうしきのわくをこえるはっそう。', 'Ý tưởng vượt khỏi khuôn khổ thường thức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (227, 31023, '月曜日の朝はいつも憂鬱だ。', 'げつようびの あさは いつも ゆううつだ。', 'Sáng thứ Hai lúc nào cũng u uất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (228, 31056, '該当する項目に丸をつける。', 'がいとうするこうもくにまるをつける。', 'Khoanh tròn vào mục tương ứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (229, 31048, 'これは私の専門の領域ではない。', 'これは わたしの せんもんの りょういき では ない。', 'Đây không phải lĩnh vực chuyên môn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (230, 31035, '彼の日本語は著しく上達した。', 'かれの にほんごは いちじるしく じょうたつ した。', 'Tiếng Nhật của anh ấy tiến bộ rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (231, 27255, '図書館で本を読みます。', 'としょかんで ほんを よみます。', 'Tôi đọc sách ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (232, 31026, '娘の結婚式で感無量だった。', 'むすめの けっこんしきで かんむりょう だった。', 'Trong đám cưới con gái, tôi xúc động khôn xiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (233, 31028, '厳しい練習になることは覚悟している。', 'きびしい れんしゅうに なる ことは かくご して いる。', 'Tôi đã sẵn sàng cho việc tập luyện khắc nghiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (234, 31030, '彼女は自分の信念を曲げなかった。', 'かのじょは じぶんの しんねんを まげなかった。', 'Cô ấy không từ bỏ niềm tin của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (235, 31033, '栄養の偏りに気をつけている。', 'えいようの かたよりに きを つけて いる。', 'Tôi chú ý để dinh dưỡng không bị thiên lệch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (236, 31036, 'それは甚だしい誤解だ。', 'それは はなはだしい ごかいだ。', 'Đó là một sự hiểu lầm nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (237, 31038, '人間関係が煩わしくなってきた。', 'にんげん かんけいが わずらわしく なって きた。', 'Các mối quan hệ con người bắt đầu trở nên phiền toái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (238, 31040, '彼は合格のためにひたすら勉強した。', 'かれは ごうかくの ために ひたすら べんきょう した。', 'Anh ấy chỉ một mực học để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (239, 31042, 'あえて難しい道を選んだ。', 'あえて むずかしい みちを えらんだ。', 'Tôi cố tình chọn con đường khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (240, 31044, 'いかにも彼らしい答えだ。', 'いかにも かれらしい こたえだ。', 'Đúng là câu trả lời rất đặc trưng của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (241, 31047, 'それは私の専門の範疇を超えている。', 'それは わたしの せんもんの はんちゅうを こえて いる。', 'Điều đó vượt quá phạm trù chuyên môn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (243, 31054, '全社員の給料を一律に上げた。', 'ぜん しゃいんの きゅうりょうを いちりつに あげた。', 'Công ty tăng lương đồng loạt cho toàn bộ nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (244, 31057, 'セール品は割引の対象外です。', 'セールひんは わりびきの たいしょうがい です。', 'Hàng khuyến mãi không thuộc diện giảm giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (245, 26968, '私は学生です。', 'わたしはがくせいです。', 'Tôi là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (246, 38096, '父は来週、胃の手術を受ける。', 'ちちは らいしゅう、いの しゅじゅつを うける。', 'Tuần sau bố tôi sẽ mổ dạ dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (247, 38098, '今も週に一回通院している。', 'いまも しゅうに いっかい つういん して いる。', 'Hiện tôi vẫn đi khám mỗi tuần một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (248, 38100, 'この薬は眠くなる副作用がある。', 'この くすりは ねむく なる ふくさようが ある。', 'Thuốc này có tác dụng phụ gây buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (249, 38101, '私は卵のアレルギーがあります。', 'わたしは たまごの アレルギーが あります。', 'Tôi bị dị ứng trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (250, 39336, '転んで膝をけがした。', 'ころんで ひざを けが した。', 'Tôi ngã và bị thương ở đầu gối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (251, 39341, '彼女は暗い表情で話した。', 'かのじょは くらい ひょうじょうで はなした。', 'Cô ấy kể chuyện với vẻ mặt u buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (252, 37754, '給料が安いことに不満がある。', 'きゅうりょうが やすい ことに ふまんが ある。', 'Tôi bất mãn vì lương thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (253, 37756, '地震の恐怖は今も忘れられない。', 'じしんの きょうふは いまも わすれられない。', 'Nỗi sợ trận động đất đến giờ vẫn không quên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (254, 37758, '子供が生まれた喜びは言葉にできない。', 'こどもが うまれた よろこびは ことばに できない。', 'Niềm vui khi con chào đời không thể diễn tả bằng lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (255, 37761, '彼には盗みの疑いがかけられている。', 'かれには ぬすみの うたがいが かけられて いる。', 'Anh ta đang bị nghi ngờ trộm cắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (256, 37764, 'みんなが彼の不運に同情した。', 'みんなが かれの ふうんに どうじょう した。', 'Mọi người đều thương cảm cho sự xui xẻo của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (257, 39102, 'みんな真剣な顔で説明を聞いている。', 'みんな しんけんな かおで せつめいを きいて いる。', 'Mọi người đang nghe giải thích với vẻ mặt nghiêm túc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (258, 39294, '息子はゲームに熱中している。', 'むすこは ゲームに ねっちゅう して いる。', 'Con trai tôi đang mê game.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (259, 39306, 'そんな馬鹿なことを言わないで。', 'そんな ばかな ことを いわないで。', 'Đừng nói chuyện ngớ ngẩn như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (260, 39333, '赤ちゃんが母親を見て微笑んだ。', 'あかちゃんが ははおやを みて ほほえんだ。', 'Em bé nhìn mẹ và mỉm cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (261, 39346, '初めての一人旅は少し不安だ。', 'はじめての ひとりたびは すこし ふあんだ。', 'Lần đầu đi du lịch một mình nên hơi lo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (262, 39352, '彼女は不平を言わずに働いている。', 'かのじょは ふへいを いわずに はたらいて いる。', 'Cô ấy làm việc mà không một lời phàn nàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (263, 27061, 'テレホンカードで電話をかけました。', 'テレホンカードで でんわを かけました。', 'Tôi gọi điện bằng thẻ điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (264, 27099, 'このかばんはいくらですか。', 'この かばんは いくら ですか。', 'Chiếc cặp này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (265, 27116, 'ここでたばこを吸わないでください。', 'ここで たばこを すわないで ください。', 'Xin đừng hút thuốc ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (266, 43264, 'お兄さんは何をしていますか。', 'おにいさんは なにを して いますか。', 'Anh trai bạn đang làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (267, 43266, '兄弟が何人いますか。', 'きょうだいが なんにん いますか。', 'Bạn có mấy anh chị em?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (268, 43267, '両親はベトナムに住んでいます。', 'りょうしんは ベトナムに すんで います。', 'Bố mẹ tôi sống ở Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (269, 43269, '祖母は田舎に住んでいます。', 'そぼは いなかに すんで います。', 'Bà tôi sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (270, 43271, 'おばあさんに道を教えました。', 'おばあさんに みちを おしえました。', 'Tôi chỉ đường cho một cụ bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (271, 39457, '彼は陽気な性格で、みんなに好かれている。', 'かれは ようきな せいかくで、みんなに すかれて いる。', 'Anh ấy tính tình vui vẻ nên được mọi người quý mến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (272, 38923, '祖父は戦争の体験を語ってくれた。', 'そふは せんそうの たいけんを かたって くれた。', 'Ông kể cho tôi nghe những trải nghiệm thời chiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (273, 39286, '事件の謎はまだ解けていない。', 'じけんの なぞは まだ とけて いない。', 'Bí ẩn của vụ án vẫn chưa được giải đáp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (274, 39423, '先生に聞かれて、彼は黙ってしまった。', 'せんせいに きかれて、かれは だまって しまった。', 'Bị thầy hỏi, cậu ấy im lặng luôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (275, 39445, '今年の売り上げを予測するのは難しい。', 'ことしの うりあげを よそく するのは むずかしい。', 'Rất khó dự báo doanh thu năm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (276, 39456, '労働者は給料を上げるよう要求した。', 'ろうどうしゃは きゅうりょうを あげる よう ようきゅう した。', 'Công nhân đã yêu cầu tăng lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (277, 37748, '担当者から明日連絡いたします。', 'たんとうしゃから あした れんらく いたします。', 'Người phụ trách sẽ liên lạc với quý khách vào ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (278, 43274, '友達と映画を見ました。', 'ともだちと えいがを みました。', 'Tôi đã xem phim với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (279, 27225, '五月五日は子供の日です。', 'ごがつ いつかは こどもの ひ です。', 'Ngày 5 tháng 5 là ngày Thiếu nhi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (280, 43311, '私の部屋は狭いです。', 'わたしの へやは せまい です。', 'Phòng của tôi hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (281, 43275, 'ここに名前を書いてください。', 'ここに なまえを かいて ください。', 'Hãy viết tên vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (282, 43286, '毎日運動すると、体にいいです。', 'まいにち うんどう すると、からだに いい です。', 'Tập thể dục mỗi ngày tốt cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (283, 43288, '朝、顔を洗います。', 'あさ、かおを あらいます。', 'Buổi sáng tôi rửa mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (284, 43290, '象は耳が大きいです。', 'ぞうは みみが おおきい です。', 'Voi có đôi tai to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (285, 43293, 'たくさん歩いて、足が痛いです。', 'たくさん あるいて、あしが いたい です。', 'Đi bộ nhiều nên đau chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (286, 43276, 'お年はおいくつですか。', 'おとしは おいくつ ですか。', 'Ông bao nhiêu tuổi ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (287, 43277, '妹は十五歳です。', 'いもうとは じゅうごさい です。', 'Em gái tôi mười lăm tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (288, 43281, '私は大学の学生です。', 'わたしは だいがくの がくせい です。', 'Tôi là sinh viên đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (289, 43283, '兄は会社員です。', 'あには かいしゃいん です。', 'Anh trai tôi là nhân viên công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (290, 43284, '姉は病院の医者です。', 'あねは びょういんの いしゃ です。', 'Chị gái tôi là bác sĩ ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (291, 43296, 'どこに住んでいますか。', 'どこに すんで いますか。', 'Bạn sống ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (292, 43314, 'すみません、トイレを貸してください。', 'すみません、トイレを かして ください。', 'Xin lỗi, cho tôi mượn nhà vệ sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (293, 43299, 'あした、駅で友達に会います。', 'あした、えきで ともだちに あいます。', 'Ngày mai tôi gặp bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (294, 43301, 'もう一度言ってください。', 'もう いちど いって ください。', 'Hãy nói lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (295, 43303, 'あの先生は若いです。', 'あの せんせいは わかい です。', 'Thầy giáo kia còn trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (296, 43305, '日本の人は親切です。', 'にほんの ひとは しんせつ です。', 'Người Nhật rất tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (297, 43307, '私は虫が嫌いです。', 'わたしは むしが きらい です。', 'Tôi ghét côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (298, 43310, 'あした、うちへ遊びに来てください。', 'あした、うちへ あそびに きて ください。', 'Ngày mai đến nhà tôi chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (299, 43313, '毎晩お風呂に入ります。', 'まいばん おふろに はいります。', 'Tối nào tôi cũng tắm bồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (300, 38885, '学校で地震の避難訓練があった。', 'がっこうで じしんの ひなん くんれんが あった。', 'Ở trường đã có buổi diễn tập sơ tán động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (301, 38903, '京都には古い建築がたくさん残っている。', 'きょうとには ふるい けんちくが たくさん のこって いる。', 'Kyoto còn lưu giữ nhiều công trình kiến trúc cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (302, 38920, '店は学生のアルバイトを二人雇った。', 'みせは がくせいの アルバイトを ふたり やとった。', 'Cửa hàng đã thuê hai sinh viên làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (303, 37990, 'この会社は薬を製造している。', 'この かいしゃは くすりを せいぞう して いる。', 'Công ty này sản xuất thuốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (304, 37992, 'このパンは駅の売店でも販売しています。', 'この パンは えきの ばいてんでも はんばい して います。', 'Loại bánh mì này cũng được bán ở quầy trong ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (305, 37996, '会社が倒産して、父は失業した。', 'かいしゃが とうさん して、ちちは しつぎょう した。', 'Công ty phá sản nên bố tôi bị thất nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (306, 43319, '階段で二階へ行きます。', 'かいだんで にかいへ いきます。', 'Tôi đi cầu thang lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (307, 43320, '机の上に本があります。', 'つくえの うえに ほんが あります。', 'Trên bàn có quyển sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (308, 43329, 'この本は日本語の本です。', 'この ほんは にほんごの ほん です。', 'Cuốn sách này là sách tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (309, 43331, '毎朝、新聞を読みます。', 'まいあさ、しんぶんを よみます。', 'Sáng nào tôi cũng đọc báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (310, 43333, '国の家族に手紙を書きました。', 'くにの かぞくに てがみを かきました。', 'Tôi viết thư cho gia đình ở quê nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (311, 43335, '鉛筆で名前を書いてください。', 'えんぴつで なまえを かいて ください。', 'Hãy viết tên bằng bút chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (312, 43338, 'この傘は誰のですか。', 'この かさは だれの ですか。', 'Chiếc ô này của ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (313, 27226, '六日にパーティーがあります。', 'むいかに パーティーが あります。', 'Ngày mùng sáu có tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (314, 27228, '八日に友達が来ます。', 'ようかに ともだちが きます。', 'Ngày mùng tám bạn tôi sẽ đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (315, 43343, 'この靴はいくらですか。', 'この くつは いくら ですか。', 'Đôi giày này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (316, 27229, '九日に試験があります。', 'ここのかに しけんが あります。', 'Ngày mùng chín có kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (317, 43316, '庭に花があります。', 'にわに はなが あります。', 'Trong vườn có hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (318, 43326, '電話はどこですか。', 'でんわは どこ ですか。', 'Điện thoại ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (319, 43336, 'この紙に名前を書いてください。', 'この かみに なまえを かいて ください。', 'Hãy viết tên vào tờ giấy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (320, 43346, '箱の中に何か物があります。', 'はこの なかに なにか ものが あります。', 'Trong hộp có đồ vật gì đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (321, 43342, '新しい服を買いました。', 'あたらしい ふくを かいました。', 'Tôi đã mua quần áo mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (322, 43340, '財布を忘れました。', 'さいふを わすれました。', 'Tôi quên ví rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (323, 43347, '日曜日に部屋の掃除をします。', 'にちようびに へやの そうじを します。', 'Chủ nhật tôi dọn dẹp phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (324, 43348, '毎朝洗濯をします。', 'まいあさ せんたくを します。', 'Sáng nào tôi cũng giặt đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (325, 43350, 'あしたは五時に起きます。', 'あしたは ごじに おきます。', 'Ngày mai tôi dậy lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (326, 43353, '暗いですから、電気をつけましょう。', 'くらい ですから、でんきを つけましょう。', 'Tối quá, bật đèn lên đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (327, 43355, 'かばんは机の上に置いてください。', 'かばんは つくえの うえに おいて ください。', 'Hãy để cặp lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (328, 43315, '玄関で靴を脱いでください。', 'げんかんで くつを ぬいで ください。', 'Hãy cởi giày ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (329, 43323, '本棚に本がたくさんあります。', 'ほんだなに ほんが たくさん あります。', 'Trên giá sách có rất nhiều sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (330, 28727, '車のキーをなくしました。', 'くるまの キーを なくしました。', 'Tôi làm mất chìa khóa xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (331, 28744, '海外から来ました。', 'かいがいからきました。', 'Tôi đến từ ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (332, 39302, 'この地方は農業が盛んだ。', 'この ちほうは のうぎょうが さかんだ。', 'Vùng này nông nghiệp phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (333, 39308, 'この本はよく売れている。', 'この ほんは よく うれて いる。', 'Cuốn sách này bán rất chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (334, 39345, '彼は貧しい家に生まれた。', 'かれは まずしい いえに うまれた。', 'Anh ấy sinh ra trong một gia đình nghèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (335, 39416, '社長は部下に調査を命じた。', 'しゃちょうは ぶかに ちょうさを めいじた。', 'Giám đốc ra lệnh cho cấp dưới điều tra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (336, 38799, '二学期は九月から始まる。', 'にがっきは くがつから はじまる。', 'Học kỳ hai bắt đầu từ tháng chín.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (337, 38884, '「山」の訓読みは「やま」です。', '「やま」の くんよみは 「やま」 です。', 'Âm kun của chữ 山 là "yama".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (338, 38915, '世界には何千もの言語がある。', 'せかいには なんぜんもの げんごが ある。', 'Trên thế giới có hàng nghìn ngôn ngữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (339, 39110, '高校を出たら、大学に進学するつもりだ。', 'こうこうを でたら、だいがくに しんがく する つもりだ。', 'Học xong cấp ba tôi định lên đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (340, 39272, '名前を書いてから答案を出してください。', 'なまえを かいてから とうあんを だして ください。', 'Ghi tên rồi hãy nộp bài thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (341, 39284, 'この漢字の読みがわかりません。', 'この かんじの よみが わかりません。', 'Tôi không biết cách đọc chữ Hán này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (342, 37749, '三番の窓口でお待ちください。', 'さんばんの まどぐちで おまち ください。', 'Xin vui lòng chờ ở quầy số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (343, 43375, '私は肉より魚が好きです。', 'わたしは にくより さかなが すき です。', 'Tôi thích cá hơn thịt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (344, 43377, 'どんな果物が好きですか。', 'どんな くだものが すき ですか。', 'Bạn thích loại trái cây nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (345, 43380, '毎朝、牛乳を飲みます。', 'まいあさ、ぎゅうにゅうを のみます。', 'Sáng nào tôi cũng uống sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (346, 43381, '水をください。', 'みずを ください。', 'Cho tôi xin nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (347, 43384, 'コーヒーを飲みませんか。', 'コーヒーを のみませんか。', 'Uống cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (348, 43379, '朝ごはんにパンを食べます。', 'あさごはんに パンを たべます。', 'Bữa sáng tôi ăn bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (349, 43356, 'このペンを使ってもいいですか。', 'この ペンを つかっても いい ですか。', 'Tôi dùng cây bút này được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (350, 43358, '朝、シャワーを浴びます。', 'あさ、シャワーを あびます。', 'Buổi sáng tôi tắm vòi sen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (351, 43360, '部屋に入る前に靴を脱ぎます。', 'へやに はいる まえに くつを ぬぎます。', 'Trước khi vào phòng tôi cởi giày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (352, 43362, '私の部屋は狭いです。', 'わたしの へやは せまい です。', 'Phòng của tôi hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (353, 43364, '外はもう暗いです。', 'そとは もう くらい です。', 'Bên ngoài đã tối rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (354, 43366, 'この町には古いお寺があります。', 'この まちには ふるい おてらが あります。', 'Thị trấn này có một ngôi chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (355, 43368, 'この部屋は汚いです。掃除しましょう。', 'この へやは きたない です。そうじ しましょう。', 'Phòng này bẩn quá. Dọn dẹp thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (356, 43371, '一緒に昼ご飯を食べましょう。', 'いっしょに ひるごはんを たべましょう。', 'Cùng ăn trưa nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (357, 43383, 'お酒はあまり飲みません。', 'おさけは あまり のみません。', 'Tôi không uống rượu nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (358, 43385, '日本のお菓子はおいしいです。', 'にほんの おかしは おいしい です。', 'Bánh kẹo Nhật ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (359, 29182, 'ある日、駅で昔の友達に会いました。', 'ある ひ、えきで むかしの ともだちに あいました。', 'Một ngày nọ, tôi gặp người bạn cũ ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (360, 30673, '旅行の準備はもう終わりましたか。', 'りょこうの じゅんびは もう おわりましたか。', 'Bạn đã chuẩn bị xong cho chuyến du lịch chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (361, 30674, '毎日努力した結果、試験に合格できました。', 'まいにち どりょくした けっか、しけんに ごうかく できました。', 'Nhờ nỗ lực mỗi ngày mà tôi đã thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (362, 29660, 'あの方は木村さんです。', 'あの かたは きむらさん です。', 'Vị kia là chị Kimura.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (363, 27231, '二月十四日はバレンタインデーです。', 'にがつ じゅうよっかは バレンタインデー です。', 'Ngày 14 tháng 2 là lễ Tình nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (364, 43412, '好きな色を一つ選んでください。', 'すきな いろを ひとつ えらんで ください。', 'Hãy chọn một màu bạn thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (365, 38927, '旅行先の候補がいくつかある。', 'りょこうさきの こうほが いくつか ある。', 'Có vài địa điểm đang được cân nhắc cho chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (408, 43438, '答えを書いてください。', 'こたえを かいて ください。', 'Hãy viết câu trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (366, 37782, '駅前で学生たちが募金をしていた。', 'えきまえで がくせいたちが ぼきんを して いた。', 'Các bạn sinh viên đang quyên góp trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (367, 38948, '国家の将来を考える。', 'こっかの しょうらいを かんがえる。', 'Suy nghĩ về tương lai của quốc gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (368, 38950, 'バスで国境を越えた。', 'バスで こっきょうを こえた。', 'Chúng tôi vượt biên giới bằng xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (369, 27009, '私たちは学生です。', 'わたしたちはがくせいです。', 'Chúng tôi là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (370, 26969, 'あなたは学生です。', 'あなたはがくせいです。', 'Anh là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (371, 38000, '二つの国が貿易の協定を結んだ。', 'ふたつの くにが ぼうえきの きょうていを むすんだ。', 'Hai nước đã ký hiệp định thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (372, 39124, '会社に新しい休暇の制度ができた。', 'かいしゃに あたらしい きゅうかの せいどが できた。', 'Công ty đã có chế độ nghỉ phép mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (373, 39167, '父の家を兄が相続した。', 'ちちの いえを あにが そうぞく した。', 'Anh tôi được thừa kế ngôi nhà của bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (374, 39197, '新しい大臣が記者会見を開いた。', 'あたらしい だいじんが きしゃかいけんを ひらいた。', 'Tân bộ trưởng đã tổ chức họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (375, 39216, '県の知事が被災地を訪れた。', 'けんの ちじが ひさいちを おとずれた。', 'Tỉnh trưởng đã đến thăm vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (376, 43393, '昼ごはんは食堂で食べます。', 'ひるごはんは しょくどうで たべます。', 'Tôi ăn trưa ở nhà ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (377, 43394, '駅の前に喫茶店があります。', 'えきの まえに きっさてんが あります。', 'Trước ga có một quán cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (378, 43389, 'テーブルに皿を並べてください。', 'テーブルに さらを ならべて ください。', 'Hãy xếp đĩa lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (379, 43400, 'この店は値段が安いです。', 'この みせは ねだんが やすい です。', 'Cửa hàng này giá rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (380, 43402, 'ケーキを一つください。', 'ケーキを ひとつ ください。', 'Cho tôi một cái bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (381, 43391, 'この店は何時までですか。', 'この みせは なんじまで ですか。', 'Cửa hàng này mở đến mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (382, 43405, '宿題を全部やりました。', 'しゅくだいを ぜんぶ やりました。', 'Tôi đã làm hết bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (383, 43407, '水をたくさん飲んでください。', 'みずを たくさん のんで ください。', 'Hãy uống nhiều nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (384, 43409, '駅で新聞を買います。', 'えきで しんぶんを かいます。', 'Tôi mua báo ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (385, 43411, 'レジでお金を払います。', 'レジで おかねを はらいます。', 'Tôi trả tiền ở quầy thu ngân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (386, 43414, 'このケーキはおいしいです。', 'この ケーキは おいしい です。', 'Chiếc bánh này ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (387, 43415, 'この料理はまずいです。', 'この りょうりは まずい です。', 'Món này dở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (388, 29202, 'はあ、そうですか。', 'はあ、そう ですか。', 'À, vậy à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (389, 29227, '日本へ来た目的は何ですか。', 'にほんへ きた もくてきは なん ですか。', 'Mục đích đến Nhật của bạn là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (390, 29231, 'やかんでお湯を沸かします。', 'やかんで おゆを わかします。', 'Tôi đun nước bằng ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (391, 29235, '非常袋に缶詰を入れておきます。', 'ひじょうぶくろに かんづめを いれて おきます。', 'Tôi để sẵn đồ hộp trong túi khẩn cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (392, 30727, '大学を卒業したら、銀行に就職したいです。', 'だいがくを そつぎょう したら、ぎんこうに しゅうしょく したいです。', 'Tốt nghiệp đại học xong tôi muốn vào làm ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (393, 30728, '明日、会社の面接を受けます。', 'あした、かいしゃの めんせつを うけます。', 'Ngày mai tôi đi phỏng vấn ở công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (394, 39265, '彼は新しい党を作った。', 'かれは あたらしい とうを つくった。', 'Ông ấy đã lập một đảng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (395, 39283, '兄は会社をやめて独立した。', 'あには かいしゃを やめて どくりつ した。', 'Anh tôi nghỉ việc ở công ty để tự lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (396, 39323, 'この町は犯罪が少ない。', 'この まちは はんざいが すくない。', 'Thị trấn này ít tội phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (397, 39351, '試験で不正をしてはいけない。', 'しけんで ふせいを しては いけない。', 'Không được gian lận trong thi cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (398, 39375, 'エジプトには古い文明があった。', 'エジプトには ふるい ぶんめいが あった。', 'Ai Cập từng có một nền văn minh cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (399, 38705, 'ライターでろうそくに火をつけた。', 'ライターで ろうそくに ひを つけた。', 'Tôi dùng bật lửa thắp nến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (400, 29225, '二度と戦争を起こしてはいけない。', 'にどと せんそうを おこしては いけない。', 'Không bao giờ được để chiến tranh xảy ra lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (401, 29226, '世界の平和を願っています。', 'せかいの へいわを ねがって います。', 'Tôi mong thế giới hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (402, 43427, 'ごちそうさま。とてもおいしかった。', 'ごちそうさま。とても おいしかった。', 'Cảm ơn vì bữa ăn, ngon lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (403, 43428, 'このかばんはいくらですか。', 'この かばんは いくら ですか。', 'Chiếc cặp này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (404, 43434, '今晩、宿題をします。', 'こんばん、しゅくだいを します。', 'Tối nay tôi làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (405, 43443, 'ミラーさんは英語の先生です。', 'ミラーさんは えいごの せんせい です。', 'Anh Miller là giáo viên tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (406, 43445, '漢字は難しいですが、おもしろいです。', 'かんじは むずかしい ですが、おもしろい です。', 'Chữ Hán khó nhưng thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (407, 43437, 'この問題は難しいです。', 'この もんだいは むずかしい です。', 'Câu hỏi này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (410, 43420, 'このお茶は熱いです。', 'この おちゃは あつい です。', 'Trà này nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (411, 43422, '東京は人が多いです。', 'とうきょうは ひとが おおい です。', 'Tokyo đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (412, 43424, 'お腹が痛いです。', 'おなかが いたい です。', 'Tôi đau bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (413, 43426, 'では、いただきます。', 'では、いただきます。', 'Vậy, xin mời mọi người ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (414, 43429, '毎日、歩いて学校へ行きます。', 'まいにち、あるいて がっこうへ いきます。', 'Ngày nào tôi cũng đi bộ đến trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (415, 43432, '図書館で本を借りました。', 'としょかんで ほんを かりました。', 'Tôi đã mượn sách ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (416, 43439, '質問がありますか。', 'しつもんが ありますか。', 'Có câu hỏi nào không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (417, 43444, 'この言葉は難しいです。', 'この ことばは むずかしい です。', 'Từ này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (418, 28715, 'なべに水を入れて、火にかけます。', 'なべに みずを いれて、ひに かけます。', 'Cho nước vào nồi rồi bắc lên bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (419, 29301, 'ガソリンの値段が上がりました。', 'ガソリンの ねだんが あがりました。', 'Giá xăng đã tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (420, 43446, '次の文を日本語に訳しなさい。', 'つぎの ぶんを にほんごに やくしなさい。', 'Hãy dịch câu sau sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (421, 39202, '明日、お宅に伺ってもよろしいですか。', 'あした、おたくに うかがっても よろしい ですか。', 'Ngày mai tôi đến nhà anh được không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (422, 39322, '板を切って本棚を作った。', 'いたを きって ほんだなを つくった。', 'Tôi cưa ván để đóng giá sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (423, 39376, '猫が塀の上を歩いている。', 'ねこが へいの うえを あるいて いる。', 'Con mèo đang đi trên bờ tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (424, 39388, '母から大きな包みが届いた。', 'ははから おおきな つつみが とどいた。', 'Tôi nhận được một gói hàng lớn từ mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (425, 29263, 'このりんごは厚いです。', 'このりんごはあついです。', 'Quả táo này dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (426, 29264, 'このりんごは薄いです。', 'このりんごはうすいです。', 'Quả táo này mỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (427, 29293, 'ガソリンがなくなります。', 'ガソリンがなくなります。', 'Mất, hết (xăng)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (428, 29295, 'ここは幸せです。', 'ここはしあわせです。', 'Ở đây hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (429, 29298, 'このりんごはまずいです。', 'このりんごはまずいです。', 'Quả táo này dở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (430, 29299, 'このりんごはつまらないです。', 'このりんごはつまらないです。', 'Quả táo này buồn tẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (431, 39399, '棒で高いところの柿を取った。', 'ぼうで たかい ところの かきを とった。', 'Tôi dùng gậy hái quả hồng trên cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (432, 39422, '寒いので、毛布をもう一枚かけた。', 'さむいので、もうふを もう いちまい かけた。', 'Lạnh quá nên tôi đắp thêm một chiếc chăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (433, 42879, '台所のパイプから水が漏れている。', 'だいどころの パイプから みずが もれて いる。', 'Ống nước trong bếp đang bị rò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (434, 38953, 'この地方では穀物がよく育つ。', 'この ちほうでは こくもつが よく そだつ。', 'Ngũ cốc phát triển tốt ở vùng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (435, 39273, '豆を煮て、スープを作った。', 'まめを にて、スープを つくった。', 'Tôi ninh đậu để nấu súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (436, 39324, '飯でも食いに行こうか。', 'めしでも くいに いこうか。', 'Đi ăn cơm không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (437, 39372, '粉に水を入れて、よく混ぜてください。', 'こなに みずを いれて、よく まぜて ください。', 'Cho nước vào bột rồi trộn đều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (438, 42874, 'パンにチーズをのせて焼いた。', 'パンに チーズを のせて やいた。', 'Tôi đặt phô mai lên bánh mì rồi nướng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (439, 37766, '台風で物資の輸送が遅れている。', 'たいふうで ぶっしの ゆそうが おくれて いる。', 'Do bão, việc vận chuyển hàng hóa bị chậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (440, 38918, 'お正月には故郷に帰る。', 'おしょうがつには こきょうに かえる。', 'Tết tôi về quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (441, 27248, '新幹線で博多へ行きます。', 'しんかんせんで はかたへ いきます。', 'Tôi đi Hakata bằng tàu Shinkansen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (442, 43458, 'パソコンでレポートを書きます。', 'パソコンで レポートを かきます。', 'Tôi viết báo cáo bằng máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (443, 43451, '父の会社は大阪にあります。', 'ちちの かいしゃは おおさかに あります。', 'Công ty của bố tôi ở Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (444, 43450, 'ペンで名前を書いてください。', 'ペンで なまえを かいて ください。', 'Hãy viết tên bằng bút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (445, 43470, 'わからない時は先生に聞きます。', 'わからない ときは せんせいに ききます。', 'Khi không hiểu tôi hỏi thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (446, 43472, '授業は九時に始まります。', 'じゅぎょうは くじに はじまります。', 'Giờ học bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (447, 43474, '兄は銀行で働いています。', 'あには ぎんこうで はたらいて います。', 'Anh tôi làm việc ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (448, 26994, 'こちらは田中さんです。', 'こちらはたなかさんです。', 'Đây là anh/chị Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (449, 26995, 'アメリカから来ました。', 'アメリカからきました。', 'Tôi đến từ Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (450, 30710, 'お客様に失礼な態度をとってはいけません。', 'おきゃくさまに しつれいな たいどを とっては いけません。', 'Không được có thái độ thất lễ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (451, 26996, 'イギリスから来ました。', 'イギリスからきました。', 'Tôi đến từ Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (452, 30712, '今日は気分がいいので、散歩に行きます。', 'きょうは きぶんが いいので、さんぽに いきます。', 'Hôm nay tâm trạng tốt nên tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (453, 38968, '座席を倒してもいいですか。', 'ざせきを たおしても いい ですか。', 'Tôi ngả ghế ra sau được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (454, 39218, 'この地区には古いお寺が多い。', 'この ちくには ふるい おてらが おおい。', 'Khu vực này có nhiều chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (455, 26982, '大学へ行きます。', 'だいがくへいきます。', 'Tôi đi đến trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (456, 26990, 'ベトナムから来ました。', 'ベトナムからきました。', 'Tôi đến từ Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (457, 26997, 'インドから来ました。', 'インドからきました。', 'Tôi đến từ Ấn Độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (458, 27004, 'サントスさんはブラジル人です。', 'サントスさんは ブラジルじん です。', 'Anh Santos là người Brazil.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (459, 26998, 'インドネシアから来ました。', 'インドネシアからきました。', 'Tôi đến từ Indonesia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (460, 39253, 'この町に初めて鉄道が通った。', 'この まちに はじめて てつどうが とおった。', 'Lần đầu tiên đường sắt chạy qua thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (461, 39280, '雪で道路が凍っている。', 'ゆきで どうろが こおって いる。', 'Tuyết làm đường bị đóng băng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (462, 39331, '飛行中はシートベルトを締めてください。', 'ひこうちゅうは シートベルトを しめて ください。', 'Trong khi bay xin thắt dây an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (463, 39394, '駅はどちらの方向ですか。', 'えきは どちらの ほうこう ですか。', 'Ga ở hướng nào vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (464, 42882, '引っ越しの荷物をバンで運んだ。', 'ひっこしの にもつを バンで はこんだ。', 'Tôi chở đồ chuyển nhà bằng xe van.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (465, 31525, '歯を磨くときは水を止めて節水しよう。', 'はを みがく ときは みずを とめて せっすい しよう。', 'Khi đánh răng hãy khóa vòi để tiết kiệm nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (466, 31528, '都会は大気の汚れがひどい。', 'とかいは たいきの よごれが ひどい。', 'Ở thành phố, ô nhiễm không khí rất nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (467, 31530, '海にはたくさんの生物がすんでいる。', 'うみには たくさんの せいぶつが すんで いる。', 'Biển là nơi sinh sống của rất nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (468, 31532, 'けがをした鳥を保護した。', 'けがを した とりを ほご した。', 'Tôi đã đem con chim bị thương về chăm sóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (469, 31538, '水をやらなかったので、花が枯れてしまった。', 'みずを やらなかったので、はなが かれて しまった。', 'Không tưới nước nên hoa đã héo mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (470, 38907, '子供たちが原っぱで走り回っている。', 'こどもたちが はらっぱで はしりまわって いる。', 'Lũ trẻ đang chạy nhảy trên bãi cỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (471, 38944, '台所からいい香りがする。', 'だいどころから いい かおりが する。', 'Trong bếp tỏa ra mùi thơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (472, 39019, '芝生に入らないでください。', 'しばふに はいらないで ください。', 'Xin đừng giẫm lên bãi cỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (473, 26991, 'アメリカから来ました。どうぞよろしくお願いします。', 'アメリカから きました。どうぞ よろしく おねがい します。', 'Tôi đến từ Mỹ. Rất mong được giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (474, 43476, '宿題を出してください。', 'しゅくだいを だして ください。', 'Hãy nộp bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (475, 27306, 'これは日本語のCDです。', 'これは にほんごの シーディー です。', 'Đây là đĩa CD tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (476, 30714, '朝晩は少し寒さを感じるようになりました。', 'あさばんは すこし さむさを かんじる ように なりました。', 'Sáng tối đã bắt đầu thấy hơi lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (477, 30717, '十年後の自分を想像してみてください。', 'じゅうねんごの じぶんを そうぞう して みて ください。', 'Hãy thử tưởng tượng bản thân mười năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (478, 30719, 'どちらがいいか、自分で判断してください。', 'どちらが いいか、じぶんで はんだん して ください。', 'Hãy tự phán đoán xem cái nào tốt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (479, 30750, 'この件は私に任せてください。', 'この けんは わたしに まかせて ください。', 'Việc này cứ giao cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (480, 30751, '彼はやっと自分の間違いを認めた。', 'かれは やっと じぶんの まちがいを みとめた。', 'Cuối cùng anh ấy cũng thừa nhận sai lầm của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (481, 30822, '申し込みの締め切りは明日です。', 'もうしこみの しめきりは あした です。', 'Hạn chót đăng ký là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (482, 30796, 'コンビニでアルバイトを募集している。', 'コンビニで アルバイトを ぼしゅう して いる。', 'Cửa hàng tiện lợi đang tuyển người làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (483, 30798, 'ビザの手続きに一か月かかった。', 'ビザの てつづきに いっかげつ かかった。', 'Thủ tục visa mất một tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (484, 39201, 'アフリカ大陸を旅してみたい。', 'アフリカ たいりくを たびして みたい。', 'Tôi muốn thử du lịch châu Phi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (485, 39230, 'このホテルの部屋は眺めがいい。', 'この ホテルの へやは ながめが いい。', 'Phòng khách sạn này có tầm nhìn đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (486, 39252, '鉄は熱いうちに打て。', 'てつは あつい うちに うて。', 'Rèn sắt khi còn nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (487, 39255, '天候が悪いため、飛行機が遅れている。', 'てんこうが わるい ため、ひこうきが おくれて いる。', 'Do thời tiết xấu, máy bay bị trễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (488, 39258, '学校で兎を飼っている。', 'がっこうで うさぎを かって いる。', 'Trường tôi có nuôi thỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (489, 39266, '寒さで池の水が凍った。', 'さむさで いけの みずが こおった。', 'Trời lạnh làm nước ao đóng băng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (490, 39313, '祖母は畑で野菜を作っている。', 'そぼは はたけで やさいを つくって いる。', 'Bà tôi trồng rau ngoài ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (491, 39363, '窓から見える風景がとてもきれいだ。', 'まどから みえる ふうけいが とても きれいだ。', 'Phong cảnh nhìn từ cửa sổ rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (492, 39412, '霧で前がよく見えない。', 'きりで まえが よく みえない。', 'Sương mù dày nên không nhìn rõ phía trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (493, 39428, '野に咲く花が好きだ。', 'のに さく はなが すきだ。', 'Tôi thích những bông hoa nở ngoài đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (494, 39458, '鳥が大きな翼を広げて飛んでいった。', 'とりが おおきな つばさを ひろげて とんで いった。', 'Con chim dang rộng đôi cánh bay đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (495, 38912, '現代の若者はスマホなしでは生活できない。', 'げんだいの わかものは スマホ なしでは せいかつ できない。', 'Giới trẻ ngày nay không thể sống thiếu điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (496, 38970, '最終電車に間に合わなかった。', 'さいしゅう でんしゃに まにあわなかった。', 'Tôi không kịp chuyến tàu cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (497, 38973, 'お降りの際は、足元にご注意ください。', 'おおりの さいは、あしもとに ごちゅうい ください。', 'Khi xuống xe, xin chú ý bước chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (498, 38047, '現在、東京に住んでいます。', 'げんざい、とうきょうに すんで います。', 'Hiện tại tôi đang sống ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (499, 39245, '車を定期的に点検している。', 'くるまを ていきてきに てんけん して いる。', 'Tôi kiểm tra xe định kỳ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (500, 39278, '二人は同時に手を挙げた。', 'ふたりは どうじに てを あげた。', 'Hai người giơ tay cùng một lúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (501, 39289, '日中はまだ暑いが、夜は涼しい。', 'にっちゅうは まだ あついが、よるは すずしい。', 'Ban ngày vẫn còn nóng nhưng đêm thì mát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (502, 39295, 'この町には年間百万人の観光客が来る。', 'この まちには ねんかん ひゃくまんにんの かんこうきゃくが くる。', 'Mỗi năm thị trấn này đón một triệu khách du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (503, 44051, '給料は毎月二十五日にもらいます。', 'きゅうりょうは まいつき にじゅうごにちに もらいます。', 'Tôi nhận lương vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (504, 26980, '私は医者です。', 'わたしはいしゃです。', 'Tôi là bác sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (505, 26981, '私は研究者です。', 'わたしはけんきゅうしゃです。', 'Tôi là nghiên cứu sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (506, 27010, '皆さん、おはようございます。', 'みなさん、おはよう ございます。', 'Chào buổi sáng mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (507, 30889, '実は、来月会社を辞めるんです。', 'じつは、らいげつ かいしゃを やめるんです。', 'Thật ra là tháng sau tôi sẽ nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (508, 43453, '午後二時から会議があります。', 'ごご にじから かいぎが あります。', 'Từ hai giờ chiều có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (509, 27151, '午後二時から会議があります。', 'ごご にじから かいぎが あります。', 'Từ hai giờ chiều có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (510, 43477, 'ペンを貸してください。', 'ペンを かして ください。', 'Cho tôi mượn cây bút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (511, 27011, '山田君は親切です。', 'やまだくんはしんせつです。', 'Cậu Yamada rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (512, 44207, '日本料理の中で、特にすしが好きです。', 'にほんりょうりの なかで、とくに すしが すきです。', 'Trong các món Nhật, tôi đặc biệt thích sushi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (513, 46164, 'この町は観光で大きく発展した。', 'この まちは かんこうで おおきく はってん した。', 'Thị trấn này phát triển mạnh nhờ du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (514, 43989, '今日は気分がいいので、散歩に行きます。', 'きょうは きぶんが いいので、さんぽに いきます。', 'Hôm nay tâm trạng tốt nên tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (515, 27079, 'まず一階の受付で名前を言ってください。', 'まず いっかいの うけつけで なまえを いって ください。', 'Trước tiên hãy báo tên ở quầy lễ tân tầng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (516, 44034, '上司に休みを取ってもいいか聞いた。', 'じょうしに やすみを とっても いいか きいた。', 'Tôi hỏi cấp trên xem có được nghỉ phép không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (517, 44035, '部長は部下にとても優しい。', 'ぶちょうは ぶかに とても やさしい。', 'Trưởng phòng rất tử tế với cấp dưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (518, 44038, 'まず一階の受付で名前を言ってください。', 'まず いっかいの うけつけで なまえを いって ください。', 'Trước tiên hãy báo tên ở quầy lễ tân tầng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (519, 39299, 'あの店は年中無休です。', 'あの みせは ねんじゅう むきゅう です。', 'Cửa hàng đó mở cửa quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (520, 39386, '年の暮れはいつも忙しい。', 'としの くれは いつも いそがしい。', 'Cuối năm lúc nào cũng bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (521, 39419, '明後日、改めてご連絡いたします。', 'みょうごにち、あらためて ごれんらく いたします。', 'Ngày kia tôi sẽ liên lạc lại với quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (522, 39426, '夜中に電話が鳴って、目が覚めた。', 'よなかに でんわが なって、めが さめた。', 'Nửa đêm điện thoại reo làm tôi tỉnh giấc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (523, 39451, '今日は何曜日ですか。', 'きょうは なんようび ですか。', 'Hôm nay là thứ mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (524, 31536, '甘い物を減らすようにしている。', 'あまい ものを へらす ように して いる。', 'Tôi đang cố giảm đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (525, 38965, '二人の点数の差はわずか一点だった。', 'ふたりの てんすうの さは わずか いってん だった。', 'Điểm của hai người chỉ chênh nhau một điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (526, 39012, '朝七時に起きます。', 'あさ しちじに おきます。', 'Tôi dậy lúc bảy giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (527, 39118, '参加者の数を数えてください。', 'さんかしゃの かずを かぞえて ください。', 'Hãy đếm số người tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (528, 39170, '雨で川の水かさが増している。', 'あめで かわの みずかさが まして いる。', 'Mưa làm mực nước sông dâng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (529, 39171, '誕生日に花の束をもらった。', 'たんじょうびに はなの たばを もらった。', 'Sinh nhật tôi được tặng một bó hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (530, 39200, '宿題の大部分は終わった。', 'しゅくだいの だいぶぶんは おわった。', 'Phần lớn bài tập đã làm xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (531, 44104, '出かける前にガスを止めてください。', 'でかける まえに ガスを とめて ください。', 'Trước khi ra ngoài hãy khóa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (532, 26971, '田中さんは先生です。', 'たなかさんはせんせいです。', 'Anh/chị Tanaka là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (534, 26973, '私はベトナム人です。', 'わたしはベトナムじんです。', 'Tôi là người Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (535, 26974, 'あの方は先生です。', 'あのかたはせんせいです。', 'Người kia là thầy/cô giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (536, 26975, '私は教師です。', 'わたしはきょうしです。', 'Tôi là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (537, 26976, '私は学生です。', 'わたしはがくせいです。', 'Tôi là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (538, 26977, '私は会社員です。', 'わたしはかいしゃいんです。', 'Tôi là nhân viên công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (539, 26978, '私はトヨタの社員です。', 'わたしはトヨタのしゃいんです。', 'Tôi là Nhân viên công ty Toyota.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (540, 26979, '私は銀行員です。', 'わたしはぎんこういんです。', 'Tôi là nhân viên ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (541, 39320, '三月の半ばに桜が咲き始めた。', 'さんがつの なかばに さくらが さきはじめた。', 'Giữa tháng ba hoa anh đào bắt đầu nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (542, 39397, 'この店はメニューが豊富だ。', 'この みせは メニューが ほうふだ。', 'Quán này có thực đơn phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (543, 42864, '駅から家まで二キロある。', 'えきから いえまで にキロ ある。', 'Từ ga về nhà là hai cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (544, 42884, 'この経験は将来きっとプラスになる。', 'この けいけんは しょうらい きっと プラスに なる。', 'Kinh nghiệm này chắc chắn sẽ có ích về sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (545, 38758, 'お客様の要望に応じて、料理を作ります。', 'おきゃくさまの ようぼうに おうじて、りょうりを つくります。', 'Chúng tôi nấu món ăn theo yêu cầu của khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (546, 38793, '地図を拡大して見た。', 'ちずを かくだい して みた。', 'Tôi phóng to bản đồ ra để xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (547, 38889, '二人は手を繋いで歩いている。', 'ふたりは てを つないで あるいて いる。', 'Hai người nắm tay nhau đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (548, 38910, '雲の間から月が現れた。', 'くもの あいだから つきが あらわれた。', 'Mặt trăng hiện ra giữa những đám mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (549, 38930, '名前を呼ばれて、後ろを向いた。', 'なまえを よばれて、うしろを むいた。', 'Bị gọi tên, tôi quay lại phía sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (550, 37998, '言葉より行動が大切だ。', 'ことばより こうどうが たいせつだ。', 'Hành động quan trọng hơn lời nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (551, 39013, '事故で彼は自信を失った。', 'じこで かれは じしんを うしなった。', 'Sau tai nạn, anh ấy mất hết tự tin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (552, 39024, 'シャツのボタンが取れてしまった。', 'シャツの ボタンが とれて しまった。', 'Cúc áo sơ mi bị tuột mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (553, 39111, '寒くて体が震えた。', 'さむくて からだが ふるえた。', 'Lạnh quá nên người run lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (554, 39164, '足を組んで座るのはよくない。', 'あしを くんで すわるのは よくない。', 'Ngồi vắt chéo chân là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (555, 39203, '誰かがドアを叩いている。', 'だれかが ドアを たたいて いる。', 'Có ai đó đang gõ cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (556, 39205, '泥棒にかばんを奪われた。', 'どろぼうに かばんを うばわれた。', 'Tôi bị tên trộm giật mất túi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (557, 39236, '太陽が海に沈んでいく。', 'たいようが うみに しずんで いく。', 'Mặt trời đang lặn xuống biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (558, 27747, 'さあ、始めましょう。', 'さあ、はじめましょう。', 'Nào, bắt đầu thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (559, 43479, '図書館に本を返します。', 'としょかんに ほんを かえします。', 'Tôi trả sách cho thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (560, 44114, 'このスープは味が薄いです。', 'この スープは あじが うすい です。', 'Món súp này nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (561, 27014, 'フランスから来ました。', 'フランスからきました。', 'Tôi đến từ Pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (562, 26999, '韓国から来ました。', 'かんこくからきました。', 'Tôi đến từ Hàn quốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (563, 27001, '中国から来ました。', 'ちゅうごくからきました。', 'Tôi đến từ Trung Quốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (564, 27003, '日本から来ました。', 'にほんからきました。', 'Tôi đến từ Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (565, 27005, 'IMC／パワー電気／ブラジルエアーへ行きます。', 'IMC／パワーでんき／ブラジルエアーへいきます。', 'Tôi đi đến công ty giả định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (566, 27000, 'タイから来ました。', 'タイからきました。', 'Tôi đến từ Thái Lan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (567, 44043, '友達と三時に会う約束があります。', 'ともだちと さんじに あう やくそくが あります。', 'Tôi có hẹn gặp bạn lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (568, 39239, '英語が通じなくて困った。', 'えいごが つうじなくて こまった。', 'Nói tiếng Anh không ai hiểu nên tôi gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (569, 39249, 'この土地は米作りに適している。', 'この とちは こめづくりに てきして いる。', 'Vùng đất này thích hợp để trồng lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (570, 39251, '子供が川で溺れそうになった。', 'こどもが かわで おぼれそうに なった。', 'Đứa trẻ suýt chết đuối dưới sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (571, 39270, '私が何歳か当ててみて。', 'わたしが なんさいか あてて みて。', 'Thử đoán xem tôi bao nhiêu tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (572, 39304, '約束を破ってはいけない。', 'やくそくを やぶっては いけない。', 'Không được thất hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (573, 39310, '工場でガスの爆発事故があった。', 'こうじょうで ガスの ばくはつ じこが あった。', 'Đã xảy ra vụ nổ khí gas ở nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (574, 39319, '最近、髪の毛がよく抜ける。', 'さいきん、かみのけが よく ぬける。', 'Dạo này tóc tôi rụng nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (575, 39332, '地震に備えて、水を買っておいた。', 'じしんに そなえて、みずを かって おいた。', 'Tôi mua sẵn nước để phòng động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (576, 39366, '山は雪に覆われている。', 'やまは ゆきに おおわれて いる。', 'Ngọn núi bị tuyết phủ kín.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (577, 39391, '彼は大きな荷物を抱えて歩いていた。', 'かれは おおきな にもつを かかえて あるいて いた。', 'Anh ấy ôm một kiện hàng lớn đi bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (578, 39448, 'この映画は多くの人に感動を与えた。', 'この えいがは おおくの ひとに かんどうを あたえた。', 'Bộ phim này đã mang lại xúc động cho nhiều người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (579, 39453, 'この実験には特別な機械を用いる。', 'この じっけんには とくべつな きかいを もちいる。', 'Thí nghiệm này sử dụng một loại máy đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (580, 38752, 'この包丁はとても鋭いので気をつけて。', 'この ほうちょうは とても するどいので きを つけて。', 'Con dao này rất sắc, cẩn thận nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (581, 38904, '彼は見事に試験に合格した。', 'かれは みごとに しけんに ごうかく した。', 'Anh ấy đã thi đỗ một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (582, 39022, '主要な駅には特急が止まる。', 'しゅような えきには とっきゅうが とまる。', 'Tàu tốc hành dừng ở các ga chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (583, 39045, '明日、重要な会議があります。', 'あした、じゅうような かいぎが あります。', 'Ngày mai có một cuộc họp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (584, 39081, 'これは上等な牛肉だ。', 'これは じょうとうな ぎゅうにくだ。', 'Đây là thịt bò hảo hạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (585, 39162, '食べ物を粗末にしてはいけない。', 'たべものを そまつに しては いけない。', 'Không được lãng phí đồ ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (586, 27006, 'ワンさんはAKCの研究者です。', 'ワンさんは エーケーシーの けんきゅうしゃ です。', 'Anh Wang là nhà nghiên cứu ở AKC.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (587, 27007, '神戸病院へ行きます。', 'こうべびょういんへいきます。', 'Tôi đi đến bệnh viện giả định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (588, 27008, 'さくら大学／富士大学へ行きます。', 'さくらだいがく／ふじだいがくへいきます。', 'Tôi đi đến trường đại học giả định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (589, 27012, '私はエンジニアです。', 'わたしはエンジニアです。', 'Tôi là kỹ sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (590, 44044, '遅れるときは、必ず連絡してください。', 'おくれる ときは、かならず れんらく して ください。', 'Khi đến muộn, nhất định phải liên lạc nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (591, 44047, '旅行の準備はもう終わりましたか。', 'りょこうの じゅんびは もう おわりましたか。', 'Bạn đã chuẩn bị xong cho chuyến du lịch chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (592, 44053, '会議の資料をコピーしておいてください。', 'かいぎの しりょうを コピー して おいて ください。', 'Hãy photo sẵn tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (593, 44054, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (594, 44071, '夏休みにどこへ行くか、まだ決めていません。', 'なつやすみに どこへ いくか、まだ きめて いません。', 'Tôi vẫn chưa quyết định nghỉ hè sẽ đi đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (595, 27455, '友達と三時に会う約束があります。', 'ともだちと さんじに あう やくそくが あります。', 'Tôi có hẹn gặp bạn lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (596, 39334, 'この味はちょっと微妙だね。', 'この あじは ちょっと びみょうだね。', 'Vị này hơi khó nói nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (597, 39349, '昨日、不思議な夢を見た。', 'きのう、ふしぎな ゆめを みた。', 'Hôm qua tôi gặp một giấc mơ kỳ lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (598, 39353, '経験がないと、就職に不利だ。', 'けいけんが ないと、しゅうしょくに ふりだ。', 'Không có kinh nghiệm thì bất lợi khi xin việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (599, 39396, 'この国は自然が豊かだ。', 'この くには しぜんが ゆたかだ。', 'Đất nước này có thiên nhiên phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (600, 39429, '厄介な問題が起きてしまった。', 'やっかいな もんだいが おきて しまった。', 'Một vấn đề rắc rối đã xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (601, 39434, '彼女はクラスで一番優秀な学生だ。', 'かのじょは クラスで いちばん ゆうしゅうな がくせいだ。', 'Cô ấy là học sinh ưu tú nhất lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (602, 39441, '有能な人が会社に入ってきた。', 'ゆうのうな ひとが かいしゃに はいって きた。', 'Một người tài giỏi đã vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (603, 39452, '世界には様々な文化がある。', 'せかいには さまざまな ぶんかが ある。', 'Thế giới có nhiều nền văn hóa đa dạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (604, 38755, '彼のピアノの演奏はすばらしかった。', 'かれの ピアノの えんそうは すばらしかった。', 'Màn trình diễn piano của anh ấy thật tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (605, 38943, '食事中は行儀よくしなさい。', 'しょくじちゅうは ぎょうぎ よく しなさい。', 'Khi ăn phải giữ phép tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (606, 39018, '彼の涙は芝居だった。', 'かれの なみだは しばい だった。', 'Nước mắt của anh ta chỉ là diễn kịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (607, 43483, 'あした暇ですか。', 'あした ひま ですか。', 'Ngày mai bạn rảnh không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (608, 43489, '今、何時ですか。', 'いま、なんじ ですか。', 'Bây giờ là mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (609, 27013, 'これは電気の会社です。', 'これは でんきの かいしゃ です。', 'Đây là công ty điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (610, 43480, '漢字は難しいです。', 'かんじは むずかしい です。', 'Chữ Hán khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (611, 43482, '今週はとても忙しいです。', 'こんしゅうは とても いそがしい です。', 'Tuần này tôi rất bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (612, 43485, '私は料理が下手です。', 'わたしは りょうりが へた です。', 'Tôi nấu ăn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (613, 43487, 'すみません、もう一度言ってください。', 'すみません、もう いちど いって ください。', 'Xin lỗi, hãy nói lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (614, 27002, 'ドイツから来ました。', 'ドイツからきました。', 'Tôi đến từ Đức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (615, 27048, '日本語から来ました。', 'にほんごからきました。', 'Tôi đến từ tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (616, 27049, '日本語を勉強しています。', 'にほんごをべんきょうしています。', 'Tôi đang học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (617, 38065, 'この本の作者は誰ですか。', 'この ほんの さくしゃは だれ ですか。', 'Tác giả của cuốn sách này là ai?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (918, 27370, 'ここはすてきです。', 'ここはすてきです。', 'Ở đây đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (618, 38068, '映画の最後の場面で泣いてしまった。', 'えいがの さいごの ばめんで ないて しまった。', 'Tôi đã khóc ở cảnh cuối của bộ phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (619, 38072, '映画より原作の小説のほうがおもしろい。', 'えいがより げんさくの しょうせつの ほうが おもしろい。', 'Tiểu thuyết gốc hay hơn bản phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (620, 39076, 'この本の第一章を読んでおいてください。', 'この ほんの だいいっしょうを よんで おいて ください。', 'Hãy đọc trước chương một của cuốn sách này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (621, 38075, '学校には一年中いろいろな行事がある。', 'がっこうには いちねんじゅう いろいろな ぎょうじが ある。', 'Ở trường có nhiều sự kiện suốt cả năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (622, 39117, '図書の貸し出しは一人五冊までです。', 'としょの かしだしは ひとり ごさつまで です。', 'Mỗi người được mượn tối đa năm cuốn sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (623, 39229, '著者のサイン会に行った。', 'ちょしゃの サインかいに いった。', 'Tôi đi dự buổi ký tặng của tác giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (624, 43493, '七時半に起きます。', 'しちじ はんに おきます。', 'Tôi dậy lúc bảy giờ rưỡi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (625, 43495, '午後は図書館で勉強します。', 'ごごは としょかんで べんきょう します。', 'Buổi chiều tôi học ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (626, 43498, '晩、家族と話します。', 'ばん、かぞくと はなします。', 'Buổi tối tôi trò chuyện với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (627, 27022, 'その辞書は私のです。', 'その じしょは わたしの です。', 'Cuốn từ điển đó là của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (628, 27036, 'これは日本語のCDです。', 'これは にほんごの シーディー です。', 'Đây là đĩa CD tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (629, 27024, '毎朝、新聞を読みます。', 'まいあさ、しんぶんを よみます。', 'Sáng nào tôi cũng đọc báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (630, 27032, 'この鍵は車の鍵です。', 'この かぎは くるまの かぎ です。', 'Chiếc chìa này là chìa khóa xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (631, 27034, 'この傘は誰のですか。', 'この かさは だれの ですか。', 'Chiếc ô này của ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (632, 27035, '新しい鞄を買いました。', 'あたらしい かばんを かいました。', 'Tôi đã mua chiếc cặp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (633, 43490, 'きょうは時間がありません。', 'きょうは じかんが ありません。', 'Hôm nay tôi không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (634, 43499, '夜は家で本を読みます。', 'よるは いえで ほんを よみます。', 'Buổi tối tôi đọc sách ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (635, 27042, '机の上に本があります。', 'つくえの うえに ほんが あります。', 'Trên bàn có quyển sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (636, 27043, 'どうぞ、この椅子に座ってください。', 'どうぞ、この いすに すわって ください。', 'Mời anh ngồi ghế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (637, 27050, 'これは何ですか。', 'これは なん ですか。', 'Cái này là cái gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (638, 27051, 'A：これは辞書ですか。B：はい、そうです。', 'エー：これは じしょ ですか。ビー：はい、そう です。', 'A: Đây là từ điển à? B: Vâng, đúng vậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (639, 27054, 'どうぞ、入ってください。', 'どうぞ、はいって ください。', 'Xin mời vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (640, 27056, 'A：これは日本の車です。B：そうですか。', 'エー：これは にほんの くるま です。ビー：そう ですか。', 'A: Đây là xe Nhật. B: Thế à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (641, 43521, '秋は涼しくて、気持ちがいいです。', 'あきは すずしくて、きもちが いい です。', 'Mùa thu mát mẻ, dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (642, 43492, '駅まで五分です。', 'えきまで ごふん です。', 'Đến ga mất năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (643, 43500, '今日は何曜日ですか。', 'きょうは なんようび ですか。', 'Hôm nay là thứ mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (644, 43502, '昨日は雨でした。', 'きのうは あめ でした。', 'Hôm qua trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (645, 44117, '日本の習慣はまだよくわかりません。', 'にほんの しゅうかんは まだ よく わかりません。', 'Tôi vẫn chưa hiểu rõ phong tục Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (646, 27059, 'これからお世話になります。', 'これからおせわになります。', 'Từ nay mong được giúp đỡ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (647, 27065, 'ほんの気持ちです。', 'ほんのきもちです。', 'Đây là chút lòng thành', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (648, 39267, '昔の武士は刀を持っていた。', 'むかしの ぶしは かたなを もって いた。', 'Võ sĩ thời xưa mang theo kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (649, 39291, '六歳以下の子供は入場無料です。', 'ろくさい いかの こどもは にゅうじょう むりょう です。', 'Trẻ em dưới sáu tuổi được vào cửa miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (650, 39326, 'その事故は大きな悲劇になった。', 'その じこは おおきな ひげきに なった。', 'Vụ tai nạn đó đã trở thành một bi kịch lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (651, 39360, '今日の試合は私たちの負けだ。', 'きょうの しあいは わたしたちの まけだ。', 'Trận hôm nay chúng tôi thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (652, 39400, '子供のころ、冒険の物語が好きだった。', 'こどもの ころ、ぼうけんの ものがたりが すき だった。', 'Hồi nhỏ tôi thích những câu chuyện phiêu lưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (653, 39435, '私たちのチームが大会で優勝した。', 'わたしたちの チームが たいかいで ゆうしょう した。', 'Đội chúng tôi đã vô địch giải đấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (654, 42869, '彼は一晩で映画のスターになった。', 'かれは ひとばんで えいがの スターに なった。', 'Chỉ sau một đêm anh ấy trở thành ngôi sao điện ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (655, 42881, '彼はうまくパスを受けて、ゴールを決めた。', 'かれは うまく パスを うけて、ゴールを きめた。', 'Anh ấy nhận đường chuyền đẹp và ghi bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (656, 31558, 'このビルはセキュリティがしっかりしている。', 'この ビルは セキュリティが しっかり して いる。', 'Tòa nhà này có hệ thống bảo an chặt chẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (657, 39168, 'この装置は地震を感じると自動で止まる。', 'この そうちは じしんを かんじると じどうで とまる。', 'Thiết bị này tự dừng khi phát hiện động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (658, 43503, '毎日、電車で会社へ行きます。', 'まいにち、でんしゃで かいしゃへ いきます。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (659, 27029, '鉛筆で名前を書いてください。', 'えんぴつで なまえを かいて ください。', 'Hãy viết tên bằng bút chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (660, 27058, 'あ、雨が降っています。', 'あ、あめが ふって います。', 'Ồ, trời đang mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (661, 27064, 'トヨタは自動車の会社です。', 'トヨタは じどうしゃの かいしゃ です。', 'Toyota là công ty ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (662, 27066, 'A：これ、どうぞ。B：あ、どうも。', 'エー：これ、どうぞ。ビー：あ、どうも。', 'A: Cái này, mời anh. B: À, cảm ơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (663, 27025, 'ノートに漢字を書きます。', 'ノートに かんじを かきます。', 'Tôi viết chữ Hán vào vở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (664, 27028, 'カードで払ってもいいですか。', 'カードで はらっても いい ですか。', 'Tôi trả bằng thẻ được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (665, 27044, 'これはベルギーのチョコレートです。', 'これは ベルギーの チョコレート です。', 'Đây là sô-cô-la Bỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (666, 27037, '晩ごはんの後でテレビを見ます。', 'ばんごはんの あとで テレビを みます。', 'Sau bữa tối tôi xem tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (667, 27038, '毎朝ラジオを聞きます。', 'まいあさ ラジオを ききます。', 'Sáng nào tôi cũng nghe radio.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (668, 27039, 'このカメラは日本のです。', 'この カメラは にほんの です。', 'Chiếc máy ảnh này là của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (669, 27040, 'コンピューターで仕事をします。', 'コンピューターで しごとを します。', 'Tôi làm việc bằng máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (670, 27045, 'コーヒーを飲みませんか。', 'コーヒーを のみませんか。', 'Uống cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (671, 27031, 'これは私のシャープペンシルです。', 'これは わたしの シャープペンシル です。', 'Đây là bút chì bấm của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (672, 40723, '何と、彼が優勝した。', 'なんと、かれが ゆうしょう した。', 'Ôi chao, anh ấy đã vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (673, 27088, '［お］国から来ました。', '［お］くにからきました。', 'Tôi đến từ đất nước (của anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (674, 27094, '売り場へ行きます。', 'うりばへいきます。', 'Tôi đi đến quầy bán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (675, 27117, '山田でございます。', 'やまだでございます。', 'Tôi là Yamada ạ. (lịch sự)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (676, 27092, 'ネクタイから来ました。', 'ネクタイからきました。', 'Tôi đến từ cà vạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (677, 39381, '田舎の母から便りが届いた。', 'いなかの ははから たよりが とどいた。', 'Tôi nhận được thư của mẹ ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (678, 31431, 'この薬には熱を下げる作用がある。', 'この くすりには ねつを さげる さようが ある。', 'Thuốc này có tác dụng hạ sốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (679, 27063, 'テープレコーダーで日本語を聞きます。', 'テープレコーダーで にほんごを ききます。', 'Tôi nghe tiếng Nhật bằng máy cát-xét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (680, 27069, 'エレベーターはあそこです。', 'エレベーターは あそこ です。', 'Thang máy ở đằng kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (681, 27070, 'お手洗いはどこですか。', 'おてあらいは どこ ですか。', 'Nhà vệ sinh ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (682, 27071, 'こちらは山田さんです。', 'こちらは やまださん です。', 'Đây là anh Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (683, 27072, '会議室はそちらです。', 'かいぎしつは そちら です。', 'Phòng họp ở phía đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (684, 27073, '受付はあちらです。', 'うけつけは あちら です。', 'Quầy lễ tân ở đằng kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (685, 27074, 'お国はどちらですか。', 'おくには どちら ですか。', 'Anh đến từ nước nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (686, 27077, '事務所は二階です。', 'じむしょは にかい です。', 'Văn phòng ở tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (687, 27078, '会議室はどこですか。', 'かいぎしつは どこ ですか。', 'Phòng họp ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (688, 27081, '私の部屋は狭いです。', 'わたしの へやは せまい です。', 'Phòng của tôi hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (689, 27090, '私のうちは駅の近くです。', 'わたしの うちは えきの ちかく です。', 'Nhà tôi ở gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (690, 27091, 'この靴はいくらですか。', 'この くつは いくら ですか。', 'Đôi giày này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (691, 27096, '靴売り場は三階です。', 'くつうりばは さんがい です。', 'Quầy giày ở tầng ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (692, 27097, 'レストランは何階ですか。', 'レストランは なんがい ですか。', 'Nhà hàng ở tầng mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (693, 27100, 'このパンは百円です。', 'この パンは ひゃくえん です。', 'Cái bánh mì này giá một trăm yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (694, 27101, 'この本は千円です。', 'この ほんは せんえん です。', 'Cuốn sách này giá một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (695, 27103, 'すみません。この傘はいくらですか。', 'すみません。この かさは いくら ですか。', 'Xin lỗi. Chiếc ô này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (696, 27107, 'じゃ、これをください。', 'じゃ、これを ください。', 'Vậy thì, cho tôi cái này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (697, 29664, '靴売り場は地下三階です。', 'くつうりばは ちか さんがい です。', 'Quầy giày ở tầng hầm ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (698, 29663, 'すみません、お手洗いはどこですか。', 'すみません、おてあらいは どこ ですか。', 'Xin lỗi, nhà vệ sinh ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (699, 27080, 'ロビーで友達を待ちます。', 'ロビーで ともだちを まちます。', 'Tôi đợi bạn ở sảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (700, 27082, 'トイレはあそこです。', 'トイレは あそこ です。', 'Nhà vệ sinh ở đằng kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (701, 27085, 'エスカレーターは右です。', 'エスカレーターは みぎ です。', 'Thang cuốn ở bên phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (702, 43504, '毎朝、公園を散歩します。', 'まいあさ、こうえんを さんぽ します。', 'Sáng nào tôi cũng đi dạo công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (703, 27119, '毎朝六時に起きます。', 'まいあさ ろくじに おきます。', 'Sáng nào tôi cũng dậy lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (704, 44100, '床に本が落ちています。', 'ゆかに ほんが おちて います。', 'Trên sàn có quyển sách rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (705, 27118, 'MT／ヨーネン／アキックスへ行きます。', 'MT／ヨーネン／アキックスへいきます。', 'Tôi đi đến công ty giả định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (706, 27126, '銀行へ行きます。', 'ぎんこうへいきます。', 'Tôi đi đến ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (707, 27127, '郵便局へ行きます。', 'ゆうびんきょくへいきます。', 'Tôi đi đến bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (708, 27128, '図書館へ行きます。', 'としょかんへいきます。', 'Tôi đi đến thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (709, 31443, '結果より過程が大切だ。', 'けっかより かていが たいせつだ。', 'Quá trình quan trọng hơn kết quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (710, 38757, 'コップの縁が欠けている。', 'コップの ふちが かけて いる。', 'Miệng cốc bị sứt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (711, 38922, '赤と青なら、私は後者のほうが好きだ。', 'あかと あおなら、わたしは こうしゃの ほうが すきだ。', 'Giữa đỏ và xanh, tôi thích màu sau hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (712, 38925, '文の誤りを直しなさい。', 'ぶんの あやまりを なおしなさい。', 'Hãy sửa lỗi sai trong câu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (713, 38929, '駅の向かいに銀行がある。', 'えきの むかいに ぎんこうが ある。', 'Đối diện ga có một ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (714, 37997, 'パソコンを使うときは姿勢に気をつけよう。', 'パソコンを つかう ときは しせいに きを つけよう。', 'Khi dùng máy tính hãy chú ý tư thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (715, 39015, '量より質が大切だ。', 'りょうより しつが たいせつだ。', 'Chất lượng quan trọng hơn số lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (716, 38049, '明日は雨が降る可能性が高い。', 'あしたは あめが ふる かのうせいが たかい。', 'Ngày mai nhiều khả năng sẽ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (717, 39053, '名前を五十音順に並べてください。', 'なまえを ごじゅうおんじゅんに ならべて ください。', 'Hãy xếp tên theo thứ tự bảng chữ cái tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (718, 39057, '寝不足のせいで、頭が痛い。', 'ねぶそくの せいで、あたまが いたい。', 'Tại thiếu ngủ nên tôi đau đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (719, 39125, '水が勢いよく出てきた。', 'みずが いきおい よく でて きた。', 'Nước phun ra rất mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (720, 43505, '今週は忙しいです。', 'こんしゅうは いそがしい です。', 'Tuần này tôi bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (721, 27110, 'この時計はスイスのです。', 'この とけいは スイスの です。', 'Chiếc đồng hồ này là của Thụy Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (722, 27113, 'バンコクは今午後二時です。', 'バンコクは いま ごご にじ です。', 'Bangkok bây giờ là hai giờ chiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (723, 27114, 'ベルリンへ行ったことがありますか。', 'ベルリンへ いった ことが ありますか。', 'Bạn đã từng đến Berlin chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (724, 27122, '日曜日は休みます。', 'にちようびは やすみます。', 'Chủ nhật tôi nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (725, 27123, '毎晩日本語を勉強します。', 'まいばん にほんごを べんきょう します。', 'Tối nào tôi cũng học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (726, 43506, '来週、試験があります。', 'らいしゅう、しけんが あります。', 'Tuần sau có kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (727, 27135, '今、何時何分ですか。', 'いま、なんじ なんぷん ですか。', 'Bây giờ là mấy giờ mấy phút?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (728, 27136, '午前九時に会社へ行きます。', 'ごぜん くじに かいしゃへ いきます。', 'Chín giờ sáng tôi đến công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (729, 27137, '午後は図書館で勉強します。', 'ごごは としょかんで べんきょう します。', 'Buổi chiều tôi học ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (730, 27139, '昼は会社の食堂で食べます。', 'ひるは かいしゃの しょくどうで たべます。', 'Buổi trưa tôi ăn ở nhà ăn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (731, 27142, 'きのう、デパートへ行きました。', 'きのう、デパートへ いきました。', 'Hôm qua tôi đã đi trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (732, 27143, 'きょうは暑いですね。', 'きょうは あつい ですね。', 'Hôm nay nóng nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (733, 27187, 'あした、銀行へ行きます。', 'あした、ぎんこうへ いきます。', 'Ngày mai tôi đi ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (734, 27125, 'デパートへ行きます。', 'デパートへいきます。', 'Tôi đi đến cửa hàng bách hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (735, 39155, '電車とバスなら、前者のほうが速い。', 'でんしゃと バスなら、ぜんしゃの ほうが はやい。', 'Giữa tàu và xe buýt thì cái trước nhanh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (736, 39161, '人の粗ばかり探すのはよくない。', 'ひとの あら ばかり さがすのは よくない。', 'Chỉ chăm chăm bới lỗi người khác là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (737, 39177, 'その他に質問はありませんか。', 'その たに しつもんは ありませんか。', 'Ngoài ra còn câu hỏi nào khác không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (738, 39212, '階段の段に気をつけてください。', 'かいだんの だんに きを つけて ください。', 'Hãy cẩn thận bậc cầu thang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (739, 27144, 'あした、京都へ行きます。', 'あした、きょうとへ いきます。', 'Ngày mai tôi đi Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (740, 27145, 'あさってはテストがあります。', 'あさっては テストが あります。', 'Ngày kia có bài kiểm tra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (741, 27147, '今晩、友達と食事します。', 'こんばん、ともだちと しょくじ します。', 'Tối nay tôi đi ăn với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (742, 27148, 'あしたは休みです。', 'あしたは やすみ です。', 'Ngày mai được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (743, 27149, '昼休みは十二時から一時までです。', 'ひるやすみは じゅうにじから いちじまで です。', 'Nghỉ trưa từ mười hai giờ đến một giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (744, 27150, '試験は九時からです。', 'しけんは くじから です。', 'Kỳ thi bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (745, 27152, '日曜日、映画を見ます。', 'にちようび、えいがを みます。', 'Chủ nhật tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (746, 27154, '毎晩、日記を書きます。', 'まいばん、にっきを かきます。', 'Tối nào tôi cũng viết nhật ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (919, 27371, 'このりんごは大きいです。', 'このりんごはおおきいです。', 'Quả táo này to lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (747, 27155, '毎日、電車で会社へ行きます。', 'まいにち、でんしゃで かいしゃへ いきます。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (748, 27156, '月曜日から金曜日まで働きます。', 'げつようびから きんようびまで はたらきます。', 'Tôi làm việc từ thứ Hai đến thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (749, 27162, '日曜日、どこへ行きますか。', 'にちようび、どこへ いきますか。', 'Chủ nhật bạn đi đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (750, 43507, '先週、京都へ行きました。', 'せんしゅう、きょうとへ いきました。', 'Tuần trước tôi đã đi Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (751, 27163, 'きょうは何曜日ですか。', 'きょうは なんようび ですか。', 'Hôm nay là thứ mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (752, 27164, '授業は九時から始まります。', 'じゅぎょうは くじから はじまります。', 'Giờ học bắt đầu từ chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (753, 27169, 'あなたの部屋は何番ですか。', 'あなたの へやは なんばん ですか。', 'Phòng của bạn số mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (754, 27170, '会議室はそちらです。', 'かいぎしつは そちら です。', 'Phòng họp ở phía đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (755, 27178, 'やまと美術館は何時までですか。', 'やまと びじゅつかんは なんじまで ですか。', 'Bảo tàng mỹ thuật Yamato mở đến mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (756, 27186, '大阪デパートは十時から八時までです。', 'おおさか デパートは じゅうじから はちじまで です。', 'Trung tâm thương mại Osaka mở cửa từ mười giờ đến tám giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (757, 29666, '今、十時十分です。', 'いま、じゅうじ じゅっぷん です。', 'Bây giờ là mười giờ mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (758, 29665, '夜は家で本を読みます。', 'よるは いえで ほんを よみます。', 'Buổi tối tôi đọc sách ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (759, 27171, 'ニューヨークは今、夜です。', 'ニューヨークは いま、よる です。', 'New York bây giờ là ban đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (760, 43508, '今月の十日は休みです。', 'こんげつの とおかは やすみ です。', 'Ngày mười tháng này được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (761, 27173, 'ロサンゼルスは今、朝の七時です。', 'ロサンゼルスは いま、あさの しちじ です。', 'Los Angeles bây giờ là bảy giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (762, 27250, '毎朝パンを食べます。', 'まいあさ パンを たべます。', 'Sáng nào tôi cũng ăn bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (763, 44156, '電車の中で漫画を読んでいる人が多いです。', 'でんしゃの なかで まんがを よんで いる ひとが おおい です。', 'Trên tàu có nhiều người đọc truyện tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (764, 27192, '駅へ行きます。', 'えきへいきます。', 'Tôi đi đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (765, 39342, '月の表面には穴がたくさんある。', 'つきの ひょうめんには あなが たくさん ある。', 'Bề mặt mặt trăng có nhiều miệng hố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (766, 39362, 'この部分がよくわかりません。', 'この ぶぶんが よく わかりません。', 'Tôi không hiểu rõ phần này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (767, 39371, '彼は医学の分野で活躍している。', 'かれは いがくの ぶんやで かつやく して いる。', 'Anh ấy hoạt động tích cực trong lĩnh vực y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (768, 39447, '時間に余裕を持って出かけよう。', 'じかんに よゆうを もって でかけよう。', 'Hãy ra khỏi nhà sớm để dư dả thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (769, 38730, 'あの人は先生に違いない。', 'あの ひとは せんせいに ちがいない。', 'Người kia chắc chắn là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (770, 38958, '今にきっと成功するよ。', 'いまに きっと せいこう するよ。', 'Sớm muộn gì bạn cũng sẽ thành công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (771, 39017, '今日の試合は実におもしろかった。', 'きょうの しあいは じつに おもしろかった。', 'Trận đấu hôm nay thật sự hấp dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (772, 39083, '彼は常に笑顔を忘れない。', 'かれは つねに えがおを わすれない。', 'Anh ấy luôn giữ nụ cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (773, 39195, '大したけがではないので、心配しないで。', 'たいした けがでは ないので、しんぱい しないで。', 'Không phải vết thương gì đáng kể, đừng lo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (774, 39208, '単に忘れていただけです。', 'たんに わすれて いた だけ です。', 'Tôi chỉ đơn giản là quên mất thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (775, 39292, '夏より、むしろ冬のほうが好きだ。', 'なつより、むしろ ふゆの ほうが すきだ。', 'So với mùa hè, tôi thích mùa đông hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (776, 43509, '来年、大学に入ります。', 'らいねん、だいがくに はいります。', 'Năm sau tôi vào đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (777, 27188, '友達が日本へ来ます。', 'ともだちが にほんへ きます。', 'Bạn tôi sẽ đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (778, 27189, '六時にうちへ帰ります。', 'ろくじに うちへ かえります。', 'Sáu giờ tôi về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (779, 43510, '去年、結婚しました。', 'きょねん、けっこん しました。', 'Năm ngoái tôi đã kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (780, 27194, '船で島へ行きました。', 'ふねで しまへ いきました。', 'Tôi đã đi ra đảo bằng thuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (781, 27195, '電車で会社へ行きます。', 'でんしゃで かいしゃへ いきます。', 'Tôi đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (782, 27197, '新幹線で大阪へ行きます。', 'しんかんせんで おおさかへ いきます。', 'Tôi đi Osaka bằng tàu Shinkansen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (783, 27200, '自転車で学校へ来ます。', 'じてんしゃで がっこうへ きます。', 'Tôi đến trường bằng xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (784, 27201, '駅から歩いて帰りました。', 'えきから あるいて かえりました。', 'Tôi đi bộ từ ga về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (785, 27202, 'あの人は日本人です。', 'あの ひとは にほんじん です。', 'Người kia là người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (786, 27203, '友達と映画を見ました。', 'ともだちと えいがを みました。', 'Tôi đã xem phim với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (787, 27204, '彼は私の友達です。', 'かれは わたしの ともだち です。', 'Anh ấy là bạn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (788, 27206, '日曜日、家族と公園へ行きます。', 'にちようび、かぞくと こうえんへ いきます。', 'Chủ nhật tôi đi công viên với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (789, 27207, '一人で東京へ来ました。', 'ひとりで とうきょうへ きました。', 'Tôi đến Tokyo một mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (790, 27208, '先週、京都へ行きました。', 'せんしゅう、きょうとへ いきました。', 'Tuần trước tôi đã đi Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (791, 27209, '今週は忙しいです。', 'こんしゅうは いそがしい です。', 'Tuần này tôi bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (792, 27210, '来週、試験があります。', 'らいしゅう、しけんが あります。', 'Tuần sau có kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (793, 44215, '田舎では星がたくさん見えます。', 'いなかでは ほしが たくさん みえます。', 'Ở quê có thể nhìn thấy nhiều sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (794, 27191, 'スーパーへ行きます。', 'スーパーへいきます。', 'Tôi đi đến siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (795, 39379, '別に怒っているわけじゃないよ。', 'べつに おこって いる わけじゃ ないよ。', 'Tôi không có giận gì đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (796, 42876, 'どんな音楽が好きですか。', 'どんな おんがくが すき ですか。', 'Bạn thích thể loại nhạc nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (797, 42890, 'ニュースによると、明日は大雪らしい。', 'ニュースに よると、あしたは おおゆき らしい。', 'Theo tin tức thì ngày mai có tuyết lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (798, 31679, 'インフルエンザの予防注射を受けた。', 'インフルエンザの よぼう ちゅうしゃを うけた。', 'Tôi đã tiêm phòng cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (799, 39534, '蚊に刺されて、腕が痒い。', 'かに さされて、うでが かゆい。', 'Bị muỗi đốt nên cánh tay ngứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (800, 39585, '正座をしていたら、足がしびれた。', 'せいざを して いたら、あしが しびれた。', 'Ngồi quỳ kiểu Nhật một lúc thì chân tê cứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (801, 39702, '風邪をひいたので、マスクをして出かけた。', 'かぜを ひいたので、マスクを して でかけた。', 'Bị cảm nên tôi đeo khẩu trang khi ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (802, 37807, 'いい加減な仕事をしないでください。', 'いいかげんな しごとを しないで ください。', 'Đừng làm việc qua loa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (803, 37810, '子育てには忍耐が必要だ。', 'こそだてには にんたいが ひつようだ。', 'Nuôi con cần sự nhẫn nại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (804, 39583, 'しつこい勧誘の電話に困っている。', 'しつこい かんゆうの でんわに こまって いる。', 'Tôi khổ vì những cuộc gọi mời chào dai dẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (805, 39747, '意地悪なことを言わないで。', 'いじわるな ことを いわないで。', 'Đừng nói những lời ác ý như vậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (806, 27211, '先月、日本へ来ました。', 'せんげつ、にほんへ きました。', 'Tháng trước tôi đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (807, 27213, '来月、国へ帰ります。', 'らいげつ、くにへ かえります。', 'Tháng sau tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (808, 27214, '去年、結婚しました。', 'きょねん、けっこん しました。', 'Năm ngoái tôi đã kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (809, 43511, '月曜日から金曜日まで働きます。', 'げつようびから きんようびまで はたらきます。', 'Tôi làm việc từ thứ Hai đến thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (810, 27216, '来年、大学に入ります。', 'らいねん、だいがくに はいります。', 'Năm sau tôi vào đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (811, 27218, '何年に生まれましたか。', 'なんねんに うまれましたか。', 'Bạn sinh năm nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (812, 27220, '誕生日は何月ですか。', 'たんじょうびは なんがつ ですか。', 'Sinh nhật bạn tháng mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (813, 27232, '二十日に国へ帰ります。', 'はつかに くにへ かえります。', 'Ngày hai mươi tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (814, 27233, '十二月二十四日はクリスマスイブです。', 'じゅうにがつ にじゅうよっかは クリスマスイブ です。', 'Ngày 24 tháng 12 là đêm Giáng sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (815, 27235, 'きょうは何日ですか。', 'きょうは なんにち ですか。', 'Hôm nay là ngày mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (816, 27236, 'いつ日本へ来ましたか。', 'いつ にほんへ きましたか。', 'Bạn đến Nhật khi nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (817, 27237, '誕生日はいつですか。', 'たんじょうびは いつ ですか。', 'Sinh nhật bạn là khi nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (818, 27242, '次の電車は何時ですか。', 'つぎの でんしゃは なんじ ですか。', 'Chuyến tàu tiếp theo là mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (819, 27244, '急行は甲子園に止まりますか。', 'きゅうこうは こうしえんに とまりますか。', 'Tàu tốc hành có dừng ở Koshien không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (820, 27245, '特急で博多まで行きます。', 'とっきゅうで はかたまで いきます。', 'Tôi đi tàu tốc hành đặc biệt đến Hakata.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (821, 27247, '大阪城へ行きました。', 'おおさかじょうへ いきました。', 'Tôi đã đi lâu đài Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (822, 27249, '伏見まで電車で行きます。', 'ふしみまで でんしゃで いきます。', 'Tôi đi tàu đến Fushimi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (823, 44227, '朝、鳥の声が聞こえます。', 'あさ、とりの こえが きこえます。', 'Buổi sáng nghe thấy tiếng chim hót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (824, 27258, '写真を撮ります。', 'しゃしんをとります。', 'Chụp [ảnh]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (825, 27260, '友達に会います。', 'ともだちにあいます。', 'Gặp gỡ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (826, 31562, 'その問題をめぐって激しい論争が起きた。', 'その もんだいを めぐって はげしい ろんそうが おきた。', 'Xung quanh vấn đề đó đã nổ ra cuộc tranh luận gay gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (827, 39748, '失恋した友達を慰めた。', 'しつれん した ともだちを なぐさめた。', 'Tôi an ủi người bạn vừa thất tình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (828, 39917, '彼は強引に話を進めた。', 'かれは ごういんに はなしを すすめた。', 'Anh ta áp đặt, cứ thế mà tiến hành câu chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (829, 40018, '厚かましいお願いですが、お金を貸してもらえませんか。', 'あつかましい おねがい ですが、おかねを かして もらえませんか。', 'Thật ngại khi nhờ vả, nhưng anh có thể cho tôi mượn tiền không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (830, 31565, '物事の見方は人によって違う。', 'ものごとの みかたは ひとに よって ちがう。', 'Cách nhìn sự việc mỗi người mỗi khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4509, 29638, '迷惑をかけます。', 'めいわくをかけます。', 'Làm phiền', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (831, 40101, '彼は自分が正しいと思い込んでいる。', 'かれは じぶんが ただしいと おもいこんで いる。', 'Anh ta cứ đinh ninh là mình đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (832, 40102, 'いいアイデアを思い付いた。', 'いい アイデアを おもいついた。', 'Tôi chợt nghĩ ra một ý tưởng hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (833, 31568, '両国の利害が一致した。', 'りょうこくの りがいが いっち した。', 'Lợi ích của hai nước đã trùng nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (834, 31591, '新しい手法で調査を行った。', 'あたらしい しゅほうで ちょうさを おこなった。', 'Chúng tôi tiến hành khảo sát bằng phương pháp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (835, 31605, '景気の停滞が続いている。', 'けいきの ていたいが つづいて いる。', 'Kinh tế vẫn tiếp tục trì trệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (836, 31614, '来週、会社の会計の監査がある。', 'らいしゅう、かいしゃの かいけいの かんさが ある。', 'Tuần sau có đợt kiểm toán sổ sách công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (837, 31618, 'このお祭りは地元のボランティアが運営している。', 'この おまつりは じもとの ボランティアが うんえい して いる。', 'Lễ hội này do tình nguyện viên địa phương điều hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (838, 31633, '一人一人が自分の役割を果たそう。', 'ひとりひとりが じぶんの やくわりを はたそう。', 'Mỗi người hãy hoàn thành vai trò của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (839, 31662, '投資にはリスクがある。', 'とうしには リスクが ある。', 'Đầu tư thì có rủi ro.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (840, 43513, '水曜日は図書館が休みです。', 'すいようびは としょかんが やすみ です。', 'Thứ Tư thư viện nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (841, 27199, 'タクシーでホテルへ帰りました。', 'タクシーで ホテルへ かえりました。', 'Tôi đi taxi về khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (842, 27251, '毎晩お茶を飲みます。', 'まいばん おちゃを のみます。', 'Tối nào tôi cũng uống trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (843, 27253, '毎晩テレビを見ます。', 'まいばん テレビを みます。', 'Tối nào tôi cũng xem tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (844, 27256, '母に手紙を書きます。', 'ははに てがみを かきます。', 'Tôi viết thư cho mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (845, 27257, 'スーパーで野菜を買います。', 'スーパーで やさいを かいます。', 'Tôi mua rau ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (846, 27259, '日曜日、テニスをします。', 'にちようび、テニスを します。', 'Chủ nhật tôi chơi tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (847, 27262, '朝ごはんを食べましたか。', 'あさごはんを たべましたか。', 'Bạn đã ăn sáng chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (848, 27263, '昼ごはんは食堂で食べます。', 'ひるごはんは しょくどうで たべます。', 'Tôi ăn trưa ở nhà ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (849, 27264, '晩ごはんは家で食べます。', 'ばんごはんは いえで たべます。', 'Tôi ăn tối ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (850, 44323, '確か、会議は三時からだと思います。', 'たしか、かいぎは さんじから だと おもいます。', 'Tôi nghĩ hình như cuộc họp bắt đầu từ ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (851, 27303, 'フランス屋から来ました。', 'フランスやからきました。', 'Tôi đến từ a fictitious supermarket.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (852, 37786, '今月の売上は先月より多い。', 'こんげつの うりあげは せんげつより おおい。', 'Doanh thu tháng này cao hơn tháng trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (853, 37784, '父は小さなレストランを経営している。', 'ちちは ちいさな レストランを けいえい して いる。', 'Bố tôi điều hành một nhà hàng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (854, 27266, '毎朝、卵を一つ食べます。', 'まいあさ、たまごを ひとつ たべます。', 'Sáng nào tôi cũng ăn một quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (855, 27267, 'スーパーで肉を買いました。', 'スーパーで にくを かいました。', 'Tôi đã mua thịt ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (856, 27269, '毎日野菜を食べます。', 'まいにち やさいを たべます。', 'Ngày nào tôi cũng ăn rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (857, 27272, 'お茶を飲みませんか。', 'おちゃを のみませんか。', 'Uống trà không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (858, 27273, '紅茶にミルクを入れます。', 'こうちゃに ミルクを いれます。', 'Tôi cho sữa vào trà đen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (859, 27274, '毎朝、牛乳を飲みます。', 'まいあさ、ぎゅうにゅうを のみます。', 'Sáng nào tôi cũng uống sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (860, 27277, 'お酒を飲みますか。', 'おさけを のみますか。', 'Bạn có uống rượu không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (861, 27278, 'ここでたばこを吸わないでください。', 'ここで たばこを すわないで ください。', 'Xin đừng hút thuốc ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (862, 27279, '国の家族に手紙を書きました。', 'くにの かぞくに てがみを かきました。', 'Tôi viết thư cho gia đình ở quê nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (863, 27288, '日曜日、友達とお花見をします。', 'にちようび、ともだちと おはなみを します。', 'Chủ nhật tôi đi ngắm hoa anh đào với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (864, 27289, 'あした、何をしますか。', 'あした、なにを しますか。', 'Ngày mai bạn làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (865, 43514, '木曜日に会議があります。', 'もくようびに かいぎが あります。', 'Thứ Năm có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (866, 27305, '日曜日、映画を見ます。', 'にちようび、えいがを みます。', 'Chủ nhật tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (867, 43515, '金曜日の晩、友達と飲みます。', 'きんようびの ばん、ともだちと のみます。', 'Tối thứ Sáu tôi đi uống với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (868, 27290, '一緒に昼ごはんを食べませんか。', 'いっしょに ひるごはんを たべませんか。', 'Cùng ăn trưa không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (869, 27291, 'ちょっと待ってください。', 'ちょっと まって ください。', 'Xin chờ một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (870, 27292, 'いつも七時に起きます。', 'いつも しちじに おきます。', 'Tôi lúc nào cũng dậy lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (871, 27293, '時々、映画を見ます。', 'ときどき、えいがを みます。', 'Thỉnh thoảng tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (872, 27294, '宿題をします。それから、寝ます。', 'しゅくだいを します。それから、ねます。', 'Tôi làm bài tập. Sau đó đi ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (920, 27372, 'このりんごは小さいです。', 'このりんごはちいさいです。', 'Quả táo này nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (873, 27296, 'A：一緒に京都へ行きませんか。B：いいですね。', 'エー：いっしょに きょうとへ いきませんか。ビー：いい ですね。', 'A: Cùng đi Kyoto không? B: Hay đấy nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (874, 27298, 'A：佐藤さん。B：はい、何ですか。', 'エー：さとうさん。ビー：はい、なん ですか。', 'A: Chị Sato. B: Vâng, có chuyện gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (875, 27299, 'じゃ、またあした。', 'じゃ、また あした。', 'Vậy hẹn mai gặp lại nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (876, 27302, 'つるやでそばを食べました。', 'つるやで そばを たべました。', 'Tôi đã ăn mì soba ở quán Tsuruya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (877, 27265, '朝ごはんにパンを食べます。', 'あさごはんに パンを たべます。', 'Bữa sáng tôi ăn bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (878, 27483, '公園に子どもがいます。', 'こうえんに こどもが います。', 'Trong công viên có trẻ con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (879, 27482, '私は車があります。', 'わたしは くるまが あります。', 'Tôi có ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (880, 27275, 'ジュースから来ました。', 'ジュースからきました。', 'Tôi đến từ hoa quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (881, 27317, '電話をかけます。', 'でんわをかけます。', 'Gọi điện', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (882, 39749, '為替のレートは毎日変わる。', 'かわせの レートは まいにち かわる。', 'Tỷ giá hối đoái thay đổi mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (883, 31721, '仕事に役立つスキルを身につけたい。', 'しごとに やくだつ スキルを みに つけたい。', 'Tôi muốn trang bị những kỹ năng hữu ích cho công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (884, 39633, '日本ではチップを払う習慣がない。', 'にほんでは チップを はらう しゅうかんが ない。', 'Ở Nhật không có thói quen đưa tiền boa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (885, 39823, 'たばこには高い税金が課税されている。', 'たばこには たかい ぜいきんが かぜい されて いる。', 'Thuốc lá bị đánh thuế cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (886, 39912, '店は改装のため、一週間休業します。', 'みせは かいそうの ため、いっしゅうかん きゅうぎょう します。', 'Cửa hàng tạm nghỉ một tuần để sửa sang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (887, 43516, '土曜日はテニスをします。', 'どようびは テニスを します。', 'Thứ Bảy tôi chơi tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (888, 27276, '仕事の後でビールを飲みます。', 'しごとの あとで ビールを のみます。', 'Sau giờ làm tôi uống bia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (889, 27282, 'うちでビデオを見ました。', 'うちで ビデオを みました。', 'Tôi đã xem video ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (890, 27286, '日曜日に友達とテニスをします。', 'にちようびに ともだちと テニスを します。', 'Chủ nhật tôi chơi tennis với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (891, 27287, '公園でサッカーをしました。', 'こうえんで サッカーを しました。', 'Tôi đã đá bóng ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (892, 27300, 'メキシコの料理が好きです。', 'メキシコの りょうりが すき です。', 'Tôi thích món ăn Mexico.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (893, 27310, '国の家族に写真を送ります。', 'くにの かぞくに しゃしんを おくります。', 'Tôi gửi ảnh cho gia đình ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (894, 27311, '母に花をあげます。', 'ははに はなを あげます。', 'Tôi tặng hoa cho mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (895, 27312, '友達にプレゼントをもらいました。', 'ともだちに プレゼントを もらいました。', 'Tôi nhận được quà từ bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (896, 27313, '友達に本を貸しました。', 'ともだちに ほんを かしました。', 'Tôi đã cho bạn mượn sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (897, 27315, '山田さんに英語を教えます。', 'やまださんに えいごを おしえます。', 'Tôi dạy tiếng Anh cho anh Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (898, 27318, 'ごはんの前に手を洗います。', 'ごはんの まえに てを あらいます。', 'Tôi rửa tay trước bữa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (899, 27319, 'はしでごはんを食べます。', 'はしで ごはんを たべます。', 'Tôi ăn cơm bằng đũa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (900, 27323, 'はさみを貸してください。', 'はさみを かして ください。', 'Cho tôi mượn cái kéo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (901, 27331, '消しゴムで字を消します。', 'けしゴムで じを けします。', 'Tôi xóa chữ bằng cục tẩy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (902, 27332, 'この紙に名前を書いてください。', 'この かみに なまえを かいて ください。', 'Hãy viết tên vào tờ giấy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (903, 27337, '銀行でお金を下ろします。', 'ぎんこうで おかねを おろします。', 'Tôi rút tiền ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (904, 27338, '駅で切符を買います。', 'えきで きっぷを かいます。', 'Tôi mua vé ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (905, 27340, '父は銀行員です。', 'ちちは ぎんこういん です。', 'Bố tôi là nhân viên ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (906, 27341, '母は料理が上手です。', 'ははは りょうりが じょうず です。', 'Mẹ tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (907, 27489, '庭に犬がいます。', 'にわに いぬが います。', 'Trong vườn có con chó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (908, 43519, '春は桜がきれいです。', 'はるは さくらが きれい です。', 'Mùa xuân hoa anh đào rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (909, 43518, '週末は何をしますか。', 'しゅうまつは なにを しますか。', 'Cuối tuần bạn làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (910, 44348, '隣の部屋から子どもの声が聞こえます。', 'となりの へやから こどもの こえが きこえます。', 'Nghe thấy tiếng trẻ con từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (911, 27347, '本、すてきですね。', 'ほん、すてきですね。', 'What a nice sách!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (912, 27349, 'どうぞお上がりください。', 'どうぞおあがりください。', 'Xin mời anh vào nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (913, 27351, '本はいかがですか。', 'ほんはいかがですか。', 'Anh/chị có muốn xem sách không? (dùng khi mời ai đó)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (914, 27325, 'ケータイから来ました。', 'ケータイからきました。', 'Tôi đến từ mobile phone.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (915, 27367, 'ここは元気です。', 'ここはげんきです。', 'Ở đây khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (916, 27368, 'ここは暇です。', 'ここはひまです。', 'Ở đây rảnh rỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (917, 27369, 'ここは便利です。', 'ここはべんりです。', 'Ở đây tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (921, 27343, 'お母さんは何歳ですか。', 'おかあさんは なんさい ですか。', 'Mẹ bạn bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (922, 27344, 'もう昼ごはんを食べましたか。', 'もう ひるごはんを たべましたか。', 'Bạn đã ăn trưa chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (923, 27345, 'いいえ、まだです。', 'いいえ、まだ です。', 'Chưa, tôi vẫn chưa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (924, 27348, 'いらっしゃい。どうぞお上がりください。', 'いらっしゃい。どうぞ おあがり ください。', 'Chào mừng bạn đến chơi. Mời vào nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (925, 27350, '失礼します。田中です。', 'しつれい します。たなか です。', 'Xin phép ạ. Tôi là Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (926, 43522, '冬はとても寒いです。', 'ふゆは とても さむい です。', 'Mùa đông rất lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (927, 27358, '夏休みに家族と旅行します。', 'なつやすみに かぞくと りょこう します。', 'Kỳ nghỉ hè tôi đi du lịch với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (928, 27359, '旅行のお土産を買いました。', 'りょこうの おみやげを かいました。', 'Tôi đã mua quà du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (929, 27320, 'スプーンでスープを飲みます。', 'スプーンで スープを のみます。', 'Tôi ăn súp bằng thìa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (930, 27321, 'ナイフで肉を切ります。', 'ナイフで にくを きります。', 'Tôi cắt thịt bằng dao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (931, 43523, 'きょうはいい天気ですね。', 'きょうは いい てんき ですね。', 'Hôm nay thời tiết đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (932, 27322, 'フォークでケーキを食べます。', 'フォークで ケーキを たべます。', 'Tôi ăn bánh ngọt bằng nĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (933, 27326, '友達にメールを送りました。', 'ともだちに メールを おくりました。', 'Tôi đã gửi email cho bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (934, 27328, 'パンチで紙に穴をあけます。', 'パンチで かみに あなを あけます。', 'Tôi đục lỗ giấy bằng cái bấm lỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (935, 27330, 'セロテープでポスターを貼ります。', 'セロテープで ポスターを はります。', 'Tôi dán áp phích bằng băng keo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (936, 27334, '白いシャツを買いました。', 'しろい シャツを かいました。', 'Tôi đã mua chiếc áo sơ mi trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (937, 27339, 'クリスマスに家族でパーティーをします。', 'クリスマスに かぞくで パーティーを します。', 'Giáng sinh cả nhà tổ chức tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (938, 27354, 'スペインへ旅行に行きたいです。', 'スペインへ りょこうに いきたい です。', 'Tôi muốn đi du lịch Tây Ban Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (939, 27355, 'ファクスで地図を送ります。', 'ファクスで ちずを おくります。', 'Tôi gửi bản đồ qua fax.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (940, 27360, '夏休みにヨーロッパへ行きます。', 'なつやすみに ヨーロッパへ いきます。', 'Kỳ nghỉ hè tôi đi châu Âu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (941, 43524, 'きのうは雨でした。', 'きのうは あめ でした。', 'Hôm qua trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (942, 27373, 'このりんごは新しいです。', 'このりんごはあたらしいです。', 'Quả táo này mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (943, 27374, 'このりんごは古いです。', 'このりんごはふるいです。', 'Quả táo này cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (944, 27375, 'このりんごはいいです。', 'このりんごはいいです。', 'Quả táo này tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (945, 27376, 'このりんごは悪いです。', 'このりんごはわるいです。', 'Quả táo này xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (946, 27377, 'このりんごは暑い、熱いです。', 'このりんごはあついです。', 'Quả táo này nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (947, 27378, 'このりんごは寒いです。', 'このりんごはさむいです。', 'Quả táo này lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (948, 27379, 'このりんごは冷たいです。', 'このりんごはつめたいです。', 'Quả táo này lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (949, 27380, 'このりんごは難しいです。', 'このりんごはむずかしいです。', 'Quả táo này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (950, 27381, 'このりんごは易しいです。', 'このりんごはやさしいです。', 'Quả táo này dễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (951, 27382, 'このりんごは高いです。', 'このりんごはたかいです。', 'Quả táo này đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (952, 27383, 'このりんごは安いです。', 'このりんごはやすいです。', 'Quả táo này rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (953, 27384, 'このりんごは低いです。', 'このりんごはひくいです。', 'Quả táo này thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (954, 27385, 'このりんごはおもしろいです。', 'このりんごはおもしろいです。', 'Quả táo này thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (955, 27386, 'このりんごはおいしいです。', 'このりんごはおいしいです。', 'Quả táo này ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (956, 27387, 'このりんごは忙しいです。', 'このりんごはいそがしいです。', 'Quả táo này bận rộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (957, 27388, 'このりんごは楽しいです。', 'このりんごはたのしいです。', 'Quả táo này vui vẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (958, 27389, 'このりんごは白いです。', 'このりんごはしろいです。', 'Quả táo này trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (959, 44116, '外国の文化に興味があります。', 'がいこくの ぶんかに きょうみが あります。', 'Tôi quan tâm đến văn hóa nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (960, 44148, '使った物はきちんと片付けてください。', 'つかった ものは きちんと かたづけて ください。', 'Đồ đã dùng thì hãy cất dọn ngăn nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (961, 44195, '去年と比べると、今年は雨が少ないです。', 'きょねんと くらべると、ことしは あめが すくないです。', 'So với năm ngoái thì năm nay ít mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (962, 44254, '運動を始めてから、体重が三キロ減りました。', 'うんどうを はじめてから、たいじゅうが さんキロ へりました。', 'Từ khi bắt đầu tập thể dục, tôi đã giảm ba ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (963, 40129, '試験で自分の実力がわかった。', 'しけんで じぶんの じつりょくが わかった。', 'Qua kỳ thi tôi biết được năng lực thực sự của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (964, 40153, '荷物の受取にはサインが必要です。', 'にもつの うけとりには サインが ひつよう です。', 'Nhận hàng cần phải ký tên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (965, 40156, '新しい社長が就任した。', 'あたらしい しゃちょうが しゅうにん した。', 'Tân giám đốc đã nhậm chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (966, 43525, '北海道は雪が多いです。', 'ほっかいどうは ゆきが おおい です。', 'Hokkaido có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (967, 27394, '日曜日に山へ行きます。', 'にちようびに やまへ いきます。', 'Chủ nhật tôi đi núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (968, 43526, '今日は風が強いです。', 'きょうは かぜが つよい です。', 'Hôm nay gió mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (969, 43527, '空がとても青いです。', 'そらが とても あおい です。', 'Bầu trời rất xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (970, 43530, '今日はとても暑いですね。', 'きょうは とても あつい ですね。', 'Hôm nay nóng quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (971, 43532, '春になって、暖かくなりました。', 'はるに なって、あたたかく なりました。', 'Sang xuân trời ấm lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (972, 43534, '朝から雨が降っています。', 'あさから あめが ふって います。', 'Trời mưa từ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (973, 43536, '午後から晴れるでしょう。', 'ごごから はれるでしょう。', 'Từ chiều có lẽ trời sẽ nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (974, 27109, 'イタリアから来ました。', 'イタリアからきました。', 'Tôi đến từ Italy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (975, 27111, 'フランスから来ました。', 'フランスからきました。', 'Tôi đến từ France.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (976, 40183, 'ケーキの出来上がりは三時ごろです。', 'ケーキの できあがりは さんじごろ です。', 'Bánh sẽ xong vào khoảng ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (977, 43174, 'この駐車場は有料です。', 'この ちゅうしゃじょうは ゆうりょう です。', 'Bãi đỗ xe này có thu phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (978, 43207, '代金を確かに領収いたしました。', 'だいきんを たしかに りょうしゅう いたしました。', 'Chúng tôi đã nhận đủ tiền hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (979, 39500, 'お金があることは、幸せとイコールではない。', 'おかねが ある ことは、しあわせと イコールでは ない。', 'Có tiền không đồng nghĩa với hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (980, 39614, 'ゼミで研究の発表をした。', 'ゼミで けんきゅうの はっぴょうを した。', 'Tôi trình bày nghiên cứu trong buổi seminar.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (981, 39675, 'わからないことは百科事典で調べた。', 'わからない ことは ひゃっか じてんで しらべた。', 'Điều gì không biết tôi tra trong từ điển bách khoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (982, 39773, '月の引力で海の満ち引きが起こる。', 'つきの いんりょくで うみの みちひきが おこる。', 'Lực hấp dẫn của mặt trăng tạo nên thủy triều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (983, 39779, '飛行機に液体を持ち込むのは制限されている。', 'ひこうきに えきたいを もちこむのは せいげん されて いる。', 'Việc mang chất lỏng lên máy bay bị hạn chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (984, 39803, '手紙を書く前に、下書きをした。', 'てがみを かく まえに、したがきを した。', 'Trước khi viết thư tôi đã viết nháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (985, 39854, '一年生は経済学概論を勉強する。', 'いちねんせいは けいざいがく がいろんを べんきょう する。', 'Sinh viên năm nhất học môn kinh tế học đại cương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (986, 39868, '彼の論文は学術雑誌に載った。', 'かれの ろんぶんは がくじゅつ ざっしに のった。', 'Luận văn của anh ấy được đăng trên tạp chí học thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (987, 39870, '経済学部の学生です。', 'けいざい がくぶの がくせい です。', 'Tôi là sinh viên khoa kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (988, 27112, 'ジャカルタは今何時ですか。', 'ジャカルタは いま なんじ ですか。', 'Bây giờ ở Jakarta là mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (989, 27157, '火曜日に日本語の授業があります。', 'かようびに にほんごの じゅぎょうが あります。', 'Thứ Ba có giờ học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (990, 27159, '木曜日に会議があります。', 'もくようびに かいぎが あります。', 'Thứ Năm có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (991, 27166, 'パンと卵を食べます。', 'パンと たまごを たべます。', 'Tôi ăn bánh mì và trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (992, 43550, '電車で会社へ行きます。', 'でんしゃで かいしゃへ いきます。', 'Tôi đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (993, 43551, '地下鉄で駅まで行きます。', 'ちかてつで えきまで いきます。', 'Tôi đi tàu điện ngầm đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (994, 27395, '私の町は静かです。', 'わたしの まちは しずか です。', 'Thị trấn của tôi yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (995, 43542, 'いつも七時に起きます。', 'いつも しちじに おきます。', 'Tôi lúc nào cũng dậy lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (996, 43544, '彼の話はよくわかりません。', 'かれの はなしは よく わかりません。', 'Tôi không hiểu rõ lời anh ấy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (997, 43547, 'もう昼ごはんを食べましたか。', 'もう ひるごはんを たべましたか。', 'Bạn đã ăn trưa chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (998, 43545, 'すぐ来てください。', 'すぐ きて ください。', 'Hãy đến ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (999, 43548, 'だんだん寒くなりました。', 'だんだん さむく なりました。', 'Trời dần dần lạnh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1000, 43538, '父は朝が早いです。', 'ちちは あさが はやい です。', 'Bố tôi dậy sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1001, 43540, 'この川はとても長いです。', 'この かわは とても ながい です。', 'Con sông này rất dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1002, 43549, '駅まで歩いて十分です。', 'えきまで あるいて じゅっぷん です。', 'Đi bộ đến ga mất mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1003, 39874, '割り算の答えが合わない。', 'わりざんの こたえが あわない。', 'Đáp án phép chia không khớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1004, 39876, '最近の若者は活字を読まなくなった。', 'さいきんの わかものは かつじを よまなく なった。', 'Giới trẻ gần đây ít đọc sách báo in.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1005, 40077, '本の索引で言葉を探した。', 'ほんの さくいんで ことばを さがした。', 'Tôi tìm từ trong bảng tra cứu của cuốn sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1006, 40106, '妹は私立の高校に通っている。', 'いもうとは しりつの こうこうに かよって いる。', 'Em gái tôi học trường cấp ba tư thục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1007, 40113, '明日の時間割を確認した。', 'あしたの じかんわりを かくにん した。', 'Tôi kiểm tra thời khóa biểu ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1008, 40120, '大学では自然科学を専攻したい。', 'だいがくでは しぜん かがくを せんこう したい。', 'Ở đại học tôi muốn học chuyên ngành khoa học tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1009, 40141, '日本語では主語がよく省略される。', 'にほんごでは しゅごが よく しょうりゃく される。', 'Trong tiếng Nhật chủ ngữ hay bị lược bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1010, 40177, '漢字の熟語をたくさん覚えた。', 'かんじの じゅくごを たくさん おぼえた。', 'Tôi đã học thuộc nhiều từ ghép chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1011, 40190, '初級の日本語クラスに入った。', 'しょきゅうの にほんご クラスに はいった。', 'Tôi vào lớp tiếng Nhật sơ cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1012, 40207, '小数の計算は難しい。', 'しょうすうの けいさんは むずかしい。', 'Tính toán số thập phân thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1013, 42892, '万年筆のインキがなくなった。', 'まんねんひつの インキが なくなった。', 'Bút máy hết mực rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1014, 27158, '水曜日は図書館が休みです。', 'すいようびは としょかんが やすみ です。', 'Thứ Tư thư viện nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1015, 27161, '土曜日はテニスをします。', 'どようびは テニスを します。', 'Thứ Bảy tôi chơi tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1016, 43559, '駅で切符を買います。', 'えきで きっぷを かいます。', 'Tôi mua vé ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1017, 43571, '日曜日に山へ行きます。', 'にちようびに やまへ いきます。', 'Chủ nhật tôi đi núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1018, 43577, '銀行の右に郵便局があります。', 'ぎんこうの みぎに ゆうびんきょくが あります。', 'Bên phải ngân hàng có bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1019, 43579, '駅の前で待っています。', 'えきの まえで まって います。', 'Tôi đang đợi trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1020, 27707, '暑いですから、エアコンをつけましょうか。', 'あつい ですから、エアコンを つけましょうか。', 'Nóng quá, để tôi bật điều hòa nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1021, 43572, '川で魚を釣りました。', 'かわで さかなを つりました。', 'Tôi câu cá ở sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1022, 43576, '地図を書いてください。', 'ちずを かいて ください。', 'Hãy vẽ bản đồ giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1023, 43562, '信号が青になったら、渡ります。', 'しんごうが あおに なったら、わたります。', 'Khi đèn xanh thì sang đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1024, 43564, 'あの角に銀行があります。', 'あの かどに ぎんこうが あります。', 'Ở góc kia có ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1025, 43566, '日曜日、公園を散歩しました。', 'にちようび、こうえんを さんぽ しました。', 'Chủ nhật tôi đã đi dạo ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1026, 43570, '道がわからないので、交番で聞きました。', 'みちが わからないので、こうばんで ききました。', 'Không biết đường nên tôi hỏi ở đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1027, 43583, '太陽は東から出ます。', 'たいようは ひがしから でます。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1028, 43585, '沖縄は日本の南にあります。', 'おきなわは にほんの みなみに あります。', 'Okinawa nằm ở phía nam Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1029, 43587, '明日、デパートへ行きます。', 'あした、デパートへ いきます。', 'Ngày mai tôi đi trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1030, 43589, '七時にうちへ帰ります。', 'しちじに うちへ かえります。', 'Bảy giờ tôi về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1031, 43591, '毎朝、川の近くを走ります。', 'まいあさ、かわの ちかくを はしります。', 'Sáng nào tôi cũng chạy bộ gần sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1032, 44386, '日本語がずいぶん上手になりましたね。', 'にほんごが ずいぶん じょうずに なりましたね。', 'Tiếng Nhật của bạn đã giỏi lên khá nhiều nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1033, 27391, 'このりんごは赤いです。', 'このりんごはあかいです。', 'Quả táo này đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1034, 27392, 'このりんごは青いです。', 'このりんごはあおいです。', 'Quả táo này xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1035, 31680, '暑さ対策に帽子をかぶっている。', 'あつさ たいさくに ぼうしを かぶって いる。', 'Tôi đội mũ để chống nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1036, 31113, '私の作文が雑誌に掲載された。', 'わたしの さくぶんが ざっしに けいさい された。', 'Bài văn của tôi đã được đăng trên tạp chí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1037, 31116, 'これは二人だけの秘密だよ。', 'これは ふたり だけの ひみつだよ。', 'Đây là bí mật của riêng hai chúng ta nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1038, 31119, '週刊誌が政治家の秘密を暴露した。', 'しゅうかんしが せいじかの ひみつを ばくろ した。', 'Tuần san đã phơi bày bí mật của chính trị gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1039, 31585, '政府は子育てを支援する政策を発表した。', 'せいふは こそだてを しえん する せいさくを はっぴょう した。', 'Chính phủ công bố chính sách hỗ trợ nuôi dạy con cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1040, 43120, '望遠鏡で月を観察した。', 'ぼうえんきょうで つきを かんさつ した。', 'Tôi quan sát mặt trăng bằng kính viễn vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1041, 43196, '勉強しなかったので、落第してしまった。', 'べんきょう しなかったので、らくだい して しまった。', 'Không học nên tôi bị đánh trượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1042, 43218, '和英辞典を使って作文を書いた。', 'わえい じてんを つかって さくぶんを かいた。', 'Tôi dùng từ điển Nhật–Anh để viết bài văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1043, 31664, '大雨で農作物に損害が出た。', 'おおあめで のうさくもつに そんがいが でた。', 'Mưa lớn gây thiệt hại cho hoa màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1044, 31670, '小さなうわさが大きな騒動になった。', 'ちいさな うわさが おおきな そうどうに なった。', 'Một tin đồn nhỏ đã thành vụ náo loạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1045, 31682, '停電は二時間後に復旧した。', 'ていでんは にじかんごに ふっきゅう した。', 'Mất điện hai tiếng thì có điện trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1046, 43611, 'あの人は日本人です。', 'あの ひとは にほんじん です。', 'Người kia là người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1047, 27396, '日本の食べ物はおいしいです。', 'にほんの たべものは おいしい です。', 'Đồ ăn Nhật rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1048, 27397, '京都はきれいな所です。', 'きょうとは きれいな ところ です。', 'Kyoto là một nơi đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1049, 43617, '母は料理が上手です。', 'ははは りょうりが じょうず です。', 'Mẹ tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1050, 27757, 'ここに荷物を置いてもいいですか。', 'ここに にもつを おいても いい ですか。', 'Tôi để hành lý ở đây được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1051, 43609, '私はベトナム人です。', 'わたしは ベトナムじん です。', 'Tôi là người Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1052, 43613, '受付に女の人がいます。', 'うけつけに おんなの ひとが います。', 'Ở quầy lễ tân có một người phụ nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1053, 43614, '公園で子供が遊んでいます。', 'こうえんで こどもが あそんで います。', 'Trẻ con đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1054, 43595, 'あの角を右へ曲がってください。', 'あの かどを みぎへ まがって ください。', 'Hãy rẽ phải ở góc kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1055, 43597, '電車は十時に東京に着きます。', 'でんしゃは じゅうじに とうきょうに つきます。', 'Tàu đến Tokyo lúc mười giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1056, 43599, '部屋に入ってください。', 'へやに はいって ください。', 'Mời vào phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1057, 43601, '私のうちは駅から近いです。', 'わたしの うちは えきから ちかい です。', 'Nhà tôi gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1058, 43602, '学校はうちから遠いです。', 'がっこうは うちから とおい です。', 'Trường ở xa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1059, 43604, 'このかばんは小さいです。', 'この かばんは ちいさい です。', 'Chiếc cặp này nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1060, 43607, '京都は古いお寺で有名です。', 'きょうとは ふるい おてらで ゆうめい です。', 'Kyoto nổi tiếng với những ngôi chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1061, 27791, '電車に乗ります。', 'でんしゃにのります。', 'Đi lên tàu, xe', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1062, 31684, '時代の潮流に乗って、会社は成長した。', 'じだいの ちょうりゅうに のって、かいしゃは せいちょう した。', 'Nắm bắt xu thế thời đại, công ty đã phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1063, 31687, '新聞社が世論調査を行った。', 'しんぶんしゃが よろん ちょうさを おこなった。', 'Tòa báo đã tiến hành khảo sát dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1064, 31691, 'ダイエットの反動で食べすぎてしまった。', 'ダイエットの はんどうで たべすぎて しまった。', 'Sau đợt ăn kiêng, tôi lại ăn quá nhiều như phản ứng ngược.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1065, 39542, 'その映画はアメリカのギャングの話だ。', 'その えいがは アメリカの ギャングの はなしだ。', 'Bộ phim đó kể về băng đảng ở Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1066, 39830, '試験が終わって、やっと勉強から解放された。', 'しけんが おわって、やっと べんきょうから かいほう された。', 'Thi xong, cuối cùng tôi cũng được giải phóng khỏi việc học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1067, 39898, '山の上に観測の基地がある。', 'やまの うえに かんそくの きちが ある。', 'Trên núi có một trạm quan trắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1068, 39957, '会場の警備のために警察官が来た。', 'かいじょうの けいびの ために けいさつかんが きた。', 'Cảnh sát đến để bảo vệ hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1069, 40049, '国王が国民の前で演説した。', 'こくおうが こくみんの まえで えんぜつ した。', 'Quốc vương phát biểu trước người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1070, 40051, '兄は国立大学に通っている。', 'あには こくりつ だいがくに かよって いる。', 'Anh tôi học ở trường đại học quốc lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1071, 43638, '誕生日はいつですか。', 'たんじょうびは いつ ですか。', 'Sinh nhật bạn là khi nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1072, 27400, '日本の生活はどうですか。', 'にほんの せいかつは どう ですか。', 'Cuộc sống ở Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1073, 27401, 'お仕事は何ですか。', 'おしごとは なん ですか。', 'Anh làm nghề gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1074, 27402, '日本の料理はどうですか。', 'にほんの りょうりは どう ですか。', 'Món ăn Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1075, 43619, 'お母さんは何歳ですか。', 'おかあさんは なんさい ですか。', 'Mẹ bạn bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1076, 43620, '兄は東京で働いています。', 'あには とうきょうで はたらいて います。', 'Anh trai tôi làm việc ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1077, 43622, '弟は大学生です。', 'おとうとは だいがくせい です。', 'Em trai tôi là sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1078, 43624, 'お兄さんは何をしていますか。', 'おにいさんは なにを して いますか。', 'Anh trai bạn đang làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1079, 43626, '兄弟が何人いますか。', 'きょうだいが なんにん いますか。', 'Bạn có mấy anh chị em?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1080, 43635, 'ここに名前を書いてください。', 'ここに なまえを かいて ください。', 'Hãy viết tên vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1081, 43646, '毎日運動すると、体にいいです。', 'まいにち うんどう すると、からだに いい です。', 'Tập thể dục mỗi ngày tốt cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1082, 43629, '祖母は田舎に住んでいます。', 'そぼは いなかに すんで います。', 'Bà tôi sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1083, 43631, 'おばあさんに道を教えました。', 'おばあさんに みちを おしえました。', 'Tôi chỉ đường cho một cụ bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1084, 43633, '妻と二人で住んでいます。', 'つまと ふたりで すんで います。', 'Tôi sống cùng vợ, hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1085, 43637, '妹は十五歳です。', 'いもうとは じゅうごさい です。', 'Em gái tôi mười lăm tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1086, 43641, '私は大学の学生です。', 'わたしは だいがくの がくせい です。', 'Tôi là sinh viên đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1087, 43643, '兄は会社員です。', 'あには かいしゃいん です。', 'Anh trai tôi là nhân viên công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1088, 43644, '姉は病院の医者です。', 'あねは びょういんの いしゃ です。', 'Chị gái tôi là bác sĩ ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1089, 44206, '私は数学が苦手です。', 'わたしは すうがくが にがて です。', 'Tôi kém môn toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1344, 43894, '朝から雨が降っています。', 'あさから あめが ふって います。', 'Trời mưa từ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1090, 40118, 'この町には住民の自治会がある。', 'この まちには じゅうみんの じちかいが ある。', 'Thị trấn này có hội tự quản của cư dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1091, 40163, '明日は朝八時に駅に集合してください。', 'あしたは あさ はちじに えきに しゅうごう して ください。', 'Ngày mai hãy tập trung ở ga lúc tám giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1092, 40212, '家の近くに消防署がある。', 'いえの ちかくに しょうぼうしょが ある。', 'Gần nhà tôi có trạm cứu hỏa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1093, 43122, '家に防犯カメラをつけた。', 'いえに ぼうはん カメラを つけた。', 'Tôi lắp camera an ninh ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1094, 31627, 'レポートを書くために徹夜した。', 'レポートを かく ために てつや した。', 'Tôi thức trắng đêm để viết báo cáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1095, 39510, 'エプロンをして料理を始めた。', 'エプロンを して りょうりを はじめた。', 'Tôi đeo tạp dề rồi bắt đầu nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1096, 39544, '暑いので、クーラーをつけた。', 'あついので、クーラーを つけた。', 'Nóng quá nên tôi bật máy lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1097, 39570, 'スマホの充電器をコンセントに差した。', 'スマホの じゅうでんきを コンセントに さした。', 'Tôi cắm sạc điện thoại vào ổ điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1098, 39598, '首にスカーフを巻いて出かけた。', 'くびに スカーフを まいて でかけた。', 'Tôi quàng khăn vào cổ rồi ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1099, 39605, 'ストッキングが破れてしまった。', 'ストッキングが やぶれて しまった。', 'Đôi tất da bị rách mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1100, 39648, 'ナイロンのかばんは軽くて丈夫だ。', 'ナイロンの かばんは かるくて じょうぶだ。', 'Túi ni lông nhẹ mà bền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1101, 39659, 'バケツに水をくんで、車を洗った。', 'バケツに みずを くんで、くるまを あらった。', 'Tôi múc nước vào xô để rửa xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1102, 39708, 'ミシンで子供の服を作った。', 'ミシンで こどもの ふくを つくった。', 'Tôi dùng máy may may quần áo cho con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1103, 39735, '雨の日はレインコートを着て自転車に乗る。', 'あめの ひは レインコートを きて じてんしゃに のる。', 'Ngày mưa tôi mặc áo mưa đi xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1104, 39785, '工場の煙突から煙が出ている。', 'こうじょうの えんとつから けむりが でて いる。', 'Khói bốc ra từ ống khói nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1105, 43668, 'はじめまして。リンと申します。', 'はじめまして。リンと もうします。', 'Rất vui được gặp anh. Tôi tên là Linh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1106, 43652, 'ごはんの前に手を洗います。', 'ごはんの まえに てを あらいます。', 'Tôi rửa tay trước bữa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1107, 43648, '朝、顔を洗います。', 'あさ、かおを あらいます。', 'Buổi sáng tôi rửa mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1108, 43650, '象は耳が大きいです。', 'ぞうは みみが おおきい です。', 'Voi có đôi tai to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1109, 43653, 'たくさん歩いて、足が痛いです。', 'たくさん あるいて、あしが いたい です。', 'Đi bộ nhiều nên đau chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1110, 27856, '毎日漢字を五つ覚えます。', 'まいにち かんじを いつつ おぼえます。', 'Mỗi ngày tôi nhớ năm chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1111, 43656, 'どこに住んでいますか。', 'どこに すんで いますか。', 'Bạn sống ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1112, 43658, 'あの人の名前を知っていますか。', 'あの ひとの なまえを しって いますか。', 'Bạn có biết tên người kia không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1113, 43660, '母と電話で話しました。', 'ははと でんわで はなしました。', 'Tôi đã nói chuyện điện thoại với mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1114, 43662, '皆さん、お元気ですか。', 'みなさん、おげんき ですか。', 'Mọi người có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1115, 43665, '日本の人は親切です。', 'にほんの ひとは しんせつ です。', 'Người Nhật rất tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1116, 43666, '私は音楽が好きです。', 'わたしは おんがくが すき です。', 'Tôi thích âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1117, 43669, '私の家は駅から遠いです。', 'わたしの いえは えきから とおい です。', 'Nhà tôi ở xa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1118, 39817, '家主に家賃を払った。', 'やぬしに やちんを はらった。', 'Tôi đã trả tiền thuê cho chủ nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1119, 39856, '庭の垣根に花が咲いている。', 'にわの かきねに はなが さいて いる。', 'Hoa nở trên hàng rào vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1120, 39886, '天気がいいので、布団を干した。', 'てんきが いいので、ふとんを ほした。', 'Trời đẹp nên tôi phơi chăn đệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1121, 39909, 'お客様を客間にお通しした。', 'おきゃくさまを きゃくまに おとおし した。', 'Tôi mời khách vào phòng khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1122, 39956, '台所の蛍光灯が切れた。', 'だいどころの けいこうとうが きれた。', 'Đèn huỳnh quang trong bếp bị cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1123, 39999, '紙を糊で貼った。', 'かみを のりで はった。', 'Tôi dán tờ giấy bằng hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1124, 40052, '公園の腰掛けに座って休んだ。', 'こうえんの こしかけに すわって やすんだ。', 'Tôi ngồi nghỉ trên ghế ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1125, 40059, '旅館の座敷で食事をした。', 'りょかんの ざしきで しょくじを した。', 'Chúng tôi dùng bữa trong phòng tatami ở lữ quán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1126, 40073, 'トラックで材木を運んだ。', 'トラックで ざいもくを はこんだ。', 'Chúng tôi chở gỗ bằng xe tải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1127, 40110, '食後の歯磨きを忘れないで。', 'しょくごの はみがきを わすれないで。', 'Đừng quên đánh răng sau bữa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1128, 40135, '車を車庫に入れた。', 'くるまを しゃこに いれた。', 'Tôi cho xe vào ga ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1129, 40147, '祭りで手拭いを頭に巻いた。', 'まつりで てぬぐいを あたまに まいた。', 'Ở lễ hội tôi quấn khăn tenugui lên đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1130, 40150, '庭の手入れは父の担当だ。', 'にわの ていれは ちちの たんとうだ。', 'Việc chăm sóc vườn là phần của bố tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1131, 40165, 'お住まいはどちらですか。', 'おすまいは どちら ですか。', 'Anh sống ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1132, 40182, '出入口の前に物を置かないでください。', 'でいりぐちの まえに ものを おかないで ください。', 'Xin đừng để đồ trước cửa ra vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1133, 40219, '猫が障子に穴をあけた。', 'ねこが しょうじに あなを あけた。', 'Con mèo chọc thủng cửa giấy shoji.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1134, 40231, 'クリスマスの飾りを片付けた。', 'クリスマスの かざりを かたづけた。', 'Tôi dọn đồ trang trí Giáng sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1135, 40238, '寝巻に着替えて、ベッドに入った。', 'ねまきに きがえて、ベッドに はいった。', 'Tôi thay đồ ngủ rồi lên giường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1136, 42924, '子供のころ、団地に住んでいた。', 'こどもの ころ、だんちに すんで いた。', 'Hồi nhỏ tôi sống ở khu chung cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1137, 43077, '大学の敷地はとても広い。', 'だいがくの しきちは とても ひろい。', 'Khuôn viên trường đại học rất rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1138, 43151, '毛糸でマフラーを編んだ。', 'けいとで マフラーを あんだ。', 'Tôi đan khăn quàng bằng len.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1139, 43189, 'このセーターは羊毛百パーセントだ。', 'この セーターは ようもう ひゃくパーセントだ。', 'Chiếc áo len này làm 100% từ lông cừu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1140, 43211, '猫の首に鈴をつけた。', 'ねこの くびに すずを つけた。', 'Tôi đeo chuông nhỏ vào cổ con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1141, 43214, '駅は赤い煉瓦の建物だ。', 'えきは あかい れんがの たてものだ。', 'Nhà ga là một tòa nhà gạch đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1142, 27068, 'トイレはそこです。', 'トイレは そこ です。', 'Nhà vệ sinh ở chỗ đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1143, 27067, 'ここは食堂です。', 'ここは しょくどう です。', 'Đây là nhà ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1144, 44101, '棚の上に本があります。', 'たなの うえに ほんが あります。', 'Trên giá có sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1145, 27404, 'このケーキはとてもおいしいです。', 'この ケーキは とても おいしい です。', 'Chiếc bánh này rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1146, 43672, '母は台所で料理をしています。', 'ははは だいどころで りょうりを して います。', 'Mẹ đang nấu ăn trong bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1147, 39727, '卵を十分茹でた。', 'たまごを じゅっぷん ゆでた。', 'Tôi luộc trứng mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1148, 39788, 'このスープは少し塩辛い。', 'この スープは すこし しおからい。', 'Món súp này hơi mặn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1149, 39879, '昔はご飯を釜で炊いていた。', 'むかしは ごはんを かまで たいて いた。', 'Ngày xưa người ta nấu cơm bằng nồi gang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1150, 40048, '玉ねぎを細かく刻んだ。', 'たまねぎを こまかく きざんだ。', 'Tôi băm nhỏ hành tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1151, 40151, '仕事帰りに駅前の酒場に寄った。', 'しごとがえりに えきまえの さかばに よった。', 'Tan làm tôi ghé quán rượu trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1152, 40215, 'パンが焦げて、真っ黒になった。', 'パンが こげて、まっくろに なった。', 'Bánh mì bị cháy đen thui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1153, 40234, '食塩を少し加えてください。', 'しょくえんを すこし くわえて ください。', 'Hãy thêm một chút muối ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1154, 42900, '会社の近くでランチを食べた。', 'かいしゃの ちかくで ランチを たべた。', 'Tôi ăn trưa gần công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1155, 43072, 'ジャムを瓶詰にして保存した。', 'ジャムを びんづめに して ほぞん した。', 'Tôi cho mứt vào lọ để bảo quản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1156, 39595, '駅ビルの中に新しいショップができた。', 'えきビルの なかに あたらしい ショップが できた。', 'Trong tòa nhà ga có cửa hàng mới mở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1157, 39676, '駅前に高いビルディングが建った。', 'えきまえに たかい ビルディングが たった。', 'Trước ga đã mọc lên một tòa nhà cao tầng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1158, 39729, 'ラッシュアワーの電車は本当に混む。', 'ラッシュアワーの でんしゃは ほんとうに こむ。', 'Tàu giờ cao điểm thật sự rất đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1159, 39776, 'この町には古い運河が流れている。', 'この まちには ふるい うんがが ながれて いる。', 'Thị trấn này có con kênh đào cổ chảy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1160, 27124, '授業は三時に終わります。', 'じゅぎょうは さんじに おわります。', 'Giờ học kết thúc lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1161, 27130, '今、何時ですか。', 'いま、なんじ ですか。', 'Bây giờ là mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1162, 27132, '今、九時五分です。', 'いま、くじ ごふん です。', 'Bây giờ là chín giờ năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1163, 43703, 'この靴はいくらですか。', 'この くつは いくら ですか。', 'Đôi giày này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1164, 27133, '七時半に起きます。', 'しちじ はんに おきます。', 'Tôi dậy lúc bảy giờ rưỡi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1165, 43705, '箱の中に何がありますか。', 'はこの なかに なにが ありますか。', 'Trong hộp có gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1166, 43706, '箱の中に何か物があります。', 'はこの なかに なにか ものが あります。', 'Trong hộp có đồ vật gì đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1167, 43700, '財布を忘れました。', 'さいふを わすれました。', 'Tôi quên ví rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1168, 43707, '日曜日に部屋の掃除をします。', 'にちようびに へやの そうじを します。', 'Chủ nhật tôi dọn dẹp phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1169, 43708, '毎朝洗濯をします。', 'まいあさ せんたくを します。', 'Sáng nào tôi cũng giặt đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1170, 43710, 'あしたは五時に起きます。', 'あしたは ごじに おきます。', 'Ngày mai tôi dậy lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1171, 43711, '窓を開けてください。', 'まどを あけて ください。', 'Hãy mở cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1172, 43713, '暗いですから、電気をつけましょう。', 'くらい ですから、でんきを つけましょう。', 'Tối quá, bật đèn lên đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1173, 43715, 'かばんは机の上に置いてください。', 'かばんは つくえの うえに おいて ください。', 'Hãy để cặp lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1174, 43718, '朝、シャワーを浴びます。', 'あさ、シャワーを あびます。', 'Buổi sáng tôi tắm vòi sen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1175, 43720, '部屋に入る前に靴を脱ぎます。', 'へやに はいる まえに くつを ぬぎます。', 'Trước khi vào phòng tôi cởi giày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1176, 43721, 'この公園は広いです。', 'この こうえんは ひろい です。', 'Công viên này rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1177, 27412, 'もう本です［ね］。', 'もうほんです［ね］。', 'It''s already sách[, isn''t it?]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1178, 27413, 'そろそろ失礼します。', 'そろそろしつれいします。', 'Đến lúc tôi phải về rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1179, 27415, 'またいらっしゃってください。', 'またいらっしゃってください。', 'Lần sau anh( chị', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1180, 39801, '次の駅で下車してください。', 'つぎの えきで げしゃ して ください。', 'Xin hãy xuống tàu ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1181, 39824, '港で貨物を船に積んでいる。', 'みなとで かもつを ふねに つんで いる。', 'Ở cảng người ta đang chất hàng lên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1182, 39833, 'バスの回数券を買うと、少し安くなる。', 'バスの かいすうけんを かうと、すこし やすく なる。', 'Mua vé tập xe buýt thì rẻ hơn một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1183, 39850, '新しいトンネルが開通した。', 'あたらしい トンネルが かいつう した。', 'Đường hầm mới đã thông xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1184, 39859, '全国各地から人が集まった。', 'ぜんこく かくちから ひとが あつまった。', 'Mọi người từ khắp nơi trên cả nước tụ về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1185, 39901, '古い機関車が博物館に展示されている。', 'ふるい きかんしゃが はくぶつかんに てんじ されて いる。', 'Đầu máy xe lửa cũ được trưng bày ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1186, 39983, 'トマトは南アメリカ原産だ。', 'トマトは みなみアメリカ げんさんだ。', 'Cà chua có nguồn gốc từ Nam Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1187, 40042, '高層ビルの最上階にレストランがある。', 'こうそう ビルの さいじょうかいに レストランが ある。', 'Trên tầng cao nhất của tòa nhà cao tầng có nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1188, 40114, '新幹線は時速三百キロで走る。', 'しんかんせんは じそく さんびゃくキロで はしる。', 'Tàu Shinkansen chạy với tốc độ 300 km/giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1189, 40137, '自転車の車輪に空気を入れた。', 'じてんしゃの しゃりんに くうきを いれた。', 'Tôi bơm hơi bánh xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1190, 40158, 'このバスの終点は空港です。', 'この バスの しゅうてんは くうこう です。', 'Điểm cuối của tuyến xe buýt này là sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1191, 40220, '上りの電車は混んでいる。', 'のぼりの でんしゃは こんで いる。', 'Tàu hướng về trung tâm đang đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1192, 40225, 'ご乗車ありがとうございます。', 'ごじょうしゃ ありがとう ございます。', 'Cảm ơn quý khách đã lên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1193, 27409, 'A：いい天気ですね。B：そうですね。', 'エー：いい てんき ですね。ビー：そう ですね。', 'A: Thời tiết đẹp nhỉ. B: Đúng vậy nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1194, 43734, 'スーパーで肉を買いました。', 'スーパーで にくを かいました。', 'Tôi đã mua thịt ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1195, 43736, '毎日野菜を食べます。', 'まいにち やさいを たべます。', 'Ngày nào tôi cũng ăn rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1196, 43738, '毎朝、卵を一つ食べます。', 'まいあさ、たまごを ひとつ たべます。', 'Sáng nào tôi cũng ăn một quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1197, 27407, '日本の食べ物はおいしいですが、高いです。', 'にほんの たべものは おいしい ですが、たかい です。', 'Đồ ăn Nhật ngon nhưng đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1198, 27408, 'お久しぶりです。お元気ですか。', 'おひさしぶり です。おげんき ですか。', 'Lâu rồi không gặp. Anh có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1199, 43733, '日本料理が好きです。', 'にほん りょうりが すき です。', 'Tôi thích món ăn Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1200, 43724, '外はもう暗いです。', 'そとは もう くらい です。', 'Bên ngoài đã tối rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1201, 43726, 'この町には古いお寺があります。', 'この まちには ふるい おてらが あります。', 'Thị trấn này có một ngôi chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1202, 43729, 'ご飯を食べましたか。', 'ごはんを たべましたか。', 'Bạn ăn cơm chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1203, 43730, '毎朝、朝ご飯を食べます。', 'まいあさ、あさごはんを たべます。', 'Sáng nào tôi cũng ăn sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1204, 43732, '晩ご飯は何を食べましたか。', 'ばんごはんは なにを たべましたか。', 'Bữa tối bạn đã ăn gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1205, 27252, 'たばこを吸います。', 'たばこをすいます。', 'Hút [thuốc lá]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1206, 40124, '今日は湿度が高くて、蒸し暑い。', 'きょうは しつどが たかくて、むしあつい。', 'Hôm nay độ ẩm cao nên oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1207, 39892, '今夜は流れ星の観測に最適だ。', 'こんやは ながれぼしの かんそくに さいてきだ。', 'Đêm nay rất lý tưởng để quan sát sao băng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1208, 42898, '冬は雪用のタイヤに替える。', 'ふゆは ゆきようの タイヤに かえる。', 'Mùa đông tôi thay lốp đi tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1209, 42976, '電車が川の鉄橋を渡っている。', 'でんしゃが かわの てっきょうを わたって いる。', 'Tàu điện đang chạy qua cầu sắt bắc ngang sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1210, 42984, '車が電柱にぶつかった。', 'くるまが でんちゅうに ぶつかった。', 'Chiếc xe đâm vào cột điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1211, 43043, '駅の売店で新聞を買った。', 'えきの ばいてんで しんぶんを かった。', 'Tôi mua báo ở quầy hàng trong ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1212, 43093, '公園の噴水で子供たちが遊んでいる。', 'こうえんの ふんすいで こどもたちが あそんで いる。', 'Bọn trẻ đang chơi bên đài phun nước trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1213, 43181, 'よその家に行ったら、きちんとあいさつしなさい。', 'よその いえに いったら、きちんと あいさつ しなさい。', 'Đến nhà người khác thì phải chào hỏi đàng hoàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1214, 39584, '犬がうれしそうにしっぽを振っている。', 'いぬが うれしそうに しっぽを ふって いる。', 'Con chó vẫy đuôi trông rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1781, 44189, '試合に勝ちました。', 'しあいに かちました。', 'Chúng tôi đã thắng trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1215, 39774, 'お正月に羽根つきをして遊んだ。', 'おしょうがつに はねつきを して あそんだ。', 'Dịp Tết chúng tôi chơi đánh cầu hanetsuki.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1216, 39781, '母の趣味は園芸です。', 'ははの しゅみは えんげい です。', 'Sở thích của mẹ tôi là làm vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1217, 39799, '日本の大部分は温帯にある。', 'にほんの だいぶぶんは おんたいに ある。', 'Phần lớn Nhật Bản nằm trong vùng ôn đới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1218, 39826, '夏の夜は蚊が多くて眠れない。', 'なつの よるは かが おおくて ねむれない。', 'Đêm hè nhiều muỗi quá, không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1219, 39884, '寒帯の地域では一年中寒い。', 'かんたいの ちいきでは いちねんじゅう さむい。', 'Ở vùng hàn đới thì lạnh quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1220, 40038, 'この山ではいろいろな鉱物がとれる。', 'この やまでは いろいろな こうぶつが とれる。', 'Ngọn núi này khai thác được nhiều loại khoáng vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1221, 40123, '梅雨の時期は湿気が多い。', 'つゆの じきは しっけが おおい。', 'Mùa mưa độ ẩm cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1222, 40217, '朝から太陽が照っている。', 'あさから たいようが てって いる。', 'Mặt trời chiếu sáng từ sáng sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1223, 40230, '暑さでプールの水が蒸発した。', 'あつさで プールの みずが じょうはつ した。', 'Trời nóng làm nước hồ bơi bốc hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1224, 40270, '吹雪で前が見えない。', 'ふぶきで まえが みえない。', 'Bão tuyết làm không nhìn thấy phía trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1225, 40276, '窓に水滴がついている。', 'まどに すいてきが ついて いる。', 'Trên cửa kính đọng những giọt nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1226, 40280, '水平線から朝日が昇ってきた。', 'すいへいせんから あさひが のぼって きた。', 'Mặt trời buổi sáng nhô lên từ đường chân trời trên biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1227, 42921, 'この魚は淡水にすんでいる。', 'この さかなは たんすいに すんで いる。', 'Loài cá này sống ở nước ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1228, 42981, '田んぼでカエルが鳴いている。', 'たんぼで カエルが ないて いる。', 'Ếch kêu ngoài ruộng lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1229, 43791, '教室は三階です。', 'きょうしつは さんがい です。', 'Lớp học ở tầng ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1230, 43789, '毎日、歩いて学校へ行きます。', 'まいにち、あるいて がっこうへ いきます。', 'Ngày nào tôi cũng đi bộ đến trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1231, 43792, '図書館で本を借りました。', 'としょかんで ほんを かりました。', 'Tôi đã mượn sách ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1232, 27361, 'ここはハンサムです。', 'ここはハンサムです。', 'Ở đây đẹp trai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1233, 27362, 'ここはきれいです。', 'ここはきれいです。', 'Ở đây beautiful.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1234, 27363, 'ここは静かです。', 'ここはしずかです。', 'Ở đây yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1235, 27364, 'ここはにぎやかです。', 'ここはにぎやかです。', 'Ở đây nhộn nhịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1236, 27365, 'ここは有名です。', 'ここはゆうめいです。', 'Ở đây nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1237, 27366, 'ここは親切です。', 'ここはしんせつです。', 'Ở đây tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1238, 43150, '庭に草が茂っている。', 'にわに くさが しげって いる。', 'Cỏ mọc um tùm trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1239, 43101, '関東平野は日本で一番広い平野だ。', 'かんとう へいやは にほんで いちばん ひろい へいやだ。', 'Đồng bằng Kanto là đồng bằng rộng nhất Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1240, 43125, 'お城の周りには堀がある。', 'おしろの まわりには ほりが ある。', 'Xung quanh lâu đài có hào nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1241, 43136, '岬から見る夕日はきれいだ。', 'みさきから みる ゆうひは きれいだ。', 'Hoàng hôn nhìn từ mũi đất rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1242, 43178, '夕立にあって、服がぬれた。', 'ゆうだちに あって、ふくが ぬれた。', 'Gặp cơn mưa rào chiều, quần áo ướt hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1243, 43191, '夏の日差しは強いので、帽子をかぶろう。', 'なつの ひざしは つよいので、ぼうしを かぶろう。', 'Nắng hè gắt nên hãy đội mũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1244, 43217, '山の麓に小さな村がある。', 'やまの ふもとに ちいさな むらが ある。', 'Dưới chân núi có một ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1245, 39561, 'こないだはありがとう。', 'こないだは ありがとう。', 'Cảm ơn bạn chuyện hôm nọ nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1246, 39579, 'しあさってから旅行に行く。', 'しあさってから りょこうに いく。', 'Ba ngày nữa tôi đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1247, 39745, '十時以後は静かにしてください。', 'じゅうじ いごは しずかに して ください。', 'Sau mười giờ xin hãy giữ yên lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1248, 39756, '一昨年、会社に入りました。', 'いっさくねん、かいしゃに はいりました。', 'Năm kia tôi vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1249, 39802, '三月下旬に桜が咲く。', 'さんがつ げじゅんに さくらが さく。', 'Hoa anh đào nở vào hạ tuần tháng ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1250, 39984, '原始の人々は火を使い始めた。', 'げんしの ひとびとは ひを つかいはじめた。', 'Người nguyên thủy bắt đầu biết dùng lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1251, 40191, '四月初旬に入学式がある。', 'しがつ しょじゅんに にゅうがくしきが ある。', 'Đầu tháng tư có lễ nhập học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1252, 43027, '会議の日時が決まったら教えてください。', 'かいぎの にちじが きまったら おしえて ください。', 'Khi chốt ngày giờ họp thì báo tôi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1253, 43028, '旅行の日程を変更した。', 'りょこうの にっていを へんこう した。', 'Tôi đã thay đổi lịch trình du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1254, 43131, '毎度ありがとうございます。', 'まいど ありがとう ございます。', 'Luôn cảm ơn quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1255, 43795, '試験は九時からです。', 'しけんは くじから です。', 'Kỳ thi bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1256, 27417, '金閣寺はとてもきれいなお寺です。', 'きんかくじは とても きれいな おてら です。', 'Kinkakuji là ngôi chùa rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1257, 27418, '奈良公園に鹿がたくさんいます。', 'なら こうえんに しかが たくさん います。', 'Công viên Nara có rất nhiều hươu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1258, 27422, '日本語の勉強は楽しいです。', 'にほんごの べんきょうは たのしい です。', 'Việc học tiếng Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1259, 27423, 'ミラーさんの傘はどれですか。', 'ミラーさんの かさは どれ ですか。', 'Ô của anh Miller là cái nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1260, 43793, '授業は九時に始まります。', 'じゅぎょうは くじに はじまります。', 'Giờ học bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1261, 27424, '日本の生活に慣れましたか。', 'にほんのせいかつになれましたか。', 'Đã quen với cuộc sống Nhật Bản chưa ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1262, 40043, 'この仕事には高度な技術が必要だ。', 'この しごとには こうどな ぎじゅつが ひつようだ。', 'Công việc này đòi hỏi kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1263, 39652, '車のナンバーを覚えていますか。', 'くるまの ナンバーを おぼえて いますか。', 'Bạn có nhớ biển số xe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1264, 39710, '昨日は百ミリの雨が降った。', 'きのうは ひゃくミリの あめが ふった。', 'Hôm qua mưa một trăm mi-li-mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1265, 39760, '資料に一通り目を通した。', 'しりょうに ひととおり めを とおした。', 'Tôi đã xem qua tài liệu một lượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1266, 39832, '運動の回数を少しずつ増やしている。', 'うんどうの かいすうを すこしずつ ふやして いる。', 'Tôi tăng dần số lần tập thể dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1267, 39857, '各々の意見を聞かせてください。', 'おのおのの いけんを きかせて ください。', 'Hãy cho tôi nghe ý kiến của từng người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1268, 40285, 'カーテンの寸法を測った。', 'カーテンの すんぽうを はかった。', 'Tôi đo kích thước rèm cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1269, 43084, '複数の会社から内定をもらった。', 'ふくすうの かいしゃから ないていを もらった。', 'Tôi nhận được thư mời làm việc từ nhiều công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1270, 43091, '砂糖の分量を間違えて、甘すぎた。', 'さとうの ぶんりょうを まちがえて、あますぎた。', 'Tôi nhầm lượng đường nên ngọt quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1271, 43130, 'コピーの枚数を確認してください。', 'コピーの まいすうを かくにん して ください。', 'Hãy kiểm tra số bản photo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1272, 43135, '十八歳未満の人はお酒を買えない。', 'じゅうはっさい みまんの ひとは おさけを かえない。', 'Người dưới mười tám tuổi không được mua rượu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1273, 43140, '夜空に無数の星が輝いている。', 'よぞらに むすうの ほしが かがやいて いる。', 'Vô số vì sao lấp lánh trên bầu trời đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1274, 43183, 'この冷蔵庫の容積は四百リットルだ。', 'この れいぞうこの ようせきは よんひゃく リットルだ。', 'Dung tích chiếc tủ lạnh này là 400 lít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1275, 31575, '電車でお年寄りに席を譲った。', 'でんしゃで おとしよりに せきを ゆずった。', 'Tôi nhường ghế cho người già trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1276, 31623, 'チームの守備を強化する必要がある。', 'チームの しゅびを きょうか する ひつようが ある。', 'Cần củng cố hàng phòng ngự của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1277, 31672, '電車の中で騒がないでください。', 'でんしゃの なかで さわがないで ください。', 'Xin đừng làm ồn trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1278, 39556, '母が弁当をこしらえてくれた。', 'ははが べんとうを こしらえて くれた。', 'Mẹ làm cơm hộp cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1279, 39562, 'コーヒーをシャツにこぼしてしまった。', 'コーヒーを シャツに こぼして しまった。', 'Tôi làm đổ cà phê lên áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1280, 39606, '工事は雨でストップしている。', 'こうじは あめで ストップ して いる。', 'Công trình đang tạm dừng vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1281, 43843, 'あした暇ですか。', 'あした ひま ですか。', 'Ngày mai bạn rảnh không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1282, 43835, '疲れたので、少し休みます。', 'つかれたので、すこし やすみます。', 'Mệt rồi nên tôi nghỉ một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1283, 43837, 'ペンを貸してください。', 'ペンを かして ください。', 'Cho tôi mượn cây bút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1284, 43839, '図書館に本を返します。', 'としょかんに ほんを かえします。', 'Tôi trả sách cho thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1285, 43840, '漢字は難しいです。', 'かんじは むずかしい です。', 'Chữ Hán khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1286, 43842, '今週はとても忙しいです。', 'こんしゅうは とても いそがしい です。', 'Tuần này tôi rất bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1287, 43845, '私は料理が下手です。', 'わたしは りょうりが へた です。', 'Tôi nấu ăn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1288, 29668, 'このりんごはよいです。', 'このりんごはよいです。', 'Quả táo này tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1289, 39763, '話が逸れてしまったので、元に戻そう。', 'はなしが それて しまったので、もとに もどそう。', 'Câu chuyện lạc đề rồi, quay lại vấn đề chính thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1290, 39765, '凧が木に引っ掛かった。', 'たこが きに ひっかかった。', 'Con diều bị mắc trên cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1291, 39767, '強い風で自転車が引っくり返った。', 'つよい かぜで じてんしゃが ひっくりかえった。', 'Gió mạnh làm chiếc xe đạp đổ nhào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1292, 39789, '車のドアが凹んでしまった。', 'くるまの ドアが へこんで しまった。', 'Cửa xe bị móp mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1293, 39793, '傷口をタオルで押さえた。', 'きずぐちを タオルで おさえた。', 'Tôi dùng khăn đè lên vết thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1294, 39834, 'この店は回転が速いので、すぐ座れる。', 'この みせは かいてんが はやいので、すぐ すわれる。', 'Quán này khách ra vào nhanh nên có chỗ ngồi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1295, 39851, '天気予報が外れて、雨が降った。', 'てんき よほうが はずれて、あめが ふった。', 'Dự báo thời tiết sai, trời đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1296, 43849, '今、何時ですか。', 'いま、なんじ ですか。', 'Bây giờ là mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1297, 43853, '七時半に起きます。', 'しちじ はんに おきます。', 'Tôi dậy lúc bảy giờ rưỡi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1298, 43856, '朝、コーヒーを飲みます。', 'あさ、コーヒーを のみます。', 'Buổi sáng tôi uống cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1299, 43858, '晩、家族と話します。', 'ばん、かぞくと はなします。', 'Buổi tối tôi trò chuyện với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1300, 43859, '夜は家で本を読みます。', 'よるは いえで ほんを よみます。', 'Buổi tối tôi đọc sách ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1301, 43865, '今週は忙しいです。', 'こんしゅうは いそがしい です。', 'Tuần này tôi bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1302, 43866, '来週、試験があります。', 'らいしゅう、しけんが あります。', 'Tuần sau có kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1303, 43868, '今月の十日は休みです。', 'こんげつの とおかは やすみ です。', 'Ngày mười tháng này được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1304, 43870, '去年、結婚しました。', 'きょねん、けっこん しました。', 'Năm ngoái tôi đã kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1305, 43873, '水曜日は図書館が休みです。', 'すいようびは としょかんが やすみ です。', 'Thứ Tư thư viện nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1306, 43874, '木曜日に会議があります。', 'もくようびに かいぎが あります。', 'Thứ Năm có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1307, 43876, '土曜日はテニスをします。', 'どようびは テニスを します。', 'Thứ Bảy tôi chơi tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1308, 43850, 'きょうは時間がありません。', 'きょうは じかんが ありません。', 'Hôm nay tôi không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1309, 27399, '駅の近くにいいレストランがあります。', 'えきの ちかくに いい レストランが あります。', 'Gần ga có một nhà hàng ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1310, 27416, 'シャンハイは大きい町です。', 'シャンハイは おおきい まち です。', 'Thượng Hải là một thành phố lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1311, 43879, '春は桜がきれいです。', 'はるは さくらが きれい です。', 'Mùa xuân hoa anh đào rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1312, 43881, '秋は涼しくて、気持ちがいいです。', 'あきは すずしくて、きもちが いい です。', 'Mùa thu mát mẻ, dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1313, 43882, '冬はとても寒いです。', 'ふゆは とても さむい です。', 'Mùa đông rất lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1314, 43878, '週末は何をしますか。', 'しゅうまつは なにを しますか。', 'Cuối tuần bạn làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1315, 43851, '毎朝七時に起きます。', 'まいあさ しちじに おきます。', 'Sáng nào tôi cũng dậy lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1316, 43852, '駅まで五分です。', 'えきまで ごふん です。', 'Đến ga mất năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1317, 43861, '明日、友達に会います。', 'あした、ともだちに あいます。', 'Ngày mai tôi gặp bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1318, 27428, 'ここは好きです。', 'ここはすきです。', 'Ở đây thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1319, 27429, 'ここは嫌いです。', 'ここはきらいです。', 'Ở đây ghét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1320, 27430, 'ここは上手です。', 'ここはじょうずです。', 'Ở đây giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1321, 27539, '子どもがいます。', 'こどもがいます。', 'Có (động vật)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1322, 27431, 'ここは下手です。', 'ここはへたです。', 'Ở đây kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1323, 39896, '私を含めて十人が参加した。', 'わたしを ふくめて じゅうにんが さんか した。', 'Tính cả tôi có mười người tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1324, 39908, '鼻が詰まって、においがわからない。', 'はなが つまって、においが わからない。', 'Mũi bị nghẹt nên không ngửi thấy mùi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1325, 40008, '子供たちに交じって、大人もゲームを楽しんだ。', 'こどもたちに まじって、おとなも ゲームを たのしんだ。', 'Người lớn cũng lẫn vào đám trẻ cùng chơi trò chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1326, 40045, '二つの学校が合同で運動会を開いた。', 'ふたつの がっこうが ごうどうで うんどうかいを ひらいた。', 'Hai trường cùng tổ chức chung hội thao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1327, 40053, 'ベンチに腰掛けて休んだ。', 'ベンチに こしかけて やすんだ。', 'Tôi ngồi xuống ghế băng nghỉ ngơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1328, 40064, 'うるさくて、耳を塞いだ。', 'うるさくて、みみを ふさいだ。', 'Ồn quá nên tôi bịt tai lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1329, 40067, '氷を細かく砕いてジュースに入れた。', 'こおりを こまかく くだいて ジュースに いれた。', 'Tôi đập nhỏ đá rồi cho vào nước ép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1330, 40075, '鉛筆をナイフで削った。', 'えんぴつを ナイフで けずった。', 'Tôi gọt bút chì bằng dao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1331, 43910, '電車で会社へ行きます。', 'でんしゃで かいしゃへ いきます。', 'Tôi đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1332, 43912, '新幹線で大阪へ行きます。', 'しんかんせんで おおさかへ いきます。', 'Tôi đi Osaka bằng tàu Shinkansen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1333, 43884, 'きのうは雨でした。', 'きのうは あめ でした。', 'Hôm qua trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1334, 43885, '北海道は雪が多いです。', 'ほっかいどうは ゆきが おおい です。', 'Hokkaido có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1335, 43903, '時々、映画を見ます。', 'ときどき、えいがを みます。', 'Thỉnh thoảng tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1336, 43906, 'いいえ、まだです。', 'いいえ、まだ です。', 'Chưa, tôi vẫn chưa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1337, 27432, 'どんな飲み物が好きですか。', 'どんな のみものが すき ですか。', 'Bạn thích đồ uống gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1338, 43889, 'あしたは曇りでしょう。', 'あしたは くもり でしょう。', 'Ngày mai có lẽ trời nhiều mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1339, 43905, 'すぐ来てください。', 'すぐ きて ください。', 'Hãy đến ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1340, 43908, 'だんだん寒くなりました。', 'だんだん さむく なりました。', 'Trời dần dần lạnh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1341, 43887, '空がとても青いです。', 'そらが とても あおい です。', 'Bầu trời rất xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1342, 43890, '今日はとても暑いですね。', 'きょうは とても あつい ですね。', 'Hôm nay nóng quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1343, 43892, '春になって、暖かくなりました。', 'はるに なって、あたたかく なりました。', 'Sang xuân trời ấm lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1345, 43896, '午後から晴れるでしょう。', 'ごごから はれるでしょう。', 'Từ chiều có lẽ trời sẽ nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1346, 43898, '父は朝が早いです。', 'ちちは あさが はやい です。', 'Bố tôi dậy sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1347, 43900, 'この川はとても長いです。', 'この かわは とても ながい です。', 'Con sông này rất dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1348, 43909, '駅まで歩いて十分です。', 'えきまで あるいて じゅっぷん です。', 'Đi bộ đến ga mất mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1349, 40112, '当日は筆記用具を持参してください。', 'とうじつは ひっき ようぐを じさん して ください。', 'Hôm đó xin mang theo dụng cụ viết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1350, 40142, 'かばんから財布を取り出した。', 'かばんから さいふを とりだした。', 'Tôi lấy ví ra khỏi túi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1351, 40160, '子供たちがボールを蹴って遊んでいる。', 'こどもたちが ボールを けって あそんで いる。', 'Bọn trẻ đang đá bóng chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1352, 40169, 'お皿を重ねて棚にしまった。', 'おさらを かさねて たなに しまった。', 'Tôi chồng đĩa lên nhau rồi cất vào kệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1353, 40174, 'ズボンの丈を少し縮めてもらった。', 'ズボンの たけを すこし ちぢめて もらった。', 'Tôi nhờ người ta cắt ngắn ống quần một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1354, 40181, 'この部屋は関係者以外の出入りが禁止されている。', 'この へやは かんけいしゃ いがいの でいりが きんし されて いる。', 'Phòng này cấm người không phận sự ra vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1355, 40213, '暑さで体力を消耗した。', 'あつさで たいりょくを しょうもう した。', 'Trời nóng làm tôi hao tổn thể lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1356, 40218, '時間がないので、あいさつは省略します。', 'じかんが ないので、あいさつは しょうりゃく します。', 'Không có thời gian nên tôi xin lược phần chào hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1357, 40291, '出発の準備が整った。', 'しゅっぱつの じゅんびが ととのった。', 'Mọi chuẩn bị cho chuyến đi đã sẵn sàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1358, 42949, '車が通って、泥水が跳ねた。', 'くるまが とおって、どろみずが はねた。', 'Xe chạy qua làm nước bùn bắn tung tóe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1359, 42964, 'ゆでたじゃがいもを潰した。', 'ゆでた じゃがいもを つぶした。', 'Tôi nghiền khoai tây đã luộc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1360, 42966, 'エレベーターが急に停止した。', 'エレベーターが きゅうに ていし した。', 'Thang máy đột ngột dừng lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1361, 43023, '台所からカレーが匂ってくる。', 'だいどころから カレーが におって くる。', 'Mùi cà ri thoang thoảng từ bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1362, 43042, '駅前でチラシを配った。', 'えきまえで チラシを くばった。', 'Tôi phát tờ rơi trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1363, 43076, '部屋に布団を敷いた。', 'へやに ふとんを しいた。', 'Tôi trải nệm trong phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1364, 43118, '騒音が睡眠を妨げている。', 'そうおんが すいみんを さまたげて いる。', 'Tiếng ồn cản trở giấc ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1365, 43185, '砂糖をお湯に溶かした。', 'さとうを おゆに とかした。', 'Tôi hòa tan đường vào nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1366, 43201, '「パーソナルコンピューター」を略して「パソコン」と言う。', '「パーソナルコンピューター」を りゃくして 「パソコン」と いう。', 'Người ta viết tắt "personal computer" thành "pasokon".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1367, 38125, 'これは典型的な日本の朝ご飯だ。', 'これは てんけいてきな にほんの あさごはんだ。', 'Đây là bữa sáng điển hình kiểu Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1368, 39577, '朝の空気はさわやかだ。', 'あさの くうきは さわやかだ。', 'Không khí buổi sáng thật trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1369, 43925, '私の町は静かです。', 'わたしの まちは しずか です。', 'Thị trấn của tôi yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1370, 27438, 'どんな音楽が好きですか。', 'どんな おんがくが すき ですか。', 'Bạn thích loại nhạc nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1371, 27439, '日本の歌が好きです。', 'にほんの うたが すき です。', 'Tôi thích các bài hát Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1372, 43924, 'あの角に銀行があります。', 'あの かどに ぎんこうが あります。', 'Ở góc kia có ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1373, 43926, '日曜日、公園を散歩しました。', 'にちようび、こうえんを さんぽ しました。', 'Chủ nhật tôi đã đi dạo ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1374, 43928, '駅の近くに映画館があります。', 'えきの ちかくに えいがかんが あります。', 'Gần ga có rạp chiếu phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1375, 44102, '出かける前に鏡を見ます。', 'でかける まえに かがみを みます。', 'Trước khi ra ngoài tôi soi gương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1376, 46151, '地震で水の供給が止まった。', 'じしんで みずの きょうきゅうが とまった。', 'Động đất làm ngừng cung cấp nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1377, 46158, '今月は出費が多くて赤字だ。', 'こんげつは しゅっぴが おおくて あかじだ。', 'Tháng này chi tiêu nhiều nên bị thâm hụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1378, 46162, '不況で仕事を探すのが難しい。', 'ふきょうで しごとを さがすのが むずかしい。', 'Kinh tế suy thoái nên tìm việc rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1379, 46182, '交通費は会社から支給されます。', 'こうつうひは かいしゃから しきゅう されます。', 'Tiền đi lại do công ty chi trả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1380, 46163, '子供の成長は早い。', 'こどもの せいちょうは はやい。', 'Trẻ con lớn nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1381, 46165, '地図を拡大して見た。', 'ちずを かくだい して みた。', 'Tôi phóng to bản đồ ra để xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1382, 46145, '為替のレートは毎日変わる。', 'かわせの レートは まいにち かわる。', 'Tỷ giá hối đoái thay đổi mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1383, 46147, '円安で外国からの観光客が増えた。', 'えんやすで がいこくからの かんこうきゃくが ふえた。', 'Do đồng yên mất giá, khách du lịch nước ngoài tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1384, 46153, '消費者の声を聞いて商品を改善した。', 'しょうひしゃの こえを きいて しょうひんを かいぜん した。', 'Chúng tôi lắng nghe người tiêu dùng để cải tiến sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1385, 46155, 'この業界は競争が激しい。', 'この ぎょうかいは きょうそうが はげしい。', 'Ngành này cạnh tranh gay gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1386, 46157, '不況で多くの会社が倒産した。', 'ふきょうで おおくの かいしゃが とうさん した。', 'Do suy thoái, nhiều công ty đã phá sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1387, 46166, '会社は海外の事業を縮小した。', 'かいしゃは かいがいの じぎょうを しゅくしょう した。', 'Công ty đã thu hẹp hoạt động kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1388, 46168, '株価が大きく下落した。', 'かぶかが おおきく げらく した。', 'Giá cổ phiếu sụt giảm mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1389, 46170, '工事は来月終わる見込みだ。', 'こうじは らいげつ おわる みこみだ。', 'Công trình dự kiến xong vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1390, 46172, 'その会社は多額の負債を抱えている。', 'その かいしゃは たがくの ふさいを かかえて いる。', 'Công ty đó đang gánh khoản nợ lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1391, 46176, '引っ越しの見積もりを三社に頼んだ。', 'ひっこしの みつもりを さんしゃに たのんだ。', 'Tôi nhờ ba công ty báo giá chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1392, 46178, '夜にATMを使うと手数料がかかる。', 'よるに エーティーエムを つかうと てすうりょうが かかる。', 'Dùng ATM vào ban đêm sẽ mất phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1393, 46180, 'この商売は儲けが少ない。', 'この しょうばいは もうけが すくない。', 'Việc buôn bán này lời ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1394, 46183, '彼はこの仕事の経験が乏しい。', 'かれは この しごとの けいけんが とぼしい。', 'Anh ấy còn ít kinh nghiệm trong công việc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1395, 46187, '電車が大幅に遅れている。', 'でんしゃが おおはばに おくれて いる。', 'Tàu điện đang trễ rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1396, 39535, 'このシャツにはいろいろなカラーがある。', 'この シャツには いろいろな カラーが ある。', 'Chiếc áo này có nhiều màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1397, 39608, '彼は背が高くてスマートだ。', 'かれは せが たかくて スマートだ。', 'Anh ấy cao và mảnh khảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1398, 27446, '先生の字はきれいです。', 'せんせいの じは きれい です。', 'Chữ của thầy giáo rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1399, 27447, '漢字は難しいですが、おもしろいです。', 'かんじは むずかしい ですが、おもしろい です。', 'Chữ Hán khó nhưng thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1400, 27448, 'ひらがなで名前を書いてください。', 'ひらがなで なまえを かいて ください。', 'Hãy viết tên bằng chữ hiragana.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1401, 27450, 'ローマ字で住所を書きました。', 'ローマじで じゅうしょを かきました。', 'Tôi viết địa chỉ bằng chữ La-tinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1402, 43993, '兄は力が強いです。', 'あには ちからが つよい です。', 'Anh tôi rất khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1403, 43990, '体の具合はどうですか。', 'からだの ぐあいは どう ですか。', 'Sức khỏe của bạn thế nào rồi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1404, 43974, 'スキーで怪我をしました。', 'スキーで けがを しました。', 'Tôi bị thương khi trượt tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1405, 43982, '喉が渇きました。', 'のどが かわきました。', 'Tôi khát nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1406, 43994, '毎朝、軽い運動をしています。', 'まいあさ、かるい うんどうを して います。', 'Sáng nào tôi cũng vận động nhẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1407, 43996, '今晩一緒に食事をしませんか。', 'こんばん いっしょに しょくじを しませんか。', 'Tối nay cùng đi ăn không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1408, 44000, '病気で五キロ痩せました。', 'びょうきで ごキロ やせました。', 'Vì ốm mà tôi gầy đi năm ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1409, 44002, '早く風邪を治してください。', 'はやく かぜを なおして ください。', 'Mau khỏi cảm nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1410, 44004, '転んで、足の骨が折れました。', 'ころんで、あしの ほねが おれました。', 'Tôi ngã và bị gãy xương chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1411, 44006, '雨の日は膝が痛みます。', 'あめの ひは ひざが いたみます。', 'Ngày mưa đầu gối tôi đau nhức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1412, 44008, '気分が悪くて、吐いてしまいました。', 'きぶんが わるくて、はいて しまいました。', 'Thấy khó chịu nên tôi đã nôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1413, 44013, '母の病気が心配です。', 'ははの びょうきが しんぱい です。', 'Tôi lo cho bệnh của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1414, 43975, 'けがをして、一週間入院した。', 'けがを して、いっしゅうかん にゅういん した。', 'Tôi bị thương và phải nằm viện một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1415, 43992, '魚の骨がのどに刺さった。', 'さかなの ほねが のどに ささった。', 'Xương cá bị hóc trong cổ họng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1416, 44012, '痛くても、もう少し我慢してください。', 'いたくても、もう すこし がまん して ください。', 'Dù đau cũng hãy chịu đựng thêm chút nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1417, 39719, 'この町にはモダンな建物が多い。', 'この まちには モダンな たてものが おおい。', 'Thị trấn này có nhiều tòa nhà hiện đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1418, 39762, '一流のホテルに泊まってみたい。', 'いちりゅうの ホテルに とまって みたい。', 'Tôi muốn thử ở khách sạn hạng nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1419, 39786, 'この髪は艶があってきれいだ。', 'この かみは つやが あって きれいだ。', 'Mái tóc này bóng mượt rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1420, 39847, '空が灰色の雲に覆われている。', 'そらが はいいろの くもに おおわれて いる。', 'Bầu trời phủ đầy mây xám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1421, 39891, 'このズボンはウエストが緩い。', 'この ズボンは ウエストが ゆるい。', 'Cái quần này rộng eo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1422, 39904, 'この辺りで雪が降るのは稀だ。', 'この あたりで ゆきが ふるのは まれだ。', 'Ở vùng này hiếm khi có tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1423, 27453, 'きょうは時間がありません。', 'きょうは じかんが ありません。', 'Hôm nay tôi không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1424, 27454, 'あしたは用事があります。', 'あしたは ようじが あります。', 'Ngày mai tôi có việc bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1425, 43970, '病気で学校を休みました。', 'びょうきで がっこうを やすみました。', 'Tôi nghỉ học vì ốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1426, 43972, 'きのうから熱があります。', 'きのうから ねつが あります。', 'Từ hôm qua tôi bị sốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1427, 43980, '寝る前に歯を磨きます。', 'ねる まえに はを みがきます。', 'Trước khi ngủ tôi đánh răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1428, 43987, '妹は髪が長いです。', 'いもうとは かみが ながい です。', 'Em gái tôi tóc dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1429, 43978, '姉は病院の看護師です。', 'あねは びょういんの かんごし です。', 'Chị tôi là y tá ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1430, 43984, 'ナイフで指を切りました。', 'ナイフで ゆびを きりました。', 'Tôi bị dao cắt vào ngón tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1431, 43991, '指から血が出ています。', 'ゆびから ちが でて います。', 'Ngón tay đang chảy máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1432, 44401, '来週の予定はもう決まりましたか。', 'らいしゅうの よていは もう きまりましたか。', 'Kế hoạch tuần sau đã định chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1433, 27018, 'この本は面白いです。', 'このほんはおもしろいです。', 'Quyển sách này thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1434, 27019, 'そのかばんは大きいです。', 'そのかばんはおおきいです。', 'Cái cặp đó to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1435, 27020, 'あの人は日本人です。', 'あのひとはにほんじんです。', 'Người kia là người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1436, 43037, '葬式に派手な服は着ないほうがいい。', 'そうしきに はでな ふくは きない ほうが いい。', 'Không nên mặc đồ sặc sỡ đến đám tang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1437, 39910, '写真を逆さに貼ってしまった。', 'しゃしんを さかさに はって しまった。', 'Tôi lỡ dán ngược bức ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1438, 39986, '空港では厳重な検査が行われている。', 'くうこうでは げんじゅうな けんさが おこなわれて いる。', 'Ở sân bay việc kiểm tra được tiến hành nghiêm ngặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1439, 40046, '合理化で仕事の時間が短くなった。', 'ごうりかで しごとの じかんが みじかく なった。', 'Nhờ hợp lý hóa mà thời gian làm việc được rút ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1440, 40096, '四角いテーブルを買った。', 'しかくい テーブルを かった。', 'Tôi mua một cái bàn vuông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1441, 40132, 'この写真は少し斜めになっている。', 'この しゃしんは すこし ななめに なって いる。', 'Bức ảnh này hơi bị lệch chéo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1442, 40164, 'お金のことで醜い争いが起きた。', 'おかねの ことで みにくい あらそいが おきた。', 'Một cuộc tranh chấp xấu xí đã nổ ra vì tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1443, 27016, 'それは何ですか。', 'それは なん ですか。', 'Đó là cái gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1444, 43012, '警察は犯人を特定した。', 'けいさつは はんにんを とくてい した。', 'Cảnh sát đã xác định được thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1445, 43074, '不規則な生活は体に悪い。', 'ふきそくな せいかつは からだに わるい。', 'Sinh hoạt thất thường không tốt cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1446, 43086, '昨夜は物凄い雨だった。', 'ゆうべは ものすごい あめ だった。', 'Tối qua mưa khủng khiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1447, 43100, '平凡な毎日だけど、幸せだ。', 'へいぼんな まいにち だけど、しあわせだ。', 'Ngày nào cũng bình thường, nhưng tôi hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1448, 43160, '彼女は背が高いので、どこにいても目立つ。', 'かのじょは せが たかいので、どこに いても めだつ。', 'Cô ấy cao nên ở đâu cũng nổi bật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1449, 43208, '友達の言葉が力強く感じられた。', 'ともだちの ことばが ちからづよく かんじられた。', 'Lời của bạn khiến tôi thấy vững tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1450, 39509, '電車の中で大声で話さないのはエチケットだ。', 'でんしゃの なかで おおごえで はなさないのは エチケットだ。', 'Không nói to trên tàu là phép lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1451, 39524, '教会でオルガンの音が聞こえる。', 'きょうかいで オルガンの おとが きこえる。', 'Trong nhà thờ vang lên tiếng đàn organ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1452, 39554, '母は町のコーラスに参加している。', 'ははは まちの コーラスに さんか して いる。', 'Mẹ tôi tham gia đội hợp xướng của thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1453, 39568, 'ピアノのコンクールで一位になった。', 'ピアノの コンクールで いちいに なった。', 'Tôi giành giải nhất cuộc thi piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1454, 39604, 'ステージの上で歌を歌った。', 'ステージの うえで うたを うたった。', 'Tôi hát trên sân khấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1455, 39731, '音楽のリズムに合わせて手をたたいた。', 'おんがくの リズムに あわせて てを たたいた。', 'Tôi vỗ tay theo nhịp điệu của bản nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1456, 40262, '公園の池は人造の湖だ。', 'こうえんの いけは じんぞうの みずうみだ。', 'Cái ao trong công viên là hồ nhân tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1457, 44014, '歯が痛いです。', 'はが いたい です。', 'Tôi bị đau răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1458, 44018, 'このかばんはとても丈夫です。', 'この かばんは とても じょうぶ です。', 'Chiếc cặp này rất bền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1459, 44022, 'この町は安全です。', 'この まちは あんぜん です。', 'Thị trấn này an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1460, 39771, '試合は一対一の引き分けだった。', 'しあいは いち たい いちの ひきわけ だった。', 'Trận đấu hòa 1–1.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1461, 39790, 'みんなで日本チームを応援した。', 'みんなで にほん チームを おうえん した。', 'Mọi người cùng cổ vũ đội tuyển Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1462, 39848, '絵の具で空の色を塗った。', 'えのぐで そらの いろを ぬった。', 'Tôi dùng màu vẽ tô màu bầu trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1463, 39883, '優勝した選手が冠をかぶった。', 'ゆうしょう した せんしゅが かんむりを かぶった。', 'Vận động viên vô địch đội vương miện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1464, 39958, '姉は芸能のニュースに詳しい。', 'あねは げいのうの ニュースに くわしい。', 'Chị tôi rành tin tức giới giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1465, 40001, '昔はラジオが一番の娯楽だった。', 'むかしは ラジオが いちばんの ごらく だった。', 'Ngày xưa radio là thú giải trí hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1585, 37852, '彼は妄想にとらわれている。', 'かれは もうそうに とらわれて いる。', 'Anh ta đang bị vọng tưởng chi phối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1466, 40060, '週末にデパートでいろいろな催しがある。', 'しゅうまつに デパートで いろいろな もよおしが ある。', 'Cuối tuần ở trung tâm thương mại có nhiều sự kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1467, 40070, '日曜祭日は休みです。', 'にちよう さいじつは やすみ です。', 'Chủ nhật và ngày lễ được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1468, 40131, '公園で花の写生をした。', 'こうえんで はなの しゃせいを した。', 'Tôi vẽ phác họa hoa trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1469, 40204, '祖父と将棋をして遊んだ。', 'そふと しょうぎを して あそんだ。', 'Tôi chơi cờ shogi với ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1470, 40332, '図書館で夏目漱石の全集を借りた。', 'としょかんで なつめ そうせきの ぜんしゅうを かりた。', 'Tôi mượn toàn tập Natsume Soseki ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1471, 42923, '寝る前に短編小説を一つ読んだ。', 'ねる まえに たんぺん しょうせつを ひとつ よんだ。', 'Trước khi ngủ tôi đọc một truyện ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1472, 43009, '寝る前に子供に童話を読んであげた。', 'ねる まえに こどもに どうわを よんで あげた。', 'Trước khi ngủ tôi đọc truyện cổ tích cho con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1473, 43019, '子供になぞなぞを出した。', 'こどもに なぞなぞを だした。', 'Tôi ra câu đố cho bọn trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1474, 43067, '筆者の考えをまとめなさい。', 'ひっしゃの かんがえを まとめなさい。', 'Hãy tóm tắt suy nghĩ của người viết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1475, 43079, '昔の武士は刀を持っていた。', 'むかしの ぶしは かたなを もって いた。', 'Võ sĩ ngày xưa mang kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1476, 43094, '高校で文芸部に入っていた。', 'こうこうで ぶんげいぶに はいって いた。', 'Hồi cấp ba tôi ở câu lạc bộ văn nghệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1477, 43128, 'お盆には実家に帰る。', 'おぼんには じっかに かえる。', 'Dịp lễ Obon tôi về quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1478, 43145, '夜に爪を切ってはいけないというのは迷信だ。', 'よるに つめを きっては いけないと いうのは めいしんだ。', 'Chuyện không được cắt móng tay ban đêm là mê tín.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1479, 43162, '彼は歌舞伎の役者だ。', 'かれは かぶきの やくしゃだ。', 'Anh ấy là diễn viên kịch kabuki.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1480, 43194, '花火大会に浴衣を着て行った。', 'はなび たいかいに ゆかたを きて いった。', 'Tôi mặc yukata đi xem pháo hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1481, 39499, '屋根のアンテナが風で倒れた。', 'やねの アンテナが かぜで たおれた。', 'Ăng-ten trên mái nhà bị gió quật đổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1482, 39511, '車のオイルを交換した。', 'くるまの オイルを こうかん した。', 'Tôi thay dầu cho xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1483, 27053, 'えっ、本当ですか。', 'えっ、ほんとう ですか。', 'Hả, thật vậy sao?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1484, 27055, '手伝ってくれて、どうもありがとうございます。', 'てつだって くれて、どうも ありがとう ございます。', 'Cảm ơn anh rất nhiều vì đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1485, 27991, 'あしたは雨が降ると思います。', 'あしたは あめが ふると おもいます。', 'Tôi nghĩ ngày mai trời sẽ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1486, 44026, '日本語がずいぶん上手になりましたね。', 'にほんごが ずいぶん じょうずに なりましたね。', 'Tiếng Nhật của bạn đã giỏi lên khá nhiều nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1487, 44103, 'カーテンを開けてください。', 'カーテンを あけて ください。', 'Hãy kéo rèm cửa ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1488, 44025, 'なるべく早く来てください。', 'なるべく はやく きて ください。', 'Hãy đến sớm nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1489, 27089, '会社へ行きます。', 'かいしゃへいきます。', 'Tôi đi đến công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1490, 40287, '新しいカメラは性能がいい。', 'あたらしい カメラは せいのうが いい。', 'Chiếc máy ảnh mới có tính năng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1491, 39532, '父は昔のカセットテープを大切にしている。', 'ちちは むかしの カセット テープを たいせつに して いる。', 'Bố tôi vẫn giữ gìn những cuộn băng cát-xét cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1492, 39607, '新しいスピーカーで音楽を聞いた。', 'あたらしい スピーカーで おんがくを きいた。', 'Tôi nghe nhạc bằng chiếc loa mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1493, 39743, '封筒に宛名を書いた。', 'ふうとうに あてなを かいた。', 'Tôi ghi tên người nhận lên phong bì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1494, 39716, 'このおもちゃはモーターで動く。', 'この おもちゃは モーターで うごく。', 'Món đồ chơi này chạy bằng mô tơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1495, 39882, 'リモコンの乾電池を替えた。', 'リモコンの かんでんちを かえた。', 'Tôi thay pin khô cho cái điều khiển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1496, 40109, '時計の中には小さな歯車がたくさんある。', 'とけいの なかには ちいさな はぐるまが たくさん ある。', 'Trong đồng hồ có nhiều bánh răng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1497, 40134, '毎朝、新聞の社説を読んでいる。', 'まいあさ、しんぶんの しゃせつを よんで いる。', 'Sáng nào tôi cũng đọc bài xã luận trên báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1498, 42958, '電池の電気は直流だ。', 'でんちの でんきは ちょくりゅうだ。', 'Điện từ pin là dòng điện một chiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1499, 43081, 'パソコンの部品を交換した。', 'パソコンの ぶひんを こうかん した。', 'Tôi thay linh kiện máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1500, 43176, '書類は郵送でお送りします。', 'しょるいは ゆうそうで おおくり します。', 'Chúng tôi sẽ gửi giấy tờ qua bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1501, 43220, '電話をかけたが、話し中だった。', 'でんわを かけたが、はなしちゅう だった。', 'Tôi gọi điện nhưng máy bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1502, 31697, '病気を契機に、たばこをやめた。', 'びょうきを けいきに、たばこを やめた。', 'Nhân dịp bị ốm, tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1503, 37811, 'この店は雰囲気がいい。', 'この みせは ふんいきが いい。', 'Quán này có bầu không khí dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1504, 38139, '問題がますます複雑化している。', 'もんだいが ますます ふくざつか して いる。', 'Vấn đề ngày càng phức tạp hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1584, 37847, '暴力は決して是認できない。', 'ぼうりょくは けっして ぜにん できない。', 'Bạo lực tuyệt đối không thể chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1505, 39853, '会社の情報を外部に漏らしてはいけない。', 'かいしゃの じょうほうを がいぶに もらしては いけない。', 'Không được tiết lộ thông tin công ty ra bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1506, 39903, '後ろに人の気配を感じた。', 'うしろに ひとの けはいを かんじた。', 'Tôi cảm thấy có người phía sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1507, 39945, 'レポートの形式を守って書いてください。', 'レポートの けいしきを まもって かいて ください。', 'Hãy viết báo cáo theo đúng hình thức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1508, 39972, '人を見掛けで判断してはいけない。', 'ひとを みかけで はんだん しては いけない。', 'Không nên đánh giá người khác qua vẻ bề ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1509, 40017, 'この契約は来月から効力を持つ。', 'この けいやくは らいげつから こうりょくを もつ。', 'Hợp đồng này có hiệu lực từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1510, 27083, '階段で二階へ行きます。', 'かいだんで にかいへ いきます。', 'Tôi đi cầu thang lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1511, 27087, '電話はどこですか。', 'でんわは どこ ですか。', 'Điện thoại ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1512, 44027, 'あしたはきっと晴れるでしょう。', 'あしたは きっと はれるでしょう。', 'Ngày mai chắc chắn trời sẽ nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1513, 44041, '来週の予定はもう決まりましたか。', 'らいしゅうの よていは もう きまりましたか。', 'Kế hoạch tuần sau đã định chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1514, 44039, 'この工場では車を作っています。', 'この こうじょうでは くるまを つくって います。', 'Nhà máy này sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1515, 44040, 'パーティーの会場はホテルです。', 'パーティーの かいじょうは ホテル です。', 'Địa điểm tổ chức tiệc là khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1516, 44036, '仕事のあと、同僚と飲みに行った。', 'しごとの あと、どうりょうと のみに いった。', 'Tan làm, tôi đi uống với đồng nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1517, 44042, 'レストランを七時に予約しました。', 'レストランを しちじに よやく しました。', 'Tôi đã đặt nhà hàng lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1518, 40039, 'すべての項目に答えてください。', 'すべての こうもくに こたえて ください。', 'Hãy trả lời tất cả các mục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1519, 40079, 'ラジオに雑音が入って、よく聞こえない。', 'ラジオに ざつおんが はいって、よく きこえない。', 'Radio bị nhiễu, nghe không rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1520, 40128, '写真より実物のほうがきれいだった。', 'しゃしんより じつぶつの ほうが きれい だった。', 'Ngoài đời còn đẹp hơn trong ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1521, 40140, '自分の弱点を知ることが大切だ。', 'じぶんの じゃくてんを しる ことが たいせつだ。', 'Biết điểm yếu của bản thân là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1522, 40221, 'エレベーターが上下に動いている。', 'エレベーターが じょうげに うごいて いる。', 'Thang máy đang chạy lên xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1523, 40322, '列の先頭に並んだ。', 'れつの せんとうに ならんだ。', 'Tôi đứng đầu hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1524, 40337, 'この子には音楽の素質がある。', 'この こには おんがくの そしつが ある。', 'Đứa trẻ này có tố chất âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1525, 42952, 'どの方法にも長短がある。', 'どの ほうほうにも ちょうたんが ある。', 'Phương pháp nào cũng có ưu và nhược điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1526, 43038, '割れたガラスの破片に気をつけて。', 'われた ガラスの はへんに きを つけて。', 'Cẩn thận mảnh thủy tinh vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1527, 43156, '赤い屋根の家を目印にして来てください。', 'あかい やねの いえを めじるしに して きて ください。', 'Hãy lấy ngôi nhà mái đỏ làm mốc mà đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1528, 43190, '彼は要領がいいので、仕事が早い。', 'かれは ようりょうが いいので、しごとが はやい。', 'Anh ấy biết cách làm nên công việc xong nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1529, 39541, '箱の中にお菓子がぎっしり入っている。', 'はこの なかに おかしが ぎっしり はいって いる。', 'Trong hộp chật ních bánh kẹo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1530, 39553, 'こうして二人は結婚しました。', 'こうして ふたりは けっこん しました。', 'Và như thế hai người đã kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1531, 39557, 'ごちそうさま。とてもおいしかった。', 'ごちそうさま。とても おいしかった。', 'Cảm ơn vì bữa ăn, ngon lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1532, 39560, '授業中にこっそりメールを見た。', 'じゅぎょうちゅうに こっそり メールを みた。', 'Trong giờ học tôi lén xem email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1533, 39571, 'こんばんは。今夜は寒いですね。', 'こんばんは。こんやは さむい ですね。', 'Chào buổi tối. Tối nay lạnh nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1534, 39576, '先生、さようなら。', 'せんせい、さようなら。', 'Em chào thầy ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1535, 39672, 'ひとまず休憩しましょう。', 'ひとまず きゅうけい しましょう。', 'Tạm thời nghỉ giải lao đã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1536, 27104, 'A：これ、どうぞ。B：あ、どうも。', 'エー：これ、どうぞ。ビー：あ、どうも。', 'A: Cái này, mời anh. B: À, cảm ơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1537, 27138, '朝、コーヒーを飲みます。', 'あさ、コーヒーを のみます。', 'Buổi sáng tôi uống cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1538, 44031, '社長は今、出張中です。', 'しゃちょうは いま、しゅっちょうちゅう です。', 'Giám đốc hiện đang đi công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1539, 44033, '課長は今会議中です。', 'かちょうは いま かいぎちゅう です。', 'Trưởng nhóm hiện đang họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1540, 44209, 'この町は自然が多くて、きれいです。', 'この まちは しぜんが おおくて、きれい です。', 'Thị trấn này có nhiều thiên nhiên, rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1541, 40389, '彼はインテリだが、話がわかりやすい。', 'かれは インテリ だが、はなしが わかりやすい。', 'Anh ấy là người trí thức nhưng nói chuyện dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1542, 40640, '一人につき千円いただきます。', 'いちにんに つき せんえん いただきます。', 'Mỗi người xin thu một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1543, 41371, '会社の入口に守衛が立っている。', 'かいしゃの いりぐちに しゅえいが たって いる。', 'Có bảo vệ đứng ở lối vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1544, 40528, '仕事のストレスでノイローゼになった。', 'しごとの ストレスで ノイローゼに なった。', 'Vì căng thẳng công việc mà tôi bị suy nhược thần kinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1545, 41323, 'ストレスで自律神経が失調した。', 'ストレスで じりつ しんけいが しっちょう した。', 'Căng thẳng làm rối loạn thần kinh thực vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1546, 41435, '妻は来月出産の予定だ。', 'つまは らいげつ しゅっさんの よていだ。', 'Vợ tôi dự kiến sinh vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1547, 41444, '顔に出来物ができた。', 'かおに できものが できた。', 'Trên mặt tôi nổi một cái mụn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1548, 37840, '過去に執着していては前に進めない。', 'かこに しゅうちゃく して いては まえに すすめない。', 'Cứ bám víu quá khứ thì không thể tiến lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1549, 40454, '試験に落ちて、ショックを受けた。', 'しけんに おちて、ショックを うけた。', 'Thi trượt khiến tôi bị sốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1550, 27190, '学校へ行きます。', 'がっこうへいきます。', 'Tôi đi đến trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1551, 44046, '先生が文法をわかりやすく説明してくれました。', 'せんせいが ぶんぽうを わかりやすく せつめい して くれました。', 'Thầy giáo giải thích ngữ pháp rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1552, 44048, '来週、大阪へ出張します。', 'らいしゅう、おおさかへ しゅっちょう します。', 'Tuần sau tôi đi công tác Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1553, 39724, '最近、やたらに眠い。', 'さいきん、やたらに ねむい。', 'Gần đây tôi buồn ngủ kinh khủng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1554, 39740, '今日はわりあいに暖かい。', 'きょうは わりあいに あたたかい。', 'Hôm nay tương đối ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1555, 39758, '一旦家に帰ってから、出かけます。', 'いったん いえに かえってから、でかけます。', 'Tôi về nhà một chút rồi mới đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1556, 39811, '何分よろしくお願いいたします。', 'なにぶん よろしく おねがい いたします。', 'Dù sao cũng mong anh chiếu cố giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1557, 39818, '果たして彼は来るだろうか。', 'はたして かれは くるだろうか。', 'Liệu anh ấy có đến thật không nhỉ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1558, 39873, 'このレストランは割と安い。', 'この レストランは わりと やすい。', 'Nhà hàng này khá rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1559, 39900, '薬を飲んで、幾分楽になった。', 'くすりを のんで、いくぶん らくに なった。', 'Uống thuốc xong tôi thấy đỡ phần nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1560, 40092, '料理を残らず食べた。', 'りょうりを のこらず たべた。', 'Tôi ăn sạch đồ ăn không sót miếng nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1561, 40317, 'この町は絶えず変化している。', 'この まちは たえず へんか して いる。', 'Thị trấn này không ngừng thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1562, 40321, '先程お電話した山田です。', 'さきほど おでんわ した やまだ です。', 'Tôi là Yamada, người vừa gọi điện lúc nãy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1563, 43127, '本来なら、私が行くべきだった。', 'ほんらいなら、わたしが いく べき だった。', 'Lẽ ra tôi phải là người đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1564, 27175, 'あすかは日本料理のレストランです。', 'あすかは にほん りょうりの レストラン です。', 'Asuka là một nhà hàng món Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1565, 27176, 'アップル銀行は九時からです。', 'アップル ぎんこうは くじから です。', 'Ngân hàng Apple mở cửa từ chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1566, 27895, '私はピアノができます。', 'わたしは ピアノが できます。', 'Tôi biết chơi piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1567, 44056, '外国で働いた経験があります。', 'がいこくで はたらいた けいけんが あります。', 'Tôi có kinh nghiệm làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1568, 44061, '学校の規則を守りましょう。', 'がっこうの きそくを まもりましょう。', 'Hãy tuân thủ nội quy trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1569, 44050, '今週は毎日残業があります。', 'こんしゅうは まいにち ざんぎょうが あります。', 'Tuần này ngày nào cũng phải làm thêm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1570, 38254, '彼は新しい遊びを考案した。', 'かれは あたらしい あそびを こうあん した。', 'Anh ấy đã nghĩ ra một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1571, 40525, 'この言葉の微妙なニュアンスが難しい。', 'この ことばの びみょうな ニュアンスが むずかしい。', 'Sắc thái tinh tế của từ này thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1572, 41471, '友達の一言に傷付いた。', 'ともだちの ひとことに きずついた。', 'Tôi bị tổn thương vì một câu nói của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1573, 44057, 'この会社は高い技術を持っている。', 'この かいしゃは たかい ぎじゅつを もって いる。', 'Công ty này có kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1574, 31151, 'これは私の専門の領域ではない。', 'これは わたしの せんもんの りょういき では ない。', 'Đây không phải lĩnh vực chuyên môn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1575, 27222, '五月二日は休みです。', 'ごがつ ふつかは やすみ です。', 'Ngày mùng hai tháng năm được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1576, 27223, '三日間、東京にいました。', 'みっかかん、とうきょうに いました。', 'Tôi ở Tokyo ba ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1577, 44052, '会議室はどこですか。', 'かいぎしつは どこ ですか。', 'Phòng họp ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1578, 44058, '大学で経済を勉強しています。', 'だいがくで けいざいを べんきょう して います。', 'Tôi đang học kinh tế ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1579, 41571, 'もう少しの辛抱だ。頑張ろう。', 'もう すこしの しんぼうだ。がんばろう。', 'Chịu đựng thêm chút nữa thôi. Cố lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1580, 41579, '彼は人格の優れた人だ。', 'かれは じんかくの すぐれた ひとだ。', 'Ông ấy là người có nhân cách tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1581, 41824, '短気は損気。', 'たんきは そんき。', 'Nóng giận thì thiệt thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1582, 31732, '問題の重大さを認識すべきだ。', 'もんだいの じゅうだいさを にんしき すべきだ。', 'Cần nhận thức được mức độ nghiêm trọng của vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1583, 31734, '無意識に髪を触る癖がある。', 'むいしきに かみを さわる くせが ある。', 'Tôi có thói quen vô thức sờ tóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1586, 38255, 'このイベントは彼女の発案だ。', 'この イベントは かのじょの はつあんだ。', 'Sự kiện này là do cô ấy đề xuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1587, 40433, '監督は試合の後でコメントを発表した。', 'かんとくは しあいの あとで コメントを はっぴょう した。', 'Sau trận đấu, huấn luyện viên đã đưa ra bình luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1588, 41373, '新入社員のための手引きを作った。', 'しんにゅう しゃいんの ための てびきを つくった。', 'Chúng tôi soạn sách hướng dẫn cho nhân viên mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1589, 41539, '彼女は茶道の心得がある。', 'かのじょは さどうの こころえが ある。', 'Cô ấy có hiểu biết về trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1590, 41549, '住民は市に工事の中止を申し入れた。', 'じゅうみんは しに こうじの ちゅうしを もうしいれた。', 'Người dân đã yêu cầu thành phố dừng công trình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1591, 41794, '彼はみんなの気持ちを代弁してくれた。', 'かれは みんなの きもちを だいべん して くれた。', 'Anh ấy đã nói thay tâm tư của mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1592, 27240, 'どういたしまして。', 'どういたしまして。', 'Không có gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1593, 27283, '店へ行きます。', 'みせへいきます。', 'Tôi đi đến cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1594, 44072, '先生によろしく伝えてください。', 'せんせいに よろしく つたえて ください。', 'Cho tôi gửi lời hỏi thăm thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1595, 44075, '友達を駅まで送りました。', 'ともだちを えきまで おくりました。', 'Tôi tiễn bạn ra ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1596, 41405, '新しい事業が大きな収益を上げた。', 'あたらしい じぎょうが おおきな しゅうえきを あげた。', 'Mảng kinh doanh mới đã mang lại lợi nhuận lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1597, 41839, '閉店前に弁当が値引きされる。', 'へいてん まえに べんとうが ねびき される。', 'Trước giờ đóng cửa, cơm hộp được giảm giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1598, 27281, '公園で写真を撮りました。', 'こうえんで しゃしんを とりました。', 'Tôi đã chụp ảnh ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1599, 27284, '庭に花があります。', 'にわに はなが あります。', 'Trong vườn có hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1600, 42597, '人の作品を貶すのはよくない。', 'ひとの さくひんを けなすのは よくない。', 'Chê bai tác phẩm của người khác là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1601, 40381, 'お客様にアンケートをお願いした。', 'おきゃくさまに アンケートを おねがい した。', 'Chúng tôi đã nhờ khách hàng điền phiếu khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1602, 40473, 'デパートで夏のセールが始まった。', 'デパートで なつの セールが はじまった。', 'Đợt giảm giá mùa hè ở trung tâm thương mại đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1603, 40494, 'このチームはチームワークがいい。', 'この チームは チームワークが いい。', 'Đội này có tinh thần đồng đội tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1604, 41249, '最後の仕上げに、塩を少し加える。', 'さいごの しあげに、しおを すこし くわえる。', 'Bước hoàn thiện cuối cùng là cho thêm chút muối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1605, 41339, '結婚するまで会社の社宅に住んでいた。', 'けっこん するまで かいしゃの しゃたくに すんで いた。', 'Trước khi cưới tôi sống ở nhà công ty cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1606, 41375, 'この建物は有名な建築家が手掛けた。', 'この たてものは ゆうめいな けんちくかが てがけた。', 'Tòa nhà này do một kiến trúc sư nổi tiếng thực hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1607, 41387, '明日の会議の手筈はもう整っている。', 'あしたの かいぎの てはずは もう ととのって いる。', 'Mọi chuẩn bị cho cuộc họp ngày mai đã xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1608, 41388, 'みんなで手分けして掃除をした。', 'みんなで てわけ して そうじを した。', 'Mọi người chia nhau dọn dẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1609, 41436, '明日は九時に出社してください。', 'あしたは くじに しゅっしゃ して ください。', 'Ngày mai hãy đến công ty lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1610, 41442, '今月は出費がかさんだ。', 'こんげつは しゅっぴが かさんだ。', 'Tháng này chi phí chồng chất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1611, 41460, '庶務の仕事を担当している。', 'しょむの しごとを たんとう して いる。', 'Tôi phụ trách công việc hành chính chung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1612, 41573, '日本企業がベトナムに進出している。', 'にほん きぎょうが ベトナムに しんしゅつ して いる。', 'Các doanh nghiệp Nhật đang mở rộng sang Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1613, 41945, '鉄鋼業は日本の重要な産業だ。', 'てっこうぎょうは にほんの じゅうような さんぎょうだ。', 'Ngành sắt thép là ngành công nghiệp quan trọng của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1614, 42504, 'パソコンの閲覧履歴を消した。', 'パソコンの えつらん りれきを けした。', 'Tôi đã xóa lịch sử duyệt web trên máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1615, 42548, 'この作業には多くの労力がかかる。', 'この さぎょうには おおくの ろうりょくが かかる。', 'Công việc này tốn nhiều công sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1616, 40380, 'アルミの缶はリサイクルできる。', 'アルミの かんは リサイクル できる。', 'Lon nhôm có thể tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1617, 40940, '私の高校は男女共学だった。', 'わたしの こうこうは だんじょ きょうがく だった。', 'Trường cấp ba của tôi học chung nam nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1618, 44416, '外国で働いた経験があります。', 'がいこくで はたらいた けいけんが あります。', 'Tôi có kinh nghiệm làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1619, 31814, '伝統文化を次の世代に継承したい。', 'でんとう ぶんかを つぎの せだいに けいしょう したい。', 'Tôi muốn truyền lại văn hóa truyền thống cho thế hệ sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1620, 40961, 'この失敗から多くの教訓を得た。', 'この しっぱいから おおくの きょうくんを えた。', 'Tôi rút ra được nhiều bài học từ thất bại này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1621, 40963, '自動車教習所に通っている。', 'じどうしゃ きょうしゅうじょに かよって いる。', 'Tôi đang học ở trường dạy lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1622, 41088, '翻訳を原文と比べてみた。', 'ほんやくを げんぶんと くらべて みた。', 'Tôi thử so bản dịch với nguyên văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1623, 41395, '第一志望の大学に受かった。', 'だいいち しぼうの だいがくに うかった。', 'Tôi đã đỗ vào trường đại học nguyện vọng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1624, 41439, 'この問題は毎年のように出題される。', 'この もんだいは まいとしの ように しゅつだい される。', 'Dạng bài này năm nào cũng được ra đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1625, 41468, '「です」や「ます」は助動詞だ。', '「です」や 「ます」は じょどうしだ。', '"Desu" và "masu" là trợ động từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1626, 41754, '他動詞は「を」を取ることが多い。', 'たどうしは 「を」を とる ことが おおい。', 'Tha động từ thường đi với trợ từ "wo".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1627, 41791, '彼は家庭の事情で大学を退学した。', 'かれは かていの じじょうで だいがくを たいがく した。', 'Anh ấy bỏ học đại học vì hoàn cảnh gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1628, 42472, '食塩を水に溶かして溶液を作った。', 'しょくえんを みずに とかして ようえきを つくった。', 'Hòa muối vào nước để tạo dung dịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1629, 31812, '大臣はスキャンダルで失脚した。', 'だいじんは スキャンダルで しっきゃく した。', 'Bộ trưởng mất ghế vì vụ bê bối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1630, 31815, '政治家の世襲を批判する声がある。', 'せいじかの せしゅうを ひはん する こえが ある。', 'Có tiếng nói chỉ trích việc cha truyền con nối trong giới chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1631, 37843, '政府が為替市場に介入した。', 'せいふが かわせ しじょうに かいにゅう した。', 'Chính phủ đã can thiệp vào thị trường ngoại hối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1632, 37844, '他人の生活に干渉しないでほしい。', 'たにんの せいかつに かんしょう しないで ほしい。', 'Mong anh đừng xen vào cuộc sống của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1633, 38214, '党は意見の違いで分裂した。', 'とうは いけんの ちがいで ぶんれつ した。', 'Đảng bị chia rẽ vì bất đồng ý kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1634, 38234, '公文書の改ざんは重大な問題だ。', 'こうぶんしょの かいざんは じゅうだいな もんだいだ。', 'Sửa đổi trái phép văn bản công là vấn đề nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1635, 38237, '彼は寄付金を着服していた。', 'かれは きふきんを ちゃくふく して いた。', 'Hắn đã tham ô tiền quyên góp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1636, 40507, '店頭で新しい掃除機のデモンストレーションをしている。', 'てんとうで あたらしい そうじきの デモンストレーションを して いる。', 'Trước cửa hàng đang trình diễn máy hút bụi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1637, 40968, '彼は脅迫の電話を受けた。', 'かれは きょうはくの でんわを うけた。', 'Anh ấy nhận được cuộc gọi đe dọa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1638, 41011, 'その国は軍事費を増やしている。', 'その くには ぐんじひを ふやして いる。', 'Nước đó đang tăng chi phí quân sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1639, 41013, '祖父の若いころの軍服姿の写真がある。', 'そふの わかい ころの ぐんぷく すがたの しゃしんが ある。', 'Có tấm ảnh ông tôi mặc quân phục thời trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1640, 41034, '国連で停戦の決議が採択された。', 'こくれんで ていせんの けつぎが さいたく された。', 'Nghị quyết ngừng bắn đã được thông qua tại Liên Hợp Quốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1641, 41078, '各国の元首が会議に集まった。', 'かっこくの げんしゅが かいぎに あつまった。', 'Nguyên thủ các nước đã tụ họp tại hội nghị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1642, 44516, '電車の中で漫画を読んでいる人が多いです。', 'でんしゃの なかで まんがを よんで いる ひとが おおい です。', 'Trên tàu có nhiều người đọc truyện tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1643, 27390, 'このりんごは黒いです。', 'このりんごはくろいです。', 'Quả táo này đen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1644, 44080, 'たばこをやめました。', 'たばこを やめました。', 'Tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1645, 44083, 'これは大事な書類です。', 'これは だいじな しょるい です。', 'Đây là tài liệu quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1646, 42464, '与党は選挙で過半数を取った。', 'よとうは せんきょで かはんすうを とった。', 'Đảng cầm quyền đã giành quá bán trong cuộc bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1647, 44084, '今日は特別な日です。', 'きょうは とくべつな ひ です。', 'Hôm nay là một ngày đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1648, 42041, '新しい内閣が発足した。', 'あたらしい ないかくが ほっそく した。', 'Nội các mới đã được thành lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1649, 41087, '広島で原爆の資料館を見学した。', 'ひろしまで げんばくの しりょうかんを けんがく した。', 'Tôi đã tham quan bảo tàng bom nguyên tử ở Hiroshima.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1650, 41222, '町で殺人事件が起きた。', 'まちで さつじん じけんが おきた。', 'Trong thị trấn đã xảy ra vụ giết người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1651, 41366, '警察は容疑者を取り調べた。', 'けいさつは ようぎしゃを とりしらべた。', 'Cảnh sát đã thẩm vấn nghi phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1652, 41368, '警察はスピード違反を取り締まっている。', 'けいさつは スピード いはんを とりしまって いる。', 'Cảnh sát đang kiểm soát vi phạm tốc độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1653, 41393, '主要国の首脳が会談した。', 'しゅよう こくの しゅのうが かいだん した。', 'Lãnh đạo các nước lớn đã hội đàm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1654, 41428, '兵士は銃を構えた。', 'へいしは つつを かまえた。', 'Người lính giương súng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1655, 41527, '内閣の信任投票が行われた。', 'ないかくの しんにん とうひょうが おこなわれた。', 'Cuộc bỏ phiếu tín nhiệm nội các đã diễn ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1656, 41565, '両国の親善のために交流会が開かれた。', 'りょうこくの しんぜんの ために こうりゅうかいが ひらかれた。', 'Buổi giao lưu được tổ chức vì tình hữu nghị hai nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1657, 41741, '蔵相は景気対策を発表した。', 'ぞうしょうは けいき たいさくを はっぴょう した。', 'Bộ trưởng tài chính đã công bố biện pháp kích thích kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1658, 41756, 'クラスの意見を多数決で決めた。', 'クラスの いけんを たすうけつで きめた。', 'Ý kiến của lớp được quyết định theo đa số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1659, 41811, 'その国は国際機関から脱退した。', 'その くには こくさい きかんから だったい した。', 'Nước đó đã rút khỏi tổ chức quốc tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1660, 41875, 'スイスは永世中立国だ。', 'スイスは えいせい ちゅうりつこくだ。', 'Thụy Sĩ là quốc gia trung lập vĩnh viễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1661, 42435, '町の役場で手続きをした。', 'まちの やくばで てつづきを した。', 'Tôi làm thủ tục ở ủy ban thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1662, 42482, '抑圧された感情が爆発した。', 'よくあつ された かんじょうが ばくはつ した。', 'Cảm xúc bị đè nén đã bùng nổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1663, 42526, '大名はそれぞれ自分の領地を治めていた。', 'だいみょうは それぞれ じぶんの りょうちを おさめて いた。', 'Mỗi lãnh chúa cai quản lãnh địa riêng của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1664, 42545, '彼はサッカー連盟の会長に選ばれた。', 'かれは サッカー れんめいの かいちょうに えらばれた。', 'Ông ấy được bầu làm chủ tịch liên đoàn bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1665, 40388, 'インターフォンが鳴ったので、玄関に出た。', 'インターフォンが なったので、げんかんに でた。', 'Chuông cửa reo nên tôi ra cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1666, 40441, 'シートベルトを締めてください。', 'シートベルトを しめて ください。', 'Xin hãy thắt dây an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1667, 40459, 'ストローでジュースを飲んだ。', 'ストローで ジュースを のんだ。', 'Tôi uống nước ép bằng ống hút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1668, 44569, 'この町は自然が多くて、きれいです。', 'この まちは しぜんが おおくて、きれい です。', 'Thị trấn này có nhiều thiên nhiên, rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1669, 44087, '父はとても厳しいです。', 'ちちは とても きびしい です。', 'Bố tôi rất nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1670, 27405, 'この映画はあまりおもしろくないです。', 'この えいがは あまり おもしろく ない です。', 'Bộ phim này không hay lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1671, 27445, '妹は絵が上手です。', 'いもうとは えが じょうず です。', 'Em gái tôi vẽ tranh giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1672, 40467, '会社にはスラックスをはいて行く。', 'かいしゃには スラックスを はいて いく。', 'Tôi mặc quần tây đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1673, 40496, '授業の終わりのチャイムが鳴った。', 'じゅぎょうの おわりの チャイムが なった。', 'Chuông báo hết giờ học đã reo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1674, 40514, 'このコートはドライクリーニングに出す。', 'この コートは ドライクリーニングに だす。', 'Chiếc áo khoác này tôi sẽ mang đi giặt khô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1675, 40529, 'お風呂の後、パジャマに着替えた。', 'おふろの あと、パジャマに きがえた。', 'Tắm xong tôi thay đồ ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1676, 40533, 'コートをハンガーに掛けた。', 'コートを ハンガーに かけた。', 'Tôi treo áo khoác lên móc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1677, 41006, '棚の空き間に本を詰めた。', 'たなの あきまに ほんを つめた。', 'Tôi nhét sách vào chỗ trống trên giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1678, 41108, '出かける前に戸締りを確認した。', 'でかける まえに とじまりを かくにん した。', 'Trước khi ra ngoài tôi kiểm tra đã khóa cửa chưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1679, 41356, '鍋の取っ手が取れてしまった。', 'なべの とってが とれて しまった。', 'Tay cầm của cái nồi bị rời ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1680, 41394, '犬に新しい首輪をつけた。', 'いぬに あたらしい くびわを つけた。', 'Tôi đeo vòng cổ mới cho con chó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1681, 41521, 'この地方は織物の産地として有名だ。', 'この ちほうは おりものの さんちと して ゆうめいだ。', 'Vùng này nổi tiếng là nơi sản xuất vải dệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1682, 41567, '面接では身なりに気をつけなさい。', 'めんせつでは みなりに きを つけなさい。', 'Khi phỏng vấn hãy chú ý cách ăn mặc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1683, 41862, '家族は茶の間でテレビを見ている。', 'かぞくは ちゃのまで テレビを みて いる。', 'Cả nhà đang xem ti vi trong phòng sinh hoạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1684, 42199, '洗った皿を布巾で拭いた。', 'あらった さらを ふきんで ふいた。', 'Tôi lau khô đĩa đã rửa bằng khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1685, 42485, 'このホテルの浴室は広い。', 'この ホテルの よくしつは ひろい。', 'Phòng tắm của khách sạn này rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1686, 42596, '結婚式のためにスーツを誂えた。', 'けっこんしきの ために スーツを あつらえた。', 'Tôi đặt may bộ vest cho đám cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1687, 40406, 'バーでカクテルを注文した。', 'バーで カクテルを ちゅうもん した。', 'Tôi gọi một ly cocktail ở quán bar.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1688, 43244, '仕事の後、同僚とバーに行った。', 'しごとの あと、どうりょうと バーに いった。', 'Sau giờ làm tôi đi quán bar với đồng nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1689, 40466, 'いつか赤いスポーツカーに乗りたい。', 'いつか あかい スポーツカーに のりたい。', 'Một ngày nào đó tôi muốn lái chiếc xe thể thao màu đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1690, 40493, '東京タワーから夜景を眺めた。', 'とうきょう タワーから やけいを ながめた。', 'Tôi ngắm cảnh đêm từ tháp Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1691, 40670, '兄は運輸会社に勤めている。', 'あには うんゆ がいしゃに つとめて いる。', 'Anh tôi làm ở công ty vận tải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1692, 40997, 'この区間は工事のため運休している。', 'この くかんは こうじの ため うんきゅう して いる。', 'Đoạn này tạm ngừng chạy tàu vì thi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1693, 41235, '桟橋から船に乗った。', 'さんばしから ふねに のった。', 'Tôi lên tàu từ cầu tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1694, 41447, '準急に乗れば、十分早く着く。', 'じゅんきゅうに のれば、じゅっぷん はやく つく。', 'Đi tàu bán tốc hành sẽ đến sớm hơn mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1695, 41504, '台風が九州に上陸した。', 'たいふうが きゅうしゅうに じょうりく した。', 'Bão đã đổ bộ vào Kyushu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1696, 41509, 'この町は昔、城下町として栄えた。', 'この まちは むかし、じょうかまちと して さかえた。', 'Thị trấn này xưa kia thịnh vượng như một đô thị dưới chân thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1697, 41556, '橋の真下を船が通った。', 'はしの ましたを ふねが とおった。', 'Con thuyền đi ngay bên dưới cây cầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1698, 44089, '日本の生活はどうですか。', 'にほんの せいかつは どう ですか。', 'Cuộc sống ở Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1699, 27459, '奥さんはどちらの方ですか。', 'おくさんは どちらの かた ですか。', 'Vợ anh là người ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1700, 27460, '妻は料理が上手です。', 'つまは りょうりが じょうず です。', 'Vợ tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1701, 44088, 'もうすぐ夏休みです。', 'もうすぐ なつやすみ です。', 'Sắp đến kỳ nghỉ hè rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1702, 27928, '富士山に登ったことがあります。', 'ふじさんに のぼった ことが あります。', 'Tôi đã từng leo núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1703, 41735, '冬山で登山者が遭難した。', 'ふゆやまで とざんしゃが そうなん した。', 'Người leo núi đã gặp nạn trên núi mùa đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1704, 41844, '彼は大学を出て、地元で就職した。', 'かれは だいがくを でて、じもとで しゅうしょく した。', 'Tốt nghiệp đại học xong anh ấy làm việc ở quê nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1705, 41847, '祭りでは地方の人が三味線を弾く。', 'まつりでは じかたの ひとが しゃみせんを ひく。', 'Trong lễ hội, người đệm nhạc chơi đàn shamisen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1706, 42211, '記者は急いで現場に赴いた。', 'きしゃは いそいで げんばに おもむいた。', 'Phóng viên vội vã đến hiện trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1707, 42519, '旅券の有効期限を確認した。', 'りょけんの ゆうこう きげんを かくにん した。', 'Tôi đã kiểm tra thời hạn hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1708, 40755, '疲れて目が霞んできた。', 'つかれて めが かすんで きた。', 'Mệt quá nên mắt tôi mờ đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1709, 40945, '冷夏のため、米が凶作だった。', 'れいかの ため、こめが きょうさく だった。', 'Do mùa hè lạnh nên lúa mất mùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1710, 41067, 'この部屋は見晴らしがいい。', 'この へやは みはらしが いい。', 'Căn phòng này có tầm nhìn đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1711, 41165, '夏休みは涼しい高原で過ごした。', 'なつやすみは すずしい こうげんで すごした。', 'Kỳ nghỉ hè tôi ở trên cao nguyên mát mẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1712, 41196, '駐車場には砂利が敷いてある。', 'ちゅうしゃじょうには じゃりが しいて ある。', 'Bãi đỗ xe được rải sỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1713, 41231, '彼は山岳写真家として知られている。', 'かれは さんがく しゃしんかと して しられて いる。', 'Ông ấy nổi tiếng là nhiếp ảnh gia chuyên chụp núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1714, 41289, 'この子猫は雌だ。', 'この こねこは めすだ。', 'Chú mèo con này là mèo cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1715, 41319, '葉っぱから雨の雫が落ちた。', 'はっぱから あめの しずくが おちた。', 'Giọt mưa rơi xuống từ chiếc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1716, 41487, '梢で小鳥が鳴いている。', 'こずえで ことりが ないて いる。', 'Chim nhỏ đang hót trên ngọn cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1717, 41488, '森の奥に小さな沼がある。', 'もりの おくに ちいさな ぬまが ある。', 'Sâu trong rừng có một đầm lầy nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1718, 41557, 'この真珠は天然のものだ。', 'この しんじゅは てんねんの ものだ。', 'Viên ngọc trai này là ngọc tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1719, 41594, 'この川の水源は山奥にある。', 'この かわの すいげんは やまおくに ある。', 'Đầu nguồn con sông này nằm sâu trong núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1720, 42078, '切り株の年輪を数えると、樹齢が分かる。', 'きりかぶの ねんりんを かぞえると、じゅれいが わかる。', 'Đếm vòng gỗ trên gốc cây sẽ biết tuổi cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1721, 44109, '洗濯機が壊れてしまいました。', 'せんたくきが こわれて しまいました。', 'Máy giặt bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1722, 44113, 'カレーの材料を買いに行きます。', 'カレーの ざいりょうを かいに いきます。', 'Tôi đi mua nguyên liệu nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1723, 44111, '電子レンジで弁当を温めました。', 'でんし レンジで べんとうを あたためました。', 'Tôi hâm nóng cơm hộp bằng lò vi sóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1724, 44115, '花のいい匂いがします。', 'はなの いい においが します。', 'Có mùi hoa thơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1725, 46191, '二つの国は平和条約を結んだ。', 'ふたつの くには へいわ じょうやくを むすんだ。', 'Hai nước đã ký hiệp ước hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1726, 27461, '子どもが二人います。', 'こどもが ふたり います。', 'Tôi có hai đứa con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1727, 27462, '彼の話はよくわかりません。', 'かれの はなしは よく わかりません。', 'Tôi không hiểu rõ lời anh ấy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1728, 27464, '公園に人がたくさんいます。', 'こうえんに ひとが たくさん います。', 'Trong công viên có rất nhiều người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1729, 27466, 'フランス語は全然わかりません。', 'フランスごは ぜんぜん わかりません。', 'Tôi hoàn toàn không hiểu tiếng Pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1730, 27467, 'きょうは早くうちへ帰ります。', 'きょうは はやく うちへ かえります。', 'Hôm nay tôi về nhà sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1731, 27469, 'どうしてきのう休みましたか。', 'どうして きのう やすみましたか。', 'Tại sao hôm qua bạn nghỉ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1732, 27516, 'ドアのうしろに猫がいます。', 'ドアの うしろに ねこが います。', 'Sau cánh cửa có con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1733, 44120, 'ここにごみを捨てないでください。', 'ここに ごみを すてないで ください。', 'Xin đừng vứt rác ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1734, 42417, '木綿の実から綿が取れる。', 'きわたの みから わたが とれる。', 'Từ quả cây bông có thể lấy được bông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1735, 42434, 'この島には野生の鹿がいる。', 'この しまには やせいの しかが いる。', 'Trên đảo này có hươu hoang dã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1736, 42494, '公園の落ち葉を掃いた。', 'こうえんの おちばを はいた。', 'Tôi quét lá rụng trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1737, 42539, '池に蓮の花が咲いている。', 'いけに はすの はなが さいて いる。', 'Hoa sen đang nở trong ao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1738, 42594, '町の中心に高いビルが聳えている。', 'まちの ちゅうしんに たかい ビルが そびえて いる。', 'Giữa thành phố có tòa nhà cao sừng sững.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1739, 40438, '生活のサイクルが乱れている。', 'せいかつの サイクルが みだれて いる。', 'Nhịp sinh hoạt đang bị rối loạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1740, 40733, 'そろそろお暇します。', 'そろそろ おいとま します。', 'Tôi xin phép cáo từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1741, 41023, '手術後の経過は順調だ。', 'しゅじゅつごの けいかは じゅんちょうだ。', 'Tình trạng sau phẫu thuật tiến triển tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1742, 41080, '令和元年に結婚した。', 'れいわ がんねんに けっこん した。', 'Tôi kết hôn vào năm Reiwa thứ nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1743, 41294, '欠席する場合は事前に連絡してください。', 'けっせき する ばあいは じぜんに れんらく して ください。', 'Nếu vắng mặt hãy báo trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1744, 41452, '今年の初雪は例年より早かった。', 'ことしの はつゆきは れいねんより はやかった。', 'Trận tuyết đầu mùa năm nay đến sớm hơn mọi năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1745, 42429, '夜更けまで友達と話し込んだ。', 'よふけまで ともだちと はなしこんだ。', 'Tôi trò chuyện với bạn đến tận đêm khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1746, 42537, '暦の上ではもう春だ。', 'こよみの うえでは もう はるだ。', 'Theo lịch thì đã sang xuân rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1747, 37896, '過剰な期待はプレッシャーになる。', 'かじょうな きたいは プレッシャーに なる。', 'Kỳ vọng quá mức sẽ trở thành áp lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1748, 37897, '適度な運動は健康にいい。', 'てきどな うんどうは けんこうに いい。', 'Vận động vừa phải tốt cho sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1749, 44155, '寝る前に小説を読みます。', 'ねる まえに しょうせつを よみます。', 'Trước khi ngủ tôi đọc tiểu thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1750, 44157, 'この番組はとてもおもしろいです。', 'この ばんぐみは とても おもしろい です。', 'Chương trình này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1751, 44150, '日本の歴史に興味があります。', 'にほんの れきしに きょうみが あります。', 'Tôi quan tâm đến lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1752, 44123, 'お湯が沸きました。', 'おゆが わきました。', 'Nước đã sôi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1753, 44124, 'パンを焼いて食べます。', 'パンを やいて たべます。', 'Tôi nướng bánh mì để ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1754, 44126, 'ビールがよく冷えています。', 'ビールが よく ひえて います。', 'Bia đã lạnh rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1755, 44149, '昔はラジオが一番の娯楽だった。', 'むかしは ラジオが いちばんの ごらく だった。', 'Ngày xưa radio là thú giải trí hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1756, 44154, '日曜日、映画を見ます。', 'にちようび、えいがを みます。', 'Chủ nhật tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1757, 27473, 'ああ、木村さんですか。', 'ああ、きむらさん ですか。', 'À, chị Kimura đấy à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1758, 27553, 'りんごをいくつ買いましたか。', 'りんごを いくつ かいましたか。', 'Bạn đã mua mấy quả táo?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1759, 44151, 'どんな音楽が好きですか。', 'どんな おんがくが すき ですか。', 'Bạn thích loại nhạc nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1760, 44152, '日本の歌が好きです。', 'にほんの うたが すき です。', 'Tôi thích các bài hát Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1761, 44153, '妹は絵が上手です。', 'いもうとは えが じょうず です。', 'Em gái tôi vẽ tranh giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1762, 44128, '雨で靴が汚れました。', 'あめで くつが よごれました。', 'Giày bị bẩn vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1763, 44130, '弟がおもちゃを壊しました。', 'おとうとが おもちゃを こわしました。', 'Em trai tôi làm hỏng đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1764, 44132, 'コップが落ちて割れました。', 'コップが おちて われました。', 'Cái cốc rơi xuống vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1765, 44134, '木から葉が落ちています。', 'きから はが おちて います。', 'Lá đang rơi từ trên cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1766, 44136, '店の前に人が並んでいます。', 'みせの まえに ひとが ならんで います。', 'Trước cửa hàng người ta đang xếp hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1767, 44138, '封筒に切手を貼りました。', 'ふうとうに きってを はりました。', 'Tôi dán tem lên phong bì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1768, 44140, '日本の生活に慣れました。', 'にほんの せいかつに なれました。', 'Tôi đã quen với cuộc sống ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1769, 44142, '隣の部屋がうるさくて、眠れません。', 'となりの へやが うるさくて、ねむれません。', 'Phòng bên ồn quá, tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1770, 44144, '丁寧に説明してくれました。', 'ていねいに せつめい して くれました。', 'Họ đã giải thích cẩn thận cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1771, 44147, 'しっかり勉強してください。', 'しっかり べんきょう して ください。', 'Hãy học hành chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1772, 40790, '各種のクレジットカードが使えます。', 'かくしゅの クレジットカードが つかえます。', 'Có thể dùng nhiều loại thẻ tín dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1773, 40864, '一、三、五は奇数だ。', 'いち、さん、ごは きすうだ。', 'Một, ba, năm là số lẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1774, 41390, '種々の思い出が胸によみがえった。', 'くさぐさの おもいでが むねに よみがえった。', 'Đủ thứ kỷ niệm ùa về trong lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1775, 41505, 'スカートの丈を短くした。', 'スカートの たけを みじかく した。', 'Tôi làm váy ngắn lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1776, 41552, '意見が真っ二つに分かれた。', 'いけんが まっぷたつに わかれた。', 'Ý kiến chia làm hai phe rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1777, 41737, '会社は営業部の人員を増強した。', 'かいしゃは えいぎょうぶの じんいんを ぞうきょう した。', 'Công ty đã tăng cường nhân sự cho phòng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1778, 44181, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1779, 44183, 'パーティーでみんなで踊りました。', 'パーティーで みんなで おどりました。', 'Ở bữa tiệc mọi người cùng nhảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1780, 44185, 'ピアノを弾くのが好きです。', 'ピアノを ひくのが すき です。', 'Tôi thích chơi piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1782, 44193, '結婚式に招待されました。', 'けっこんしきに しょうたい されました。', 'Tôi được mời dự đám cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1783, 44191, 'みんなで日本チームを応援した。', 'みんなで にほん チームを おうえん した。', 'Mọi người cùng cổ vũ đội tuyển Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1784, 44179, '郵便局で切手を買います。', 'ゆうびんきょくで きってを かいます。', 'Tôi mua tem ở bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1785, 44188, '日曜日、山に登りました。', 'にちようび、やまに のぼりました。', 'Chủ nhật tôi đã leo núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1786, 44196, 'いい店を見つけました。', 'いい みせを みつけました。', 'Tôi tìm được một quán ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1787, 44198, '昨日のパーティーは楽しかったです。', 'きのうの パーティーは たのしかった です。', 'Bữa tiệc hôm qua rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1788, 44200, 'この映画はつまらないです。', 'この えいがは つまらない です。', 'Bộ phim này chán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1789, 44202, '山の上からの景色は素晴らしかったです。', 'やまの うえからの けしきは すばらしかった です。', 'Phong cảnh từ trên núi thật tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1790, 31173, '今月の収支は赤字だった。', 'こんげつの しゅうしは あかじ だった。', 'Thu chi tháng này bị thâm hụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1791, 41750, '家族でお揃いのシャツを着た。', 'かぞくで おそろいの シャツを きた。', 'Cả nhà mặc áo đồng bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1792, 41804, '大部の本を一週間で読み終えた。', 'たいぶの ほんを いっしゅうかんで よみおえた。', 'Tôi đọc xong cuốn sách đồ sộ trong một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1793, 42164, '水から微量の鉛が検出された。', 'みずから びりょうの なまりが けんしゅつ された。', 'Đã phát hiện một lượng chì rất nhỏ trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1794, 42167, 'うちには猫が二匹いる。', 'うちには ねこが にひき いる。', 'Nhà tôi có hai con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1795, 42422, '荷物の目方を量った。', 'にもつの めかたを はかった。', 'Tôi cân trọng lượng hành lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1796, 37873, 'ゲームは現実からの逃避に過ぎない。', 'ゲームは げんじつからの とうひに すぎない。', 'Trò chơi chẳng qua là sự trốn tránh thực tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1797, 40471, '眼鏡がずれている。', 'めがねが ずれて いる。', 'Kính bị lệch rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1798, 40436, '感情をコントロールするのは難しい。', 'かんじょうを コントロール するのは むずかしい。', 'Kiểm soát cảm xúc thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1799, 40647, '彼の実力には誰もが一目置いている。', 'かれの じつりょくには だれもが いちもく おいて いる。', 'Ai cũng nể phục thực lực của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1800, 40736, '疲れ果てて、もう一歩も歩けない。', 'つかれはてて、もう いっぽも あるけない。', 'Mệt rã rời, tôi không bước nổi một bước nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1801, 40776, '北海道は明治時代に開拓された。', 'ほっかいどうは めいじ じだいに かいたく された。', 'Hokkaido được khai hoang vào thời Minh Trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1802, 40785, '彼の一言で気分を害した。', 'かれの ひとことで きぶんを がいした。', 'Một câu nói của anh ta làm tôi phật ý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1803, 40792, '日本は金メダルを五個獲得した。', 'にほんは きんメダルを ごこ かくとく した。', 'Nhật Bản đã giành được năm huy chương vàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1804, 40795, '早めに行って席を確保した。', 'はやめに いって せきを かくほ した。', 'Tôi đến sớm để giữ chỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1805, 27474, 'いっしょにいかがですか。', 'いっしょにいかがですか。', 'Anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1806, 44213, '太陽が東から昇ります。', 'たいようが ひがしから のぼります。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1807, 27475, '本はちょっと……。', 'ほんはちょっと……。', 'Sách thì hơi khó. (cách từ chối lời mời một cách khéo léo)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1808, 44225, '強い風で木の枝が折れました。', 'つよい かぜで きの えだが おれました。', 'Gió mạnh làm gãy cành cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1809, 44231, '昨夜、地震がありました。', 'ゆうべ、じしんが ありました。', 'Tối qua có động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1810, 44221, '道に大きい石が落ちています。', 'みちに おおきい いしが おちて います。', 'Trên đường có hòn đá to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1811, 44232, 'ゆうべ近所で火事がありました。', 'ゆうべ きんじょで かじが ありました。', 'Tối qua gần nhà xảy ra hỏa hoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1812, 44235, '部屋の温度を少し上げてください。', 'へやの おんどを すこし あげて ください。', 'Hãy tăng nhiệt độ phòng lên một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1813, 44210, '環境を守ることは大切です。', 'かんきょうを まもる ことは たいせつ です。', 'Bảo vệ môi trường là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1814, 44238, '梅雨に入って、毎日雨が降っている。', 'つゆに はいって、まいにち あめが ふって いる。', 'Vào mùa mưa rồi, ngày nào cũng mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1815, 44237, 'どの季節が一番好きですか。', 'どの きせつが いちばん すき ですか。', 'Bạn thích mùa nào nhất?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1816, 44211, '世界で一番高い山はエベレストです。', 'せかいで いちばん たかい やまは エベレスト です。', 'Ngọn núi cao nhất thế giới là Everest.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1817, 27627, 'あしたは曇りでしょう。', 'あしたは くもり でしょう。', 'Ngày mai có lẽ trời nhiều mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1818, 44214, '今夜は月がきれいですね。', 'こんやは つきが きれい ですね。', 'Đêm nay trăng đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1819, 44234, '今日の気温は三十度です。', 'きょうの きおんは さんじゅうど です。', 'Nhiệt độ hôm nay là ba mươi độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1820, 44218, '家の後ろに林があります。', 'いえの うしろに はやしが あります。', 'Phía sau nhà có một khu rừng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1821, 44222, '子どもたちが砂で遊んでいます。', 'こどもたちが すなで あそんで います。', 'Bọn trẻ đang chơi cát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1822, 44223, '庭の草を取りました。', 'にわの くさを とりました。', 'Tôi nhổ cỏ trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1823, 44249, '地震で家が揺れました。', 'じしんで いえが ゆれました。', 'Động đất làm ngôi nhà rung lắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1824, 44251, '雨が止んだら、出かけましょう。', 'あめが やんだら、でかけましょう。', 'Mưa tạnh thì ra ngoài nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1825, 40811, '長年の夢がついに叶った。', 'ながねんの ゆめが ついに かなった。', 'Giấc mơ bao năm cuối cùng đã thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1826, 40813, '犬が紐を噛み切って逃げた。', 'いぬが ひもを かみきって にげた。', 'Con chó cắn đứt dây rồi chạy mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1827, 40834, 'ねじが緩んでいる。', 'ねじが ゆるんで いる。', 'Con ốc bị lỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1828, 40840, '利益の一部を社会に還元する。', 'りえきの いちぶを しゃかいに かんげん する。', 'Hoàn trả một phần lợi nhuận cho xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1829, 40843, '道を間違って、遅刻してしまった。', 'みちを まちがって、ちこく して しまった。', 'Tôi đi nhầm đường nên bị muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1830, 40850, '紙を丸めてゴミ箱に捨てた。', 'かみを まるめて ゴミばこに すてた。', 'Tôi vo tròn tờ giấy rồi vứt vào thùng rác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1831, 40866, '卒業生が図書館に本を寄贈した。', 'そつぎょうせいが としょかんに ほんを きぞう した。', 'Cựu học sinh đã tặng sách cho thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1832, 40891, '答案用紙に記名を忘れないでください。', 'とうあん ようしに きめいを わすれないで ください。', 'Đừng quên ghi tên vào giấy làm bài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1833, 27477, 'また今度お願いします。', 'またこんどおねがいします。', 'Hẹn lần sau', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1834, 44268, '宿題はほとんど終わりました。', 'しゅくだいは ほとんど おわりました。', 'Bài tập gần như xong hết rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1835, 44276, '姉に赤ちゃんが生まれました。', 'あねに あかちゃんが うまれました。', 'Chị tôi vừa sinh em bé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1836, 44277, '大人の料金は千円です。', 'おとなの りょうきんは せんえん です。', 'Giá vé người lớn là một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1837, 44255, '町の様子がずいぶん変わりました。', 'まちの ようすが ずいぶん かわりました。', 'Diện mạo thị trấn đã thay đổi nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1838, 44258, '服を汚さないように気をつけてください。', 'ふくを よごさない ように きを つけて ください。', 'Hãy cẩn thận đừng làm bẩn quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1839, 44263, 'このパンは柔らかいです。', 'この パンは やわらかい です。', 'Bánh mì này mềm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1840, 44264, 'この肉は硬いです。', 'この にくは かたい です。', 'Thịt này dai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1841, 44269, 'あなたの気持ちはよくわかります。', 'あなたの きもちは よく わかります。', 'Tôi rất hiểu cảm xúc của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1842, 44271, '母の愛はどんなものより深い。', 'ははの あいは どんな ものより ふかい。', 'Tình yêu của mẹ sâu nặng hơn bất cứ điều gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1843, 44262, '夜中に激しい雨が降った。', 'よなかに はげしい あめが ふった。', 'Nửa đêm trời mưa dữ dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1844, 44274, '彼女は東京に住んでいます。', 'かのじょは とうきょうに すんで います。', 'Cô ấy sống ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1845, 27434, 'どんなスポーツが好きですか。', 'どんな スポーツが すき ですか。', 'Bạn thích môn thể thao nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1846, 27436, '妹はダンスが上手です。', 'いもうとは ダンスが じょうず です。', 'Em gái tôi nhảy giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1847, 27440, 'クラシックの音楽をよく聞きます。', 'クラシックの おんがくを よく ききます。', 'Tôi hay nghe nhạc cổ điển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1848, 44259, 'この川は深いですから、泳がないでください。', 'この かわは ふかい ですから、およがないで ください。', 'Sông này sâu, đừng bơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1849, 44270, '心をこめて手紙を書きました。', 'こころを こめて てがみを かきました。', 'Tôi viết thư bằng cả tấm lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1850, 44279, '会社の先輩に仕事を教えてもらいました。', 'かいしゃの せんぱいに しごとを おしえて もらいました。', 'Tôi được đàn anh ở công ty chỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1851, 40916, '少し手を休めて、お茶にしよう。', 'すこし てを やすめて、おちゃに しよう。', 'Tạm nghỉ tay một chút uống trà nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1852, 40923, 'そんなに急かさないでください。', 'そんなに せかさないで ください。', 'Xin đừng giục giã như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1853, 40950, '午後から風が強まるでしょう。', 'ごごから かぜが つよまる でしょう。', 'Từ chiều gió có lẽ sẽ mạnh lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1854, 40954, '子供がおもちゃをねだった。', 'こどもが おもちゃを ねだった。', 'Đứa trẻ vòi mua đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1855, 40967, '犯人は店員をナイフで脅した。', 'はんにんは てんいんを ナイフで おどした。', 'Hung thủ dùng dao đe dọa nhân viên cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1856, 40992, '台風が近付いている。', 'たいふうが ちかづいて いる。', 'Bão đang đến gần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1857, 41001, '駆け足で駅に向かった。', 'かけあしで えきに むかった。', 'Tôi chạy vội tới ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1858, 41009, '砂糖に蟻が群がっている。', 'さとうに ありが むらがって いる。', 'Kiến bu đầy đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1859, 41019, '困っている人にお金を恵んだ。', 'こまって いる ひとに おかねを めぐんだ。', 'Tôi bố thí tiền cho người gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1860, 44573, '太陽が東から昇ります。', 'たいようが ひがしから のぼります。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1861, 44281, '駅で知り合いに会いました。', 'えきで しりあいに あいました。', 'Tôi gặp người quen ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1862, 44284, '朝、近所の人に挨拶をします。', 'あさ、きんじょの ひとに あいさつを します。', 'Buổi sáng tôi chào hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1863, 44288, '家族が元気で安心しました。', 'かぞくが げんきで あんしん しました。', 'Gia đình khỏe mạnh nên tôi yên tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2189, 27599, 'オーストラリアから来ました。', 'オーストラリアからきました。', 'Tôi đến từ Úc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1864, 44285, '弟とつまらないことで喧嘩した。', 'おとうとと つまらない ことで けんか した。', 'Tôi cãi nhau với em trai vì chuyện vớ vẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1865, 44290, '遠慮しないで、たくさん食べてください。', 'えんりょ しないで、たくさん たべて ください。', 'Đừng khách sáo, cứ ăn nhiều vào nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1866, 27442, 'あした、コンサートへ行きます。', 'あした、コンサートへ いきます。', 'Ngày mai tôi đi xem hòa nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1867, 27443, '金曜日、みんなでカラオケへ行きましょう。', 'きんようび、みんなで カラオケへ いきましょう。', 'Thứ Sáu mọi người cùng đi karaoke nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1868, 44293, '遅刻して、先生に怒られました。', 'ちこく して、せんせいに おこられました。', 'Đi muộn nên tôi bị thầy mắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1869, 44295, '映画を見て、泣きました。', 'えいがを みて、なきました。', 'Xem phim xong tôi đã khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1870, 44297, 'ニュースを聞いて驚きました。', 'ニュースを きいて おどろきました。', 'Nghe tin tôi đã rất ngạc nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1871, 44299, '先生に褒められて、うれしかったです。', 'せんせいに ほめられて、うれしかった です。', 'Được thầy khen nên tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1872, 41169, '二枚の写真を合成した。', 'にまいの しゃしんを ごうせい した。', 'Tôi ghép hai bức ảnh lại với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1873, 41029, '新しい機械で作業の負担が軽減された。', 'あたらしい きかいで さぎょうの ふたんが けいげん された。', 'Nhờ máy mới, gánh nặng công việc đã giảm nhẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1874, 41058, '包丁を研いだら、よく切れるようになった。', 'ほうちょうを といだら、よく きれる ように なった。', 'Mài dao xong thì dao cắt ngọt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1875, 41062, '駅で先生を見掛けた。', 'えきで せんせいを みかけた。', 'Tôi tình cờ thấy thầy giáo ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1876, 41070, '丘の上から町を見渡した。', 'おかの うえから まちを みわたした。', 'Từ trên đồi tôi phóng tầm mắt nhìn khắp thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1877, 41072, '大事な点を見落としていた。', 'だいじな てんを みおとして いた。', 'Tôi đã bỏ sót điểm quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1878, 41104, '棚を壁に固定した。', 'たなを かべに こてい した。', 'Tôi cố định giá lên tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1879, 41119, '彼は笑って話を誤魔化した。', 'かれは わらって はなしを ごまかした。', 'Anh ta cười trừ để lảng câu chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1880, 41121, '冗談を交えて話した。', 'じょうだんを まじえて はなした。', 'Tôi nói chuyện có xen lẫn đùa vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1881, 41164, '環境問題への関心が高まっている。', 'かんきょう もんだいへの かんしんが たかまって いる。', 'Mối quan tâm đến vấn đề môi trường đang tăng cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1882, 41182, '心を込めて手紙を書いた。', 'こころを こめて てがみを かいた。', 'Tôi viết thư bằng cả tấm lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1883, 41192, '車は急な坂に差し掛かった。', 'くるまは きゅうな さかに さしかかった。', 'Xe đã đến gần con dốc gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1884, 41194, '彼は笑顔で手を差し出した。', 'かれは えがおで てを さしだした。', 'Anh ấy tươi cười chìa tay ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1885, 41220, '靴が擦れて、かかとが痛い。', 'くつが すれて、かかとが いたい。', 'Giày cọ vào nên gót chân đau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1886, 44329, '健康のために、たばこをやめました。', 'けんこうの ために、たばこを やめました。', 'Vì sức khỏe, tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1887, 44324, 'やっと宿題が終わりました。', 'やっと しゅくだいが おわりました。', 'Cuối cùng bài tập cũng xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1888, 27484, 'ここはいろいろです。', 'ここはいろいろです。', 'Ở đây nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1889, 44304, '試験に合格できるように頑張ります。', 'しけんに ごうかく できる ように がんばります。', 'Tôi sẽ cố gắng để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1890, 44305, '駅で友達を迎えました。', 'えきで ともだちを むかえました。', 'Tôi đón bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1891, 44308, '合格して、とても嬉しいです。', 'ごうかく して、とても うれしい です。', 'Thi đỗ nên tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1892, 44309, '友達が国へ帰って、悲しいです。', 'ともだちが くにへ かえって、かなしい です。', 'Bạn về nước nên tôi buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1893, 44313, '夜一人で歩くのは怖いです。', 'よる ひとりで あるくのは こわい です。', 'Đi bộ một mình ban đêm thật đáng sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1894, 44316, 'パーティーに行けなくて残念です。', 'パーティーに いけなくて ざんねん です。', 'Tiếc quá vì không đi dự tiệc được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1895, 44335, 'けがをして、一週間入院した。', 'けがを して、いっしゅうかん にゅういん した。', 'Tôi bị thương và phải nằm viện một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1896, 44319, '仕事が多くて大変です。', 'しごとが おおくて たいへん です。', 'Công việc nhiều nên vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1897, 44322, '人の前でそんなことを言うのは失礼です。', 'ひとの まえで そんな ことを いうのは しつれい です。', 'Nói như thế trước mặt người khác là thất lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1898, 44321, '休みの日は自由に過ごしたい。', 'やすみの ひは じゆうに すごしたい。', 'Ngày nghỉ tôi muốn được tự do thoải mái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1899, 44312, 'この歌を聞くと、学生時代が懐かしくなる。', 'この うたを きくと、がくせい じだいが なつかしく なる。', 'Nghe bài hát này tôi lại nhớ thời sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1900, 27456, '週末、レストランでアルバイトをします。', 'しゅうまつ、レストランで アルバイトを します。', 'Cuối tuần tôi làm thêm ở nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1901, 27964, '僕はサッカーが好きだ。', 'ぼくは サッカーが すきだ。', 'Tớ thích bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1902, 44325, '日本語はなかなか上手になりません。', 'にほんごは なかなか じょうずに なりません。', 'Tiếng Nhật mãi không giỏi lên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2190, 27606, 'このりんごは近いです。', 'このりんごはちかいです。', 'Quả táo này gần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1903, 44332, 'きのうから熱があります。', 'きのうから ねつが あります。', 'Từ hôm qua tôi bị sốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1904, 44340, '寝る前に歯を磨きます。', 'ねる まえに はを みがきます。', 'Trước khi ngủ tôi đánh răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1905, 44326, 'たぶん、彼は来ないと思います。', 'たぶん、かれは こないと おもいます。', 'Có lẽ anh ấy sẽ không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1906, 44341, '首が痛いです。', 'くびが いたい です。', 'Tôi bị đau cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1907, 44331, '風邪をひいて、学校を休みました。', 'かぜを ひいて、がっこうを やすみました。', 'Bị cảm nên tôi nghỉ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1908, 44342, '喉が渇きました。', 'のどが かわきました。', 'Tôi khát nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1909, 41234, '駅前でチラシを散蒔いている人がいた。', 'えきまえで チラシを ばらまいて いる ひとが いた。', 'Có người đang rải tờ rơi trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1910, 41250, '徹夜してレポートを仕上げた。', 'てつや して レポートを しあげた。', 'Tôi thức trắng đêm để hoàn thành báo cáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1911, 41271, '医者は応急処置を施した。', 'いしゃは おうきゅう しょちを ほどこした。', 'Bác sĩ đã tiến hành sơ cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1912, 41274, '被害は最小限にとどまった。', 'ひがいは さいしょうげんに とどまった。', 'Thiệt hại chỉ dừng ở mức tối thiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1913, 41284, 'これは初めての試みだ。', 'これは はじめての こころみだ。', 'Đây là lần thử nghiệm đầu tiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1914, 44353, '兄は力が強いです。', 'あには ちからが つよい です。', 'Anh tôi rất khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1915, 44382, 'この町は安全です。', 'この まちは あんぜん です。', 'Thị trấn này an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1916, 44354, '毎朝、軽い運動をしています。', 'まいあさ、かるい うんどうを して います。', 'Sáng nào tôi cũng vận động nhẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1917, 44356, '今晩一緒に食事をしませんか。', 'こんばん いっしょに しょくじを しませんか。', 'Tối nay cùng đi ăn không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1918, 44369, '赤ちゃんがよく眠っています。', 'あかちゃんが よく ねむって います。', 'Em bé đang ngủ ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1919, 44352, '魚の骨がのどに刺さった。', 'さかなの ほねが のどに ささった。', 'Xương cá bị hóc trong cổ họng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1920, 44373, '母の病気が心配です。', 'ははの びょうきが しんぱい です。', 'Tôi lo cho bệnh của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1921, 44376, '熱があって、体がだるいです。', 'ねつが あって、からだが だるい です。', 'Tôi bị sốt nên người uể oải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1922, 44377, '走りすぎて、息が苦しい。', 'はしりすぎて、いきが くるしい。', 'Chạy nhiều quá nên thở không nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1923, 44381, 'この川で泳ぐのは危険です。', 'この かわで およぐのは きけん です。', 'Bơi ở con sông này rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1924, 44384, '旅行にパスポートが必要です。', 'りょこうに パスポートが ひつよう です。', 'Đi du lịch cần có hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1925, 41296, '二人の作品はよく似通っている。', 'ふたりの さくひんは よく にかよって いる。', 'Tác phẩm của hai người rất giống nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1926, 27485, 'あそこに男の人がいます。', 'あそこに おとこの ひとが います。', 'Đằng kia có một người đàn ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1927, 27486, '受付に女の人がいます。', 'うけつけに おんなの ひとが います。', 'Ở quầy lễ tân có một người phụ nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1928, 27487, '公園で男の子が遊んでいます。', 'こうえんで おとこの こが あそんで います。', 'Có một cậu bé đang chơi trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1929, 44347, '妹は髪が長いです。', 'いもうとは かみが ながい です。', 'Em gái tôi tóc dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1930, 44344, 'ナイフで指を切りました。', 'ナイフで ゆびを きりました。', 'Tôi bị dao cắt vào ngón tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1931, 44346, '背中がかゆいです。', 'せなかが かゆい です。', 'Lưng tôi ngứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1932, 44374, '歯が痛いです。', 'はが いたい です。', 'Tôi bị đau răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1933, 44379, 'A：大丈夫ですか。B：はい、大丈夫です。', 'エー：だいじょうぶ ですか。ビー：はい、だいじょうぶ です。', 'A: Bạn ổn chứ? B: Vâng, tôi không sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1934, 41302, 'お客様を手料理で持て成した。', 'おきゃくさまを てりょうりで もてなした。', 'Tôi tiếp đãi khách bằng món ăn tự nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1935, 41363, 'お電話を担当者にお取り次ぎします。', 'おでんわを たんとうしゃに おとりつぎ します。', 'Tôi xin chuyển máy cho người phụ trách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1936, 41365, 'サイズが合わない場合は取り替えができます。', 'サイズが あわない ばあいは とりかえが できます。', 'Nếu không vừa cỡ thì có thể đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1937, 41370, '借金を厳しく取り立てられた。', 'しゃっきんを きびしく とりたてられた。', 'Tôi bị đòi nợ gắt gao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1938, 41396, '彼は父の店を受け継いだ。', 'かれは ちちの みせを うけついだ。', 'Anh ấy kế thừa cửa hàng của bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1939, 41398, 'この大学は留学生の受け入れに積極的だ。', 'この だいがくは りゅうがくせいの うけいれに せっきょくてきだ。', 'Trường đại học này tích cực tiếp nhận du học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1940, 41402, '師匠は弟子に秘伝を授けた。', 'ししょうは でしに ひでんを さずけた。', 'Sư phụ truyền bí quyết cho đệ tử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1941, 44411, '給料は毎月二十五日にもらいます。', 'きゅうりょうは まいつき にじゅうごにちに もらいます。', 'Tôi nhận lương vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1942, 44397, 'お客様、こちらへどうぞ。', 'おきゃくさま、こちらへ どうぞ。', 'Thưa quý khách, mời đi lối này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1943, 44399, 'この工場では車を作っています。', 'この こうじょうでは くるまを つくって います。', 'Nhà máy này sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1944, 44400, 'パーティーの会場はホテルです。', 'パーティーの かいじょうは ホテル です。', 'Địa điểm tổ chức tiệc là khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1945, 44385, 'なるべく早く来てください。', 'なるべく はやく きて ください。', 'Hãy đến sớm nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1946, 44388, '早く起きてください。', 'はやく おきて ください。', 'Dậy sớm đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1947, 44405, '仕事のことで先輩に相談しました。', 'しごとの ことで せんぱいに そうだん しました。', 'Tôi xin ý kiến đàn anh về công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1948, 44415, '夏休みの計画を立てました。', 'なつやすみの けいかくを たてました。', 'Tôi đã lên kế hoạch cho kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1949, 41413, '台風が九州を襲った。', 'たいふうが きゅうしゅうを おそった。', 'Bão đã tấn công Kyushu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1950, 41431, '二人の距離が少しずつ縮まった。', 'ふたりの きょりが すこしずつ ちぢまった。', 'Khoảng cách giữa hai người dần rút ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1951, 41440, '失敗したので、一からの出直しだ。', 'しっぱい したので、いちからの でなおしだ。', 'Thất bại rồi nên phải làm lại từ đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1952, 41446, 'アルバイトの待遇は正社員に準じる。', 'アルバイトの たいぐうは せいしゃいんに じゅんじる。', 'Đãi ngộ của nhân viên bán thời gian dựa theo nhân viên chính thức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1953, 41449, 'けが人は病院で処置を受けた。', 'けがにんは びょういんで しょちを うけた。', 'Người bị thương đã được xử lý vết thương tại bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1954, 44257, '約束は必ず守ります。', 'やくそくは かならず まもります。', 'Tôi nhất định sẽ giữ lời hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1955, 44396, '仕事のあと、同僚と飲みに行った。', 'しごとの あと、どうりょうと のみに いった。', 'Tan làm, tôi đi uống với đồng nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1956, 44403, '友達と三時に会う約束があります。', 'ともだちと さんじに あう やくそくが あります。', 'Tôi có hẹn gặp bạn lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1957, 44406, '先生が文法をわかりやすく説明してくれました。', 'せんせいが ぶんぽうを わかりやすく せつめい して くれました。', 'Thầy giáo giải thích ngữ pháp rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1958, 44408, '来週、大阪へ出張します。', 'らいしゅう、おおさかへ しゅっちょう します。', 'Tuần sau tôi đi công tác Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1959, 44417, 'この会社は高い技術を持っている。', 'この かいしゃは たかい ぎじゅつを もって いる。', 'Công ty này có kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1960, 27495, '時計の電池が切れた。', 'とけいの でんちが きれた。', 'Pin đồng hồ đã hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1961, 27490, '机の下に猫がいます。', 'つくえの したに ねこが います。', 'Dưới gầm bàn có con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1962, 27492, '動物園に象がいます。', 'どうぶつえんに ぞうが います。', 'Trong sở thú có voi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1963, 27493, '家の前に大きい木があります。', 'いえの まえに おおきい きが あります。', 'Trước nhà có một cái cây to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1964, 44391, '社長は今、出張中です。', 'しゃちょうは いま、しゅっちょうちゅう です。', 'Giám đốc hiện đang đi công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1965, 44393, '課長は今会議中です。', 'かちょうは いま かいぎちゅう です。', 'Trưởng nhóm hiện đang họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1966, 44387, 'あしたはきっと晴れるでしょう。', 'あしたは きっと はれるでしょう。', 'Ngày mai chắc chắn trời sẽ nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1967, 44419, '政治にはあまり興味がありません。', 'せいじには あまり きょうみが ありません。', 'Tôi không quan tâm lắm đến chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1968, 44585, '強い風で木の枝が折れました。', 'つよい かぜで きの えだが おれました。', 'Gió mạnh làm gãy cành cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1969, 44434, '注文した本が届きました。', 'ちゅうもん した ほんが とどきました。', 'Cuốn sách tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1970, 44436, '母の料理を手伝いました。', 'ははの りょうりを てつだいました。', 'Tôi giúp mẹ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1971, 44438, '電車が十分遅れています。', 'でんしゃが じゅっぷん おくれて います。', 'Tàu đang trễ mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1972, 44433, '拾った財布を交番に届けた。', 'ひろった さいふを こうばんに とどけた。', 'Tôi mang chiếc ví nhặt được đến đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1973, 27496, '箱の中に何がありますか。', 'はこの なかに なにが ありますか。', 'Trong hộp có gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1974, 27498, '冷蔵庫に牛乳があります。', 'れいぞうこに ぎゅうにゅうが あります。', 'Trong tủ lạnh có sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1975, 27501, '棚の上に本があります。', 'たなの うえに ほんが あります。', 'Trên giá có sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1976, 27503, '窓を開けてください。', 'まどを あけて ください。', 'Hãy mở cửa sổ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1977, 44449, '日本の生活はどうですか。', 'にほんの せいかつは どう ですか。', 'Cuộc sống ở Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1978, 44440, 'たばこをやめました。', 'たばこを やめました。', 'Tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1979, 44442, '駅の前に人が集まっています。', 'えきの まえに ひとが あつまって います。', 'Trước ga có nhiều người đang tụ tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1980, 44444, '今日は特別な日です。', 'きょうは とくべつな ひ です。', 'Hôm nay là một ngày đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1981, 44446, 'この問題は複雑です。', 'この もんだいは ふくざつ です。', 'Vấn đề này phức tạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1982, 44453, '大家さんに家賃を払いました。', 'おおやさんに やちんを はらいました。', 'Tôi trả tiền thuê nhà cho chủ nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1983, 41456, '彼は麻薬の所持で逮捕された。', 'かれは まやくの しょじで たいほ された。', 'Hắn bị bắt vì tàng trữ ma túy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1984, 41472, '健康は何物にも勝る。', 'けんこうは なにものにも まさる。', 'Sức khỏe hơn mọi thứ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1985, 41500, '売り上げが予想を上回った。', 'うりあげが よそうを うわまわった。', 'Doanh thu đã vượt dự kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2107, 37695, '毎日ピアノを練習します。', 'まいにち ピアノを れんしゅう します。', 'Ngày nào tôi cũng tập piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1986, 41507, '会社が外国企業に乗っ取られた。', 'かいしゃが がいこく きぎょうに のっとられた。', 'Công ty bị doanh nghiệp nước ngoài thâu tóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1987, 41528, '他国の領空を侵してはならない。', 'たこくの りょうくうを おかしては ならない。', 'Không được xâm phạm không phận nước khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1988, 41547, '留学生との交流で理解を深めた。', 'りゅうがくせいとの こうりゅうで りかいを ふかめた。', 'Nhờ giao lưu với du học sinh, sự hiểu biết đã sâu sắc hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1989, 41577, '彼女は肩を震わせて泣いていた。', 'かのじょは かたを ふるわせて ないて いた。', 'Cô ấy khóc run cả vai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1990, 41599, '入院が長引いて、医療費が嵩んだ。', 'にゅういんが ながびいて、いりょうひが かさんだ。', 'Nằm viện kéo dài nên viện phí chồng chất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1991, 41688, '門を潜ると、きれいな庭が広がっていた。', 'もんを くぐると、きれいな にわが ひろがって いた。', 'Bước qua cổng thì thấy một khu vườn đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1992, 41720, '彼は三か国語を自由に操る。', 'かれは さんかこくごを じゆうに あやつる。', 'Anh ấy sử dụng thành thạo ba thứ tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1993, 41729, 'その事件は闇に葬られた。', 'その じけんは やみに ほうむられた。', 'Vụ việc đó đã bị vùi lấp vào bóng tối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1994, 27508, '公園へ行きます。', 'こうえんへいきます。', 'Tôi đi đến công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1995, 27961, 'ビザが要ります。', 'ビザがいります。', 'Cần visa', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1996, 45343, 'まとめて買うとお得です。', 'まとめて かうと おとく です。', 'Mua cả lô thì được hời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1997, 27506, '駅の中にATMがあります。', 'えきの なかに エーティーエムが あります。', 'Trong ga có máy ATM.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1998, 44474, 'このスープは味が薄いです。', 'この スープは あじが うすい です。', 'Món súp này nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (1999, 44587, '朝、鳥の声が聞こえます。', 'あさ、とりの こえが きこえます。', 'Buổi sáng nghe thấy tiếng chim hót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2000, 44489, 'テレビが壊れてしまいました。', 'テレビが こわれて しまいました。', 'Tivi bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2001, 44491, '壊れた時計を直しました。', 'こわれた とけいを なおしました。', 'Tôi đã sửa chiếc đồng hồ hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2002, 44494, '木から葉が落ちています。', 'きから はが おちて います。', 'Lá đang rơi từ trên cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2003, 44495, '本を棚に並べました。', 'ほんを たなに ならべました。', 'Tôi xếp sách lên giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2004, 44497, 'ここに車を止めてもいいですか。', 'ここに くるまを とめても いい ですか。', 'Tôi đỗ xe ở đây được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2005, 44499, 'プレゼントを紙で包みました。', 'プレゼントを かみで つつみました。', 'Tôi gói quà bằng giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2006, 44502, '隣の部屋がうるさくて、眠れません。', 'となりの へやが うるさくて、ねむれません。', 'Phòng bên ồn quá, tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2007, 44504, '丁寧に説明してくれました。', 'ていねいに せつめい して くれました。', 'Họ đã giải thích cẩn thận cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2008, 44507, 'しっかり勉強してください。', 'しっかり べんきょう して ください。', 'Hãy học hành chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2009, 41753, '無理をすると健康を損なう。', 'むりを すると けんこうを そこなう。', 'Gắng sức quá sẽ hại sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2010, 41789, '彼は第一線から退いた。', 'かれは だいいっせんから しりぞいた。', 'Ông ấy đã lui khỏi tuyến đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2011, 41792, '桃太郎は鬼を退治した。', 'ももたろうは おにを たいじ した。', 'Momotaro đã diệt trừ lũ quỷ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2012, 41809, '患者は危険な状態を脱した。', 'かんじゃは きけんな じょうたいを だっした。', 'Bệnh nhân đã thoát khỏi tình trạng nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2013, 41813, '記憶を辿って、昔の家を探した。', 'きおくを たどって、むかしの いえを さがした。', 'Tôi lần theo ký ức để tìm ngôi nhà cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2014, 41832, '久しぶりに友達と会って、話が弾んだ。', 'ひさしぶりに ともだちと あって、はなしが はずんだ。', 'Lâu rồi mới gặp bạn nên trò chuyện rôm rả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2015, 41878, '体操選手が見事な宙返りを見せた。', 'たいそう せんしゅが みごとな ちゅうがえりを みせた。', 'Vận động viên thể dục trình diễn cú lộn nhào tuyệt đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2016, 41906, '彼は疲れた体を湯船に沈めた。', 'かれは つかれた からだを ゆぶねに しずめた。', 'Anh ấy ngâm cơ thể mệt mỏi vào bồn tắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2017, 41908, '嵐で船が沈没した。', 'あらしで ふねが ちんぼつ した。', 'Con tàu bị chìm trong cơn bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2018, 41957, '景気は回復に転じた。', 'けいきは かいふくに てんじた。', 'Kinh tế đã chuyển sang phục hồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2019, 41962, '聖火台に点火された。', 'せいかだいに てんか された。', 'Đài đuốc thiêng đã được châm lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2020, 42104, '彼は親の期待に背いた。', 'かれは おやの きたいに そむいた。', 'Anh ta đã phụ lòng kỳ vọng của bố mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2021, 44515, '寝る前に小説を読みます。', 'ねる まえに しょうせつを よみます。', 'Trước khi ngủ tôi đọc tiểu thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2022, 44517, 'この番組はとてもおもしろいです。', 'この ばんぐみは とても おもしろい です。', 'Chương trình này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2023, 42134, '授業を抜け出して、屋上へ行った。', 'じゅぎょうを ぬけだして、おくじょうへ いった。', 'Tôi lẻn khỏi lớp lên sân thượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2024, 42137, '結果は予想に反していた。', 'けっかは よそうに はんして いた。', 'Kết quả trái với dự đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2025, 42193, '最後に一言付け加えたいことがあります。', 'さいごに ひとこと つけくわえたい ことが あります。', 'Cuối cùng tôi muốn bổ sung một lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2026, 42207, '政治の腐敗が問題になっている。', 'せいじの ふはいが もんだいに なって いる。', 'Sự thối nát chính trị đang là vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2027, 44514, '日曜日、映画を見ます。', 'にちようび、えいがを みます。', 'Chủ nhật tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2028, 44512, '日本の歌が好きです。', 'にほんの うたが すき です。', 'Tôi thích các bài hát Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2029, 44513, '妹は絵が上手です。', 'いもうとは えが じょうず です。', 'Em gái tôi vẽ tranh giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2030, 27512, '大阪の隣は奈良県です。', 'おおさかの となりは ならけん です。', 'Bên cạnh Osaka là tỉnh Nara.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2031, 27513, '机の上に写真があります。', 'つくえの うえに しゃしんが あります。', 'Trên bàn có bức ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2032, 27514, 'いすの下にかばんがあります。', 'いすの したに かばんが あります。', 'Dưới ghế có chiếc cặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2033, 27515, '駅の前で待っています。', 'えきの まえで まって います。', 'Tôi đang đợi trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2034, 27517, '銀行の右に郵便局があります。', 'ぎんこうの みぎに ゆうびんきょくが あります。', 'Bên phải ngân hàng có bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2035, 27519, 'かばんの中に財布があります。', 'かばんの なかに さいふが あります。', 'Trong cặp có chiếc ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2036, 42219, '手紙の封を切った。', 'てがみの ふうを きった。', 'Tôi bóc niêm phong lá thư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2037, 42274, '沖縄は一九七二年に日本に返還された。', 'おきなわは せんきゅうひゃく ななじゅうにねんに にほんに へんかん された。', 'Okinawa được trao trả cho Nhật năm 1972.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2038, 42304, '神前に供え物を奉った。', 'しんぜんに そなえものを たてまつった。', 'Đã dâng lễ vật trước thần linh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2039, 42309, '彼は仕事を途中で放り出した。', 'かれは しごとを とちゅうで ほうりだした。', 'Anh ta vứt bỏ công việc giữa chừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2040, 42313, '駅前に自転車を放置しないでください。', 'えきまえに じてんしゃを ほうち しないで ください。', 'Xin đừng bỏ xe đạp bừa bãi trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2041, 42355, 'グラスに水を満たした。', 'グラスに みずを みたした。', 'Tôi rót đầy nước vào cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2042, 42468, 'その一言で決心が揺らいだ。', 'その ひとことで けっしんが ゆらいだ。', 'Chỉ một câu nói đó mà quyết tâm của tôi lung lay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2043, 42495, '工事現場で落下事故が起きた。', 'こうじ げんばで らっか じこが おきた。', 'Đã xảy ra tai nạn rơi ngã ở công trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2044, 42498, '事故でダイヤが乱れている。', 'じこで ダイヤが みだれて いる。', 'Do tai nạn, lịch chạy tàu bị xáo trộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2045, 42536, '彼は毎日練習に励んでいる。', 'かれは まいにち れんしゅうに はげんで いる。', 'Anh ấy ngày nào cũng chăm chỉ luyện tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2046, 42540, '遠くに山々が連なっている。', 'とおくに やまやまが つらなって いる。', 'Xa xa núi non trùng điệp nối tiếp nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2047, 42552, 'ガスが漏れているような臭いがする。', 'ガスが もれて いる ような においが する。', 'Có mùi như gas bị rò rỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2048, 44549, '試合に勝ちました。', 'しあいに かちました。', 'Chúng tôi đã thắng trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2049, 44553, '結婚式に招待されました。', 'けっこんしきに しょうたい されました。', 'Tôi được mời dự đám cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2050, 27524, 'など～や ～。', 'など～や ～。', 'Sách, vở, v.v.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2051, 44556, 'いい店を見つけました。', 'いい みせを みつけました。', 'Tôi tìm được một quán ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2052, 44558, '昨日のパーティーは楽しかったです。', 'きのうの パーティーは たのしかった です。', 'Bữa tiệc hôm qua rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2053, 44560, 'この映画はつまらないです。', 'この えいがは つまらない です。', 'Bộ phim này chán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2054, 44562, '山の上からの景色は素晴らしかったです。', 'やまの うえからの けしきは すばらしかった です。', 'Phong cảnh từ trên núi thật tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2055, 37870, 'これは画期的な発明だ。', 'これは かっきてきな はつめいだ。', 'Đây là một phát minh mang tính đột phá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2056, 44551, 'みんなで日本チームを応援した。', 'みんなで にほん チームを おうえん した。', 'Mọi người cùng cổ vũ đội tuyển Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2057, 27520, '外は寒いです。', 'そとは さむい です。', 'Bên ngoài lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2058, 27522, 'この近くに病院がありますか。', 'この ちかくに びょういんが ありますか。', 'Gần đây có bệnh viện không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2059, 27523, '銀行と花屋の間にコンビニがあります。', 'ぎんこうと はなやの あいだに コンビニが あります。', 'Giữa ngân hàng và tiệm hoa có cửa hàng tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2060, 27528, '本は棚のいちばん下にあります。', 'ほんは たなの いちばん したに あります。', 'Sách ở ngăn dưới cùng của giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2061, 44568, 'ぜひ一度、うちへ来てください。', 'ぜひ いちど、うちへ きて ください。', 'Nhất định hãy đến nhà tôi chơi một lần nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2062, 44564, '彼はとても熱心に勉強しています。', 'かれは とても ねっしんに べんきょう して います。', 'Anh ấy học rất chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2063, 44566, '私は数学が苦手です。', 'わたしは すうがくが にがて です。', 'Tôi kém môn toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2064, 42586, '雨で手紙の字が滲んでしまった。', 'あめで てがみの じが にじんで しまった。', 'Vì mưa, chữ trong lá thư bị nhòe mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2065, 42601, '古い床が歩くたびに軋む。', 'ふるい ゆかが あるく たびに きしむ。', 'Sàn nhà cũ kêu cọt kẹt mỗi khi bước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2066, 31832, '彼女は卓越した語学力を持っている。', 'かのじょは たくえつ した ごがくりょくを もって いる。', 'Cô ấy có năng lực ngoại ngữ xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2067, 37869, '陳腐な表現は避けたほうがいい。', 'ちんぷな ひょうげんは さけた ほうが いい。', 'Nên tránh những cách diễn đạt sáo rỗng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2068, 40387, 'この学校はインターナショナルな雰囲気がある。', 'この がっこうは インターナショナルな ふんいきが ある。', 'Trường này có bầu không khí quốc tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2069, 40393, 'オートマチックの車しか運転できない。', 'オートマチックの くるましか うんてん できない。', 'Tôi chỉ lái được xe số tự động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2070, 40444, 'シックな色の家具でそろえた。', 'シックな いろの かぐで そろえた。', 'Tôi chọn đồng bộ đồ nội thất màu sang trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2071, 40648, '参加者は一様に驚いた顔をした。', 'さんかしゃは いちように おどろいた かおを した。', 'Những người tham gia đều tỏ vẻ ngạc nhiên như nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2072, 40697, '子供の心には汚れがない。', 'こどもの こころには けがれが ない。', 'Tâm hồn trẻ thơ không vướng chút ô uế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2073, 40703, '黄金に輝く稲穂が実った。', 'おうごんに かがやく いなほが みのった。', 'Bông lúa chín vàng óng ánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2074, 40737, '桜の命は儚い。', 'さくらの いのちは はかない。', 'Đời hoa anh đào thật ngắn ngủi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2075, 44575, '田舎では星がたくさん見えます。', 'いなかでは ほしが たくさん みえます。', 'Ở quê có thể nhìn thấy nhiều sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2076, 44591, '昨夜、地震がありました。', 'ゆうべ、じしんが ありました。', 'Tối qua có động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2077, 44576, '船で島へ行きました。', 'ふねで しまへ いきました。', 'Tôi đi ra đảo bằng thuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2078, 44590, '台風で電車が止まりました。', 'たいふうで でんしゃが とまりました。', 'Tàu điện ngừng chạy vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2079, 44593, '山の空気はきれいです。', 'やまの くうきは きれい です。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2080, 44570, '環境を守ることは大切です。', 'かんきょうを まもる ことは たいせつ です。', 'Bảo vệ môi trường là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2081, 44287, '新しい計画は大成功でした。', 'あたらしい けいかくは だいせいこう でした。', 'Kế hoạch mới đã thành công rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2082, 27532, '駅の前に本屋があります。', 'えきの まえに ほんやが あります。', 'Trước ga có hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2083, 27533, 'かばんは棚のいちばん上にあります。', 'かばんは たなの いちばん うえに あります。', 'Chiếc cặp ở ngăn trên cùng của giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2084, 27534, 'しょうゆは上から二段目にあります。', 'しょうゆは うえから にだんめに あります。', 'Xì dầu ở kệ thứ hai từ trên xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2085, 27536, 'トイレは店の奥にあります。', 'トイレは みせの おくに あります。', 'Nhà vệ sinh ở phía trong cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2086, 44597, 'どの季節が一番好きですか。', 'どの きせつが いちばん すき ですか。', 'Bạn thích mùa nào nhất?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2087, 27491, '上野動物園にパンダがいます。', 'うえの どうぶつえんに パンダが います。', 'Sở thú Ueno có gấu trúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2088, 44588, 'どんな動物が好きですか。', 'どんな どうぶつが すき ですか。', 'Bạn thích con vật nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2089, 44572, '地球は丸いです。', 'ちきゅうは まるい です。', 'Trái đất hình tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2090, 44600, '隣の部屋から音が聞こえます。', 'となりの へやから おとが きこえます。', 'Có tiếng động từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2091, 44599, '窓から光が入ります。', 'まどから ひかりが はいります。', 'Ánh sáng chiếu vào qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2092, 44577, '森の中を散歩しました。', 'もりの なかを さんぽ しました。', 'Tôi đi dạo trong rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2093, 44579, '湖でボートに乗りました。', 'みずうみで ボートに のりました。', 'Tôi đi thuyền trên hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2094, 44582, '子どもたちが砂で遊んでいます。', 'こどもたちが すなで あそんで います。', 'Bọn trẻ đang chơi cát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2095, 44586, '夏は虫が多いです。', 'なつは むしが おおい です。', 'Mùa hè có nhiều côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2096, 40747, 'パーティー会場は華やかな雰囲気だった。', 'パーティー かいじょうは はなやかな ふんいき だった。', 'Hội trường tiệc mang bầu không khí rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2097, 40749, '彼女は華奢な体つきをしている。', 'かのじょは きゃしゃな からだつきを して いる。', 'Cô ấy có dáng người mảnh mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2098, 40781, 'この建物は外観が美しい。', 'この たてものは がいかんが うつくしい。', 'Tòa nhà này có bề ngoài đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2099, 40809, 'このクリームを塗ると肌が滑らかになる。', 'この クリームを ぬると はだが なめらかに なる。', 'Thoa kem này da sẽ mịn màng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2100, 40836, '肝心な時に限って、パソコンが壊れる。', 'かんじんな ときに かぎって、パソコンが こわれる。', 'Cứ đúng lúc quan trọng là máy tính lại hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2101, 40892, '命は何よりも貴い。', 'いのちは なによりも たっとい。', 'Sinh mạng quý hơn tất cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2102, 40955, '彼の第一印象は強烈だった。', 'かれの だいいち いんしょうは きょうれつ だった。', 'Ấn tượng đầu tiên về anh ấy rất mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2103, 41005, '彼は空ろな目で窓の外を見ていた。', 'かれは うつろな めで まどの そとを みて いた。', 'Anh ấy nhìn ra cửa sổ với ánh mắt trống rỗng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2104, 44628, '宿題はほとんど終わりました。', 'しゅくだいは ほとんど おわりました。', 'Bài tập gần như xong hết rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2105, 37693, 'あした三時に会うと約束しました。', 'あした さんじに あうと やくそく しました。', 'Tôi đã hẹn gặp lúc ba giờ ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2106, 44292, '悪いと思ったら、すぐに謝りなさい。', 'わるいと おもったら、すぐに あやまりなさい。', 'Nếu thấy mình sai thì xin lỗi ngay đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2108, 41763, '彼はうわさの打ち消しに必死だった。', 'かれは うわさの うちけしに ひっし だった。', 'Anh ta ra sức phủ nhận tin đồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2109, 41048, '月並みな言葉ですが、おめでとうございます。', 'つきなみな ことば ですが、おめでとう ございます。', 'Lời thì bình thường thôi, nhưng xin chúc mừng anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2110, 44303, '朝晩は少し寒さを感じるようになりました。', 'あさばんは すこし さむさを かんじる ように なりました。', 'Sáng tối đã bắt đầu thấy hơi lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2111, 44349, '今日は気分がいいので、散歩に行きます。', 'きょうは きぶんが いいので、さんぽに いきます。', 'Hôm nay tâm trạng tốt nên tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2112, 44394, '上司に休みを取ってもいいか聞いた。', 'じょうしに やすみを とっても いいか きいた。', 'Tôi hỏi cấp trên xem có được nghỉ phép không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2113, 44395, '部長は部下にとても優しい。', 'ぶちょうは ぶかに とても やさしい。', 'Trưởng phòng rất tử tế với cấp dưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2114, 39540, '日本語を始めたきっかけはアニメだった。', 'にほんごを はじめた きっかけは アニメ だった。', 'Tôi bắt đầu học tiếng Nhật nhờ anime.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2115, 27497, '電気のスイッチはドアの右です。', 'でんきの スイッチは ドアの みぎ です。', 'Công tắc điện ở bên phải cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2116, 27499, 'テーブルの上に花があります。', 'テーブルの うえに はなが あります。', 'Trên bàn có hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2117, 27500, 'ベッドの下に猫がいます。', 'ベッドの したに ねこが います。', 'Dưới gầm giường có con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2118, 27502, 'ドアを閉めてください。', 'ドアを しめて ください。', 'Hãy đóng cửa lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2119, 27504, 'ポストは郵便局の前にあります。', 'ポストは ゆうびんきょくの まえに あります。', 'Hộp thư ở trước bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2120, 27505, 'あの白いビルは病院です。', 'あの しろい ビルは びょういん です。', 'Tòa nhà trắng kia là bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2121, 27526, 'ナンプラーはどこにありますか。', 'ナンプラーは どこに ありますか。', 'Nước mắm Thái để ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2122, 27530, 'アジアストアでタイの料理の材料を買いました。', 'アジアストアで タイの りょうりの ざいりょうを かいました。', 'Tôi mua nguyên liệu món Thái ở Asia Store.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2123, 27531, 'カメラのフィルムを買いました。', 'カメラの フィルムを かいました。', 'Tôi mua cuộn phim cho máy ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2124, 27535, 'チリソースは辛いです。', 'チリソースは からい です。', 'Tương ớt cay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2125, 27538, 'ユニューア・ストアは駅の近くです。', 'ユニューア・ストアは えきの ちかく です。', 'Uniyua Store ở gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2126, 41059, '彼は見すぼらしい服を着ていた。', 'かれは みすぼらしい ふくを きて いた。', 'Ông ấy mặc bộ quần áo tồi tàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2127, 41074, '今は何も言わないほうが賢明だ。', 'いまは なにも いわない ほうが けんめいだ。', 'Lúc này không nói gì là khôn ngoan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2128, 41126, 'この布には美しい光沢がある。', 'この ぬのには うつくしい こうたくが ある。', 'Tấm vải này có độ bóng đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2129, 41142, '彼は巧みな話術で客を引きつけた。', 'かれは たくみな わじゅつで きゃくを ひきつけた。', 'Anh ấy thu hút khách bằng tài ăn nói khéo léo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2130, 27540, '日本にいます。', 'にほんにいます。', 'Có (động vật)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2131, 27542, '会社を休みます。', 'かいしゃをやすみます。', 'Nghỉ ngơi, nghỉ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2132, 41774, '雑誌で作家と俳優の対談が行われた。', 'ざっしで さっかと はいゆうの たいだんが おこなわれた。', 'Tạp chí tổ chức cuộc trò chuyện giữa nhà văn và diễn viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2133, 27578, '外国から来ました。', 'がいこくからきました。', 'Tôi đến từ ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2134, 44398, 'まず一階の受付で名前を言ってください。', 'まず いっかいの うけつけで なまえを いって ください。', 'Trước tiên hãy báo tên ở quầy lễ tân tầng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2135, 44402, 'レストランを七時に予約しました。', 'レストランを しちじに よやく しました。', 'Tôi đã đặt nhà hàng lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2136, 27541, 'うちから会社まで一時間かかります。', 'うちから かいしゃまで いちじかん かかります。', 'Từ nhà đến công ty mất một tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2137, 27543, 'りんごを一つください。', 'りんごを ひとつ ください。', 'Cho tôi một quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2138, 27545, 'みかんを三つ買いました。', 'みかんを みっつ かいました。', 'Tôi đã mua ba quả quýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2139, 27546, '卵が四つあります。', 'たまごが よっつ あります。', 'Có bốn quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2140, 27548, 'ケーキを六つ買いました。', 'ケーキを むっつ かいました。', 'Tôi đã mua sáu cái bánh ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2141, 27549, 'いすが七つあります。', 'いすが ななつ あります。', 'Có bảy cái ghế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2142, 27550, 'りんごを八つください。', 'りんごを やっつ ください。', 'Cho tôi tám quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2143, 27552, 'みかんを十ください。', 'みかんを とお ください。', 'Cho tôi mười quả quýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2144, 27554, '私は一人で住んでいます。', 'わたしは ひとりで すんで います。', 'Tôi sống một mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2145, 27555, '子どもが二人います。', 'こどもが ふたり います。', 'Tôi có hai con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2146, 27556, 'クラスに学生が二十人います。', 'クラスに がくせいが にじゅうにん います。', 'Lớp có hai mươi học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2147, 27558, '八十円の切手を五枚ください。', 'はちじゅうえんの きってを ごまい ください。', 'Cho tôi năm con tem loại tám mươi yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2148, 27559, '一週間に三回、テニスをします。', 'いっしゅうかんに さんかい、テニスを します。', 'Một tuần tôi chơi tennis ba lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2149, 27561, '冬はみかんがおいしいです。', 'ふゆは みかんが おいしい です。', 'Mùa đông quýt ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2150, 27565, '郵便局で切手を買います。', 'ゆうびんきょくで きってを かいます。', 'Tôi mua tem ở bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2151, 27566, '旅行先から友達にはがきを書きました。', 'りょこうさきから ともだちに はがきを かきました。', 'Tôi viết bưu thiếp cho bạn từ nơi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2152, 27568, '両親はベトナムに住んでいます。', 'りょうしんは ベトナムに すんで います。', 'Bố mẹ tôi sống ở Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2153, 27569, '兄弟が何人いますか。', 'きょうだいが なんにん いますか。', 'Bạn có mấy anh chị em?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2154, 27570, '兄は東京で働いています。', 'あには とうきょうで はたらいて います。', 'Anh trai tôi làm việc ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2155, 27572, '姉は先生です。', 'あねは せんせい です。', 'Chị gái tôi là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2156, 27573, 'お姉さんはおいくつですか。', 'おねえさんは おいくつ ですか。', 'Chị gái bạn bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2157, 27574, '弟は大学生です。', 'おとうとは だいがくせい です。', 'Em trai tôi là sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2158, 27575, '弟さんはどこに住んでいますか。', 'おとうとさんは どこに すんで いますか。', 'Em trai bạn sống ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2159, 27576, '妹は高校生です。', 'いもうとは こうこうせい です。', 'Em gái tôi là học sinh cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2160, 27577, '妹さんは何歳ですか。', 'いもうとさんは なんさい ですか。', 'Em gái bạn mấy tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2161, 44683, '確か、会議は三時からだと思います。', 'たしか、かいぎは さんじから だと おもいます。', 'Tôi nghĩ hình như cuộc họp bắt đầu từ ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2162, 44611, '雨が止んだら、出かけましょう。', 'あめが やんだら、でかけましょう。', 'Mưa tạnh thì ra ngoài nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2163, 41780, '駅の改札で待ち合わせをした。', 'えきの かいさつで まちあわせを した。', 'Chúng tôi hẹn gặp nhau ở cổng soát vé ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2164, 41783, '熱があって、体が怠い。', 'ねつが あって、からだが だるい。', 'Bị sốt nên người uể oải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2165, 41784, '事故の原因は管理者の怠慢だった。', 'じこの げんいんは かんりしゃの たいまん だった。', 'Nguyên nhân tai nạn là do người quản lý lơ là.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2166, 41777, '親子の対話が大切だ。', 'おやこの たいわが たいせつだ。', 'Đối thoại giữa cha mẹ và con cái là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2167, 27593, 'ちょっと本まで。', 'ちょっとほんまで。', 'Đếnsáchmột chút', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2168, 27595, '行ってきます。', 'いってきます。', 'Đi đây', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2169, 27603, '行ってまいります。', 'いってまいります。', 'Đi đây', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2170, 44404, '遅れるときは、必ず連絡してください。', 'おくれる ときは、かならず れんらく して ください。', 'Khi đến muộn, nhất định phải liên lạc nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2171, 44407, '旅行の準備はもう終わりましたか。', 'りょこうの じゅんびは もう おわりましたか。', 'Bạn đã chuẩn bị xong cho chuyến du lịch chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2172, 44413, '会議の資料をコピーしておいてください。', 'かいぎの しりょうを コピー して おいて ください。', 'Hãy photo sẵn tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2173, 44414, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2174, 41223, '彼は仕事が雑だ。', 'かれは しごとが ざつだ。', 'Anh ta làm việc cẩu thả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2175, 27598, '大阪デパートの番号、お願いします。', 'おおさか デパートの ばんごう、おねがい します。', 'Cho tôi xin số của trung tâm thương mại Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2176, 27602, 'いらっしゃいませ。何名様ですか。', 'いらっしゃいませ。なんめいさま ですか。', 'Xin chào quý khách. Quý khách đi mấy người ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2177, 27579, 'この大学には留学生がたくさんいます。', 'この だいがくには りゅうがくせいが たくさん います。', 'Trường đại học này có rất nhiều du học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2178, 27582, '二週間日本を旅行しました。', 'にしゅうかん にほんを りょこう しました。', 'Tôi du lịch Nhật Bản hai tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2179, 27583, '三か月日本語を勉強しました。', 'さんかげつ にほんごを べんきょう しました。', 'Tôi đã học tiếng Nhật ba tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2180, 27586, '東京から大阪までどのくらいかかりますか。', 'とうきょうから おおさかまで どのくらい かかりますか。', 'Từ Tokyo đến Osaka mất bao lâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2181, 27587, '全部でいくらですか。', 'ぜんぶで いくら ですか。', 'Tất cả bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2182, 27588, 'みんなで写真を撮りましょう。', 'みんなで しゃしんを とりましょう。', 'Mọi người cùng chụp ảnh nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2183, 27592, 'A：お出かけですか。B：ええ、ちょっと郵便局まで。', 'エー：おでかけ ですか。ビー：ええ、ちょっと ゆうびんきょくまで。', 'A: Chị đi ra ngoài à? B: Vâng, tôi ra bưu điện một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2184, 27596, 'この荷物は船便でお願いします。', 'この にもつは ふなびんで おねがい します。', 'Gói hàng này xin gửi bằng đường biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2185, 27597, '航空便で一週間ぐらいかかります。', 'こうくうびんで いっしゅうかん ぐらい かかります。', 'Gửi đường hàng không mất khoảng một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2186, 27600, 'この手紙を速達で送ってください。', 'この てがみを そくたつで おくって ください。', 'Hãy gửi lá thư này bằng chuyển phát nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2187, 27601, '大切な書類は書留で送ります。', 'たいせつな しょるいは かきとめで おくります。', 'Giấy tờ quan trọng tôi gửi bảo đảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2188, 44632, '恋人と一緒に旅行しました。', 'こいびとと いっしょに りょこう しました。', 'Tôi đã đi du lịch cùng người yêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2191, 27607, 'このりんごは遠いです。', 'このりんごはとおいです。', 'Quả táo này xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2192, 27608, 'このりんごは速い、早いです。', 'このりんごははやいです。', 'Quả táo này nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2193, 44616, '雨の日が続いています。', 'あめの ひが つづいて います。', 'Những ngày mưa vẫn kéo dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2194, 44621, '富士山は美しい山です。', 'ふじさんは うつくしい やま です。', 'Núi Phú Sĩ là ngọn núi đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2195, 44623, 'このパンは柔らかいです。', 'この パンは やわらかい です。', 'Bánh mì này mềm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2196, 44625, '野菜を細かく切ってください。', 'やさいを こまかく きって ください。', 'Hãy thái nhỏ rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2197, 27609, 'このりんごは遅いです。', 'このりんごはおそいです。', 'Quả táo này chậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2198, 27610, '人が多い。', 'ひとがおおい。', 'Nhiều [người]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2199, 27611, '人が少ない。', 'ひとがすくない。', 'Ít [người]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2200, 27612, 'このりんごは暖かい、温かいです。', 'このりんごはあたたかいです。', 'Quả táo này ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2201, 27613, 'このりんごは涼しいです。', 'このりんごはすずしいです。', 'Quả táo này mát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2202, 27614, 'このりんごは甘いです。', 'このりんごはあまいです。', 'Quả táo này ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2203, 27615, 'このりんごは辛いです。', 'このりんごはからいです。', 'Quả táo này cay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2204, 27616, 'このりんごは重いです。', 'このりんごはおもいです。', 'Quả táo này nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2205, 44431, '夏休みにどこへ行くか、まだ決めていません。', 'なつやすみに どこへ いくか、まだ きめて いません。', 'Tôi vẫn chưa quyết định nghỉ hè sẽ đi đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2206, 44508, '使った物はきちんと片付けてください。', 'つかった ものは きちんと かたづけて ください。', 'Đồ đã dùng thì hãy cất dọn ngăn nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2207, 44555, '去年と比べると、今年は雨が少ないです。', 'きょねんと くらべると、ことしは あめが すくないです。', 'So với năm ngoái thì năm nay ít mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2208, 44567, '日本料理の中で、特にすしが好きです。', 'にほんりょうりの なかで、とくに すしが すきです。', 'Trong các món Nhật, tôi đặc biệt thích sushi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2209, 44614, '運動を始めてから、体重が三キロ減りました。', 'うんどうを はじめてから、たいじゅうが さんキロ へりました。', 'Từ khi bắt đầu tập thể dục, tôi đã giảm ba ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2210, 44631, '母の愛はどんなものより深い。', 'ははの あいは どんな ものより ふかい。', 'Tình yêu của mẹ sâu nặng hơn bất cứ điều gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2211, 44633, '彼は私の友達です。', 'かれは わたしの ともだち です。', 'Anh ấy là bạn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2212, 27563, '食堂でカレーライスを食べました。', 'しょくどうで カレーライスを たべました。', 'Tôi ăn cơm cà ri ở nhà ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2213, 27564, '暑い日はアイスクリームを食べます。', 'あつい ひは アイスクリームを たべます。', 'Ngày nóng tôi ăn kem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2214, 29669, '国へエアメールを送りました。', 'くにへ エアメールを おくりました。', 'Tôi gửi thư đường hàng không về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2215, 28128, '友達が私に本をくれました。', 'ともだちが わたしに ほんを くれました。', 'Bạn đã tặng tôi một cuốn sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2216, 44620, '子どものプールは浅いです。', 'こどもの プールは あさい です。', 'Hồ bơi trẻ em thì nông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2217, 44630, '心をこめて手紙を書きました。', 'こころを こめて てがみを かきました。', 'Tôi viết thư bằng cả tấm lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2218, 27617, 'このりんごは軽いです。', 'このりんごはかるいです。', 'Quả táo này nhẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2219, 27618, 'コーヒーがいい。', 'コーヒーがいい。', 'Thích, chọn, dùng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2220, 28172, 'お医者さんに診てもらいました。', 'おいしゃさんに みて もらいました。', 'Tôi đã được bác sĩ khám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2221, 44636, '姉に赤ちゃんが生まれました。', 'あねに あかちゃんが うまれました。', 'Chị tôi vừa sinh em bé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2222, 44638, '親に心配をかけたくないです。', 'おやに しんぱいを かけたく ない です。', 'Tôi không muốn làm cha mẹ lo lắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2223, 27629, '空港へ行きます。', 'くうこうへいきます。', 'Tôi đi đến sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2224, 44640, '後輩の面倒を見ています。', 'こうはいの めんどうを みて います。', 'Tôi đang kèm cặp đàn em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2225, 44617, '約束は必ず守ります。', 'やくそくは かならず まもります。', 'Tôi nhất định sẽ giữ lời hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2226, 44634, '彼女は東京に住んでいます。', 'かのじょは とうきょうに すんで います。', 'Cô ấy sống ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2227, 27644, 'お国はどちらですか。', 'おくには どちら ですか。', 'Anh đến từ nước nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2228, 27619, 'どの季節が一番好きですか。', 'どの きせつが いちばん すき ですか。', 'Bạn thích mùa nào nhất?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2229, 27621, '日本の夏は暑いです。', 'にほんの なつは あつい です。', 'Mùa hè ở Nhật nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2230, 27622, '秋は涼しくて、気持ちがいいです。', 'あきは すずしくて、きもちが いい です。', 'Mùa thu mát mẻ, dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2231, 27623, '冬はとても寒いです。', 'ふゆは とても さむい です。', 'Mùa đông rất lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2232, 27625, 'きのうは雨でした。', 'きのうは あめ でした。', 'Hôm qua trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2233, 27626, '北海道は雪が多いです。', 'ほっかいどうは ゆきが おおい です。', 'Hokkaido có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2234, 27630, '夏休みに海へ行きました。', 'なつやすみに うみへ いきました。', 'Kỳ nghỉ hè tôi đã đi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2235, 27633, '夏に町でお祭りがあります。', 'なつに まちで おまつりが あります。', 'Mùa hè thị trấn có lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2236, 27634, 'お正月にすき焼きを食べました。', 'おしょうがつに すきやきを たべました。', 'Dịp Tết tôi đã ăn sukiyaki.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2237, 27635, '刺身は好きですか。', 'さしみは すき ですか。', 'Bạn có thích sashimi không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2238, 27636, 'すしとてんぷらとどちらが好きですか。', 'すしと てんぷらと どちらが すき ですか。', 'Bạn thích sushi hay tempura hơn?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2239, 27640, 'すき焼きは牛肉で作ります。', 'すきやきは ぎゅうにくで つくります。', 'Sukiyaki được làm từ thịt bò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2240, 27642, '毎週、生け花を習っています。', 'まいしゅう、いけばなを ならって います。', 'Hằng tuần tôi học cắm hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2241, 27643, '秋は紅葉がきれいです。', 'あきは もみじが きれい です。', 'Mùa thu lá đỏ rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2242, 27645, 'A：コーヒーと紅茶とどちらが好きですか。B：どちらも好きです。', 'エー：コーヒーと こうちゃと どちらが すき ですか。ビー：どちらも すき です。', 'A: Bạn thích cà phê hay trà? B: Cả hai đều thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2243, 27646, '一年でいつがいちばん寒いですか。', 'いちねんで いつが いちばん さむい ですか。', 'Trong năm, lúc nào lạnh nhất?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2244, 27648, '初めて日本へ来ました。', 'はじめて にほんへ きました。', 'Lần đầu tiên tôi đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2245, 27649, 'ただいま。お母さん、おなかがすいた。', 'ただいま。おかあさん、おなかが すいた。', 'Con về rồi. Mẹ ơi, con đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2246, 27650, 'A：ただいま。B：お帰りなさい。', 'エー：ただいま。ビー：おかえりなさい。', 'A: Tôi về rồi. B: Anh về rồi đấy à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2247, 27653, '祇園祭は七月に京都であります。', 'ぎおんまつりは しちがつに きょうとで あります。', 'Lễ hội Gion diễn ra ở Kyoto vào tháng bảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2248, 28234, 'うちで犬を飼っています。', 'うちで いぬを かって います。', 'Nhà tôi nuôi chó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2249, 44643, '入学のお祝いに時計をもらいました。', 'にゅうがくの おいわいに とけいを もらいました。', 'Tôi được tặng đồng hồ làm quà mừng nhập học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2250, 44644, '朝、近所の人に挨拶をします。', 'あさ、きんじょの ひとに あいさつを します。', 'Buổi sáng tôi chào hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2251, 44648, '家族が元気で安心しました。', 'かぞくが げんきで あんしん しました。', 'Gia đình khỏe mạnh nên tôi yên tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2252, 27669, '公園を散歩します。', 'こうえんをさんぽします。', 'Đi dạo', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2253, 27670, 'ここは大変です。', 'ここはたいへんです。', 'Ở đây hard.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2254, 27671, 'このりんごは欲しいです。', 'このりんごはほしいです。', 'Quả táo này muốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2255, 27672, 'このりんごは広いです。', 'このりんごはひろいです。', 'Quả táo này rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2256, 27673, 'このりんごは狭いです。', 'このりんごはせまいです。', 'Quả táo này hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2257, 27684, 'のどがかわきます。', 'のどがかわきます。', 'Khát nước', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2258, 27685, 'おなかがすきます。', 'おなかがすきます。', 'Đói bụng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2259, 47949, '売り上げが減った要因を調べている。', 'うりあげが へった よういんを しらべて いる。', 'Chúng tôi đang tìm hiểu nhân tố khiến doanh thu giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2260, 27658, '試験は九時からです。', 'しけんは くじから です。', 'Kỳ thi bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2261, 27654, '香港は買い物が楽しいです。', 'ホンコンは かいものが たのしい です。', 'Mua sắm ở Hồng Kông rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2262, 27659, 'A：毎日十キロ走ります。B：すごいですね。', 'エー：まいにち じゅっキロ はしります。ビー：すごい ですね。', 'A: Mỗi ngày tôi chạy mười cây số. B: Giỏi quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2263, 27628, '駅の近くのホテルに泊まりました。', 'えきの ちかくの ホテルに とまりました。', 'Tôi đã ở khách sạn gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2264, 27632, '週末にうちでパーティーをします。', 'しゅうまつに うちで パーティーを します。', 'Cuối tuần tôi tổ chức tiệc ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2265, 27641, '紅茶にレモンを入れます。', 'こうちゃに レモンを いれます。', 'Tôi cho chanh vào trà đen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2266, 27656, 'ABCストアでパンを買いました。', 'エービーシー ストアで パンを かいました。', 'Tôi mua bánh mì ở ABC Store.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2267, 27657, 'ジャパンは駅の前のスーパーです。', 'ジャパンは えきの まえの スーパー です。', 'Japan là siêu thị ở trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2268, 27663, '夏は海で泳ぎます。', 'なつは うみで およぎます。', 'Mùa hè tôi bơi ở biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2269, 27664, '空港へ友達を迎えに行きます。', 'くうこうへ ともだちを むかえに いきます。', 'Tôi ra sân bay đón bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2270, 27666, '来年、結婚します。', 'らいねん、けっこん します。', 'Năm sau tôi kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2271, 27667, '日曜日、デパートで買い物します。', 'にちようび、デパートで かいもの します。', 'Chủ nhật tôi mua sắm ở trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2272, 27675, '川で魚を釣りました。', 'かわで さかなを つりました。', 'Tôi câu cá ở sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2273, 27676, '日本の美術を勉強しています。', 'にほんの びじゅつを べんきょう して います。', 'Tôi đang học mỹ thuật Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2274, 27677, '週末、父と釣りに行きます。', 'しゅうまつ、ちちと つりに いきます。', 'Cuối tuần tôi đi câu cá với bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2275, 27679, '週末は何をしますか。', 'しゅうまつは なにを しますか。', 'Cuối tuần bạn làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2276, 27682, '何か飲みませんか。', 'なにか のみませんか。', 'Uống gì đó không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2277, 27683, '夏休みにどこか行きましたか。', 'なつやすみに どこか いきましたか。', 'Kỳ nghỉ hè bạn có đi đâu không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2278, 27686, 'そうしましょう。', 'そうしましょう。', 'Làm như vậy nhé', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2279, 44653, '遅刻して、先生に怒られました。', 'ちこく して、せんせいに おこられました。', 'Đi muộn nên tôi bị thầy mắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2280, 27690, '［少々］お待ちください。', '［しょうしょう］おまちください。', 'Xin vui lòng chờ [một chút].', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2281, 27695, '手紙を出します。', 'てがみをだします。', 'Giao, nộp', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2282, 27696, '喫茶店に入ります。', 'きっさてんにはいります。', 'Vào, bỏ vào', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2283, 27697, '喫茶店を出ます。', 'きっさてんをでます。', 'Đi ra ngoài', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2284, 27698, 'このりんごは寂しいです。', 'このりんごはさびしいです。', 'Quả táo này buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2285, 27703, 'おなかがいっぱいです。', 'おなかがいっぱいです。', 'No rồi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2286, 44654, '赤ちゃんが笑っています。', 'あかちゃんが わらって います。', 'Em bé đang cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2287, 27705, 'ロシアから来ました。', 'ロシアからきました。', 'Tôi đến từ Russia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2288, 44629, 'あなたの気持ちはよくわかります。', 'あなたの きもちは よく わかります。', 'Tôi rất hiểu cảm xúc của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2289, 44647, '新しい計画は大成功でした。', 'あたらしい けいかくは だいせいこう でした。', 'Kế hoạch mới đã thành công rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2290, 27701, '午後二時から会議があります。', 'ごご にじから かいぎが あります。', 'Từ hai giờ chiều có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2291, 44650, '遠慮しないで、たくさん食べてください。', 'えんりょ しないで、たくさん たべて ください。', 'Đừng khách sáo, cứ ăn nhiều vào nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2292, 27706, 'つるやでそばを食べました。', 'つるやで そばを たべました。', 'Tôi đã ăn mì soba ở quán Tsuruya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2293, 27687, 'いらっしゃいませ。ご注文は?', 'いらっしゃいませ。ごちゅうもんは?', 'Xin chào quý khách. Quý khách dùng gì ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2294, 27688, '昼ごはんに魚の定食を食べました。', 'ひるごはんに さかなの ていしょくを たべました。', 'Bữa trưa tôi ăn suất cơm cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2295, 27692, '会計は別々にお願いします。', 'かいけいは べつべつに おねがい します。', 'Xin cho chúng tôi thanh toán riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2296, 27694, '毎朝おはようテレビを見ます。', 'まいあさ おはよう テレビを みます。', 'Sáng nào tôi cũng xem chương trình Ohayou TV.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2297, 27699, '市役所へ登録に行きます。', 'しやくしょへ とうろくに いきます。', 'Tôi đến tòa thị chính để đăng ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2298, 27700, '大学で経済を勉強しています。', 'だいがくで けいざいを べんきょう して います。', 'Tôi đang học kinh tế ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2299, 27702, '外国人登録をしました。', 'がいこくじん とうろくを しました。', 'Tôi đã làm đăng ký người nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2300, 27678, '冬に北海道へスキーに行きます。', 'ふゆに ほっかいどうへ スキーに いきます。', 'Mùa đông tôi đi Hokkaido trượt tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2301, 27693, 'アキックスは靴の会社です。', 'アキックスは くつの かいしゃ です。', 'Akikkusu là công ty giày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2302, 27708, '電気を消してください。', 'でんきを けして ください。', 'Hãy tắt đèn đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2303, 27709, '窓を開けてもいいですか。', 'まどを あけても いい ですか。', 'Tôi mở cửa sổ được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2304, 27711, '時間がありません。急いでください。', 'じかんが ありません。いそいで ください。', 'Không còn thời gian. Hãy nhanh lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2305, 27712, '駅で友達を待ちます。', 'えきで ともだちを まちます。', 'Tôi đợi bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2306, 27714, 'すみません、塩を取ってください。', 'すみません、しおを とって ください。', 'Xin lỗi, lấy giúp tôi lọ muối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2307, 44689, '健康のために、たばこをやめました。', 'けんこうの ために、たばこを やめました。', 'Vì sức khỏe, tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2308, 44659, '先生に褒められて、うれしかったです。', 'せんせいに ほめられて、うれしかった です。', 'Được thầy khen nên tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2309, 27721, '住所を教えます。', 'じゅうしょをおしえます。', 'Dạy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2310, 44660, '子どもを叱りました。', 'こどもを しかりました。', 'Tôi đã mắng con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2311, 27724, '喫茶店に入ります。', 'きっさてんにはいります。', 'Enter [a café]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2312, 27725, '喫茶店を出ます。', 'きっさてんをでます。', 'Ra khỏi [quán cà phê]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2313, 27726, '雨が降ります。', 'あめがふります。', 'Rơi rớt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2314, 44662, '子どものころを思い出しました。', 'こどもの ころを おもいだしました。', 'Tôi nhớ lại thời thơ ấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2315, 44665, '駅で友達を迎えました。', 'えきで ともだちを むかえました。', 'Tôi đón bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2316, 44667, '二人は三年付き合っています。', 'ふたりは さんねん つきあって います。', 'Hai người đã hẹn hò ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2317, 44669, '友達が国へ帰って、悲しいです。', 'ともだちが くにへ かえって、かなしい です。', 'Bạn về nước nên tôi buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2318, 44652, '悪いと思ったら、すぐに謝りなさい。', 'わるいと おもったら、すぐに あやまりなさい。', 'Nếu thấy mình sai thì xin lỗi ngay đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2319, 45347, 'なるほど、そういうことだったのか。', 'なるほど、そういう こと だったのか。', 'Ra là vậy, hóa ra là chuyện như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2320, 27715, 'ちょっと手伝ってください。', 'ちょっと てつだって ください。', 'Giúp tôi một chút nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2321, 27716, 'タクシーを呼んでください。', 'タクシーを よんで ください。', 'Hãy gọi taxi giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2322, 27717, '日本語で話してください。', 'にほんごで はなして ください。', 'Hãy nói bằng tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2323, 27719, 'ここに車を止めないでください。', 'ここに くるまを とめないで ください。', 'Xin đừng đỗ xe ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2324, 27722, 'どうぞ、ここに座ってください。', 'どうぞ、ここに すわって ください。', 'Mời anh ngồi đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2325, 27727, 'この資料を十枚コピーしてください。', 'この しりょうを じゅうまい コピー して ください。', 'Hãy photo tài liệu này mười bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2326, 27731, 'ここに名前を書いてください。', 'ここに なまえを かいて ください。', 'Hãy viết tên vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2327, 27733, '地図を書いてください。', 'ちずを かいて ください。', 'Hãy vẽ bản đồ giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2328, 27734, 'スープに塩を少し入れてください。', 'スープに しおを すこし いれて ください。', 'Hãy cho một chút muối vào súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2329, 27735, 'コーヒーに砂糖を入れますか。', 'コーヒーに さとうを いれますか。', 'Bạn có cho đường vào cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2330, 27737, '答えを書いてください。', 'こたえを かいて ください。', 'Hãy viết câu trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2331, 27738, 'この漢字の読み方を教えてください。', 'この かんじの よみかたを おしえて ください。', 'Hãy chỉ tôi cách đọc chữ Hán này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2332, 27739, 'このカメラの使い方を教えてください。', 'この カメラの つかいかたを おしえて ください。', 'Hãy chỉ tôi cách dùng chiếc máy ảnh này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2333, 27741, 'もう少しゆっくり話してください。', 'もう すこし ゆっくり はなして ください。', 'Hãy nói chậm hơn một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2334, 27742, 'すぐ来てください。', 'すぐ きて ください。', 'Hãy đến ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2335, 27743, 'また来てください。', 'また きて ください。', 'Lại đến chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2336, 44671, 'みんなの前で歌うのは恥ずかしいです。', 'みんなの まえで うたうのは はずかしい です。', 'Hát trước mặt mọi người thật xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2337, 44708, '隣の部屋から子どもの声が聞こえます。', 'となりの へやから こどもの こえが きこえます。', 'Nghe thấy tiếng trẻ con từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2338, 27749, '信号を右へ曲がってください。', 'しんごうをみぎへまがってください。', 'Rẽ phải ở chỗ đèn giao thông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2339, 27750, 'これでお願いします。', 'これでおねがいします。', 'Tôi muốn thanh toán bằng cái này', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2340, 44675, '毎日勉強して、偉いですね。', 'まいにち べんきょう して、えらい ですね。', 'Ngày nào cũng học, giỏi quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2341, 27753, '右へ曲がります。', 'みぎへまがります。', 'Uốn cong, rẽ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2342, 44677, '彼は真面目な学生です。', 'かれは まじめな がくせい です。', 'Cậu ấy là học sinh chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2343, 44680, '家族と一緒にいられて幸せです。', 'かぞくと いっしょに いられて しあわせ です。', 'Được ở bên gia đình, tôi thấy hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2344, 28352, 'ドアが開きます。', 'ドアがあきます。', 'Mở (cửa)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2345, 44663, '朝晩は少し寒さを感じるようになりました。', 'あさばんは すこし さむさを かんじる ように なりました。', 'Sáng tối đã bắt đầu thấy hơi lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2346, 27763, '会議の資料をコピーしておいてください。', 'かいぎの しりょうを コピー して おいて ください。', 'Hãy photo sẵn tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2347, 27957, '実は、来月会社を辞めるんです。', 'じつは、らいげつ かいしゃを やめるんです。', 'Thật ra là tháng sau tôi sẽ nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2348, 28103, 'エレベーターが故障して、使えません。', 'エレベーターが こしょう して、つかえません。', 'Thang máy bị hỏng, không dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2349, 44762, 'レストランを七時に予約しました。', 'レストランを しちじに よやく しました。', 'Tôi đã đặt nhà hàng lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2350, 44763, '友達と三時に会う約束があります。', 'ともだちと さんじに あう やくそくが あります。', 'Tôi có hẹn gặp bạn lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2351, 44674, '彼とは高校時代から親しくしている。', 'かれとは こうこう じだいから したしく して いる。', 'Tôi thân với anh ấy từ thời cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2352, 38001, '両国は貿易について協議を続けている。', 'りょうこくは ぼうえきに ついて きょうぎを つづけて いる。', 'Hai nước đang tiếp tục thương thảo về thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2353, 44672, 'この歌を聞くと、学生時代が懐かしくなる。', 'この うたを きくと、がくせい じだいが なつかしく なる。', 'Nghe bài hát này tôi lại nhớ thời sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2354, 27744, 'あとで電話します。', 'あとで でんわ します。', 'Lát nữa tôi sẽ gọi điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2355, 27746, 'もう一度言ってください。', 'もう いちど いって ください。', 'Hãy nói lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2356, 27748, 'あれ?私の傘がありません。', 'あれ?わたしの かさが ありません。', 'Ơ? Ô của tôi đâu mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2357, 27752, 'みどり町までお願いします。', 'みどり ちょうまで おねがい します。', 'Cho tôi đến Midori-cho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2358, 27754, '九時に会議を始めます。', 'くじに かいぎを はじめます。', 'Chín giờ chúng ta bắt đầu cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2359, 27756, '梅田で買い物をしました。', 'うめだで かいものを しました。', 'Tôi đã mua sắm ở Umeda.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2360, 27730, 'パスポートを忘れないでください。', 'パスポートを わすれないで ください。', 'Đừng quên hộ chiếu nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2361, 27758, '母は晩ごはんを作っています。', 'ははは ばんごはんを つくって います。', 'Mẹ đang nấu bữa tối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2362, 27759, 'あの店で切手を売っています。', 'あの みせで きってを うって います。', 'Cửa hàng kia có bán tem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2363, 27761, '私は大阪に住んでいます。', 'わたしは おおさかに すんで います。', 'Tôi sống ở Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2364, 27762, '大学で経済を研究しています。', 'だいがくで けいざいを けんきゅう して います。', 'Tôi nghiên cứu kinh tế ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2365, 44682, '人の前でそんなことを言うのは失礼です。', 'ひとの まえで そんな ことを いうのは しつれい です。', 'Nói như thế trước mặt người khác là thất lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2366, 27784, '知っています。', 'しっています。', 'Biết', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2367, 27785, '大阪に住んで います。', 'おおさかにすんで います。', 'Sống', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2368, 27792, '電車を降ります。', 'でんしゃをおります。', 'Xuống tàu,xe', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2369, 27794, 'シャワーを浴びます。', 'シャワーをあびます。', 'Tắm', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2370, 27797, 'お金を下ろします。', 'おかねをおろします。', 'Rút (tiền)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2371, 27798, '大学に入ります。', 'だいがくにはいります。', 'Vào, nhập học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2372, 27799, '大学を出ます。', 'だいがくをでます。', 'Ra, tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2373, 27789, '日本料理の中で、特にすしが好きです。', 'にほんりょうりの なかで、とくに すしが すきです。', 'Trong các món Nhật, tôi đặc biệt thích sushi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2374, 45348, 'せっかく作ったのに、誰も食べてくれなかった。', 'せっかく つくったのに、だれも たべて くれなかった。', 'Đã mất công nấu mà chẳng ai ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2375, 27801, '毎晩お茶を飲みます。', 'まいばん おちゃを のみます。', 'Tối nào tôi cũng uống trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2376, 27769, '電子辞書で言葉の意味を調べます。', 'でんし じしょで ことばの いみを しらべます。', 'Tôi tra nghĩa từ bằng từ điển điện tử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2377, 27770, '大学で経済を勉強しています。', 'だいがくで けいざいを べんきょう して います。', 'Tôi đang học kinh tế ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2378, 27772, '弟は高校で勉強しています。', 'おとうとは こうこうで べんきょう して います。', 'Em trai tôi đang học cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2379, 27773, '歯が痛いので、歯医者へ行きます。', 'はが いたいので、はいしゃへ いきます。', 'Răng đau nên tôi đi nha sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2380, 27774, '兄はまだ独身です。', 'あには まだ どくしん です。', 'Anh trai tôi vẫn còn độc thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2381, 27775, 'すみません、ちょっと通してください。', 'すみません、ちょっと とおして ください。', 'Xin lỗi, cho tôi đi qua một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2382, 27778, '田中さんは今どこにいらっしゃいますか。', 'たなかさんは いま どこに いらっしゃいますか。', 'Anh Tanaka bây giờ đang ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2383, 27779, '日本橋で電気製品を買いました。', 'にっぽんばしで でんき せいひんを かいました。', 'Tôi mua đồ điện ở Nipponbashi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2384, 27781, '皆さん、立ってください。', 'みなさん、たって ください。', 'Mọi người hãy đứng dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2385, 27782, 'どうぞ、ここに座ってください。', 'どうぞ、ここに すわって ください。', 'Mời anh ngồi đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2386, 27783, 'このパソコンを使ってもいいですか。', 'この パソコンを つかっても いい ですか。', 'Tôi dùng máy tính này được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2387, 27787, '床屋で髪を切りました。', 'とこやで かみを きりました。', 'Tôi đã cắt tóc ở hiệu cắt tóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2388, 27764, 'カタログを見て、注文しました。', 'カタログを みて、ちゅうもん しました。', 'Tôi xem ca-ta-lô rồi đặt hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2389, 27768, '新しいソフトを使っています。', 'あたらしい ソフトを つかって います。', 'Tôi đang dùng phần mềm mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2390, 27793, '新宿で電車を乗り換えます。', 'しんじゅくで でんしゃを のりかえます。', 'Tôi chuyển tàu ở Shinjuku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2391, 27795, 'コーヒーに砂糖を入れます。', 'コーヒーに さとうを いれます。', 'Tôi cho đường vào cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2392, 27800, 'このボタンを押してください。', 'この ボタンを おして ください。', 'Hãy nhấn nút này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2393, 27802, '九時に会議を始めます。', 'くじに かいぎを はじめます。', 'Chín giờ chúng ta bắt đầu cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2394, 44684, 'やっと宿題が終わりました。', 'やっと しゅくだいが おわりました。', 'Cuối cùng bài tập cũng xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2395, 27805, 'このりんごは若いです。', 'このりんごはわかいです。', 'Quả táo này trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2396, 27806, 'このりんごは長いです。', 'このりんごはながいです。', 'Quả táo này dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2397, 27807, 'このりんごは短いです。', 'このりんごはみじかいです。', 'Quả táo này ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2398, 27808, 'このりんごは明るいです。', 'このりんごはあかるいです。', 'Quả táo này sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2399, 27809, 'このりんごは暗いです。', 'このりんごはくらいです。', 'Quả táo này tối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2400, 44691, '風邪をひいて、学校を休みました。', 'かぜを ひいて、がっこうを やすみました。', 'Bị cảm nên tôi nghỉ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2401, 44696, '退院の日が決まりました。', 'たいいんの ひが きまりました。', 'Ngày xuất viện đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2402, 44702, '喉が渇きました。', 'のどが かわきました。', 'Tôi khát nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2403, 44766, '先生が文法をわかりやすく説明してくれました。', 'せんせいが ぶんぽうを わかりやすく せつめい して くれました。', 'Thầy giáo giải thích ngữ pháp rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2404, 27831, 'ミラーさんの傘はどれですか。', 'ミラーさんの かさは どれ ですか。', 'Ô của anh Miller là cái nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2405, 27804, 'あとで電話します。', 'あとで でんわ します。', 'Lát nữa tôi sẽ gọi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2406, 27810, '毎日運動すると、体にいいです。', 'まいにち うんどう すると、からだに いい です。', 'Tập thể dục mỗi ngày tốt cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2407, 27812, '妹は髪が長いです。', 'いもうとは かみが ながい です。', 'Em gái tôi tóc dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2408, 27813, '朝、顔を洗います。', 'あさ、かおを あらいます。', 'Buổi sáng tôi rửa mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2409, 27814, '彼女は目が大きいです。', 'かのじょは めが おおきい です。', 'Cô ấy có đôi mắt to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2410, 44690, '病気で学校を休みました。', 'びょうきで がっこうを やすみました。', 'Tôi nghỉ học vì ốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2411, 44693, 'この薬を一日三回飲んでください。', 'この くすりを いちにち さんかい のんで ください。', 'Hãy uống thuốc này ngày ba lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2412, 44699, '歯が痛いので、歯医者へ行きます。', 'はが いたいので、はいしゃへ いきます。', 'Răng đau nên tôi đi nha sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2413, 27816, '象は鼻が長いです。', 'ぞうは はなが ながい です。', 'Voi có cái vòi dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2414, 27817, '口を大きく開けてください。', 'くちを おおきく あけて ください。', 'Hãy há miệng thật to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2415, 27819, 'おなかがすきました。', 'おなかが すきました。', 'Tôi đói bụng rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2416, 27820, 'たくさん歩いて、足が痛いです。', 'たくさん あるいて、あしが いたい です。', 'Đi bộ nhiều nên đau chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2417, 27821, '兄は背が高いです。', 'あには せが たかい です。', 'Anh trai tôi cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2418, 27825, 'この町は緑が多いです。', 'この まちは みどりが おおい です。', 'Thị trấn này có nhiều cây xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2419, 27827, 'お正月に神社へ行きます。', 'おしょうがつに じんじゃへ いきます。', 'Dịp Tết tôi đi đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2420, 27829, '駅までどうやって行きますか。', 'えきまで どうやって いきますか。', 'Đến ga thì đi bằng cách nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2421, 27830, 'どの人が田中さんですか。', 'どの ひとが たなかさん ですか。', 'Người nào là anh Tanaka?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2422, 44686, 'たぶん、彼は来ないと思います。', 'たぶん、かれは こないと おもいます。', 'Có lẽ anh ấy sẽ không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2423, 44687, 'A：一緒に行きますか。B：もちろん行きます。', 'エー：いっしょに いきますか。ビー：もちろん いきます。', 'A: Cùng đi chứ? B: Tất nhiên rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2424, 44701, '首が痛いです。', 'くびが いたい です。', 'Tôi bị đau cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2425, 44704, 'ナイフで指を切りました。', 'ナイフで ゆびを きりました。', 'Tôi bị dao cắt vào ngón tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2426, 28474, '日本語の勉強を続けます。', 'にほんごの べんきょうを つづけます。', 'Tôi sẽ tiếp tục học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2427, 27849, '会社をやめます。', 'かいしゃをやめます。', 'Từ bỏ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2428, 27850, 'このりんごは背が高いです。', 'このりんごはせがたかいです。', 'Quả táo này cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2429, 27851, 'このりんごは頭がいいです。', 'このりんごはあたまがいいです。', 'Quả táo này giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2430, 27852, '私は留学生です。', 'わたしはりゅうがくせいです。', 'Tôi là du học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2431, 27837, 'キャッシュカードへ行きます。', 'キャッシュカードへいきます。', 'Tôi đi đến Thẻ ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2432, 27854, 'ベトナムから来ました。', 'ベトナムからきました。', 'Tôi đến từ Vietnam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2433, 44709, '今日は気分がいいので、散歩に行きます。', 'きょうは きぶんが いいので、さんぽに いきます。', 'Hôm nay tâm trạng tốt nên tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2434, 27840, '出かける前に、ガスを確認した。', 'でかける まえに、ガスを かくにん した。', 'Trước khi ra ngoài tôi kiểm tra lại bếp ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2435, 27834, 'いらっしゃいませ。お引き出しですか。', 'いらっしゃいませ。おひきだし ですか。', 'Xin chào quý khách. Quý khách rút tiền phải không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2436, 27835, 'まず、カードを入れてください。', 'まず、カードを いれて ください。', 'Trước hết hãy cho thẻ vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2437, 27836, '次に、暗証番号を押してください。', 'つぎに、あんしょう ばんごうを おして ください。', 'Tiếp theo hãy nhập mật khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2438, 27839, '金額を確認してください。', 'きんがくを かくにん して ください。', 'Hãy kiểm tra số tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2439, 44707, '妹は髪が長いです。', 'いもうとは かみが ながい です。', 'Em gái tôi tóc dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2440, 27842, 'JRで京都へ行きます。', 'ジェイアールで きょうとへ いきます。', 'Tôi đi tàu JR đến Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2441, 27847, '梅田で買い物をしました。', 'うめだで かいものを しました。', 'Tôi đã mua sắm ở Umeda.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2442, 27822, 'このホテルはサービスがいいです。', 'この ホテルは サービスが いい です。', 'Khách sạn này dịch vụ tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2443, 27823, '毎朝、公園をジョギングします。', 'まいあさ、こうえんを ジョギング します。', 'Sáng nào tôi cũng chạy bộ trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2444, 27824, '朝、シャワーを浴びます。', 'あさ、シャワーを あびます。', 'Buổi sáng tôi tắm vòi sen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2445, 27841, 'このボタンを押すと、お茶が出ます。', 'この ボタンを おすと、おちゃが でます。', 'Bấm nút này thì trà sẽ chảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2446, 27845, 'フランケンはワインで有名です。', 'フランケンは ワインで ゆうめい です。', 'Franken nổi tiếng với rượu vang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2447, 27846, 'ベラクルスはメキシコの町です。', 'ベラクルスは メキシコの まち です。', 'Veracruz là một thành phố của Mexico.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2448, 27853, 'アジアの国を旅行したいです。', 'アジアの くにを りょこう したい です。', 'Tôi muốn du lịch các nước châu Á.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2449, 27855, 'フエは古い町です。', 'フエは ふるい まち です。', 'Huế là một thành phố cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2450, 27857, '宿題を忘れないでください。', 'しゅくだいを わすれないで ください。', 'Đừng quên bài tập nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2451, 27859, 'ここでお金を払ってください。', 'ここで おかねを はらって ください。', 'Hãy trả tiền ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2452, 27860, 'あした本を返します。', 'あした ほんを かえします。', 'Ngày mai tôi trả sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2453, 44706, '背中がかゆいです。', 'せなかが かゆい です。', 'Lưng tôi ngứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2454, 44711, '指から血が出ています。', 'ゆびから ちが でて います。', 'Ngón tay đang chảy máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2455, 44713, '兄は力が強いです。', 'あには ちからが つよい です。', 'Anh tôi rất khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2456, 27863, '持って行きます。', 'もっていきます。', 'Mang đi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2457, 27864, '持って来ます。', 'もってきます。', 'Mang đến', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2458, 44714, '毎朝、軽い運動をしています。', 'まいあさ、かるい うんどうを して います。', 'Sáng nào tôi cũng vận động nhẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2459, 27868, '薬を飲みます。', 'くすりをのみます。', 'Uống', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2460, 27869, 'おふろに入ります。', 'おふろにはいります。', 'Vào', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2461, 27870, 'ここは大切です。', 'ここはたいせつです。', 'Ở đây quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2462, 27871, 'ここは大丈夫です。', 'ここはだいじょうぶです。', 'Ở đây không sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2463, 27872, 'このりんごは危ないです。', 'このりんごはあぶないです。', 'Quả táo này nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2464, 27885, 'どうしましたか。', 'どうしましたか。', 'Có chuyện gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2465, 27891, 'レポートを出します。', 'レポートをだします。', 'Nộp', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2466, 27889, '宿題をします。それから、寝ます。', 'しゅくだいを します。それから、ねます。', 'Tôi làm bài tập. Sau đó đi ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2467, 27865, '大丈夫ですから、心配しないでください。', 'だいじょうぶ ですから、しんぱい しないで ください。', 'Không sao đâu, đừng lo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2468, 27866, '今晩は残業しなければなりません。', 'こんばんは ざんぎょう しなければ なりません。', 'Tối nay tôi phải làm thêm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2469, 27873, 'この部屋は禁煙です。', 'この へやは きんえん です。', 'Phòng này cấm hút thuốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2470, 27874, '病院へ保険証を持っていってください。', 'びょういんへ ほけんしょうを もって いって ください。', 'Hãy mang thẻ bảo hiểm đến bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2471, 27875, 'きのうから熱があります。', 'きのうから ねつが あります。', 'Từ hôm qua tôi bị sốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2472, 27876, '病気で学校を休みました。', 'びょうきで がっこうを やすみました。', 'Tôi nghỉ học vì ốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2473, 27878, '毎晩おふろに入ります。', 'まいばん おふろに はいります。', 'Tối nào tôi cũng tắm bồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2474, 27879, '寒いですから、上着を着てください。', 'さむい ですから、うわぎを きて ください。', 'Trời lạnh, hãy mặc áo khoác vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2475, 27880, '旅行に下着を三枚持っていきます。', 'りょこうに したぎを さんまい もって いきます。', 'Đi du lịch tôi mang ba bộ đồ lót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2476, 27881, '二、三日休んでください。', 'に、さんにち やすんで ください。', 'Hãy nghỉ hai, ba ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2477, 27882, '二、三人来ました。', 'に、さんにん きました。', 'Có hai, ba người đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2478, 27884, 'あしたは休みです。ですから、どこかへ行きます。', 'あしたは やすみ です。ですから、どこかへ いきます。', 'Mai là ngày nghỉ. Vì thế tôi sẽ đi đâu đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2479, 27886, 'かぜで、のどが痛いです。', 'かぜで、のどが いたい です。', 'Bị cảm nên tôi đau họng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2480, 27888, 'かぜをひいて、会社を休みました。', 'かぜを ひいて、かいしゃを やすみました。', 'Bị cảm nên tôi nghỉ làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2481, 27892, 'この問題は難しいです。', 'この もんだいは むずかしい です。', 'Câu hỏi này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2482, 27893, '答えを書いてください。', 'こたえを かいて ください。', 'Hãy viết câu trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2483, 27896, '食事の前に手を洗います。', 'しょくじの まえに てを あらいます。', 'Trước bữa ăn tôi rửa tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2484, 27898, 'カラオケで日本の歌を歌いました。', 'カラオケで にほんの うたを うたいました。', 'Tôi đã hát bài Nhật ở karaoke.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2485, 27899, '私の趣味は切手を集めることです。', 'わたしの しゅみは きってを あつめる こと です。', 'Sở thích của tôi là sưu tầm tem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2486, 28757, '秋になると、木の葉が赤くなります。', 'あきに なると、きの はが あかく なります。', 'Sang thu, lá cây chuyển đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2487, 44715, '晩ご飯の後で散歩をします。', 'ばんごはんの あとで さんぽを します。', 'Sau bữa tối tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2488, 44719, '最近、少し太りました。', 'さいきん、すこし ふとりました。', 'Gần đây tôi hơi béo lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2489, 44720, '病気で五キロ痩せました。', 'びょうきで ごキロ やせました。', 'Vì ốm mà tôi gầy đi năm ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2490, 27918, 'それはおもしろいですね。', 'それはおもしろいですね。', 'Thú vị nhỉ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2491, 44722, '早く風邪を治してください。', 'はやく かぜを なおして ください。', 'Mau khỏi cảm nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2492, 44724, '転んで、足の骨が折れました。', 'ころんで、あしの ほねが おれました。', 'Tôi ngã và bị gãy xương chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2493, 44730, 'ここで十分休憩しましょう。', 'ここで じゅっぷん きゅうけい しましょう。', 'Nghỉ giải lao mười phút ở đây nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2494, 27901, 'ドルを円に換えます。', 'ドルを えんに かえます。', 'Tôi đổi đô la sang yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2495, 27902, '車を運転することができますか。', 'くるまを うんてん する ことが できますか。', 'Bạn có biết lái xe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2496, 27903, 'ホテルを予約しました。', 'ホテルを よやく しました。', 'Tôi đã đặt phòng khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2497, 27907, '趣味は何ですか。', 'しゅみは なん ですか。', 'Sở thích của bạn là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2498, 27908, '毎晩日記を書きます。', 'まいばん にっきを かきます。', 'Tối nào tôi cũng viết nhật ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2499, 27910, '課長は今会議中です。', 'かちょうは いま かいぎちゅう です。', 'Trưởng nhóm hiện đang họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2500, 27911, '部長に報告します。', 'ぶちょうに ほうこく します。', 'Tôi báo cáo cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2501, 27912, '社長は今、出張中です。', 'しゃちょうは いま、しゅっちょうちゅう です。', 'Giám đốc hiện đang đi công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2502, 27913, 'どんな動物が好きですか。', 'どんな どうぶつが すき ですか。', 'Bạn thích con vật nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2503, 27914, '牧場で馬に乗りました。', 'ぼくじょうで うまに のりました。', 'Tôi cưỡi ngựa ở trang trại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2504, 27917, 'へえ、そうですか。知りませんでした。', 'へえ、そう ですか。しりません でした。', 'Ồ, vậy à. Tôi không biết đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2505, 27920, 'A：あした休みですよ。B：ほんとうですか。', 'エー：あした やすみ ですよ。ビー：ほんとう ですか。', 'A: Mai được nghỉ đấy. B: Thật à?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2506, 27921, 'ぜひ一度、うちへ来てください。', 'ぜひ いちど、うちへ きて ください。', 'Nhất định hãy đến nhà tôi chơi một lần nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2507, 27924, '秋葉原でパソコンを買いました。', 'あきはばらで パソコンを かいました。', 'Tôi mua máy tính ở Akihabara.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2508, 27925, 'きのう、工場を見学しました。', 'きのう、こうじょうを けんがく しました。', 'Hôm qua tôi đi tham quan nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2509, 27926, '国際電話をかけます。', 'こくさい でんわを かけます。', 'Tôi gọi điện thoại quốc tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2510, 27927, '北海道の牧場で牛を見ました。', 'ほっかいどうの ぼくじょうで うしを みました。', 'Tôi đã xem bò ở trang trại Hokkaido.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2511, 27904, '娘はピアノを習っています。', 'むすめは ピアノを ならって います。', 'Con gái tôi đang học piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2512, 27905, 'このプールは五十メートルあります。', 'この プールは ごじゅう メートル あります。', 'Hồ bơi này dài năm mươi mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2513, 44726, '雨の日は膝が痛みます。', 'あめの ひは ひざが いたみます。', 'Ngày mưa đầu gối tôi đau nhức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2514, 44729, '赤ちゃんがよく眠っています。', 'あかちゃんが よく ねむって います。', 'Em bé đang ngủ ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2515, 41377, '電子レンジで手軽に作れる料理だ。', 'でんし レンジで てがるに つくれる りょうりだ。', 'Đây là món có thể làm dễ dàng bằng lò vi sóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2516, 27929, 'ホテルに泊まります。', 'ホテルにとまります。', 'Trọ, ngủ trọ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2517, 27933, 'このりんごは眠いです。', 'このりんごはねむいです。', 'Quả táo này buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2518, 27934, 'このりんごは強いです。', 'このりんごはつよいです。', 'Quả táo này mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2519, 27935, 'このりんごは弱いです。', 'このりんごはよわいです。', 'Quả táo này yếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2520, 27950, 'ここは無理です。', 'ここはむりです。', 'Ở đây excessive.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2521, 27951, 'このりんごは体にいいです。', 'このりんごはからだにいいです。', 'Quả táo này tốt cho sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2522, 27954, 'このりんごは調子がいいです。', 'このりんごはちょうしがいいです。', 'Quả táo này tình trạng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2523, 27955, 'このりんごは調子が悪いです。', 'このりんごはちょうしがわるいです。', 'Quả táo này tình trạng xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2524, 27939, 'お茶を飲みませんか。', 'おちゃを のみませんか。', 'Uống trà không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2525, 27930, '毎週土曜日に部屋を掃除します。', 'まいしゅう どようびに へやを そうじ します。', 'Thứ bảy hằng tuần tôi dọn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2526, 27931, '日曜日に洗濯します。', 'にちようびに せんたく します。', 'Chủ nhật tôi giặt quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2527, 27932, '暖かくなりました。', 'あたたかく なりました。', 'Trời đã ấm lên rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2528, 27938, 'テレビで相撲を見ました。', 'テレビで すもうを みました。', 'Tôi đã xem vật sumo trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2529, 27940, '雨の日は家で本を読みます。', 'あめの ひは いえで ほんを よみます。', 'Ngày mưa tôi ở nhà đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2530, 27941, '最近、体の調子がいいです。', 'さいきん、からだの ちょうしが いい です。', 'Gần đây sức khỏe tôi tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2531, 27942, '一度、京都へ行ってみたいです。', 'いちど、きょうとへ いって みたい です。', 'Tôi muốn thử đi Kyoto một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2532, 27943, 'すしを一度も食べたことがありません。', 'すしを いちども たべた ことが ありません。', 'Tôi chưa ăn sushi lần nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2533, 27944, 'だんだん寒くなりました。', 'だんだん さむく なりました。', 'Trời dần dần lạnh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2534, 27945, 'もうすぐ夏休みです。', 'もうすぐ なつやすみ です。', 'Sắp đến kỳ nghỉ hè rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2535, 27947, 'この店は安いです。でも、あまりおいしくないです。', 'この みせは やすい です。でも、あまり おいしく ない です。', 'Quán này rẻ. Nhưng không ngon lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2536, 27948, 'では、乾杯しましょう。', 'では、かんぱい しましょう。', 'Nào, chúng ta nâng cốc nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2537, 27953, '葛飾北斎の絵は世界で有名です。', 'かつしか ほくさいの えは せかいで ゆうめい です。', 'Tranh của Katsushika Hokusai nổi tiếng khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2538, 27958, 'この映画は何回も見ました。', 'この えいがは なんかいも みました。', 'Bộ phim này tôi đã xem nhiều lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2539, 27959, 'この部屋は広いです。しかし、駅から遠いです。', 'この へやは ひろい です。しかし、えきから とおい です。', 'Căn phòng này rộng. Tuy nhiên, xa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2540, 27937, '父は日曜日にゴルフをします。', 'ちちは にちようびに ゴルフを します。', 'Chủ nhật bố tôi chơi gôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2755, 28223, '新聞社へ行きます。', 'しんぶんしゃへいきます。', 'Tôi đi đến công ty phát hành báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2541, 27949, 'ダイエットをしていますから、甘い物を食べません。', 'ダイエットを して いますから、あまい ものを たべません。', 'Tôi đang ăn kiêng nên không ăn đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2542, 27960, '誕生日にケーキを食べました。', 'たんじょうびに ケーキを たべました。', 'Sinh nhật tôi đã ăn bánh ga-tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2543, 27962, 'わからない言葉を辞書で調べます。', 'わからない ことばを じしょで しらべます。', 'Từ không hiểu tôi tra trong từ điển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2544, 28556, '駅の西に大きい公園があります。', 'えきの にしに おおきい こうえんが あります。', 'Phía tây ga có một công viên lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2545, 44733, '母の病気が心配です。', 'ははの びょうきが しんぱい です。', 'Tôi lo cho bệnh của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2546, 27966, '山田君は親切です。', 'やまだくんはしんせつです。', 'Cậu Yamada rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2547, 27988, '国へ帰るの？', 'くにへかえるの？', 'Anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2548, 27989, 'どうするの？', 'どうするの？', 'Anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2549, 27990, 'どうしようかな。', 'どうしようかな。', 'Tính sao đây nhỉ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2550, 27995, 'お祭りがあります。', 'おまつりがあります。', 'Được tổ chức', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2551, 27996, '役に立ちます。', 'やくにたちます。', 'Giúp ích', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2552, 27998, '会社をやめます。', 'かいしゃをやめます。', 'Nghỉ [việc ở công ty], bỏ, thôi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2553, 27999, '気をつけます。', 'きをつけます。', 'Chú ý', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2554, 47065, '今、この映画が話題になっている。', 'いま、この えいがが わだいに なって いる。', 'Hiện bộ phim này đang được bàn tán sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2555, 27965, '君はどこへ行くの。', 'きみは どこへ いくの。', 'Cậu đi đâu đấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2556, 27967, 'A：あした行く?B：うん、行く。', 'エー：あした いく?ビー：うん、いく。', 'A: Mai đi không? B: Ừ, đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2557, 27968, 'A：お茶、飲む?B：ううん、いらない。', 'エー：おちゃ、のむ?ビー：ううん、いらない。', 'A: Uống trà không? B: Không, không cần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2558, 27970, 'お正月に着物を着ました。', 'おしょうがつに きものを きました。', 'Dịp Tết tôi mặc kimono.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2559, 27972, '初めは日本語が全然わかりませんでした。', 'はじめは にほんごが ぜんぜん わかりません でした。', 'Lúc đầu tôi hoàn toàn không hiểu tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2560, 27974, 'こっちへ来て。', 'こっちへ きて。', 'Lại đây nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2561, 27975, 'そっちは暑い?', 'そっちは あつい?', 'Bên đó có nóng không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2562, 27976, '駅はあっちだよ。', 'えきは あっちだよ。', 'Ga ở đằng kia đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2563, 27984, 'あとで電話します。', 'あとで でんわ します。', 'Lát nữa tôi sẽ gọi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2564, 27977, 'コーヒーとお茶、どっちがいい?', 'コーヒーと おちゃ、どっちが いい?', 'Cà phê với trà, cậu chọn cái nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2565, 27978, 'みんなで写真を撮りましょう。', 'みんなで しゃしんを とりましょう。', 'Mọi người cùng chụp ảnh nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2566, 27979, '行きたいけど、時間がない。', 'いきたい けど、じかんが ない。', 'Muốn đi nhưng không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2567, 27980, 'もうおなかがいっぱいです。', 'もう おなかが いっぱい です。', 'Tôi no rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2568, 27981, 'よかったら、一緒に行きませんか。', 'よかったら、いっしょに いきませんか。', 'Nếu bạn muốn thì cùng đi nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2569, 27982, '日本でいろいろな所へ行きました。', 'にほんで いろいろな ところへ いきました。', 'Ở Nhật tôi đã đi nhiều nơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2570, 27987, 'この間、駅で先生に会いました。', 'この あいだ、えきで せんせいに あいました。', 'Hôm nọ tôi gặp thầy ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2571, 27971, '日本のビザを取りました。', 'にほんの ビザを とりました。', 'Tôi đã xin được visa Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2572, 27985, '父はサラリーマンです。', 'ちちは サラリーマン です。', 'Bố tôi là nhân viên văn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2573, 27992, '先生は「あしたテストがある」と言いました。', 'せんせいは 「あした テストが ある」と いいました。', 'Thầy nói "mai có bài kiểm tra".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2574, 27997, 'この時計は動きません。', 'この とけいは うごきません。', 'Chiếc đồng hồ này không chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2575, 28001, 'ここはむだです。', 'ここはむだです。', 'Ở đây sự lãng phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2576, 28002, 'ここは不便です。', 'ここはふべんです。', 'Ở đây bất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2577, 28003, 'このりんごはすごいです。', 'このりんごはすごいです。', 'Quả táo này giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2578, 28528, '健康のために毎日運動します。', 'けんこうの ために まいにち うんどう します。', 'Vì sức khỏe, ngày nào tôi cũng tập thể dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2579, 41490, '焦げ茶色のコートを買った。', 'こげちゃいろの コートを かった。', 'Tôi mua chiếc áo khoác màu nâu sẫm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2580, 28028, 'お茶でも飲みませんか。', 'おちゃでものみませんか。', 'Anh/chị uống trà (hay gì đó) nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2581, 28030, 'もう帰らないと……。', 'もうかえらないと……。', 'Tôi phải về nhà bây giờ…', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2582, 28008, '東京は物価が高い。', 'とうきょうは ぶっかが たかい。', 'Vật giá ở Tokyo cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2583, 28009, 'その試合はテレビで生放送された。', 'その しあいは テレビで なま ほうそう された。', 'Trận đấu đó được truyền hình trực tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2584, 28006, 'トヨタは自動車の会社です。', 'トヨタは じどうしゃの かいしゃ です。', 'Toyota là công ty ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2585, 28000, '来年、日本に留学します。', 'らいねん、にほんに りゅうがく します。', 'Năm sau tôi sẽ du học Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2586, 28004, 'それはほんとうですか。', 'それは ほんとう ですか。', 'Chuyện đó có thật không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2587, 28005, 'うそを言ってはいけません。', 'うそを いっては いけません。', 'Không được nói dối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2588, 28015, '彼は数学の天才だと思います。', 'かれは すうがくの てんさいだと おもいます。', 'Tôi nghĩ anh ấy là thiên tài toán học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2589, 28016, 'あした、サッカーの試合があります。', 'あした、サッカーの しあいが あります。', 'Ngày mai có trận đấu bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2590, 28018, '先生の話はおもしろいです。', 'せんせいの はなしは おもしろい です。', 'Câu chuyện của thầy rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2591, 28019, '地球は丸いです。', 'ちきゅうは まるい です。', 'Trái đất hình tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2592, 28020, '今夜は月がきれいですね。', 'こんやは つきが きれい ですね。', 'Đêm nay trăng đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2593, 28021, '最近、忙しいです。', 'さいきん、いそがしい です。', 'Gần đây tôi bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2594, 28023, 'あしたはきっと晴れるでしょう。', 'あしたは きっと はれるでしょう。', 'Ngày mai chắc chắn trời sẽ nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2595, 28024, 'ほんとうにありがとうございました。', 'ほんとうに ありがとう ございました。', 'Thật sự cảm ơn anh rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2596, 28025, 'この料理はそんなに辛くないです。', 'この りょうりは そんなに からく ない です。', 'Món này không cay lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2597, 28027, '田中さん、久しぶりですね。', 'たなかさん、ひさしぶり ですね。', 'Anh Tanaka, lâu rồi không gặp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2598, 28029, 'A：一緒に行きますか。B：もちろん行きます。', 'エー：いっしょに いきますか。ビー：もちろん いきます。', 'A: Cùng đi chứ? B: Tất nhiên rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2599, 28036, 'かぐや姫は月へ帰りました。', 'かぐやひめは つきへ かえりました。', 'Công chúa Kaguya đã trở về mặt trăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2600, 28037, '天神祭は七月に大阪であります。', 'てんじんまつりは しちがつに おおさかで あります。', 'Lễ hội Tenjin diễn ra ở Osaka vào tháng bảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2601, 28038, '吉野山の桜は有名です。', 'よしのやまの さくらは ゆうめい です。', 'Hoa anh đào núi Yoshino rất nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2602, 28042, 'お金が足りません。', 'おかねが たりません。', 'Tôi không đủ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2603, 28043, '私と兄は同じ大学です。', 'わたしと あには おなじ だいがく です。', 'Tôi và anh trai học cùng trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2604, 44734, '歯が痛いです。', 'はが いたい です。', 'Tôi bị đau răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2605, 28052, 'しかたがありません。', 'しかたがありません。', 'Không còn cách nào khác', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2606, 44735, '昨日遅く寝たので、眠いです。', 'きのう おそく ねたので、ねむい です。', 'Hôm qua ngủ muộn nên tôi buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2607, 28031, 'アインシュタインから来ました。', 'アインシュタインからきました。', 'Tôi đến từ Albert Einstein.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2608, 28058, '眼鏡をかけます。', 'めがねをかけます。', 'Đeo [kính]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2609, 28059, 'ネクタイをします。', 'ネクタイをします。', 'Thắt [cà vạt]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2610, 28061, '私たちは学生です。', 'わたしたちはがくせいです。', 'We là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2611, 44768, '来週、大阪へ出張します。', 'らいしゅう、おおさかへ しゅっちょう します。', 'Tuần sau tôi đi công tác Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2612, 44774, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2613, 28072, '彼の話はよくわかりません。', 'かれの はなしは よく わかりません。', 'Tôi không hiểu rõ lời anh ấy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2614, 28046, '政治にはあまり興味がありません。', 'せいじには あまり きょうみが ありません。', 'Tôi không quan tâm lắm đến chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2615, 28050, 'お金をむだに使わないでください。', 'おかねを むだに つかわないで ください。', 'Đừng tiêu tiền lãng phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2616, 28054, 'あ、もう九時。ニュースを見ないと……。', 'あ、もう くじ。ニュースを みないと……。', 'À, chín giờ rồi. Phải xem tin tức mới được...', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2617, 28010, '毎晩テレビでニュースを見ます。', 'まいばん テレビで ニュースを みます。', 'Tối nào tôi cũng xem tin tức trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2618, 28011, '日本のアニメが大好きです。', 'にほんの アニメが だいすき です。', 'Tôi rất thích anime Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2619, 28013, 'このかばんはデザインがいいです。', 'この かばんは デザインが いい です。', 'Chiếc cặp này thiết kế đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2620, 28033, 'ガリレオは有名な科学者です。', 'ガリレオは ゆうめいな かがくしゃ です。', 'Galileo là nhà khoa học nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2621, 28035, 'フランクリンは雷の研究をしました。', 'フランクリンは かみなりの けんきゅうを しました。', 'Franklin đã nghiên cứu về sấm sét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2622, 28039, 'オーストラリアでカンガルーを見ました。', 'オーストラリアで カンガルーを みました。', 'Tôi đã thấy chuột túi ở Úc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2623, 28040, 'キャプテン・クックは世界を旅行しました。', 'キャプテン・クックは せかいを りょこう しました。', 'Thuyền trưởng Cook đã đi vòng quanh thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2624, 28041, 'ヨーネンは新しい会社です。', 'ヨーネンは あたらしい かいしゃ です。', 'Yōnen là một công ty mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2625, 28047, '結婚式でスピーチをしました。', 'けっこんしきで スピーチを しました。', 'Tôi đã phát biểu ở lễ cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2626, 28051, '朝のラッシュは大変です。', 'あさの ラッシュは たいへん です。', 'Giờ cao điểm buổi sáng thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2627, 28056, '新しい靴をはきます。', 'あたらしい くつを はきます。', 'Tôi đi đôi giày mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2628, 28057, '暑いですから、帽子をかぶります。', 'あつい ですから、ぼうしを かぶります。', 'Trời nóng nên tôi đội mũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2629, 28065, 'あの帽子をかぶっている人が田中さんです。', 'あの ぼうしを かぶって いる ひとが たなかさん です。', 'Người đội mũ kia là anh Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2630, 28066, '眼鏡をかけている人は誰ですか。', 'めがねを かけて いる ひとは だれ ですか。', 'Người đeo kính là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2631, 28071, 'あしたは都合が悪いです。', 'あしたは つごうが わるい です。', 'Ngày mai tôi không tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2632, 28074, 'ご結婚おめでとうございます。', 'ごけっこん おめでとう ございます。', 'Chúc mừng anh chị kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2633, 44738, 'このかばんはとても丈夫です。', 'この かばんは とても じょうぶ です。', 'Chiếc cặp này rất bền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2634, 28075, '本お探しですか。', 'ほんおさがしですか。', 'Anh/chị đang tìm sách à?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2635, 44746, '日本語がずいぶん上手になりましたね。', 'にほんごが ずいぶん じょうずに なりましたね。', 'Tiếng Nhật của bạn đã giỏi lên khá nhiều nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2636, 28084, '万里の長城へ行きます。', 'ばんりのちょうじょうへいきます。', 'Tôi đi đến Vạn lý trường thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2637, 44759, 'この工場では車を作っています。', 'この こうじょうでは くるまを つくって います。', 'Nhà máy này sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2638, 44760, 'パーティーの会場はホテルです。', 'パーティーの かいじょうは ホテル です。', 'Địa điểm tổ chức tiệc là khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2639, 28730, '花が咲きます。', 'はながさきます。', 'Nở (hoa)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2640, 44744, '旅行にパスポートが必要です。', 'りょこうに パスポートが ひつよう です。', 'Đi du lịch cần có hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2641, 44748, '早く起きてください。', 'はやく おきて ください。', 'Dậy sớm đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2642, 44754, '上司に休みを取ってもいいか聞いた。', 'じょうしに やすみを とっても いいか きいた。', 'Tôi hỏi cấp trên xem có được nghỉ phép không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2643, 44755, '部長は部下にとても優しい。', 'ぶちょうは ぶかに とても やさしい。', 'Trưởng phòng rất tử tế với cấp dưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2644, 44756, '仕事のあと、同僚と飲みに行った。', 'しごとの あと、どうりょうと のみに いった。', 'Tan làm, tôi đi uống với đồng nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2645, 44758, 'まず一階の受付で名前を言ってください。', 'まず いっかいの うけつけで なまえを いって ください。', 'Trước tiên hãy báo tên ở quầy lễ tân tầng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2646, 44741, 'この川で泳ぐのは危険です。', 'この かわで およぐのは きけん です。', 'Bơi ở con sông này rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2647, 28077, 'こちらは山田さんです。', 'こちらは やまださん です。', 'Đây là anh Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2648, 44751, '社長は今、出張中です。', 'しゃちょうは いま、しゅっちょうちゅう です。', 'Giám đốc hiện đang đi công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2649, 44753, '課長は今会議中です。', 'かちょうは いま かいぎちゅう です。', 'Trưởng nhóm hiện đang họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2650, 28076, 'では、また来週。', 'では、また らいしゅう。', 'Vậy hẹn tuần sau gặp lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2651, 28078, 'このアパートの家賃は六万円です。', 'この アパートの やちんは ろくまんえん です。', 'Tiền thuê căn hộ này là sáu mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2652, 28081, '布団は押し入れに入れます。', 'ふとんは おしいれに いれます。', 'Chăn nệm được cất vào tủ âm tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2653, 28082, '天気がいいので、布団を干しました。', 'てんきが いいので、ふとんを ほしました。', 'Trời đẹp nên tôi phơi chăn nệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2654, 44747, 'あしたはきっと晴れるでしょう。', 'あしたは きっと はれるでしょう。', 'Ngày mai chắc chắn trời sẽ nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2655, 28086, 'うーん、ちょっと難しいですね。', 'うーん、ちょっと むずかしい ですね。', 'Ừm, hơi khó nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2656, 28088, '余暇開発センターがレジャー白書を出しています。', 'よか かいはつ センターが レジャー はくしょを だして います。', 'Trung tâm phát triển giải trí phát hành sách trắng về giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2657, 28062, '寒いので、コートを着て出かけます。', 'さむいので、コートを きて でかけます。', 'Trời lạnh nên tôi mặc áo khoác ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2658, 28063, '母が編んだセーターを着ています。', 'ははが あんだ セーターを きて います。', 'Tôi đang mặc chiếc áo len mẹ đan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2659, 28064, '面接にスーツを着て行きます。', 'めんせつに スーツを きて いきます。', 'Tôi mặc com-lê đi phỏng vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2660, 44739, 'A：大丈夫ですか。B：はい、大丈夫です。', 'エー：だいじょうぶ ですか。ビー：はい、だいじょうぶ です。', 'A: Bạn ổn chứ? B: Vâng, tôi không sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2661, 28876, '新しい星が発見されました。', 'あたらしい ほしが はっけん されました。', 'Một ngôi sao mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2662, 41554, '今夜は真ん丸い月が出ている。', 'こんやは まんまるい つきが でて いる。', 'Đêm nay trăng tròn vành vạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2663, 28094, 'ドアに触ります。', 'ドアにさわります。', 'Sờ, chạm vào', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2664, 28095, 'お釣りが出ます。', 'おつりがでます。', 'Ra,đi ra', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2665, 41636, 'そんな生温いやり方では解決しない。', 'そんな なまぬるい やりかたでは かいけつ しない。', 'Cách làm nửa vời như thế không giải quyết được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2666, 28097, '橋を渡ります。', 'はしをわたります。', 'Qua,đi qua (cầu)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2667, 28098, '右へ曲がります。', 'みぎへまがります。', 'Rẽ [phải]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2668, 28099, 'このりんごは寂しいです。', 'このりんごはさびしいです。', 'Quả táo này lonely.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2669, 28118, '時計が動きます。', 'とけいがうごきます。', 'Chuyển động,chạy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2670, 28119, '車に気を つけます。', 'くるまにきを つけます。', 'Chú ý,cẩn thận', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2671, 28111, 'この映画は何回も見ました。', 'この えいがは なんかいも みました。', 'Bộ phim này tôi đã xem nhiều lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2672, 28069, 'このロボットは料理を作ることができます。', 'この ロボットは りょうりを つくる ことが できます。', 'Con rô-bốt này có thể nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2673, 28079, 'うちはダイニングキチンが広いです。', 'うちは ダイニングキチンが ひろい です。', 'Nhà tôi có bếp liền phòng ăn rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2674, 28083, 'パリへ旅行に行きたいです。', 'パリへ りょこうに いきたい です。', 'Tôi muốn đi du lịch Paris.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2675, 28087, '駅の近くのアパートに住んでいます。', 'えきの ちかくの アパートに すんで います。', 'Tôi sống ở căn hộ gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2676, 28092, 'ドアを引いて開けてください。', 'ドアを ひいて あけて ください。', 'Hãy kéo cửa ra để mở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2677, 28093, '部屋の電気を変えました。', 'へやの でんきを かえました。', 'Tôi đã thay đèn trong phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2678, 28100, 'お湯を入れて、三分待ってください。', 'おゆを いれて、さんぷん まって ください。', 'Hãy rót nước nóng vào rồi đợi ba phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2679, 28101, '隣の部屋から音が聞こえます。', 'となりの へやから おとが きこえます。', 'Có tiếng động từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2680, 28104, 'この道をまっすぐ行ってください。', 'この みちを まっすぐ いって ください。', 'Hãy đi thẳng con đường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2681, 28106, '信号が青になったら、渡ります。', 'しんごうが あおに なったら、わたります。', 'Khi đèn xanh thì sang đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2682, 28107, 'あの角に銀行があります。', 'あの かどに ぎんこうが あります。', 'Ở góc kia có ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2683, 28108, '橋を渡ると、駅があります。', 'はしを わたると、えきが あります。', 'Qua cầu là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2684, 28110, 'あの白い建物は病院です。', 'あの しろい たてものは びょういん です。', 'Tòa nhà trắng kia là bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2685, 28112, '二つ目の信号を左へ曲がってください。', 'ふたつめの しんごうを ひだりへ まがって ください。', 'Đến đèn tín hiệu thứ hai hãy rẽ trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2686, 28115, '元気茶を飲むと、元気になります。', 'げんきちゃを のむと、げんきに なります。', 'Uống trà Genki thì sẽ khỏe khoắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2687, 28116, '本田駅でバスに乗り換えてください。', 'ほんだえきで バスに のりかえて ください。', 'Hãy đổi sang xe buýt ở ga Honda.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2688, 28117, '図書館前でバスを降りてください。', 'としょかんまえで バスを おりて ください。', 'Hãy xuống xe buýt ở trạm Toshokan-mae.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2689, 28120, '来月、大阪へ引っ越しします。', 'らいげつ、おおさかへ ひっこし します。', 'Tháng sau tôi chuyển nhà đến Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2690, 28121, '電気屋へ行きます。', 'でんきやへいきます。', 'Tôi đi đến cửa hàng đồ điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2691, 28127, '外国人登録証から来ました。', 'がいこくじんとうろくしょうからきました。', 'Tôi đến từ thẻ đăng kí người nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2692, 44761, '来週の予定はもう決まりましたか。', 'らいしゅうの よていは もう きまりましたか。', 'Kế hoạch tuần sau đã định chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2693, 28130, '連れて行きます。', 'つれていきます。', 'Dẫn đi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2694, 28131, '連れて来ます。', 'つれてきます。', 'Dẫn đến', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2695, 28132, '人を送ります。', 'ひとをおくります。', 'Đưa đi, đưa đến, tiễn', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2696, 28146, 'コーヒーをいれます。', 'コーヒーをいれます。', 'Pha(cà phê)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2697, 28152, '年を取ります。', 'としをとります。', 'Thêm [tuổi]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2698, 28157, 'たらもし。', 'たらもし。', 'Nếu [~ thì]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2699, 44764, '遅れるときは、必ず連絡してください。', 'おくれる ときは、かならず れんらく して ください。', 'Khi đến muộn, nhất định phải liên lạc nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2700, 44767, '旅行の準備はもう終わりましたか。', 'りょこうの じゅんびは もう おわりましたか。', 'Bạn đã chuẩn bị xong cho chuyến du lịch chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2701, 28122, '花屋で花を買いました。', 'はなやで はなを かいました。', 'Tôi mua hoa ở tiệm hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2702, 28123, 'この機械の使い方を教えてください。', 'この きかいの つかいかたを おしえて ください。', 'Hãy chỉ tôi cách dùng chiếc máy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2703, 28124, 'このつまみを回すと、音が大きくなります。', 'この つまみを まわすと、おとが おおきく なります。', 'Vặn núm này thì âm thanh to lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2704, 28129, '先生が作文を直してくれました。', 'せんせいが さくぶんを なおして くれました。', 'Thầy đã sửa bài văn cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2705, 28133, '友達を紹介します。', 'ともだちを しょうかい します。', 'Tôi xin giới thiệu bạn tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2706, 28135, '使い方を説明します。', 'つかいかたを せつめい します。', 'Tôi sẽ giải thích cách sử dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2707, 28136, 'おじいちゃんは毎朝散歩します。', 'おじいちゃんは まいあさ さんぽ します。', 'Ông sáng nào cũng đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2708, 28137, 'おばあちゃんにお菓子をもらいました。', 'おばあちゃんに おかしを もらいました。', 'Tôi được bà cho bánh kẹo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2709, 28140, '子どもにお菓子をあげました。', 'こどもに おかしを あげました。', 'Tôi cho trẻ con bánh kẹo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2710, 28142, '宿題を全部やりました。', 'しゅくだいを ぜんぶ やりました。', 'Tôi đã làm hết bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2711, 28143, 'この料理は自分で作りました。', 'この りょうりは じぶんで つくりました。', 'Món này tôi tự làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2712, 28144, 'ほかに何か質問がありますか。', 'ほかに なにか しつもんが ありますか。', 'Ngoài ra còn câu hỏi nào không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2756, 39673, 'ドアがひとりでに開いた。', 'ドアが ひとりでに あいた。', 'Cánh cửa tự mở ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2713, 28145, '母の日に花をあげました。', 'ははの ひに はなを あげました。', 'Ngày của mẹ tôi tặng hoa cho mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2714, 28147, 'この言葉の意味を教えてください。', 'この ことばの いみを おしえて ください。', 'Hãy cho tôi biết nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2715, 28148, '家族で旅行するので、ワゴン車を借りました。', 'かぞくで りょこう するので、ワゴンしゃを かりました。', 'Đi du lịch cả nhà nên tôi thuê xe wagon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2716, 28151, '東京に何時に着きますか。', 'とうきょうに なんじに つきますか。', 'Mấy giờ thì đến Tokyo?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2717, 28153, 'お金が足りません。', 'おかねが たりません。', 'Tôi không đủ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2718, 28156, '日本の人口は一億二千万人ぐらいです。', 'にほんの じんこうは いちおく にせんまんにん ぐらい です。', 'Dân số Nhật khoảng một trăm hai mươi triệu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2719, 28173, '駅の近くでアパートを探しています。', 'えきの ちかくで アパートを さがして います。', 'Tôi đang tìm căn hộ gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2720, 28163, '［いろいろ］お世話になりました。', '［いろいろ］おせわになりました。', 'Cảm ơn anh/chị đã giúp đỡ tôi trong thời gian qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2721, 28165, 'どうぞお元気で。', 'どうぞおげんきで。', 'Chúc anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2722, 44776, '外国で働いた経験があります。', 'がいこくで はたらいた けいけんが あります。', 'Tôi có kinh nghiệm làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2723, 28176, '宿題はもうやりました。', 'しゅくだいは もう やりました。', 'Bài tập tôi đã làm rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2724, 28178, '遅れるときは連絡してください。', 'おくれる ときは れんらく して ください。', 'Khi đến muộn hãy liên lạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2725, 28182, '夏祭りで盆踊りを踊りました。', 'なつまつりで ぼんおどりを おどりました。', 'Ở lễ hội mùa hè tôi đã múa điệu Bon odori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2726, 28174, '時間に遅れます。', 'じかんにおくれます。', 'Chậm, muộn [cuộc hẹn,v.v.]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2727, 28175, '時間に間に 合います。', 'じかんにまに あいます。', 'Kịp [giờ hẹn…]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2728, 28184, 'パーティーの場所はどこですか。', 'パーティーの ばしょは どこ ですか。', 'Địa điểm bữa tiệc ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2729, 44773, '会議の資料をコピーしておいてください。', 'かいぎの しりょうを コピー して おいて ください。', 'Hãy photo sẵn tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2730, 44777, 'この会社は高い技術を持っている。', 'この かいしゃは たかい ぎじゅつを もって いる。', 'Công ty này có kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2731, 28159, 'もしもし、山田です。', 'もしもし、やまだ です。', 'A lô, tôi là Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2732, 44778, '大学で経済を勉強しています。', 'だいがくで けいざいを べんきょう して います。', 'Tôi đang học kinh tế ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2733, 28161, '国の家族のことを考えます。', 'くにの かぞくの ことを かんがえます。', 'Tôi nghĩ về gia đình ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2734, 28162, 'あした暇ですか。', 'あした ひま ですか。', 'Ngày mai bạn rảnh không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2735, 28164, '試験まで毎日頑張ります。', 'しけんまで まいにち がんばります。', 'Đến kỳ thi tôi sẽ cố gắng mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2736, 28155, 'これはいいチャンスですね。', 'これは いい チャンス ですね。', 'Đây là cơ hội tốt nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2737, 44779, '政治にはあまり興味がありません。', 'せいじには あまり きょうみが ありません。', 'Tôi không quan tâm lắm đến chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2738, 28188, '国会議事堂を見学しました。', 'こっかい ぎじどうを けんがく しました。', 'Tôi đã tham quan tòa nhà Quốc hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2739, 28189, '平日は忙しいですが、週末は暇です。', 'へいじつは いそがしい ですが、しゅうまつは ひま です。', 'Ngày thường tôi bận, nhưng cuối tuần thì rảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2740, 28191, '今度の日曜日、一緒に出かけませんか。', 'こんどの にちようび、いっしょに でかけませんか。', 'Chủ nhật tới cùng ra ngoài chơi không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2741, 44781, '学校の規則を守りましょう。', 'がっこうの きそくを まもりましょう。', 'Hãy tuân thủ nội quy trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2742, 44780, '大学で法律を勉強しています。', 'だいがくで ほうりつを べんきょう して います。', 'Tôi đang học luật ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2743, 44775, '夏休みの計画を立てました。', 'なつやすみの けいかくを たてました。', 'Tôi đã lên kế hoạch cho kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2744, 41695, '秋の紅葉が鮮やかだ。', 'あきの こうようが あざやかだ。', 'Lá đỏ mùa thu rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2745, 41710, '彼は素早く部屋を片付けた。', 'かれは すばやく へやを かたづけた。', 'Anh ấy dọn phòng nhanh thoăn thoắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2746, 28196, 'だれでもですか。', 'だれでもですか。', 'Ai cũng vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2747, 28199, '私はそんな本です。', 'わたしはそんなほんです。', 'Tôi là ~ như thế đó (gần người nghe).', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2748, 28200, '私はあんな本です。', 'わたしはあんなほんです。', 'Tôi là ~ như thế kia (xa cả người nói và người nghe).', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2749, 28202, '荷物が片づきます。', 'にもつがかたづきます。', 'Được dọn dẹp ngăn nắp, gọn gàng [đồ đạc ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2750, 28203, 'ごみを出します。', 'ごみをだします。', 'Đổ, để [rác]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2751, 28214, 'このりんごは怖いです。', 'このりんごはこわいです。', 'Quả táo này sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2752, 28219, 'パーティーに参加します。', 'パーティーにさんかします。', 'Tham gia, dự [buổi tiệc]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2753, 28221, 'このりんごは都合がいいです。', 'このりんごはつごうがいいです。', 'Quả táo này có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2754, 28222, 'このりんごは都合が悪いです。', 'このりんごはつごうがわるいです。', 'Quả táo này không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2757, 28193, '社長に直接話したいんですが。', 'しゃちょうに ちょくせつ はなしたいん ですが。', 'Tôi muốn nói chuyện trực tiếp với giám đốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2758, 28194, '困ったときは、いつでも電話してください。', 'こまった ときは、いつでも でんわ して ください。', 'Khi gặp khó khăn, cứ gọi tôi bất cứ lúc nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2759, 28195, 'このカードはどこでも使えます。', 'この カードは どこでも つかえます。', 'Thẻ này dùng được ở bất cứ đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2760, 28198, 'こんな料理を食べたのは初めてです。', 'こんな りょうりを たべたのは はじめて です。', 'Đây là lần đầu tôi ăn món như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2761, 28204, '燃えるごみは月曜日と木曜日です。', 'もえる ごみは げつようびと もくようび です。', 'Rác cháy được đổ vào thứ Hai và thứ Năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2762, 28206, '駅の横にコンビニがあります。', 'えきの よこに コンビニが あります。', 'Bên cạnh ga có cửa hàng tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2763, 28207, '瓶と缶は水曜日に出してください。', 'びんと かんは すいようびに だして ください。', 'Chai lọ và lon hãy đổ vào thứ tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2764, 28208, '空いた缶はここに捨ててください。', 'あいた かんは ここに すてて ください。', 'Lon rỗng hãy vứt ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2765, 28211, 'いつか宇宙へ行ってみたいです。', 'いつか うちゅうへ いって みたい です。', 'Một ngày nào đó tôi muốn thử lên vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2766, 28213, '宇宙船の中は狭いそうです。', 'うちゅうせんの なかは せまい そう です。', 'Nghe nói bên trong tàu vũ trụ rất chật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2767, 28215, '宇宙ステーションで実験をしています。', 'うちゅう ステーションで じっけんを して います。', 'Người ta đang làm thí nghiệm trên trạm vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2768, 28217, '子どものころ、宇宙飛行士になりたかったです。', 'こどもの ころ、うちゅう ひこうしに なりたかった です。', 'Hồi nhỏ tôi muốn làm phi hành gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2769, 28218, '星出彰彦さんは宇宙ステーションで働きました。', 'ほしで あきひこさんは うちゅう ステーションで はたらきました。', 'Ông Hoshide Akihiko đã làm việc trên trạm vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2770, 28224, '毎週柔道を習っています。', 'まいしゅう じゅうどうを ならって います。', 'Hằng tuần tôi học judo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2771, 41757, 'ご多忙のところ、ありがとうございます。', 'ごたぼうの ところ、ありがとう ございます。', 'Cảm ơn anh đã dành thời gian dù rất bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2772, 41796, '雨で旅行が台無しになった。', 'あめで りょこうが だいなしに なった。', 'Chuyến du lịch hỏng bét vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2773, 28227, 'ごみが燃えます。', 'ごみがもえます。', 'Cháy được [rác ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2774, 28228, 'ジムには月・水・金に行きます。', 'ジムには げっすいきんに いきます。', 'Tôi đi phòng gym vào thứ Hai, thứ Tư, thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2775, 28230, '財布を忘れてしまった。困ったなあ。', 'さいふを わすれて しまった。こまったなあ。', 'Quên ví mất rồi. Gay quá!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2776, 28232, '別の日にしてもいいですか。', 'べつの ひに しても いい ですか。', 'Đổi sang ngày khác được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2777, 28233, '土井隆雄さんは日本人の宇宙飛行士です。', 'どい たかおさんは にほんじんの うちゅう ひこうし です。', 'Ông Doi Takao là phi hành gia người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2778, 28183, '公園でフリーマーケットがあります。', 'こうえんで フリーマーケットが あります。', 'Ở công viên có chợ đồ cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2779, 28185, '週末にボランティアをしています。', 'しゅうまつに ボランティアを して います。', 'Cuối tuần tôi làm tình nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2780, 28201, 'エドアストアで電気製品を買いました。', 'エドア ストアで でんき せいひんを かいました。', 'Tôi mua đồ điện ở Edoa Store.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2781, 41808, '祖母は九十歳になっても達者だ。', 'そぼは きゅうじゅっさいに なっても たっしゃだ。', 'Bà tôi chín mươi tuổi mà vẫn khỏe mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2782, 41814, '夏は単の着物を着る。', 'なつは ひとえの きものを きる。', 'Mùa hè mặc kimono một lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2783, 41833, 'このボールは弾力がある。', 'この ボールは だんりょくが ある。', 'Quả bóng này có độ đàn hồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2784, 41900, '田舎で長閑な一日を過ごした。', 'いなかで のどかな いちにちを すごした。', 'Tôi trải qua một ngày yên bình ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2785, 42017, '彼は大学卒業と同等の学力がある。', 'かれは だいがく そつぎょうと どうとうの がくりょくが ある。', 'Anh ấy có học lực tương đương tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2786, 42097, 'そんな馬鹿馬鹿しい話は信じられない。', 'そんな ばかばかしい はなしは しんじられない。', 'Chuyện ngớ ngẩn như thế không thể tin được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2787, 42138, 'あの二人はどうも反りが合わない。', 'あの ふたりは どうも そりが あわない。', 'Hai người đó dường như không hợp nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2788, 42143, '白と黒の斑の猫がいる。', 'しろと くろの ぶちの ねこが いる。', 'Có con mèo đốm trắng đen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2789, 42190, '事故の原因はまだ不明だ。', 'じこの げんいんは まだ ふめいだ。', 'Nguyên nhân tai nạn vẫn chưa rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2790, 42249, '落としたコップが粉々に割れた。', 'おとした コップが こなごなに われた。', 'Chiếc cốc làm rơi vỡ tan tành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2791, 42261, '平たく言えば、失敗したということだ。', 'ひらたく いえば、しっぱい したと いう ことだ。', 'Nói nôm na là đã thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2792, 42266, '電池を並列につないだ。', 'でんちを へいれつに つないだ。', 'Tôi mắc pin song song.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2793, 42300, '試合は呆気なく終わった。', 'しあいは あっけなく おわった。', 'Trận đấu kết thúc chóng vánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2794, 42354, '彼はスポーツ万能だ。', 'かれは スポーツ ばんのうだ。', 'Anh ấy môn thể thao nào cũng giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2795, 42364, '次の会議の日程は未定です。', 'つぎの かいぎの にっていは みてい です。', 'Lịch cuộc họp tới chưa được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2796, 42382, '一日で全部やるなんて無茶だ。', 'いちにちで ぜんぶ やる なんて むちゃだ。', 'Làm hết trong một ngày thì thật quá sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2797, 42384, '初めてのデートなら、無難な店を選んだほうがいい。', 'はじめての デートなら、ぶなんな みせを えらんだ ほうが いい。', 'Buổi hẹn đầu tiên thì nên chọn quán an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2798, 42414, '猛烈な暑さが続いている。', 'もうれつな あつさが つづいて いる。', 'Cái nóng dữ dội vẫn kéo dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2799, 28235, '道を走ります。', 'みちをはしります。', 'Chạy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2800, 31822, 'この詩には美しい比喩が使われている。', 'この しには うつくしい ひゆが つかわれて いる。', 'Bài thơ này sử dụng những ẩn dụ đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2801, 31817, 'パリは芸術の町として知られている。', 'パリは げいじゅつの まちと して しられて いる。', 'Paris được biết đến là thành phố nghệ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2802, 42443, '白鳥が優美に泳いでいる。', 'はくちょうが ゆうびに およいで いる。', 'Thiên nga bơi một cách thanh tao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2803, 42448, '今日のセミナーはとても有益だった。', 'きょうの セミナーは とても ゆうえき だった。', 'Buổi hội thảo hôm nay rất bổ ích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2804, 42451, '彼は次の首相の有力な候補だ。', 'かれは つぎの しゅしょうの ゆうりょくな こうほだ。', 'Ông ấy là ứng viên sáng giá cho chức thủ tướng tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2805, 42479, '遥か遠くに富士山が見える。', 'はるか とおくに ふじさんが みえる。', 'Xa tít đằng xa có thể thấy núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2806, 42525, 'この店は良質な肉を使っている。', 'この みせは りょうしつな にくを つかって いる。', 'Quán này dùng thịt chất lượng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2807, 42577, 'ダンサーの嫋かな動きに見とれた。', 'ダンサーの しなやかな うごきに みとれた。', 'Tôi say mê những động tác uyển chuyển của vũ công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2808, 31820, '『平家物語』は代表的な叙事文学だ。', '『へいけ ものがたり』は だいひょうてきな じょじ ぶんがくだ。', '"Truyện Heike" là tác phẩm văn học tự sự tiêu biểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2809, 31823, '鳩は平和の象徴だ。', 'はとは へいわの しょうちょうだ。', 'Chim bồ câu là biểu tượng của hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2810, 31825, '横綱らしい風格が出てきた。', 'よこづならしい ふうかくが でて きた。', 'Anh ấy đã toát lên phong thái của một yokozuna.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2811, 31827, '生け花にはいろいろな流派がある。', 'いけばなには いろいろな りゅうはが ある。', 'Nghệ thuật cắm hoa có nhiều trường phái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2812, 31830, '名作と呼ばれる映画を見た。', 'めいさくと よばれる えいがを みた。', 'Tôi đã xem bộ phim được gọi là kiệt tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2813, 40382, '観客のアンコールに応えて、もう一曲歌った。', 'かんきゃくの アンコールに こたえて、もう いっきょく うたった。', 'Đáp lại yêu cầu của khán giả, ca sĩ hát thêm một bài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2814, 40446, '彼は映画のシナリオを書いている。', 'かれは えいがの シナリオを かいて いる。', 'Anh ấy đang viết kịch bản phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2815, 40453, '水族館でイルカのショーを見た。', 'すいぞくかんで イルカの ショーを みた。', 'Tôi xem màn trình diễn cá heo ở thủy cung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2816, 40476, '開会のセレモニーが行われた。', 'かいかいの セレモニーが おこなわれた。', 'Buổi lễ khai mạc đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2817, 40503, 'ケーキのデコレーションを子供と一緒にした。', 'ケーキの デコレーションを こどもと いっしょに した。', 'Tôi cùng con trang trí bánh kem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2818, 40519, '今夜は野球のナイターを見に行く。', 'こんやは やきゅうの ナイターを みに いく。', 'Tối nay tôi đi xem trận bóng chày ban đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2819, 40577, 'この曲はメロディーが美しい。', 'この きょくは メロディーが うつくしい。', 'Bài hát này có giai điệu đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2820, 40687, '彼女は主人公の母親を演じた。', 'かのじょは しゅじんこうの ははおやを えんじた。', 'Cô ấy đóng vai mẹ của nhân vật chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2821, 40756, 'この庭には雅致がある。', 'この にわには がちが ある。', 'Khu vườn này mang vẻ tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2822, 40807, '母が玄関に花を活けた。', 'ははが げんかんに はなを いけた。', 'Mẹ cắm hoa ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2823, 40841, '父の還暦を家族で祝った。', 'ちちの かんれきを かぞくで いわった。', 'Cả nhà mừng thọ sáu mươi của bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2824, 40897, 'シェークスピアの戯曲を翻訳した。', 'シェークスピアの ぎきょくを ほんやく した。', 'Tôi đã dịch kịch bản của Shakespeare.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2825, 28236, '山が見えます。', 'やまがみえます。', 'Có thể nhìn thấy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2826, 28237, '音が聞こえます。', 'おとがきこえます。', 'Có thể nghe thấy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2827, 28238, '道ができます。', 'みちができます。', 'Được hoàn thành,được làm', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2828, 28240, 'ここは心配です。', 'ここはしんぱいです。', 'Ở đây worried.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2829, 38618, 'お昼は何を食べましょうか。', 'おひるは なにを たべましょうか。', 'Trưa nay mình ăn gì nhỉ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2830, 38691, 'マイクを使って話してください。', 'マイクを つかって はなして ください。', 'Hãy dùng micro để nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2831, 28258, '引っ越しで新しい家具を買った。', 'ひっこしで あたらしい かぐを かった。', 'Chuyển nhà nên tôi mua đồ nội thất mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2832, 28248, '私の家は駅から遠いです。', 'わたしの いえは えきから とおい です。', 'Nhà tôi ở xa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2833, 44771, '給料は毎月二十五日にもらいます。', 'きゅうりょうは まいつき にじゅうごにちに もらいます。', 'Tôi nhận lương vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2957, 28337, 'うーん、どうしようかな。', 'うーん、どう しようかな。', 'Ừm, làm sao bây giờ nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2834, 28245, '川で花火が見えます。', 'かわで はなびが みえます。', 'Ở bờ sông có thể nhìn thấy pháo hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2835, 28254, '日本語を勉強しています。', 'にほんごをべんきょうしています。', 'Tôi đang học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2836, 28251, '料理教室に通っています。', 'りょうり きょうしつに かよって います。', 'Tôi đang đi học lớp nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2837, 28255, '財布に千円しかありません。', 'さいふに せんえん しか ありません。', 'Trong ví chỉ có một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2838, 28256, 'ほかの色はありませんか。', 'ほかの いろは ありませんか。', 'Không có màu khác à?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2839, 28260, 'いつか自分の店を持ちたいです。', 'いつか じぶんの みせを もちたい です。', 'Một ngày nào đó tôi muốn có cửa hàng riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2840, 29060, 'お金を数えてください。', 'おかねを かぞえて ください。', 'Hãy đếm tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2841, 41819, '彼は会社の将来を担う人材だ。', 'かれは かいしゃの しょうらいを になう じんざいだ。', 'Anh ấy là nhân tài sẽ gánh vác tương lai công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2842, 40914, '体育の時間に逆立ちの練習をした。', 'たいいくの じかんに さかだちの れんしゅうを した。', 'Giờ thể dục chúng tôi tập trồng cây chuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2843, 40921, 'ベルサイユ宮殿を見学した。', 'ベルサイユ きゅうでんを けんがく した。', 'Tôi tham quan cung điện Versailles.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2844, 40969, '子供たちはゲームに興じていた。', 'こどもたちは ゲームに きょうじて いた。', 'Bọn trẻ đang mải vui với trò chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2845, 41032, '彼女は大学時代から劇団に入っている。', 'かのじょは だいがく じだいから げきだんに はいって いる。', 'Cô ấy tham gia đoàn kịch từ thời đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2846, 41115, '京都の道は碁盤の目のようになっている。', 'きょうとの みちは ごばんの めの ように なって いる。', 'Đường phố Kyoto chia ô như bàn cờ vây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2847, 41168, 'クラス全員で合唱した。', 'クラス ぜんいんで がっしょう した。', 'Cả lớp cùng hợp xướng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2848, 41217, 'この作物は作者の若いころの作だ。', 'この さくぶつは さくしゃの わかい ころの さくだ。', 'Tác phẩm này là sáng tác thời trẻ của tác giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2849, 41297, 'この映画は侍の生き方を描いている。', 'この えいがは さむらいの いきかたを えがいて いる。', 'Bộ phim này khắc họa lối sống của samurai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2850, 41372, 'このチームは守備が固い。', 'この チームは しゅびが かたい。', 'Đội này phòng thủ chắc chắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2851, 41430, '優勝の祝賀会が開かれた。', 'ゆうしょうの しゅくがかいが ひらかれた。', 'Tiệc mừng chức vô địch đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2852, 28262, 'このりんごはすばらしいです。', 'このりんごはすばらしいです。', 'Quả táo này tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2853, 28264, 'ここは大好きです。', 'ここはだいすきです。', 'Ở đây rất thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2854, 28177, '道で財布を拾いました。', 'みちで さいふを ひろいました。', 'Tôi nhặt được chiếc ví trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2855, 28267, 'ここは不思議です。', 'ここはふしぎです。', 'Ở đây fantastic.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2856, 28257, '嫌なら、はっきり言ったほうがいいですよ。', 'いやなら、はっきり いった ほうが いいですよ。', 'Nếu không thích thì nên nói rõ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2857, 28286, '秋葉原でパソコンを買いました。', 'あきはばらで パソコンを かいました。', 'Tôi mua máy tính ở Akihabara.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2858, 28278, '休みを取ります。', 'やすみをとります。', 'Xin(nghỉ)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2859, 28263, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2860, 28285, '関西空港へ行きます。', 'かんさいくうこうへいきます。', 'Tôi đi đến sân bay Kansai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2861, 28283, '母は台所で料理をしています。', 'ははは だいどころで りょうりを して います。', 'Mẹ đang nấu ăn trong bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2862, 28272, '空がとても青いです。', 'そらが とても あおい です。', 'Bầu trời rất xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2863, 28266, 'このケーキはおもしろい形をしています。', 'この ケーキは おもしろい かたちを して います。', 'Chiếc bánh này có hình dạng thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2864, 28270, '自転車にかごを付けました。', 'じてんしゃに かごを つけました。', 'Tôi gắn giỏ vào xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2865, 28271, 'ここにある本は自由に読んでもいいです。', 'ここに ある ほんは じゆうに よんでも いい です。', 'Sách ở đây cứ tự do đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2866, 28273, '鳥のように空を飛びたいです。', 'とりの ように そらを とびたい です。', 'Tôi muốn bay trên trời như chim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2867, 28275, '自分のことは自分でしなさい。', 'じぶんの ことは じぶんで しなさい。', 'Việc của mình thì tự mình làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2868, 28276, '将来、先生になりたいです。', 'しょうらい、せんせいに なりたい です。', 'Sau này tôi muốn làm giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2869, 28279, '山の上から見る景色はきれいです。', 'やまの うえから みる けしきは きれい です。', 'Phong cảnh nhìn từ trên núi rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2870, 28282, '通信販売で服を買いました。', 'つうしん はんばいで ふくを かいました。', 'Tôi mua quần áo qua hình thức bán hàng từ xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2871, 28284, '宿題はほとんど終わりました。', 'しゅくだいは ほとんど おわりました。', 'Bài tập gần như xong hết rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2872, 44826, 'ごみは決められた日に出してください。', 'ごみは きめられた ひに だして ください。', 'Hãy đổ rác vào ngày quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2873, 44839, '机の上を片付けてください。', 'つくえの うえを かたづけて ください。', 'Hãy dọn mặt bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2874, 44841, '道でお金を拾いました。', 'みちで おかねを ひろいました。', 'Tôi nhặt được tiền trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2875, 41821, '子供たちは森を探検した。', 'こどもたちは もりを たんけん した。', 'Bọn trẻ đã thám hiểm khu rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2876, 41454, 'この本の初版は二十年前に出た。', 'この ほんの しょはんは にじゅうねんまえに でた。', 'Ấn bản đầu tiên của cuốn sách ra cách đây hai mươi năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2877, 41520, 'この帯は西陣の織だ。', 'この おびは にしじんの おりだ。', 'Chiếc thắt lưng obi này là hàng dệt Nishijin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2878, 41526, 'この宗教には世界中に信者がいる。', 'この しゅうきょうには せかいじゅうに しんじゃが いる。', 'Tôn giáo này có tín đồ khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2879, 41598, '古代の人々は太陽を崇拝した。', 'こだいの ひとびとは たいようを すうはい した。', 'Người cổ đại tôn thờ mặt trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2880, 28296, '大学に通います。', 'だいがくにかよいます。', 'Đi học(đại học)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2881, 28298, 'ここはまじめです。', 'ここはまじめです。', 'Ở đây nghiêm túc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2882, 28299, 'ここは熱心です。', 'ここはねっしんです。', 'Ở đây nhiệt tình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2883, 28300, 'このりんごは偉いです。', 'このりんごはえらいです。', 'Quả táo này vĩ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2884, 28301, 'このりんごはちょうどいいです。', 'このりんごはちょうどいいです。', 'Quả táo này vừa đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2885, 28181, '日曜日に子どもの運動会があります。', 'にちようびに こどもの うんどうかいが あります。', 'Chủ nhật có hội thao của con tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2886, 38800, '彼は有名な歴史の学者です。', 'かれは ゆうめいな れきしの がくしゃ です。', 'Ông ấy là một học giả lịch sử nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2887, 38803, '朝の市場は活気がある。', 'あさの いちばは かっきが ある。', 'Chợ buổi sáng rất sôi động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2888, 38808, '風邪はまだ完全には治っていない。', 'かぜは まだ かんぜんには なおって いない。', 'Cảm vẫn chưa khỏi hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2889, 38809, 'この病院は患者がとても多い。', 'この びょういんは かんじゃが とても おおい。', 'Bệnh viện này có rất nhiều bệnh nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2890, 38812, '新入社員の歓迎会を開いた。', 'しんにゅうしゃいんの かんげいかいを ひらいた。', 'Chúng tôi tổ chức tiệc chào đón nhân viên mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2891, 38814, '話の途中で少し間があいた。', 'はなしの とちゅうで すこし まが あいた。', 'Giữa câu chuyện có một khoảng lặng ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2892, 38816, '料金には税金が含まれています。', 'りょうきんには ぜいきんが ふくまれて います。', 'Giá đã bao gồm thuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2893, 38819, '一つだけお願いがあります。', 'ひとつだけ おねがいが あります。', 'Tôi có một lời nhờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2894, 38821, '大きな企業で働きたい。', 'おおきな きぎょうで はたらきたい。', 'Tôi muốn làm việc ở doanh nghiệp lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2895, 28289, '私の夢は医者になることです。', 'わたしの ゆめは いしゃに なる こと です。', 'Ước mơ của tôi là trở thành bác sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2896, 28290, '電車の中で漫画を読んでいる人が多いです。', 'でんしゃの なかで まんがを よんで いる ひとが おおい です。', 'Trên tàu có nhiều người đọc truyện tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2897, 28249, '新しいマンションに引っ越しました。', 'あたらしい マンションに ひっこしました。', 'Tôi đã chuyển đến chung cư mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2898, 28250, 'このアパートはキッチンが広いです。', 'この アパートは キッチンが ひろい です。', 'Căn hộ này có bếp rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2899, 28252, 'マンションのパーティールームを予約しました。', 'マンションの パーティールームを よやく しました。', 'Tôi đặt phòng tiệc của chung cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2900, 28268, 'ポケットに鍵が入っています。', 'ポケットに かぎが はいって います。', 'Trong túi có chìa khóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2901, 28294, 'よくかんで食べてください。', 'よく かんで たべて ください。', 'Hãy nhai kỹ khi ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2902, 28295, '好きな色を選んでください。', 'すきな いろを えらんで ください。', 'Hãy chọn màu bạn thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2903, 28302, '山の上から見る景色はきれいです。', 'やまの うえから みる けしきは きれい です。', 'Phong cảnh nhìn từ trên núi rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2904, 28303, '美容院で髪を切りました。', 'びよういんで かみを きりました。', 'Tôi cắt tóc ở tiệm làm tóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2905, 28291, 'このロボットは料理を作ることができます。', 'この ロボットは りょうりを つくる ことが できます。', 'Con rô-bốt này có thể nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2906, 44842, 'お風呂を沸かしておきます。', 'おふろを わかして おきます。', 'Tôi đun sẵn nước tắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2907, 44844, 'パンを焼いて食べます。', 'パンを やいて たべます。', 'Tôi nướng bánh mì để ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2908, 44846, 'ビールがよく冷えています。', 'ビールが よく ひえて います。', 'Bia đã lạnh rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2909, 28190, '大阪弁はおもしろいですね。', 'おおさかべんは おもしろい ですね。', 'Giọng Osaka thú vị nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2910, 28310, 'このスープは味が薄いです。', 'この スープは あじが うすい です。', 'Món súp này nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2911, 28317, 'この番組はとてもおもしろいです。', 'この ばんぐみは とても おもしろい です。', 'Chương trình này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2912, 28320, '寝る前に小説を読みます。', 'ねる まえに しょうせつを よみます。', 'Trước khi ngủ tôi đọc tiểu thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2913, 28322, '彼は有名な音楽家です。', 'かれは ゆうめいな おんがくか です。', 'Ông ấy là một nhạc sĩ nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2914, 28323, '新しい洗濯機を買いました。', 'あたらしい せんたくきを かいました。', 'Tôi đã mua máy giặt mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2915, 28324, '息子は今年小学校に入りました。', 'むすこは ことし しょうがっこうに はいりました。', 'Con trai tôi năm nay vào tiểu học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2916, 28325, '息子さんはおいくつですか。', 'むすこさんは おいくつ ですか。', 'Con trai anh bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2917, 28319, '私は歌手です。', 'わたしはかしゅです。', 'Tôi là ca sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2918, 38805, '父は株で大きな損をした。', 'ちちは かぶで おおきな そんを した。', 'Bố tôi lỗ nặng vì cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2919, 38817, '川の向こう岸まで泳いだ。', 'かわの むこうぎしまで およいだ。', 'Tôi bơi sang tận bờ bên kia sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2920, 38822, '彼は手が器用で、何でも作れる。', 'かれは てが きようで、なんでも つくれる。', 'Anh ấy khéo tay, làm được đủ thứ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2921, 38825, '夜中に奇妙な音が聞こえた。', 'よなかに きみょうな おとが きこえた。', 'Nửa đêm tôi nghe thấy một âm thanh kỳ lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2922, 38826, '学校の前に旗が立っている。', 'がっこうの まえに はたが たって いる。', 'Trước trường có cắm lá cờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2923, 38829, '毎日七時ごろ帰宅します。', 'まいにち しちじごろ きたく します。', 'Ngày nào tôi cũng về nhà khoảng bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2924, 38831, '事故にあうなんて、気の毒ですね。', 'じこに あう なんて、きのどく ですね。', 'Gặp tai nạn như thế thật đáng thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2925, 28312, '注文した品物が届いた。', 'ちゅうもん した しなものが とどいた。', 'Món hàng tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2926, 29137, 'では、いただきます。', 'では、いただきます。', 'Vậy, xin mời mọi người ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2927, 28313, 'この店は値段が安いです。', 'この みせは ねだんが やすい です。', 'Cửa hàng này giá rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2928, 44866, '今ちょうど十二時です。', 'いま ちょうど じゅうにじ です。', 'Bây giờ vừa đúng mười hai giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2929, 44848, '雨で靴が汚れました。', 'あめで くつが よごれました。', 'Giày bị bẩn vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2930, 44850, '弟がおもちゃを壊しました。', 'おとうとが おもちゃを こわしました。', 'Em trai tôi làm hỏng đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2931, 44852, 'コップが落ちて割れました。', 'コップが おちて われました。', 'Cái cốc rơi xuống vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2932, 44854, '木から葉が落ちています。', 'きから はが おちて います。', 'Lá đang rơi từ trên cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2933, 44856, '店の前に人が並んでいます。', 'みせの まえに ひとが ならんで います。', 'Trước cửa hàng người ta đang xếp hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2934, 44858, '封筒に切手を貼りました。', 'ふうとうに きってを はりました。', 'Tôi dán tem lên phong bì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2935, 44860, '日本の生活に慣れました。', 'にほんの せいかつに なれました。', 'Tôi đã quen với cuộc sống ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2936, 44862, '隣の部屋がうるさくて、眠れません。', 'となりの へやが うるさくて、ねむれません。', 'Phòng bên ồn quá, tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2937, 44864, '丁寧に説明してくれました。', 'ていねいに せつめい して くれました。', 'Họ đã giải thích cẩn thận cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2938, 44867, 'しっかり勉強してください。', 'しっかり べんきょう して ください。', 'Hãy học hành chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2939, 28334, '［ちょっと］お願いがあるんですが。', '［ちょっと］おねがいがあるんですが。', 'Tôi có [chút] việc muốn nhờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2940, 28192, '日本語がずいぶん上手になりましたね。', 'にほんごが ずいぶん じょうずに なりましたね。', 'Tiếng Nhật của bạn đã giỏi lên khá nhiều nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2941, 38802, '新しい仕事は前より楽です。', 'あたらしい しごとは まえより らく です。', 'Công việc mới nhàn hơn trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2942, 38801, '毎日三十分、日本語の学習を続けている。', 'まいにち さんじゅっぷん、にほんごの がくしゅうを つづけて いる。', 'Tôi duy trì học tiếng Nhật 30 phút mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2943, 44868, '使った物はきちんと片付けてください。', 'つかった ものは きちんと かたづけて ください。', 'Đồ đã dùng thì hãy cất dọn ngăn nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2944, 38837, '彼は市の議員に選ばれた。', 'かれは しの ぎいんに えらばれた。', 'Ông ấy được bầu làm nghị viên thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2945, 38841, '道を逆に行ってしまった。', 'みちを ぎゃくに いって しまった。', 'Tôi lỡ đi ngược đường mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2946, 38842, '子供のころ、よく親に逆らった。', 'こどもの ころ、よく おやに さからった。', 'Hồi nhỏ tôi hay cãi lời bố mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2947, 38845, 'ここで十分休憩しましょう。', 'ここで じゅっぷん きゅうけい しましょう。', 'Nghỉ giải lao mười phút ở đây nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2948, 38847, 'このタオルは水をよく吸収する。', 'この タオルは みずを よく きゅうしゅう する。', 'Chiếc khăn này thấm nước tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2949, 38849, '医者は多くの人の命を救った。', 'いしゃは おおくの ひとの いのちを すくった。', 'Bác sĩ đã cứu sống rất nhiều người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2950, 38853, '駅前に巨大なビルが建った。', 'えきまえに きょだいな ビルが たった。', 'Một tòa nhà khổng lồ đã mọc lên trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2951, 46194, '駐車違反で罰金を払った。', 'ちゅうしゃ いはんで ばっきんを はらった。', 'Tôi bị phạt tiền vì đỗ xe sai quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2952, 28328, '自分のことは自分でしなさい。', 'じぶんの ことは じぶんで しなさい。', 'Việc của mình thì tự mình làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2953, 28330, 'しばらくここで待っていてください。', 'しばらく ここで まって いて ください。', 'Xin hãy đợi ở đây một lát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2954, 28331, '日曜日はたいてい家にいます。', 'にちようびは たいてい いえに います。', 'Chủ nhật tôi thường ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2955, 28333, '電車が遅れました。それで、遅刻しました。', 'でんしゃが おくれました。それで、ちこく しました。', 'Tàu bị trễ. Do đó tôi đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2956, 28336, '日本人と会話するのは楽しいです。', 'にほんじんと かいわ するのは たのしい です。', 'Nói chuyện với người Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2958, 28339, '日曜日のパーティーに参加します。', 'にちようびの パーティーに さんか します。', 'Tôi sẽ tham gia bữa tiệc chủ nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2959, 28340, 'パーティーの日にちが決まりました。', 'パーティーの ひにちが きまりました。', 'Ngày tổ chức tiệc đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2960, 28342, '雨の日は体育館で運動します。', 'あめの ひは たいいくかんで うんどう します。', 'Ngày mưa chúng tôi tập thể dục trong nhà thi đấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2961, 28343, '子どもは入場無料です。', 'こどもは にゅうじょう むりょう です。', 'Trẻ em vào cửa miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2962, 28344, '友達を映画に誘いました。', 'ともだちを えいがに さそいました。', 'Tôi rủ bạn đi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2963, 46196, '裁判の結果は来月出る。', 'さいばんの けっかは らいげつ でる。', 'Kết quả xét xử sẽ có vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2964, 41828, '肉や魚は蛋白質が豊富だ。', 'にくや さかなは たんぱくしつが ほうふだ。', 'Thịt và cá giàu chất đạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2965, 28347, 'このりんごは優しいです。', 'このりんごはやさしいです。', 'Quả táo này phong cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2966, 38836, '兄は電気の技師として働いている。', 'あには でんきの ぎしと して はたらいて いる。', 'Anh tôi làm kỹ sư điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2967, 28197, 'わからないことは何でも聞いてください。', 'わからない ことは なんでも きいて ください。', 'Không hiểu gì thì cứ hỏi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2968, 28351, '友達と喫茶店でおしゃべりしました。', 'ともだちと きっさてんで おしゃべり しました。', 'Tôi trò chuyện với bạn ở quán cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2969, 28311, '授業中にガムをかまないでください。', 'じゅぎょうちゅうに ガムを かまないで ください。', 'Xin đừng nhai kẹo cao su trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2970, 29209, 'プレゼントをきれいな紙で包みました。', 'プレゼントを きれいな かみで つつみました。', 'Tôi gói quà bằng giấy đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2971, 38851, '牧場で牛がのんびり草を食べている。', 'ぼくじょうで うしが のんびり くさを たべて いる。', 'Trên đồng cỏ, đàn bò thong thả gặm cỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2972, 38854, 'うそをついた彼をどうしても許せない。', 'うそを ついた かれを どうしても ゆるせない。', 'Tôi không thể nào tha thứ cho kẻ đã nói dối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2973, 38858, 'この川が二つの県の境になっている。', 'この かわが ふたつの けんの さかいに なって いる。', 'Con sông này là ranh giới giữa hai tỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2974, 38860, '失敗を恐れずに挑戦してください。', 'しっぱいを おそれずに ちょうせん して ください。', 'Hãy thử thách mà đừng sợ thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2975, 38863, '田中教授は経済学の専門家です。', 'たなか きょうじゅは けいざいがくの せんもんか です。', 'Giáo sư Tanaka là chuyên gia kinh tế học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2976, 38865, '緊張して、胸がどきどきする。', 'きんちょう して、むねが どきどき する。', 'Hồi hộp quá, tim đập thình thịch trong ngực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2977, 38867, '子供たちがガラスの玉で遊んでいる。', 'こどもたちが ガラスの たまで あそんで いる。', 'Bọn trẻ đang chơi bi thủy tinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2978, 38869, '父は毎朝七時に勤めに出る。', 'ちちは まいあさ しちじに つとめに でる。', 'Sáng nào bố tôi cũng đi làm lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2979, 38871, '近頃、物の値段が上がった。', 'ちかごろ、ものの ねだんが あがった。', 'Dạo này giá cả tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2980, 38876, 'この部品は軽い金属でできている。', 'この ぶひんは かるい きんぞくで できて いる。', 'Linh kiện này làm bằng kim loại nhẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2981, 38879, '走りすぎて、息が苦しい。', 'はしりすぎて、いきが くるしい。', 'Chạy nhiều quá nên thở không nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2982, 38881, '満員電車での通勤は苦痛だ。', 'まんいんでんしゃでの つうきんは くつうだ。', 'Đi làm bằng tàu chật cứng người thật là cực hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2983, 38883, '同じ間違いを繰り返さないようにしよう。', 'おなじ まちがいを くりかえさない ように しよう。', 'Hãy cố đừng lặp lại sai lầm cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2984, 46213, '日曜日に選挙の投票に行った。', 'にちようびに せんきょの とうひょうに いった。', 'Chủ nhật tôi đi bỏ phiếu bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2985, 46199, '犯人だという証拠がない。', 'はんにん だと いう しょうこが ない。', 'Không có bằng chứng cho thấy đó là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2986, 46201, '警察は容疑者を逮捕した。', 'けいさつは ようぎしゃを たいほ した。', 'Cảnh sát đã bắt giữ nghi phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2987, 46205, '与党は選挙で過半数を取った。', 'よとうは せんきょで かはんすうを とった。', 'Đảng cầm quyền đã giành quá bán trong cuộc bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2988, 46210, '来月から新しい制度を実施する。', 'らいげつから あたらしい せいどを じっし する。', 'Từ tháng sau sẽ thực thi chế độ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2989, 46208, '教育の改革が必要だと言われている。', 'きょういくの かいかくが ひつようだと いわれて いる。', 'Người ta cho rằng cần phải cải cách giáo dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2990, 46212, 'この路線のバスは来月で廃止される。', 'この ろせんの バスは らいげつで はいし される。', 'Tuyến xe buýt này sẽ bị bãi bỏ từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2991, 28353, 'ドアが閉まりる。', 'ドアがしまります。', 'Đóng(cửa)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2992, 28354, '電気がつきます。', 'でんきがつきます。', 'Dính, đính (có túi)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2993, 28355, '電気が消えます。', 'でんきがきえます。', 'Tắt(đèn)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2994, 28356, 'いすが壊れます。', 'いすがこわれます。', 'Hỏng(ghế)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2995, 28357, 'コップが割れます。', 'コップがわれます。', 'Có thể nghe thấy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2996, 28360, '服が汚れます。', 'ふくがよごれます。', 'Dơ,bẩn(tay)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2997, 28361, 'ポケットが付きます。', 'ポケットがつきます。', 'Dính, đính (có túi)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2998, 28362, 'ボタンが外れます。', 'ボタンがはずれます。', 'Tuột,bung,rời ra(sút nút)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (2999, 28366, 'かぎが掛かります。', 'かぎがかかります。', 'Khóa', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3000, 28205, 'ごみ置き場は駐車場の横にあります。', 'ごみ おきばは ちゅうしゃじょうの よこに あります。', 'Chỗ để rác nằm bên cạnh bãi đỗ xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3001, 28377, '私は駅員です。', 'わたしはえきいんです。', 'Tôi là nhân viên nhà ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3002, 28316, '弟は毎日ゲームをしています。', 'おとうとは まいにち ゲームを して います。', 'Em trai tôi ngày nào cũng chơi game.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3003, 28345, '週末に駅前でイベントがあります。', 'しゅうまつに えきまえで イベントが あります。', 'Cuối tuần có sự kiện ở trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3004, 28381, 'お先にどうぞ。', 'おさきにどうぞ。', 'Xin mời anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3005, 38862, '教科書の二十ページを開いてください。', 'きょうかしょの にじゅっページを ひらいて ください。', 'Hãy mở sách giáo khoa trang 20.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3006, 38873, '金がなくて、何も買えない。', 'かねが なくて、なにも かえない。', 'Không có tiền nên chẳng mua được gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3007, 44871, 'どんな音楽が好きですか。', 'どんな おんがくが すき ですか。', 'Bạn thích loại nhạc nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3008, 28364, '電話番号をまちがえました。', 'でんわ ばんごうを まちがえました。', 'Tôi đã nhầm số điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3009, 28365, 'どこかで財布を落としました。', 'どこかで さいふを おとしました。', 'Tôi đánh rơi ví ở đâu đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3010, 28367, 'テーブルをふいてください。', 'テーブルを ふいて ください。', 'Hãy lau bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3011, 28369, '遊んだ後で、おもちゃを片付けなさい。', 'あそんだ あとで、おもちゃを かたづけなさい。', 'Chơi xong thì dọn đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3012, 28370, 'お皿が割れてしまいました。', 'おさらが われて しまいました。', 'Cái đĩa bị vỡ mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3013, 28376, '強い風で木の枝が折れました。', 'つよい かぜで きの えだが おれました。', 'Gió mạnh làm gãy cành cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3014, 28380, 'メールの返事を待っています。', 'メールの へんじを まって います。', 'Tôi đang chờ thư trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3015, 28383, '今の電車に忘れ物をしてしまいました。', 'いまの でんしゃに わすれものを して しまいました。', 'Tôi để quên đồ trên chuyến tàu vừa chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3016, 28384, '電車に忘れ物をしました。', 'でんしゃに わすれものを しました。', 'Tôi để quên đồ trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3017, 28385, 'このくらいの大きさの箱です。', 'この くらいの おおきさの はこ です。', 'Là chiếc hộp cỡ chừng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3018, 28386, '駅の右側に銀行があります。', 'えきの みぎがわに ぎんこうが あります。', 'Phía bên phải ga có ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3019, 28388, '駅の辺で待っています。', 'えきの へんで まって います。', 'Tôi đang đợi ở quanh ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3020, 44870, '日本の歴史に興味があります。', 'にほんの れきしに きょうみが あります。', 'Tôi quan tâm đến lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3021, 28389, '覚えていません。', 'おぼえていません。', 'Tôi không nhớ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3022, 28210, '兄は旅行会社で働いています。', 'あには りょこうがいしゃで はたらいて います。', 'Anh tôi làm việc ở công ty du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3023, 28392, '財布が見つかりました。ああ、よかった。', 'さいふが みつかりました。ああ、よかった。', 'Tìm thấy ví rồi. Ôi, may quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3024, 28393, '新宿でデパートに行きました。', 'しんじゅくで デパートに いきました。', 'Tôi đi trung tâm thương mại ở Shinjuku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3025, 28404, '道が込みます。', 'みちがこみます。', 'Đông(đường)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3026, 28405, '道がすきます。', 'みちがすきます。', 'Vắng, thoáng [đường ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3027, 28394, '昨夜、地震がありました。', 'ゆうべ、じしんが ありました。', 'Tối qua có động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3028, 38804, '空いている部屋を会議室として活用している。', 'あいて いる へやを かいぎしつと して かつよう して いる。', 'Chúng tôi tận dụng phòng trống làm phòng họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3029, 44873, '妹は絵が上手です。', 'いもうとは えが じょうず です。', 'Em gái tôi vẽ tranh giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3030, 28379, '結婚式でスピーチをしました。', 'けっこんしきで スピーチを しました。', 'Tôi đã phát biểu ở lễ cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3031, 44880, 'あした、サッカーの試合があります。', 'あした、サッカーの しあいが あります。', 'Ngày mai có trận đấu bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3032, 28395, '壁に絵が掛けてあります。', 'かべに えが かけて あります。', 'Trên tường có treo một bức tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3033, 44875, '寝る前に小説を読みます。', 'ねる まえに しょうせつを よみます。', 'Trước khi ngủ tôi đọc tiểu thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3034, 44877, 'この番組はとてもおもしろいです。', 'この ばんぐみは とても おもしろい です。', 'Chương trình này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3035, 28398, '駅前で友達と待ち合わせします。', 'えきまえで ともだちと まちあわせ します。', 'Tôi hẹn gặp bạn ở trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3036, 28399, '地震で棚が倒れました。', 'じしんで たなが たおれました。', 'Động đất làm đổ cái giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3037, 28401, '駅の方へ歩いていきました。', 'えきの ほうへ あるいて いきました。', 'Tôi đi bộ về phía ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3038, 28407, 'この辺にコンビニはありますか。', 'この へんに コンビニは ありますか。', 'Quanh đây có cửa hàng tiện lợi không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3039, 28408, '四ツ谷で電車を降りました。', 'よつやで でんしゃを おりました。', 'Tôi xuống tàu ở Yotsuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3040, 28409, '駅はあちらの方です。', 'えきは あちらの ほう です。', 'Ga ở hướng đằng kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3041, 28373, '地震で窓のガラスが割れました。', 'じしんで まどの ガラスが われました。', 'Động đất làm vỡ kính cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3042, 28403, 'テレビのレポーターが町の人に話を聞いています。', 'テレビの レポーターが まちの ひとに はなしを きいて います。', 'Phóng viên truyền hình đang phỏng vấn người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3043, 28412, '壁にカレンダーを掛けました。', 'かべに カレンダーを かけました。', 'Tôi treo lịch lên tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3044, 28414, 'テーブルにお皿を並べてください。', 'テーブルに おさらを ならべて ください。', 'Hãy xếp đĩa lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3045, 41842, '彼女の話し方には知性が感じられる。', 'かのじょの はなしかたには ちせいが かんじられる。', 'Cách nói chuyện của cô ấy toát lên trí tuệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3046, 41766, '批評家はその映画を駄作だと言った。', 'ひひょうかは その えいがを ださくだと いった。', 'Nhà phê bình nói bộ phim đó là tác phẩm dở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3047, 41883, '先生の著書を読んで感動した。', 'せんせいの ちょしょを よんで かんどう した。', 'Đọc sách của thầy viết, tôi rất cảm động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3048, 41903, '神社の鳥居をくぐる前に一礼する。', 'じんじゃの とりいを くぐる まえに いちれい する。', 'Trước khi đi qua cổng torii của đền thì cúi chào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3049, 28415, '庭に木を植えました。', 'にわに きを うえました。', 'Tôi trồng cây trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3050, 28417, '会議の内容をまとめてください。', 'かいぎの ないようを まとめて ください。', 'Hãy tóm tắt nội dung cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3051, 28418, '冬の服を押し入れにしまいました。', 'ふゆの ふくを おしいれに しまいました。', 'Tôi cất quần áo mùa đông vào tủ âm tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3052, 28420, '授業の前に予習しておきます。', 'じゅぎょうの まえに よしゅう して おきます。', 'Tôi chuẩn bị bài trước giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3053, 28426, '来週の予定はもう決まりましたか。', 'らいしゅうの よていは もう きまりましたか。', 'Kế hoạch tuần sau đã định chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3054, 28422, 'そのままにします。', 'そのままにします。', 'Để nguyên như thế', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3055, 28427, '会社からお知らせが届きました。', 'かいしゃから おしらせが とどきました。', 'Có thông báo từ công ty gửi đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3056, 38806, 'すみません、お勘定をお願いします。', 'すみません、おかんじょうを おねがい します。', 'Xin lỗi, cho tôi thanh toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3057, 28335, '実は、来月会社を辞めるんです。', 'じつは、らいげつ かいしゃを やめるんです。', 'Thật ra là tháng sau tôi sẽ nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3058, 28375, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3059, 45058, '毎日努力した結果、試験に合格できました。', 'まいにち どりょくした けっか、しけんに ごうかく できました。', 'Nhờ nỗ lực mỗi ngày mà tôi đã thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3060, 45112, '新しい商品が来月発売されます。', 'あたらしい しょうひんが らいげつ はつばい されます。', 'Sản phẩm mới sẽ được bán ra vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3061, 28431, '予定表に会議の時間を書きました。', 'よていひょうに かいぎの じかんを かきました。', 'Tôi ghi giờ họp vào lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3062, 45121, '給料から税金が引かれる。', 'きゅうりょうから ぜいきんが ひかれる。', 'Thuế bị trừ vào lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3063, 45122, 'アパートの契約は二年です。', 'アパートの けいやくは にねん です。', 'Hợp đồng thuê căn hộ là hai năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3064, 39947, '「静か」は形容動詞だ。', '「しずか」は けいようどうしだ。', '"Shizuka" là tính từ đuôi na.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3065, 39942, '空を鳥の群れが飛んでいる。', 'そらを とりの むれが とんで いる。', 'Một đàn chim đang bay trên trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3066, 39944, '地震で家が少し傾いた。', 'じしんで いえが すこし かたむいた。', 'Động đất làm ngôi nhà hơi nghiêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3067, 39951, '毎週土曜日に剣道の稽古をしている。', 'まいしゅう どようびに けんどうの けいこを して いる。', 'Thứ bảy hằng tuần tôi tập kiếm đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3068, 44899, '郵便局で切手を買います。', 'ゆうびんきょくで きってを かいます。', 'Tôi mua tem ở bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3069, 28437, '玄関で靴を脱いでください。', 'げんかんで くつを ぬいで ください。', 'Hãy cởi giày ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3070, 28432, 'ごみはごみ箱に捨ててください。', 'ごみは ごみばこに すてて ください。', 'Hãy bỏ rác vào thùng rác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3071, 28434, '花瓶に花が飾ってあります。', 'かびんに はなが かざって あります。', 'Trong lọ có cắm hoa trang trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3072, 28435, '出かける前に鏡を見ます。', 'でかける まえに かがみを みます。', 'Trước khi ra ngoài tôi soi gương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3073, 28436, 'はさみは机の引き出しに入っています。', 'はさみは つくえの ひきだしに はいって います。', 'Cái kéo ở trong ngăn kéo bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3074, 28438, '廊下を走らないでください。', 'ろうかを はしらないで ください。', 'Xin đừng chạy ngoài hành lang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3075, 44888, '四月に公園で花見をしました。', 'しがつに こうえんで はなみを しました。', 'Tháng tư tôi ngắm hoa anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3076, 44901, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3077, 28442, '家の周りに花を植えました。', 'いえの まわりに はなを うえました。', 'Tôi trồng hoa xung quanh nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3078, 28443, '部屋の真ん中にテーブルを置きました。', 'へやの まんなかに テーブルを おきました。', 'Tôi đặt cái bàn ở giữa phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3079, 28444, '部屋の隅にごみ箱があります。', 'へやの すみに ごみばこが あります。', 'Ở góc phòng có thùng rác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3080, 28452, 'このりんごは丸いです。', 'このりんごはまるいです。', 'Quả táo này tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3081, 28454, '夢を見ます。', 'ゆめをみます。', 'Giấc mơ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3082, 28455, 'このりんごはうれしいです。', 'このりんごはうれしいです。', 'Quả táo này vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3083, 28456, 'ここは嫌です。', 'ここはいやです。', 'Ở đây chán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3084, 28458, '目が覚めます。', 'めがさめます。', 'Tỉnh giấc', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3085, 44915, '去年と比べると、今年は雨が少ないです。', 'きょねんと くらべると、ことしは あめが すくないです。', 'So với năm ngoái thì năm nay ít mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3086, 45125, '調査の結果を部長に報告しました。', 'ちょうさの けっかを ぶちょうに ほうこく しました。', 'Tôi đã báo cáo kết quả khảo sát cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3087, 45128, 'この仕事は田中さんが担当しています。', 'この しごとは たなかさんが たんとう して います。', 'Công việc này do anh Tanaka phụ trách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3088, 44911, 'みんなで日本チームを応援した。', 'みんなで にほん チームを おうえん した。', 'Mọi người cùng cổ vũ đội tuyển Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3089, 28440, '公園の池に魚がいます。', 'こうえんの いけに さかなが います。', 'Trong ao ở công viên có cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3090, 44907, '夏は海で泳ぎます。', 'なつは うみで およぎます。', 'Mùa hè tôi bơi ở biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3091, 28448, '非常時にはこの階段を使ってください。', 'ひじょうじには この かいだんを つかって ください。', 'Lúc khẩn cấp hãy dùng cầu thang này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3092, 28449, '宇宙飛行士は宇宙ステーションで生活します。', 'うちゅう ひこうしは うちゅう ステーションで せいかつ します。', 'Phi hành gia sinh sống trên trạm vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3093, 28450, '非常袋に懐中電灯を入れておきました。', 'ひじょうぶくろに かいちゅう でんとうを いれて おきました。', 'Tôi để sẵn đèn pin trong túi đồ khẩn cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3094, 28453, 'ある日、駅で昔の友達に会いました。', 'ある ひ、えきで むかしの ともだちに あいました。', 'Một ngày nọ, tôi gặp người bạn cũ ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3095, 28457, 'ボタンを押しました。すると、ドアが開きました。', 'ボタンを おしました。すると、ドアが あきました。', 'Tôi bấm nút. Thế là cửa mở ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3096, 29372, 'あなたを信じています。', 'あなたを しんじて います。', 'Tôi tin bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3097, 44902, '日本の生活を楽しんでいます。', 'にほんの せいかつを たのしんで います。', 'Tôi đang tận hưởng cuộc sống ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3098, 44904, 'カラオケで歌いました。', 'カラオケで うたいました。', 'Tôi đã hát karaoke.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3099, 44905, 'ピアノを弾くのが好きです。', 'ピアノを ひくのが すき です。', 'Tôi thích chơi piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3100, 44909, '試合に勝ちました。', 'しあいに かちました。', 'Chúng tôi đã thắng trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3101, 44913, '結婚式に招待されました。', 'けっこんしきに しょうたい されました。', 'Tôi được mời dự đám cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3102, 44916, 'いい店を見つけました。', 'いい みせを みつけました。', 'Tôi tìm được một quán ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3103, 44918, '昨日のパーティーは楽しかったです。', 'きのうの パーティーは たのしかった です。', 'Bữa tiệc hôm qua rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3104, 44920, 'この映画はつまらないです。', 'この えいがは つまらない です。', 'Bộ phim này chán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3105, 44923, '素敵なプレゼントをありがとう。', 'すてきな プレゼントを ありがとう。', 'Cảm ơn món quà tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3106, 44924, '彼はとても熱心に勉強しています。', 'かれは とても ねっしんに べんきょう して います。', 'Anh ấy học rất chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3107, 28461, '困ったときは先生に相談します。', 'こまった ときは せんせいに そうだん します。', 'Khi gặp khó khăn tôi hỏi ý kiến thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3108, 28468, '何かご希望がありますか。', 'なにかごきぼうがありますか。', 'Anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3109, 28470, 'それはいいですね。', 'それはいいですね。', 'Ý kiến hay đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3110, 28462, 'お子さんは何人いますか。', 'おこさんは なんにん いますか。', 'Anh có mấy con?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3111, 28476, '休みを取ります。', 'やすみをとります。', 'Nghỉ [phép]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3112, 44927, '日本料理の中で、特にすしが好きです。', 'にほんりょうりの なかで、とくに すしが すきです。', 'Trong các món Nhật, tôi đặc biệt thích sushi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3113, 44928, 'ぜひ一度、うちへ来てください。', 'ぜひ いちど、うちへ きて ください。', 'Nhất định hãy đến nhà tôi chơi một lần nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3114, 44932, '地球は丸いです。', 'ちきゅうは まるい です。', 'Trái đất hình tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3115, 44934, '今夜は月がきれいですね。', 'こんやは つきが きれい ですね。', 'Đêm nay trăng đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3116, 28473, '地球は丸いです。', 'ちきゅうは まるい です。', 'Trái đất hình tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3117, 28464, '道がわからないので、交番で聞きました。', 'みちが わからないので、こうばんで ききました。', 'Không biết đường nên tôi hỏi ở đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3118, 28465, '駅まで歩いて十分ほどです。', 'えきまで あるいて じゅっぷん ほど です。', 'Đi bộ đến ga mất chừng mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3119, 28466, '遅くまでご苦労さま。', 'おそくまで ごくろうさま。', 'Cảm ơn anh đã vất vả đến khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3120, 28467, '旅行の希望を聞かせてください。', 'りょこうの きぼうを きかせて ください。', 'Hãy cho tôi biết nguyện vọng về chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3121, 44929, 'この町は自然が多くて、きれいです。', 'この まちは しぜんが おおくて、きれい です。', 'Thị trấn này có nhiều thiên nhiên, rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3709, 28676, '忘れ物に気が つきます。', 'わすれものにきが つきます。', 'Nhận thấy, phát hiện', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3122, 44935, '田舎では星がたくさん見えます。', 'いなかでは ほしが たくさん みえます。', 'Ở quê có thể nhìn thấy nhiều sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3123, 44945, '強い風で木の枝が折れました。', 'つよい かぜで きの えだが おれました。', 'Gió mạnh làm gãy cành cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3124, 28429, 'カレンダーに予定を書きます。', 'カレンダーに よていを かきます。', 'Tôi ghi lịch hẹn lên tờ lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3125, 28446, '山へ行くときはリュックを持っていきます。', 'やまへ いく ときは リュックを もって いきます。', 'Khi đi núi tôi mang theo ba lô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3126, 28469, 'ニューヨークでミュージカルを見ました。', 'ニューヨークで ミュージカルを みました。', 'Tôi đã xem nhạc kịch ở New York.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3127, 28475, 'いいアパートを見つけました。', 'いい アパートを みつけました。', 'Tôi đã tìm được một căn hộ tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3128, 44947, '朝、鳥の声が聞こえます。', 'あさ、とりの こえが きこえます。', 'Buổi sáng nghe thấy tiếng chim hót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3129, 44936, '船で島へ行きました。', 'ふねで しまへ いきました。', 'Tôi đi ra đảo bằng thuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3130, 44944, '秋になると、木の葉が赤くなります。', 'あきに なると、きの はが あかく なります。', 'Sang thu, lá cây chuyển đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3131, 44925, '私は料理が得意です。', 'わたしは りょうりが とくい です。', 'Tôi giỏi nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3132, 44930, '環境を守ることは大切です。', 'かんきょうを まもる ことは たいせつ です。', 'Bảo vệ môi trường là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3133, 44939, '湖でボートに乗りました。', 'みずうみで ボートに のりました。', 'Tôi đi thuyền trên hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3134, 44942, '子どもたちが砂で遊んでいます。', 'こどもたちが すなで あそんで います。', 'Bọn trẻ đang chơi cát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3135, 44943, '庭の草を取りました。', 'にわの くさを とりました。', 'Tôi nhổ cỏ trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3136, 28477, '試験を受けます。', 'しけんをうけます。', 'Dự [thi]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3137, 28485, '祖父のお葬式に行きました。', 'そふの おそうしきに いきました。', 'Tôi đã đi dự đám tang của ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3138, 28488, '来月から大阪の支店で働きます。', 'らいげつから おおさかの してんで はたらきます。', 'Từ tháng sau tôi làm ở chi nhánh Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3139, 28489, '日曜日に教会へ行きます。', 'にちようびに きょうかいへ いきます。', 'Chủ nhật tôi đi nhà thờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3140, 28492, '温泉から来ました。', 'おんせんからきました。', 'Tôi đến từ suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3141, 44951, '昨夜、地震がありました。', 'ゆうべ、じしんが ありました。', 'Tối qua có động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3142, 45131, '社長の命令なら、従うしかない。', 'しゃちょうの めいれいなら、したがう しか ない。', 'Nếu là lệnh của giám đốc thì chỉ còn cách tuân theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3143, 44949, '部屋に植物を置くと、気持ちが落ち着く。', 'へやに しょくぶつを おくと、きもちが おちつく。', 'Đặt cây xanh trong phòng giúp tâm trạng thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3144, 44961, '日本は天然資源が少ない国だ。', 'にほんは てんねん しげんが すくない くにだ。', 'Nhật Bản là nước ít tài nguyên thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3145, 44957, 'どの季節が一番好きですか。', 'どの きせつが いちばん すき ですか。', 'Bạn thích mùa nào nhất?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3146, 44948, 'どんな動物が好きですか。', 'どんな どうぶつが すき ですか。', 'Bạn thích con vật nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3147, 44960, '隣の部屋から音が聞こえます。', 'となりの へやから おとが きこえます。', 'Có tiếng động từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3148, 44959, '窓から光が入ります。', 'まどから ひかりが はいります。', 'Ánh sáng chiếu vào qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3149, 28491, '子どもを動物園に連れていきました。', 'こどもを どうぶつえんに つれて いきました。', 'Tôi đưa con đi sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3150, 28493, '帰りにスーパーで買い物をします。', 'かえりに スーパーで かいものを します。', 'Trên đường về tôi mua đồ ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3151, 28494, 'お子さんは何人いますか。', 'おこさんは なんにん いますか。', 'Anh có mấy con?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3152, 28496, '駅の方へ歩いていきました。', 'えきの ほうへ あるいて いきました。', 'Tôi đi bộ về phía ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3153, 28501, '新神戸で新幹線を降りました。', 'しんこうべで しんかんせんを おりました。', 'Tôi xuống tàu Shinkansen ở Shin-Kobe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3154, 28502, '仕事が終わらないので、会社に残ります。', 'しごとが おわらないので、かいしゃに のこります。', 'Việc chưa xong nên tôi ở lại công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3155, 44950, '台風で電車が止まりました。', 'たいふうで でんしゃが とまりました。', 'Tàu điện ngừng chạy vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3156, 44952, 'ゆうべ近所で火事がありました。', 'ゆうべ きんじょで かじが ありました。', 'Tối qua gần nhà xảy ra hỏa hoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3157, 44955, '部屋の温度を少し上げてください。', 'へやの おんどを すこし あげて ください。', 'Hãy tăng nhiệt độ phòng lên một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3158, 44962, '燃えるごみは火曜日に出してください。', 'もえる ごみは かようびに だして ください。', 'Rác cháy được hãy đổ vào thứ Ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3159, 41851, '彼女は恥じらいながら花束を受け取った。', 'かのじょは はじらいながら はなたばを うけとった。', 'Cô ấy e thẹn nhận bó hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3160, 41952, '美術館で古い仏像が展示されている。', 'びじゅつかんで ふるい ぶつぞうが てんじ されて いる。', 'Bảo tàng mỹ thuật đang trưng bày tượng Phật cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3161, 42144, '北斎の版画は海外でも人気がある。', 'ほくさいの はんがは かいがいでも にんきが ある。', 'Tranh khắc gỗ của Hokusai được ưa chuộng cả ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4335, 29395, '私は大学生です。', 'わたしはだいがくせいです。', 'Tôi là sinh viên đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3162, 42216, '桜の花びらが風に舞っている。', 'さくらの はなびらが かぜに まって いる。', 'Cánh hoa anh đào bay lượn trong gió.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3163, 42247, 'キャンプで焚火を囲んで話した。', 'キャンプで たきびを かこんで はなした。', 'Khi cắm trại chúng tôi ngồi quanh đống lửa trò chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3164, 28504, '月に二回、映画を見ます。', 'つきに にかい、えいがを みます。', 'Mỗi tháng tôi xem phim hai lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3165, 28505, '祖父母は小さな村に住んでいます。', 'そふぼは ちいさな むらに すんで います。', 'Ông bà tôi sống ở một ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3166, 28506, '来年の三月に大学を卒業します。', 'らいねんの さんがつに だいがくを そつぎょう します。', 'Tháng ba năm sau tôi tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3167, 28514, '式が始まります。', 'しきがはじまります。', '[buổi lễ] bắt đầu', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3168, 28515, '大学に入学します。', 'だいがくににゅうがくします。', 'Vào [đại học]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3169, 28516, '会議に出席します。', 'かいぎにしゅっせきします。', 'Dự [cuộc họp]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3170, 28518, '誰かですか。', 'だれかですか。', 'Ai đó vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3171, 28524, 'このりんごは美しいです。', 'このりんごはうつくしいです。', 'Quả táo này đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3172, 28527, '気がつきます。', 'きがつきます。', 'Để ý', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3173, 45141, '今年の目標は日本語能力試験に合格することです。', 'ことしの もくひょうは にほんごのうりょくしけんに ごうかくする ことです。', 'Mục tiêu năm nay là đỗ kỳ thi năng lực tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3174, 31179, '貧困に苦しむ子供たちを支援したい。', 'ひんこんに くるしむ こどもたちを しえん したい。', 'Tôi muốn giúp đỡ những đứa trẻ khổ vì nghèo đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3175, 44979, 'この川は深いですから、泳がないでください。', 'この かわは ふかい ですから、およがないで ください。', 'Sông này sâu, đừng bơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3176, 28510, '目を閉じて、音楽を聞きます。', 'めを とじて、おんがくを ききます。', 'Tôi nhắm mắt nghe nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3177, 28520, '普通の会社員です。', 'ふつうの かいしゃいん です。', 'Tôi là một nhân viên công ty bình thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3178, 28522, '世界中から観光客が来ます。', 'せかいじゅうから かんこうきゃくが きます。', 'Khách du lịch đến từ khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3179, 28525, 'この町は自然が多くて、きれいです。', 'この まちは しぜんが おおくて、きれい です。', 'Thị trấn này có nhiều thiên nhiên, rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3180, 28526, '旅行で自然のすばらしさを知りました。', 'りょこうで しぜんの すばらしさを しりました。', 'Qua chuyến đi tôi biết được vẻ tuyệt vời của thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3181, 28498, '新婚旅行でバリへ行きました。', 'しんこん りょこうで バリへ いきました。', 'Tôi đi Bali trong tuần trăng mật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3182, 29509, '銀行でお金を下ろしました。', 'ぎんこうで おかねを おろしました。', 'Tôi rút tiền ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3183, 31177, 'ビタミンの欠乏は病気の原因になる。', 'ビタミンの けつぼうは びょうきの げんいんに なる。', 'Thiếu hụt vitamin là nguyên nhân gây bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3184, 31182, '被災地の復興が急務だ。', 'ひさいちの ふっこうが きゅうむだ。', 'Tái thiết vùng thiên tai là việc cấp bách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3185, 31181, '医療現場は人手が逼迫している。', 'いりょう げんばは ひとでが ひっぱく して いる。', 'Cơ sở y tế đang thiếu người trầm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3186, 42254, '昔の人は恋しい人に文を送った。', 'むかしの ひとは こいしい ひとに ふみを おくった。', 'Người xưa gửi thư cho người mình thương nhớ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3187, 42438, '趣味で油絵を描いている。', 'しゅみで あぶらえを かいて いる。', 'Tôi vẽ tranh sơn dầu như một sở thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3188, 42471, 'この旅館は洋風の部屋もある。', 'この りょかんは ようふうの へやも ある。', 'Lữ quán này cũng có phòng kiểu Tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3189, 42585, '駅前に洒落たカフェができた。', 'えきまえに しゃれた カフェが できた。', 'Một quán cà phê sành điệu đã mở trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3190, 42593, '籤引で座席を決めた。', 'くじびきで ざせきを きめた。', 'Chúng tôi bốc thăm để chọn chỗ ngồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3191, 28529, '実験は成功しました。', 'じっけんは せいこう しました。', 'Thí nghiệm đã thành công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3192, 28534, '午後から曇るそうです。', 'ごごから くもる そう です。', 'Nghe nói từ chiều trời sẽ nhiều mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3193, 28553, '田舎では星がたくさん見えます。', 'いなかでは ほしが たくさん みえます。', 'Ở quê có thể nhìn thấy nhiều sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3194, 45346, '台所はいつも清潔にしておこう。', 'だいどころは いつも せいけつに して おこう。', 'Hãy luôn giữ bếp sạch sẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3195, 28530, '試験に失敗します。', 'しけんにしっぱいします。', 'Thất bại, trượt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3196, 28531, '試験に合格します。', 'しけんにごうかくします。', 'Đỗ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3197, 28532, '雨がやみます。', 'あめがやみます。', 'Tạnh,ngừng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3198, 28535, '熱が続づきます。', 'ねつがつづきます。', 'Tiếp tục, tiếp diễn', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3199, 28536, 'かぜをひきます。', 'かぜをひきます。', 'Bị [cảm]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3200, 28538, '道が込みます。', 'みちがこみます。', '[đường] đông, tắc', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3201, 28539, '道がすきます。', 'みちがすきます。', '[đường] vắng, thông', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3202, 28540, '試合に出ます。', 'しあいにでます。', 'Tham gia [trận đấu]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3203, 28541, 'パーティーに出ます。', 'パーティーにでます。', 'Dự [tiệc]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3204, 28544, 'このりんごはおかしいです。', 'このりんごはおかしいです。', 'Quả táo này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3205, 28545, 'このりんごはうるさいです。', 'このりんごはうるさいです。', 'Quả táo này ồn ào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3206, 31183, '試合に負けた友達を励ました。', 'しあいに まけた ともだちを はげました。', 'Tôi động viên người bạn vừa thua trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3207, 31214, '日本では礼儀を大切にする。', 'にほんでは れいぎを たいせつに する。', 'Ở Nhật, người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3208, 31184, '先生は学生に発言を促した。', 'せんせいは がくせいに はつげんを うながした。', 'Thầy giáo khuyến khích học sinh phát biểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3209, 31186, '毎日が充実している。', 'まいにちが じゅうじつ して いる。', 'Mỗi ngày đều trôi qua đầy ý nghĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3210, 31190, '自炊は外食より経済的だ。', 'じすいは がいしょくより けいざいてきだ。', 'Tự nấu ăn tiết kiệm hơn ăn ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3211, 31212, '古い慣習を見直す時期に来ている。', 'ふるい かんしゅうを みなおす じきに きて いる。', 'Đã đến lúc xem xét lại những tập quán cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3212, 43245, '私はこの歌手の大ファンだ。', 'わたしは この かしゅの だいファンだ。', 'Tôi là fan cuồng của ca sĩ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3213, 43246, 'カメラに向かってポーズを取った。', 'カメラに むかって ポーズを とった。', 'Tôi tạo dáng trước máy ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3214, 40390, '駅のインフォメーションで道を聞いた。', 'えきの インフォメーションで みちを きいた。', 'Tôi hỏi đường ở quầy thông tin của nhà ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3215, 40460, '暗いところではストロボを使って撮影する。', 'くらい ところでは ストロボを つかって さつえい する。', 'Ở chỗ tối thì dùng đèn flash để chụp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3216, 40508, '昔はテレックスで海外と連絡を取っていた。', 'むかしは テレックスで かいがいと れんらくを とって いた。', 'Ngày xưa người ta liên lạc với nước ngoài bằng telex.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3217, 40526, '写真のネガを保管している。', 'しゃしんの ネガを ほかん して いる。', 'Tôi vẫn cất giữ phim âm bản của ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3218, 40673, 'この映画は映像がとても美しい。', 'この えいがは えいぞうが とても うつくしい。', 'Bộ phim này có hình ảnh rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3219, 28560, '水道から来ました。', 'すいどうからきました。', 'Tôi đến từ máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3220, 28563, '今夜は月がきれいです。', 'こんやは つきが きれい です。', 'Đêm nay trăng đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3221, 28574, 'それはいけませんね。', 'それはいけませんね。', 'Thế thì thật không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3222, 28580, '宝くじが当たります。', 'たからくじがあたります。', 'Trúng(số)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3223, 28587, '風が吹きます。', 'かぜがふきます。', 'Thổi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3224, 28588, '病気が治ります。', 'びょうきがなおります。', 'Khỏi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3225, 28589, '故障が直ります。', 'こしょうがなおります。', 'Khỏi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3226, 28590, 'ここは心配です。', 'ここはしんぱいです。', 'Ở đây lo lắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3227, 44989, 'あなたの気持ちはよくわかります。', 'あなたの きもちは よく わかります。', 'Tôi rất hiểu cảm xúc của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3228, 45144, 'この仕事には英語の能力が必要です。', 'この しごとには えいごの のうりょくが ひつよう です。', 'Công việc này cần năng lực tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3229, 45168, 'ついに夢がかないました。', 'ついに ゆめが かないました。', 'Rốt cuộc ước mơ đã thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3230, 44991, '母の愛はどんなものより深い。', 'ははの あいは どんな ものより ふかい。', 'Tình yêu của mẹ sâu nặng hơn bất cứ điều gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3231, 28592, 'もしかしたら、彼は来ないかもしれない。', 'もしかしたら、かれは こないかも しれない。', 'Biết đâu anh ấy sẽ không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3232, 44993, '彼は私の友達です。', 'かれは わたしの ともだち です。', 'Anh ấy là bạn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3233, 28571, '皆さん、お元気ですか。', 'みなさん、おげんき ですか。', 'Mọi người có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3234, 28554, '今日は風が強いです。', 'きょうは かぜが つよい です。', 'Hôm nay gió mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3235, 28555, '太陽は東から出ます。', 'たいようは ひがしから でます。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3236, 28558, '北海道は日本の北にあります。', 'ほっかいどうは にほんの きたに あります。', 'Hokkaido nằm ở phía bắc Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3237, 28566, 'きのうは夜遅くまで勉強しました。', 'きのうは よる おそくまで べんきょう しました。', 'Hôm qua tôi học đến khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3238, 28567, 'こんなにおいしいケーキは初めてです。', 'こんなに おいしい ケーキは はじめて です。', 'Lần đầu tiên tôi ăn chiếc bánh ngon như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3239, 28572, '食べすぎて、胃が痛いです。', 'たべすぎて、いが いたい です。', 'Ăn nhiều quá nên tôi đau dạ dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3240, 28575, '雑誌の星占いを毎月読みます。', 'ざっしの ほしうらないを まいつき よみます。', 'Tháng nào tôi cũng đọc mục bói sao trên tạp chí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3241, 28576, '私は牡牛座です。', 'わたしは おうしざ です。', 'Tôi thuộc cung Kim Ngưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3242, 28578, '日本語がわからなくて困りました。', 'にほんごが わからなくて こまりました。', 'Không hiểu tiếng Nhật nên tôi gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3243, 28579, '宝くじが当たったら、家を買いたいです。', 'たからくじが あたったら、いえを かいたい です。', 'Nếu trúng xổ số tôi muốn mua nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3244, 28581, '健康のために、たばこをやめました。', 'けんこうの ために、たばこを やめました。', 'Vì sức khỏe, tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3245, 28582, 'この映画は恋愛の話です。', 'この えいがは れんあいの はなし です。', 'Bộ phim này là chuyện tình yêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3246, 28585, '道に大きい石が落ちています。', 'みちに おおきい いしが おちて います。', 'Trên đường có hòn đá to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4423, 29508, '私は調べです。', 'わたしはしらべです。', 'Tôi là cuộc điều tra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3247, 28586, '忘れ物をしたので、家に戻りました。', 'わすれものを したので、いえに もどりました。', 'Quên đồ nên tôi quay về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3248, 44990, '心をこめて手紙を書きました。', 'こころを こめて てがみを かきました。', 'Tôi viết thư bằng cả tấm lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3249, 28594, 'ゆっくりします。', 'ゆっくりします。', 'Nghỉ ngơi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3250, 28212, '田中様、お待ちしておりました。', 'たなかさま、おまち して おりました。', 'Ông Tanaka, chúng tôi đã chờ ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3251, 28550, 'インフルエンザで一週間休みました。', 'インフルエンザで いっしゅうかん やすみました。', 'Tôi nghỉ một tuần vì bị cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3252, 28561, '車のエンジンがかかりません。', 'くるまの エンジンが かかりません。', 'Động cơ xe không nổ máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3253, 28604, '車に注意します。', 'くるまにちゅういします。', 'Chú ý', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3254, 28562, '私たちのチームが勝ちました。', 'わたしたちの チームが かちました。', 'Đội chúng tôi đã thắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3255, 45007, '新しい計画は大成功でした。', 'あたらしい けいかくは だいせいこう でした。', 'Kế hoạch mới đã thành công rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3256, 45012, '悪いと思ったら、すぐに謝りなさい。', 'わるいと おもったら、すぐに あやまりなさい。', 'Nếu thấy mình sai thì xin lỗi ngay đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3257, 45184, '交差点で交通事故があった。', 'こうさてんで こうつうじこが あった。', 'Đã xảy ra tai nạn giao thông ở ngã tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3258, 45005, '弟とつまらないことで喧嘩した。', 'おとうとと つまらない ことで けんか した。', 'Tôi cãi nhau với em trai vì chuyện vớ vẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3259, 45010, '遠慮しないで、たくさん食べてください。', 'えんりょ しないで、たくさん たべて ください。', 'Đừng khách sáo, cứ ăn nhiều vào nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3260, 44994, '彼女は東京に住んでいます。', 'かのじょは とうきょうに すんで います。', 'Cô ấy sống ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3261, 28573, '仕事でストレスがたまっています。', 'しごとで ストレスが たまって います。', 'Tôi bị căng thẳng vì công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3262, 28593, 'オリンピックをテレビで見ました。', 'オリンピックを テレビで みました。', 'Tôi xem Olympic trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3263, 28597, '夜、外で騒がないでください。', 'よる、そとで さわがないで ください。', 'Ban đêm đừng làm ồn ở bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3264, 28599, 'ボールを投げてください。', 'ボールを なげて ください。', 'Hãy ném bóng đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3265, 28600, '約束を守ってください。', 'やくそくを まもって ください。', 'Hãy giữ lời hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3266, 44997, '大人の料金は千円です。', 'おとなの りょうきんは せんえん です。', 'Giá vé người lớn là một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3267, 44998, '親に心配をかけたくないです。', 'おやに しんぱいを かけたく ない です。', 'Tôi không muốn làm cha mẹ lo lắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3268, 45000, '後輩の面倒を見ています。', 'こうはいの めんどうを みて います。', 'Tôi đang kèm cặp đàn em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3269, 45002, 'お世話になった先生にお礼を言いました。', 'おせわに なった せんせいに おれいを いいました。', 'Tôi nói lời cảm ơn thầy đã giúp đỡ mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3270, 45008, '家族が元気で安心しました。', 'かぞくが げんきで あんしん しました。', 'Gia đình khỏe mạnh nên tôi yên tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3271, 45011, '自己紹介をしてください。', 'じこ しょうかいを して ください。', 'Hãy tự giới thiệu bản thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3272, 45014, '赤ちゃんが笑っています。', 'あかちゃんが わらって います。', 'Em bé đang cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3273, 45016, '母はプレゼントをとても喜びました。', 'ははは プレゼントを とても よろこびました。', 'Mẹ rất vui với món quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3274, 41865, 'パーティーのために着飾って出かけた。', 'パーティーの ために きかざって でかけた。', 'Tôi diện thật đẹp đi dự tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3275, 41863, '茶の湯の作法を習っている。', 'ちゃのゆの さほうを ならって いる。', 'Tôi đang học lễ nghi trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3276, 41141, '夏休みの宿題で工作を作った。', 'なつやすみの しゅくだいで こうさくを つくった。', 'Tôi làm đồ thủ công cho bài tập hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3277, 28606, '忘れ物をしたので、家に戻りました。', 'わすれものを したので、いえに もどりました。', 'Quên đồ nên tôi quay về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3278, 28605, '席を外します。', 'せきをはずします。', 'Rời, không có ở (chỗ ngồi)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3279, 28607, '電話があります。', 'でんわがあります。', 'Có [điện thoại]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3280, 28609, 'ここはだめです。', 'ここはだめです。', 'Ở đây không được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3281, 28608, '古い新聞をリサイクルします。', 'ふるい しんぶんを リサイクル します。', 'Tôi tái chế báo cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3282, 28138, '旅行の準備はもう終わりましたか。', 'りょこうの じゅんびは もう おわりましたか。', 'Bạn đã chuẩn bị xong cho chuyến du lịch chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3283, 28615, '申し込みの締め切りは明日です。', 'もうしこみの しめきりは あした です。', 'Hạn chót đăng ký là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3284, 45023, '朝晩は少し寒さを感じるようになりました。', 'あさばんは すこし さむさを かんじる ように なりました。', 'Sáng tối đã bắt đầu thấy hơi lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3285, 45195, '話し合いで問題を解決しましょう。', 'はなしあいで もんだいを かいけつ しましょう。', 'Hãy giải quyết vấn đề bằng cách bàn bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3286, 45034, '彼とは高校時代から親しくしている。', 'かれとは こうこう じだいから したしく して いる。', 'Tôi thân với anh ấy từ thời cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3287, 45041, '休みの日は自由に過ごしたい。', 'やすみの ひは じゆうに すごしたい。', 'Ngày nghỉ tôi muốn được tự do thoải mái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3288, 28612, 'この席は空いていますか。', 'この せきは あいて いますか。', 'Ghế này còn trống không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3289, 45032, 'この歌を聞くと、学生時代が懐かしくなる。', 'この うたを きくと、がくせい じだいが なつかしく なる。', 'Nghe bài hát này tôi lại nhớ thời sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3290, 28168, '大使館でビザをもらいました。', 'たいしかんで ビザを もらいました。', 'Tôi nhận visa ở đại sứ quán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3291, 28610, '私と兄は同じ大学です。', 'わたしと あには おなじ だいがく です。', 'Tôi và anh trai học cùng trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3292, 45019, '先生に褒められて、うれしかったです。', 'せんせいに ほめられて、うれしかった です。', 'Được thầy khen nên tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3293, 45021, '彼の話を信じています。', 'かれの はなしを しんじて います。', 'Tôi tin lời anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3294, 45024, '試験に合格できるように頑張ります。', 'しけんに ごうかく できる ように がんばります。', 'Tôi sẽ cố gắng để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3295, 45026, '彼女と別れました。', 'かのじょと わかれました。', 'Tôi đã chia tay bạn gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3296, 45028, '合格して、とても嬉しいです。', 'ごうかく して、とても うれしい です。', 'Thi đỗ nên tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3297, 45030, '一人で住んでいるので、寂しいです。', 'ひとりで すんで いるので、さびしい です。', 'Sống một mình nên tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3298, 45033, '夜一人で歩くのは怖いです。', 'よる ひとりで あるくのは こわい です。', 'Đi bộ một mình ban đêm thật đáng sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3299, 45037, '彼は真面目な学生です。', 'かれは まじめな がくせい です。', 'Cậu ấy là học sinh chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3300, 45040, '家族と一緒にいられて幸せです。', 'かぞくと いっしょに いられて しあわせ です。', 'Được ở bên gia đình, tôi thấy hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3301, 41868, '研究者はこの現象に着目した。', 'けんきゅうしゃは この げんしょうに ちゃくもく した。', 'Nhà nghiên cứu đã chú ý tới hiện tượng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3302, 42432, '夏は野外コンサートが多い。', 'なつは やがい コンサートが おおい。', 'Mùa hè có nhiều buổi hòa nhạc ngoài trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3303, 41826, '短波放送で海外のニュースを聞いた。', 'たんぱ ほうそうで かいがいの ニュースを きいた。', 'Tôi nghe tin quốc tế qua đài sóng ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3304, 45044, 'やっと宿題が終わりました。', 'やっと しゅくだいが おわりました。', 'Cuối cùng bài tập cũng xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3305, 28170, 'でもいくら。', 'でもいくら。', 'Cho dù, thế nào [~ đi nữa]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3306, 28171, '一杯飲みましょう。', 'いっぱいのみましょう。', 'Chúng ta cùng uống nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3307, 31729, '計画をもっと具体化してください。', 'けいかくを もっと ぐたいか して ください。', 'Hãy cụ thể hóa kế hoạch hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3308, 28179, 'このりんごは気分がいいです。', 'このりんごはきぶんがいいです。', 'Quả táo này cảm thấy tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3309, 28180, 'このりんごは気分が悪いです。', 'このりんごはきぶんがわるいです。', 'Quả táo này cảm thấy không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3310, 45050, 'お客様に失礼な態度をとってはいけません。', 'おきゃくさまに しつれいな たいどを とっては いけません。', 'Không được có thái độ thất lễ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3311, 41888, '店の入口に「休業」の張り紙があった。', 'みせの いりぐちに 「きゅうぎょう」の はりがみが あった。', 'Ở cửa hàng có dán giấy "Nghỉ bán".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3312, 41970, '電線にカラスが止まっている。', 'でんせんに カラスが とまって いる。', 'Con quạ đậu trên dây điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3313, 42302, '新聞は事故の詳細を報じた。', 'しんぶんは じこの しょうさいを ほうじた。', 'Báo chí đưa tin chi tiết về vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3314, 42378, 'このカフェでは無線ＬＡＮが使える。', 'この カフェでは むせん ランが つかえる。', 'Quán cà phê này dùng được mạng không dây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3315, 45051, '彼女は暗い表情で話した。', 'かのじょは くらい ひょうじょうで はなした。', 'Cô ấy kể chuyện với vẻ mặt u buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3316, 45069, 'わがままばかり言っていると、友達がいなくなるよ。', 'わがまま ばかり いって いると、ともだちが いなく なるよ。', 'Cứ ích kỷ đòi hỏi mãi thì sẽ mất hết bạn đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3317, 45053, '子供の個性を大切にしたい。', 'こどもの こせいを たいせつに したい。', 'Tôi muốn trân trọng cá tính của con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3318, 45055, '私の短所は気が短いところです。', 'わたしの たんしょは きが みじかい ところ です。', 'Khuyết điểm của tôi là nóng tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3319, 45057, '彼には音楽の才能がある。', 'かれには おんがくの さいのうが ある。', 'Cậu ấy có tài năng âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3320, 45061, 'うちの犬は大人しくて、ほとんど吠えない。', 'うちの いぬは おとなしくて、ほとんど ほえない。', 'Con chó nhà tôi hiền lắm, hầu như không sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3321, 45063, '自分だけ休むなんて、ずるいよ。', 'じぶん だけ やすむ なんて、ずるいよ。', 'Mỗi mình cậu được nghỉ, gian thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3322, 45066, '授業では積極的に質問しよう。', 'じゅぎょうでは せっきょくてきに しつもん しよう。', 'Trong giờ học hãy tích cực đặt câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3323, 45068, '彼は素直に自分の間違いを認めた。', 'かれは すなおに じぶんの まちがいを みとめた。', 'Anh ấy thật thà thừa nhận lỗi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3324, 45071, '大事なことは慎重に決めたほうがいい。', 'だいじな ことは しんちょうに きめた ほうが いい。', 'Chuyện quan trọng thì nên quyết định thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3325, 45073, 'どんなときも冷静に判断しよう。', 'どんな ときも れいせいに はんだん しよう。', 'Lúc nào cũng hãy bình tĩnh phán đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4505, 29617, 'コーヒーをいれます。', 'コーヒーをいれます。', 'Pha [cà phê]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3326, 45076, '年下のくせに生意気なことを言うな。', 'としした の くせに なまいきな ことを いうな。', 'Nhỏ tuổi hơn mà dám nói láo xược thế à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3327, 42082, '燃料の値段が上がって、運賃も高くなった。', 'ねんりょうの ねだんが あがって、うんちんも たかく なった。', 'Giá nhiên liệu tăng nên giá vé cũng đắt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3328, 45045, '日本語はなかなか上手になりません。', 'にほんごは なかなか じょうずに なりません。', 'Tiếng Nhật mãi không giỏi lên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3329, 45047, 'A：一緒に行きますか。B：もちろん行きます。', 'エー：いっしょに いきますか。ビー：もちろん いきます。', 'A: Cùng đi chứ? B: Tất nhiên rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3330, 28616, '学校の規則を守りましょう。', 'がっこうの きそくを まもりましょう。', 'Hãy tuân thủ nội quy trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3331, 28619, 'ここは立入禁止です。入ってはいけません。', 'ここは たちいり きんし です。はいっては いけません。', 'Đây là khu cấm vào. Không được vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3332, 28621, '入口はあちらです。', 'いりぐちは あちら です。', 'Lối vào ở đằng kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3333, 28622, '出口はどこですか。', 'でぐちは どこ ですか。', 'Lối ra ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3334, 28623, '非常口はこの廊下の奥にあります。', 'ひじょうぐちは この ろうかの おくに あります。', 'Cửa thoát hiểm ở cuối hành lang này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3335, 28625, '学生は二割引で入れます。', 'がくせいは にわりびきで はいれます。', 'Sinh viên được giảm giá 20% khi vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3336, 45096, '試合に負けて、みんながっかりしました。', 'しあいに まけて、みんな がっかり しました。', 'Thua trận nên ai cũng thất vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3337, 45120, '留学の費用はどのくらいかかりますか。', 'りゅうがくの ひようは どのくらい かかりますか。', 'Chi phí du học khoảng bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3338, 45082, '昨日の敵は今日の友。', 'きのうの てきは きょうの とも。', 'Kẻ thù hôm qua là bạn hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3339, 45111, '大きな企業で働きたい。', 'おおきな きぎょうで はたらきたい。', 'Tôi muốn làm việc ở doanh nghiệp lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3340, 45085, '私は父を一番尊敬しています。', 'わたしは ちちを いちばん そんけい して います。', 'Người tôi kính trọng nhất là bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3341, 45093, '給料が安いことに不満がある。', 'きゅうりょうが やすい ことに ふまんが ある。', 'Tôi bất mãn vì lương thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3342, 45117, '安い物を買って、かえって損をした。', 'やすい ものを かって、かえって そんを した。', 'Mua đồ rẻ hóa ra lại thiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3343, 45106, 'わざと負けたわけではない。', 'わざと まけた わけでは ない。', 'Không phải tôi cố tình thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3344, 45080, '仲間と一緒に新しい会社を作った。', 'なかまと いっしょに あたらしい かいしゃを つくった。', 'Tôi cùng các bạn lập công ty mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3345, 45083, 'この問題は私には関係がない。', 'この もんだいは わたしには かんけいが ない。', 'Vấn đề này không liên quan đến tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3346, 45088, '失敗の原因をよく反省した。', 'しっぱいの げんいんを よく はんせい した。', 'Tôi đã tự kiểm điểm kỹ nguyên nhân thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3347, 45091, '試合に勝って、みんな興奮していた。', 'しあいに かって、みんな こうふん して いた。', 'Thắng trận nên ai nấy đều phấn khích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3348, 45095, '発表の前は胸がどきどきする。', 'はっぴょうの まえは むねが どきどき する。', 'Trước khi thuyết trình tim tôi đập thình thịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3349, 45098, '深呼吸をしたら、気持ちが落ち着いた。', 'しんこきゅうを したら、きもちが おちついた。', 'Hít thở sâu xong thì tâm trạng bình tĩnh lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3350, 45101, '毎年海外旅行に行けるなんて、羨ましい。', 'まいとし かいがい りょこうに いける なんて、うらやましい。', 'Năm nào cũng được đi du lịch nước ngoài, thật đáng ghen tị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3351, 45103, '毎日料理をするのは面倒だ。', 'まいにち りょうりを するのは めんどうだ。', 'Ngày nào cũng nấu ăn thật phiền phức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3352, 45105, '彼女はお母さんによく似ている。', 'かのじょは おかあさんに よく にて いる。', 'Cô ấy rất giống mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3353, 45113, 'この工場ではいろいろな製品を作っている。', 'この こうじょうでは いろいろな せいひんを つくって いる。', 'Nhà máy này sản xuất nhiều loại sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3354, 45116, '今年は会社の利益が増えた。', 'ことしは かいしゃの りえきが ふえた。', 'Năm nay lợi nhuận công ty tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3355, 45119, '今月の売上は先月より多い。', 'こんげつの うりあげは せんげつより おおい。', 'Doanh thu tháng này cao hơn tháng trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3356, 28617, 'この川で泳ぐのは危険です。', 'この かわで およぐのは きけん です。', 'Bơi ở con sông này rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3357, 28246, '料理の道具を買いました。', 'りょうりの どうぐを かいました。', 'Tôi mua dụng cụ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3358, 28241, 'このマンションではペットを飼うことができません。', 'この マンションでは ペットを かう ことが できません。', 'Ở chung cư này không được nuôi thú cưng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3359, 31736, '問題が顕在化する前に対策を取るべきだ。', 'もんだいが けんざいか する まえに たいさくを とる べきだ。', 'Nên có biện pháp trước khi vấn đề lộ rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3360, 31798, '人生には栄枯盛衰がある。', 'じんせいには えいこ せいすいが ある。', 'Đời người có lúc thịnh lúc suy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3361, 28239, '教室を開きます。', 'きょうしつをひらきます。', 'Mở,tổ chức (lớp)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3362, 45129, '失敗の責任は私にあります。', 'しっぱいの せきにんは わたしに あります。', 'Trách nhiệm cho thất bại thuộc về tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3400, 45179, '誰にでも意見を言う権利がある。', 'だれにでも いけんを いう けんりが ある。', 'Ai cũng có quyền nêu ý kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3363, 45132, 'ここで写真を撮るには許可が必要です。', 'ここで しゃしんを とるには きょかが ひつよう です。', 'Muốn chụp ảnh ở đây cần phải xin phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3364, 45149, 'この件は私に任せてください。', 'この けんは わたしに まかせて ください。', 'Việc này cứ giao cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3365, 45160, '申し込みの締め切りは明日です。', 'もうしこみの しめきりは あした です。', 'Hạn chót đăng ký là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3366, 45169, '選挙は国民の大切な権利だ。', 'せんきょは こくみんの たいせつな けんりだ。', 'Bầu cử là quyền quan trọng của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3367, 45164, '有能な人が会社に入ってきた。', 'ゆうのうな ひとが かいしゃに はいって きた。', 'Một người tài giỏi đã vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3368, 45127, '出かける前に、ガスを確認した。', 'でかける まえに、ガスを かくにん した。', 'Trước khi ra ngoài tôi kiểm tra lại bếp ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3369, 45134, '父は来年退職する予定だ。', 'ちちは らいねん たいしょく する よていだ。', 'Bố tôi dự định nghỉ hưu vào năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3370, 45135, '兄は課長に昇進した。', 'あには かちょうに しょうしん した。', 'Anh tôi được thăng chức trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3371, 45138, '毎日電車で通勤しています。', 'まいにち でんしゃで つうきん して います。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3372, 45140, '顧客の満足を第一に考えている。', 'こきゃくの まんぞくを だいいちに かんがえて いる。', 'Chúng tôi đặt sự hài lòng của khách hàng lên hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3373, 45143, 'この薬はすぐに効果が出た。', 'この くすりは すぐに こうかが でた。', 'Thuốc này có hiệu quả ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3374, 45146, '仕事のために資格を取りたい。', 'しごとの ために しかくを とりたい。', 'Tôi muốn lấy chứng chỉ để phục vụ công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3375, 45150, '昼ご飯はパンで済ませた。', 'ひるごはんは パンで すませた。', 'Bữa trưa tôi ăn tạm bánh mì cho xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3376, 45151, '用事が済んだら、すぐ帰ります。', 'ようじが すんだら、すぐ かえります。', 'Xong việc là tôi về ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3377, 45153, '工事は予定どおり進んでいる。', 'こうじは よてい どおり すすんで いる。', 'Công trình đang tiến triển đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3378, 45156, 'この商売はあまり儲からない。', 'この しょうばいは あまり もうからない。', 'Việc buôn bán này không lãi mấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3379, 45158, '提出する前に、もう一度答えを見直した。', 'ていしゅつ する まえに、もう いちど こたえを みなおした。', 'Trước khi nộp tôi xem lại đáp án một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3380, 45161, 'この牛乳は期限が切れている。', 'この ぎゅうにゅうは きげんが きれて いる。', 'Hộp sữa này đã hết hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3381, 45165, 'この町の主な産業は観光だ。', 'この まちの おもな さんぎょうは かんこうだ。', 'Ngành chủ yếu của thị trấn này là du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3382, 45170, '市民の意見を聞く会が開かれた。', 'しみんの いけんを きく かいが ひらかれた。', 'Một buổi lấy ý kiến người dân đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3383, 28305, '外国で働いた経験があります。', 'がいこくで はたらいた けいけんが あります。', 'Tôi có kinh nghiệm làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3384, 28306, '兄は力が強いです。', 'あには ちからが つよい です。', 'Anh tôi rất khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3385, 28308, 'このケーキはおもしろい形をしています。', 'この ケーキは おもしろい かたちを して います。', 'Chiếc bánh này có hình dạng thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3386, 37836, '日本語の変遷について研究している。', 'にほんごの へんせんに ついて けんきゅう して いる。', 'Tôi đang nghiên cứu về sự biến thiên của tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3387, 31801, '彼は全盛期に引退した。', 'かれは ぜんせいきに いんたい した。', 'Anh ấy giải nghệ khi đang ở thời kỳ đỉnh cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3388, 31803, '三角形の底辺の長さを求めなさい。', 'さんかくけいの ていへんの ながさを もとめなさい。', 'Hãy tính độ dài cạnh đáy của tam giác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3389, 31805, '地震でビルが崩壊した。', 'じしんで ビルが ほうかい した。', 'Tòa nhà sụp đổ vì động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3390, 31809, '地震で壊れた城が再建された。', 'じしんで こわれた しろが さいけん された。', 'Tòa thành bị động đất phá hủy đã được xây lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3391, 37849, '彼が助かったのは奇跡だ。', 'かれが たすかったのは きせきだ。', 'Việc anh ấy sống sót là một phép màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3392, 37872, '先生の話はよく脱線する。', 'せんせいの はなしは よく だっせん する。', 'Thầy giáo hay nói lạc đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3393, 37877, '彼の説明にはいくつかの矛盾点がある。', 'かれの せつめいには いくつかの むじゅんてんが ある。', 'Lời giải thích của anh ta có vài điểm mâu thuẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3394, 37879, '書類に不備があって、受け付けてもらえなかった。', 'しょるいに ふびが あって、うけつけて もらえなかった。', 'Hồ sơ có thiếu sót nên không được tiếp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3395, 37889, '大地震の前兆ではないかと心配した。', 'だいじしんの ぜんちょう では ないかと しんぱい した。', 'Tôi lo không biết có phải điềm báo động đất lớn không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3396, 45177, '彼は市の議員に選ばれた。', 'かれは しの ぎいんに えらばれた。', 'Ông ấy được bầu làm nghị viên thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3397, 45178, '会社に新しい休暇の制度ができた。', 'かいしゃに あたらしい きゅうかの せいどが できた。', 'Công ty đã có chế độ nghỉ phép mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3398, 45171, '東京の人口は千四百万人ぐらいだ。', 'とうきょうの じんこうは せんよんひゃくまんにん ぐらいだ。', 'Dân số Tokyo khoảng mười bốn triệu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3399, 45174, '来月、市長の選挙がある。', 'らいげつ、しちょうの せんきょが ある。', 'Tháng sau có bầu cử thị trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3401, 45181, '世界の平和を願っています。', 'せかいの へいわを ねがって います。', 'Tôi mong thế giới hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3402, 45183, '昨夜、近所で事件があったらしい。', 'ゆうべ、きんじょで じけんが あった らしい。', 'Nghe nói tối qua gần nhà có xảy ra vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3403, 45187, '財布を落としたので、警察に届けた。', 'さいふを おとしたので、けいさつに とどけた。', 'Đánh rơi ví nên tôi đã báo cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3404, 45190, '大雨で住民は学校に避難した。', 'おおあめで じゅうみんは がっこうに ひなん した。', 'Do mưa lớn, người dân đã sơ tán đến trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3405, 45192, '試験の結果は来週わかる。', 'しけんの けっかは らいしゅう わかる。', 'Tuần sau sẽ biết kết quả thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3406, 45196, '暑さ対策に帽子をかぶっている。', 'あつさ たいさくに ぼうしを かぶって いる。', 'Tôi đội mũ để chống nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3407, 45198, '明日、授業でレポートを発表する。', 'あした、じゅぎょうで レポートを はっぴょう する。', 'Ngày mai tôi trình bày báo cáo trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3408, 28307, 'このラーメン屋はいつも人気で、行列ができている。', 'この ラーメンやは いつも にんきで、ぎょうれつが できて いる。', 'Quán ramen này lúc nào cũng đông khách, người xếp hàng dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3409, 28358, '木が折れます。', 'きがおれます。', 'Gãy(cây)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3410, 28359, '紙が破れます。', 'かみがやぶれます。', 'Rách(giấy)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3411, 28363, '車が止まります。', 'くるまがとまります。', 'Dừng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3412, 28220, '日本語のスピーチ大会に申し込みました。', 'にほんごの スピーチ たいかいに もうしこみました。', 'Tôi đã đăng ký cuộc thi hùng biện tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3413, 37891, 'この時代に民主主義の萌芽が見られる。', 'この じだいに みんしゅ しゅぎの ほうがが みられる。', 'Ở thời đại này đã thấy mầm mống của dân chủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3414, 37895, '究極の選択を迫られた。', 'きゅうきょくの せんたくを せまられた。', 'Tôi bị buộc phải đưa ra lựa chọn tột cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3415, 37899, '生活の基盤を固める。', 'せいかつの きばんを かためる。', 'Củng cố nền tảng cuộc sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3416, 38239, 'この仕事を足掛かりにして、独立したい。', 'この しごとを あしがかりに して、どくりつ したい。', 'Tôi muốn lấy công việc này làm bàn đạp để tự lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3417, 38240, '問題解決の糸口が見つかった。', 'もんだい かいけつの いとぐちが みつかった。', 'Đã tìm ra đầu mối để giải quyết vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3418, 38243, '不況の打開策を話し合った。', 'ふきょうの だかいさくを はなしあった。', 'Chúng tôi bàn biện pháp vượt qua suy thoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3419, 38277, '新興国の台頭が目立つ。', 'しんこうこくの たいとうが めだつ。', 'Sự trỗi dậy của các nước mới nổi rất rõ nét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3420, 38279, 'かつての大企業も凋落の一途をたどっている。', 'かつての だいきぎょうも ちょうらくの いっとを たどって いる。', 'Doanh nghiệp lớn ngày nào cũng đang trên đà suy tàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3421, 45228, '写真で見るより、実際に行ったほうがきれいでした。', 'しゃしんで みるより、じっさいに いった ほうが きれい でした。', 'Đến tận nơi còn đẹp hơn xem qua ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3422, 45209, '景気がよくなって、給料が上がった。', 'けいきが よく なって、きゅうりょうが あがった。', 'Kinh tế khởi sắc nên lương tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3423, 45230, '学問に終わりはない。', 'がくもんに おわりは ない。', 'Việc học không có điểm dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3424, 45205, '男女の差別をなくすべきだ。', 'だんじょの さべつを なくす べきだ。', 'Cần xóa bỏ phân biệt nam nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3425, 45200, 'インターネットで旅行の情報を集めた。', 'インターネットで りょこうの じょうほうを あつめた。', 'Tôi thu thập thông tin du lịch trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3426, 45202, '世論は新しい法律に反対している。', 'よろんは あたらしい ほうりつに はんたい して いる。', 'Dư luận phản đối luật mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3427, 45207, '祖父は年金で生活している。', 'そふは ねんきんで せいかつ して いる。', 'Ông tôi sống bằng lương hưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3428, 45210, '不景気で給料が下がった。', 'ふけいきで きゅうりょうが さがった。', 'Kinh tế suy thoái nên lương bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3429, 45213, '両親は私の留学に反対した。', 'りょうしんは わたしの りゅうがくに はんたい した。', 'Bố mẹ phản đối việc tôi đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3430, 45216, '夜中に地震が発生した。', 'よなかに じしんが はっせい した。', 'Nửa đêm đã xảy ra động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3431, 45217, '外国人観光客が増加している。', 'がいこくじん かんこうきゃくが ぞうか して いる。', 'Khách du lịch nước ngoài đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3432, 45221, '明日の朝、六時に起こしてください。', 'あしたの あさ、ろくじに おこして ください。', 'Sáng mai hãy đánh thức tôi lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3433, 45223, '犯人はすぐに捕まった。', 'はんにんは すぐに つかまった。', 'Thủ phạm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3434, 45225, '水不足が深刻な問題になっている。', 'みずぶそくが しんこくな もんだいに なって いる。', 'Thiếu nước đang trở thành vấn đề nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3435, 28226, '五月五日はこどもの日です。', 'ごがつ いつかは こどもの ひ です。', 'Ngày 5 tháng 5 là ngày Thiếu nhi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3436, 28627, 'トイレは今使用中です。', 'トイレは いま しようちゅう です。', 'Nhà vệ sinh đang có người dùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3437, 28628, 'アルバイト募集中と書いてあります。', 'アルバイト ぼしゅうちゅうと かいて あります。', 'Có ghi "đang tuyển người làm thêm".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3438, 41895, '両国の首脳が条約に調印した。', 'りょうこくの しゅのうが じょうやくに ちょういん した。', 'Lãnh đạo hai nước đã ký kết hiệp ước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3439, 41896, '調理師の資格を取った。', 'ちょうりしの しかくを とった。', 'Tôi đã lấy chứng chỉ đầu bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3440, 38282, '会社は存亡の危機に立たされている。', 'かいしゃは そんぼうの ききに たたされて いる。', 'Công ty đang đứng trước nguy cơ tồn vong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3441, 38296, '両国の間には多くの問題が介在している。', 'りょうこくの あいだには おおくの もんだいが かいざい して いる。', 'Giữa hai nước tồn tại nhiều vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3442, 38303, '技術はすぐに陳腐化する。', 'ぎじゅつは すぐに ちんぷか する。', 'Công nghệ nhanh chóng trở nên lỗi thời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3443, 40410, '商品をカテゴリーごとに分けた。', 'しょうひんを カテゴリーごとに わけた。', 'Tôi chia sản phẩm theo từng danh mục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3444, 40435, '青い空と白い雲のコントラストが美しい。', 'あおい そらと しろい くもの コントラストが うつくしい。', 'Sự tương phản giữa trời xanh và mây trắng thật đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3445, 45229, '子供の教育にはお金がかかる。', 'こどもの きょういくには おかねが かかる。', 'Việc giáo dục con cái tốn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3446, 45232, '一番好きな科目は数学です。', 'いちばん すきな かもくは すうがく です。', 'Môn học tôi thích nhất là toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3447, 45270, '電話はベルによって発明された。', 'でんわは ベルに よって はつめい された。', 'Điện thoại do Bell phát minh ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3448, 45272, 'まず基礎をしっかり勉強しよう。', 'まず きそを しっかり べんきょう しよう。', 'Trước hết hãy học chắc phần cơ bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3449, 45233, '数学のテストで百点を取った。', 'すうがくの テストで ひゃくてんを とった。', 'Tôi được một trăm điểm bài kiểm tra toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3450, 45235, 'この町には長い歴史がある。', 'この まちには ながい れきしが ある。', 'Thị trấn này có lịch sử lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3451, 45236, 'この辺りの地理に詳しいですか。', 'この あたりの ちりに くわしい ですか。', 'Bạn có rành đường sá quanh đây không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3452, 45237, '日本の文学に興味がある。', 'にほんの ぶんがくに きょうみが ある。', 'Tôi quan tâm đến văn học Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3453, 45238, '大学で哲学を専攻した。', 'だいがくで てつがくを せんこう した。', 'Tôi học chuyên ngành triết học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3454, 45241, '今日の講義はとてもわかりやすかった。', 'きょうの こうぎは とても わかりやすかった。', 'Bài giảng hôm nay rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3455, 45243, '卒業論文を書いている。', 'そつぎょう ろんぶんを かいて いる。', 'Tôi đang viết luận văn tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3456, 45245, '今学期は成績が上がった。', 'こんがっきは せいせきが あがった。', 'Học kỳ này thành tích của tôi tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3457, 45248, '一回目の試験は不合格だった。', 'いっかいめの しけんは ふごうかく だった。', 'Lần thi đầu tôi đã trượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3458, 45250, '来年の三月に大学を卒業します。', 'らいねんの さんがつに だいがくを そつぎょう します。', 'Tháng ba năm sau tôi tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3459, 45253, '奨学金をもらって大学に通っている。', 'しょうがくきんを もらって だいがくに かよって いる。', 'Tôi nhận học bổng để học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3460, 45257, 'この高校には生徒が千人いる。', 'この こうこうには せいとが せんにん いる。', 'Trường cấp ba này có một nghìn học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3461, 45271, 'あいさつは人間関係の基本だ。', 'あいさつは にんげん かんけいの きほんだ。', 'Chào hỏi là điều cơ bản trong quan hệ con người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3462, 28634, '駅まで歩いて十分ほどです。', 'えきまで あるいて じゅっぷん ほど です。', 'Đi bộ đến ga mất chừng mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3463, 28629, '部長は今会議中です。', 'ぶちょうは いま かいぎちゅう です。', 'Trưởng phòng hiện đang họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3464, 28630, 'これはどういう意味ですか。', 'これは どういう いみ ですか。', 'Cái này có nghĩa là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3465, 28633, 'あと五分で駅に着きます。', 'あと ごふんで えきに つきます。', 'Còn năm phút nữa là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3466, 31219, 'お年寄りを狙った詐欺が増えている。', 'おとしよりを ねらった さぎが ふえて いる。', 'Các vụ lừa đảo nhắm vào người già đang gia tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3467, 28631, 'でもいくら。', 'でもいくら。', 'However sách, even if sách', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3468, 45292, '旅行のために毎月貯金しています。', 'りょこうの ために まいつき ちょきん して います。', 'Tôi để dành tiền mỗi tháng cho chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3469, 45300, 'ネットで本を注文した。', 'ネットで ほんを ちゅうもん した。', 'Tôi đã đặt mua sách trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3470, 45303, '電池を新しいのと交換した。', 'でんちを あたらしいのと こうかん した。', 'Tôi đã thay pin mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3471, 45304, '壊れた時計を修理に出した。', 'こわれた とけいを しゅうりに だした。', 'Tôi đã mang chiếc đồng hồ hỏng đi sửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3472, 45316, '夫も育児に協力してくれる。', 'おっとも いくじに きょうりょく して くれる。', 'Chồng tôi cũng phụ giúp nuôi con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3473, 45308, '被災地に衣服や毛布を送った。', 'ひさいちに いふくや もうふを おくった。', 'Chúng tôi gửi quần áo và chăn cho vùng bị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3474, 45284, '彼女はクラスで一番優秀な学生だ。', 'かのじょは クラスで いちばん ゆうしゅうな がくせいだ。', 'Cô ấy là học sinh ưu tú nhất lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3475, 45277, '名前の書き方に間違いがあった。', 'なまえの かきかたに まちがいが あった。', 'Cách viết tên có chỗ bị sai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3476, 45278, '祖母から料理を教わった。', 'そぼから りょうりを おそわった。', 'Tôi được bà dạy nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3477, 45281, 'この問題を十分で解いてください。', 'この もんだいを じゅっぷんで といて ください。', 'Hãy giải bài này trong mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3478, 45282, 'お金を数えてから財布に入れた。', 'おかねを かぞえてから さいふに いれた。', 'Tôi đếm tiền rồi mới cho vào ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3479, 45286, '話はだいたいわかりました。', 'はなしは だいたい わかりました。', 'Câu chuyện thì tôi hiểu đại khái rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3480, 45289, '田舎の暮らしにもう慣れた。', 'いなかの くらしにも もう なれた。', 'Tôi đã quen với cuộc sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3481, 45294, 'この店は現金しか使えない。', 'この みせは げんきん しか つかえない。', 'Cửa hàng này chỉ nhận tiền mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3482, 45297, '来月から電車の運賃が値上げされる。', 'らいげつから でんしゃの うんちんが ねあげ される。', 'Từ tháng sau giá vé tàu sẽ tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3483, 45299, '注文した品物が届いた。', 'ちゅうもん した しなものが とどいた。', 'Món hàng tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3484, 45306, '家電の店で冷蔵庫を買った。', 'かでんの みせで れいぞうこを かった。', 'Tôi mua tủ lạnh ở cửa hàng điện máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3485, 45309, 'この店では外国の食品も買える。', 'この みせでは がいこくの しょくひんも かえる。', 'Ở cửa hàng này cũng mua được thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3486, 45313, '忙しくて、外食が多くなった。', 'いそがしくて、がいしょくが おおく なった。', 'Bận quá nên tôi ăn ngoài nhiều hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3487, 45315, '夫婦で家事を分担している。', 'ふうふで かじを ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3488, 45318, '工事の騒音で眠れない。', 'こうじの そうおんで ねむれない。', 'Tiếng ồn công trình khiến tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3489, 45321, 'エアコンを使いすぎて、電気代が高くなった。', 'エアコンを つかいすぎて、でんきだいが たかく なった。', 'Dùng điều hòa nhiều quá nên tiền điện tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3490, 28479, '少し休憩しましょう。', 'すこし きゅうけい しましょう。', 'Nghỉ giải lao một chút nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3491, 28484, '友達の結婚式に出ました。', 'ともだちの けっこんしきに でました。', 'Tôi đã dự đám cưới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3492, 28486, '式は十時から始まります。', 'しきは じゅうじから はじまります。', 'Buổi lễ bắt đầu từ mười giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3493, 28487, '本社は東京にあります。', 'ほんしゃは とうきょうに あります。', 'Trụ sở chính ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3494, 28508, 'ここは嫌です。', 'ここはいやです。', 'Ở đây hateful.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3495, 31222, 'お正月には一族が集まる。', 'おしょうがつには いちぞくが あつまる。', 'Dịp Tết cả họ tụ họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3496, 28542, '無理をします。', 'むりをします。', 'Làm quá sức', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3497, 28543, 'ここは十分です。', 'ここはじゅうぶんです。', 'Ở đây đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3498, 40552, 'このスープは鶏がらがベースになっている。', 'この スープは とりがらが ベースに なって いる。', 'Món súp này có nền là nước hầm xương gà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3499, 40646, 'その事件は新聞の一面に載った。', 'その じけんは しんぶんの いちめんに のった。', 'Vụ việc đó lên trang nhất báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3500, 40735, '宇宙の果てはどうなっているのだろう。', 'うちゅうの はては どう なって いるの だろう。', 'Tận cùng vũ trụ ra sao nhỉ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3501, 40752, '誰でも過ちを犯すことはある。', 'だれでも あやまちを おかす ことは ある。', 'Ai cũng có lúc phạm sai lầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3502, 40894, 'この道は東京を起点にしている。', 'この みちは とうきょうを きてんに して いる。', 'Con đường này lấy Tokyo làm điểm xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3503, 40898, '職人の技に感心した。', 'しょくにんの わざに かんしん した。', 'Tôi thán phục kỹ thuật của người thợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3504, 40924, '被害者が少なかったのがせめてもの救いだ。', 'ひがいしゃが すくなかったのが せめても の すくいだ。', 'Điều an ủi duy nhất là ít người bị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3505, 40947, '彼は恵まれない境遇で育った。', 'かれは めぐまれない きょうぐうで そだった。', 'Anh ấy lớn lên trong hoàn cảnh thiệt thòi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3506, 45350, '事故のせいで、道が渋滞している。', 'じこの せいで、みちが じゅうたい して いる。', 'Vì tai nạn mà đường đang tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3507, 45322, '冬は光熱費が高くなる。', 'ふゆは こうねつひが たかく なる。', 'Mùa đông tiền điện nước ga tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3508, 45325, '日本語のスピーチ大会に申し込んだ。', 'にほんごの スピーチ たいかいに もうしこんだ。', 'Tôi đã đăng ký cuộc thi hùng biện tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3509, 45328, '役所で住民票をもらった。', 'やくしょで じゅうみんひょうを もらった。', 'Tôi lấy giấy chứng nhận cư trú ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3510, 45330, 'ホテルのフロントに荷物を預けた。', 'ホテルの フロントに にもつを あずけた。', 'Tôi gửi hành lý ở quầy lễ tân khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3511, 45332, 'ATMでお金を引き出した。', 'エーティーエムで おかねを ひきだした。', 'Tôi rút tiền ở cây ATM.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3512, 45335, '一万円あれば足りると思う。', 'いちまんえん あれば たりると おもう。', 'Tôi nghĩ có mười nghìn yên là đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3513, 45337, '計算が間違っていたので、もう一度やり直した。', 'けいさんが まちがって いたので、もう いちど やりなおした。', 'Tính sai nên tôi làm lại lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3514, 45339, 'お弁当におかずを詰めた。', 'おべんとうに おかずを つめた。', 'Tôi xếp thức ăn vào hộp cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3515, 45341, '昼過ぎの電車は空いている。', 'ひるすぎの でんしゃは すいて いる。', 'Tàu buổi chiều thì vắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3516, 45351, '雪の日は運転に気をつけてください。', 'ゆきの ひは うんてんに きを つけて ください。', 'Ngày tuyết rơi hãy cẩn thận khi lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3517, 28481, '家族について作文を書きました。', 'かぞくに ついて さくぶんを かきました。', 'Tôi viết bài văn về gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3518, 28548, 'サッカーをして、足にけがをしました。', 'サッカーを して、あしに けがを しました。', 'Đá bóng nên tôi bị thương ở chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3519, 28549, 'かぜで、せきが止まりません。', 'かぜで、せきが とまりません。', 'Bị cảm nên tôi ho mãi không dứt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3520, 41069, '景気の見通しは明るい。', 'けいきの みとおしは あかるい。', 'Triển vọng kinh tế rất sáng sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3521, 40972, '自然の驚異に言葉を失った。', 'しぜんの きょういに ことばを うしなった。', 'Tôi lặng người trước kỳ quan của thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3522, 41016, '後半に入って形勢が逆転した。', 'こうはんに はいって けいせいが ぎゃくてん した。', 'Sang hiệp hai, cục diện đã đảo ngược.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3523, 41018, '自然の恵みに感謝する。', 'しぜんの めぐみに かんしゃ する。', 'Biết ơn những ân huệ của thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3524, 41025, '線路の継ぎ目で電車が揺れる。', 'せんろの つぎめで でんしゃが ゆれる。', 'Tàu rung lắc ở mối nối đường ray.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3525, 45369, '今年の夏は国内を旅行するつもりだ。', 'ことしの なつは こくないを りょこう する つもりだ。', 'Hè này tôi định du lịch trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3526, 45376, '駅はどちらの方向ですか。', 'えきは どちらの ほうこう ですか。', 'Ga ở hướng nào vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3527, 45379, 'アフリカ大陸を旅してみたい。', 'アフリカ たいりくを たびして みたい。', 'Tôi muốn thử du lịch châu Phi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3528, 45389, '霧で前がよく見えない。', 'きりで まえが よく みえない。', 'Sương mù dày nên không nhìn rõ phía trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3529, 45354, 'バスの運賃は降りるときに払います。', 'バスの うんちんは おりる ときに はらいます。', 'Tiền vé xe buýt trả khi xuống xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3530, 45356, '大阪まで片道一万四千円かかる。', 'おおさかまで かたみち いちまん よんせんえん かかる。', 'Vé một chiều đến Osaka mất mười bốn nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3531, 45359, '飛行機は予定通りに到着した。', 'ひこうきは よていどおりに とうちゃく した。', 'Máy bay đã đến đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3532, 45361, 'バスの行き先を確認してから乗ってください。', 'バスの いきさきを かくにん してから のって ください。', 'Hãy kiểm tra điểm đến của xe buýt rồi mới lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3533, 45363, '京都の名所を案内してもらった。', 'きょうとの めいしょを あんない して もらった。', 'Tôi được dẫn đi thăm các danh thắng ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3534, 45367, '重い荷物を持ってあげましょうか。', 'おもい にもつを もって あげましょうか。', 'Để tôi xách giúp hành lý nặng nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3535, 45370, 'いつか海外で働いてみたい。', 'いつか かいがいで はたらいて みたい。', 'Một ngày nào đó tôi muốn thử làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3536, 45373, '夏休みは田舎の祖父母の家で過ごした。', 'なつやすみは いなかの そふぼの いえで すごした。', 'Kỳ nghỉ hè tôi ở nhà ông bà dưới quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3537, 45377, '家から駅までの距離は一キロぐらいだ。', 'いえから えきまでの きょりは いちキロ ぐらいだ。', 'Khoảng cách từ nhà đến ga chừng một cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3538, 45380, '伊豆半島は温泉で有名だ。', 'いず はんとうは おんせんで ゆうめいだ。', 'Bán đảo Izu nổi tiếng với suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3539, 45382, '今日は波が高いので、泳がないでください。', 'きょうは なみが たかいので、およがないで ください。', 'Hôm nay sóng lớn, xin đừng bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3540, 45387, '大雨で洪水が起きた。', 'おおあめで こうずいが おきた。', 'Mưa lớn đã gây ra lũ lụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3541, 45391, '今日は湿度が高くて、蒸し暑い。', 'きょうは しつどが たかくて、むしあつい。', 'Hôm nay độ ẩm cao nên oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3542, 45393, '地球の温暖化が進んでいる。', 'ちきゅうの おんだんかが すすんで いる。', 'Trái đất đang ngày càng nóng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3543, 45395, '今、駅に向かっています。', 'いま、えきに むかって います。', 'Tôi đang trên đường đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3544, 41066, '工事は来月終わる見込みだ。', 'こうじは らいげつ おわる みこみだ。', 'Công trình dự kiến xong vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3545, 28598, '夢をあきらめないでください。', 'ゆめを あきらめないで ください。', 'Đừng từ bỏ ước mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3546, 28639, '困ったときは助け合いましょう。', 'こまった ときは たすけあいましょう。', 'Khi khó khăn hãy giúp đỡ lẫn nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3547, 41082, '原文と訳文を比べる。', 'げんぶんと やくぶんを くらべる。', 'So sánh bản gốc với bản dịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3548, 45288, '寒さがますます厳しくなってきた。', 'さむさが ますます きびしく なって きた。', 'Cái lạnh ngày càng khắc nghiệt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3549, 45411, '彼女は暗い表情で話した。', 'かのじょは くらい ひょうじょうで はなした。', 'Cô ấy kể chuyện với vẻ mặt u buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3550, 45442, '昨日の敵は今日の友。', 'きのうの てきは きょうの とも。', 'Kẻ thù hôm qua là bạn hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3551, 45429, 'わがままばかり言っていると、友達がいなくなるよ。', 'わがまま ばかり いって いると、ともだちが いなく なるよ。', 'Cứ ích kỷ đòi hỏi mãi thì sẽ mất hết bạn đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3552, 45397, 'どちらの服を買うか迷っている。', 'どちらの ふくを かうか まよって いる。', 'Tôi đang phân vân không biết mua bộ nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3553, 45399, '帰りにスーパーに寄った。', 'かえりに スーパーに よった。', 'Trên đường về tôi ghé siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3554, 45401, '道が凍っているので、滑らないように気をつけて。', 'みちが こおって いるので、すべらない ように きを つけて。', 'Đường đóng băng, cẩn thận kẻo trượt ngã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3555, 45403, '夕日が山の向こうに沈んだ。', 'ゆうひが やまの むこうに しずんだ。', 'Mặt trời chiều đã lặn sau núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3556, 45405, '頂上までの道はとても険しかった。', 'ちょうじょうまでの みちは とても けわしかった。', 'Đường lên đỉnh núi rất hiểm trở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3557, 45412, '日本の第一印象はどうでしたか。', 'にほんの だいいち いんしょうは どう でしたか。', 'Ấn tượng đầu tiên của bạn về Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3558, 45415, '私の短所は気が短いところです。', 'わたしの たんしょは きが みじかい ところ です。', 'Khuyết điểm của tôi là nóng tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3559, 45417, '彼には音楽の才能がある。', 'かれには おんがくの さいのうが ある。', 'Cậu ấy có tài năng âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3560, 45421, 'うちの犬は大人しくて、ほとんど吠えない。', 'うちの いぬは おとなしくて、ほとんど ほえない。', 'Con chó nhà tôi hiền lắm, hầu như không sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3561, 45423, '自分だけ休むなんて、ずるいよ。', 'じぶん だけ やすむ なんて、ずるいよ。', 'Mỗi mình cậu được nghỉ, gian thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3562, 45426, '授業では積極的に質問しよう。', 'じゅぎょうでは せっきょくてきに しつもん しよう。', 'Trong giờ học hãy tích cực đặt câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3563, 45428, '彼は素直に自分の間違いを認めた。', 'かれは すなおに じぶんの まちがいを みとめた。', 'Anh ấy thật thà thừa nhận lỗi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3564, 45431, '大事なことは慎重に決めたほうがいい。', 'だいじな ことは しんちょうに きめた ほうが いい。', 'Chuyện quan trọng thì nên quyết định thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3565, 45433, 'どんなときも冷静に判断しよう。', 'どんな ときも れいせいに はんだん しよう。', 'Lúc nào cũng hãy bình tĩnh phán đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3566, 45436, '年下のくせに生意気なことを言うな。', 'としした の くせに なまいきな ことを いうな。', 'Nhỏ tuổi hơn mà dám nói láo xược thế à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3567, 45438, '彼は年下だが、とてもしっかりしている。', 'かれは としした だが、とても しっかり して いる。', 'Cậu ấy nhỏ tuổi hơn nhưng rất chững chạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3568, 45443, 'この問題は私には関係がない。', 'この もんだいは わたしには かんけいが ない。', 'Vấn đề này không liên quan đến tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3569, 28636, 'スピード違反で罰金を取られた。', 'スピード いはんで ばっきんを とられた。', 'Tôi bị phạt tiền vì chạy quá tốc độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3570, 28638, 'ここに荷物を置いてもいいですか。', 'ここに にもつを おいても いい ですか。', 'Tôi để hành lý ở đây được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3571, 28641, 'このりんごは悲しいです。', 'このりんごはかなしいです。', 'Quả táo này buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3572, 28640, 'この建物はもともと学校でした。', 'この たてものは もともと がっこう でした。', 'Tòa nhà này vốn là trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3573, 28643, '朝、近所の人にあいさつします。', 'あさ、きんじょの ひとに あいさつ します。', 'Buổi sáng tôi chào hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3574, 28644, '話す相手がいなくて、寂しいです。', 'はなす あいてが いなくて、さびしい です。', 'Không có ai để nói chuyện nên tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3575, 28673, '歯を磨きます。', 'はをみがきます。', 'Mài, đánh (răng)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3576, 28646, '質問がある人は手を上げてください。', 'しつもんが ある ひとは てを あげて ください。', 'Ai có câu hỏi thì giơ tay lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3577, 41915, '警察は逃げた車を追跡した。', 'けいさつは にげた くるまを ついせき した。', 'Cảnh sát truy đuổi chiếc xe bỏ trốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3578, 45472, '新しい商品が来月発売されます。', 'あたらしい しょうひんが らいげつ はつばい されます。', 'Sản phẩm mới sẽ được bán ra vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3579, 45481, '給料から税金が引かれる。', 'きゅうりょうから ぜいきんが ひかれる。', 'Thuế bị trừ vào lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3580, 28645, 'あなたの気持ちはよくわかります。', 'あなたの きもちは よく わかります。', 'Tôi rất hiểu cảm xúc của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3581, 45446, '手伝ってくれたみんなに感謝しています。', 'てつだって くれた みんなに かんしゃ して います。', 'Tôi biết ơn mọi người đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3582, 45445, '私は父を一番尊敬しています。', 'わたしは ちちを いちばん そんけい して います。', 'Người tôi kính trọng nhất là bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3583, 45453, '給料が安いことに不満がある。', 'きゅうりょうが やすい ことに ふまんが ある。', 'Tôi bất mãn vì lương thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3584, 45477, '安い物を買って、かえって損をした。', 'やすい ものを かって、かえって そんを した。', 'Mua đồ rẻ hóa ra lại thiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3585, 45454, '電車が遅れて、いらいらした。', 'でんしゃが おくれて、いらいら した。', 'Tàu bị trễ làm tôi bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3586, 45466, 'わざと負けたわけではない。', 'わざと まけた わけでは ない。', 'Không phải tôi cố tình thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3587, 45448, '失敗の原因をよく反省した。', 'しっぱいの げんいんを よく はんせい した。', 'Tôi đã tự kiểm điểm kỹ nguyên nhân thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3588, 45451, '試合に勝って、みんな興奮していた。', 'しあいに かって、みんな こうふん して いた。', 'Thắng trận nên ai nấy đều phấn khích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3589, 45455, '発表の前は胸がどきどきする。', 'はっぴょうの まえは むねが どきどき する。', 'Trước khi thuyết trình tim tôi đập thình thịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3590, 45459, '子供のころから、パイロットに憧れていた。', 'こどもの ころから、パイロットに あこがれて いた。', 'Từ nhỏ tôi đã ngưỡng mộ nghề phi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3591, 45462, '一点差で負けて、とても悔しい。', 'いってんさで まけて、とても くやしい。', 'Thua chỉ một điểm, thật cay cú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3592, 45463, '毎日料理をするのは面倒だ。', 'まいにち りょうりを するのは めんどうだ。', 'Ngày nào cũng nấu ăn thật phiền phức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3593, 45465, '彼女はお母さんによく似ている。', 'かのじょは おかあさんに よく にて いる。', 'Cô ấy rất giống mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3594, 45470, '職場の人たちはみんな親切だ。', 'しょくばの ひとたちは みんな しんせつだ。', 'Mọi người ở chỗ làm đều tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3595, 45476, '今年は会社の利益が増えた。', 'ことしは かいしゃの りえきが ふえた。', 'Năm nay lợi nhuận công ty tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3596, 45478, '早く予約すると得だ。', 'はやく よやく すると とくだ。', 'Đặt sớm thì có lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3597, 45486, '会議で新しい企画を提案した。', 'かいぎで あたらしい きかくを ていあん した。', 'Tôi đề xuất một kế hoạch mới trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3598, 28647, 'エアコンの温度を下げてください。', 'エアコンの おんどを さげて ください。', 'Hãy hạ nhiệt độ điều hòa xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3599, 41124, '兄と交互に車を運転した。', 'あにと こうごに くるまを うんてん した。', 'Tôi và anh trai thay phiên nhau lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3600, 45492, 'ここで写真を撮るには許可が必要です。', 'ここで しゃしんを とるには きょかが ひつよう です。', 'Muốn chụp ảnh ở đây cần phải xin phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3601, 45504, 'この仕事には英語の能力が必要です。', 'この しごとには えいごの のうりょくが ひつよう です。', 'Công việc này cần năng lực tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3602, 45520, '申し込みの締め切りは明日です。', 'もうしこみの しめきりは あした です。', 'Hạn chót đăng ký là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3603, 45537, '彼は市の議員に選ばれた。', 'かれは しの ぎいんに えらばれた。', 'Ông ấy được bầu làm nghị viên thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3604, 45535, '政府は新しい経済政策を発表した。', 'せいふは あたらしい けいざい せいさくを はっぴょう した。', 'Chính phủ đã công bố chính sách kinh tế mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3605, 45524, '有能な人が会社に入ってきた。', 'ゆうのうな ひとが かいしゃに はいって きた。', 'Một người tài giỏi đã vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3606, 45493, '面接を受けた会社に採用された。', 'めんせつを うけた かいしゃに さいよう された。', 'Tôi đã được công ty mình phỏng vấn tuyển dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3607, 45495, '兄は課長に昇進した。', 'あには かちょうに しょうしん した。', 'Anh tôi được thăng chức trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3608, 45497, '姉は銀行に勤務している。', 'あねは ぎんこうに きんむ して いる。', 'Chị tôi làm việc ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3609, 45500, '顧客の満足を第一に考えている。', 'こきゃくの まんぞくを だいいちに かんがえて いる。', 'Chúng tôi đặt sự hài lòng của khách hàng lên hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3610, 45503, 'この薬はすぐに効果が出た。', 'この くすりは すぐに こうかが でた。', 'Thuốc này có hiệu quả ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3611, 45506, '仕事のために資格を取りたい。', 'しごとの ために しかくを とりたい。', 'Tôi muốn lấy chứng chỉ để phục vụ công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3612, 45508, '難しい仕事を引き受けてしまった。', 'むずかしい しごとを ひきうけて しまった。', 'Tôi lỡ nhận một công việc khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3613, 45511, '用事が済んだら、すぐ帰ります。', 'ようじが すんだら、すぐ かえります。', 'Xong việc là tôi về ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3614, 45513, '工事は予定どおり進んでいる。', 'こうじは よてい どおり すすんで いる。', 'Công trình đang tiến triển đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3615, 45516, 'この商売はあまり儲からない。', 'この しょうばいは あまり もうからない。', 'Việc buôn bán này không lãi mấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3616, 45518, '提出する前に、もう一度答えを見直した。', 'ていしゅつ する まえに、もう いちど こたえを みなおした。', 'Trước khi nộp tôi xem lại đáp án một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3617, 45521, 'この牛乳は期限が切れている。', 'この ぎゅうにゅうは きげんが きれて いる。', 'Hộp sữa này đã hết hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3618, 45525, 'この町の主な産業は観光だ。', 'この まちの おもな さんぎょうは かんこうだ。', 'Ngành chủ yếu của thị trấn này là du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3619, 45530, '市民の意見を聞く会が開かれた。', 'しみんの いけんを きく かいが ひらかれた。', 'Một buổi lấy ý kiến người dân đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3620, 45532, '少子化で学校の数が減っている。', 'しょうしかで がっこうの かずが へって いる。', 'Do tỷ lệ sinh giảm, số trường học đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3621, 45536, '首相が新しい政策を発表した。', 'しゅしょうが あたらしい せいさくを はっぴょう した。', 'Thủ tướng đã công bố chính sách mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3622, 45540, '税金を払うのは国民の義務だ。', 'ぜいきんを はらうのは こくみんの ぎむだ。', 'Nộp thuế là nghĩa vụ của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3623, 45542, '二度と戦争を起こしてはいけない。', 'にどと せんそうを おこしては いけない。', 'Không bao giờ được để chiến tranh xảy ra lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3624, 28652, 'あの店は今営業中です。', 'あの みせは いま えいぎょうちゅう です。', 'Cửa hàng kia đang mở cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3625, 28653, 'そりゃあ大変でしたね。', 'そりゃあ たいへん でしたね。', 'Ồ, thế thì vất vả quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3626, 28654, '一時間以内に戻ってください。', 'いちじかん いないに もどって ください。', 'Hãy quay lại trong vòng một tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3627, 28655, '友達の結婚式に電報を送りました。', 'ともだちの けっこんしきに でんぽうを おくりました。', 'Tôi gửi điện chúc mừng đám cưới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3628, 28656, '祭りに大勢の人々が集まりました。', 'まつりに おおぜいの ひとびとが あつまりました。', 'Rất nhiều người tụ tập ở lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3629, 28657, '急用ができたので、帰ります。', 'きゅうようが できたので、かえります。', 'Có việc gấp nên tôi về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3630, 28660, 'できるだけ早く来てください。', 'できるだけ はやく きて ください。', 'Hãy đến sớm nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3631, 28661, '髪を短く切りました。', 'かみを みじかく きりました。', 'Tôi cắt tóc ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3632, 28664, '「チチキトク スグカエレ」という電報が来ました。', '「チチ キトク スグ カエレ」と いう でんぽうが きました。', 'Tôi nhận được điện "Bố nguy kịch, về ngay".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3633, 28665, '祖父は重い病気で入院しています。', 'そふは おもい びょうきで にゅういん して います。', 'Ông tôi đang nằm viện vì bệnh nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3634, 28666, '明日、またお電話いたします。', 'あす、また おでんわ いたします。', 'Ngày mai tôi sẽ gọi lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3635, 41133, 'この薬はすぐに効き目が出る。', 'この くすりは すぐに ききめが でる。', 'Thuốc này có tác dụng ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3636, 41136, 'この本は子供向きだ。', 'この ほんは こどもむきだ。', 'Cuốn sách này phù hợp với trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3637, 41180, '料理の骨をつかんだ。', 'りょうりの こつを つかんだ。', 'Tôi đã nắm được bí quyết nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3638, 41246, 'この箱には不思議な仕掛けがある。', 'この はこには ふしぎな しかけが ある。', 'Chiếc hộp này có cơ chế kỳ lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3639, 28658, '電報を打ちます。', 'でんぽうをうちます。', 'Gửi(điện báo)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3640, 45559, '新聞でおもしろい記事を読んだ。', 'しんぶんで おもしろい きじを よんだ。', 'Tôi đã đọc một bài báo thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3641, 45565, '男女の差別をなくすべきだ。', 'だんじょの さべつを なくす べきだ。', 'Cần xóa bỏ phân biệt nam nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3642, 45543, '昨夜、近所で事件があったらしい。', 'ゆうべ、きんじょで じけんが あった らしい。', 'Nghe nói tối qua gần nhà có xảy ra vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3643, 45547, '財布を落としたので、警察に届けた。', 'さいふを おとしたので、けいさつに とどけた。', 'Đánh rơi ví nên tôi đã báo cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3644, 45550, '大雨で住民は学校に避難した。', 'おおあめで じゅうみんは がっこうに ひなん した。', 'Do mưa lớn, người dân đã sơ tán đến trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3645, 45552, '試験の結果は来週わかる。', 'しけんの けっかは らいしゅう わかる。', 'Tuần sau sẽ biết kết quả thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3646, 45554, 'この計画の問題点を話し合おう。', 'この けいかくの もんだいてんを はなしあおう。', 'Hãy bàn về những điểm có vấn đề trong kế hoạch này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3647, 45558, '明日、授業でレポートを発表する。', 'あした、じゅぎょうで レポートを はっぴょう する。', 'Ngày mai tôi trình bày báo cáo trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3648, 45561, '事故のニュースが大きく報道された。', 'じこの ニュースが おおきく ほうどう された。', 'Tin về vụ tai nạn đã được đưa rầm rộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3649, 45567, '祖父は年金で生活している。', 'そふは ねんきんで せいかつ して いる。', 'Ông tôi sống bằng lương hưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3650, 28662, 'また来てください。', 'また きて ください。', 'Lại đến chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3651, 41248, '仕上がりは来週の月曜日になります。', 'しあがりは らいしゅうの げつようびに なります。', 'Thứ hai tuần sau sẽ hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3652, 28231, '会議の時間を電子メールで知らせます。', 'かいぎの じかんを でんし メールで しらせます。', 'Tôi sẽ báo giờ họp qua email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3653, 28669, '友達に結婚のお祝いを送りました。', 'ともだちに けっこんの おいわいを おくりました。', 'Tôi gửi quà mừng cưới cho bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3654, 28670, '祖父は去年亡くなりました。', 'そふは きょねん なくなりました。', 'Ông tôi mất năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3655, 28671, '悲しみを忘れるのは難しいです。', 'かなしみを わすれるのは むずかしい です。', 'Quên đi nỗi buồn thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3656, 28613, 'このマークはどういう意味ですか。', 'この マークは どういう いみ ですか。', 'Ký hiệu này có nghĩa là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3657, 28755, 'ひもで箱を縛りました。', 'ひもで はこを しばりました。', 'Tôi buộc hộp bằng dây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3658, 41941, '父の敵を討つと誓った。', 'ちちの かたきを うつと ちかった。', 'Anh ta thề sẽ trả thù cho cha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3659, 41252, 'インターネットの仕組みを説明した。', 'インターネットの しくみを せつめい した。', 'Tôi đã giải thích cơ chế hoạt động của Internet.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3660, 41295, '大切な事柄はメモしておこう。', 'たいせつな ことがらは メモ して おこう。', 'Hãy ghi lại những việc quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3661, 41329, '値上げで実質的な収入が減った。', 'ねあげで じっしつてきな しゅうにゅうが へった。', 'Do tăng giá, thu nhập thực tế đã giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3662, 41332, '若者の生活の実態を調査した。', 'わかものの せいかつの じったいを ちょうさ した。', 'Đã khảo sát thực trạng cuộc sống của giới trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3663, 41379, '今、手元にお金がない。', 'いま、てもとに おかねが ない。', 'Bây giờ trong tay tôi không có tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3664, 41381, '説明書の手順どおりに組み立てた。', 'せつめいしょの てじゅん どおりに くみたてた。', 'Tôi lắp ráp theo đúng trình tự trong sách hướng dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3665, 45588, '写真で見るより、実際に行ったほうがきれいでした。', 'しゃしんで みるより、じっさいに いった ほうが きれい でした。', 'Đến tận nơi còn đẹp hơn xem qua ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3666, 45571, '会社が倒産して、父は失業した。', 'かいしゃが とうさん して、ちちは しつぎょう した。', 'Công ty phá sản nên bố tôi bị thất nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3667, 45592, '一番好きな科目は数学です。', 'いちばん すきな かもくは すうがく です。', 'Môn học tôi thích nhất là toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3668, 45568, '東京は物価が高い。', 'とうきょうは ぶっかが たかい。', 'Vật giá ở Tokyo cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3669, 45572, 'その意見に賛成です。', 'その いけんに さんせい です。', 'Tôi tán thành ý kiến đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3670, 45574, '彼は自分の考えを強く主張した。', 'かれは じぶんの かんがえを つよく しゅちょう した。', 'Anh ấy khẳng định mạnh mẽ suy nghĩ của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3671, 45576, '夜中に地震が発生した。', 'よなかに じしんが はっせい した。', 'Nửa đêm đã xảy ra động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3672, 45579, '手を洗って、風邪を防ごう。', 'てを あらって、かぜを ふせごう。', 'Hãy rửa tay để phòng cảm cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3673, 45581, '明日の朝、六時に起こしてください。', 'あしたの あさ、ろくじに おこして ください。', 'Sáng mai hãy đánh thức tôi lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3674, 45583, '犯人はすぐに捕まった。', 'はんにんは すぐに つかまった。', 'Thủ phạm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3675, 45585, '水不足が深刻な問題になっている。', 'みずぶそくが しんこくな もんだいに なって いる。', 'Thiếu nước đang trở thành vấn đề nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3676, 45591, '旅行の前に、その国の知識を身につけた。', 'りょこうの まえに、その くにの ちしきを みに つけた。', 'Trước chuyến đi tôi tìm hiểu kiến thức về nước đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3677, 45594, '科学の進歩で生活が便利になった。', 'かがくの しんぽで せいかつが べんりに なった。', 'Nhờ tiến bộ khoa học, cuộc sống trở nên tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3678, 45597, '日本の文学に興味がある。', 'にほんの ぶんがくに きょうみが ある。', 'Tôi quan tâm đến văn học Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3679, 28648, 'ファイト!最後まで頑張って!', 'ファイト!さいごまで がんばって!', 'Cố lên! Cố gắng đến cùng nhé!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3680, 28675, '次の駅で電車を降ります。', 'つぎの えきで でんしゃを おります。', 'Tôi xuống tàu ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3681, 28811, '毎週日曜日にテニスをします。', 'まいしゅう にちようびに テニスを します。', 'Chủ nhật hằng tuần tôi chơi tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3682, 41389, '先生が手本を見せてくれた。', 'せんせいが てほんを みせて くれた。', 'Thầy đã làm mẫu cho chúng tôi xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3683, 41429, '二人は戦うことが宿命だった。', 'ふたりは たたかう ことが しゅくめい だった。', 'Hai người định mệnh phải đối đầu nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3684, 41465, '先輩の一助となれば幸いです。', 'せんぱいの いちじょと なれば さいわい です。', 'Nếu giúp được anh phần nào thì tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3685, 41495, 'この指輪は二人の愛の証だ。', 'この ゆびわは ふたりの あいの あかしだ。', 'Chiếc nhẫn này là minh chứng tình yêu của hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3686, 41502, '口では彼のほうが一枚上手だ。', 'くちでは かれの ほうが いちまい うわてだ。', 'Về khoản ăn nói thì anh ấy cao tay hơn một bậc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3687, 41541, '計画は振り出しに戻った。', 'けいかくは ふりだしに もどった。', 'Kế hoạch quay về điểm xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3688, 45616, '田中教授は経済学の専門家です。', 'たなか きょうじゅは けいざいがくの せんもんか です。', 'Giáo sư Tanaka là chuyên gia kinh tế học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3689, 45630, '電話はベルによって発明された。', 'でんわは ベルに よって はつめい された。', 'Điện thoại do Bell phát minh ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3690, 45632, 'まず基礎をしっかり勉強しよう。', 'まず きそを しっかり べんきょう しよう。', 'Trước hết hãy học chắc phần cơ bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3691, 45644, '彼女はクラスで一番優秀な学生だ。', 'かのじょは クラスで いちばん ゆうしゅうな がくせいだ。', 'Cô ấy là học sinh ưu tú nhất lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3692, 45600, '大学では経済を専攻しています。', 'だいがくでは けいざいを せんこう して います。', 'Ở đại học tôi học chuyên ngành kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3693, 45603, '卒業論文を書いている。', 'そつぎょう ろんぶんを かいて いる。', 'Tôi đang viết luận văn tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3694, 45605, '今学期は成績が上がった。', 'こんがっきは せいせきが あがった。', 'Học kỳ này thành tích của tôi tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3695, 45608, '一回目の試験は不合格だった。', 'いっかいめの しけんは ふごうかく だった。', 'Lần thi đầu tôi đã trượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3696, 45610, '来年の三月に大学を卒業します。', 'らいねんの さんがつに だいがくを そつぎょう します。', 'Tháng ba năm sau tôi tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3697, 45613, '奨学金をもらって大学に通っている。', 'しょうがくきんを もらって だいがくに かよって いる。', 'Tôi nhận học bổng để học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3698, 45617, 'この高校には生徒が千人いる。', 'この こうこうには せいとが せんにん いる。', 'Trường cấp ba này có một nghìn học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3699, 45631, 'あいさつは人間関係の基本だ。', 'あいさつは にんげん かんけいの きほんだ。', 'Chào hỏi là điều cơ bản trong quan hệ con người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3700, 45634, '例を挙げて説明してください。', 'れいを あげて せつめい して ください。', 'Hãy lấy ví dụ để giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3701, 45638, '祖母から料理を教わった。', 'そぼから りょうりを おそわった。', 'Tôi được bà dạy nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3702, 45640, '留学して、生きた日本語を身につけたい。', 'りゅうがく して、いきた にほんごを みに つけたい。', 'Tôi muốn đi du học để học được tiếng Nhật thực tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3703, 45642, 'お金を数えてから財布に入れた。', 'おかねを かぞえてから さいふに いれた。', 'Tôi đếm tiền rồi mới cho vào ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3704, 45646, '話はだいたいわかりました。', 'はなしは だいたい わかりました。', 'Câu chuyện thì tôi hiểu đại khái rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3705, 45647, '明日は必ず来てください。', 'あしたは かならず きて ください。', 'Ngày mai nhất định phải đến nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3706, 28209, '出かける前にガスを止めてください。', 'でかける まえに ガスを とめて ください。', 'Trước khi ra ngoài hãy khóa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3707, 28683, '説明書をよく読んでから使ってください。', 'せつめいしょを よく よんでから つかって ください。', 'Hãy đọc kỹ hướng dẫn rồi mới sử dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3708, 28684, '図を見てください。', 'ずを みて ください。', 'Hãy xem hình vẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3710, 28685, '大事な所に線を引きました。', 'だいじな ところに せんを ひきました。', 'Tôi kẻ đường gạch dưới chỗ quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3711, 28686, '矢印の方向へ進んでください。', 'やじるしの ほうこうへ すすんで ください。', 'Hãy đi theo hướng mũi tên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3712, 41542, '電車の振動で目が覚めた。', 'でんしゃの しんどうで めが さめた。', 'Tôi tỉnh giấc vì tàu rung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3713, 41560, '事件の真相が明らかになった。', 'じけんの しんそうが あきらかに なった。', 'Chân tướng vụ án đã được làm rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3714, 28677, 'しゅうゆをつけます。', 'しゅうゆをつけます。', 'Chấm', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3715, 41572, 'この時計は少し進みが早い。', 'この とけいは すこし すすみが はやい。', 'Chiếc đồng hồ này chạy hơi nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3716, 41576, '授業の進度が速くてついていけない。', 'じゅぎょうの しんどが はやくて ついて いけない。', 'Tiến độ bài giảng nhanh quá, tôi theo không kịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3717, 41618, '彼は年齢の割に成熟している。', 'かれは ねんれいの わりに せいじゅく して いる。', 'Anh ấy chín chắn so với tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3718, 41638, '彼は生死の境をさまよった。', 'かれは せいしの さかいを さまよった。', 'Anh ấy đã từng lơ lửng giữa sự sống và cái chết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3719, 28678, 'かぎが見つかります。', 'かぎがみつかります。', 'Được tìm thấy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3720, 28680, '傘をさします。', 'かさをさします。', 'Giương [ô]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3721, 45652, '旅行のために毎月貯金しています。', 'りょこうの ために まいつき ちょきん して います。', 'Tôi để dành tiền mỗi tháng cho chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3722, 45656, '学生は二割引で入れます。', 'がくせいは にわりびきで はいれます。', 'Sinh viên được giảm giá 20% khi vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3723, 45662, 'サイズが合わなかったので、返品した。', 'サイズが あわなかったので、へんぴん した。', 'Không vừa cỡ nên tôi đã trả lại hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3724, 45664, '壊れた時計を修理に出した。', 'こわれた とけいを しゅうりに だした。', 'Tôi đã mang chiếc đồng hồ hỏng đi sửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3725, 45653, '支払いはカードでもできますか。', 'しはらいは カードでも できますか。', 'Có thể thanh toán bằng thẻ không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3726, 45649, '田舎の暮らしにもう慣れた。', 'いなかの くらしにも もう なれた。', 'Tôi đã quen với cuộc sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3727, 45654, 'この店は現金しか使えない。', 'この みせは げんきん しか つかえない。', 'Cửa hàng này chỉ nhận tiền mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3728, 45657, '来月から電車の運賃が値上げされる。', 'らいげつから でんしゃの うんちんが ねあげ される。', 'Từ tháng sau giá vé tàu sẽ tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3729, 45659, '注文した品物が届いた。', 'ちゅうもん した しなものが とどいた。', 'Món hàng tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3730, 45666, '家電の店で冷蔵庫を買った。', 'かでんの みせで れいぞうこを かった。', 'Tôi mua tủ lạnh ở cửa hàng điện máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3731, 45670, 'しょうゆは日本料理に欠かせない調味料だ。', 'しょうゆは にほん りょうりに かかせない ちょうみりょうだ。', 'Xì dầu là gia vị không thể thiếu trong món Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3732, 40013, '駅の前に公衆電話がある。', 'えきの まえに こうしゅう でんわが ある。', 'Trước ga có điện thoại công cộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3733, 28242, '朝、鳥の声が聞こえます。', 'あさ、とりの こえが きこえます。', 'Buổi sáng nghe thấy tiếng chim hót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3734, 28688, '白のシャツが好きです。', 'しろの シャツが すき です。', 'Tôi thích áo sơ mi trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3735, 45291, '電気を節約するために、エアコンを使わないようにしている。', 'でんきを せつやく する ために、エアコンを つかわない ように して いる。', 'Để tiết kiệm điện, tôi cố không dùng điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3736, 28690, '信号が青になりました。', 'しんごうが あおに なりました。', 'Đèn tín hiệu đã chuyển xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3737, 28691, '紺のスカートをはいています。', 'こんの スカートを はいて います。', 'Tôi đang mặc chân váy màu xanh lam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3738, 28692, '黄色の花が咲いています。', 'きいろの はなが さいて います。', 'Hoa màu vàng đang nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3739, 45296, '学生は二割引で入れます。', 'がくせいは にわりびきで はいれます。', 'Sinh viên được giảm giá 20% khi vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3740, 45301, '荷物は明日の午前中に配達されます。', 'にもつは あしたの ごぜんちゅうに はいたつ されます。', 'Hàng sẽ được giao vào sáng mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3741, 45676, '夫も育児に協力してくれる。', 'おっとも いくじに きょうりょく して くれる。', 'Chồng tôi cũng phụ giúp nuôi con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3742, 45686, 'パスポートを申請した。', 'パスポートを しんせい した。', 'Tôi đã nộp đơn xin hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3743, 45713, '事故で乗客が数人けがをした。', 'じこで じょうきゃくが すうにん けがを した。', 'Vài hành khách bị thương trong vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3744, 45705, '新しい部屋はとても快適だ。', 'あたらしい へやは とても かいてきだ。', 'Căn phòng mới rất dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3745, 45674, '節約のために毎日自炊している。', 'せつやくの ために まいにち じすい して いる。', 'Để tiết kiệm, ngày nào tôi cũng tự nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3746, 45677, '都会では近所付き合いが少ない。', 'とかいでは きんじょづきあいが すくない。', 'Ở thành phố ít có quan hệ hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3747, 45679, 'ごみ出しは朝八時までにしてください。', 'ごみだしは あさ はちじまでに して ください。', 'Hãy đổ rác trước tám giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3748, 45682, '冬は光熱費が高くなる。', 'ふゆは こうねつひが たかく なる。', 'Mùa đông tiền điện nước ga tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3790, 28711, 'たまねぎを細かく切ってください。', 'たまねぎを こまかく きって ください。', 'Hãy thái nhỏ hành tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3749, 45687, '引っ越したら、役所に届け出をしてください。', 'ひっこしたら、やくしょに とどけでを して ください。', 'Chuyển nhà xong hãy khai báo ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3750, 45689, '旅行の前に保険に入った。', 'りょこうの まえに ほけんに はいった。', 'Trước chuyến đi tôi đã mua bảo hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3751, 45691, '旅行中、友達の猫を預かっている。', 'りょこうちゅう、ともだちの ねこを あずかって いる。', 'Trong lúc bạn đi du lịch, tôi trông giúp con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3752, 45693, '家賃を銀行に振り込んだ。', 'やちんを ぎんこうに ふりこんだ。', 'Tôi đã chuyển khoản tiền nhà qua ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3753, 45695, '一万円あれば足りると思う。', 'いちまんえん あれば たりると おもう。', 'Tôi nghĩ có mười nghìn yên là đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3754, 45698, 'プレゼント用に包装してください。', 'プレゼントように ほうそう して ください。', 'Hãy gói lại giúp tôi để làm quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3755, 45700, '朝の電車はとても混んでいる。', 'あさの でんしゃは とても こんで いる。', 'Tàu buổi sáng rất đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3756, 45701, '昼過ぎの電車は空いている。', 'ひるすぎの でんしゃは すいて いる。', 'Tàu buổi chiều thì vắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3757, 45703, 'まとめて買うとお得です。', 'まとめて かうと おとく です。', 'Mua cả lô thì được hời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3758, 45709, 'この町は交通が便利だ。', 'この まちは こうつうが べんりだ。', 'Giao thông ở thị trấn này rất thuận tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3759, 45712, '十八歳になったら、車の免許を取りたい。', 'じゅうはっさいに なったら、くるまの めんきょを とりたい。', 'Đủ mười tám tuổi tôi muốn lấy bằng lái ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3760, 28694, 'すしにしょうゆをつけて食べます。', 'すしに しょうゆを つけて たべます。', 'Tôi chấm sushi với xì dầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3761, 28697, 'コーヒーか紅茶を飲みます。', 'コーヒーか こうちゃを のみます。', 'Tôi uống cà phê hoặc trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3762, 28698, 'ゆうべは遅くまで起きていました。', 'ゆうべは おそくまで おきて いました。', 'Tối qua tôi thức đến khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3763, 28700, '日本で茶道を習いました。', 'にほんで さどうを ならいました。', 'Tôi đã học trà đạo ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3764, 28702, '先に食べてください。', 'さきに たべて ください。', 'Mọi người cứ ăn trước đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3765, 28703, '荷物を車に載せました。', 'にもつを くるまに のせました。', 'Tôi chất hành lý lên xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3766, 28701, 'お茶をたてます。', 'おちゃをたてます。', 'Pha trà', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3767, 28704, 'これでいいですか。', 'これでいいですか。', 'Thế này có được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3768, 28707, 'カレーの材料を買いに行きます。', 'カレーの ざいりょうを かいに いきます。', 'Tôi đi mua nguyên liệu nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3769, 41700, '物事には善し悪しがある。', 'ものごとには よしあしが ある。', 'Mọi việc đều có mặt tốt mặt xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3770, 28705, 'このりんごは苦いです。', 'このりんごはにがいです。', 'Quả táo này đắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3771, 45729, '今年の夏は国内を旅行するつもりだ。', 'ことしの なつは こくないを りょこう する つもりだ。', 'Hè này tôi định du lịch trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3772, 45736, '駅はどちらの方向ですか。', 'えきは どちらの ほうこう ですか。', 'Ga ở hướng nào vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3773, 45744, '谷の底を川が流れている。', 'たにの そこを かわが ながれて いる。', 'Dưới đáy thung lũng có dòng sông chảy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3774, 45749, '霧で前がよく見えない。', 'きりで まえが よく みえない。', 'Sương mù dày nên không nhìn rõ phía trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3775, 45716, '大阪まで片道一万四千円かかる。', 'おおさかまで かたみち いちまん よんせんえん かかる。', 'Vé một chiều đến Osaka mất mười bốn nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3776, 45718, '飲み会で終電を逃してしまった。', 'のみかいで しゅうでんを のがして しまった。', 'Đi nhậu nên tôi lỡ chuyến tàu cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3777, 45720, '明日の朝六時に出発します。', 'あしたの あさ ろくじに しゅっぱつ します。', 'Sáu giờ sáng mai chúng ta xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3778, 45722, '京都へ観光に行った。', 'きょうとへ かんこうに いった。', 'Tôi đi tham quan Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3779, 45725, '温泉の旅館に二泊した。', 'おんせんの りょかんに にはく した。', 'Tôi nghỉ hai đêm ở lữ quán có suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3780, 45727, '重い荷物を持ってあげましょうか。', 'おもい にもつを もって あげましょうか。', 'Để tôi xách giúp hành lý nặng nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3781, 45732, '都会の生活は便利だが、疲れる。', 'とかいの せいかつは べんりだが、つかれる。', 'Cuộc sống thành phố tiện lợi nhưng mệt mỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3782, 45734, '子供が生まれて、郊外に引っ越した。', 'こどもが うまれて、こうがいに ひっこした。', 'Có con rồi nên chúng tôi chuyển ra ngoại ô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3783, 45738, '高いビルが町の景観を壊している。', 'たかい ビルが まちの けいかんを こわして いる。', 'Những tòa nhà cao tầng đang phá hỏng cảnh quan thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3784, 45741, '朝、海岸を散歩した。', 'あさ、かいがんを さんぽ した。', 'Buổi sáng tôi đi dạo dọc bờ biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3785, 45746, '日本には火山がたくさんある。', 'にほんには かざんが たくさん ある。', 'Nhật Bản có rất nhiều núi lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3786, 45748, '夜中に大きな雷が鳴った。', 'よなかに おおきな かみなりが なった。', 'Nửa đêm có tiếng sấm lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3787, 31217, '彼は誠実な人だから信頼できる。', 'かれは せいじつな ひと だから しんらい できる。', 'Anh ấy là người thành thật nên có thể tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3788, 28253, 'あの方はどなたですか。', 'あの かたは どなた ですか。', 'Vị kia là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3789, 28710, '卵を二個使います。', 'たまごを にこ つかいます。', 'Dùng hai quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3791, 28712, 'ケーキの四分の一を食べました。', 'ケーキの よんぶんの いちを たべました。', 'Tôi đã ăn một phần tư chiếc bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3792, 28716, '火を消すのを忘れないでください。', 'ひを けすのを わすれないで ください。', 'Đừng quên tắt lửa nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3793, 28718, '野菜を十分煮てください。', 'やさいを じゅっぷん にて ください。', 'Hãy nấu rau trong mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3794, 28719, '野菜がよく煮えました。', 'やさいが よく にえました。', 'Rau đã chín kỹ rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3795, 41968, '昔、この城には殿様が住んでいた。', 'むかし、この しろには とのさまが すんで いた。', 'Ngày xưa lãnh chúa sống trong thành này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3796, 41742, '彼の意外な側面を見た。', 'かれの いがいな そくめんを みた。', 'Tôi thấy một khía cạnh bất ngờ của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3797, 41749, '鍵はそこらに置いたはずだ。', 'かぎは そこらに おいた はずだ。', 'Chìa khóa chắc tôi để đâu quanh đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3798, 41755, '一方は賛成し、他方は反対した。', 'いっぽうは さんせい し、たほうは はんたい した。', 'Một bên tán thành, bên kia phản đối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3799, 41769, '初めて茶道を体験した。', 'はじめて さどうを たいけん した。', 'Lần đầu tiên tôi trải nghiệm trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3800, 41770, '彼は体裁を気にしすぎる。', 'かれは ていさいを きに しすぎる。', 'Anh ta quá để ý đến thể diện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3801, 28717, '火にかけます。', 'ひにかけます。', 'Đun', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3802, 45302, 'サイズが合わなかったので、返品した。', 'サイズが あわなかったので、へんぴん した。', 'Không vừa cỡ nên tôi đã trả lại hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3803, 45771, '彼女は暗い表情で話した。', 'かのじょは くらい ひょうじょうで はなした。', 'Cô ấy kể chuyện với vẻ mặt u buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3804, 45766, '今日は海が穏やかだ。', 'きょうは うみが おだやかだ。', 'Hôm nay biển lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3805, 45767, '彼は見事に試験に合格した。', 'かれは みごとに しけんに ごうかく した。', 'Anh ấy đã thi đỗ một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3806, 45753, '地球の温暖化が進んでいる。', 'ちきゅうの おんだんかが すすんで いる。', 'Trái đất đang ngày càng nóng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3807, 45755, '今、駅に向かっています。', 'いま、えきに むかって います。', 'Tôi đang trên đường đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3808, 45757, 'どちらの服を買うか迷っている。', 'どちらの ふくを かうか まよって いる。', 'Tôi đang phân vân không biết mua bộ nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3809, 45759, '帰りにスーパーに寄った。', 'かえりに スーパーに よった。', 'Trên đường về tôi ghé siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3810, 45762, '暑くて、アイスがすぐ溶けた。', 'あつくて、アイスが すぐ とけた。', 'Trời nóng nên kem tan ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3811, 45763, '夕日が山の向こうに沈んだ。', 'ゆうひが やまの むこうに しずんだ。', 'Mặt trời chiều đã lặn sau núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3812, 28713, 'しょうゆは日本料理に欠かせない調味料だ。', 'しょうゆは にほん りょうりに かかせない ちょうみりょうだ。', 'Xì dầu là gia vị không thể thiếu trong món Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3813, 45768, 'ぎりぎりで電車に間に合った。', 'ぎりぎりで でんしゃに まにあった。', 'Tôi kịp tàu trong gang tấc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3814, 45773, '子供の個性を大切にしたい。', 'こどもの こせいを たいせつに したい。', 'Tôi muốn trân trọng cá tính của con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3815, 45775, '私の短所は気が短いところです。', 'わたしの たんしょは きが みじかい ところ です。', 'Khuyết điểm của tôi là nóng tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3816, 45777, '彼には音楽の才能がある。', 'かれには おんがくの さいのうが ある。', 'Cậu ấy có tài năng âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3817, 28720, 'ご飯をどんぶりに入れます。', 'ごはんを どんぶりに いれます。', 'Cho cơm vào bát tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3818, 42202, '愛は人類に普遍的なテーマだ。', 'あいは じんるいに ふへんてきな テーマだ。', 'Tình yêu là chủ đề phổ quát của nhân loại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3819, 41799, '計画の大筋は決まった。', 'けいかくの おおすじは きまった。', 'Nét chính của kế hoạch đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3820, 41838, '彼の勇気は称賛に値する。', 'かれの ゆうきは しょうさんに あたいする。', 'Lòng dũng cảm của anh ấy đáng được ca ngợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3821, 41871, '東京は日本の政治の中枢だ。', 'とうきょうは にほんの せいじの ちゅうすうだ。', 'Tokyo là trung tâm chính trị của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3822, 41905, '会社は深刻な問題に直面している。', 'かいしゃは しんこくな もんだいに ちょくめん して いる。', 'Công ty đang đối mặt với vấn đề nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3823, 41953, '展望台から海が見渡せる。', 'てんぼうだいから うみが みわたせる。', 'Từ đài quan sát có thể phóng tầm mắt ra biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3824, 41963, '点線に沿って切ってください。', 'てんせんに そって きって ください。', 'Hãy cắt theo đường chấm chấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3825, 42105, '事件の背後には大きな組織がある。', 'じけんの はいごには おおきな そしきが ある。', 'Đằng sau vụ án có một tổ chức lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3826, 42166, '自然の美を写真に収めた。', 'しぜんの びを しゃしんに おさめた。', 'Tôi ghi lại vẻ đẹp thiên nhiên bằng ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3827, 28722, 'ネクタイをします。', 'ネクタイをします。', 'Đeo, thắt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3828, 28723, 'このりんごは細いです。', 'このりんごはほそいです。', 'Quả táo này gầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3829, 28724, 'このりんごは太いです。', 'このりんごはふといです。', 'Quả táo này béo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3830, 42273, '湖の辺りに小さなホテルがある。', 'みずうみの ほとりに ちいさな ホテルが ある。', 'Bên bờ hồ có một khách sạn nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3831, 42314, '支払いの方式を選んでください。', 'しはらいの ほうしきを えらんで ください。', 'Hãy chọn phương thức thanh toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3832, 45782, 'カラスはとても賢い鳥だ。', 'カラスは とても かしこい とりだ。', 'Quạ là loài chim rất thông minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3833, 45783, '自分だけ休むなんて、ずるいよ。', 'じぶん だけ やすむ なんて、ずるいよ。', 'Mỗi mình cậu được nghỉ, gian thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3834, 45786, '授業では積極的に質問しよう。', 'じゅぎょうでは せっきょくてきに しつもん しよう。', 'Trong giờ học hãy tích cực đặt câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3835, 42319, '頑張ったご褒美にケーキを買った。', 'がんばった ごほうびに ケーキを かった。', 'Tôi mua bánh kem để tự thưởng vì đã cố gắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3836, 45788, '彼は素直に自分の間違いを認めた。', 'かれは すなおに じぶんの まちがいを みとめた。', 'Anh ấy thật thà thừa nhận lỗi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3837, 45791, '大事なことは慎重に決めたほうがいい。', 'だいじな ことは しんちょうに きめた ほうが いい。', 'Chuyện quan trọng thì nên quyết định thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3838, 45792, '人のものを勝手に使わないで。', 'ひとの ものを かってに つかわないで。', 'Đừng tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3839, 45794, '彼女は話し方が上品だ。', 'かのじょは はなしかたが じょうひんだ。', 'Cô ấy nói năng thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3840, 45795, 'そんな下品な言葉を使わないで。', 'そんな げひんな ことばを つかわないで。', 'Đừng dùng những lời thô tục như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3841, 31074, '給料のいい会社に転職した。', 'きゅうりょうの いい かいしゃに てんしょく した。', 'Tôi đã chuyển sang công ty lương cao hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3842, 31111, '新聞に求人の広告を出した。', 'しんぶんに きゅうじんの こうこくを だした。', 'Chúng tôi đăng quảng cáo tuyển dụng trên báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3843, 42367, '食生活と健康は密接な関係がある。', 'しょくせいかつと けんこうは みっせつな かんけいが ある。', 'Thói quen ăn uống và sức khỏe có quan hệ mật thiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3844, 28261, '将来、大きい家を建てたいです。', 'しょうらい、おおきい いえを たてたい です。', 'Sau này tôi muốn xây một ngôi nhà lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3845, 29670, '砂糖を一／四カップ入れてください。', 'さとうを よんぶんの いち カップ いれて ください。', 'Hãy cho một phần tư cốc đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3846, 31220, '友人の裏切りに深く傷ついた。', 'ゆうじんの うらぎりに ふかく きずついた。', 'Tôi bị tổn thương sâu sắc vì sự phản bội của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3847, 31231, '大学で哲学を専攻した。', 'だいがくで てつがくを せんこう した。', 'Tôi học chuyên ngành triết học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3848, 31224, 'この作家は大衆に人気がある。', 'この さっかは たいしゅうに にんきが ある。', 'Nhà văn này được đại chúng yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3849, 31225, '広場は群衆で埋め尽くされた。', 'ひろばは ぐんしゅうで うめつくされた。', 'Quảng trường chật kín đám đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3850, 31252, '老後のために貯蓄をしている。', 'ろうごの ために ちょちくを して いる。', 'Tôi tiết kiệm cho tuổi già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3851, 31268, '大雨のあと、川の水が濁っている。', 'おおあめの あと、かわの みずが にごって いる。', 'Sau trận mưa lớn, nước sông bị đục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3852, 28729, 'とり肉は牛肉より安いです。', 'とりにくは ぎゅうにくより やすい です。', 'Thịt gà rẻ hơn thịt bò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3853, 31229, '彼の考え方は私たちとは異質だ。', 'かれの かんがえかたは わたしたちとは いしつだ。', 'Cách nghĩ của anh ấy khác hẳn chúng tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3854, 31232, '茶道の深奥を極めるのは容易ではない。', 'さどうの しんおうを きわめるのは よういでは ない。', 'Thấu triệt cái huyền sâu của trà đạo không phải dễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3855, 31235, '小さなミスも許せないのは狭量だ。', 'ちいさな ミスも ゆるせないのは きょうりょうだ。', 'Đến lỗi nhỏ cũng không tha thứ được thì thật hẹp hòi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3856, 31237, '近隣の住民に迷惑をかけないようにしよう。', 'きんりんの じゅうみんに めいわくを かけない ように しよう。', 'Hãy cố đừng làm phiền cư dân lân cận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3857, 31239, '永続する平和を築きたい。', 'えいぞく する へいわを きずきたい。', 'Tôi muốn xây dựng một nền hòa bình bền vững.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3858, 31253, 'パンを牛乳に浸して食べた。', 'パンを ぎゅうにゅうに ひたして たべた。', 'Tôi ngâm bánh mì vào sữa để ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3859, 31254, '砂糖は水によく溶解する。', 'さとうは みずに よく ようかい する。', 'Đường hòa tan tốt trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3860, 31257, '子供は純粋な心を持っている。', 'こどもは じゅんすいな こころを もって いる。', 'Trẻ em có tâm hồn trong sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3861, 31259, '空気は温めると膨張する。', 'くうきは あたためると ぼうちょう する。', 'Không khí khi được làm nóng sẽ giãn nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3862, 31261, '彼は緻密な計画を立てた。', 'かれは ちみつな けいかくを たてた。', 'Anh ấy đã lập một kế hoạch chặt chẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3863, 31263, '駅前に複合施設ができた。', 'えきまえに ふくごう しせつが できた。', 'Trước ga mới có một khu phức hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3864, 31265, '詳細は後ほどメールでお知らせします。', 'しょうさいは のちほど メールで おしらせ します。', 'Chi tiết sẽ được thông báo sau qua email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3865, 31269, '彼の部屋は雑然としている。', 'かれの へやは ざつぜんと して いる。', 'Phòng của anh ấy lộn xộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3866, 42415, 'それは計画の盲点だった。', 'それは けいかくの もうてん だった。', 'Đó là điểm sơ hở của kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3867, 42442, '前半は相手チームが優勢だった。', 'ぜんはんは あいて チームが ゆうせい だった。', 'Hiệp một đội bạn chiếm ưu thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3868, 42450, '部屋はひどい有様だった。', 'へやは ひどい ありさま だった。', 'Căn phòng ở trong tình trạng thê thảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4506, 29619, '私は学生です。', 'わたしはがくせいです。', 'Tôi là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3869, 42475, '薬は用法を守って飲んでください。', 'くすりは ようほうを まもって のんで ください。', 'Hãy uống thuốc theo đúng cách dùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3870, 28695, 'ソースから来ました。', 'ソースからきました。', 'Tôi đến từ chấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3871, 28731, '色が変わります。', 'いろがかわります。', 'Thay đổi, đổi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3872, 28733, '丸を付けます。', 'まるをつけます。', 'Vẽ, đánh dấu', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3873, 28734, '病気が治ります。', 'びょうきがなおります。', 'Khỏi [bệnh]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3874, 28735, '故障が直ります。', 'こしょうがなおります。', 'Được sửa', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3875, 28738, 'このりんごは正しいです。', 'このりんごはただしいです。', 'Quả táo này đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3876, 28758, '昔、ここに大きな木がありました。', 'むかし、ここに おおきな きが ありました。', 'Ngày xưa ở đây có một cái cây to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3877, 28681, '毎週スポーツクラブで泳いでいます。', 'まいしゅう スポーツクラブで およいで います。', 'Hằng tuần tôi bơi ở câu lạc bộ thể thao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3878, 28760, 'これで終わりましょう。', 'これでおわりましょう。', 'Chúng ta kết thúc ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3879, 28746, 'この町には長い歴史がある。', 'この まちには ながい れきしが ある。', 'Thị trấn này có lịch sử lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3880, 28751, 'このホテルは設備が整っている。', 'この ホテルは せつびが ととのって いる。', 'Khách sạn này đầy đủ trang thiết bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3881, 28709, 'このりんごは三百グラムあります。', 'この りんごは さんびゃく グラム あります。', 'Quả táo này nặng ba trăm gam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3882, 28736, 'ここをくりっくしてください。', 'ここを くりっく して ください。', 'Hãy nhấp chuột vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3883, 28737, '名前と住所を入力してください。', 'なまえと じゅうしょを にゅうりょく して ください。', 'Hãy nhập tên và địa chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3884, 28739, '川の向こうに山が見えます。', 'かわの むこうに やまが みえます。', 'Bên kia sông có thể thấy núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3885, 28740, '船で島へ行きました。', 'ふねで しまへ いきました。', 'Tôi đi ra đảo bằng thuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3886, 28742, '近所にスーパーがあるので、便利です。', 'きんじょに スーパーが あるので、べんり です。', 'Gần nhà có siêu thị nên rất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3887, 28745, '週末、友達と山登りに行きました。', 'しゅうまつ、ともだちと やまのぼりに いきました。', 'Cuối tuần tôi đi leo núi với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3888, 28747, '日本人と話す機会がありません。', 'にほんじんと はなす きかいが ありません。', 'Tôi không có cơ hội nói chuyện với người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3889, 28749, '正しい答えに丸をつけてください。', 'ただしい こたえに まるを つけて ください。', 'Hãy khoanh tròn đáp án đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3890, 28756, '炊飯器でご飯を炊きます。', 'すいはんきで ごはんを たきます。', 'Tôi nấu cơm bằng nồi cơm điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3891, 28759, 'もっとゆっくり話してください。', 'もっと ゆっくり はなして ください。', 'Hãy nói chậm hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3892, 28761, '箱根の温泉に行きました。', 'はこねの おんせんに いきました。', 'Tôi đi suối nước nóng ở Hakone.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3893, 28765, 'みんなの学校で日本語を勉強しています。', 'みんなの がっこうで にほんごを べんきょう して います。', 'Tôi học tiếng Nhật ở trường Minna.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3894, 28767, 'IMCパソコン教室でパソコンを習っています。', 'アイエムシー パソコン きょうしつで パソコンを ならって います。', 'Tôi học máy tính ở lớp IMC.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3895, 28768, 'この料理は母の味がします。', 'この りょうりは ははの あじが します。', 'Món này có hương vị của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3896, 28769, '美容院はるで髪を切りました。', 'びよういん はるで かみを きりました。', 'Tôi cắt tóc ở tiệm Haru.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3897, 31221, '彼は音楽家の血筋を引いている。', 'かれは おんがくかの ちすじを ひいて いる。', 'Anh ấy mang dòng máu của gia đình nhạc sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3898, 28786, '道で財布を拾いました。', 'みちで さいふを ひろいました。', 'Tôi nhặt được chiếc ví trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3899, 28775, '旅行社へ行きます。', 'りょこうしゃへいきます。', 'Tôi đi đến công ty du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3900, 28776, 'このりんごは詳しいです。', 'このりんごはくわしいです。', 'Quả táo này cụ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3901, 28790, 'あの方はどなたですか。', 'あの かたは どなた ですか。', 'Vị kia là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3902, 28784, '仲よくします。', 'なかよくします。', 'Quan hệ tốt với', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3903, 28785, 'ここは必要です。', 'ここはひつようです。', 'Ở đây cần thiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3904, 28787, '電話がかかります。', 'でんわがかかります。', 'Có điện thoại', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3905, 28788, 'ここは楽です。', 'ここはらくです。', 'Ở đây thoải mái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3906, 28789, 'このりんごは珍しいです。', 'このりんごはめずらしいです。', 'Quả táo này hiếm có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3907, 28799, 'これで終わります。', 'これでおわります。', 'Đến đây là hết', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3908, 28803, '７時を過ぎます。', '７じをすぎます。', 'Quá', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3909, 28793, 'この機械は操作が簡単だ。', 'この きかいは そうさが かんたんだ。', 'Máy này thao tác đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3910, 28774, 'さあ、始めましょう。', 'さあ、はじめましょう。', 'Nào, bắt đầu thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3911, 28771, '毎日クッキングで料理を習っています。', 'まいにち クッキングで りょうりを ならって います。', 'Tôi học nấu ăn ở Mainichi Cooking.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3912, 28773, '夜行バスで東京へ行きました。', 'やこう バスで とうきょうへ いきました。', 'Tôi đi Tokyo bằng xe buýt đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3913, 28777, '冬はスキー場が混んでいます。', 'ふゆは スキーじょうが こんで います。', 'Mùa đông khu trượt tuyết đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3914, 28778, '草津は温泉で有名です。', 'くさつは おんせんで ゆうめい です。', 'Kusatsu nổi tiếng với suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3915, 28779, '志賀高原でスキーをしました。', 'しが こうげんで スキーを しました。', 'Tôi trượt tuyết ở cao nguyên Shiga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3916, 28780, '朱に交われば赤くなる。', 'しゅに まじわれば あかく なる。', 'Gần mực thì đen, gần đèn thì sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3917, 28781, 'いい友達と交わることが大切です。', 'いい ともだちと まじわる ことが たいせつ です。', 'Kết giao với bạn tốt là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3918, 28794, 'いい勉強の方法を教えてください。', 'いい べんきょうの ほうほうを おしえて ください。', 'Hãy chỉ tôi phương pháp học tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3919, 28795, 'なべのふたを閉めてください。', 'なべの ふたを しめて ください。', 'Hãy đậy nắp nồi lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3920, 28797, '夏休みの旅行が楽しみです。', 'なつやすみの りょこうが たのしみ です。', 'Tôi rất mong chuyến du lịch kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3921, 28798, '初めに、名前を書いてください。', 'はじめに、なまえを かいて ください。', 'Trước hết, hãy viết tên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3922, 28800, '白馬はスキーで有名な所です。', 'はくばは スキーで ゆうめいな ところ です。', 'Hakuba là nơi nổi tiếng về trượt tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3923, 28752, 'このレバーを下げると、水が出ます。', 'この レバーを さげると、みずが でます。', 'Gạt cần này xuống thì nước chảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3924, 28754, 'カーテンを開けてください。', 'カーテンを あけて ください。', 'Hãy kéo rèm cửa ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3925, 28792, '天気がいいので、ハイキングに行きましょう。', 'てんきが いいので、ハイキングに いきましょう。', 'Trời đẹp, đi bộ leo núi thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3926, 41106, '戦争で多くの子供が孤児になった。', 'せんそうで おおくの こどもが こじに なった。', 'Chiến tranh khiến nhiều trẻ em mồ côi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3927, 41117, '本を読んで語彙を増やしたい。', 'ほんを よんで ごいを ふやしたい。', 'Tôi muốn đọc sách để tăng vốn từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3928, 28804, '仕事に慣れます。', 'しごとになれます。', 'Làm quen, quen', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3929, 28805, '食べ物が腐ります。', 'たべものがくさります。', '[đồ ăn] bị hỏng, thiu', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3930, 28269, '日本の食べ物、例えばすしやてんぷらが好きです。', 'にほんの たべもの、たとえば すしや てんぷらが すき です。', 'Tôi thích đồ ăn Nhật, ví dụ như sushi hay tempura.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3931, 28824, 'ここは特別です。', 'ここはとくべつです。', 'Ở đây đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3932, 28825, 'していらっしゃいます。', 'していらっしゃいます。', 'Đang làm (tôn kính ngữ của しています）', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3933, 28828, '使っていらっしゃるんですね。', 'つかっていらっしゃるんですね。', 'Anh/chị đang dùng nhỉ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3934, 28806, '弟は剣道を習っています。', 'おとうとは けんどうを ならって います。', 'Em trai tôi đang học kiếm đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3935, 28834, 'このりんごは珍しいです。', 'このりんごはめずらしいです。', 'Quả táo này rare.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3936, 28841, '荷物が届きます。', 'にもつがとどきます。', 'Được gửi đến, được chuyển đến', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3937, 28842, '試合に出ます。', 'しあいにでます。', 'Tham gia, tham dự', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3938, 28843, 'ワープロを打ちます。', 'ワープロをうちます。', 'Đánh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3939, 28817, '明日は必ず来てください。', 'あしたは かならず きて ください。', 'Ngày mai nhất định phải đến nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3940, 28810, 'この曲を聞くと、元気になります。', 'この きょくを きくと、げんきに なります。', 'Nghe bản nhạc này tôi thấy phấn chấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3941, 28813, '毎年お正月に国へ帰ります。', 'まいとし おしょうがつに くにへ かえります。', 'Năm nào tôi cũng về nước dịp Tết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3942, 28814, 'このごろ、よく眠れません。', 'このごろ、よく ねむれません。', 'Dạo này tôi không ngủ ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3943, 28815, 'やっと宿題が終わりました。', 'やっと しゅくだいが おわりました。', 'Cuối cùng bài tập cũng xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3944, 28816, '今日はかなり寒いですね。', 'きょうは かなり さむい ですね。', 'Hôm nay khá lạnh nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3945, 28819, '日本語が上手に話せるようになりました。', 'にほんごが じょうずに はなせる ように なりました。', 'Tôi đã nói tiếng Nhật giỏi hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3946, 28820, 'できるだけ早く来てください。', 'できるだけ はやく きて ください。', 'Hãy đến sớm nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3947, 28823, 'お客様、こちらへどうぞ。', 'おきゃくさま、こちらへ どうぞ。', 'Thưa quý khách, mời đi lối này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3948, 28826, '毎朝、水泳をしています。', 'まいあさ、すいえいを して います。', 'Sáng nào tôi cũng đi bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3949, 28831, '子どもは乗り物が大好きです。', 'こどもは のりものが だいすき です。', 'Trẻ con rất thích các phương tiện đi lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3950, 28832, '二十一世紀になりました。', 'にじゅういっせいきに なりました。', 'Đã sang thế kỷ 21.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3951, 28833, '遠くに山が見えます。', 'とおくに やまが みえます。', 'Ở xa có thể nhìn thấy núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3952, 28835, '昔は汽車で旅行しました。', 'むかしは きしゃで りょこう しました。', 'Ngày xưa người ta đi du lịch bằng tàu hơi nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3953, 28837, '駅に大勢の人がいます。', 'えきに おおぜいの ひとが います。', 'Ở ga có rất đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3954, 28838, 'この荷物を二階へ運んでください。', 'この にもつを にかいへ はこんで ください。', 'Hãy mang hành lý này lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3955, 28839, '図書館を利用したいんですが。', 'としょかんを りよう したいん ですが。', 'Tôi muốn sử dụng thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3956, 28844, '甘い物を食べすぎて、太りました。', 'あまい ものを たべすぎて、ふとりました。', 'Ăn quá nhiều đồ ngọt nên tôi béo lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3957, 28846, 'このりんごは硬いです。', 'このりんごはかたいです。', 'Quả táo này cứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3958, 28847, 'このりんごは軟らかいです。', 'このりんごはやわらかいです。', 'Quả táo này mềm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3959, 28863, '友達を映画に誘いました。', 'ともだちを えいがに さそいました。', 'Tôi rủ bạn đi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3960, 28858, 'ここは安全です。', 'ここはあんぜんです。', 'Ở đây an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3961, 28885, '世界中から観光客が来ます。', 'せかいじゅうから かんこうきゃくが きます。', 'Khách du lịch đến từ khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3962, 28880, 'しょうゆの原料は大豆だ。', 'しょうゆの げんりょうは だいずだ。', 'Nguyên liệu làm xì dầu là đậu nành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3963, 28808, '朝のラッシュは大変です。', 'あさの ラッシュは たいへん です。', 'Giờ cao điểm buổi sáng thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3964, 28845, '毎日運動して、三キロやせました。', 'まいにち うんどう して、さんキロ やせました。', 'Tập thể dục mỗi ngày, tôi giảm được ba ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3965, 28849, '携帯電話を家に忘れました。', 'けいたい でんわを いえに わすれました。', 'Tôi để quên điện thoại di động ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3966, 28850, 'この工場では車を作っています。', 'この こうじょうでは くるまを つくって います。', 'Nhà máy này sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3967, 28853, '電車で行きましょう。そのほうが速いです。', 'でんしゃで いきましょう。その ほうが はやい です。', 'Đi tàu điện đi. Như thế nhanh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3968, 29671, 'まいねん八月に祭りがあります。', 'まいねん はちがつに まつりが あります。', 'Tháng tám hằng năm có lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3969, 28855, 'アルゼンチンでタンゴを踊りました。', 'アルゼンチンで タンゴを おどりました。', 'Tôi đã nhảy tango ở Argentina.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3970, 28862, '遅刻して、部長にしかられました。', 'ちこく して、ぶちょうに しかられました。', 'Đi muộn nên tôi bị trưởng phòng mắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3971, 28864, '友達を誕生日のパーティーに招待しました。', 'ともだちを たんじょうびの パーティーに しょうたい しました。', 'Tôi mời bạn đến dự tiệc sinh nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3972, 28865, '友達に引っ越しの手伝いを頼みました。', 'ともだちに ひっこしの てつだいを たのみました。', 'Tôi nhờ bạn giúp chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3973, 28867, '電車の中で財布をとられました。', 'でんしゃの なかで さいふを とられました。', 'Tôi bị lấy trộm ví trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3974, 28868, '電車の中で足を踏まれました。', 'でんしゃの なかで あしを ふまれました。', 'Tôi bị giẫm vào chân trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3975, 28870, '子どもに服を汚されました。', 'こどもに ふくを よごされました。', 'Tôi bị trẻ con làm bẩn quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3976, 28872, '日本は車を外国に輸出しています。', 'にほんは くるまを がいこくに ゆしゅつ して います。', 'Nhật Bản xuất khẩu ô tô ra nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3977, 28873, '日本は石油を輸入しています。', 'にほんは せきゆを ゆにゅう して います。', 'Nhật Bản nhập khẩu dầu mỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3978, 28875, '電話はベルによって発明されました。', 'でんわは ベルに よって はつめい されました。', 'Điện thoại được phát minh bởi Bell.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3979, 28877, '日本人は米をよく食べます。', 'にほんじんは こめを よく たべます。', 'Người Nhật ăn gạo nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3980, 28878, 'ビールは麦から作られます。', 'ビールは むぎから つくられます。', 'Bia được làm từ lúa mạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3981, 28879, '石油の値段が上がりました。', 'せきゆの ねだんが あがりました。', 'Giá dầu mỏ đã tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3982, 28884, '警官に道を聞きました。', 'けいかんに みちを ききました。', 'Tôi hỏi đường cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3983, 28886, 'この歌は世界中で歌われています。', 'この うたは せかいじゅうで うたわれて います。', 'Bài hát này được hát khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3984, 28888, 'ブラジルでは何語を話しますか。', 'ブラジルでは なにごを はなしますか。', 'Ở Brazil người ta nói tiếng gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3985, 42476, 'この工事は三年を要する。', 'この こうじは さんねんを ようする。', 'Công trình này cần ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3986, 28900, 'うちが焼けます。', 'うちがやけます。', '[nhà] cháy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3987, 28908, 'このりんごは美しいです。', 'このりんごはうつくしいです。', 'Quả táo này beautiful.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3988, 28909, 'ここは豪華です。', 'ここはごうかです。', 'Ở đây hào hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3989, 28274, '昔、ここに大きな木がありました。', 'むかし、ここに おおきな きが ありました。', 'Ngày xưa ở đây có một cái cây to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3990, 28889, '誰か来ましたよ。', 'だれか きましたよ。', 'Có ai đó đến đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3991, 28919, '一匹もいません。', 'いっぴきもいません。', 'Không có con nào cả', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3992, 28890, 'A：試験に合格しました。B：よかったですね。', 'エー：しけんに ごうかく しました。ビー：よかった ですね。', 'A: Tôi thi đỗ rồi. B: May quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3993, 28893, '奈良の東大寺には大きい大仏があります。', 'ならの とうだいじには おおきい だいぶつが あります。', 'Chùa Todaiji ở Nara có tượng Phật lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3994, 28895, 'この建物は江戸時代に建てられました。', 'この たてものは えど じだいに たてられました。', 'Tòa nhà này được xây vào thời Edo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3995, 28901, 'その後、彼は国へ帰りました。', 'そのご、かれは くにへ かえりました。', 'Sau đó anh ấy đã về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3996, 28902, 'この寺は世界遺産に選ばれました。', 'この てらは せかい いさんに えらばれました。', 'Ngôi chùa này đã được chọn là di sản thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3997, 28903, '富士山は日本の世界遺産の一つです。', 'ふじさんは にほんの せかい いさんの ひとつ です。', 'Núi Phú Sĩ là một trong những di sản thế giới của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3998, 28904, '金閣寺は金色に光っています。', 'きんかくじは きんいろに ひかって います。', 'Kinkakuji lấp lánh màu vàng kim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (3999, 28905, 'この絵は本物ですか。', 'この えは ほんもの ですか。', 'Bức tranh này là đồ thật à?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4000, 28906, 'この指輪は金でできています。', 'この ゆびわは きんで できて います。', 'Chiếc nhẫn này làm bằng vàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4001, 28911, 'この村には古い言い伝えがあります。', 'この むらには ふるい いいつたえが あります。', 'Ngôi làng này có truyền thuyết cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4002, 28912, '疲れていたので、よく眠りました。', 'つかれて いたので、よく ねむりました。', 'Mệt nên tôi ngủ rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4003, 28913, '木に名前を彫りました。', 'きに なまえを ほりました。', 'Tôi khắc tên lên gỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4004, 28917, '試験のために一生懸命勉強しました。', 'しけんの ために いっしょうけんめい べんきょう しました。', 'Tôi đã học hết sức cho kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4005, 28918, '台所にねずみがいます。', 'だいどころに ねずみが います。', 'Trong bếp có chuột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4006, 28921, '東照宮で眠り猫を見ました。', 'とうしょうぐうで ねむりねこを みました。', 'Tôi đã xem tượng Con mèo ngủ ở đền Toshogu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4007, 28922, '眠り猫は左甚五郎が彫ったと言われています。', 'ねむりねこは ひだり じんごろうが ほったと いわれて います。', 'Người ta nói Con mèo ngủ do Hidari Jingoro khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4008, 28923, 'あした六時に起こしてください。', 'あした ろくじに おこして ください。', 'Ngày mai hãy đánh thức tôi lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4009, 28925, '将来、建築家になりたいです。', 'しょうらい、けんちくかに なりたい です。', 'Sau này tôi muốn làm kiến trúc sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4010, 28926, 'アインシュタインは有名な科学者です。', 'アインシュタインは ゆうめいな かがくしゃ です。', 'Einstein là nhà khoa học nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4011, 28928, 'この寺は聖徳太子によって建てられました。', 'この てらは しょうとく たいしに よって たてられました。', 'Ngôi chùa này được xây bởi Thái tử Shotoku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4012, 28280, '昼間は暑いですが、夜は涼しいです。', 'ひるまは あつい ですが、よるは すずしい です。', 'Ban ngày nóng nhưng đêm thì mát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4013, 28959, '祖父母は小さな村に住んでいます。', 'そふぼは ちいさな むらに すんで います。', 'Ông bà tôi sống ở một ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4014, 28929, 'ドミニカから来ました。', 'ドミニカからきました。', 'Tôi đến từ Dominica.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4015, 28945, '電源を入れます。', 'でんげんをいれます。', 'Bật', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4016, 28946, '電源を切ります。', 'でんげんをきります。', 'Tắt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4017, 28947, 'かぎを掛けます。', 'かぎをかけます。', 'Khóa', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4018, 28948, 'うそをつきます。', 'うそをつきます。', 'Nói [dối]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4019, 28949, 'このりんごは気持ちがいいです。', 'このりんごはきもちがいいです。', 'Quả táo này dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4020, 28950, 'このりんごは気持ちが悪いです。', 'このりんごはきもちがわるいです。', 'Quả táo này khó chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4021, 28954, '小学校へ行きます。', 'しょうがっこうへいきます。', 'Tôi đi đến trường tiểu học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4022, 28955, '中学校へ行きます。', 'ちゅうがっこうへいきます。', 'Tôi đi đến trường trung học cơ sở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4023, 28934, '海を埋め立てて、空港を作りました。', 'うみを うめたてて、くうこうを つくりました。', 'Người ta lấp biển để xây sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4024, 28937, '工事の騒音で眠れない。', 'こうじの そうおんで ねむれない。', 'Tiếng ồn công trình khiến tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4025, 28938, '図書館を利用したいんですが。', 'としょかんを りよう したいん ですが。', 'Tôi muốn sử dụng thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4026, 28882, '週末、彼女とデートします。', 'しゅうまつ、かのじょと デート します。', 'Cuối tuần tôi hẹn hò với bạn gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4027, 28891, 'オリンピックをテレビで見ました。', 'オリンピックを テレビで みました。', 'Tôi xem Olympic trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4028, 28892, 'ワールドカップは四年に一回行われます。', 'ワールドカップは よねんに いっかい おこなわれます。', 'World Cup được tổ chức bốn năm một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4029, 28896, 'ポルトガルの料理を食べました。', 'ポルトガルの りょうりを たべました。', 'Tôi đã ăn món Bồ Đào Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4030, 28897, '日本はサウジアラビアから石油を輸入しています。', 'にほんは サウジアラビアから せきゆを ゆにゅう して います。', 'Nhật Bản nhập khẩu dầu mỏ từ Ả Rập Xê Út.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4031, 28907, '駅まで二キロあります。', 'えきまで にキロ あります。', 'Đến ga là hai cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4032, 28939, 'このホテルは駅からのアクセスがいいです。', 'この ホテルは えきからの アクセスが いい です。', 'Khách sạn này đi từ ga đến rất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4033, 28941, 'ベランダで野菜を育てています。', 'ベランダで やさいを そだてて います。', 'Tôi trồng rau ở ban công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4034, 28942, 'この荷物を二階へ運んでください。', 'この にもつを にかいへ はこんで ください。', 'Hãy mang hành lý này lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4035, 28944, '祖母は昨日退院しました。', 'そぼは きのう たいいん しました。', 'Bà tôi đã xuất viện hôm qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4036, 28951, '大きな声で話してください。', 'おおきな こえで はなして ください。', 'Hãy nói to lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4037, 28952, '小さな村で生まれました。', 'ちいさな むらで うまれました。', 'Tôi sinh ra ở một ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4038, 28953, '姉に赤ちゃんが生まれました。', 'あねに あかちゃんが うまれました。', 'Chị tôi vừa sinh em bé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4039, 28960, '名前をかなで書いてください。', 'なまえを かなで かいて ください。', 'Hãy viết tên bằng chữ kana.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4040, 28961, '誕生日に指輪をもらいました。', 'たんじょうびに ゆびわを もらいました。', 'Sinh nhật tôi được tặng nhẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4041, 42503, '在宅勤務には多くの利点がある。', 'ざいたく きんむには おおくの りてんが ある。', 'Làm việc tại nhà có nhiều lợi thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4042, 28973, '私は研究室です。', 'わたしはけんきゅうしつです。', 'Tôi là Phòng nghiên cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4043, 28964, '健康のために、たばこをやめました。', 'けんこうの ために、たばこを やめました。', 'Vì sức khỏe, tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4044, 28980, 'はんこを押します。', 'はんこをおします。', 'Đóng(dấu)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4045, 28983, '私は５年生です。', 'わたしは５ねんせいです。', 'Tôi là học sinh năm thứ 5.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4046, 28984, '似ています。', 'にています。', 'Giống', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4047, 28986, 'このりんごはおとなしいです。', 'このりんごはおとなしいです。', 'Quả táo này hiền lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4048, 28987, 'このりんごは優しいです。', 'このりんごはやさしいです。', 'Quả táo này kind.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4049, 28988, '世話をします。', 'せわをします。', 'Chăm sóc', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4050, 28989, '時間がたちます。', 'じかんがたちます。', 'Thời gian trôi đi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4051, 28994, 'ここは不思議です。', 'ここはふしぎです。', 'Ở đây bí ẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4052, 28962, 'パソコンの電源を切ってください。', 'パソコンの でんげんを きって ください。', 'Hãy tắt nguồn máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4053, 45803, 'この問題は私には関係がない。', 'この もんだいは わたしには かんけいが ない。', 'Vấn đề này không liên quan đến tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4054, 28985, '兄と私は性格が全然違う。', 'あにと わたしは せいかくが ぜんぜん ちがう。', 'Anh trai và tôi tính cách hoàn toàn khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4055, 28998, 'うそを言ってはいけません。', 'うそを いっては いけません。', 'Không được nói dối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4056, 28965, 'このカメラは日本製です。', 'この カメラは にほんせい です。', 'Chiếc máy ảnh này sản xuất tại Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4057, 28966, 'おととし日本へ来ました。', 'おととし にほんへ きました。', 'Năm kia tôi đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4058, 28968, 'お先に失礼します。', 'おさきに しつれい します。', 'Tôi xin phép về trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4059, 28969, '広島で原爆ドームを見ました。', 'ひろしまで げんばく ドームを みました。', 'Tôi đã xem Mái vòm bom nguyên tử ở Hiroshima.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4060, 28970, '出雲大社は縁結びの神社として有名です。', 'いずも たいしゃは えんむすびの じんじゃと して ゆうめい です。', 'Đền Izumo Taisha nổi tiếng là đền cầu duyên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4061, 28972, '町内会の回覧が来ました。', 'ちょうないかいの かいらんが きました。', 'Tập thông báo của tổ dân phố đã được chuyền đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4062, 28976, 'いい勉強の方法を教えてください。', 'いい べんきょうの ほうほうを おしえて ください。', 'Hãy chỉ tôi phương pháp học tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4063, 28977, 'これは「さくら」という歌です。', 'これは 「さくら」と いう うた です。', 'Đây là bài hát tên là "Sakura".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4064, 28978, '図書館で本を三冊借りました。', 'としょかんで ほんを さんさつ かりました。', 'Tôi mượn ba cuốn sách ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4065, 28979, 'ここにはんこを押してください。', 'ここに はんこを おして ください。', 'Hãy đóng dấu vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4066, 28982, '私たちは三人姉妹です。', 'わたしたちは さんにん しまい です。', 'Chúng tôi là ba chị em gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4067, 28991, 'テストで八十点を取りました。', 'テストで はちじってんを とりました。', 'Tôi được tám mươi điểm bài kiểm tra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4068, 28993, '弟とけんかしました。', 'おとうとと けんか しました。', 'Tôi cãi nhau với em trai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4069, 28996, 'このカメラの使い方のしかたがわかりません。', 'この カメラの つかいかたの しかたが わかりません。', 'Tôi không biết cách sử dụng chiếc máy ảnh này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4070, 28971, 'チェンマイはタイの北にある町です。', 'チェンマイは タイの きたに ある まち です。', 'Chiang Mai là thành phố ở miền bắc Thái Lan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4071, 28287, '週末、伊豆の温泉へ行きました。', 'しゅうまつ、いずの おんせんへ いきました。', 'Cuối tuần tôi đi suối nước nóng ở Izu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4072, 29002, 'ビルが倒れます。', 'ビルがたおれます。', 'Đổ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4073, 29003, '道を通ります。', 'みちをとおります。', 'Đi qua', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4074, 29005, '大きな音がして、びっくりしました。', 'おおきな おとが して、びっくり しました。', 'Có tiếng động lớn nên tôi giật mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4075, 29012, 'ここは複雑です。', 'ここはふくざつです。', 'Ở đây phức tạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4076, 29013, 'ここは邪魔です。', 'ここはじゃまです。', 'Ở đây cản trở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4077, 29014, 'このりんごは硬いです。', 'このりんごはかたいです。', 'Quả táo này hard.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4078, 29015, 'このりんごは軟らかいです。', 'このりんごはやわらかいです。', 'Quả táo này soft.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4079, 29016, 'このりんごは汚いです。', 'このりんごはきたないです。', 'Quả táo này bẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4080, 29017, 'このりんごはうれしいです。', 'このりんごはうれしいです。', 'Quả táo này vui mừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4081, 29018, 'このりんごは悲しいです。', 'このりんごはかなしいです。', 'Quả táo này buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4082, 29019, 'このりんごは恥ずかしいです。', 'このりんごははずかしいです。', 'Quả táo này xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4083, 29007, '家族が元気だと聞いて、安心しました。', 'かぞくが げんきだと きいて、あんしん しました。', 'Nghe tin gia đình khỏe mạnh, tôi yên tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4084, 29009, '二人は去年離婚しました。', 'ふたりは きょねん りこん しました。', 'Hai người đã ly hôn năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4085, 29020, '首相が新しい政策を発表した。', 'しゅしょうが あたらしい せいさくを はっぴょう した。', 'Thủ tướng đã công bố chính sách mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4086, 29022, '地震のあとは津波に注意してください。', 'じしんの あとは つなみに ちゅうい して ください。', 'Sau động đất hãy cảnh giác với sóng thần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4087, 29029, 'この機械は操作が簡単だ。', 'この きかいは そうさが かんたんだ。', 'Máy này thao tác đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4088, 29000, '私のクラスには学生が十五人います。', 'わたしの クラスには がくせいが じゅうごにん います。', 'Lớp tôi có mười lăm học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4089, 29011, '毎日運動して、三キロやせました。', 'まいにち うんどう して、さんキロ やせました。', 'Tập thể dục mỗi ngày, tôi giảm được ba ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4090, 29023, '台風で電車が止まりました。', 'たいふうで でんしゃが とまりました。', 'Tàu điện ngừng chạy vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4091, 29026, '事後の報告は必ずしてください。', 'じごの ほうこくは かならず して ください。', 'Sau đó nhất định phải báo cáo lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4092, 29030, 'パーティーの会場はホテルです。', 'パーティーの かいじょうは ホテル です。', 'Địa điểm tổ chức tiệc là khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4093, 29031, '今月は電気代が高かったです。', 'こんげつは でんきだいが たかかった です。', 'Tháng này tiền điện cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4094, 29034, '私の部屋は三〇五号室です。', 'わたしの へやは さんまるごごうしつ です。', 'Phòng tôi là phòng số 305.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4095, 29036, 'せっけんで手を洗いましょう。', 'せっけんで てを あらいましょう。', 'Hãy rửa tay bằng xà phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4096, 29037, '会場に大勢来ていました。', 'かいじょうに おおぜい きて いました。', 'Rất nhiều người đã đến hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4097, 29039, 'あした三時にお宅に伺います。', 'あした さんじに おたくに うかがいます。', 'Ngày mai ba giờ tôi xin đến thăm nhà anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4098, 29040, '会社へ行く途中で事故を見ました。', 'かいしゃへ いく とちゅうで じこを みました。', 'Trên đường đi làm tôi đã thấy một vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4099, 29042, '自転車が車にぶつかりました。', 'じてんしゃが くるまに ぶつかりました。', 'Xe đạp đâm vào ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4100, 29043, '大人の料金は千円です。', 'おとなの りょうきんは せんえん です。', 'Giá vé người lớn là một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4101, 29027, '天気がいいので、ハイキングに行きましょう。', 'てんきが いいので、ハイキングに いきましょう。', 'Trời đẹp, đi bộ leo núi thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4102, 29051, 'ここは伝統的です。', 'ここはでんとうてきです。', 'Ở đây traditional.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4103, 29052, 'うちが焼けます。', 'うちがやけます。', 'Nướng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4104, 29053, 'パンが焼けます。', 'パンがやけます。', 'Nướng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4105, 29054, '肉が焼けます。', 'にくがやけます。', 'Nướng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4106, 29063, 'サイズが合います。', 'サイズがあいます。', 'Vừa, hợp', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4107, 29067, 'うまくいきます。', 'うまくいきます。', 'Suôn sẻ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4108, 29068, '問題が出ます。', 'もんだいがでます。', '[câu hỏi] ra trong bài thi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4109, 45324, 'ビザの手続きに一か月かかった。', 'ビザの てつづきに いっかげつ かかった。', 'Thủ tục visa mất một tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4110, 29045, 'また来てください。', 'また きて ください。', 'Lại đến chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4111, 29046, '新しい洋服を買いました。', 'あたらしい ようふくを かいました。', 'Tôi mua quần áo mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4112, 29047, '日本の生活はずいぶん西洋化しました。', 'にほんの せいかつは ずいぶん せいようか しました。', 'Lối sống Nhật Bản đã Tây hóa khá nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4113, 29048, 'このくつはサイズが合いません。', 'この くつは サイズが あいません。', 'Đôi giày này không vừa cỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4114, 29050, '成人式に着物を着て行きました。', 'せいじんしきに きものを きて いきました。', 'Tôi mặc kimono đi dự lễ trưởng thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4115, 29055, '電車が遅れて、遅刻しました。', 'でんしゃが おくれて、ちこく しました。', 'Tàu bị trễ nên tôi đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4116, 29057, '今月は電話代が高いです。', 'こんげつは でんわだいが たかい です。', 'Tháng này tiền điện thoại cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4117, 29058, '暑くて汗がたくさん出ました。', 'あつくて あせが たくさん でました。', 'Nóng quá nên ra nhiều mồ hôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4118, 29059, 'チケットを買うために並びました。', 'チケットを かう ために ならびました。', 'Tôi xếp hàng để mua vé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4119, 29035, 'タオルを持ってきてください。', 'タオルを もって きて ください。', 'Hãy mang khăn tắm đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4120, 29041, '大きなトラックが通りました。', 'おおきな トラックが とおりました。', 'Một chiếc xe tải lớn vừa chạy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4121, 29062, '出かける前に、窓が閉まっているか確かめます。', 'でかける まえに、まどが しまって いるか たしかめます。', 'Trước khi ra ngoài tôi kiểm tra xem cửa sổ đã đóng chưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4122, 29065, '飛行機は十時に到着します。', 'ひこうきは じゅうじに とうちゃく します。', 'Máy bay đến nơi lúc mười giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4123, 29066, 'お酒を飲みすぎて、酔ってしまいました。', 'おさけを のみすぎて、よって しまいました。', 'Uống quá nhiều rượu nên tôi say mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4204, 29176, '最後にひとことお願いします。', 'さいごに ひとこと おねがい します。', 'Cuối cùng xin anh nói vài lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4124, 29072, '十二月に会社の忘年会があります。', 'じゅうにがつに かいしゃの ぼうねんかいが あります。', 'Tháng mười hai có tiệc tất niên của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4125, 29073, '一月に新年会をします。', 'いちがつに しんねんかいを します。', 'Tháng một chúng tôi tổ chức tiệc tân niên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4126, 29074, '二次会はカラオケに行きました。', 'にじかいは カラオケに いきました。', 'Tăng hai chúng tôi đi karaoke.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4127, 29076, 'スピーチ大会で一位になりました。', 'スピーチ たいかいで いちいに なりました。', 'Tôi giành giải nhất cuộc thi hùng biện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4128, 29079, '封筒の表に住所を書いてください。', 'ふうとうの おもてに じゅうしょを かいて ください。', 'Hãy viết địa chỉ ở mặt trước phong bì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4129, 31249, 'その発見が事件解決の端緒となった。', 'その はっけんが じけん かいけつの たんしょと なった。', 'Phát hiện đó trở thành manh mối để phá án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4130, 29117, '試験のために一生懸命勉強しました。', 'しけんの ために いっしょうけんめい べんきょう しました。', 'Tôi đã học hết sức cho kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4131, 29081, '作文にまちがいがあったら、直してください。', 'さくぶんに まちがいが あったら、なおして ください。', 'Nếu bài văn có lỗi sai thì hãy sửa giúp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4132, 29082, '新しい車に傷がついてしまいました。', 'あたらしい くるまに きずが ついて しまいました。', 'Chiếc xe mới bị trầy mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4133, 29120, '手に入れます。', 'てにいれます。', 'Có được', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4134, 29122, 'ここは危険です。', 'ここはきけんです。', 'Ở đây nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4135, 29105, '今学期は成績が上がった。', 'こんがっきは せいせきが あがった。', 'Học kỳ này thành tích của tôi tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4136, 29118, '警察は犯人を探している。', 'けいさつは はんにんを さがして いる。', 'Cảnh sát đang truy tìm thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4137, 29107, '田中さんは今どこにいらっしゃいますか。', 'たなかさんは いま どこに いらっしゃいますか。', 'Anh Tanaka bây giờ đang ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4138, 29119, 'このクラスは男が十人、女が五人です。', 'この クラスは おとこが じゅうにん、おんなが ごにん です。', 'Lớp này có mười nam và năm nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4139, 29085, 'この川の長さはどのくらいですか。', 'この かわの ながさは どのくらい ですか。', 'Con sông này dài khoảng bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4140, 29086, '荷物の重さを量ってください。', 'にもつの おもさを はかって ください。', 'Hãy cân trọng lượng hành lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4141, 29087, '富士山の高さは三千七百七十六メートルです。', 'ふじさんの たかさは さんぜん ななひゃく ななじゅうろく メートル です。', 'Núi Phú Sĩ cao 3.776 mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4142, 29089, '十時の便で大阪へ行きます。', 'じゅうじの びんで おおさかへ いきます。', 'Tôi đi Osaka bằng chuyến bay lúc mười giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4143, 29090, 'りんごを三個ください。', 'りんごを さんこ ください。', 'Cho tôi ba quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4144, 29091, 'ビールを二本買いました。', 'ビールを にほん かいました。', 'Tôi đã mua hai chai bia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4145, 29096, '二十歳以上の人はお酒を飲むことができます。', 'はたち いじょうの ひとは おさけを のむ ことが できます。', 'Người từ hai mươi tuổi trở lên được uống rượu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4146, 29097, '三歳以下の子どもは無料です。', 'さんさい いかの こどもは むりょう です。', 'Trẻ em từ ba tuổi trở xuống miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4147, 29098, '長崎へ旅行に行きました。', 'ながさきへ りょこうに いきました。', 'Tôi đã đi du lịch Nagasaki.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4148, 29100, 'JL１２３便で東京へ行きます。', 'ジェイエル ひゃくにじゅうさんびんで とうきょうへ いきます。', 'Tôi đi Tokyo bằng chuyến bay JL123.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4149, 29101, '七夕祭りで願いごとを書きました。', 'たなばた まつりで ねがいごとを かきました。', 'Ở lễ hội Tanabata tôi đã viết điều ước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4150, 29103, 'この計画はどうでしょうか。', 'この けいかくは どう でしょうか。', 'Kế hoạch này thế nào ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4151, 29106, 'ところで、来週の会議は何時からですか。', 'ところで、らいしゅうの かいぎは なんじから ですか。', 'Nhân tiện, cuộc họp tuần sau mấy giờ bắt đầu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4152, 29112, 'トラックに荷物を積みました。', 'トラックに にもつを つみました。', 'Tôi chất hàng lên xe tải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4153, 29113, 'バスの運転手に道を聞きました。', 'バスの うんてんしゅに みちを ききました。', 'Tôi hỏi đường bác tài xế xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4154, 29114, '駅から離れた所に住んでいます。', 'えきから はなれた ところに すんで います。', 'Tôi sống ở nơi cách xa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4155, 29116, '机を動かすのを手伝ってください。', 'つくえを うごかすのを てつだって ください。', 'Hãy giúp tôi dịch cái bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4156, 42529, 'この類の話はよく聞く。', 'この たぐいの はなしは よく きく。', 'Những chuyện kiểu này tôi nghe nhiều rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4157, 28288, '父の趣味は日曜大工です。', 'ちちの しゅみは にちよう だいく です。', 'Sở thích của bố tôi là làm thợ mộc ngày chủ nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4158, 29139, '宿題はもうやりました。', 'しゅくだいは もう やりました。', 'Bài tập tôi đã làm rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4159, 29142, '親切にします。', 'しんせつにします。', 'Giúp đỡ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4160, 29143, 'このりんごはかわいいです。', 'このりんごはかわいいです。', 'Quả táo này xinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4161, 29095, 'このりんごは三百グラムあります。', 'この りんごは さんびゃく グラム あります。', 'Quả táo này nặng ba trăm gam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4162, 29151, '日本語の発音を練習している。', 'にほんごの はつおんを れんしゅう して いる。', 'Tôi đang luyện phát âm tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4163, 29134, '私のクラスには学生が十五人います。', 'わたしの クラスには がくせいが じゅうごにん います。', 'Lớp tôi có mười lăm học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4164, 29130, 'さあ、始めましょう。', 'さあ、はじめましょう。', 'Nào, bắt đầu thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4165, 29127, 'それはほんとうですか。', 'それは ほんとう ですか。', 'Chuyện đó có thật không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4166, 29129, '駅まで二キロあります。', 'えきまで にキロ あります。', 'Đến ga là hai cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4167, 29141, 'エアコンの温度を下げてください。', 'エアコンの おんどを さげて ください。', 'Hãy hạ nhiệt độ điều hòa xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4168, 29126, '申し込みは金曜日までです。', 'もうしこみは きんようびまで です。', 'Hạn đăng ký đến thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4169, 29135, '日本語は難しいですが、おもしろいです。', 'にほんごは むずかしい ですが、おもしろい です。', 'Tiếng Nhật khó nhưng thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4170, 29674, '水を一杯ください。', 'みずを いっぱい ください。', 'Cho tôi một cốc nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4171, 29675, 'コーヒーを三杯飲みました。', 'コーヒーを さんばい のみました。', 'Tôi đã uống ba cốc cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4172, 29672, '鉛筆を一本貸してください。', 'えんぴつを いっぽん かして ください。', 'Cho tôi mượn một cây bút chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4173, 29078, '写真のコンテストに出しました。', 'しゃしんの コンテストに だしました。', 'Tôi gửi ảnh dự cuộc thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4174, 29083, 'このズボンは長すぎます。', 'この ズボンは ながすぎます。', 'Cái quần này dài quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4175, 29093, 'この机は八十センチあります。', 'この つくえは はちじゅっセンチ あります。', 'Cái bàn này dài tám mươi phân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4176, 29094, '雨が五十ミリ降りました。', 'あめが ごじゅうミリ ふりました。', 'Trời mưa năm mươi mi-li-mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4177, 29131, 'ゴッホの絵を見に美術館へ行きました。', 'ゴッホの えを みに びじゅつかんへ いきました。', 'Tôi đến bảo tàng mỹ thuật xem tranh Van Gogh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4178, 29145, '入学のお祝いに時計をもらいました。', 'にゅうがくの おいわいに とけいを もらいました。', 'Tôi được tặng đồng hồ làm quà mừng nhập học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4179, 29146, 'お正月に子どもたちにお年玉をあげました。', 'おしょうがつに こどもたちに おとしだまを あげました。', 'Dịp Tết tôi lì xì cho bọn trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4180, 29147, '友達のお見舞いに病院へ行きました。', 'ともだちの おみまいに びょういんへ いきました。', 'Tôi đến bệnh viện thăm bạn bị ốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4181, 29148, '日本の歴史に興味があります。', 'にほんの れきしに きょうみが あります。', 'Tôi quan tâm đến lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4182, 29152, '動物園で猿にえさをやりました。', 'どうぶつえんで さるに えさを やりました。', 'Tôi cho khỉ ăn ở sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4183, 29156, '旅行先から絵はがきを送りました。', 'りょこうさきから えはがきを おくりました。', 'Tôi gửi bưu ảnh từ nơi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4184, 29159, '寒いので、厚い靴下をはきます。', 'さむいので、あつい くつしたを はきます。', 'Trời lạnh nên tôi đi tất dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4185, 28247, 'スーツをクリーニングに出しました。', 'スーツを クリーニングに だしました。', 'Tôi mang bộ vest đi giặt ủi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4186, 29184, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4187, 29192, 'ボタンを押しました。すると、ドアが開きました。', 'ボタンを おしました。すると、ドアが あきました。', 'Tôi bấm nút. Thế là cửa mở ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4188, 29174, '田中さんは先生です。', 'たなかさんはせんせいです。', 'Anh/chị Tanaka là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4189, 29180, 'どうぞお幸せに。', 'どうぞおしあわせに。', 'Chúc hai bạn hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4190, 29198, '時計の電池を取り替えました。', 'とけいの でんちを とりかえました。', 'Tôi đã thay pin đồng hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4191, 29194, 'ここは真っ白です。', 'ここはまっしろです。', 'Ở đây trắng toát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4192, 29197, 'タクシーを呼んでください。', 'タクシーを よんで ください。', 'Hãy gọi taxi giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4193, 29165, '祖父は八十歳です。', 'そふは はちじゅっさい です。', 'Ông tôi tám mươi tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4194, 29175, 'この間、駅で先生に会いました。', 'この あいだ、えきで せんせいに あいました。', 'Hôm nọ tôi gặp thầy ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4195, 29199, '誕生日に指輪をもらいました。', 'たんじょうびに ゆびわを もらいました。', 'Sinh nhật tôi được tặng nhẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4196, 29201, 'おととし日本へ来ました。', 'おととし にほんへ きました。', 'Năm kia tôi đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4197, 29161, '娘は幼稚園に通っています。', 'むすめは ようちえんに かよって います。', 'Con gái tôi đang đi học mẫu giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4198, 29163, 'この部屋は冷房がききすぎています。', 'この へやは れいぼうが ききすぎて います。', 'Điều hòa phòng này lạnh quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4199, 29164, '部屋の温度を少し上げてください。', 'へやの おんどを すこし あげて ください。', 'Hãy tăng nhiệt độ phòng lên một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4200, 29167, '祖母は孫と遊ぶのが好きです。', 'そぼは まごと あそぶのが すき です。', 'Bà tôi thích chơi với cháu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4201, 29169, 'おじは大阪に住んでいます。', 'おじは おおさかに すんで います。', 'Chú tôi sống ở Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4202, 29170, '隣のおじさんはとても親切です。', 'となりの おじさんは とても しんせつ です。', 'Chú hàng xóm rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4203, 29171, 'おばから手紙が届きました。', 'おばから てがみが とどきました。', 'Tôi nhận được thư của cô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4246, 29287, '輸出が減ります。', 'ゆしゅつがへります。', 'Giảm, giảm xuống [xuất khẩu ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4205, 29178, '二人で映画を見に行きました。', 'ふたりで えいがを みに いきました。', 'Hai người cùng đi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4206, 29179, 'あした、お宅に伺ってもいいですか。', 'あした、おたくに うかがっても いい ですか。', 'Ngày mai tôi đến nhà anh được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4207, 29185, '弱い動物をいじめてはいけません。', 'よわい どうぶつを いじめては いけません。', 'Không được bắt nạt con vật yếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4208, 29186, '浦島太郎はかめを助けました。', 'うらしま たろうは かめを たすけました。', 'Urashima Taro đã cứu con rùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4209, 29187, '困っている人を助けました。', 'こまって いる ひとを たすけました。', 'Tôi đã giúp người đang gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4210, 29190, '祖父母は田舎で暮らしています。', 'そふぼは いなかで くらして います。', 'Ông bà tôi sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4211, 29191, 'かめは海から陸へ上がりました。', 'かめは うみから りくへ あがりました。', 'Con rùa từ biển bò lên đất liền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4212, 29195, '箱の中身は何ですか。', 'はこの なかみは なん ですか。', 'Bên trong hộp là gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4213, 29196, '浦島太郎は有名な昔話です。', 'うらしま たろうは ゆうめいな むかしばなし です。', 'Urashima Taro là truyện cổ tích nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4214, 29203, '申し訳ありません。', 'もうしわけありません。', 'Xin lỗi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4215, 29219, 'この町は自然が多くて、きれいです。', 'この まちは しぜんが おおくて、きれい です。', 'Thị trấn này có nhiều thiên nhiên, rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4216, 29214, 'ここは丈夫です。', 'ここはじょうぶです。', 'Ở đây strong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4217, 29216, '私は弁護士です。', 'わたしはべんごしです。', 'Tôi là luật sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4218, 29241, 'ある日、駅で昔の友達に会いました。', 'ある ひ、えきで むかしの ともだちに あいました。', 'Một ngày nọ, tôi gặp người bạn cũ ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4219, 29207, '大阪のお城を見に行きました。', 'おおさかの おしろを みに いきました。', 'Tôi đi xem lâu đài Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4220, 29221, '外国の文化に興味があります。', 'がいこくの ぶんかに きょうみが あります。', 'Tôi quan tâm đến văn hóa nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4221, 45811, '試合に勝って、みんな興奮していた。', 'しあいに かって、みんな こうふん して いた。', 'Thắng trận nên ai nấy đều phấn khích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4222, 29223, '政治にはあまり興味がありません。', 'せいじには あまり きょうみが ありません。', 'Tôi không quan tâm lắm đến chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4223, 29232, 'なべのふたを閉めてください。', 'なべの ふたを しめて ください。', 'Hãy đậy nắp nồi lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4224, 29240, 'カレーの材料を買いに行きます。', 'カレーの ざいりょうを かいに いきます。', 'Tôi đi mua nguyên liệu nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4225, 29242, '試験のために一生懸命勉強しました。', 'しけんの ために いっしょうけんめい べんきょう しました。', 'Tôi đã học hết sức cho kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4226, 29205, '先日はありがとうございました。', 'せんじつは ありがとう ございました。', 'Cảm ơn anh về hôm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4227, 29206, '手伝ってくれて、助かりました。', 'てつだって くれて、たすかりました。', 'Bạn giúp tôi, đỡ quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4228, 29208, 'みんなで楽しく歌いました。', 'みんなで たのしく うたいました。', 'Mọi người cùng hát vui vẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4229, 29157, 'ドライバーでねじを締めました。', 'ドライバーで ねじを しめました。', 'Tôi siết ốc bằng tua-vít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4230, 29158, 'ハンカチで汗をふきました。', 'ハンカチで あせを ふきました。', 'Tôi lau mồ hôi bằng khăn tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4231, 29210, 'お茶を入れるためにお湯を沸かします。', 'おちゃを いれる ために おゆを わかします。', 'Tôi đun nước để pha trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4232, 29211, '卵と砂糖をよく混ぜてください。', 'たまごと さとうを よく まぜて ください。', 'Hãy trộn đều trứng với đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4233, 29213, 'チケットを買うために並びました。', 'チケットを かう ために ならびました。', 'Tôi xếp hàng để mua vé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4234, 29222, '大学で社会について勉強しています。', 'だいがくで しゃかいに ついて べんきょう して います。', 'Tôi đang học về xã hội ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4235, 29233, '栓抜きでビールを開けました。', 'せんぬきで ビールを あけました。', 'Tôi mở chai bia bằng cái mở nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4236, 29234, '缶切がないので、缶詰が開けられません。', 'かんきりが ないので、かんづめが あけられません。', 'Không có đồ mở hộp nên không mở được đồ hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4237, 29237, 'ふろしきでお弁当を包みました。', 'ふろしきで おべんとうを つつみました。', 'Tôi gói cơm hộp bằng khăn furoshiki.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4238, 29238, '子どものころ、そろばんを習いました。', 'こどもの ころ、そろばんを ならいました。', 'Hồi nhỏ tôi học bàn tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4239, 29239, '体温計で熱を測りました。', 'たいおんけいで ねつを はかりました。', 'Tôi đo nhiệt độ bằng cặp nhiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4240, 29243, 'なぜ遅れたんですか。', 'なぜ おくれたん ですか。', 'Tại sao bạn đến muộn?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4241, 29245, '将来、国連で働きたいです。', 'しょうらい、こくれんで はたらきたい です。', 'Sau này tôi muốn làm việc ở Liên Hợp Quốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4242, 42530, '類似の事件が全国で起きている。', 'るいじの じけんが ぜんこくで おきて いる。', 'Các vụ việc tương tự đang xảy ra trên cả nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4243, 29249, 'ボーナスが出ます。', 'ボーナスがでます。', '[tiền thưởng] được trả', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4244, 29255, 'ご飯をどんぶりに入れます。', 'ごはんを どんぶりに いれます。', 'Cho cơm vào bát tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4245, 29269, '道に大きい石が落ちています。', 'みちに おおきい いしが おちて います。', 'Trên đường có hòn đá to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4247, 29280, '市が住民の生活について調査している。', 'しが じゅうみんの せいかつに ついて ちょうさ して いる。', 'Thành phố đang khảo sát về đời sống người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4248, 29282, 'また来てください。', 'また きて ください。', 'Lại đến chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4249, 29215, '駅の近くのアパートに住んでいます。', 'えきの ちかくの アパートに すんで います。', 'Tôi sống ở căn hộ gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4250, 29248, 'こどもニュースはわかりやすいです。', 'こども ニュースは わかりやすい です。', 'Chương trình Kodomo News rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4251, 29250, 'ケーキを半分に切りました。', 'ケーキを はんぶんに きりました。', 'Tôi cắt đôi chiếc bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4252, 29252, '忙しいときは、カップめんを食べます。', 'いそがしい ときは、カップめんを たべます。', 'Khi bận tôi ăn mì ly.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4253, 29253, 'これは世界初の技術です。', 'これは せかいはつの ぎじゅつ です。', 'Đây là công nghệ đầu tiên trên thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4254, 29256, 'このめんはとても細いです。', 'この めんは とても ほそい です。', 'Sợi mì này rất mảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4255, 29257, '日本の文化を世界に広めたいです。', 'にほんの ぶんかを せかいに ひろめたい です。', 'Tôi muốn phổ biến văn hóa Nhật ra thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4256, 29259, '卵を割って、よく混ぜてください。', 'たまごを わって、よく まぜて ください。', 'Hãy đập trứng rồi khuấy đều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4257, 29260, 'カップにお湯を注いでください。', 'カップに おゆを そそいで ください。', 'Hãy rót nước nóng vào cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4258, 29265, '二人で映画を見に行きました。', 'ふたりで えいがを みに いきました。', 'Hai người cùng đi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4259, 29267, 'この町は安全です。', 'この まちは あんぜん です。', 'Thị trấn này an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4260, 29275, 'あとは私がやります。', 'あとは わたしが やります。', 'Phần còn lại để tôi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4261, 29283, '部長の代わりに私が会議に出ました。', 'ぶちょうの かわりに わたしが かいぎに でました。', 'Tôi dự họp thay cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4262, 29284, 'このパソコンはどこででも使えます。', 'この パソコンは どこででも つかえます。', 'Máy tính này dùng được ở bất cứ đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4263, 29285, '昔は着物を着ましたが、今では洋服を着る人が多いです。', 'むかしは きものを きましたが、いまでは ようふくを きる ひとが おおい です。', 'Ngày xưa người ta mặc kimono, nhưng bây giờ nhiều người mặc đồ Tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4264, 29251, 'ローンで車を買いました。', 'ローンで くるまを かいました。', 'Tôi mua xe trả góp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4265, 29270, 'エジプトでピラミッドを見ました。', 'エジプトで ピラミッドを みました。', 'Tôi xem kim tự tháp ở Ai Cập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4266, 29271, 'パソコンのデータが消えてしまいました。', 'パソコンの データが きえて しまいました。', 'Dữ liệu trong máy tính bị mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4267, 29272, '書類をファイルに入れてください。', 'しょるいを ファイルに いれて ください。', 'Hãy cho giấy tờ vào bìa hồ sơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4268, 29273, 'ショパンはポーランドで生まれました。', 'ショパンは ポーランドで うまれました。', 'Chopin sinh ra ở Ba Lan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4269, 29274, 'ハンバーガーのセットを注文しました。', 'ハンバーガーの セットを ちゅうもん しました。', 'Tôi gọi một suất hamburger.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4270, 29276, '夜遅くカップラーメンを食べました。', 'よる おそく カップラーメンを たべました。', 'Đêm khuya tôi ăn mì cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4271, 29281, 'カップにコーヒーを入れます。', 'カップに コーヒーを いれます。', 'Tôi rót cà phê vào tách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4272, 29288, '値段が上がります。', 'ねだんがあがります。', 'Tăng, tăng lên [giá ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4273, 29289, '値段が下がります。', 'ねだんがさがります。', 'Giảm, giảm xuống [giá ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4274, 29290, 'ひもが切れます。', 'ひもがきれます。', 'Đứt [sợi dây bị ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4275, 29291, 'ボタンがとれます。', 'ボタンがとれます。', 'Tuột [cái cúc bị ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4276, 29292, '荷物が落ちます。', 'にもつおちます。', 'Rơi [hành lý bị ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4277, 29294, 'ここは変です。', 'ここはへんです。', 'Ở đây strange.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4278, 29296, 'ここは楽です。', 'ここはらくです。', 'Ở đây easy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4279, 29297, 'このりんごはうまいです。', 'このりんごはうまいです。', 'Quả táo này ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4280, 29316, 'ここは適当です。', 'ここはてきとうです。', 'Ở đây suitable.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4281, 28293, 'パーティーでみんなと踊りました。', 'パーティーで みんなと おどりました。', 'Tôi đã nhảy cùng mọi người ở bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4282, 29305, 'わあ、きれいな花ですね。', 'わあ、きれいな はな ですね。', 'Ôi, bông hoa đẹp quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4283, 29325, 'シャツが乾きます。', 'シャツがかわきます。', 'Khô', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4284, 29326, 'シャツが濡れる。', 'シャツがぬれます。', 'Ướt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4285, 29328, '事故が起きます。', 'じこがおきます。', 'Xảy ra [tai nạn ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4286, 29306, '誕生日にばらの花をもらいました。', 'たんじょうびに ばらの はなを もらいました。', 'Sinh nhật tôi được tặng hoa hồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4287, 29331, 'ここは危険です。', 'ここはきけんです。', 'Ở đây dangerous.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4288, 29332, 'このりんごは濃いです。', 'このりんごはこいです。', 'Quả táo này đậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4289, 29333, 'このりんごは薄いです。', 'このりんごはうすいです。', 'Quả táo này nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4290, 29334, 'このりんごは厚いです。', 'このりんごはあついです。', 'Quả táo này thick.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4291, 29335, 'このりんごは太いです。', 'このりんごはふといです。', 'Quả táo này thick.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4292, 45812, '今の生活に満足している。', 'いまの せいかつに まんぞく して いる。', 'Tôi hài lòng với cuộc sống hiện tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4293, 29308, '遅刻した理由を説明してください。', 'ちこく した りゆうを せつめい して ください。', 'Hãy giải thích lý do đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4294, 29312, '寒いので、暖房をつけました。', 'さむいので、だんぼうを つけました。', 'Lạnh quá nên tôi bật máy sưởi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4295, 29313, 'この部屋は冷房がききすぎています。', 'この へやは れいぼうが ききすぎて います。', 'Điều hòa phòng này lạnh quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4296, 29315, 'スポーツクラブの会員になりました。', 'スポーツクラブの かいいんに なりました。', 'Tôi đã trở thành hội viên câu lạc bộ thể thao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4297, 29321, 'これは日本語で何といいますか。', 'これは にほんごで なんと いいますか。', 'Cái này tiếng Nhật gọi là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4298, 29303, '旅行のパンフレットをもらいました。', 'りょこうの パンフレットを もらいました。', 'Tôi nhận được tờ rơi giới thiệu du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4299, 29307, '週末、海までドライブしました。', 'しゅうまつ、うみまで ドライブ しました。', 'Cuối tuần tôi lái xe đi chơi ra biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4300, 29323, 'みんなが彼の話を聞いて笑いました。', 'みんなが かれの はなしを きいて わらいました。', 'Nghe chuyện của anh ấy, mọi người đều cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4301, 29329, 'エアコンの温度を調節してください。', 'エアコンの おんどを ちょうせつ して ください。', 'Hãy điều chỉnh nhiệt độ điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4302, 29336, 'このりんごは細いです。', 'このりんごはほそいです。', 'Quả táo này thin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4303, 29338, '涙から来ました。', 'なみだからきました。', 'Tôi đến từ mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4304, 29337, '山の空気はきれいです。', 'やまの くうきは きれい です。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4305, 29339, '和食と洋食とどちらが好きですか。', 'わしょくと ようしょくと どちらが すき ですか。', 'Bạn thích món Nhật hay món Âu hơn?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4306, 29349, 'どうなさいますか。', 'どうなさいますか。', 'Tôi có thể giúp gì cho ông?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4307, 29352, 'どういうふうになさいますか。', 'どういうふうになさいますか。', 'Anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4308, 29354, '本みたいにしてください。', 'ほんみたいにしてください。', 'Xin làm giống như', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4309, 29355, 'これでよろしいでしょうか。', 'これでよろしいでしょうか。', 'Thế này được chưa ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4310, 29361, 'ここは安心です。', 'ここはあんしんです。', 'Ở đây relieved.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4311, 29366, 'このりんごは縁起が悪いです。', 'このりんごはえんぎがわるいです。', 'Quả táo này không may.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4312, 29367, 'ここは丁寧です。', 'ここはていねいです。', 'Ở đây lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4313, 29368, 'このりんごは細かいです。', 'このりんごはこまかいです。', 'Quả táo này nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4314, 29362, '気持ちを言葉で表現するのは難しい。', 'きもちを ことばで ひょうげん するのは むずかしい。', 'Diễn đạt cảm xúc bằng lời thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4315, 29358, 'また来てください。', 'また きて ください。', 'Lại đến chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4316, 29340, '朝は洋食を食べます。', 'あさは ようしょくを たべます。', 'Buổi sáng tôi ăn món Âu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4317, 29341, '今晩のおかずは何ですか。', 'こんばんの おかずは なん ですか。', 'Thức ăn tối nay là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4318, 29347, 'DVDで映画を見ました。', 'ディーブイディーで えいがを みました。', 'Tôi xem phim bằng đĩa DVD.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4319, 29348, 'ホテルひろしまに二泊しました。', 'ホテル ひろしまに にはく しました。', 'Tôi ở Khách sạn Hiroshima hai đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4320, 29357, '子どもが薬を飲むのを嫌がります。', 'こどもが くすりを のむのを いやがります。', 'Đứa trẻ không chịu uống thuốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4321, 29359, '日本語でうまく話せません。', 'にほんごで うまく はなせません。', 'Tôi không nói tiếng Nhật trôi chảy được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4322, 29360, '順序を間違えないように気をつけてください。', 'じゅんじょを まちがえない ように きを つけて ください。', 'Hãy cẩn thận đừng làm sai thứ tự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4323, 29364, '駅で友達と別れました。', 'えきで ともだちと わかれました。', 'Tôi chia tay bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4324, 29365, 'これらの本は全部図書館の本です。', 'これらの ほんは ぜんぶ としょかんの ほん です。', 'Những cuốn sách này đều là của thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4325, 29369, 'ケーキを半分に切りました。', 'ケーキを はんぶんに きりました。', 'Tôi cắt đôi chiếc bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4326, 29371, '遅刻した理由を説明してください。', 'ちこく した りゆうを せつめい して ください。', 'Hãy giải thích lý do đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4327, 29344, 'ホテルのシングルを予約しました。', 'ホテルの シングルを よやく しました。', 'Tôi đặt phòng đơn ở khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4328, 29345, 'ツインの部屋をお願いします。', 'ツインの へやを おねがい します。', 'Cho tôi một phòng đôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4329, 29351, 'このシャンプーはいいにおいがします。', 'この シャンプーは いい においが します。', 'Dầu gội này có mùi thơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4330, 29353, '髪をショートにしました。', 'かみを ショートに しました。', 'Tôi cắt tóc kiểu ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4331, 29373, 'ホテルの予約をキャンセルしました。', 'ホテルの よやくを キャンセル しました。', 'Tôi đã hủy đặt phòng khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4332, 29385, '楽しみにしています。', 'たのしみにしています。', 'Mong đợi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4333, 29387, '私は係員です。', 'わたしはかかりいんです。', 'Tôi là nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4334, 29394, '目が覚めます。', 'めがさめます。', 'Mở mắt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4336, 28297, '大切なことはメモしてください。', 'たいせつな ことは メモ して ください。', 'Điều quan trọng thì hãy ghi lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4337, 29401, '事故にあいます。', 'じこにあいます。', 'Gặp (tai nạn)', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4338, 29403, 'うまくいきます。', 'うまくいきます。', 'Tốt', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4339, 29406, '私は係です。', 'わたしはかかりです。', 'Tôi là nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4340, 29375, '保証書がないと、修理は有料です。', 'ほしょうしょが ないと、しゅうりは ゆうりょう です。', 'Không có phiếu bảo hành thì sửa phải trả tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4341, 29412, '帰って来ます。', 'かえってきます。', 'Quay về', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4342, 29413, 'バスが出ます。', 'バスがでます。', '[sách] được xuất bản', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4343, 29376, 'すみません、領収書をください。', 'すみません、りょうしゅうしょを ください。', 'Xin lỗi, cho tôi xin hóa đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4344, 29378, '台風でコンサートが中止になった。', 'たいふうで コンサートが ちゅうしに なった。', 'Buổi hòa nhạc bị hủy vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4345, 29379, 'この点について説明してください。', 'この てんに ついて せつめい して ください。', 'Hãy giải thích về điểm này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4346, 29382, '火事のときは１１９番に電話します。', 'かじの ときは ひゃくじゅうきゅうばんに でんわ します。', 'Khi có cháy hãy gọi số 119.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4347, 29383, '急に雨が降り出しました。', 'きゅうに あめが ふりだしました。', 'Trời đột nhiên đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4348, 29384, '無理に食べなくてもいいですよ。', 'むりに たべなくても いい ですよ。', 'Không cần cố ăn đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4349, 29386, '私の発表は以上です。', 'わたしの はっぴょうは いじょう です。', 'Phần trình bày của tôi xin hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4350, 29390, 'マラソン大会で三位になりました。', 'マラソン たいかいで さんいに なりました。', 'Tôi về thứ ba trong cuộc thi marathon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4351, 29392, '何か悩みがあれば、相談してください。', 'なにか なやみが あれば、そうだん して ください。', 'Nếu có điều gì phiền muộn, hãy tâm sự với tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4352, 29396, '質問への回答をメールで送ります。', 'しつもんへの かいとうを メールで おくります。', 'Tôi sẽ gửi câu trả lời qua email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4353, 29397, '目覚まし時計が鳴りました。', 'めざまし どけいが なりました。', 'Đồng hồ báo thức đã reo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4354, 29398, '目覚ましを五時にセットしました。', 'めざましを ごじに セット しました。', 'Tôi đặt báo thức lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4355, 29399, '雨が降っています。それでも、試合はあります。', 'あめが ふって います。それでも、しあいは あります。', 'Trời đang mưa. Tuy vậy, trận đấu vẫn diễn ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4356, 29402, 'パーティーの料理を用意しました。', 'パーティーの りょうりを ようい しました。', 'Tôi đã chuẩn bị đồ ăn cho bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4357, 29408, '千円札を百円玉に替えてください。', 'せんえんさつを ひゃくえんだまに かえて ください。', 'Hãy đổi tờ nghìn yên sang xu trăm yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4358, 29377, '夏休みに山でキャンプをしました。', 'なつやすみに やまで キャンプを しました。', 'Kỳ nghỉ hè tôi cắm trại trên núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4359, 29388, 'マラソンのコースは四十二キロです。', 'マラソンの コースは よんじゅうにキロ です。', 'Đường chạy marathon dài 42 km.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4360, 29389, 'マラソンは九時にスタートします。', 'マラソンは くじに スタート します。', 'Cuộc chạy marathon xuất phát lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4361, 29414, '荷物が届きます。', 'にもつがとどきます。', '[bưu phẩm] được giao đến', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4362, 29416, '大学を卒業します。', 'だいがくをそつぎょうします。', 'Tốt nghiệp [đại học]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4363, 28309, 'どの色が好きですか。', 'どの いろが すき ですか。', 'Bạn thích màu nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4364, 29418, 'パンが焼けます。', 'パンがやけます。', '[bánh mì] được nướng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4365, 29419, '肉が焼けます。', 'にくがやけます。', '[thịt] được nướng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4366, 29420, '電話しましたが、留守でした。', 'でんわ しましたが、るす でした。', 'Tôi đã gọi điện nhưng không có ai ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4367, 29417, '魚を焼いて食べました。', 'さかなを やいて たべました。', 'Tôi nướng cá để ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4368, 29428, '今いいですか。', 'いまいいですか。', 'Anh/chị có rảnh một chút không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4369, 29436, 'ついています。', 'ついています。', 'May mắn', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4370, 29448, '今いいでしょうか。', 'いまいいでしょうか。', 'Bây giờ có thể làm phiền anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4371, 29451, '情報が手に入ります。', 'じょうほうがてにはいります。', 'Có,được [thông tin]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4372, 29449, '旅行の前に、その国の知識を身につけた。', 'りょこうの まえに、その くにの ちしきを みに つけた。', 'Trước chuyến đi tôi tìm hiểu kiến thức về nước đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4373, 45817, '子供が無事だと聞いて、ほっとした。', 'こどもが ぶじだと きいて、ほっと した。', 'Nghe tin con an toàn, tôi thở phào nhẹ nhõm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4374, 29424, '駅の所で待っています。', 'えきの ところで まって います。', 'Tôi đang đợi ở chỗ ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4375, 29425, '日本に来て半年になりました。', 'にほんに きて はんとしに なりました。', 'Tôi đến Nhật được nửa năm rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4376, 29426, '今ちょうど十二時です。', 'いま ちょうど じゅうにじ です。', 'Bây giờ vừa đúng mười hai giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4377, 29427, 'たった今、田中さんが帰りました。', 'たったいま、たなかさんが かえりました。', 'Anh Tanaka vừa mới về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4378, 29431, '体の具合はどうですか。', 'からだの ぐあいは どう ですか。', 'Sức khỏe của bạn thế nào rồi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4507, 29632, '夢がかないます。', 'ゆめがかないます。', '(giấc mơ)thành hiện thực,linh ứng', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4379, 29433, '失礼ですが、どちら様でしょうか。', 'しつれい ですが、どちらさま でしょうか。', 'Xin lỗi, xin hỏi ai đấy ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4380, 29434, 'お待たせしました。どうぞ。', 'おまたせ しました。どうぞ。', 'Xin lỗi đã để quý khách chờ. Mời quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4381, 29435, '今、そちらへ向かっています。', 'いま、そちらへ むかって います。', 'Tôi đang trên đường đến chỗ anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4382, 29437, '床に本が落ちています。', 'ゆかに ほんが おちて います。', 'Trên sàn có quyển sách rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4383, 29438, '階段で転んで、けがをしました。', 'かいだんで ころんで、けがを しました。', 'Tôi ngã ở cầu thang và bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4384, 29441, '寝坊して、慌てて家を出ました。', 'ねぼう して、あわてて いえを でました。', 'Ngủ quên nên tôi vội vàng ra khỏi nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4385, 29442, '順番に並んでください。', 'じゅんばんに ならんで ください。', 'Hãy xếp hàng theo thứ tự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4386, 29444, '病院で注射をしてもらいました。', 'びょういんで ちゅうしゃを して もらいました。', 'Tôi được tiêm ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4387, 29445, 'かぜで食欲がありません。', 'かぜで しょくよくが ありません。', 'Bị cảm nên tôi không thấy thèm ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4388, 29450, 'この森は動物の宝庫です。', 'この もりは どうぶつの ほうこ です。', 'Khu rừng này là kho báu của các loài động vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4389, 29455, 'これは計画の一部分です。', 'これは けいかくの いちぶぶん です。', 'Đây là một phần của kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4390, 29458, '本が出ます。', 'ほんがでます。', '[sách] được xuất bản', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4391, 28314, '給料は毎月二十五日にもらいます。', 'きゅうりょうは まいつき にじゅうごにちに もらいます。', 'Tôi nhận lương vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4392, 29460, 'ごみが燃えます。', 'ごみがもえます。', '[rác] cháy', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4393, 29462, '人が集まります。', 'ひとがあつまります。', 'Tập hợp, tập trung [ người ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4394, 29463, '人が別れます。', 'ひとがわかれます。', 'Chia tay [ người ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4395, 29464, '音／声がします。', 'おと／こえがします。', 'Có [~ mùi ]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4396, 29465, '味がします。', 'あじがします。', 'Có [~ mùi ]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4397, 29466, 'においがします。', 'においがします。', 'Có [~ mùi ]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4398, 29467, 'このりんごは厳しいです。', 'このりんごはきびしいです。', 'Quả táo này strict.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4399, 29468, 'このりんごはひどいです。', 'このりんごはひどいです。', 'Quả táo này tồi tệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4400, 29469, 'このりんごは怖いです。', 'このりんごはこわいです。', 'Quả táo này sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4401, 29486, '話す相手がいなくて、寂しいです。', 'はなす あいてが いなくて、さびしい です。', 'Không có ai để nói chuyện nên tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4402, 29457, '彼は百メートルを十秒で走ります。', 'かれは ひゃく メートルを じゅうびょうで はしります。', 'Anh ấy chạy một trăm mét trong mười giây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4403, 29489, '世話をします。', 'せわをします。', 'Chăm sóc', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4404, 29470, '理科の授業で実験をした。', 'りかの じゅぎょうで じっけんを した。', 'Trong giờ khoa học chúng tôi làm thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4405, 29474, '科学の進歩で生活が便利になった。', 'かがくの しんぽで せいかつが べんりに なった。', 'Nhờ tiến bộ khoa học, cuộc sống trở nên tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4406, 29476, '日本の文学に興味がある。', 'にほんの ぶんがくに きょうみが ある。', 'Tôi quan tâm đến văn học Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4407, 29479, 'その意見に賛成です。', 'その いけんに さんせい です。', 'Tôi tán thành ý kiến đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4408, 29481, 'アメリカの大統領が日本へ来ました。', 'アメリカの だいとうりょうが にほんへ きました。', 'Tổng thống Mỹ đã đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4409, 29430, 'ガスレンジで料理を作ります。', 'ガスレンジで りょうりを つくります。', 'Tôi nấu ăn bằng bếp ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4410, 29439, '授業の終わりのベルが鳴りました。', 'じゅぎょうの おわりの ベルが なりました。', 'Chuông báo hết giờ học đã reo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4411, 29447, '新しいステレオで音楽を聞きます。', 'あたらしい ステレオで おんがくを ききます。', 'Tôi nghe nhạc bằng dàn âm thanh mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4412, 29452, '会社の新しいシステムを覚えました。', 'かいしゃの あたらしい システムを おぼえました。', 'Tôi đã học cách dùng hệ thống mới của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4413, 29454, 'キーワードを入力して、検索します。', 'キーワードを にゅうりょく して、けんさく します。', 'Nhập từ khóa rồi tìm kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4414, 29473, '台所からいいにおいがします。', 'だいどころから いい においが します。', 'Có mùi thơm từ bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4415, 29478, 'けが人がいたので、救急車を呼びました。', 'けがにんが いたので、きゅうきゅうしゃを よびました。', 'Có người bị thương nên tôi gọi xe cứu thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4416, 29483, '姉は来月婚約します。', 'あねは らいげつ こんやく します。', 'Tháng sau chị tôi đính hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4417, 29484, 'どうもかぜをひいたようです。', 'どうも かぜを ひいた よう です。', 'Có vẻ như tôi bị cảm rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4418, 29487, '妻とは大学で知り合いました。', 'つまとは だいがくで しりあいました。', 'Tôi quen vợ ở trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4419, 29488, '出かける前に化粧をします。', 'でかける まえに けしょうを します。', 'Trước khi ra ngoài tôi trang điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4420, 29495, '傘をさします。', 'かさをさします。', 'Dương che [ dù ]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4421, 28321, '将来、小説家になりたいです。', 'しょうらい、しょうせつかに なりたい です。', 'Sau này tôi muốn trở thành nhà văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4422, 29503, '男性と比べます。', 'だんせいとくらべます。', 'So sánh [với nam giới ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4424, 29490, 'この会社は女性の社員が多いです。', 'この かいしゃは じょせいの しゃいんが おおい です。', 'Công ty này có nhiều nhân viên nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4425, 29499, 'イランから来ました。', 'イランからきました。', 'Tôi đến từ IRAN.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4426, 29511, '世話をします。', 'せわをします。', 'Chăm sóc', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4427, 29513, 'ここは嫌です。', 'ここはいやです。', 'Ở đây không thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4428, 29515, '私は生徒です。', 'わたしはせいとです。', 'Tôi là học trò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4429, 29519, 'いいことですね。', 'いいことですね。', 'Hay nhỉ', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4430, 29491, '男性のトイレは右です。', 'だんせいの トイレは みぎ です。', 'Nhà vệ sinh nam ở bên phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4431, 29496, '天気予報によると、あしたは雨だそうです。', 'てんき よほうに よると、あしたは あめだ そう です。', 'Theo dự báo thời tiết thì ngày mai trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4432, 29498, 'バリ島へ旅行に行きました。', 'バリとうへ りょこうに いきました。', 'Tôi đã đi du lịch đảo Bali.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4433, 29502, '日本人の平均寿命は長いです。', 'にほんじんの へいきん じゅみょうは ながい です。', 'Tuổi thọ bình quân của người Nhật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4434, 29504, '彼は医学の博士です。', 'かれは いがくの はかせ です。', 'Ông ấy là tiến sĩ y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4435, 29505, 'よく寝ると、脳が休まります。', 'よく ねると、のうが やすまります。', 'Ngủ đủ giấc thì não được nghỉ ngơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4436, 29471, 'パソコンのデータが消えてしまいました。', 'パソコンの データが きえて しまいました。', 'Dữ liệu trong máy tính bị mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4437, 29477, 'パトカーがサイレンを鳴らして走っていきました。', 'パトカーが サイレンを ならして はしって いきました。', 'Xe cảnh sát hú còi chạy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4438, 29501, '夏休みにグアムへ行きました。', 'なつやすみに グアムへ いきました。', 'Kỳ nghỉ hè tôi đi Guam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4439, 29506, 'ストレスでホルモンのバランスが悪くなります。', 'ストレスで ホルモンの バランスが わるく なります。', 'Căng thẳng làm mất cân bằng hormone.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4440, 29510, '忘れ物を交番に届けました。', 'わすれものを こうばんに とどけました。', 'Tôi mang đồ bỏ quên đến đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4441, 29512, '先生の話を録音しました。', 'せんせいの はなしを ろくおん しました。', 'Tôi ghi âm lời thầy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4442, 29518, '夏休みに二週間国へ帰ります。', 'なつやすみに にしゅうかん くにへ かえります。', 'Kỳ nghỉ hè tôi về nước hai tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4443, 29521, '兄は営業の仕事をしています。', 'あには えいぎょうの しごとを して います。', 'Anh tôi làm công việc kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4444, 29522, '会議は三時からです。それまでに資料を準備してください。', 'かいぎは さんじから です。それまでに しりょうを じゅんび して ください。', 'Họp lúc ba giờ. Trước lúc đó hãy chuẩn bị tài liệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4445, 29524, '旅行を楽しんでください。', 'りょこうを たのしんで ください。', 'Chúc bạn tận hưởng chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4446, 29525, '親に心配をかけたくないです。', 'おやに しんぱいを かけたく ない です。', 'Tôi không muốn làm cha mẹ lo lắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4447, 29526, '弟はまだ小学生です。', 'おとうとは まだ しょうがくせい です。', 'Em trai tôi vẫn còn là học sinh tiểu học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4448, 29528, 'その次の電車に乗ります。', 'その つぎの でんしゃに のります。', 'Tôi sẽ đi chuyến tàu tiếp theo sau đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4449, 28326, '娘はピアノが上手です。', 'むすめは ピアノが じょうず です。', 'Con gái tôi chơi piano giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4450, 29531, 'このりんごは厳しいです。', 'このりんごはきびしいです。', 'Quả táo này nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4451, 29530, '普通の会社員です。', 'ふつうの かいしゃいん です。', 'Tôi là một nhân viên công ty bình thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4452, 29539, '代わりをします。', 'かわりをします。', 'Thay thế', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4453, 29551, 'いすに掛けます。', 'いすにかけます。', 'Ngồi xuống [ ghế]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4454, 29537, 'この建物はもともと学校でした。', 'この たてものは もともと がっこう でした。', 'Tòa nhà này vốn là trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4455, 29557, 'ご覧になります。', 'ごらんになります。', 'Xem', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4456, 29560, '温泉の旅館に二泊した。', 'おんせんの りょかんに にはく した。', 'Tôi nghỉ hai đêm ở lữ quán có suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4457, 29548, 'この寺は聖徳太子によって建てられました。', 'この てらは しょうとく たいしに よって たてられました。', 'Ngôi chùa này được xây bởi Thái tử Shotoku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4458, 29559, '朝、近所の人にあいさつします。', 'あさ、きんじょの ひとに あいさつ します。', 'Buổi sáng tôi chào hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4459, 29529, '子どものころ、習字を習っていました。', 'こどもの ころ、しゅうじを ならって いました。', 'Hồi nhỏ tôi học thư pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4460, 29533, '私は田中と申す者です。', 'わたしは たなかと もうす もの です。', 'Tôi là người tên Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4461, 29534, '入管でビザの手続きをしました。', 'にゅうかんで ビザの てつづきを しました。', 'Tôi làm thủ tục visa ở sở nhập cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4462, 29536, '久しぶりに友達に会いました。', 'ひさしぶりに ともだちに あいました。', 'Lâu lắm rồi tôi mới gặp lại bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4463, 29541, '運動会で百メートルを競走しました。', 'うんどうかいで ひゃく メートルを きょうそう しました。', 'Ở hội thao chúng tôi chạy thi một trăm mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4464, 29543, '猿がおもしろい芸を見せてくれました。', 'さるが おもしろい げいを みせて くれました。', 'Con khỉ biểu diễn tiết mục thú vị cho chúng tôi xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4508, 29637, 'お元気でいらっしゃいますか。', 'おげんきでいらっしゃいますか。', 'Anh', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4465, 29546, '心をこめて手紙を書きました。', 'こころを こめて てがみを かきました。', 'Tôi viết thư bằng cả tấm lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4466, 29547, 'その歌は若い人の心をとらえました。', 'その うたは わかい ひとの こころを とらえました。', 'Bài hát đó đã chiếm được trái tim giới trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4467, 29532, '来週のスケジュールを確認してください。', 'らいしゅうの スケジュールを かくにん して ください。', 'Hãy kiểm tra lịch trình tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4468, 29540, 'スピードを出しすぎないでください。', 'スピードを だしすぎないで ください。', 'Đừng chạy quá tốc độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4469, 29552, '週末は家族と過ごします。', 'しゅうまつは かぞくと すごします。', 'Cuối tuần tôi ở bên gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4470, 29555, '先生がおっしゃったことを覚えています。', 'せんせいが おっしゃった ことを おぼえて います。', 'Tôi vẫn nhớ những điều thầy đã nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4471, 29556, '週末は何をなさいますか。', 'しゅうまつは なにを なさいますか。', 'Cuối tuần anh làm gì ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4472, 29558, '田中さんの電話番号をご存じですか。', 'たなかさんの でんわ ばんごうを ごぞんじ ですか。', 'Anh có biết số điện thoại của anh Tanaka không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4473, 29561, 'バス停でバスを待っています。', 'バスていで バスを まって います。', 'Tôi đang đợi xe buýt ở trạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4474, 29564, 'たまに外で食事をします。', 'たまに そとで しょくじを します。', 'Thỉnh thoảng tôi ăn ở ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4475, 38245, '給料を下げたのは苦肉の策だった。', 'きゅうりょうを さげたのは くにくの さく だった。', 'Việc cắt lương là kế sách bất đắc dĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4476, 29568, '熱を出します。', 'ねつをだします。', 'Bị [sốt]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4477, 29569, 'よろしくお伝えください。', 'よろしくおつたえください。', 'Cho tôi gửi lời hỏi thăm', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4478, 28327, '娘さんはどちらの大学ですか。', 'むすめさんは どちらの だいがく ですか。', 'Con gái anh học trường đại học nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4479, 29585, '銀行に寄ります。', 'ぎんこうによります。', 'Ghé vào (ngân hàng )', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4480, 29587, '会場へ行きます。', 'かいじょうへいきます。', 'Tôi đi đến hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4481, 29567, '息子は三年二組です。', 'むすこは さんねん にくみ です。', 'Con trai tôi học lớp 3-2.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4482, 45823, '毎日料理をするのは面倒だ。', 'まいにち りょうりを するのは めんどうだ。', 'Ngày nào cũng nấu ăn thật phiền phức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4483, 29597, '将来は作家になりたい。', 'しょうらいは さっかに なりたい。', 'Sau này tôi muốn trở thành nhà văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4484, 29592, 'では、また来週。', 'では、また らいしゅう。', 'Vậy hẹn tuần sau gặp lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4485, 29570, 'では、失礼いたします。', 'では、しつれい いたします。', 'Vậy tôi xin phép ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4486, 29571, '娘はひまわり小学校に通っています。', 'むすめは ひまわり しょうがっこうに かよって います。', 'Con gái tôi học trường tiểu học Himawari.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4487, 29572, '先生の経歴を紹介します。', 'せんせいの けいれきを しょうかい します。', 'Tôi xin giới thiệu lý lịch của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4488, 29573, '兄は医学部の学生です。', 'あには いがくぶの がくせい です。', 'Anh tôi là sinh viên khoa y.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4489, 29575, '大学を出たら、大学院に進みたいです。', 'だいがくを でたら、だいがくいんに すすみたい です。', 'Học xong đại học tôi muốn học lên cao học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4490, 29577, 'この会社は新しい薬を開発しています。', 'この かいしゃは あたらしい くすりを かいはつ して います。', 'Công ty này đang nghiên cứu phát triển thuốc mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4491, 29580, '彼はノーベル賞を授賞しました。', 'かれは ノーベルしょうを じゅしょう しました。', 'Ông ấy đã được trao giải Nobel.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4492, 29582, '山中伸弥先生はノーベル賞をもらいました。', 'やまなか しんや せんせいは ノーベルしょうを もらいました。', 'Giáo sư Yamanaka Shinya đã nhận giải Nobel.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4493, 29583, 'ノーベル賞をもらった日本人はたくさんいます。', 'ノーベルしょうを もらった にほんじんは たくさん います。', 'Có nhiều người Nhật đã nhận giải Nobel.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4494, 29586, '灰皿はどこにありますか。', 'はいざらは どこに ありますか。', 'Gạt tàn thuốc ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4495, 29588, '父は貿易の会社で働いています。', 'ちちは ぼうえきの かいしゃで はたらいて います。', 'Bố tôi làm ở công ty thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4496, 29590, 'この映画はちっともおもしろくなかったです。', 'この えいがは ちっとも おもしろく なかった です。', 'Bộ phim này chẳng hay chút nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4497, 29591, '質問があれば、遠慮なく聞いてください。', 'しつもんが あれば、えんりょ なく きいて ください。', 'Nếu có câu hỏi, xin đừng ngại hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4498, 29594, '多くの人がこの本を読んでいます。', 'おおくの ひとが この ほんを よんで います。', 'Nhiều người đang đọc cuốn sách này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4499, 29596, '彼は世界的に有名な音楽家です。', 'かれは せかいてきに ゆうめいな おんがくか です。', 'Ông ấy là nhạc sĩ nổi tiếng thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4500, 29598, 'こちらは山田先生でいらっしゃいます。', 'こちらは やまだ せんせいで いらっしゃいます。', 'Đây là thầy Yamada ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4501, 29599, '長男は大学生です。', 'ちょうなんは だいがくせい です。', 'Con trai cả của tôi là sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4502, 28332, 'この部屋は広いです。それに、駅から近いです。', 'この へやは ひろい です。それに、えきから ちかい です。', 'Căn phòng này rộng. Ngoài ra còn gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4503, 29618, 'パーティーの料理を用意しました。', 'パーティーの りょうりを ようい しました。', 'Tôi đã chuẩn bị đồ ăn cho bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4504, 29616, 'お目にかかります。', 'おめにかかります。', 'Gặp', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4510, 29602, '彼は映画の音楽を作曲しています。', 'かれは えいがの おんがくを さっきょく して います。', 'Anh ấy sáng tác nhạc cho phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4511, 29603, 'ボランティア活動に参加しています。', 'ボランティア かつどうに さんか して います。', 'Tôi đang tham gia hoạt động tình nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4512, 29604, 'それでは、会議を始めます。', 'それでは、かいぎを はじめます。', 'Thế thì chúng ta bắt đầu cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4513, 29606, '兄は東京大学で研究しています。', 'あには とうきょう だいがくで けんきゅう して います。', 'Anh tôi đang nghiên cứu ở Đại học Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4514, 29607, '川端康成は日本人で初めてノーベル文学賞をもらいました。', 'かわばた やすなりは にほんじんで はじめて ノーベル ぶんがくしょうを もらいました。', 'Kawabata Yasunari là người Nhật đầu tiên nhận giải Nobel văn học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4515, 29578, 'マウスでクリックしてください。', 'マウスで クリック して ください。', 'Hãy nhấp bằng chuột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4516, 29609, '父は今、家におります。', 'ちちは いま、いえに おります。', 'Bố tôi hiện đang ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4517, 29611, '初めまして。リンと申します。', 'はじめまして。リンと もうします。', 'Rất hân hạnh. Tôi tên là Linh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4518, 29613, 'お手紙を拝見しました。', 'おてがみを はいけん しました。', 'Tôi đã đọc thư của anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4519, 29614, 'その件はよく存じております。', 'その けんは よく ぞんじて おります。', 'Việc đó tôi biết rõ ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4520, 29623, 'さ来週、試験があります。', 'さらいしゅう、しけんが あります。', 'Tuần tới nữa có kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4521, 29624, 'さ来月、国へ帰ります。', 'さらいげつ、くにへ かえります。', 'Tháng tới nữa tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4522, 29625, 'さ来年、大学を卒業します。', 'さらいねん、だいがくを そつぎょう します。', 'Năm tới nữa tôi tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4523, 29628, '面接の前はとても緊張しました。', 'めんせつの まえは とても きんちょう しました。', 'Trước buổi phỏng vấn tôi rất hồi hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4524, 29630, '動物園できりんを見ました。', 'どうぶつえんで きりんを みました。', 'Tôi xem hươu cao cổ ở sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4525, 29631, '子どものころ、よく川で遊びました。', 'こどもの ころ、よく かわで あそびました。', 'Hồi nhỏ tôi hay chơi ở sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4526, 29633, 'みんなで日本チームを応援しました。', 'みんなで にほん チームを おうえん しました。', 'Mọi người cùng cổ vũ đội Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4527, 29634, '心から感謝しています。', 'こころから かんしゃ して います。', 'Tôi chân thành biết ơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4528, 29636, 'お世話になった先生にお礼を言いました。', 'おせわに なった せんせいに おれいを いいました。', 'Tôi nói lời cảm ơn thầy đã giúp đỡ mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4529, 28338, '会社からお知らせが届きました。', 'かいしゃから おしらせが とどきました。', 'Có thông báo từ công ty gửi đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4530, 29649, 'ただ今は学生です。', 'ただいまはがくせいです。', 'Tôi đã về ! là học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4531, 29651, 'ビデオに撮ります。', 'ビデオにとります。', 'Thu, quay', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4532, 29654, 'ひとことよろしいでしょうか。', 'ひとことよろしいでしょうか。', 'Cho tôi nói một lời', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4533, 29646, '日本に来て半年になりました。', 'にほんに きて はんとしに なりました。', 'Tôi đến Nhật được nửa năm rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4534, 29639, '日本で習ったことを仕事に生かしたいです。', 'にほんで ならった ことを しごとに いかしたい です。', 'Tôi muốn phát huy những gì học được ở Nhật vào công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4535, 29642, 'こちらが会議室でございます。', 'こちらが かいぎしつで ございます。', 'Đây là phòng họp ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4536, 30681, '外国人観光客が増えている。', 'がいこくじんかんこうきゃくがふえている。', 'Khách du lịch nước ngoài đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4537, 29647, '最初に名前を書いてください。', 'さいしょに なまえを かいて ください。', 'Trước hết hãy viết tên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4538, 30686, 'せっかく来たのに、店は閉まっていた。', 'せっかくきたのに、みせはしまっていた。', 'Cất công đến mà quán đóng cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4539, 29648, '最後に、皆さんにお礼を申し上げます。', 'さいごに、みなさんに おれいを もうしあげます。', 'Cuối cùng, tôi xin cảm ơn tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4540, 29655, '皆さんのご協力をお願いします。', 'みなさんの ごきょうりょくを おねがい します。', 'Mong mọi người hợp tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4541, 29656, '手紙は「拝啓」で始めます。', 'てがみは 「はいけい」で はじめます。', 'Thư được mở đầu bằng "Kính gửi".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4542, 29620, 'ガイドさんがお寺を案内してくれました。', 'ガイドさんが おてらを あんない して くれました。', 'Hướng dẫn viên dẫn chúng tôi tham quan chùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4543, 29621, 'メールアドレスを教えてください。', 'メールアドレスを おしえて ください。', 'Hãy cho tôi địa chỉ email của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4544, 29622, '来週のスケジュールを確認してください。', 'らいしゅうの スケジュールを かくにん して ください。', 'Hãy kiểm tra lịch trình tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4545, 30696, '結局、彼は来なかった。', 'けっきょく、かれはこなかった。', 'Rốt cuộc anh ấy không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4546, 29645, '昔のアルバムを見ました。', 'むかしの アルバムを みました。', 'Tôi xem lại album ảnh cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4547, 30679, '好きな色を一つ選んでください。', 'すきな いろを ひとつ えらんで ください。', 'Hãy chọn một màu bạn thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4548, 30683, 'この町は十年でずいぶん変化しました。', 'この まちは じゅうねんで ずいぶん へんか しました。', 'Thị trấn này đã thay đổi nhiều trong mười năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4549, 30688, '三年かかって、とうとう家を買いました。', 'さんねん かかって、とうとう いえを かいました。', 'Mất ba năm, cuối cùng tôi cũng mua được nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4550, 30691, '実は、来月会社を辞めるんです。', 'じつは、らいげつ かいしゃを やめるんです。', 'Thật ra là tháng sau tôi sẽ nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4551, 30693, 'この工場では主に車の部品を作っています。', 'この こうじょうでは おもに くるまの ぶひんを つくって います。', 'Nhà máy này chủ yếu sản xuất linh kiện ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4552, 38613, '友達とおしゃべりしていたら、もう夜になっていた。', 'ともだちと おしゃべり して いたら、もう よるに なって いた。', 'Mải buôn chuyện với bạn, đã tối lúc nào không hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4553, 45825, '彼女はお母さんによく似ている。', 'かのじょは おかあさんに よく にて いる。', 'Cô ấy rất giống mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4554, 29653, '動物園に象がいます。', 'どうぶつえんに ぞうが います。', 'Trong sở thú có voi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4555, 28341, 'お店は月曜日から土曜日まで開いています。', 'おみせは げつようびから どようびまで あいて います。', 'Cửa hàng mở cửa từ thứ Hai đến thứ Bảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4556, 30699, '母によろしくお伝えください。', 'ははによろしくおつたえください。', 'Cho tôi gửi lời hỏi thăm mẹ bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4557, 30702, '先生に進路を相談した。', 'せんせいにしんろをそうだんした。', 'Tôi đã xin thầy tư vấn về hướng đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4558, 30723, '娘は母親にそっくりだ。', 'むすめはははおやにそっくりだ。', 'Con gái giống hệt mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4559, 30730, '今日は残業しなければならない。', 'きょうはざんぎょうしなければならない。', 'Hôm nay tôi phải tăng ca.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4560, 38619, '試合に負けて、みんながっかりしました。', 'しあいに まけて、みんな がっかり しました。', 'Thua trận nên ai cũng thất vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4561, 38622, 'かわいらしい花が庭に咲いています。', 'かわいらしい はなが にわに さいて います。', 'Trong vườn nở những bông hoa xinh xắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4562, 38623, 'このズボンは少しきついです。', 'この ズボンは すこし きついです。', 'Cái quần này hơi chật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4563, 38625, 'グラスにワインを注ぎました。', 'グラスに ワインを つぎました。', 'Tôi rót rượu vang vào ly.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4564, 38627, '眼鏡をケースに入れてください。', 'めがねを ケースに いれて ください。', 'Hãy cho kính vào hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4565, 38629, 'コーチの指導で、泳ぐのが速くなった。', 'コーチの しどうで、およぐのが はやく なった。', 'Nhờ huấn luyện viên chỉ dạy, tôi bơi nhanh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4566, 30701, '遅れるときは、必ず連絡してください。', 'おくれる ときは、かならず れんらく して ください。', 'Khi đến muộn, nhất định phải liên lạc nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4567, 30706, '友達と三時に会う約束があります。', 'ともだちと さんじに あう やくそくが あります。', 'Tôi có hẹn gặp bạn lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4568, 30721, '彼はマラソンで新しい記録を出した。', 'かれは マラソンで あたらしい きろくを だした。', 'Anh ấy đã lập kỷ lục mới ở môn marathon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4569, 30724, 'このくつはサイズがぴったりです。', 'この くつは サイズが ぴったり です。', 'Đôi giày này vừa khít cỡ chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4570, 30726, 'なんとなく彼女が元気がないように見えた。', 'なんとなく かのじょが げんきが ない ように みえた。', 'Không hiểu sao tôi thấy cô ấy có vẻ không khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4571, 38635, 'シャワーを浴びて、さっぱりした。', 'シャワーを あびて、さっぱり した。', 'Tắm xong thấy sảng khoái hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4572, 38639, 'この店は安くて、しかもおいしい。', 'この みせは やすくて、しかも おいしい。', 'Quán này rẻ, mà lại còn ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4573, 38640, '彼はしきりに時計を見ていた。', 'かれは しきりに とけいを みて いた。', 'Anh ấy cứ liên tục nhìn đồng hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4574, 38642, '猫が窓の外をじっと見ている。', 'ねこが まどの そとを じっと みて いる。', 'Con mèo đang chăm chú nhìn ra ngoài cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4575, 38644, 'じゃあ、また明日。', 'じゃあ、また あした。', 'Vậy hẹn mai gặp lại nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4576, 38630, 'パソコンのコードが短くて届かない。', 'パソコンの コードが みじかくて とどかない。', 'Dây máy tính ngắn quá, không với tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4577, 38633, 'ここにサインをお願いします。', 'ここに サインを おねがい します。', 'Xin vui lòng ký vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4578, 38646, '冬になると、湖でスケートができます。', 'ふゆに なると、みずうみで スケートが できます。', 'Đến mùa đông có thể trượt băng trên hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4579, 30733, '会議の資料をコピーしておいてください。', 'かいぎの しりょうを コピー して おいて ください。', 'Hãy photo sẵn tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4580, 30737, '仕事のあと、同僚と飲みに行った。', 'しごとの あと、どうりょうと のみに いった。', 'Tan làm, tôi đi uống với đồng nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4581, 45826, 'わざと負けたわけではない。', 'わざと まけた わけでは ない。', 'Không phải tôi cố tình thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4582, 28348, '日本の習慣はまだよくわかりません。', 'にほんの しゅうかんは まだ よく わかりません。', 'Tôi vẫn chưa hiểu rõ phong tục Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4583, 30744, 'ここは駐車禁止です。', 'ここはちゅうしゃきんしです。', 'Ở đây cấm đỗ xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4584, 30749, '残念ですが、お断りします。', 'ざんねんですが、おことわりします。', 'Rất tiếc, tôi xin từ chối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4585, 30761, '環境を守ることは大切だ。', 'かんきょうをまもることはたいせつだ。', 'Bảo vệ môi trường là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4586, 30775, '時間を無駄にしたくない。', 'じかんをむだにしたくない。', 'Tôi không muốn lãng phí thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4587, 30742, 'アパートの契約は二年です。', 'アパートの けいやくは にねん です。', 'Hợp đồng thuê căn hộ là hai năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4588, 30745, '社長の命令なら、従うしかない。', 'しゃちょうの めいれいなら、したがう しか ない。', 'Nếu là lệnh của giám đốc thì chỉ còn cách tuân theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4589, 30748, '悪いと思ったら、すぐに謝りなさい。', 'わるいと おもったら、すぐに あやまりなさい。', 'Nếu thấy mình sai thì xin lỗi ngay đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4590, 30752, '約束は必ず守ります。', 'やくそくは かならず まもります。', 'Tôi nhất định sẽ giữ lời hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4591, 30756, 'この仕事には英語の能力が必要です。', 'この しごとには えいごの のうりょくが ひつよう です。', 'Công việc này cần năng lực tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4592, 38649, '日本の首都、すなわち東京に住んでいます。', 'にほんの しゅと、すなわち とうきょうに すんで います。', 'Tôi sống ở thủ đô Nhật Bản, tức là Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4593, 38653, '人にはそれぞれ考え方がある。', 'ひとには それぞれ かんがえかたが ある。', 'Mỗi người có một cách nghĩ riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4594, 38656, '行きたい。だけど、時間がない。', 'いきたい。だけど、じかんが ない。', 'Muốn đi lắm. Nhưng mà không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4595, 38659, 'その本、ちょっと見せてちょうだい。', 'その ほん、ちょっと みせて ちょうだい。', 'Cho mình xem quyển sách đó chút nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4596, 38662, 'どうかよろしくお願いします。', 'どうか よろしく おねがい します。', 'Xin hãy giúp đỡ tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4597, 38652, 'ソファーに座ってテレビを見た。', 'ソファーに すわって テレビを みた。', 'Tôi ngồi trên ghế sofa xem tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4598, 38660, '駅前で大きなデモが行われた。', 'えきまえで おおきな デモが おこなわれた。', 'Một cuộc biểu tình lớn đã diễn ra trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4599, 30763, '子供の教育にはお金がかかる。', 'こどもの きょういくには おかねが かかる。', 'Việc giáo dục con cái tốn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4600, 30765, 'この地域は自動車産業が盛んです。', 'この ちいきは じどうしゃさんぎょうが さかん です。', 'Vùng này phát triển mạnh ngành công nghiệp ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4601, 30769, '野菜の価格が上がっている。', 'やさいの かかくが あがって いる。', 'Giá rau đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4602, 30771, '給料から税金が引かれる。', 'きゅうりょうから ぜいきんが ひかれる。', 'Thuế bị trừ vào lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4603, 30773, 'やっと借金を全部返した。', 'やっと しゃっきんを ぜんぶ かえした。', 'Cuối cùng tôi cũng trả hết nợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4604, 30776, 'この町は観光で大きく発展した。', 'この まちは かんこうで おおきく はってん した。', 'Thị trấn này phát triển mạnh nhờ du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4605, 30779, '話し合いで問題を解決しましょう。', 'はなしあいで もんだいを かいけつ しましょう。', 'Hãy giải quyết vấn đề bằng cách bàn bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4606, 30782, '現状では、計画を進めるのは難しい。', 'げんじょうでは、けいかくを すすめるのは むずかしい。', 'Với hiện trạng này, khó mà triển khai kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4607, 30785, '兄は背が高い。一方、弟は低い。', 'あには せが たかい。いっぽう、おとうとは ひくい。', 'Anh trai thì cao. Mặt khác, em trai lại thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4608, 38664, '晴れると思っていた。ところが、急に雨が降り出した。', 'はれると おもって いた。ところが、きゅうに あめが ふりだした。', 'Tôi tưởng trời sẽ nắng. Thế nhưng bỗng đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4609, 28349, 'マンションの管理人に相談しました。', 'マンションの かんりにんに そうだん しました。', 'Tôi đã trao đổi với người quản lý chung cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4610, 30982, '今年は売り上げの増加が顕著だ。', 'ことしは うりあげの ぞうかが けんちょだ。', 'Năm nay doanh thu tăng rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4611, 30985, '画一的な教育では個性が育たない。', 'かくいつてきな きょういくでは こせいが そだたない。', 'Giáo dục rập khuôn thì cá tính không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4612, 30975, '賃金の交渉が難航している。', 'ちんぎんのこうしょうがなんこうしている。', 'Đàm phán lương đang bế tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4613, 38670, '会議は三時からです。なお、場所は二階に変わりました。', 'かいぎは さんじから です。なお、ばしょは にかいに かわりました。', 'Cuộc họp bắt đầu lúc ba giờ. Ngoài ra, địa điểm đã đổi lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4614, 38673, '彼女は私を見て、にっこり笑った。', 'かのじょは わたしを みて、にっこり わらった。', 'Cô ấy nhìn tôi và mỉm cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4615, 38676, '駅で昔の友達にばったり会った。', 'えきで むかしの ともだちに ばったり あった。', 'Tôi tình cờ gặp bạn cũ ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4616, 38680, 'ふと窓の外を見ると、雪が降っていた。', 'ふと まどの そとを みると、ゆきが ふって いた。', 'Bất chợt nhìn ra cửa sổ thì thấy tuyết đang rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4617, 38666, '結婚式で白いドレスを着た。', 'けっこんしきで しろい ドレスを きた。', 'Tôi mặc váy trắng trong lễ cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4618, 38677, '新しい先生はハンサムで人気がある。', 'あたらしい せんせいは ハンサムで にんきが ある。', 'Thầy giáo mới đẹp trai nên được yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4619, 30788, '事故のせいで、道が渋滞している。', 'じこの せいで、みちが じゅうたい して いる。', 'Vì tai nạn mà đường đang tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4620, 30791, '壊れた時計を修理に出した。', 'こわれた とけいを しゅうりに だした。', 'Tôi đã mang chiếc đồng hồ hỏng đi sửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4621, 45832, '新しい商品が来月発売されます。', 'あたらしい しょうひんが らいげつ はつばい されます。', 'Sản phẩm mới sẽ được bán ra vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4622, 45841, '給料から税金が引かれる。', 'きゅうりょうから ぜいきんが ひかれる。', 'Thuế bị trừ vào lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4623, 45845, '調査の結果を部長に報告しました。', 'ちょうさの けっかを ぶちょうに ほうこく しました。', 'Tôi đã báo cáo kết quả khảo sát cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4624, 45849, '失敗の責任は私にあります。', 'しっぱいの せきにんは わたしに あります。', 'Trách nhiệm cho thất bại thuộc về tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4625, 45831, '大きな企業で働きたい。', 'おおきな きぎょうで はたらきたい。', 'Tôi muốn làm việc ở doanh nghiệp lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4626, 45834, 'このパンは駅の売店でも販売しています。', 'この パンは えきの ばいてんでも はんばい して います。', 'Loại bánh mì này cũng được bán ở quầy trong ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4627, 45844, 'お会計はレジでお願いします。', 'おかいけいは レジで おねがい します。', 'Xin vui lòng thanh toán tại quầy thu ngân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4628, 45830, '職場の人たちはみんな親切だ。', 'しょくばの ひとたちは みんな しんせつだ。', 'Mọi người ở chỗ làm đều tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4629, 45836, '今年は会社の利益が増えた。', 'ことしは かいしゃの りえきが ふえた。', 'Năm nay lợi nhuận công ty tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4630, 45838, '早く予約すると得だ。', 'はやく よやく すると とくだ。', 'Đặt sớm thì có lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4631, 45843, '給料について会社と交渉した。', 'きゅうりょうに ついて かいしゃと こうしょう した。', 'Tôi đã đàm phán lương với công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4632, 45850, '上司の指示どおりに作業を進めた。', 'じょうしの しじ どおりに さぎょうを すすめた。', 'Tôi tiến hành công việc theo chỉ thị của cấp trên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4633, 30976, '二つの意見が対立している。', 'ふたつの いけんが たいりつ して いる。', 'Hai ý kiến đang đối lập nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4634, 28315, 'ボーナスで新しいパソコンを買います。', 'ボーナスで あたらしい パソコンを かいます。', 'Tôi sẽ dùng tiền thưởng mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4635, 31064, '彼の主張は最初から一貫している。', 'かれの しゅちょうは さいしょから いっかん して いる。', 'Lập luận của anh ấy nhất quán từ đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4636, 30941, '価格が大幅に下がった。', 'かかくがおおはばにさがった。', 'Giá giảm đáng kể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4637, 30799, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4638, 30801, 'レポートは金曜日までに提出してください。', 'レポートは きんようびまでに ていしゅつ して ください。', 'Hãy nộp báo cáo trước thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4639, 30804, '新しい道ができて、通勤時間が短縮された。', 'あたらしい みちが できて、つうきんじかんが たんしゅく された。', 'Có đường mới nên thời gian đi làm được rút ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4640, 30806, 'サイズが合わなかったので、返品した。', 'サイズが あわなかったので、へんぴん した。', 'Không vừa cỡ nên tôi đã trả lại hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4641, 30808, '荷物は明日の午前中に配達されます。', 'にもつは あしたの ごぜんちゅうに はいたつ されます。', 'Hàng sẽ được giao vào sáng mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4642, 30810, '使った物はきちんと片付けてください。', 'つかった ものは きちんと かたづけて ください。', 'Đồ đã dùng thì hãy cất dọn ngăn nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4643, 38688, '工事はほぼ終わりました。', 'こうじは ほぼ おわりました。', 'Công trình gần như đã xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4644, 38690, 'まあ、そんなに怒らないで。', 'まあ、そんなに おこらないで。', 'Thôi nào, đừng giận như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4645, 38692, 'これこそ、まさに私が探していた本だ。', 'これこそ、まさに わたしが さがして いた ほんだ。', 'Đây đúng là quyển sách tôi đang tìm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4646, 38681, '旅行のプランを一緒に考えましょう。', 'りょこうの プランを いっしょに かんがえましょう。', 'Cùng nhau lên kế hoạch du lịch nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4647, 38683, '彼はプロのカメラマンです。', 'かれは プロの カメラマン です。', 'Anh ấy là nhiếp ảnh gia chuyên nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4648, 38685, '壁を白いペンキで塗った。', 'かべを しろい ペンキで ぬった。', 'Tôi sơn tường bằng sơn trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4649, 38687, '三番線のホームで待っています。', 'さんばんせんの ホームで まって います。', 'Tôi đang đợi ở sân ga số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4650, 38696, '小さなミスが大きな問題になった。', 'ちいさな ミスが おおきな もんだいに なった。', 'Một sai sót nhỏ đã thành vấn đề lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4651, 45854, '父は来年退職する予定だ。', 'ちちは らいねん たいしょく する よていだ。', 'Bố tôi dự định nghỉ hưu vào năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4652, 30939, '売り上げが減った要因を調べている。', 'うりあげが へった よういんを しらべて いる。', 'Chúng tôi đang tìm hiểu nhân tố khiến doanh thu giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4653, 30943, '病気は徐々によくなっている。', 'びょうきは じょじょに よく なって いる。', 'Bệnh đang dần dần khá lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4654, 30944, '空が次第に明るくなってきた。', 'そらが しだいに あかるく なって きた。', 'Bầu trời dần dần sáng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4655, 30947, '長年の夢がついに実現した。', 'ながねんの ゆめが ついに じつげん した。', 'Ước mơ bao năm cuối cùng đã thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4656, 30949, '計画を立てるだけでなく、実行することが大切だ。', 'けいかくを たてる だけで なく、じっこう する ことが たいせつだ。', 'Không chỉ lập kế hoạch mà thực hiện mới quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4657, 30952, '今年は会話の練習に重点を置いている。', 'ことしは かいわの れんしゅうに じゅうてんを おいて いる。', 'Năm nay tôi đặt trọng điểm vào luyện hội thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4658, 30955, 'この店のケーキはことにおいしい。', 'この みせの ケーキは ことに おいしい。', 'Bánh ngọt ở tiệm này đặc biệt ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4659, 31066, '状況に応じて柔軟に対応しよう。', 'じょうきょうに おうじて じゅうなんに たいおう しよう。', 'Hãy ứng phó linh hoạt tùy theo tình hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4660, 31068, '祖父は厳格な人だった。', 'そふは げんかくな ひと だった。', 'Ông tôi là người nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4661, 41932, 'この言葉の定義を確認しよう。', 'この ことばの ていぎを かくにん しよう。', 'Hãy xác nhận định nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4662, 45856, '給与は毎月二十五日に振り込まれる。', 'きゅうよは まいつき にじゅうごにちに ふりこまれる。', 'Lương được chuyển khoản vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4663, 31101, '地球の温暖化が進んでいる。', 'ちきゅうの おんだんかが すすんで いる。', 'Trái đất đang ngày càng nóng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4664, 31123, 'その問題について議論が続いている。', 'その もんだいに ついて ぎろんが つづいて いる。', 'Cuộc tranh luận về vấn đề đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4665, 31149, '誰にでも意見を言う権利がある。', 'だれにでも いけんを いう けんりが ある。', 'Ai cũng có quyền nêu ý kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4666, 31079, '大きなミスをして、課長から降格された。', 'おおきな ミスを して、かちょうから こうかく された。', 'Mắc lỗi lớn nên ông ấy bị giáng chức từ trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4667, 31084, '手続きを弁護士に委任した。', 'てつづきを べんごしに いにん した。', 'Tôi đã ủy nhiệm thủ tục cho luật sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4668, 31086, '拾った財布を交番に届けた。', 'ひろった さいふを こうばんに とどけた。', 'Tôi mang chiếc ví nhặt được đến đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4669, 31089, '兄は市役所の公務員だ。', 'あには しやくしょの こうむいんだ。', 'Anh tôi là công chức ở tòa thị chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4670, 31095, '昔、この町では公害が大きな問題になった。', 'むかし、この まちでは こうがいが おおきな もんだいに なった。', 'Ngày trước ô nhiễm từng là vấn đề lớn ở thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4671, 31102, 'この紙は再生紙から作られている。', 'この かみは さいせいしから つくられて いる。', 'Loại giấy này được làm từ giấy tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4672, 31104, '統計によると、日本の人口は減り続けている。', 'とうけいに よると、にほんの じんこうは へり つづけて いる。', 'Theo thống kê, dân số Nhật tiếp tục giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4673, 31107, 'このクラスは女性の割合が高い。', 'この クラスは じょせいの わりあいが たかい。', 'Lớp này tỷ lệ nữ cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4674, 31093, '太陽のエネルギーを利用して電気を作る。', 'たいようの エネルギーを りよう して でんきを つくる。', 'Tận dụng năng lượng mặt trời để sản xuất điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4675, 31125, '彼の発言は世間から非難を浴びた。', 'かれの はつげんは せけんから ひなんを あびた。', 'Phát ngôn của ông ta hứng chịu chỉ trích của dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4676, 31128, '記者が大臣に質問した。', 'きしゃが だいじんに しつもん した。', 'Phóng viên đặt câu hỏi cho bộ trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4677, 31129, '旅行のビデオを編集した。', 'りょこうの ビデオを へんしゅう した。', 'Tôi đã biên tập video chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4678, 31134, '両社は業務提携の契約を締結した。', 'りょうしゃは ぎょうむ ていけいの けいやくを ていけつ した。', 'Hai công ty đã ký kết hợp đồng hợp tác kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4679, 31137, '刑事が事件の現場を調べている。', 'けいじが じけんの げんばを しらべて いる。', 'Cảnh sát hình sự đang điều tra hiện trường vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4680, 31140, '裁判の結果は来月出る。', 'さいばんの けっかは らいげつ でる。', 'Kết quả xét xử sẽ có vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4681, 31141, '裁判所は無罪の判決を下した。', 'さいばんしょは むざいの はんけつを くだした。', 'Tòa án đã tuyên án vô tội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4682, 31144, '男は窃盗の容疑で逮捕された。', 'おとこは せっとうの ようぎで たいほ された。', 'Người đàn ông bị bắt vì nghi trộm cắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4683, 31147, '事故の被害者に補償金が支払われた。', 'じこの ひがいしゃに ほしょうきんが しはらわれた。', 'Tiền bồi thường đã được trả cho nạn nhân vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4684, 31192, 'いろいろな意見を総合して判断した。', 'いろいろな いけんを そうごう して はんだん した。', 'Tôi tổng hợp nhiều ý kiến rồi đưa ra phán đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4685, 31199, '科学者は真理を探究し続けている。', 'かがくしゃは しんりを たんきゅう し つづけて いる。', 'Các nhà khoa học không ngừng tìm tòi chân lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4686, 31203, '失敗して初めて自分の未熟さを悟った。', 'しっぱい して はじめて じぶんの みじゅくさを さとった。', 'Thất bại rồi tôi mới nhận ra mình còn non nớt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4687, 31207, '子供の視点から町を見直してみよう。', 'こどもの してんから まちを みなおして みよう。', 'Hãy thử nhìn lại thành phố từ góc nhìn của trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4688, 31209, '議論の焦点は費用の問題に移った。', 'ぎろんの しょうてんは ひようの もんだいに うつった。', 'Tiêu điểm của cuộc tranh luận đã chuyển sang vấn đề chi phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4689, 31242, '彼は質問に即座に答えた。', 'かれは しつもんに そくざに こたえた。', 'Anh ấy trả lời câu hỏi ngay lập tức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4690, 31245, 'ここはかつて城があった場所だ。', 'ここは かつて しろが あった ばしょだ。', 'Đây là nơi từng có một tòa lâu đài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4691, 31247, '問題を根本から見直す必要がある。', 'もんだいを こんぽんから みなおす ひつようが ある。', 'Cần xem xét lại vấn đề từ căn bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4692, 31250, '使ったものは自分で始末してください。', 'つかった ものは じぶんで しまつ して ください。', 'Đồ đã dùng hãy tự xử lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4693, 45410, 'お客様に失礼な態度をとってはいけません。', 'おきゃくさまに しつれいな たいどを とっては いけません。', 'Không được có thái độ thất lễ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4694, 45418, '毎日努力した結果、試験に合格できました。', 'まいにち どりょくした けっか、しけんに ごうかく できました。', 'Nhờ nỗ lực mỗi ngày mà tôi đã thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4695, 45456, '試合に負けて、みんながっかりしました。', 'しあいに まけて、みんな がっかり しました。', 'Thua trận nên ai cũng thất vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4696, 45480, '留学の費用はどのくらいかかりますか。', 'りゅうがくの ひようは どのくらい かかりますか。', 'Chi phí du học khoảng bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4697, 45482, 'アパートの契約は二年です。', 'アパートの けいやくは にねん です。', 'Hợp đồng thuê căn hộ là hai năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4698, 45485, '調査の結果を部長に報告しました。', 'ちょうさの けっかを ぶちょうに ほうこく しました。', 'Tôi đã báo cáo kết quả khảo sát cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4699, 45488, 'この仕事は田中さんが担当しています。', 'この しごとは たなかさんが たんとう して います。', 'Công việc này do anh Tanaka phụ trách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4700, 45489, '失敗の責任は私にあります。', 'しっぱいの せきにんは わたしに あります。', 'Trách nhiệm cho thất bại thuộc về tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4701, 45857, '姉は銀行に勤務している。', 'あねは ぎんこうに きんむ して いる。', 'Chị tôi làm việc ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4702, 31154, '図書館の本はテーマごとに分類されている。', 'としょかんの ほんは テーマごとに ぶんるい されて いる。', 'Sách thư viện được phân loại theo chủ đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4703, 31160, '計画はまだ準備の段階だ。', 'けいかくは まだ じゅんびの だんかいだ。', 'Kế hoạch vẫn đang ở giai đoạn chuẩn bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4704, 31162, '大きな組織で働くのは大変だ。', 'おおきな そしきで はたらくのは たいへんだ。', 'Làm việc trong một tổ chức lớn thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4705, 31164, '机の上を整理してから帰りなさい。', 'つくえの うえを せいり してから かえりなさい。', 'Sắp xếp gọn bàn rồi hãy về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4706, 31170, '二人には共通の趣味がある。', 'ふたりには きょうつうの しゅみが ある。', 'Hai người có sở thích chung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4707, 31198, '医者にインフルエンザだと診断された。', 'いしゃに インフルエンザだと しんだん された。', 'Tôi được bác sĩ chẩn đoán là bị cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4708, 31200, '書類を精査してから返事します。', 'しょるいを せいさ してから へんじ します。', 'Tôi sẽ rà soát kỹ giấy tờ rồi trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4709, 45491, '社長の命令なら、従うしかない。', 'しゃちょうの めいれいなら、したがう しか ない。', 'Nếu là lệnh của giám đốc thì chỉ còn cách tuân theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4710, 45501, '今年の目標は日本語能力試験に合格することです。', 'ことしの もくひょうは にほんごのうりょくしけんに ごうかくする ことです。', 'Mục tiêu năm nay là đỗ kỳ thi năng lực tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4711, 45509, 'この件は私に任せてください。', 'この けんは わたしに まかせて ください。', 'Việc này cứ giao cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4712, 45528, 'ついに夢がかないました。', 'ついに ゆめが かないました。', 'Rốt cuộc ước mơ đã thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4713, 45544, '交差点で交通事故があった。', 'こうさてんで こうつうじこが あった。', 'Đã xảy ra tai nạn giao thông ở ngã tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4714, 45555, '話し合いで問題を解決しましょう。', 'はなしあいで もんだいを かいけつ しましょう。', 'Hãy giải quyết vấn đề bằng cách bàn bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4715, 45589, '子供の教育にはお金がかかる。', 'こどもの きょういくには おかねが かかる。', 'Việc giáo dục con cái tốn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4716, 45648, '寒さがますます厳しくなってきた。', 'さむさが ますます きびしく なって きた。', 'Cái lạnh ngày càng khắc nghiệt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4717, 45651, '電気を節約するために、エアコンを使わないようにしている。', 'でんきを せつやく する ために、エアコンを つかわない ように して いる。', 'Để tiết kiệm điện, tôi cố không dùng điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4718, 45660, 'ネットで本を注文した。', 'ネットで ほんを ちゅうもん した。', 'Tôi đã đặt mua sách trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4719, 45661, '荷物は明日の午前中に配達されます。', 'にもつは あしたの ごぜんちゅうに はいたつ されます。', 'Hàng sẽ được giao vào sáng mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4720, 45663, '電池を新しいのと交換した。', 'でんちを あたらしいのと こうかん した。', 'Tôi đã thay pin mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4721, 45684, 'ビザの手続きに一か月かかった。', 'ビザの てつづきに いっかげつ かかった。', 'Thủ tục visa mất một tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4722, 45869, 'この件は私に任せてください。', 'この けんは わたしに まかせて ください。', 'Việc này cứ giao cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4723, 38887, '祖父は若いころ軍隊にいた。', 'そふは わかい ころ ぐんたいに いた。', 'Hồi trẻ ông tôi từng ở trong quân đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4724, 45884, '有能な人が会社に入ってきた。', 'ゆうのうな ひとが かいしゃに はいって きた。', 'Một người tài giỏi đã vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4725, 45860, '顧客の満足を第一に考えている。', 'こきゃくの まんぞくを だいいちに かんがえて いる。', 'Chúng tôi đặt sự hài lòng của khách hàng lên hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4726, 45863, 'この薬はすぐに効果が出た。', 'この くすりは すぐに こうかが でた。', 'Thuốc này có hiệu quả ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4727, 45865, '彼の専門は日本文学だ。', 'かれの せんもんは にほん ぶんがくだ。', 'Chuyên môn của anh ấy là văn học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4728, 45868, '難しい仕事を引き受けてしまった。', 'むずかしい しごとを ひきうけて しまった。', 'Tôi lỡ nhận một công việc khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4729, 45871, '用事が済んだら、すぐ帰ります。', 'ようじが すんだら、すぐ かえります。', 'Xong việc là tôi về ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4730, 45873, '工事は予定どおり進んでいる。', 'こうじは よてい どおり すすんで いる。', 'Công trình đang tiến triển đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4731, 45875, '夏休みにアルバイトで旅行のお金を稼いだ。', 'なつやすみに アルバイトで りょこうの おかねを かせいだ。', 'Kỳ nghỉ hè tôi làm thêm để kiếm tiền đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4732, 45878, '提出する前に、もう一度答えを見直した。', 'ていしゅつ する まえに、もう いちど こたえを みなおした。', 'Trước khi nộp tôi xem lại đáp án một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4733, 45881, 'この牛乳は期限が切れている。', 'この ぎゅうにゅうは きげんが きれて いる。', 'Hộp sữa này đã hết hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4734, 45885, 'この町の主な産業は観光だ。', 'この まちの おもな さんぎょうは かんこうだ。', 'Ngành chủ yếu của thị trấn này là du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4735, 41984, '時代劇に奴が出てきた。', 'じだいげきに やっこが でて きた。', 'Trong phim cổ trang có xuất hiện một tên hầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4736, 31006, '政府は緊急の措置を取った。', 'せいふは きんきゅうの そちを とった。', 'Chính phủ đã áp dụng biện pháp khẩn cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4737, 45710, '事故のせいで、道が渋滞している。', 'じこの せいで、みちが じゅうたい して いる。', 'Vì tai nạn mà đường đang tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4738, 45770, 'お客様に失礼な態度をとってはいけません。', 'おきゃくさまに しつれいな たいどを とっては いけません。', 'Không được có thái độ thất lễ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4739, 45778, '毎日努力した結果、試験に合格できました。', 'まいにち どりょくした けっか、しけんに ごうかく できました。', 'Nhờ nỗ lực mỗi ngày mà tôi đã thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4740, 31072, '大学を卒業したら、銀行に就職したいです。', 'だいがくを そつぎょう したら、ぎんこうに しゅうしょく したいです。', 'Tốt nghiệp đại học xong tôi muốn vào làm ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4741, 28748, 'ここで写真を撮るには許可が必要です。', 'ここで しゃしんを とるには きょかが ひつよう です。', 'Muốn chụp ảnh ở đây cần phải xin phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4742, 28830, 'あなたの気持ちはよくわかります。', 'あなたの きもちは よく わかります。', 'Tôi rất hiểu cảm xúc của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4743, 28935, 'この会社は高い技術を持っている。', 'この かいしゃは たかい ぎじゅつを もって いる。', 'Công ty này có kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4744, 28974, '使った物はきちんと片付けてください。', 'つかった ものは きちんと かたづけて ください。', 'Đồ đã dùng thì hãy cất dọn ngăn nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4745, 28999, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4746, 29108, '彼は最近、様子がおかしい。', 'かれは さいきん、ようすが おかしい。', 'Dạo này anh ấy có vẻ lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4747, 29220, '子供の教育にはお金がかかる。', 'こどもの きょういくには おかねが かかる。', 'Việc giáo dục con cái tốn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4748, 29319, 'このくつはサイズがぴったりです。', 'この くつは サイズが ぴったり です。', 'Đôi giày này vừa khít cỡ chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4749, 29409, 'ちゃんと歯を磨いてから寝なさい。', 'ちゃんと はを みがいてから ねなさい。', 'Đánh răng cho đàng hoàng rồi hãy ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4750, 45816, '試合に負けて、みんながっかりしました。', 'しあいに まけて、みんな がっかり しました。', 'Thua trận nên ai cũng thất vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4751, 30677, '夏休みにどこへ行くか、まだ決めていません。', 'なつやすみに どこへ いくか、まだ きめて いません。', 'Tôi vẫn chưa quyết định nghỉ hè sẽ đi đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4752, 30678, '会議の日にちが来週の月曜日に決まりました。', 'かいぎの ひにちが らいしゅうの げつようびに きまりました。', 'Ngày họp đã được chốt vào thứ Hai tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4753, 30680, '去年と比べると、今年は雨が少ないです。', 'きょねんと くらべると、ことしは あめが すくないです。', 'So với năm ngoái thì năm nay ít mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4754, 30682, '運動を始めてから、体重が三キロ減りました。', 'うんどうを はじめてから、たいじゅうが さんキロ へりました。', 'Từ khi bắt đầu tập thể dục, tôi đã giảm ba ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4755, 30687, 'わざわざ駅まで迎えに来てくれて、ありがとう。', 'わざわざ えきまで むかえに きて くれて、ありがとう。', 'Cảm ơn bạn đã cất công ra tận ga đón tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4756, 30689, 'ついに夢がかないました。', 'ついに ゆめが かないました。', 'Rốt cuộc ước mơ đã thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4757, 30690, 'いよいよ明日から夏休みです。', 'いよいよ あしたから なつやすみです。', 'Cuối cùng thì từ mai là kỳ nghỉ hè rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4758, 30692, '確かに、この店の料理はおいしいですね。', 'たしかに、この みせの りょうりは おいしいですね。', 'Đúng là đồ ăn quán này ngon thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4759, 30694, '日本料理の中で、特にすしが好きです。', 'にほんりょうりの なかで、とくに すしが すきです。', 'Trong các món Nhật, tôi đặc biệt thích sushi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4760, 30695, '写真で見るより、実際に行ったほうがきれいでした。', 'しゃしんで みるより、じっさいに いった ほうが きれい でした。', 'Đến tận nơi còn đẹp hơn xem qua ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4761, 45887, '買ったばかりの服を早速着てみた。', 'かった ばかりの ふくを さっそく きて みた。', 'Tôi mặc thử ngay bộ quần áo vừa mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4762, 38614, 'おそらく明日は雪が降るでしょう。', 'おそらく あしたは ゆきが ふるでしょう。', 'E rằng ngày mai trời sẽ có tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4763, 38616, 'おまえ、まだ宿題をやってないのか。', 'おまえ、まだ しゅくだいを やって ないのか。', 'Mày vẫn chưa làm bài tập à?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4764, 38617, '駅から会社まで、およそ十分かかります。', 'えきから かいしゃまで、およそ じゅっぷん かかります。', 'Từ ga đến công ty mất khoảng mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4765, 38620, '午後から雨が降るかもしれません。', 'ごごから あめが ふるかも しれません。', 'Có thể chiều nay trời sẽ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4766, 38621, '雨の中で子犬が震えていて、かわいそうだった。', 'あめの なかで こいぬが ふるえて いて、かわいそう だった。', 'Chú cún run rẩy trong mưa, trông thật tội nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4767, 38628, '彼はけちで、お金を全然使わない。', 'かれは けちで、おかねを ぜんぜん つかわない。', 'Anh ấy keo kiệt, chẳng chịu tiêu tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4768, 38615, '新しいオフィスは駅のすぐ近くにあります。', 'あたらしい オフィスは えきの すぐ ちかくに あります。', 'Văn phòng mới ở ngay gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4769, 38626, '冬は手にクリームを塗っています。', 'ふゆは てに クリームを ぬって います。', 'Mùa đông tôi thoa kem lên tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4770, 30698, '結果が出たら、すぐに知らせます。', 'けっかが でたら、すぐに しらせます。', 'Có kết quả tôi sẽ báo ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4771, 30700, '調査の結果を部長に報告しました。', 'ちょうさの けっかを ぶちょうに ほうこく しました。', 'Tôi đã báo cáo kết quả khảo sát cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4772, 30703, '先生が文法をわかりやすく説明してくれました。', 'せんせいが ぶんぽうを わかりやすく せつめい して くれました。', 'Thầy giáo giải thích ngữ pháp rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4773, 30707, 'この車はまだいい状態です。', 'この くるまは まだ いい じょうたい です。', 'Chiếc xe này vẫn còn trong tình trạng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4774, 30722, '嫌なら、はっきり言ったほうがいいですよ。', 'いやなら、はっきり いった ほうが いいですよ。', 'Nếu không thích thì nên nói rõ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4775, 30725, '地震で部屋の中がめちゃくちゃになった。', 'じしんで へやの なかが めちゃくちゃに なった。', 'Động đất làm trong phòng lộn xộn hết cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4776, 38632, '遅れて、ごめんなさい。', 'おくれて、ごめんなさい。', 'Xin lỗi vì đã đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4777, 38634, '資料にざっと目を通しておいてください。', 'しりょうに ざっと めを とおして おいて ください。', 'Hãy đọc lướt qua tài liệu trước nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4778, 38636, 'さて、次の問題に移りましょう。', 'さて、つぎの もんだいに うつりましょう。', 'Giờ thì chuyển sang câu tiếp theo nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4779, 38638, 'ジェット機が大きな音を立てて飛んでいった。', 'ジェットきが おおきな おとを たてて とんで いった。', 'Chiếc máy bay phản lực bay qua với tiếng ầm lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4780, 38641, '台風が来ている。したがって、明日の試合は中止だ。', 'たいふうが きて いる。したがって、あしたの しあいは ちゅうしだ。', 'Bão đang đến. Do đó trận đấu ngày mai bị hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4781, 38643, '今日の授業はこれでおしまいです。', 'きょうの じゅぎょうは これで おしまい です。', 'Buổi học hôm nay đến đây là hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4782, 38645, '授業中にしゃべってはいけません。', 'じゅぎょうちゅうに しゃべっては いけません。', 'Không được nói chuyện riêng trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4783, 38631, '最後まで走って、ゴールに着いた。', 'さいごまで はしって、ゴールに ついた。', 'Tôi chạy đến cùng và về tới đích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4784, 38637, '休みの日はたいていジーンズをはいています。', 'やすみの ひは たいてい ジーンズを はいて います。', 'Ngày nghỉ tôi thường mặc quần jean.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4785, 30731, '来週、大阪へ出張します。', 'らいしゅう、おおさかへ しゅっちょう します。', 'Tuần sau tôi đi công tác Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4786, 30734, '必要な書類を窓口に出してください。', 'ひつような しょるいを まどぐちに だして ください。', 'Hãy nộp giấy tờ cần thiết tại quầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4787, 30735, 'この仕事は田中さんが担当しています。', 'この しごとは たなかさんが たんとう して います。', 'Công việc này do anh Tanaka phụ trách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4788, 30738, '部長は部下にとても優しい。', 'ぶちょうは ぶかに とても やさしい。', 'Trưởng phòng rất tử tế với cấp dưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4789, 30739, '上司に休みを取ってもいいか聞いた。', 'じょうしに やすみを とっても いいか きいた。', 'Tôi hỏi cấp trên xem có được nghỉ phép không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4790, 30740, '取引先の会社に電話をかけた。', 'とりひきさきの かいしゃに でんわを かけた。', 'Tôi đã gọi điện cho công ty đối tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4791, 30743, 'ここで写真を撮るには許可が必要です。', 'ここで しゃしんを とるには きょかが ひつよう です。', 'Muốn chụp ảnh ở đây cần phải xin phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4792, 30746, '車に注意して道を渡りましょう。', 'くるまに ちゅうい して みちを わたりましょう。', 'Hãy chú ý xe cộ khi qua đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4793, 30747, '彼はいつも仕事の文句ばかり言っている。', 'かれは いつも しごとの もんく ばかり いって いる。', 'Anh ta lúc nào cũng chỉ than phiền về công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4794, 47702, '社会の規範を守ることが求められる。', 'しゃかいの きはんを まもる ことが もとめられる。', 'Cần tuân thủ chuẩn mực xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4795, 30753, 'みんなで協力して、部屋を片付けた。', 'みんなで きょうりょく して、へやを かたづけた。', 'Mọi người cùng hợp sức dọn dẹp căn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4796, 30754, '失敗の責任は私にあります。', 'しっぱいの せきにんは わたしに あります。', 'Trách nhiệm cho thất bại thuộc về tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4797, 38648, 'すてきなプレゼントをありがとう。', 'すてきな プレゼントを ありがとう。', 'Cảm ơn món quà tuyệt vời nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4798, 38650, '電車が止まった。そこで、タクシーで行くことにした。', 'でんしゃが とまった。そこで、タクシーで いく ことに した。', 'Tàu điện dừng chạy. Vì thế tôi quyết định đi taxi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4799, 38651, '赤ちゃんが寝ているので、そっとドアを閉めた。', 'あかちゃんが ねて いるので、そっと ドアを しめた。', 'Em bé đang ngủ nên tôi khẽ khép cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4800, 38654, 'コーヒーにしますか、それとも紅茶にしますか。', 'コーヒーに しますか、それとも こうちゃに しますか。', 'Bạn dùng cà phê hay là trà?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4801, 38657, 'この雑誌はただでもらえます。', 'この ざっしは ただで もらえます。', 'Tạp chí này được phát miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4802, 38658, 'どうして食べないの。――だって、おなかがいっぱいなんだもん。', 'どうして たべないの。――だって、おなかが いっぱい なんだもん。', 'Sao không ăn? – Vì con no rồi mà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4803, 38663, 'どうしてもこの映画が見たい。', 'どうしても この えいがが みたい。', 'Dù thế nào tôi cũng muốn xem bộ phim này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4804, 38647, '彼女はスタイルがよくて、何を着ても似合う。', 'かのじょは スタイルが よくて、なにを きても にあう。', 'Cô ấy dáng đẹp, mặc gì cũng hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4805, 38661, '山の上にテントを張って一晩過ごした。', 'やまの うえに テントを はって ひとばん すごした。', 'Chúng tôi dựng lều trên núi và ngủ lại một đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4806, 30760, '外国の文化に興味があります。', 'がいこくの ぶんかに きょうみが あります。', 'Tôi quan tâm đến văn hóa nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4807, 30764, 'この会社は高い技術を持っている。', 'この かいしゃは たかい ぎじゅつを もって いる。', 'Công ty này có kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4808, 30767, '新しい商品が来月発売されます。', 'あたらしい しょうひんが らいげつ はつばい されます。', 'Sản phẩm mới sẽ được bán ra vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4809, 30770, '留学の費用はどのくらいかかりますか。', 'りゅうがくの ひようは どのくらい かかりますか。', 'Chi phí du học khoảng bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4810, 30772, '旅行のために毎月貯金しています。', 'りょこうの ために まいつき ちょきん して います。', 'Tôi để dành tiền mỗi tháng cho chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4811, 30774, '電気を節約するために、エアコンを使わないようにしている。', 'でんきを せつやく する ために、エアコンを つかわない ように して いる。', 'Để tiết kiệm điện, tôi cố không dùng điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4812, 30777, 'インターネットの発達で、生活が便利になった。', 'インターネットの はったつで、せいかつが べんりに なった。', 'Nhờ sự phát triển của Internet, cuộc sống trở nên tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4813, 30778, '医学の進歩で、多くの病気が治るようになった。', 'いがくの しんぽで、おおくの びょうきが なおる ように なった。', 'Nhờ tiến bộ y học, nhiều bệnh đã chữa được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4814, 30781, '今の状況を詳しく説明してください。', 'いまの じょうきょうを くわしく せつめい して ください。', 'Hãy giải thích chi tiết tình hình hiện tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4815, 30783, 'とにかく一度やってみよう。', 'とにかく いちど やって みよう。', 'Dù sao thì cứ thử làm một lần đã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4816, 30784, '明日は休みです。ただし、午前中は電話に出ます。', 'あしたは やすみ です。ただし、ごぜんちゅうは でんわに でます。', 'Mai tôi nghỉ. Tuy nhiên buổi sáng vẫn nghe điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4817, 30786, '母の姉、つまりおばが来ました。', 'ははの あね、つまり おばが きました。', 'Chị của mẹ, tức là dì tôi, đã đến chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4818, 38667, '私が社長だなんて、とんでもないです。', 'わたしが しゃちょう だなんて、とんでもない です。', 'Tôi mà là giám đốc ư, đâu có chuyện đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4819, 38668, 'どんなに忙しくても、朝ご飯は食べます。', 'どんなに いそがしくても、あさごはんは たべます。', 'Dù bận đến đâu tôi cũng ăn sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4820, 38671, '明日は行けません。なぜなら、仕事があるからです。', 'あしたは いけません。なぜなら、しごとが あるから です。', 'Mai tôi không đi được. Bởi vì có việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4821, 38672, '朝から何も食べていません。', 'あさから なにも たべて いません。', 'Từ sáng tôi chưa ăn gì cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4822, 38674, '週末は家でのんびり過ごした。', 'しゅうまつは いえで のんびり すごした。', 'Cuối tuần tôi ở nhà thong thả nghỉ ngơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4823, 38679, '急に大きな音がして、びっくりした。', 'きゅうに おおきな おとが して、びっくり した。', 'Bỗng có tiếng động lớn làm tôi giật mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4824, 28318, '日本のドラマを見て、日本語を勉強します。', 'にほんの ドラマを みて、にほんごを べんきょう します。', 'Tôi học tiếng Nhật qua phim truyền hình Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4825, 38665, '家族でトランプをして遊んだ。', 'かぞくで トランプを して あそんだ。', 'Cả nhà cùng chơi bài tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4826, 38669, '長いトンネルを抜けると、海が見えた。', 'ながい トンネルを ぬけると、うみが みえた。', 'Ra khỏi đường hầm dài thì thấy biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4827, 38675, '娘は五歳からバイオリンを習っています。', 'むすめは ごさいから バイオリンを ならって います。', 'Con gái tôi học violin từ năm năm tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4828, 38678, '天気がいいので、公園へピクニックに行こう。', 'てんきが いいので、こうえんへ ピクニックに いこう。', 'Trời đẹp, mình đi dã ngoại ở công viên đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4829, 30789, '交差点で交通事故があった。', 'こうさてんで こうつうじこが あった。', 'Đã xảy ra tai nạn giao thông ở ngã tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4830, 30790, 'エレベーターが故障して、使えません。', 'エレベーターが こしょう して、つかえません。', 'Thang máy bị hỏng, không dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4831, 30792, '電池を新しいのと交換した。', 'でんちを あたらしいのと こうかん した。', 'Tôi đã thay pin mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4832, 45840, '留学の費用はどのくらいかかりますか。', 'りゅうがくの ひようは どのくらい かかりますか。', 'Chi phí du học khoảng bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4833, 45842, 'アパートの契約は二年です。', 'アパートの けいやくは にねん です。', 'Hợp đồng thuê căn hộ là hai năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4834, 45848, 'この仕事は田中さんが担当しています。', 'この しごとは たなかさんが たんとう して います。', 'Công việc này do anh Tanaka phụ trách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4835, 45851, '社長の命令なら、従うしかない。', 'しゃちょうの めいれいなら、したがう しか ない。', 'Nếu là lệnh của giám đốc thì chỉ còn cách tuân theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4836, 45852, 'ここで写真を撮るには許可が必要です。', 'ここで しゃしんを とるには きょかが ひつよう です。', 'Muốn chụp ảnh ở đây cần phải xin phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4837, 30793, '図書館は誰でも無料で利用できます。', 'としょかんは だれでも むりょうで りよう できます。', 'Ai cũng có thể sử dụng thư viện miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4838, 30794, 'レストランを七時に予約しました。', 'レストランを しちじに よやく しました。', 'Tôi đã đặt nhà hàng lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4839, 30800, 'この用紙に住所と名前を記入してください。', 'この ようしに じゅうしょと なまえを きにゅう して ください。', 'Hãy điền địa chỉ và họ tên vào tờ giấy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4840, 30802, '申し込みの締め切りは明日です。', 'もうしこみの しめきりは あした です。', 'Hạn chót đăng ký là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4841, 30803, 'ビザの期間を延長したい。', 'ビザの きかんを えんちょう したい。', 'Tôi muốn gia hạn thời hạn visa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4842, 45897, '彼は市の議員に選ばれた。', 'かれは しの ぎいんに えらばれた。', 'Ông ấy được bầu làm nghị viên thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4843, 45931, '会社が倒産して、父は失業した。', 'かいしゃが とうさん して、ちちは しつぎょう した。', 'Công ty phá sản nên bố tôi bị thất nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4844, 45898, '会社に新しい休暇の制度ができた。', 'かいしゃに あたらしい きゅうかの せいどが できた。', 'Công ty đã có chế độ nghỉ phép mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4845, 45923, '東京で国際会議が開かれた。', 'とうきょうで こくさい かいぎが ひらかれた。', 'Một hội nghị quốc tế đã được tổ chức ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4846, 28368, '時計の電池を取り替えました。', 'とけいの でんちを とりかえました。', 'Tôi đã thay pin đồng hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4847, 45926, '姉は福祉の仕事に就いた。', 'あねは ふくしの しごとに ついた。', 'Chị tôi làm trong ngành phúc lợi xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4848, 45894, '来月、市長の選挙がある。', 'らいげつ、しちょうの せんきょが ある。', 'Tháng sau có bầu cử thị trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4849, 45900, '税金を払うのは国民の義務だ。', 'ぜいきんを はらうのは こくみんの ぎむだ。', 'Nộp thuế là nghĩa vụ của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4850, 45902, '二度と戦争を起こしてはいけない。', 'にどと せんそうを おこしては いけない。', 'Không bao giờ được để chiến tranh xảy ra lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4851, 45905, '警察は犯人を探している。', 'けいさつは はんにんを さがして いる。', 'Cảnh sát đang truy tìm thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4852, 45909, '災害のときのために、水と食料を用意しておこう。', 'さいがいの ときの ために、みずと しょくりょうを ようい して おこう。', 'Hãy chuẩn bị sẵn nước và lương thực phòng khi thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4853, 45911, '事故の原因はまだわかっていない。', 'じこの げんいんは まだ わかって いない。', 'Nguyên nhân tai nạn vẫn chưa rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4854, 45914, 'この計画の問題点を話し合おう。', 'この けいかくの もんだいてんを はなしあおう。', 'Hãy bàn về những điểm có vấn đề trong kế hoạch này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4855, 45918, '明日、授業でレポートを発表する。', 'あした、じゅぎょうで レポートを はっぴょう する。', 'Ngày mai tôi trình bày báo cáo trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4856, 45920, 'インターネットで旅行の情報を集めた。', 'インターネットで りょこうの じょうほうを あつめた。', 'Tôi thu thập thông tin du lịch trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4857, 45924, 'この町には外国人がたくさん住んでいる。', 'この まちには がいこくじんが たくさん すんで いる。', 'Thị trấn này có nhiều người nước ngoài sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4858, 45928, '東京は物価が高い。', 'とうきょうは ぶっかが たかい。', 'Vật giá ở Tokyo cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4859, 45932, 'その意見に賛成です。', 'その いけんに さんせい です。', 'Tôi tán thành ý kiến đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4860, 45934, '彼は自分の考えを強く主張した。', 'かれは じぶんの かんがえを つよく しゅちょう した。', 'Anh ấy khẳng định mạnh mẽ suy nghĩ của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4861, 45936, '夜中に地震が発生した。', 'よなかに じしんが はっせい した。', 'Nửa đêm đã xảy ra động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4862, 45939, '手を洗って、風邪を防ごう。', 'てを あらって、かぜを ふせごう。', 'Hãy rửa tay để phòng cảm cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4863, 45941, '明日の朝、六時に起こしてください。', 'あしたの あさ、ろくじに おこして ください。', 'Sáng mai hãy đánh thức tôi lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4864, 45943, '犯人はすぐに捕まった。', 'はんにんは すぐに つかまった。', 'Thủ phạm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4865, 28371, 'ちゃわんにご飯を入れてください。', 'ちゃわんに ごはんを いれて ください。', 'Hãy xới cơm vào bát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4866, 30805, '学生は二割引で入れます。', 'がくせいは にわりびきで はいれます。', 'Sinh viên được giảm giá 20% khi vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4867, 30807, 'ネットで本を注文した。', 'ネットで ほんを ちゅうもん した。', 'Tôi đã đặt mua sách trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4868, 30809, 'ちゃんと歯を磨いてから寝なさい。', 'ちゃんと はを みがいてから ねなさい。', 'Đánh răng cho đàng hoàng rồi hãy ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4869, 30811, 'そのうち、また遊びに来てください。', 'そのうち、また あそびに きて ください。', 'Nay mai lại đến chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4870, 30812, 'いつのまにか外が暗くなっていた。', 'いつのまにか そとが くらく なって いた。', 'Bên ngoài đã tối lúc nào không hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4871, 38689, '疲れて、ぼんやり窓の外を見ていた。', 'つかれて、ぼんやり まどの そとを みて いた。', 'Mệt quá, tôi lơ đãng nhìn ra ngoài cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4872, 38694, '寒さがますます厳しくなってきた。', 'さむさが ますます きびしく なって きた。', 'Cái lạnh ngày càng khắc nghiệt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4989, 43739, '朝ごはんにパンを食べます。', 'あさごはんに パンを たべます。', 'Bữa sáng tôi ăn bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4873, 38695, '彼の日本語はまるで日本人のようだ。', 'かれの にほんごは まるで にほんじんの ようだ。', 'Tiếng Nhật của anh ấy cứ như người Nhật vậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4874, 38682, '子供が飛び出してきたので、急ブレーキをかけた。', 'こどもが とびだして きたので、きゅうブレーキを かけた。', 'Có đứa trẻ lao ra nên tôi phanh gấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4875, 38684, 'シートベルトを締めてください。', 'シートベルトを しめて ください。', 'Xin hãy thắt dây an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4876, 38686, '公園のベンチで本を読んだ。', 'こうえんの ベンチで ほんを よんだ。', 'Tôi đọc sách trên ghế băng ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4877, 38693, '喫茶店のマスターがコーヒーをいれてくれた。', 'きっさてんの マスターが コーヒーを いれて くれた。', 'Chủ quán cà phê pha cà phê cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4878, 38697, '大事なことはメモしておいたほうがいい。', 'だいじな ことは メモ して おいた ほうが いい。', 'Việc quan trọng thì nên ghi chú lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4879, 31202, '子供のころの記憶はあまりありません。', 'こどもの ころの きおくは あまり ありません。', 'Tôi không còn nhớ nhiều về thời thơ ấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4880, 45861, '今年の目標は日本語能力試験に合格することです。', 'ことしの もくひょうは にほんごのうりょくしけんに ごうかくする ことです。', 'Mục tiêu năm nay là đỗ kỳ thi năng lực tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4881, 45864, 'この仕事には英語の能力が必要です。', 'この しごとには えいごの のうりょくが ひつよう です。', 'Công việc này cần năng lực tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4882, 45880, '申し込みの締め切りは明日です。', 'もうしこみの しめきりは あした です。', 'Hạn chót đăng ký là ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4883, 45888, 'ついに夢がかないました。', 'ついに ゆめが かないました。', 'Rốt cuộc ước mơ đã thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4884, 45904, '交差点で交通事故があった。', 'こうさてんで こうつうじこが あった。', 'Đã xảy ra tai nạn giao thông ở ngã tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4885, 45915, '話し合いで問題を解決しましょう。', 'はなしあいで もんだいを かいけつ しましょう。', 'Hãy giải quyết vấn đề bằng cách bàn bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4886, 45948, '写真で見るより、実際に行ったほうがきれいでした。', 'しゃしんで みるより、じっさいに いった ほうが きれい でした。', 'Đến tận nơi còn đẹp hơn xem qua ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4887, 45949, '子供の教育にはお金がかかる。', 'こどもの きょういくには おかねが かかる。', 'Việc giáo dục con cái tốn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4888, 46011, '電気を節約するために、エアコンを使わないようにしている。', 'でんきを せつやく する ために、エアコンを つかわない ように して いる。', 'Để tiết kiệm điện, tôi cố không dùng điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4889, 45950, '学問に終わりはない。', 'がくもんに おわりは ない。', 'Việc học không có điểm dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4890, 46649, '日本人の平均寿命は世界でも長い。', 'にほんじんの へいきん じゅみょうは せかいでも ながい。', 'Tuổi thọ trung bình của người Nhật thuộc hàng cao thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4891, 31451, '毎日努力した結果、試験に合格できました。', 'まいにち どりょくした けっか、しけんに ごうかく できました。', 'Nhờ nỗ lực mỗi ngày mà tôi đã thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4892, 45962, '教科書の二十ページを開いてください。', 'きょうかしょの にじゅっページを ひらいて ください。', 'Hãy mở sách giáo khoa trang 20.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4893, 28382, '源氏物語は千年前に書かれた小説です。', 'げんじ ものがたりは せんねんまえに かかれた しょうせつ です。', 'Truyện Genji là tiểu thuyết được viết từ một nghìn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4894, 38271, '几帳面過ぎると、疲れてしまう。', 'きちょうめん すぎると、つかれて しまう。', 'Quá tỉ mỉ thì sẽ mệt mỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4895, 40462, '彼女は問題点をずばり指摘した。', 'かのじょは もんだいてんを ずばり してき した。', 'Cô ấy chỉ ra vấn đề trúng phóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4896, 40472, '交渉はすんなりまとまった。', 'こうしょうは すんなり まとまった。', 'Cuộc đàm phán đã thỏa thuận suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4897, 40510, 'どうにか締め切りに間に合った。', 'どうにか しめきりに まにあった。', 'Bằng cách nào đó tôi cũng kịp hạn chót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4898, 40511, 'どうやら雨が降りそうだ。', 'どうやら あめが ふりそうだ。', 'Hình như trời sắp mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4899, 40521, 'お茶なんかいかがですか。', 'おちゃ なんか いかが ですか。', 'Anh dùng chút trà gì đó nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4900, 40524, '雨にも拘らず、多くの人が集まった。', 'あめにも かかわらず、おおくの ひとが あつまった。', 'Mặc dù trời mưa, rất nhiều người vẫn tụ tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4901, 40538, 'ひょっと外を見ると、雪が降っていた。', 'ひょっと そとを みると、ゆきが ふって いた。', 'Chợt nhìn ra ngoài thì thấy tuyết đang rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4902, 40678, '子供は厭々宿題をしていた。', 'こどもは いやいや しゅくだいを して いた。', 'Đứa trẻ miễn cưỡng làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4903, 40684, '川沿いの道を散歩した。', 'かわぞいの みちを さんぽ した。', 'Tôi đi dạo trên con đường dọc bờ sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4904, 45952, '一番好きな科目は数学です。', 'いちばん すきな かもくは すうがく です。', 'Môn học tôi thích nhất là toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4905, 45972, '来年、日本に留学する予定です。', 'らいねん、にほんに りゅうがく する よてい です。', 'Sang năm tôi dự định đi du học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4906, 45953, '数学のテストで百点を取った。', 'すうがくの テストで ひゃくてんを とった。', 'Tôi được một trăm điểm bài kiểm tra toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4907, 45955, 'この町には長い歴史がある。', 'この まちには ながい れきしが ある。', 'Thị trấn này có lịch sử lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4908, 45957, '日本の文学に興味がある。', 'にほんの ぶんがくに きょうみが ある。', 'Tôi quan tâm đến văn học Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4909, 45960, '大学では経済を専攻しています。', 'だいがくでは けいざいを せんこう して います。', 'Ở đại học tôi học chuyên ngành kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4910, 45963, '卒業論文を書いている。', 'そつぎょう ろんぶんを かいて いる。', 'Tôi đang viết luận văn tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4911, 45965, '今学期は成績が上がった。', 'こんがっきは せいせきが あがった。', 'Học kỳ này thành tích của tôi tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4912, 45967, '試験に合格して、とてもうれしい。', 'しけんに ごうかく して、とても うれしい。', 'Thi đỗ rồi, tôi vui lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4913, 45969, '四月に大学に入学した。', 'しがつに だいがくに にゅうがく した。', 'Tôi nhập học đại học vào tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4914, 45971, '兄は今年、大学を受験する。', 'あには ことし、だいがくを じゅけん する。', 'Năm nay anh tôi thi đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4915, 45974, 'アルバイトをして学費を払っている。', 'アルバイトを して がくひを はらって いる。', 'Tôi làm thêm để trả học phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4916, 45977, 'この高校には生徒が千人いる。', 'この こうこうには せいとが せんにん いる。', 'Trường cấp ba này có một nghìn học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4917, 46016, '学生は二割引で入れます。', 'がくせいは にわりびきで はいれます。', 'Sinh viên được giảm giá 20% khi vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4918, 46021, '荷物は明日の午前中に配達されます。', 'にもつは あしたの ごぜんちゅうに はいたつ されます。', 'Hàng sẽ được giao vào sáng mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4919, 46023, '電池を新しいのと交換した。', 'でんちを あたらしいのと こうかん した。', 'Tôi đã thay pin mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4920, 46044, 'ビザの手続きに一か月かかった。', 'ビザの てつづきに いっかげつ かかった。', 'Thủ tục visa mất một tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4921, 46036, '夫も育児に協力してくれる。', 'おっとも いくじに きょうりょく して くれる。', 'Chồng tôi cũng phụ giúp nuôi con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4922, 46040, 'ごみは分別して出してください。', 'ごみは ぶんべつ して だして ください。', 'Hãy phân loại rác trước khi đem đổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4923, 46064, 'たまには贅沢なレストランで食事したい。', 'たまには ぜいたくな レストランで しょくじ したい。', 'Thỉnh thoảng tôi muốn ăn ở nhà hàng sang trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4924, 46066, '台所はいつも清潔にしておこう。', 'だいどころは いつも せいけつに して おこう。', 'Hãy luôn giữ bếp sạch sẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4925, 46010, '毎月家計簿をつけている。', 'まいつき かけいぼを つけて いる。', 'Tháng nào tôi cũng ghi sổ chi tiêu gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4926, 46017, '来月から電車の運賃が値上げされる。', 'らいげつから でんしゃの うんちんが ねあげ される。', 'Từ tháng sau giá vé tàu sẽ tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4927, 46019, '注文した品物が届いた。', 'ちゅうもん した しなものが とどいた。', 'Món hàng tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4928, 46026, '家電の店で冷蔵庫を買った。', 'かでんの みせで れいぞうこを かった。', 'Tôi mua tủ lạnh ở cửa hàng điện máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4929, 46029, 'この店では外国の食品も買える。', 'この みせでは がいこくの しょくひんも かえる。', 'Ở cửa hàng này cũng mua được thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4930, 46033, '忙しくて、外食が多くなった。', 'いそがしくて、がいしょくが おおく なった。', 'Bận quá nên tôi ăn ngoài nhiều hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4931, 46035, '夫婦で家事を分担している。', 'ふうふで かじを ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4932, 46038, '工事の騒音で眠れない。', 'こうじの そうおんで ねむれない。', 'Tiếng ồn công trình khiến tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4933, 46041, 'エアコンを使いすぎて、電気代が高くなった。', 'エアコンを つかいすぎて、でんきだいが たかく なった。', 'Dùng điều hòa nhiều quá nên tiền điện tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4934, 46045, '日本語のスピーチ大会に申し込んだ。', 'にほんごの スピーチ たいかいに もうしこんだ。', 'Tôi đã đăng ký cuộc thi hùng biện tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4935, 46048, '役所で住民票をもらった。', 'やくしょで じゅうみんひょうを もらった。', 'Tôi lấy giấy chứng nhận cư trú ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4936, 46050, 'ホテルのフロントに荷物を預けた。', 'ホテルの フロントに にもつを あずけた。', 'Tôi gửi hành lý ở quầy lễ tân khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4937, 46052, 'ATMでお金を引き出した。', 'エーティーエムで おかねを ひきだした。', 'Tôi rút tiền ở cây ATM.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4938, 46054, '新しいパソコンを買うためにお金を貯めている。', 'あたらしい パソコンを かう ために おかねを ためて いる。', 'Tôi đang để dành tiền mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4939, 46057, '計算が間違っていたので、もう一度やり直した。', 'けいさんが まちがって いたので、もう いちど やりなおした。', 'Tính sai nên tôi làm lại lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4940, 46059, 'お弁当におかずを詰めた。', 'おべんとうに おかずを つめた。', 'Tôi xếp thức ăn vào hộp cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4941, 46061, '昼過ぎの電車は空いている。', 'ひるすぎの でんしゃは すいて いる。', 'Tàu buổi chiều thì vắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4942, 46063, 'まとめて買うとお得です。', 'まとめて かうと おとく です。', 'Mua cả lô thì được hời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4943, 28390, 'かばんを網棚に置きました。', 'かばんを あみだなに おきました。', 'Tôi để cặp lên giá hành lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4944, 46012, '旅行のために毎月貯金しています。', 'りょこうの ために まいつき ちょきん して います。', 'Tôi để dành tiền mỗi tháng cho chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4945, 46020, 'ネットで本を注文した。', 'ネットで ほんを ちゅうもん した。', 'Tôi đã đặt mua sách trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4946, 46022, 'サイズが合わなかったので、返品した。', 'サイズが あわなかったので、へんぴん した。', 'Không vừa cỡ nên tôi đã trả lại hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4947, 46024, '壊れた時計を修理に出した。', 'こわれた とけいを しゅうりに だした。', 'Tôi đã mang chiếc đồng hồ hỏng đi sửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4948, 46070, '事故のせいで、道が渋滞している。', 'じこの せいで、みちが じゅうたい して いる。', 'Vì tai nạn mà đường đang tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4949, 43772, '好きな色を一つ選んでください。', 'すきな いろを ひとつ えらんで ください。', 'Hãy chọn một màu bạn thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4950, 43813, '午後二時から会議があります。', 'ごご にじから かいぎが あります。', 'Từ hai giờ chiều có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4951, 46084, 'このホテルの宿泊料金は一泊一万円です。', 'この ホテルの しゅくはく りょうきんは いっぱく いちまんえん です。', 'Giá phòng khách sạn này là mười nghìn yên một đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4952, 46096, '駅はどちらの方向ですか。', 'えきは どちらの ほうこう ですか。', 'Ga ở hướng nào vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4953, 46067, 'なるほど、そういうことだったのか。', 'なるほど、そういう こと だったのか。', 'Ra là vậy, hóa ra là chuyện như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4954, 46069, 'この町は交通が便利だ。', 'この まちは こうつうが べんりだ。', 'Giao thông ở thị trấn này rất thuận tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4955, 46074, 'バスの運賃は降りるときに払います。', 'バスの うんちんは おりる ときに はらいます。', 'Tiền vé xe buýt trả khi xuống xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4956, 46076, '大阪まで片道一万四千円かかる。', 'おおさかまで かたみち いちまん よんせんえん かかる。', 'Vé một chiều đến Osaka mất mười bốn nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4957, 46078, '飲み会で終電を逃してしまった。', 'のみかいで しゅうでんを のがして しまった。', 'Đi nhậu nên tôi lỡ chuyến tàu cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4958, 46081, 'バスの行き先を確認してから乗ってください。', 'バスの いきさきを かくにん してから のって ください。', 'Hãy kiểm tra điểm đến của xe buýt rồi mới lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4959, 46083, '京都の名所を案内してもらった。', 'きょうとの めいしょを あんない して もらった。', 'Tôi được dẫn đi thăm các danh thắng ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4960, 46087, '重い荷物を持ってあげましょうか。', 'おもい にもつを もって あげましょうか。', 'Để tôi xách giúp hành lý nặng nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4961, 46088, '空港の税関で荷物を調べられた。', 'くうこうの ぜいかんで にもつを しらべられた。', 'Hành lý của tôi bị kiểm tra ở hải quan sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4962, 46093, '夏休みは田舎の祖父母の家で過ごした。', 'なつやすみは いなかの そふぼの いえで すごした。', 'Kỳ nghỉ hè tôi ở nhà ông bà dưới quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4963, 46095, '机の位置を窓の近くに変えた。', 'つくえの いちを まどの ちかくに かえた。', 'Tôi chuyển vị trí bàn lại gần cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4964, 43327, 'その時計はいくらですか。', 'その とけいは いくら ですか。', 'Chiếc đồng hồ đó bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4965, 43322, 'ベッドの下に猫がいます。', 'ベッドの したに ねこが います。', 'Dưới gầm giường có con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4966, 43454, '事務所は二階です。', 'じむしょは にかい です。', 'Văn phòng ở tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4967, 43328, 'これは電気の会社です。', 'これは でんきの かいしゃ です。', 'Đây là công ty điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4968, 43390, 'コップに水を入れてください。', 'コップに みずを いれて ください。', 'Hãy rót nước vào cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4969, 43436, 'あしたは漢字のテストです。', 'あしたは かんじの テスト です。', 'Ngày mai có bài kiểm tra chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4970, 43455, '銀行は三時までです。', 'ぎんこうは さんじまで です。', 'Ngân hàng mở cửa đến ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4971, 28391, '確か、会議は三時からだと思います。', 'たしか、かいぎは さんじから だと おもいます。', 'Tôi nghĩ hình như cuộc họp bắt đầu từ ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4972, 46100, '伊豆半島は温泉で有名だ。', 'いず はんとうは おんせんで ゆうめいだ。', 'Bán đảo Izu nổi tiếng với suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4973, 43461, 'あしたは休みです。', 'あしたは やすみ です。', 'Ngày mai được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4974, 43556, '自転車で学校へ来ます。', 'じてんしゃで がっこうへ きます。', 'Tôi đến trường bằng xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4975, 43553, 'バスで駅へ行きます。', 'バスで えきへ いきます。', 'Tôi đi xe buýt đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4976, 43676, '庭に花があります。', 'にわに はなが あります。', 'Trong vườn có hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4977, 43680, '机の上に本があります。', 'つくえの うえに ほんが あります。', 'Trên bàn có quyển sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4978, 43686, '電話はどこですか。', 'でんわは どこ ですか。', 'Điện thoại ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4979, 43692, 'これは車の雑誌です。', 'これは くるまの ざっし です。', 'Đây là tạp chí về ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4980, 43690, 'その辞書は私のです。', 'その じしょは わたしの です。', 'Cuốn từ điển đó là của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4981, 43459, '友達にメールを送りました。', 'ともだちに メールを おくりました。', 'Tôi đã gửi email cho bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4982, 43694, '公園で写真を撮りました。', 'こうえんで しゃしんを とりました。', 'Tôi đã chụp ảnh ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4983, 43697, 'この鍵は車の鍵です。', 'この かぎは くるまの かぎ です。', 'Chiếc chìa này là chìa khóa xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4984, 43685, '晩ごはんの後でテレビを見ます。', 'ばんごはんの あとで テレビを みます。', 'Sau bữa tối tôi xem tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4985, 43742, 'お茶を飲みませんか。', 'おちゃを のみませんか。', 'Uống trà không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4986, 43688, 'これは電気の会社です。', 'これは でんきの かいしゃ です。', 'Đây là công ty điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4987, 43684, '冷蔵庫に牛乳があります。', 'れいぞうこに ぎゅうにゅうが あります。', 'Trong tủ lạnh có sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4988, 43678, 'ドアを閉めてください。', 'ドアを しめて ください。', 'Hãy đóng cửa lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4990, 43758, '銀行でお金を下ろします。', 'ぎんこうで おかねを おろします。', 'Tôi rút tiền ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4991, 43746, 'スープに塩を少し入れてください。', 'スープに しおを すこし いれて ください。', 'Hãy cho một chút muối vào súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4992, 43463, '駅への道を教えてください。', 'えきへの みちを おしえて ください。', 'Hãy chỉ tôi đường đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4993, 43465, '新しい言葉を覚えました。', 'あたらしい ことばを おぼえました。', 'Tôi đã nhớ được từ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4994, 43683, '本棚に本がたくさんあります。', 'ほんだなに ほんが たくさん あります。', 'Trên giá sách có rất nhiều sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4995, 43743, 'お酒はあまり飲みません。', 'おさけは あまり のみません。', 'Tôi không uống rượu nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4996, 43748, '箸を使うことができますか。', 'はしを つかう ことが できますか。', 'Bạn có biết dùng đũa không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4997, 43751, 'この店は何時までですか。', 'この みせは なんじまで ですか。', 'Cửa hàng này mở đến mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4998, 43759, 'このりんごは一つ百円です。', 'この りんごは ひとつ ひゃくえん です。', 'Quả táo này giá một trăm yên một quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (4999, 43761, 'あした、買い物に行きます。', 'あした、かいものに いきます。', 'Ngày mai tôi đi mua sắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5000, 43763, 'りんごを二つ買いました。', 'りんごを ふたつ かいました。', 'Tôi mua hai quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5001, 43765, '宿題を全部やりました。', 'しゅくだいを ぜんぶ やりました。', 'Tôi đã làm hết bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5002, 43466, '傘を電車に忘れました。', 'かさを でんしゃに わすれました。', 'Tôi để quên ô trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5003, 43468, '毎晩、本を読みます。', 'まいばん、ほんを よみます。', 'Tối nào tôi cũng đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5004, 28396, '時計の針が十時を指しています。', 'とけいの はりが じゅうじを さして います。', 'Kim đồng hồ đang chỉ mười giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5005, 43806, '次の文を日本語に訳しなさい。', 'つぎの ぶんを にほんごに やくしなさい。', 'Hãy dịch câu sau sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5006, 43788, 'このかばんはいくらですか。', 'この かばんは いくら ですか。', 'Chiếc cặp này bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5007, 43814, '事務所は二階です。', 'じむしょは にかい です。', 'Văn phòng ở tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5008, 43820, '電話番号は何番ですか。', 'でんわ ばんごうは なんばん ですか。', 'Số điện thoại là số mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5009, 43809, 'ノートに漢字を書きます。', 'ノートに かんじを かきます。', 'Tôi viết chữ Hán vào vở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5010, 43801, '日本語の勉強は楽しいです。', 'にほんごの べんきょうは たのしい です。', 'Việc học tiếng Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5011, 43797, 'この問題は難しいです。', 'この もんだいは むずかしい です。', 'Câu hỏi này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5012, 43798, '答えを書いてください。', 'こたえを かいて ください。', 'Hãy viết câu trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5013, 43767, '水をたくさん飲んでください。', 'みずを たくさん のんで ください。', 'Hãy uống nhiều nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5014, 43769, '駅で新聞を買います。', 'えきで しんぶんを かいます。', 'Tôi mua báo ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5015, 43771, 'レジでお金を払います。', 'レジで おかねを はらいます。', 'Tôi trả tiền ở quầy thu ngân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5016, 43774, 'このケーキはおいしいです。', 'この ケーキは おいしい です。', 'Chiếc bánh này ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5017, 43775, 'この料理はまずいです。', 'この りょうりは まずい です。', 'Món này dở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5018, 43777, 'タイ料理は辛いです。', 'タイ りょうりは からい です。', 'Món Thái cay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5019, 43779, 'この店の野菜は安いです。', 'この みせの やさいは やすい です。', 'Rau ở cửa hàng này rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5020, 43782, '東京は人が多いです。', 'とうきょうは ひとが おおい です。', 'Tokyo đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5021, 43783, 'この町は人が少ないです。', 'この まちは ひとが すくない です。', 'Thị trấn này ít người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5022, 43786, 'では、いただきます。', 'では、いただきます。', 'Vậy, xin mời mọi người ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5023, 43750, 'コップに水を入れてください。', 'コップに みずを いれて ください。', 'Hãy rót nước vào cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5024, 43756, 'デパートでかばんを買いました。', 'デパートで かばんを かいました。', 'Tôi mua cặp ở trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5025, 43802, '毎日日本語を勉強します。', 'まいにち にほんごを べんきょう します。', 'Ngày nào tôi cũng học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5026, 43807, 'この言葉の意味を教えてください。', 'この ことばの いみを おしえて ください。', 'Hãy cho tôi biết nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5027, 43812, '仕事は六時に終わります。', 'しごとは ろくじに おわります。', 'Công việc kết thúc lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5028, 43815, '銀行は三時までです。', 'ぎんこうは さんじまで です。', 'Ngân hàng mở cửa đến ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5029, 43822, '夏休みに国へ帰ります。', 'なつやすみに くにへ かえります。', 'Kỳ nghỉ hè tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5030, 43823, '駅への道を教えてください。', 'えきへの みちを おしえて ください。', 'Hãy chỉ tôi đường đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5031, 43796, 'あしたは漢字のテストです。', 'あしたは かんじの テスト です。', 'Ngày mai có bài kiểm tra chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5032, 43810, 'ペンで名前を書いてください。', 'ペンで なまえを かいて ください。', 'Hãy viết tên bằng bút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5033, 43827, '先生の話がよく分かりました。', 'せんせいの はなしが よく わかりました。', 'Tôi hiểu rõ lời thầy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5034, 43830, 'わからない時は先生に聞きます。', 'わからない ときは せんせいに ききます。', 'Khi không hiểu tôi hỏi thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5035, 43832, '授業は九時に始まります。', 'じゅぎょうは くじに はじまります。', 'Giờ học bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5036, 44066, '父は貿易の会社で働いています。', 'ちちは ぼうえきの かいしゃで はたらいて います。', 'Bố tôi làm ở công ty thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5037, 44062, 'ルールを守ってください。', 'ルールを まもって ください。', 'Hãy tuân thủ luật lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5038, 44067, '日本は車をたくさん輸出している。', 'にほんは くるまを たくさん ゆしゅつ して いる。', 'Nhật Bản xuất khẩu rất nhiều ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5039, 46101, '朝、海岸を散歩した。', 'あさ、かいがんを さんぽ した。', 'Buổi sáng tôi đi dạo dọc bờ biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5040, 43916, '自転車で学校へ来ます。', 'じてんしゃで がっこうへ きます。', 'Tôi đến trường bằng xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5041, 43913, 'バスで駅へ行きます。', 'バスで えきへ いきます。', 'Tôi đi xe buýt đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5042, 43819, '友達にメールを送りました。', 'ともだちに メールを おくりました。', 'Tôi đã gửi email cho bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5043, 43931, '日曜日に山へ行きます。', 'にちようびに やまへ いきます。', 'Chủ nhật tôi đi núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5044, 43937, '銀行の右に郵便局があります。', 'ぎんこうの みぎに ゆうびんきょくが あります。', 'Bên phải ngân hàng có bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5045, 43939, '駅の前で待っています。', 'えきの まえで まって います。', 'Tôi đang đợi trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5046, 43942, 'この近くに病院がありますか。', 'この ちかくに びょういんが ありますか。', 'Gần đây có bệnh viện không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5047, 43932, '川で魚を釣りました。', 'かわで さかなを つりました。', 'Tôi câu cá ở sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5048, 43936, '地図を書いてください。', 'ちずを かいて ください。', 'Hãy vẽ bản đồ giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5049, 43920, 'この道をまっすぐ行ってください。', 'この みちを まっすぐ いって ください。', 'Hãy đi thẳng con đường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5050, 43923, '橋を渡ると、駅があります。', 'はしを わたると、えきが あります。', 'Qua cầu là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5051, 43929, '大使館でビザをもらいました。', 'たいしかんで ビザを もらいました。', 'Tôi nhận visa ở đại sứ quán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5052, 43918, '空港へ友達を迎えに行きます。', 'くうこうへ ともだちを むかえに いきます。', 'Tôi ra sân bay đón bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5053, 43934, '公園の池に魚がいます。', 'こうえんの いけに さかなが います。', 'Trong ao ở công viên có cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5054, 43940, '私の後ろに田中さんがいます。', 'わたしの うしろに たなかさんが います。', 'Anh Tanaka ở phía sau tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5055, 43944, '駅の西に大きい公園があります。', 'えきの にしに おおきい こうえんが あります。', 'Phía tây ga có một công viên lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5056, 43947, '明日、デパートへ行きます。', 'あした、デパートへ いきます。', 'Ngày mai tôi đi trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5057, 43949, '七時にうちへ帰ります。', 'しちじに うちへ かえります。', 'Bảy giờ tôi về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5058, 43951, '毎朝、川の近くを走ります。', 'まいあさ、かわの ちかくを はしります。', 'Sáng nào tôi cũng chạy bộ gần sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5059, 43953, '次の駅で電車を降ります。', 'つぎの えきで でんしゃを おります。', 'Tôi xuống tàu ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5060, 43955, 'あの角を右へ曲がってください。', 'あの かどを みぎへ まがって ください。', 'Hãy rẽ phải ở góc kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5061, 43957, '電車は十時に東京に着きます。', 'でんしゃは じゅうじに とうきょうに つきます。', 'Tàu đến Tokyo lúc mười giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5062, 43959, '部屋に入ってください。', 'へやに はいって ください。', 'Mời vào phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5063, 43961, '私のうちは駅から近いです。', 'わたしの うちは えきから ちかい です。', 'Nhà tôi gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5064, 43963, 'あの大きい建物は何ですか。', 'あの おおきい たてものは なん ですか。', 'Tòa nhà to kia là gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5065, 43965, 'この町はにぎやかです。', 'この まちは にぎやか です。', 'Thị trấn này náo nhiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5066, 43968, '駅の近くは便利です。', 'えきの ちかくは べんり です。', 'Gần ga thì tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5067, 44876, '電車の中で漫画を読んでいる人が多いです。', 'でんしゃの なかで まんがを よんで いる ひとが おおい です。', 'Trên tàu có nhiều người đọc truyện tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5068, 44107, '料理の道具を買いました。', 'りょうりの どうぐを かいました。', 'Tôi mua dụng cụ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5069, 44174, '子どもを動物園に連れていきました。', 'こどもを どうぶつえんに つれて いきました。', 'Tôi đưa con đi sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5070, 44458, '壁に絵が掛けてあります。', 'かべに えが かけて あります。', 'Trên tường có treo một bức tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5071, 44162, '毎朝、水泳をしています。', 'まいあさ、すいえいを して います。', 'Sáng nào tôi cũng đi bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5072, 44460, '床に本が落ちています。', 'ゆかに ほんが おちて います。', 'Trên sàn có quyển sách rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5073, 44105, '水道の水を飲むことができます。', 'すいどうの みずを のむ ことが できます。', 'Có thể uống nước máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5074, 44168, '四月に公園で花見をしました。', 'しがつに こうえんで はなみを しました。', 'Tháng tư tôi ngắm hoa anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5075, 44245, '桜の花が散ってしまいました。', 'さくらの はなが ちって しまいました。', 'Hoa anh đào đã rụng hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5076, 44247, '私は田舎で育ちました。', 'わたしは いなかで そだちました。', 'Tôi lớn lên ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5077, 44243, 'ペットボトルはリサイクルできます。', 'ペットボトルは リサイクル できます。', 'Chai nhựa có thể tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5078, 44361, '薬を飲んだら、すぐ治りました。', 'くすりを のんだら、すぐ なおりました。', 'Uống thuốc xong là khỏi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5079, 44363, '強い風で木が倒れました。', 'つよい かぜで きが たおれました。', 'Gió mạnh làm đổ cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5080, 44365, '長い時間歩いて、疲れました。', 'ながい じかん あるいて、つかれました。', 'Đi bộ lâu nên tôi mệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5081, 44367, '咳が止まらないので、病院へ行きました。', 'せきが とまらないので、びょういんへ いきました。', 'Ho mãi không dứt nên tôi đi bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5082, 44422, 'ルールを守ってください。', 'ルールを まもって ください。', 'Hãy tuân thủ luật lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5083, 46103, '大きな岩の上に座って海を見た。', 'おおきな いわの うえに すわって うみを みた。', 'Tôi ngồi trên tảng đá lớn ngắm biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5084, 44459, '屋根の上に猫がいる。', 'やねの うえに ねこが いる。', 'Có con mèo trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5085, 44161, '彼はサッカーの日本代表選手だ。', 'かれは サッカーの にほん だいひょう せんしゅだ。', 'Anh ấy là tuyển thủ bóng đá quốc gia Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5086, 44173, '博物館で古い土器を見た。', 'はくぶつかんで ふるい どきを みた。', 'Tôi xem đồ gốm cổ ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5087, 44175, '日曜日に子供を連れて遊園地に行った。', 'にちようびに こどもを つれて ゆうえんちに いった。', 'Chủ nhật tôi đưa con đi công viên giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5088, 44159, 'どんなスポーツが好きですか。', 'どんな スポーツが すき ですか。', 'Bạn thích môn thể thao nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5089, 44425, '週末、レストランでアルバイトをします。', 'しゅうまつ、レストランで アルバイトを します。', 'Cuối tuần tôi làm thêm ở nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5090, 44164, '週末、父と釣りに行きます。', 'しゅうまつ、ちちと つりに いきます。', 'Cuối tuần tôi đi câu cá với bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5091, 44455, '住所を教えてください。', 'じゅうしょを おしえて ください。', 'Cho tôi biết địa chỉ của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5092, 44096, '布団は押し入れに入れます。', 'ふとんは おしいれに いれます。', 'Chăn nệm được cất vào tủ âm tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5093, 44160, 'あした、サッカーの試合があります。', 'あした、サッカーの しあいが あります。', 'Ngày mai có trận đấu bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5094, 44452, 'このアパートの家賃は六万円です。', 'この アパートの やちんは ろくまんえん です。', 'Tiền thuê căn hộ này là sáu mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5095, 44457, 'この部屋は畳が六枚あります。', 'この へやは たたみが ろくまい あります。', 'Phòng này có sáu chiếu tatami.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5096, 44063, '明日、会社の面接を受けます。', 'あした、かいしゃの めんせつを うけます。', 'Ngày mai tôi đi phỏng vấn ở công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5097, 44064, '大学を卒業したら、銀行に就職したいです。', 'だいがくを そつぎょう したら、ぎんこうに しゅうしょく したいです。', 'Tốt nghiệp đại học xong tôi muốn vào làm ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5098, 44423, '明日、会社の面接を受けます。', 'あした、かいしゃの めんせつを うけます。', 'Ngày mai tôi đi phỏng vấn ở công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5099, 44462, '出かける前に鏡を見ます。', 'でかける まえに かがみを みます。', 'Trước khi ra ngoài tôi soi gương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5100, 44424, '大学を卒業したら、銀行に就職したいです。', 'だいがくを そつぎょう したら、ぎんこうに しゅうしょく したいです。', 'Tốt nghiệp đại học xong tôi muốn vào làm ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5101, 44476, '外国の文化に興味があります。', 'がいこくの ぶんかに きょうみが あります。', 'Tôi quan tâm đến văn hóa nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5102, 46235, 'みんなで協力して、部屋を片付けた。', 'みんなで きょうりょく して、へやを かたづけた。', 'Mọi người cùng hợp sức dọn dẹp căn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5103, 44525, '夏休みに友達と富士山に登山した。', 'なつやすみに ともだちと ふじさんに とざん した。', 'Kỳ nghỉ hè tôi cùng bạn leo núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5104, 44530, '旅行のお土産を買いました。', 'りょこうの おみやげを かいました。', 'Tôi đã mua quà du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5105, 44468, 'この機械の使い方を教えてください。', 'この きかいの つかいかたを おしえて ください。', 'Hãy chỉ tôi cách dùng chiếc máy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5106, 44477, '日本の習慣はまだよくわかりません。', 'にほんの しゅうかんは まだ よく わかりません。', 'Tôi vẫn chưa hiểu rõ phong tục Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5107, 44523, '毎週柔道を習っています。', 'まいしゅう じゅうどうを ならって います。', 'Hằng tuần tôi học judo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5108, 44473, 'カレーの材料を買いに行きます。', 'カレーの ざいりょうを かいに いきます。', 'Tôi đi mua nguyên liệu nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5109, 44463, 'カーテンを開けてください。', 'カーテンを あけて ください。', 'Hãy kéo rèm cửa ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5110, 44522, '毎朝、水泳をしています。', 'まいあさ、すいえいを して います。', 'Sáng nào tôi cũng đi bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5111, 44471, '電子レンジで弁当を温めました。', 'でんし レンジで べんとうを あたためました。', 'Tôi hâm nóng cơm hộp bằng lò vi sóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5112, 44475, '花のいい匂いがします。', 'はなの いい においが します。', 'Có mùi hoa thơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5113, 44480, 'ここにごみを捨てないでください。', 'ここに ごみを すてないで ください。', 'Xin đừng vứt rác ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5114, 44482, 'お風呂を沸かしておきます。', 'おふろを わかして おきます。', 'Tôi đun sẵn nước tắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5115, 44483, 'お湯が沸きました。', 'おゆが わきました。', 'Nước đã sôi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5116, 44486, 'ビールがよく冷えています。', 'ビールが よく ひえて います。', 'Bia đã lạnh rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5117, 44487, 'スープを温めてください。', 'スープを あたためて ください。', 'Hãy hâm nóng súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5118, 44526, '京都でお寺を見物しました。', 'きょうとで おてらを けんぶつ しました。', 'Tôi tham quan chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5119, 43239, '性教育ではセックスについても学ぶ。', 'せい きょういくでは セックスに ついても まなぶ。', 'Trong giáo dục giới tính cũng học về quan hệ tình dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5120, 43236, '売り上げの変化をグラフで示した。', 'うりあげの へんかを グラフで しめした。', 'Tôi thể hiện sự thay đổi doanh thu bằng biểu đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5121, 43227, 'アラブの国々は石油が豊富だ。', 'アラブの くにぐには せきゆが ほうふだ。', 'Các nước Ả Rập giàu dầu mỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5122, 43228, 'ラッシュアワーの電車はとても混む。', 'ラッシュアワーの でんしゃは とても こむ。', 'Tàu điện giờ cao điểm rất đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5123, 44536, '日本人と会話するのは楽しいです。', 'にほんじんと かいわ するのは たのしい です。', 'Nói chuyện với người Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5124, 30684, '天気は気分に影響する。', 'てんきはきぶんにえいきょうする。', 'Thời tiết ảnh hưởng đến tâm trạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5125, 30732, '午後二時から会議があります。', 'ごご にじから かいぎが あります。', 'Từ hai giờ chiều có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5126, 44540, 'ごみの収集は月曜日です。', 'ごみの しゅうしゅうは げつようび です。', 'Rác được thu gom vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5127, 44542, '日本の生活を楽しんでいます。', 'にほんの せいかつを たのしんで います。', 'Tôi đang tận hưởng cuộc sống ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5128, 44544, 'カラオケで歌いました。', 'カラオケで うたいました。', 'Tôi đã hát karaoke.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5129, 44546, '子どもが絵を描いています。', 'こどもが えを かいて います。', 'Đứa trẻ đang vẽ tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5130, 31379, '電話番号を教えてください。', 'でんわ ばんごうを おしえて ください。', 'Hãy cho tôi số điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5131, 31059, '前例のない試みに挑戦した。', 'ぜんれいの ない こころみに ちょうせん した。', 'Chúng tôi thử sức với một nỗ lực chưa có tiền lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5132, 46243, '彼はやっと自分の間違いを認めた。', 'かれは やっと じぶんの まちがいを みとめた。', 'Cuối cùng anh ấy cũng thừa nhận sai lầm của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5133, 46291, '医学の進歩で、多くの病気が治るようになった。', 'いがくの しんぽで、おおくの びょうきが なおる ように なった。', 'Nhờ tiến bộ y học, nhiều bệnh đã chữa được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5134, 46294, '図書館は誰でも無料で利用できます。', 'としょかんは だれでも むりょうで りよう できます。', 'Ai cũng có thể sử dụng thư viện miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5135, 46497, '父は株で大きな損をした。', 'ちちは かぶで おおきな そんを した。', 'Bố tôi lỗ nặng vì cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5136, 46501, 'やっと借金を全部返した。', 'やっと しゃっきんを ぜんぶ かえした。', 'Cuối cùng tôi cũng trả hết nợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5137, 46524, 'この町は観光で大きく発展した。', 'この まちは かんこうで おおきく はってん した。', 'Thị trấn này phát triển mạnh nhờ du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5138, 46595, 'みんなで協力して、部屋を片付けた。', 'みんなで きょうりょく して、へやを かたづけた。', 'Mọi người cùng hợp sức dọn dẹp căn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5139, 46603, '彼はやっと自分の間違いを認めた。', 'かれは やっと じぶんの まちがいを みとめた。', 'Cuối cùng anh ấy cũng thừa nhận sai lầm của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5140, 46105, '三時間かけて山の頂上に着いた。', 'さんじかん かけて やまの ちょうじょうに ついた。', 'Mất ba tiếng chúng tôi mới lên đến đỉnh núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5141, 31007, '暑さ対策に帽子をかぶっている。', 'あつさ たいさくに ぼうしを かぶって いる。', 'Tôi đội mũ để chống nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5142, 30914, 'やっと事件の真実が明らかになった。', 'やっと じけんの しんじつが あきらかに なった。', 'Cuối cùng sự thật của vụ án cũng sáng tỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5143, 44537, '館内での撮影はご遠慮ください。', 'かんないでの さつえいは ごえんりょ ください。', 'Xin vui lòng không chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5144, 44532, '美術館は月曜日休みです。', 'びじゅつかんは げつようび やすみ です。', 'Bảo tàng mỹ thuật nghỉ vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5145, 44539, '郵便局で切手を買います。', 'ゆうびんきょくで きってを かいます。', 'Tôi mua tem ở bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5146, 44519, 'どんなスポーツが好きですか。', 'どんな スポーツが すき ですか。', 'Bạn thích môn thể thao nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5147, 44518, '毎晩テレビでニュースを見ます。', 'まいばん テレビで ニュースを みます。', 'Tối nào tôi cũng xem tin tức trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5148, 44548, '日曜日、山に登りました。', 'にちようび、やまに のぼりました。', 'Chủ nhật tôi đã leo núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5149, 28397, '先生は地図の上の町を指しました。', 'せんせいは ちずの うえの まちを さしました。', 'Thầy chỉ vào thị trấn trên bản đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5150, 28402, '火事で家が燃えています。', 'かじで いえが もえて います。', 'Ngôi nhà đang cháy vì hỏa hoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5151, 44604, '春になると、桜が咲きます。', 'はるに なると、さくらが さきます。', 'Sang xuân hoa anh đào nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5152, 44606, '庭でトマトを育てています。', 'にわで トマトを そだてて います。', 'Tôi trồng cà chua trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5153, 44607, '私は田舎で育ちました。', 'わたしは いなかで そだちました。', 'Tôi lớn lên ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5154, 44786, '父は貿易の会社で働いています。', 'ちちは ぼうえきの かいしゃで はたらいて います。', 'Bố tôi làm ở công ty thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5155, 31781, '新しい法制の整備が急がれている。', 'あたらしい ほうせいの せいびが いそがれて いる。', 'Việc hoàn thiện hệ thống pháp chế mới đang được gấp rút tiến hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5314, 44984, 'この肉は硬いです。', 'この にくは かたい です。', 'Thịt này dai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5156, 40842, 'そういうことは間々ある。', 'そう いう ことは まま ある。', 'Chuyện như vậy thỉnh thoảng vẫn có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5157, 44783, '明日、会社の面接を受けます。', 'あした、かいしゃの めんせつを うけます。', 'Ngày mai tôi đi phỏng vấn ở công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5158, 44784, '大学を卒業したら、銀行に就職したいです。', 'だいがくを そつぎょう したら、ぎんこうに しゅうしょく したいです。', 'Tốt nghiệp đại học xong tôi muốn vào làm ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5159, 46106, '日本には火山がたくさんある。', 'にほんには かざんが たくさん ある。', 'Nhật Bản có rất nhiều núi lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5160, 46108, '夜中に大きな雷が鳴った。', 'よなかに おおきな かみなりが なった。', 'Nửa đêm có tiếng sấm lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5161, 46112, '日本の気候は地方によって違う。', 'にほんの きこうは ちほうに よって ちがう。', 'Khí hậu Nhật Bản khác nhau theo từng vùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5162, 27180, 'わからない番号は１０４で聞きます。', 'わからない ばんごうは いちれいよんで ききます。', 'Số điện thoại không biết thì hỏi tổng đài 104.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5163, 44538, 'このカメラは日本のです。', 'この カメラは にほんの です。', 'Chiếc máy ảnh này là của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5164, 27308, '大阪城公園で花見をしました。', 'おおさかじょう こうえんで はなみを しました。', 'Tôi đã ngắm hoa ở công viên Lâu đài Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5165, 27420, '「七人の侍」は有名な映画です。', '「しちにんの さむらい」は ゆうめいな えいが です。', '"Bảy võ sĩ đạo" là một bộ phim nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5166, 27639, 'とり肉は牛肉より安いです。', 'とりにくは ぎゅうにくより やすい です。', 'Thịt gà rẻ hơn thịt bò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5167, 27790, 'ご家族は何人ですか。', 'ごかぞくは なんにん ですか。', 'Gia đình anh có mấy người?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5168, 27923, '父はビートルズの歌が好きです。', 'ちちは ビートルズの うたが すき です。', 'Bố tôi thích bài hát của The Beatles.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5169, 40848, 'りんごを丸ごとかじった。', 'りんごを まるごと かじった。', 'Tôi cắn nguyên quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5170, 40868, '彼は幾多の困難を乗り越えてきた。', 'かれは いくたの こんなんを のりこえて きた。', 'Anh ấy đã vượt qua vô số khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5171, 40948, '強いて言えば、青のほうが好きだ。', 'しいて いえば、あおの ほうが すきだ。', 'Nếu buộc phải nói thì tôi thích màu xanh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5172, 41053, '兼ねてから行きたかった店に行った。', 'かねてから いきたかった みせに いった。', 'Tôi đã đến quán mà từ lâu muốn ghé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5173, 41137, 'これは子供向けの番組だ。', 'これは こどもむけの ばんぐみだ。', 'Đây là chương trình dành cho trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5174, 41183, '今更謝っても遅い。', 'いまさら あやまっても おそい。', 'Giờ mới xin lỗi thì đã muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5175, 28410, '三宮で買い物をしました。', 'さんのみやで かいものを しました。', 'Tôi mua sắm ở Sannomiya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5176, 28762, '日光で東照宮を見ました。', 'にっこうで とうしょうぐうを みました。', 'Ở Nikko tôi đã xem đền Toshogu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5177, 28753, '車のキーをなくしました。', 'くるまの キーを なくしました。', 'Tôi làm mất chìa khóa xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5178, 28764, '京都のマンガミュージアムへ行きました。', 'きょうとの マンガミュージアムへ いきました。', 'Tôi đã đến bảo tàng truyện tranh Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5179, 41278, 'あたし、甘いものが大好きなの。', 'あたし、あまい ものが だいすきなの。', 'Em rất thích đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5180, 41281, '祖父は至って元気だ。', 'そふは いたって げんきだ。', 'Ông tôi vô cùng khỏe mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5181, 41304, '時折強い風が吹く。', 'ときおり つよい かぜが ふく。', 'Thỉnh thoảng có gió mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5182, 46115, '今、駅に向かっています。', 'いま、えきに むかって います。', 'Tôi đang trên đường đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5183, 46117, 'どちらの服を買うか迷っている。', 'どちらの ふくを かうか まよって いる。', 'Tôi đang phân vân không biết mua bộ nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5184, 46119, '帰りにスーパーに寄った。', 'かえりに スーパーに よった。', 'Trên đường về tôi ghé siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5185, 46122, '暑くて、アイスがすぐ溶けた。', 'あつくて、アイスが すぐ とけた。', 'Trời nóng nên kem tan ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5186, 46123, '夕日が山の向こうに沈んだ。', 'ゆうひが やまの むこうに しずんだ。', 'Mặt trời chiều đã lặn sau núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5187, 27527, 'ナンプラーはスパイス・コーナーにあります。', 'ナンプラーは スパイス・コーナーに あります。', 'Nước mắm Thái ở gian hàng gia vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5188, 27580, '私のクラスには学生が十五人います。', 'わたしの クラスには がくせいが じゅうごにん います。', 'Lớp tôi có mười lăm học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5189, 41342, '黒もしくは青のペンで書いてください。', 'くろ もしくは あおの ペンで かいて ください。', 'Hãy viết bằng bút đen hoặc xanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5190, 41357, '取りあえずビールをください。', 'とりあえず ビールを ください。', 'Trước hết cho tôi bia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5191, 41553, '真に申し訳ございません。', 'まことに もうしわけ ございません。', 'Thật sự vô cùng xin lỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5192, 41578, 'ここには多くの外国人が住んでいる。', 'ここには おおくの がいこくじんが すんで いる。', 'Ở đây có nhiều người nước ngoài sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5193, 41625, 'これは正しく私が探していた本だ。', 'これは まさしく わたしが さがして いた ほんだ。', 'Đây đích thực là cuốn sách tôi đang tìm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5194, 41696, '欠席する時は前もって知らせてください。', 'けっせき する ときは まえもって しらせて ください。', 'Khi vắng mặt hãy báo trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5195, 41703, '彼は然も知っているかのように話した。', 'かれは さも しって いるかの ように はなした。', 'Anh ta nói ra chiều như mình biết rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5196, 41793, '子供たちが代わる代わるブランコに乗った。', 'こどもたちが かわるがわる ブランコに のった。', 'Bọn trẻ thay phiên nhau chơi xích đu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5197, 41835, 'こっちのほうが断然安い。', 'こっちの ほうが だんぜん やすい。', 'Cái này rẻ hơn hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5198, 41898, '長々と話してしまって、すみません。', 'ながながと はなして しまって、すみません。', 'Xin lỗi vì đã nói dài dòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5199, 41960, '彼は職を転転とした。', 'かれは しょくを てんてんと した。', 'Anh ấy chuyển hết việc này sang việc khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5200, 41998, '一日でこの仕事を終えるのは到底無理だ。', 'いちにちで この しごとを おえるのは とうてい むりだ。', 'Hoàn thành việc này trong một ngày là hoàn toàn không thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5201, 29247, 'ベートーベンの曲が好きです。', 'ベートーベンの きょくが すき です。', 'Tôi thích nhạc của Beethoven.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5202, 44790, 'インターネットで電車の時間を調べました。', 'インターネットで でんしゃの じかんを しらべました。', 'Tôi tra giờ tàu trên Internet.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5203, 44791, '夏休みにどこへ行くか、まだ決めていません。', 'なつやすみに どこへ いくか、まだ きめて いません。', 'Tôi vẫn chưa quyết định nghỉ hè sẽ đi đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5204, 44794, '注文した本が届きました。', 'ちゅうもん した ほんが とどきました。', 'Cuốn sách tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5205, 46651, '医学の進歩で、多くの病気が治るようになった。', 'いがくの しんぽで、おおくの びょうきが なおる ように なった。', 'Nhờ tiến bộ y học, nhiều bệnh đã chữa được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5206, 44795, '友達を駅まで送りました。', 'ともだちを えきまで おくりました。', 'Tôi tiễn bạn ra ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5207, 44798, '電車が十分遅れています。', 'でんしゃが じゅっぷん おくれて います。', 'Tàu đang trễ mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5208, 44799, '毎日運動を続けています。', 'まいにち うんどうを つづけて います。', 'Tôi duy trì tập thể dục mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5209, 44801, '古い切手を集めています。', 'ふるい きってを あつめて います。', 'Tôi đang sưu tầm tem cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5210, 44803, 'これは大事な書類です。', 'これは だいじな しょるい です。', 'Đây là tài liệu quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5211, 46654, '図書館は誰でも無料で利用できます。', 'としょかんは だれでも むりょうで りよう できます。', 'Ai cũng có thể sử dụng thư viện miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5212, 46857, '父は株で大きな損をした。', 'ちちは かぶで おおきな そんを した。', 'Bố tôi lỗ nặng vì cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5213, 46861, 'やっと借金を全部返した。', 'やっと しゃっきんを ぜんぶ かえした。', 'Cuối cùng tôi cũng trả hết nợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5214, 46129, '姉は金融関係の会社に勤めている。', 'あねは きんゆう かんけいの かいしゃに つとめて いる。', 'Chị tôi làm ở một công ty tài chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5215, 38209, '祖父がこの奨学金制度を創設した。', 'そふが この しょうがくきん せいどを そうせつ した。', 'Ông tôi đã lập ra chế độ học bổng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5216, 44788, 'この店の果物はほとんどが輸入品だ。', 'この みせの くだものは ほとんどが ゆにゅうひんだ。', 'Hoa quả ở cửa hàng này hầu hết là hàng nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5217, 37995, '最低賃金が来月から上がる。', 'さいてい ちんぎんが らいげつから あがる。', 'Lương tối thiểu sẽ tăng từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5218, 46126, '今日は海が穏やかだ。', 'きょうは うみが おだやかだ。', 'Hôm nay biển lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5219, 46127, '彼は見事に試験に合格した。', 'かれは みごとに しけんに ごうかく した。', 'Anh ấy đã thi đỗ một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5220, 46125, '頂上までの道はとても険しかった。', 'ちょうじょうまでの みちは とても けわしかった。', 'Đường lên đỉnh núi rất hiểm trở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5221, 37813, '子供の個性を大切にしたい。', 'こどもの こせいを たいせつに したい。', 'Tôi muốn trân trọng cá tính của con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5222, 37794, '引っ越しの見積もりを三社に頼んだ。', 'ひっこしの みつもりを さんしゃに たのんだ。', 'Tôi nhờ ba công ty báo giá chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5223, 27638, '豚肉と野菜を炒めました。', 'ぶたにくと やさいを いためました。', 'Tôi xào thịt lợn với rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5224, 27751, 'はい、お釣りです。', 'はい、おつり です。', 'Đây là tiền thừa của quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5225, 27843, '札幌の雪祭りを見に行きたいです。', 'さっぽろの ゆきまつりを みに いきたい です。', 'Tôi muốn đi xem lễ hội tuyết ở Sapporo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5226, 38236, '経理担当者が会社の金を横領した。', 'けいり たんとうしゃが かいしゃの かねを おうりょう した。', 'Nhân viên kế toán đã biển thủ tiền công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5227, 38624, '昨日は疲れていたので、ぐっすり眠りました。', 'きのうは つかれて いたので、ぐっすり ねむりました。', 'Hôm qua mệt nên tôi ngủ say.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5228, 38655, '祖父は昔、タイプライターで手紙を書いていた。', 'そふは むかし、タイプライターで てがみを かいて いた。', 'Ngày xưa ông tôi viết thư bằng máy đánh chữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5229, 46884, 'この町は観光で大きく発展した。', 'この まちは かんこうで おおきく はってん した。', 'Thị trấn này phát triển mạnh nhờ du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5230, 46955, 'みんなで協力して、部屋を片付けた。', 'みんなで きょうりょく して、へやを かたづけた。', 'Mọi người cùng hợp sức dọn dẹp căn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5231, 46963, '彼はやっと自分の間違いを認めた。', 'かれは やっと じぶんの まちがいを みとめた。', 'Cuối cùng anh ấy cũng thừa nhận sai lầm của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5232, 47011, '医学の進歩で、多くの病気が治るようになった。', 'いがくの しんぽで、おおくの びょうきが なおる ように なった。', 'Nhờ tiến bộ y học, nhiều bệnh đã chữa được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5233, 47014, '図書館は誰でも無料で利用できます。', 'としょかんは だれでも むりょうで りよう できます。', 'Ai cũng có thể sử dụng thư viện miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5234, 38839, '議長が会議の開始を告げた。', 'ぎちょうが かいぎの かいしを つげた。', 'Chủ tọa tuyên bố khai mạc cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5235, 38855, '魚市場は朝早くからにぎやかだ。', 'うおいちばは あさ はやくから にぎやかだ。', 'Chợ cá nhộn nhịp từ sáng sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5236, 38878, '銀の指輪をプレゼントした。', 'ぎんの ゆびわを プレゼント した。', 'Tôi đã tặng một chiếc nhẫn bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5237, 38779, 'アルバイトで学費を稼いでいる。', 'アルバイトで がくひを かせいで いる。', 'Tôi làm thêm để kiếm tiền học phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5238, 38596, 'シャツにアイロンをかけた。', 'シャツに アイロンを かけた。', 'Tôi đã là áo sơ mi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5239, 38703, '夏休みに海でヨットに乗った。', 'なつやすみに うみで ヨットに のった。', 'Kỳ nghỉ hè tôi đi thuyền buồm trên biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5240, 38739, '秋になると、稲が黄色くなる。', 'あきに なると、いねが きいろく なる。', 'Sang thu, lúa chín vàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5241, 28413, '部屋に花を飾りました。', 'へやに はなを かざりました。', 'Tôi trang trí phòng bằng hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5242, 44807, '父はとても厳しいです。', 'ちちは とても きびしい です。', 'Bố tôi rất nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5243, 38425, '社長は三時においでになります。', 'しゃちょうは さんじに おいでに なります。', 'Giám đốc sẽ đến lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5244, 38716, '子供の手をしっかり握って道を渡った。', 'こどもの てを しっかり にぎって みちを わたった。', 'Tôi nắm chặt tay con rồi qua đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5245, 38742, '子供が母親の手を引っ張った。', 'こどもが ははおやの てを ひっぱった。', 'Đứa trẻ kéo tay mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5246, 38600, 'あらゆる方法を試してみた。', 'あらゆる ほうほうを ためして みた。', 'Tôi đã thử mọi cách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5247, 46132, 'アルバイトで毎月五万円の収入がある。', 'アルバイトで まいつき ごまんえんの しゅうにゅうが ある。', 'Tôi có thu nhập năm mươi nghìn yên mỗi tháng nhờ làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5248, 39689, '先生が宿題のプリントを配った。', 'せんせいが しゅくだいの プリントを くばった。', 'Thầy phát tờ bài tập về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5249, 39596, 'この映画のシリーズは全部見た。', 'この えいがの シリーズは ぜんぶ みた。', 'Tôi đã xem hết loạt phim này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5250, 39711, 'タクシーのメーターがどんどん上がる。', 'タクシーの メーターが どんどん あがる。', 'Đồng hồ tính tiền taxi cứ nhảy liên tục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5251, 41822, 'うちの旦那は料理が上手だ。', 'うちの だんなは りょうりが じょうずだ。', 'Ông xã nhà tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5252, 44818, '壁に絵が掛けてあります。', 'かべに えが かけて あります。', 'Trên tường có treo một bức tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5253, 44822, '出かける前に鏡を見ます。', 'でかける まえに かがみを みます。', 'Trước khi ra ngoài tôi soi gương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5254, 28992, 'このりんごは気が強いです。', 'このりんごはきがつよいです。', 'Quả táo này tough.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5255, 44814, '近所にスーパーがあるので、便利です。', 'きんじょに スーパーが あるので、べんり です。', 'Gần nhà có siêu thị nên rất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5256, 46137, '父は株で大きな損をした。', 'ちちは かぶで おおきな そんを した。', 'Bố tôi lỗ nặng vì cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5257, 44820, '床に本が落ちています。', 'ゆかに ほんが おちて います。', 'Trên sàn có quyển sách rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5258, 44782, 'ルールを守ってください。', 'ルールを まもって ください。', 'Hãy tuân thủ luật lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5259, 44813, '大家さんに家賃を払いました。', 'おおやさんに やちんを はらいました。', 'Tôi trả tiền thuê nhà cho chủ nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5260, 44817, 'この部屋は畳が六枚あります。', 'この へやは たたみが ろくまい あります。', 'Phòng này có sáu chiếu tatami.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5261, 44825, '水道の水を飲むことができます。', 'すいどうの みずを のむ ことが できます。', 'Có thể uống nước máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5262, 41852, '彼は自分の行動を恥じた。', 'かれは じぶんの こうどうを はじた。', 'Anh ấy thấy xấu hổ vì hành động của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5263, 38892, '駅まで迎えに来てくれますか。', 'えきまで むかえに きて くれますか。', 'Bạn ra ga đón tôi được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5264, 39354, '仕事の付き合いで、毎週飲みに行く。', 'しごとの つきあいで、まいしゅう のみに いく。', 'Vì quan hệ công việc, tuần nào tôi cũng đi nhậu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5265, 39355, '社長夫人がパーティーに来られた。', 'しゃちょう ふじんが パーティーに こられた。', 'Phu nhân giám đốc đã đến dự tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5266, 39461, 'いつまでも親に頼ってはいけない。', 'いつまでも おやに たよっては いけない。', 'Không thể cứ dựa dẫm vào bố mẹ mãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5267, 42885, 'ホテルのボーイが荷物を運んでくれた。', 'ホテルの ボーイが にもつを はこんで くれた。', 'Nhân viên khách sạn đã mang hành lý giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5268, 46136, '彼は財産をすべて寄付した。', 'かれは ざいさんを すべて きふ した。', 'Ông ấy đã quyên góp toàn bộ tài sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5269, 44819, '屋根の上に猫がいる。', 'やねの うえに ねこが いる。', 'Có con mèo trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5270, 46135, '彼は親から大きな資産を受け継いだ。', 'かれは おやから おおきな しさんを うけついだ。', 'Anh ấy thừa hưởng khối tài sản lớn từ cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5271, 39852, 'けがをしたので、外科で診てもらった。', 'けがを したので、げかで みて もらった。', 'Bị thương nên tôi đến khoa ngoại khám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5272, 39775, '台風が来るので、雨戸を閉めた。', 'たいふうが くるので、あまどを しめた。', 'Bão sắp đến nên tôi đóng cửa chớp chống mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5273, 39828, '市民会館でコンサートがある。', 'しみん かいかんで コンサートが ある。', 'Có buổi hòa nhạc ở nhà văn hóa thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5274, 44821, '棚の上に本があります。', 'たなの うえに ほんが あります。', 'Trên giá có sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5275, 44808, 'もうすぐ夏休みです。', 'もうすぐ なつやすみ です。', 'Sắp đến kỳ nghỉ hè rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5276, 44812, 'このアパートの家賃は六万円です。', 'この アパートの やちんは ろくまんえん です。', 'Tiền thuê căn hộ này là sáu mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5277, 44816, '布団は押し入れに入れます。', 'ふとんは おしいれに いれます。', 'Chăn nệm được cất vào tủ âm tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5278, 41857, 'この地方は畜産が盛んだ。', 'この ちほうは ちくさんが さかんだ。', 'Vùng này chăn nuôi gia súc phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5279, 41874, '山の中腹で休憩した。', 'やまの ちゅうふくで きゅうけい した。', 'Chúng tôi nghỉ chân ở lưng chừng núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5280, 44836, '外国の文化に興味があります。', 'がいこくの ぶんかに きょうみが あります。', 'Tôi quan tâm đến văn hóa nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5281, 42888, 'ママ、おなかがすいた。', 'ママ、おなかが すいた。', 'Mẹ ơi, con đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5282, 38796, '大きな音で目が覚めた。', 'おおきな おとで めが さめた。', 'Tôi tỉnh giấc vì một tiếng động lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5283, 38095, '歯の治療に毎週通っている。', 'はの ちりょうに まいしゅう かよって いる。', 'Tuần nào tôi cũng đi chữa răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5284, 44881, '彼はサッカーの日本代表選手だ。', 'かれは サッカーの にほん だいひょう せんしゅだ。', 'Anh ấy là tuyển thủ bóng đá quốc gia Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5285, 44893, '博物館で古い土器を見た。', 'はくぶつかんで ふるい どきを みた。', 'Tôi xem đồ gốm cổ ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5286, 44895, '日曜日に子供を連れて遊園地に行った。', 'にちようびに こどもを つれて ゆうえんちに いった。', 'Chủ nhật tôi đưa con đi công viên giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5287, 44890, '旅行のお土産を買いました。', 'りょこうの おみやげを かいました。', 'Tôi đã mua quà du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5288, 44879, 'どんなスポーツが好きですか。', 'どんな スポーツが すき ですか。', 'Bạn thích môn thể thao nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5289, 44827, '料理の道具を買いました。', 'りょうりの どうぐを かいました。', 'Tôi mua dụng cụ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5290, 44824, '出かける前にガスを止めてください。', 'でかける まえに ガスを とめて ください。', 'Trước khi ra ngoài hãy khóa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5291, 44883, '毎週柔道を習っています。', 'まいしゅう じゅうどうを ならって います。', 'Hằng tuần tôi học judo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5292, 44896, '日本人と会話するのは楽しいです。', 'にほんじんと かいわ するのは たのしい です。', 'Nói chuyện với người Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5293, 44833, 'カレーの材料を買いに行きます。', 'カレーの ざいりょうを かいに いきます。', 'Tôi đi mua nguyên liệu nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5294, 44823, 'カーテンを開けてください。', 'カーテンを あけて ください。', 'Hãy kéo rèm cửa ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5295, 44828, 'この機械の使い方を教えてください。', 'この きかいの つかいかたを おしえて ください。', 'Hãy chỉ tôi cách dùng chiếc máy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5296, 44878, '毎晩テレビでニュースを見ます。', 'まいばん テレビで ニュースを みます。', 'Tối nào tôi cũng xem tin tức trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5297, 44830, '掃除機で部屋を掃除しました。', 'そうじきで へやを そうじ しました。', 'Tôi dọn phòng bằng máy hút bụi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5298, 44832, 'お湯を沸かして、お茶を入れました。', 'おゆを わかして、おちゃを いれました。', 'Tôi đun nước nóng để pha trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5299, 44886, '京都でお寺を見物しました。', 'きょうとで おてらを けんぶつ しました。', 'Tôi tham quan chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5300, 44965, '桜の花が散ってしまいました。', 'さくらの はなが ちって しまいました。', 'Hoa anh đào đã rụng hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5301, 44967, '私は田舎で育ちました。', 'わたしは いなかで そだちました。', 'Tôi lớn lên ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5302, 40437, 'コンパスで円を描いた。', 'コンパスで えんを かいた。', 'Tôi vẽ hình tròn bằng com-pa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5303, 40449, '寒いのでジャンパーを着て出かけた。', 'さむいので ジャンパーを きて でかけた。', 'Trời lạnh nên tôi mặc áo khoác ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5304, 40504, 'デザートにアイスクリームを頼んだ。', 'デザートに アイスクリームを たのんだ。', 'Tôi gọi kem làm món tráng miệng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5305, 40450, 'スキーのジャンプ競技を見に行った。', 'スキーの ジャンプ きょうぎを みに いった。', 'Tôi đi xem môn nhảy xa trượt tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5306, 42265, '氏名並びに住所を記入してください。', 'しめい ならびに じゅうしょを きにゅう して ください。', 'Hãy ghi họ tên và địa chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5307, 42361, '事件の犯人は未だに捕まっていない。', 'じけんの はんにんは いまだに つかまって いない。', 'Thủ phạm vụ án đến nay vẫn chưa bị bắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5308, 44988, '宿題はほとんど終わりました。', 'しゅくだいは ほとんど おわりました。', 'Bài tập gần như xong hết rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5309, 44969, '地震で家が揺れました。', 'じしんで いえが ゆれました。', 'Động đất làm ngôi nhà rung lắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5310, 44971, '雨が止んだら、出かけましょう。', 'あめが やんだら、でかけましょう。', 'Mưa tạnh thì ra ngoài nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5311, 44975, '町の様子がずいぶん変わりました。', 'まちの ようすが ずいぶん かわりました。', 'Diện mạo thị trấn đã thay đổi nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5312, 44976, '雨の日が続いています。', 'あめの ひが つづいて います。', 'Những ngày mưa vẫn kéo dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5313, 44981, '富士山は美しい山です。', 'ふじさんは うつくしい やま です。', 'Núi Phú Sĩ là ngọn núi đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5315, 44986, 'これは貴重な経験でした。', 'これは きちょうな けいけん でした。', 'Đây là một trải nghiệm quý giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5316, 47703, '医者には高い倫理観が必要だ。', 'いしゃには たかい りんりかんが ひつようだ。', 'Bác sĩ cần có ý thức đạo đức cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5317, 44974, '運動を始めてから、体重が三キロ減りました。', 'うんどうを はじめてから、たいじゅうが さんキロ へりました。', 'Từ khi bắt đầu tập thể dục, tôi đã giảm ba ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5318, 44977, '約束は必ず守ります。', 'やくそくは かならず まもります。', 'Tôi nhất định sẽ giữ lời hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5319, 38097, 'けがをして、一週間入院した。', 'けがを して、いっしゅうかん にゅういん した。', 'Tôi bị thương và phải nằm viện một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5320, 38099, '会社で年に一度、検診がある。', 'かいしゃで ねんに いちど、けんしんが ある。', 'Công ty khám sức khỏe định kỳ mỗi năm một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5321, 45262, '試験の前に単語を暗記した。', 'しけんの まえに たんごを あんき した。', 'Trước kỳ thi tôi học thuộc lòng từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5322, 45622, '試験の前に単語を暗記した。', 'しけんの まえに たんごを あんき した。', 'Trước kỳ thi tôi học thuộc lòng từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5323, 45982, '試験の前に単語を暗記した。', 'しけんの まえに たんごを あんき した。', 'Trước kỳ thi tôi học thuộc lòng từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5324, 45625, 'この小説はいろいろな言語に翻訳されている。', 'この しょうせつは いろいろな げんごに ほんやく されて いる。', 'Cuốn tiểu thuyết này đã được dịch ra nhiều thứ tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5325, 44982, '夜中に激しい雨が降った。', 'よなかに はげしい あめが ふった。', 'Nửa đêm trời mưa dữ dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5326, 45264, '日本語の発音を練習している。', 'にほんごの はつおんを れんしゅう して いる。', 'Tôi đang luyện phát âm tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5327, 45266, '会議で社長の通訳をした。', 'かいぎで しゃちょうの つうやくを した。', 'Tôi phiên dịch cho giám đốc trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5328, 45620, '授業の前に予習しておきましょう。', 'じゅぎょうの まえに よしゅう して おきましょう。', 'Hãy chuẩn bị bài trước giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5329, 45623, '先生の説明をやっと理解できた。', 'せんせいの せつめいを やっと りかい できた。', 'Cuối cùng tôi cũng hiểu được lời giải thích của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5330, 45626, '会議で社長の通訳をした。', 'かいぎで しゃちょうの つうやくを した。', 'Tôi phiên dịch cho giám đốc trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5331, 45619, 'クラスメートと一緒に宿題をした。', 'クラスメートと いっしょに しゅくだいを した。', 'Tôi làm bài tập cùng bạn cùng lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5332, 45981, '授業のあと、すぐに復習するといい。', 'じゅぎょうの あと、すぐに ふくしゅう すると いい。', 'Học xong nên ôn bài ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5333, 45986, '会議で社長の通訳をした。', 'かいぎで しゃちょうの つうやくを した。', 'Tôi phiên dịch cho giám đốc trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5334, 27720, 'パスポートを見せてください。', 'パスポートを みせて ください。', 'Xin cho tôi xem hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5335, 38102, 'どんな症状がありますか。', 'どんな しょうじょうが ありますか。', 'Bạn có triệu chứng gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5336, 39316, '髪の毛を短く切った。', 'かみのけを みじかく きった。', 'Tôi đã cắt tóc ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5337, 39327, '温泉に入って、旅の疲れがとれた。', 'おんせんに はいって、たびの つかれが とれた。', 'Ngâm suối nước nóng xong, mệt mỏi của chuyến đi tan biến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5338, 39415, '命より大切なものはない。', 'いのちより たいせつな ものは ない。', 'Không gì quý hơn mạng sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5339, 39459, '子供たちが裸で川で遊んでいる。', 'こどもたちが はだかで かわで あそんで いる。', 'Bọn trẻ cởi trần nô đùa dưới sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5340, 43985, '緊張して、胸がどきどきする。', 'きんちょう して、むねが どきどき する。', 'Hồi hộp quá, tim đập thình thịch trong ngực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5341, 43997, '毎日七時間は睡眠をとるようにしている。', 'まいにち しちじかんは すいみんを とる ように して いる。', 'Tôi cố ngủ đủ bảy tiếng mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5342, 44010, 'ここで十分休憩しましょう。', 'ここで じゅっぷん きゅうけい しましょう。', 'Nghỉ giải lao mười phút ở đây nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5343, 44017, '走りすぎて、息が苦しい。', 'はしりすぎて、いきが くるしい。', 'Chạy nhiều quá nên thở không nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5344, 44275, '隣の夫婦はとても仲がいい。', 'となりの ふうふは とても なかが いい。', 'Cặp vợ chồng nhà bên rất hòa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5345, 44314, '彼とは高校時代から親しくしている。', 'かれとは こうこう じだいから したしく して いる。', 'Tôi thân với anh ấy từ thời cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5346, 44345, '緊張して、胸がどきどきする。', 'きんちょう して、むねが どきどき する。', 'Hồi hộp quá, tim đập thình thịch trong ngực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5347, 44357, '毎日七時間は睡眠をとるようにしている。', 'まいにち しちじかんは すいみんを とる ように して いる。', 'Tôi cố ngủ đủ bảy tiếng mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5348, 44370, 'ここで十分休憩しましょう。', 'ここで じゅっぷん きゅうけい しましょう。', 'Nghỉ giải lao mười phút ở đây nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5349, 44635, '隣の夫婦はとても仲がいい。', 'となりの ふうふは とても なかが いい。', 'Cặp vợ chồng nhà bên rất hòa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5350, 44645, '弟とつまらないことで喧嘩した。', 'おとうとと つまらない ことで けんか した。', 'Tôi cãi nhau với em trai vì chuyện vớ vẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5351, 44695, 'けがをして、一週間入院した。', 'けがを して、いっしゅうかん にゅういん した。', 'Tôi bị thương và phải nằm viện một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11140, 43762, 'ケーキを一つください。', 'ケーキを ひとつ ください。', 'Cho tôi một cái bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5352, 44705, '緊張して、胸がどきどきする。', 'きんちょう して、むねが どきどき する。', 'Hồi hộp quá, tim đập thình thịch trong ngực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5353, 44712, '魚の骨がのどに刺さった。', 'さかなの ほねが のどに ささった。', 'Xương cá bị hóc trong cổ họng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5354, 44717, '毎日七時間は睡眠をとるようにしている。', 'まいにち しちじかんは すいみんを とる ように して いる。', 'Tôi cố ngủ đủ bảy tiếng mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5355, 44737, '走りすぎて、息が苦しい。', 'はしりすぎて、いきが くるしい。', 'Chạy nhiều quá nên thở không nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5356, 29155, '寝る前に子どもに絵本を読んでやります。', 'ねる まえに こどもに えほんを よんで やります。', 'Trước khi ngủ tôi đọc truyện tranh cho con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5357, 42373, '無闇に薬を飲むのはよくない。', 'むやみに くすりを のむのは よくない。', 'Uống thuốc bừa bãi là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5358, 42587, '夜中なのに部屋の明かりが煌々とついている。', 'よなか なのに へやの あかりが こうこうと ついて いる。', 'Nửa đêm rồi mà đèn trong phòng vẫn sáng rực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5359, 42591, '最近、碌なことがない。', 'さいきん、ろくな ことが ない。', 'Dạo này chẳng có chuyện gì ra hồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5360, 43234, '弟は注射を怖がる。', 'おとうとは ちゅうしゃを こわがる。', 'Em trai tôi sợ tiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5361, 43237, '手伝ってくれて、サンキュー。', 'てつだって くれて、サンキュー。', 'Cảm ơn vì đã giúp nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5362, 38807, '医者に運動を勧められました。', 'いしゃに うんどうを すすめられました。', 'Tôi được bác sĩ khuyên nên tập thể dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5363, 38810, '寒くて指の感覚がなくなった。', 'さむくて ゆびの かんかくが なくなった。', 'Lạnh quá, ngón tay mất cả cảm giác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5364, 38811, '手伝ってくれたみんなに感謝しています。', 'てつだって くれた みんなに かんしゃ して います。', 'Tôi biết ơn mọi người đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5365, 38813, '細い管を通して水を流す。', 'ほそい くだを とおして みずを ながす。', 'Cho nước chảy qua một ống nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5366, 38815, '環境に関する本を読んでいます。', 'かんきょうに かんする ほんを よんで います。', 'Tôi đang đọc sách liên quan đến môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5367, 38818, '大きな岩の上に座って海を見た。', 'おおきな いわの うえに すわって うみを みた。', 'Tôi ngồi trên tảng đá lớn ngắm biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5368, 38820, '皆様の健康を願っております。', 'みなさまの けんこうを ねがって おります。', 'Kính chúc mọi người mạnh khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5369, 38823, 'この映画は本当の話を基にしている。', 'この えいがは ほんとうの はなしを もとに して いる。', 'Bộ phim này dựa trên câu chuyện có thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5370, 38824, '調査の結果に基づいて計画を立てた。', 'ちょうさの けっかに もとづいて けいかくを たてた。', 'Chúng tôi lập kế hoạch dựa trên kết quả khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5371, 38827, '駅に着いたとき、電車は既に出ていた。', 'えきに ついた とき、でんしゃは すでに でて いた。', 'Khi tôi đến ga thì tàu đã chạy mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5372, 38828, '両親は私に大きな期待をしている。', 'りょうしんは わたしに おおきな きたいを して いる。', 'Bố mẹ kỳ vọng rất nhiều vào tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5373, 38830, 'このかばんがとても気に入りました。', 'この かばんが とても きに いりました。', 'Tôi rất ưng chiếc túi này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5374, 38832, '財布を落としたことに気付かなかった。', 'さいふを おとした ことに きづかなかった。', 'Tôi không nhận ra mình đã đánh rơi ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5375, 38835, '節分には「鬼は外」と言って豆をまく。', 'せつぶんには 「おには そと」と いって まめを まく。', 'Vào lễ Setsubun, người ta vừa rải đậu vừa hô "quỷ ra ngoài".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5376, 38838, '新しい法律が議会で決まった。', 'あたらしい ほうりつが ぎかいで きまった。', 'Luật mới đã được quốc hội thông qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5377, 38840, 'かばんに服を詰めて、旅行に出かけた。', 'かばんに ふくを つめて、りょこうに でかけた。', 'Tôi nhét quần áo vào túi rồi lên đường du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5378, 38843, '丘の上から町全体が見える。', 'おかの うえから まち ぜんたいが みえる。', 'Từ trên đồi có thể nhìn thấy cả thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5379, 38844, '夏に一週間の休暇を取る予定です。', 'なつに いっしゅうかんの きゅうかを とる よてい です。', 'Mùa hè tôi định nghỉ phép một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5380, 38846, 'たばこは体に悪い影響を及ぼす。', 'たばこは からだに わるい えいきょうを およぼす。', 'Thuốc lá gây ảnh hưởng xấu đến cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5381, 38848, 'スマートフォンは急速に広まった。', 'スマートフォンは きゅうそくに ひろまった。', 'Điện thoại thông minh đã lan rộng nhanh chóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5382, 38850, '市民は政府に説明を求めている。', 'しみんは せいふに せつめいを もとめて いる。', 'Người dân đang yêu cầu chính phủ giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5383, 38833, '新聞でおもしろい記事を読んだ。', 'しんぶんで おもしろい きじを よんだ。', 'Tôi đã đọc một bài báo thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5384, 38834, '夜空に星が輝いている。', 'よぞらに ほしが かがやいて いる。', 'Những vì sao lấp lánh trên bầu trời đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5385, 38852, '授業中に居眠りをして、先生に注意された。', 'じゅぎょうちゅうに いねむりを して、せんせいに ちゅうい された。', 'Tôi ngủ gật trong giờ học và bị thầy nhắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5386, 38856, '家族と共に新年を迎えた。', 'かぞくと ともに しんねんを むかえた。', 'Tôi đón năm mới cùng gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5387, 38857, '「助けて!」と誰かが叫んだ。', '「たすけて!」と だれかが さけんだ。', 'Có ai đó hét lên "Cứu với!".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5388, 38859, '昨夜、近くの銀行に強盗が入った。', 'ゆうべ、ちかくの ぎんこうに ごうとうが はいった。', 'Tối qua ngân hàng gần đây bị cướp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5389, 38861, 'ゆうべ、恐ろしい夢を見た。', 'ゆうべ、おそろしい ゆめを みた。', 'Tối qua tôi gặp một giấc mơ đáng sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5390, 38864, '時計が五分狂っている。', 'とけいが ごふん くるって いる。', 'Đồng hồ bị lệch năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5391, 28416, '使った物は元の所に戻してください。', 'つかった ものは もとの ところに もどして ください。', 'Đồ đã dùng hãy để lại chỗ cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5392, 38868, '残りの時間はわずか五分です。', 'のこりの じかんは わずか ごふん です。', 'Thời gian còn lại chỉ vỏn vẹn năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5393, 38870, 'この小説は筋がおもしろい。', 'この しょうせつは すじが おもしろい。', 'Tiểu thuyết này có cốt truyện hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5394, 38872, 'この町には近代的な建物が多い。', 'この まちには きんだいてきな たてものが おおい。', 'Thành phố này có nhiều tòa nhà hiện đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5395, 38874, '大事な書類は金庫にしまってある。', 'だいじな しょるいは きんこに しまって ある。', 'Giấy tờ quan trọng được cất trong két sắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5396, 38877, '姉は金融関係の会社に勤めている。', 'あねは きんゆう かんけいの かいしゃに つとめて いる。', 'Chị tôi làm ở một công ty tài chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5397, 38880, '彼は長い間、病気に苦しんだ。', 'かれは ながい あいだ、びょうきに くるしんだ。', 'Anh ấy đã khổ sở vì bệnh suốt thời gian dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5398, 38882, '冷蔵庫の中は空っぽだった。', 'れいぞうこの なかは からっぽ だった。', 'Trong tủ lạnh trống trơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5399, 38875, '友達と金銭の貸し借りはしないほうがいい。', 'ともだちと きんせんの かしかりは しない ほうが いい。', 'Không nên vay mượn tiền bạc với bạn bè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5400, 44995, '隣の夫婦はとても仲がいい。', 'となりの ふうふは とても なかが いい。', 'Cặp vợ chồng nhà bên rất hòa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5401, 45079, '他人の物を勝手に使ってはいけない。', 'たにんの ものを かってに つかっては いけない。', 'Không được tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5402, 45086, '手伝ってくれたみんなに感謝しています。', 'てつだって くれた みんなに かんしゃ して います。', 'Tôi biết ơn mọi người đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5403, 45199, '新聞でおもしろい記事を読んだ。', 'しんぶんで おもしろい きじを よんだ。', 'Tôi đã đọc một bài báo thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5404, 45242, '教科書の二十ページを開いてください。', 'きょうかしょの にじゅっページを ひらいて ください。', 'Hãy mở sách giáo khoa trang 20.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5405, 45256, '田中教授は経済学の専門家です。', 'たなか きょうじゅは けいざいがくの せんもんか です。', 'Giáo sư Tanaka là chuyên gia kinh tế học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5406, 45311, '子供には栄養のある物を食べさせたい。', 'こどもには えいようの ある ものを たべさせたい。', 'Tôi muốn cho con ăn đồ bổ dưỡng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5407, 45383, '大きな岩の上に座って海を見た。', 'おおきな いわの うえに すわって うみを みた。', 'Tôi ngồi trên tảng đá lớn ngắm biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5408, 45439, '他人の物を勝手に使ってはいけない。', 'たにんの ものを かってに つかっては いけない。', 'Không được tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5409, 45471, '大きな企業で働きたい。', 'おおきな きぎょうで はたらきたい。', 'Tôi muốn làm việc ở doanh nghiệp lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5410, 45602, '教科書の二十ページを開いてください。', 'きょうかしょの にじゅっページを ひらいて ください。', 'Hãy mở sách giáo khoa trang 20.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5411, 45671, '子供には栄養のある物を食べさせたい。', 'こどもには えいようの ある ものを たべさせたい。', 'Tôi muốn cho con ăn đồ bổ dưỡng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5412, 45743, '大きな岩の上に座って海を見た。', 'おおきな いわの うえに すわって うみを みた。', 'Tôi ngồi trên tảng đá lớn ngắm biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5413, 45799, '他人の物を勝手に使ってはいけない。', 'たにんの ものを かってに つかっては いけない。', 'Không được tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5414, 45802, '昨日の敵は今日の友。', 'きのうの てきは きょうの とも。', 'Kẻ thù hôm qua là bạn hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5415, 45806, '手伝ってくれたみんなに感謝しています。', 'てつだって くれた みんなに かんしゃ して います。', 'Tôi biết ơn mọi người đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5416, 45919, '新聞でおもしろい記事を読んだ。', 'しんぶんで おもしろい きじを よんだ。', 'Tôi đã đọc một bài báo thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5417, 45976, '田中教授は経済学の専門家です。', 'たなか きょうじゅは けいざいがくの せんもんか です。', 'Giáo sư Tanaka là chuyên gia kinh tế học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5418, 46031, '子供には栄養のある物を食べさせたい。', 'こどもには えいようの ある ものを たべさせたい。', 'Tôi muốn cho con ăn đồ bổ dưỡng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5419, 46278, '午前中に病院で診察を受けた。', 'ごぜんちゅうに びょういんで しんさつを うけた。', 'Sáng nay tôi đi khám ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5420, 46281, '父は来週、胃の手術を受ける。', 'ちちは らいしゅう、いの しゅじゅつを うける。', 'Tuần sau bố tôi sẽ mổ dạ dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5421, 46286, 'この薬は眠くなる副作用がある。', 'この くすりは ねむく なる ふくさようが ある。', 'Thuốc này có tác dụng phụ gây buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5422, 46288, '手術のあと、順調に回復している。', 'しゅじゅつの あと、じゅんちょうに かいふく して いる。', 'Sau phẫu thuật, tôi đang hồi phục tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5423, 46355, 'この小説は筋がおもしろい。', 'この しょうせつは すじが おもしろい。', 'Tiểu thuyết này có cốt truyện hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5424, 46380, '今夜、町内会の会合がある。', 'こんや、ちょうないかいの かいごうが ある。', 'Tối nay có buổi họp tổ dân phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5425, 46638, '午前中に病院で診察を受けた。', 'ごぜんちゅうに びょういんで しんさつを うけた。', 'Sáng nay tôi đi khám ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
