INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5431, 46758, '仕事の付き合いで、毎週飲みに行く。', 'しごとの つきあいで、まいしゅう のみに いく。', 'Vì quan hệ công việc, tuần nào tôi cũng đi nhậu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
