INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5434, 47007, 'この病院は患者がとても多い。', 'この びょういんは かんじゃが とても おおい。', 'Bệnh viện này có rất nhiều bệnh nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5435, 47008, '手術のあと、順調に回復している。', 'しゅじゅつの あと、じゅんちょうに かいふく して いる。', 'Sau phẫu thuật, tôi đang hồi phục tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5436, 47075, 'この小説は筋がおもしろい。', 'この しょうせつは すじが おもしろい。', 'Tiểu thuyết này có cốt truyện hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5437, 47100, '今夜、町内会の会合がある。', 'こんや、ちょうないかいの かいごうが ある。', 'Tối nay có buổi họp tổ dân phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5438, 47118, '仕事の付き合いで、毎週飲みに行く。', 'しごとの つきあいで、まいしゅう のみに いく。', 'Vì quan hệ công việc, tuần nào tôi cũng đi nhậu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5439, 47511, 'この町には近代的な建物が多い。', 'この まちには きんだいてきな たてものが おおい。', 'Thành phố này có nhiều tòa nhà hiện đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5440, 47871, 'この町には近代的な建物が多い。', 'この まちには きんだいてきな たてものが おおい。', 'Thành phố này có nhiều tòa nhà hiện đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5441, 48231, 'この町には近代的な建物が多い。', 'この まちには きんだいてきな たてものが おおい。', 'Thành phố này có nhiều tòa nhà hiện đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5442, 28419, '旅行の日にちを決めました。', 'りょこうの ひにちを きめました。', 'Tôi đã quyết định ngày đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5443, 28421, '習った言葉を毎日復習します。', 'ならった ことばを まいにち ふくしゅう します。', 'Ngày nào tôi cũng ôn lại các từ đã học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5444, 28433, '娘に人形を買ってあげました。', 'むすめに にんぎょうを かって あげました。', 'Tôi mua búp bê cho con gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5445, 28441, '使ったはさみは元の所に戻してください。', 'つかった はさみは もとの ところに もどして ください。', 'Kéo đã dùng hãy để lại chỗ cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5446, 28447, '地震のために非常袋を準備しておきます。', 'じしんの ために ひじょうぶくろを じゅんび して おきます。', 'Tôi chuẩn bị sẵn túi đồ khẩn cấp phòng động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5447, 28451, '週末は掃除とか洗濯とかをします。', 'しゅうまつは そうじとか せんたくとかを します。', 'Cuối tuần tôi dọn dẹp, giặt giũ, v.v.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5448, 28459, '遊んだ後で、おもちゃを片付けなさい。', 'あそんだ あとで、おもちゃを かたづけなさい。', 'Chơi xong thì dọn đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5449, 28460, '結果がわかったら、知らせてください。', 'けっかが わかったら、しらせて ください。', 'Khi biết kết quả hãy báo cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5450, 28463, '大学の案内書をもらいました。', 'だいがくの あんないしょを もらいました。', 'Tôi nhận được tài liệu hướng dẫn của trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5451, 44933, '太陽が東から昇ります。', 'たいようが ひがしから のぼります。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5452, 28425, '午後二時からミーティングがあります。', 'ごご にじから ミーティングが あります。', 'Từ hai giờ chiều có cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5453, 28430, '駅にコンサートのポスターがはってあります。', 'えきに コンサートの ポスターが はって あります。', 'Ở ga có dán áp phích buổi hòa nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5454, 28471, 'ブロードウェイでミュージカルを見たいです。', 'ブロードウェイで ミュージカルを みたい です。', 'Tôi muốn xem nhạc kịch ở Broadway.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5455, 28478, '日本語のスピーチ大会に申し込みました。', 'にほんごの スピーチ たいかいに もうしこみました。', 'Tôi đã đăng ký cuộc thi hùng biện tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5456, 28490, '大学を卒業してから、大学院に入りたいです。', 'だいがくを そつぎょう してから、だいがくいんに はいりたい です。', 'Tốt nghiệp đại học xong tôi muốn học cao học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5457, 28495, '台風十号が近づいています。', 'たいふう じゅうごうが ちかづいて います。', 'Cơn bão số mười đang đến gần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5458, 28500, 'のぞみ四十二号で東京へ帰ります。', 'のぞみ よんじゅうにごうで とうきょうへ かえります。', 'Tôi về Tokyo bằng tàu Nozomi số 42.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5459, 28503, '来月、大学の入学試験があります。', 'らいげつ、だいがくの にゅうがく しけんが あります。', 'Tháng sau có kỳ thi tuyển sinh đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5460, 28517, 'お客さんが来ましたよ。', 'おきゃくさんが きましたよ。', 'Có khách đến đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5461, 28523, '八時に駅の前に集まってください。', 'はちじに えきの まえに あつまって ください。', 'Tám giờ hãy tập trung trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5462, 28499, '美術館でピカソの絵を見ました。', 'びじゅつかんで ピカソの えを みました。', 'Tôi xem tranh của Picasso ở bảo tàng mỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5463, 28533, 'あしたは晴れるでしょう。', 'あしたは はれるでしょう。', 'Ngày mai có lẽ trời nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5464, 28537, 'ビールを冷蔵庫で冷やしておきます。', 'ビールを れいぞうこで ひやして おきます。', 'Tôi để bia vào tủ lạnh cho mát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5465, 28564, '夕方から雨が降るそうです。', 'ゆうがたから あめが ふる そう です。', 'Nghe nói từ chiều tối trời sẽ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5466, 28569, 'あんなに大きな魚は見たことがありません。', 'あんなに おおきな さかなは みた ことが ありません。', 'Tôi chưa từng thấy con cá nào to như thế kia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5467, 30876, '最後まで諦めないでください。', 'さいごまで あきらめないで ください。', 'Đừng bỏ cuộc cho đến phút cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5468, 37755, '面接の前はとても緊張した。', 'めんせつの まえは とても きんちょう した。', 'Trước buổi phỏng vấn tôi rất hồi hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5469, 37757, '一人暮らしを始めて、孤独を感じることがある。', 'ひとりぐらしを はじめて、こどくを かんじる ことが ある。', 'Từ khi sống một mình, đôi lúc tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5470, 37759, '彼の失礼な言葉に怒りを感じた。', 'かれの しつれいな ことばに いかりを かんじた。', 'Tôi thấy giận trước lời lẽ thất lễ của anh ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5471, 37760, '合格の知らせに驚きを隠せなかった。', 'ごうかくの しらせに おどろきを かくせなかった。', 'Tôi không giấu nổi sự ngạc nhiên khi nhận tin đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5472, 37763, '好きな歌手に会えて感激した。', 'すきな かしゅに あえて かんげき した。', 'Được gặp ca sĩ yêu thích, tôi xúc động vô cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5473, 38901, '猫は水を嫌う。', 'ねこは みずを きらう。', 'Mèo ghét nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5474, 39109, '家族と離れて暮らすのは辛い。', 'かぞくと はなれて くらすのは つらい。', 'Sống xa gia đình thật khổ sở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5475, 39300, '進学か就職か、まだ悩んでいる。', 'しんがくか しゅうしょくか、まだ なやんで いる。', 'Tôi vẫn đang phân vân nên học lên hay đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5476, 39325, 'みんなが先生の死を悲しんだ。', 'みんなが せんせいの しを かなしんだ。', 'Mọi người đều đau buồn trước cái chết của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5477, 39338, '電車に間に合うように必死に走った。', 'でんしゃに まにあう ように ひっしに はしった。', 'Tôi chạy thục mạng cho kịp tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5478, 39348, '彼は若いころ、多くの不幸を経験した。', 'かれは わかい ころ、おおくの ふこうを けいけん した。', 'Hồi trẻ anh ấy đã trải qua nhiều bất hạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5479, 39430, '昨日のパーティーは本当に愉快だった。', 'きのうの パーティーは ほんとうに ゆかい だった。', 'Bữa tiệc hôm qua thật sự vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5480, 39436, '勇気を出して、彼女に話しかけた。', 'ゆうきを だして、かのじょに はなしかけた。', 'Tôi lấy hết can đảm để bắt chuyện với cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5481, 38913, 'なんてゆうか、ちょっと変な人だね。', 'なんて ゆうか、ちょっと へんな ひとだね。', 'Nói sao nhỉ, đúng là người hơi lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5482, 37772, '狭い部屋を広く使うために工夫した。', 'せまい へやを ひろく つかう ために くふう した。', 'Tôi đã nghĩ cách để dùng căn phòng hẹp cho rộng rãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5483, 38002, '授業で環境問題について討論した。', 'じゅぎょうで かんきょう もんだいに ついて とうろん した。', 'Trong giờ học chúng tôi đã thảo luận về vấn đề môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5484, 39424, '次の問いに答えなさい。', 'つぎの といに こたえなさい。', 'Hãy trả lời các câu hỏi sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5485, 39444, '予期しない問題が起きた。', 'よき しない もんだいが おきた。', 'Đã xảy ra một vấn đề không lường trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5486, 39454, '夜道は危ないから、用心して帰ってね。', 'よみちは あぶないから、ようじん して かえってね。', 'Đường đêm nguy hiểm, về cẩn thận nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5487, 37747, 'この店の責任者を呼んでください。', 'この みせの せきにんしゃを よんで ください。', 'Hãy gọi người phụ trách cửa hàng này ra đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5488, 37750, '写真のコンテストに応募した。', 'しゃしんの コンテストに おうぼ した。', 'Tôi đã gửi bài dự thi cuộc thi ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5489, 37751, '第一志望の大学に合格した。', 'だいいち しぼうの だいがくに ごうかく した。', 'Tôi đã đỗ trường đại học nguyện vọng một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5490, 38902, '駅の近くに新しい病院を建設している。', 'えきの ちかくに あたらしい びょういんを けんせつ して いる。', 'Người ta đang xây bệnh viện mới gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5491, 38911, '警察が事故の現場を調べている。', 'けいさつが じこの げんばを しらべて いる。', 'Cảnh sát đang điều tra hiện trường vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5492, 37768, '出発前に車を点検した。', 'しゅっぱつまえに くるまを てんけん した。', 'Trước khi khởi hành tôi đã kiểm tra xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5493, 37989, 'この工場では一日に千台の車を生産している。', 'この こうじょうでは いちにちに せんだいの くるまを せいさん して いる。', 'Nhà máy này sản xuất một nghìn chiếc ô tô mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5494, 37991, 'とれた魚を工場で加工する。', 'とれた さかなを こうじょうで かこう する。', 'Cá đánh bắt được đem về nhà máy chế biến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5495, 28292, 'パンが売れます。', 'パンがうれます。', 'Bán', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5496, 37993, '米の需給のバランスが崩れている。', 'こめの じゅきゅうの バランスが くずれて いる。', 'Cung cầu gạo đang mất cân bằng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5497, 37994, '好況で多くの会社がボーナスを増やした。', 'こうきょうで おおくの かいしゃが ボーナスを ふやした。', 'Kinh tế thịnh vượng nên nhiều công ty tăng thưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5498, 39275, '肝臓の働きについて調べた。', 'かんぞうの はたらきに ついて しらべた。', 'Tôi đã tìm hiểu về chức năng của gan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5499, 39301, '祖父母は農家で、米を作っている。', 'そふぼは のうかで、こめを つくって いる。', 'Ông bà tôi là nhà nông, trồng lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5500, 39305, '事業に失敗して、破産してしまった。', 'じぎょうに しっぱい して、はさん して しまった。', 'Kinh doanh thất bại nên đã phá sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5501, 39344, 'この店はいい品をそろえている。', 'この みせは いい しなを そろえて いる。', 'Cửa hàng này bày bán nhiều hàng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5502, 39414, '祖母は漬物作りの名人だ。', 'そぼは つけものづくりの めいじんだ。', 'Bà tôi là bậc thầy muối dưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5503, 38797, '彼は学はないが、知恵がある。', 'かれは がくは ないが、ちえが ある。', 'Ông ấy không có học vấn nhưng rất khôn ngoan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5504, 38798, '留学して、たくさんのことを学んだ。', 'りゅうがく して、たくさんの ことを まなんだ。', 'Đi du học, tôi đã học được rất nhiều điều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5505, 38890, '電卓で合計を計算した。', 'でんたくで ごうけいを けいさん した。', 'Tôi dùng máy tính bỏ túi để tính tổng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5506, 38924, '語学の勉強には時間がかかる。', 'ごがくの べんきょうには じかんが かかる。', 'Học ngoại ngữ thì cần thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5507, 46150, '冬は暖房器具の需要が高まる。', 'ふゆは だんぼうきぐの じゅようが たかまる。', 'Mùa đông nhu cầu thiết bị sưởi tăng cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5508, 46152, '夏は電気の消費が増える。', 'なつは でんきの しょうひが ふえる。', 'Mùa hè lượng điện tiêu thụ tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5509, 46159, '会社は三年ぶりに黒字になった。', 'かいしゃは さんねんぶりに くろじに なった。', 'Sau ba năm, công ty đã có lãi trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5510, 46161, '好況で多くの会社がボーナスを増やした。', 'こうきょうで おおくの かいしゃが ボーナスを ふやした。', 'Kinh tế thịnh vượng nên nhiều công ty tăng thưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5511, 46175, '電気代の請求が来た。', 'でんきだいの せいきゅうが きた。', 'Hóa đơn tiền điện đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5512, 44069, 'この工場では一日に千台の車を生産している。', 'この こうじょうでは いちにちに せんだいの くるまを せいさん して いる。', 'Nhà máy này sản xuất một nghìn chiếc ô tô mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5513, 31174, '今月は出費が多くて赤字だ。', 'こんげつは しゅっぴが おおくて あかじだ。', 'Tháng này chi tiêu nhiều nên bị thâm hụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5514, 31175, '会社は三年ぶりに黒字になった。', 'かいしゃは さんねんぶりに くろじに なった。', 'Sau ba năm, công ty đã có lãi trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5515, 44289, 'その映画を見て、とても感動した。', 'その えいがを みて、とても かんどう した。', 'Xem bộ phim đó tôi rất cảm động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5516, 44318, '正直に話してくれてありがとう。', 'しょうじきに はなして くれて ありがとう。', 'Cảm ơn bạn đã nói thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5517, 44372, '痛くても、もう少し我慢してください。', 'いたくても、もう すこし がまん して ください。', 'Dù đau cũng hãy chịu đựng thêm chút nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
