INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5523, 45038, '正直に話してくれてありがとう。', 'しょうじきに はなして くれて ありがとう。', 'Cảm ơn bạn đã nói thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5524, 45060, '彼は陽気な性格で、みんなに好かれている。', 'かれは ようきな せいかくで、みんなに すかれて いる。', 'Anh ấy tính tình vui vẻ nên được mọi người quý mến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5525, 45090, '面接の前はとても緊張した。', 'めんせつの まえは とても きんちょう した。', 'Trước buổi phỏng vấn tôi rất hồi hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5526, 45109, '子供のころ、いろいろな職業にあこがれた。', 'こどもの ころ、いろいろな しょくぎょうに あこがれた。', 'Hồi nhỏ tôi mơ ước đủ thứ nghề nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5527, 45114, 'このパンは駅の売店でも販売しています。', 'この パンは えきの ばいてんでも はんばい して います。', 'Loại bánh mì này cũng được bán ở quầy trong ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5528, 45124, 'お会計はレジでお願いします。', 'おかいけいは レジで おねがい します。', 'Xin vui lòng thanh toán tại quầy thu ngân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5529, 45211, '会社が倒産して、父は失業した。', 'かいしゃが とうさん して、ちちは しつぎょう した。', 'Công ty phá sản nên bố tôi bị thất nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5530, 45269, '新しい星が発見された。', 'あたらしい ほしが はっけん された。', 'Một ngôi sao mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5531, 45293, '支払いはカードでもできますか。', 'しはらいは カードでも できますか。', 'Có thể thanh toán bằng thẻ không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5532, 45420, '彼は陽気な性格で、みんなに好かれている。', 'かれは ようきな せいかくで、みんなに すかれて いる。', 'Anh ấy tính tình vui vẻ nên được mọi người quý mến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
