INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5537, 45569, '景気がよくなって、給料が上がった。', 'けいきが よく なって、きゅうりょうが あがった。', 'Kinh tế khởi sắc nên lương tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5538, 45590, '学問に終わりはない。', 'がくもんに おわりは ない。', 'Việc học không có điểm dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5539, 45629, '新しい星が発見された。', 'あたらしい ほしが はっけん された。', 'Một ngôi sao mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5540, 45780, '彼は陽気な性格で、みんなに好かれている。', 'かれは ようきな せいかくで、みんなに すかれて いる。', 'Anh ấy tính tình vui vẻ nên được mọi người quý mến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5541, 45789, 'わがままばかり言っていると、友達がいなくなるよ。', 'わがまま ばかり いって いると、ともだちが いなく なるよ。', 'Cứ ích kỷ đòi hỏi mãi thì sẽ mất hết bạn đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5542, 45805, '私は父を一番尊敬しています。', 'わたしは ちちを いちばん そんけい して います。', 'Người tôi kính trọng nhất là bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5543, 45810, '面接の前はとても緊張した。', 'めんせつの まえは とても きんちょう した。', 'Trước buổi phỏng vấn tôi rất hồi hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5544, 45813, '給料が安いことに不満がある。', 'きゅうりょうが やすい ことに ふまんが ある。', 'Tôi bất mãn vì lương thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5545, 46510, '冬は暖房器具の需要が高まる。', 'ふゆは だんぼうきぐの じゅようが たかまる。', 'Mùa đông nhu cầu thiết bị sưởi tăng cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5546, 45829, '子供のころ、いろいろな職業にあこがれた。', 'こどもの ころ、いろいろな しょくぎょうに あこがれた。', 'Hồi nhỏ tôi mơ ước đủ thứ nghề nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5547, 45837, '安い物を買って、かえって損をした。', 'やすい ものを かって、かえって そんを した。', 'Mua đồ rẻ hóa ra lại thiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5548, 45929, '景気がよくなって、給料が上がった。', 'けいきが よく なって、きゅうりょうが あがった。', 'Kinh tế khởi sắc nên lương tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5549, 42887, '週末に駅前でフリーマーケットがある。', 'しゅうまつに えきまえで フリーマーケットが ある。', 'Cuối tuần có chợ đồ cũ trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5550, 31455, '彼は病気を克服して、仕事に戻った。', 'かれは びょうきを こくふく して、しごとに もどった。', 'Anh ấy đã vượt qua bệnh tật và quay lại làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5551, 31457, '毎日練習して、日本語の力が向上した。', 'まいにち れんしゅう して、にほんごの ちからが こうじょう した。', 'Luyện tập mỗi ngày nên tiếng Nhật đã tiến bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5552, 46013, '支払いはカードでもできますか。', 'しはらいは カードでも できますか。', 'Có thể thanh toán bằng thẻ không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5553, 44068, 'この店の果物はほとんどが輸入品だ。', 'この みせの くだものは ほとんどが ゆにゅうひんだ。', 'Hoa quả ở cửa hàng này hầu hết là hàng nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5554, 44427, '日本は車をたくさん輸出している。', 'にほんは くるまを たくさん ゆしゅつ して いる。', 'Nhật Bản xuất khẩu rất nhiều ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5555, 44428, 'この店の果物はほとんどが輸入品だ。', 'この みせの くだものは ほとんどが ゆにゅうひんだ。', 'Hoa quả ở cửa hàng này hầu hết là hàng nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5556, 44787, '日本は車をたくさん輸出している。', 'にほんは くるまを たくさん ゆしゅつ して いる。', 'Nhật Bản xuất khẩu rất nhiều ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5557, 46131, '予算が足りなくて、計画を変えた。', 'よさんが たりなくて、けいかくを かえた。', 'Ngân sách không đủ nên tôi phải đổi kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5558, 44789, 'この工場では一日に千台の車を生産している。', 'この こうじょうでは いちにちに せんだいの くるまを せいさん して いる。', 'Nhà máy này sản xuất một nghìn chiếc ô tô mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5559, 37762, '私は父を一番尊敬しています。', 'わたしは ちちを いちばん そんけい して います。', 'Người tôi kính trọng nhất là bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5560, 38032, '履歴書に学歴と職歴を書いてください。', 'りれきしょに がくれきと しょくれきを かいて ください。', 'Hãy ghi quá trình học tập và làm việc vào sơ yếu lý lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5561, 46133, '今月は支出が収入より多かった。', 'こんげつは ししゅつが しゅうにゅうより おおかった。', 'Tháng này chi nhiều hơn thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5562, 45268, '大学で日本の歴史を研究している。', 'だいがくで にほんの れきしを けんきゅう して いる。', 'Tôi nghiên cứu lịch sử Nhật Bản ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5563, 45628, '大学で日本の歴史を研究している。', 'だいがくで にほんの れきしを けんきゅう して いる。', 'Tôi nghiên cứu lịch sử Nhật Bản ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5564, 28577, '働きすぎは体によくないですよ。', 'はたらきすぎは からだに よくない ですよ。', 'Làm việc quá sức không tốt cho cơ thể đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5565, 46349, '子供は想像力が豊かだ。', 'こどもは そうぞうりょくが ゆたかだ。', 'Trẻ con có trí tưởng tượng phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5566, 46378, '作業が終わったら、道具を片付けてください。', 'さぎょうが おわったら、どうぐを かたづけて ください。', 'Làm xong việc thì hãy cất dọn dụng cụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5567, 46387, '先生の指導のおかげで、論文が書けた。', 'せんせいの しどうの おかげで、ろんぶんが かけた。', 'Nhờ sự hướng dẫn của thầy mà tôi viết được luận văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11141, 43764, '卵を三つ使います。', 'たまごを みっつ つかいます。', 'Dùng ba quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5568, 46414, '会社全体で省エネに取り組んでいる。', 'かいしゃ ぜんたいで しょうエネに とりくんで いる。', 'Cả công ty đang nỗ lực tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5569, 46461, 'この地方は農業が盛んだ。', 'この ちほうは のうぎょうが さかんだ。', 'Vùng này nông nghiệp phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5570, 46491, '予算が足りなくて、計画を変えた。', 'よさんが たりなくて、けいかくを かえた。', 'Ngân sách không đủ nên tôi phải đổi kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5571, 46493, '今月は支出が収入より多かった。', 'こんげつは ししゅつが しゅうにゅうより おおかった。', 'Tháng này chi nhiều hơn thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5572, 46499, '将来のために少しずつ投資をしている。', 'しょうらいの ために すこしずつ とうしを して いる。', 'Tôi đầu tư từng chút một cho tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5573, 46512, '夏は電気の消費が増える。', 'なつは でんきの しょうひが ふえる。', 'Mùa hè lượng điện tiêu thụ tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5574, 46519, '会社は三年ぶりに黒字になった。', 'かいしゃは さんねんぶりに くろじに なった。', 'Sau ba năm, công ty đã có lãi trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5575, 46522, '不況で仕事を探すのが難しい。', 'ふきょうで しごとを さがすのが むずかしい。', 'Kinh tế suy thoái nên tìm việc rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5576, 46542, '交通費は会社から支給されます。', 'こうつうひは かいしゃから しきゅう されます。', 'Tiền đi lại do công ty chi trả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5577, 46618, '出発前に車を点検した。', 'しゅっぱつまえに くるまを てんけん した。', 'Trước khi khởi hành tôi đã kiểm tra xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5578, 46723, '好きな歌手に会えて感激した。', 'すきな かしゅに あえて かんげき した。', 'Được gặp ca sĩ yêu thích, tôi xúc động vô cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5579, 46747, '先生の指導のおかげで、論文が書けた。', 'せんせいの しどうの おかげで、ろんぶんが かけた。', 'Nhờ sự hướng dẫn của thầy mà tôi viết được luận văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
