INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5581, 46821, 'この地方は農業が盛んだ。', 'この ちほうは のうぎょうが さかんだ。', 'Vùng này nông nghiệp phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5582, 46851, '予算が足りなくて、計画を変えた。', 'よさんが たりなくて、けいかくを かえた。', 'Ngân sách không đủ nên tôi phải đổi kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5583, 46853, '今月は支出が収入より多かった。', 'こんげつは ししゅつが しゅうにゅうより おおかった。', 'Tháng này chi nhiều hơn thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5584, 46859, '将来のために少しずつ投資をしている。', 'しょうらいの ために すこしずつ とうしを して いる。', 'Tôi đầu tư từng chút một cho tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5585, 46871, '地震で水の供給が止まった。', 'じしんで みずの きょうきゅうが とまった。', 'Động đất làm ngừng cung cấp nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5586, 46878, '今月は出費が多くて赤字だ。', 'こんげつは しゅっぴが おおくて あかじだ。', 'Tháng này chi tiêu nhiều nên bị thâm hụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5587, 46881, '好況で多くの会社がボーナスを増やした。', 'こうきょうで おおくの かいしゃが ボーナスを ふやした。', 'Kinh tế thịnh vượng nên nhiều công ty tăng thưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5588, 46895, '電気代の請求が来た。', 'でんきだいの せいきゅうが きた。', 'Hóa đơn tiền điện đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5589, 46936, '労働者は給料を上げるよう要求した。', 'ろうどうしゃは きゅうりょうを あげる よう ようきゅう した。', 'Công nhân đã yêu cầu tăng lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5590, 47083, '好きな歌手に会えて感激した。', 'すきな かしゅに あえて かんげき した。', 'Được gặp ca sĩ yêu thích, tôi xúc động vô cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5591, 47098, '作業が終わったら、道具を片付けてください。', 'さぎょうが おわったら、どうぐを かたづけて ください。', 'Làm xong việc thì hãy cất dọn dụng cụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5592, 47134, '会社全体で省エネに取り組んでいる。', 'かいしゃ ぜんたいで しょうエネに とりくんで いる。', 'Cả công ty đang nỗ lực tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5593, 47181, 'この地方は農業が盛んだ。', 'この ちほうは のうぎょうが さかんだ。', 'Vùng này nông nghiệp phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5594, 47183, '秋は米の収穫の季節だ。', 'あきは こめの しゅうかくの きせつだ。', 'Mùa thu là mùa thu hoạch lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5595, 47291, '米の需給のバランスが崩れている。', 'こめの じゅきゅうの バランスが くずれて いる。', 'Cung cầu gạo đang mất cân bằng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5596, 47396, '一人暮らしを始めて、孤独を感じることがある。', 'ひとりぐらしを はじめて、こどくを かんじる ことが ある。', 'Từ khi sống một mình, đôi lúc tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5597, 47416, 'みんなが彼の不運に同情した。', 'みんなが かれの ふうんに どうじょう した。', 'Mọi người đều thương cảm cho sự xui xẻo của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5598, 47463, 'レポートに新聞の記事を引用した。', 'レポートに しんぶんの きじを いんよう した。', 'Tôi đã trích dẫn một bài báo vào bản báo cáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
