INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5607, 45043, '確か、会議は三時からだと思います。', 'たしか、かいぎは さんじから だと おもいます。', 'Tôi nghĩ hình như cuộc họp bắt đầu từ ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5608, 28243, '隣の部屋から子どもの声が聞こえます。', 'となりの へやから こどもの こえが きこえます。', 'Nghe thấy tiếng trẻ con từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5609, 28277, 'ドラえもんはポケットからいろいろな道具を出します。', 'ドラえもんは ポケットから いろいろな どうぐを だします。', 'Doraemon lấy đủ loại bảo bối ra từ chiếc túi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5610, 28374, '買った物を袋に入れました。', 'かった ものを ふくろに いれました。', 'Tôi cho đồ đã mua vào túi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5611, 28480, '五月の連休に旅行します。', 'ごがつの れんきゅうに りょこう します。', 'Dịp nghỉ dài tháng năm tôi đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5612, 28547, '熱いお湯で手にやけどをしました。', 'あつい おゆで てに やけどを しました。', 'Tôi bị bỏng tay vì nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5613, 28552, '太陽が東から昇ります。', 'たいようが ひがしから のぼります。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5614, 28637, '昨夜、地震がありました。', 'ゆうべ、じしんが ありました。', 'Tối qua có động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5615, 28650, '新しい洗濯機を買いました。', 'あたらしい せんたくきを かいました。', 'Tôi đã mua máy giặt mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5616, 28725, '夏祭りで盆踊りを踊りました。', 'なつまつりで ぼんおどりを おどりました。', 'Ở lễ hội mùa hè tôi đã múa điệu Bon odori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5617, 28732, '日本語がわからなくて困りました。', 'にほんごが わからなくて こまりました。', 'Không hiểu tiếng Nhật nên tôi gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5618, 28807, '毎週柔道を習っています。', 'まいしゅう じゅうどうを ならって います。', 'Hằng tuần tôi học judo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5619, 30969, '外国人に偏見を持ってはいけない。', 'がいこくじんに へんけんを もっては いけない。', 'Không được có định kiến với người nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5620, 39224, '弟は今年中学に入った。', 'おとうとは ことし ちゅうがくに はいった。', 'Năm nay em trai tôi vào cấp hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5621, 39276, 'この文の動詞を正しい形に変えなさい。', 'この ぶんの どうしを ただしい かたちに かえなさい。', 'Hãy chia động từ trong câu này cho đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5622, 39339, 'お正月に筆で字を書いた。', 'おしょうがつに ふでで じを かいた。', 'Dịp Tết tôi viết chữ bằng bút lông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5623, 39340, '結果を表にまとめてください。', 'けっかを ひょうに まとめて ください。', 'Hãy tổng hợp kết quả thành bảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5624, 38891, '医者からたばこをやめるよう警告された。', 'いしゃから たばこを やめる よう けいこく された。', 'Tôi bị bác sĩ cảnh cáo phải bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5625, 37781, '被災地にお金を寄付した。', 'ひさいちに おかねを きふ した。', 'Tôi đã quyên góp tiền cho vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5626, 37783, '山で迷った人が無事に救助された。', 'やまで まよった ひとが ぶじに きゅうじょ された。', 'Người bị lạc trên núi đã được cứu an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5627, 38949, '新しい法律が国会で決まった。', 'あたらしい ほうりつが こっかいで きまった。', 'Luật mới đã được quốc hội thông qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5628, 38952, '選挙は国民の大切な権利だ。', 'せんきょは こくみんの たいせつな けんりだ。', 'Bầu cử là quyền quan trọng của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5629, 39120, '世の中にはいろいろな人がいる。', 'よのなかには いろいろな ひとが いる。', 'Trên đời có đủ loại người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5630, 39121, '世間の目を気にしすぎないほうがいい。', 'せけんの めを きに しすぎない ほうが いい。', 'Không nên quá bận tâm đến ánh mắt thiên hạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5631, 39166, '彼は会社を訴えた。', 'かれは かいしゃを うったえた。', 'Anh ấy đã kiện công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5632, 39196, '日本の大使が大統領と会談した。', 'にほんの たいしが だいとうりょうと かいだん した。', 'Đại sứ Nhật Bản đã hội đàm với tổng thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5633, 39198, '祖父は大戦の話をよくしてくれた。', 'そふは たいせんの はなしを よく して くれた。', 'Ông tôi hay kể chuyện về thế chiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5634, 39217, '女性の社会的地位が高くなった。', 'じょせいの しゃかいてき ちいが たかく なった。', 'Địa vị xã hội của phụ nữ đã được nâng cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5635, 39261, '京都は千年以上日本の都だった。', 'きょうとは せんねん いじょう にほんの みやこ だった。', 'Kyoto từng là kinh đô Nhật Bản hơn một nghìn năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5636, 39268, '日曜日に選挙の投票に行った。', 'にちようびに せんきょの とうひょうに いった。', 'Chủ nhật tôi đi bỏ phiếu bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5637, 39317, 'ルールを破った人は罰せられる。', 'ルールを やぶった ひとは ばっせられる。', 'Ai vi phạm quy định sẽ bị phạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5638, 39321, '中学生のころ、親に反抗ばかりしていた。', 'ちゅうがくせいの ころ、おやに はんこう ばかり して いた。', 'Hồi cấp hai tôi toàn chống đối bố mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5639, 29286, '輸出が増えます。', 'ゆしゅつがふえます。', 'Tăng, tăng lên [xuất khẩu ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5640, 39361, '彼の武器は明るい性格だ。', 'かれの ぶきは あかるい せいかくだ。', 'Vũ khí của anh ấy là tính cách vui vẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5641, 39383, 'スピードを出しすぎて、警察に捕まった。', 'スピードを だしすぎて、けいさつに つかまった。', 'Chạy quá tốc độ nên bị cảnh sát tóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5642, 38612, '予算を一万円オーバーしてしまった。', 'よさんを いちまんえん オーバー して しまった。', 'Tôi đã tiêu vượt ngân sách mười nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5643, 38967, '犬を鎖でつないでおいた。', 'いぬを くさりで つないで おいた。', 'Tôi đã xích con chó lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5644, 39145, '残った布の切れでかばんを作った。', 'のこった ぬのの きれで かばんを つくった。', 'Tôi làm túi từ những mảnh vải thừa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5645, 39173, '暑いので、シャツの袖をまくった。', 'あついので、シャツの そでを まくった。', 'Nóng quá nên tôi xắn tay áo sơ mi lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5646, 39287, '箱を縄でしっかり縛った。', 'はこを なわで しっかり しばった。', 'Tôi buộc chặt chiếc hộp bằng dây thừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5647, 39356, 'この布でカーテンを作るつもりだ。', 'この ぬので カーテンを つくる つもりだ。', 'Tôi định may rèm bằng tấm vải này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5648, 39365, '面接にはきちんとした服装で行きましょう。', 'めんせつには きちんと した ふくそうで いきましょう。', 'Đi phỏng vấn thì nên ăn mặc chỉnh tề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5649, 39389, '子供は国の宝だ。', 'こどもは くにの たからだ。', 'Trẻ em là báu vật của đất nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5650, 39390, 'このネックレスの宝石は本物だ。', 'この ネックレスの ほうせきは ほんものだ。', 'Đá quý trên chiếc vòng cổ này là hàng thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5651, 39417, '部屋の明かりをつけてください。', 'へやの あかりを つけて ください。', 'Hãy bật đèn trong phòng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5652, 42872, '雪で電車のダイヤが乱れている。', 'ゆきで でんしゃの ダイヤが みだれて いる。', 'Do tuyết mà lịch chạy tàu bị xáo trộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5653, 42883, 'ポスターをピンで壁にとめた。', 'ポスターを ピンで かべに とめた。', 'Tôi ghim tấm áp phích lên tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5654, 39221, '京都は茶の産地として有名だ。', 'きょうとは ちゃの さんちと して ゆうめいだ。', 'Kyoto nổi tiếng là vùng sản xuất trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5655, 39226, '昼食は会社の近くの店で食べる。', 'ちゅうしょくは かいしゃの ちかくの みせで たべる。', 'Tôi ăn trưa ở quán gần công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5656, 39359, '夏は食べ物がすぐ腐る。', 'なつは たべものが すぐ くさる。', 'Mùa hè đồ ăn mau hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5657, 39431, 'フライパンに油をひいて、肉を焼いた。', 'フライパンに あぶらを ひいて、にくを やいた。', 'Tôi tráng dầu lên chảo rồi rán thịt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5658, 38888, 'ソウル経由でニューヨークへ行った。', 'ソウル けいゆで ニューヨークへ いった。', 'Tôi bay đến New York quá cảnh Seoul.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5659, 37765, '引っ越しの荷物を運送会社に頼んだ。', 'ひっこしの にもつを うんそう がいしゃに たのんだ。', 'Tôi thuê công ty vận chuyển đồ đạc khi chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5660, 37767, 'この電車は次の駅を通過します。', 'この でんしゃは つぎの えきを つうか します。', 'Chuyến tàu này sẽ chạy qua ga tiếp theo không dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5661, 38945, '高速道路を使えば、一時間で着く。', 'こうそくどうろを つかえば、いちじかんで つく。', 'Đi đường cao tốc thì một tiếng là tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5662, 38963, '連休は空港がとても混雑する。', 'れんきゅうは くうこうが とても こんざつ する。', 'Dịp nghỉ dài, sân bay rất đông đúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5663, 39113, '人込みは苦手だ。', 'ひとごみは にがてだ。', 'Tôi không thích chỗ đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5664, 39220, '地方によって言葉が少しずつ違う。', 'ちほうに よって ことばが すこしずつ ちがう。', 'Mỗi vùng miền ngôn ngữ lại khác nhau đôi chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5665, 39264, '旅行のお土産にお菓子を買った。', 'りょこうの おみやげに おかしを かった。', 'Tôi mua bánh kẹo làm quà du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5666, 39315, 'バスはもうすぐ発車します。', 'バスは もうすぐ はっしゃ します。', 'Xe buýt sắp khởi hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5667, 39384, '自転車は歩道を走らないでください。', 'じてんしゃは ほどうを はしらないで ください。', 'Xe đạp xin đừng chạy trên vỉa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5668, 42871, '市民センターで日本語教室が開かれている。', 'しみん センターで にほんご きょうしつが ひらかれて いる。', 'Ở trung tâm cộng đồng có mở lớp tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5669, 42880, '子供のころ、パイロットになりたかった。', 'こどもの ころ、パイロットに なりたかった。', 'Hồi nhỏ tôi muốn làm phi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5670, 42886, '公園の池でボートに乗った。', 'こうえんの いけで ボートに のった。', 'Chúng tôi chèo thuyền trên hồ trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5671, 31526, 'ごみは分別して出してください。', 'ごみは ぶんべつ して だして ください。', 'Hãy phân loại rác trước khi đem đổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5672, 31529, '日本は国土の約七割が森林だ。', 'にほんは こくどの やく ななわりが しんりんだ。', 'Khoảng 70% diện tích Nhật Bản là rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5673, 31531, 'この鳥は絶滅しそうになっている。', 'この とりは ぜつめつ しそうに なって いる。', 'Loài chim này đang có nguy cơ tuyệt chủng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5674, 31533, '地域の自然を保全する活動に参加している。', 'ちいきの しぜんを ほぜん する かつどうに さんか して いる。', 'Tôi tham gia hoạt động bảo tồn thiên nhiên địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5675, 31534, 'この薬の効果は六時間持続する。', 'この くすりの こうかは ろくじかん じぞく する。', 'Tác dụng của thuốc này kéo dài sáu tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5676, 44099, '屋根の上に猫がいる。', 'やねの うえに ねこが いる。', 'Có con mèo trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5677, 46189, '国家の将来を考える。', 'こっかの しょうらいを かんがえる。', 'Suy nghĩ về tương lai của quốc gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5678, 37746, 'パスポートを申請した。', 'パスポートを しんせい した。', 'Tôi đã nộp đơn xin hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5679, 44681, '休みの日は自由に過ごしたい。', 'やすみの ひは じゆうに すごしたい。', 'Ngày nghỉ tôi muốn được tự do thoải mái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5680, 46202, '泥棒はすぐに逮捕された。', 'どろぼうは すぐに たいほ された。', 'Tên trộm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5681, 45175, '政府は新しい経済政策を発表した。', 'せいふは あたらしい けいざい せいさくを はっぴょう した。', 'Chính phủ đã công bố chính sách kinh tế mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5682, 45186, 'この町は犯罪が少ない。', 'この まちは はんざいが すくない。', 'Thị trấn này ít tội phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5683, 45203, '東京で国際会議が開かれた。', 'とうきょうで こくさい かいぎが ひらかれた。', 'Một hội nghị quốc tế đã được tổ chức ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5684, 45206, '姉は福祉の仕事に就いた。', 'あねは ふくしの しごとに ついた。', 'Chị tôi làm trong ngành phúc lợi xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5685, 45252, '来年、日本に留学する予定です。', 'らいねん、にほんに りゅうがく する よてい です。', 'Sang năm tôi dự định đi du học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5686, 45275, '名前を書いてから答案を出してください。', 'なまえを かいてから とうあんを だして ください。', 'Ghi tên rồi hãy nộp bài thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5687, 45320, 'ごみは分別して出してください。', 'ごみは ぶんべつ して だして ください。', 'Hãy phân loại rác trước khi đem đổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5688, 45326, 'パスポートを申請した。', 'パスポートを しんせい した。', 'Tôi đã nộp đơn xin hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5689, 45353, '事故で乗客が数人けがをした。', 'じこで じょうきゃくが すうにん けがを した。', 'Vài hành khách bị thương trong vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5690, 45364, 'このホテルの宿泊料金は一泊一万円です。', 'この ホテルの しゅくはく りょうきんは いっぱく いちまんえん です。', 'Giá phòng khách sạn này là mười nghìn yên một đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5691, 45371, '地方によって言葉が少しずつ違う。', 'ちほうに よって ことばが すこしずつ ちがう。', 'Mỗi vùng miền ngôn ngữ lại khác nhau đôi chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5692, 45529, '選挙は国民の大切な権利だ。', 'せんきょは こくみんの たいせつな けんりだ。', 'Bầu cử là quyền quan trọng của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5693, 45538, '会社に新しい休暇の制度ができた。', 'かいしゃに あたらしい きゅうかの せいどが できた。', 'Công ty đã có chế độ nghỉ phép mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5694, 45546, 'この町は犯罪が少ない。', 'この まちは はんざいが すくない。', 'Thị trấn này ít tội phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5695, 45563, '東京で国際会議が開かれた。', 'とうきょうで こくさい かいぎが ひらかれた。', 'Một hội nghị quốc tế đã được tổ chức ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5696, 45566, '姉は福祉の仕事に就いた。', 'あねは ふくしの しごとに ついた。', 'Chị tôi làm trong ngành phúc lợi xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5697, 45612, '来年、日本に留学する予定です。', 'らいねん、にほんに りゅうがく する よてい です。', 'Sang năm tôi dự định đi du học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5698, 45635, '名前を書いてから答案を出してください。', 'なまえを かいてから とうあんを だして ください。', 'Ghi tên rồi hãy nộp bài thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5699, 45668, '被災地に衣服や毛布を送った。', 'ひさいちに いふくや もうふを おくった。', 'Chúng tôi gửi quần áo và chăn cho vùng bị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5700, 45680, 'ごみは分別して出してください。', 'ごみは ぶんべつ して だして ください。', 'Hãy phân loại rác trước khi đem đổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5701, 45724, 'このホテルの宿泊料金は一泊一万円です。', 'この ホテルの しゅくはく りょうきんは いっぱく いちまんえん です。', 'Giá phòng khách sạn này là mười nghìn yên một đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5702, 45731, '地方によって言葉が少しずつ違う。', 'ちほうに よって ことばが すこしずつ ちがう。', 'Mỗi vùng miền ngôn ngữ lại khác nhau đôi chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5703, 31098, '地域の自然を保全する活動に参加している。', 'ちいきの しぜんを ほぜん する かつどうに さんか して いる。', 'Tôi tham gia hoạt động bảo tồn thiên nhiên địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5704, 45889, '選挙は国民の大切な権利だ。', 'せんきょは こくみんの たいせつな けんりだ。', 'Bầu cử là quyền quan trọng của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5705, 45895, '政府は新しい経済政策を発表した。', 'せいふは あたらしい けいざい せいさくを はっぴょう した。', 'Chính phủ đã công bố chính sách kinh tế mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5706, 45906, 'この町は犯罪が少ない。', 'この まちは はんざいが すくない。', 'Thị trấn này ít tội phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5707, 45925, '男女の差別をなくすべきだ。', 'だんじょの さべつを なくす べきだ。', 'Cần xóa bỏ phân biệt nam nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5708, 46028, '被災地に衣服や毛布を送った。', 'ひさいちに いふくや もうふを おくった。', 'Chúng tôi gửi quần áo và chăn cho vùng bị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5709, 46046, 'パスポートを申請した。', 'パスポートを しんせい した。', 'Tôi đã nộp đơn xin hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5710, 46073, '事故で乗客が数人けがをした。', 'じこで じょうきゃくが すうにん けがを した。', 'Vài hành khách bị thương trong vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5711, 46089, '今年の夏は国内を旅行するつもりだ。', 'ことしの なつは こくないを りょこう する つもりだ。', 'Hè này tôi định du lịch trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5712, 46091, '地方によって言葉が少しずつ違う。', 'ちほうに よって ことばが すこしずつ ちがう。', 'Mỗi vùng miền ngôn ngữ lại khác nhau đôi chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5713, 31524, '夏は節電のため、エアコンの温度を高めにしている。', 'なつは せつでんの ため、エアコンの おんどを たかめに して いる。', 'Mùa hè để tiết kiệm điện, tôi để nhiệt độ điều hòa cao hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5714, 45265, 'この小説はいろいろな言語に翻訳されている。', 'この しょうせつは いろいろな げんごに ほんやく されて いる。', 'Cuốn tiểu thuyết này đã được dịch ra nhiều thứ tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5715, 45985, 'この小説はいろいろな言語に翻訳されている。', 'この しょうせつは いろいろな げんごに ほんやく されて いる。', 'Cuốn tiểu thuyết này đã được dịch ra nhiều thứ tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5716, 46229, '団体で行くと、入場料が安くなる。', 'だんたいで いくと、にゅうじょうりょうが やすく なる。', 'Đi theo đoàn thì vé vào cửa rẻ hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5717, 46233, '住民が集まって、町の掃除をした。', 'じゅうみんが あつまって、まちの そうじを した。', 'Cư dân tập trung lại dọn dẹp khu phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5718, 46339, 'この店はパンがおいしいと評判だ。', 'この みせは パンが おいしいと ひょうばんだ。', 'Tiệm này nổi tiếng là bánh mì ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5719, 46430, '海にはたくさんの生物がすんでいる。', 'うみには たくさんの せいぶつが すんで いる。', 'Biển là nơi sinh sống của rất nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5720, 46432, 'けがをした鳥を保護した。', 'けがを した とりを ほご した。', 'Tôi đã đem con chim bị thương về chăm sóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
