INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5723, 46470, '医者からたばこをやめるよう警告された。', 'いしゃから たばこを やめる よう けいこく された。', 'Tôi bị bác sĩ cảnh cáo phải bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5724, 46472, '水をやらなかったので、花が枯れてしまった。', 'みずを やらなかったので、はなが かれて しまった。', 'Không tưới nước nên hoa đã héo mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
