INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5746, 47353, '外国人に偏見を持ってはいけない。', 'がいこくじんに へんけんを もっては いけない。', 'Không được có định kiến với người nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5747, 47690, '新しい法律が国会で決まった。', 'あたらしい ほうりつが こっかいで きまった。', 'Luật mới đã được quốc hội thông qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
