INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5751, 48069, '母は祖母の介護をしている。', 'ははは そぼの かいごを して いる。', 'Mẹ tôi đang chăm sóc bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5752, 48073, '外国人に偏見を持ってはいけない。', 'がいこくじんに へんけんを もっては いけない。', 'Không được có định kiến với người nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5753, 46138, 'あの会社は株式を上場した。', 'あの かいしゃは かぶしきを じょうじょう した。', 'Công ty đó đã niêm yết cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5754, 28840, 'ここにある本は自由に読んでもいいです。', 'ここに ある ほんは じゆうに よんでも いい です。', 'Sách ở đây cứ tự do đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5755, 28854, '週末は掃除とか洗濯とかをします。', 'しゅうまつは そうじとか せんたくとかを します。', 'Cuối tuần tôi dọn dẹp, giặt giũ, v.v.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5756, 28931, '源氏物語は千年前に書かれた小説です。', 'げんじ ものがたりは せんねんまえに かかれた しょうせつ です。', 'Truyện Genji là tiểu thuyết được viết từ một nghìn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5757, 28956, '駅前で友達と待ち合わせします。', 'えきまえで ともだちと まちあわせ します。', 'Tôi hẹn gặp bạn ở trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5758, 28963, '日本の習慣はまだよくわかりません。', 'にほんの しゅうかんは まだ よく わかりません。', 'Tôi vẫn chưa hiểu rõ phong tục Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5759, 29069, '困ったときは先生に相談します。', 'こまった ときは せんせいに そうだん します。', 'Khi gặp khó khăn tôi hỏi ý kiến thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5760, 29125, 'メールの返事を待っています。', 'メールの へんじを まって います。', 'Tôi đang chờ thư trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5761, 29128, '台風十号が近づいています。', 'たいふう じゅうごうが ちかづいて います。', 'Cơn bão số mười đang đến gần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5762, 29133, 'のぞみ四十二号で東京へ帰ります。', 'のぞみ よんじゅうにごうで とうきょうへ かえります。', 'Tôi về Tokyo bằng tàu Nozomi số 42.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5763, 29173, 'マンションの管理人に相談しました。', 'マンションの かんりにんに そうだん しました。', 'Tôi đã trao đổi với người quản lý chung cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5764, 29218, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5765, 29363, '日本の食べ物、例えばすしやてんぷらが好きです。', 'にほんの たべもの、たとえば すしや てんぷらが すき です。', 'Tôi thích đồ ăn Nhật, ví dụ như sushi hay tempura.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5766, 29374, '結果がわかったら、知らせてください。', 'けっかが わかったら、しらせて ください。', 'Khi biết kết quả hãy báo cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5767, 29453, '日本の食べ物、例えばすしやてんぷらが好きです。', 'にほんの たべもの、たとえば すしや てんぷらが すき です。', 'Tôi thích đồ ăn Nhật, ví dụ như sushi hay tempura.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5768, 29517, 'ここにある本は自由に読んでもいいです。', 'ここに ある ほんは じゆうに よんでも いい です。', 'Sách ở đây cứ tự do đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5769, 29563, '田中様、お待ちしておりました。', 'たなかさま、おまち して おりました。', 'Ông Tanaka, chúng tôi đã chờ ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5770, 44098, '壁に絵が掛けてあります。', 'かべに えが かけて あります。', 'Trên tường có treo một bức tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5771, 44106, 'ごみは決められた日に出してください。', 'ごみは きめられた ひに だして ください。', 'Hãy đổ rác vào ngày quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5772, 44163, '毎週柔道を習っています。', 'まいしゅう じゅうどうを ならって います。', 'Hằng tuần tôi học judo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5773, 44171, '山の上から見る景色はきれいです。', 'やまの うえから みる けしきは きれい です。', 'Phong cảnh nhìn từ trên núi rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5774, 44176, '日本人と会話するのは楽しいです。', 'にほんじんと かいわ するのは たのしい です。', 'Nói chuyện với người Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5775, 44466, 'ごみは決められた日に出してください。', 'ごみは きめられた ひに だして ください。', 'Hãy đổ rác vào ngày quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5776, 44467, '料理の道具を買いました。', 'りょうりの どうぐを かいました。', 'Tôi mua dụng cụ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5777, 38767, 'この島は一年中温暖な気候だ。', 'この しまは いちねんじゅう おんだんな きこうだ。', 'Hòn đảo này có khí hậu ấm áp quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5778, 38919, '動物園で虎の赤ちゃんが生まれた。', 'どうぶつえんで とらの あかちゃんが うまれた。', 'Ở sở thú, một chú hổ con vừa chào đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5779, 38966, '砂漠では昼と夜の気温の差が大きい。', 'さばくでは ひると よるの きおんの さが おおきい。', 'Ở sa mạc, nhiệt độ ngày và đêm chênh lệch lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5780, 39142, '昔は石炭で汽車を動かしていた。', 'むかしは せきたんで きしゃを うごかして いた。', 'Ngày xưa tàu hỏa chạy bằng than đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5781, 39143, '一晩で雪が三十センチ積もった。', 'ひとばんで ゆきが さんじゅっセンチ つもった。', 'Chỉ một đêm tuyết đã dày ba mươi phân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5782, 39153, '山の中にきれいな泉がある。', 'やまの なかに きれいな いずみが ある。', 'Trong núi có một dòng suối trong vắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5783, 39169, '今朝は畑に霜が降りていた。', 'けさは はたけに しもが おりて いた。', 'Sáng nay sương giá phủ trên ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5784, 39206, '谷の底を川が流れている。', 'たにの そこを かわが ながれて いる。', 'Dưới đáy thung lũng có dòng sông chảy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5785, 39219, '地平線に太陽が沈んでいく。', 'ちへいせんに たいようが しずんで いく。', 'Mặt trời đang lặn xuống đường chân trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5786, 39233, '三時間かけて山の頂上に着いた。', 'さんじかん かけて やまの ちょうじょうに ついた。', 'Mất ba tiếng chúng tôi mới lên đến đỉnh núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5787, 39256, 'この店では天然の魚しか使わない。', 'この みせでは てんねんの さかな しか つかわない。', 'Quán này chỉ dùng cá tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5788, 39263, '鉢に土を入れて、花を植えた。', 'はちに つちを いれて、はなを うえた。', 'Tôi cho đất vào chậu rồi trồng hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5789, 39293, '熱帯の国では一年中暑い。', 'ねったいの くにでは いちねんじゅう あつい。', 'Ở các nước nhiệt đới, nóng quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5790, 39307, '梅雨に入って、毎日雨が降っている。', 'つゆに はいって、まいにち あめが ふって いる。', 'Vào mùa mưa rồi, ngày nào cũng mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5791, 39395, 'せっけんがよく泡立つ。', 'せっけんが よく あわだつ。', 'Xà phòng nổi nhiều bọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5792, 39401, '夜中に隣の犬が吠えて、眠れなかった。', 'よなかに となりの いぬが ほえて、ねむれなかった。', 'Nửa đêm chó nhà bên sủa nên tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5793, 39446, '天気予報によると、明日は晴れるそうだ。', 'てんき よほうに よると、あしたは はれる そうだ。', 'Theo dự báo thời tiết, ngày mai trời nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5794, 39462, '嵐で木が何本も倒れた。', 'あらしで きが なんぼんも たおれた。', 'Cơn bão quật đổ nhiều cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5795, 38749, 'この会員カードは永久に使えます。', 'この かいいん カードは えいきゅうに つかえます。', 'Thẻ hội viên này dùng được vĩnh viễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5796, 38959, '今回の旅行はとても楽しかった。', 'こんかいの りょこうは とても たのしかった。', 'Chuyến du lịch lần này rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5797, 38960, '今日では誰でもインターネットを使っている。', 'こんにちでは だれでも インターネットを つかって いる。', 'Ngày nay ai cũng sử dụng Internet.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5798, 38046, '子供たちの未来のために環境を守ろう。', 'こどもたちの みらいの ために かんきょうを まもろう。', 'Hãy bảo vệ môi trường vì tương lai của trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5799, 38078, '休日は家族と過ごすことが多い。', 'きゅうじつは かぞくと すごす ことが おおい。', 'Ngày nghỉ tôi thường ở bên gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5800, 39232, '夏休みに長期の旅行をする予定だ。', 'なつやすみに ちょうきの りょこうを する よていだ。', 'Nghỉ hè tôi định đi du lịch dài ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5801, 39260, '家を出た途端、雨が降り出した。', 'いえを でた とたん、あめが ふりだした。', 'Vừa ra khỏi nhà thì trời đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5802, 47527, 'この家には古いしきたりが残っている。', 'この いえには ふるい しきたりが のこって いる。', 'Gia đình này vẫn giữ những lề thói cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5803, 38941, '航空会社に勤めている。', 'こうくう がいしゃに つとめて いる。', 'Tôi làm việc ở hãng hàng không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5804, 39288, '日常会話ぐらいなら日本語で話せる。', 'にちじょう かいわ ぐらいなら にほんごで はなせる。', 'Hội thoại thường ngày thì tôi nói được bằng tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5805, 39290, '書類に今日の日付を書いてください。', 'しょるいに きょうの ひづけを かいて ください。', 'Hãy ghi ngày hôm nay vào giấy tờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5806, 39297, 'この橋を作るのに長い年月がかかった。', 'この はしを つくるのに ながい としつきが かかった。', 'Xây cây cầu này đã mất rất nhiều năm tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5807, 39298, 'この歌は八十年代にはやった。', 'この うたは はちじゅう ねんだいに はやった。', 'Bài hát này thịnh hành vào những năm 80.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5808, 39357, '普段は電車で通勤している。', 'ふだんは でんしゃで つうきん して いる。', 'Bình thường tôi đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5809, 39405, '悩んだ末、会社を辞めることにした。', 'なやんだ すえ、かいしゃを やめる ことに した。', 'Sau bao trăn trở, tôi quyết định nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5810, 39425, '夜が明けるまで話し続けた。', 'よが あけるまで はなし つづけた。', 'Chúng tôi trò chuyện đến tận sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5811, 39427, '夜明け前に家を出た。', 'よあけまえに いえを でた。', 'Tôi ra khỏi nhà trước lúc bình minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5812, 39460, '来年度から新しい制度が始まる。', 'らいねんどから あたらしい せいどが はじまる。', 'Từ năm tài chính tới, chế độ mới sẽ bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5813, 31537, '日本語の勉強時間を増やしたい。', 'にほんごの べんきょう じかんを ふやしたい。', 'Tôi muốn tăng thời gian học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5814, 38971, '今朝の最低気温は零度だった。', 'けさの さいてい きおんは れいど だった。', 'Nhiệt độ thấp nhất sáng nay là 0 độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5815, 39119, 'この数字は何を表していますか。', 'この すうじは なにを あらわして いますか。', 'Con số này thể hiện điều gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5816, 39157, '問題は全て解決した。', 'もんだいは すべて かいけつ した。', 'Mọi vấn đề đều đã được giải quyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5817, 39179, '日本語なら多少話せます。', 'にほんごなら たしょう はなせます。', 'Tiếng Nhật thì tôi nói được chút ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5818, 39199, 'クラスの大半が賛成した。', 'クラスの たいはんが さんせい した。', 'Phần lớn cả lớp đã tán thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5819, 39262, 'この歌を聞く度に、故郷を思い出す。', 'この うたを きく たびに、こきょうを おもいだす。', 'Mỗi lần nghe bài hát này tôi lại nhớ quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5820, 39271, '二つの線の長さは等しい。', 'ふたつの せんの ながさは ひとしい。', 'Độ dài của hai đoạn thẳng bằng nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5821, 39311, '新しい空港には莫大な費用がかかった。', 'あたらしい くうこうには ばくだいな ひようが かかった。', 'Sân bay mới tốn một khoản chi phí khổng lồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5822, 39364, 'この道は幅が狭くて、車が通れない。', 'この みちは はばが せまくて、くるまが とおれない。', 'Con đường này hẹp nên xe hơi không đi qua được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5823, 39432, '音楽を聴くのが唯一の楽しみだ。', 'おんがくを きくのが ゆいいつの たのしみだ。', 'Nghe nhạc là niềm vui duy nhất của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5824, 42878, 'このシャツは三十パーセント引きだ。', 'この シャツは さんじゅっ パーセント びきだ。', 'Chiếc áo này được giảm 30%.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5825, 38753, '山を越えると、海が見えてくる。', 'やまを こえると、うみが みえて くる。', 'Vượt qua núi là sẽ thấy biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5826, 38754, '今年の冬は無事に越せそうだ。', 'ことしの ふゆは ぶじに こせそうだ。', 'Có vẻ mùa đông năm nay sẽ qua êm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5827, 38795, '冷たい水で顔を洗って、目を覚ました。', 'つめたい みずで かおを あらって、めを さました。', 'Tôi rửa mặt bằng nước lạnh cho tỉnh ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5828, 44464, '出かける前にガスを止めてください。', 'でかける まえに ガスを とめて ください。', 'Trước khi ra ngoài hãy khóa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5829, 38908, '会議の途中で社長が姿を現した。', 'かいぎの とちゅうで しゃちょうが すがたを あらわした。', 'Giữa cuộc họp thì giám đốc xuất hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5830, 37769, '図書館の本を返却した。', 'としょかんの ほんを へんきゃく した。', 'Tôi đã trả sách cho thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5831, 38972, '出かける前に宿題を済ませた。', 'でかける まえに しゅくだいを すませた。', 'Tôi làm xong bài tập trước khi ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5832, 37999, '彼にメールを送ったが、まだ反応がない。', 'かれに メールを おくったが、まだ はんのうが ない。', 'Tôi đã gửi mail cho anh ấy nhưng vẫn chưa có phản hồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5833, 39023, '授業中に使っていた携帯を先生に取り上げられた。', 'じゅぎょうちゅうに つかって いた けいたいを せんせいに とりあげられた。', 'Tôi bị thầy tịch thu điện thoại vì dùng trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5834, 39146, 'パスポートの期限が切れている。', 'パスポートの きげんが きれて いる。', 'Hộ chiếu đã hết hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5835, 39180, '転んで頭をぶった。', 'ころんで あたまを ぶった。', 'Tôi ngã và bị đập đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5836, 39204, '参加者が百人に達した。', 'さんかしゃが ひゃくにんに たっした。', 'Số người tham gia đã lên tới một trăm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5837, 39231, '窓から外の景色を眺めた。', 'まどから そとの けしきを ながめた。', 'Tôi ngắm cảnh bên ngoài qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5838, 39237, '急いで走って、前の人に追い付いた。', 'いそいで はしって、まえの ひとに おいついた。', 'Tôi chạy vội và đuổi kịp người phía trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5839, 39240, 'すみません、ちょっと通してください。', 'すみません、ちょっと とおして ください。', 'Xin lỗi, cho tôi đi qua một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5840, 39250, 'この割引は学生にだけ適用される。', 'この わりびきは がくせいに だけ てきよう される。', 'Ưu đãi giảm giá này chỉ áp dụng cho sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5841, 39269, '宝くじで一万円が当たった。', 'たからくじで いちまんえんが あたった。', 'Tôi trúng xổ số mười nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5842, 39281, 'この経験から多くのことを得た。', 'この けいけんから おおくの ことを えた。', 'Tôi đã thu được nhiều điều từ trải nghiệm này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5843, 39318, '忙しくて、昼ご飯を抜いた。', 'いそがしくて、ひるごはんを ぬいた。', 'Bận quá nên tôi bỏ bữa trưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5844, 39329, '風で帽子を飛ばされた。', 'かぜで ぼうしを とばされた。', 'Gió thổi bay mất chiếc mũ của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5845, 39330, '子供が急に道に飛び出してきた。', 'こどもが きゅうに みちに とびだして きた。', 'Một đứa trẻ bỗng lao ra đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5846, 39382, 'ファイルを保存してから閉じてください。', 'ファイルを ほぞん してから とじて ください。', 'Hãy lưu tệp trước khi đóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5847, 39392, '彼は大きな夢を抱いて東京に来た。', 'かれは おおきな ゆめを いだいて とうきょうに きた。', 'Anh ấy ôm ấp ước mơ lớn khi lên Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5848, 44229, '部屋に植物を置くと、気持ちが落ち着く。', 'へやに しょくぶつを おくと、きもちが おちつく。', 'Đặt cây xanh trong phòng giúp tâm trạng thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5849, 44589, '部屋に植物を置くと、気持ちが落ち着く。', 'へやに しょくぶつを おくと、きもちが おちつく。', 'Đặt cây xanh trong phòng giúp tâm trạng thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5850, 44598, '梅雨に入って、毎日雨が降っている。', 'つゆに はいって、まいにち あめが ふって いる。', 'Vào mùa mưa rồi, ngày nào cũng mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5851, 44958, '梅雨に入って、毎日雨が降っている。', 'つゆに はいって、まいにち あめが ふって いる。', 'Vào mùa mưa rồi, ngày nào cũng mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5852, 45218, 'この村の人口は減少している。', 'この むらの じんこうは げんしょう して いる。', 'Dân số làng này đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5853, 45384, '谷の底を川が流れている。', 'たにの そこを かわが ながれて いる。', 'Dưới đáy thung lũng có dòng sông chảy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5854, 45385, '三時間かけて山の頂上に着いた。', 'さんじかん かけて やまの ちょうじょうに ついた。', 'Mất ba tiếng chúng tôi mới lên đến đỉnh núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
