INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5856, 45739, 'アフリカ大陸を旅してみたい。', 'アフリカ たいりくを たびして みたい。', 'Tôi muốn thử du lịch châu Phi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
