INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5860, 46104, '谷の底を川が流れている。', 'たにの そこを かわが ながれて いる。', 'Dưới đáy thung lũng có dòng sông chảy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5861, 46109, '霧で前がよく見えない。', 'きりで まえが よく みえない。', 'Sương mù dày nên không nhìn rõ phía trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5862, 46302, 'ファイルを保存してから閉じてください。', 'ファイルを ほぞん してから とじて ください。', 'Hãy lưu tệp trước khi đóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5863, 46442, '砂漠では昼と夜の気温の差が大きい。', 'さばくでは ひると よるの きおんの さが おおきい。', 'Ở sa mạc, nhiệt độ ngày và đêm chênh lệch lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5864, 46523, '子供の成長は早い。', 'こどもの せいちょうは はやい。', 'Trẻ con lớn nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5865, 46662, 'ファイルを保存してから閉じてください。', 'ファイルを ほぞん してから とじて ください。', 'Hãy lưu tệp trước khi đóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5866, 46845, 'この店はメニューが豊富だ。', 'この みせは メニューが ほうふだ。', 'Quán này có thực đơn phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5867, 46883, '子供の成長は早い。', 'こどもの せいちょうは はやい。', 'Trẻ con lớn nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5868, 47009, '日本人の平均寿命は世界でも長い。', 'にほんじんの へいきん じゅみょうは せかいでも ながい。', 'Tuổi thọ trung bình của người Nhật thuộc hàng cao thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5869, 47205, 'この店はメニューが豊富だ。', 'この みせは メニューが ほうふだ。', 'Quán này có thực đơn phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5870, 47489, '彼にメールを送ったが、まだ反応がない。', 'かれに メールを おくったが、まだ はんのうが ない。', 'Tôi đã gửi mail cho anh ấy nhưng vẫn chưa có phản hồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5871, 47849, '彼にメールを送ったが、まだ反応がない。', 'かれに メールを おくったが、まだ はんのうが ない。', 'Tôi đã gửi mail cho anh ấy nhưng vẫn chưa có phản hồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5872, 47872, '現代の若者はスマホなしでは生活できない。', 'げんだいの わかものは スマホ なしでは せいかつ できない。', 'Giới trẻ ngày nay không thể sống thiếu điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5873, 48209, '彼にメールを送ったが、まだ反応がない。', 'かれに メールを おくったが、まだ はんのうが ない。', 'Tôi đã gửi mail cho anh ấy nhưng vẫn chưa có phản hồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5874, 44531, '山の上から見る景色はきれいです。', 'やまの うえから みる けしきは きれい です。', 'Phong cảnh nhìn từ trên núi rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5875, 44534, '子どもを動物園に連れていきました。', 'こどもを どうぶつえんに つれて いきました。', 'Tôi đưa con đi sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5876, 38866, 'このことはごく一部の人しか知らない。', 'この ことは ごく いちぶの ひと しか しらない。', 'Chuyện này chỉ một số rất ít người biết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5877, 28225, 'NHKのニュースを毎晩見ます。', 'エヌエイチケーの ニュースを まいばん みます。', 'Tối nào tôi cũng xem tin tức của NHK.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5878, 28428, 'ガイドブックを読んで、旅行の計画を立てました。', 'ガイドブックを よんで、りょこうの けいかくを たてました。', 'Tôi đọc sách hướng dẫn rồi lên kế hoạch du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5879, 28519, '上野公園で花見をしました。', 'うえの こうえんで はなみを しました。', 'Tôi ngắm hoa anh đào ở công viên Ueno.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5880, 39385, 'お盆に祖父の墓参りに行った。', 'おぼんに そふの はかまいりに いった。', 'Dịp lễ Obon tôi đi viếng mộ ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5881, 39449, '旅行の間、犬を友達に預けた。', 'りょこうの あいだ、いぬを ともだちに あずけた。', 'Trong thời gian đi du lịch, tôi gửi chó cho bạn trông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5882, 42877, '部屋に入る前にノックしてください。', 'へやに はいる まえに ノック して ください。', 'Trước khi vào phòng hãy gõ cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5883, 38794, 'この方法なら確実に成功する。', 'この ほうほうなら かくじつに せいこう する。', 'Với cách này chắc chắn sẽ thành công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5884, 38947, 'ホテルで豪華な食事をした。', 'ホテルで ごうかな しょくじを した。', 'Chúng tôi ăn một bữa thịnh soạn ở khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5885, 39044, 'これは会社にとって重大な問題だ。', 'これは かいしゃに とって じゅうだいな もんだいだ。', 'Đây là vấn đề nghiêm trọng đối với công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5886, 39054, '仕事は順調に進んでいる。', 'しごとは じゅんちょうに すすんで いる。', 'Công việc đang tiến triển suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5887, 39150, 'このことは絶対に誰にも言わないで。', 'この ことは ぜったいに だれにも いわないで。', 'Chuyện này tuyệt đối đừng nói với ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5888, 39210, '理由はとても単純だった。', 'りゆうは とても たんじゅん だった。', 'Lý do rất đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5889, 39277, 'この二つの事件の犯人は同一人物らしい。', 'この ふたつの じけんの はんにんは どういつ じんぶつ らしい。', 'Có vẻ thủ phạm của hai vụ này là cùng một người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5890, 39279, '今年も去年と同様に忙しい。', 'ことしも きょねんと どうように いそがしい。', 'Năm nay cũng bận như năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5891, 39328, '非常のときはこの階段を使ってください。', 'ひじょうの ときは この かいだんを つかって ください。', 'Khi khẩn cấp hãy dùng cầu thang này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5892, 39347, 'この部屋は飲食不可です。', 'この へやは いんしょく ふか です。', 'Phòng này không được ăn uống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5893, 39350, 'お金に不自由しない生活をしたい。', 'おかねに ふじゆう しない せいかつを したい。', 'Tôi muốn một cuộc sống không thiếu thốn tiền bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5894, 39377, '平らな場所にテントを張った。', 'たいらな ばしょに テントを はった。', 'Chúng tôi dựng lều ở chỗ bằng phẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5895, 39418, '彼がうそをついているのは明らかだ。', 'かれが うそを ついて いるのは あきらかだ。', 'Rõ ràng là anh ta đang nói dối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5969, 45094, '電車が遅れて、いらいらした。', 'でんしゃが おくれて、いらいら した。', 'Tàu bị trễ làm tôi bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5896, 39433, 'この製品は品質が優れている。', 'この せいひんは ひんしつが すぐれて いる。', 'Sản phẩm này có chất lượng vượt trội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5897, 39440, 'このチケットは今月末まで有効です。', 'この チケットは こんげつまつまで ゆうこう です。', 'Vé này có hiệu lực đến cuối tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5898, 39442, '英語ができると、就職に有利だ。', 'えいごが できると、しゅうしょくに ゆうりだ。', 'Biết tiếng Anh thì có lợi khi xin việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5899, 39450, '幼いころ、この公園でよく遊んだ。', 'おさない ころ、この こうえんで よく あそんだ。', 'Hồi còn bé tôi hay chơi ở công viên này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5900, 38706, '新しいテニスのラケットを買った。', 'あたらしい テニスの ラケットを かった。', 'Tôi đã mua cây vợt tennis mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5901, 38893, '学園祭でクラスの劇をやった。', 'がくえんさいで クラスの げきを やった。', 'Lớp tôi diễn kịch trong lễ hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5902, 38894, '週末、劇場でミュージカルを見た。', 'しゅうまつ、げきじょうで ミュージカルを みた。', 'Cuối tuần tôi xem nhạc kịch ở nhà hát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5903, 38044, '卒業の記念に写真を撮った。', 'そつぎょうの きねんに しゃしんを とった。', 'Chúng tôi chụp ảnh kỷ niệm ngày tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5904, 39048, '友達に結婚のお祝いを送った。', 'ともだちに けっこんの おいわいを おくった。', 'Tôi gửi quà mừng cưới cho bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5905, 39049, 'みんなで母の誕生日を祝った。', 'みんなで ははの たんじょうびを いわった。', 'Cả nhà cùng mừng sinh nhật mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5906, 38066, 'これは小さな村の少年の物語だ。', 'これは ちいさな むらの しょうねんの ものがたりだ。', 'Đây là câu chuyện về một cậu bé ở ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5907, 38067, 'この小説は登場人物が多くて、覚えられない。', 'この しょうせつは とうじょう じんぶつが おおくて、おぼえられない。', 'Tiểu thuyết này có nhiều nhân vật quá, tôi không nhớ nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5908, 38069, 'この作家は自然の描写がうまい。', 'この さっかは しぜんの びょうしゃが うまい。', 'Nhà văn này miêu tả thiên nhiên rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5909, 38073, 'あの人気漫画が映画化されるそうだ。', 'あの にんき まんがが えいがか される そうだ。', 'Nghe nói bộ truyện tranh nổi tiếng đó sẽ được chuyển thể thành phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5910, 38074, '夏になると、町で祭りが開かれる。', 'なつに なると、まちで まつりが ひらかれる。', 'Đến mùa hè, thị trấn tổ chức lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5911, 38076, 'お正月に家族で集まるのが我が家の習わしだ。', 'おしょうがつに かぞくで あつまるのが わがやの ならわしだ。', 'Tụ họp gia đình dịp Tết là tập tục của nhà tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5912, 38077, '来週の月曜日は祝日で休みだ。', 'らいしゅうの げつようびは しゅくじつで やすみだ。', 'Thứ Hai tuần sau là ngày lễ nên được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5913, 39154, '彼はサッカーの日本代表選手だ。', 'かれは サッカーの にほん だいひょう せんしゅだ。', 'Anh ấy là tuyển thủ bóng đá quốc gia Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5914, 39259, '夏休みに友達と富士山に登山した。', 'なつやすみに ともだちと ふじさんに とざん した。', 'Kỳ nghỉ hè tôi cùng bạn leo núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5915, 39285, '趣味は読書です。', 'しゅみは どくしょ です。', 'Sở thích của tôi là đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5916, 39309, '博物館で古い土器を見た。', 'はくぶつかんで ふるい どきを みた。', 'Tôi xem đồ gốm cổ ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5917, 39343, 'この小説は戦争の悲しさを描いている。', 'この しょうせつは せんそうの かなしさを えがいて いる。', 'Cuốn tiểu thuyết này miêu tả nỗi đau chiến tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5918, 39367, 'お寺で仏に手を合わせた。', 'おてらで ほとけに てを あわせた。', 'Tôi chắp tay vái Phật ở chùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5919, 39404, '幕が上がって、劇が始まった。', 'まくが あがって、げきが はじまった。', 'Màn kéo lên và vở kịch bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5920, 39421, '花の模様のハンカチをもらった。', 'はなの もようの ハンカチを もらった。', 'Tôi được tặng chiếc khăn tay họa tiết hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5921, 42865, '放課後、グランドでサッカーをした。', 'ほうかご、グランドで サッカーを した。', 'Sau giờ học chúng tôi đá bóng ở sân vận động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5922, 42870, 'スタンドから大きな声援が聞こえた。', 'スタンドから おおきな せいえんが きこえた。', 'Từ khán đài vang lên tiếng cổ vũ lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5923, 38707, '新しいロケットの打ち上げが成功した。', 'あたらしい ロケットの うちあげが せいこう した。', 'Vụ phóng tên lửa mới đã thành công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5924, 38751, '気象衛星の写真で台風の動きがわかる。', 'きしょう えいせいの しゃしんで たいふうの うごきが わかる。', 'Qua ảnh vệ tinh khí tượng có thể biết đường đi của bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5925, 37770, 'こちらに連絡先を書いてください。', 'こちらに れんらくさきを かいて ください。', 'Hãy ghi thông tin liên lạc vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5926, 39257, '最近は電子書籍で本を読む人が多い。', 'さいきんは でんし しょせきで ほんを よむ ひとが おおい。', 'Gần đây nhiều người đọc sách điện tử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5927, 39314, '会員カードを発行してもらった。', 'かいいん カードを はっこう して もらった。', 'Tôi đã được cấp thẻ hội viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5928, 39443, '郵便で書類を送った。', 'ゆうびんで しょるいを おくった。', 'Tôi gửi giấy tờ qua bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5929, 31432, '最近、結婚しない人が増える傾向にある。', 'さいきん、けっこん しない ひとが ふえる けいこうに ある。', 'Gần đây có xu hướng nhiều người không kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5930, 31433, 'これは珍しい自然現象だ。', 'これは めずらしい しぜん げんしょうだ。', 'Đây là một hiện tượng tự nhiên hiếm gặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5931, 31438, 'まず基礎をしっかり勉強しよう。', 'まず きそを しっかり べんきょう しよう。', 'Trước hết hãy học chắc phần cơ bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5932, 31450, 'ニュースでは標準語が使われている。', 'ニュースでは ひょうじゅんごが つかわれて いる。', 'Trên bản tin người ta dùng tiếng chuẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5933, 38909, '彼の言葉は優しさの現れだ。', 'かれの ことばは やさしさの あらわれだ。', 'Lời nói của anh ấy thể hiện sự tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5934, 38928, '山の上から見た光景は忘れられない。', 'やまの うえから みた こうけいは わすれられない。', 'Cảnh tượng nhìn từ đỉnh núi khó mà quên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5935, 38961, '困難を乗り越えて、夢をかなえた。', 'こんなんを のりこえて、ゆめを かなえた。', 'Vượt qua khó khăn, tôi đã thực hiện được ước mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5936, 38964, '道を渡る前に左右をよく見なさい。', 'みちを わたる まえに さゆうを よく みなさい。', 'Trước khi qua đường hãy nhìn kỹ hai bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5937, 38038, '練習しなければ、負けるのは必然だ。', 'れんしゅう しなければ、まけるのは ひつぜんだ。', 'Không luyện tập thì thua là điều tất yếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5938, 38048, 'この業界は将来性がある。', 'この ぎょうかいは しょうらいせいが ある。', 'Ngành này có tiềm năng trong tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5939, 38050, '正しい答えを四つの選択肢から選びなさい。', 'ただしい こたえを よっつの せんたくしから えらびなさい。', 'Hãy chọn đáp án đúng trong bốn phương án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5940, 39055, '順番に並んでお待ちください。', 'じゅんばんに ならんで おまち ください。', 'Xin hãy xếp hàng theo thứ tự và chờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5941, 39148, 'この歌は節が覚えやすい。', 'この うたは ふしが おぼえやすい。', 'Bài hát này có giai điệu dễ nhớ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5942, 39160, 'クラス全体で協力して準備した。', 'クラス ぜんたいで きょうりょく して じゅんび した。', 'Cả lớp đã cùng hợp sức chuẩn bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5943, 39172, 'ドラマの続きが気になる。', 'ドラマの つづきが きに なる。', 'Tôi rất tò mò về phần tiếp theo của bộ phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5944, 29001, '質問に答えます。', 'しつもんにこたえます。', 'Trả lời', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5945, 39174, '彼はチームにとって大きな存在だ。', 'かれは チームに とって おおきな そんざいだ。', 'Anh ấy là một nhân vật quan trọng đối với đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5946, 39222, '部長は今、会議中です。', 'ぶちょうは いま、かいぎちゅう です。', 'Trưởng phòng hiện đang họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5947, 39223, '部屋の中央にテーブルを置いた。', 'へやの ちゅうおうに テーブルを おいた。', 'Tôi đặt chiếc bàn ở giữa phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5948, 39254, '彼は典型的な日本のサラリーマンだ。', 'かれは てんけいてきな にほんの サラリーマンだ。', 'Anh ấy là kiểu nhân viên văn phòng Nhật điển hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5949, 39368, '夜中に台所で物音がした。', 'よなかに だいどころで ものおとが した。', 'Nửa đêm có tiếng động trong bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5950, 39369, '物事を前向きに考えるようにしている。', 'ものごとを まえむきに かんがえる ように して いる。', 'Tôi cố gắng nhìn mọi việc một cách tích cực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5951, 39380, 'この辺りにコンビニはありますか。', 'この あたりに コンビニは ありますか。', 'Quanh đây có cửa hàng tiện lợi không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5952, 42875, '彼はクラスでトップの成績だった。', 'かれは クラスで トップの せいせき だった。', 'Cậu ấy đứng đầu lớp về thành tích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5953, 38914, '彼は言わば会社の顔だ。', 'かれは いわば かいしゃの かおだ。', 'Có thể nói anh ấy là gương mặt đại diện của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5954, 38969, '十年後、再びこの町を訪れた。', 'じゅうねんご、ふたたび この まちを おとずれた。', 'Mười năm sau, tôi lại đến thăm thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5955, 39070, '彼の話は少しもおもしろくない。', 'かれの はなしは すこしも おもしろく ない。', 'Chuyện của anh ta chẳng thú vị chút nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5956, 39156, 'フランス語は全くわからない。', 'フランスごは まったく わからない。', 'Tiếng Pháp thì tôi hoàn toàn không hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5957, 39207, 'それは単なるうわさにすぎない。', 'それは たんなる うわさに すぎない。', 'Đó chỉ đơn thuần là tin đồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5958, 39234, '火事のときは直ちに外に出てください。', 'かじの ときは ただちに そとに でて ください。', 'Khi có cháy hãy ra ngoài ngay lập tức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5959, 39235, '社長と直に話す機会があった。', 'しゃちょうと じかに はなす きかいが あった。', 'Tôi có dịp nói chuyện trực tiếp với giám đốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5960, 39337, '高い物が必ずしもいい物とは限らない。', 'たかい ものが かならずしも いい ものとは かぎらない。', 'Đồ đắt không hẳn là đồ tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5961, 39455, '要するに、お金が足りないということだ。', 'ようするに、おかねが たりない と いう ことだ。', 'Tóm lại là không đủ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5962, 42889, '今日は昨日より暖かい。', 'きょうは きのうより あたたかい。', 'Hôm nay ấm hơn hôm qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5963, 46184, 'この国は自然が豊かだ。', 'この くには しぜんが ゆたかだ。', 'Đất nước này có thiên nhiên phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5964, 46185, '安定した仕事に就きたい。', 'あんてい した しごとに つきたい。', 'Tôi muốn có một công việc ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5965, 44622, '夜中に激しい雨が降った。', 'よなかに はげしい あめが ふった。', 'Nửa đêm trời mưa dữ dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5966, 45344, 'たまには贅沢なレストランで食事したい。', 'たまには ぜいたくな レストランで しょくじ したい。', 'Thỉnh thoảng tôi muốn ăn ở nhà hàng sang trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5967, 45345, '新しい部屋はとても快適だ。', 'あたらしい へやは とても かいてきだ。', 'Căn phòng mới rất dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5968, 47950, '最近、結婚しない人が増える傾向にある。', 'さいきん、けっこん しない ひとが ふえる けいこうに ある。', 'Gần đây có xu hướng nhiều người không kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11269, 43836, '宿題を出してください。', 'しゅくだいを だして ください。', 'Hãy nộp bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5970, 45107, 'おかしくて、思わず笑ってしまった。', 'おかしくて、おもわず わらって しまった。', 'Buồn cười quá, tôi bật cười không kìm được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5971, 45163, '明日、重要な会議があります。', 'あした、じゅうような かいぎが あります。', 'Ngày mai có một cuộc họp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5972, 45273, '習った文法を会話に応用してみよう。', 'ならった ぶんぽうを かいわに おうよう して みよう。', 'Hãy thử ứng dụng ngữ pháp đã học vào hội thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5973, 45406, '今日は海が穏やかだ。', 'きょうは うみが おだやかだ。', 'Hôm nay biển lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5974, 45407, '彼は見事に試験に合格した。', 'かれは みごとに しけんに ごうかく した。', 'Anh ấy đã thi đỗ một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5975, 45467, 'おかしくて、思わず笑ってしまった。', 'おかしくて、おもわず わらって しまった。', 'Buồn cười quá, tôi bật cười không kìm được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
