INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5977, 45633, '習った文法を会話に応用してみよう。', 'ならった ぶんぽうを かいわに おうよう して みよう。', 'Hãy thử ứng dụng ngữ pháp đã học vào hội thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5978, 45704, 'たまには贅沢なレストランで食事したい。', 'たまには ぜいたくな レストランで しょくじ したい。', 'Thỉnh thoảng tôi muốn ăn ở nhà hàng sang trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5979, 45706, '台所はいつも清潔にしておこう。', 'だいどころは いつも せいけつに して おこう。', 'Hãy luôn giữ bếp sạch sẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5980, 45814, '電車が遅れて、いらいらした。', 'でんしゃが おくれて、いらいら した。', 'Tàu bị trễ làm tôi bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5981, 45827, 'おかしくて、思わず笑ってしまった。', 'おかしくて、おもわず わらって しまった。', 'Buồn cười quá, tôi bật cười không kìm được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5982, 45883, '明日、重要な会議があります。', 'あした、じゅうような かいぎが あります。', 'Ngày mai có một cuộc họp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5983, 46065, '新しい部屋はとても快適だ。', 'あたらしい へやは とても かいてきだ。', 'Căn phòng mới rất dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5984, 44165, '夏休みに友達と富士山に登山した。', 'なつやすみに ともだちと ふじさんに とざん した。', 'Kỳ nghỉ hè tôi cùng bạn leo núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5985, 44521, '彼はサッカーの日本代表選手だ。', 'かれは サッカーの にほん だいひょう せんしゅだ。', 'Anh ấy là tuyển thủ bóng đá quốc gia Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5986, 44533, '博物館で古い土器を見た。', 'はくぶつかんで ふるい どきを みた。', 'Tôi xem đồ gốm cổ ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5987, 44885, '夏休みに友達と富士山に登山した。', 'なつやすみに ともだちと ふじさんに とざん した。', 'Kỳ nghỉ hè tôi cùng bạn leo núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5988, 38940, '雨は夜になって更に強くなった。', 'あめは よるに なって さらに つよく なった。', 'Về đêm mưa càng lớn hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5989, 46251, 'この装置は地震を感じると自動で止まる。', 'この そうちは じしんを かんじると じどうで とまる。', 'Thiết bị này tự dừng khi phát hiện động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5990, 46264, '山の中は通信が不安定だ。', 'やまの なかは つうしんが ふあんていだ。', 'Trong núi sóng liên lạc không ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5991, 46272, 'これは珍しい自然現象だ。', 'これは めずらしい しぜん げんしょうだ。', 'Đây là một hiện tượng tự nhiên hiếm gặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5992, 46305, 'アプリを最新のバージョンに更新してください。', 'アプリを さいしんの バージョンに こうしん して ください。', 'Hãy cập nhật ứng dụng lên phiên bản mới nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5993, 46319, 'この祭りには三百年の伝統がある。', 'この まつりには さんびゃくねんの でんとうが ある。', 'Lễ hội này có truyền thống ba trăm năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5994, 46323, '学校には一年中いろいろな行事がある。', 'がっこうには いちねんじゅう いろいろな ぎょうじが ある。', 'Ở trường có nhiều sự kiện suốt cả năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5995, 46331, '著者のサイン会に行った。', 'ちょしゃの サインかいに いった。', 'Tôi đi dự buổi ký tặng của tác giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5996, 46354, '映画の最後の場面で泣いてしまった。', 'えいがの さいごの ばめんで ないて しまった。', 'Tôi đã khóc ở cảnh cuối của bộ phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5997, 46364, 'このチーズには独特のにおいがある。', 'この チーズには どくとくの においが ある。', 'Loại phô mai này có mùi rất riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5998, 46544, 'この国は自然が豊かだ。', 'この くには しぜんが ゆたかだ。', 'Đất nước này có thiên nhiên phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (5999, 46616, 'スマホの言語を日本語に設定した。', 'スマホの げんごを にほんごに せってい した。', 'Tôi cài ngôn ngữ điện thoại sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6000, 46626, '人工知能が翻訳の仕事を手伝ってくれる。', 'じんこうちのうが ほんやくの しごとを てつだって くれる。', 'Trí tuệ nhân tạo hỗ trợ công việc dịch thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6001, 46672, 'この本の作者は誰ですか。', 'この ほんの さくしゃは だれ ですか。', 'Tác giả của cuốn sách này là ai?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6002, 46679, 'この祭りには三百年の伝統がある。', 'この まつりには さんびゃくねんの でんとうが ある。', 'Lễ hội này có truyền thống ba trăm năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6003, 46683, '学校には一年中いろいろな行事がある。', 'がっこうには いちねんじゅう いろいろな ぎょうじが ある。', 'Ở trường có nhiều sự kiện suốt cả năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6004, 46691, '著者のサイン会に行った。', 'ちょしゃの サインかいに いった。', 'Tôi đi dự buổi ký tặng của tác giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6005, 46707, 'この作家は自然の描写がうまい。', 'この さっかは しぜんの びょうしゃが うまい。', 'Nhà văn này miêu tả thiên nhiên rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
