INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6008, 46971, 'この装置は地震を感じると自動で止まる。', 'この そうちは じしんを かんじると じどうで とまる。', 'Thiết bị này tự dừng khi phát hiện động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6009, 46984, '山の中は通信が不安定だ。', 'やまの なかは つうしんが ふあんていだ。', 'Trong núi sóng liên lạc không ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6010, 28187, 'ごみは決められた日に出してください。', 'ごみは きめられた ひに だして ください。', 'Hãy đổ rác vào ngày quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6011, 46992, 'これは珍しい自然現象だ。', 'これは めずらしい しぜん げんしょうだ。', 'Đây là một hiện tượng tự nhiên hiếm gặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6012, 47025, 'アプリを最新のバージョンに更新してください。', 'アプリを さいしんの バージョンに こうしん して ください。', 'Hãy cập nhật ứng dụng lên phiên bản mới nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6013, 47033, 'この絵は有名な画家が描いたものだ。', 'この えは ゆうめいな がかが かいた ものだ。', 'Bức tranh này do một họa sĩ nổi tiếng vẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6014, 47043, '学校には一年中いろいろな行事がある。', 'がっこうには いちねんじゅう いろいろな ぎょうじが ある。', 'Ở trường có nhiều sự kiện suốt cả năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6015, 29550, '会社に勤めます。', 'かいしゃにつとめます。', 'Làm việc [ công ty ~]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6016, 47046, 'これは小さな村の少年の物語だ。', 'これは ちいさな むらの しょうねんの ものがたりだ。', 'Đây là câu chuyện về một cậu bé ở ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6017, 47067, 'この作家は自然の描写がうまい。', 'この さっかは しぜんの びょうしゃが うまい。', 'Nhà văn này miêu tả thiên nhiên rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6018, 47084, 'このチーズには独特のにおいがある。', 'この チーズには どくとくの においが ある。', 'Loại phô mai này có mùi rất riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6019, 47230, '最近、結婚しない人が増える傾向にある。', 'さいきん、けっこん しない ひとが ふえる けいこうに ある。', 'Gần đây có xu hướng nhiều người không kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6020, 47247, '要するに、お金が足りないということだ。', 'ようするに、おかねが たりない と いう ことだ。', 'Tóm lại là không đủ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6021, 47469, '彼は医学の分野で活躍している。', 'かれは いがくの ぶんやで かつやく して いる。', 'Anh ấy hoạt động tích cực trong lĩnh vực y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6022, 47607, '要するに、お金が足りないということだ。', 'ようするに、おかねが たりない と いう ことだ。', 'Tóm lại là không đủ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6023, 47967, '要するに、お金が足りないということだ。', 'ようするに、おかねが たりない と いう ことだ。', 'Tóm lại là không đủ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6024, 38704, 'ご家族の皆さんによろしくお伝えください。', 'ごかぞくの みなさんに よろしく おつたえ ください。', 'Cho tôi gửi lời hỏi thăm cả gia đình nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6025, 38729, 'この二つの言葉の違いを教えてください。', 'この ふたつの ことばの ちがいを おしえて ください。', 'Hãy cho tôi biết sự khác nhau giữa hai từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6026, 39006, '新しい店が次々にできている。', 'あたらしい みせが つぎつぎに できて いる。', 'Các cửa hàng mới lần lượt mọc lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6027, 42866, 'こんにちは、いい天気ですね。', 'こんにちは、いい てんき ですね。', 'Xin chào, hôm nay trời đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6028, 47959, '証拠がないので、犯人だと断定できない。', 'しょうこが ないので、はんにんだと だんてい できない。', 'Không có bằng chứng nên không thể khẳng định là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6029, 44834, 'このスープは味が薄いです。', 'この スープは あじが うすい です。', 'Món súp này nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6030, 44837, '日本の習慣はまだよくわかりません。', 'にほんの しゅうかんは まだ よく わかりません。', 'Tôi vẫn chưa hiểu rõ phong tục Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6031, 44891, '山の上から見る景色はきれいです。', 'やまの うえから みる けしきは きれい です。', 'Phong cảnh nhìn từ trên núi rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6032, 44894, '子どもを動物園に連れていきました。', 'こどもを どうぶつえんに つれて いきました。', 'Tôi đưa con đi sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6033, 28411, '壁にポスターをはりました。', 'かべに ポスターを はりました。', 'Tôi dán áp phích lên tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6034, 47841, 'いつか宇宙へ行ってみたいです。', 'いつか うちゅうへ いって みたい です。', 'Một ngày nào đó tôi muốn thử lên vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6035, 48201, 'いつか宇宙へ行ってみたいです。', 'いつか うちゅうへ いって みたい です。', 'Một ngày nào đó tôi muốn thử lên vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6036, 47529, '伝統文化を次の世代に継承したい。', 'でんとう ぶんかを つぎの せだいに けいしょう したい。', 'Tôi muốn truyền lại văn hóa truyền thống cho thế hệ sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6037, 46945, 'すべての人は法の前に平等だ。', 'すべての ひとは ほうの まえに びょうどうだ。', 'Mọi người đều bình đẳng trước pháp luật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6038, 37919, '家から会社まで往復二時間かかる。', 'いえから かいしゃまで おうふく にじかん かかる。', 'Đi về giữa nhà và công ty mất hai tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6039, 37922, '京都へ観光に行った。', 'きょうとへ かんこうに いった。', 'Tôi đi tham quan Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6040, 30834, '明日の朝六時に出発します。', 'あしたの あさ ろくじに しゅっぱつ します。', 'Sáu giờ sáng mai chúng ta xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6041, 30844, 'あいさつは人間関係の基本だ。', 'あいさつは にんげん かんけいの きほんだ。', 'Chào hỏi là điều cơ bản trong quan hệ con người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6042, 30871, '彼は自分の考えを強く主張した。', 'かれは じぶんの かんがえを つよく しゅちょう した。', 'Anh ấy khẳng định mạnh mẽ suy nghĩ của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6043, 30877, '彼女は我慢強くて、文句を言わない。', 'かのじょは がまんづよくて、もんくを いわない。', 'Cô ấy rất nhẫn nại, không hề than phiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6044, 30907, '市が住民の生活について調査している。', 'しが じゅうみんの せいかつに ついて ちょうさ して いる。', 'Thành phố đang khảo sát về đời sống người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6045, 30924, '私の言い方が悪くて、誤解されてしまった。', 'わたしの いいかたが わるくて、ごかい されて しまった。', 'Tôi nói chưa khéo nên bị hiểu lầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6046, 30926, 'その意見に賛成です。', 'その いけんに さんせい です。', 'Tôi tán thành ý kiến đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6047, 30935, '一年間の努力の成果が出た。', 'いちねんかんの どりょくの せいかが でた。', 'Thành quả của một năm nỗ lực đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6048, 37707, '彼の長所は誰にでも優しいところだ。', 'かれの ちょうしょは だれにでも やさしい ところだ。', 'Ưu điểm của anh ấy là tốt bụng với tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6049, 38521, '市民の意見を聞く会が開かれた。', 'しみんの いけんを きく かいが ひらかれた。', 'Một buổi lấy ý kiến người dân đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6050, 29228, '卒業論文を書いている。', 'そつぎょう ろんぶんを かいて いる。', 'Tôi đang viết luận văn tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6051, 31561, 'その問題について議論が続いている。', 'その もんだいに ついて ぎろんが つづいて いる。', 'Cuộc tranh luận về vấn đề đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6052, 31563, '彼は自分の考えを強く主張した。', 'かれは じぶんの かんがえを つよく しゅちょう した。', 'Anh ấy khẳng định mạnh mẽ suy nghĩ của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6053, 31707, '十八歳になったら、車の免許を取りたい。', 'じゅうはっさいに なったら、くるまの めんきょを とりたい。', 'Đủ mười tám tuổi tôi muốn lấy bằng lái ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6054, 27336, '重い荷物を持ってあげましょうか。', 'おもい にもつを もって あげましょうか。', 'Để tôi xách giúp hành lý nặng nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6055, 39913, '給与は毎月二十五日に振り込まれる。', 'きゅうよは まいつき にじゅうごにちに ふりこまれる。', 'Lương được chuyển khoản vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6056, 31114, '明日、授業でレポートを発表する。', 'あした、じゅぎょうで レポートを はっぴょう する。', 'Ngày mai tôi trình bày báo cáo trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6057, 31675, '大雨で住民は学校に避難した。', 'おおあめで じゅうみんは がっこうに ひなん した。', 'Do mưa lớn, người dân đã sơ tán đến trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6058, 31686, '世論は新しい法律に反対している。', 'よろんは あたらしい ほうりつに はんたい して いる。', 'Dư luận phản đối luật mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6059, 43143, '京都の名所を案内してもらった。', 'きょうとの めいしょを あんない して もらった。', 'Tôi được dẫn đi thăm các danh thắng ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6060, 31665, '災害のときのために、水と食料を用意しておこう。', 'さいがいの ときの ために、みずと しょくりょうを ようい して おこう。', 'Hãy chuẩn bị sẵn nước và lương thực phòng khi thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6061, 39821, '日本には火山がたくさんある。', 'にほんには かざんが たくさん ある。', 'Nhật Bản có rất nhiều núi lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6062, 40227, '日本の夏は蒸し暑い。', 'にほんの なつは むしあつい。', 'Mùa hè ở Nhật oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6063, 31677, '手を洗って、風邪を防ごう。', 'てを あらって、かぜを ふせごう。', 'Hãy rửa tay để phòng cảm cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6064, 39980, '頂上までの道はとても険しかった。', 'ちょうじょうまでの みちは とても けわしかった。', 'Đường lên đỉnh núi rất hiểm trở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6065, 40345, '買ったばかりの服を早速着てみた。', 'かった ばかりの ふくを さっそく きて みた。', 'Tôi mặc thử ngay bộ quần áo vừa mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6066, 45487, '出かける前に、ガスを確認した。', 'でかける まえに、ガスを かくにん した。', 'Trước khi ra ngoài tôi kiểm tra lại bếp ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6067, 41127, '冬は光熱費が高くなる。', 'ふゆは こうねつひが たかく なる。', 'Mùa đông tiền điện nước ga tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6068, 27463, '話はだいたいわかりました。', 'はなしは だいたい わかりました。', 'Câu chuyện thì tôi hiểu đại khái rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6069, 31172, '今年は会社の利益が増えた。', 'ことしは かいしゃの りえきが ふえた。', 'Năm nay lợi nhuận công ty tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6070, 27767, 'この工場ではいろいろな製品を作っている。', 'この こうじょうでは いろいろな せいひんを つくって いる。', 'Nhà máy này sản xuất nhiều loại sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6071, 27786, '彼の専門は日本文学だ。', 'かれの せんもんは にほん ぶんがくだ。', 'Chuyên môn của anh ấy là văn học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6072, 45349, 'この町は交通が便利だ。', 'この まちは こうつうが べんりだ。', 'Giao thông ở thị trấn này rất thuận tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6073, 27906, 'この店は現金しか使えない。', 'この みせは げんきん しか つかえない。', 'Cửa hàng này chỉ nhận tiền mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6074, 27986, '東京は物価が高い。', 'とうきょうは ぶっかが たかい。', 'Vật giá ở Tokyo cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6075, 28007, 'この町は交通が便利だ。', 'この まちは こうつうが べんりだ。', 'Giao thông ở thị trấn này rất thuận tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6076, 28044, '首相が新しい政策を発表した。', 'しゅしょうが あたらしい せいさくを はっぴょう した。', 'Thủ tướng đã công bố chính sách mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6077, 28154, '夏休みは田舎の祖父母の家で過ごした。', 'なつやすみは いなかの そふぼの いえで すごした。', 'Kỳ nghỉ hè tôi ở nhà ông bà dưới quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6078, 28244, '今日は波が高いので、泳がないでください。', 'きょうは なみが たかいので、およがないで ください。', 'Hôm nay sóng lớn, xin đừng bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6079, 28482, '明日、授業でレポートを発表する。', 'あした、じゅぎょうで レポートを はっぴょう する。', 'Ngày mai tôi trình bày báo cáo trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6080, 28511, '都会の生活は便利だが、疲れる。', 'とかいの せいかつは べんりだが、つかれる。', 'Cuộc sống thành phố tiện lợi nhưng mệt mỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6081, 31187, '今の生活に満足している。', 'いまの せいかつに まんぞく して いる。', 'Tôi hài lòng với cuộc sống hiện tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6082, 28611, '財布を落としたので、警察に届けた。', 'さいふを おとしたので、けいさつに とどけた。', 'Đánh rơi ví nên tôi đã báo cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6083, 45049, '兄と私は性格が全然違う。', 'あにと わたしは せいかくが ぜんぜん ちがう。', 'Anh trai và tôi tính cách hoàn toàn khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6084, 45052, '日本の第一印象はどうでしたか。', 'にほんの だいいち いんしょうは どう でしたか。', 'Ấn tượng đầu tiên của bạn về Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6085, 45054, '彼の長所は誰にでも優しいところだ。', 'かれの ちょうしょは だれにでも やさしい ところだ。', 'Ưu điểm của anh ấy là tốt bụng với tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6086, 45056, '日本語の会話に自信がついてきた。', 'にほんごの かいわに じしんが ついて きた。', 'Tôi đã tự tin hơn khi nói tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6087, 45059, '彼女は我慢強くて、文句を言わない。', 'かのじょは がまんづよくて、もんくを いわない。', 'Cô ấy rất nhẫn nại, không hề than phiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6088, 45062, 'カラスはとても賢い鳥だ。', 'カラスは とても かしこい とりだ。', 'Quạ là loài chim rất thông minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6089, 45064, '服装がだらしないと、印象が悪い。', 'ふくそうが だらしないと、いんしょうが わるい。', 'Ăn mặc luộm thuộm thì gây ấn tượng xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6090, 45065, '困ったときに助けてくれる頼もしい先輩だ。', 'こまった ときに たすけて くれる たのもしい せんぱいだ。', 'Đó là đàn anh đáng tin cậy, luôn giúp tôi khi khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6091, 45067, '彼は会議ではいつも消極的だ。', 'かれは かいぎでは いつも しょうきょくてきだ。', 'Trong cuộc họp anh ấy lúc nào cũng thụ động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6092, 45070, '明日が試験なのに、弟はのんきに遊んでいる。', 'あしたが しけん なのに、おとうとは のんきに あそんで いる。', 'Mai thi mà em trai tôi vẫn vô tư chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6093, 45072, '人のものを勝手に使わないで。', 'ひとの ものを かってに つかわないで。', 'Đừng tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6094, 45074, '彼女は話し方が上品だ。', 'かのじょは はなしかたが じょうひんだ。', 'Cô ấy nói năng thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6095, 45075, 'そんな下品な言葉を使わないで。', 'そんな げひんな ことばを つかわないで。', 'Đừng dùng những lời thô tục như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6096, 45077, '彼女は私より三つ年上だ。', 'かのじょは わたしより みっつ としうえだ。', 'Cô ấy hơn tôi ba tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6097, 45078, '彼は年下だが、とてもしっかりしている。', 'かれは としした だが、とても しっかり して いる。', 'Cậu ấy nhỏ tuổi hơn nhưng rất chững chạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6098, 45081, '何があっても、私はあなたの味方だよ。', 'なにが あっても、わたしは あなたの みかた だよ。', 'Dù có chuyện gì, tôi vẫn đứng về phía bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6099, 45084, '彼は部下から信頼されている。', 'かれは ぶかから しんらい されて いる。', 'Anh ấy được cấp dưới tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6100, 45087, '私の言い方が悪くて、誤解されてしまった。', 'わたしの いいかたが わるくて、ごかい されて しまった。', 'Tôi nói chưa khéo nên bị hiểu lầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6101, 45089, 'もっと勉強すればよかったと後悔している。', 'もっと べんきょう すれば よかったと こうかい して いる。', 'Tôi hối hận vì đã không học chăm hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6102, 45092, '今の生活に満足している。', 'いまの せいかつに まんぞく して いる。', 'Tôi hài lòng với cuộc sống hiện tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6103, 45097, '子供が無事だと聞いて、ほっとした。', 'こどもが ぶじだと きいて、ほっと した。', 'Nghe tin con an toàn, tôi thở phào nhẹ nhõm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6104, 45099, '子供のころから、パイロットに憧れていた。', 'こどもの ころから、パイロットに あこがれて いた。', 'Từ nhỏ tôi đã ngưỡng mộ nghề phi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6105, 45100, '彼は今でも昔の友達を恨んでいる。', 'かれは いまでも むかしの ともだちを うらんで いる。', 'Đến giờ anh ấy vẫn oán người bạn cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6106, 45102, '一点差で負けて、とても悔しい。', 'いってんさで まけて、とても くやしい。', 'Thua chỉ một điểm, thật cay cú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6107, 45104, 'この料理は見た目はよくないが、おいしい。', 'この りょうりは みためは よくないが、おいしい。', 'Món này trông không đẹp mắt nhưng ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6108, 45108, 'ダイエット中なのに、ついケーキを食べてしまった。', 'ダイエットちゅう なのに、つい ケーキを たべて しまった。', 'Đang ăn kiêng mà tôi lỡ ăn mất miếng bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6109, 45110, '職場の人たちはみんな親切だ。', 'しょくばの ひとたちは みんな しんせつだ。', 'Mọi người ở chỗ làm đều tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6110, 45115, 'テレビで新商品を宣伝している。', 'テレビで しんしょうひんを せんでん して いる。', 'Sản phẩm mới đang được quảng cáo trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6111, 45118, '早く予約すると得だ。', 'はやく よやく すると とくだ。', 'Đặt sớm thì có lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6112, 45123, '給料について会社と交渉した。', 'きゅうりょうに ついて かいしゃと こうしょう した。', 'Tôi đã đàm phán lương với công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6113, 45126, '会議で新しい企画を提案した。', 'かいぎで あたらしい きかくを ていあん した。', 'Tôi đề xuất một kế hoạch mới trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6114, 45130, '上司の指示どおりに作業を進めた。', 'じょうしの しじ どおりに さぎょうを すすめた。', 'Tôi tiến hành công việc theo chỉ thị của cấp trên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6115, 45133, '面接を受けた会社に採用された。', 'めんせつを うけた かいしゃに さいよう された。', 'Tôi đã được công ty mình phỏng vấn tuyển dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6116, 45136, '給与は毎月二十五日に振り込まれる。', 'きゅうよは まいつき にじゅうごにちに ふりこまれる。', 'Lương được chuyển khoản vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6117, 45137, '姉は銀行に勤務している。', 'あねは ぎんこうに きんむ して いる。', 'Chị tôi làm việc ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6118, 45139, 'あの会社とは長い間取引がある。', 'あの かいしゃとは ながい あいだ とりひきが ある。', 'Chúng tôi giao dịch với công ty đó đã lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6119, 45142, '一年間の努力の成果が出た。', 'いちねんかんの どりょくの せいかが でた。', 'Thành quả của một năm nỗ lực đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6120, 45145, '彼の専門は日本文学だ。', 'かれの せんもんは にほん ぶんがくだ。', 'Chuyên môn của anh ấy là văn học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6121, 45147, '間違いが多かったので、作文を書き直した。', 'まちがいが おおかったので、さくぶんを かきなおした。', 'Nhiều lỗi quá nên tôi viết lại bài văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6122, 45148, '難しい仕事を引き受けてしまった。', 'むずかしい しごとを ひきうけて しまった。', 'Tôi lỡ nhận một công việc khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6123, 45152, 'このまま計画を進めましょう。', 'この まま けいかくを すすめましょう。', 'Cứ tiếp tục triển khai kế hoạch như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6124, 45154, '忙しかったので、誘いを断った。', 'いそがしかったので、さそいを ことわった。', 'Vì bận nên tôi đã từ chối lời mời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6125, 45155, '夏休みにアルバイトで旅行のお金を稼いだ。', 'なつやすみに アルバイトで りょこうの おかねを かせいだ。', 'Kỳ nghỉ hè tôi làm thêm để kiếm tiền đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6126, 45157, '電車を間違えて、遠くまで行ってしまった。', 'でんしゃを まちがえて、とおくまで いって しまった。', 'Đi nhầm tàu nên tôi bị đi xa mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6127, 45159, '忙しさのあまり、食事を忘れてしまった。', 'いそがしさの あまり、しょくじを わすれて しまった。', 'Bận quá đến mức quên cả ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6128, 45162, '正確な時間を教えてください。', 'せいかくな じかんを おしえて ください。', 'Hãy cho tôi biết giờ chính xác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6129, 27605, 'ここは簡単です。', 'ここはかんたんです。', 'Ở đây easy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6130, 45166, '至急、部長に連絡してください。', 'しきゅう、ぶちょうに れんらく して ください。', 'Hãy liên lạc với trưởng phòng gấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6131, 45167, '買ったばかりの服を早速着てみた。', 'かった ばかりの ふくを さっそく きて みた。', 'Tôi mặc thử ngay bộ quần áo vừa mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6132, 45172, '少子化で学校の数が減っている。', 'しょうしかで がっこうの かずが へって いる。', 'Do tỷ lệ sinh giảm, số trường học đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6133, 45173, '日本では高齢化が進んでいる。', 'にほんでは こうれいかが すすんで いる。', 'Ở Nhật, dân số đang ngày càng già hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6134, 45176, '首相が新しい政策を発表した。', 'しゅしょうが あたらしい せいさくを はっぴょう した。', 'Thủ tướng đã công bố chính sách mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6135, 45180, '税金を払うのは国民の義務だ。', 'ぜいきんを はらうのは こくみんの ぎむだ。', 'Nộp thuế là nghĩa vụ của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6136, 45182, '二度と戦争を起こしてはいけない。', 'にどと せんそうを おこしては いけない。', 'Không bao giờ được để chiến tranh xảy ra lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6137, 45185, '警察は犯人を探している。', 'けいさつは はんにんを さがして いる。', 'Cảnh sát đang truy tìm thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6138, 45188, '台風で農作物に大きな被害が出た。', 'たいふうで のうさくもつに おおきな ひがいが でた。', 'Bão gây thiệt hại lớn cho hoa màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6139, 45189, '災害のときのために、水と食料を用意しておこう。', 'さいがいの ときの ために、みずと しょくりょうを ようい して おこう。', 'Hãy chuẩn bị sẵn nước và lương thực phòng khi thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6140, 45191, '事故の原因はまだわかっていない。', 'じこの げんいんは まだ わかって いない。', 'Nguyên nhân tai nạn vẫn chưa rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6141, 45193, '台風の影響で、電車が止まった。', 'たいふうの えいきょうで、でんしゃが とまった。', 'Do ảnh hưởng của bão, tàu điện ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6142, 45194, 'この計画の問題点を話し合おう。', 'この けいかくの もんだいてんを はなしあおう。', 'Hãy bàn về những điểm có vấn đề trong kế hoạch này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6143, 45197, '市が住民の生活について調査している。', 'しが じゅうみんの せいかつに ついて ちょうさ して いる。', 'Thành phố đang khảo sát về đời sống người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6144, 45201, '事故のニュースが大きく報道された。', 'じこの ニュースが おおきく ほうどう された。', 'Tin về vụ tai nạn đã được đưa rầm rộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6145, 45204, 'この町には外国人がたくさん住んでいる。', 'この まちには がいこくじんが たくさん すんで いる。', 'Thị trấn này có nhiều người nước ngoài sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6146, 45208, '東京は物価が高い。', 'とうきょうは ぶっかが たかい。', 'Vật giá ở Tokyo cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6147, 45212, 'その意見に賛成です。', 'その いけんに さんせい です。', 'Tôi tán thành ý kiến đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6148, 45214, '彼は自分の考えを強く主張した。', 'かれは じぶんの かんがえを つよく しゅちょう した。', 'Anh ấy khẳng định mạnh mẽ suy nghĩ của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6149, 45215, 'その問題について議論が続いている。', 'その もんだいに ついて ぎろんが つづいて いる。', 'Cuộc tranh luận về vấn đề đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6150, 45219, '手を洗って、風邪を防ごう。', 'てを あらって、かぜを ふせごう。', 'Hãy rửa tay để phòng cảm cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6151, 45220, '何が起こったのか、教えてください。', 'なにが おこったのか、おしえて ください。', 'Hãy cho tôi biết chuyện gì đã xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6152, 45222, '泥棒は窓から逃げた。', 'どろぼうは まどから にげた。', 'Tên trộm chạy trốn qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6153, 45224, '彼はけがの痛みを医者に訴えた。', 'かれは けがの いたみを いしゃに うったえた。', 'Anh ấy than với bác sĩ về cơn đau do vết thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6154, 45226, '先生はすべての学生に公平だ。', 'せんせいは すべての がくせいに こうへいだ。', 'Thầy giáo công bằng với mọi học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6155, 45227, '日本では、家に入るとき靴を脱ぐのが一般的だ。', 'にほんでは、いえに はいる とき くつを ぬぐのが いっぱんてきだ。', 'Ở Nhật, cởi giày khi vào nhà là chuyện thông thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6156, 45231, '旅行の前に、その国の知識を身につけた。', 'りょこうの まえに、その くにの ちしきを みに つけた。', 'Trước chuyến đi tôi tìm hiểu kiến thức về nước đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6157, 45234, '科学の進歩で生活が便利になった。', 'かがくの しんぽで せいかつが べんりに なった。', 'Nhờ tiến bộ khoa học, cuộc sống trở nên tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6158, 28424, '今日の講義はとてもわかりやすかった。', 'きょうの こうぎは とても わかりやすかった。', 'Bài giảng hôm nay rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6159, 45260, '授業の前に予習しておきましょう。', 'じゅぎょうの まえに よしゅう して おきましょう。', 'Hãy chuẩn bị bài trước giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6160, 45239, '大学で心理学の授業を取っている。', 'だいがくで しんりがくの じゅぎょうを とって いる。', 'Tôi đang học môn tâm lý học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6161, 45240, '大学では経済を専攻しています。', 'だいがくでは けいざいを せんこう して います。', 'Ở đại học tôi học chuyên ngành kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6162, 45244, '週末までに課題を出さなければならない。', 'しゅうまつまでに かだいを ださなければ ならない。', 'Tôi phải nộp bài tập trước cuối tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6163, 45246, 'テストの点数が思ったより悪かった。', 'テストの てんすうが おもったより わるかった。', 'Điểm bài kiểm tra tệ hơn tôi nghĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6164, 45247, '試験に合格して、とてもうれしい。', 'しけんに ごうかく して、とても うれしい。', 'Thi đỗ rồi, tôi vui lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6165, 45249, '四月に大学に入学した。', 'しがつに だいがくに にゅうがく した。', 'Tôi nhập học đại học vào tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6166, 45251, '兄は今年、大学を受験する。', 'あには ことし、だいがくを じゅけん する。', 'Năm nay anh tôi thi đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6167, 45254, 'アルバイトをして学費を払っている。', 'アルバイトを して がくひを はらって いる。', 'Tôi làm thêm để trả học phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6168, 46139, '将来のために少しずつ投資をしている。', 'しょうらいの ために すこしずつ とうしを して いる。', 'Tôi đầu tư từng chút một cho tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6169, 45255, '校長先生が入学式でスピーチをした。', 'こうちょう せんせいが にゅうがくしきで スピーチを した。', 'Thầy hiệu trưởng phát biểu trong lễ khai giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6170, 45258, '駅で小学校の同級生に会った。', 'えきで しょうがっこうの どうきゅうせいに あった。', 'Tôi gặp bạn cùng lớp tiểu học ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6171, 45274, '例を挙げて説明してください。', 'れいを あげて せつめい して ください。', 'Hãy lấy ví dụ để giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6172, 45276, 'この問題の正解は三番です。', 'この もんだいの せいかいは さんばん です。', 'Đáp án đúng của câu này là số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6173, 45279, '失敗から学ぶことは多い。', 'しっぱいから まなぶ ことは おおい。', 'Có nhiều điều học được từ thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6174, 45280, '留学して、生きた日本語を身につけたい。', 'りゅうがく して、いきた にほんごを みに つけたい。', 'Tôi muốn đi du học để học được tiếng Nhật thực tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6175, 45283, '仕事を通して多くの経験を得た。', 'しごとを とおして おおくの けいけんを えた。', 'Qua công việc tôi đã có thêm nhiều kinh nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6176, 45285, '学生たちは熱心に先生の話を聞いている。', 'がくせいたちは ねっしんに せんせいの はなしを きいて いる。', 'Các học sinh đang chăm chú nghe thầy giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6177, 45287, '明日は必ず来てください。', 'あしたは かならず きて ください。', 'Ngày mai nhất định phải đến nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6178, 45290, '毎月家計簿をつけている。', 'まいつき かけいぼを つけて いる。', 'Tháng nào tôi cũng ghi sổ chi tiêu gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6179, 45295, 'すみません、領収書をください。', 'すみません、りょうしゅうしょを ください。', 'Xin lỗi, cho tôi xin hóa đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6180, 45298, 'その商品は在庫がありません。', 'その しょうひんは ざいこが ありません。', 'Mặt hàng đó đã hết hàng trong kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6181, 45305, 'このパソコンは一年間の保証がついている。', 'この パソコンは いちねんかんの ほしょうが ついて いる。', 'Máy tính này được bảo hành một năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6182, 45307, '引っ越しで新しい家具を買った。', 'ひっこしで あたらしい かぐを かった。', 'Chuyển nhà nên tôi mua đồ nội thất mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6183, 45310, 'しょうゆは日本料理に欠かせない調味料だ。', 'しょうゆは にほん りょうりに かかせない ちょうみりょうだ。', 'Xì dầu là gia vị không thể thiếu trong món Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6184, 45312, '毎日の献立を考えるのは大変だ。', 'まいにちの こんだてを かんがえるのは たいへんだ。', 'Nghĩ thực đơn mỗi ngày thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6185, 45314, '節約のために毎日自炊している。', 'せつやくの ために まいにち じすい して いる。', 'Để tiết kiệm, ngày nào tôi cũng tự nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6186, 45317, '都会では近所付き合いが少ない。', 'とかいでは きんじょづきあいが すくない。', 'Ở thành phố ít có quan hệ hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6187, 45319, 'ごみ出しは朝八時までにしてください。', 'ごみだしは あさ はちじまでに して ください。', 'Hãy đổ rác trước tám giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6188, 45323, '契約書をよく読んでからサインしてください。', 'けいやくしょを よく よんでから サイン して ください。', 'Hãy đọc kỹ hợp đồng rồi mới ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6189, 45327, '引っ越したら、役所に届け出をしてください。', 'ひっこしたら、やくしょに とどけでを して ください。', 'Chuyển nhà xong hãy khai báo ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6190, 45329, '旅行の前に保険に入った。', 'りょこうの まえに ほけんに はいった。', 'Trước chuyến đi tôi đã mua bảo hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6191, 45331, '旅行中、友達の猫を預かっている。', 'りょこうちゅう、ともだちの ねこを あずかって いる。', 'Trong lúc bạn đi du lịch, tôi trông giúp con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6192, 45333, '家賃を銀行に振り込んだ。', 'やちんを ぎんこうに ふりこんだ。', 'Tôi đã chuyển khoản tiền nhà qua ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6193, 47532, '小学生のころ、書道を習っていた。', 'しょうがくせいの ころ、しょどうを ならって いた。', 'Hồi tiểu học tôi từng học thư pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6194, 28216, '私の考えはあなたと違います。', 'わたしの かんがえは あなたと ちがいます。', 'Suy nghĩ của tôi khác với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6195, 38942, '行きは電車で、帰りはバスにしよう。', 'いきは でんしゃで、かえりは バスに しよう。', 'Lúc đi bằng tàu, lúc về đi xe buýt nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6196, 45334, '新しいパソコンを買うためにお金を貯めている。', 'あたらしい パソコンを かう ために おかねを ためて いる。', 'Tôi đang để dành tiền mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6197, 45336, '料理が余ったので、近所に分けた。', 'りょうりが あまったので、きんじょに わけた。', 'Đồ ăn còn thừa nên tôi chia cho hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6198, 45338, 'プレゼント用に包装してください。', 'プレゼントように ほうそう して ください。', 'Hãy gói lại giúp tôi để làm quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6199, 45340, '朝の電車はとても混んでいる。', 'あさの でんしゃは とても こんで いる。', 'Tàu buổi sáng rất đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6200, 45342, 'コンビニは便利だが、少し割高だ。', 'コンビニは べんりだが、すこし わりだかだ。', 'Cửa hàng tiện lợi thì tiện nhưng hơi đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6201, 45352, '十八歳になったら、車の免許を取りたい。', 'じゅうはっさいに なったら、くるまの めんきょを とりたい。', 'Đủ mười tám tuổi tôi muốn lấy bằng lái ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6202, 45355, '家から会社まで往復二時間かかる。', 'いえから かいしゃまで おうふく にじかん かかる。', 'Đi về giữa nhà và công ty mất hai tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6203, 45357, '新宿で乗り換えがあります。', 'しんじゅくで のりかえが あります。', 'Phải chuyển tàu ở Shinjuku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6204, 45358, '飲み会で終電を逃してしまった。', 'のみかいで しゅうでんを のがして しまった。', 'Đi nhậu nên tôi lỡ chuyến tàu cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6205, 45360, '明日の朝六時に出発します。', 'あしたの あさ ろくじに しゅっぱつ します。', 'Sáu giờ sáng mai chúng ta xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6206, 45362, '京都へ観光に行った。', 'きょうとへ かんこうに いった。', 'Tôi đi tham quan Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6207, 45365, '温泉の旅館に二泊した。', 'おんせんの りょかんに にはく した。', 'Tôi nghỉ hai đêm ở lữ quán có suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6208, 45366, '週末に温泉に行って、ゆっくり休んだ。', 'しゅうまつに おんせんに いって、ゆっくり やすんだ。', 'Cuối tuần tôi đi suối nước nóng và nghỉ ngơi thong thả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6209, 45368, '空港の税関で荷物を調べられた。', 'くうこうの ぜいかんで にもつを しらべられた。', 'Hành lý của tôi bị kiểm tra ở hải quan sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6210, 45372, '都会の生活は便利だが、疲れる。', 'とかいの せいかつは べんりだが、つかれる。', 'Cuộc sống thành phố tiện lợi nhưng mệt mỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6211, 45374, '子供が生まれて、郊外に引っ越した。', 'こどもが うまれて、こうがいに ひっこした。', 'Có con rồi nên chúng tôi chuyển ra ngoại ô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6212, 45375, '机の位置を窓の近くに変えた。', 'つくえの いちを まどの ちかくに かえた。', 'Tôi chuyển vị trí bàn lại gần cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6213, 45378, '高いビルが町の景観を壊している。', 'たかい ビルが まちの けいかんを こわして いる。', 'Những tòa nhà cao tầng đang phá hỏng cảnh quan thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6214, 45381, '朝、海岸を散歩した。', 'あさ、かいがんを さんぽ した。', 'Buổi sáng tôi đi dạo dọc bờ biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6215, 45386, '日本には火山がたくさんある。', 'にほんには かざんが たくさん ある。', 'Nhật Bản có rất nhiều núi lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6216, 45388, '夜中に大きな雷が鳴った。', 'よなかに おおきな かみなりが なった。', 'Nửa đêm có tiếng sấm lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6217, 45390, '雨のあとで、空に虹が出た。', 'あめの あとで、そらに にじが でた。', 'Sau cơn mưa, cầu vồng hiện trên bầu trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6218, 45392, '日本の気候は地方によって違う。', 'にほんの きこうは ちほうに よって ちがう。', 'Khí hậu Nhật Bản khác nhau theo từng vùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6219, 45394, '工場の水で川が汚染された。', 'こうじょうの みずで かわが おせん された。', 'Nước thải nhà máy đã làm ô nhiễm dòng sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6220, 45396, '話に夢中で、降りる駅を通り過ぎた。', 'はなしに むちゅうで、おりる えきを とおりすぎた。', 'Mải nói chuyện nên tôi đi quá ga cần xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6221, 45398, '忘れ物をして、家に戻った。', 'わすれものを して、いえに もどった。', 'Quên đồ nên tôi quay về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6222, 45400, '寝坊して、バスに乗り遅れた。', 'ねぼう して、バスに のりおくれた。', 'Ngủ quên nên tôi lỡ xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6223, 45402, '暑くて、アイスがすぐ溶けた。', 'あつくて、アイスが すぐ とけた。', 'Trời nóng nên kem tan ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6224, 45404, '日本の夏は蒸し暑い。', 'にほんの なつは むしあつい。', 'Mùa hè ở Nhật oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6225, 45408, 'ぎりぎりで電車に間に合った。', 'ぎりぎりで でんしゃに まにあった。', 'Tôi kịp tàu trong gang tấc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6226, 45409, '兄と私は性格が全然違う。', 'あにと わたしは せいかくが ぜんぜん ちがう。', 'Anh trai và tôi tính cách hoàn toàn khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6227, 45413, '子供の個性を大切にしたい。', 'こどもの こせいを たいせつに したい。', 'Tôi muốn trân trọng cá tính của con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6228, 45414, '彼の長所は誰にでも優しいところだ。', 'かれの ちょうしょは だれにでも やさしい ところだ。', 'Ưu điểm của anh ấy là tốt bụng với tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6229, 45416, '日本語の会話に自信がついてきた。', 'にほんごの かいわに じしんが ついて きた。', 'Tôi đã tự tin hơn khi nói tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6230, 45419, '彼女は我慢強くて、文句を言わない。', 'かのじょは がまんづよくて、もんくを いわない。', 'Cô ấy rất nhẫn nại, không hề than phiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6231, 45422, 'カラスはとても賢い鳥だ。', 'カラスは とても かしこい とりだ。', 'Quạ là loài chim rất thông minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6232, 45424, '服装がだらしないと、印象が悪い。', 'ふくそうが だらしないと、いんしょうが わるい。', 'Ăn mặc luộm thuộm thì gây ấn tượng xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6233, 45425, '困ったときに助けてくれる頼もしい先輩だ。', 'こまった ときに たすけて くれる たのもしい せんぱいだ。', 'Đó là đàn anh đáng tin cậy, luôn giúp tôi khi khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6234, 45427, '彼は会議ではいつも消極的だ。', 'かれは かいぎでは いつも しょうきょくてきだ。', 'Trong cuộc họp anh ấy lúc nào cũng thụ động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6235, 45430, '明日が試験なのに、弟はのんきに遊んでいる。', 'あしたが しけん なのに、おとうとは のんきに あそんで いる。', 'Mai thi mà em trai tôi vẫn vô tư chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6236, 45432, '人のものを勝手に使わないで。', 'ひとの ものを かってに つかわないで。', 'Đừng tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6237, 45434, '彼女は話し方が上品だ。', 'かのじょは はなしかたが じょうひんだ。', 'Cô ấy nói năng thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6238, 45435, 'そんな下品な言葉を使わないで。', 'そんな げひんな ことばを つかわないで。', 'Đừng dùng những lời thô tục như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6239, 45437, '彼女は私より三つ年上だ。', 'かのじょは わたしより みっつ としうえだ。', 'Cô ấy hơn tôi ba tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6240, 45440, '仲間と一緒に新しい会社を作った。', 'なかまと いっしょに あたらしい かいしゃを つくった。', 'Tôi cùng các bạn lập công ty mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6241, 45441, '何があっても、私はあなたの味方だよ。', 'なにが あっても、わたしは あなたの みかた だよ。', 'Dù có chuyện gì, tôi vẫn đứng về phía bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6242, 45444, '彼は部下から信頼されている。', 'かれは ぶかから しんらい されて いる。', 'Anh ấy được cấp dưới tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6243, 45447, '私の言い方が悪くて、誤解されてしまった。', 'わたしの いいかたが わるくて、ごかい されて しまった。', 'Tôi nói chưa khéo nên bị hiểu lầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6244, 45449, 'もっと勉強すればよかったと後悔している。', 'もっと べんきょう すれば よかったと こうかい して いる。', 'Tôi hối hận vì đã không học chăm hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6245, 45452, '今の生活に満足している。', 'いまの せいかつに まんぞく して いる。', 'Tôi hài lòng với cuộc sống hiện tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6246, 45457, '子供が無事だと聞いて、ほっとした。', 'こどもが ぶじだと きいて、ほっと した。', 'Nghe tin con an toàn, tôi thở phào nhẹ nhõm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6247, 45458, '深呼吸をしたら、気持ちが落ち着いた。', 'しんこきゅうを したら、きもちが おちついた。', 'Hít thở sâu xong thì tâm trạng bình tĩnh lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6248, 46141, 'やっと借金を全部返した。', 'やっと しゃっきんを ぜんぶ かえした。', 'Cuối cùng tôi cũng trả hết nợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6249, 46216, '労働者は給料を上げるよう要求した。', 'ろうどうしゃは きゅうりょうを あげる よう ようきゅう した。', 'Công nhân đã yêu cầu tăng lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6250, 46218, '両国の外交関係が改善した。', 'りょうこくの がいこう かんけいが かいぜん した。', 'Quan hệ ngoại giao giữa hai nước đã được cải thiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6251, 46225, 'すべての人は法の前に平等だ。', 'すべての ひとは ほうの まえに びょうどうだ。', 'Mọi người đều bình đẳng trước pháp luật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6252, 45460, '彼は今でも昔の友達を恨んでいる。', 'かれは いまでも むかしの ともだちを うらんで いる。', 'Đến giờ anh ấy vẫn oán người bạn cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6253, 45461, '毎年海外旅行に行けるなんて、羨ましい。', 'まいとし かいがい りょこうに いける なんて、うらやましい。', 'Năm nào cũng được đi du lịch nước ngoài, thật đáng ghen tị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6254, 45464, 'この料理は見た目はよくないが、おいしい。', 'この りょうりは みためは よくないが、おいしい。', 'Món này trông không đẹp mắt nhưng ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6255, 45468, 'ダイエット中なのに、ついケーキを食べてしまった。', 'ダイエットちゅう なのに、つい ケーキを たべて しまった。', 'Đang ăn kiêng mà tôi lỡ ăn mất miếng bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6256, 45473, 'この工場ではいろいろな製品を作っている。', 'この こうじょうでは いろいろな せいひんを つくって いる。', 'Nhà máy này sản xuất nhiều loại sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6257, 45475, 'テレビで新商品を宣伝している。', 'テレビで しんしょうひんを せんでん して いる。', 'Sản phẩm mới đang được quảng cáo trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6258, 45479, '今月の売上は先月より多い。', 'こんげつの うりあげは せんげつより おおい。', 'Doanh thu tháng này cao hơn tháng trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6259, 45483, '給料について会社と交渉した。', 'きゅうりょうに ついて かいしゃと こうしょう した。', 'Tôi đã đàm phán lương với công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6260, 45490, '上司の指示どおりに作業を進めた。', 'じょうしの しじ どおりに さぎょうを すすめた。', 'Tôi tiến hành công việc theo chỉ thị của cấp trên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6261, 45494, '父は来年退職する予定だ。', 'ちちは らいねん たいしょく する よていだ。', 'Bố tôi dự định nghỉ hưu vào năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6262, 45496, '給与は毎月二十五日に振り込まれる。', 'きゅうよは まいつき にじゅうごにちに ふりこまれる。', 'Lương được chuyển khoản vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6263, 45498, '毎日電車で通勤しています。', 'まいにち でんしゃで つうきん して います。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6264, 45499, 'あの会社とは長い間取引がある。', 'あの かいしゃとは ながい あいだ とりひきが ある。', 'Chúng tôi giao dịch với công ty đó đã lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6265, 45502, '一年間の努力の成果が出た。', 'いちねんかんの どりょくの せいかが でた。', 'Thành quả của một năm nỗ lực đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6266, 46142, '住宅ローンの返済が終わった。', 'じゅうたく ローンの へんさいが おわった。', 'Tôi đã trả xong khoản vay mua nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6267, 46143, '銀行に預けても、利子はほとんどつかない。', 'ぎんこうに あずけても、りしは ほとんど つかない。', 'Gửi ngân hàng cũng hầu như chẳng có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6268, 46217, '日本の学生と交流するイベントに参加した。', 'にほんの がくせいと こうりゅう する イベントに さんか した。', 'Tôi tham gia sự kiện giao lưu với sinh viên Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6269, 46220, '戦争で多くの人が難民になった。', 'せんそうで おおくの ひとが なんみんに なった。', 'Chiến tranh khiến nhiều người trở thành người tị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6270, 46223, '都市と地方の格差が広がっている。', 'としと ちほうの かくさが ひろがって いる。', 'Khoảng cách giữa thành thị và nông thôn đang nới rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6271, 46227, '少数の意見も大切にするべきだ。', 'しょうすうの いけんも たいせつに する べきだ。', 'Ý kiến thiểu số cũng cần được coi trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6272, 46228, '多数の人がその案に賛成した。', 'たすうの ひとが その あんに さんせい した。', 'Đa số mọi người tán thành đề án đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6273, 46257, 'エレベーターが故障して、使えません。', 'エレベーターが こしょう して、つかえません。', 'Thang máy bị hỏng, không dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6274, 46280, '歯の治療に毎週通っている。', 'はの ちりょうに まいしゅう かよって いる。', 'Tuần nào tôi cũng đi chữa răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6275, 46282, 'どんな症状がありますか。', 'どんな しょうじょうが ありますか。', 'Bạn có triệu chứng gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6276, 46287, 'この病院は患者がとても多い。', 'この びょういんは かんじゃが とても おおい。', 'Bệnh viện này có rất nhiều bệnh nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6277, 46258, '出発前に車を点検した。', 'しゅっぱつまえに くるまを てんけん した。', 'Trước khi khởi hành tôi đã kiểm tra xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6278, 46232, 'この地域は雪が多い。', 'この ちいきは ゆきが おおい。', 'Khu vực này có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6279, 46256, 'スマホの言語を日本語に設定した。', 'スマホの げんごを にほんごに せってい した。', 'Tôi cài ngôn ngữ điện thoại sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6280, 46266, '人工知能が翻訳の仕事を手伝ってくれる。', 'じんこうちのうが ほんやくの しごとを てつだって くれる。', 'Trí tuệ nhân tạo hỗ trợ công việc dịch thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6281, 46230, '大きな組織で働くのは大変だ。', 'おおきな そしきで はたらくのは たいへんだ。', 'Làm việc trong một tổ chức lớn thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6282, 46231, '公共の交通機関を利用してください。', 'こうきょうの こうつう きかんを りよう して ください。', 'Xin hãy sử dụng phương tiện giao thông công cộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6283, 46236, 'お互いに少し妥協しよう。', 'おたがいに すこし だきょう しよう。', 'Hai bên hãy thỏa hiệp một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6284, 46238, '専門家の間でも見解が分かれている。', 'せんもんかの あいだでも けんかいが わかれて いる。', 'Ngay giữa các chuyên gia cũng có quan điểm khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6285, 46242, '法律で定められたルールを守ろう。', 'ほうりつで さだめられた ルールを まもろう。', 'Hãy tuân thủ các quy tắc do pháp luật quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6286, 46245, '公的な書類には印鑑が必要だ。', 'こうてきな しょるいには いんかんが ひつようだ。', 'Giấy tờ chính thức cần đóng dấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6287, 46247, 'その値段は妥当だと思う。', 'その ねだんは だとうだと おもう。', 'Tôi nghĩ mức giá đó là hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6288, 46249, 'この会社は優秀な技術者を募集している。', 'この かいしゃは ゆうしゅうな ぎじゅつしゃを ぼしゅう して いる。', 'Công ty này đang tuyển kỹ sư giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6289, 46252, 'このホテルは設備が整っている。', 'この ホテルは せつびが ととのって いる。', 'Khách sạn này đầy đủ trang thiết bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6290, 46255, 'この機械は操作が簡単だ。', 'この きかいは そうさが かんたんだ。', 'Máy này thao tác đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6291, 46260, 'しょうゆの原料は大豆だ。', 'しょうゆの げんりょうは だいずだ。', 'Nguyên liệu làm xì dầu là đậu nành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6292, 46262, '時計の電池が切れた。', 'とけいの でんちが きれた。', 'Pin đồng hồ đã hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6293, 46265, '情報技術の発達で働き方が変わった。', 'じょうほう ぎじゅつの はったつで はたらきかたが かわった。', 'Nhờ sự phát triển của công nghệ thông tin, cách làm việc đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6294, 46270, '実験で仮説が正しいことが証明された。', 'じっけんで かせつが ただしい ことが しょうめい された。', 'Thí nghiệm đã chứng minh giả thuyết là đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6295, 46273, 'この食品には体に悪い物質は入っていない。', 'この しょくひんには からだに わるい ぶっしつは はいって いない。', 'Thực phẩm này không chứa chất có hại cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6296, 46277, 'この地域は医療の設備が足りない。', 'この ちいきは いりょうの せつびが たりない。', 'Khu vực này thiếu cơ sở y tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6297, 46283, '手を洗って、感染を防ぎましょう。', 'てを あらって、かんせんを ふせぎましょう。', 'Hãy rửa tay để phòng lây nhiễm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6298, 46285, 'よく寝ると、免疫が強くなる。', 'よく ねると、めんえきが つよく なる。', 'Ngủ đủ giấc giúp hệ miễn dịch khỏe hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6299, 44037, 'お客様、こちらへどうぞ。', 'おきゃくさま、こちらへ どうぞ。', 'Thưa quý khách, mời đi lối này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6300, 46320, 'エジプトには古い文明があった。', 'エジプトには ふるい ぶんめいが あった。', 'Ai Cập từng có một nền văn minh cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6301, 46289, '日本人の平均寿命は世界でも長い。', 'にほんじんの へいきん じゅみょうは せかいでも ながい。', 'Tuổi thọ trung bình của người Nhật thuộc hàng cao thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6302, 46312, 'この本の作者は誰ですか。', 'この ほんの さくしゃは だれ ですか。', 'Tác giả của cuốn sách này là ai?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6303, 46313, 'この絵は有名な画家が描いたものだ。', 'この えは ゆうめいな がかが かいた ものだ。', 'Bức tranh này do một họa sĩ nổi tiếng vẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6304, 46326, 'これは小さな村の少年の物語だ。', 'これは ちいさな むらの しょうねんの ものがたりだ。', 'Đây là câu chuyện về một cậu bé ở ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6305, 46295, '新しい機械で作業の効率が上がった。', 'あたらしい きかいで さぎょうの こうりつが あがった。', 'Nhờ máy mới, hiệu suất công việc tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6306, 46337, 'テレビ局がこの店を取材に来た。', 'テレビきょくが この みせを しゅざいに きた。', 'Đài truyền hình đến phỏng vấn cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6307, 46338, '記者が大臣に質問した。', 'きしゃが だいじんに しつもん した。', 'Phóng viên đặt câu hỏi cho bộ trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6308, 46290, '適度な運動は老化を遅らせる。', 'てきどな うんどうは ろうかを おくらせる。', 'Vận động vừa phải làm chậm quá trình lão hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6309, 46293, '会社に新しいシステムを導入した。', 'かいしゃに あたらしい システムを どうにゅう した。', 'Công ty đã đưa hệ thống mới vào áp dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6310, 46297, 'これは画期的な発明だ。', 'これは かっきてきな はつめいだ。', 'Đây là một phát minh mang tính đột phá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6311, 46300, '買ってきた本棚を自分で組み立てた。', 'かって きた ほんだなを じぶんで くみたてた。', 'Tôi tự lắp ráp chiếc giá sách mới mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6312, 46303, '間違えて大事なファイルを削除してしまった。', 'まちがえて だいじな ファイルを さくじょ して しまった。', 'Tôi lỡ xóa nhầm một tệp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6313, 46306, 'この絵は有名な作品の複製だ。', 'この えは ゆうめいな さくひんの ふくせいだ。', 'Bức tranh này là bản sao của một tác phẩm nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6314, 46309, 'パリは芸術の町として知られている。', 'パリは げいじゅつの まちと して しられて いる。', 'Paris được biết đến là thành phố nghệ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6315, 46311, '将来は作家になりたい。', 'しょうらいは さっかに なりたい。', 'Sau này tôi muốn trở thành nhà văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6316, 46315, '監督の指示で選手が動いた。', 'かんとくの しじで せんしゅが うごいた。', 'Các cầu thủ di chuyển theo chỉ thị của huấn luyện viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6317, 46318, '週末、写真の展覧会に行った。', 'しゅうまつ、しゃしんの てんらんかいに いった。', 'Cuối tuần tôi đi xem triển lãm ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6318, 46322, '神社で伝統的な儀式が行われた。', 'じんじゃで でんとうてきな ぎしきが おこなわれた。', 'Một nghi lễ truyền thống đã được tổ chức ở đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6319, 46327, '彼女は毎晩、詩を書いている。', 'かのじょは まいばん、しを かいて いる。', 'Tối nào cô ấy cũng làm thơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6320, 46330, 'この小説は有名な翻訳者が訳した。', 'この しょうせつは ゆうめいな ほんやくしゃが やくした。', 'Cuốn tiểu thuyết này do một dịch giả nổi tiếng dịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6321, 46333, '番組に視聴者から多くの意見が届いた。', 'ばんぐみに しちょうしゃから おおくの いけんが とどいた。', 'Chương trình nhận được nhiều ý kiến từ khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6322, 46342, '新しい映画は批評家から高い評価を受けた。', 'あたらしい えいがは ひひょうかから たかい ひょうかを うけた。', 'Bộ phim mới được giới phê bình đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6323, 46344, 'このラーメン屋はいつも人気で、行列ができている。', 'この ラーメンやは いつも にんきで、ぎょうれつが できて いる。', 'Quán ramen này lúc nào cũng đông khách, người xếp hàng dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6324, 44118, '電話しましたが、留守でした。', 'でんわ しましたが、るす でした。', 'Tôi đã gọi điện nhưng không có ai ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6325, 46398, '仕事の付き合いで、毎週飲みに行く。', 'しごとの つきあいで、まいしゅう のみに いく。', 'Vì quan hệ công việc, tuần nào tôi cũng đi nhậu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6326, 46363, '好きな歌手に会えて感激した。', 'すきな かしゅに あえて かんげき した。', 'Được gặp ca sĩ yêu thích, tôi xúc động vô cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6327, 46391, 'ごみの処理は市がしている。', 'ごみの しょりは しが して いる。', 'Việc xử lý rác do thành phố đảm nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6328, 46347, 'この作家は自然の描写がうまい。', 'この さっかは しぜんの びょうしゃが うまい。', 'Nhà văn này miêu tả thiên nhiên rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6329, 46374, '待遇がよくないので、辞める人が多い。', 'たいぐうが よくないので、やめる ひとが おおい。', 'Đãi ngộ không tốt nên nhiều người nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6330, 46348, '子供には創造する力がある。', 'こどもには そうぞう する ちからが ある。', 'Trẻ em có khả năng sáng tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6331, 46351, '演奏が終わると、大きな拍手が起こった。', 'えんそうが おわると、おおきな はくしゅが おこった。', 'Khi màn trình diễn kết thúc, tiếng vỗ tay vang lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6332, 46356, 'その本の題名を忘れてしまった。', 'その ほんの だいめいを わすれて しまった。', 'Tôi quên mất tựa đề cuốn sách đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6333, 46358, 'この絵は春の田舎を描いている。', 'この えは はるの いなかを えがいて いる。', 'Bức tranh này vẽ cảnh làng quê mùa xuân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6334, 46360, '父の店を受け継いだ。', 'ちちの みせを うけついだ。', 'Tôi đã kế nghiệp cửa hàng của bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6335, 46362, '料理をゆっくり味わって食べた。', 'りょうりを ゆっくり あじわって たべた。', 'Tôi chậm rãi thưởng thức món ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6336, 46365, '白鳥が優雅に泳いでいる。', 'はくちょうが ゆうがに およいで いる。', 'Những chú thiên nga đang bơi một cách tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6337, 46368, '彼は難しい技を見事に成功させた。', 'かれは むずかしい わざを みごとに せいこう させた。', 'Anh ấy thực hiện thành công một kỹ thuật khó một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6338, 46370, '四月に人事の発表がある。', 'しがつに じんじの はっぴょうが ある。', 'Tháng tư sẽ có công bố nhân sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6339, 46373, 'アルバイトから正社員になった。', 'アルバイトから せいしゃいんに なった。', 'Tôi từ nhân viên làm thêm trở thành nhân viên chính thức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6340, 46376, '勤め先の住所を書いてください。', 'つとめさきの じゅうしょを かいて ください。', 'Hãy ghi địa chỉ nơi làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6341, 46379, '午後、お客様と打ち合わせがある。', 'ごご、おきゃくさまと うちあわせが ある。', 'Chiều nay tôi có buổi họp bàn với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6342, 46382, '会議の議事録を作成してください。', 'かいぎの ぎじろくを さくせい して ください。', 'Hãy lập biên bản cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6343, 46384, '会議は予定どおりに進行した。', 'かいぎは よてい どおりに しんこう した。', 'Cuộc họp diễn ra đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6344, 46388, '先輩の助言のおかげで、うまくいった。', 'せんぱいの じょげんの おかげで、うまく いった。', 'Nhờ lời khuyên của đàn anh mà mọi việc suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6345, 46392, '会社は記者会見で謝罪した。', 'かいしゃは きしゃかいけんで しゃざい した。', 'Công ty đã tạ lỗi trong buổi họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6346, 46394, '日本では礼儀を大切にする。', 'にほんでは れいぎを たいせつに する。', 'Ở Nhật, người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6347, 46396, 'チームで働くには協調性が必要だ。', 'チームで はたらくには きょうちょうせいが ひつようだ。', 'Làm việc nhóm cần tính hòa đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6348, 46399, '新入社員の歓迎会を開いた。', 'しんにゅう しゃいんの かんげいかいを ひらいた。', 'Chúng tôi tổ chức tiệc chào mừng nhân viên mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6349, 46402, '思いやりのある人になりたい。', 'おもいやりの ある ひとに なりたい。', 'Tôi muốn trở thành người biết quan tâm đến người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6350, 44216, '船で島へ行きました。', 'ふねで しまへ いきました。', 'Tôi đi ra đảo bằng thuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6351, 46431, 'この鳥は絶滅しそうになっている。', 'この とりは ぜつめつ しそうに なって いる。', 'Loài chim này đang có nguy cơ tuyệt chủng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6352, 46438, '都会は大気の汚れがひどい。', 'とかいは たいきの よごれが ひどい。', 'Ở thành phố, ô nhiễm không khí rất nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6353, 46443, '日本は国土の約七割が森林だ。', 'にほんは こくどの やく ななわりが しんりんだ。', 'Khoảng 70% diện tích Nhật Bản là rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6354, 46428, 'あいにく、部長は外出しております。', 'あいにく、ぶちょうは がいしゅつ して おります。', 'Rất tiếc, trưởng phòng đang ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6355, 46404, '率直な意見を聞かせてください。', 'そっちょくな いけんを きかせて ください。', 'Hãy cho tôi nghe ý kiến thẳng thắn của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6356, 46406, '父は几帳面で、いつも時間を守る。', 'ちちは きちょうめんで、いつも じかんを まもる。', 'Bố tôi rất tỉ mỉ, lúc nào cũng đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6357, 46409, '新人のくせに偉そうなことを言う。', 'しんじんの くせに えらそうな ことを いう。', 'Mới vào mà đã nói năng ra vẻ ta đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6358, 46411, '遅刻の言い訳はもう聞きたくない。', 'ちこくの いいわけは もう ききたく ない。', 'Tôi không muốn nghe lời bào chữa cho việc đi muộn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6359, 46415, '間違えたので、最初からやり直した。', 'まちがえたので、さいしょから やりなおした。', 'Làm sai nên tôi làm lại từ đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6360, 46417, '先輩の働き方を見習いたい。', 'せんぱいの はたらきかたを みならいたい。', 'Tôi muốn noi theo cách làm việc của đàn anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6361, 46419, '泣いている子供を優しく慰めた。', 'ないて いる こどもを やさしく なぐさめた。', 'Tôi dịu dàng dỗ dành đứa trẻ đang khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6362, 46421, '子供を甘やかしすぎるのはよくない。', 'こどもを あまやかしすぎるのは よくない。', 'Nuông chiều con quá mức là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6363, 46423, '練習を怠けると、すぐ下手になる。', 'れんしゅうを なまけると、すぐ へたに なる。', 'Lười luyện tập là sẽ kém đi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6364, 46426, '年末は慌ただしく過ぎていく。', 'ねんまつは あわただしく すぎて いく。', 'Cuối năm trôi qua thật tất bật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6365, 46427, '問題は円満に解決した。', 'もんだいは えんまんに かいけつ した。', 'Vấn đề đã được giải quyết êm đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6366, 46434, '戦争で町が破壊された。', 'せんそうで まちが はかい された。', 'Thị trấn bị chiến tranh phá hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6367, 46436, '木は二酸化炭素を吸収する。', 'きは にさんかたんそを きゅうしゅう する。', 'Cây xanh hấp thụ khí CO2.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6368, 46439, '温暖化で海面が上昇している。', 'おんだんかで かいめんが じょうしょう して いる。', 'Do trái đất nóng lên, mực nước biển đang dâng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6369, 46444, '森林の伐採が問題になっている。', 'しんりんの ばっさいが もんだいに なって いる。', 'Việc chặt phá rừng đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6370, 46446, '豪雨で川があふれた。', 'ごううで かわが あふれた。', 'Mưa lớn khiến sông tràn bờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6371, 46448, '火山が噴火して、近くの村に灰が降った。', 'かざんが ふんか して、ちかくの むらに はいが ふった。', 'Núi lửa phun trào, tro rơi xuống ngôi làng gần đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6372, 46450, '最近、世界中で異常気象が続いている。', 'さいきん、せかいじゅうで いじょう きしょうが つづいて いる。', 'Gần đây thời tiết bất thường liên tục xảy ra trên khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6373, 46455, '省エネのエアコンに買い替えた。', 'しょうエネの エアコンに かいかえた。', 'Tôi đã đổi sang điều hòa tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6374, 46457, '海の近くに風力発電所ができた。', 'うみの ちかくに ふうりょく はつでんしょが できた。', 'Một nhà máy điện gió đã được xây gần biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6375, 46459, '事故の後、放射能の検査が行われた。', 'じこの あと、ほうしゃのうの けんさが おこなわれた。', 'Sau sự cố, việc kiểm tra phóng xạ đã được tiến hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6376, 46489, '姉は金融関係の会社に勤めている。', 'あねは きんゆう かんけいの かいしゃに つとめて いる。', 'Chị tôi làm ở một công ty tài chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6377, 46463, '秋は米の収穫の季節だ。', 'あきは こめの しゅうかくの きせつだ。', 'Mùa thu là mùa thu hoạch lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6378, 46496, '彼は財産をすべて寄付した。', 'かれは ざいさんを すべて きふ した。', 'Ông ấy đã quyên góp toàn bộ tài sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6379, 46511, '地震で水の供給が止まった。', 'じしんで みずの きょうきゅうが とまった。', 'Động đất làm ngừng cung cấp nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6380, 46518, '今月は出費が多くて赤字だ。', 'こんげつは しゅっぴが おおくて あかじだ。', 'Tháng này chi tiêu nhiều nên bị thâm hụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6381, 46521, '好況で多くの会社がボーナスを増やした。', 'こうきょうで おおくの かいしゃが ボーナスを ふやした。', 'Kinh tế thịnh vượng nên nhiều công ty tăng thưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6382, 46485, 'この店はメニューが豊富だ。', 'この みせは メニューが ほうふだ。', 'Quán này có thực đơn phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6383, 46488, '空が次第に明るくなってきた。', 'そらが しだいに あかるく なって きた。', 'Bầu trời dần dần sáng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6384, 46492, 'アルバイトで毎月五万円の収入がある。', 'アルバイトで まいつき ごまんえんの しゅうにゅうが ある。', 'Tôi có thu nhập năm mươi nghìn yên mỗi tháng nhờ làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6385, 46495, '彼は親から大きな資産を受け継いだ。', 'かれは おやから おおきな しさんを うけついだ。', 'Anh ấy thừa hưởng khối tài sản lớn từ cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6386, 46502, '住宅ローンの返済が終わった。', 'じゅうたく ローンの へんさいが おわった。', 'Tôi đã trả xong khoản vay mua nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6387, 46504, '金利が上がると、ローンの返済が大変になる。', 'きんりが あがると、ローンの へんさいが たいへんに なる。', 'Lãi suất tăng thì trả nợ vay sẽ vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6388, 46507, '円安で外国からの観光客が増えた。', 'えんやすで がいこくからの かんこうきゃくが ふえた。', 'Do đồng yên mất giá, khách du lịch nước ngoài tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6389, 46514, 'この野菜には生産者の名前が書いてある。', 'この やさいには せいさんしゃの なまえが かいて ある。', 'Trên rau này có ghi tên người sản xuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6390, 46516, '弟がテレビを独占している。', 'おとうとが テレビを どくせん して いる。', 'Em trai tôi độc chiếm cái tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6391, 46520, '今年の景況は去年より厳しい。', 'ことしの けいきょうは きょねんより きびしい。', 'Tình hình kinh doanh năm nay khó khăn hơn năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6392, 46464, 'ベランダでトマトを栽培している。', 'ベランダで トマトを さいばい して いる。', 'Tôi trồng cà chua ở ban công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6393, 46467, '持続可能な社会を作ることが目標だ。', 'じぞく かのうな しゃかいを つくる ことが もくひょうだ。', 'Mục tiêu là xây dựng một xã hội bền vững.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6394, 46469, 'この会社は今、経営の危機にある。', 'この かいしゃは いま、けいえいの ききに ある。', 'Công ty này hiện đang trong khủng hoảng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6395, 46473, '庭に草が茂っている。', 'にわに くさが しげって いる。', 'Cỏ mọc um tùm trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6396, 46474, '努力がやっと実った。', 'どりょくが やっと みのった。', 'Nỗ lực cuối cùng đã đơm hoa kết trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6397, 46477, '事故防止のために、信号を新しくした。', 'じこ ぼうしの ために、しんごうを あたらしく した。', 'Để ngăn tai nạn, đèn tín hiệu đã được thay mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6398, 46480, 'この洗剤は汚れがよく落ちる。', 'この せんざいは よごれが よく おちる。', 'Loại bột giặt này tẩy vết bẩn rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6399, 46482, '大雨のあと、川の水が濁っている。', 'おおあめの あと、かわの みずが にごって いる。', 'Sau trận mưa lớn, nước sông bị đục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6400, 46484, 'どんな命も貴いものだ。', 'どんな いのちも とうとい ものだ。', 'Sinh mạng nào cũng quý giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6401, 46487, '彼の日本語は著しく上達した。', 'かれの にほんごは いちじるしく じょうたつ した。', 'Tiếng Nhật của anh ấy tiến bộ rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6402, 44224, '秋になると、木の葉が赤くなります。', 'あきに なると、きの はが あかく なります。', 'Sang thu, lá cây chuyển đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6403, 46535, '電気代の請求が来た。', 'でんきだいの せいきゅうが きた。', 'Hóa đơn tiền điện đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6404, 46576, '労働者は給料を上げるよう要求した。', 'ろうどうしゃは きゅうりょうを あげる よう ようきゅう した。', 'Công nhân đã yêu cầu tăng lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6405, 46562, '泥棒はすぐに逮捕された。', 'どろぼうは すぐに たいほ された。', 'Tên trộm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6406, 46578, '両国の外交関係が改善した。', 'りょうこくの がいこう かんけいが かいぜん した。', 'Quan hệ ngoại giao giữa hai nước đã được cải thiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6407, 46525, '地図を拡大して見た。', 'ちずを かくだい して みた。', 'Tôi phóng to bản đồ ra để xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6408, 46545, '安定した仕事に就きたい。', 'あんてい した しごとに つきたい。', 'Tôi muốn có một công việc ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6409, 46527, '気温が上昇して、夏らしくなってきた。', 'きおんが じょうしょう して、なつらしく なって きた。', 'Nhiệt độ tăng lên, đã ra dáng mùa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6410, 46530, '工事は来月終わる見込みだ。', 'こうじは らいげつ おわる みこみだ。', 'Công trình dự kiến xong vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6411, 46531, '交通費は会社が負担します。', 'こうつうひは かいしゃが ふたん します。', 'Chi phí đi lại do công ty chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6412, 46534, '事故の被害者に補償金が支払われた。', 'じこの ひがいしゃに ほしょうきんが しはらわれた。', 'Tiền bồi thường đã được trả cho nạn nhân vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6413, 46537, '閉店前に弁当が値引きされる。', 'へいてん まえに べんとうが ねびき される。', 'Trước giờ đóng cửa, cơm hộp được giảm giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6414, 46539, '今月は稼ぎが少なかった。', 'こんげつは かせぎが すくなかった。', 'Tháng này tôi kiếm được ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6415, 46541, '老後のために貯蓄をしている。', 'ろうごの ために ちょちくを して いる。', 'Tôi tiết kiệm cho tuổi già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6416, 46547, '電車が大幅に遅れている。', 'でんしゃが おおはばに おくれて いる。', 'Tàu điện đang trễ rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6417, 46548, '病気は徐々によくなっている。', 'びょうきは じょじょに よく なって いる。', 'Bệnh đang dần dần khá lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6418, 46552, 'この仕事の条件はとてもいい。', 'この しごとの じょうけんは とても いい。', 'Điều kiện của công việc này rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6419, 46554, '駐車違反で罰金を払った。', 'ちゅうしゃ いはんで ばっきんを はらった。', 'Tôi bị phạt tiền vì đỗ xe sai quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6420, 46556, '裁判の結果は来月出る。', 'さいばんの けっかは らいげつ でる。', 'Kết quả xét xử sẽ có vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6421, 46558, '弁護士に相談することにした。', 'べんごしに そうだん する ことに した。', 'Tôi quyết định hỏi ý kiến luật sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6422, 46561, '警察は容疑者を逮捕した。', 'けいさつは ようぎしゃを たいほ した。', 'Cảnh sát đã bắt giữ nghi phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6423, 46564, '自治体によってごみの出し方が違う。', 'じちたいに よって ごみの だしかたが ちがう。', 'Mỗi địa phương có cách đổ rác khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6424, 46566, '野党は政府の案に反対している。', 'やとうは せいふの あんに はんたい して いる。', 'Phe đối lập đang phản đối đề án của chính phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6425, 46567, '政府は子育てを支援する政策を発表した。', 'せいふは こそだてを しえん する せいさくを はっぴょう した。', 'Chính phủ công bố chính sách hỗ trợ nuôi dạy con cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6426, 46571, '新しい法律は来年四月から施行される。', 'あたらしい ほうりつは らいねん しがつから しこう される。', 'Luật mới sẽ được thi hành từ tháng tư năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6427, 46574, '多くの若者がその候補者を支持している。', 'おおくの わかものが その こうほしゃを しじ して いる。', 'Nhiều người trẻ ủng hộ ứng viên đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6428, 46579, 'その地域では紛争が続いている。', 'その ちいきでは ふんそうが つづいて いる。', 'Xung đột vẫn đang tiếp diễn ở khu vực đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6429, 46617, 'エレベーターが故障して、使えません。', 'エレベーターが こしょう して、つかえません。', 'Thang máy bị hỏng, không dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6430, 46585, 'すべての人は法の前に平等だ。', 'すべての ひとは ほうの まえに びょうどうだ。', 'Mọi người đều bình đẳng trước pháp luật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6431, 46592, 'この地域は雪が多い。', 'この ちいきは ゆきが おおい。', 'Khu vực này có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6432, 46611, 'この装置は地震を感じると自動で止まる。', 'この そうちは じしんを かんじると じどうで とまる。', 'Thiết bị này tự dừng khi phát hiện động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6433, 46624, '山の中は通信が不安定だ。', 'やまの なかは つうしんが ふあんていだ。', 'Trong núi sóng liên lạc không ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6434, 46632, 'これは珍しい自然現象だ。', 'これは めずらしい しぜん げんしょうだ。', 'Đây là một hiện tượng tự nhiên hiếm gặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6435, 46627, 'アンケートの結果を分析した。', 'アンケートの けっかを ぶんせき した。', 'Tôi đã phân tích kết quả khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6436, 46581, '日本は治安がいい国だと言われている。', 'にほんは ちあんが いい くにだと いわれて いる。', 'Nhật Bản được cho là đất nước có an ninh tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6437, 46583, '都市と地方の格差が広がっている。', 'としと ちほうの かくさが ひろがって いる。', 'Khoảng cách giữa thành thị và nông thôn đang nới rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6438, 46587, '少数の意見も大切にするべきだ。', 'しょうすうの いけんも たいせつに する べきだ。', 'Ý kiến thiểu số cũng cần được coi trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6439, 46591, '公共の交通機関を利用してください。', 'こうきょうの こうつう きかんを りよう して ください。', 'Xin hãy sử dụng phương tiện giao thông công cộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6440, 46596, 'お互いに少し妥協しよう。', 'おたがいに すこし だきょう しよう。', 'Hai bên hãy thỏa hiệp một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6441, 46600, '会社の方針が変わった。', 'かいしゃの ほうしんが かわった。', 'Phương châm của công ty đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6442, 46602, '法律で定められたルールを守ろう。', 'ほうりつで さだめられた ルールを まもろう。', 'Hãy tuân thủ các quy tắc do pháp luật quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6443, 46605, '公的な書類には印鑑が必要だ。', 'こうてきな しょるいには いんかんが ひつようだ。', 'Giấy tờ chính thức cần đóng dấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6444, 46607, 'その値段は妥当だと思う。', 'その ねだんは だとうだと おもう。', 'Tôi nghĩ mức giá đó là hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6445, 46609, 'この会社は優秀な技術者を募集している。', 'この かいしゃは ゆうしゅうな ぎじゅつしゃを ぼしゅう して いる。', 'Công ty này đang tuyển kỹ sư giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6446, 46612, 'このホテルは設備が整っている。', 'この ホテルは せつびが ととのって いる。', 'Khách sạn này đầy đủ trang thiết bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6447, 46615, 'この機械は操作が簡単だ。', 'この きかいは そうさが かんたんだ。', 'Máy này thao tác đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6448, 46620, 'しょうゆの原料は大豆だ。', 'しょうゆの げんりょうは だいずだ。', 'Nguyên liệu làm xì dầu là đậu nành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6449, 46622, '時計の電池が切れた。', 'とけいの でんちが きれた。', 'Pin đồng hồ đã hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6450, 46625, '情報技術の発達で働き方が変わった。', 'じょうほう ぎじゅつの はったつで はたらきかたが かわった。', 'Nhờ sự phát triển của công nghệ thông tin, cách làm việc đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6451, 46630, '実験で仮説が正しいことが証明された。', 'じっけんで かせつが ただしい ことが しょうめい された。', 'Thí nghiệm đã chứng minh giả thuyết là đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6452, 46633, 'この食品には体に悪い物質は入っていない。', 'この しょくひんには からだに わるい ぶっしつは はいって いない。', 'Thực phẩm này không chứa chất có hại cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6453, 46636, '背の高さは遺伝によるところが大きい。', 'せの たかさは いでんに よる ところが おおきい。', 'Chiều cao phần lớn là do di truyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6454, 46639, '医者にインフルエンザだと診断された。', 'いしゃに インフルエンザだと しんだん された。', 'Tôi được bác sĩ chẩn đoán là bị cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6455, 44230, '台風で電車が止まりました。', 'たいふうで でんしゃが とまりました。', 'Tàu điện ngừng chạy vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6456, 46640, '歯の治療に毎週通っている。', 'はの ちりょうに まいしゅう かよって いる。', 'Tuần nào tôi cũng đi chữa răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6457, 46642, 'どんな症状がありますか。', 'どんな しょうじょうが ありますか。', 'Bạn có triệu chứng gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6458, 46647, 'この病院は患者がとても多い。', 'この びょういんは かんじゃが とても おおい。', 'Bệnh viện này có rất nhiều bệnh nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6459, 46680, 'エジプトには古い文明があった。', 'エジプトには ふるい ぶんめいが あった。', 'Ai Cập từng có một nền văn minh cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6460, 46665, 'アプリを最新のバージョンに更新してください。', 'アプリを さいしんの バージョンに こうしん して ください。', 'Hãy cập nhật ứng dụng lên phiên bản mới nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6461, 46673, 'この絵は有名な画家が描いたものだ。', 'この えは ゆうめいな がかが かいた ものだ。', 'Bức tranh này do một họa sĩ nổi tiếng vẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6462, 46686, 'これは小さな村の少年の物語だ。', 'これは ちいさな むらの しょうねんの ものがたりだ。', 'Đây là câu chuyện về một cậu bé ở ngôi làng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6463, 46655, '新しい機械で作業の効率が上がった。', 'あたらしい きかいで さぎょうの こうりつが あがった。', 'Nhờ máy mới, hiệu suất công việc tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6464, 46697, 'テレビ局がこの店を取材に来た。', 'テレビきょくが この みせを しゅざいに きた。', 'Đài truyền hình đến phỏng vấn cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6465, 46643, '手を洗って、感染を防ぎましょう。', 'てを あらって、かんせんを ふせぎましょう。', 'Hãy rửa tay để phòng lây nhiễm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6466, 46645, 'よく寝ると、免疫が強くなる。', 'よく ねると、めんえきが つよく なる。', 'Ngủ đủ giấc giúp hệ miễn dịch khỏe hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6467, 46653, '会社に新しいシステムを導入した。', 'かいしゃに あたらしい システムを どうにゅう した。', 'Công ty đã đưa hệ thống mới vào áp dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6468, 46657, 'これは画期的な発明だ。', 'これは かっきてきな はつめいだ。', 'Đây là một phát minh mang tính đột phá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6469, 46659, '台風に備えて、窓を閉めておいた。', 'たいふうに そなえて、まどを しめて おいた。', 'Để phòng bão, tôi đã đóng cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6470, 46661, '部屋にエアコンを取り付けてもらった。', 'へやに エアコンを とりつけて もらった。', 'Tôi nhờ người lắp điều hòa cho phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6471, 46664, 'わからない言葉をネットで検索した。', 'わからない ことばを ネットで けんさく した。', 'Tôi tra từ không hiểu trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6472, 46667, 'この仕事には高度な技術が必要だ。', 'この しごとには こうどな ぎじゅつが ひつようだ。', 'Công việc này đòi hỏi kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6473, 46670, '美術館で有名な画家の作品を見た。', 'びじゅつかんで ゆうめいな がかの さくひんを みた。', 'Tôi xem tác phẩm của họa sĩ nổi tiếng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6474, 46674, '好きな俳優の映画を見に行った。', 'すきな はいゆうの えいがを みに いった。', 'Tôi đi xem phim của diễn viên mình thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6475, 46676, '彼女は初めて大きな舞台に立った。', 'かのじょは はじめて おおきな ぶたいに たった。', 'Lần đầu tiên cô ấy đứng trên sân khấu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6476, 46678, '週末、写真の展覧会に行った。', 'しゅうまつ、しゃしんの てんらんかいに いった。', 'Cuối tuần tôi đi xem triển lãm ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6477, 46684, 'この辺りから古代の遺跡が見つかった。', 'この あたりから こだいの いせきが みつかった。', 'Người ta đã tìm thấy di tích cổ đại quanh đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6478, 46687, '彼女は毎晩、詩を書いている。', 'かのじょは まいばん、しを かいて いる。', 'Tối nào cô ấy cũng làm thơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6479, 46692, 'この雑誌は若い読者に人気がある。', 'この ざっしは わかい どくしゃに にんきが ある。', 'Tạp chí này được độc giả trẻ yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6480, 46694, 'その試合はテレビで生放送された。', 'その しあいは テレビで なま ほうそう された。', 'Trận đấu đó được truyền hình trực tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6481, 44272, '恋人と一緒に旅行しました。', 'こいびとと いっしょに りょこう しました。', 'Tôi đã đi du lịch cùng người yêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6482, 46709, '子供は想像力が豊かだ。', 'こどもは そうぞうりょくが ゆたかだ。', 'Trẻ con có trí tưởng tượng phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6483, 46738, '作業が終わったら、道具を片付けてください。', 'さぎょうが おわったら、どうぐを かたづけて ください。', 'Làm xong việc thì hãy cất dọn dụng cụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6484, 46751, 'ごみの処理は市がしている。', 'ごみの しょりは しが して いる。', 'Việc xử lý rác do thành phố đảm nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6485, 46714, '映画の最後の場面で泣いてしまった。', 'えいがの さいごの ばめんで ないて しまった。', 'Tôi đã khóc ở cảnh cuối của bộ phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6486, 46701, '政府の政策は多くの人から批判された。', 'せいふの せいさくは おおくの ひとから ひはん された。', 'Chính sách của chính phủ bị nhiều người phê phán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6487, 46702, '新しい映画は批評家から高い評価を受けた。', 'あたらしい えいがは ひひょうかから たかい ひょうかを うけた。', 'Bộ phim mới được giới phê bình đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6488, 46704, 'このラーメン屋はいつも人気で、行列ができている。', 'この ラーメンやは いつも にんきで、ぎょうれつが できて いる。', 'Quán ramen này lúc nào cũng đông khách, người xếp hàng dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6489, 46708, '子供には創造する力がある。', 'こどもには そうぞう する ちからが ある。', 'Trẻ em có khả năng sáng tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6490, 46711, '演奏が終わると、大きな拍手が起こった。', 'えんそうが おわると、おおきな はくしゅが おこった。', 'Khi màn trình diễn kết thúc, tiếng vỗ tay vang lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6491, 46713, 'この物語の主人公は十歳の少女だ。', 'この ものがたりの しゅじんこうは じゅっさいの しょうじょだ。', 'Nhân vật chính của câu chuyện là một cô bé mười tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6492, 46718, 'この絵は春の田舎を描いている。', 'この えは はるの いなかを えがいて いる。', 'Bức tranh này vẽ cảnh làng quê mùa xuân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6493, 46720, '父の店を受け継いだ。', 'ちちの みせを うけついだ。', 'Tôi đã kế nghiệp cửa hàng của bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6494, 46722, '料理をゆっくり味わって食べた。', 'りょうりを ゆっくり あじわって たべた。', 'Tôi chậm rãi thưởng thức món ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6495, 46726, '彼女はいつも地味な色の服を着ている。', 'かのじょは いつも じみな いろの ふくを きて いる。', 'Cô ấy lúc nào cũng mặc đồ màu giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6496, 46729, '上役の許可がないと、決められない。', 'うわやくの きょかが ないと、きめられない。', 'Không có sự cho phép của cấp trên thì không quyết được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6497, 46730, '四月に人事の発表がある。', 'しがつに じんじの はっぴょうが ある。', 'Tháng tư sẽ có công bố nhân sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6498, 46733, 'アルバイトから正社員になった。', 'アルバイトから せいしゃいんに なった。', 'Tôi từ nhân viên làm thêm trở thành nhân viên chính thức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6499, 46736, '勤め先の住所を書いてください。', 'つとめさきの じゅうしょを かいて ください。', 'Hãy ghi địa chỉ nơi làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6500, 46739, '午後、お客様と打ち合わせがある。', 'ごご、おきゃくさまと うちあわせが ある。', 'Chiều nay tôi có buổi họp bàn với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6501, 46742, '会議の議事録を作成してください。', 'かいぎの ぎじろくを さくせい して ください。', 'Hãy lập biên bản cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6502, 46744, '会議は予定どおりに進行した。', 'かいぎは よてい どおりに しんこう した。', 'Cuộc họp diễn ra đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6503, 46748, '先輩の助言のおかげで、うまくいった。', 'せんぱいの じょげんの おかげで、うまく いった。', 'Nhờ lời khuyên của đàn anh mà mọi việc suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6504, 46752, '会社は記者会見で謝罪した。', 'かいしゃは きしゃかいけんで しゃざい した。', 'Công ty đã tạ lỗi trong buổi họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6505, 46754, '日本では礼儀を大切にする。', 'にほんでは れいぎを たいせつに する。', 'Ở Nhật, người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6506, 44421, '学校の規則を守りましょう。', 'がっこうの きそくを まもりましょう。', 'Hãy tuân thủ nội quy trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6507, 46790, '海にはたくさんの生物がすんでいる。', 'うみには たくさんの せいぶつが すんで いる。', 'Biển là nơi sinh sống của rất nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6508, 46792, 'けがをした鳥を保護した。', 'けがを した とりを ほご した。', 'Tôi đã đem con chim bị thương về chăm sóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6509, 46798, '都会は大気の汚れがひどい。', 'とかいは たいきの よごれが ひどい。', 'Ở thành phố, ô nhiễm không khí rất nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6510, 46802, '砂漠では昼と夜の気温の差が大きい。', 'さばくでは ひると よるの きおんの さが おおきい。', 'Ở sa mạc, nhiệt độ ngày và đêm chênh lệch lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6511, 46813, 'この紙は再生紙から作られている。', 'この かみは さいせいしから つくられて いる。', 'Loại giấy này được làm từ giấy tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6512, 46759, '新入社員の歓迎会を開いた。', 'しんにゅう しゃいんの かんげいかいを ひらいた。', 'Chúng tôi tổ chức tiệc chào mừng nhân viên mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6513, 46761, '彼女は周りへの気配りができる人だ。', 'かのじょは まわりへの きくばりが できる ひとだ。', 'Cô ấy là người chu đáo với mọi người xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6514, 46764, '率直な意見を聞かせてください。', 'そっちょくな いけんを きかせて ください。', 'Hãy cho tôi nghe ý kiến thẳng thắn của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6515, 46766, '父は几帳面で、いつも時間を守る。', 'ちちは きちょうめんで、いつも じかんを まもる。', 'Bố tôi rất tỉ mỉ, lúc nào cũng đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6516, 46768, '成功しても謙虚な気持ちを忘れない。', 'せいこう しても けんきょな きもちを わすれない。', 'Dù thành công cũng không quên giữ lòng khiêm tốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6517, 46771, '遅刻の言い訳はもう聞きたくない。', 'ちこくの いいわけは もう ききたく ない。', 'Tôi không muốn nghe lời bào chữa cho việc đi muộn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6518, 46775, '間違えたので、最初からやり直した。', 'まちがえたので、さいしょから やりなおした。', 'Làm sai nên tôi làm lại từ đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6519, 46777, '先輩の働き方を見習いたい。', 'せんぱいの はたらきかたを みならいたい。', 'Tôi muốn noi theo cách làm việc của đàn anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6520, 46778, '試合に負けた友達を励ました。', 'しあいに まけた ともだちを はげました。', 'Tôi động viên người bạn vừa thua trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6521, 46781, '子供を甘やかしすぎるのはよくない。', 'こどもを あまやかしすぎるのは よくない。', 'Nuông chiều con quá mức là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6522, 46783, '練習を怠けると、すぐ下手になる。', 'れんしゅうを なまけると、すぐ へたに なる。', 'Lười luyện tập là sẽ kém đi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6523, 46786, '年末は慌ただしく過ぎていく。', 'ねんまつは あわただしく すぎて いく。', 'Cuối năm trôi qua thật tất bật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6524, 46787, '問題は円満に解決した。', 'もんだいは えんまんに かいけつ した。', 'Vấn đề đã được giải quyết êm đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6525, 46794, '戦争で町が破壊された。', 'せんそうで まちが はかい された。', 'Thị trấn bị chiến tranh phá hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6526, 46796, '木は二酸化炭素を吸収する。', 'きは にさんかたんそを きゅうしゅう する。', 'Cây xanh hấp thụ khí CO2.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6527, 46799, '温暖化で海面が上昇している。', 'おんだんかで かいめんが じょうしょう して いる。', 'Do trái đất nóng lên, mực nước biển đang dâng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6528, 46804, '森林の伐採が問題になっている。', 'しんりんの ばっさいが もんだいに なって いる。', 'Việc chặt phá rừng đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6529, 46806, '豪雨で川があふれた。', 'ごううで かわが あふれた。', 'Mưa lớn khiến sông tràn bờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6530, 46808, '火山が噴火して、近くの村に灰が降った。', 'かざんが ふんか して、ちかくの むらに はいが ふった。', 'Núi lửa phun trào, tro rơi xuống ngôi làng gần đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6531, 46811, '資源ごみは水曜日に出してください。', 'しげん ごみは すいようびに だして ください。', 'Rác tái chế hãy đổ vào thứ tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6532, 44581, '道に大きい石が落ちています。', 'みちに おおきい いしが おちて います。', 'Trên đường có hòn đá to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6533, 46849, '姉は金融関係の会社に勤めている。', 'あねは きんゆう かんけいの かいしゃに つとめて いる。', 'Chị tôi làm ở một công ty tài chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6534, 46823, '秋は米の収穫の季節だ。', 'あきは こめの しゅうかくの きせつだ。', 'Mùa thu là mùa thu hoạch lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6535, 46856, '彼は財産をすべて寄付した。', 'かれは ざいさんを すべて きふ した。', 'Ông ấy đã quyên góp toàn bộ tài sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6536, 46870, '冬は暖房器具の需要が高まる。', 'ふゆは だんぼうきぐの じゅようが たかまる。', 'Mùa đông nhu cầu thiết bị sưởi tăng cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6537, 46872, '夏は電気の消費が増える。', 'なつは でんきの しょうひが ふえる。', 'Mùa hè lượng điện tiêu thụ tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6538, 46832, '水をやらなかったので、花が枯れてしまった。', 'みずを やらなかったので、はなが かれて しまった。', 'Không tưới nước nên hoa đã héo mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6539, 46848, '空が次第に明るくなってきた。', 'そらが しだいに あかるく なって きた。', 'Bầu trời dần dần sáng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6540, 46852, 'アルバイトで毎月五万円の収入がある。', 'アルバイトで まいつき ごまんえんの しゅうにゅうが ある。', 'Tôi có thu nhập năm mươi nghìn yên mỗi tháng nhờ làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6541, 46855, '彼は親から大きな資産を受け継いだ。', 'かれは おやから おおきな しさんを うけついだ。', 'Anh ấy thừa hưởng khối tài sản lớn từ cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6542, 46862, '住宅ローンの返済が終わった。', 'じゅうたく ローンの へんさいが おわった。', 'Tôi đã trả xong khoản vay mua nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6543, 46864, '金利が上がると、ローンの返済が大変になる。', 'きんりが あがると、ローンの へんさいが たいへんに なる。', 'Lãi suất tăng thì trả nợ vay sẽ vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6544, 46867, '円安で外国からの観光客が増えた。', 'えんやすで がいこくからの かんこうきゃくが ふえた。', 'Do đồng yên mất giá, khách du lịch nước ngoài tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6545, 46869, 'この会社は海外の市場に進出した。', 'この かいしゃは かいがいの しじょうに しんしゅつ した。', 'Công ty này đã tiến vào thị trường nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6546, 46816, '家の屋根に太陽光パネルをつけた。', 'いえの やねに たいようこう パネルを つけた。', 'Tôi lắp tấm pin mặt trời trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6547, 46818, '原子力発電について議論が続いている。', 'げんしりょく はつでんに ついて ぎろんが つづいて いる。', 'Tranh luận về điện hạt nhân vẫn tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6548, 46822, 'この町は昔から漁業が盛んだ。', 'この まちは むかしから ぎょぎょうが さかんだ。', 'Thị trấn này từ xưa đã phát triển nghề cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6549, 46825, '小学校でうさぎを飼育している。', 'しょうがっこうで うさぎを しいく して いる。', 'Trường tiểu học có nuôi thỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6550, 46827, '持続可能な社会を作ることが目標だ。', 'じぞく かのうな しゃかいを つくる ことが もくひょうだ。', 'Mục tiêu là xây dựng một xã hội bền vững.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6551, 46829, 'この会社は今、経営の危機にある。', 'この かいしゃは いま、けいえいの ききに ある。', 'Công ty này hiện đang trong khủng hoảng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6552, 46833, '庭に草が茂っている。', 'にわに くさが しげって いる。', 'Cỏ mọc um tùm trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6553, 46835, '冬に備えて食料を蓄えた。', 'ふゆに そなえて しょくりょうを たくわえた。', 'Chúng tôi dự trữ lương thực cho mùa đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6554, 46839, '怒りを抑えて、冷静に話した。', 'いかりを おさえて、れいせいに はなした。', 'Tôi kìm cơn giận và nói chuyện bình tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6555, 46840, 'この洗剤は汚れがよく落ちる。', 'この せんざいは よごれが よく おちる。', 'Loại bột giặt này tẩy vết bẩn rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6556, 46843, '話が尽きなくて、朝まで話した。', 'はなしが つきなくて、あさまで はなした。', 'Chuyện không dứt nên chúng tôi nói đến sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6557, 46846, '人手不足が深刻化している。', 'ひとで ぶそくが しんこくか して いる。', 'Tình trạng thiếu nhân lực đang trở nên nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6558, 44584, '秋になると、木の葉が赤くなります。', 'あきに なると、きの はが あかく なります。', 'Sang thu, lá cây chuyển đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6559, 46879, '会社は三年ぶりに黒字になった。', 'かいしゃは さんねんぶりに くろじに なった。', 'Sau ba năm, công ty đã có lãi trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6560, 46882, '不況で仕事を探すのが難しい。', 'ふきょうで しごとを さがすのが むずかしい。', 'Kinh tế suy thoái nên tìm việc rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6561, 46902, '交通費は会社から支給されます。', 'こうつうひは かいしゃから しきゅう されます。', 'Tiền đi lại do công ty chi trả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6562, 46922, '泥棒はすぐに逮捕された。', 'どろぼうは すぐに たいほ された。', 'Tên trộm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6563, 46885, '地図を拡大して見た。', 'ちずを かくだい して みた。', 'Tôi phóng to bản đồ ra để xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6564, 46905, '安定した仕事に就きたい。', 'あんてい した しごとに つきたい。', 'Tôi muốn có một công việc ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6565, 46875, 'この業界は競争が激しい。', 'この ぎょうかいは きょうそうが はげしい。', 'Ngành này cạnh tranh gay gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6566, 46877, '不況で多くの会社が倒産した。', 'ふきょうで おおくの かいしゃが とうさん した。', 'Do suy thoái, nhiều công ty đã phá sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6567, 46887, '気温が上昇して、夏らしくなってきた。', 'きおんが じょうしょう して、なつらしく なって きた。', 'Nhiệt độ tăng lên, đã ra dáng mùa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6568, 46888, '株価が大きく下落した。', 'かぶかが おおきく げらく した。', 'Giá cổ phiếu sụt giảm mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6569, 46890, '工事は来月終わる見込みだ。', 'こうじは らいげつ おわる みこみだ。', 'Công trình dự kiến xong vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6570, 46892, 'その会社は多額の負債を抱えている。', 'その かいしゃは たがくの ふさいを かかえて いる。', 'Công ty đó đang gánh khoản nợ lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6571, 46896, '引っ越しの見積もりを三社に頼んだ。', 'ひっこしの みつもりを さんしゃに たのんだ。', 'Tôi nhờ ba công ty báo giá chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6572, 46898, '夜にATMを使うと手数料がかかる。', 'よるに エーティーエムを つかうと てすうりょうが かかる。', 'Dùng ATM vào ban đêm sẽ mất phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6573, 46900, 'この商売は儲けが少ない。', 'この しょうばいは もうけが すくない。', 'Việc buôn bán này lời ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6574, 46903, '彼はこの仕事の経験が乏しい。', 'かれは この しごとの けいけんが とぼしい。', 'Anh ấy còn ít kinh nghiệm trong công việc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6575, 46907, '電車が大幅に遅れている。', 'でんしゃが おおはばに おくれて いる。', 'Tàu điện đang trễ rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6576, 46911, '二つの国は平和条約を結んだ。', 'ふたつの くには へいわ じょうやくを むすんだ。', 'Hai nước đã ký hiệp ước hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6577, 46913, '政府は輸入を規制している。', 'せいふは ゆにゅうを きせい して いる。', 'Chính phủ đang hạn chế nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6578, 46915, 'スピード違反で罰金を取られた。', 'スピード いはんで ばっきんを とられた。', 'Tôi bị phạt tiền vì chạy quá tốc độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6579, 46917, '裁判所は無罪の判決を下した。', 'さいばんしょは むざいの はんけつを くだした。', 'Tòa án đã tuyên án vô tội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6580, 46919, '犯人だという証拠がない。', 'はんにん だと いう しょうこが ない。', 'Không có bằng chứng cho thấy đó là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6581, 46921, '警察は容疑者を逮捕した。', 'けいさつは ようぎしゃを たいほ した。', 'Cảnh sát đã bắt giữ nghi phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6582, 46925, '与党は選挙で過半数を取った。', 'よとうは せんきょで かはんすうを とった。', 'Đảng cầm quyền đã giành quá bán trong cuộc bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6583, 46930, '来月から新しい制度を実施する。', 'らいげつから あたらしい せいどを じっし する。', 'Từ tháng sau sẽ thực thi chế độ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6584, 46929, '法律が改正されて、成人の年齢が十八歳になった。', 'ほうりつが かいせい されて、せいじんの ねんれいが じゅうはっさいに なった。', 'Luật được sửa đổi, tuổi thành niên trở thành 18.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6585, 28596, '地震のときは、外へ逃げないでください。', 'じしんの ときは、そとへ にげないで ください。', 'Khi động đất, đừng chạy ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6586, 46977, 'エレベーターが故障して、使えません。', 'エレベーターが こしょう して、つかえません。', 'Thang máy bị hỏng, không dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6587, 46978, '出発前に車を点検した。', 'しゅっぱつまえに くるまを てんけん した。', 'Trước khi khởi hành tôi đã kiểm tra xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6588, 46938, '両国の外交関係が改善した。', 'りょうこくの がいこう かんけいが かいぜん した。', 'Quan hệ ngoại giao giữa hai nước đã được cải thiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6589, 46952, 'この地域は雪が多い。', 'この ちいきは ゆきが おおい。', 'Khu vực này có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6590, 46976, 'スマホの言語を日本語に設定した。', 'スマホの げんごを にほんごに せってい した。', 'Tôi cài ngôn ngữ điện thoại sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6591, 46986, '人工知能が翻訳の仕事を手伝ってくれる。', 'じんこうちのうが ほんやくの しごとを てつだって くれる。', 'Trí tuệ nhân tạo hỗ trợ công việc dịch thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6592, 46950, '大きな組織で働くのは大変だ。', 'おおきな そしきで はたらくのは たいへんだ。', 'Làm việc trong một tổ chức lớn thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6593, 46932, 'この路線のバスは来月で廃止される。', 'この ろせんの バスは らいげつで はいし される。', 'Tuyến xe buýt này sẽ bị bãi bỏ từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6594, 46935, '住民は工場の建設に抗議した。', 'じゅうみんは こうじょうの けんせつに こうぎ した。', 'Người dân phản đối việc xây dựng nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6595, 46939, 'その地域では紛争が続いている。', 'その ちいきでは ふんそうが つづいて いる。', 'Xung đột vẫn đang tiếp diễn ở khu vực đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6596, 46947, '少数の意見も大切にするべきだ。', 'しょうすうの いけんも たいせつに する べきだ。', 'Ý kiến thiểu số cũng cần được coi trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6597, 46951, '公共の交通機関を利用してください。', 'こうきょうの こうつう きかんを りよう して ください。', 'Xin hãy sử dụng phương tiện giao thông công cộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6598, 46956, 'お互いに少し妥協しよう。', 'おたがいに すこし だきょう しよう。', 'Hai bên hãy thỏa hiệp một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6599, 46960, '会社の方針が変わった。', 'かいしゃの ほうしんが かわった。', 'Phương châm của công ty đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6600, 46962, '法律で定められたルールを守ろう。', 'ほうりつで さだめられた ルールを まもろう。', 'Hãy tuân thủ các quy tắc do pháp luật quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6601, 46965, '公的な書類には印鑑が必要だ。', 'こうてきな しょるいには いんかんが ひつようだ。', 'Giấy tờ chính thức cần đóng dấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6602, 46967, 'その値段は妥当だと思う。', 'その ねだんは だとうだと おもう。', 'Tôi nghĩ mức giá đó là hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6603, 46969, 'この会社は優秀な技術者を募集している。', 'この かいしゃは ゆうしゅうな ぎじゅつしゃを ぼしゅう して いる。', 'Công ty này đang tuyển kỹ sư giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6604, 46972, 'このホテルは設備が整っている。', 'この ホテルは せつびが ととのって いる。', 'Khách sạn này đầy đủ trang thiết bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6605, 46975, 'この機械は操作が簡単だ。', 'この きかいは そうさが かんたんだ。', 'Máy này thao tác đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6606, 46980, 'しょうゆの原料は大豆だ。', 'しょうゆの げんりょうは だいずだ。', 'Nguyên liệu làm xì dầu là đậu nành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6607, 46982, '時計の電池が切れた。', 'とけいの でんちが きれた。', 'Pin đồng hồ đã hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6608, 46985, '情報技術の発達で働き方が変わった。', 'じょうほう ぎじゅつの はったつで はたらきかたが かわった。', 'Nhờ sự phát triển của công nghệ thông tin, cách làm việc đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6609, 46989, '今夜は流れ星の観測に最適だ。', 'こんやは ながれぼしの かんそくに さいてきだ。', 'Đêm nay rất lý tưởng để quan sát sao băng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6610, 46993, 'この食品には体に悪い物質は入っていない。', 'この しょくひんには からだに わるい ぶっしつは はいって いない。', 'Thực phẩm này không chứa chất có hại cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6611, 44757, 'お客様、こちらへどうぞ。', 'おきゃくさま、こちらへ どうぞ。', 'Thưa quý khách, mời đi lối này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6612, 47000, '歯の治療に毎週通っている。', 'はの ちりょうに まいしゅう かよって いる。', 'Tuần nào tôi cũng đi chữa răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6613, 47002, 'どんな症状がありますか。', 'どんな しょうじょうが ありますか。', 'Bạn có triệu chứng gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6614, 47006, 'この薬は眠くなる副作用がある。', 'この くすりは ねむく なる ふくさようが ある。', 'Thuốc này có tác dụng phụ gây buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6615, 47040, 'エジプトには古い文明があった。', 'エジプトには ふるい ぶんめいが あった。', 'Ai Cập từng có một nền văn minh cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6616, 47022, 'ファイルを保存してから閉じてください。', 'ファイルを ほぞん してから とじて ください。', 'Hãy lưu tệp trước khi đóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6617, 47032, 'この本の作者は誰ですか。', 'この ほんの さくしゃは だれ ですか。', 'Tác giả của cuốn sách này là ai?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6618, 47039, 'この祭りには三百年の伝統がある。', 'この まつりには さんびゃくねんの でんとうが ある。', 'Lễ hội này có truyền thống ba trăm năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6619, 47051, '著者のサイン会に行った。', 'ちょしゃの サインかいに いった。', 'Tôi đi dự buổi ký tặng của tác giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6620, 47049, '彼女の初めての本が出版された。', 'かのじょの はじめての ほんが しゅっぱん された。', 'Cuốn sách đầu tay của cô ấy đã được xuất bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6621, 46997, 'この地域は医療の設備が足りない。', 'この ちいきは いりょうの せつびが たりない。', 'Khu vực này thiếu cơ sở y tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6622, 47003, '手を洗って、感染を防ぎましょう。', 'てを あらって、かんせんを ふせぎましょう。', 'Hãy rửa tay để phòng lây nhiễm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6623, 47010, '適度な運動は老化を遅らせる。', 'てきどな うんどうは ろうかを おくらせる。', 'Vận động vừa phải làm chậm quá trình lão hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6624, 47016, '病院で精密な検査を受けた。', 'びょういんで せいみつな けんさを うけた。', 'Tôi đã được kiểm tra kỹ lưỡng ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6625, 47018, 'この研究所は先端の技術を研究している。', 'この けんきゅうじょは せんたんの ぎじゅつを けんきゅう して いる。', 'Viện này nghiên cứu công nghệ tiên tiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6626, 47020, '買ってきた本棚を自分で組み立てた。', 'かって きた ほんだなを じぶんで くみたてた。', 'Tôi tự lắp ráp chiếc giá sách mới mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6627, 47024, 'わからない言葉をネットで検索した。', 'わからない ことばを ネットで けんさく した。', 'Tôi tra từ không hiểu trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6628, 47027, 'この仕事には高度な技術が必要だ。', 'この しごとには こうどな ぎじゅつが ひつようだ。', 'Công việc này đòi hỏi kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6629, 47029, 'パリは芸術の町として知られている。', 'パリは げいじゅつの まちと して しられて いる。', 'Paris được biết đến là thành phố nghệ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6630, 47031, '将来は作家になりたい。', 'しょうらいは さっかに なりたい。', 'Sau này tôi muốn trở thành nhà văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6631, 47036, '彼女は初めて大きな舞台に立った。', 'かのじょは はじめて おおきな ぶたいに たった。', 'Lần đầu tiên cô ấy đứng trên sân khấu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6632, 47038, '週末、写真の展覧会に行った。', 'しゅうまつ、しゃしんの てんらんかいに いった。', 'Cuối tuần tôi đi xem triển lãm ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6633, 47042, '神社で伝統的な儀式が行われた。', 'じんじゃで でんとうてきな ぎしきが おこなわれた。', 'Một nghi lễ truyền thống đã được tổ chức ở đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6634, 47047, '彼女は毎晩、詩を書いている。', 'かのじょは まいばん、しを かいて いる。', 'Tối nào cô ấy cũng làm thơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6635, 47050, 'この小説は有名な翻訳者が訳した。', 'この しょうせつは ゆうめいな ほんやくしゃが やくした。', 'Cuốn tiểu thuyết này do một dịch giả nổi tiếng dịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6636, 47053, '番組に視聴者から多くの意見が届いた。', 'ばんぐみに しちょうしゃから おおくの いけんが とどいた。', 'Chương trình nhận được nhiều ý kiến từ khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6637, 47069, '子供は想像力が豊かだ。', 'こどもは そうぞうりょくが ゆたかだ。', 'Trẻ con có trí tưởng tượng phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6638, 47107, '先生の指導のおかげで、論文が書けた。', 'せんせいの しどうの おかげで、ろんぶんが かけた。', 'Nhờ sự hướng dẫn của thầy mà tôi viết được luận văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6639, 47111, 'ごみの処理は市がしている。', 'ごみの しょりは しが して いる。', 'Việc xử lý rác do thành phố đảm nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6640, 47074, '映画の最後の場面で泣いてしまった。', 'えいがの さいごの ばめんで ないて しまった。', 'Tôi đã khóc ở cảnh cuối của bộ phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6641, 47056, '新聞に求人の広告を出した。', 'しんぶんに きゅうじんの こうこくを だした。', 'Chúng tôi đăng quảng cáo tuyển dụng trên báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6642, 47058, '記者が大臣に質問した。', 'きしゃが だいじんに しつもん した。', 'Phóng viên đặt câu hỏi cho bộ trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6643, 47061, '政府の政策は多くの人から批判された。', 'せいふの せいさくは おおくの ひとから ひはん された。', 'Chính sách của chính phủ bị nhiều người phê phán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6644, 47062, '新しい映画は批評家から高い評価を受けた。', 'あたらしい えいがは ひひょうかから たかい ひょうかを うけた。', 'Bộ phim mới được giới phê bình đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6645, 47066, '気持ちを言葉で表現するのは難しい。', 'きもちを ことばで ひょうげん するのは むずかしい。', 'Diễn đạt cảm xúc bằng lời thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6646, 47070, '趣味は映画鑑賞です。', 'しゅみは えいが かんしょう です。', 'Sở thích của tôi là thưởng thức phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6647, 47072, 'スタジアムは観客でいっぱいだった。', 'スタジアムは かんきゃくで いっぱい だった。', 'Sân vận động chật kín khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6648, 47076, 'その本の題名を忘れてしまった。', 'その ほんの だいめいを わすれて しまった。', 'Tôi quên mất tựa đề cuốn sách đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6649, 47078, 'この絵は春の田舎を描いている。', 'この えは はるの いなかを えがいて いる。', 'Bức tranh này vẽ cảnh làng quê mùa xuân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6650, 47080, '父の店を受け継いだ。', 'ちちの みせを うけついだ。', 'Tôi đã kế nghiệp cửa hàng của bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6651, 47082, '料理をゆっくり味わって食べた。', 'りょうりを ゆっくり あじわって たべた。', 'Tôi chậm rãi thưởng thức món ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6652, 47087, '葬式に派手な服は着ないほうがいい。', 'そうしきに はでな ふくは きない ほうが いい。', 'Không nên mặc đồ sặc sỡ đến đám tang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6653, 47089, '上役の許可がないと、決められない。', 'うわやくの きょかが ないと、きめられない。', 'Không có sự cho phép của cấp trên thì không quyết được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6654, 47091, '来月から大阪の支店に異動になった。', 'らいげつから おおさかの してんに いどうに なった。', 'Từ tháng sau tôi được điều sang chi nhánh Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6655, 47095, '会社を選ぶとき、福利厚生も大切だ。', 'かいしゃを えらぶ とき、ふくり こうせいも たいせつだ。', 'Khi chọn công ty, chế độ phúc lợi cũng quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6656, 47097, '今日の業務は五時に終わった。', 'きょうの ぎょうむは ごじに おわった。', 'Công việc hôm nay kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6657, 47101, '今日の会議の議題は来年の予算です。', 'きょうの かいぎの ぎだいは らいねんの よさん です。', 'Chủ đề cuộc họp hôm nay là ngân sách năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6658, 47103, '新商品の企画が通った。', 'しんしょうひんの きかくが とおった。', 'Kế hoạch sản phẩm mới đã được duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6659, 47105, '彼は営業で大きな実績を上げた。', 'かれは えいぎょうで おおきな じっせきを あげた。', 'Anh ấy đạt thành tích lớn trong kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6660, 47109, '隣の人から騒音の苦情が来た。', 'となりの ひとから そうおんの くじょうが きた。', 'Hàng xóm đã phàn nàn về tiếng ồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6661, 47113, '一度失った信用を取り戻すのは難しい。', 'いちど うしなった しんようを とりもどすのは むずかしい。', 'Lấy lại lòng tin một khi đã mất là rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6662, 28861, '先生に作文を褒められました。', 'せんせいに さくぶんを ほめられました。', 'Tôi được thầy khen bài văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6663, 47150, '海にはたくさんの生物がすんでいる。', 'うみには たくさんの せいぶつが すんで いる。', 'Biển là nơi sinh sống của rất nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6664, 47152, 'けがをした鳥を保護した。', 'けがを した とりを ほご した。', 'Tôi đã đem con chim bị thương về chăm sóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6665, 47158, '都会は大気の汚れがひどい。', 'とかいは たいきの よごれが ひどい。', 'Ở thành phố, ô nhiễm không khí rất nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6666, 47162, '砂漠では昼と夜の気温の差が大きい。', 'さばくでは ひると よるの きおんの さが おおきい。', 'Ở sa mạc, nhiệt độ ngày và đêm chênh lệch lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6667, 47114, '日本では礼儀を大切にする。', 'にほんでは れいぎを たいせつに する。', 'Ở Nhật, người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6668, 47117, '職場の人間関係に悩んでいる。', 'しょくばの にんげん かんけいに なやんで いる。', 'Tôi đang khổ tâm vì các mối quan hệ ở chỗ làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6669, 47120, '帰国する友達の送別会をした。', 'きこく する ともだちの そうべつかいを した。', 'Chúng tôi làm tiệc chia tay người bạn về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6670, 47122, '思いやりのある人になりたい。', 'おもいやりの ある ひとに なりたい。', 'Tôi muốn trở thành người biết quan tâm đến người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6671, 47125, '彼は誠実な人だから信頼できる。', 'かれは せいじつな ひと だから しんらい できる。', 'Anh ấy là người thành thật nên có thể tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6672, 47127, '祖父は頑固で、人の話を聞かない。', 'そふは がんこで、ひとの はなしを きかない。', 'Ông tôi bướng bỉnh, không chịu nghe ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6673, 47129, '新人のくせに偉そうなことを言う。', 'しんじんの くせに えらそうな ことを いう。', 'Mới vào mà đã nói năng ra vẻ ta đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6674, 47132, '先輩に怒られても、言い返せなかった。', 'せんぱいに おこられても、いいかえせなかった。', 'Bị đàn anh mắng, tôi không cãi lại được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6675, 47135, '間違えたので、最初からやり直した。', 'まちがえたので、さいしょから やりなおした。', 'Làm sai nên tôi làm lại từ đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6676, 47137, '先輩の働き方を見習いたい。', 'せんぱいの はたらきかたを みならいたい。', 'Tôi muốn noi theo cách làm việc của đàn anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6677, 47139, '泣いている子供を優しく慰めた。', 'ないて いる こどもを やさしく なぐさめた。', 'Tôi dịu dàng dỗ dành đứa trẻ đang khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6678, 47141, '子供を甘やかしすぎるのはよくない。', 'こどもを あまやかしすぎるのは よくない。', 'Nuông chiều con quá mức là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6679, 47144, '一日中歩いて、くたびれた。', 'いちにちじゅう あるいて、くたびれた。', 'Đi bộ cả ngày nên mệt lả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6680, 47146, '年末は慌ただしく過ぎていく。', 'ねんまつは あわただしく すぎて いく。', 'Cuối năm trôi qua thật tất bật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6681, 47149, '外来種が生態系を壊している。', 'がいらいしゅが せいたいけいを こわして いる。', 'Các loài ngoại lai đang phá vỡ hệ sinh thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6682, 47155, '工場から排出されるガスを減らす必要がある。', 'こうじょうから はいしゅつ される ガスを へらす ひつようが ある。', 'Cần giảm lượng khí thải ra từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6683, 47159, '温暖化で海面が上昇している。', 'おんだんかで かいめんが じょうしょう して いる。', 'Do trái đất nóng lên, mực nước biển đang dâng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6684, 47161, 'この地域は土壌が豊かで、作物がよく育つ。', 'この ちいきは どじょうが ゆたかで、さくもつが よく そだつ。', 'Vùng này đất đai màu mỡ nên hoa màu phát triển tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6685, 47165, '干ばつで米が育たなかった。', 'かんばつで こめが そだたなかった。', 'Do hạn hán, lúa không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6686, 47168, '火山が噴火して、近くの村に灰が降った。', 'かざんが ふんか して、ちかくの むらに はいが ふった。', 'Núi lửa phun trào, tro rơi xuống ngôi làng gần đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6687, 47171, '資源ごみは水曜日に出してください。', 'しげん ごみは すいようびに だして ください。', 'Rác tái chế hãy đổ vào thứ tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6688, 44941, '道に大きい石が落ちています。', 'みちに おおきい いしが おちて います。', 'Trên đường có hòn đá to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6689, 47213, 'その主張には科学的な根拠がない。', 'その しゅちょうには かがくてきな こんきょが ない。', 'Lập luận đó không có căn cứ khoa học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6690, 47215, '彼の説明には矛盾がある。', 'かれの せつめいには むじゅんが ある。', 'Lời giải thích của anh ta có mâu thuẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6691, 47217, 'データから一つの結論を推論した。', 'データから ひとつの けつろんを すいろん した。', 'Từ dữ liệu, chúng tôi suy luận ra một kết luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6692, 47221, '二人の間には見解の相違がある。', 'ふたりの あいだには けんかいの そういが ある。', 'Giữa hai người có sự khác biệt về quan điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6693, 47222, '彼の意見にも一理ある。', 'かれの いけんにも いちり ある。', 'Ý kiến của anh ấy cũng có lý phần nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6694, 47225, 'これは私の主観ですが、彼は信頼できます。', 'これは わたしの しゅかん ですが、かれは しんらい できます。', 'Đây là cảm nhận chủ quan của tôi, nhưng anh ấy đáng tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6695, 47227, '計画をもっと具体化してください。', 'けいかくを もっと ぐたいか して ください。', 'Hãy cụ thể hóa kế hoạch hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6696, 47190, '医者からたばこをやめるよう警告された。', 'いしゃから たばこを やめる よう けいこく された。', 'Tôi bị bác sĩ cảnh cáo phải bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6697, 47192, '水をやらなかったので、花が枯れてしまった。', 'みずを やらなかったので、はなが かれて しまった。', 'Không tưới nước nên hoa đã héo mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6698, 47198, '会社は経費を削減することにした。', 'かいしゃは けいひを さくげん する ことに した。', 'Công ty quyết định cắt giảm chi phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6699, 47210, '環境の観点から、この計画には問題がある。', 'かんきょうの かんてんから、この けいかくには もんだいが ある。', 'Xét từ quan điểm môi trường, kế hoạch này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6700, 47172, '工場の廃棄物を正しく処理する。', 'こうじょうの はいきぶつを ただしく しょり する。', 'Xử lý đúng cách chất thải của nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6701, 47176, '家の屋根に太陽光パネルをつけた。', 'いえの やねに たいようこう パネルを つけた。', 'Tôi lắp tấm pin mặt trời trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6702, 47179, '事故の後、放射能の検査が行われた。', 'じこの あと、ほうしゃのうの けんさが おこなわれた。', 'Sau sự cố, việc kiểm tra phóng xạ đã được tiến hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6703, 47182, 'この町は昔から漁業が盛んだ。', 'この まちは むかしから ぎょぎょうが さかんだ。', 'Thị trấn này từ xưa đã phát triển nghề cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6704, 47185, '小学校でうさぎを飼育している。', 'しょうがっこうで うさぎを しいく して いる。', 'Trường tiểu học có nuôi thỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6705, 47187, '持続可能な社会を作ることが目標だ。', 'じぞく かのうな しゃかいを つくる ことが もくひょうだ。', 'Mục tiêu là xây dựng một xã hội bền vững.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6706, 47189, 'この会社は今、経営の危機にある。', 'この かいしゃは いま、けいえいの ききに ある。', 'Công ty này hiện đang trong khủng hoảng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6707, 47193, '庭に草が茂っている。', 'にわに くさが しげって いる。', 'Cỏ mọc um tùm trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6708, 47196, '夜更かしは健康に悪い影響を及ぼす。', 'よふかしは けんこうに わるい えいきょうを およぼす。', 'Thức khuya gây ảnh hưởng xấu đến sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6709, 47199, '怒りを抑えて、冷静に話した。', 'いかりを おさえて、れいせいに はなした。', 'Tôi kìm cơn giận và nói chuyện bình tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6710, 47201, '山の空気は澄んでいる。', 'やまの くうきは すんで いる。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6711, 47203, '話が尽きなくて、朝まで話した。', 'はなしが つきなくて、あさまで はなした。', 'Chuyện không dứt nên chúng tôi nói đến sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6712, 47207, '彼の日本語は著しく上達した。', 'かれの にほんごは いちじるしく じょうたつ した。', 'Tiếng Nhật của anh ấy tiến bộ rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6713, 47232, 'これは環境保護活動の一環です。', 'これは かんきょう ほご かつどうの いっかん です。', 'Đây là một phần của hoạt động bảo vệ môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6714, 47236, '彼は経済について高い見識を持っている。', 'かれは けいざいに ついて たかい けんしきを もって いる。', 'Ông ấy có hiểu biết sâu sắc về kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6715, 47238, '彼の話には誇張が多い。', 'かれの はなしには こちょうが おおい。', 'Câu chuyện của anh ta có nhiều phóng đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6716, 47244, 'あえて難しい道を選んだ。', 'あえて むずかしい みちを えらんだ。', 'Tôi cố tình chọn con đường khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6717, 47245, '彼は天才というより、むしろ努力家だ。', 'かれは てんさいと いうより、むしろ どりょくかだ。', 'Anh ấy không hẳn là thiên tài mà đúng hơn là người chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6718, 47249, '彼は家庭を顧みずに働き続けた。', 'かれは かていを かえりみずに はたらき つづけた。', 'Anh ấy làm việc liên tục mà chẳng đoái hoài đến gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6719, 47251, '前回の反省を踏まえて、計画を立てた。', 'ぜんかいの はんせいを ふまえて、けいかくを たてた。', 'Chúng tôi lập kế hoạch dựa trên bài học lần trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6720, 47253, '大事な点を見落としていた。', 'だいじな てんを みおとして いた。', 'Tôi đã bỏ sót một điểm quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6721, 47256, '新しい発見が従来の定説を覆した。', 'あたらしい はっけんが じゅうらいの ていせつを くつがえした。', 'Phát hiện mới đã lật đổ học thuyết vốn có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6722, 47258, '自分の行動を省みて、反省した。', 'じぶんの こうどうを かえりみて、はんせい した。', 'Tôi tự xét lại hành động của mình và kiểm điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6723, 47241, '彼女は質問に肯定も否定もしなかった。', 'かのじょは しつもんに こうていも ひていも しなかった。', 'Cô ấy không khẳng định cũng không phủ nhận câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6724, 47233, '子供の発想はおもしろい。', 'こどもの はっそうは おもしろい。', 'Cách nghĩ của trẻ con rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6725, 47271, '新しい販売戦略を考えた。', 'あたらしい はんばい せんりゃくを かんがえた。', 'Chúng tôi đã nghĩ ra chiến lược bán hàng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6726, 47269, '父は小さなレストランを経営している。', 'ちちは ちいさな レストランを けいえい して いる。', 'Bố tôi điều hành một nhà hàng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6727, 47280, '部品を工場に発注した。', 'ぶひんを こうじょうに はっちゅう した。', 'Chúng tôi đã đặt linh kiện từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6728, 47282, '商品は来週の月曜日に納品します。', 'しょうひんは らいしゅうの げつようびに のうひん します。', 'Hàng sẽ được giao vào thứ Hai tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6729, 47265, 'もっと合理的な方法があるはずだ。', 'もっと ごうりてきな ほうほうが ある はずだ。', 'Chắc chắn có cách hợp lý hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6730, 47263, '画一的な教育では個性が育たない。', 'かくいつてきな きょういくでは こせいが そだたない。', 'Giáo dục rập khuôn thì cá tính không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6731, 47266, '将来に漠然とした不安を感じている。', 'しょうらいに ばくぜんと した ふあんを かんじて いる。', 'Tôi cảm thấy lo lắng mơ hồ về tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6732, 47268, '彼はもっともらしい言い訳をした。', 'かれは もっともらしい いいわけを した。', 'Anh ta đưa ra một lời bào chữa nghe có vẻ hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6733, 47274, '多くの企業がこの市場に参入した。', 'おおくの きぎょうが この しじょうに さんにゅう した。', 'Nhiều doanh nghiệp đã gia nhập thị trường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6734, 47277, '大手企業がその会社を買収した。', 'おおて きぎょうが その かいしゃを ばいしゅう した。', 'Một doanh nghiệp lớn đã thâu tóm công ty đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6735, 47283, '在庫管理をシステム化した。', 'ざいこ かんりを システムか した。', 'Chúng tôi đã hệ thống hóa việc quản lý tồn kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6736, 47285, 'この値段では採算が合わない。', 'この ねだんでは さいさんが あわない。', 'Với giá này thì không có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6737, 28583, '恋人と一緒に旅行しました。', 'こいびとと いっしょに りょこう しました。', 'Tôi đã đi du lịch cùng người yêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6738, 47289, '今年は会社の業績が好調だ。', 'ことしは かいしゃの ぎょうせきが こうちょうだ。', 'Năm nay kết quả kinh doanh của công ty rất khả quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6739, 47292, '話し合いで事態の打開を図った。', 'はなしあいで じたいの だかいを はかった。', 'Chúng tôi tìm cách phá vỡ bế tắc bằng đối thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6740, 47294, '業界の再編が進んでいる。', 'ぎょうかいの さいへんが すすんで いる。', 'Ngành đang được tái cơ cấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6741, 47296, '家事を夫婦で分担している。', 'かじを ふうふで ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6742, 47297, 'この件を決める権限は部長にある。', 'この けんを きめる けんげんは ぶちょうに ある。', 'Quyền quyết định việc này thuộc về trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6743, 47341, '会社は損害を賠償することになった。', 'かいしゃは そんがいを ばいしょう する ことに なった。', 'Công ty phải đền bù thiệt hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6744, 47300, '会議の前に関係者に根回しをしておいた。', 'かいぎの まえに かんけいしゃに ねまわしを して おいた。', 'Trước cuộc họp tôi đã vận động trước với những người liên quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6745, 47302, '若手社員がリーダーに抜擢された。', 'わかて しゃいんが リーダーに ばってき された。', 'Một nhân viên trẻ đã được đề bạt làm trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6746, 47304, '不景気で多くの社員が解雇された。', 'ふけいきで おおくの しゃいんが かいこ された。', 'Do suy thoái, nhiều nhân viên đã bị sa thải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6747, 47308, '株主総会が来月開かれる。', 'かぶぬし そうかいが らいげつ ひらかれる。', 'Đại hội cổ đông sẽ được tổ chức vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6748, 47310, '小さな会社は資金繰りに苦労している。', 'ちいさな かいしゃは しきんぐりに くろう して いる。', 'Các công ty nhỏ đang vất vả xoay vòng vốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6749, 47313, '台風のため、運転を見合わせています。', 'たいふうの ため、うんてんを みあわせて います。', 'Do bão, tàu đang tạm ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6750, 47315, 'この店では外国の食品も取り扱っている。', 'この みせでは がいこくの しょくひんも とりあつかって いる。', 'Cửa hàng này cũng kinh doanh thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6751, 47317, '父は長年教育に携わってきた。', 'ちちは ながねん きょういくに たずさわって きた。', 'Bố tôi đã gắn bó với ngành giáo dục nhiều năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6752, 47319, '彼は百人の社員を率いている。', 'かれは ひゃくにんの しゃいんを ひきいて いる。', 'Anh ấy đang dẫn dắt một trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6753, 47322, '彼は大手のメーカーに就職した。', 'かれは おおての メーカーに しゅうしょく した。', 'Anh ấy vào làm ở một nhà sản xuất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6754, 47324, '状況に応じて柔軟に対応しよう。', 'じょうきょうに おうじて じゅうなんに たいおう しよう。', 'Hãy ứng phó linh hoạt tùy theo tình hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6755, 47326, '抜本的な改革が求められている。', 'ばっぽんてきな かいかくが もとめられて いる。', 'Một cuộc cải cách triệt để đang được đòi hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6756, 47328, '全社員の給料を一律に上げた。', 'ぜん しゃいんの きゅうりょうを いちりつに あげた。', 'Công ty tăng lương đồng loạt cho toàn bộ nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6757, 47333, '官僚の天下りが問題になっている。', 'かんりょうの あまくだりが もんだいに なって いる。', 'Việc quan chức nghỉ hưu chuyển sang doanh nghiệp đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6758, 47336, '会社の不祥事が相次いでいる。', 'かいしゃの ふしょうじが あいついで いる。', 'Các vụ bê bối của công ty liên tiếp xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6759, 47338, '社員が会社の不正を告発した。', 'しゃいんが かいしゃの ふせいを こくはつ した。', 'Một nhân viên đã tố giác hành vi gian lận của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6760, 47342, '社会の規範を守ることが求められる。', 'しゃかいの きはんを まもる ことが もとめられる。', 'Cần tuân thủ chuẩn mực xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6761, 47345, '警察は治安維持に努めている。', 'けいさつは ちあん いじに つとめて いる。', 'Cảnh sát đang nỗ lực giữ gìn an ninh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6762, 47347, '都市の過密が問題になっている。', 'としの かみつが もんだいに なって いる。', 'Tình trạng quá đông đúc ở thành phố đang là vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6763, 47350, '動物の虐待は許されない。', 'どうぶつの ぎゃくたいは ゆるされない。', 'Ngược đãi động vật là không thể chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6764, 47352, 'あらゆる差別を排除すべきだ。', 'あらゆる さべつを はいじょ すべきだ。', 'Cần loại trừ mọi sự phân biệt đối xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6765, 47356, 'この国は多くの移民を受け入れている。', 'この くには おおくの いみんを うけいれて いる。', 'Đất nước này tiếp nhận nhiều người di cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6766, 47369, '景気の悪化が懸念されている。', 'けいきの あっかが けねん されて いる。', 'Người ta lo ngại kinh tế sẽ xấu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6767, 47373, '政府は省エネを推進している。', 'せいふは しょうエネを すいしん して いる。', 'Chính phủ đang thúc đẩy tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6768, 47391, '仕事と家庭の間で葛藤している。', 'しごとと かていの あいだで かっとう して いる。', 'Tôi đang giằng xé giữa công việc và gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6769, 47367, '被災地にお金を寄付した。', 'ひさいちに おかねを きふ した。', 'Tôi đã quyên góp tiền cho vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6770, 47366, '被災地の支援のために、ボランティアに行った。', 'ひさいちの しえんの ために、ボランティアに いった。', 'Tôi đi tình nguyện để hỗ trợ vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6771, 47360, '小さなうわさが大きな騒動になった。', 'ちいさな うわさが おおきな そうどうに なった。', 'Một tin đồn nhỏ đã thành vụ náo loạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6772, 47371, '政府は規制を緩和した。', 'せいふは きせいを かんわ した。', 'Chính phủ đã nới lỏng các quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6773, 47372, 'チームの守備を強化する必要がある。', 'チームの しゅびを きょうか する ひつようが ある。', 'Cần củng cố hàng phòng ngự của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6774, 47400, '彼は友人の成功に嫉妬した。', 'かれは ゆうじんの せいこうに しっと した。', 'Anh ta ghen tị với thành công của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6775, 47363, '台風で農業は大きな打撃を受けた。', 'たいふうで のうぎょうは おおきな だげきを うけた。', 'Nông nghiệp chịu tổn thất nặng nề vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6776, 47374, '警察は犯人の逃走を阻止した。', 'けいさつは はんにんの とうそうを そし した。', 'Cảnh sát đã ngăn chặn thủ phạm bỏ trốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6777, 47378, '住民の切実な声に耳を傾けるべきだ。', 'じゅうみんの せつじつな こえに みみを かたむける べきだ。', 'Cần lắng nghe tiếng nói bức thiết của người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6778, 47380, '著名な作家の講演会に参加した。', 'ちょめいな さっかの こうえんかいに さんか した。', 'Tôi đã tham dự buổi diễn thuyết của một nhà văn nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6779, 47382, 'その事件で会社への信頼が揺らいだ。', 'その じけんで かいしゃへの しんらいが ゆらいだ。', 'Vụ việc đó đã làm lung lay niềm tin vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6780, 47384, '夜更かしは健康を損なう。', 'よふかしは けんこうを そこなう。', 'Thức khuya làm tổn hại sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6781, 47387, '感染の拡大を食い止めなければならない。', 'かんせんの かくだいを くいとめなければ ならない。', 'Phải ngăn chặn sự lây lan của dịch bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6782, 47390, '被害者の心情を考えると胸が痛む。', 'ひがいしゃの しんじょうを かんがえると むねが いたむ。', 'Nghĩ đến tâm tình của nạn nhân mà tôi thấy đau lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6783, 47394, '試験が近づき、焦りを感じ始めた。', 'しけんが ちかづき、あせりを かんじ はじめた。', 'Kỳ thi đến gần, tôi bắt đầu thấy sốt ruột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6784, 47398, '人を見下して優越感に浸るのはよくない。', 'ひとを みくだして ゆうえつかんに ひたるのは よくない。', 'Coi thường người khác để thấy mình hơn người là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6785, 44992, '恋人と一緒に旅行しました。', 'こいびとと いっしょに りょこう しました。', 'Tôi đã đi du lịch cùng người yêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6786, 47434, '人間関係が煩わしくなってきた。', 'にんげん かんけいが わずらわしく なって きた。', 'Các mối quan hệ con người bắt đầu trở nên phiền toái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6787, 47405, '長く使っている机に愛着がある。', 'ながく つかって いる つくえに あいちゃくが ある。', 'Tôi gắn bó với chiếc bàn đã dùng lâu năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6788, 47410, '臆病な性格を直したい。', 'おくびょうな せいかくを なおしたい。', 'Tôi muốn sửa tính nhút nhát của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6789, 47413, '彼の几帳面さは仕事にも表れている。', 'かれの きちょうめんさは しごとにも あらわれて いる。', 'Tính tỉ mỉ của anh ấy thể hiện cả trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6790, 47415, '彼の考えに深く共感した。', 'かれの かんがえに ふかく きょうかん した。', 'Tôi đồng cảm sâu sắc với suy nghĩ của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6791, 47418, '温泉で旅の疲れを癒した。', 'おんせんで たびの つかれを いやした。', 'Tôi xua tan mệt mỏi của chuyến đi ở suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6792, 47420, '彼は自分の不運を嘆いた。', 'かれは じぶんの ふうんを なげいた。', 'Anh ấy than thở về vận rủi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6793, 47409, '成功してから、彼は傲慢になった。', 'せいこう してから、かれは ごうまんに なった。', 'Từ khi thành công, anh ta trở nên kiêu ngạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6794, 47457, 'データを使って仮説を検証した。', 'データを つかって かせつを けんしょう した。', 'Chúng tôi dùng dữ liệu để kiểm chứng giả thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6795, 47452, 'ニュートンは引力の法則を発見した。', 'ニュートンは いんりょくの ほうそくを はっけん した。', 'Newton đã phát hiện ra định luật vạn vật hấp dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6796, 47456, '博物館で昆虫の標本を見た。', 'はくぶつかんで こんちゅうの ひょうほんを みた。', 'Tôi xem mẫu vật côn trùng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6797, 47422, '急に質問されて戸惑った。', 'きゅうに しつもん されて とまどった。', 'Bị hỏi đột ngột nên tôi lúng túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6798, 47425, '人目をはばからずに泣いた。', 'ひとめを はばからずに ないた。', 'Tôi khóc chẳng e ngại ánh mắt người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6799, 47427, 'お年寄りをいたわる気持ちを忘れないで。', 'おとしよりを いたわる きもちを わすれないで。', 'Đừng quên tấm lòng quan tâm người già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6800, 47429, '一人で思い詰めないで、相談してください。', 'ひとりで おもいつめないで、そうだん して ください。', 'Đừng một mình nghĩ quẩn, hãy tâm sự với tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6801, 47431, '別れの場面は切なかった。', 'わかれの ばめんは せつなかった。', 'Cảnh chia ly thật da diết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6802, 47435, '約束を破って、後ろめたい気持ちだ。', 'やくそくを やぶって、うしろめたい きもちだ。', 'Thất hứa nên tôi thấy áy náy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6803, 47437, '手伝ってもらえるのは本当にありがたい。', 'てつだって もらえるのは ほんとうに ありがたい。', 'Được giúp đỡ thật là quý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6804, 47439, '病気の母を支える少女の姿が健気だ。', 'びょうきの ははを ささえる しょうじょの すがたが けなげだ。', 'Hình ảnh cô bé chăm sóc mẹ ốm thật đáng khen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6805, 47442, '親のありがたさをつくづく感じた。', 'おやの ありがたさを つくづく かんじた。', 'Tôi thấm thía công ơn cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6806, 47445, '母に言われて、しぶしぶ宿題をした。', 'ははに いわれて、しぶしぶ しゅくだいを した。', 'Bị mẹ nhắc, tôi miễn cưỡng làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6807, 47448, '過ぎたことをくよくよしても仕方がない。', 'すぎた ことを くよくよ しても しかたが ない。', 'Ủ ê vì chuyện đã qua cũng chẳng ích gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6808, 47454, '検査の数値が正常に戻った。', 'けんさの すうちが せいじょうに もどった。', 'Chỉ số xét nghiệm đã trở lại bình thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6809, 47460, '警察は事件の真相を究明している。', 'けいさつは じけんの しんそうを きゅうめい して いる。', 'Cảnh sát đang điều tra làm rõ sự thật vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6810, 47481, 'いつか宇宙へ行ってみたいです。', 'いつか うちゅうへ いって みたい です。', 'Một ngày nào đó tôi muốn thử lên vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6811, 47485, '空気は温めると膨張する。', 'くうきは あたためると ぼうちょう する。', 'Không khí khi được làm nóng sẽ giãn nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6812, 47486, '寒さで筋肉が収縮する。', 'さむさで きんにくが しゅうしゅく する。', 'Cơ bắp co lại vì lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6813, 47506, '彼は緻密な計画を立てた。', 'かれは ちみつな けいかくを たてた。', 'Anh ấy đã lập một kế hoạch chặt chẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6814, 47465, '彼は新しい遊びを考案した。', 'かれは あたらしい あそびを こうあん した。', 'Anh ấy đã nghĩ ra một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6815, 47467, 'この研究から新たな知見が得られた。', 'この けんきゅうから あらたな ちけんが えられた。', 'Từ nghiên cứu này đã thu được những hiểu biết mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6816, 47472, '遺伝子の研究が進んでいる。', 'いでんしの けんきゅうが すすんで いる。', 'Nghiên cứu về gen đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6817, 47475, '土の中には多くの微生物がいる。', 'つちの なかには おおくの びせいぶつが いる。', 'Trong đất có rất nhiều vi sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6818, 47477, '新しい元素が発見された。', 'あたらしい げんそが はっけん された。', 'Một nguyên tố mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6819, 47478, '水の分子は小さい。', 'みずの ぶんしは ちいさい。', 'Phân tử nước rất nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6820, 47512, '現代の若者はスマホなしでは生活できない。', 'げんだいの わかものは スマホ なしでは せいかつ できない。', 'Giới trẻ ngày nay không thể sống thiếu điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6821, 47468, 'これは私の専門の領域ではない。', 'これは わたしの せんもんの りょういき では ない。', 'Đây không phải lĩnh vực chuyên môn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6822, 47473, 'スマホは年々進化している。', 'スマホは ねんねん しんか して いる。', 'Điện thoại thông minh tiến hóa qua từng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6823, 47515, '天皇の誕生日は祝日だ。', 'てんのうの たんじょうびは しゅくじつだ。', 'Sinh nhật Nhật hoàng là ngày lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6824, 47507, '膨大な資料を一人で整理した。', 'ぼうだいな しりょうを ひとりで せいり した。', 'Tôi một mình sắp xếp lượng tài liệu đồ sộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6825, 47536, '高校で日本の古典を勉強した。', 'こうこうで にほんの こてんを べんきょう した。', 'Ở cấp ba tôi học văn học cổ điển Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6826, 47483, '人工衛星が軌道に乗った。', 'じんこう えいせいが きどうに のった。', 'Vệ tinh nhân tạo đã vào quỹ đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6827, 47490, '植物から香りの成分を抽出する。', 'しょくぶつから かおりの せいぶんを ちゅうしゅつ する。', 'Chiết xuất thành phần hương thơm từ thực vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6828, 47492, 'この機械は精度が高い。', 'この きかいは せいどが たかい。', 'Máy này có độ chính xác cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6829, 47494, 'このクラスの男女の比率は半々だ。', 'この クラスの だんじょの ひりつは はんはんだ。', 'Tỷ lệ nam nữ của lớp này là một nửa mỗi bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6830, 47497, '愛は人類に普遍的なテーマだ。', 'あいは じんるいに ふへんてきな テーマだ。', 'Tình yêu là chủ đề phổ quát của nhân loại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6831, 47500, '新しい国際協力の枠組みが作られた。', 'あたらしい こくさい きょうりょくの わくぐみが つくられた。', 'Một khuôn khổ hợp tác quốc tế mới đã được xây dựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6832, 47503, '彼は茶道の道を究めた。', 'かれは さどうの みちを きわめた。', 'Ông ấy đã đạt đến tận cùng con đường trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6833, 47505, '宇宙の謎を解き明かしたい。', 'うちゅうの なぞを ときあかしたい。', 'Tôi muốn giải đáp những bí ẩn của vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6834, 47509, '古代エジプトの文明に興味がある。', 'こだい エジプトの ぶんめいに きょうみが ある。', 'Tôi quan tâm đến nền văn minh Ai Cập cổ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6835, 47514, 'この寺は平安王朝の時代に建てられた。', 'この てらは へいあん おうちょうの じだいに たてられた。', 'Ngôi chùa này được xây vào thời triều đại Heian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6836, 28595, 'お金持ちになったら、世界を旅行したいです。', 'おかねもちに なったら、せかいを りょこう したい です。', 'Nếu giàu có, tôi muốn đi du lịch khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6837, 47571, '子供の視点から町を見直してみよう。', 'こどもの してんから まちを みなおして みよう。', 'Hãy thử nhìn lại thành phố từ góc nhìn của trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6838, 47590, '最近、結婚しない人が増える傾向にある。', 'さいきん、けっこん しない ひとが ふえる けいこうに ある。', 'Gần đây có xu hướng nhiều người không kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6839, 45505, '彼の専門は日本文学だ。', 'かれの せんもんは にほん ぶんがくだ。', 'Chuyên môn của anh ấy là văn học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6840, 45507, '間違いが多かったので、作文を書き直した。', 'まちがいが おおかったので、さくぶんを かきなおした。', 'Nhiều lỗi quá nên tôi viết lại bài văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6841, 45510, '昼ご飯はパンで済ませた。', 'ひるごはんは パンで すませた。', 'Bữa trưa tôi ăn tạm bánh mì cho xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6842, 47579, 'ご提案については、社内で検討いたします。', 'ごていあんに ついては、しゃないで けんとう いたします。', 'Về đề xuất của quý vị, chúng tôi sẽ xem xét trong công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6843, 47542, '文脈から言葉の意味を考えなさい。', 'ぶんみゃくから ことばの いみを かんがえなさい。', 'Hãy suy ra nghĩa của từ từ ngữ cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6844, 47574, '彼の話は論理が通っていない。', 'かれの はなしは ろんりが とおって いない。', 'Câu chuyện của anh ta không hợp logic.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6845, 47576, '彼の表情から気持ちを推測した。', 'かれの ひょうじょうから きもちを すいそく した。', 'Tôi đoán tâm trạng anh ấy qua nét mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6846, 47580, '材料を吟味して料理を作る。', 'ざいりょうを ぎんみ して りょうりを つくる。', 'Tôi lựa chọn kỹ nguyên liệu rồi mới nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6847, 47582, '彼の意見にも一理ある。', 'かれの いけんにも いちり ある。', 'Ý kiến của anh ấy cũng có lý phần nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6848, 47583, 'この計画の妥当性を検討する。', 'この けいかくの だとうせいを けんとう する。', 'Chúng tôi xem xét tính hợp lý của kế hoạch này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6849, 47586, 'この絵は抽象的でよくわからない。', 'この えは ちゅうしょうてきで よく わからない。', 'Bức tranh này trừu tượng, tôi không hiểu lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6850, 47588, '問題の本質を見極めることが大切だ。', 'もんだいの ほんしつを みきわめる ことが たいせつだ。', 'Nhận rõ bản chất vấn đề là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6851, 47594, '彼女のレポートは着眼点がおもしろい。', 'かのじょの レポートは ちゃくがんてんが おもしろい。', 'Bản báo cáo của cô ấy có điểm nhìn thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6852, 47596, '彼は経済について高い見識を持っている。', 'かれは けいざいに ついて たかい けんしきを もって いる。', 'Ông ấy có hiểu biết sâu sắc về kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6853, 47540, '本を読んで語彙を増やしたい。', 'ほんを よんで ごいを ふやしたい。', 'Tôi muốn đọc sách để tăng vốn từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6854, 47544, '「顔が広い」は慣用句の一つだ。', '「かおが ひろい」は かんようくの ひとつだ。', '"Mặt rộng" (quen biết nhiều) là một thành ngữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6855, 47548, 'この本は口語で書かれていて読みやすい。', 'この ほんは こうごで かかれて いて よみやすい。', 'Cuốn sách này viết bằng văn nói nên dễ đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6856, 47559, 'この伝統行事は廃れつつある。', 'この でんとう ぎょうじは すたれつつ ある。', 'Sự kiện truyền thống này đang dần mai một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6857, 47561, '亡くなった祖父を偲んで、みんなで集まった。', 'なくなった そふを しのんで、みんなで あつまった。', 'Mọi người tụ họp để tưởng nhớ ông đã khuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6858, 47564, '日本料理の世界は奥深い。', 'にほん りょうりの せかいは おくぶかい。', 'Thế giới ẩm thực Nhật Bản thật thâm sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6859, 47566, '京都には雅な文化が残っている。', 'きょうとには みやびな ぶんかが のこって いる。', 'Kyoto còn lưu giữ nền văn hóa tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6860, 47567, '田舎の人々は素朴で温かい。', 'いなかの ひとびとは そぼくで あたたかい。', 'Người dân quê mộc mạc và ấm áp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6861, 44996, '姉に赤ちゃんが生まれました。', 'あねに あかちゃんが うまれました。', 'Chị tôi vừa sinh em bé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6862, 47603, '若者はみんな本を読まないとは一概には言えない。', 'わかものは みんな ほんを よまないとは いちがいには いえない。', 'Không thể vơ đũa cả nắm rằng giới trẻ đều không đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6863, 47606, '彼はこの店の、いわば顔のような存在だ。', 'かれは この みせの、いわば かおの ような そんざいだ。', 'Anh ấy có thể nói là gương mặt đại diện của cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6864, 47610, '本物かどうかを見極めるのは難しい。', 'ほんもの か どうかを みきわめるのは むずかしい。', 'Nhận định rõ đâu là đồ thật thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6865, 47612, '連絡がない場合は、欠席と見なします。', 'れんらくが ない ばあいは、けっせきと みなします。', 'Trường hợp không liên lạc sẽ bị coi là vắng mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6866, 47614, '彼は仕事に生きがいを見出した。', 'かれは しごとに いきがいを みいだした。', 'Anh ấy tìm ra lẽ sống trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6867, 47616, '新しい発見が従来の定説を覆した。', 'あたらしい はっけんが じゅうらいの ていせつを くつがえした。', 'Phát hiện mới đã lật đổ học thuyết vốn có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6868, 47620, '彼の責任は明白だ。', 'かれの せきにんは めいはくだ。', 'Trách nhiệm của anh ta là rõ ràng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6975, 47853, '測定には多少の誤差がある。', 'そくていには たしょうの ごさが ある。', 'Phép đo có một chút sai số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6869, 47623, '画一的な教育では個性が育たない。', 'かくいつてきな きょういくでは こせいが そだたない。', 'Giáo dục rập khuôn thì cá tính không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6870, 47626, '将来に漠然とした不安を感じている。', 'しょうらいに ばくぜんと した ふあんを かんじて いる。', 'Tôi cảm thấy lo lắng mơ hồ về tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6871, 47601, '彼女は質問に肯定も否定もしなかった。', 'かのじょは しつもんに こうていも ひていも しなかった。', 'Cô ấy không khẳng định cũng không phủ nhận câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6872, 47631, '新しい販売戦略を考えた。', 'あたらしい はんばい せんりゃくを かんがえた。', 'Chúng tôi đã nghĩ ra chiến lược bán hàng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6873, 47638, '日本の会社と海外の会社が提携した。', 'にほんの かいしゃと かいがいの かいしゃが ていけい した。', 'Một công ty Nhật và một công ty nước ngoài đã liên kết với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6874, 47636, '二つの銀行が合併して、一つになった。', 'ふたつの ぎんこうが がっぺい して、ひとつに なった。', 'Hai ngân hàng sáp nhập thành một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6875, 47642, '商品は来週の月曜日に納品します。', 'しょうひんは らいしゅうの げつようびに のうひん します。', 'Hàng sẽ được giao vào thứ Hai tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6876, 47625, 'もっと合理的な方法があるはずだ。', 'もっと ごうりてきな ほうほうが ある はずだ。', 'Chắc chắn có cách hợp lý hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6877, 47628, '彼はもっともらしい言い訳をした。', 'かれは もっともらしい いいわけを した。', 'Anh ta đưa ra một lời bào chữa nghe có vẻ hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6878, 47634, '多くの企業がこの市場に参入した。', 'おおくの きぎょうが この しじょうに さんにゅう した。', 'Nhiều doanh nghiệp đã gia nhập thị trường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6879, 47637, '大手企業がその会社を買収した。', 'おおて きぎょうが その かいしゃを ばいしゅう した。', 'Một doanh nghiệp lớn đã thâu tóm công ty đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6880, 47643, '在庫管理をシステム化した。', 'ざいこ かんりを システムか した。', 'Chúng tôi đã hệ thống hóa việc quản lý tồn kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6881, 47645, 'この値段では採算が合わない。', 'この ねだんでは さいさんが あわない。', 'Với giá này thì không có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6882, 47648, '人件費が経営を圧迫している。', 'じんけんひが けいえいを あっぱく して いる。', 'Chi phí nhân sự đang gây áp lực lên việc kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6883, 47650, '景気の見通しは明るい。', 'けいきの みとおしは あかるい。', 'Triển vọng kinh tế rất sáng sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6884, 47653, '新社長は組織の刷新を進めている。', 'しん しゃちょうは そしきの さっしんを すすめて いる。', 'Tân giám đốc đang tiến hành đổi mới toàn diện tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6885, 28584, '今日のラッキーアイテムは傘だそうです。', 'きょうの ラッキーアイテムは かさだ そう です。', 'Nghe nói vật may mắn hôm nay là cây ô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6886, 47655, '二つの部署が統合された。', 'ふたつの ぶしょが とうごう された。', 'Hai phòng ban đã được hợp nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6887, 47658, 'この件は部長の決裁が必要だ。', 'この けんは ぶちょうの けっさいが ひつようだ。', 'Việc này cần trưởng phòng phê duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6888, 47661, '彼は営業部長と企画部長を兼任している。', 'かれは えいぎょう ぶちょうと きかく ぶちょうを けんにん して いる。', 'Anh ấy kiêm nhiệm trưởng phòng kinh doanh và trưởng phòng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6889, 47664, '不景気で多くの社員が解雇された。', 'ふけいきで おおくの しゃいんが かいこ された。', 'Do suy thoái, nhiều nhân viên đã bị sa thải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6890, 47657, 'この件を決める権限は部長にある。', 'この けんを きめる けんげんは ぶちょうに ある。', 'Quyền quyết định việc này thuộc về trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6891, 47699, '被害者は会社を相手に訴訟を起こした。', 'ひがいしゃは かいしゃを あいてに そしょうを おこした。', 'Người bị hại đã khởi kiện công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6892, 47667, '彼は退職後、会社の顧問になった。', 'かれは たいしょくご、かいしゃの こもんに なった。', 'Sau khi nghỉ hưu ông ấy trở thành cố vấn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6893, 47669, '友人の新しい事業に出資した。', 'ゆうじんの あたらしい じぎょうに しゅっし した。', 'Tôi đã góp vốn vào công việc kinh doanh mới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6894, 47671, 'その銀行は経営が破綻した。', 'その ぎんこうは けいえいが はたん した。', 'Ngân hàng đó đã đổ vỡ kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6895, 47673, '台風のため、運転を見合わせています。', 'たいふうの ため、うんてんを みあわせて います。', 'Do bão, tàu đang tạm ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6896, 47676, 'アルバイトで生活費を賄っている。', 'アルバイトで せいかつひを まかなって いる。', 'Tôi trang trải sinh hoạt phí bằng việc làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6897, 47678, '若者が国の未来を担っている。', 'わかものが くにの みらいを になって いる。', 'Giới trẻ đang gánh vác tương lai đất nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6898, 47680, '今年は売り上げの増加が見込まれる。', 'ことしは うりあげの ぞうかが みこまれる。', 'Năm nay dự tính doanh thu sẽ tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6899, 47682, '彼は大手のメーカーに就職した。', 'かれは おおての メーカーに しゅうしょく した。', 'Anh ấy vào làm ở một nhà sản xuất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6900, 47684, '状況に応じて柔軟に対応しよう。', 'じょうきょうに おうじて じゅうなんに たいおう しよう。', 'Hãy ứng phó linh hoạt tùy theo tình hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6901, 47686, '抜本的な改革が求められている。', 'ばっぽんてきな かいかくが もとめられて いる。', 'Một cuộc cải cách triệt để đang được đòi hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6902, 47691, '新しい内閣が発足した。', 'あたらしい ないかくが ほっそく した。', 'Nội các mới đã được thành lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6903, 47692, '閣僚の一人が辞任した。', 'かくりょうの ひとりが じにん した。', 'Một thành viên nội các đã từ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6904, 47695, '役人が賄賂を受け取ったことが発覚した。', 'やくにんが わいろを うけとった ことが はっかく した。', 'Đã phát hiện việc quan chức nhận hối lộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6905, 47697, '会社は事故を隠蔽しようとした。', 'かいしゃは じこを いんぺい しようと した。', 'Công ty đã tìm cách che giấu tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6906, 47700, '長い裁判の末、両者は和解した。', 'ながい さいばんの すえ、りょうしゃは わかい した。', 'Sau phiên tòa kéo dài, hai bên đã hòa giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6907, 47704, '社会の秩序を守るために法律がある。', 'しゃかいの ちつじょを まもる ために ほうりつが ある。', 'Pháp luật tồn tại để giữ gìn trật tự xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6908, 47706, '過疎の村では学校がなくなっている。', 'かその むらでは がっこうが なくなって いる。', 'Ở những ngôi làng thưa dân, trường học đang biến mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6909, 47710, '動物の虐待は許されない。', 'どうぶつの ぎゃくたいは ゆるされない。', 'Ngược đãi động vật là không thể chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6910, 47712, 'あらゆる差別を排除すべきだ。', 'あらゆる さべつを はいじょ すべきだ。', 'Cần loại trừ mọi sự phân biệt đối xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6911, 47716, 'この国は多くの移民を受け入れている。', 'この くには おおくの いみんを うけいれて いる。', 'Đất nước này tiếp nhận nhiều người di cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6912, 47718, '会議は予算をめぐって紛糾した。', 'かいぎは よさんを めぐって ふんきゅう した。', 'Cuộc họp trở nên rối ren xung quanh vấn đề ngân sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6913, 47733, '政府は省エネを推進している。', 'せいふは しょうエネを すいしん して いる。', 'Chính phủ đang thúc đẩy tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6914, 47751, '仕事と家庭の間で葛藤している。', 'しごとと かていの あいだで かっとう して いる。', 'Tôi đang giằng xé giữa công việc và gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6915, 47760, '彼は友人の成功に嫉妬した。', 'かれは ゆうじんの せいこうに しっと した。', 'Anh ta ghen tị với thành công của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6916, 47763, '別れた恋人にまだ未練がある。', 'わかれた こいびとに まだ みれんが ある。', 'Tôi vẫn còn lưu luyến người yêu cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6917, 47722, '両国の関係が緊迫している。', 'りょうこくの かんけいが きんぱく して いる。', 'Quan hệ giữa hai nước đang căng thẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6918, 47727, '被災地にお金を寄付した。', 'ひさいちに おかねを きふ した。', 'Tôi đã quyên góp tiền cho vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6919, 47768, '彼は「まだまだです」と謙遜した。', 'かれは 「まだまだ です」と けんそん した。', 'Anh ấy khiêm tốn nói "tôi còn kém lắm".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6920, 47720, '小さなうわさが大きな騒動になった。', 'ちいさな うわさが おおきな そうどうに なった。', 'Một tin đồn nhỏ đã thành vụ náo loạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6921, 47725, '地震の後、町の復興が進んでいる。', 'じしんの あと、まちの ふっこうが すすんで いる。', 'Sau động đất, công cuộc tái thiết thị trấn đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6922, 47732, 'チームの守備を強化する必要がある。', 'チームの しゅびを きょうか する ひつようが ある。', 'Cần củng cố hàng phòng ngự của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6923, 47728, '被災地に義援金を送った。', 'ひさいちに ぎえんきんを おくった。', 'Tôi đã gửi tiền cứu trợ đến vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6924, 47737, '事態の深刻さに気づいていない人が多い。', 'じたいの しんこくさに きづいて いない ひとが おおい。', 'Nhiều người không nhận ra mức độ nghiêm trọng của sự việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6925, 47739, '人手不足への対応が喫緊の課題だ。', 'ひとで ぶそくへの たいおうが きっきんの かだいだ。', 'Ứng phó với tình trạng thiếu nhân lực là vấn đề cấp bách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6926, 47741, '大臣の発言が物議を醸した。', 'だいじんの はつげんが ぶつぎを かもした。', 'Phát ngôn của bộ trưởng đã gây xôn xao dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6927, 47744, '夜更かしは健康を損なう。', 'よふかしは けんこうを そこなう。', 'Thức khuya làm tổn hại sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6928, 47746, '会社は経営難に陥った。', 'かいしゃは けいえいなんに おちいった。', 'Công ty rơi vào khó khăn kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6929, 47749, '引退を決めた今の心境を聞かせてください。', 'いんたいを きめた いまの しんきょうを きかせて ください。', 'Hãy cho tôi biết tâm trạng của anh lúc quyết định giải nghệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6930, 47752, '突然の知らせに彼は動揺した。', 'とつぜんの しらせに かれは どうよう した。', 'Trước tin báo đột ngột, anh ấy bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6931, 47757, '優秀な兄に劣等感を抱いていた。', 'ゆうしゅうな あにに れっとうかんを いだいて いた。', 'Tôi từng mặc cảm trước người anh xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6932, 47759, 'うそをついて罪悪感を覚えた。', 'うそを ついて ざいあくかんを おぼえた。', 'Nói dối xong tôi thấy có lỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6933, 47764, '過去に執着していては前に進めない。', 'かこに しゅうちゃく して いては まえに すすめない。', 'Cứ bám víu quá khứ thì không thể tiến lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6934, 47766, '古い写真を見て、郷愁にかられた。', 'ふるい しゃしんを みて、きょうしゅうに かられた。', 'Nhìn bức ảnh cũ, nỗi nhớ quê dâng trào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6935, 47804, '彼は合格のためにひたすら勉強した。', 'かれは ごうかくの ために ひたすら べんきょう した。', 'Anh ấy chỉ một mực học để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6936, 47770, '臆病な性格を直したい。', 'おくびょうな せいかくを なおしたい。', 'Tôi muốn sửa tính nhút nhát của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6937, 47774, '看護師たちの献身的な働きに感謝した。', 'かんごしたちの けんしんてきな はたらきに かんしゃ した。', 'Tôi biết ơn sự tận tụy của các y tá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6938, 47777, '子供たちの歌声に心が和んだ。', 'こどもたちの うたごえに こころが なごんだ。', 'Tiếng hát của bọn trẻ làm lòng tôi dịu lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6939, 47779, '多くの学生がその先生を慕っている。', 'おおくの がくせいが その せんせいを したって いる。', 'Nhiều học trò yêu mến người thầy đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6940, 47781, '今さら悔やんでもしかたがない。', 'いまさら くやんでも しかたが ない。', 'Bây giờ hối tiếc cũng chẳng ích gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6941, 47783, '子供は雷の音に怯えていた。', 'こどもは かみなりの おとに おびえて いた。', 'Đứa trẻ sợ hãi trước tiếng sấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6942, 47785, '人目をはばからずに泣いた。', 'ひとめを はばからずに ないた。', 'Tôi khóc chẳng e ngại ánh mắt người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6943, 47815, '統計によると、日本の人口は減り続けている。', 'とうけいに よると、にほんの じんこうは へり つづけて いる。', 'Theo thống kê, dân số Nhật tiếp tục giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6944, 47817, 'データを使って仮説を検証した。', 'データを つかって かせつを けんしょう した。', 'Chúng tôi dùng dữ liệu để kiểm chứng giả thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6945, 47811, '飛行機が飛ぶ原理を説明してください。', 'ひこうきが とぶ げんりを せつめい して ください。', 'Hãy giải thích nguyên lý máy bay bay được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6946, 47816, '博物館で昆虫の標本を見た。', 'はくぶつかんで こんちゅうの ひょうほんを みた。', 'Tôi xem mẫu vật côn trùng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6947, 47801, '親のありがたさをしみじみ感じた。', 'おやの ありがたさを しみじみ かんじた。', 'Tôi thấm thía công ơn của cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6948, 47788, '新しいクラスメートとすぐに打ち解けた。', 'あたらしい クラスメートと すぐに うちとけた。', 'Tôi nhanh chóng thân thiết với bạn học mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6949, 47790, '気兼ねなく何でも言ってください。', 'きがね なく なんでも いって ください。', 'Cứ nói bất cứ điều gì, đừng e ngại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6950, 47792, '初めての一人暮らしは心細い。', 'はじめての ひとりぐらしは こころぼそい。', 'Lần đầu sống một mình thấy bất an.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6951, 47795, '約束を破って、後ろめたい気持ちだ。', 'やくそくを やぶって、うしろめたい きもちだ。', 'Thất hứa nên tôi thấy áy náy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6952, 47797, '手伝ってもらえるのは本当にありがたい。', 'てつだって もらえるのは ほんとうに ありがたい。', 'Được giúp đỡ thật là quý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6953, 47800, '自分から掃除をするとは殊勝な心がけだ。', 'じぶんから そうじを するとは しゅしょうな こころがけだ。', 'Tự giác dọn dẹp là một ý thức đáng khen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6954, 47803, '彼女はひそかに彼を思っていた。', 'かのじょは ひそかに かれを おもって いた。', 'Cô ấy thầm thương anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6955, 47806, '美しい音楽にうっとりした。', 'うつくしい おんがくに うっとり した。', 'Tôi mê mẩn trước bản nhạc tuyệt đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6956, 47810, 'この言葉の定義を確認しよう。', 'この ことばの ていぎを かくにん しよう。', 'Hãy xác nhận định nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6957, 47814, '検査の数値が正常に戻った。', 'けんさの すうちが せいじょうに もどった。', 'Chỉ số xét nghiệm đã trở lại bình thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6958, 47820, '警察は事件の真相を究明している。', 'けいさつは じけんの しんそうを きゅうめい して いる。', 'Cảnh sát đang điều tra làm rõ sự thật vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6959, 47825, '彼は新しい遊びを考案した。', 'かれは あたらしい あそびを こうあん した。', 'Anh ấy đã nghĩ ra một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6960, 47845, '空気は温めると膨張する。', 'くうきは あたためると ぼうちょう する。', 'Không khí khi được làm nóng sẽ giãn nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6961, 47858, 'この辞書は専門用語を網羅している。', 'この じしょは せんもん ようごを もうら して いる。', 'Cuốn từ điển này bao quát hết thuật ngữ chuyên môn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6962, 47885, 'この地方には珍しい風習が残っている。', 'この ちほうには めずらしい ふうしゅうが のこって いる。', 'Vùng này còn lưu giữ những phong tục lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6963, 47830, '環境問題は学際的な研究が必要だ。', 'かんきょう もんだいは がくさいてきな けんきゅうが ひつようだ。', 'Vấn đề môi trường cần nghiên cứu liên ngành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6964, 47832, '遺伝子の研究が進んでいる。', 'いでんしの けんきゅうが すすんで いる。', 'Nghiên cứu về gen đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6965, 47835, '土の中には多くの微生物がいる。', 'つちの なかには おおくの びせいぶつが いる。', 'Trong đất có rất nhiều vi sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6966, 47837, '新しい元素が発見された。', 'あたらしい げんそが はっけん された。', 'Một nguyên tố mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6967, 47829, '彼は医学の分野で活躍している。', 'かれは いがくの ぶんやで かつやく して いる。', 'Anh ấy hoạt động tích cực trong lĩnh vực y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6968, 47833, 'スマホは年々進化している。', 'スマホは ねんねん しんか して いる。', 'Điện thoại thông minh tiến hóa qua từng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6969, 47875, '天皇の誕生日は祝日だ。', 'てんのうの たんじょうびは しゅくじつだ。', 'Sinh nhật Nhật hoàng là ngày lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6970, 47867, '膨大な資料を一人で整理した。', 'ぼうだいな しりょうを ひとりで せいり した。', 'Tôi một mình sắp xếp lượng tài liệu đồ sộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6971, 47876, '昔の武士は刀を持っていた。', 'むかしの ぶしは かたなを もって いた。', 'Võ sĩ ngày xưa mang kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6972, 47842, '地球は太陽系の惑星の一つだ。', 'ちきゅうは たいようけいの わくせいの ひとつだ。', 'Trái đất là một trong các hành tinh của hệ Mặt trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6973, 47850, '植物から香りの成分を抽出する。', 'しょくぶつから かおりの せいぶんを ちゅうしゅつ する。', 'Chiết xuất thành phần hương thơm từ thực vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6974, 47851, '二枚の写真を合成した。', 'にまいの しゃしんを ごうせい した。', 'Tôi ghép hai bức ảnh lại với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6976, 47856, '二つの出来事の因果関係を調べる。', 'ふたつの できごとの いんが かんけいを しらべる。', 'Điều tra quan hệ nhân quả giữa hai sự kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6977, 47859, '知識を体系的に整理した。', 'ちしきを たいけいてきに せいり した。', 'Tôi sắp xếp kiến thức một cách có hệ thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6978, 47862, '留学で国際的な感覚を培った。', 'りゅうがくで こくさいてきな かんかくを つちかった。', 'Qua du học tôi đã bồi dưỡng được cảm quan quốc tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6979, 47864, '新しい方法を試みることにした。', 'あたらしい ほうほうを こころみる ことに した。', 'Tôi quyết định thử một phương pháp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6980, 47868, '厳密に言えば、これは正しくない。', 'げんみつに いえば、これは ただしく ない。', 'Nói chặt chẽ thì điều này không đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6981, 47873, '祖父は時代劇を見るのが好きだ。', 'そふは じだいげきを みるのが すきだ。', 'Ông tôi thích xem phim cổ trang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6982, 47877, '昔、この城には大名が住んでいた。', 'むかし、この しろには だいみょうが すんで いた。', 'Ngày xưa lâu đài này là nơi lãnh chúa sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6983, 47880, '開国によって日本は大きく変わった。', 'かいこくに よって にほんは おおきく かわった。', 'Nhờ mở cửa, Nhật Bản đã thay đổi rất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6984, 47882, 'この祭りの起源は千年前にさかのぼる。', 'この まつりの きげんは せんねんまえに さかのぼる。', 'Nguồn gốc lễ hội này có từ một nghìn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6985, 47905, 'このことわざの意味を知っていますか。', 'この ことわざの いみを しって いますか。', 'Bạn có biết ý nghĩa câu tục ngữ này không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6986, 47931, '子供の視点から町を見直してみよう。', 'こどもの してんから まちを みなおして みよう。', 'Hãy thử nhìn lại thành phố từ góc nhìn của trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6987, 47934, '彼の話は論理が通っていない。', 'かれの はなしは ろんりが とおって いない。', 'Câu chuyện của anh ta không hợp logic.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6988, 45512, 'このまま計画を進めましょう。', 'この まま けいかくを すすめましょう。', 'Cứ tiếp tục triển khai kế hoạch như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6989, 45514, '忙しかったので、誘いを断った。', 'いそがしかったので、さそいを ことわった。', 'Vì bận nên tôi đã từ chối lời mời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6990, 45515, '夏休みにアルバイトで旅行のお金を稼いだ。', 'なつやすみに アルバイトで りょこうの おかねを かせいだ。', 'Kỳ nghỉ hè tôi làm thêm để kiếm tiền đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6991, 45517, '電車を間違えて、遠くまで行ってしまった。', 'でんしゃを まちがえて、とおくまで いって しまった。', 'Đi nhầm tàu nên tôi bị đi xa mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6992, 45519, '忙しさのあまり、食事を忘れてしまった。', 'いそがしさの あまり、しょくじを わすれて しまった。', 'Bận quá đến mức quên cả ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6993, 45522, '正確な時間を教えてください。', 'せいかくな じかんを おしえて ください。', 'Hãy cho tôi biết giờ chính xác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6994, 45526, '至急、部長に連絡してください。', 'しきゅう、ぶちょうに れんらく して ください。', 'Hãy liên lạc với trưởng phòng gấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6995, 45527, '買ったばかりの服を早速着てみた。', 'かった ばかりの ふくを さっそく きて みた。', 'Tôi mặc thử ngay bộ quần áo vừa mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6996, 47902, '文脈から言葉の意味を考えなさい。', 'ぶんみゃくから ことばの いみを かんがえなさい。', 'Hãy suy ra nghĩa của từ từ ngữ cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6997, 47906, '祖母は大阪の方言で話す。', 'そぼは おおさかの ほうげんで はなす。', 'Bà tôi nói giọng địa phương Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6998, 47895, '姉は芸能のニュースに詳しい。', 'あねは げいのうの ニュースに くわしい。', 'Chị tôi rành tin tức giới giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (6999, 47892, '小学生のころ、書道を習っていた。', 'しょうがくせいの ころ、しょどうを ならって いた。', 'Hồi tiểu học tôi từng học thư pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7000, 47936, '彼の表情から気持ちを推測した。', 'かれの ひょうじょうから きもちを すいそく した。', 'Tôi đoán tâm trạng anh ấy qua nét mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7001, 47938, '実験の結果について考察した。', 'じっけんの けっかに ついて こうさつ した。', 'Tôi đã suy xét về kết quả thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7002, 47942, '彼の意見にも一理ある。', 'かれの いけんにも いちり ある。', 'Ý kiến của anh ấy cũng có lý phần nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7003, 47943, 'この計画の妥当性を検討する。', 'この けいかくの だとうせいを けんとう する。', 'Chúng tôi xem xét tính hợp lý của kế hoạch này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7004, 47946, 'この絵は抽象的でよくわからない。', 'この えは ちゅうしょうてきで よく わからない。', 'Bức tranh này trừu tượng, tôi không hiểu lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7005, 47888, 'この地方には河童の伝承がある。', 'この ちほうには かっぱの でんしょうが ある。', 'Vùng này lưu truyền truyền thuyết về thủy quái Kappa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7006, 47891, '週末に陶芸教室に通っている。', 'しゅうまつに とうげい きょうしつに かよって いる。', 'Cuối tuần tôi đi học lớp làm gốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7007, 47899, 'この言葉の語源はポルトガル語だ。', 'この ことばの ごげんは ポルトガルごだ。', 'Từ này có nguồn gốc từ tiếng Bồ Đào Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7008, 47903, 'この詩には美しい比喩が使われている。', 'この しには うつくしい ひゆが つかわれて いる。', 'Bài thơ này sử dụng những ẩn dụ đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7009, 47907, 'ニュースでは標準語が使われる。', 'ニュースでは ひょうじゅんごが つかわれる。', 'Trên bản tin người ta dùng tiếng chuẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7010, 47909, '古い法律は文語で書かれている。', 'ふるい ほうりつは ぶんごで かかれて いる。', 'Luật cũ được viết bằng văn ngôn cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7011, 47964, 'あえて難しい道を選んだ。', 'あえて むずかしい みちを えらんだ。', 'Tôi cố tình chọn con đường khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7012, 47965, '彼は天才というより、むしろ努力家だ。', 'かれは てんさいと いうより、むしろ どりょくかだ。', 'Anh ấy không hẳn là thiên tài mà đúng hơn là người chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7013, 47969, '彼は家庭を顧みずに働き続けた。', 'かれは かていを かえりみずに はたらき つづけた。', 'Anh ấy làm việc liên tục mà chẳng đoái hoài đến gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7014, 47971, '前回の反省を踏まえて、計画を立てた。', 'ぜんかいの はんせいを ふまえて、けいかくを たてた。', 'Chúng tôi lập kế hoạch dựa trên bài học lần trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7015, 47974, '彼は仕事に生きがいを見出した。', 'かれは しごとに いきがいを みいだした。', 'Anh ấy tìm ra lẽ sống trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7016, 47976, '新しい発見が従来の定説を覆した。', 'あたらしい はっけんが じゅうらいの ていせつを くつがえした。', 'Phát hiện mới đã lật đổ học thuyết vốn có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7017, 47978, '自分の行動を省みて、反省した。', 'じぶんの こうどうを かえりみて、はんせい した。', 'Tôi tự xét lại hành động của mình và kiểm điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7018, 47983, '画一的な教育では個性が育たない。', 'かくいつてきな きょういくでは こせいが そだたない。', 'Giáo dục rập khuôn thì cá tính không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7019, 47986, '将来に漠然とした不安を感じている。', 'しょうらいに ばくぜんと した ふあんを かんじて いる。', 'Tôi cảm thấy lo lắng mơ hồ về tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7020, 47960, '彼はうわさを強く否定した。', 'かれは うわさを つよく ひてい した。', 'Anh ấy kịch liệt phủ nhận tin đồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7021, 47991, '新しい販売戦略を考えた。', 'あたらしい はんばい せんりゃくを かんがえた。', 'Chúng tôi đã nghĩ ra chiến lược bán hàng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7022, 47998, '日本の会社と海外の会社が提携した。', 'にほんの かいしゃと かいがいの かいしゃが ていけい した。', 'Một công ty Nhật và một công ty nước ngoài đã liên kết với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7023, 47996, '二つの銀行が合併して、一つになった。', 'ふたつの ぎんこうが がっぺい して、ひとつに なった。', 'Hai ngân hàng sáp nhập thành một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7024, 48002, '商品は来週の月曜日に納品します。', 'しょうひんは らいしゅうの げつようびに のうひん します。', 'Hàng sẽ được giao vào thứ Hai tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7025, 47985, 'もっと合理的な方法があるはずだ。', 'もっと ごうりてきな ほうほうが ある はずだ。', 'Chắc chắn có cách hợp lý hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7026, 47990, '経営者は社員の生活を守る責任がある。', 'けいえいしゃは しゃいんの せいかつを まもる せきにんが ある。', 'Người quản lý có trách nhiệm bảo vệ đời sống nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7027, 47994, '多くの企業がこの市場に参入した。', 'おおくの きぎょうが この しじょうに さんにゅう した。', 'Nhiều doanh nghiệp đã gia nhập thị trường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7028, 47999, '商品の配送を外部に委託している。', 'しょうひんの はいそうを がいぶに いたく して いる。', 'Việc giao hàng được ủy thác cho bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7029, 48004, '新しい事業が大きな収益を上げた。', 'あたらしい じぎょうが おおきな しゅうえきを あげた。', 'Mảng kinh doanh mới đã mang lại lợi nhuận lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7030, 48006, '店は三年間赤字経営が続いている。', 'みせは さんねんかん あかじ けいえいが つづいて いる。', 'Cửa hàng đã kinh doanh thua lỗ suốt ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7031, 48008, '人件費が経営を圧迫している。', 'じんけんひが けいえいを あっぱく して いる。', 'Chi phí nhân sự đang gây áp lực lên việc kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7032, 48010, '景気の見通しは明るい。', 'けいきの みとおしは あかるい。', 'Triển vọng kinh tế rất sáng sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7033, 48014, '業界の再編が進んでいる。', 'ぎょうかいの さいへんが すすんで いる。', 'Ngành đang được tái cơ cấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7034, 48015, '二つの部署が統合された。', 'ふたつの ぶしょが とうごう された。', 'Hai phòng ban đã được hợp nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7035, 48018, 'この件は部長の決裁が必要だ。', 'この けんは ぶちょうの けっさいが ひつようだ。', 'Việc này cần trưởng phòng phê duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7036, 48021, '彼は営業部長と企画部長を兼任している。', 'かれは えいぎょう ぶちょうと きかく ぶちょうを けんにん して いる。', 'Anh ấy kiêm nhiệm trưởng phòng kinh doanh và trưởng phòng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7037, 48024, '不景気で多くの社員が解雇された。', 'ふけいきで おおくの しゃいんが かいこ された。', 'Do suy thoái, nhiều nhân viên đã bị sa thải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7038, 48027, '彼は退職後、会社の顧問になった。', 'かれは たいしょくご、かいしゃの こもんに なった。', 'Sau khi nghỉ hưu ông ấy trở thành cố vấn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7039, 48017, 'この件を決める権限は部長にある。', 'この けんを きめる けんげんは ぶちょうに ある。', 'Quyền quyết định việc này thuộc về trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7040, 48059, '被害者は会社を相手に訴訟を起こした。', 'ひがいしゃは かいしゃを あいてに そしょうを おこした。', 'Người bị hại đã khởi kiện công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7041, 48049, '新聞社が世論調査を行った。', 'しんぶんしゃが よろん ちょうさを おこなった。', 'Tòa báo đã tiến hành khảo sát dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7042, 48029, '友人の新しい事業に出資した。', 'ゆうじんの あたらしい じぎょうに しゅっし した。', 'Tôi đã góp vốn vào công việc kinh doanh mới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7043, 48031, 'その銀行は経営が破綻した。', 'その ぎんこうは けいえいが はたん した。', 'Ngân hàng đó đã đổ vỡ kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7044, 48034, '視聴率が低く、番組は打ち切られた。', 'しちょうりつが ひくく、ばんぐみは うちきられた。', 'Tỷ lệ người xem thấp nên chương trình đã bị dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7045, 48036, 'アルバイトで生活費を賄っている。', 'アルバイトで せいかつひを まかなって いる。', 'Tôi trang trải sinh hoạt phí bằng việc làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7046, 48038, '若者が国の未来を担っている。', 'わかものが くにの みらいを になって いる。', 'Giới trẻ đang gánh vác tương lai đất nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7047, 48040, '今年は売り上げの増加が見込まれる。', 'ことしは うりあげの ぞうかが みこまれる。', 'Năm nay dự tính doanh thu sẽ tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7048, 48042, '彼は大手のメーカーに就職した。', 'かれは おおての メーカーに しゅうしょく した。', 'Anh ấy vào làm ở một nhà sản xuất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7049, 48044, '状況に応じて柔軟に対応しよう。', 'じょうきょうに おうじて じゅうなんに たいおう しよう。', 'Hãy ứng phó linh hoạt tùy theo tình hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7050, 48047, 'この問題は慎重に扱う必要がある。', 'この もんだいは しんちょうに あつかう ひつようが ある。', 'Vấn đề này cần được xử lý thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7051, 48051, '新しい内閣が発足した。', 'あたらしい ないかくが ほっそく した。', 'Nội các mới đã được thành lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7052, 48053, '官僚の天下りが問題になっている。', 'かんりょうの あまくだりが もんだいに なって いる。', 'Việc quan chức nghỉ hưu chuyển sang doanh nghiệp đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7053, 48056, '会社の不祥事が相次いでいる。', 'かいしゃの ふしょうじが あいついで いる。', 'Các vụ bê bối của công ty liên tiếp xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7054, 48058, '社員が会社の不正を告発した。', 'しゃいんが かいしゃの ふせいを こくはつ した。', 'Một nhân viên đã tố giác hành vi gian lận của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7055, 48062, '社会の規範を守ることが求められる。', 'しゃかいの きはんを まもる ことが もとめられる。', 'Cần tuân thủ chuẩn mực xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7056, 48065, '警察は治安維持に努めている。', 'けいさつは ちあん いじに つとめて いる。', 'Cảnh sát đang nỗ lực giữ gìn an ninh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7057, 48067, '都市の過密が問題になっている。', 'としの かみつが もんだいに なって いる。', 'Tình trạng quá đông đúc ở thành phố đang là vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7058, 48070, '動物の虐待は許されない。', 'どうぶつの ぎゃくたいは ゆるされない。', 'Ngược đãi động vật là không thể chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7059, 48076, 'この国は多くの移民を受け入れている。', 'この くには おおくの いみんを うけいれて いる。', 'Đất nước này tiếp nhận nhiều người di cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7060, 48078, '会議は予算をめぐって紛糾した。', 'かいぎは よさんを めぐって ふんきゅう した。', 'Cuộc họp trở nên rối ren xung quanh vấn đề ngân sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7061, 48090, '男女の賃金格差を是正すべきだ。', 'だんじょの ちんぎん かくさを ぜせい すべきだ。', 'Cần điều chỉnh chênh lệch tiền lương giữa nam và nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7062, 48096, '今年は売り上げの増加が顕著だ。', 'ことしは うりあげの ぞうかが けんちょだ。', 'Năm nay doanh thu tăng rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7063, 48115, '月曜日の朝はいつも憂鬱だ。', 'げつようびの あさは いつも ゆううつだ。', 'Sáng thứ Hai lúc nào cũng u uất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7064, 48123, '別れた恋人にまだ未練がある。', 'わかれた こいびとに まだ みれんが ある。', 'Tôi vẫn còn lưu luyến người yêu cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7065, 48081, '選挙の結果に不満を持つ人々が暴動を起こした。', 'せんきょの けっかに ふまんを もつ ひとびとが ぼうどうを おこした。', 'Những người bất mãn với kết quả bầu cử đã gây bạo động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7066, 48088, '被災地に義援金を送った。', 'ひさいちに ぎえんきんを おくった。', 'Tôi đã gửi tiền cứu trợ đến vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7067, 48095, '円安の影響が様々な業界に波及している。', 'えんやすの えいきょうが さまざまな ぎょうかいに はきゅう して いる。', 'Ảnh hưởng của đồng yên yếu đang lan rộng sang nhiều ngành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7068, 48087, '被災地にお金を寄付した。', 'ひさいちに おかねを きふ した。', 'Tôi đã quyên góp tiền cho vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7069, 48128, '彼は「まだまだです」と謙遜した。', 'かれは 「まだまだ です」と けんそん した。', 'Anh ấy khiêm tốn nói "tôi còn kém lắm".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7070, 48131, '彼は大胆な計画を発表した。', 'かれは だいたんな けいかくを はっぴょう した。', 'Anh ấy công bố một kế hoạch táo bạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7071, 48080, '小さなうわさが大きな騒動になった。', 'ちいさな うわさが おおきな そうどうに なった。', 'Một tin đồn nhỏ đã thành vụ náo loạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7072, 48091, '政府は規制を緩和した。', 'せいふは きせいを かんわ した。', 'Chính phủ đã nới lỏng các quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7073, 48077, 'この会社にはいろいろな国籍の社員がいる。', 'この かいしゃには いろいろな こくせきの しゃいんが いる。', 'Công ty này có nhân viên mang nhiều quốc tịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7074, 48098, '住民の切実な声に耳を傾けるべきだ。', 'じゅうみんの せつじつな こえに みみを かたむける べきだ。', 'Cần lắng nghe tiếng nói bức thiết của người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7075, 48101, '大臣の発言が物議を醸した。', 'だいじんの はつげんが ぶつぎを かもした。', 'Phát ngôn của bộ trưởng đã gây xôn xao dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7076, 48103, '温暖化が多くの生物を脅かしている。', 'おんだんかが おおくの せいぶつを おびやかして いる。', 'Hiện tượng ấm lên đang đe dọa nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7077, 48106, '会社は経営難に陥った。', 'かいしゃは けいえいなんに おちいった。', 'Công ty rơi vào khó khăn kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7078, 48109, '引退を決めた今の心境を聞かせてください。', 'いんたいを きめた いまの しんきょうを きかせて ください。', 'Hãy cho tôi biết tâm trạng của anh lúc quyết định giải nghệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7079, 48113, '新しい環境に戸惑いを感じている。', 'あたらしい かんきょうに とまどいを かんじて いる。', 'Tôi cảm thấy lúng túng với môi trường mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7151, 45560, 'インターネットで旅行の情報を集めた。', 'インターネットで りょこうの じょうほうを あつめた。', 'Tôi thu thập thông tin du lịch trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7080, 48118, '人を見下して優越感に浸るのはよくない。', 'ひとを みくだして ゆうえつかんに ひたるのは よくない。', 'Coi thường người khác để thấy mình hơn người là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7081, 48121, '不公平な扱いに強い憤りを感じた。', 'ふこうへいな あつかいに つよい いきどおりを かんじた。', 'Tôi cảm thấy phẫn nộ trước sự đối xử bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7082, 48126, '古い写真を見て、郷愁にかられた。', 'ふるい しゃしんを みて、きょうしゅうに かられた。', 'Nhìn bức ảnh cũ, nỗi nhớ quê dâng trào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7083, 48130, '臆病な性格を直したい。', 'おくびょうな せいかくを なおしたい。', 'Tôi muốn sửa tính nhút nhát của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7084, 48164, '彼は合格のためにひたすら勉強した。', 'かれは ごうかくの ために ひたすら べんきょう した。', 'Anh ấy chỉ một mực học để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7085, 48132, '子供の無邪気な笑顔に癒される。', 'こどもの むじゃきな えがおに いやされる。', 'Nụ cười hồn nhiên của trẻ con khiến tôi thấy thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7086, 48135, '彼の考えに深く共感した。', 'かれの かんがえに ふかく きょうかん した。', 'Tôi đồng cảm sâu sắc với suy nghĩ của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7087, 48137, '子供たちの歌声に心が和んだ。', 'こどもたちの うたごえに こころが なごんだ。', 'Tiếng hát của bọn trẻ làm lòng tôi dịu lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7088, 48140, '彼は自分の不運を嘆いた。', 'かれは じぶんの ふうんを なげいた。', 'Anh ấy than thở về vận rủi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7089, 48142, '急に質問されて戸惑った。', 'きゅうに しつもん されて とまどった。', 'Bị hỏi đột ngột nên tôi lúng túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7090, 48144, '渋滞で運転手が苛立っている。', 'じゅうたいで うんてんしゅが いらだって いる。', 'Tắc đường làm tài xế bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7091, 48146, '彼女に本当のことを言うのをためらった。', 'かのじょに ほんとうの ことを いうのを ためらった。', 'Tôi do dự không dám nói thật với cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7092, 48189, '彼は医学の分野で活躍している。', 'かれは いがくの ぶんやで かつやく して いる。', 'Anh ấy hoạt động tích cực trong lĩnh vực y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7093, 48177, 'データを使って仮説を検証した。', 'データを つかって かせつを けんしょう した。', 'Chúng tôi dùng dữ liệu để kiểm chứng giả thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7094, 48171, '飛行機が飛ぶ原理を説明してください。', 'ひこうきが とぶ げんりを せつめい して ください。', 'Hãy giải thích nguyên lý máy bay bay được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7095, 48176, '博物館で昆虫の標本を見た。', 'はくぶつかんで こんちゅうの ひょうほんを みた。', 'Tôi xem mẫu vật côn trùng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7096, 48161, '親のありがたさをしみじみ感じた。', 'おやの ありがたさを しみじみ かんじた。', 'Tôi thấm thía công ơn của cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7097, 48149, '一人で思い詰めないで、相談してください。', 'ひとりで おもいつめないで、そうだん して ください。', 'Đừng một mình nghĩ quẩn, hãy tâm sự với tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7098, 48151, '別れの場面は切なかった。', 'わかれの ばめんは せつなかった。', 'Cảnh chia ly thật da diết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7099, 48153, '言いたいことが日本語でうまく言えなくて、もどかしい。', 'いいたい ことが にほんごで うまく いえなくて、もどかしい。', 'Không nói được điều muốn nói bằng tiếng Nhật, thật bứt rứt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7100, 48157, '手伝ってもらえるのは本当にありがたい。', 'てつだって もらえるのは ほんとうに ありがたい。', 'Được giúp đỡ thật là quý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7101, 48159, '病気の母を支える少女の姿が健気だ。', 'びょうきの ははを ささえる しょうじょの すがたが けなげだ。', 'Hình ảnh cô bé chăm sóc mẹ ốm thật đáng khen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7102, 48162, '親のありがたさをつくづく感じた。', 'おやの ありがたさを つくづく かんじた。', 'Tôi thấm thía công ơn cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7103, 48165, '母に言われて、しぶしぶ宿題をした。', 'ははに いわれて、しぶしぶ しゅくだいを した。', 'Bị mẹ nhắc, tôi miễn cưỡng làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7104, 48168, '過ぎたことをくよくよしても仕方がない。', 'すぎた ことを くよくよ しても しかたが ない。', 'Ủ ê vì chuyện đã qua cũng chẳng ích gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7105, 48174, '検査の数値が正常に戻った。', 'けんさの すうちが せいじょうに もどった。', 'Chỉ số xét nghiệm đã trở lại bình thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7106, 48180, '警察は事件の真相を究明している。', 'けいさつは じけんの しんそうを きゅうめい して いる。', 'Cảnh sát đang điều tra làm rõ sự thật vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7107, 48185, '彼は新しい遊びを考案した。', 'かれは あたらしい あそびを こうあん した。', 'Anh ấy đã nghĩ ra một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7108, 48187, 'この研究から新たな知見が得られた。', 'この けんきゅうから あらたな ちけんが えられた。', 'Từ nghiên cứu này đã thu được những hiểu biết mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7109, 48204, '両国の間で貿易摩擦が起きている。', 'りょうこくの あいだで ぼうえき まさつが おきて いる。', 'Giữa hai nước đang xảy ra xích mích thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7110, 48206, '寒さで筋肉が収縮する。', 'さむさで きんにくが しゅうしゅく する。', 'Cơ bắp co lại vì lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7111, 48226, '彼は緻密な計画を立てた。', 'かれは ちみつな けいかくを たてた。', 'Anh ấy đã lập một kế hoạch chặt chẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7112, 48246, '古い慣習を見直す時期に来ている。', 'ふるい かんしゅうを みなおす じきに きて いる。', 'Đã đến lúc xem xét lại những tập quán cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7113, 48192, '遺伝子の研究が進んでいる。', 'いでんしの けんきゅうが すすんで いる。', 'Nghiên cứu về gen đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7114, 48195, '土の中には多くの微生物がいる。', 'つちの なかには おおくの びせいぶつが いる。', 'Trong đất có rất nhiều vi sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7115, 48232, '現代の若者はスマホなしでは生活できない。', 'げんだいの わかものは スマホ なしでは せいかつ できない。', 'Giới trẻ ngày nay không thể sống thiếu điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7116, 48235, '天皇の誕生日は祝日だ。', 'てんのうの たんじょうびは しゅくじつだ。', 'Sinh nhật Nhật hoàng là ngày lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7117, 48227, '膨大な資料を一人で整理した。', 'ぼうだいな しりょうを ひとりで せいり した。', 'Tôi một mình sắp xếp lượng tài liệu đồ sộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7118, 48236, '昔の武士は刀を持っていた。', 'むかしの ぶしは かたなを もって いた。', 'Võ sĩ ngày xưa mang kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7119, 48197, '新しい元素が発見された。', 'あたらしい げんそが はっけん された。', 'Một nguyên tố mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7120, 48198, '水の分子は小さい。', 'みずの ぶんしは ちいさい。', 'Phân tử nước rất nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7121, 48203, '人工衛星が軌道に乗った。', 'じんこう えいせいが きどうに のった。', 'Vệ tinh nhân tạo đã vào quỹ đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7122, 48210, '植物から香りの成分を抽出する。', 'しょくぶつから かおりの せいぶんを ちゅうしゅつ する。', 'Chiết xuất thành phần hương thơm từ thực vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7123, 48212, 'この機械は精度が高い。', 'この きかいは せいどが たかい。', 'Máy này có độ chính xác cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7124, 48214, 'このクラスの男女の比率は半々だ。', 'この クラスの だんじょの ひりつは はんはんだ。', 'Tỷ lệ nam nữ của lớp này là một nửa mỗi bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7125, 48217, '愛は人類に普遍的なテーマだ。', 'あいは じんるいに ふへんてきな テーマだ。', 'Tình yêu là chủ đề phổ quát của nhân loại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7126, 48220, '新しい国際協力の枠組みが作られた。', 'あたらしい こくさい きょうりょくの わくぐみが つくられた。', 'Một khuôn khổ hợp tác quốc tế mới đã được xây dựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7127, 48223, '彼は茶道の道を究めた。', 'かれは さどうの みちを きわめた。', 'Ông ấy đã đạt đến tận cùng con đường trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7128, 48225, '宇宙の謎を解き明かしたい。', 'うちゅうの なぞを ときあかしたい。', 'Tôi muốn giải đáp những bí ẩn của vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7129, 48229, '古代エジプトの文明に興味がある。', 'こだい エジプトの ぶんめいに きょうみが ある。', 'Tôi quan tâm đến nền văn minh Ai Cập cổ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7130, 48234, 'この寺は平安王朝の時代に建てられた。', 'この てらは へいあん おうちょうの じだいに たてられた。', 'Ngôi chùa này được xây vào thời triều đại Heian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7131, 48239, '江戸時代、日本は鎖国をしていた。', 'えど じだい、にほんは さこくを して いた。', 'Thời Edo, Nhật Bản thực hiện bế quan tỏa cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7132, 48241, '明治維新で日本は近代化した。', 'めいじ いしんで にほんは きんだいか した。', 'Nhờ Minh Trị Duy Tân, Nhật Bản đã hiện đại hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7133, 48244, '日本語の変遷について研究している。', 'にほんごの へんせんに ついて けんきゅう して いる。', 'Tôi đang nghiên cứu về sự biến thiên của tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7134, 48248, 'この地方には河童の伝承がある。', 'この ちほうには かっぱの でんしょうが ある。', 'Vùng này lưu truyền truyền thuyết về thủy quái Kappa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7135, 48265, 'このことわざの意味を知っていますか。', 'この ことわざの いみを しって いますか。', 'Bạn có biết ý nghĩa câu tục ngữ này không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7136, 48251, '週末に陶芸教室に通っている。', 'しゅうまつに とうげい きょうしつに かよって いる。', 'Cuối tuần tôi đi học lớp làm gốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7137, 48257, '昔の貴族は和歌を詠んで気持ちを伝えた。', 'むかしの きぞくは わかを よんで きもちを つたえた。', 'Quý tộc ngày xưa làm thơ waka để bày tỏ tình cảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7138, 48260, '本を読んで語彙を増やしたい。', 'ほんを よんで ごいを ふやしたい。', 'Tôi muốn đọc sách để tăng vốn từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7139, 45531, '東京の人口は千四百万人ぐらいだ。', 'とうきょうの じんこうは せんよんひゃくまんにん ぐらいだ。', 'Dân số Tokyo khoảng mười bốn triệu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7140, 45533, '日本では高齢化が進んでいる。', 'にほんでは こうれいかが すすんで いる。', 'Ở Nhật, dân số đang ngày càng già hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7141, 45534, '来月、市長の選挙がある。', 'らいげつ、しちょうの せんきょが ある。', 'Tháng sau có bầu cử thị trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7142, 45539, '誰にでも意見を言う権利がある。', 'だれにでも いけんを いう けんりが ある。', 'Ai cũng có quyền nêu ý kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7143, 45541, '世界の平和を願っています。', 'せかいの へいわを ねがって います。', 'Tôi mong thế giới hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7144, 45545, '警察は犯人を探している。', 'けいさつは はんにんを さがして いる。', 'Cảnh sát đang truy tìm thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7145, 45548, '台風で農作物に大きな被害が出た。', 'たいふうで のうさくもつに おおきな ひがいが でた。', 'Bão gây thiệt hại lớn cho hoa màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7146, 45549, '災害のときのために、水と食料を用意しておこう。', 'さいがいの ときの ために、みずと しょくりょうを ようい して おこう。', 'Hãy chuẩn bị sẵn nước và lương thực phòng khi thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7147, 45551, '事故の原因はまだわかっていない。', 'じこの げんいんは まだ わかって いない。', 'Nguyên nhân tai nạn vẫn chưa rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7148, 45553, '台風の影響で、電車が止まった。', 'たいふうの えいきょうで、でんしゃが とまった。', 'Do ảnh hưởng của bão, tàu điện ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7149, 45556, '暑さ対策に帽子をかぶっている。', 'あつさ たいさくに ぼうしを かぶって いる。', 'Tôi đội mũ để chống nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7150, 45557, '市が住民の生活について調査している。', 'しが じゅうみんの せいかつに ついて ちょうさ して いる。', 'Thành phố đang khảo sát về đời sống người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7152, 45562, '世論は新しい法律に反対している。', 'よろんは あたらしい ほうりつに はんたい して いる。', 'Dư luận phản đối luật mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7153, 45564, 'この町には外国人がたくさん住んでいる。', 'この まちには がいこくじんが たくさん すんで いる。', 'Thị trấn này có nhiều người nước ngoài sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7154, 45570, '不景気で給料が下がった。', 'ふけいきで きゅうりょうが さがった。', 'Kinh tế suy thoái nên lương bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7155, 48266, '祖母は大阪の方言で話す。', 'そぼは おおさかの ほうげんで はなす。', 'Bà tôi nói giọng địa phương Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7156, 48256, '高校で日本の古典を勉強した。', 'こうこうで にほんの こてんを べんきょう した。', 'Ở cấp ba tôi học văn học cổ điển Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7157, 48258, '授業で季節の俳句を作った。', 'じゅぎょうで きせつの はいくを つくった。', 'Trong giờ học chúng tôi làm thơ haiku về mùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7158, 48267, 'ニュースでは標準語が使われる。', 'ニュースでは ひょうじゅんごが つかわれる。', 'Trên bản tin người ta dùng tiếng chuẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7159, 48269, '古い法律は文語で書かれている。', 'ふるい ほうりつは ぶんごで かかれて いる。', 'Luật cũ được viết bằng văn ngôn cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7160, 27106, 'これを見せてください。', 'これをみせてください。', 'Cho tôi xem cái này với.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7161, 45573, '両親は私の留学に反対した。', 'りょうしんは わたしの りゅうがくに はんたい した。', 'Bố mẹ phản đối việc tôi đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7162, 45575, 'その問題について議論が続いている。', 'その もんだいに ついて ぎろんが つづいて いる。', 'Cuộc tranh luận về vấn đề đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7163, 45577, '外国人観光客が増加している。', 'がいこくじん かんこうきゃくが ぞうか して いる。', 'Khách du lịch nước ngoài đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7164, 45580, '何が起こったのか、教えてください。', 'なにが おこったのか、おしえて ください。', 'Hãy cho tôi biết chuyện gì đã xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7165, 45582, '泥棒は窓から逃げた。', 'どろぼうは まどから にげた。', 'Tên trộm chạy trốn qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7166, 45584, '彼はけがの痛みを医者に訴えた。', 'かれは けがの いたみを いしゃに うったえた。', 'Anh ấy than với bác sĩ về cơn đau do vết thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7167, 45586, '先生はすべての学生に公平だ。', 'せんせいは すべての がくせいに こうへいだ。', 'Thầy giáo công bằng với mọi học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7168, 45587, '日本では、家に入るとき靴を脱ぐのが一般的だ。', 'にほんでは、いえに はいる とき くつを ぬぐのが いっぱんてきだ。', 'Ở Nhật, cởi giày khi vào nhà là chuyện thông thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7169, 45593, '数学のテストで百点を取った。', 'すうがくの テストで ひゃくてんを とった。', 'Tôi được một trăm điểm bài kiểm tra toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7170, 45595, 'この町には長い歴史がある。', 'この まちには ながい れきしが ある。', 'Thị trấn này có lịch sử lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7171, 45596, 'この辺りの地理に詳しいですか。', 'この あたりの ちりに くわしい ですか。', 'Bạn có rành đường sá quanh đây không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7172, 45598, '大学で哲学を専攻した。', 'だいがくで てつがくを せんこう した。', 'Tôi học chuyên ngành triết học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7173, 45599, '大学で心理学の授業を取っている。', 'だいがくで しんりがくの じゅぎょうを とって いる。', 'Tôi đang học môn tâm lý học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7174, 45601, '今日の講義はとてもわかりやすかった。', 'きょうの こうぎは とても わかりやすかった。', 'Bài giảng hôm nay rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7175, 45604, '週末までに課題を出さなければならない。', 'しゅうまつまでに かだいを ださなければ ならない。', 'Tôi phải nộp bài tập trước cuối tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7176, 45606, 'テストの点数が思ったより悪かった。', 'テストの てんすうが おもったより わるかった。', 'Điểm bài kiểm tra tệ hơn tôi nghĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7177, 45607, '試験に合格して、とてもうれしい。', 'しけんに ごうかく して、とても うれしい。', 'Thi đỗ rồi, tôi vui lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7178, 45609, '四月に大学に入学した。', 'しがつに だいがくに にゅうがく した。', 'Tôi nhập học đại học vào tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7179, 45611, '兄は今年、大学を受験する。', 'あには ことし、だいがくを じゅけん する。', 'Năm nay anh tôi thi đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7180, 45614, 'アルバイトをして学費を払っている。', 'アルバイトを して がくひを はらって いる。', 'Tôi làm thêm để trả học phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7181, 45615, '校長先生が入学式でスピーチをした。', 'こうちょう せんせいが にゅうがくしきで スピーチを した。', 'Thầy hiệu trưởng phát biểu trong lễ khai giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7182, 45618, '駅で小学校の同級生に会った。', 'えきで しょうがっこうの どうきゅうせいに あった。', 'Tôi gặp bạn cùng lớp tiểu học ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7183, 45636, 'この問題の正解は三番です。', 'この もんだいの せいかいは さんばん です。', 'Đáp án đúng của câu này là số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7184, 45637, '名前の書き方に間違いがあった。', 'なまえの かきかたに まちがいが あった。', 'Cách viết tên có chỗ bị sai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7185, 45639, '失敗から学ぶことは多い。', 'しっぱいから まなぶ ことは おおい。', 'Có nhiều điều học được từ thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7186, 45641, 'この問題を十分で解いてください。', 'この もんだいを じゅっぷんで といて ください。', 'Hãy giải bài này trong mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7187, 28603, '田中さんに、会議は三時からだと伝えてください。', 'たなかさんに、かいぎは さんじから だと つたえて ください。', 'Hãy nhắn anh Tanaka rằng cuộc họp bắt đầu từ ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7188, 45643, '仕事を通して多くの経験を得た。', 'しごとを とおして おおくの けいけんを えた。', 'Qua công việc tôi đã có thêm nhiều kinh nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7189, 45645, '学生たちは熱心に先生の話を聞いている。', 'がくせいたちは ねっしんに せんせいの はなしを きいて いる。', 'Các học sinh đang chăm chú nghe thầy giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7190, 45650, '毎月家計簿をつけている。', 'まいつき かけいぼを つけて いる。', 'Tháng nào tôi cũng ghi sổ chi tiêu gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7191, 45655, 'すみません、領収書をください。', 'すみません、りょうしゅうしょを ください。', 'Xin lỗi, cho tôi xin hóa đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7192, 45658, 'その商品は在庫がありません。', 'その しょうひんは ざいこが ありません。', 'Mặt hàng đó đã hết hàng trong kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7193, 45665, 'このパソコンは一年間の保証がついている。', 'この パソコンは いちねんかんの ほしょうが ついて いる。', 'Máy tính này được bảo hành một năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7194, 45667, '引っ越しで新しい家具を買った。', 'ひっこしで あたらしい かぐを かった。', 'Chuyển nhà nên tôi mua đồ nội thất mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7195, 45669, 'この店では外国の食品も買える。', 'この みせでは がいこくの しょくひんも かえる。', 'Ở cửa hàng này cũng mua được thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7196, 45672, '毎日の献立を考えるのは大変だ。', 'まいにちの こんだてを かんがえるのは たいへんだ。', 'Nghĩ thực đơn mỗi ngày thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7197, 45673, '忙しくて、外食が多くなった。', 'いそがしくて、がいしょくが おおく なった。', 'Bận quá nên tôi ăn ngoài nhiều hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7198, 45675, '夫婦で家事を分担している。', 'ふうふで かじを ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7199, 45678, '工事の騒音で眠れない。', 'こうじの そうおんで ねむれない。', 'Tiếng ồn công trình khiến tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7200, 45681, 'エアコンを使いすぎて、電気代が高くなった。', 'エアコンを つかいすぎて、でんきだいが たかく なった。', 'Dùng điều hòa nhiều quá nên tiền điện tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7201, 45683, '契約書をよく読んでからサインしてください。', 'けいやくしょを よく よんでから サイン して ください。', 'Hãy đọc kỹ hợp đồng rồi mới ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7202, 45685, '日本語のスピーチ大会に申し込んだ。', 'にほんごの スピーチ たいかいに もうしこんだ。', 'Tôi đã đăng ký cuộc thi hùng biện tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7203, 45688, '役所で住民票をもらった。', 'やくしょで じゅうみんひょうを もらった。', 'Tôi lấy giấy chứng nhận cư trú ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7204, 45690, 'ホテルのフロントに荷物を預けた。', 'ホテルの フロントに にもつを あずけた。', 'Tôi gửi hành lý ở quầy lễ tân khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7205, 45692, 'ATMでお金を引き出した。', 'エーティーエムで おかねを ひきだした。', 'Tôi rút tiền ở cây ATM.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7206, 45694, '新しいパソコンを買うためにお金を貯めている。', 'あたらしい パソコンを かう ために おかねを ためて いる。', 'Tôi đang để dành tiền mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7207, 45696, '料理が余ったので、近所に分けた。', 'りょうりが あまったので、きんじょに わけた。', 'Đồ ăn còn thừa nên tôi chia cho hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7208, 27828, '三番のバスに乗ってください。', 'さんばんの バスに のって ください。', 'Hãy đi xe buýt số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7209, 28618, 'このトイレは使用禁止です。', 'この トイレは しよう きんし です。', 'Nhà vệ sinh này cấm sử dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7210, 29310, '妻とは大学で知り合いました。', 'つまとは だいがくで しりあいました。', 'Tôi quen vợ ở trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7211, 29459, '風が吹きます。', 'かぜがふきます。', '[gió] thổi', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7212, 27651, 'わあ、すごい人ですね。', 'わあ、すごいひとですね。', 'Ôi! Đông người quá!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7213, 27887, '本が痛いです。', 'ほんがいたいです。', '(Tôi) bị đau [～].', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7214, 45697, '計算が間違っていたので、もう一度やり直した。', 'けいさんが まちがって いたので、もう いちど やりなおした。', 'Tính sai nên tôi làm lại lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7215, 45699, 'お弁当におかずを詰めた。', 'おべんとうに おかずを つめた。', 'Tôi xếp thức ăn vào hộp cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7216, 45702, 'コンビニは便利だが、少し割高だ。', 'コンビニは べんりだが、すこし わりだかだ。', 'Cửa hàng tiện lợi thì tiện nhưng hơi đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7217, 45707, 'なるほど、そういうことだったのか。', 'なるほど、そういう こと だったのか。', 'Ra là vậy, hóa ra là chuyện như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7218, 45708, 'せっかく作ったのに、誰も食べてくれなかった。', 'せっかく つくったのに、だれも たべて くれなかった。', 'Đã mất công nấu mà chẳng ai ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7219, 45711, '雪の日は運転に気をつけてください。', 'ゆきの ひは うんてんに きを つけて ください。', 'Ngày tuyết rơi hãy cẩn thận khi lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7220, 45714, 'バスの運賃は降りるときに払います。', 'バスの うんちんは おりる ときに はらいます。', 'Tiền vé xe buýt trả khi xuống xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7221, 45715, '家から会社まで往復二時間かかる。', 'いえから かいしゃまで おうふく にじかん かかる。', 'Đi về giữa nhà và công ty mất hai tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7222, 45717, '新宿で乗り換えがあります。', 'しんじゅくで のりかえが あります。', 'Phải chuyển tàu ở Shinjuku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7223, 45719, '飛行機は予定通りに到着した。', 'ひこうきは よていどおりに とうちゃく した。', 'Máy bay đã đến đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7224, 45721, 'バスの行き先を確認してから乗ってください。', 'バスの いきさきを かくにん してから のって ください。', 'Hãy kiểm tra điểm đến của xe buýt rồi mới lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7225, 45723, '京都の名所を案内してもらった。', 'きょうとの めいしょを あんない して もらった。', 'Tôi được dẫn đi thăm các danh thắng ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7335, 45892, '少子化で学校の数が減っている。', 'しょうしかで がっこうの かずが へって いる。', 'Do tỷ lệ sinh giảm, số trường học đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7226, 45726, '週末に温泉に行って、ゆっくり休んだ。', 'しゅうまつに おんせんに いって、ゆっくり やすんだ。', 'Cuối tuần tôi đi suối nước nóng và nghỉ ngơi thong thả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7227, 45728, '空港の税関で荷物を調べられた。', 'くうこうの ぜいかんで にもつを しらべられた。', 'Hành lý của tôi bị kiểm tra ở hải quan sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7228, 27098, 'このネクタイは三千円です。', 'この ネクタイは さんぜんえん です。', 'Chiếc cà vạt này giá ba nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7229, 27181, '大阪デパートの番号、お願いします。', 'おおさか デパートの ばんごう、おねがい します。', 'Cho tôi xin số của trung tâm thương mại Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7230, 27182, 'A：コーヒーを二つください。B：かしこまりました。', 'エー：コーヒーを ふたつ ください。ビー：かしこまりました。', 'A: Cho tôi hai cà phê. B: Vâng, tôi hiểu rồi ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7231, 27217, '二〇二〇年に日本へ来ました。', 'にせんにじゅうねんに にほんへ きました。', 'Tôi đến Nhật vào năm 2020.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7232, 27219, '三月に桜が咲きます。', 'さんがつに さくらが さきます。', 'Tháng ba hoa anh đào nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7233, 27241, '大阪行きの電車は三番線です。', 'おおさかゆきの でんしゃは さんばんせん です。', 'Tàu đi Osaka ở sân ga số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7234, 27478, 'A：あした行けません。B：そうですか。残念ですね。', 'エー：あした いけません。ビー：そう ですか。ざんねん ですね。', 'A: Mai tôi không đi được. B: Thế à. Tiếc quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7235, 28626, 'この店は二時間飲み放題です。', 'この みせは にじかん のみほうだい です。', 'Quán này cho uống thả ga trong hai tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7236, 27108, 'コーヒーをください。', NULL, 'Cho tôi cà phê với.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7237, 27184, '［どうも］ありがとうございました。', '［どうも］ありがとうございました。', 'Cảm ơn rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7238, 27410, '本、もう一杯いかがですか。', 'ほん、もういっぱいいかがですか。', 'Anh/chị dùng thêm một chén nữa nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7239, 27470, '貸してください。', 'かしてください。', 'Cho tôi mượn', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7240, 45730, 'いつか海外で働いてみたい。', 'いつか かいがいで はたらいて みたい。', 'Một ngày nào đó tôi muốn thử làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7241, 45733, '夏休みは田舎の祖父母の家で過ごした。', 'なつやすみは いなかの そふぼの いえで すごした。', 'Kỳ nghỉ hè tôi ở nhà ông bà dưới quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7242, 45735, '机の位置を窓の近くに変えた。', 'つくえの いちを まどの ちかくに かえた。', 'Tôi chuyển vị trí bàn lại gần cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7243, 45737, '家から駅までの距離は一キロぐらいだ。', 'いえから えきまでの きょりは いちキロ ぐらいだ。', 'Khoảng cách từ nhà đến ga chừng một cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7244, 45740, '伊豆半島は温泉で有名だ。', 'いず はんとうは おんせんで ゆうめいだ。', 'Bán đảo Izu nổi tiếng với suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7245, 45742, '今日は波が高いので、泳がないでください。', 'きょうは なみが たかいので、およがないで ください。', 'Hôm nay sóng lớn, xin đừng bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7246, 45747, '大雨で洪水が起きた。', 'おおあめで こうずいが おきた。', 'Mưa lớn đã gây ra lũ lụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7247, 45750, '雨のあとで、空に虹が出た。', 'あめの あとで、そらに にじが でた。', 'Sau cơn mưa, cầu vồng hiện trên bầu trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7248, 45751, '今日は湿度が高くて、蒸し暑い。', 'きょうは しつどが たかくて、むしあつい。', 'Hôm nay độ ẩm cao nên oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7249, 45752, '日本の気候は地方によって違う。', 'にほんの きこうは ちほうに よって ちがう。', 'Khí hậu Nhật Bản khác nhau theo từng vùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7250, 45754, '工場の水で川が汚染された。', 'こうじょうの みずで かわが おせん された。', 'Nước thải nhà máy đã làm ô nhiễm dòng sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7251, 45756, '話に夢中で、降りる駅を通り過ぎた。', 'はなしに むちゅうで、おりる えきを とおりすぎた。', 'Mải nói chuyện nên tôi đi quá ga cần xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7252, 45758, '忘れ物をして、家に戻った。', 'わすれものを して、いえに もどった。', 'Quên đồ nên tôi quay về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7253, 45760, '寝坊して、バスに乗り遅れた。', 'ねぼう して、バスに のりおくれた。', 'Ngủ quên nên tôi lỡ xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7254, 45761, '道が凍っているので、滑らないように気をつけて。', 'みちが こおって いるので、すべらない ように きを つけて。', 'Đường đóng băng, cẩn thận kẻo trượt ngã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7255, 45764, '日本の夏は蒸し暑い。', 'にほんの なつは むしあつい。', 'Mùa hè ở Nhật oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7256, 45765, '頂上までの道はとても険しかった。', 'ちょうじょうまでの みちは とても けわしかった。', 'Đường lên đỉnh núi rất hiểm trở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7257, 45769, '兄と私は性格が全然違う。', 'あにと わたしは せいかくが ぜんぜん ちがう。', 'Anh trai và tôi tính cách hoàn toàn khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7258, 45772, '日本の第一印象はどうでしたか。', 'にほんの だいいち いんしょうは どう でしたか。', 'Ấn tượng đầu tiên của bạn về Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7259, 45774, '彼の長所は誰にでも優しいところだ。', 'かれの ちょうしょは だれにでも やさしい ところだ。', 'Ưu điểm của anh ấy là tốt bụng với tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7260, 45776, '日本語の会話に自信がついてきた。', 'にほんごの かいわに じしんが ついて きた。', 'Tôi đã tự tin hơn khi nói tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7261, 45779, '彼女は我慢強くて、文句を言わない。', 'かのじょは がまんづよくて、もんくを いわない。', 'Cô ấy rất nhẫn nại, không hề than phiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7262, 45781, 'うちの犬は大人しくて、ほとんど吠えない。', 'うちの いぬは おとなしくて、ほとんど ほえない。', 'Con chó nhà tôi hiền lắm, hầu như không sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7449, 37916, '歯が痛いです。', 'はが いたい です。', 'Tôi bị đau răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7263, 45784, '服装がだらしないと、印象が悪い。', 'ふくそうが だらしないと、いんしょうが わるい。', 'Ăn mặc luộm thuộm thì gây ấn tượng xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7264, 45785, '困ったときに助けてくれる頼もしい先輩だ。', 'こまった ときに たすけて くれる たのもしい せんぱいだ。', 'Đó là đàn anh đáng tin cậy, luôn giúp tôi khi khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7265, 28635, 'ここに車を止めると、駐車違反になります。', 'ここに くるまを とめると、ちゅうしゃ いはんに なります。', 'Đỗ xe ở đây là vi phạm quy định đỗ xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7266, 28090, '先生に聞きます。', 'せんせいにききます。', 'Hỏi [thầy giáo]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7267, 45787, '彼は会議ではいつも消極的だ。', 'かれは かいぎでは いつも しょうきょくてきだ。', 'Trong cuộc họp anh ấy lúc nào cũng thụ động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7268, 45790, '明日が試験なのに、弟はのんきに遊んでいる。', 'あしたが しけん なのに、おとうとは のんきに あそんで いる。', 'Mai thi mà em trai tôi vẫn vô tư chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7269, 31073, '父は来年退職する予定だ。', 'ちちは らいねん たいしょく する よていだ。', 'Bố tôi dự định nghỉ hưu vào năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7270, 45793, 'どんなときも冷静に判断しよう。', 'どんな ときも れいせいに はんだん しよう。', 'Lúc nào cũng hãy bình tĩnh phán đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7271, 31112, 'テレビで新商品を宣伝している。', 'テレビで しんしょうひんを せんでん して いる。', 'Sản phẩm mới đang được quảng cáo trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7272, 45796, '年下のくせに生意気なことを言うな。', 'としした の くせに なまいきな ことを いうな。', 'Nhỏ tuổi hơn mà dám nói láo xược thế à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7273, 45797, '彼女は私より三つ年上だ。', 'かのじょは わたしより みっつ としうえだ。', 'Cô ấy hơn tôi ba tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7274, 45798, '彼は年下だが、とてもしっかりしている。', 'かれは としした だが、とても しっかり して いる。', 'Cậu ấy nhỏ tuổi hơn nhưng rất chững chạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7275, 28726, '引っ越しで新しい家具を買った。', 'ひっこしで あたらしい かぐを かった。', 'Chuyển nhà nên tôi mua đồ nội thất mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7276, 28783, 'この問題は私には関係がない。', 'この もんだいは わたしには かんけいが ない。', 'Vấn đề này không liên quan đến tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7277, 45800, '仲間と一緒に新しい会社を作った。', 'なかまと いっしょに あたらしい かいしゃを つくった。', 'Tôi cùng các bạn lập công ty mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7278, 28856, 'この町には長い歴史がある。', 'この まちには ながい れきしが ある。', 'Thị trấn này có lịch sử lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7279, 45801, '何があっても、私はあなたの味方だよ。', 'なにが あっても、わたしは あなたの みかた だよ。', 'Dù có chuyện gì, tôi vẫn đứng về phía bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7280, 28914, '仲間と一緒に新しい会社を作った。', 'なかまと いっしょに あたらしい かいしゃを つくった。', 'Tôi cùng các bạn lập công ty mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7281, 28957, '朝、海岸を散歩した。', 'あさ、かいがんを さんぽ した。', 'Buổi sáng tôi đi dạo dọc bờ biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7282, 45804, '彼は部下から信頼されている。', 'かれは ぶかから しんらい されて いる。', 'Anh ấy được cấp dưới tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7283, 29024, '夜中に大きな雷が鳴った。', 'よなかに おおきな かみなりが なった。', 'Nửa đêm có tiếng sấm lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7284, 29109, '昨夜、近所で事件があったらしい。', 'ゆうべ、きんじょで じけんが あった らしい。', 'Nghe nói tối qua gần nhà có xảy ra vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7285, 45807, '私の言い方が悪くて、誤解されてしまった。', 'わたしの いいかたが わるくて、ごかい されて しまった。', 'Tôi nói chưa khéo nên bị hiểu lầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7286, 29149, 'インターネットで旅行の情報を集めた。', 'インターネットで りょこうの じょうほうを あつめた。', 'Tôi thu thập thông tin du lịch trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7287, 45808, '失敗の原因をよく反省した。', 'しっぱいの げんいんを よく はんせい した。', 'Tôi đã tự kiểm điểm kỹ nguyên nhân thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7288, 45809, 'もっと勉強すればよかったと後悔している。', 'もっと べんきょう すれば よかったと こうかい して いる。', 'Tôi hối hận vì đã không học chăm hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7289, 29268, 'この問題は私には関係がない。', 'この もんだいは わたしには かんけいが ない。', 'Vấn đề này không liên quan đến tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7290, 29279, 'この店では外国の食品も買える。', 'この みせでは がいこくの しょくひんも かえる。', 'Ở cửa hàng này cũng mua được thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7291, 45815, '発表の前は胸がどきどきする。', 'はっぴょうの まえは むねが どきどき する。', 'Trước khi thuyết trình tim tôi đập thình thịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7292, 28801, '事故にあいます。', 'じこにあいます。', 'Gặp [tai nạn]', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7293, 29422, '事故の原因はまだわかっていない。', 'じこの げんいんは まだ わかって いない。', 'Nguyên nhân tai nạn vẫn chưa rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7294, 45818, '深呼吸をしたら、気持ちが落ち着いた。', 'しんこきゅうを したら、きもちが おちついた。', 'Hít thở sâu xong thì tâm trạng bình tĩnh lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7295, 29472, '東京の人口は千四百万人ぐらいだ。', 'とうきょうの じんこうは せんよんひゃくまんにん ぐらいだ。', 'Dân số Tokyo khoảng mười bốn triệu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7296, 28940, '旅行に参加します。', 'りょこうにさんかします。', 'Tham gia [tour], tham dự', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7297, 29480, '両親は私の留学に反対した。', 'りょうしんは わたしの りゅうがくに はんたい した。', 'Bố mẹ phản đối việc tôi đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7298, 29497, '明日、授業でレポートを発表する。', 'あした、じゅぎょうで レポートを はっぴょう する。', 'Ngày mai tôi trình bày báo cáo trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7299, 45819, '子供のころから、パイロットに憧れていた。', 'こどもの ころから、パイロットに あこがれて いた。', 'Từ nhỏ tôi đã ngưỡng mộ nghề phi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7300, 45820, '彼は今でも昔の友達を恨んでいる。', 'かれは いまでも むかしの ともだちを うらんで いる。', 'Đến giờ anh ấy vẫn oán người bạn cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7301, 45821, '毎年海外旅行に行けるなんて、羨ましい。', 'まいとし かいがい りょこうに いける なんて、うらやましい。', 'Năm nào cũng được đi du lịch nước ngoài, thật đáng ghen tị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7302, 45822, '一点差で負けて、とても悔しい。', 'いってんさで まけて、とても くやしい。', 'Thua chỉ một điểm, thật cay cú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7303, 45824, 'この料理は見た目はよくないが、おいしい。', 'この りょうりは みためは よくないが、おいしい。', 'Món này trông không đẹp mắt nhưng ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7304, 29644, '子供が生まれて、郊外に引っ越した。', 'こどもが うまれて、こうがいに ひっこした。', 'Có con rồi nên chúng tôi chuyển ra ngoại ô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7305, 45828, 'ダイエット中なのに、ついケーキを食べてしまった。', 'ダイエットちゅう なのに、つい ケーキを たべて しまった。', 'Đang ăn kiêng mà tôi lỡ ăn mất miếng bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7306, 30983, '水不足が深刻な問題になっている。', 'みずぶそくが しんこくな もんだいに なって いる。', 'Thiếu nước đang trở thành vấn đề nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7307, 45833, 'この工場ではいろいろな製品を作っている。', 'この こうじょうでは いろいろな せいひんを つくって いる。', 'Nhà máy này sản xuất nhiều loại sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7308, 45835, 'テレビで新商品を宣伝している。', 'テレビで しんしょうひんを せんでん して いる。', 'Sản phẩm mới đang được quảng cáo trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7309, 45839, '今月の売上は先月より多い。', 'こんげつの うりあげは せんげつより おおい。', 'Doanh thu tháng này cao hơn tháng trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7310, 45846, '会議で新しい企画を提案した。', 'かいぎで あたらしい きかくを ていあん した。', 'Tôi đề xuất một kế hoạch mới trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7311, 45847, '出かける前に、ガスを確認した。', 'でかける まえに、ガスを かくにん した。', 'Trước khi ra ngoài tôi kiểm tra lại bếp ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7312, 45853, '面接を受けた会社に採用された。', 'めんせつを うけた かいしゃに さいよう された。', 'Tôi đã được công ty mình phỏng vấn tuyển dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7313, 45855, '兄は課長に昇進した。', 'あには かちょうに しょうしん した。', 'Anh tôi được thăng chức trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7314, 31078, '兄は課長に昇進した。', 'あには かちょうに しょうしん した。', 'Anh tôi được thăng chức trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7315, 31094, '工場の水で川が汚染された。', 'こうじょうの みずで かわが おせん された。', 'Nước thải nhà máy đã làm ô nhiễm dòng sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7316, 31100, '外国人観光客が増加している。', 'がいこくじん かんこうきゃくが ぞうか して いる。', 'Khách du lịch nước ngoài đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7317, 31105, '市が住民の生活について調査している。', 'しが じゅうみんの せいかつに ついて ちょうさ して いる。', 'Thành phố đang khảo sát về đời sống người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7318, 31126, '事故のニュースが大きく報道された。', 'じこの ニュースが おおきく ほうどう された。', 'Tin về vụ tai nạn đã được đưa rầm rộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7319, 31150, '税金を払うのは国民の義務だ。', 'ぜいきんを はらうのは こくみんの ぎむだ。', 'Nộp thuế là nghĩa vụ của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7320, 45858, '毎日電車で通勤しています。', 'まいにち でんしゃで つうきん して います。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7321, 45859, 'あの会社とは長い間取引がある。', 'あの かいしゃとは ながい あいだ とりひきが ある。', 'Chúng tôi giao dịch với công ty đó đã lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7322, 45862, '一年間の努力の成果が出た。', 'いちねんかんの どりょくの せいかが でた。', 'Thành quả của một năm nỗ lực đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7323, 45866, '仕事のために資格を取りたい。', 'しごとの ために しかくを とりたい。', 'Tôi muốn lấy chứng chỉ để phục vụ công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7324, 45867, '間違いが多かったので、作文を書き直した。', 'まちがいが おおかったので、さくぶんを かきなおした。', 'Nhiều lỗi quá nên tôi viết lại bài văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7325, 45870, '昼ご飯はパンで済ませた。', 'ひるごはんは パンで すませた。', 'Bữa trưa tôi ăn tạm bánh mì cho xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7326, 45872, 'このまま計画を進めましょう。', 'この まま けいかくを すすめましょう。', 'Cứ tiếp tục triển khai kế hoạch như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7327, 45874, '忙しかったので、誘いを断った。', 'いそがしかったので、さそいを ことわった。', 'Vì bận nên tôi đã từ chối lời mời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7328, 45876, 'この商売はあまり儲からない。', 'この しょうばいは あまり もうからない。', 'Việc buôn bán này không lãi mấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7329, 45877, '電車を間違えて、遠くまで行ってしまった。', 'でんしゃを まちがえて、とおくまで いって しまった。', 'Đi nhầm tàu nên tôi bị đi xa mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7330, 45879, '忙しさのあまり、食事を忘れてしまった。', 'いそがしさの あまり、しょくじを わすれて しまった。', 'Bận quá đến mức quên cả ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7331, 45882, '正確な時間を教えてください。', 'せいかくな じかんを おしえて ください。', 'Hãy cho tôi biết giờ chính xác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7332, 45886, '至急、部長に連絡してください。', 'しきゅう、ぶちょうに れんらく して ください。', 'Hãy liên lạc với trưởng phòng gấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7333, 45890, '市民の意見を聞く会が開かれた。', 'しみんの いけんを きく かいが ひらかれた。', 'Một buổi lấy ý kiến người dân đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7334, 45891, '東京の人口は千四百万人ぐらいだ。', 'とうきょうの じんこうは せんよんひゃくまんにん ぐらいだ。', 'Dân số Tokyo khoảng mười bốn triệu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7450, 37914, 'この枕は柔らかいです。', 'この まくらは やわらかい です。', 'Chiếc gối này mềm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7336, 45893, '日本では高齢化が進んでいる。', 'にほんでは こうれいかが すすんで いる。', 'Ở Nhật, dân số đang ngày càng già hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7337, 45896, '首相が新しい政策を発表した。', 'しゅしょうが あたらしい せいさくを はっぴょう した。', 'Thủ tướng đã công bố chính sách mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7338, 45899, '誰にでも意見を言う権利がある。', 'だれにでも いけんを いう けんりが ある。', 'Ai cũng có quyền nêu ý kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7339, 45901, '世界の平和を願っています。', 'せかいの へいわを ねがって います。', 'Tôi mong thế giới hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7340, 45903, '昨夜、近所で事件があったらしい。', 'ゆうべ、きんじょで じけんが あった らしい。', 'Nghe nói tối qua gần nhà có xảy ra vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7341, 45907, '財布を落としたので、警察に届けた。', 'さいふを おとしたので、けいさつに とどけた。', 'Đánh rơi ví nên tôi đã báo cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7342, 45908, '台風で農作物に大きな被害が出た。', 'たいふうで のうさくもつに おおきな ひがいが でた。', 'Bão gây thiệt hại lớn cho hoa màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7343, 45910, '大雨で住民は学校に避難した。', 'おおあめで じゅうみんは がっこうに ひなん した。', 'Do mưa lớn, người dân đã sơ tán đến trường học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7344, 45912, '試験の結果は来週わかる。', 'しけんの けっかは らいしゅう わかる。', 'Tuần sau sẽ biết kết quả thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7345, 28642, 'もっとゆっくり話してください。', 'もっと ゆっくり はなして ください。', 'Hãy nói chậm hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7346, 45988, '大学で日本の歴史を研究している。', 'だいがくで にほんの れきしを けんきゅう して いる。', 'Tôi nghiên cứu lịch sử Nhật Bản ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7347, 45989, '新しい星が発見された。', 'あたらしい ほしが はっけん された。', 'Một ngôi sao mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7348, 45990, '電話はベルによって発明された。', 'でんわは ベルに よって はつめい された。', 'Điện thoại do Bell phát minh ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7349, 45995, '名前を書いてから答案を出してください。', 'なまえを かいてから とうあんを だして ください。', 'Ghi tên rồi hãy nộp bài thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7350, 45992, 'まず基礎をしっかり勉強しよう。', 'まず きそを しっかり べんきょう しよう。', 'Trước hết hãy học chắc phần cơ bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7351, 45993, '習った文法を会話に応用してみよう。', 'ならった ぶんぽうを かいわに おうよう して みよう。', 'Hãy thử ứng dụng ngữ pháp đã học vào hội thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7352, 45913, '台風の影響で、電車が止まった。', 'たいふうの えいきょうで、でんしゃが とまった。', 'Do ảnh hưởng của bão, tàu điện ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7353, 45916, '暑さ対策に帽子をかぶっている。', 'あつさ たいさくに ぼうしを かぶって いる。', 'Tôi đội mũ để chống nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7354, 45917, '市が住民の生活について調査している。', 'しが じゅうみんの せいかつに ついて ちょうさ して いる。', 'Thành phố đang khảo sát về đời sống người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7355, 45921, '事故のニュースが大きく報道された。', 'じこの ニュースが おおきく ほうどう された。', 'Tin về vụ tai nạn đã được đưa rầm rộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7356, 45922, '世論は新しい法律に反対している。', 'よろんは あたらしい ほうりつに はんたい して いる。', 'Dư luận phản đối luật mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7357, 45927, '祖父は年金で生活している。', 'そふは ねんきんで せいかつ して いる。', 'Ông tôi sống bằng lương hưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7358, 45930, '不景気で給料が下がった。', 'ふけいきで きゅうりょうが さがった。', 'Kinh tế suy thoái nên lương bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7359, 45933, '両親は私の留学に反対した。', 'りょうしんは わたしの りゅうがくに はんたい した。', 'Bố mẹ phản đối việc tôi đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7360, 45935, 'その問題について議論が続いている。', 'その もんだいに ついて ぎろんが つづいて いる。', 'Cuộc tranh luận về vấn đề đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7361, 45937, '外国人観光客が増加している。', 'がいこくじん かんこうきゃくが ぞうか して いる。', 'Khách du lịch nước ngoài đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7362, 45991, 'あいさつは人間関係の基本だ。', 'あいさつは にんげん かんけいの きほんだ。', 'Chào hỏi là điều cơ bản trong quan hệ con người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7363, 45994, '例を挙げて説明してください。', 'れいを あげて せつめい して ください。', 'Hãy lấy ví dụ để giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7364, 45996, 'この問題の正解は三番です。', 'この もんだいの せいかいは さんばん です。', 'Đáp án đúng của câu này là số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7365, 45997, '名前の書き方に間違いがあった。', 'なまえの かきかたに まちがいが あった。', 'Cách viết tên có chỗ bị sai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7366, 26985, '私は二十歳です。', 'わたしは はたち です。', 'Tôi hai mươi tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7367, 26986, 'お子さんは何歳ですか。', 'おこさんは なんさい ですか。', 'Con anh mấy tuổi rồi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7368, 26987, 'はい、私は学生です。', 'はい、わたしは がくせい です。', 'Vâng, tôi là sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7369, 26988, 'いいえ、私は先生じゃありません。', 'いいえ、わたしは せんせい じゃ ありません。', 'Không, tôi không phải giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7370, 26989, '初めまして。マイク・ミラーです。', 'はじめまして。マイク・ミラー です。', 'Rất vui được gặp anh. Tôi là Mike Miller.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7371, 28649, '洗濯機が壊れてしまいました。', 'せんたくきが こわれて しまいました。', 'Máy giặt bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7372, 26983, '病院へ行きます。', 'びょういんへいきます。', 'Tôi đi đến bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7373, 29662, 'どなたですか。', 'どなたですか。', 'Ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7374, 47554, '茶道はわび・さびの心を大切にする。', 'さどうは わび・さびの こころを たいせつに する。', 'Trà đạo coi trọng tinh thần wabi-sabi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7375, 47556, 'この旅館は格式が高い。', 'この りょかんは かくしきが たかい。', 'Lữ quán này rất có đẳng cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7376, 47558, 'この町は昔、港町として栄えた。', 'この まちは むかし、みなとまちと して さかえた。', 'Ngày xưa thị trấn này thịnh vượng như một thương cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7377, 47912, 'この古い町並みには趣がある。', 'この ふるい まちなみには おもむきが ある。', 'Dãy phố cổ này mang một phong vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7378, 47915, '彼の着物の着こなしは粋だ。', 'かれの きものの きこなしは いきだ。', 'Cách anh ấy mặc kimono thật thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7379, 46008, '寒さがますます厳しくなってきた。', 'さむさが ますます きびしく なって きた。', 'Cái lạnh ngày càng khắc nghiệt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7380, 46004, '彼女はクラスで一番優秀な学生だ。', 'かのじょは クラスで いちばん ゆうしゅうな がくせいだ。', 'Cô ấy là học sinh ưu tú nhất lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7381, 45940, '何が起こったのか、教えてください。', 'なにが おこったのか、おしえて ください。', 'Hãy cho tôi biết chuyện gì đã xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7382, 45942, '泥棒は窓から逃げた。', 'どろぼうは まどから にげた。', 'Tên trộm chạy trốn qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7383, 45944, '彼はけがの痛みを医者に訴えた。', 'かれは けがの いたみを いしゃに うったえた。', 'Anh ấy than với bác sĩ về cơn đau do vết thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7384, 45945, '水不足が深刻な問題になっている。', 'みずぶそくが しんこくな もんだいに なって いる。', 'Thiếu nước đang trở thành vấn đề nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7385, 45946, '先生はすべての学生に公平だ。', 'せんせいは すべての がくせいに こうへいだ。', 'Thầy giáo công bằng với mọi học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7386, 45947, '日本では、家に入るとき靴を脱ぐのが一般的だ。', 'にほんでは、いえに はいる とき くつを ぬぐのが いっぱんてきだ。', 'Ở Nhật, cởi giày khi vào nhà là chuyện thông thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7387, 45951, '旅行の前に、その国の知識を身につけた。', 'りょこうの まえに、その くにの ちしきを みに つけた。', 'Trước chuyến đi tôi tìm hiểu kiến thức về nước đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7388, 45954, '科学の進歩で生活が便利になった。', 'かがくの しんぽで せいかつが べんりに なった。', 'Nhờ tiến bộ khoa học, cuộc sống trở nên tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7389, 45956, 'この辺りの地理に詳しいですか。', 'この あたりの ちりに くわしい ですか。', 'Bạn có rành đường sá quanh đây không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7390, 45958, '大学で哲学を専攻した。', 'だいがくで てつがくを せんこう した。', 'Tôi học chuyên ngành triết học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7391, 45959, '大学で心理学の授業を取っている。', 'だいがくで しんりがくの じゅぎょうを とって いる。', 'Tôi đang học môn tâm lý học ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7392, 45961, '今日の講義はとてもわかりやすかった。', 'きょうの こうぎは とても わかりやすかった。', 'Bài giảng hôm nay rất dễ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7393, 45964, '週末までに課題を出さなければならない。', 'しゅうまつまでに かだいを ださなければ ならない。', 'Tôi phải nộp bài tập trước cuối tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7394, 45966, 'テストの点数が思ったより悪かった。', 'テストの てんすうが おもったより わるかった。', 'Điểm bài kiểm tra tệ hơn tôi nghĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7395, 45999, '失敗から学ぶことは多い。', 'しっぱいから まなぶ ことは おおい。', 'Có nhiều điều học được từ thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7396, 46001, 'この問題を十分で解いてください。', 'この もんだいを じゅっぷんで といて ください。', 'Hãy giải bài này trong mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7397, 46003, '仕事を通して多くの経験を得た。', 'しごとを とおして おおくの けいけんを えた。', 'Qua công việc tôi đã có thêm nhiều kinh nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7398, 46006, '話はだいたいわかりました。', 'はなしは だいたい わかりました。', 'Câu chuyện thì tôi hiểu đại khái rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7399, 45979, 'クラスメートと一緒に宿題をした。', 'クラスメートと いっしょに しゅくだいを した。', 'Tôi làm bài tập cùng bạn cùng lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7400, 45968, '一回目の試験は不合格だった。', 'いっかいめの しけんは ふごうかく だった。', 'Lần thi đầu tôi đã trượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7401, 45970, '来年の三月に大学を卒業します。', 'らいねんの さんがつに だいがくを そつぎょう します。', 'Tháng ba năm sau tôi tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7402, 45973, '奨学金をもらって大学に通っている。', 'しょうがくきんを もらって だいがくに かよって いる。', 'Tôi nhận học bổng để học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7403, 45975, '校長先生が入学式でスピーチをした。', 'こうちょう せんせいが にゅうがくしきで スピーチを した。', 'Thầy hiệu trưởng phát biểu trong lễ khai giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7404, 45978, '駅で小学校の同級生に会った。', 'えきで しょうがっこうの どうきゅうせいに あった。', 'Tôi gặp bạn cùng lớp tiểu học ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7405, 40561, '子供が無事だと聞いて、ほっとした。', 'こどもが ぶじだと きいて、ほっと した。', 'Nghe tin con an toàn, tôi thở phào nhẹ nhõm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7406, 46009, '田舎の暮らしにもう慣れた。', 'いなかの くらしにも もう なれた。', 'Tôi đã quen với cuộc sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7407, 46014, 'この店は現金しか使えない。', 'この みせは げんきん しか つかえない。', 'Cửa hàng này chỉ nhận tiền mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7408, 46015, 'すみません、領収書をください。', 'すみません、りょうしゅうしょを ください。', 'Xin lỗi, cho tôi xin hóa đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7409, 31333, '背中がかゆいです。', 'せなかが かゆい です。', 'Lưng tôi ngứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7410, 47916, 'この旅館は格式が高い。', 'この りょかんは かくしきが たかい。', 'Lữ quán này rất có đẳng cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7411, 47919, 'この伝統行事は廃れつつある。', 'この でんとう ぎょうじは すたれつつ ある。', 'Sự kiện truyền thống này đang dần mai một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7412, 47921, '亡くなった祖父を偲んで、みんなで集まった。', 'なくなった そふを しのんで、みんなで あつまった。', 'Mọi người tụ họp để tưởng nhớ ông đã khuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7413, 47924, '日本料理の世界は奥深い。', 'にほん りょうりの せかいは おくぶかい。', 'Thế giới ẩm thực Nhật Bản thật thâm sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7414, 47926, '京都には雅な文化が残っている。', 'きょうとには みやびな ぶんかが のこって いる。', 'Kyoto còn lưu giữ nền văn hóa tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7415, 31310, 'この手紙を先生に渡してください。', 'この てがみを せんせいに わたして ください。', 'Hãy đưa lá thư này cho thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7416, 31318, '子どものプールは浅いです。', 'こどもの プールは あさい です。', 'Hồ bơi trẻ em thì nông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7417, 47927, '田舎の人々は素朴で温かい。', 'いなかの ひとびとは そぼくで あたたかい。', 'Người dân quê mộc mạc và ấm áp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7418, 48272, 'この古い町並みには趣がある。', 'この ふるい まちなみには おもむきが ある。', 'Dãy phố cổ này mang một phong vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7419, 48274, '茶道はわび・さびの心を大切にする。', 'さどうは わび・さびの こころを たいせつに する。', 'Trà đạo coi trọng tinh thần wabi-sabi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7420, 48276, 'この旅館は格式が高い。', 'この りょかんは かくしきが たかい。', 'Lữ quán này rất có đẳng cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7421, 48279, 'この伝統行事は廃れつつある。', 'この でんとう ぎょうじは すたれつつ ある。', 'Sự kiện truyền thống này đang dần mai một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7422, 48281, '亡くなった祖父を偲んで、みんなで集まった。', 'なくなった そふを しのんで、みんなで あつまった。', 'Mọi người tụ họp để tưởng nhớ ông đã khuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7423, 48283, '長い歴史の中で培われた技術だ。', 'ながい れきしの なかで つちかわれた ぎじゅつだ。', 'Đây là kỹ thuật được vun đắp qua lịch sử lâu dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7424, 48286, '京都には雅な文化が残っている。', 'きょうとには みやびな ぶんかが のこって いる。', 'Kyoto còn lưu giữ nền văn hóa tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7425, 48288, '伝統の技は脈々と受け継がれている。', 'でんとうの わざは みゃくみゃくと うけつがれて いる。', 'Kỹ thuật truyền thống được kế thừa không ngừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7426, 46018, 'その商品は在庫がありません。', 'その しょうひんは ざいこが ありません。', 'Mặt hàng đó đã hết hàng trong kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7427, 46025, 'このパソコンは一年間の保証がついている。', 'この パソコンは いちねんかんの ほしょうが ついて いる。', 'Máy tính này được bảo hành một năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7428, 46027, '引っ越しで新しい家具を買った。', 'ひっこしで あたらしい かぐを かった。', 'Chuyển nhà nên tôi mua đồ nội thất mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7429, 46030, 'しょうゆは日本料理に欠かせない調味料だ。', 'しょうゆは にほん りょうりに かかせない ちょうみりょうだ。', 'Xì dầu là gia vị không thể thiếu trong món Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7430, 46032, '毎日の献立を考えるのは大変だ。', 'まいにちの こんだてを かんがえるのは たいへんだ。', 'Nghĩ thực đơn mỗi ngày thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7431, 46034, '節約のために毎日自炊している。', 'せつやくの ために まいにち じすい して いる。', 'Để tiết kiệm, ngày nào tôi cũng tự nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7432, 46037, '都会では近所付き合いが少ない。', 'とかいでは きんじょづきあいが すくない。', 'Ở thành phố ít có quan hệ hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7433, 46039, 'ごみ出しは朝八時までにしてください。', 'ごみだしは あさ はちじまでに して ください。', 'Hãy đổ rác trước tám giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7434, 46042, '冬は光熱費が高くなる。', 'ふゆは こうねつひが たかく なる。', 'Mùa đông tiền điện nước ga tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7435, 46043, '契約書をよく読んでからサインしてください。', 'けいやくしょを よく よんでから サイン して ください。', 'Hãy đọc kỹ hợp đồng rồi mới ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7436, 46047, '引っ越したら、役所に届け出をしてください。', 'ひっこしたら、やくしょに とどけでを して ください。', 'Chuyển nhà xong hãy khai báo ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7437, 46049, '旅行の前に保険に入った。', 'りょこうの まえに ほけんに はいった。', 'Trước chuyến đi tôi đã mua bảo hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7438, 46051, '旅行中、友達の猫を預かっている。', 'りょこうちゅう、ともだちの ねこを あずかって いる。', 'Trong lúc bạn đi du lịch, tôi trông giúp con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7439, 46053, '家賃を銀行に振り込んだ。', 'やちんを ぎんこうに ふりこんだ。', 'Tôi đã chuyển khoản tiền nhà qua ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7440, 46055, '一万円あれば足りると思う。', 'いちまんえん あれば たりると おもう。', 'Tôi nghĩ có mười nghìn yên là đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7441, 46056, '料理が余ったので、近所に分けた。', 'りょうりが あまったので、きんじょに わけた。', 'Đồ ăn còn thừa nên tôi chia cho hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7442, 46058, 'プレゼント用に包装してください。', 'プレゼントように ほうそう して ください。', 'Hãy gói lại giúp tôi để làm quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7443, 46060, '朝の電車はとても混んでいる。', 'あさの でんしゃは とても こんで いる。', 'Tàu buổi sáng rất đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7444, 46062, 'コンビニは便利だが、少し割高だ。', 'コンビニは べんりだが、すこし わりだかだ。', 'Cửa hàng tiện lợi thì tiện nhưng hơi đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7445, 46068, 'せっかく作ったのに、誰も食べてくれなかった。', 'せっかく つくったのに、だれも たべて くれなかった。', 'Đã mất công nấu mà chẳng ai ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7446, 38324, 'おばあさんに道を教えました。', 'おばあさんに みちを おしえました。', 'Tôi chỉ đường cho một cụ bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7447, 31336, '爪が長いですから、切ります。', 'つめが ながい ですから、きります。', 'Móng tay dài rồi nên tôi cắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7448, 31341, '指から血が出ています。', 'ゆびから ちが でて います。', 'Ngón tay đang chảy máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7451, 37683, '週末は家で料理します。', 'しゅうまつは いえで りょうり します。', 'Cuối tuần tôi nấu ăn ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7452, 37909, 'ジュースに氷を入れてください。', 'ジュースに こおりを いれて ください。', 'Hãy cho đá vào nước ép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7453, 46071, '雪の日は運転に気をつけてください。', 'ゆきの ひは うんてんに きを つけて ください。', 'Ngày tuyết rơi hãy cẩn thận khi lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7454, 46072, '十八歳になったら、車の免許を取りたい。', 'じゅうはっさいに なったら、くるまの めんきょを とりたい。', 'Đủ mười tám tuổi tôi muốn lấy bằng lái ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7455, 46075, '家から会社まで往復二時間かかる。', 'いえから かいしゃまで おうふく にじかん かかる。', 'Đi về giữa nhà và công ty mất hai tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7456, 46077, '新宿で乗り換えがあります。', 'しんじゅくで のりかえが あります。', 'Phải chuyển tàu ở Shinjuku.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7457, 46079, '飛行機は予定通りに到着した。', 'ひこうきは よていどおりに とうちゃく した。', 'Máy bay đã đến đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7458, 46080, '明日の朝六時に出発します。', 'あしたの あさ ろくじに しゅっぱつ します。', 'Sáu giờ sáng mai chúng ta xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7459, 46082, '京都へ観光に行った。', 'きょうとへ かんこうに いった。', 'Tôi đi tham quan Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7460, 46085, '温泉の旅館に二泊した。', 'おんせんの りょかんに にはく した。', 'Tôi nghỉ hai đêm ở lữ quán có suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7461, 46086, '週末に温泉に行って、ゆっくり休んだ。', 'しゅうまつに おんせんに いって、ゆっくり やすんだ。', 'Cuối tuần tôi đi suối nước nóng và nghỉ ngơi thong thả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7462, 46090, 'いつか海外で働いてみたい。', 'いつか かいがいで はたらいて みたい。', 'Một ngày nào đó tôi muốn thử làm việc ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7463, 46092, '都会の生活は便利だが、疲れる。', 'とかいの せいかつは べんりだが、つかれる。', 'Cuộc sống thành phố tiện lợi nhưng mệt mỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7464, 46094, '子供が生まれて、郊外に引っ越した。', 'こどもが うまれて、こうがいに ひっこした。', 'Có con rồi nên chúng tôi chuyển ra ngoại ô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7465, 46097, '家から駅までの距離は一キロぐらいだ。', 'いえから えきまでの きょりは いちキロ ぐらいだ。', 'Khoảng cách từ nhà đến ga chừng một cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7466, 38328, 'お酒はあまり飲みません。', 'おさけは あまり のみません。', 'Tôi không uống rượu nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7467, 38333, 'この花はとてもきれいです。', 'この はなは とても きれい です。', 'Bông hoa này rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7468, 38362, '一緒に映画を見ませんか。', 'いっしょに えいがを みませんか。', 'Cùng xem phim không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7469, 38339, '部屋ではスリッパをはいてください。', 'へやでは スリッパを はいて ください。', 'Trong phòng xin hãy đi dép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7470, 38331, '今晩はカレーを作ります。', 'こんばんは カレーを つくります。', 'Tối nay tôi nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7471, 38349, 'パンにバターを塗ります。', 'パンに バターを ぬります。', 'Tôi phết bơ lên bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7472, 38335, '肉を三百グラムください。', 'にくを さんびゃく グラム ください。', 'Cho tôi ba trăm gam thịt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7473, 38357, 'りっぱな家ですね。', 'りっぱな いえ ですね。', 'Ngôi nhà lộng lẫy nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7474, 38336, 'この傘は私のです。', 'この かさは わたしの です。', 'Chiếc ô này là của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7475, 38341, 'その本を見せてください。', 'その ほんを みせて ください。', 'Cho tôi xem cuốn sách đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7476, 38346, 'どうぞ、座ってください。', 'どうぞ、すわって ください。', 'Xin mời ngồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7477, 38347, 'どの人が先生ですか。', 'どの ひとが せんせい ですか。', 'Người nào là giáo viên?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7478, 38356, 'ゆっくりと話してください。', 'ゆっくりと はなして ください。', 'Hãy nói chậm rãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7479, 38332, '兄はギターを弾きます。', 'あには ギターを ひきます。', 'Anh tôi chơi đàn ghi-ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7480, 31223, '結婚したら、戸籍を移す手続きが必要だ。', 'けっこん したら、こせきを うつす てつづきが ひつようだ。', 'Kết hôn rồi thì cần làm thủ tục chuyển hộ tịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7481, 38344, '紙にたての線を引いてください。', 'かみに たての せんを ひいて ください。', 'Hãy kẻ một đường dọc trên giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7482, 38352, 'ほかの色はありますか。', 'ほかの いろは ありますか。', 'Có màu khác không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7483, 46098, '高いビルが町の景観を壊している。', 'たかい ビルが まちの けいかんを こわして いる。', 'Những tòa nhà cao tầng đang phá hỏng cảnh quan thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7484, 46102, '今日は波が高いので、泳がないでください。', 'きょうは なみが たかいので、およがないで ください。', 'Hôm nay sóng lớn, xin đừng bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7485, 46107, '大雨で洪水が起きた。', 'おおあめで こうずいが おきた。', 'Mưa lớn đã gây ra lũ lụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7486, 46110, '雨のあとで、空に虹が出た。', 'あめの あとで、そらに にじが でた。', 'Sau cơn mưa, cầu vồng hiện trên bầu trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7487, 46111, '今日は湿度が高くて、蒸し暑い。', 'きょうは しつどが たかくて、むしあつい。', 'Hôm nay độ ẩm cao nên oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7488, 46113, '地球の温暖化が進んでいる。', 'ちきゅうの おんだんかが すすんで いる。', 'Trái đất đang ngày càng nóng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7489, 46114, '工場の水で川が汚染された。', 'こうじょうの みずで かわが おせん された。', 'Nước thải nhà máy đã làm ô nhiễm dòng sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7490, 46116, '話に夢中で、降りる駅を通り過ぎた。', 'はなしに むちゅうで、おりる えきを とおりすぎた。', 'Mải nói chuyện nên tôi đi quá ga cần xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7530, 38378, 'りんごを三個買いました。', 'りんごを さんこ かいました。', 'Tôi mua ba quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7491, 46118, '忘れ物をして、家に戻った。', 'わすれものを して、いえに もどった。', 'Quên đồ nên tôi quay về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7492, 46120, '寝坊して、バスに乗り遅れた。', 'ねぼう して、バスに のりおくれた。', 'Ngủ quên nên tôi lỡ xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7493, 46121, '道が凍っているので、滑らないように気をつけて。', 'みちが こおって いるので、すべらない ように きを つけて。', 'Đường đóng băng, cẩn thận kẻo trượt ngã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7494, 46124, '日本の夏は蒸し暑い。', 'にほんの なつは むしあつい。', 'Mùa hè ở Nhật oi bức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7495, 46128, 'ぎりぎりで電車に間に合った。', 'ぎりぎりで でんしゃに まにあった。', 'Tôi kịp tàu trong gang tấc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7496, 45261, '授業のあと、すぐに復習するといい。', 'じゅぎょうの あと、すぐに ふくしゅう すると いい。', 'Học xong nên ôn bài ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7497, 45263, '先生の説明をやっと理解できた。', 'せんせいの せつめいを やっと りかい できた。', 'Cuối cùng tôi cũng hiểu được lời giải thích của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7498, 45267, '理科の授業で実験をした。', 'りかの じゅぎょうで じっけんを した。', 'Trong giờ khoa học chúng tôi làm thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7499, 45259, 'クラスメートと一緒に宿題をした。', 'クラスメートと いっしょに しゅくだいを した。', 'Tôi làm bài tập cùng bạn cùng lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7500, 45621, '授業のあと、すぐに復習するといい。', 'じゅぎょうの あと、すぐに ふくしゅう すると いい。', 'Học xong nên ôn bài ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7501, 45624, '日本語の発音を練習している。', 'にほんごの はつおんを れんしゅう して いる。', 'Tôi đang luyện phát âm tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7502, 45627, '理科の授業で実験をした。', 'りかの じゅぎょうで じっけんを した。', 'Trong giờ khoa học chúng tôi làm thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7503, 45980, '授業の前に予習しておきましょう。', 'じゅぎょうの まえに よしゅう して おきましょう。', 'Hãy chuẩn bị bài trước giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7504, 38372, '私は虫が嫌いです。', 'わたしは むしが きらい です。', 'Tôi ghét côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7505, 38375, '私は音楽が好きです。', 'わたしは おんがくが すき です。', 'Tôi thích âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7506, 38368, '九月に日本へ行きます。', 'くがつに にほんへ いきます。', 'Tháng chín tôi đi Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7507, 38364, '黄色い帽子をかぶっている子が弟です。', 'きいろい ぼうしを かぶって いる こが おとうと です。', 'Đứa bé đội mũ vàng là em trai tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7508, 38369, 'A：もう少しいかがですか。B：いいえ、結構です。', 'エー：もう すこし いかが ですか。ビー：いいえ、けっこう です。', 'A: Dùng thêm chút nữa nhé? B: Không, đủ rồi ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7509, 38371, '雨の日は嫌です。', 'あめの ひは いや です。', 'Tôi không thích ngày mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7510, 45983, '先生の説明をやっと理解できた。', 'せんせいの せつめいを やっと りかい できた。', 'Cuối cùng tôi cũng hiểu được lời giải thích của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7511, 45984, '日本語の発音を練習している。', 'にほんごの はつおんを れんしゅう して いる。', 'Tôi đang luyện phát âm tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7512, 45987, '理科の授業で実験をした。', 'りかの じゅぎょうで じっけんを した。', 'Trong giờ khoa học chúng tôi làm thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7513, 45998, '祖母から料理を教わった。', 'そぼから りょうりを おそわった。', 'Tôi được bà dạy nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7514, 46000, '留学して、生きた日本語を身につけたい。', 'りゅうがく して、いきた にほんごを みに つけたい。', 'Tôi muốn đi du học để học được tiếng Nhật thực tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7515, 46002, 'お金を数えてから財布に入れた。', 'おかねを かぞえてから さいふに いれた。', 'Tôi đếm tiền rồi mới cho vào ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7516, 46005, '学生たちは熱心に先生の話を聞いている。', 'がくせいたちは ねっしんに せんせいの はなしを きいて いる。', 'Các học sinh đang chăm chú nghe thầy giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7517, 46007, '明日は必ず来てください。', 'あしたは かならず きて ください。', 'Ngày mai nhất định phải đến nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7518, 37901, 'この町には外国人がたくさん住んでいる。', 'この まちには がいこくじんが たくさん すんで いる。', 'Thị trấn này có nhiều người nước ngoài sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7519, 38386, '受付に女の人がいます。', 'うけつけに おんなの ひとが います。', 'Ở quầy lễ tân có một người phụ nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7520, 38406, '公園でおじいさんが本を読んでいます。', 'こうえんで おじいさんが ほんを よんで います。', 'Có một cụ ông đang đọc sách trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7521, 38387, 'あの女の子は私の妹です。', 'あの おんなのこは わたしの いもうと です。', 'Cô bé kia là em gái tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7522, 38398, '男の子がサッカーをしています。', 'おとこのこが サッカーを して います。', 'Bọn con trai đang đá bóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7523, 38400, '日本では二十歳からお酒が飲めます。', 'にほんでは はたちから おさけが のめます。', 'Ở Nhật từ hai mươi tuổi mới được uống rượu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7524, 38404, '父は毎日背広を着て会社へ行きます。', 'ちちは まいにち せびろを きて かいしゃへ いきます。', 'Ngày nào bố tôi cũng mặc vest đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7525, 38412, '毎晩、歯を磨きます。', 'まいばん、はを みがきます。', 'Tối nào tôi cũng đánh răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7526, 38414, '学校の門の前で待っています。', 'がっこうの もんの まえで まって います。', 'Tôi đang đợi trước cổng trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7527, 38416, '夕飯は七時に食べます。', 'ゆうはんは しちじに たべます。', 'Tôi ăn tối lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7528, 38376, '明日は雪が降ります。', 'あしたは ゆきが ふります。', 'Ngày mai tuyết sẽ rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7529, 38377, '四月に桜が咲きます。', 'しがつに さくらが さきます。', 'Tháng tư hoa anh đào nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7531, 38379, '教室に学生が四人います。', 'きょうしつに がくせいが よにん います。', 'Trong lớp có bốn học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7532, 38382, 'ななひくさんは四です。', 'なな ひく さんは よん です。', 'Bảy trừ ba bằng bốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7533, 38384, '十時に寝ます。', 'じゅうじに ねます。', 'Mười giờ tôi đi ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7534, 28651, '店の前に「本日休業」と書いてあります。', 'みせの まえに 「ほんじつ きゅうぎょう」と かいて あります。', 'Trước cửa hàng có ghi "hôm nay nghỉ".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7535, 28659, '電報代は字の数で決まります。', 'でんぽうだいは じの かずで きまります。', 'Cước điện báo được tính theo số chữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7536, 28667, '電話しましたが、留守でした。', 'でんわ しましたが、るす でした。', 'Tôi đã gọi điện nhưng không có ai ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7537, 28668, '子どもが留守番をしています。', 'こどもが るすばんを して います。', 'Bọn trẻ đang trông nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7538, 31362, 'パーティーに行けなくて残念です。', 'パーティーに いけなくて ざんねん です。', 'Tiếc quá vì không đi dự tiệc được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7539, 30814, '家を出た直後に、雨が降り出した。', 'いえを でた ちょくごに、あめが ふりだした。', 'Ngay sau khi tôi ra khỏi nhà thì trời đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7540, 30815, '試験の直前に風邪をひいてしまった。', 'しけんの ちょくぜんに かぜを ひいて しまった。', 'Ngay trước kỳ thi thì tôi bị cảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7541, 30817, '今後ともよろしくお願いします。', 'こんごとも よろしく おねがい します。', 'Từ nay về sau cũng mong được anh chị giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7542, 30819, '会社へ行く途中で、友達に会った。', 'かいしゃへ いく とちゅうで、ともだちに あった。', 'Trên đường đến công ty tôi gặp bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7543, 30823, '雨のため、運動会は来週に延期された。', 'あめの ため、うんどうかいは らいしゅうに えんき された。', 'Vì mưa, hội thao bị hoãn sang tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7544, 30825, '来月から新しい制度を実施する。', 'らいげつから あたらしい せいどを じっし する。', 'Từ tháng sau sẽ thực thi chế độ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7545, 30826, '二〇二〇年に東京でオリンピックが開催される予定だった。', 'にせんにじゅうねんに とうきょうで オリンピックが かいさい される よてい だった。', 'Olympic từng dự định được tổ chức tại Tokyo năm 2020.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7546, 30829, '熱があるので、今日は授業を欠席します。', 'ねつが あるので、きょうは じゅぎょうを けっせき します。', 'Tôi bị sốt nên hôm nay nghỉ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7547, 30831, '頭が痛かったので、学校を早退した。', 'あたまが いたかったので、がっこうを そうたい した。', 'Đau đầu nên tôi về sớm khỏi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7548, 30836, '毎日自転車で通学している。', 'まいにち じてんしゃで つうがく して いる。', 'Ngày nào tôi cũng đạp xe đi học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7549, 30838, 'この地方ではしばしば地震が起こる。', 'この ちほうでは しばしば じしんが おこる。', 'Ở vùng này động đất thường xuyên xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7550, 30840, 'たまたま入った店がとてもおいしかった。', 'たまたま はいった みせが とても おいしかった。', 'Quán tôi tình cờ ghé vào lại rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7551, 30842, '突然、電気が消えた。', 'とつぜん、でんきが きえた。', 'Bỗng nhiên đèn tắt phụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7552, 30845, '原則として、遅刻は認めません。', 'げんそくと して、ちこくは みとめません。', 'Về nguyên tắc, không chấp nhận đi muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7553, 30847, '相手の立場になって考えてみよう。', 'あいての たちばに なって かんがえて みよう。', 'Hãy thử đặt mình vào vị trí của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7554, 30849, 'この本は読む価値がある。', 'この ほんは よむ かちが ある。', 'Cuốn sách này đáng đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7555, 30850, '彼の仕事は上司に高く評価された。', 'かれの しごとは じょうしに たかく ひょうか された。', 'Công việc của anh ấy được cấp trên đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7556, 30852, 'この講座は初心者を対象にしている。', 'この こうざは しょしんしゃを たいしょうに して いる。', 'Khóa học này dành cho người mới bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7557, 30855, '成功にはいくつかの要素が必要だ。', 'せいこうには いくつかの ようそが ひつようだ。', 'Để thành công cần một vài yếu tố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7558, 31355, '電車が十分遅れています。', 'でんしゃが じゅっぷん おくれて います。', 'Tàu đang trễ mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7559, 31364, '駅から遠くて不便です。', 'えきから とおくて ふべん です。', 'Xa ga nên bất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7560, 31359, '慌てないで、ゆっくり話してください。', 'あわてないで、ゆっくり はなして ください。', 'Đừng hoảng, hãy nói từ từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7561, 31350, '予約の取消は前の日までにしてください。', 'よやくの とりけしは まえの ひまでに して ください。', 'Hãy hủy đặt chỗ trước một ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7562, 31358, '急いでください。電車が来ます。', 'いそいで ください。でんしゃが きます。', 'Nhanh lên. Tàu đến rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7563, 31411, '彼には音楽の才能がある。', 'かれには おんがくの さいのうが ある。', 'Cậu ấy có tài năng âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7564, 31391, '田舎の暮らしにもう慣れた。', 'いなかの くらしにも もう なれた。', 'Tôi đã quen với cuộc sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7565, 31417, '彼女はお母さんによく似ている。', 'かのじょは おかあさんに よく にて いる。', 'Cô ấy rất giống mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7566, 30858, 'この車の特徴は燃費がいいことだ。', 'この くるまの とくちょうは ねんぴが いい ことだ。', 'Đặc trưng của chiếc xe này là tiết kiệm nhiên liệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7567, 30859, 'この金属は熱に強い性質を持っている。', 'この きんぞくは ねつに つよい せいしつを もって いる。', 'Kim loại này có tính chất chịu nhiệt tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8017, 38784, '靴のひもが解けている。', 'くつの ひもが とけて いる。', 'Dây giày bị tuột rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7568, 30861, '試験の範囲を教えてください。', 'しけんの はんいを おしえて ください。', 'Hãy cho tôi biết phạm vi thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7569, 30863, 'クラスの平均点は七十点だった。', 'クラスの へいきんてんは ななじってん だった。', 'Điểm trung bình của lớp là 70.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7570, 30867, '二つの商品を比較してから買った。', 'ふたつの しょうひんを ひかく してから かった。', 'Tôi so sánh hai sản phẩm rồi mới mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7571, 30868, '双子なので、どちらがどちらか区別できない。', 'ふたご なので、どちらが どちらか くべつ できない。', 'Vì là sinh đôi nên tôi không phân biệt được ai với ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7572, 30874, '遠慮しないで、たくさん食べてください。', 'えんりょ しないで、たくさん たべて ください。', 'Đừng khách sáo, cứ ăn nhiều vào nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7573, 30875, '健康のために、早く寝るように努めている。', 'けんこうの ために、はやく ねる ように つとめて いる。', 'Vì sức khỏe, tôi cố gắng đi ngủ sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7574, 30881, '料理が遅いと、客が文句を言った。', 'りょうりが おそいと、きゃくが もんくを いった。', 'Khách than phiền vì món ăn lên chậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7575, 30883, 'もう疲れて、体力の限界だ。', 'もう つかれて、たいりょくの げんかいだ。', 'Mệt quá rồi, thể lực đã đến giới hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7576, 30884, 'この道路は速度制限が厳しい。', 'この どうろは そくど せいげんが きびしい。', 'Đường này giới hạn tốc độ rất nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7577, 30887, '念のため、余分にお金を持っていこう。', 'ねんの ため、よぶんに おかねを もって いこう。', 'Để chắc ăn, hãy mang dư tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7578, 31400, '日曜日に部屋の掃除をします。', 'にちようびに へやの そうじを します。', 'Chủ nhật tôi dọn dẹp phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7579, 31401, '毎朝洗濯をします。', 'まいあさ せんたくを します。', 'Sáng nào tôi cũng giặt đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7580, 31413, '私は料理が下手です。', 'わたしは りょうりが へた です。', 'Tôi nấu ăn kém.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7581, 31384, '自己紹介をしてください。', 'じこ しょうかいを して ください。', 'Hãy tự giới thiệu bản thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7582, 31387, '週末、友達の家を訪ねました。', 'しゅうまつ、ともだちの いえを たずねました。', 'Cuối tuần tôi đến thăm nhà bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7583, 31398, '雨で靴が汚れました。', 'あめで くつが よごれました。', 'Giày bị bẩn vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7584, 31402, '机の上を片付けてください。', 'つくえの うえを かたづけて ください。', 'Hãy dọn mặt bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7585, 31396, 'テレビが壊れてしまいました。', 'テレビが こわれて しまいました。', 'Tivi bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7586, 31408, '電車の中で財布を落としました。', 'でんしゃの なかで さいふを おとしました。', 'Tôi đánh rơi ví trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7587, 31403, 'やっと部屋が片付きました。', 'やっと へやが かたづきました。', 'Cuối cùng căn phòng cũng gọn gàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7588, 31405, '食事の用意ができました。', 'しょくじの よういが できました。', 'Bữa ăn đã chuẩn bị xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7589, 31381, '昔の友達の消息を聞きました。', 'むかしの ともだちの しょうそくを ききました。', 'Tôi nghe được tin tức về người bạn cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7590, 37721, 'カラスはとても賢い鳥だ。', 'カラスは とても かしこい とりだ。', 'Quạ là loài chim rất thông minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7591, 30891, 'どうせ間に合わないから、ゆっくり行こう。', 'どうせ まにあわないから、ゆっくり いこう。', 'Đằng nào cũng không kịp, cứ đi thong thả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7592, 30893, 'たとえ雨が降っても、試合は行われる。', 'たとえ あめが ふっても、しあいは おこなわれる。', 'Cho dù trời mưa, trận đấu vẫn diễn ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7593, 30894, 'もしかしたら、彼は来ないかもしれない。', 'もしかしたら、かれは こないかも しれない。', 'Biết đâu anh ấy sẽ không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7594, 30896, '一回で合格するなんて、さすがだね。', 'いっかいで ごうかく する なんて、さすがだね。', 'Thi một lần là đỗ, quả là đáng nể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7595, 30898, '彼は相変わらず元気そうだ。', 'かれは あいかわらず げんき そうだ。', 'Anh ấy trông vẫn khỏe như mọi khi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7596, 30900, '難しいと思っていたが、案外簡単だった。', 'むずかしいと おもって いたが、あんがい かんたん だった。', 'Tưởng là khó, không ngờ lại dễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7597, 30902, '悪いことをしたら、謝るのは当然だ。', 'わるい ことを したら、あやまるのは とうぜんだ。', 'Làm sai thì xin lỗi là đương nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7598, 30903, 'この文はいろいろな解釈ができる。', 'この ぶんは いろいろな かいしゃくが できる。', 'Câu này có thể hiểu theo nhiều cách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7599, 30906, '病院で血液の検査を受けた。', 'びょういんで けつえきの けんさを うけた。', 'Tôi xét nghiệm máu ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7600, 30909, 'アンケートの結果を分析した。', 'アンケートの けっかを ぶんせき した。', 'Tôi đã phân tích kết quả khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7601, 30912, '犯人だという証拠がない。', 'はんにん だと いう しょうこが ない。', 'Không có bằng chứng cho thấy đó là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7602, 30915, '家庭の事情で、会社を辞めることになった。', 'かていの じじょうで、かいしゃを やめる ことに なった。', 'Vì hoàn cảnh gia đình, tôi phải nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7603, 30918, '明日雨が降ると仮定して、計画を立てよう。', 'あした あめが ふると かてい して、けいかくを たてよう。', 'Hãy giả định ngày mai mưa để lên kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7604, 30919, '話し合いの結果、まだ結論は出ていない。', 'はなしあいの けっか、まだ けつろんは でて いない。', 'Bàn bạc xong vẫn chưa đi đến kết luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7605, 30921, 'この文章を二百字に要約しなさい。', 'この ぶんしょうを にひゃくじに ようやく しなさい。', 'Hãy tóm tắt đoạn văn này trong hai trăm chữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7606, 28672, '図書館を利用したいんですが。', 'としょかんを りよう したいん ですが。', 'Tôi muốn sử dụng thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7607, 31414, '私は料理が得意です。', 'わたしは りょうりが とくい です。', 'Tôi giỏi nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7608, 31426, '今日は部長の機嫌がいいです。', 'きょうは ぶちょうの きげんが いい です。', 'Hôm nay trưởng phòng vui vẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7609, 37697, '痛かったですが、我慢しました。', 'いたかった ですが、がまん しました。', 'Đau lắm nhưng tôi đã chịu đựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7610, 31422, 'いい考えがあります。', 'いい かんがえが あります。', 'Tôi có một ý hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7611, 31427, '冗談ですよ。怒らないでください。', 'じょうだん ですよ。おこらないで ください。', 'Đùa thôi mà. Đừng giận nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7612, 37715, '事故で電車が遅れました。', 'じこで でんしゃが おくれました。', 'Tàu bị trễ vì tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7613, 37709, '最近、体重が増えました。', 'さいきん、たいじゅうが ふえました。', 'Gần đây cân nặng tôi tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7614, 37710, 'この町の人口は減っています。', 'この まちの じんこうは へって います。', 'Dân số thị trấn này đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7615, 37698, '試験に失敗しました。', 'しけんに しっぱい しました。', 'Tôi đã thi trượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7616, 30925, '彼の説明に納得できなかった。', 'かれの せつめいに なっとく できなかった。', 'Tôi không thể chấp nhận lời giải thích của anh ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7617, 30928, '彼はうわさを強く否定した。', 'かれは うわさを つよく ひてい した。', 'Anh ấy kịch liệt phủ nhận tin đồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7618, 30929, '彼女は質問に肯定も否定もしなかった。', 'かのじょは しつもんに こうていも ひていも しなかった。', 'Cô ấy không khẳng định cũng không phủ nhận câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7619, 30931, '目標を明確にすることが大切だ。', 'もくひょうを めいかくに する ことが たいせつだ。', 'Xác định mục tiêu rõ ràng là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7620, 30934, '新しい機械で作業の効率が上がった。', 'あたらしい きかいで さぎょうの こうりつが あがった。', 'Nhờ máy mới, hiệu suất công việc tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7621, 46144, '金利が上がると、ローンの返済が大変になる。', 'きんりが あがると、ローンの へんさいが たいへんに なる。', 'Lãi suất tăng thì trả nợ vay sẽ vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7622, 31053, '電車が大幅に遅れている。', 'でんしゃが おおはばに おくれて いる。', 'Tàu điện đang trễ rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7623, 31567, '相手の立場になって考えてみよう。', 'あいての たちばに なって かんがえて みよう。', 'Hãy thử đặt mình vào vị trí của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7624, 37787, '不況で多くの会社が倒産した。', 'ふきょうで おおくの かいしゃが とうさん した。', 'Do suy thoái, nhiều công ty đã phá sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7625, 31620, '政府は輸入を規制している。', 'せいふは ゆにゅうを きせい して いる。', 'Chính phủ đang hạn chế nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7626, 31115, '新しい映画が来週公開される。', 'あたらしい えいがが らいしゅう こうかい される。', 'Bộ phim mới sẽ công chiếu vào tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7627, 31117, '匿名で寄付をした人がいる。', 'とくめいで きふを した ひとが いる。', 'Có người đã quyên góp ẩn danh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7628, 31118, '客の個人情報が漏洩した。', 'きゃくの こじん じょうほうが ろうえい した。', 'Thông tin cá nhân của khách hàng đã bị rò rỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7629, 31681, 'お客様のクレームに丁寧に対応した。', 'おきゃくさまの クレームに ていねいに たいおう した。', 'Tôi đã xử lý khiếu nại của khách một cách lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7630, 40176, '会社は海外の事業を縮小した。', 'かいしゃは かいがいの じぎょうを しゅくしょう した。', 'Công ty đã thu hẹp hoạt động kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7631, 46146, '円高のおかげで、海外旅行が安くなった。', 'えんだかの おかげで、かいがい りょこうが やすく なった。', 'Nhờ đồng yên tăng giá, du lịch nước ngoài rẻ hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7632, 46148, 'ベトナムの通貨はドンです。', 'ベトナムの つうかは ドン です。', 'Đơn vị tiền tệ của Việt Nam là đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7633, 37723, '素直な子どもですね。', 'すなおな こども ですね。', 'Đứa trẻ ngoan ngoãn nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7634, 37725, '熱心な先生に習っています。', 'ねっしんな せんせいに ならって います。', 'Tôi học với một thầy giáo nhiệt tình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7635, 37727, '彼は消極的な性格です。', 'かれは しょうきょくてきな せいかく です。', 'Anh ấy có tính cách thụ động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7636, 37729, '丁寧な説明をありがとうございました。', 'ていねいな せつめいを ありがとう ございました。', 'Cảm ơn anh vì lời giải thích cẩn thận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7637, 37734, '十分な睡眠をとってください。', 'じゅうぶんな すいみんを とって ください。', 'Hãy ngủ đủ giấc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7638, 37732, '複雑な問題ですね。', 'ふくざつな もんだい ですね。', 'Vấn đề phức tạp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7639, 37735, '不便な所に住んでいます。', 'ふべんな ところに すんで います。', 'Tôi sống ở nơi bất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7640, 37737, '安全な場所に避難してください。', 'あんぜんな ばしょに ひなん して ください。', 'Hãy sơ tán đến nơi an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7641, 46149, 'この会社は海外の市場に進出した。', 'この かいしゃは かいがいの しじょうに しんしゅつ した。', 'Công ty này đã tiến vào thị trường nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7642, 46154, 'この野菜には生産者の名前が書いてある。', 'この やさいには せいさんしゃの なまえが かいて ある。', 'Trên rau này có ghi tên người sản xuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7643, 46156, '弟がテレビを独占している。', 'おとうとが テレビを どくせん して いる。', 'Em trai tôi độc chiếm cái tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8374, 39127, '子供の成長は早い。', 'こどもの せいちょうは はやい。', 'Trẻ con lớn nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7644, 46160, '今年の景況は去年より厳しい。', 'ことしの けいきょうは きょねんより きびしい。', 'Tình hình kinh doanh năm nay khó khăn hơn năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7645, 46167, '気温が上昇して、夏らしくなってきた。', 'きおんが じょうしょう して、なつらしく なって きた。', 'Nhiệt độ tăng lên, đã ra dáng mùa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7646, 46169, '野菜の値段は天気によって変動する。', 'やさいの ねだんは てんきに よって へんどう する。', 'Giá rau biến động theo thời tiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7647, 46171, '交通費は会社が負担します。', 'こうつうひは かいしゃが ふたん します。', 'Chi phí đi lại do công ty chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7648, 46173, '台風で会社は大きな損失を出した。', 'たいふうで かいしゃは おおきな そんしつを だした。', 'Do bão, công ty chịu tổn thất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7649, 46174, '事故の被害者に補償金が支払われた。', 'じこの ひがいしゃに ほしょうきんが しはらわれた。', 'Tiền bồi thường đã được trả cho nạn nhân vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7650, 46177, '閉店前に弁当が値引きされる。', 'へいてん まえに べんとうが ねびき される。', 'Trước giờ đóng cửa, cơm hộp được giảm giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7651, 46179, '今月は稼ぎが少なかった。', 'こんげつは かせぎが すくなかった。', 'Tháng này tôi kiếm được ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7652, 46181, '老後のために貯蓄をしている。', 'ろうごの ために ちょちくを して いる。', 'Tôi tiết kiệm cho tuổi già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7653, 46186, '夜になって、気温が急激に下がった。', 'よるに なって、きおんが きゅうげきに さがった。', 'Về đêm nhiệt độ giảm đột ngột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7654, 46188, '病気は徐々によくなっている。', 'びょうきは じょじょに よく なって いる。', 'Bệnh đang dần dần khá lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7655, 46190, '日本の憲法は一九四七年に施行された。', 'にほんの けんぽうは せんきゅうひゃくよんじゅうななねんに しこう された。', 'Hiến pháp Nhật Bản có hiệu lực từ năm 1947.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7656, 44021, 'この川で泳ぐのは危険です。', 'この かわで およぐのは きけん です。', 'Bơi ở con sông này rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7657, 44023, '時間は十分にあるので、急がなくてもいい。', 'じかんは じゅうぶんに あるので、いそがなくても いい。', 'Thời gian còn đủ nên không cần vội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7658, 44073, '拾った財布を交番に届けた。', 'ひろった さいふを こうばんに とどけた。', 'Tôi mang chiếc ví nhặt được đến đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7659, 41515, '二つの国は平和条約を結んだ。', 'ふたつの くには へいわ じょうやくを むすんだ。', 'Hai nước đã ký hiệp ước hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7660, 31171, '台風で会社は大きな損失を出した。', 'たいふうで かいしゃは おおきな そんしつを だした。', 'Do bão, công ty chịu tổn thất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7661, 44192, 'ボランティア活動に参加したい。', 'ボランティア かつどうに さんか したい。', 'Tôi muốn tham gia hoạt động tình nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7662, 44241, '日本は天然資源が少ない国だ。', 'にほんは てんねん しげんが すくない くにだ。', 'Nhật Bản là nước ít tài nguyên thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7663, 46192, 'この仕事の条件はとてもいい。', 'この しごとの じょうけんは とても いい。', 'Điều kiện của công việc này rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7664, 37927, '約束を忘れて、友達が怒りました。', 'やくそくを わすれて、ともだちが おこりました。', 'Tôi quên lời hẹn nên bạn giận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7665, 37929, '犬が死んで、悲しいです。', 'いぬが しんで、かなしい です。', 'Con chó chết nên tôi buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7666, 37931, '間違えて、恥ずかしいです。', 'まちがえて、はずかしい です。', 'Bị nhầm nên tôi thấy xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7667, 37962, 'エアコンを使いすぎて、電気代が高くなった。', 'エアコンを つかいすぎて、でんきだいが たかく なった。', 'Dùng điều hòa nhiều quá nên tiền điện tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7668, 44383, '時間は十分にあるので、急がなくてもいい。', 'じかんは じゅうぶんに あるので、いそがなくても いい。', 'Thời gian còn đủ nên không cần vội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7669, 41503, '気温が上昇して、夏らしくなってきた。', 'きおんが じょうしょう して、なつらしく なって きた。', 'Nhiệt độ tăng lên, đã ra dáng mùa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7670, 42269, '野菜の値段は天気によって変動する。', 'やさいの ねだんは てんきに よって へんどう する。', 'Giá rau biến động theo thời tiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7671, 44552, 'ボランティア活動に参加したい。', 'ボランティア かつどうに さんか したい。', 'Tôi muốn tham gia hoạt động tình nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7672, 44601, '日本は天然資源が少ない国だ。', 'にほんは てんねん しげんが すくない くにだ。', 'Nhật Bản là nước ít tài nguyên thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7673, 44743, '時間は十分にあるので、急がなくてもいい。', 'じかんは じゅうぶんに あるので、いそがなくても いい。', 'Thời gian còn đủ nên không cần vội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7674, 46193, '政府は輸入を規制している。', 'せいふは ゆにゅうを きせい して いる。', 'Chính phủ đang hạn chế nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7675, 46195, 'スピード違反で罰金を取られた。', 'スピード いはんで ばっきんを とられた。', 'Tôi bị phạt tiền vì chạy quá tốc độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7676, 46197, '裁判所は無罪の判決を下した。', 'さいばんしょは むざいの はんけつを くだした。', 'Tòa án đã tuyên án vô tội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7677, 46198, '弁護士に相談することにした。', 'べんごしに そうだん する ことに した。', 'Tôi quyết định hỏi ý kiến luật sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7678, 46200, '身分を証明するものを持っていますか。', 'みぶんを しょうめい する ものを もって いますか。', 'Bạn có giấy tờ chứng minh nhân thân không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7679, 46203, '行政のサービスがオンラインで使えるようになった。', 'ぎょうせいの サービスが オンラインで つかえる ように なった。', 'Dịch vụ hành chính giờ đã dùng được trực tuyến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7680, 46204, '自治体によってごみの出し方が違う。', 'じちたいに よって ごみの だしかたが ちがう。', 'Mỗi địa phương có cách đổ rác khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7681, 46206, '野党は政府の案に反対している。', 'やとうは せいふの あんに はんたい して いる。', 'Phe đối lập đang phản đối đề án của chính phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7682, 44912, 'ボランティア活動に参加したい。', 'ボランティア かつどうに さんか したい。', 'Tôi muốn tham gia hoạt động tình nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7683, 31188, '最近、睡眠不足が続いている。', 'さいきん、すいみん ぶそくが つづいて いる。', 'Gần đây tôi liên tục bị thiếu ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7684, 31808, 'この紙は再生紙から作られている。', 'この かみは さいせいしから つくられて いる。', 'Loại giấy này được làm từ giấy tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7685, 31071, '新しい工場ができて、雇用が増えた。', 'あたらしい こうじょうが できて、こようが ふえた。', 'Có nhà máy mới nên việc làm tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7686, 28614, '公園でボールを投げて遊びました。', 'こうえんで ボールを なげて あそびました。', 'Tôi chơi ném bóng ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7687, 37964, 'この学校の先生は厳しいです。', 'この がっこうの せんせいは きびしい です。', 'Giáo viên trường này nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7688, 37966, '最近、彼は少し暗いです。', 'さいきん、かれは すこし くらい です。', 'Gần đây anh ấy hơi u sầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7689, 37967, '彼はとても正直です。', 'かれは とても しょうじき です。', 'Anh ấy rất thành thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7690, 37969, '弟は真面目です。', 'おとうとは まじめ です。', 'Em trai tôi chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7691, 37960, '私の部屋は五階にあります。', 'わたしの へやは ごかいに あります。', 'Phòng tôi ở tầng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7692, 37961, '仕事の後、風呂に入ります。', 'しごとの あと、ふろに はいります。', 'Sau giờ làm tôi tắm bồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7693, 42210, '交通費は会社が負担します。', 'こうつうひは かいしゃが ふたん します。', 'Chi phí đi lại do công ty chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7694, 46509, 'この会社は海外の市場に進出した。', 'この かいしゃは かいがいの しじょうに しんしゅつ した。', 'Công ty này đã tiến vào thị trường nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7695, 29318, 'アルバイトで毎月五万円の収入がある。', 'アルバイトで まいつき ごまんえんの しゅうにゅうが ある。', 'Tôi có thu nhập năm mươi nghìn yên mỗi tháng nhờ làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7696, 29342, 'この店は料理の量が多い。', 'この みせは りょうりの りょうが おおい。', 'Quán này cho đồ ăn nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7697, 30940, '彼は相当疲れているようだ。', 'かれは そうとう つかれて いる ようだ。', 'Có vẻ anh ấy khá mệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7698, 30942, '夜になって、気温が急激に下がった。', 'よるに なって、きおんが きゅうげきに さがった。', 'Về đêm nhiệt độ giảm đột ngột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7699, 30945, '冷たい水を一気に飲んだ。', 'つめたい みずを いっきに のんだ。', 'Tôi uống một hơi cốc nước lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7700, 30946, '今月は大きな事故が相次いで起きた。', 'こんげつは おおきな じこが あいついで おきた。', 'Tháng này liên tiếp xảy ra các vụ tai nạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7701, 30948, '今月の売り上げ目標を達成した。', 'こんげつの うりあげ もくひょうを たっせい した。', 'Chúng tôi đã đạt mục tiêu doanh thu tháng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7702, 30950, 'この町の中心には大きな公園がある。', 'この まちの ちゅうしんには おおきな こうえんが ある。', 'Ở trung tâm thị trấn này có một công viên lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7703, 30951, '彼はプロジェクトの中核を担っている。', 'かれは プロジェクトの ちゅうかくを になって いる。', 'Anh ấy đảm nhận vai trò cốt lõi trong dự án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7704, 30953, '料金は一人五千円前後です。', 'りょうきんは ひとり ごせんえん ぜんご です。', 'Chi phí khoảng năm nghìn yên mỗi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7705, 30956, '彼はいわゆる天才だ。', 'かれは いわゆる てんさいだ。', 'Anh ấy là cái gọi là thiên tài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7706, 31076, 'この会社は福利厚生が充実している。', 'この かいしゃは ふくり こうせいが じゅうじつ して いる。', 'Công ty này có chế độ phúc lợi đầy đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7707, 31077, '待遇がよくないので、辞める人が多い。', 'たいぐうが よくないので、やめる ひとが おおい。', 'Đãi ngộ không tốt nên nhiều người nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7708, 31083, 'この件を決める権限は部長にある。', 'この けんを きめる けんげんは ぶちょうに ある。', 'Quyền quyết định việc này thuộc về trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7709, 31085, '先生に推薦状を依頼した。', 'せんせいに すいせんじょうを いらい した。', 'Tôi nhờ thầy viết thư giới thiệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7710, 31088, 'この大学の入試の倍率は十倍だ。', 'この だいがくの にゅうしの ばいりつは じゅうばいだ。', 'Tỷ lệ chọi kỳ thi vào trường này là một chọi mười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7711, 38428, '入院している先生のお見舞いに行きました。', 'にゅういん して いる せんせいの おみまいに いきました。', 'Tôi đi thăm thầy đang nằm viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7712, 38432, 'きょうはかっこうがいいですね。', 'きょうは かっこうが いい ですね。', 'Hôm nay trông bạn bảnh nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7713, 37971, '父は頑固です。', 'ちちは がんこ です。', 'Bố tôi cố chấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7714, 38433, '私のことはかまわないでください。', 'わたしの ことは かまわないで ください。', 'Đừng bận tâm về tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7715, 37979, 'お金を節約して、旅行に行きます。', 'おかねを せつやく して、りょこうに いきます。', 'Tôi tiết kiệm tiền để đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7716, 37987, '新しい駅が完成しました。', 'あたらしい えきが かんせい しました。', 'Nhà ga mới đã hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7717, 37980, '雨の日は車が汚れます。', 'あめの ひは くるまが よごれます。', 'Ngày mưa xe bị bẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7718, 38420, 'この店はアクセサリーが安いです。', 'この みせは アクセサリーが やすい です。', 'Cửa hàng này bán phụ kiện rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7719, 38462, 'なるほど、そういうことだったのか。', 'なるほど、そういう こと だったのか。', 'Ra là vậy, hóa ra là chuyện như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7720, 31090, '民間の会社に就職したい。', 'みんかんの かいしゃに しゅうしょく したい。', 'Tôi muốn vào làm ở công ty tư nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7721, 31092, '日本は天然資源が少ない国だ。', 'にほんは てんねん しげんが すくない くにだ。', 'Nhật Bản là nước ít tài nguyên thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7722, 31096, 'この川で泳ぐのは危険です。', 'この かわで およぐのは きけん です。', 'Bơi ở con sông này rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7723, 31099, '会社は経費を削減することにした。', 'かいしゃは けいひを さくげん する ことに した。', 'Công ty quyết định cắt giảm chi phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7724, 31103, '運動すると血液の循環がよくなる。', 'うんどう すると けつえきの じゅんかんが よく なる。', 'Vận động giúp tuần hoàn máu tốt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7725, 31106, '今年の大学の合格率は七十パーセントだった。', 'ことしの だいがくの ごうかくりつは ななじゅっ パーセント だった。', 'Tỷ lệ đỗ đại học năm nay là 70%.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7726, 31110, '被害を最小に抑えるよう努力した。', 'ひがいを さいしょうに おさえる よう どりょく した。', 'Chúng tôi đã cố gắng giảm thiệt hại xuống mức nhỏ nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7727, 31122, 'その問題をめぐって激しい論争が起きた。', 'その もんだいを めぐって はげしい ろんそうが おきた。', 'Xung quanh vấn đề đó đã nổ ra cuộc tranh luận gay gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7728, 31124, '彼の勇気ある行動は多くの人に称賛された。', 'かれの ゆうき ある こうどうは おおくの ひとに しょうさん された。', 'Hành động dũng cảm của anh ấy được nhiều người ca ngợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7729, 31127, 'テレビ局がこの店を取材に来た。', 'テレビきょくが この みせを しゅざいに きた。', 'Đài truyền hình đến phỏng vấn cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7730, 31130, '彼女の初めての本が出版された。', 'かのじょの はじめての ほんが しゅっぱん された。', 'Cuốn sách đầu tay của cô ấy đã được xuất bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7731, 38442, 'おじゃまします。', 'おじゃま します。', 'Xin phép làm phiền ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7732, 31109, '琵琶湖は日本で最大の湖だ。', 'びわこは にほんで さいだいの みずうみだ。', 'Hồ Biwa là hồ lớn nhất Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7733, 38468, '父はひげをそっています。', 'ちちは ひげを そって います。', 'Bố đang cạo râu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7734, 38464, '彼は仕事にねっしんです。', 'かれは しごとに ねっしん です。', 'Anh ấy nhiệt tình với công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7735, 38465, '母はスーパーでパートをしています。', 'ははは スーパーで パートを して います。', 'Mẹ tôi làm bán thời gian ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7736, 38440, '夏はサンダルをはきます。', 'なつは サンダルを はきます。', 'Mùa hè tôi đi dép xăng đan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7737, 38449, 'レストランでステーキを食べました。', 'レストランで ステーキを たべました。', 'Tôi ăn bít tết ở nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7738, 38463, '雨で服が濡れました。', 'あめで ふくが ぬれました。', 'Quần áo bị ướt vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7739, 38445, '昼過ぎは電車がすいています。', 'ひるすぎは でんしゃが すいて います。', 'Quá trưa thì tàu vắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7740, 38446, '大きいスクリーンで映画を見ました。', 'おおきい スクリーンで えいがを みました。', 'Tôi xem phim trên màn hình lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7741, 38447, '約束をすっかり忘れていました。', 'やくそくを すっかり わすれて いました。', 'Tôi quên khuấy mất lời hẹn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7742, 38451, '今日はそれほど寒くないです。', 'きょうは それほど さむく ない です。', 'Hôm nay không lạnh đến mức đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7743, 38453, 'そんなことはありません。', 'そんな ことは ありません。', 'Không có chuyện như thế đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7744, 38458, 'ゆきちゃん、こっちへおいで。', 'ゆきちゃん、こっちへ おいで。', 'Bé Yuki ơi, lại đây nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7745, 38466, '彼はもう着いたはずです。', 'かれは もう ついた はず です。', 'Lẽ ra anh ấy đã đến nơi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7746, 31132, '市は路上での喫煙を禁止する条例を作った。', 'しは ろじょうでの きつえんを きんし する じょうれいを つくった。', 'Thành phố ban hành điều lệ cấm hút thuốc trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7747, 31135, '駐車違反で罰金を払った。', 'ちゅうしゃ いはんで ばっきんを はらった。', 'Tôi bị phạt tiền vì đỗ xe sai quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7748, 31138, 'これは刑事事件ではなく、民事の問題だ。', 'これは けいじ じけんでは なく、みんじの もんだいだ。', 'Đây không phải vụ án hình sự mà là vấn đề dân sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7749, 31139, '被害者は会社を相手に訴訟を起こした。', 'ひがいしゃは かいしゃを あいてに そしょうを おこした。', 'Người bị hại đã khởi kiện công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7750, 31142, '被告は有罪となった。', 'ひこくは ゆうざいと なった。', 'Bị cáo đã bị kết án có tội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7751, 31143, '十年後、彼の無罪が証明された。', 'じゅうねんご、かれの むざいが しょうめい された。', 'Mười năm sau, sự vô tội của ông ấy đã được chứng minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7752, 31146, '友達はいつも私を弁護してくれる。', 'ともだちは いつも わたしを べんご して くれる。', 'Bạn tôi lúc nào cũng bênh vực tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7753, 31148, '会社は損害を賠償することになった。', 'かいしゃは そんがいを ばいしょう する ことに なった。', 'Công ty phải đền bù thiệt hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7754, 31153, 'ごみは地域の区分に従って出してください。', 'ごみは ちいきの くぶんに したがって だして ください。', 'Hãy đổ rác theo cách phân loại của địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7755, 31156, 'この学校の特色は国際交流が盛んなことだ。', 'この がっこうの とくしょくは こくさい こうりゅうが さかんな ことだ。', 'Nét đặc sắc của trường này là giao lưu quốc tế sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7756, 31158, 'この店は料理の量が多い。', 'この みせは りょうりの りょうが おおい。', 'Quán này cho đồ ăn nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7757, 31161, 'この建物は地震に強い構造になっている。', 'この たてものは じしんに つよい こうぞうに なって いる。', 'Tòa nhà này có kết cấu chịu động đất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7758, 31163, 'この電車は十両編成です。', 'この でんしゃは じゅうりょう へんせい です。', 'Đoàn tàu này gồm mười toa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7759, 31167, '善は急げ。', 'ぜんは いそげ。', 'Việc tốt thì nên làm ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7760, 38487, '家内は料理が上手です。', 'かないは りょうりが じょうず です。', 'Vợ tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7761, 38491, '皆、元気にしています。', 'みな、げんきに して います。', 'Mọi người đều khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7762, 38483, '子どもに泳ぎ方を教えました。', 'こどもに およぎかたを おしえました。', 'Tôi dạy con cách bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7763, 38481, 'ATMでお金を引き出しました。', 'エーティーエムで おかねを ひきだしました。', 'Tôi rút tiền ở máy ATM.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7764, 38480, '会社が新しいビルに移りました。', 'かいしゃが あたらしい ビルに うつりました。', 'Công ty đã chuyển sang tòa nhà mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7765, 38470, '秋はぶどうがおいしいです。', 'あきは ぶどうが おいしい です。', 'Mùa thu nho rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7766, 38482, '空に白い雲が浮かんでいます。', 'そらに しろい くもが うかんで います。', 'Trên trời có những đám mây trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7767, 38477, '十人以下のグループで行きます。', 'じゅうにん いかの グループで いきます。', 'Chúng tôi đi theo nhóm từ mười người trở xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7768, 38485, '熱が下がりました。', 'ねつが さがりました。', 'Đã hạ sốt rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7769, 38475, 'この席でよろしいですか。', 'この せきで よろしい ですか。', 'Ghế này có được không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7770, 38471, 'きのうほど暑くないです。', 'きのう ほど あつく ない です。', 'Không nóng bằng hôm qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7771, 38473, '電話またはメールで連絡してください。', 'でんわ または メールで れんらく して ください。', 'Hãy liên lạc qua điện thoại hoặc email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7772, 38508, '校長先生が入学式でスピーチをした。', 'こうちょう せんせいが にゅうがくしきで スピーチを した。', 'Thầy hiệu trưởng phát biểu trong lễ khai giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7773, 31168, 'この映画は善と悪の戦いを描いている。', 'この えいがは ぜんと あくの たたかいを えがいて いる。', 'Bộ phim này mô tả cuộc chiến giữa thiện và ác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7774, 30853, 'お客様のクレームに丁寧に対応した。', 'おきゃくさまの クレームに ていねいに たいおう した。', 'Tôi đã xử lý khiếu nại của khách một cách lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7775, 31780, '日本の憲法は一九四七年に施行された。', 'にほんの けんぽうは せんきゅうひゃくよんじゅうななねんに しこう された。', 'Hiến pháp Nhật Bản có hiệu lực từ năm 1947.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7776, 46130, '市の財政が厳しくなっている。', 'しの ざいせいが きびしく なって いる。', 'Tài chính của thành phố đang trở nên khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7777, 44793, '拾った財布を交番に届けた。', 'ひろった さいふを こうばんに とどけた。', 'Tôi mang chiếc ví nhặt được đến đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7778, 46134, '所得が多い人ほど税金が高い。', 'しょとくが おおい ひと ほど ぜいきんが たかい。', 'Người thu nhập càng cao thì thuế càng nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7779, 31080, '入社後、営業部に配属された。', 'にゅうしゃご、えいぎょうぶに はいぞく された。', 'Sau khi vào công ty tôi được phân về phòng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7780, 46140, '銀行から店を開くための融資を受けた。', 'ぎんこうから みせを ひらく ための ゆうしを うけた。', 'Tôi được ngân hàng cho vay vốn để mở cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7781, 46239, '相手の立場になって考えてみよう。', 'あいての たちばに なって かんがえて みよう。', 'Hãy thử đặt mình vào vị trí của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7782, 46267, 'アンケートの結果を分析した。', 'アンケートの けっかを ぶんせき した。', 'Tôi đã phân tích kết quả khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7783, 46329, '彼女の初めての本が出版された。', 'かのじょの はじめての ほんが しゅっぱん された。', 'Cuốn sách đầu tay của cô ấy đã được xuất bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7784, 46336, '新聞に求人の広告を出した。', 'しんぶんに きゅうじんの こうこくを だした。', 'Chúng tôi đăng quảng cáo tuyển dụng trên báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7785, 46340, '彼の仕事は上司に高く評価された。', 'かれの しごとは じょうしに たかく ひょうか された。', 'Công việc của anh ấy được cấp trên đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7786, 38517, '妻と二人で住んでいます。', 'つまと ふたりで すんで います。', 'Tôi sống cùng vợ, hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7787, 38513, '先生にお土産を差し上げました。', 'せんせいに おみやげを さしあげました。', 'Tôi biếu thầy món quà lưu niệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7788, 38504, '京都でお寺を見物しました。', 'きょうとで おてらを けんぶつ しました。', 'Tôi tham quan chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7789, 38506, '湖でボートに乗りました。', 'みずうみで ボートに のりました。', 'Tôi đi thuyền trên hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7790, 38495, '看護婦さんが薬を持ってきました。', 'かんごふさんが くすりを もって きました。', 'Cô y tá mang thuốc đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7791, 38510, '妹は高校生です。', 'いもうとは こうこうせい です。', 'Em gái tôi là học sinh cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7792, 38501, 'このスカーフは絹でできています。', 'この スカーフは きぬで できて います。', 'Chiếc khăn này làm bằng lụa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7793, 38512, '朝の電車は込んでいます。', 'あさの でんしゃは こんで います。', 'Tàu buổi sáng đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7794, 38509, '急に雨が降り出しました。', 'きゅうに あめが ふりだしました。', 'Trời bỗng đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7795, 38515, '最後まであきらめないでください。', 'さいごまで あきらめないで ください。', 'Đừng bỏ cuộc cho đến cuối cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7796, 38493, '窓ガラスが割れました。', 'まど ガラスが われました。', 'Kính cửa sổ bị vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7797, 38542, '数学のテストで百点を取った。', 'すうがくの テストで ひゃくてんを とった。', 'Tôi được một trăm điểm bài kiểm tra toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7798, 46341, '政府の政策は多くの人から批判された。', 'せいふの せいさくは おおくの ひとから ひはん された。', 'Chính sách của chính phủ bị nhiều người phê phán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7799, 46390, 'お客様のクレームに丁寧に対応した。', 'おきゃくさまの クレームに ていねいに たいおう した。', 'Tôi đã xử lý khiếu nại của khách một cách lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7800, 46453, 'この紙は再生紙から作られている。', 'この かみは さいせいしから つくられて いる。', 'Loại giấy này được làm từ giấy tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7801, 46478, '会社は経費を削減することにした。', 'かいしゃは けいひを さくげん する ことに した。', 'Công ty quyết định cắt giảm chi phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7802, 46490, '市の財政が厳しくなっている。', 'しの ざいせいが きびしく なって いる。', 'Tài chính của thành phố đang trở nên khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7803, 46494, '所得が多い人ほど税金が高い。', 'しょとくが おおい ひと ほど ぜいきんが たかい。', 'Người thu nhập càng cao thì thuế càng nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7804, 46498, 'あの会社は株式を上場した。', 'あの かいしゃは かぶしきを じょうじょう した。', 'Công ty đó đã niêm yết cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7805, 46500, '銀行から店を開くための融資を受けた。', 'ぎんこうから みせを ひらく ための ゆうしを うけた。', 'Tôi được ngân hàng cho vay vốn để mở cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7806, 46503, '銀行に預けても、利子はほとんどつかない。', 'ぎんこうに あずけても、りしは ほとんど つかない。', 'Gửi ngân hàng cũng hầu như chẳng có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7807, 46505, '為替のレートは毎日変わる。', 'かわせの レートは まいにち かわる。', 'Tỷ giá hối đoái thay đổi mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7808, 46506, '円高のおかげで、海外旅行が安くなった。', 'えんだかの おかげで、かいがい りょこうが やすく なった。', 'Nhờ đồng yên tăng giá, du lịch nước ngoài rẻ hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7809, 46508, 'ベトナムの通貨はドンです。', 'ベトナムの つうかは ドン です。', 'Đơn vị tiền tệ của Việt Nam là đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7810, 46513, '消費者の声を聞いて商品を改善した。', 'しょうひしゃの こえを きいて しょうひんを かいぜん した。', 'Chúng tôi lắng nghe người tiêu dùng để cải tiến sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7811, 46515, 'この業界は競争が激しい。', 'この ぎょうかいは きょうそうが はげしい。', 'Ngành này cạnh tranh gay gắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7812, 46517, '不況で多くの会社が倒産した。', 'ふきょうで おおくの かいしゃが とうさん した。', 'Do suy thoái, nhiều công ty đã phá sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7813, 38541, '日本の人は親切です。', 'にほんの ひとは しんせつ です。', 'Người Nhật rất tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7814, 38539, '森の中を散歩しました。', 'もりの なかを さんぽ しました。', 'Tôi đi dạo trong rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7815, 38531, 'はい、承知しました。', 'はい、しょうち しました。', 'Vâng, tôi đã rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7816, 38526, 'わからない言葉を辞典で調べました。', 'わからない ことばを じてんで しらべました。', 'Tôi tra từ không hiểu trong từ điển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7817, 38528, '来月、試験を受けます。', 'らいげつ、しけんを うけます。', 'Tháng sau tôi dự thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7818, 38524, '針と糸でボタンをつけました。', 'はりと いとで ボタンを つけました。', 'Tôi khâu cúc bằng kim và chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7819, 38533, 'パンが焼けました。', 'パンが やけました。', 'Bánh mì đã nướng xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7820, 38523, 'やっと雨が止みました。', 'やっと あめが やみました。', 'Cuối cùng mưa cũng tạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7821, 38530, '庭に小鳥が来ています。', 'にわに ことりが きて います。', 'Có chim nhỏ đến vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7822, 38527, '黒板の字をノートに写しました。', 'こくばんの じを ノートに うつしました。', 'Tôi chép chữ trên bảng vào vở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7823, 38534, 'どうぞ、上がってください。', 'どうぞ、あがって ください。', 'Mời anh vào nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7824, 38551, '来年の三月に大学を卒業します。', 'らいねんの さんがつに だいがくを そつぎょう します。', 'Tháng ba năm sau tôi tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7825, 38556, 'この辺りの地理に詳しいですか。', 'この あたりの ちりに くわしい ですか。', 'Bạn có rành đường sá quanh đây không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7826, 38575, '授業のあと、すぐに復習するといい。', 'じゅぎょうの あと、すぐに ふくしゅう すると いい。', 'Học xong nên ôn bài ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7827, 38586, '授業の前に予習しておきましょう。', 'じゅぎょうの まえに よしゅう して おきましょう。', 'Hãy chuẩn bị bài trước giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7828, 46526, '会社は海外の事業を縮小した。', 'かいしゃは かいがいの じぎょうを しゅくしょう した。', 'Công ty đã thu hẹp hoạt động kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7829, 46528, '株価が大きく下落した。', 'かぶかが おおきく げらく した。', 'Giá cổ phiếu sụt giảm mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7830, 46529, '野菜の値段は天気によって変動する。', 'やさいの ねだんは てんきに よって へんどう する。', 'Giá rau biến động theo thời tiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7831, 46532, 'その会社は多額の負債を抱えている。', 'その かいしゃは たがくの ふさいを かかえて いる。', 'Công ty đó đang gánh khoản nợ lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7832, 46533, '台風で会社は大きな損失を出した。', 'たいふうで かいしゃは おおきな そんしつを だした。', 'Do bão, công ty chịu tổn thất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7833, 46536, '引っ越しの見積もりを三社に頼んだ。', 'ひっこしの みつもりを さんしゃに たのんだ。', 'Tôi nhờ ba công ty báo giá chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7834, 46538, '夜にATMを使うと手数料がかかる。', 'よるに エーティーエムを つかうと てすうりょうが かかる。', 'Dùng ATM vào ban đêm sẽ mất phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7835, 46540, 'この商売は儲けが少ない。', 'この しょうばいは もうけが すくない。', 'Việc buôn bán này lời ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7836, 46543, '彼はこの仕事の経験が乏しい。', 'かれは この しごとの けいけんが とぼしい。', 'Anh ấy còn ít kinh nghiệm trong công việc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7837, 46546, '夜になって、気温が急激に下がった。', 'よるに なって、きおんが きゅうげきに さがった。', 'Về đêm nhiệt độ giảm đột ngột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7838, 46550, '日本の憲法は一九四七年に施行された。', 'にほんの けんぽうは せんきゅうひゃくよんじゅうななねんに しこう された。', 'Hiến pháp Nhật Bản có hiệu lực từ năm 1947.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7839, 46551, '二つの国は平和条約を結んだ。', 'ふたつの くには へいわ じょうやくを むすんだ。', 'Hai nước đã ký hiệp ước hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7840, 46553, '政府は輸入を規制している。', 'せいふは ゆにゅうを きせい して いる。', 'Chính phủ đang hạn chế nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7841, 46555, 'スピード違反で罰金を取られた。', 'スピード いはんで ばっきんを とられた。', 'Tôi bị phạt tiền vì chạy quá tốc độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7842, 46557, '裁判所は無罪の判決を下した。', 'さいばんしょは むざいの はんけつを くだした。', 'Tòa án đã tuyên án vô tội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7843, 46559, '犯人だという証拠がない。', 'はんにん だと いう しょうこが ない。', 'Không có bằng chứng cho thấy đó là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7844, 38574, '夫は料理が上手です。', 'おっとは りょうりが じょうず です。', 'Chồng tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7845, 28674, '説明書を見ながら、机を組み立てました。', 'せつめいしょを みながら、つくえを くみたてました。', 'Tôi vừa xem hướng dẫn vừa lắp ráp cái bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7846, 38547, '赤ん坊が泣いています。', 'あかんぼうが ないて います。', 'Em bé đang khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7847, 38582, 'この犬は毛が長いです。', 'この いぬは けが ながい です。', 'Con chó này lông dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7848, 38563, '店員にサイズを聞きました。', 'てんいんに サイズを ききました。', 'Tôi hỏi nhân viên cửa hàng về cỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7849, 38566, '湯を沸かしてください。', 'ゆを わかして ください。', 'Hãy đun nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7850, 38580, '味噌汁を作りました。', 'みそしるを つくりました。', 'Tôi nấu súp miso.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7851, 38608, 'プリンターのインクがなくなった。', 'プリンターの インクが なくなった。', 'Máy in hết mực rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7852, 38609, '父は寝る前にウイスキーを少し飲む。', 'ちちは ねる まえに ウイスキーを すこし のむ。', 'Bố tôi uống một chút whisky trước khi ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7853, 38605, '子供のいたずらで、壁に落書きされた。', 'こどもの いたずらで、かべに らくがき された。', 'Bọn trẻ nghịch ngợm vẽ bậy lên tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7854, 38597, 'ボールが線の外に出て、アウトになった。', 'ボールが せんの そとに でて、アウトに なった。', 'Bóng ra ngoài vạch nên bị tính là out.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7855, 38598, '鍵をあちこち探したが、見つからない。', 'かぎを あちこち さがしたが、みつからない。', 'Tôi tìm chìa khóa khắp nơi mà không thấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7856, 38599, 'あっ、財布を忘れた!', 'あっ、さいふを わすれた!', 'Ôi, quên ví rồi!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7857, 38601, '電話あるいはメールで連絡してください。', 'でんわ あるいは メールで れんらく して ください。', 'Hãy liên lạc qua điện thoại hoặc email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7858, 38602, 'この映画はあんまりおもしろくなかった。', 'この えいがは あんまり おもしろく なかった。', 'Bộ phim này không hay lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7859, 38603, 'ここでたばこを吸ってはいけません。', 'ここで たばこを すっては いけません。', 'Không được hút thuốc ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7860, 38604, 'いずれまた会いましょう。', 'いずれ また あいましょう。', 'Rồi sẽ có dịp gặp lại nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7861, 38606, 'いつまでも元気でいてください。', 'いつまでも げんきで いて ください。', 'Mong bạn mãi luôn khỏe mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7862, 38607, '電車が遅れて、いらいらした。', 'でんしゃが おくれて、いらいら した。', 'Tàu bị trễ làm tôi bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7863, 46560, '身分を証明するものを持っていますか。', 'みぶんを しょうめい する ものを もって いますか。', 'Bạn có giấy tờ chứng minh nhân thân không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7864, 46563, '行政のサービスがオンラインで使えるようになった。', 'ぎょうせいの サービスが オンラインで つかえる ように なった。', 'Dịch vụ hành chính giờ đã dùng được trực tuyến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7865, 46565, '与党は選挙で過半数を取った。', 'よとうは せんきょで かはんすうを とった。', 'Đảng cầm quyền đã giành quá bán trong cuộc bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7866, 46570, '来月から新しい制度を実施する。', 'らいげつから あたらしい せいどを じっし する。', 'Từ tháng sau sẽ thực thi chế độ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7867, 46590, '大きな組織で働くのは大変だ。', 'おおきな そしきで はたらくのは たいへんだ。', 'Làm việc trong một tổ chức lớn thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7868, 28679, 'わからないことを先生に質問しました。', 'わからない ことを せんせいに しつもん しました。', 'Tôi hỏi thầy điều mình không hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7869, 28682, '大阪のお城を見に行きました。', 'おおさかの おしろを みに いきました。', 'Tôi đi xem lâu đài Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7870, 28687, '黒のスーツを着て行きました。', 'くろの スーツを きて いきました。', 'Tôi mặc bộ vest đen đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7871, 28689, '信号が赤のときは渡ってはいけません。', 'しんごうが あかの ときは わたっては いけません。', 'Khi đèn đỏ không được sang đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7872, 28693, '茶色のかばんを買いました。', 'ちゃいろの かばんを かいました。', 'Tôi mua chiếc cặp màu nâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7873, 28699, 'さっき田中さんから電話がありました。', 'さっき たなかさんから でんわが ありました。', 'Lúc nãy có điện thoại của anh Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7874, 38593, '子どもを公園へ連れて行きました。', 'こどもを こうえんへ つれて いきました。', 'Tôi dẫn con đi công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7875, 38595, '何か用ですか。', 'なにか よう ですか。', 'Có việc gì không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7876, 38589, 'テーブルからコップが落ちました。', 'テーブルから コップが おちました。', 'Cái cốc rơi từ trên bàn xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7877, 38588, '祭りで日本の踊りを見ました。', 'まつりで にほんの おどりを みました。', 'Tôi xem điệu múa Nhật ở lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7878, 38698, 'チームのメンバーは全部で十人です。', 'チームの メンバーは ぜんぶで じゅうにん です。', 'Đội có tất cả mười thành viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7879, 38610, '外から帰ったら、手を洗ってうがいをしよう。', 'そとから かえったら、てを あらって うがいを しよう。', 'Đi ngoài về thì rửa tay và súc miệng nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7880, 38708, 'わがままばかり言っていると、友達がいなくなるよ。', 'わがまま ばかり いって いると、ともだちが いなく なるよ。', 'Cứ ích kỷ đòi hỏi mãi thì sẽ mất hết bạn đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7881, 38710, '雨にぬれた子猫の姿は哀れだった。', 'あめに ぬれた こねこの すがたは あわれ だった。', 'Hình ảnh chú mèo con ướt mưa thật đáng thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7882, 38711, '母の愛はどんなものより深い。', 'ははの あいは どんな ものより ふかい。', 'Tình yêu của mẹ sâu nặng hơn bất cứ điều gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7883, 38712, '彼は家族を心から愛している。', 'かれは かぞくを こころから あいして いる。', 'Anh ấy yêu gia đình bằng cả trái tim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7884, 38713, '祖父母の愛情を受けて育った。', 'そふぼの あいじょうを うけて そだった。', 'Tôi lớn lên trong tình yêu thương của ông bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7885, 31470, '最後まで諦めないでください。', 'さいごまで あきらめないで ください。', 'Đừng bỏ cuộc cho đến phút cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7886, 31471, '彼は三時間粘って、やっと問題を解いた。', 'かれは さんじかん ねばって、やっと もんだいを といた。', 'Anh ấy kiên trì ba tiếng và cuối cùng giải được bài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7887, 31472, '痛くても、もう少し我慢してください。', 'いたくても、もう すこし がまん して ください。', 'Dù đau cũng hãy chịu đựng thêm chút nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7888, 38714, '人の悪口を言うのはやめなさい。', 'ひとの わるくちを いうのは やめなさい。', 'Thôi ngay việc nói xấu người khác đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7889, 38721, '何かいい案はありませんか。', 'なにか いい あんは ありませんか。', 'Có ai có ý kiến hay nào không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7890, 31462, '継続は力なり。', 'けいぞくは ちからなり。', 'Kiên trì là sức mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7891, 31465, '工事の予定を一週間前倒しすることになった。', 'こうじの よていを いっしゅうかん まえだおし する ことに なった。', 'Lịch thi công được đẩy sớm lên một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7892, 31467, '今は仕事より健康を優先したい。', 'いまは しごとより けんこうを ゆうせん したい。', 'Bây giờ tôi muốn ưu tiên sức khỏe hơn công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7893, 31468, '面倒なことをつい後回しにしてしまう。', 'めんどうな ことを つい あとまわしに して しまう。', 'Việc phiền phức là tôi hay để sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7894, 31469, '会社全体で省エネに取り組んでいる。', 'かいしゃ ぜんたいで しょうエネに とりくんで いる。', 'Cả công ty đang nỗ lực tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7895, 31458, '最近、子供の体力が低下している。', 'さいきん、こどもの たいりょくが ていか して いる。', 'Gần đây thể lực của trẻ em đang suy giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7896, 31460, 'この村の人口は減少している。', 'この むらの じんこうは げんしょう して いる。', 'Dân số làng này đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7897, 38611, '犬が知らない人を見て唸った。', 'いぬが しらない ひとを みて うなった。', 'Con chó gầm gừ khi thấy người lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7898, 38715, 'その映画には恐ろしい悪魔が出てくる。', 'その えいがには おそろしい あくまが でて くる。', 'Trong phim đó có một con quỷ đáng sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7899, 38699, 'もしも宝くじが当たったら、何をしますか。', 'もしも たからくじが あたったら、なにを しますか。', 'Nếu như trúng xổ số, bạn sẽ làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7900, 38700, 'やがて雨もやむでしょう。', 'やがて あめも やむでしょう。', 'Chẳng bao lâu nữa mưa sẽ tạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7901, 38701, 'やはり彼の言ったとおりだった。', 'やはり かれの いった とおり だった。', 'Quả nhiên đúng như anh ấy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7902, 38702, '今日はやや寒いですね。', 'きょうは やや さむい ですね。', 'Hôm nay hơi lạnh nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7903, 38709, 'わざと負けたわけではない。', 'わざと まけた わけでは ない。', 'Không phải tôi cố tình thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7904, 38717, '試合のあと、選手たちは握手をした。', 'しあいの あと、せんしゅたちは あくしゅを した。', 'Sau trận đấu, các cầu thủ bắt tay nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7905, 38731, '田中さん一家は去年東京に引っ越した。', 'たなかさん いっかは きょねん とうきょうに ひっこした。', 'Gia đình anh Tanaka đã chuyển lên Tokyo năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7906, 31491, '彼は会社の命令を拒否した。', 'かれは かいしゃの めいれいを きょひ した。', 'Anh ấy đã từ chối mệnh lệnh của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7907, 31492, 'その意見に同意します。', 'その いけんに どうい します。', 'Tôi đồng ý với ý kiến đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7908, 38720, '試験の前に単語を暗記した。', 'しけんの まえに たんごを あんき した。', 'Trước kỳ thi tôi học thuộc lòng từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7909, 38725, 'クラスの図書委員に選ばれた。', 'クラスの としょ いいんに えらばれた。', 'Tôi được bầu làm ủy viên thư viện của lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7910, 31479, '人の家に勝手に入らないのは常識だ。', 'ひとの いえに かってに はいらないのは じょうしきだ。', 'Không tự tiện vào nhà người khác là lẽ thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7911, 31480, '外国人に偏見を持ってはいけない。', 'がいこくじんに へんけんを もっては いけない。', 'Không được có định kiến với người nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7912, 31481, '男女の差別をなくすべきだ。', 'だんじょの さべつを なくす べきだ。', 'Cần xóa bỏ phân biệt nam nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7913, 31482, 'すべての人は法の前に平等だ。', 'すべての ひとは ほうの まえに びょうどうだ。', 'Mọi người đều bình đẳng trước pháp luật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7914, 31483, '休みの日は自由に過ごしたい。', 'やすみの ひは じゆうに すごしたい。', 'Ngày nghỉ tôi muốn được tự do thoải mái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7915, 31490, '計画は部長の承認を得た。', 'けいかくは ぶちょうの しょうにんを えた。', 'Kế hoạch đã được trưởng phòng phê duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7916, 38728, '被災地に衣服や毛布を送った。', 'ひさいちに いふくや もうふを おくった。', 'Chúng tôi gửi quần áo và chăn cho vùng bị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7917, 38727, '会議室を三階に移動します。', 'かいぎしつを さんがいに いどう します。', 'Phòng họp sẽ chuyển lên tầng ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7918, 38722, '以前ここに古い映画館があった。', 'いぜん ここに ふるい えいがかんが あった。', 'Trước đây ở chỗ này có một rạp chiếu phim cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7919, 38732, '一時はどうなるかと思った。', 'いちじは どう なるかと おもった。', 'Có lúc tôi đã lo không biết rồi sẽ ra sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7920, 38718, 'ガラスの物なので、丁寧に扱ってください。', 'ガラスの もの なので、ていねいに あつかって ください。', 'Đồ thủy tinh nên xin hãy cầm nhẹ tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7921, 38724, '正しい答えを丸で囲みなさい。', 'ただしい こたえを まるで かこみなさい。', 'Hãy khoanh tròn đáp án đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7922, 38719, '安定した仕事に就きたい。', 'あんてい した しごとに つきたい。', 'Tôi muốn có một công việc ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7923, 38723, '彼は偉大な科学者として知られている。', 'かれは いだいな かがくしゃと して しられて いる。', 'Ông ấy được biết đến như một nhà khoa học vĩ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7924, 31475, 'この祭りには三百年の伝統がある。', 'この まつりには さんびゃくねんの でんとうが ある。', 'Lễ hội này có truyền thống ba trăm năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7925, 31476, 'この村には古い習俗が残っている。', 'この むらには ふるい しゅうぞくが のこって いる。', 'Làng này vẫn giữ những tập tục cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7926, 31478, '電車の中で大声で話すのはマナー違反だ。', 'でんしゃの なかで おおごえで はなすのは マナーいはんだ。', 'Nói to trên tàu là vi phạm phép lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7927, 38726, '国によって習慣が異なる。', 'くにに よって しゅうかんが ことなる。', 'Mỗi nước có phong tục khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7928, 38733, 'トマトは野菜の一種だ。', 'トマトは やさいの いっしゅだ。', 'Cà chua là một loại rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7929, 46599, '相手の立場になって考えてみよう。', 'あいての たちばに なって かんがえて みよう。', 'Hãy thử đặt mình vào vị trí của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7930, 38735, '先生は学生一人一人に話しかけた。', 'せんせいは がくせい ひとりひとりに はなしかけた。', 'Thầy giáo trò chuyện với từng học sinh một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7931, 38747, '二人が付き合っているという噂を聞いた。', 'ふたりが つきあって いると いう うわさを きいた。', 'Tôi nghe đồn hai người đó đang hẹn hò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7932, 38743, 'その選手は今シーズンで引退する。', 'その せんしゅは こんシーズンで いんたい する。', 'Vận động viên đó sẽ giải nghệ sau mùa giải này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7933, 31501, '日本は車をたくさん輸出している。', 'にほんは くるまを たくさん ゆしゅつ して いる。', 'Nhật Bản xuất khẩu rất nhiều ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7934, 31502, 'この店の果物はほとんどが輸入品だ。', 'この みせの くだものは ほとんどが ゆにゅうひんだ。', 'Hoa quả ở cửa hàng này hầu hết là hàng nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7935, 31505, '景気がよくなって、給料が上がった。', 'けいきが よく なって、きゅうりょうが あがった。', 'Kinh tế khởi sắc nên lương tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7936, 31506, '不況で仕事を探すのが難しい。', 'ふきょうで しごとを さがすのが むずかしい。', 'Kinh tế suy thoái nên tìm việc rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7937, 31504, 'インフレで物の値段が上がり続けている。', 'インフレで ものの ねだんが あがり つづけて いる。', 'Do lạm phát, giá cả cứ tiếp tục tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7938, 38744, 'レポートに新聞の記事を引用した。', 'レポートに しんぶんの きじを いんよう した。', 'Tôi đã trích dẫn một bài báo vào bản báo cáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7939, 31497, '東京で国際会議が開かれた。', 'とうきょうで こくさい かいぎが ひらかれた。', 'Một hội nghị quốc tế đã được tổ chức ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7940, 31498, '今年の夏は国内を旅行するつもりだ。', 'ことしの なつは こくないを りょこう する つもりだ。', 'Hè này tôi định du lịch trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7941, 38734, '一瞬、何が起きたのかわからなかった。', 'いっしゅん、なにが おきたのか わからなかった。', 'Trong khoảnh khắc, tôi không hiểu chuyện gì xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7942, 38748, '二人は永遠の愛を誓った。', 'ふたりは えいえんの あいを ちかった。', 'Hai người thề nguyện yêu nhau mãi mãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7943, 38745, '彼は何かを隠しているようだ。', 'かれは なにかを かくして いる ようだ。', 'Hình như anh ấy đang giấu điều gì đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7944, 38746, '猫がベッドの下に隠れている。', 'ねこが ベッドの したに かくれて いる。', 'Con mèo đang trốn dưới gầm giường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7945, 38738, 'この施設は一般の人も利用できる。', 'この しせつは いっぱんの ひとも りよう できる。', 'Cơ sở này người dân bình thường cũng dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7946, 38741, '会議の資料を二十部印刷した。', 'かいぎの しりょうを にじゅうぶ いんさつ した。', 'Tôi in hai mươi bản tài liệu họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7947, 38740, '大事なところに赤い印をつけた。', 'だいじな ところに あかい しるしを つけた。', 'Tôi đánh dấu đỏ vào chỗ quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7948, 38736, 'これから一層努力します。', 'これから いっそう どりょく します。', 'Từ nay tôi sẽ nỗ lực hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7949, 38737, 'そんなにたくさん一度に覚えられない。', 'そんなに たくさん いちどに おぼえられない。', 'Nhiều như thế không thể nhớ hết cùng một lúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7950, 46689, '彼女の初めての本が出版された。', 'かのじょの はじめての ほんが しゅっぱん された。', 'Cuốn sách đầu tay của cô ấy đã được xuất bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7951, 46696, '新聞に求人の広告を出した。', 'しんぶんに きゅうじんの こうこくを だした。', 'Chúng tôi đăng quảng cáo tuyển dụng trên báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7952, 46698, '記者が大臣に質問した。', 'きしゃが だいじんに しつもん した。', 'Phóng viên đặt câu hỏi cho bộ trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7953, 28706, '昼ごはんに親子どんぶりを作りました。', 'ひるごはんに おやこどんぶりを つくりました。', 'Bữa trưa tôi nấu món oyako-don.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7954, 28708, '四人分の料理を作ります。', 'よにんぶんの りょうりを つくります。', 'Tôi nấu món ăn cho bốn người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7955, 38766, '先生の恩は一生忘れません。', 'せんせいの おんは いっしょう わすれません。', 'Ơn thầy tôi sẽ không bao giờ quên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7956, 38750, '兄は泳ぎがとても上手だ。', 'あには およぎが とても じょうずだ。', 'Anh tôi bơi rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7957, 31508, '予算が足りなくて、計画を変えた。', 'よさんが たりなくて、けいかくを かえた。', 'Ngân sách không đủ nên tôi phải đổi kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7958, 31509, '今月は出費が多くて赤字だ。', 'こんげつは しゅっぴが おおくて あかじだ。', 'Tháng này chi tiêu nhiều nên bị thâm hụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7959, 31510, '会社は三年ぶりに黒字になった。', 'かいしゃは さんねんぶりに くろじに なった。', 'Sau ba năm, công ty đã có lãi trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7960, 31511, '将来のために少しずつ投資をしている。', 'しょうらいの ために すこしずつ とうしを して いる。', 'Tôi đầu tư từng chút một cho tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7961, 31513, '使わない物を買うのはお金の浪費だ。', 'つかわない ものを かうのは おかねの ろうひだ。', 'Mua đồ không dùng đến là lãng phí tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7962, 31514, '夏は電気の消費が増える。', 'なつは でんきの しょうひが ふえる。', 'Mùa hè lượng điện tiêu thụ tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7963, 31515, '冬は暖房器具の需要が高まる。', 'ふゆは だんぼうきぐの じゅようが たかまる。', 'Mùa đông nhu cầu thiết bị sưởi tăng cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7964, 31516, '地震で水の供給が止まった。', 'じしんで みずの きょうきゅうが とまった。', 'Động đất làm ngừng cung cấp nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7965, 38761, '昔、この国には強い王がいた。', 'むかし、この くにには つよい おうが いた。', 'Ngày xưa đất nước này có một vị vua hùng mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7966, 38762, '王子はお城で育った。', 'おうじは おしろで そだった。', 'Hoàng tử lớn lên trong lâu đài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7967, 38763, '昔々、ある国に王様がいました。', 'むかしむかし、ある くにに おうさまが いました。', 'Ngày xửa ngày xưa, ở một vương quốc nọ có một vị vua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7968, 38765, '屋根の上に猫がいる。', 'やねの うえに ねこが いる。', 'Có con mèo trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7969, 38759, '猫が道を横切った。', 'ねこが みちを よこぎった。', 'Một con mèo băng qua đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7970, 38760, 'ここで道を横断しないでください。', 'ここで みちを おうだん しないで ください。', 'Xin đừng băng qua đường ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7971, 38756, 'ろうそくの炎が風で揺れている。', 'ろうそくの ほのおが かぜで ゆれて いる。', 'Ngọn lửa nến lay động trong gió.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7972, 38764, '沖に大きな船が見える。', 'おきに おおきな ふねが みえる。', 'Ngoài khơi có thể thấy một con tàu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7973, 46700, '彼の仕事は上司に高く評価された。', 'かれの しごとは じょうしに たかく ひょうか された。', 'Công việc của anh ấy được cấp trên đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7974, 46734, '待遇がよくないので、辞める人が多い。', 'たいぐうが よくないので、やめる ひとが おおい。', 'Đãi ngộ không tốt nên nhiều người nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7975, 46750, 'お客様のクレームに丁寧に対応した。', 'おきゃくさまの クレームに ていねいに たいおう した。', 'Tôi đã xử lý khiếu nại của khách một cách lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7976, 46788, 'あいにく、部長は外出しております。', 'あいにく、ぶちょうは がいしゅつ して おります。', 'Rất tiếc, trưởng phòng đang ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7977, 46838, '会社は経費を削減することにした。', 'かいしゃは けいひを さくげん する ことに した。', 'Công ty quyết định cắt giảm chi phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7978, 46850, '市の財政が厳しくなっている。', 'しの ざいせいが きびしく なって いる。', 'Tài chính của thành phố đang trở nên khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7979, 46854, '所得が多い人ほど税金が高い。', 'しょとくが おおい ひと ほど ぜいきんが たかい。', 'Người thu nhập càng cao thì thuế càng nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7980, 46858, 'あの会社は株式を上場した。', 'あの かいしゃは かぶしきを じょうじょう した。', 'Công ty đó đã niêm yết cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7981, 28714, '肉を適当な大きさに切ってください。', 'にくを てきとうな おおきさに きって ください。', 'Hãy cắt thịt với kích cỡ vừa phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7982, 38776, '息子の嫁はとても料理が上手だ。', 'むすこの よめは とても りょうりが じょうずだ。', 'Con dâu tôi nấu ăn rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7983, 38781, 'お会計はレジでお願いします。', 'おかいけいは レジで おねがい します。', 'Xin vui lòng thanh toán tại quầy thu ngân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7984, 38777, '一番好きな科目は数学です。', 'いちばん すきな かもくは すうがく です。', 'Môn học tôi thích nhất là toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7985, 38778, '火災が起きたら、すぐに逃げてください。', 'かさいが おきたら、すぐに にげて ください。', 'Nếu xảy ra hỏa hoạn, hãy chạy thoát ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7986, 38886, '軍が災害地に送られた。', 'ぐんが さいがいちに おくられた。', 'Quân đội đã được điều đến vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7987, 38769, '下りの電車は混んでいなかった。', 'くだりの でんしゃは こんで いなかった。', 'Tàu chiều đi ra ngoại ô không đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7988, 38774, 'お風呂の湯加減はどうですか。', 'おふろの ゆかげんは どう ですか。', 'Nước tắm nóng vừa chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7989, 38772, 'スープに塩を少し加えてください。', 'スープに しおを すこし くわえて ください。', 'Hãy cho thêm một chút muối vào súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7990, 38773, '新しいメンバーがチームに加わった。', 'あたらしい メンバーが チームに くわわった。', 'Có thành viên mới gia nhập đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7991, 38768, '今日は海が穏やかだ。', 'きょうは うみが おだやかだ。', 'Hôm nay biển lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7992, 38775, '明日までに終わらせるのは可能ですか。', 'あしたまでに おわらせるのは かのう ですか。', 'Có thể làm xong trước ngày mai không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7993, 38780, 'この絵は有名な画家が描いたものだ。', 'この えは ゆうめいな がかが かいた ものだ。', 'Bức tranh này do một họa sĩ nổi tiếng vẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7994, 38770, '何で昨日来なかったの。', 'なんで きのう こなかったの。', 'Sao hôm qua không đến?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7995, 38771, '何とか締め切りに間に合った。', 'なんとか しめきりに まにあった。', 'Bằng cách nào đó tôi cũng kịp hạn chót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7996, 46860, '銀行から店を開くための融資を受けた。', 'ぎんこうから みせを ひらく ための ゆうしを うけた。', 'Tôi được ngân hàng cho vay vốn để mở cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7997, 46863, '銀行に預けても、利子はほとんどつかない。', 'ぎんこうに あずけても、りしは ほとんど つかない。', 'Gửi ngân hàng cũng hầu như chẳng có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7998, 46865, '為替のレートは毎日変わる。', 'かわせの レートは まいにち かわる。', 'Tỷ giá hối đoái thay đổi mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (7999, 46866, '円高のおかげで、海外旅行が安くなった。', 'えんだかの おかげで、かいがい りょこうが やすく なった。', 'Nhờ đồng yên tăng giá, du lịch nước ngoài rẻ hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8000, 46868, 'ベトナムの通貨はドンです。', 'ベトナムの つうかは ドン です。', 'Đơn vị tiền tệ của Việt Nam là đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8001, 46873, '消費者の声を聞いて商品を改善した。', 'しょうひしゃの こえを きいて しょうひんを かいぜん した。', 'Chúng tôi lắng nghe người tiêu dùng để cải tiến sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8002, 46874, 'この野菜には生産者の名前が書いてある。', 'この やさいには せいさんしゃの なまえが かいて ある。', 'Trên rau này có ghi tên người sản xuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8003, 28721, '日本に来てから三年たちました。', 'にほんに きてから さんねん たちました。', 'Từ khi đến Nhật đã ba năm trôi qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8004, 28728, '車に乗ったら、シートベルトをしてください。', 'くるまに のったら、シートベルトを して ください。', 'Lên xe thì hãy thắt dây an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8005, 28741, '港に大きな船が止まっています。', 'みなとに おおきな ふねが とまって います。', 'Ở cảng có một con tàu lớn đang đậu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8006, 28743, 'デパートの屋上から花火が見えます。', 'デパートの おくじょうから はなびが みえます。', 'Từ sân thượng trung tâm thương mại có thể xem pháo hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8007, 28750, '漢字にふりがなを書いてください。', 'かんじに ふりがなを かいて ください。', 'Hãy viết phiên âm furigana cho chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8008, 28766, '大黒ずしのすしはおいしいです。', 'だいこくずしの すしは おいしい です。', 'Sushi ở quán Daikoku rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8009, 38782, '今夜、町内会の会合がある。', 'こんや、ちょうないかいの かいごうが ある。', 'Tối nay có buổi họp tổ dân phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8010, 38785, '手術のあと、順調に回復している。', 'しゅじゅつの あと、じゅんちょうに かいふく して いる。', 'Sau phẫu thuật, tôi đang hồi phục tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8011, 31541, '大学で日本の歴史を研究している。', 'だいがくで にほんの れきしを けんきゅう して いる。', 'Tôi nghiên cứu lịch sử Nhật Bản ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8012, 31543, '電話はベルによって発明された。', 'でんわは ベルに よって はつめい された。', 'Điện thoại do Bell phát minh ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8013, 31544, '新しい星が発見された。', 'あたらしい ほしが はっけん された。', 'Một ngôi sao mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8014, 38783, 'この数学の問題が解けない。', 'この すうがくの もんだいが とけない。', 'Tôi không giải được bài toán này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8015, 38790, '両国の外交関係が改善した。', 'りょうこくの がいこう かんけいが かいぜん した。', 'Quan hệ ngoại giao giữa hai nước đã được cải thiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8016, 38791, '部長は今、外出しています。', 'ぶちょうは いま、がいしゅつ して います。', 'Trưởng phòng hiện đang ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8018, 38788, '試験開始の合図があるまで、問題を見ないでください。', 'しけん かいしの あいずが あるまで、もんだいを みないで ください。', 'Đừng xem đề cho đến khi có hiệu lệnh bắt đầu thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8019, 38789, '部屋に入るときは帽子を外しなさい。', 'へやに はいる ときは ぼうしを はずしなさい。', 'Khi vào phòng hãy bỏ mũ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8020, 38786, '新しい部屋はとても快適だ。', 'あたらしい へやは とても かいてきだ。', 'Căn phòng mới rất dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8021, 38787, '美術館で西洋の絵画を見た。', 'びじゅつかんで せいようの かいがを みた。', 'Tôi xem tranh phương Tây ở bảo tàng mỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8022, 31547, 'この会社は技術の革新を続けている。', 'この かいしゃは ぎじゅつの かくしんを つづけて いる。', 'Công ty này không ngừng đổi mới công nghệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8023, 31548, '人工知能が翻訳の仕事を手伝ってくれる。', 'じんこうちのうが ほんやくの しごとを てつだって くれる。', 'Trí tuệ nhân tạo hỗ trợ công việc dịch thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8024, 31550, 'このドアは自動で開きます。', 'この ドアは じどうで ひらきます。', 'Cánh cửa này tự động mở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8025, 31552, 'スマホの言語を日本語に設定した。', 'スマホの げんごを にほんごに せってい した。', 'Tôi cài ngôn ngữ điện thoại sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8026, 31553, 'アプリを最新のバージョンに更新してください。', 'アプリを さいしんの バージョンに こうしん して ください。', 'Hãy cập nhật ứng dụng lên phiên bản mới nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8027, 31554, 'ホテルのWi-Fiに接続できない。', 'ホテルの ワイファイに せつぞく できない。', 'Tôi không kết nối được Wi-Fi của khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8028, 31555, '山の中は通信が不安定だ。', 'やまの なかは つうしんが ふあんていだ。', 'Trong núi sóng liên lạc không ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8029, 38792, 'たばこは健康に害がある。', 'たばこは けんこうに がいが ある。', 'Thuốc lá có hại cho sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8030, 46876, '弟がテレビを独占している。', 'おとうとが テレビを どくせん して いる。', 'Em trai tôi độc chiếm cái tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8031, 46880, '今年の景況は去年より厳しい。', 'ことしの けいきょうは きょねんより きびしい。', 'Tình hình kinh doanh năm nay khó khăn hơn năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8032, 46886, '会社は海外の事業を縮小した。', 'かいしゃは かいがいの じぎょうを しゅくしょう した。', 'Công ty đã thu hẹp hoạt động kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8033, 46889, '野菜の値段は天気によって変動する。', 'やさいの ねだんは てんきに よって へんどう する。', 'Giá rau biến động theo thời tiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8034, 38900, '弟とつまらないことで喧嘩した。', 'おとうとと つまらない ことで けんか した。', 'Tôi cãi nhau với em trai vì chuyện vớ vẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8035, 38897, '来年留学しようと決心した。', 'らいねん りゅうがく しようと けっしん した。', 'Tôi đã quyết tâm sang năm sẽ đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8036, 37752, 'その映画を見て、とても感動した。', 'その えいがを みて、とても かんどう した。', 'Xem bộ phim đó tôi rất cảm động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8037, 37753, '最近、環境問題に関心を持っている。', 'さいきん、かんきょう もんだいに かんしんを もって いる。', 'Gần đây tôi quan tâm đến vấn đề môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8038, 38896, '寮には夜十時までに帰る決まりがある。', 'りょうには よる じゅうじまでに かえる きまりが ある。', 'Ký túc xá có quy định phải về trước 10 giờ tối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8039, 38898, '靴下に穴があいている。', 'くつしたに あなが あいて いる。', 'Chiếc tất bị thủng một lỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8040, 38899, '靴のひもをしっかり結んだ。', 'くつの ひもを しっかり むすんだ。', 'Tôi buộc chặt dây giày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8041, 38895, '夜中に激しい雨が降った。', 'よなかに はげしい あめが ふった。', 'Nửa đêm trời mưa dữ dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8042, 46891, '交通費は会社が負担します。', 'こうつうひは かいしゃが ふたん します。', 'Chi phí đi lại do công ty chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8043, 46893, '台風で会社は大きな損失を出した。', 'たいふうで かいしゃは おおきな そんしつを だした。', 'Do bão, công ty chịu tổn thất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8044, 46894, '事故の被害者に補償金が支払われた。', 'じこの ひがいしゃに ほしょうきんが しはらわれた。', 'Tiền bồi thường đã được trả cho nạn nhân vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8045, 46897, '閉店前に弁当が値引きされる。', 'へいてん まえに べんとうが ねびき される。', 'Trước giờ đóng cửa, cơm hộp được giảm giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8046, 46899, '今月は稼ぎが少なかった。', 'こんげつは かせぎが すくなかった。', 'Tháng này tôi kiếm được ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8047, 46901, '老後のために貯蓄をしている。', 'ろうごの ために ちょちくを して いる。', 'Tôi tiết kiệm cho tuổi già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8048, 46906, '夜になって、気温が急激に下がった。', 'よるに なって、きおんが きゅうげきに さがった。', 'Về đêm nhiệt độ giảm đột ngột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8049, 46908, '病気は徐々によくなっている。', 'びょうきは じょじょに よく なって いる。', 'Bệnh đang dần dần khá lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8050, 46910, '日本の憲法は一九四七年に施行された。', 'にほんの けんぽうは せんきゅうひゃくよんじゅうななねんに しこう された。', 'Hiến pháp Nhật Bản có hiệu lực từ năm 1947.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8051, 46912, 'この仕事の条件はとてもいい。', 'この しごとの じょうけんは とても いい。', 'Điều kiện của công việc này rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8052, 46914, '駐車違反で罰金を払った。', 'ちゅうしゃ いはんで ばっきんを はらった。', 'Tôi bị phạt tiền vì đỗ xe sai quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8053, 46916, '裁判の結果は来月出る。', 'さいばんの けっかは らいげつ でる。', 'Kết quả xét xử sẽ có vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8054, 46918, '弁護士に相談することにした。', 'べんごしに そうだん する ことに した。', 'Tôi quyết định hỏi ý kiến luật sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8055, 46920, '身分を証明するものを持っていますか。', 'みぶんを しょうめい する ものを もって いますか。', 'Bạn có giấy tờ chứng minh nhân thân không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8056, 46923, '行政のサービスがオンラインで使えるようになった。', 'ぎょうせいの サービスが オンラインで つかえる ように なった。', 'Dịch vụ hành chính giờ đã dùng được trực tuyến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8057, 28770, '歯が痛いので、佐藤歯科に行きます。', 'はが いたいので、さとう しかに いきます。', 'Đau răng nên tôi đến nha khoa Sato.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8058, 28772, 'A：あしたは忙しいです。B：それなら、あさってはどうですか。', 'エー：あしたは いそがしい です。ビー：それなら、あさっては どう ですか。', 'A: Mai tôi bận. B: Vậy thì ngày kia thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8059, 28782, 'このことわざの意味を知っていますか。', 'この ことわざの いみを しって いますか。', 'Bạn có biết ý nghĩa câu tục ngữ này không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8060, 38905, '空港まで友達の見送りに行った。', 'くうこうまで ともだちの みおくりに いった。', 'Tôi ra sân bay tiễn bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8061, 38916, 'これは個人の問題だから、口を出さないで。', 'これは こじんの もんだい だから、くちを ださないで。', 'Đây là chuyện cá nhân, đừng xen vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8062, 37771, 'ここに氏名と住所を書いてください。', 'ここに しめいと じゅうしょを かいて ください。', 'Hãy ghi họ tên và địa chỉ vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8063, 38921, '困ったときは、お互いに助け合いましょう。', 'こまった ときは、おたがいに たすけあいましょう。', 'Khi khó khăn thì hãy giúp đỡ lẫn nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8064, 38926, '二人は三年間交際してから結婚した。', 'ふたりは さんねんかん こうさい してから けっこん した。', 'Hai người quen nhau ba năm rồi mới cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8065, 38906, '入院している友達のお見舞いに行った。', 'にゅういん して いる ともだちの おみまいに いった。', 'Tôi đi thăm người bạn đang nằm viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8066, 38917, '緊張したら、深く呼吸してください。', 'きんちょう したら、ふかく こきゅう して ください。', 'Khi căng thẳng, hãy hít thở thật sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8067, 46924, '自治体によってごみの出し方が違う。', 'じちたいに よって ごみの だしかたが ちがう。', 'Mỗi địa phương có cách đổ rác khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8068, 46926, '野党は政府の案に反対している。', 'やとうは せいふの あんに はんたい して いる。', 'Phe đối lập đang phản đối đề án của chính phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8069, 46959, '相手の立場になって考えてみよう。', 'あいての たちばに なって かんがえて みよう。', 'Hãy thử đặt mình vào vị trí của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8070, 46987, 'アンケートの結果を分析した。', 'アンケートの けっかを ぶんせき した。', 'Tôi đã phân tích kết quả khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8071, 47015, '新しい機械で作業の効率が上がった。', 'あたらしい きかいで さぎょうの こうりつが あがった。', 'Nhờ máy mới, hiệu suất công việc tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8072, 47057, 'テレビ局がこの店を取材に来た。', 'テレビきょくが この みせを しゅざいに きた。', 'Đài truyền hình đến phỏng vấn cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8073, 47060, '彼の仕事は上司に高く評価された。', 'かれの しごとは じょうしに たかく ひょうか された。', 'Công việc của anh ấy được cấp trên đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8074, 47094, '待遇がよくないので、辞める人が多い。', 'たいぐうが よくないので、やめる ひとが おおい。', 'Đãi ngộ không tốt nên nhiều người nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8075, 47110, 'お客様のクレームに丁寧に対応した。', 'おきゃくさまの クレームに ていねいに たいおう した。', 'Tôi đã xử lý khiếu nại của khách một cách lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8076, 47148, 'あいにく、部長は外出しております。', 'あいにく、ぶちょうは がいしゅつ して おります。', 'Rất tiếc, trưởng phòng đang ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8077, 47173, 'この紙は再生紙から作られている。', 'この かみは さいせいしから つくられて いる。', 'Loại giấy này được làm từ giấy tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8078, 47208, '空が次第に明るくなってきた。', 'そらが しだいに あかるく なって きた。', 'Bầu trời dần dần sáng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8079, 47212, '結婚を前提に付き合っている。', 'けっこんを ぜんていに つきあって いる。', 'Chúng tôi hẹn hò với tiền đề là sẽ kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8080, 47229, '売り上げが減った要因を調べている。', 'うりあげが へった よういんを しらべて いる。', 'Chúng tôi đang tìm hiểu nhân tố khiến doanh thu giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8081, 47240, '彼はうわさを強く否定した。', 'かれは うわさを つよく ひてい した。', 'Anh ấy kịch liệt phủ nhận tin đồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8082, 28796, 'この曲を聞くと、元気になります。', 'この きょくを きくと、げんきに なります。', 'Nghe bản nhạc này tôi thấy phấn chấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8083, 28763, 'いつかアフリカへ行ってみたいです。', 'いつか アフリカへ いって みたい です。', 'Một ngày nào đó tôi muốn thử đến châu Phi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8084, 28802, '車を買うために貯金しています。', 'くるまを かう ために ちょきん して います。', 'Tôi đang tiết kiệm tiền để mua xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8085, 28812, '毎月国の家族にお金を送っています。', 'まいつき くにの かぞくに おかねを おくって います。', 'Hằng tháng tôi gửi tiền về cho gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8086, 38932, 'この料理は私の好みに合う。', 'この りょうりは わたしの このみに あう。', 'Món này hợp khẩu vị của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8087, 38933, '祖父は静かな生活を好んでいる。', 'そふは しずかな せいかつを このんで いる。', 'Ông tôi thích cuộc sống yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8088, 38935, '幸い、けが人は一人もいなかった。', 'さいわい、けがにんは ひとりも いなかった。', 'May mắn là không ai bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8089, 38936, '幸運にも、最後の一枚のチケットが買えた。', 'こううんにも、さいごの いちまいの チケットが かえた。', 'May mắn thay, tôi mua được tấm vé cuối cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8090, 38937, '家族と過ごす時間が一番の幸福です。', 'かぞくと すごす じかんが いちばんの こうふく です。', 'Thời gian bên gia đình là hạnh phúc lớn nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8091, 38934, '祖父は町の小さな工場で働いていた。', 'そふは まちの ちいさな こうばで はたらいて いた。', 'Ông tôi từng làm ở một xưởng nhỏ trong thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8092, 38939, '相手チームの攻撃をうまく防いだ。', 'あいて チームの こうげきを うまく ふせいだ。', 'Chúng tôi đã chặn tốt các đợt tấn công của đội bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8093, 38931, 'カメラをこちらに向けてください。', 'カメラを こちらに むけて ください。', 'Hãy hướng máy ảnh về phía này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8094, 38938, '噂はすぐに町中に広がった。', 'うわさは すぐに まちじゅうに ひろがった。', 'Tin đồn nhanh chóng lan khắp thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8095, 47259, '曖昧な返事をしないで、はっきり言ってください。', 'あいまいな へんじを しないで、はっきり いって ください。', 'Đừng trả lời mập mờ, hãy nói rõ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8096, 47305, '新しい工場ができて、雇用が増えた。', 'あたらしい こうじょうが できて、こようが ふえた。', 'Có nhà máy mới nên việc làm tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8097, 47339, '被害者は会社を相手に訴訟を起こした。', 'ひがいしゃは かいしゃを あいてに そしょうを おこした。', 'Người bị hại đã khởi kiện công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8098, 47388, '今月は大きな事故が相次いで起きた。', 'こんげつは おおきな じこが あいついで おきた。', 'Tháng này liên tiếp xảy ra các vụ tai nạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8099, 47455, '統計によると、日本の人口は減り続けている。', 'とうけいに よると、にほんの じんこうは へり つづけて いる。', 'Theo thống kê, dân số Nhật tiếp tục giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8100, 47570, '環境の観点から、この計画には問題がある。', 'かんきょうの かんてんから、この けいかくには もんだいが ある。', 'Xét từ quan điểm môi trường, kế hoạch này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8101, 47572, '結婚を前提に付き合っている。', 'けっこんを ぜんていに つきあって いる。', 'Chúng tôi hẹn hò với tiền đề là sẽ kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8102, 47589, '売り上げが減った要因を調べている。', 'うりあげが へった よういんを しらべて いる。', 'Chúng tôi đang tìm hiểu nhân tố khiến doanh thu giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8103, 47600, '彼はうわさを強く否定した。', 'かれは うわさを つよく ひてい した。', 'Anh ấy kịch liệt phủ nhận tin đồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8104, 47619, '曖昧な返事をしないで、はっきり言ってください。', 'あいまいな へんじを しないで、はっきり いって ください。', 'Đừng trả lời mập mờ, hãy nói rõ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8105, 47665, '新しい工場ができて、雇用が増えた。', 'あたらしい こうじょうが できて、こようが ふえた。', 'Có nhà máy mới nên việc làm tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8106, 47701, '会社は損害を賠償することになった。', 'かいしゃは そんがいを ばいしょう する ことに なった。', 'Công ty phải đền bù thiệt hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8107, 28818, 'このことは絶対に忘れません。', 'この ことは ぜったいに わすれません。', 'Chuyện này tôi tuyệt đối không quên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8108, 28829, '新しいことにチャレンジしたいです。', 'あたらしい ことに チャレンジ したい です。', 'Tôi muốn thử thách bản thân với điều mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8109, 28836, '汽船で海を渡りました。', 'きせんで うみを わたりました。', 'Họ vượt biển bằng tàu hơi nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8110, 28848, '電子レンジでご飯を温めます。', 'でんし レンジで ごはんを あたためます。', 'Tôi hâm nóng cơm bằng lò vi sóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8111, 37775, 'この町は高齢者が増えている。', 'この まちは こうれいしゃが ふえて いる。', 'Thị trấn này ngày càng nhiều người cao tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8112, 37776, '最近の若者はあまり新聞を読まない。', 'さいきんの わかものは あまり しんぶんを よまない。', 'Giới trẻ gần đây ít đọc báo giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8113, 37777, '隣の夫婦はとても仲がいい。', 'となりの ふうふは とても なかが いい。', 'Cặp vợ chồng nhà bên rất hòa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8114, 37778, '夫も育児に協力してくれる。', 'おっとも いくじに きょうりょく して くれる。', 'Chồng tôi cũng phụ giúp nuôi con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8115, 38962, '姉は先月、恋人と婚約した。', 'あねは せんげつ、こいびとと こんやく した。', 'Tháng trước chị tôi đã đính hôn với người yêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8116, 38955, '重い物を持って、腰を痛めた。', 'おもい ものを もって、こしを いためた。', 'Tôi bê đồ nặng nên bị đau lưng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8117, 38956, '魚の骨がのどに刺さった。', 'さかなの ほねが のどに ささった。', 'Xương cá bị hóc trong cổ họng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8118, 38957, 'スキーで転んで、足を骨折した。', 'スキーで ころんで、あしを こっせつ した。', 'Tôi ngã khi trượt tuyết và bị gãy chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8119, 38946, '先生の合図で、みんな一斉に走り出した。', 'せんせいの あいずで、みんな いっせいに はしりだした。', 'Theo hiệu lệnh của thầy, mọi người đồng loạt chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8120, 38951, '小学生のとき、国語が得意だった。', 'しょうがくせいの とき、こくごが とくい だった。', 'Hồi tiểu học tôi giỏi môn quốc ngữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8121, 38954, '先生が黒板に字を書いた。', 'せんせいが こくばんに じを かいた。', 'Thầy giáo viết chữ lên bảng đen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8122, 37773, 'この地域は雪が多い。', 'この ちいきは ゆきが おおい。', 'Khu vực này có nhiều tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8123, 37774, '住民が集まって、町の掃除をした。', 'じゅうみんが あつまって、まちの そうじを した。', 'Cư dân tập trung lại dọn dẹp khu phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8124, 37779, '母は祖母の介護をしている。', 'ははは そぼの かいごを して いる。', 'Mẹ tôi đang chăm sóc bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8125, 37780, '姉は福祉の仕事に就いた。', 'あねは ふくしの しごとに ついた。', 'Chị tôi làm trong ngành phúc lợi xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8126, 47748, '今月は大きな事故が相次いで起きた。', 'こんげつは おおきな じこが あいついで おきた。', 'Tháng này liên tiếp xảy ra các vụ tai nạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8127, 47828, 'これは私の専門の領域ではない。', 'これは わたしの せんもんの りょういき では ない。', 'Đây không phải lĩnh vực chuyên môn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8128, 47930, '環境の観点から、この計画には問題がある。', 'かんきょうの かんてんから、この けいかくには もんだいが ある。', 'Xét từ quan điểm môi trường, kế hoạch này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8129, 47932, '結婚を前提に付き合っている。', 'けっこんを ぜんていに つきあって いる。', 'Chúng tôi hẹn hò với tiền đề là sẽ kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8130, 28852, '一人二つずつ取ってください。', 'ひとり ふたつずつ とって ください。', 'Mỗi người hãy lấy hai cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8131, 28860, 'ライト兄弟は初めて飛行機で空を飛びました。', 'ライト きょうだいは はじめて ひこうきで そらを とびました。', 'Anh em nhà Wright lần đầu tiên bay lên trời bằng máy bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8132, 28866, '車に注意してください。', 'くるまに ちゅうい して ください。', 'Hãy chú ý xe cộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8133, 28869, '弟にカメラを壊されました。', 'おとうとに カメラを こわされました。', 'Tôi bị em trai làm hỏng máy ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8134, 28871, '入学式は四月に行われます。', 'にゅうがくしきは しがつに おこなわれます。', 'Lễ nhập học được tổ chức vào tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8135, 28874, 'この本はいろいろな言葉に翻訳されています。', 'この ほんは いろいろな ことばに ほんやく されて います。', 'Cuốn sách này được dịch ra nhiều thứ tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8136, 28883, 'ゆうべ、隣の家に泥棒が入りました。', 'ゆうべ、となりの いえに どろぼうが はいりました。', 'Tối qua nhà bên bị trộm đột nhập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8137, 38003, '合格の通知が郵便で届いた。', 'ごうかくの つうちが ゆうびんで とどいた。', 'Giấy báo đỗ đã được gửi đến qua bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8138, 38989, 'この本には作者の思想がよく表れている。', 'この ほんには さくしゃの しそうが よく あらわれて いる。', 'Tư tưởng của tác giả thể hiện rõ trong cuốn sách này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8139, 38975, '彼は財産をすべて寄付した。', 'かれは ざいさんを すべて きふ した。', 'Ông ấy đã quyên góp toàn bộ tài sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8140, 38976, '作業が終わったら、道具を片付けてください。', 'さぎょうが おわったら、どうぐを かたづけて ください。', 'Làm xong việc thì hãy cất dọn dụng cụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8141, 38977, '今年は雨が少なくて、作物がよく育たない。', 'ことしは あめが すくなくて、さくもつが よく そだたない。', 'Năm nay ít mưa nên hoa màu không phát triển tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8142, 38979, '財布に一万円札が一枚入っている。', 'さいふに いちまんえんさつが いちまい はいって いる。', 'Trong ví có một tờ mười nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8143, 38987, '朝早く市場へ魚を買いに行った。', 'あさ はやく いちばへ さかなを かいに いった。', 'Sáng sớm tôi ra chợ mua cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8144, 38981, '高い山の上は酸素が少ない。', 'たかい やまの うえは さんそが すくない。', 'Trên núi cao ít ô xy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8145, 38990, '先生の指導のおかげで、論文が書けた。', 'せんせいの しどうの おかげで、ろんぶんが かけた。', 'Nhờ sự hướng dẫn của thầy mà tôi viết được luận văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8146, 38974, '彼は自分の罪を認めた。', 'かれは じぶんの つみを みとめた。', 'Anh ta đã thừa nhận tội của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8147, 38005, 'いくつかの会社が連合して、新しい事業を始めた。', 'いくつかの かいしゃが れんごう して、あたらしい じぎょうを はじめた。', 'Vài công ty liên kết lại để bắt đầu dự án kinh doanh mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8148, 38006, '団体で行くと、入場料が安くなる。', 'だんたいで いくと、にゅうじょうりょうが やすく なる。', 'Đi theo đoàn thì vé vào cửa rẻ hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8149, 38980, '犯人は人を殺した疑いで逮捕された。', 'はんにんは ひとを ころした うたがいで たいほ された。', 'Hung thủ bị bắt vì bị nghi giết người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8150, 38004, '三日連続で雨が降っている。', 'みっか れんぞくで あめが ふって いる。', 'Trời đã mưa ba ngày liên tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8151, 38986, 'これが二人の恋の始まりだった。', 'これが ふたりの こいの はじまり だった。', 'Đó là khởi đầu tình yêu của hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8152, 38983, 'ケーキの残りは明日食べよう。', 'ケーキの のこりは あした たべよう。', 'Phần bánh còn lại để mai ăn nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8153, 38982, '料理を残さないで、全部食べてください。', 'りょうりを のこさないで、ぜんぶ たべて ください。', 'Đừng để thừa, hãy ăn hết nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8154, 38984, 'この部屋は今、使用中です。', 'この へやは いま、しようちゅう です。', 'Phòng này hiện đang được sử dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8155, 38991, '家族の支えがあったから、頑張れた。', 'かぞくの ささえが あったから、がんばれた。', 'Nhờ có gia đình nâng đỡ mà tôi đã cố gắng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8156, 38978, '茶道の作法を習っている。', 'さどうの さほうを ならって いる。', 'Tôi đang học lễ nghi trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8157, 38985, '留学はいい刺激になった。', 'りゅうがくは いい しげきに なった。', 'Du học là một động lực tốt cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8158, 38988, 'おかしくて、思わず笑ってしまった。', 'おかしくて、おもわず わらって しまった。', 'Buồn cười quá, tôi bật cười không kìm được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8159, 47961, '彼女は質問に肯定も否定もしなかった。', 'かのじょは しつもんに こうていも ひていも しなかった。', 'Cô ấy không khẳng định cũng không phủ nhận câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8160, 47979, '曖昧な返事をしないで、はっきり言ってください。', 'あいまいな へんじを しないで、はっきり いって ください。', 'Đừng trả lời mập mờ, hãy nói rõ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8161, 48025, '新しい工場ができて、雇用が増えた。', 'あたらしい こうじょうが できて、こようが ふえた。', 'Có nhà máy mới nên việc làm tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8162, 39010, '彼はいつも息子の自慢ばかりしている。', 'かれは いつも むすこの じまん ばかり して いる。', 'Ông ấy lúc nào cũng khoe con trai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8163, 38992, '交通費は会社から支給されます。', 'こうつうひは かいしゃから しきゅう されます。', 'Tiền đi lại do công ty chi trả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8164, 38993, '今月は支出が収入より多かった。', 'こんげつは ししゅつが しゅうにゅうより おおかった。', 'Tháng này chi nhiều hơn thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8165, 38994, '支払いはカードでもできますか。', 'しはらいは カードでも できますか。', 'Có thể thanh toán bằng thẻ không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8166, 38995, '家賃は毎月二十五日に支払います。', 'やちんは まいつき にじゅうごにちに しはらいます。', 'Tiền nhà tôi trả vào ngày 25 hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8167, 39000, '会社を始めるには資本が必要だ。', 'かいしゃを はじめるには しほんが ひつようだ。', 'Muốn mở công ty thì cần có vốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8168, 39002, '姉は病院で事務の仕事をしている。', 'あねは びょういんで じむの しごとを して いる。', 'Chị tôi làm công việc văn phòng ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8169, 38013, '先輩の意見を参考にした。', 'せんぱいの いけんを さんこうに した。', 'Tôi đã tham khảo ý kiến của đàn anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8170, 39009, '自殺を防ぐための相談窓口がある。', 'じさつを ふせぐ ための そうだん まどぐちが ある。', 'Có đường dây tư vấn để phòng chống tự sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8171, 39004, '今は桜の時期で、どこも人が多い。', 'いまは さくらの じきで、どこも ひとが おおい。', 'Bây giờ đang mùa hoa anh đào nên đâu cũng đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8172, 39005, '出発の時刻が変わりました。', 'しゅっぱつの じこくが かわりました。', 'Giờ khởi hành đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8173, 38007, 'この国の生活水準は高い。', 'この くにの せいかつ すいじゅんは たかい。', 'Mức sống ở nước này cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8174, 38011, '他社の商品を模倣してはいけない。', 'たしゃの しょうひんを もほう しては いけない。', 'Không được bắt chước sản phẩm của công ty khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8175, 38012, '子供は親の真似をして育つ。', 'こどもは おやの まねを して そだつ。', 'Trẻ con lớn lên bằng cách bắt chước bố mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8176, 38996, '危ないから、そんなことはよしなさい。', 'あぶないから、そんな ことは よしなさい。', 'Nguy hiểm đấy, thôi đừng làm thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8177, 38997, '話し合いの結果、合意に至った。', 'はなしあいの けっか、ごういに いたった。', 'Sau khi bàn bạc, hai bên đã đi đến thống nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8178, 38999, '試しに新しい店に行ってみた。', 'ためしに あたらしい みせに いって みた。', 'Tôi thử ghé quán mới xem sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8179, 39003, 'この箱は重くて、一人では持ち上げられない。', 'この はこは おもくて、ひとりでは もちあげられない。', 'Chiếc hộp này nặng quá, một mình không nhấc lên nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8180, 39008, '先生は地図で場所を示した。', 'せんせいは ちずで ばしょを しめした。', 'Thầy giáo chỉ vị trí trên bản đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8181, 38998, '彼は有名な詩人の詩を暗記している。', 'かれは ゆうめいな しじんの しを あんき して いる。', 'Anh ấy thuộc lòng thơ của một nhà thơ nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8182, 38008, '習った文法を会話に応用してみよう。', 'ならった ぶんぽうを かいわに おうよう して みよう。', 'Hãy thử ứng dụng ngữ pháp đã học vào hội thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8183, 38009, 'この本は実用的な表現が多い。', 'この ほんは じつようてきな ひょうげんが おおい。', 'Cuốn sách này có nhiều cách diễn đạt thực dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8184, 38010, '実際に会ってみると、優しい人だった。', 'じっさいに あって みると、やさしい ひと だった。', 'Gặp tận mặt mới thấy đó là người hiền lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8185, 39001, '事態は思ったより深刻だ。', 'じたいは おもったより しんこくだ。', 'Tình hình nghiêm trọng hơn tôi nghĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8186, 39007, '準備ができ次第、出発します。', 'じゅんびが でき しだい、しゅっぱつ します。', 'Chuẩn bị xong là chúng ta xuất phát ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8187, 39021, '母は主婦で、毎日家事をしている。', 'ははは しゅふで、まいにち かじを して いる。', 'Mẹ tôi là nội trợ, ngày nào cũng làm việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8188, 38014, '人を容姿だけで判断してはいけない。', 'ひとを ようし だけで はんだん しては いけない。', 'Không nên đánh giá người khác chỉ qua dung mạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8189, 38015, '彼は外見はこわそうだが、本当は優しい。', 'かれは がいけんは こわそう だが、ほんとうは やさしい。', 'Bề ngoài anh ấy trông dữ, nhưng thật ra rất hiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8190, 38016, '野菜中心の健康的な食事を心がけている。', 'やさい ちゅうしんの けんこうてきな しょくじを こころがけて いる。', 'Tôi cố gắng ăn uống lành mạnh, chủ yếu là rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8191, 38017, '年を取って、体力が落ちた。', 'としを とって、たいりょくが おちた。', 'Có tuổi rồi nên thể lực giảm sút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8192, 38018, '毎日運動して、筋肉をつけている。', 'まいにち うんどう して、きんにくを つけて いる。', 'Tôi tập thể dục mỗi ngày để tăng cơ bắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8193, 38019, '毎朝、体重を量っています。', 'まいあさ、たいじゅうを はかって います。', 'Sáng nào tôi cũng cân cân nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8194, 38020, '姿勢を正して、先生の話を聞きなさい。', 'しせいを ただして、せんせいの はなしを ききなさい。', 'Hãy ngồi thẳng lưng và nghe thầy giảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8195, 39014, '結果を聞いて、失望した。', 'けっかを きいて、しつぼう した。', 'Nghe kết quả, tôi thất vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8196, 39020, '借金はしない主義です。', 'しゃっきんは しない しゅぎ です。', 'Nguyên tắc của tôi là không vay nợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8197, 38023, 'イルカは知能が高い動物だ。', 'イルカは ちのうが たかい どうぶつだ。', 'Cá heo là loài vật có trí thông minh cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8198, 38024, '年を取ると、記憶力が落ちる。', 'としを とると、きおくりょくが おちる。', 'Có tuổi thì trí nhớ giảm sút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8199, 38025, '寝不足で集中力が続かない。', 'ねぶそくで しゅうちゅうりょくが つづかない。', 'Thiếu ngủ nên không tập trung được lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8200, 38026, '子供は想像力が豊かだ。', 'こどもは そうぞうりょくが ゆたかだ。', 'Trẻ con có trí tưởng tượng phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8201, 38027, 'リーダーには正しい判断力が必要だ。', 'リーダーには ただしい はんだんりょくが ひつようだ。', 'Người lãnh đạo cần có khả năng phán đoán đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8202, 38028, '彼は理解力があって、何でもすぐ覚える。', 'かれは りかいりょくが あって、なんでも すぐ おぼえる。', 'Cậu ấy hiểu nhanh, cái gì cũng nhớ ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8203, 38029, '作文で表現力を高めたい。', 'さくぶんで ひょうげんりょくを たかめたい。', 'Tôi muốn nâng cao khả năng diễn đạt qua viết văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8204, 39011, '彼は先月会社を辞めた。', 'かれは せんげつ かいしゃを やめた。', 'Anh ấy đã nghỉ việc ở công ty tháng trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8205, 39025, '手作りの料理は手間がかかる。', 'てづくりの りょうりは てまが かかる。', 'Món ăn tự làm thì tốn công sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8206, 38021, '本をたくさん読んで教養を身につけたい。', 'ほんを たくさん よんで きょうようを みに つけたい。', 'Tôi muốn đọc nhiều sách để trau dồi học vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8207, 38022, '学問に終わりはない。', 'がくもんに おわりは ない。', 'Việc học không có điểm dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8208, 38030, 'この仕事には高い語学力が求められる。', 'この しごとには たかい ごがくりょくが もとめられる。', 'Công việc này đòi hỏi năng lực ngoại ngữ cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8209, 38031, '学歴より実力を重視する会社が増えた。', 'がくれきより じつりょくを じゅうし する かいしゃが ふえた。', 'Ngày càng nhiều công ty coi trọng năng lực thực tế hơn bằng cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8210, 39016, '庭の木にたくさん実がなった。', 'にわの きに たくさん みが なった。', 'Cây trong vườn đã ra rất nhiều quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8211, 48061, '会社は損害を賠償することになった。', 'かいしゃは そんがいを ばいしょう する ことに なった。', 'Công ty phải đền bù thiệt hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8212, 48108, '今月は大きな事故が相次いで起きた。', 'こんげつは おおきな じこが あいついで おきた。', 'Tháng này liên tiếp xảy ra các vụ tai nạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8213, 39026, '引っ越しの手伝いに来てくれてありがとう。', 'ひっこしの てつだいに きて くれて ありがとう。', 'Cảm ơn bạn đã đến giúp chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8214, 39038, '日曜日に同級生の集まりがある。', 'にちようびに どうきゅうせいの あつまりが ある。', 'Chủ nhật có buổi họp mặt bạn cùng lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8215, 39039, 'テレビを消して、勉強に集中しなさい。', 'テレビを けして、べんきょうに しゅうちゅう しなさい。', 'Tắt tivi đi và tập trung học bài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8216, 39032, '秋は米の収穫の季節だ。', 'あきは こめの しゅうかくの きせつだ。', 'Mùa thu là mùa thu hoạch lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8217, 39029, 'ベトナムの首都はハノイです。', 'ベトナムの しゅとは ハノイ です。', 'Thủ đô của Việt Nam là Hà Nội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8218, 39034, 'アメリカには五十の州がある。', 'アメリカには ごじゅうの しゅうが ある。', 'Nước Mỹ có năm mươi bang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8219, 39040, 'この辺りは静かな住宅地だ。', 'この あたりは しずかな じゅうたくちだ。', 'Quanh đây là khu dân cư yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8220, 39028, '春に花の種をまいた。', 'はるに はなの たねを まいた。', 'Mùa xuân tôi gieo hạt hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8221, 38033, '日本人の平均寿命は世界でも長い。', 'にほんじんの へいきん じゅみょうは せかいでも ながい。', 'Tuổi thọ trung bình của người Nhật thuộc hàng cao thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8222, 38034, 'この日のことは一生忘れない。', 'この ひの ことは いっしょう わすれない。', 'Tôi sẽ không bao giờ quên ngày hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8223, 39030, '荷物を受け取ったら、連絡してください。', 'にもつを うけとったら、れんらく して ください。', 'Nhận được hàng thì hãy báo cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8224, 39031, 'チームは大きな成功を収めた。', 'チームは おおきな せいこうを おさめた。', 'Đội đã gặt hái thành công lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8225, 39035, '資料の間違いを修正した。', 'しりょうの まちがいを しゅうせい した。', 'Tôi đã sửa lỗi trong tài liệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8226, 39036, '仕事を終えて、まっすぐ家に帰った。', 'しごとを おえて、まっすぐ いえに かえった。', 'Xong việc, tôi đi thẳng về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8227, 39041, '係員の指示に従ってください。', 'かかりいんの しじに したがって ください。', 'Xin hãy làm theo hướng dẫn của nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8228, 39037, 'この部屋は何か臭い。', 'この へやは なにか くさい。', 'Căn phòng này có mùi gì hôi hôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8229, 39027, 'パーティーで手品を見せた。', 'パーティーで てじなを みせた。', 'Tôi biểu diễn ảo thuật ở bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8230, 39033, '周囲の人に迷惑をかけないようにしよう。', 'しゅういの ひとに めいわくを かけない ように しよう。', 'Hãy cố đừng làm phiền những người xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8231, 38035, '人生は一度しかない。', 'じんせいは いちど しか ない。', 'Đời người chỉ có một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8232, 38036, '彼女との出会いは運命だと思う。', 'かのじょとの であいは うんめいだと おもう。', 'Tôi nghĩ gặp cô ấy là định mệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8233, 38037, '駅で偶然、先生に会った。', 'えきで ぐうぜん、せんせいに あった。', 'Tôi tình cờ gặp thầy ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8234, 48175, '統計によると、日本の人口は減り続けている。', 'とうけいに よると、にほんの じんこうは へり つづけて いる。', 'Theo thống kê, dân số Nhật tiếp tục giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8235, 48188, 'これは私の専門の領域ではない。', 'これは わたしの せんもんの りょういき では ない。', 'Đây không phải lĩnh vực chuyên môn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8236, 28887, 'このお寺は八世紀に建てられました。', 'この おてらは はっせいきに たてられました。', 'Ngôi chùa này được xây vào thế kỷ tám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8237, 28894, '鎌倉で大仏を見ました。', 'かまくらで だいぶつを みました。', 'Tôi xem tượng Phật lớn ở Kamakura.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8238, 28899, '皆様、本日はありがとうございます。', 'みなさま、ほんじつは ありがとう ございます。', 'Kính thưa quý vị, cảm ơn quý vị hôm nay đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8239, 38039, '同じ町の出身だなんて、何かの縁ですね。', 'おなじ まちの しゅっしん だなんて、なにかの えん ですね。', 'Cùng quê với nhau, đúng là có duyên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8240, 38040, '大学での出会いが人生を変えた。', 'だいがくでの であいが じんせいを かえた。', 'Cuộc gặp gỡ ở đại học đã thay đổi cuộc đời tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8241, 38041, '友達との別れはいつも寂しい。', 'ともだちとの わかれは いつも さびしい。', 'Chia tay bạn bè lúc nào cũng buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8242, 38042, '十年ぶりに先生と再会した。', 'じゅうねんぶりに せんせいと さいかい した。', 'Sau mười năm tôi mới gặp lại thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8243, 39042, '夏休みにいとこの家に泊まった。', 'なつやすみに いとこの いえに とまった。', 'Kỳ nghỉ hè tôi ngủ lại nhà anh họ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8244, 39050, '旅行中にすてきな人と出会った。', 'りょこうちゅうに すてきな ひとと であった。', 'Trong chuyến du lịch tôi đã gặp một người tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8245, 39051, 'ご出身はどちらですか。', 'ごしゅっしんは どちら ですか。', 'Quê anh ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8246, 39043, 'この会社は経験より人柄を重視している。', 'この かいしゃは けいけんより ひとがらを じゅうし して いる。', 'Công ty này coi trọng tính cách hơn kinh nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8247, 39052, '自分の意見をはっきり述べてください。', 'じぶんの いけんを はっきり のべて ください。', 'Hãy trình bày rõ ý kiến của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8248, 39056, 'ごみの処理は市がしている。', 'ごみの しょりは しが して いる。', 'Việc xử lý rác do thành phố đảm nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8249, 39058, '契約書に署名してください。', 'けいやくしょに しょめい して ください。', 'Xin hãy ký tên vào hợp đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8250, 39046, '今夜の宿はまだ決まっていない。', 'こんやの やどは まだ きまって いない。', 'Chỗ trọ tối nay vẫn chưa quyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8251, 39047, 'このホテルの宿泊料金は一泊一万円です。', 'この ホテルの しゅくはく りょうきんは いっぱく いちまんえん です。', 'Giá phòng khách sạn này là mười nghìn yên một đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8252, 38051, '東京は交通機関が便利だ。', 'とうきょうは こうつうきかんが べんりだ。', 'Phương tiện giao thông công cộng ở Tokyo rất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8253, 38052, '信号無視をして、警察に注意された。', 'しんごうむしを して、けいさつに ちゅうい された。', 'Tôi vượt đèn đỏ và bị cảnh sát nhắc nhở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8254, 38053, '雨の日は速度を落として運転しよう。', 'あめの ひは そくどを おとして うんてん しよう。', 'Ngày mưa hãy giảm tốc độ khi lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8255, 38054, '運転するときは免許証を持っていてください。', 'うんてん する ときは めんきょしょうを もって いて ください。', 'Khi lái xe hãy mang theo bằng lái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8256, 38055, 'この道は日曜日、歩行者だけが通れる。', 'この みちは にちようび、ほこうしゃ だけが とおれる。', 'Con đường này vào chủ nhật chỉ dành cho người đi bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8257, 38056, '道を渡るときは横断歩道を使いましょう。', 'みちを わたる ときは おうだんほどうを つかいましょう。', 'Khi qua đường hãy đi trên vạch dành cho người đi bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8258, 38043, 'この写真を見ると、楽しい思い出がよみがえる。', 'この しゃしんを みると、たのしい おもいでが よみがえる。', 'Nhìn bức ảnh này, những kỷ niệm vui lại ùa về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8259, 38045, '過去のことはもう忘れよう。', 'かこの ことは もう わすれよう。', 'Hãy quên chuyện quá khứ đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8260, 31354, '友達の結婚式に出席した。', 'ともだちの けっこんしきに しゅっせき した。', 'Tôi đã dự đám cưới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8261, 31369, '拾った財布を交番に届けた。', 'ひろった さいふを こうばんに とどけた。', 'Tôi mang chiếc ví nhặt được đến đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8262, 28910, '美術館で古い彫刻を見ました。', 'びじゅつかんで ふるい ちょうこくを みました。', 'Tôi xem tác phẩm điêu khắc cổ ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8263, 28916, '昼ご飯を食べました。そのあと、散歩しました。', 'ひるごはんを たべました。その あと、さんぽ しました。', 'Tôi ăn trưa. Sau đó đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8264, 41893, '犬は聴覚がとても優れている。', 'いぬは ちょうかくが とても すぐれて いる。', 'Chó có thính giác rất nhạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8265, 39063, 'このクラスは女子のほうが多い。', 'この クラスは じょしの ほうが おおい。', 'Lớp này con gái nhiều hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8266, 39072, 'その少年は将来、医者になりたいそうだ。', 'その しょうねんは しょうらい、いしゃに なりたい そうだ。', 'Nghe nói cậu bé ấy sau này muốn làm bác sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8267, 39061, '大学で教授の助手をしている。', 'だいがくで きょうじゅの じょしゅを して いる。', 'Tôi làm trợ lý cho giáo sư ở trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8268, 39066, 'この店は駅前にあるので商売がうまくいっている。', 'この みせは えきまえに あるので しょうばいが うまく いって いる。', 'Cửa hàng này ở trước ga nên buôn bán thuận lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8269, 39062, 'イギリスの女王がこの町を訪れた。', 'イギリスの じょおうが この まちを おとずれた。', 'Nữ hoàng Anh đã đến thăm thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8270, 39059, '父は夜遅くまで書斎で本を読んでいる。', 'ちちは よる おそくまで しょさいで ほんを よんで いる。', 'Bố tôi đọc sách trong thư phòng đến khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8271, 39067, '庭に道具を入れる小屋がある。', 'にわに どうぐを いれる こやが ある。', 'Trong vườn có một nhà kho nhỏ để dụng cụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8272, 39068, 'パンは小麦から作られる。', 'パンは こむぎから つくられる。', 'Bánh mì được làm từ lúa mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8273, 38057, 'この電車は各駅に停車します。', 'この でんしゃは かくえきに ていしゃ します。', 'Chuyến tàu này dừng ở tất cả các ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8274, 38058, '大雨でこの先は通行止めです。', 'おおあめで この さきは つうこうどめ です。', 'Do mưa lớn, đoạn đường phía trước bị cấm lưu thông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8275, 38059, '駅の入口が工事中で使えない。', 'えきの いりぐちが こうじちゅうで つかえない。', 'Lối vào ga đang thi công nên không dùng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8276, 38060, '事故があったので、迂回して帰った。', 'じこが あったので、うかい して かえった。', 'Có tai nạn nên tôi đi đường vòng về nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8277, 38061, '公園を通ると近道になる。', 'こうえんを とおると ちかみちに なる。', 'Đi qua công viên là đường tắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8278, 38062, '道を間違えて、遠回りしてしまった。', 'みちを まちがえて、とおまわり して しまった。', 'Nhầm đường nên tôi phải đi vòng xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8279, 38064, 'この道は一方通行なので、入れません。', 'この みちは いっぽうつうこう なので、はいれません。', 'Đường này một chiều nên không vào được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8280, 39065, '日曜日を除いて、毎日営業しています。', 'にちようびを のぞいて、まいにち えいぎょう して います。', 'Chúng tôi mở cửa mỗi ngày trừ chủ nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8281, 39060, '図書館には古い書物がたくさんある。', 'としょかんには ふるい しょもつが たくさん ある。', 'Thư viện có rất nhiều sách cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8282, 39064, '彼女は有名な女優になった。', 'かのじょは ゆうめいな じょゆうに なった。', 'Cô ấy đã trở thành một nữ diễn viên nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8283, 38063, '母に言われて、渋々部屋を片付けた。', 'ははに いわれて、しぶしぶ へやを かたづけた。', 'Bị mẹ nhắc, tôi miễn cưỡng dọn phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8284, 39069, '少々お待ちください。', 'しょうしょう おまち ください。', 'Xin vui lòng đợi một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8285, 37704, '宗教によって食べられない物がある。', 'しゅうきょうに よって たべられない ものが ある。', 'Tùy tôn giáo mà có những thứ không được ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8286, 30994, '会社に新しいシステムを導入した。', 'かいしゃに あたらしい システムを どうにゅう した。', 'Công ty đã đưa hệ thống mới vào áp dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8287, 31002, '教育の改革が必要だと言われている。', 'きょういくの かいかくが ひつようだと いわれて いる。', 'Người ta cho rằng cần phải cải cách giáo dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8288, 28920, '日光の東照宮には有名な彫刻があります。', 'にっこうの とうしょうぐうには ゆうめいな ちょうこくが あります。', 'Đền Toshogu ở Nikko có những tác phẩm điêu khắc nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8289, 28924, 'この建物は有名な建築家が設計しました。', 'この たてものは ゆうめいな けんちくかが せっけい しました。', 'Tòa nhà này do một kiến trúc sư nổi tiếng thiết kế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8290, 39071, '公園で少女が一人で本を読んでいた。', 'こうえんで しょうじょが ひとりで ほんを よんで いた。', 'Một cô bé ngồi đọc sách một mình trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8291, 39073, '友達を家に招いて、パーティーをした。', 'ともだちを いえに まねいて、パーティーを した。', 'Tôi mời bạn bè đến nhà và tổ chức tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8292, 39092, '長く座っていたので、お尻が痛くなった。', 'ながく すわって いたので、おしりが いたく なった。', 'Ngồi lâu quá nên bị đau mông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8293, 39077, '彼の話で会場は笑いに包まれた。', 'かれの はなしで かいじょうは わらいに つつまれた。', 'Câu chuyện của anh ấy khiến cả hội trường rộn tiếng cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8294, 39078, '彼女の笑顔を見ると元気が出る。', 'かのじょの えがおを みると げんきが でる。', 'Nhìn nụ cười của cô ấy là tôi thấy có sức sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8295, 39085, '不況で職を失う人が増えた。', 'ふきょうで しょくを うしなう ひとが ふえた。', 'Do suy thoái, số người mất việc tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8296, 39086, '子供のころ、いろいろな職業にあこがれた。', 'こどもの ころ、いろいろな しょくぎょうに あこがれた。', 'Hồi nhỏ tôi mơ ước đủ thứ nghề nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8297, 38071, 'この小説はいろいろな言語に翻訳されている。', 'この しょうせつは いろいろな げんごに ほんやく されて いる。', 'Cuốn tiểu thuyết này đã được dịch ra nhiều thứ tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8298, 39080, '毎日練習すれば、ピアノはすぐ上達しますよ。', 'まいにち れんしゅう すれば、ピアノは すぐ じょうたつ しますよ。', 'Ngày nào cũng luyện thì piano sẽ tiến bộ nhanh thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8299, 39074, '消防の人たちがすぐに火を消した。', 'しょうぼうの ひとたちが すぐに ひを けした。', 'Lính cứu hỏa đã nhanh chóng dập lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8300, 38070, 'この店はパンがおいしいと評判だ。', 'この みせは パンが おいしいと ひょうばんだ。', 'Tiệm này nổi tiếng là bánh mì ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8301, 39088, '腹が減った。何か食おうぜ。', 'はらが へった。なにか くおうぜ。', 'Đói rồi. Kiếm gì ăn đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8302, 39089, '家族みんなで食卓を囲んだ。', 'かぞく みんなで しょくたくを かこんだ。', 'Cả nhà quây quần bên bàn ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8375, 39134, '計画に問題が生じた。', 'けいかくに もんだいが しょうじた。', 'Kế hoạch đã phát sinh vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8303, 39090, '食物アレルギーがある人は注意してください。', 'しょくもつ アレルギーが ある ひとは ちゅうい して ください。', 'Người bị dị ứng thực phẩm xin hãy chú ý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8304, 39091, '災害に備えて食料を買っておいた。', 'さいがいに そなえて しょくりょうを かって おいた。', 'Tôi mua sẵn lương thực để phòng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8305, 39082, '事故で乗客が数人けがをした。', 'じこで じょうきゃくが すうにん けがを した。', 'Vài hành khách bị thương trong vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8306, 39084, '部屋に植物を置くと、気持ちが落ち着く。', 'へやに しょくぶつを おくと、きもちが おちつく。', 'Đặt cây xanh trong phòng giúp tâm trạng thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8307, 39075, '時間がないので、説明を省きます。', 'じかんが ないので、せつめいを はぶきます。', 'Không có thời gian nên tôi xin lược bỏ phần giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8308, 39079, '交差点で車とバイクが衝突した。', 'こうさてんで くるまと バイクが しょうとつ した。', 'Ô tô và xe máy va chạm ở ngã tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8309, 39087, '展示品に手を触れないでください。', 'てんじひんに てを ふれないで ください。', 'Xin đừng chạm tay vào hiện vật trưng bày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8310, 30972, 'お互いに少し妥協しよう。', 'おたがいに すこし だきょう しよう。', 'Hai bên hãy thỏa hiệp một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8311, 31632, '二つの大学が共同で研究を進めている。', 'ふたつの だいがくが きょうどうで けんきゅうを すすめて いる。', 'Hai trường đại học đang cùng tiến hành nghiên cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8312, 39539, '祖母は孫をとても可愛がっている。', 'そぼは まごを とても かわいがって いる。', 'Bà rất cưng chiều cháu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8313, 37806, '父は几帳面で、いつも時間を守る。', 'ちちは きちょうめんで、いつも じかんを まもる。', 'Bố tôi rất tỉ mỉ, lúc nào cũng đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8314, 39096, 'びっくりして、心臓が止まるかと思った。', 'びっくり して、しんぞうが とまるかと おもった。', 'Giật mình đến mức tưởng tim ngừng đập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8315, 38087, '先生の話はとても興味深かった。', 'せんせいの はなしは とても きょうみぶかかった。', 'Câu chuyện của thầy rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8316, 39097, '大学で人間の心理を研究している。', 'だいがくで にんげんの しんりを けんきゅう して いる。', 'Tôi nghiên cứu tâm lý con người ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8317, 39100, 'ご迷惑をおかけして、申し訳ありません。', 'ごめいわくを おかけ して、もうしわけ ありません。', 'Thành thật xin lỗi vì đã làm phiền quý vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8318, 39099, 'この店の魚はいつも新鮮だ。', 'この みせの さかなは いつも しんせんだ。', 'Cá ở cửa hàng này lúc nào cũng tươi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8319, 39093, '髪を長く伸ばしている。', 'かみを ながく のばして いる。', 'Tôi đang để tóc dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8320, 39094, 'この一年で背が五センチ伸びた。', 'この いちねんで せが ごセンチ のびた。', 'Trong một năm qua tôi cao thêm năm phân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8321, 38086, 'このチーズには独特のにおいがある。', 'この チーズには どくとくの においが ある。', 'Loại phô mai này có mùi rất riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8322, 39098, '新たな気持ちで仕事を始めた。', 'あらたな きもちで しごとを はじめた。', 'Tôi bắt đầu công việc với tâm thế mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8323, 39101, '恥ずかしくて顔が真っ赤になった。', 'はずかしくて かおが まっかに なった。', 'Xấu hổ quá nên mặt đỏ bừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8324, 38079, '正月には家族で神社へ行く。', 'しょうがつには かぞくで じんじゃへ いく。', 'Tết cả nhà tôi đi đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8325, 38080, '京都には古い寺がたくさんある。', 'きょうとには ふるい てらが たくさん ある。', 'Kyoto có rất nhiều ngôi chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8326, 38081, '初詣で神社に参拝した。', 'はつもうでで じんじゃに さんぱい した。', 'Đầu năm tôi đi lễ ở đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8327, 38082, 'みんなの幸せを祈っています。', 'みんなの しあわせを いのって います。', 'Tôi cầu mong mọi người hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8328, 38083, '試験の前に母からお守りをもらった。', 'しけんの まえに ははから おまもりを もらった。', 'Trước kỳ thi, mẹ cho tôi một lá bùa hộ mệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8329, 38084, '毎朝、テレビの占いを見ている。', 'まいあさ、テレビの うらないを みて いる。', 'Sáng nào tôi cũng xem bói trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8330, 38085, 'この行事は宗教的というより風習的なものだ。', 'この ぎょうじは しゅうきょうてき と いうより ふうしゅうてきな ものだ。', 'Sự kiện này mang tính phong tục hơn là tôn giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8331, 39095, '審判の判定に選手たちが抗議した。', 'しんぱんの はんていに せんしゅたちが こうぎ した。', 'Các cầu thủ phản đối quyết định của trọng tài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8332, 31570, '両社は話し合いの末、合意に達した。', 'りょうしゃは はなしあいの すえ、ごういに たっした。', 'Sau khi bàn bạc, hai công ty đã đạt được đồng thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8333, 39914, 'この町は昔から漁業が盛んだ。', 'この まちは むかしから ぎょぎょうが さかんだ。', 'Thị trấn này từ xưa đã phát triển nghề cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8334, 39950, 'お客様には敬語を使いましょう。', 'おきゃくさまには けいごを つかいましょう。', 'Hãy dùng kính ngữ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8335, 31678, '事故防止のために、信号を新しくした。', 'じこ ぼうしの ために、しんごうを あたらしく した。', 'Để ngăn tai nạn, đèn tín hiệu đã được thay mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8336, 31688, '多くの若者がその候補者を支持している。', 'おおくの わかものが その こうほしゃを しじ して いる。', 'Nhiều người trẻ ủng hộ ứng viên đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8337, 43092, '火山が噴火して、近くの村に灰が降った。', 'かざんが ふんか して、ちかくの むらに はいが ふった。', 'Núi lửa phun trào, tro rơi xuống ngôi làng gần đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9816, 39835, '肉の塊を切って料理した。', 'にくの かたまりを きって りょうり した。', 'Tôi cắt tảng thịt ra để nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8338, 31226, '日本人は集団行動を重んじると言われる。', 'にほんじんは しゅうだん こうどうを おもんじると いわれる。', 'Người ta nói người Nhật coi trọng hành động tập thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8339, 39104, '彼とは高校時代から親しくしている。', 'かれとは こうこう じだいから したしく して いる。', 'Tôi thân với anh ấy từ thời cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8340, 39105, 'お正月には親戚がみんな集まる。', 'おしょうがつには しんせきが みんな あつまる。', 'Dịp Tết, họ hàng tụ họp đông đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8341, 39106, '彼女は小学校からの親友です。', 'かのじょは しょうがっこうからの しんゆう です。', 'Cô ấy là bạn thân của tôi từ hồi tiểu học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8342, 39112, '人間は一人では生きていけない。', 'にんげんは ひとりでは いきて いけない。', 'Con người không thể sống một mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8343, 39114, '人種によって人を差別してはいけない。', 'じんしゅに よって ひとを さべつ しては いけない。', 'Không được phân biệt đối xử dựa trên chủng tộc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8344, 39115, '彼は信頼できる人物だ。', 'かれは しんらい できる じんぶつだ。', 'Anh ấy là người đáng tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8345, 39116, '人類は初めて月に立った。', 'じんるいは はじめて つきに たった。', 'Lần đầu tiên loài người đặt chân lên mặt trăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8346, 39123, '旅行中、犬の世話を隣の人に頼んだ。', 'りょこうちゅう、いぬの せわを となりの ひとに たのんだ。', 'Đi du lịch, tôi nhờ hàng xóm chăm chó giúp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8347, 39103, '試験の前は神経が高ぶって眠れない。', 'しけんの まえは しんけいが たかぶって ねむれない。', 'Trước kỳ thi thần kinh căng thẳng nên không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8348, 39107, '午前中に病院で診察を受けた。', 'ごぜんちゅうに びょういんで しんさつを うけた。', 'Sáng nay tôi đi khám ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8349, 39108, 'この仕事は身体への負担が大きい。', 'この しごとは しんたいへの ふたんが おおきい。', 'Công việc này gây gánh nặng lớn cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8350, 38088, '体調が悪いので、今日は早く帰ります。', 'たいちょうが わるいので、きょうは はやく かえります。', 'Tôi không được khỏe nên hôm nay về sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8351, 38089, '毎日七時間は睡眠をとるようにしている。', 'まいにち しちじかんは すいみんを とる ように して いる。', 'Tôi cố ngủ đủ bảy tiếng mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8352, 38090, '子供には栄養のある物を食べさせたい。', 'こどもには えいようの ある ものを たべさせたい。', 'Tôi muốn cho con ăn đồ bổ dưỡng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8353, 38091, '偏食をすると、体によくない。', 'へんしょくを すると、からだに よくない。', 'Ăn uống lệch lạc thì không tốt cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8354, 38092, '疲労がたまって、病気になった。', 'ひろうが たまって、びょうきに なった。', 'Mệt mỏi tích tụ lâu ngày khiến tôi đổ bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8355, 38093, '父は過労で倒れてしまった。', 'ちちは かろうで たおれて しまった。', 'Bố tôi bị ngã quỵ vì làm việc quá sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8356, 38094, '祖母は田舎で療養している。', 'そぼは いなかで りょうよう して いる。', 'Bà tôi đang dưỡng bệnh ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8357, 39122, 'この寺は八世紀に建てられた。', 'この てらは はっせいきに たてられた。', 'Ngôi chùa này được xây vào thế kỷ thứ tám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8358, 38131, '今年はこの色の服が流行している。', 'ことしは この いろの ふくが りゅうこう して いる。', 'Năm nay quần áo màu này đang thịnh hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8359, 40076, '間違えて大事なファイルを削除してしまった。', 'まちがえて だいじな ファイルを さくじょ して しまった。', 'Tôi lỡ xóa nhầm một tệp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8360, 40288, 'この薬の成分を確認してください。', 'この くすりの せいぶんを かくにん して ください。', 'Hãy kiểm tra thành phần của thuốc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8361, 40320, 'この研究所は先端の技術を研究している。', 'この けんきゅうじょは せんたんの ぎじゅつを けんきゅう して いる。', 'Viện này nghiên cứu công nghệ tiên tiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8362, 28932, '源氏物語は紫式部によって書かれました。', 'げんじ ものがたりは むらさき しきぶに よって かかれました。', 'Truyện Genji được viết bởi Murasaki Shikibu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8363, 28936, 'この辺は土地が高いです。', 'この へんは とちが たかい です。', 'Đất quanh đây đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8364, 39135, '私は北海道の生まれです。', 'わたしは ほっかいどうの うまれ です。', 'Tôi sinh ra ở Hokkaido.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8365, 39141, '一人の青年が道を教えてくれた。', 'ひとりの せいねんが みちを おしえて くれた。', 'Một chàng thanh niên đã chỉ đường cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8366, 39136, '海はたくさんの生命を育てている。', 'うみは たくさんの せいめいを そだてて いる。', 'Biển nuôi dưỡng biết bao sự sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8367, 39131, '正直に話してくれてありがとう。', 'しょうじきに はなして くれて ありがとう。', 'Cảm ơn bạn đã nói thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8368, 39139, 'スポーツは体だけでなく精神も強くする。', 'スポーツは からだ だけで なく せいしんも つよく する。', 'Thể thao không chỉ rèn luyện cơ thể mà còn cả tinh thần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8369, 39140, '電気代の請求が来た。', 'でんきだいの せいきゅうが きた。', 'Hóa đơn tiền điện đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8370, 39128, '政府は新しい経済政策を発表した。', 'せいふは あたらしい けいざい せいさくを はっぴょう した。', 'Chính phủ đã công bố chính sách kinh tế mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8371, 39133, 'どんな生き物も大切にしよう。', 'どんな いきものも たいせつに しよう。', 'Hãy trân trọng mọi sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8372, 39129, '正午に駅で会いましょう。', 'しょうごに えきで あいましょう。', 'Hẹn gặp nhau ở ga lúc giữa trưa nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8373, 39137, '今が桜の花の盛りだ。', 'いまが さくらの はなの さかりだ。', 'Bây giờ đang là lúc hoa anh đào nở rộ nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8376, 39130, '結果は来週正式に発表される。', 'けっかは らいしゅう せいしきに はっぴょう される。', 'Kết quả sẽ được công bố chính thức vào tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8377, 39132, '台所はいつも清潔にしておこう。', 'だいどころは いつも せいけつに して おこう。', 'Hãy luôn giữ bếp sạch sẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8378, 39138, 'この仕事は、せいぜい一時間で終わる。', 'この しごとは、せいぜい いちじかんで おわる。', 'Việc này cùng lắm một tiếng là xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8379, 41467, '先輩の助言のおかげで、うまくいった。', 'せんぱいの じょげんの おかげで、うまく いった。', 'Nhờ lời khuyên của đàn anh mà mọi việc suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8380, 40978, '今日の業務は五時に終わった。', 'きょうの ぎょうむは ごじに おわった。', 'Công việc hôm nay kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8381, 41290, '小学校でうさぎを飼育している。', 'しょうがっこうで うさぎを しいく して いる。', 'Trường tiểu học có nuôi thỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8382, 40681, '問題は円満に解決した。', 'もんだいは えんまんに かいけつ した。', 'Vấn đề đã được giải quyết êm đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8383, 28881, 'インスタントラーメンは日本で発明されました。', 'インスタントラーメンは にほんで はつめい されました。', 'Mì ăn liền được phát minh ở Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8384, 28933, 'グラハムーベルは電話を発明しました。', 'グラハムーベルは でんわを はつめい しました。', 'Graham Bell đã phát minh ra điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8385, 28943, '父は来週入院します。', 'ちちは らいしゅう にゅういん します。', 'Tuần sau bố tôi nhập viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8386, 28958, 'この工場では車を作っています。', 'この こうじょうでは くるまを つくって います。', 'Nhà máy này sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8387, 28967, 'あ、いけない。宿題を忘れた。', 'あ、いけない。しゅくだいを わすれた。', 'Ôi, chết rồi. Quên bài tập mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8388, 28975, '机の上を整理してください。', 'つくえの うえを せいり して ください。', 'Hãy sắp xếp lại mặt bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8389, 28981, 'あの二人は双子です。', 'あの ふたりは ふたご です。', 'Hai người kia là cặp sinh đôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8390, 28995, 'ここに年齢を書いてください。', 'ここに ねんれいを かいて ください。', 'Hãy ghi tuổi vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8391, 39158, 'クラスの全員が試験に合格した。', 'クラスの ぜんいんが しけんに ごうかく した。', 'Cả lớp đều thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8392, 39163, '私は三年二組です。', 'わたしは さんねん にくみ です。', 'Tôi học lớp 3-2.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8393, 39178, '他人の物を勝手に使ってはいけない。', 'たにんの ものを かってに つかっては いけない。', 'Không được tự tiện dùng đồ của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8394, 39182, '熱があるかもしれないので、体温を測った。', 'ねつが あるかも しれないので、たいおんを はかった。', 'Có thể bị sốt nên tôi đã đo nhiệt độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8395, 39175, '相手の意見を尊重することが大切だ。', 'あいての いけんを そんちょう する ことが たいせつだ。', 'Tôn trọng ý kiến của người khác là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8396, 39144, '失敗した部下を責めてもしかたがない。', 'しっぱい した ぶかを せめても しかたが ない。', 'Trách cấp dưới đã thất bại cũng chẳng giải quyết được gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8397, 39147, 'この家は有名な建築家が設計した。', 'この いえは ゆうめいな けんちくかが せっけい した。', 'Ngôi nhà này do một kiến trúc sư nổi tiếng thiết kế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8398, 39165, '父は労働組合に入っている。', 'ちちは ろうどう くみあいに はいって いる。', 'Bố tôi tham gia công đoàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8399, 39176, '安い物を買って、かえって損をした。', 'やすい ものを かって、かえって そんを した。', 'Mua đồ rẻ hóa ra lại thiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8400, 39149, '恐竜が絶滅した原因にはいくつかの説がある。', 'きょうりゅうが ぜつめつ した げんいんには いくつかの せつが ある。', 'Về nguyên nhân khủng long tuyệt chủng có vài giả thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8401, 39181, '体育の授業でサッカーをした。', 'たいいくの じゅぎょうで サッカーを した。', 'Trong giờ thể dục chúng tôi đá bóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8402, 39151, '病気との戦いは長かった。', 'びょうきとの たたかいは ながかった。', 'Cuộc chiến với bệnh tật thật dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8403, 39152, '選手たちは最後まで戦った。', 'せんしゅたちは さいごまで たたかった。', 'Các cầu thủ đã chiến đấu đến phút cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8404, 39159, 'この店は全国に百以上ある。', 'この みせは ぜんこくに ひゃく いじょう ある。', 'Chuỗi cửa hàng này có hơn một trăm chi nhánh trên toàn quốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8405, 41760, '午後、お客様と打ち合わせがある。', 'ごご、おきゃくさまと うちあわせが ある。', 'Chiều nay tôi có buổi họp bàn với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8406, 28265, 'この物語の主人公は十歳の少女だ。', 'この ものがたりの しゅじんこうは じゅっさいの しょうじょだ。', 'Nhân vật chính của câu chuyện là một cô bé mười tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8407, 46207, '政府は子育てを支援する政策を発表した。', 'せいふは こそだてを しえん する せいさくを はっぴょう した。', 'Chính phủ công bố chính sách hỗ trợ nuôi dạy con cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8408, 46209, '法律が改正されて、成人の年齢が十八歳になった。', 'ほうりつが かいせい されて、せいじんの ねんれいが じゅうはっさいに なった。', 'Luật được sửa đổi, tuổi thành niên trở thành 18.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8409, 28997, '祖父は去年亡くなりました。', 'そふは きょねん なくなりました。', 'Ông tôi mất năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8410, 29004, '水をやらなかったので、花が死んでしまいました。', 'みずを やらなかったので、はなが しんで しまいました。', 'Không tưới nước nên cây hoa đã chết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8411, 29006, '試合に負けて、がっかりしました。', 'しあいに まけて、がっかり しました。', 'Thua trận nên tôi thất vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8412, 29010, '甘い物を食べすぎて、太りました。', 'あまい ものを たべすぎて、ふとりました。', 'Ăn quá nhiều đồ ngọt nên tôi béo lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8413, 29140, '質問がある人は手を上げてください。', 'しつもんが ある ひとは てを あげて ください。', 'Ai có câu hỏi thì giơ tay lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8414, 29177, '一人二つずつ取ってください。', 'ひとり ふたつずつ とって ください。', 'Mỗi người hãy lấy hai cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8415, 29229, '夏休みの旅行が楽しみです。', 'なつやすみの りょこうが たのしみ です。', 'Tôi rất mong chuyến du lịch kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8416, 39186, '怠けていないで、早く宿題をしなさい。', 'なまけて いないで、はやく しゅくだいを しなさい。', 'Đừng lười nữa, mau làm bài tập đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8417, 39188, '雨で外に出られず、退屈な一日だった。', 'あめで そとに でられず、たいくつな いちにち だった。', 'Mưa không ra ngoài được, cả ngày buồn chán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8418, 39190, '商品の代金は届いたときに払います。', 'しょうひんの だいきんは とどいた ときに はらいます。', 'Tiền hàng sẽ trả khi nhận hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8419, 39191, '彼はクラスの代表に選ばれた。', 'かれは クラスの だいひょうに えらばれた。', 'Cậu ấy được chọn làm đại diện lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8420, 39192, '部長の代理で会議に出た。', 'ぶちょうの だいりで かいぎに でた。', 'Tôi dự họp thay mặt trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8421, 39189, '泥棒はすぐに逮捕された。', 'どろぼうは すぐに たいほ された。', 'Tên trộm đã bị bắt ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8422, 39185, '着物の帯を結ぶのは難しい。', 'きものの おびを むすぶのは むずかしい。', 'Thắt đai kimono rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8423, 39193, '台の上に乗って、棚の上の箱を取った。', 'だいの うえに のって、たなの うえの はこを とった。', 'Tôi đứng lên bệ để lấy chiếc hộp trên giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8424, 39187, '日本には二週間滞在する予定です。', 'にほんには にしゅうかん たいざい する よてい です。', 'Tôi dự định lưu lại Nhật hai tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8425, 39183, '試合は三対一で私たちのチームが勝った。', 'しあいは さん たい いちで わたしたちの チームが かった。', 'Đội chúng tôi thắng với tỉ số 3–1.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8426, 39184, '先生の質問に対して、はっきり答えた。', 'せんせいの しつもんに たいして、はっきり こたえた。', 'Tôi trả lời rõ ràng câu hỏi của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8427, 39194, '今夜は大いに楽しもう。', 'こんやは おおいに たのしもう。', 'Tối nay hãy vui hết mình nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8428, 46211, '新しい法律は来年四月から施行される。', 'あたらしい ほうりつは らいねん しがつから しこう される。', 'Luật mới sẽ được thi hành từ tháng tư năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8429, 42255, 'このお寺は重要な文化財に指定されている。', 'この おてらは じゅうような ぶんかざいに してい されて いる。', 'Ngôi chùa này được công nhận là di sản văn hóa quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8430, 31213, '神社で伝統的な儀式が行われた。', 'じんじゃで でんとうてきな ぎしきが おこなわれた。', 'Một nghi lễ truyền thống đã được tổ chức ở đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8431, 40777, '新しいゲームを開発している。', 'あたらしい ゲームを かいはつ して いる。', 'Chúng tôi đang phát triển một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8432, 46214, '多くの若者がその候補者を支持している。', 'おおくの わかものが その こうほしゃを しじ して いる。', 'Nhiều người trẻ ủng hộ ứng viên đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8433, 28483, '週末、写真の展覧会に行った。', 'しゅうまつ、しゃしんの てんらんかいに いった。', 'Cuối tuần tôi đi xem triển lãm ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8434, 31216, '成功しても謙虚な気持ちを忘れない。', 'せいこう しても けんきょな きもちを わすれない。', 'Dù thành công cũng không quên giữ lòng khiêm tốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8435, 29278, 'なべに水を入れて、火にかけます。', 'なべに みずを いれて、ひに かけます。', 'Cho nước vào nồi rồi bắc lên bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8436, 29277, 'インスタントラーメンは日本で発明されました。', 'インスタントラーメンは にほんで はつめい されました。', 'Mì ăn liền được phát minh ở Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8437, 29317, 'ここに年齢を書いてください。', 'ここに ねんれいを かいて ください。', 'Hãy ghi tuổi vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8438, 29407, 'このレバーを下げると、水が出ます。', 'この レバーを さげると、みずが でます。', 'Gạt cần này xuống thì nước chảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8439, 29456, '名前と住所を入力してください。', 'なまえと じゅうしょを にゅうりょく して ください。', 'Hãy nhập tên và địa chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8440, 29461, '祖父は去年亡くなりました。', 'そふは きょねん なくなりました。', 'Ông tôi mất năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8441, 29626, '初めに、名前を書いてください。', 'はじめに、なまえを かいて ください。', 'Trước hết, hãy viết tên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8442, 39211, '友達に子供が誕生した。', 'ともだちに こどもが たんじょう した。', 'Bạn tôi vừa có em bé chào đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8443, 39213, '入口に背の高い男の人が立っている。', 'いりぐちに せの たかい おとこのひとが たって いる。', 'Có một người đàn ông cao đứng ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8444, 39214, '男子は体育館に集まってください。', 'だんしは たいいくかんに あつまって ください。', 'Các bạn nam hãy tập trung ở nhà thể chất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8445, 39228, '甘い物ばかり食べると虫歯になるよ。', 'あまい もの ばかり たべると むしばに なるよ。', 'Ăn toàn đồ ngọt là bị sâu răng đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8446, 39238, '薬を飲んだら、痛みが少し楽になった。', 'くすりを のんだら、いたみが すこし らくに なった。', 'Uống thuốc xong thì cơn đau dịu đi một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8447, 39215, 'みんなで知恵を出し合って、問題を解決した。', 'みんなで ちえを だしあって、もんだいを かいけつ した。', 'Mọi người cùng góp trí tuệ và giải quyết được vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8448, 39227, '新しい技術が世界から注目されている。', 'あたらしい ぎじゅつが せかいから ちゅうもく されて いる。', 'Công nghệ mới đang được cả thế giới chú ý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8449, 39225, 'お金がないので、中古の車を買った。', 'おかねが ないので、ちゅうこの くるまを かった。', 'Không có tiền nên tôi mua xe cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8450, 39209, '毎日新しい単語を十個覚えている。', 'まいにち あたらしい たんごを じゅっこ おぼえて いる。', 'Mỗi ngày tôi học thuộc mười từ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8451, 31227, '各国が協調して問題に取り組んでいる。', 'かっこくが きょうちょう して もんだいに とりくんで いる。', 'Các nước đang phối hợp để giải quyết vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8452, 31270, 'この食品には体に悪い物質は入っていない。', 'この しょくひんには からだに わるい ぶっしつは はいって いない。', 'Thực phẩm này không chứa chất có hại cho cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8453, 46275, '人の体は多くの細胞でできている。', 'ひとの からだは おおくの さいぼうで できて いる。', 'Cơ thể người được tạo nên từ vô số tế bào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8454, 29595, '美術館で有名な画家の作品を見た。', 'びじゅつかんで ゆうめいな がかの さくひんを みた。', 'Tôi xem tác phẩm của họa sĩ nổi tiếng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8455, 30981, 'その値段は妥当だと思う。', 'その ねだんは だとうだと おもう。', 'Tôi nghĩ mức giá đó là hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8456, 31194, '学校で体力を測定した。', 'がっこうで たいりょくを そくてい した。', 'Ở trường chúng tôi đã đo thể lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8457, 31206, '専門家の間でも見解が分かれている。', 'せんもんかの あいだでも けんかいが わかれて いる。', 'Ngay giữa các chuyên gia cũng có quan điểm khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8458, 39792, '電話の応対は丁寧にしてください。', 'でんわの おうたいは ていねいに して ください。', 'Hãy tiếp điện thoại một cách lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8459, 46941, '日本は治安がいい国だと言われている。', 'にほんは ちあんが いい くにだと いわれて いる。', 'Nhật Bản được cho là đất nước có an ninh tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8460, 46942, '貧困に苦しむ子供たちを支援したい。', 'ひんこんに くるしむ こどもたちを しえん したい。', 'Tôi muốn giúp đỡ những đứa trẻ khổ vì nghèo đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8461, 46943, '都市と地方の格差が広がっている。', 'としと ちほうの かくさが ひろがって いる。', 'Khoảng cách giữa thành thị và nông thôn đang nới rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8462, 46944, 'すべての人の人権を守らなければならない。', 'すべての ひとの じんけんを まもらなければ ならない。', 'Phải bảo vệ nhân quyền của tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8463, 29658, '大阪のお城を見に行きました。', 'おおさかの おしろを みに いきました。', 'Tôi đi xem lâu đài Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8464, 44094, '近所にスーパーがあるので、便利です。', 'きんじょに スーパーが あるので、べんり です。', 'Gần nhà có siêu thị nên rất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8465, 44454, '近所にスーパーがあるので、便利です。', 'きんじょに スーパーが あるので、べんり です。', 'Gần nhà có siêu thị nên rất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8466, 44469, '洗濯機が壊れてしまいました。', 'せんたくきが こわれて しまいました。', 'Máy giặt bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8467, 39247, '昨日の敵は今日の友。', 'きのうの てきは きょうの とも。', 'Kẻ thù hôm qua là bạn hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8468, 39241, '話に夢中で、店の前を通り過ぎてしまった。', 'はなしに むちゅうで、みせの まえを とおりすぎて しまった。', 'Mải nói chuyện nên chúng tôi đi quá cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8469, 39242, '工事中のため、右側を通行してください。', 'こうじちゅうの ため、みぎがわを つうこう して ください。', 'Do đang thi công, xin hãy đi bên phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8470, 39244, '次の停留所で降ります。', 'つぎの ていりゅうじょで おります。', 'Tôi xuống ở trạm dừng tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8471, 39246, '雨の後で、靴が泥だらけになった。', 'あめの あとで、くつが どろだらけに なった。', 'Sau cơn mưa, giày dính đầy bùn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8472, 39243, 'チャンスをしっかり掴みたい。', 'チャンスを しっかり つかみたい。', 'Tôi muốn nắm chắc cơ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8473, 39248, '先生が笛を吹いて、試合が始まった。', 'せんせいが ふえを ふいて、しあいが はじまった。', 'Thầy giáo thổi còi, trận đấu bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8474, 46215, '住民は工場の建設に抗議した。', 'じゅうみんは こうじょうの けんせつに こうぎ した。', 'Người dân phản đối việc xây dựng nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8475, 46219, 'その地域では紛争が続いている。', 'その ちいきでは ふんそうが つづいて いる。', 'Xung đột vẫn đang tiếp diễn ở khu vực đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8476, 46221, '日本は治安がいい国だと言われている。', 'にほんは ちあんが いい くにだと いわれて いる。', 'Nhật Bản được cho là đất nước có an ninh tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8477, 46222, '貧困に苦しむ子供たちを支援したい。', 'ひんこんに くるしむ こどもたちを しえん したい。', 'Tôi muốn giúp đỡ những đứa trẻ khổ vì nghèo đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8478, 46224, 'すべての人の人権を守らなければならない。', 'すべての ひとの じんけんを まもらなければ ならない。', 'Phải bảo vệ nhân quyền của tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8479, 46226, '電力の自由化で、会社を選べるようになった。', 'でんりょくの じゆうかで、かいしゃを えらべる ように なった。', 'Nhờ tự do hóa ngành điện, giờ ta có thể chọn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8480, 46234, '二つの意見が対立している。', 'ふたつの いけんが たいりつ して いる。', 'Hai ý kiến đang đối lập nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8481, 46237, '両社は話し合いの末、合意に達した。', 'りょうしゃは はなしあいの すえ、ごういに たっした。', 'Sau khi bàn bạc, hai công ty đã đạt được đồng thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8482, 46240, '会社の方針が変わった。', 'かいしゃの ほうしんが かわった。', 'Phương châm của công ty đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8483, 46241, '先生は毎日たくさんの宿題を課す。', 'せんせいは まいにち たくさんの しゅくだいを かす。', 'Ngày nào thầy cũng giao nhiều bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8484, 46244, '館内での撮影は禁じられています。', 'かんないでの さつえいは きんじられて います。', 'Cấm chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8485, 46246, '彼は不当な理由で解雇された。', 'かれは ふとうな りゆうで かいこ された。', 'Anh ấy bị sa thải vì lý do bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8486, 46248, '会場の入口は厳重に警備されている。', 'かいじょうの いりぐちは げんじゅうに けいび されて いる。', 'Lối vào hội trường được canh gác nghiêm ngặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8487, 46250, '新しいゲームを開発している。', 'あたらしい ゲームを かいはつ して いる。', 'Chúng tôi đang phát triển một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8488, 46253, '新しいカメラは性能がいい。', 'あたらしい カメラは せいのうが いい。', 'Chiếc máy ảnh mới có tính năng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8489, 44478, '電話しましたが、留守でした。', 'でんわ しましたが、るす でした。', 'Tôi đã gọi điện nhưng không có ai ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8490, 28620, 'あのマークは「徐行」という意味です。', 'あの マークは 「じょこう」と いう いみ です。', 'Ký hiệu kia có nghĩa là "đi chậm".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8491, 28822, 'ショパンの曲をピアノで弾きました。', 'ショパンの きょくを ピアノで ひきました。', 'Tôi chơi bản nhạc của Chopin trên đàn piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8492, 44829, '洗濯機が壊れてしまいました。', 'せんたくきが こわれて しまいました。', 'Máy giặt bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8493, 39296, '電車ではお年寄りに席を譲りましょう。', 'でんしゃでは おとしよりに せきを ゆずりましょう。', 'Trên tàu hãy nhường ghế cho người già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8494, 39274, '朝から頭痛がひどい。', 'あさから ずつうが ひどい。', 'Từ sáng tôi đã đau đầu dữ dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8495, 39282, 'このきのこには毒がある。', 'この きのこには どくが ある。', 'Loại nấm này có độc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8496, 46254, 'このスマホにはたくさんの機能がある。', 'この スマホには たくさんの きのうが ある。', 'Chiếc điện thoại này có rất nhiều chức năng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8497, 46259, 'このシャツは自然の素材で作られている。', 'この シャツは しぜんの そざいで つくられて いる。', 'Chiếc áo này làm từ chất liệu tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8498, 46261, '燃料の値段が上がって、運賃も高くなった。', 'ねんりょうの ねだんが あがって、うんちんも たかく なった。', 'Giá nhiên liệu tăng nên giá vé cũng đắt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8499, 46263, 'ここは電波が弱くて、電話がつながらない。', 'ここは でんぱが よわくて、でんわが つながらない。', 'Ở đây sóng yếu nên không gọi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8500, 46268, '学校で体力を測定した。', 'がっこうで たいりょくを そくてい した。', 'Ở trường chúng tôi đã đo thể lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8501, 46269, '今夜は流れ星の観測に最適だ。', 'こんやは ながれぼしの かんそくに さいてきだ。', 'Đêm nay rất lý tưởng để quan sát sao băng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8502, 46271, '理論はわかっても、実際にやるのは難しい。', 'りろんは わかっても、じっさいに やるのは むずかしい。', 'Hiểu lý thuyết rồi nhưng làm thực tế thì khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8503, 46274, 'この薬の成分を確認してください。', 'この くすりの せいぶんを かくにん して ください。', 'Hãy kiểm tra thành phần của thuốc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8504, 46276, '背の高さは遺伝によるところが大きい。', 'せの たかさは いでんに よる ところが おおきい。', 'Chiều cao phần lớn là do di truyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8505, 46279, '医者にインフルエンザだと診断された。', 'いしゃに インフルエンザだと しんだん された。', 'Tôi được bác sĩ chẩn đoán là bị cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8506, 46284, 'インフルエンザの予防注射を受けた。', 'インフルエンザの よぼう ちゅうしゃを うけた。', 'Tôi đã tiêm phòng cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8507, 46292, 'スマホが普及して、生活が大きく変わった。', 'スマホが ふきゅう して、せいかつが おおきく かわった。', 'Điện thoại thông minh phổ biến khiến cuộc sống thay đổi lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8508, 46296, '病院で精密な検査を受けた。', 'びょういんで せいみつな けんさを うけた。', 'Tôi đã được kiểm tra kỹ lưỡng ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8509, 46298, 'この研究所は先端の技術を研究している。', 'この けんきゅうじょは せんたんの ぎじゅつを けんきゅう して いる。', 'Viện này nghiên cứu công nghệ tiên tiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8510, 46299, '台風に備えて、窓を閉めておいた。', 'たいふうに そなえて、まどを しめて おいた。', 'Để phòng bão, tôi đã đóng cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8511, 46301, '部屋にエアコンを取り付けてもらった。', 'へやに エアコンを とりつけて もらった。', 'Tôi nhờ người lắp điều hòa cho phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8512, 46304, 'わからない言葉をネットで検索した。', 'わからない ことばを ネットで けんさく した。', 'Tôi tra từ không hiểu trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8513, 46307, 'この仕事には高度な技術が必要だ。', 'この しごとには こうどな ぎじゅつが ひつようだ。', 'Công việc này đòi hỏi kỹ thuật cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8514, 46308, '十分たつと、画面は自動的に暗くなる。', 'じゅっぷん たつと、がめんは じどうてきに くらく なる。', 'Sau mười phút, màn hình tự động tối đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8515, 46310, '美術館で有名な画家の作品を見た。', 'びじゅつかんで ゆうめいな がかの さくひんを みた。', 'Tôi xem tác phẩm của họa sĩ nổi tiếng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8516, 46314, '好きな俳優の映画を見に行った。', 'すきな はいゆうの えいがを みに いった。', 'Tôi đi xem phim của diễn viên mình thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8517, 44838, '電話しましたが、留守でした。', 'でんわ しましたが、るす でした。', 'Tôi đã gọi điện nhưng không có ai ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8518, 44882, '毎朝、水泳をしています。', 'まいあさ、すいえいを して います。', 'Sáng nào tôi cũng đi bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8519, 39303, '昔、この村の農民は貧しかった。', 'むかし、この むらの のうみんは まずしかった。', 'Ngày xưa nông dân làng này rất nghèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8520, 46316, '彼女は初めて大きな舞台に立った。', 'かのじょは はじめて おおきな ぶたいに たった。', 'Lần đầu tiên cô ấy đứng trên sân khấu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8521, 46317, '劇団の公演は来週から始まる。', 'げきだんの こうえんは らいしゅうから はじまる。', 'Buổi biểu diễn của đoàn kịch bắt đầu từ tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8522, 46321, '宗教によって食べられない物がある。', 'しゅうきょうに よって たべられない ものが ある。', 'Tùy tôn giáo mà có những thứ không được ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8523, 46324, 'この辺りから古代の遺跡が見つかった。', 'この あたりから こだいの いせきが みつかった。', 'Người ta đã tìm thấy di tích cổ đại quanh đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8524, 46325, 'このお寺は重要な文化財に指定されている。', 'この おてらは じゅうような ぶんかざいに してい されて いる。', 'Ngôi chùa này được công nhận là di sản văn hóa quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8525, 46328, 'この作家の随筆はやさしい言葉で書かれている。', 'この さっかの ずいひつは やさしい ことばで かかれて いる。', 'Tùy bút của nhà văn này được viết bằng lời lẽ giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8526, 46332, 'この雑誌は若い読者に人気がある。', 'この ざっしは わかい どくしゃに にんきが ある。', 'Tạp chí này được độc giả trẻ yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8527, 46334, 'その試合はテレビで生放送された。', 'その しあいは テレビで なま ほうそう された。', 'Trận đấu đó được truyền hình trực tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8528, 46335, '新聞の番組表で今夜の映画を探した。', 'しんぶんの ばんぐみひょうで こんやの えいがを さがした。', 'Tôi xem lịch chương trình trên báo để tìm phim tối nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8529, 46343, '今年はこの色の服が流行している。', 'ことしは この いろの ふくが りゅうこう して いる。', 'Năm nay quần áo màu này đang thịnh hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8530, 46345, '今、この映画が話題になっている。', 'いま、この えいがが わだいに なって いる。', 'Hiện bộ phim này đang được bàn tán sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8531, 46346, '気持ちを言葉で表現するのは難しい。', 'きもちを ことばで ひょうげん するのは むずかしい。', 'Diễn đạt cảm xúc bằng lời thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8532, 46350, '趣味は映画鑑賞です。', 'しゅみは えいが かんしょう です。', 'Sở thích của tôi là thưởng thức phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8533, 46352, 'スタジアムは観客でいっぱいだった。', 'スタジアムは かんきゃくで いっぱい だった。', 'Sân vận động chật kín khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8534, 46353, 'この物語の主人公は十歳の少女だ。', 'この ものがたりの しゅじんこうは じゅっさいの しょうじょだ。', 'Nhân vật chính của câu chuyện là một cô bé mười tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8535, 46357, '彼は映画で医者の役を演じた。', 'かれは えいがで いしゃの やくを えんじた。', 'Anh ấy đóng vai bác sĩ trong phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8536, 46359, '彼は日本の歴史について本を著した。', 'かれは にほんの れきしに ついて ほんを あらわした。', 'Ông ấy đã viết sách về lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8537, 46361, 'この村には古い伝説が伝わっている。', 'この むらには ふるい でんせつが つたわって いる。', 'Ngôi làng này lưu truyền một truyền thuyết cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8538, 46366, '彼女はいつも地味な色の服を着ている。', 'かのじょは いつも じみな いろの ふくを きて いる。', 'Cô ấy lúc nào cũng mặc đồ màu giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8539, 46367, '葬式に派手な服は着ないほうがいい。', 'そうしきに はでな ふくは きない ほうが いい。', 'Không nên mặc đồ sặc sỡ đến đám tang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8540, 46369, '上役の許可がないと、決められない。', 'うわやくの きょかが ないと、きめられない。', 'Không có sự cho phép của cấp trên thì không quyết được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8541, 46371, '来月から大阪の支店に異動になった。', 'らいげつから おおさかの してんに いどうに なった。', 'Từ tháng sau tôi được điều sang chi nhánh Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8542, 46372, '姉は派遣社員として働いている。', 'あねは はけん しゃいんと して はたらいて いる。', 'Chị tôi làm việc với tư cách nhân viên phái cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8543, 47533, '日本で茶道を習いました。', 'にほんで さどうを ならいました。', 'Tôi đã học trà đạo ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8544, 39335, '彼女のお母さんはとても美人だ。', 'かのじょの おかあさんは とても びじんだ。', 'Mẹ cô ấy rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8545, 39312, '冬は肌が乾燥しやすい。', 'ふゆは はだが かんそう しやすい。', 'Mùa đông da dễ bị khô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8546, 46375, '会社を選ぶとき、福利厚生も大切だ。', 'かいしゃを えらぶ とき、ふくり こうせいも たいせつだ。', 'Khi chọn công ty, chế độ phúc lợi cũng quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8547, 46377, '今日の業務は五時に終わった。', 'きょうの ぎょうむは ごじに おわった。', 'Công việc hôm nay kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8548, 46381, '今日の会議の議題は来年の予算です。', 'きょうの かいぎの ぎだいは らいねんの よさん です。', 'Chủ đề cuộc họp hôm nay là ngân sách năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8549, 46383, '新商品の企画が通った。', 'しんしょうひんの きかくが とおった。', 'Kế hoạch sản phẩm mới đã được duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8550, 46385, '彼は営業で大きな実績を上げた。', 'かれは えいぎょうで おおきな じっせきを あげた。', 'Anh ấy đạt thành tích lớn trong kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8551, 46386, '今学期の評定は「優」だった。', 'こんがっきの ひょうていは 「ゆう」 だった。', 'Xếp loại học kỳ này của tôi là "Giỏi".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8552, 46389, '隣の人から騒音の苦情が来た。', 'となりの ひとから そうおんの くじょうが きた。', 'Hàng xóm đã phàn nàn về tiếng ồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8625, 39438, '二人の友情は今も続いている。', 'ふたりの ゆうじょうは いまも つづいて いる。', 'Tình bạn của hai người vẫn còn đến nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8553, 46393, '一度失った信用を取り戻すのは難しい。', 'いちど うしなった しんようを とりもどすのは むずかしい。', 'Lấy lại lòng tin một khi đã mất là rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8554, 46395, 'お客様には敬語を使いましょう。', 'おきゃくさまには けいごを つかいましょう。', 'Hãy dùng kính ngữ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8555, 46397, '職場の人間関係に悩んでいる。', 'しょくばの にんげん かんけいに なやんで いる。', 'Tôi đang khổ tâm vì các mối quan hệ ở chỗ làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8556, 46400, '帰国する友達の送別会をした。', 'きこく する ともだちの そうべつかいを した。', 'Chúng tôi làm tiệc chia tay người bạn về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8557, 46401, '彼女は周りへの気配りができる人だ。', 'かのじょは まわりへの きくばりが できる ひとだ。', 'Cô ấy là người chu đáo với mọi người xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8558, 46403, '彼女は遠回しに誘いを断った。', 'かのじょは とおまわしに さそいを ことわった。', 'Cô ấy từ chối lời mời một cách vòng vo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8559, 46405, '彼は誠実な人だから信頼できる。', 'かれは せいじつな ひと だから しんらい できる。', 'Anh ấy là người thành thật nên có thể tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8560, 46407, '祖父は頑固で、人の話を聞かない。', 'そふは がんこで、ひとの はなしを きかない。', 'Ông tôi bướng bỉnh, không chịu nghe ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8561, 46408, '成功しても謙虚な気持ちを忘れない。', 'せいこう しても けんきょな きもちを わすれない。', 'Dù thành công cũng không quên giữ lòng khiêm tốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8562, 46410, '悩みを親友に打ち明けた。', 'なやみを しんゆうに うちあけた。', 'Tôi đã thổ lộ nỗi lòng với bạn thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8563, 46412, '先輩に怒られても、言い返せなかった。', 'せんぱいに おこられても、いいかえせなかった。', 'Bị đàn anh mắng, tôi không cãi lại được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8564, 46413, '雨のため、今日の出発は見送ることにした。', 'あめの ため、きょうの しゅっぱつは みおくる ことに した。', 'Vì mưa, chúng tôi quyết định hoãn chuyến đi hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8565, 46416, '前の担当者から仕事を引き継いだ。', 'まえの たんとうしゃから しごとを ひきついだ。', 'Tôi tiếp quản công việc từ người phụ trách trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8566, 46418, '試合に負けた友達を励ました。', 'しあいに まけた ともだちを はげました。', 'Tôi động viên người bạn vừa thua trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8567, 46420, '自分ばかり責めないでください。', 'じぶん ばかり せめないで ください。', 'Đừng chỉ tự trách bản thân như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8568, 46422, '困ったときは、いつでも頼ってください。', 'こまった ときは、いつでも たよって ください。', 'Khi khó khăn, cứ dựa vào tôi bất cứ lúc nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8569, 47545, 'このことわざの意味を知っていますか。', 'この ことわざの いみを しって いますか。', 'Bạn có biết ý nghĩa câu tục ngữ này không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8570, 39358, '彼は二人の子供の父親です。', 'かれは ふたりの こどもの ちちおや です。', 'Anh ấy là bố của hai đứa trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8571, 39387, '母親になって、親の気持ちがわかった。', 'ははおやに なって、おやの きもちが わかった。', 'Làm mẹ rồi tôi mới hiểu lòng cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8572, 39393, 'ご協力いただいた方々にお礼を申し上げます。', 'ごきょうりょく いただいた かたがたに おれいを もうしあげます。', 'Xin cảm ơn những vị đã hợp tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8573, 39403, '申し込みは本人が来てください。', 'もうしこみは ほんにんが きて ください。', 'Đăng ký thì đương sự phải tự đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8574, 39402, '寒さで子供の頬が赤くなっている。', 'さむさで こどもの ほほが あかく なって いる。', 'Má bọn trẻ đỏ ửng vì lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8575, 39378, '爪をかむ癖がなかなか直らない。', 'つめを かむ くせが なかなか なおらない。', 'Tật cắn móng tay mãi không bỏ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8576, 39398, '誰もが平和な世界を望んでいる。', 'だれもが へいわな せかいを のぞんで いる。', 'Ai cũng mong một thế giới hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8577, 39370, '高校で物理が一番難しかった。', 'こうこうで ぶつりが いちばん むずかしかった。', 'Hồi cấp ba môn vật lý là khó nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8578, 39373, '次の文を日本語に訳しなさい。', 'つぎの ぶんを にほんごに やくしなさい。', 'Hãy dịch câu sau sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8579, 39374, '画面の文字が小さくて読めない。', 'がめんの もじが ちいさくて よめない。', 'Chữ trên màn hình nhỏ quá, không đọc được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8580, 46424, '一日中歩いて、くたびれた。', 'いちにちじゅう あるいて、くたびれた。', 'Đi bộ cả ngày nên mệt lả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8581, 46425, 'けんかした後、気まずい雰囲気になった。', 'けんか した あと、きまずい ふんいきに なった。', 'Sau khi cãi nhau, bầu không khí trở nên khó xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8582, 46429, '外来種が生態系を壊している。', 'がいらいしゅが せいたいけいを こわして いる。', 'Các loài ngoại lai đang phá vỡ hệ sinh thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8583, 46435, '工場から排出されるガスを減らす必要がある。', 'こうじょうから はいしゅつ される ガスを へらす ひつようが ある。', 'Cần giảm lượng khí thải ra từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8584, 46437, '車の排気ガスで空気が汚れている。', 'くるまの はいき ガスで くうきが よごれて いる。', 'Khí thải xe cộ làm bẩn không khí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8585, 46440, 'この川の水質は年々よくなっている。', 'この かわの すいしつは ねんねん よく なって いる。', 'Chất lượng nước sông này ngày càng tốt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8586, 46441, 'この地域は土壌が豊かで、作物がよく育つ。', 'この ちいきは どじょうが ゆたかで、さくもつが よく そだつ。', 'Vùng này đất đai màu mỡ nên hoa màu phát triển tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8587, 46445, '干ばつで米が育たなかった。', 'かんばつで こめが そだたなかった。', 'Do hạn hán, lúa không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8588, 46447, '地震のあとは津波に注意してください。', 'じしんの あとは つなみに ちゅうい して ください。', 'Sau động đất hãy cảnh giác với sóng thần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8589, 46449, '大雨で土砂崩れが起き、道が通れなくなった。', 'おおあめで どしゃくずれが おき、みちが とおれなく なった。', 'Mưa lớn gây lở đất khiến đường không đi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8590, 47005, 'よく寝ると、免疫が強くなる。', 'よく ねると、めんえきが つよく なる。', 'Ngủ đủ giấc giúp hệ miễn dịch khỏe hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8591, 47893, '日本で茶道を習いました。', 'にほんで さどうを ならいました。', 'Tôi đã học trà đạo ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8592, 48253, '日本で茶道を習いました。', 'にほんで さどうを ならいました。', 'Tôi đã học trà đạo ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8593, 29324, '疲れていたので、よく眠りました。', 'つかれて いたので、よく ねむりました。', 'Mệt nên tôi ngủ rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8594, 31228, '周りの意見に同調するだけでは成長しない。', 'まわりの いけんに どうちょう する だけでは せいちょう しない。', 'Chỉ đồng tình theo ý kiến xung quanh thì không thể trưởng thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8595, 31230, 'この店は独自の方法でコーヒーをいれている。', 'この みせは どくじの ほうほうで コーヒーを いれて いる。', 'Quán này pha cà phê bằng cách riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8596, 39409, '本に夢中になって、駅を乗り過ごした。', 'ほんに むちゅうに なって、えきを のりすごした。', 'Mải mê đọc sách nên tôi đi quá ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8597, 39407, '会場は期待に満ちた空気だった。', 'かいじょうは きたいに みちた くうき だった。', 'Hội trường tràn ngập bầu không khí mong đợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8598, 39408, '今日は妙に静かだね。', 'きょうは みょうに しずかだね。', 'Hôm nay yên ắng lạ thường nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8599, 39411, '飛行機は無事に着陸した。', 'ひこうきは ぶじに ちゃくりく した。', 'Máy bay đã hạ cánh an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8600, 39410, '砂糖なしのコーヒーをください。', 'さとう なしの コーヒーを ください。', 'Cho tôi cà phê không đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8601, 39406, '万一に備えて、保険に入っている。', 'まんいちに そなえて、ほけんに はいって いる。', 'Tôi mua bảo hiểm để phòng khi bất trắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8602, 46451, '資源ごみは水曜日に出してください。', 'しげん ごみは すいようびに だして ください。', 'Rác tái chế hãy đổ vào thứ tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8603, 46452, '工場の廃棄物を正しく処理する。', 'こうじょうの はいきぶつを ただしく しょり する。', 'Xử lý đúng cách chất thải của nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8604, 46456, '家の屋根に太陽光パネルをつけた。', 'いえの やねに たいようこう パネルを つけた。', 'Tôi lắp tấm pin mặt trời trên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8605, 46458, '原子力発電について議論が続いている。', 'げんしりょく はつでんに ついて ぎろんが つづいて いる。', 'Tranh luận về điện hạt nhân vẫn tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8606, 46460, 'この川の水を使って発電している。', 'この かわの みずを つかって はつでん して いる。', 'Người ta dùng nước sông này để phát điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8607, 46462, 'この町は昔から漁業が盛んだ。', 'この まちは むかしから ぎょぎょうが さかんだ。', 'Thị trấn này từ xưa đã phát triển nghề cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8608, 46465, '小学校でうさぎを飼育している。', 'しょうがっこうで うさぎを しいく して いる。', 'Trường tiểu học có nuôi thỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8609, 46466, '環境保護のために、マイバッグを使っている。', 'かんきょう ほごの ために、マイバッグを つかって いる。', 'Để bảo vệ môi trường, tôi dùng túi cá nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8610, 46468, '彼の発言は影響力が大きい。', 'かれの はつげんは えいきょうりょくが おおきい。', 'Phát ngôn của ông ấy có sức ảnh hưởng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8611, 46471, '市は駅前の緑化を進めている。', 'しは えきまえの りょっかを すすめて いる。', 'Thành phố đang đẩy mạnh phủ xanh khu trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8612, 46475, '冬に備えて食料を蓄えた。', 'ふゆに そなえて しょくりょうを たくわえた。', 'Chúng tôi dự trữ lương thực cho mùa đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8613, 46476, '夜更かしは健康に悪い影響を及ぼす。', 'よふかしは けんこうに わるい えいきょうを およぼす。', 'Thức khuya gây ảnh hưởng xấu đến sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8614, 46479, '怒りを抑えて、冷静に話した。', 'いかりを おさえて、れいせいに はなした。', 'Tôi kìm cơn giận và nói chuyện bình tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8615, 46481, '山の空気は澄んでいる。', 'やまの くうきは すんで いる。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8616, 46483, '話が尽きなくて、朝まで話した。', 'はなしが つきなくて、あさまで はなした。', 'Chuyện không dứt nên chúng tôi nói đến sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8617, 46486, '人手不足が深刻化している。', 'ひとで ぶそくが しんこくか して いる。', 'Tình trạng thiếu nhân lực đang trở nên nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8618, 46568, '教育の改革が必要だと言われている。', 'きょういくの かいかくが ひつようだと いわれて いる。', 'Người ta cho rằng cần phải cải cách giáo dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8619, 29061, '毎朝体重を量ります。', 'まいあさ たいじゅうを はかります。', 'Sáng nào tôi cũng cân cân nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8620, 29153, '毎朝、犬にえさをやります。', 'まいあさ、いぬに えさを やります。', 'Sáng nào tôi cũng cho chó ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8621, 29224, '大学で法律を勉強しています。', 'だいがくで ほうりつを べんきょう して います。', 'Tôi đang học luật ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8622, 39413, 'この山は名が知られている。', 'この やまは なが しられて いる。', 'Ngọn núi này nổi danh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8623, 39420, 'デパートで子供が迷子になった。', 'デパートで こどもが まいごに なった。', 'Đứa trẻ bị lạc ở trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8624, 39437, '本は一生の友だ。', 'ほんは いっしょうの ともだ。', 'Sách là người bạn suốt đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8626, 46569, '法律が改正されて、成人の年齢が十八歳になった。', 'ほうりつが かいせい されて、せいじんの ねんれいが じゅうはっさいに なった。', 'Luật được sửa đổi, tuổi thành niên trở thành 18.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8627, 46572, 'この路線のバスは来月で廃止される。', 'この ろせんの バスは らいげつで はいし される。', 'Tuyến xe buýt này sẽ bị bãi bỏ từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8628, 46575, '住民は工場の建設に抗議した。', 'じゅうみんは こうじょうの けんせつに こうぎ した。', 'Người dân phản đối việc xây dựng nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8629, 46577, '日本の学生と交流するイベントに参加した。', 'にほんの がくせいと こうりゅう する イベントに さんか した。', 'Tôi tham gia sự kiện giao lưu với sinh viên Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8630, 46580, '戦争で多くの人が難民になった。', 'せんそうで おおくの ひとが なんみんに なった。', 'Chiến tranh khiến nhiều người trở thành người tị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8631, 46582, '貧困に苦しむ子供たちを支援したい。', 'ひんこんに くるしむ こどもたちを しえん したい。', 'Tôi muốn giúp đỡ những đứa trẻ khổ vì nghèo đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8632, 46584, 'すべての人の人権を守らなければならない。', 'すべての ひとの じんけんを まもらなければ ならない。', 'Phải bảo vệ nhân quyền của tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8633, 46586, '電力の自由化で、会社を選べるようになった。', 'でんりょくの じゆうかで、かいしゃを えらべる ように なった。', 'Nhờ tự do hóa ngành điện, giờ ta có thể chọn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8634, 46588, '多数の人がその案に賛成した。', 'たすうの ひとが その あんに さんせい した。', 'Đa số mọi người tán thành đề án đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8635, 46594, '二つの意見が対立している。', 'ふたつの いけんが たいりつ して いる。', 'Hai ý kiến đang đối lập nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8636, 46597, '両社は話し合いの末、合意に達した。', 'りょうしゃは はなしあいの すえ、ごういに たっした。', 'Sau khi bàn bạc, hai công ty đã đạt được đồng thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8637, 46598, '専門家の間でも見解が分かれている。', 'せんもんかの あいだでも けんかいが わかれて いる。', 'Ngay giữa các chuyên gia cũng có quan điểm khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8638, 46601, '先生は毎日たくさんの宿題を課す。', 'せんせいは まいにち たくさんの しゅくだいを かす。', 'Ngày nào thầy cũng giao nhiều bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8639, 46604, '館内での撮影は禁じられています。', 'かんないでの さつえいは きんじられて います。', 'Cấm chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8640, 46606, '彼は不当な理由で解雇された。', 'かれは ふとうな りゆうで かいこ された。', 'Anh ấy bị sa thải vì lý do bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8641, 46608, '会場の入口は厳重に警備されている。', 'かいじょうの いりぐちは げんじゅうに けいび されて いる。', 'Lối vào hội trường được canh gác nghiêm ngặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8642, 46610, '新しいゲームを開発している。', 'あたらしい ゲームを かいはつ して いる。', 'Chúng tôi đang phát triển một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8643, 46613, '新しいカメラは性能がいい。', 'あたらしい カメラは せいのうが いい。', 'Chiếc máy ảnh mới có tính năng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8644, 46614, 'このスマホにはたくさんの機能がある。', 'この スマホには たくさんの きのうが ある。', 'Chiếc điện thoại này có rất nhiều chức năng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8645, 46619, 'このシャツは自然の素材で作られている。', 'この シャツは しぜんの そざいで つくられて いる。', 'Chiếc áo này làm từ chất liệu tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8646, 29404, '母の日の贈り物を選んでいます。', 'ははの ひの おくりものを えらんで います。', 'Tôi đang chọn quà cho ngày của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8647, 39465, '二人は性格が合わなくて離婚した。', 'ふたりは せいかくが あわなくて りこん した。', 'Hai người không hợp tính nên đã ly hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8648, 39464, '大学に入って、家族と離れて暮らしている。', 'だいがくに はいって、かぞくと はなれて くらして いる。', 'Vào đại học, tôi sống xa gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8649, 39466, '名前を呼ばれて、彼は立ち上がった。', 'なまえを よばれて、かれは たちあがった。', 'Được gọi tên, anh ấy đứng dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8650, 39463, 'この犬はとても利口だ。', 'この いぬは とても りこうだ。', 'Con chó này rất khôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8651, 39468, 'この川は流れが速いので危ない。', 'この かわは ながれが はやいので あぶない。', 'Sông này nước chảy xiết nên rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8652, 31640, '彼は部下から信頼されている。', 'かれは ぶかから しんらい されて いる。', 'Anh ấy được cấp dưới tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8653, 31663, '台風で農作物に大きな被害が出た。', 'たいふうで のうさくもつに おおきな ひがいが でた。', 'Bão gây thiệt hại lớn cho hoa màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8654, 31658, '国と国の相互理解が大切だ。', 'くにと くにの そうご りかいが たいせつだ。', 'Sự hiểu biết lẫn nhau giữa các nước là quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8655, 46621, '燃料の値段が上がって、運賃も高くなった。', 'ねんりょうの ねだんが あがって、うんちんも たかく なった。', 'Giá nhiên liệu tăng nên giá vé cũng đắt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8656, 46623, 'ここは電波が弱くて、電話がつながらない。', 'ここは でんぱが よわくて、でんわが つながらない。', 'Ở đây sóng yếu nên không gọi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8657, 46628, '学校で体力を測定した。', 'がっこうで たいりょくを そくてい した。', 'Ở trường chúng tôi đã đo thể lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8658, 46629, '今夜は流れ星の観測に最適だ。', 'こんやは ながれぼしの かんそくに さいてきだ。', 'Đêm nay rất lý tưởng để quan sát sao băng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8659, 46631, '理論はわかっても、実際にやるのは難しい。', 'りろんは わかっても、じっさいに やるのは むずかしい。', 'Hiểu lý thuyết rồi nhưng làm thực tế thì khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8660, 46634, 'この薬の成分を確認してください。', 'この くすりの せいぶんを かくにん して ください。', 'Hãy kiểm tra thành phần của thuốc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8661, 46635, '人の体は多くの細胞でできている。', 'ひとの からだは おおくの さいぼうで できて いる。', 'Cơ thể người được tạo nên từ vô số tế bào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8662, 46637, 'この地域は医療の設備が足りない。', 'この ちいきは いりょうの せつびが たりない。', 'Khu vực này thiếu cơ sở y tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8663, 31639, '監督の言葉がチームを鼓舞した。', 'かんとくの ことばが チームを こぶ した。', 'Lời của huấn luyện viên đã cổ vũ tinh thần cả đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8664, 31641, '一度失った信用を取り戻すのは難しい。', 'いちど うしなった しんようを とりもどすのは むずかしい。', 'Lấy lại lòng tin một khi đã mất là rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8665, 31642, 'うそが続いて、彼への不信が強まった。', 'うそが つづいて、かれへの ふしんが つよまった。', 'Những lời nói dối liên tiếp khiến sự nghi ngờ đối với anh ta tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8666, 31645, '信じていた友達に裏切られた。', 'しんじて いた ともだちに うらぎられた。', 'Tôi bị người bạn mình tin tưởng phản bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8667, 31653, 'チームの結束が勝利につながった。', 'チームの けっそくが しょうりに つながった。', 'Sự đoàn kết của đội đã dẫn đến chiến thắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8668, 31657, 'ボランティアの間に連帯感が生まれた。', 'ボランティアの あいだに れんたいかんが うまれた。', 'Giữa các tình nguyện viên đã nảy sinh tinh thần liên đới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8669, 31660, 'この会社は今、経営の危機にある。', 'この かいしゃは いま、けいえいの ききに ある。', 'Công ty này hiện đang trong khủng hoảng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8670, 31643, '彼の説明に疑念を抱いた。', 'かれの せつめいに ぎねんを いだいた。', 'Tôi nảy sinh nghi ngờ với lời giải thích của anh ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8671, 31644, '自分の目を疑った。', 'じぶんの めを うたがった。', 'Tôi không tin vào mắt mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8672, 31655, 'いったい何があったんですか。', 'いったい なにが あったん ですか。', 'Rốt cuộc đã có chuyện gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8673, 39476, 'お連れの方はどちらにいらっしゃいますか。', 'おつれの かたは どちらに いらっしゃいますか。', 'Người đi cùng quý khách đang ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8674, 39479, '最近、老いを感じるようになった。', 'さいきん、おいを かんじる ように なった。', 'Gần đây tôi bắt đầu cảm thấy mình già đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8675, 39480, '老人ホームでボランティアをしている。', 'ろうじんホームで ボランティアを して いる。', 'Tôi làm tình nguyện ở viện dưỡng lão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8676, 39483, 'かばんを脇に抱えて走った。', 'かばんを わきに かかえて はしった。', 'Tôi kẹp chiếc cặp dưới nách rồi chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8677, 39477, '夏といえば、海を連想する。', 'なつと いえば、うみを れんそう する。', 'Nhắc đến mùa hè là tôi liên tưởng đến biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8678, 39481, 'この本は日本の教育について論じている。', 'この ほんは にほんの きょういくに ついて ろんじて いる。', 'Cuốn sách này bàn luận về giáo dục Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8679, 39482, '家族で旅行の行き先を話し合った。', 'かぞくで りょこうの いきさきを はなしあった。', 'Cả nhà bàn bạc về điểm đến của chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8680, 39471, 'タクシーの料金が上がった。', 'タクシーの りょうきんが あがった。', 'Cước taxi đã tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8681, 39478, '長時間の労働は体に悪い。', 'ちょうじかんの ろうどうは からだに わるい。', 'Lao động nhiều giờ liền không tốt cho sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8682, 39470, '来年、日本に留学する予定です。', 'らいねん、にほんに りゅうがく する よてい です。', 'Sang năm tôi dự định đi du học Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8683, 39485, 'かごに野菜をたくさん入れた。', 'かごに やさいを たくさん いれた。', 'Tôi bỏ thật nhiều rau vào giỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8684, 42868, '寒い日は温かいスープが飲みたくなる。', 'さむい ひは あたたかい スープが のみたく なる。', 'Ngày lạnh lại thèm bát súp nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8685, 39474, '夜行列車で北海道へ行った。', 'やこう れっしゃで ほっかいどうへ いった。', 'Tôi đi Hokkaido bằng tàu đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8686, 42862, '休日はカーシェアを利用している。', 'きゅうじつは カーシェアを りよう して いる。', 'Ngày nghỉ tôi dùng dịch vụ đi chung xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8687, 39484, '東京湾にたくさんの船が浮かんでいる。', 'とうきょうわんに たくさんの ふねが うかんで いる。', 'Vịnh Tokyo có rất nhiều tàu thuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8688, 39467, 'トイレの水を流すのを忘れないで。', 'トイレの みずを ながすのを わすれないで。', 'Đừng quên xả nước nhà vệ sinh nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8689, 39469, '町の真ん中を大きな川が流れている。', 'まちの まんなかを おおきな かわが ながれて いる。', 'Một con sông lớn chảy qua giữa thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8690, 42867, '冬の服を押し入れに仕舞った。', 'ふゆの ふくを おしいれに しまった。', 'Tôi đã cất quần áo mùa đông vào tủ âm tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8691, 39475, 'この商品は値段は安いが、質が劣る。', 'この しょうひんは ねだんは やすいが、しつが おとる。', 'Hàng này giá rẻ nhưng chất lượng kém hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8692, 39486, 'たまには贅沢なレストランで食事したい。', 'たまには ぜいたくな レストランで しょくじ したい。', 'Thỉnh thoảng tôi muốn ăn ở nhà hàng sang trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8693, 39472, 'みんなで輪になって踊った。', 'みんなで わに なって おどった。', 'Mọi người xếp thành vòng tròn nhảy múa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8694, 39473, '店の前に長い列ができている。', 'みせの まえに ながい れつが できて いる。', 'Trước cửa hàng có một hàng dài người xếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8695, 42859, '手伝ってくれて、ありがとう。', 'てつだって くれて、ありがとう。', 'Cảm ơn bạn đã giúp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8696, 42860, 'いらっしゃい。どうぞ上がって。', 'いらっしゃい。どうぞ あがって。', 'Chào mừng bạn đến chơi. Mời vào nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8697, 42861, '合格、おめでとう!', 'ごうかく、おめでとう!', 'Chúc mừng bạn thi đỗ!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8698, 42873, '時間はたっぷりあるから、ゆっくりでいいよ。', 'じかんは たっぷり あるから、ゆっくりで いいよ。', 'Còn dư thời gian, cứ từ từ thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8699, 41089, '原油の価格が上がっている。', 'げんゆの かかくが あがって いる。', 'Giá dầu thô đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8700, 31581, '先生の説明をやっと理解できた。', 'せんせいの せつめいを やっと りかい できた。', 'Cuối cùng tôi cũng hiểu được lời giải thích của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8701, 31577, '彼の説明に納得できなかった。', 'かれの せつめいに なっとく できなかった。', 'Tôi không thể chấp nhận lời giải thích của anh ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8702, 31607, '審判の判定に不満を持つ選手もいた。', 'しんぱんの はんていに ふまんを もつ せんしゅも いた。', 'Có cầu thủ không hài lòng với phán định của trọng tài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8703, 31592, '来月から新しい制度を実施する。', 'らいげつから あたらしい せいどを じっし する。', 'Từ tháng sau sẽ thực thi chế độ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8704, 31593, '計画を立てるだけでなく、実行することが大切だ。', 'けいかくを たてる だけで なく、じっこう する ことが たいせつだ。', 'Không chỉ lập kế hoạch mà thực hiện mới quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8705, 46644, 'インフルエンザの予防注射を受けた。', 'インフルエンザの よぼう ちゅうしゃを うけた。', 'Tôi đã tiêm phòng cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8706, 46650, '適度な運動は老化を遅らせる。', 'てきどな うんどうは ろうかを おくらせる。', 'Vận động vừa phải làm chậm quá trình lão hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8707, 46652, 'スマホが普及して、生活が大きく変わった。', 'スマホが ふきゅう して、せいかつが おおきく かわった。', 'Điện thoại thông minh phổ biến khiến cuộc sống thay đổi lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8708, 46656, '病院で精密な検査を受けた。', 'びょういんで せいみつな けんさを うけた。', 'Tôi đã được kiểm tra kỹ lưỡng ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8709, 46658, 'この研究所は先端の技術を研究している。', 'この けんきゅうじょは せんたんの ぎじゅつを けんきゅう して いる。', 'Viện này nghiên cứu công nghệ tiên tiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8710, 46660, '買ってきた本棚を自分で組み立てた。', 'かって きた ほんだなを じぶんで くみたてた。', 'Tôi tự lắp ráp chiếc giá sách mới mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8711, 46663, '間違えて大事なファイルを削除してしまった。', 'まちがえて だいじな ファイルを さくじょ して しまった。', 'Tôi lỡ xóa nhầm một tệp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8712, 46666, 'この絵は有名な作品の複製だ。', 'この えは ゆうめいな さくひんの ふくせいだ。', 'Bức tranh này là bản sao của một tác phẩm nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8713, 46668, '十分たつと、画面は自動的に暗くなる。', 'じゅっぷん たつと、がめんは じどうてきに くらく なる。', 'Sau mười phút, màn hình tự động tối đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8714, 46669, 'パリは芸術の町として知られている。', 'パリは げいじゅつの まちと して しられて いる。', 'Paris được biết đến là thành phố nghệ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8715, 31584, '会社の方針が変わった。', 'かいしゃの ほうしんが かわった。', 'Phương châm của công ty đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8716, 31578, '丁寧に説明すると、相手の納得感が高まる。', 'ていねいに せつめい すると、あいての なっとくかんが たかまる。', 'Giải thích tận tình thì người nghe sẽ thấy thuyết phục hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8717, 31579, '両親を説得して、留学を許してもらった。', 'りょうしんを せっとく して、りゅうがくを ゆるして もらった。', 'Tôi thuyết phục được bố mẹ cho đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8718, 31583, '会議は明日だと勘違いしていた。', 'かいぎは あしただと かんちがい して いた。', 'Tôi cứ nhầm là cuộc họp vào ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8719, 31586, '新しい販売戦略を考えた。', 'あたらしい はんばい せんりゃくを かんがえた。', 'Chúng tôi đã nghĩ ra chiến lược bán hàng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8720, 31589, '目的のためなら手段を選ばない人もいる。', 'もくてきの ためなら しゅだんを えらばない ひとも いる。', 'Có người vì mục đích mà bất chấp thủ đoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8721, 31596, '登録が完了しました。', 'とうろくが かんりょう しました。', 'Đăng ký đã hoàn tất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8722, 31599, '事故の影響で、電車に遅延が出ている。', 'じこの えいきょうで、でんしゃに ちえんが でて いる。', 'Do ảnh hưởng của tai nạn, tàu điện đang bị chậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8723, 31602, '段取りがいいので、仕事が早く終わった。', 'だんどりが いいので、しごとが はやく おわった。', 'Sắp xếp trình tự tốt nên công việc xong sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8724, 46671, '将来は作家になりたい。', 'しょうらいは さっかに なりたい。', 'Sau này tôi muốn trở thành nhà văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8725, 46675, '監督の指示で選手が動いた。', 'かんとくの しじで せんしゅが うごいた。', 'Các cầu thủ di chuyển theo chỉ thị của huấn luyện viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8726, 46677, '劇団の公演は来週から始まる。', 'げきだんの こうえんは らいしゅうから はじまる。', 'Buổi biểu diễn của đoàn kịch bắt đầu từ tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8727, 46681, '宗教によって食べられない物がある。', 'しゅうきょうに よって たべられない ものが ある。', 'Tùy tôn giáo mà có những thứ không được ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8728, 43977, '病院で注射をしてもらいました。', 'びょういんで ちゅうしゃを して もらいました。', 'Tôi được tiêm ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8729, 46682, '神社で伝統的な儀式が行われた。', 'じんじゃで でんとうてきな ぎしきが おこなわれた。', 'Một nghi lễ truyền thống đã được tổ chức ở đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8799, 37799, '使わない物は倉庫にしまってある。', 'つかわない ものは そうこに しまって ある。', 'Đồ không dùng được cất trong nhà kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8730, 46685, 'このお寺は重要な文化財に指定されている。', 'この おてらは じゅうような ぶんかざいに してい されて いる。', 'Ngôi chùa này được công nhận là di sản văn hóa quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8731, 46688, 'この作家の随筆はやさしい言葉で書かれている。', 'この さっかの ずいひつは やさしい ことばで かかれて いる。', 'Tùy bút của nhà văn này được viết bằng lời lẽ giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8732, 46690, 'この小説は有名な翻訳者が訳した。', 'この しょうせつは ゆうめいな ほんやくしゃが やくした。', 'Cuốn tiểu thuyết này do một dịch giả nổi tiếng dịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8733, 46693, '番組に視聴者から多くの意見が届いた。', 'ばんぐみに しちょうしゃから おおくの いけんが とどいた。', 'Chương trình nhận được nhiều ý kiến từ khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8734, 46695, '新聞の番組表で今夜の映画を探した。', 'しんぶんの ばんぐみひょうで こんやの えいがを さがした。', 'Tôi xem lịch chương trình trên báo để tìm phim tối nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8735, 46703, '今年はこの色の服が流行している。', 'ことしは この いろの ふくが りゅうこう して いる。', 'Năm nay quần áo màu này đang thịnh hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8736, 46705, '今、この映画が話題になっている。', 'いま、この えいがが わだいに なって いる。', 'Hiện bộ phim này đang được bàn tán sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8737, 46706, '気持ちを言葉で表現するのは難しい。', 'きもちを ことばで ひょうげん するのは むずかしい。', 'Diễn đạt cảm xúc bằng lời thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8738, 46710, '趣味は映画鑑賞です。', 'しゅみは えいが かんしょう です。', 'Sở thích của tôi là thưởng thức phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8739, 46712, 'スタジアムは観客でいっぱいだった。', 'スタジアムは かんきゃくで いっぱい だった。', 'Sân vận động chật kín khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8740, 46716, 'その本の題名を忘れてしまった。', 'その ほんの だいめいを わすれて しまった。', 'Tôi quên mất tựa đề cuốn sách đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8741, 46717, '彼は映画で医者の役を演じた。', 'かれは えいがで いしゃの やくを えんじた。', 'Anh ấy đóng vai bác sĩ trong phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8742, 46719, '彼は日本の歴史について本を著した。', 'かれは にほんの れきしに ついて ほんを あらわした。', 'Ông ấy đã viết sách về lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8743, 46721, 'この村には古い伝説が伝わっている。', 'この むらには ふるい でんせつが つたわって いる。', 'Ngôi làng này lưu truyền một truyền thuyết cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8744, 46725, '白鳥が優雅に泳いでいる。', 'はくちょうが ゆうがに およいで いる。', 'Những chú thiên nga đang bơi một cách tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8745, 46727, '葬式に派手な服は着ないほうがいい。', 'そうしきに はでな ふくは きない ほうが いい。', 'Không nên mặc đồ sặc sỡ đến đám tang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8746, 31638, '社長が選手たちを激励した。', 'しゃちょうが せんしゅたちを げきれい した。', 'Giám đốc đã khích lệ các vận động viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8747, 31630, '病院と学校が連携して子供を守る。', 'びょういんと がっこうが れんけい して こどもを まもる。', 'Bệnh viện và trường học phối hợp bảo vệ trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8748, 31636, '被災地に食料を援助した。', 'ひさいちに しょくりょうを えんじょ した。', 'Chúng tôi viện trợ lương thực cho vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8749, 31706, '仕事のために資格を取りたい。', 'しごとの ために しかくを とりたい。', 'Tôi muốn lấy chứng chỉ để phục vụ công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8750, 31711, '面接を受けた会社に採用された。', 'めんせつを うけた かいしゃに さいよう された。', 'Tôi đã được công ty mình phỏng vấn tuyển dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8751, 31709, '試験に合格して、とてもうれしい。', 'しけんに ごうかく して、とても うれしい。', 'Thi đỗ rồi, tôi vui lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8752, 31710, '一回目の試験は不合格だった。', 'いっかいめの しけんは ふごうかく だった。', 'Lần thi đầu tôi đã trượt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8753, 31704, '夜になって、気温が急激に下がった。', 'よるに なって、きおんが きゅうげきに さがった。', 'Về đêm nhiệt độ giảm đột ngột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8754, 46728, '彼は難しい技を見事に成功させた。', 'かれは むずかしい わざを みごとに せいこう させた。', 'Anh ấy thực hiện thành công một kỹ thuật khó một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8755, 46731, '来月から大阪の支店に異動になった。', 'らいげつから おおさかの してんに いどうに なった。', 'Từ tháng sau tôi được điều sang chi nhánh Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8756, 46732, '姉は派遣社員として働いている。', 'あねは はけん しゃいんと して はたらいて いる。', 'Chị tôi làm việc với tư cách nhân viên phái cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8757, 46735, '会社を選ぶとき、福利厚生も大切だ。', 'かいしゃを えらぶ とき、ふくり こうせいも たいせつだ。', 'Khi chọn công ty, chế độ phúc lợi cũng quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8758, 46737, '今日の業務は五時に終わった。', 'きょうの ぎょうむは ごじに おわった。', 'Công việc hôm nay kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8759, 46741, '今日の会議の議題は来年の予算です。', 'きょうの かいぎの ぎだいは らいねんの よさん です。', 'Chủ đề cuộc họp hôm nay là ngân sách năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8760, 46743, '新商品の企画が通った。', 'しんしょうひんの きかくが とおった。', 'Kế hoạch sản phẩm mới đã được duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8761, 46745, '彼は営業で大きな実績を上げた。', 'かれは えいぎょうで おおきな じっせきを あげた。', 'Anh ấy đạt thành tích lớn trong kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8762, 46746, '今学期の評定は「優」だった。', 'こんがっきの ひょうていは 「ゆう」 だった。', 'Xếp loại học kỳ này của tôi là "Giỏi".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8763, 46749, '隣の人から騒音の苦情が来た。', 'となりの ひとから そうおんの くじょうが きた。', 'Hàng xóm đã phàn nàn về tiếng ồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8975, 39551, '赤ちゃんを毛布でくるんだ。', 'あかちゃんを もうふで くるんだ。', 'Tôi quấn em bé trong chăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8764, 46753, '一度失った信用を取り戻すのは難しい。', 'いちど うしなった しんようを とりもどすのは むずかしい。', 'Lấy lại lòng tin một khi đã mất là rất khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8765, 46755, 'お客様には敬語を使いましょう。', 'おきゃくさまには けいごを つかいましょう。', 'Hãy dùng kính ngữ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8766, 46756, 'チームで働くには協調性が必要だ。', 'チームで はたらくには きょうちょうせいが ひつようだ。', 'Làm việc nhóm cần tính hòa đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8767, 46757, '職場の人間関係に悩んでいる。', 'しょくばの にんげん かんけいに なやんで いる。', 'Tôi đang khổ tâm vì các mối quan hệ ở chỗ làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8768, 46760, '帰国する友達の送別会をした。', 'きこく する ともだちの そうべつかいを した。', 'Chúng tôi làm tiệc chia tay người bạn về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8769, 31708, '来月、資格試験を受ける予定だ。', 'らいげつ、しかく しけんを うける よていだ。', 'Tháng sau tôi dự định thi lấy chứng chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8770, 31700, '社会は今、大きな過渡期にある。', 'しゃかいは いま、おおきな かときに ある。', 'Xã hội hiện đang trong giai đoạn chuyển tiếp lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8771, 31699, '新しいシステムへの移行が完了した。', 'あたらしい システムへの いこうが かんりょう した。', 'Việc chuyển sang hệ thống mới đã hoàn tất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8772, 31702, '十年ぶりに帰ると、町は大きく変貌していた。', 'じゅうねんぶりに かえると、まちは おおきく へんぼう して いた。', 'Sau mười năm trở về, thị trấn đã thay đổi diện mạo hoàn toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8773, 31705, 'この坂は緩やかなので、歩きやすい。', 'この さかは ゆるやか なので、あるきやすい。', 'Con dốc này thoai thoải nên dễ đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8774, 37800, '大事なことは慎重に決めたほうがいい。', 'だいじな ことは しんちょうに きめた ほうが いい。', 'Chuyện quan trọng thì nên quyết định thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8775, 37802, 'どんなときも冷静に判断しよう。', 'どんな ときも れいせいに はんだん しよう。', 'Lúc nào cũng hãy bình tĩnh phán đoán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8776, 37791, 'あの会社とは長い間取引がある。', 'あの かいしゃとは ながい あいだ とりひきが ある。', 'Chúng tôi giao dịch với công ty đó đã lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8777, 37792, '契約書をよく読んでからサインしてください。', 'けいやくしょを よく よんでから サイン して ください。', 'Hãy đọc kỹ hợp đồng rồi mới ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8778, 37798, 'その商品は在庫がありません。', 'その しょうひんは ざいこが ありません。', 'Mặt hàng đó đã hết hàng trong kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8779, 37789, 'あの会社は株式を上場した。', 'あの かいしゃは かぶしきを じょうじょう した。', 'Công ty đó đã niêm yết cổ phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8780, 37790, '銀行から店を開くための融資を受けた。', 'ぎんこうから みせを ひらく ための ゆうしを うけた。', 'Tôi được ngân hàng cho vay vốn để mở cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8781, 44029, '大学で社会について勉強しています。', 'だいがくで しゃかいに ついて べんきょう して います。', 'Tôi đang học về xã hội ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8782, 46762, '思いやりのある人になりたい。', 'おもいやりの ある ひとに なりたい。', 'Tôi muốn trở thành người biết quan tâm đến người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8783, 46763, '彼女は遠回しに誘いを断った。', 'かのじょは とおまわしに さそいを ことわった。', 'Cô ấy từ chối lời mời một cách vòng vo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8784, 46765, '彼は誠実な人だから信頼できる。', 'かれは せいじつな ひと だから しんらい できる。', 'Anh ấy là người thành thật nên có thể tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8785, 46767, '祖父は頑固で、人の話を聞かない。', 'そふは がんこで、ひとの はなしを きかない。', 'Ông tôi bướng bỉnh, không chịu nghe ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8786, 46769, '新人のくせに偉そうなことを言う。', 'しんじんの くせに えらそうな ことを いう。', 'Mới vào mà đã nói năng ra vẻ ta đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8787, 46770, '悩みを親友に打ち明けた。', 'なやみを しんゆうに うちあけた。', 'Tôi đã thổ lộ nỗi lòng với bạn thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8788, 37803, '率直な意見を聞かせてください。', 'そっちょくな いけんを きかせて ください。', 'Hãy cho tôi nghe ý kiến thẳng thắn của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8789, 37805, '祖父は頑固で、人の話を聞かない。', 'そふは がんこで、ひとの はなしを きかない。', 'Ông tôi bướng bỉnh, không chịu nghe ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8790, 31719, '彼は営業で大きな実績を上げた。', 'かれは えいぎょうで おおきな じっせきを あげた。', 'Anh ấy đạt thành tích lớn trong kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8791, 37801, '彼は大胆な計画を発表した。', 'かれは だいたんな けいかくを はっぴょう した。', 'Anh ấy công bố một kế hoạch táo bạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8792, 37804, '成功してから、彼は傲慢になった。', 'せいこう してから、かれは ごうまんに なった。', 'Từ khi thành công, anh ta trở nên kiêu ngạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8793, 31712, '残念ながら、今回は不採用となりました。', 'ざんねん ながら、こんかいは ふさいようと なりました。', 'Rất tiếc, lần này bạn không được tuyển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8794, 31715, '履歴書に写真をはってください。', 'りれきしょに しゃしんを はって ください。', 'Hãy dán ảnh vào sơ yếu lý lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8795, 31723, '専門家の意見を聞いてみよう。', 'せんもんかの いけんを きいて みよう。', 'Hãy thử nghe ý kiến của chuyên gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8796, 31726, '入社後、一か月の研修がある。', 'にゅうしゃご、いっかげつの けんしゅうが ある。', 'Sau khi vào công ty có một tháng đào tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8797, 37795, '部品を工場に発注した。', 'ぶひんを こうじょうに はっちゅう した。', 'Chúng tôi đã đặt linh kiện từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8798, 37797, '商品は来週の月曜日に納品します。', 'しょうひんは らいしゅうの げつようびに のうひん します。', 'Hàng sẽ được giao vào thứ Hai tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8800, 44060, '大学で法律を勉強しています。', 'だいがくで ほうりつを べんきょう して います。', 'Tôi đang học luật ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8801, 37815, '会議で新しい企画を提案した。', 'かいぎで あたらしい きかくを ていあん した。', 'Tôi đề xuất một kế hoạch mới trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8802, 37826, '兄は今年、大学を受験する。', 'あには ことし、だいがくを じゅけん する。', 'Năm nay anh tôi thi đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8803, 37828, '奨学金をもらって大学に通っている。', 'しょうがくきんを もらって だいがくに かよって いる。', 'Tôi nhận học bổng để học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8804, 46772, '先輩に怒られても、言い返せなかった。', 'せんぱいに おこられても、いいかえせなかった。', 'Bị đàn anh mắng, tôi không cãi lại được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8805, 46773, '雨のため、今日の出発は見送ることにした。', 'あめの ため、きょうの しゅっぱつは みおくる ことに した。', 'Vì mưa, chúng tôi quyết định hoãn chuyến đi hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8806, 46776, '前の担当者から仕事を引き継いだ。', 'まえの たんとうしゃから しごとを ひきついだ。', 'Tôi tiếp quản công việc từ người phụ trách trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8807, 46779, '泣いている子供を優しく慰めた。', 'ないて いる こどもを やさしく なぐさめた。', 'Tôi dịu dàng dỗ dành đứa trẻ đang khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8808, 46780, '自分ばかり責めないでください。', 'じぶん ばかり せめないで ください。', 'Đừng chỉ tự trách bản thân như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8809, 46782, '困ったときは、いつでも頼ってください。', 'こまった ときは、いつでも たよって ください。', 'Khi khó khăn, cứ dựa vào tôi bất cứ lúc nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8810, 46784, '一日中歩いて、くたびれた。', 'いちにちじゅう あるいて、くたびれた。', 'Đi bộ cả ngày nên mệt lả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8811, 46785, 'けんかした後、気まずい雰囲気になった。', 'けんか した あと、きまずい ふんいきに なった。', 'Sau khi cãi nhau, bầu không khí trở nên khó xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8812, 46789, '外来種が生態系を壊している。', 'がいらいしゅが せいたいけいを こわして いる。', 'Các loài ngoại lai đang phá vỡ hệ sinh thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8813, 37835, '都市と地方の格差が広がっている。', 'としと ちほうの かくさが ひろがって いる。', 'Khoảng cách giữa thành thị và nông thôn đang nới rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8814, 37820, '工場から排出されるガスを減らす必要がある。', 'こうじょうから はいしゅつ される ガスを へらす ひつようが ある。', 'Cần giảm lượng khí thải ra từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8815, 37814, '来年の旅行先はハワイに決定した。', 'らいねんの りょこうさきは ハワイに けってい した。', 'Điểm du lịch năm sau đã được quyết định là Hawaii.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8816, 38103, '社会人としての自覚を持ちなさい。', 'しゃかいじんと しての じかくを もちなさい。', 'Hãy có ý thức của một người đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8817, 38105, '怒っても理性を失ってはいけない。', 'おこっても りせいを うしなっては いけない。', 'Dù tức giận cũng không được mất lý trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8818, 37833, '会社は優秀な人材を求めている。', 'かいしゃは ゆうしゅうな じんざいを もとめて いる。', 'Công ty đang tìm kiếm nhân tài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8819, 37824, '国によって教育制度が違う。', 'くにに よって きょういく せいどが ちがう。', 'Mỗi nước có hệ thống giáo dục khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8820, 37827, 'この大学は偏差値が高い。', 'この だいがくは へんさちが たかい。', 'Trường đại học này có điểm chuẩn cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8821, 37829, '私立大学は授業料が高い。', 'しりつ だいがくは じゅぎょうりょうが たかい。', 'Đại học tư học phí cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8822, 37817, '授業で環境問題について話し合った。', 'じゅぎょうで かんきょう もんだいに ついて はなしあった。', 'Trong giờ học chúng tôi thảo luận về vấn đề môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8823, 37819, '二酸化炭素は温室効果を高める。', 'にさんかたんそは おんしつ こうかを たかめる。', 'Khí CO2 làm tăng hiệu ứng nhà kính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8824, 37823, '検査の結果、異常は見つからなかった。', 'けんさの けっか、いじょうは みつからなかった。', 'Kết quả kiểm tra không phát hiện bất thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8825, 38118, '授業では積極的に質問しよう。', 'じゅぎょうでは せっきょくてきに しつもん しよう。', 'Trong giờ học hãy tích cực đặt câu hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8826, 38119, '彼は会議ではいつも消極的だ。', 'かれは かいぎでは いつも しょうきょくてきだ。', 'Trong cuộc họp anh ấy lúc nào cũng thụ động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8827, 38123, '日本では、家に入るとき靴を脱ぐのが一般的だ。', 'にほんでは、いえに はいる とき くつを ぬぐのが いっぱんてきだ。', 'Ở Nhật, cởi giày khi vào nhà là chuyện thông thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8828, 46795, '工場から排出されるガスを減らす必要がある。', 'こうじょうから はいしゅつ される ガスを へらす ひつようが ある。', 'Cần giảm lượng khí thải ra từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8829, 46797, '車の排気ガスで空気が汚れている。', 'くるまの はいき ガスで くうきが よごれて いる。', 'Khí thải xe cộ làm bẩn không khí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8830, 46800, 'この川の水質は年々よくなっている。', 'この かわの すいしつは ねんねん よく なって いる。', 'Chất lượng nước sông này ngày càng tốt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8831, 46801, 'この地域は土壌が豊かで、作物がよく育つ。', 'この ちいきは どじょうが ゆたかで、さくもつが よく そだつ。', 'Vùng này đất đai màu mỡ nên hoa màu phát triển tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8832, 46805, '干ばつで米が育たなかった。', 'かんばつで こめが そだたなかった。', 'Do hạn hán, lúa không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8833, 46807, '地震のあとは津波に注意してください。', 'じしんの あとは つなみに ちゅうい して ください。', 'Sau động đất hãy cảnh giác với sóng thần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9050, 39684, '買い物袋をぶら下げて歩いた。', 'かいものぶくろを ぶらさげて あるいた。', 'Tôi xách túi đồ đi bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8834, 46809, '大雨で土砂崩れが起き、道が通れなくなった。', 'おおあめで どしゃくずれが おき、みちが とおれなく なった。', 'Mưa lớn gây lở đất khiến đường không đi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8835, 46810, '最近、世界中で異常気象が続いている。', 'さいきん、せかいじゅうで いじょう きしょうが つづいて いる。', 'Gần đây thời tiết bất thường liên tục xảy ra trên khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8836, 46812, '工場の廃棄物を正しく処理する。', 'こうじょうの はいきぶつを ただしく しょり する。', 'Xử lý đúng cách chất thải của nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8837, 38129, '実験で仮説が正しいことが証明された。', 'じっけんで かせつが ただしい ことが しょうめい された。', 'Thí nghiệm đã chứng minh giả thuyết là đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8838, 38107, '子供の発想はおもしろい。', 'こどもの はっそうは おもしろい。', 'Cách nghĩ của trẻ con rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8839, 38108, '留学をきっかけに人生観が変わった。', 'りゅうがくを きっかけに じんせいかんが かわった。', 'Nhờ đi du học mà quan niệm sống của tôi thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8840, 38127, '彼は理論的に説明するのが上手だ。', 'かれは りろんてきに せつめい するのが じょうずだ。', 'Anh ấy giỏi giải thích một cách có lý luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8841, 38135, 'スマホは年々進化している。', 'スマホは ねんねん しんか して いる。', 'Điện thoại thông minh tiến hóa qua từng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8842, 38132, '新しい考え方が社会に浸透してきた。', 'あたらしい かんがえかたが しゃかいに しんとう して きた。', 'Cách nghĩ mới đã dần thấm vào xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8843, 38134, 'このままでは、多くの村が消滅してしまう。', 'この ままでは、おおくの むらが しょうめつ して しまう。', 'Cứ đà này, nhiều ngôi làng sẽ biến mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8844, 38112, '彼の話は抽象的でわかりにくい。', 'かれの はなしは ちゅうしょうてきで わかりにくい。', 'Câu chuyện của anh ấy trừu tượng, khó hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8845, 38114, 'この評価は少し主観的すぎる。', 'この ひょうかは すこし しゅかんてき すぎる。', 'Đánh giá này hơi quá chủ quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8846, 38117, '効率的に仕事を進めたい。', 'こうりつてきに しごとを すすめたい。', 'Tôi muốn làm việc một cách hiệu quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8847, 38121, '彼はいつも否定的な意見ばかり言う。', 'かれは いつも ひていてきな いけん ばかり いう。', 'Anh ta lúc nào cũng chỉ đưa ra ý kiến phủ định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8848, 38124, 'この仕事には特殊な技術が必要だ。', 'この しごとには とくしゅな ぎじゅつが ひつようだ。', 'Công việc này cần kỹ thuật đặc thù.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8849, 44146, '今ちょうど十二時です。', 'いま ちょうど じゅうにじ です。', 'Bây giờ vừa đúng mười hai giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8850, 38140, '日本では高齢化が進んでいる。', 'にほんでは こうれいかが すすんで いる。', 'Ở Nhật, dân số đang ngày càng già hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8851, 38141, '少子化で学校の数が減っている。', 'しょうしかで がっこうの かずが へって いる。', 'Do tỷ lệ sinh giảm, số trường học đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8852, 38159, '旅行の前に保険に入った。', 'りょこうの まえに ほけんに はいった。', 'Trước chuyến đi tôi đã mua bảo hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8853, 38160, '祖父は年金で生活している。', 'そふは ねんきんで せいかつ して いる。', 'Ông tôi sống bằng lương hưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8854, 46815, '省エネのエアコンに買い替えた。', 'しょうエネの エアコンに かいかえた。', 'Tôi đã đổi sang điều hòa tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8855, 46817, '海の近くに風力発電所ができた。', 'うみの ちかくに ふうりょく はつでんしょが できた。', 'Một nhà máy điện gió đã được xây gần biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8856, 46819, '事故の後、放射能の検査が行われた。', 'じこの あと、ほうしゃのうの けんさが おこなわれた。', 'Sau sự cố, việc kiểm tra phóng xạ đã được tiến hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8857, 46820, 'この川の水を使って発電している。', 'この かわの みずを つかって はつでん して いる。', 'Người ta dùng nước sông này để phát điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8858, 46824, 'ベランダでトマトを栽培している。', 'ベランダで トマトを さいばい して いる。', 'Tôi trồng cà chua ở ban công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8859, 46826, '環境保護のために、マイバッグを使っている。', 'かんきょう ほごの ために、マイバッグを つかって いる。', 'Để bảo vệ môi trường, tôi dùng túi cá nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8860, 46828, '彼の発言は影響力が大きい。', 'かれの はつげんは えいきょうりょくが おおきい。', 'Phát ngôn của ông ấy có sức ảnh hưởng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8861, 46831, '市は駅前の緑化を進めている。', 'しは えきまえの りょっかを すすめて いる。', 'Thành phố đang đẩy mạnh phủ xanh khu trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8862, 46834, '努力がやっと実った。', 'どりょくが やっと みのった。', 'Nỗ lực cuối cùng đã đơm hoa kết trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8863, 38158, 'この地域は医療の設備が足りない。', 'この ちいきは いりょうの せつびが たりない。', 'Khu vực này thiếu cơ sở y tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8864, 38150, '会議は予定どおりに進行した。', 'かいぎは よてい どおりに しんこう した。', 'Cuộc họp diễn ra đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8865, 38155, '演奏が終わると、大きな拍手が起こった。', 'えんそうが おわると、おおきな はくしゅが おこった。', 'Khi màn trình diễn kết thúc, tiếng vỗ tay vang lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8866, 38142, '国際化が進んで、外国人の社員が増えた。', 'こくさいかが すすんで、がいこくじんの しゃいんが ふえた。', 'Quốc tế hóa ngày càng mạnh, nhân viên người nước ngoài tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8867, 38163, '仕事を失って、生活保護を受けている。', 'しごとを うしなって、せいかつ ほごを うけて いる。', 'Mất việc nên anh ấy đang nhận trợ cấp xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8868, 38143, 'このイベントは市が主催している。', 'この イベントは しが しゅさい して いる。', 'Sự kiện này do thành phố chủ trì tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8869, 38145, '地元の企業がお祭りに協賛している。', 'じもとの きぎょうが おまつりに きょうさん して いる。', 'Các doanh nghiệp địa phương tài trợ cho lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8870, 38147, '主催者があいさつをした。', 'しゅさいしゃが あいさつを した。', 'Ban tổ chức phát biểu chào mừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8871, 38149, '友達の結婚式で司会をした。', 'ともだちの けっこんしきで しかいを した。', 'Tôi làm MC trong đám cưới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8872, 38152, '校長先生が卒業式で祝辞を述べた。', 'こうちょう せんせいが そつぎょうしきで しゅくじを のべた。', 'Thầy hiệu trưởng đọc lời chúc mừng trong lễ tốt nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8873, 38156, '発表のあと、質疑応答の時間があります。', 'はっぴょうの あと、しつぎ おうとうの じかんが あります。', 'Sau phần trình bày sẽ có thời gian hỏi đáp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8874, 38190, '日本の気候は地方によって違う。', 'にほんの きこうは ちほうに よって ちがう。', 'Khí hậu Nhật Bản khác nhau theo từng vùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8875, 38167, '所得が多い人ほど税金が高い。', 'しょとくが おおい ひと ほど ぜいきんが たかい。', 'Người thu nhập càng cao thì thuế càng nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8876, 38169, '市の財政が厳しくなっている。', 'しの ざいせいが きびしく なって いる。', 'Tài chính của thành phố đang trở nên khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8877, 38170, '住宅ローンの返済が終わった。', 'じゅうたく ローンの へんさいが おわった。', 'Tôi đã trả xong khoản vay mua nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8878, 46836, '夜更かしは健康に悪い影響を及ぼす。', 'よふかしは けんこうに わるい えいきょうを およぼす。', 'Thức khuya gây ảnh hưởng xấu đến sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8879, 46837, '事故防止のために、信号を新しくした。', 'じこ ぼうしの ために、しんごうを あたらしく した。', 'Để ngăn tai nạn, đèn tín hiệu đã được thay mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8880, 46841, '山の空気は澄んでいる。', 'やまの くうきは すんで いる。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8881, 46842, '大雨のあと、川の水が濁っている。', 'おおあめの あと、かわの みずが にごって いる。', 'Sau trận mưa lớn, nước sông bị đục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8882, 46844, 'どんな命も貴いものだ。', 'どんな いのちも とうとい ものだ。', 'Sinh mạng nào cũng quý giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8883, 46847, '彼の日本語は著しく上達した。', 'かれの にほんごは いちじるしく じょうたつ した。', 'Tiếng Nhật của anh ấy tiến bộ rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8884, 46927, '政府は子育てを支援する政策を発表した。', 'せいふは こそだてを しえん する せいさくを はっぴょう した。', 'Chính phủ công bố chính sách hỗ trợ nuôi dạy con cái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8885, 46928, '教育の改革が必要だと言われている。', 'きょういくの かいかくが ひつようだと いわれて いる。', 'Người ta cho rằng cần phải cải cách giáo dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8886, 46931, '新しい法律は来年四月から施行される。', 'あたらしい ほうりつは らいねん しがつから しこう される。', 'Luật mới sẽ được thi hành từ tháng tư năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8887, 38191, '外来種が生態系を壊している。', 'がいらいしゅが せいたいけいを こわして いる。', 'Các loài ngoại lai đang phá vỡ hệ sinh thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8888, 38172, '好きな俳優の映画を見に行った。', 'すきな はいゆうの えいがを みに いった。', 'Tôi đi xem phim của diễn viên mình thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8889, 38173, '監督の指示で選手が動いた。', 'かんとくの しじで せんしゅが うごいた。', 'Các cầu thủ di chuyển theo chỉ thị của huấn luyện viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8890, 38180, '彼女は初めて大きな舞台に立った。', 'かのじょは はじめて おおきな ぶたいに たった。', 'Lần đầu tiên cô ấy đứng trên sân khấu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8891, 38168, '納税は国民の義務だ。', 'のうぜいは こくみんの ぎむだ。', 'Nộp thuế là nghĩa vụ của công dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8892, 38166, '国と国の経済格差が広がっている。', 'くにと くにの けいざい かくさが ひろがって いる。', 'Chênh lệch kinh tế giữa các nước đang nới rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8893, 38171, '彼女の演技はとても自然だった。', 'かのじょの えんぎは とても しぜん だった。', 'Diễn xuất của cô ấy rất tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8894, 38175, '台本を何度も読んで、せりふを覚えた。', 'だいほんを なんども よんで、せりふを おぼえた。', 'Tôi đọc kịch bản nhiều lần để thuộc lời thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8895, 38177, 'サーカスの興行が町にやって来た。', 'サーカスの こうぎょうが まちに やって きた。', 'Đoàn xiếc đã về thị trấn biểu diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8896, 38181, '学校の劇で主役に選ばれた。', 'がっこうの げきで しゅやくに えらばれた。', 'Tôi được chọn đóng vai chính trong vở kịch của trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8897, 38184, 'この舞台は演出がすばらしい。', 'この ぶたいは えんしゅつが すばらしい。', 'Vở diễn này có phần dàn dựng tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8898, 38187, '彼の新しい曲が大ヒットした。', 'かれの あたらしい きょくが だいヒット した。', 'Ca khúc mới của anh ấy đã thành công vang dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8899, 44233, '山の空気はきれいです。', 'やまの くうきは きれい です。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8900, 46934, '多くの若者がその候補者を支持している。', 'おおくの わかものが その こうほしゃを しじ して いる。', 'Nhiều người trẻ ủng hộ ứng viên đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8901, 46937, '日本の学生と交流するイベントに参加した。', 'にほんの がくせいと こうりゅう する イベントに さんか した。', 'Tôi tham gia sự kiện giao lưu với sinh viên Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8902, 46940, '戦争で多くの人が難民になった。', 'せんそうで おおくの ひとが なんみんに なった。', 'Chiến tranh khiến nhiều người trở thành người tị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8903, 46946, '電力の自由化で、会社を選べるようになった。', 'でんりょくの じゆうかで、かいしゃを えらべる ように なった。', 'Nhờ tự do hóa ngành điện, giờ ta có thể chọn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8904, 46948, '多数の人がその案に賛成した。', 'たすうの ひとが その あんに さんせい した。', 'Đa số mọi người tán thành đề án đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8905, 46954, '二つの意見が対立している。', 'ふたつの いけんが たいりつ して いる。', 'Hai ý kiến đang đối lập nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8906, 46957, '両社は話し合いの末、合意に達した。', 'りょうしゃは はなしあいの すえ、ごういに たっした。', 'Sau khi bàn bạc, hai công ty đã đạt được đồng thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8907, 46958, '専門家の間でも見解が分かれている。', 'せんもんかの あいだでも けんかいが わかれて いる。', 'Ngay giữa các chuyên gia cũng có quan điểm khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8908, 46961, '先生は毎日たくさんの宿題を課す。', 'せんせいは まいにち たくさんの しゅくだいを かす。', 'Ngày nào thầy cũng giao nhiều bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8909, 46964, '館内での撮影は禁じられています。', 'かんないでの さつえいは きんじられて います。', 'Cấm chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8910, 44236, '天気予報によると、あしたは雨だそうです。', 'てんき よほうに よると、あしたは あめだ そう です。', 'Theo dự báo thời tiết thì ngày mai trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8911, 46966, '彼は不当な理由で解雇された。', 'かれは ふとうな りゆうで かいこ された。', 'Anh ấy bị sa thải vì lý do bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8912, 46968, '会場の入口は厳重に警備されている。', 'かいじょうの いりぐちは げんじゅうに けいび されて いる。', 'Lối vào hội trường được canh gác nghiêm ngặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8913, 46970, '新しいゲームを開発している。', 'あたらしい ゲームを かいはつ して いる。', 'Chúng tôi đang phát triển một trò chơi mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8914, 46973, '新しいカメラは性能がいい。', 'あたらしい カメラは せいのうが いい。', 'Chiếc máy ảnh mới có tính năng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8915, 38201, '豪雨で川があふれた。', 'ごううで かわが あふれた。', 'Mưa lớn khiến sông tràn bờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8916, 39488, 'この言葉はアクセントで意味が変わる。', 'この ことばは アクセントで いみが かわる。', 'Từ này đổi nghĩa theo trọng âm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8917, 39494, 'のりを火で軽く炙った。', 'のりを ひで かるく あぶった。', 'Tôi hơ nhẹ lá rong biển trên lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8918, 38195, 'アフリカでは砂漠化が進んでいる。', 'アフリカでは さばくかが すすんで いる。', 'Ở châu Phi tình trạng sa mạc hóa đang lan rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8919, 38197, '温暖化で氷河が小さくなっている。', 'おんだんかで ひょうがが ちいさく なって いる。', 'Sông băng đang thu nhỏ lại do trái đất nóng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8920, 38198, '北極の氷の融解が進んでいる。', 'ほっきょくの こおりの ゆうかいが すすんで いる。', 'Băng ở Bắc Cực đang tan chảy dần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8921, 38203, '今年の夏は酷暑が続いた。', 'ことしの なつは こくしょが つづいた。', 'Mùa hè năm nay nóng dữ dội kéo dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8922, 38205, 'ヨーロッパは熱波に襲われた。', 'ヨーロッパは ねっぱに おそわれた。', 'Châu Âu hứng chịu một đợt nắng nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8923, 39495, '大雨で川の水が溢れた。', 'おおあめで かわの みずが あふれた。', 'Mưa lớn làm nước sông tràn bờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8924, 39496, '映画の粗筋を簡単に教えてください。', 'えいがの あらすじを かんたんに おしえて ください。', 'Hãy kể tóm tắt nội dung bộ phim giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8925, 39497, '旅行の準備であれこれ忙しい。', 'りょこうの じゅんびで あれこれ いそがしい。', 'Tôi bận đủ thứ để chuẩn bị cho chuyến du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8926, 46974, 'このスマホにはたくさんの機能がある。', 'この スマホには たくさんの きのうが ある。', 'Chiếc điện thoại này có rất nhiều chức năng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8927, 46979, 'このシャツは自然の素材で作られている。', 'この シャツは しぜんの そざいで つくられて いる。', 'Chiếc áo này làm từ chất liệu tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8928, 46981, '燃料の値段が上がって、運賃も高くなった。', 'ねんりょうの ねだんが あがって、うんちんも たかく なった。', 'Giá nhiên liệu tăng nên giá vé cũng đắt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8929, 46983, 'ここは電波が弱くて、電話がつながらない。', 'ここは でんぱが よわくて、でんわが つながらない。', 'Ở đây sóng yếu nên không gọi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8930, 46988, '学校で体力を測定した。', 'がっこうで たいりょくを そくてい した。', 'Ở trường chúng tôi đã đo thể lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8931, 46990, '実験で仮説が正しいことが証明された。', 'じっけんで かせつが ただしい ことが しょうめい された。', 'Thí nghiệm đã chứng minh giả thuyết là đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8932, 46991, '理論はわかっても、実際にやるのは難しい。', 'りろんは わかっても、じっさいに やるのは むずかしい。', 'Hiểu lý thuyết rồi nhưng làm thực tế thì khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8933, 46994, 'この薬の成分を確認してください。', 'この くすりの せいぶんを かくにん して ください。', 'Hãy kiểm tra thành phần của thuốc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8934, 46995, '人の体は多くの細胞でできている。', 'ひとの からだは おおくの さいぼうで できて いる。', 'Cơ thể người được tạo nên từ vô số tế bào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8935, 46996, '背の高さは遺伝によるところが大きい。', 'せの たかさは いでんに よる ところが おおきい。', 'Chiều cao phần lớn là do di truyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8936, 46999, '医者にインフルエンザだと診断された。', 'いしゃに インフルエンザだと しんだん された。', 'Tôi được bác sĩ chẩn đoán là bị cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8937, 47004, 'インフルエンザの予防注射を受けた。', 'インフルエンザの よぼう ちゅうしゃを うけた。', 'Tôi đã tiêm phòng cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8938, 47012, 'スマホが普及して、生活が大きく変わった。', 'スマホが ふきゅう して、せいかつが おおきく かわった。', 'Điện thoại thông minh phổ biến khiến cuộc sống thay đổi lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9051, 39677, '娘はピンクの服が好きだ。', 'むすめは ピンクの ふくが すきだ。', 'Con gái tôi thích quần áo màu hồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8939, 47013, '会社に新しいシステムを導入した。', 'かいしゃに あたらしい システムを どうにゅう した。', 'Công ty đã đưa hệ thống mới vào áp dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8940, 47017, 'これは画期的な発明だ。', 'これは かっきてきな はつめいだ。', 'Đây là một phát minh mang tính đột phá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8941, 39516, '姉はおしゃれで、服をたくさん持っている。', 'あねは おしゃれで、ふくを たくさん もって いる。', 'Chị tôi sành điệu, có rất nhiều quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8942, 39529, 'この先に急なカーブがあります。', 'この さきに きゅうな カーブが あります。', 'Phía trước có khúc cua gấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8943, 39498, '朝はいつもあわただしい。', 'あさは いつも あわただしい。', 'Buổi sáng lúc nào cũng vội vã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8944, 39526, 'お正月に家族で神社にお参りした。', 'おしょうがつに かぞくで じんじゃに おまいり した。', 'Dịp Tết cả nhà đi lễ đền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8945, 39504, 'うっかり傘を電車に忘れてしまった。', 'うっかり かさを でんしゃに わすれて しまった。', 'Tôi lơ đễnh để quên ô trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8946, 39507, '今日はうんと遊ぼう。', 'きょうは うんと あそぼう。', 'Hôm nay chơi thỏa thích nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8947, 39514, 'お先に失礼します。', 'おさきに しつれい します。', 'Tôi xin phép về trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8948, 39517, '風邪ですか。どうぞおだいじに。', 'かぜ ですか。どうぞ おだいじに。', 'Bị cảm à? Mong bạn mau khỏe nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8949, 39519, 'コーヒーを一つ、おねがいします。', 'コーヒーを ひとつ、おねがい します。', 'Cho tôi một ly cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8950, 39521, '少々おまちください。', 'しょうしょう おまち ください。', 'Xin vui lòng chờ một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8951, 39525, 'お帰り。今日はどうだった?', 'おかえり。きょうは どう だった?', 'Con về rồi à. Hôm nay thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8952, 47019, '台風に備えて、窓を閉めておいた。', 'たいふうに そなえて、まどを しめて おいた。', 'Để phòng bão, tôi đã đóng cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8953, 47021, '部屋にエアコンを取り付けてもらった。', 'へやに エアコンを とりつけて もらった。', 'Tôi nhờ người lắp điều hòa cho phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8954, 47023, '間違えて大事なファイルを削除してしまった。', 'まちがえて だいじな ファイルを さくじょ して しまった。', 'Tôi lỡ xóa nhầm một tệp quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8955, 47026, 'この絵は有名な作品の複製だ。', 'この えは ゆうめいな さくひんの ふくせいだ。', 'Bức tranh này là bản sao của một tác phẩm nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8956, 47028, '十分たつと、画面は自動的に暗くなる。', 'じゅっぷん たつと、がめんは じどうてきに くらく なる。', 'Sau mười phút, màn hình tự động tối đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8957, 47030, '美術館で有名な画家の作品を見た。', 'びじゅつかんで ゆうめいな がかの さくひんを みた。', 'Tôi xem tác phẩm của họa sĩ nổi tiếng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8958, 47034, '好きな俳優の映画を見に行った。', 'すきな はいゆうの えいがを みに いった。', 'Tôi đi xem phim của diễn viên mình thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8959, 47035, '監督の指示で選手が動いた。', 'かんとくの しじで せんしゅが うごいた。', 'Các cầu thủ di chuyển theo chỉ thị của huấn luyện viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8960, 44267, '急に雨が降り出しました。', 'きゅうに あめが ふりだしました。', 'Trời đột nhiên đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8961, 47037, '劇団の公演は来週から始まる。', 'げきだんの こうえんは らいしゅうから はじまる。', 'Buổi biểu diễn của đoàn kịch bắt đầu từ tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8962, 47041, '宗教によって食べられない物がある。', 'しゅうきょうに よって たべられない ものが ある。', 'Tùy tôn giáo mà có những thứ không được ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8963, 47044, 'この辺りから古代の遺跡が見つかった。', 'この あたりから こだいの いせきが みつかった。', 'Người ta đã tìm thấy di tích cổ đại quanh đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8964, 47045, 'このお寺は重要な文化財に指定されている。', 'この おてらは じゅうような ぶんかざいに してい されて いる。', 'Ngôi chùa này được công nhận là di sản văn hóa quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8965, 47048, 'この作家の随筆はやさしい言葉で書かれている。', 'この さっかの ずいひつは やさしい ことばで かかれて いる。', 'Tùy bút của nhà văn này được viết bằng lời lẽ giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8966, 47052, 'この雑誌は若い読者に人気がある。', 'この ざっしは わかい どくしゃに にんきが ある。', 'Tạp chí này được độc giả trẻ yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8967, 47054, 'その試合はテレビで生放送された。', 'その しあいは テレビで なま ほうそう された。', 'Trận đấu đó được truyền hình trực tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8968, 47055, '新聞の番組表で今夜の映画を探した。', 'しんぶんの ばんぐみひょうで こんやの えいがを さがした。', 'Tôi xem lịch chương trình trên báo để tìm phim tối nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8969, 47063, '今年はこの色の服が流行している。', 'ことしは この いろの ふくが りゅうこう して いる。', 'Năm nay quần áo màu này đang thịnh hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8970, 47064, 'このラーメン屋はいつも人気で、行列ができている。', 'この ラーメンやは いつも にんきで、ぎょうれつが できて いる。', 'Quán ramen này lúc nào cũng đông khách, người xếp hàng dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8971, 47068, '子供には創造する力がある。', 'こどもには そうぞう する ちからが ある。', 'Trẻ em có khả năng sáng tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8972, 47071, '演奏が終わると、大きな拍手が起こった。', 'えんそうが おわると、おおきな はくしゅが おこった。', 'Khi màn trình diễn kết thúc, tiếng vỗ tay vang lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8973, 39536, '弟をからかって、泣かせてしまった。', 'おとうとを からかって、なかせて しまった。', 'Tôi trêu em trai đến mức làm nó khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8974, 39548, 'ご飯粒が服にくっついている。', 'ごはんつぶが ふくに くっついて いる。', 'Hạt cơm dính trên áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8976, 39550, '同じ話を何度もして、くどいね。', 'おなじ はなしを なんども して、くどいね。', 'Nói đi nói lại một chuyện, dài dòng quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8977, 47073, 'この物語の主人公は十歳の少女だ。', 'この ものがたりの しゅじんこうは じゅっさいの しょうじょだ。', 'Nhân vật chính của câu chuyện là một cô bé mười tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8978, 47077, '彼は映画で医者の役を演じた。', 'かれは えいがで いしゃの やくを えんじた。', 'Anh ấy đóng vai bác sĩ trong phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8979, 47079, '彼は日本の歴史について本を著した。', 'かれは にほんの れきしに ついて ほんを あらわした。', 'Ông ấy đã viết sách về lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8980, 47081, 'この村には古い伝説が伝わっている。', 'この むらには ふるい でんせつが つたわって いる。', 'Ngôi làng này lưu truyền một truyền thuyết cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8981, 47085, '白鳥が優雅に泳いでいる。', 'はくちょうが ゆうがに およいで いる。', 'Những chú thiên nga đang bơi một cách tao nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8982, 47086, '彼女はいつも地味な色の服を着ている。', 'かのじょは いつも じみな いろの ふくを きて いる。', 'Cô ấy lúc nào cũng mặc đồ màu giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8983, 47088, '彼は難しい技を見事に成功させた。', 'かれは むずかしい わざを みごとに せいこう させた。', 'Anh ấy thực hiện thành công một kỹ thuật khó một cách xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8984, 47090, '四月に人事の発表がある。', 'しがつに じんじの はっぴょうが ある。', 'Tháng tư sẽ có công bố nhân sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8985, 47092, '姉は派遣社員として働いている。', 'あねは はけん しゃいんと して はたらいて いる。', 'Chị tôi làm việc với tư cách nhân viên phái cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8986, 47093, 'アルバイトから正社員になった。', 'アルバイトから せいしゃいんに なった。', 'Tôi từ nhân viên làm thêm trở thành nhân viên chính thức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8987, 47096, '勤め先の住所を書いてください。', 'つとめさきの じゅうしょを かいて ください。', 'Hãy ghi địa chỉ nơi làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8988, 47099, '午後、お客様と打ち合わせがある。', 'ごご、おきゃくさまと うちあわせが ある。', 'Chiều nay tôi có buổi họp bàn với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8989, 47102, '会議の議事録を作成してください。', 'かいぎの ぎじろくを さくせい して ください。', 'Hãy lập biên bản cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8990, 47104, '会議は予定どおりに進行した。', 'かいぎは よてい どおりに しんこう した。', 'Cuộc họp diễn ra đúng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8991, 47106, '今学期の評定は「優」だった。', 'こんがっきの ひょうていは 「ゆう」 だった。', 'Xếp loại học kỳ này của tôi là "Giỏi".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8992, 39597, '列に割り込むなんて、ずうずうしい人だ。', 'れつに わりこむ なんて、ずうずうしい ひとだ。', 'Chen ngang hàng như thế, đúng là người mặt dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8993, 39588, '彼女は戦場で取材するジャーナリストだ。', 'かのじょは せんじょうで しゅざい する ジャーナリストだ。', 'Cô ấy là nhà báo tác nghiệp ở chiến trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8994, 39603, 'この梅干しはとてもすっぱい。', 'この うめぼしは とても すっぱい。', 'Quả mơ muối này rất chua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8995, 39586, '風船が一晩でしぼんでしまった。', 'ふうせんが ひとばんで しぼんで しまった。', 'Quả bóng bay xẹp hết chỉ sau một đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8996, 39589, '子供は道にしゃがんで花を見ている。', 'こどもは みちに しゃがんで はなを みて いる。', 'Đứa trẻ ngồi xổm bên đường ngắm hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8997, 39593, 'じゃんけんで順番を決めよう。', 'じゃんけんで じゅんばんを きめよう。', 'Oẳn tù tì để quyết định thứ tự nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8998, 44283, '入学のお祝いに時計をもらいました。', 'にゅうがくの おいわいに とけいを もらいました。', 'Tôi được tặng đồng hồ làm quà mừng nhập học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (8999, 39602, '部屋を片付けたら、すっきりした。', 'へやを かたづけたら、すっきり した。', 'Dọn phòng xong thấy gọn gàng hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9000, 39613, 'ぜひとも参加していただきたい。', 'ぜひとも さんか して いただきたい。', 'Rất mong anh nhất định tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9001, 39620, '大雪が降った。そのため、電車が止まった。', 'おおゆきが ふった。その ため、でんしゃが とまった。', 'Tuyết rơi dày. Vì thế tàu điện ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9002, 39631, '服装がだらしないと、印象が悪い。', 'ふくそうが だらしないと、いんしょうが わるい。', 'Ăn mặc luộm thuộm thì gây ấn tượng xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9003, 39642, '発表の前は胸がどきどきする。', 'はっぴょうの まえは むねが どきどき する。', 'Trước khi thuyết trình tim tôi đập thình thịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9004, 47108, '先輩の助言のおかげで、うまくいった。', 'せんぱいの じょげんの おかげで、うまく いった。', 'Nhờ lời khuyên của đàn anh mà mọi việc suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9005, 47112, '会社は記者会見で謝罪した。', 'かいしゃは きしゃかいけんで しゃざい した。', 'Công ty đã tạ lỗi trong buổi họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9006, 47115, 'お客様には敬語を使いましょう。', 'おきゃくさまには けいごを つかいましょう。', 'Hãy dùng kính ngữ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9007, 47116, 'チームで働くには協調性が必要だ。', 'チームで はたらくには きょうちょうせいが ひつようだ。', 'Làm việc nhóm cần tính hòa đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9008, 47119, '新入社員の歓迎会を開いた。', 'しんにゅう しゃいんの かんげいかいを ひらいた。', 'Chúng tôi tổ chức tiệc chào mừng nhân viên mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9009, 47121, '彼女は周りへの気配りができる人だ。', 'かのじょは まわりへの きくばりが できる ひとだ。', 'Cô ấy là người chu đáo với mọi người xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9010, 47123, '彼女は遠回しに誘いを断った。', 'かのじょは とおまわしに さそいを ことわった。', 'Cô ấy từ chối lời mời một cách vòng vo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9925, 29400, '彼に謝ったほうがいいですよ。', 'かれに あやまった ほうが いい ですよ。', 'Bạn nên xin lỗi anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9011, 47124, '率直な意見を聞かせてください。', 'そっちょくな いけんを きかせて ください。', 'Hãy cho tôi nghe ý kiến thẳng thắn của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9012, 47126, '父は几帳面で、いつも時間を守る。', 'ちちは きちょうめんで、いつも じかんを まもる。', 'Bố tôi rất tỉ mỉ, lúc nào cũng đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9013, 47128, '成功しても謙虚な気持ちを忘れない。', 'せいこう しても けんきょな きもちを わすれない。', 'Dù thành công cũng không quên giữ lòng khiêm tốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9014, 47130, '悩みを親友に打ち明けた。', 'なやみを しんゆうに うちあけた。', 'Tôi đã thổ lộ nỗi lòng với bạn thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9015, 39630, '彼女に話しかけるのをためらった。', 'かのじょに はなしかけるのを ためらった。', 'Tôi chần chừ không dám bắt chuyện với cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9016, 39634, '先生はチョークで黒板に図を描いた。', 'せんせいは チョークで こくばんに ずを かいた。', 'Thầy giáo dùng phấn vẽ sơ đồ lên bảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9017, 39653, 'いすのねじがゆるんでいる。', 'いすの ねじが ゆるんで いる。', 'Con ốc của chiếc ghế bị lỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9018, 39655, 'のこぎりで板を切った。', 'のこぎりで いたを きった。', 'Tôi cưa tấm ván.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9019, 39632, 'パンをちぎって鳥にあげた。', 'パンを ちぎって とりに あげた。', 'Tôi xé bánh mì cho chim ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9020, 39649, 'けんかで人を殴ってはいけない。', 'けんかで ひとを なぐっては いけない。', 'Không được đánh người khi cãi nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9021, 39657, 'こんなことで悩むのはばからしい。', 'こんな ことで なやむのは ばからしい。', 'Phiền muộn vì chuyện này thật ngớ ngẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9022, 39640, 'この曲はテンポが速い。', 'この きょくは テンポが はやい。', 'Bản nhạc này có nhịp độ nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9023, 39626, '新商品はたちまち売り切れた。', 'しんしょうひんは たちまち うりきれた。', 'Sản phẩm mới bán hết veo trong chốc lát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9024, 39643, '宿題はとっくに終わったよ。', 'しゅくだいは とっくに おわったよ。', 'Bài tập thì xong từ lâu rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9025, 39646, '結果はともかく、最後まで頑張ろう。', 'けっかは ともかく、さいごまで がんばろう。', 'Kết quả thế nào cũng được, hãy cố gắng đến cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9026, 39651, '彼の気持ちはなんとも言えない。', 'かれの きもちは なんとも いえない。', 'Tâm trạng anh ấy thì chẳng thể nói được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9027, 39658, '彼女ははきはきと答えた。', 'かのじょは はきはきと こたえた。', 'Cô ấy trả lời rành mạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9028, 44337, '病院で注射をしてもらいました。', 'びょういんで ちゅうしゃを して もらいました。', 'Tôi được tiêm ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9029, 47131, '遅刻の言い訳はもう聞きたくない。', 'ちこくの いいわけは もう ききたく ない。', 'Tôi không muốn nghe lời bào chữa cho việc đi muộn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9030, 47133, '雨のため、今日の出発は見送ることにした。', 'あめの ため、きょうの しゅっぱつは みおくる ことに した。', 'Vì mưa, chúng tôi quyết định hoãn chuyến đi hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9031, 47136, '前の担当者から仕事を引き継いだ。', 'まえの たんとうしゃから しごとを ひきついだ。', 'Tôi tiếp quản công việc từ người phụ trách trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9032, 47138, '試合に負けた友達を励ました。', 'しあいに まけた ともだちを はげました。', 'Tôi động viên người bạn vừa thua trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9033, 47140, '自分ばかり責めないでください。', 'じぶん ばかり せめないで ください。', 'Đừng chỉ tự trách bản thân như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9034, 47142, '困ったときは、いつでも頼ってください。', 'こまった ときは、いつでも たよって ください。', 'Khi khó khăn, cứ dựa vào tôi bất cứ lúc nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9035, 47143, '練習を怠けると、すぐ下手になる。', 'れんしゅうを なまけると、すぐ へたに なる。', 'Lười luyện tập là sẽ kém đi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9036, 47145, 'けんかした後、気まずい雰囲気になった。', 'けんか した あと、きまずい ふんいきに なった。', 'Sau khi cãi nhau, bầu không khí trở nên khó xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9037, 47147, '問題は円満に解決した。', 'もんだいは えんまんに かいけつ した。', 'Vấn đề đã được giải quyết êm đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9038, 47154, '戦争で町が破壊された。', 'せんそうで まちが はかい された。', 'Thị trấn bị chiến tranh phá hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9039, 47156, '木は二酸化炭素を吸収する。', 'きは にさんかたんそを きゅうしゅう する。', 'Cây xanh hấp thụ khí CO2.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9040, 47157, '車の排気ガスで空気が汚れている。', 'くるまの はいき ガスで くうきが よごれて いる。', 'Khí thải xe cộ làm bẩn không khí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9041, 47160, 'この川の水質は年々よくなっている。', 'この かわの すいしつは ねんねん よく なって いる。', 'Chất lượng nước sông này ngày càng tốt lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9042, 39670, '警官はピストルを持っている。', 'けいかんは ピストルを もって いる。', 'Cảnh sát mang theo súng lục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9043, 39666, '子供のパンツを買った。', 'こどもの パンツを かった。', 'Tôi mua quần lót cho con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9044, 39685, 'ブラシで靴の泥を落とした。', 'ブラシで くつの どろを おとした。', 'Tôi dùng bàn chải chải sạch bùn trên giày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9045, 39690, 'コートに花のブローチをつけた。', 'コートに はなの ブローチを つけた。', 'Tôi cài chiếc trâm hình hoa lên áo khoác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9046, 39682, 'フライパンで卵を焼いた。', 'フライパンで たまごを やいた。', 'Tôi rán trứng bằng chảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9047, 39687, 'プラットホームで電車を待っている。', 'プラットホームで でんしゃを まって いる。', 'Tôi đang chờ tàu trên sân ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9048, 39664, '寒いので手袋をはめた。', 'さむいので てぶくろを はめた。', 'Lạnh quá nên tôi đeo găng tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9049, 39680, 'ドアに頭をぶつけた。', 'ドアに あたまを ぶつけた。', 'Tôi bị đập đầu vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9052, 39691, 'コンサートのプログラムをもらった。', 'コンサートの プログラムを もらった。', 'Tôi nhận được tờ chương trình buổi hòa nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9053, 39662, '車をバックさせて、駐車した。', 'くるまを バック させて、ちゅうしゃ した。', 'Tôi lùi xe để đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9054, 39660, 'はじめまして。リンと申します。', 'はじめまして。リンと もうします。', 'Rất vui được gặp anh. Tôi tên là Linh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9055, 44350, '体の具合はどうですか。', 'からだの ぐあいは どう ですか。', 'Sức khỏe của bạn thế nào rồi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9056, 47164, '森林の伐採が問題になっている。', 'しんりんの ばっさいが もんだいに なって いる。', 'Việc chặt phá rừng đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9057, 47166, '豪雨で川があふれた。', 'ごううで かわが あふれた。', 'Mưa lớn khiến sông tràn bờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9058, 47167, '地震のあとは津波に注意してください。', 'じしんの あとは つなみに ちゅうい して ください。', 'Sau động đất hãy cảnh giác với sóng thần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9059, 47169, '大雨で土砂崩れが起き、道が通れなくなった。', 'おおあめで どしゃくずれが おき、みちが とおれなく なった。', 'Mưa lớn gây lở đất khiến đường không đi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9060, 47170, '最近、世界中で異常気象が続いている。', 'さいきん、せかいじゅうで いじょう きしょうが つづいて いる。', 'Gần đây thời tiết bất thường liên tục xảy ra trên khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9061, 47175, '省エネのエアコンに買い替えた。', 'しょうエネの エアコンに かいかえた。', 'Tôi đã đổi sang điều hòa tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9062, 47177, '海の近くに風力発電所ができた。', 'うみの ちかくに ふうりょく はつでんしょが できた。', 'Một nhà máy điện gió đã được xây gần biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9063, 47178, '原子力発電について議論が続いている。', 'げんしりょく はつでんに ついて ぎろんが つづいて いる。', 'Tranh luận về điện hạt nhân vẫn tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9064, 47180, 'この川の水を使って発電している。', 'この かわの みずを つかって はつでん して いる。', 'Người ta dùng nước sông này để phát điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9065, 47184, 'ベランダでトマトを栽培している。', 'ベランダで トマトを さいばい して いる。', 'Tôi trồng cà chua ở ban công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9066, 47186, '環境保護のために、マイバッグを使っている。', 'かんきょう ほごの ために、マイバッグを つかって いる。', 'Để bảo vệ môi trường, tôi dùng túi cá nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9067, 47188, '彼の発言は影響力が大きい。', 'かれの はつげんは えいきょうりょくが おおきい。', 'Phát ngôn của ông ấy có sức ảnh hưởng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9068, 47191, '市は駅前の緑化を進めている。', 'しは えきまえの りょっかを すすめて いる。', 'Thành phố đang đẩy mạnh phủ xanh khu trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9069, 47194, '努力がやっと実った。', 'どりょくが やっと みのった。', 'Nỗ lực cuối cùng đã đơm hoa kết trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9070, 47195, '冬に備えて食料を蓄えた。', 'ふゆに そなえて しょくりょうを たくわえた。', 'Chúng tôi dự trữ lương thực cho mùa đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9071, 47197, '事故防止のために、信号を新しくした。', 'じこ ぼうしの ために、しんごうを あたらしく した。', 'Để ngăn tai nạn, đèn tín hiệu đã được thay mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9072, 47200, 'この洗剤は汚れがよく落ちる。', 'この せんざいは よごれが よく おちる。', 'Loại bột giặt này tẩy vết bẩn rất tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9073, 47202, '大雨のあと、川の水が濁っている。', 'おおあめの あと、かわの みずが にごって いる。', 'Sau trận mưa lớn, nước sông bị đục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9074, 47204, 'どんな命も貴いものだ。', 'どんな いのちも とうとい ものだ。', 'Sinh mạng nào cũng quý giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9075, 39709, '電車の中で化粧するのはみっともない。', 'でんしゃの なかで けしょう するのは みっともない。', 'Trang điểm trên tàu thật khó coi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9076, 39720, 'まだ使えるのに捨てるのはもったいない。', 'まだ つかえるのに すてるのは もったいない。', 'Còn dùng được mà vứt đi thì phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9077, 39703, '水たまりをまたいで歩いた。', 'みずたまりを またいで あるいた。', 'Tôi bước qua vũng nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9078, 39704, '日差しがまぶしくて、目を細めた。', 'ひざしが まぶしくて、めを ほそめた。', 'Nắng chói quá nên tôi nheo mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9079, 39699, 'テストの結果はまあまあだった。', 'テストの けっかは まあまあ だった。', 'Kết quả bài kiểm tra cũng tàm tạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9080, 39712, '朝晩がめっきり寒くなった。', 'あさばんが めっきり さむく なった。', 'Sáng tối đã lạnh hẳn đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9081, 47206, '人手不足が深刻化している。', 'ひとで ぶそくが しんこくか して いる。', 'Tình trạng thiếu nhân lực đang trở nên nghiêm trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9082, 47726, '被災地の支援のために、ボランティアに行った。', 'ひさいちの しえんの ために、ボランティアに いった。', 'Tôi đi tình nguyện để hỗ trợ vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9083, 48086, '被災地の支援のために、ボランティアに行った。', 'ひさいちの しえんの ために、ボランティアに いった。', 'Tôi đi tình nguyện để hỗ trợ vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9084, 31651, '各国が協調して問題に取り組んでいる。', 'かっこくが きょうちょう して もんだいに とりくんで いる。', 'Các nước đang phối hợp để giải quyết vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9085, 31654, 'クラス全員が団結して、合唱コンクールで優勝した。', 'クラス ぜんいんが だんけつ して、がっしょう コンクールで ゆうしょう した。', 'Cả lớp đoàn kết và đã vô địch cuộc thi hợp xướng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9086, 31659, '交流を通して相互理解を深めたい。', 'こうりゅうを とおして そうご りかいを ふかめたい。', 'Tôi muốn qua giao lưu để hiểu nhau sâu sắc hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10104, 39688, '彼女はフリーのカメラマンだ。', 'かのじょは フリーの カメラマンだ。', 'Cô ấy là nhiếp ảnh gia tự do.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9087, 31635, '被災地の支援のために、ボランティアに行った。', 'ひさいちの しえんの ために、ボランティアに いった。', 'Tôi đi tình nguyện để hỗ trợ vùng bị thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9088, 37822, '持続可能な社会を作ることが目標だ。', 'じぞく かのうな しゃかいを つくる ことが もくひょうだ。', 'Mục tiêu là xây dựng một xã hội bền vững.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9089, 38178, 'スタジアムは観客でいっぱいだった。', 'スタジアムは かんきゃくで いっぱい だった。', 'Sân vận động chật kín khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9090, 38186, '今、この映画が話題になっている。', 'いま、この えいがが わだいに なって いる。', 'Hiện bộ phim này đang được bàn tán sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9091, 38199, '最近、世界中で異常気象が続いている。', 'さいきん、せかいじゅうで いじょう きしょうが つづいて いる。', 'Gần đây thời tiết bất thường liên tục xảy ra trên khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9092, 38200, '干ばつで米が育たなかった。', 'かんばつで こめが そだたなかった。', 'Do hạn hán, lúa không phát triển được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9093, 39527, 'その家にはお手伝いさんが二人いる。', 'その いえには おてつだいさんが ふたり いる。', 'Nhà đó có hai người giúp việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9094, 39628, '電話で騙されて、お金を払ってしまった。', 'でんわで だまされて、おかねを はらって しまった。', 'Tôi bị lừa qua điện thoại và đã trả tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9095, 39752, '衣食住に困らない生活がしたい。', 'いしょくじゅうに こまらない せいかつが したい。', 'Tôi muốn một cuộc sống không phải lo ăn mặc ở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9096, 39751, '北海道は東京より緯度が高い。', 'ほっかいどうは とうきょうより いどが たかい。', 'Hokkaido nằm ở vĩ độ cao hơn Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9097, 39750, '事務所が駅の近くに移転した。', 'じむしょが えきの ちかくに いてん した。', 'Văn phòng đã chuyển đến gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9098, 39753, '一応、傘を持っていこう。', 'いちおう、かさを もって いこう。', 'Cứ mang theo ô cho chắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9099, 44389, '大学で社会について勉強しています。', 'だいがくで しゃかいに ついて べんきょう して います。', 'Tôi đang học về xã hội ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9100, 44420, '大学で法律を勉強しています。', 'だいがくで ほうりつを べんきょう して います。', 'Tôi đang học luật ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9101, 44506, '今ちょうど十二時です。', 'いま ちょうど じゅうにじ です。', 'Bây giờ vừa đúng mười hai giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9102, 44510, '日本の歴史に興味があります。', 'にほんの れきしに きょうみが あります。', 'Tôi quan tâm đến lịch sử Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9103, 44592, 'ゆうべ近所で火事がありました。', 'ゆうべ きんじょで かじが ありました。', 'Tối qua gần nhà xảy ra hỏa hoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9104, 44595, '部屋の温度を少し上げてください。', 'へやの おんどを すこし あげて ください。', 'Hãy tăng nhiệt độ phòng lên một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9105, 44596, '天気予報によると、あしたは雨だそうです。', 'てんき よほうに よると、あしたは あめだ そう です。', 'Theo dự báo thời tiết thì ngày mai trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9106, 44627, '急に雨が降り出しました。', 'きゅうに あめが ふりだしました。', 'Trời đột nhiên đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9107, 39791, 'お客様を応接室にご案内した。', 'おきゃくさまを おうせつしつに ごあんない した。', 'Tôi dẫn khách vào phòng tiếp khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9108, 31016, '彼は任務を最後まで遂行した。', 'かれは にんむを さいごまで すいこう した。', 'Anh ấy đã thực hiện nhiệm vụ đến cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9109, 39647, '毎朝ジムでトレーニングしている。', 'まいあさ ジムで トレーニング して いる。', 'Sáng nào tôi cũng tập ở phòng gym.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9110, 39730, '毎晩、公園でランニングしている。', 'まいばん、こうえんで ランニング して いる。', 'Tối nào tôi cũng chạy bộ ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9111, 37808, '彼は仕事への意欲が高い。', 'かれは しごとへの いよくが たかい。', 'Anh ấy rất nhiệt huyết với công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9112, 37809, '語学の勉強には根気が必要だ。', 'ごがくの べんきょうには こんきが ひつようだ。', 'Học ngoại ngữ cần sự kiên nhẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9113, 39566, '涙をこらえて、最後まで話した。', 'なみだを こらえて、さいごまで はなした。', 'Tôi cố kìm nước mắt và nói đến cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9114, 39746, '先輩だからといって、威張らないでほしい。', 'せんぱい だからと いって、いばらないで ほしい。', 'Dù là đàn anh cũng đừng ra oai như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9115, 39839, 'あのとき謝らなかったことを今でも悔やんでいる。', 'あの とき あやまらなかった ことを いまでも くやんで いる。', 'Đến giờ tôi vẫn hối hận vì lúc đó đã không xin lỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9116, 39918, '彼は強気な態度で交渉に臨んだ。', 'かれは つよきな たいどで こうしょうに のぞんだ。', 'Anh ấy bước vào đàm phán với thái độ cứng rắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9117, 43215, '彼女はいつも朗らかで、周りを明るくする。', 'かのじょは いつも ほがらかで、まわりを あかるく する。', 'Cô ấy lúc nào cũng vui vẻ, làm sáng bừng xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9118, 31571, '住民との合意形成には時間がかかる。', 'じゅうみんとの ごうい けいせいには じかんが かかる。', 'Đạt được đồng thuận với người dân cần nhiều thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9119, 39829, 'ニュースの解説を聞いて、やっと理解できた。', 'ニュースの かいせつを きいて、やっと りかい できた。', 'Nghe bình luận tin tức xong tôi mới hiểu được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9120, 42926, '証拠がないので、犯人だと断定できない。', 'しょうこが ないので、はんにんだと だんてい できない。', 'Không có bằng chứng nên không thể khẳng định là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9121, 31572, '会議の日程を調整している。', 'かいぎの にっていを ちょうせい して いる。', 'Tôi đang điều chỉnh lịch họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9122, 31604, 'プロジェクトの進捗を報告してください。', 'プロジェクトの しんちょくを ほうこく して ください。', 'Hãy báo cáo tiến độ dự án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9123, 31613, '書類を精査してから返事します。', 'しょるいを せいさ してから へんじ します。', 'Tôi sẽ rà soát kỹ giấy tờ rồi trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9124, 31616, 'このマンションは管理がしっかりしている。', 'この マンションは かんりが しっかり して いる。', 'Chung cư này được quản lý chu đáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9125, 31617, '新しいシステムの運用が始まった。', 'あたらしい システムの うんようが はじまった。', 'Hệ thống mới đã bắt đầu được vận hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9126, 31619, 'この国では報道が統制されている。', 'この くにでは ほうどうが とうせい されて いる。', 'Ở nước này báo chí bị kiểm soát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9127, 31634, '責任分担をはっきり決めておこう。', 'せきにん ぶんたんを はっきり きめて おこう。', 'Hãy quy định rõ việc phân chia trách nhiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9128, 39953, '地域の人との繋がりを大切にしている。', 'ちいきの ひととの つながりを たいせつに して いる。', 'Tôi trân trọng mối liên kết với người trong khu phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9129, 39795, '王女は国民にとても愛されている。', 'おうじょは こくみんに とても あいされて いる。', 'Công chúa rất được người dân yêu mến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9130, 39770, '友達の頼みを引き受けた。', 'ともだちの たのみを ひきうけた。', 'Tôi nhận lời nhờ của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9131, 39808, 'そんな下品な言葉を使わないで。', 'そんな げひんな ことばを つかわないで。', 'Đừng dùng những lời thô tục như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9132, 39949, 'お年寄りを敬う気持ちを忘れてはいけない。', 'おとしよりを うやまう きもちを わすれては いけない。', 'Không được quên lòng kính trọng người già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9133, 31588, '人手不足を解決する方策を考えよう。', 'ひとで ぶそくを かいけつ する ほうさくを かんがえよう。', 'Hãy nghĩ biện pháp giải quyết tình trạng thiếu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9134, 47953, '子供の発想はおもしろい。', 'こどもの はっそうは おもしろい。', 'Cách nghĩ của trẻ con rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9135, 47219, 'ご提案については、社内で検討いたします。', 'ごていあんに ついては、しゃないで けんとう いたします。', 'Về đề xuất của quý vị, chúng tôi sẽ xem xét trong công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9136, 47239, '証拠がないので、犯人だと断定できない。', 'しょうこが ないので、はんにんだと だんてい できない。', 'Không có bằng chứng nên không thể khẳng định là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9137, 47272, '人手不足を解決する方策を考えよう。', 'ひとで ぶそくを かいけつ する ほうさくを かんがえよう。', 'Hãy nghĩ biện pháp giải quyết tình trạng thiếu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9138, 47278, '日本の会社と海外の会社が提携した。', 'にほんの かいしゃと かいがいの かいしゃが ていけい した。', 'Một công ty Nhật và một công ty nước ngoài đã liên kết với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9139, 47408, '彼は「まだまだです」と謙遜した。', 'かれは 「まだまだ です」と けんそん した。', 'Anh ấy khiêm tốn nói "tôi còn kém lắm".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9140, 47411, '彼は大胆な計画を発表した。', 'かれは だいたんな けいかくを はっぴょう した。', 'Anh ấy công bố một kế hoạch táo bạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9141, 47593, '子供の発想はおもしろい。', 'こどもの はっそうは おもしろい。', 'Cách nghĩ của trẻ con rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9142, 47599, '証拠がないので、犯人だと断定できない。', 'しょうこが ないので、はんにんだと だんてい できない。', 'Không có bằng chứng nên không thể khẳng định là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9143, 47632, '人手不足を解決する方策を考えよう。', 'ひとで ぶそくを かいけつ する ほうさくを かんがえよう。', 'Hãy nghĩ biện pháp giải quyết tình trạng thiếu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9144, 47769, '成功してから、彼は傲慢になった。', 'せいこう してから、かれは ごうまんに なった。', 'Từ khi thành công, anh ta trở nên kiêu ngạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9145, 47771, '彼は大胆な計画を発表した。', 'かれは だいたんな けいかくを はっぴょう した。', 'Anh ấy công bố một kế hoạch táo bạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9146, 47939, 'ご提案については、社内で検討いたします。', 'ごていあんに ついては、しゃないで けんとう いたします。', 'Về đề xuất của quý vị, chúng tôi sẽ xem xét trong công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9147, 47992, '人手不足を解決する方策を考えよう。', 'ひとで ぶそくを かいけつ する ほうさくを かんがえよう。', 'Hãy nghĩ biện pháp giải quyết tình trạng thiếu người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9148, 48129, '成功してから、彼は傲慢になった。', 'せいこう してから、かれは ごうまんに なった。', 'Từ khi thành công, anh ta trở nên kiêu ngạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9149, 31647, '犬は飼い主に忠実な動物だ。', 'いぬは かいぬしに ちゅうじつな どうぶつだ。', 'Chó là loài vật trung thành với chủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9150, 31650, '彼女は包容力があって、みんなに頼られている。', 'かのじょは ほうようりょくが あって、みんなに たよられて いる。', 'Cô ấy bao dung nên được mọi người tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9151, 31656, '二人の意見が一致した。', 'ふたりの いけんが いっち した。', 'Ý kiến của hai người đã nhất trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9152, 31610, 'ご提案については、社内で検討いたします。', 'ごていあんに ついては、しゃないで けんとう いたします。', 'Về đề xuất của quý vị, chúng tôi sẽ xem xét trong công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9153, 39805, '大事なところに下線を引いた。', 'だいじな ところに かせんを ひいた。', 'Tôi gạch chân những chỗ quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9154, 39807, '東京の下町には古い店が残っている。', 'とうきょうの したまちには ふるい みせが のこって いる。', 'Khu phố cổ Tokyo vẫn còn những cửa hàng lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9155, 39838, '一点差で負けて、とても悔しい。', 'いってんさで まけて、とても くやしい。', 'Thua chỉ một điểm, thật cay cú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9156, 31611, 'データを使って仮説を検証した。', 'データを つかって かせつを けんしょう した。', 'Chúng tôi dùng dữ liệu để kiểm chứng giả thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9157, 31587, '監督の戦術が見事に当たった。', 'かんとくの せんじゅつが みごとに あたった。', 'Chiến thuật của huấn luyện viên đã thành công mỹ mãn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9158, 31594, '彼は任務を最後まで遂行した。', 'かれは にんむを さいごまで すいこう した。', 'Anh ấy đã thực hiện nhiệm vụ đến cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9159, 31598, '今月の目標は未達に終わった。', 'こんげつの もくひょうは みたつに おわった。', 'Mục tiêu tháng này đã không đạt được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9160, 31601, '仕事の優先順位をつけて進めよう。', 'しごとの ゆうせん じゅんいを つけて すすめよう。', 'Hãy sắp xếp thứ tự ưu tiên rồi tiến hành công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9161, 31603, 'この製品は十の工程を経て作られる。', 'この せいひんは じゅうの こうていを へて つくられる。', 'Sản phẩm này được làm qua mười công đoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9162, 31628, '彼はチームの勝利に大きく貢献した。', 'かれは チームの しょうりに おおきく こうけん した。', 'Anh ấy đóng góp lớn vào chiến thắng của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9163, 31631, '日本の会社と海外の会社が提携した。', 'にほんの かいしゃと かいがいの かいしゃが ていけい した。', 'Một công ty Nhật và một công ty nước ngoài đã liên kết với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9164, 31713, '書類選考を通過して、面接に進んだ。', 'しょるい せんこうを つうか して、めんせつに すすんだ。', 'Tôi vượt qua vòng hồ sơ và vào vòng phỏng vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9165, 31716, '先生の推薦で大学に入った。', 'せんせいの すいせんで だいがくに はいった。', 'Tôi vào đại học nhờ thầy tiến cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9166, 31717, '教授に推薦状を書いてもらった。', 'きょうじゅに すいせんじょうを かいて もらった。', 'Tôi được giáo sư viết thư giới thiệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9167, 31724, 'この仕事は熟練した技術が必要だ。', 'この しごとは じゅくれん した ぎじゅつが ひつようだ。', 'Công việc này đòi hỏi tay nghề thành thạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9168, 37816, '彼の意見に反論する人はいなかった。', 'かれの いけんに はんろん する ひとは いなかった。', 'Không ai phản bác ý kiến của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9169, 38104, '動物は本能で危険を感じる。', 'どうぶつは ほんのうで きけんを かんじる。', 'Động vật cảm nhận nguy hiểm bằng bản năng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9170, 38106, '彼女は豊かな感性を持っている。', 'かのじょは ゆたかな かんせいを もって いる。', 'Cô ấy có cảm quan phong phú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9171, 38109, 'この作家の独特な世界観が好きだ。', 'この さっかの どくとくな せかいかんが すきだ。', 'Tôi thích thế giới quan độc đáo của nhà văn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9172, 38188, '興味本位で人の秘密を聞いてはいけない。', 'きょうみ ほんいで ひとの ひみつを きいては いけない。', 'Không nên hỏi bí mật của người khác chỉ vì tò mò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9173, 39489, '授業中にあくびが止まらなかった。', 'じゅぎょうちゅうに あくびが とまらなかった。', 'Trong giờ học tôi ngáp mãi không dừng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9174, 39487, '彼の無責任な態度に呆れた。', 'かれの むせきにんな たいどに あきれた。', 'Tôi ngán ngẩm trước thái độ vô trách nhiệm của anh ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9175, 39523, '姉に赤ちゃんが生まれて、おめでたいことが続いている。', 'あねに あかちゃんが うまれて、おめでたい ことが つづいて いる。', 'Chị tôi vừa sinh em bé, nhà liên tiếp có chuyện vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9176, 39545, '花粉症で、くしゃみが止まらない。', 'かふんしょうで、くしゃみが とまらない。', 'Dị ứng phấn hoa nên tôi hắt hơi liên tục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9177, 39822, '白いドレスの花嫁がとてもきれいだった。', 'しろい ドレスの はなよめが とても きれい だった。', 'Cô dâu trong chiếc váy trắng thật xinh đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9178, 39840, 'この歌を聞くと、学生時代が懐かしくなる。', 'この うたを きくと、がくせい じだいが なつかしく なる。', 'Nghe bài hát này tôi lại nhớ thời sinh viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9179, 39546, '一日中立ち仕事で、すっかりくたびれた。', 'いちにちじゅう たちしごとで、すっかり くたびれた。', 'Đứng làm cả ngày nên mệt rã rời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9180, 39590, 'しゃっくりが止まらなくて困った。', 'しゃっくりが とまらなくて こまった。', 'Nấc cụt mãi không dứt, khổ quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9181, 39619, 'そそっかしくて、よく忘れ物をする。', 'そそっかしくて、よく わすれものを する。', 'Tôi đãng trí nên hay quên đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9182, 39645, '隣の家から男の人が怒鳴る声が聞こえた。', 'となりの いえから おとこの ひとが どなる こえが きこえた。', 'Từ nhà bên vọng sang tiếng một người đàn ông quát tháo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9183, 39693, '雷が鳴ると、子供はへそを隠す。', 'かみなりが なると、こどもは へそを かくす。', 'Khi sấm rền, trẻ con lấy tay che rốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9184, 39705, '寝不足で、まぶたが重い。', 'ねぶそくで、まぶたが おもい。', 'Thiếu ngủ nên mí mắt nặng trĩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9185, 39715, '急に立ち上がったら、めまいがした。', 'きゅうに たちあがったら、めまいが した。', 'Đứng dậy đột ngột thì tôi bị chóng mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9186, 39707, 'みんなの前で失敗して、みじめな気持ちになった。', 'みんなの まえで しっぱい して、みじめな きもちに なった。', 'Thất bại trước mặt mọi người khiến tôi thấy thảm hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9187, 39713, '兄の結婚が決まって、めでたい。', 'あにの けっこんが きまって、めでたい。', 'Anh tôi đã định ngày cưới, thật đáng mừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9188, 39754, '疲れたから、ここで一休みしよう。', 'つかれたから、ここで ひとやすみ しよう。', 'Mệt rồi, nghỉ một chút ở đây nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9189, 39858, '昼ご飯は各自で用意してください。', 'ひるごはんは かくじで ようい して ください。', 'Bữa trưa mỗi người tự chuẩn bị nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9190, 39865, '大学で英文学科に入った。', 'だいがくで えいぶん がっかに はいった。', 'Tôi vào khoa văn học Anh ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9191, 39866, '教授は海外の学会で発表した。', 'きょうじゅは かいがいの がっかいで はっぴょう した。', 'Giáo sư đã trình bày tại hội nghị học thuật ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9192, 39864, '川を隔てて二つの町がある。', 'かわを へだてて ふたつの まちが ある。', 'Hai thị trấn nằm cách nhau bởi một con sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9193, 44637, '大人の料金は千円です。', 'おとなの りょうきんは せんえん です。', 'Giá vé người lớn là một nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9194, 44697, '病院で注射をしてもらいました。', 'びょういんで ちゅうしゃを して もらいました。', 'Tôi được tiêm ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9195, 44710, '体の具合はどうですか。', 'からだの ぐあいは どう ですか。', 'Sức khỏe của bạn thế nào rồi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9196, 44742, 'この町は安全です。', 'この まちは あんぜん です。', 'Thị trấn này an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9197, 44749, '大学で社会について勉強しています。', 'だいがくで しゃかいに ついて べんきょう して います。', 'Tôi đang học về xã hội ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9198, 29322, '赤ちゃんが泣いています。', 'あかちゃんが ないて います。', 'Em bé đang khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9199, 29411, 'この書類を部長に渡してください。', 'この しょるいを ぶちょうに わたして ください。', 'Hãy đưa tài liệu này cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9200, 44953, '山の空気はきれいです。', 'やまの くうきは きれい です。', 'Không khí trên núi trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9201, 44956, '天気予報によると、あしたは雨だそうです。', 'てんき よほうに よると、あしたは あめだ そう です。', 'Theo dự báo thời tiết thì ngày mai trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9202, 45003, '入学のお祝いに時計をもらいました。', 'にゅうがくの おいわいに とけいを もらいました。', 'Tôi được tặng đồng hồ làm quà mừng nhập học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9203, 29025, 'ゆうべ近所で火事がありました。', 'ゆうべ きんじょで かじが ありました。', 'Tối qua gần nhà xảy ra hỏa hoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9204, 29028, '姉はお見合いで結婚しました。', 'あねは おみあいで けっこん しました。', 'Chị tôi kết hôn qua mai mối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9205, 29038, 'きょうはお疲れ様でした。', 'きょうは おつかれさま でした。', 'Hôm nay anh vất vả rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9206, 39888, '祖父母は孫を甘やかしてばかりいる。', 'そふぼは まごを あまやかして ばかり いる。', 'Ông bà cứ chiều cháu suốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9207, 39878, '朝ご飯は一日の活力のもとだ。', 'あさごはんは いちにちの かつりょくの もとだ。', 'Bữa sáng là nguồn năng lượng cho cả ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9208, 39890, '母は寝ないで私を看病してくれた。', 'ははは ねないで わたしを かんびょう して くれた。', 'Mẹ thức trắng đêm chăm sóc tôi lúc ốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9209, 30992, '政府は規制を緩和した。', 'せいふは きせいを かんわ した。', 'Chính phủ đã nới lỏng các quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9210, 37785, '出張の経費は会社が払う。', 'しゅっちょうの けいひは かいしゃが はらう。', 'Chi phí công tác do công ty chi trả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9211, 37788, '二つの銀行が合併して、一つになった。', 'ふたつの ぎんこうが がっぺい して、ひとつに なった。', 'Hai ngân hàng sáp nhập thành một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9212, 39578, '化粧品のサンプルをもらった。', 'けしょうひんの サンプルを もらった。', 'Tôi được tặng mẫu thử mỹ phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9213, 39733, '現地からのリポートをお伝えします。', 'げんちからの リポートを おつたえ します。', 'Xin gửi đến quý vị bản tin từ hiện trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9214, 39877, '日本人選手が海外で活躍している。', 'にほんじん せんしゅが かいがいで かつやく して いる。', 'Các cầu thủ Nhật đang tỏa sáng ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9215, 39915, '祖父は漁師で、毎朝早く海に出ていた。', 'そふは りょうしで、まいあさ はやく うみに でて いた。', 'Ông tôi là ngư dân, sáng nào cũng ra khơi sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9216, 40016, '彼の功績は高く評価された。', 'かれの こうせきは たかく ひょうか された。', 'Công lao của ông ấy được đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9217, 40103, '指定された席に座ってください。', 'してい された せきに すわって ください。', 'Xin hãy ngồi đúng ghế đã chỉ định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9218, 40108, '新しいデザインの紙幣が発行された。', 'あたらしい デザインの しへいが はっこう された。', 'Tiền giấy mẫu mới đã được phát hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9219, 40127, '看護学校の学生が病院で実習している。', 'かんご がっこうの がくせいが びょういんで じっしゅう して いる。', 'Sinh viên trường điều dưỡng đang thực tập ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9220, 40152, '山田先生は二年生のクラスを受け持っている。', 'やまだ せんせいは にねんせいの クラスを うけもって いる。', 'Thầy Yamada phụ trách lớp năm hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9221, 40162, '新聞の集金の人が来た。', 'しんぶんの しゅうきんの ひとが きた。', 'Người thu tiền báo đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9222, 40170, '重役会議で新しい計画が決まった。', 'じゅうやく かいぎで あたらしい けいかくが きまった。', 'Kế hoạch mới đã được quyết định tại cuộc họp ban giám đốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9223, 40178, '毎朝八時に出勤する。', 'まいあさ はちじに しゅっきん する。', 'Sáng nào tôi cũng đi làm lúc tám giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9224, 42922, '昔、この町には炭鉱があった。', 'むかし、この まちには たんこうが あった。', 'Ngày xưa thị trấn này có mỏ than.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9225, 42894, 'ウエートレスが水を持ってきてくれた。', 'ウエートレスが みずを もって きて くれた。', 'Cô phục vụ mang nước đến cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9226, 31693, '光は水の中で屈折する。', 'ひかりは みずの なかで くっせつ する。', 'Ánh sáng bị khúc xạ khi đi vào nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9227, 39543, '大学のキャンパスはとても広い。', 'だいがくの キャンパスは とても ひろい。', 'Khuôn viên trường đại học rất rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9228, 39599, '週末に英会話スクールに通っている。', 'しゅうまつに えいかいわ スクールに かよって いる。', 'Cuối tuần tôi đi học ở trường dạy tiếng Anh giao tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9229, 39623, '電車のダイヤグラムを見て、時間を調べた。', 'でんしゃの ダイヤグラムを みて、じかんを しらべた。', 'Tôi xem biểu đồ chạy tàu để tra giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9230, 29049, '昔は着物を着ましたが、今では洋服を着る人が多いです。', 'むかしは きものを きましたが、いまでは ようふくを きる ひとが おおい です。', 'Ngày xưa người ta mặc kimono, nhưng bây giờ nhiều người mặc đồ Tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9231, 39919, 'お忙しいところ恐縮ですが、ご確認ください。', 'おいそがしい ところ きょうしゅく ですが、ごかくにん ください。', 'Xin lỗi đã làm phiền lúc anh bận, mong anh kiểm tra giúp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9232, 39925, '後ろから声をかけて友達を驚かした。', 'うしろから こえを かけて ともだちを おどろかした。', 'Tôi gọi từ phía sau làm bạn giật mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9233, 39769, '弟は引き算が苦手だ。', 'おとうとは ひきざんが にがてだ。', 'Em trai tôi kém phép trừ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9234, 29056, '熱があったので、学校を早退しました。', 'ねつが あったので、がっこうを そうたい しました。', 'Bị sốt nên tôi về sớm khỏi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9235, 39777, '英文のメールを書くのは難しい。', 'えいぶんの メールを かくのは むずかしい。', 'Viết email bằng tiếng Anh thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9236, 39778, '英和辞典で単語の意味を調べた。', 'えいわ じてんで たんごの いみを しらべた。', 'Tôi tra nghĩa từ bằng từ điển Anh–Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9237, 39780, '円周の長さを計算しなさい。', 'えんしゅうの ながさを けいさん しなさい。', 'Hãy tính chu vi hình tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9238, 39813, '物理の授業で加速度について習った。', 'ぶつりの じゅぎょうで かそくどに ついて ならった。', 'Trong giờ vật lý tôi học về gia tốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9239, 39863, '違う角度から問題を考えてみよう。', 'ちがう かくどから もんだいを かんがえて みよう。', 'Hãy thử nhìn vấn đề từ một góc độ khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9240, 39867, 'インフルエンザで学級閉鎖になった。', 'インフルエンザで がっきゅう へいさに なった。', 'Lớp học bị đóng cửa vì dịch cúm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9241, 39869, '弟と私は学年が二つ違う。', 'おとうとと わたしは がくねんが ふたつ ちがう。', 'Em trai và tôi cách nhau hai khối lớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9242, 39871, '毎日の勉強で学力がついた。', 'まいにちの べんきょうで がくりょくが ついた。', 'Nhờ học mỗi ngày mà năng lực học tập được nâng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9243, 39872, '小学二年生で掛け算を習う。', 'しょうがく にねんせいで かけざんを ならう。', 'Học sinh lớp hai được học phép nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9244, 39875, '括弧の中に正しい言葉を入れなさい。', 'かっこの なかに ただしい ことばを いれなさい。', 'Hãy điền từ đúng vào trong ngoặc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9245, 39906, '地図の記号の意味を覚えよう。', 'ちずの きごうの いみを おぼえよう。', 'Hãy nhớ ý nghĩa các ký hiệu trên bản đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9246, 40091, '小学生のころ、算数が好きだった。', 'しょうがくせいの ころ、さんすうが すき だった。', 'Hồi tiểu học tôi thích môn số học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9247, 40097, '小数点以下を四捨五入してください。', 'しょうすうてん いかを ししゃごにゅう して ください。', 'Hãy làm tròn phần thập phân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9248, 40116, '冷蔵庫に磁石でメモを貼った。', 'れいぞうこに じしゃくで メモを はった。', 'Tôi dùng nam châm dán giấy nhớ lên tủ lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9249, 40119, '先生が休みで、授業は自習になった。', 'せんせいが やすみで、じゅぎょうは じしゅうに なった。', 'Thầy nghỉ nên giờ học chuyển thành tự học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9250, 39922, 'この料理の作り方は母から教わりました。', 'この りょうりの つくりかたは ははから おそわりました。', 'Cách nấu món này tôi được mẹ dạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9251, 39927, 'グラフの曲線が急に上がっている。', 'グラフの きょくせんが きゅうに あがって いる。', 'Đường cong trên biểu đồ tăng vọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9252, 39933, 'この区域は駐車禁止です。', 'この くいきは ちゅうしゃ きんし です。', 'Khu vực này cấm đỗ xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9253, 39920, '歯に何か挟まっている。', 'はに なにか はさまって いる。', 'Có gì đó mắc vào kẽ răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9254, 39924, 'ホールにピアノの音が響いた。', 'ホールに ピアノの おとが ひびいた。', 'Tiếng đàn piano vang khắp hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9255, 39929, '危ないから、川に近寄らないで。', 'あぶないから、かわに ちかよらないで。', 'Nguy hiểm đấy, đừng lại gần sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9256, 39923, 'この言葉は響きがきれいだ。', 'この ことばは ひびきが きれいだ。', 'Từ này nghe âm điệu rất hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9257, 39968, '毎日の献立を考えるのは大変だ。', 'まいにちの こんだてを かんがえるのは たいへんだ。', 'Nghĩ thực đơn mỗi ngày thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9258, 39935, '隣の人から騒音の苦情が来た。', 'となりの ひとから そうおんの くじょうが きた。', 'Hàng xóm đã phàn nàn về tiếng ồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9259, 39962, '父は血圧が高いので、塩分を控えている。', 'ちちは けつあつが たかいので、えんぶんを ひかえて いる。', 'Bố tôi huyết áp cao nên hạn chế ăn mặn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9260, 39963, '血液の検査の結果は来週わかる。', 'けつえきの けんさの けっかは らいしゅう わかる。', 'Tuần sau sẽ có kết quả xét nghiệm máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9261, 39977, '入院中の祖母を見舞った。', 'にゅういんちゅうの そぼを みまった。', 'Tôi đi thăm bà đang nằm viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9262, 39937, '子供のころ、よく空想にふけっていた。', 'こどもの ころ、よく くうそうに ふけって いた。', 'Hồi nhỏ tôi hay mải mê mộng tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9263, 39976, '生活習慣を見直す必要がある。', 'せいかつ しゅうかんを みなおす ひつようが ある。', 'Cần xem lại thói quen sinh hoạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9264, 40133, '経済学は社会科学の一つだ。', 'けいざいがくは しゃかい かがくの ひとつだ。', 'Kinh tế học là một ngành khoa học xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9265, 40172, '宇宙では重力がないので、体が浮く。', 'うちゅうでは じゅうりょくが ないので、からだが うく。', 'Trong vũ trụ không có trọng lực nên cơ thể lơ lửng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9266, 40185, 'この文の述語はどれですか。', 'この ぶんの じゅつごは どれ ですか。', 'Vị ngữ của câu này là từ nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9267, 40193, '漢字の書き取りのテストがある。', 'かんじの かきとりの テストが ある。', 'Có bài kiểm tra viết chính tả chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9268, 40222, '来年は上級のクラスに進みたい。', 'らいねんは じょうきゅうの クラスに すすみたい。', 'Năm sau tôi muốn lên lớp cao cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9269, 43116, 'ニュートンは引力の法則を発見した。', 'ニュートンは いんりょくの ほうそくを はっけん した。', 'Newton đã phát hiện ra định luật vạn vật hấp dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9270, 39964, '月給は二十五万円です。', 'げっきゅうは にじゅうごまんえん です。', 'Lương tháng là hai trăm năm mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9271, 39967, 'このソファーはベッドも兼ねている。', 'この ソファーは ベッドも かねて いる。', 'Chiếc sofa này kiêm luôn giường ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9272, 39978, '店の前に料理の見本が並んでいる。', 'みせの まえに りょうりの みほんが ならんで いる。', 'Trước cửa quán bày mẫu các món ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9273, 39939, '二、四、六は偶数です。', 'に、よん、ろくは ぐうすう です。', 'Hai, bốn, sáu là số chẵn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9274, 39971, '社会科の授業で工場を見学した。', 'しゃかいかの じゅぎょうで こうじょうを けんがく した。', 'Trong giờ xã hội chúng tôi đi tham quan nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9275, 39969, '県庁で手続きをした。', 'けんちょうで てつづきを した。', 'Tôi làm thủ tục ở văn phòng tỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9276, 39940, '櫛で髪をとかした。', 'くしで かみを とかした。', 'Tôi chải tóc bằng lược.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9277, 39938, '風船が空中に浮かんでいる。', 'ふうせんが くうちゅうに うかんで いる。', 'Quả bóng bay lơ lửng trên không trung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9278, 39965, '月日がたつのは早い。', 'つきひが たつのは はやい。', 'Thời gian trôi nhanh thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9279, 39959, '外国人観光客が激増している。', 'がいこくじん かんこうきゃくが げきぞう して いる。', 'Khách du lịch nước ngoài đang tăng vọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9280, 39955, '二本のロープを繋げて長くした。', 'にほんの ロープを つなげて ながく した。', 'Tôi nối hai sợi dây thừng cho dài ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9281, 39973, '毎日通る道なので、すっかり見慣れた。', 'まいにち とおる みち なので、すっかり みなれた。', 'Con đường ngày nào cũng đi nên đã quá quen mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9282, 39936, '財布の中が空っぽだ。', 'さいふの なかが からっぽだ。', 'Trong ví trống rỗng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9283, 40004, 'ご無沙汰しております。お元気ですか。', 'ごぶさた して おります。おげんき ですか。', 'Lâu quá không liên lạc. Anh vẫn khỏe chứ ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9284, 39979, '彼は「まだまだです」と謙遜した。', 'かれは 「まだまだ です」と けんそん した。', 'Anh ấy khiêm tốn nói "tôi còn kém lắm".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9285, 39988, '彼が急に会社を辞めると言い出した。', 'かれが きゅうに かいしゃを やめると いいだした。', 'Anh ấy bỗng nói ra rằng sẽ nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9286, 39989, '弟は何でも母に言い付ける。', 'おとうとは なんでも ははに いいつける。', 'Em trai tôi chuyện gì cũng mách mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9287, 39990, '留守だったので、隣の人に手紙を言付けた。', 'るす だったので、となりの ひとに てがみを ことづけた。', 'Chủ nhà đi vắng nên tôi gửi lại lá thư cho hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9288, 39991, 'お客様には言葉遣いに気をつけなさい。', 'おきゃくさまには ことばづかいに きを つけなさい。', 'Với khách hàng phải chú ý cách dùng từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9289, 39995, '市は住民に節電を呼び掛けた。', 'しは じゅうみんに せつでんを よびかけた。', 'Thành phố kêu gọi người dân tiết kiệm điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9290, 39996, '授業中に校長室に呼び出された。', 'じゅぎょうちゅうに こうちょうしつに よびだされた。', 'Đang giờ học thì tôi bị gọi lên phòng hiệu trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9291, 40005, 'ご免ください。どなたかいらっしゃいますか。', 'ごめん ください。どなたか いらっしゃいますか。', 'Xin phép ạ. Có ai ở nhà không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9292, 40006, 'こちらの資料をご覧ください。', 'こちらの しりょうを ごらん ください。', 'Xin mời xem tài liệu này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9293, 43134, '漢字のテストで満点を取った。', 'かんじの テストで まんてんを とった。', 'Tôi được điểm tuyệt đối bài kiểm tra chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9294, 43199, '理科の実験はいつも楽しい。', 'りかの じっけんは いつも たのしい。', 'Giờ thí nghiệm khoa học lúc nào cũng vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9295, 43212, 'テストで零点を取って、母に怒られた。', 'テストで れいてんを とって、ははに おこられた。', 'Bị điểm không bài kiểm tra nên tôi bị mẹ mắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9296, 31622, '政府は規制を緩和した。', 'せいふは きせいを かんわ した。', 'Chính phủ đã nới lỏng các quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9297, 31669, '急な変更で現場が混乱した。', 'きゅうな へんこうで げんばが こんらん した。', 'Thay đổi đột ngột khiến hiện trường hỗn loạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9298, 31671, '外で何か騒ぎがあったようだ。', 'そとで なにか さわぎが あった ようだ。', 'Hình như bên ngoài có chuyện ồn ào gì đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9299, 31674, '緊急の場合はこの番号に電話してください。', 'きんきゅうの ばあいは この ばんごうに でんわ して ください。', 'Trường hợp khẩn cấp hãy gọi số này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9300, 40010, '夜の仕事は三人で交替している。', 'よるの しごとは さんにんで こうたい して いる。', 'Ca đêm có ba người thay phiên nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9301, 39981, '顕微鏡で植物の細胞を観察した。', 'けんびきょうで しょくぶつの さいぼうを かんさつ した。', 'Tôi quan sát tế bào thực vật bằng kính hiển vi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9302, 39985, '飛行機が飛ぶ原理を説明してください。', 'ひこうきが とぶ げんりを せつめい して ください。', 'Hãy giải thích nguyên lý máy bay bay được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9303, 39993, '同じ種類の動物でも、個体によって性格が違う。', 'おなじ しゅるいの どうぶつでも、こたいに よって せいかくが ちがう。', 'Dù cùng loài, mỗi cá thể lại có tính cách khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9304, 40000, 'まず五十音を覚えましょう。', 'まず ごじゅうおんを おぼえましょう。', 'Trước tiên hãy học thuộc bảng 50 âm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9305, 40012, 'この問題は公式を使えばすぐ解ける。', 'この もんだいは こうしきを つかえば すぐ とける。', 'Bài này dùng công thức là giải được ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9306, 29033, 'ホテルのフロントで鍵をもらいました。', 'ホテルの フロントで かぎを もらいました。', 'Tôi nhận chìa khóa ở quầy lễ tân khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9307, 40021, 'うちの子は食べ物の好き嫌いが多い。', 'うちの こは たべものの すききらいが おおい。', 'Con tôi kén ăn lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9308, 40022, 'どの色を選ぶかは好き好きだ。', 'どの いろを えらぶかは すきずきだ。', 'Chọn màu nào là tùy sở thích mỗi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9309, 40020, '彼は頭痛を口実に会議を休んだ。', 'かれは ずつうを こうじつに かいぎを やすんだ。', 'Anh ta lấy cớ đau đầu để nghỉ họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9310, 31683, '地震の後、町の復興が進んでいる。', 'じしんの あと、まちの ふっこうが すすんで いる。', 'Sau động đất, công cuộc tái thiết thị trấn đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9311, 31685, '最近は結婚しなくてもいいという風潮がある。', 'さいきんは けっこん しなくても いいと いう ふうちょうが ある。', 'Gần đây có xu hướng cho rằng không cưới cũng được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9312, 31689, '内閣の支持率が下がっている。', 'ないかくの しじりつが さがって いる。', 'Tỷ lệ ủng hộ nội các đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9313, 31690, '増税に国民が強く反発した。', 'ぞうぜいに こくみんが つよく はんぱつ した。', 'Người dân phản đối mạnh mẽ việc tăng thuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9314, 31692, '新しいやり方に抵抗を感じる人もいる。', 'あたらしい やりかたに ていこうを かんじる ひとも いる。', 'Có người cảm thấy e ngại với cách làm mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9315, 39946, '「高い」は形容詞です。', '「たかい」は けいようし です。', '"Takai" là tính từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9316, 47276, '二つの銀行が合併して、一つになった。', 'ふたつの ぎんこうが がっぺい して、ひとつに なった。', 'Hai ngân hàng sáp nhập thành một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9317, 47281, '大きな仕事を受注することができた。', 'おおきな しごとを じゅちゅう する ことが できた。', 'Chúng tôi đã nhận được một đơn hàng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9318, 47329, '新聞社が世論調査を行った。', 'しんぶんしゃが よろん ちょうさを おこなった。', 'Tòa báo đã tiến hành khảo sát dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9319, 47359, '急な変更で現場が混乱した。', 'きゅうな へんこうで げんばが こんらん した。', 'Thay đổi đột ngột khiến hiện trường hỗn loạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9320, 47364, '停電は二時間後に復旧した。', 'ていでんは にじかんごに ふっきゅう した。', 'Mất điện hai tiếng thì có điện trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9321, 47365, '地震の後、町の復興が進んでいる。', 'じしんの あと、まちの ふっこうが すすんで いる。', 'Sau động đất, công cuộc tái thiết thị trấn đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9322, 47449, 'その学説は今では否定されている。', 'その がくせつは いまでは ひてい されて いる。', 'Học thuyết đó giờ đã bị bác bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9323, 47451, '飛行機が飛ぶ原理を説明してください。', 'ひこうきが とぶ げんりを せつめい して ください。', 'Hãy giải thích nguyên lý máy bay bay được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9324, 47453, 'この問題は公式を使えばすぐ解ける。', 'この もんだいは こうしきを つかえば すぐ とける。', 'Bài này dùng công thức là giải được ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9325, 40023, 'この工場では二百人の工員が働いている。', 'この こうじょうでは にひゃくにんの こういんが はたらいて いる。', 'Nhà máy này có hai trăm công nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9326, 40025, '家の前で道路の工事をしている。', 'いえの まえで どうろの こうじを して いる。', 'Trước nhà đang thi công đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9327, 40019, '出かける前に口紅を塗った。', 'でかける まえに くちべにを ぬった。', 'Trước khi ra ngoài tôi tô son môi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9328, 40029, '駅前の広場で待ち合わせしよう。', 'えきまえの ひろばで まちあわせ しよう。', 'Hẹn nhau ở quảng trường trước ga nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9329, 40028, 'この部屋の広さは十畳ぐらいだ。', 'この へやの ひろさは じゅうじょう ぐらいだ。', 'Phòng này rộng khoảng mười chiếu tatami.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9330, 40032, 'タオルをよく絞ってから干した。', 'タオルを よく しぼってから ほした。', 'Tôi vắt khăn thật kỹ rồi phơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9331, 40026, '広々とした公園で子供が遊んでいる。', 'ひろびろと した こうえんで こどもが あそんで いる。', 'Trẻ con đang chơi trong công viên rộng rãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9332, 29064, 'バスは八時に出発します。', 'バスは はちじに しゅっぱつ します。', 'Xe buýt xuất phát lúc tám giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9333, 40054, '彼に恨みはないが、許すことはできない。', 'かれに うらみは ないが、ゆるす ことは できない。', 'Tôi không oán anh ta, nhưng cũng không thể tha thứ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9334, 40055, '人を恨んでも、何も変わらない。', 'ひとを うらんでも、なにも かわらない。', 'Oán hận người khác cũng chẳng thay đổi được gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9335, 40061, '大家さんに家賃を催促された。', 'おおやさんに やちんを さいそく された。', 'Tôi bị chủ nhà giục trả tiền thuê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9336, 47462, '論文を書くために、多くの文献を読んだ。', 'ろんぶんを かく ために、おおくの ぶんけんを よんだ。', 'Để viết luận văn, tôi đã đọc nhiều tài liệu tham khảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9337, 47480, '宇宙では重力がないので、体が浮く。', 'うちゅうでは じゅうりょくが ないので、からだが うく。', 'Trong vũ trụ không có trọng lực nên cơ thể lơ lửng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9338, 47546, '祖母は大阪の方言で話す。', 'そぼは おおさかの ほうげんで はなす。', 'Bà tôi nói giọng địa phương Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9339, 47629, '父は小さなレストランを経営している。', 'ちちは ちいさな レストランを けいえい して いる。', 'Bố tôi điều hành một nhà hàng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9340, 47640, '部品を工場に発注した。', 'ぶひんを こうじょうに はっちゅう した。', 'Chúng tôi đã đặt linh kiện từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
