INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9345, 47731, '政府は規制を緩和した。', 'せいふは きせいを かんわ した。', 'Chính phủ đã nới lỏng các quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
