INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9347, 47812, 'ニュートンは引力の法則を発見した。', 'ニュートンは いんりょくの ほうそくを はっけん した。', 'Newton đã phát hiện ra định luật vạn vật hấp dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
