INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9353, 48001, '大きな仕事を受注することができた。', 'おおきな しごとを じゅちゅう する ことが できた。', 'Chúng tôi đã nhận được một đơn hàng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9354, 40034, '春になると、農家は畑を耕す。', 'はるに なると、のうかは はたけを たがやす。', 'Sang xuân, nhà nông cày xới ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9355, 40056, '収入から支出を差し引きすると、三万円残る。', 'しゅうにゅうから ししゅつを さしひき すると、さんまんえん のこる。', 'Lấy thu trừ chi thì còn ba mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9356, 40065, '先生はテストの採点に忙しい。', 'せんせいは テストの さいてんに いそがしい。', 'Thầy giáo đang bận chấm bài kiểm tra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9357, 48079, '急な変更で現場が混乱した。', 'きゅうな へんこうで げんばが こんらん した。', 'Thay đổi đột ngột khiến hiện trường hỗn loạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9358, 48084, '停電は二時間後に復旧した。', 'ていでんは にじかんごに ふっきゅう した。', 'Mất điện hai tiếng thì có điện trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9359, 48085, '地震の後、町の復興が進んでいる。', 'じしんの あと、まちの ふっこうが すすんで いる。', 'Sau động đất, công cuộc tái thiết thị trấn đang tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9360, 48169, 'その学説は今では否定されている。', 'その がくせつは いまでは ひてい されて いる。', 'Học thuyết đó giờ đã bị bác bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9361, 48172, 'ニュートンは引力の法則を発見した。', 'ニュートンは いんりょくの ほうそくを はっけん した。', 'Newton đã phát hiện ra định luật vạn vật hấp dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9362, 48173, 'この問題は公式を使えばすぐ解ける。', 'この もんだいは こうしきを つかえば すぐ とける。', 'Bài này dùng công thức là giải được ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9363, 48182, '論文を書くために、多くの文献を読んだ。', 'ろんぶんを かく ために、おおくの ぶんけんを よんだ。', 'Để viết luận văn, tôi đã đọc nhiều tài liệu tham khảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9364, 48193, 'スマホは年々進化している。', 'スマホは ねんねん しんか して いる。', 'Điện thoại thông minh tiến hóa qua từng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9365, 48200, '宇宙では重力がないので、体が浮く。', 'うちゅうでは じゅうりょくが ないので、からだが うく。', 'Trong vũ trụ không có trọng lực nên cơ thể lơ lửng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9366, 48262, '文脈から言葉の意味を考えなさい。', 'ぶんみゃくから ことばの いみを かんがえなさい。', 'Hãy suy ra nghĩa của từ từ ngữ cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9367, 31637, 'この大会は市が後援している。', 'この たいかいは しが こうえん して いる。', 'Giải đấu này được thành phố bảo trợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9368, 37793, '今月の請求書をお送りします。', 'こんげつの せいきゅうしょを おおくり します。', 'Chúng tôi xin gửi hóa đơn tháng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9403, 29084, '電車でお年寄りに席を譲りました。', 'でんしゃで おとしよりに せきを ゆずりました。', 'Tôi nhường ghế cho người già trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9369, 37796, '大きな仕事を受注することができた。', 'おおきな しごとを じゅちゅう する ことが できた。', 'Chúng tôi đã nhận được một đơn hàng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9370, 31727, '会社は若い社員の育成に力を入れている。', 'かいしゃは わかい しゃいんの いくせいに ちからを いれて いる。', 'Công ty chú trọng bồi dưỡng nhân viên trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9371, 37832, '大学三年生から就職活動を始めた。', 'だいがく さんねんせいから しゅうしょく かつどうを はじめた。', 'Từ năm ba đại học tôi đã bắt đầu đi xin việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9372, 37834, 'この会社は年齢より能力主義で評価する。', 'この かいしゃは ねんれいより のうりょく しゅぎで ひょうか する。', 'Công ty này đánh giá theo năng lực hơn là tuổi tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9373, 37825, '日本の義務教育は九年間だ。', 'にほんの ぎむ きょういくは きゅうねんかんだ。', 'Giáo dục bắt buộc ở Nhật kéo dài chín năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9374, 37830, '卒業するには百二十四単位が必要だ。', 'そつぎょう するには ひゃくにじゅうよん たんいが ひつようだ。', 'Để tốt nghiệp cần 124 tín chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9375, 37831, '高校を卒業した後の進路を考えている。', 'こうこうを そつぎょう した あとの しんろを かんがえて いる。', 'Tôi đang suy nghĩ hướng đi sau khi tốt nghiệp cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9376, 38128, 'その学説は今では否定されている。', 'その がくせつは いまでは ひてい されて いる。', 'Học thuyết đó giờ đã bị bác bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9377, 40086, '子供がおもちゃを散らかしている。', 'こどもが おもちゃを ちらかして いる。', 'Bọn trẻ bày đồ chơi bừa bãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9378, 40084, '夜空に細い三日月が出ている。', 'よぞらに ほそい みかづきが でて いる。', 'Trên trời đêm có vầng trăng lưỡi liềm mảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9379, 40089, '風で桜の花が散ってしまった。', 'かぜで さくらの はなが ちって しまった。', 'Gió làm hoa anh đào rụng hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9380, 40088, 'ご飯の上にのりを散らした。', 'ごはんの うえに のりを ちらした。', 'Tôi rắc rong biển lên trên cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9381, 40099, '美しい自然を子孫に残したい。', 'うつくしい しぜんを しそんに のこしたい。', 'Tôi muốn để lại thiên nhiên tươi đẹp cho con cháu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9382, 40104, '山の中で死体が見つかったというニュースがあった。', 'やまの なかで したいが みつかったと いう ニュースが あった。', 'Có tin tức về việc phát hiện thi thể trong núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9383, 40122, '失恋して、一週間何もする気になれなかった。', 'しつれん して、いっしゅうかん なにも する きに なれなかった。', 'Thất tình, cả tuần tôi chẳng muốn làm gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9384, 40126, '日本に来て、やっと留学生活の実感がわいた。', 'にほんに きて、やっと りゅうがく せいかつの じっかんが わいた。', 'Đến Nhật rồi tôi mới thực sự cảm nhận được cuộc sống du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9385, 38136, '使わない筋肉は退化する。', 'つかわない きんにくは たいか する。', 'Cơ bắp không dùng đến sẽ thoái hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9386, 38130, '市場の動向に注意している。', 'しじょうの どうこうに ちゅうい して いる。', 'Chúng tôi đang theo dõi động thái thị trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9387, 38137, '人々の働き方が多様化している。', 'ひとびとの はたらきかたが たようか して いる。', 'Cách làm việc của mọi người ngày càng đa dạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9388, 38161, '祖父は近くの福祉施設に通っている。', 'そふは ちかくの ふくし しせつに かよって いる。', 'Ông tôi thường đến cơ sở phúc lợi xã hội gần nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9389, 38162, '高齢化で社会保障の費用が増えている。', 'こうれいかで しゃかい ほしょうの ひようが ふえて いる。', 'Do già hóa dân số, chi phí an sinh xã hội ngày càng tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9390, 38164, '政府は貧困層への支援を増やした。', 'せいふは ひんこんそうへの しえんを ふやした。', 'Chính phủ tăng hỗ trợ cho tầng lớp nghèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9391, 38165, '格差社会をなくすための政策が必要だ。', 'かくさ しゃかいを なくす ための せいさくが ひつようだ。', 'Cần có chính sách xóa bỏ xã hội phân hóa giàu nghèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9392, 39694, '彼はこの道三十年のベテランだ。', 'かれは この みち さんじゅうねんの ベテランだ。', 'Ông ấy là người kỳ cựu với ba mươi năm trong nghề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9393, 39809, '古い本は今と仮名遣いが違う。', 'ふるい ほんは いまと かなづかいが ちがう。', 'Sách cũ có cách viết kana khác bây giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9394, 39932, '作文では句読点を正しく使いなさい。', 'さくぶんでは くとうてんを ただしく つかいなさい。', 'Khi viết văn hãy dùng dấu câu cho đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9395, 40035, 'この村は耕地が少ない。', 'この むらは こうちが すくない。', 'Làng này ít đất canh tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9396, 40074, '会議の資料を作成した。', 'かいぎの しりょうを さくせい した。', 'Tôi đã soạn tài liệu cho cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9397, 40072, '大学に在学中に留学した。', 'だいがくに ざいがくちゅうに りゅうがく した。', 'Trong thời gian học đại học tôi đã đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9398, 40083, '紙を三角に折った。', 'かみを さんかくに おった。', 'Tôi gấp tờ giấy thành hình tam giác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9399, 40090, 'この地方はみかんの産地として有名だ。', 'この ちほうは みかんの さんちと して ゆうめいだ。', 'Vùng này nổi tiếng là nơi sản xuất quýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9400, 29071, '天気予報によると、あしたは雨だそうです。', 'てんき よほうに よると、あしたは あめだ そう です。', 'Theo dự báo thời tiết thì ngày mai trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9401, 29075, '娘のピアノの発表会を見に行きました。', 'むすめの ピアノの はっぴょうかいを みに いきました。', 'Tôi đi xem buổi biểu diễn piano của con gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9402, 29080, '紙の裏に名前を書いてください。', 'かみの うらに なまえを かいて ください。', 'Hãy viết tên ở mặt sau tờ giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9404, 29088, 'この箱の大きさはちょうどいいです。', 'この はこの おおきさは ちょうど いい です。', 'Kích cỡ chiếc hộp này vừa đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9405, 29092, 'コーヒーを一杯ください。', 'コーヒーを いっぱい ください。', 'Cho tôi một ly cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9406, 39815, 'その法案は国会で可決された。', 'その ほうあんは こっかいで かけつ された。', 'Dự luật đó đã được quốc hội thông qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9407, 39885, 'この辺りには官庁の建物が多い。', 'この あたりには かんちょうの たてものが おおい。', 'Quanh đây có nhiều tòa nhà cơ quan chính phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9408, 39905, 'この学校は規律が厳しい。', 'この がっこうは きりつが きびしい。', 'Trường này kỷ luật nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9409, 39907, '昔、この地方では飢饉で多くの人が亡くなった。', 'むかし、この ちほうでは ききんで おおくの ひとが なくなった。', 'Ngày xưa vùng này nhiều người chết vì nạn đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9410, 40014, '調査の結果が公表された。', 'ちょうさの けっかが こうひょう された。', 'Kết quả điều tra đã được công bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9411, 40050, 'この会社にはいろいろな国籍の社員がいる。', 'この かいしゃには いろいろな こくせきの しゃいんが いる。', 'Công ty này có nhân viên mang nhiều quốc tịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9412, 40066, '財布を落とすなんて、とんだ災難だったね。', 'さいふを おとす なんて、とんだ さいなん だったね。', 'Đánh rơi ví, đúng là xui xẻo nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9413, 40117, '自衛のために、ドアに鍵を二つつけた。', 'じえいの ために、ドアに かぎを ふたつ つけた。', 'Để tự vệ, tôi lắp hai ổ khóa cho cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9414, 40161, '駅前で大きな集会が開かれた。', 'えきまえで おおきな しゅうかいが ひらかれた。', 'Một cuộc mít tinh lớn đã diễn ra trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9415, 40188, '町の巡査が道を教えてくれた。', 'まちの じゅんさが みちを おしえて くれた。', 'Anh cảnh sát tuần tra chỉ đường cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9416, 40236, '夜中に泥棒が家に侵入した。', 'よなかに どろぼうが いえに しんにゅう した。', 'Nửa đêm kẻ trộm đột nhập vào nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9417, 43206, '大阪の領事館でビザを申請した。', 'おおさかの りょうじかんで ビザを しんせい した。', 'Tôi xin visa ở lãnh sự quán tại Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9418, 39503, '冬はウールのセーターが暖かい。', 'ふゆは ウールの セーターが あたたかい。', 'Mùa đông áo len lông cừu rất ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9419, 39533, '本にカバーをかけてもらった。', 'ほんに カバーを かけて もらった。', 'Tôi được bọc bìa cho cuốn sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9420, 39564, '髪をゴムで結んだ。', 'かみを ゴムで むすんだ。', 'Tôi buộc tóc bằng dây thun.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9421, 39569, '昔の木の橋がコンクリートの橋になった。', 'むかしの きの はしが コンクリートの はしに なった。', 'Cây cầu gỗ ngày xưa đã thành cầu bê tông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9422, 39581, '週に一回シーツを洗っている。', 'しゅうに いっかい シーツを あらって いる。', 'Mỗi tuần tôi giặt ga trải giường một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9423, 39591, '夜になると、商店街の店はシャッターを下ろす。', 'よるに なると、しょうてんがいの みせは シャッターを おろす。', 'Về đêm, các cửa hàng trong khu phố kéo cửa cuốn xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9424, 39615, 'セメントに水と砂を混ぜる。', 'セメントに みずと すなを まぜる。', 'Trộn xi măng với nước và cát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9425, 39654, '誕生日に母からネックレスをもらった。', 'たんじょうびに ははから ネックレスを もらった。', 'Sinh nhật tôi được mẹ tặng dây chuyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9426, 39674, '雨の日は自転車にビニールのカバーをかける。', 'あめの ひは じてんしゃに ビニールの カバーを かける。', 'Ngày mưa tôi trùm áo ni lông lên xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9427, 39706, '寒いので、マフラーを巻いて出かけた。', 'さむいので、マフラーを まいて でかけた。', 'Trời lạnh nên tôi quàng khăn rồi ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9428, 39734, 'プレゼントの箱にリボンをかけた。', 'プレゼントの はこに リボンを かけた。', 'Tôi thắt ruy băng lên hộp quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9429, 39739, '荷物を駅のロッカーに入れた。', 'にもつを えきの ロッカーに いれた。', 'Tôi cất hành lý vào tủ khóa ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9430, 39796, '襖を開けると、隣の部屋が見えた。', 'ふすまを あけると、となりの へやが みえた。', 'Kéo cửa fusuma ra thì thấy phòng bên cạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9431, 40145, 'この店は手頃な値段で食事ができる。', 'この みせは てごろな ねだんで しょくじが できる。', 'Quán này có thể ăn với giá phải chăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9432, 40179, '空港でお出迎えいたします。', 'くうこうで おでむかえ いたします。', 'Chúng tôi sẽ ra sân bay đón quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9433, 40180, '駅で友達を出迎えた。', 'えきで ともだちを でむかえた。', 'Tôi ra ga đón bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9434, 40146, 'テニスで手首を痛めた。', 'テニスで てくびを いためた。', 'Chơi tennis tôi bị đau cổ tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9435, 40186, '彼は純情で、すぐに顔が赤くなる。', 'かれは じゅんじょうで、すぐに かおが あかく なる。', 'Cậu ấy ngây thơ, hơi tí là đỏ mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9436, 39804, '大雨で下水があふれた。', 'おおあめで げすいが あふれた。', 'Mưa lớn làm cống ngầm tràn nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9437, 39816, '地震で多くの家屋が倒れた。', 'じしんで おおくの かおくが たおれた。', 'Động đất làm đổ nhiều nhà cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9438, 39880, '古い家の屋根は瓦でできている。', 'ふるい いえの やねは かわらで できて いる。', 'Mái nhà cũ được lợp bằng ngói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9439, 39881, 'ドライヤーで髪を乾かした。', 'ドライヤーで かみを かわかした。', 'Tôi sấy khô tóc bằng máy sấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9440, 39887, 'ときどき窓を開けて換気しましょう。', 'ときどき まどを あけて かんき しましょう。', 'Thỉnh thoảng hãy mở cửa sổ cho thông gió.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9441, 39998, 'お菓子は戸棚の中にしまってある。', 'おかしは とだなの なかに しまって ある。', 'Bánh kẹo được cất trong tủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9442, 40040, '彼女はいつもいい香水をつけている。', 'かのじょは いつも いい こうすいを つけて いる。', 'Cô ấy lúc nào cũng xức nước hoa thơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9443, 40058, 'お客様に座布団を出した。', 'おきゃくさまに ざぶとんを だした。', 'Tôi đưa đệm ngồi cho khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9444, 40071, '祖母は裁縫が得意だ。', 'そぼは さいほうが とくいだ。', 'Bà tôi giỏi may vá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9445, 40080, '雑巾で床をふいた。', 'ぞうきんで ゆかを ふいた。', 'Tôi lau sàn bằng giẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9446, 40107, '紙屑はこの箱に捨ててください。', 'かみくずは この はこに すてて ください。', 'Hãy bỏ giấy vụn vào thùng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9447, 40138, '蛇口から水がぽたぽた落ちている。', 'じゃぐちから みずが ぽたぽた おちて いる。', 'Nước nhỏ giọt từ vòi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9448, 40148, 'お手洗いはどこですか。', 'おてあらいは どこ ですか。', 'Nhà vệ sinh ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9449, 40157, '古い屋根を修繕した。', 'ふるい やねを しゅうぜん した。', 'Chúng tôi đã sửa lại mái nhà cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9450, 40166, '地震で住居を失った人がたくさんいる。', 'じしんで じゅうきょを うしなった ひとが たくさん いる。', 'Có nhiều người mất nhà cửa vì động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9451, 40208, '床の間に花を飾った。', 'とこのまに はなを かざった。', 'Tôi cắm hoa trang trí ở hốc tường tokonoma.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9452, 40226, '洗濯物を畳んで、たんすにしまった。', 'せんたくものを たたんで、たんすに しまった。', 'Tôi gấp quần áo đã giặt rồi cất vào tủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9453, 40286, '瀬戸物の皿を落として割ってしまった。', 'せとものの さらを おとして わって しまった。', 'Tôi làm rơi vỡ chiếc đĩa sứ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9454, 42925, '工事のため、明日の午前中は断水します。', 'こうじの ため、あしたの ごぜんちゅうは だんすい します。', 'Do thi công, sáng mai sẽ cúp nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9455, 43117, '取れたボタンを縫い付けた。', 'とれた ボタンを ぬいつけた。', 'Tôi khâu lại chiếc cúc bị tuột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9456, 43152, '動物の毛皮のコートは着ないことにしている。', 'どうぶつの けがわの コートは きない ことに して いる。', 'Tôi quyết không mặc áo khoác lông thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9457, 29099, '仙台の七夕祭りは有名です。', 'せんだいの たなばた まつりは ゆうめい です。', 'Lễ hội Tanabata ở Sendai rất nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9458, 29111, '空港に爆弾があるという電話がありました。', 'くうこうに ばくだんが あると いう でんわが ありました。', 'Đã có cuộc gọi báo có bom ở sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9459, 40198, '受付に髪の長い女の人がいる。', 'うけつけに かみの ながい おんなのひとが いる。', 'Ở quầy lễ tân có một người phụ nữ tóc dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9460, 40199, 'うちの女房は料理が上手なんだ。', 'うちの にょうぼうは りょうりが じょうず なんだ。', 'Bà xã nhà tôi nấu ăn giỏi lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9461, 40197, '彼は三十歳で助教授になった。', 'かれは さんじゅっさいで じょきょうじゅに なった。', 'Anh ấy trở thành phó giáo sư ở tuổi ba mươi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9462, 43154, 'この家は日本の木材で建てられた。', 'この いえは にほんの もくざいで たてられた。', 'Ngôi nhà này được xây bằng gỗ Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9463, 43200, '店の裏口から荷物を運び入れた。', 'みせの うらぐちから にもつを はこびいれた。', 'Chúng tôi chuyển hàng vào qua cửa sau cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9464, 43216, 'ケーキに蝋燭を十本立てた。', 'ケーキに ろうそくを じゅっぽん たてた。', 'Tôi cắm mười cây nến lên bánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9465, 39538, 'この料理はカロリーが高い。', 'この りょうりは カロリーが たかい。', 'Món này nhiều calo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9466, 39559, '兄はホテルのコックとして働いている。', 'あには ホテルの コックと して はたらいて いる。', 'Anh tôi làm đầu bếp ở khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9467, 39714, 'メニューを見せてください。', 'メニューを みせて ください。', 'Cho tôi xem thực đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9468, 39782, '年末に会社の宴会がある。', 'ねんまつに かいしゃの えんかいが ある。', 'Cuối năm công ty có tiệc liên hoan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9469, 39814, '肉はよく加熱してから食べてください。', 'にくは よく かねつ してから たべて ください。', 'Thịt hãy nấu chín kỹ rồi mới ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9470, 40078, '砂糖を小さじ一杯入れてください。', 'さとうを こさじ いっぱい いれて ください。', 'Hãy cho một thìa nhỏ đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9471, 40214, '話に夢中で、魚を焦がしてしまった。', 'はなしに むちゅうで、さかなを こがして しまった。', 'Mải nói chuyện nên tôi làm cháy cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9472, 40228, '野菜を蒸して食べるとおいしい。', 'やさいを むして たべると おいしい。', 'Rau hấp ăn rất ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9473, 40235, '食事の後、食器を洗った。', 'しょくじの あと、しょっきを あらった。', 'Ăn xong tôi rửa bát đĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9474, 40281, 'キャンプでは炊事を交代でした。', 'キャンプでは すいじを こうたいで した。', 'Đi cắm trại, chúng tôi thay phiên nhau nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9475, 43192, '植物は根から養分を吸収する。', 'しょくぶつは ねから ようぶんを きゅうしゅう する。', 'Cây hấp thụ chất dinh dưỡng qua rễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9476, 43210, '残ったご飯を冷凍しておいた。', 'のこった ごはんを れいとう して おいた。', 'Tôi cho cơm thừa vào ngăn đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9477, 39601, 'スチュワーデスが飲み物を配っている。', 'スチュワーデスが のみものを くばって いる。', 'Tiếp viên hàng không đang phát đồ uống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9478, 39722, '空港までモノレールで行った。', 'くうこうまで モノレールで いった。', 'Tôi đi tàu một ray ra sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9626, 40349, '着物には草履を合わせる。', 'きものには ぞうりを あわせる。', 'Mặc kimono thì đi dép zori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9479, 39772, '雨が強くなったので、途中で引き返した。', 'あめが つよく なったので、とちゅうで ひきかえした。', 'Mưa nặng hạt hơn nên tôi quay lại giữa đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9480, 39787, '小学校の遠足で動物園に行った。', 'しょうがっこうの えんそくで どうぶつえんに いった。', 'Chuyến dã ngoại của trường tiểu học đi sở thú.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9481, 40195, '駅前の書店で雑誌を買った。', 'えきまえの しょてんで ざっしを かった。', 'Tôi mua tạp chí ở hiệu sách trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9482, 40194, 'この店ではいろいろな書籍を売っている。', 'この みせでは いろいろな しょせきを うって いる。', 'Cửa hàng này bán nhiều loại sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9483, 40196, '小学生のころ、書道を習っていた。', 'しょうがくせいの ころ、しょどうを ならって いた。', 'Hồi tiểu học tôi từng học thư pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9484, 40201, '次の試合で勝負が決まる。', 'つぎの しあいで しょうぶが きまる。', 'Trận tiếp theo sẽ quyết định thắng thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9485, 42927, '知人の紹介で、この会社に入った。', 'ちじんの しょうかいで、この かいしゃに はいった。', 'Nhờ người quen giới thiệu, tôi vào công ty này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9486, 40206, 'ドアに小指をはさんでしまった。', 'ドアに こゆびを はさんで しまった。', 'Tôi bị kẹp ngón út vào cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9487, 40210, 'おかゆは消化がいい。', 'おかゆは しょうかが いい。', 'Cháo dễ tiêu hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9488, 40211, '傷口を消毒してから、ばんそうこうをはった。', 'きずぐちを しょうどく してから、ばんそうこうを はった。', 'Tôi sát trùng vết thương rồi dán băng cá nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9489, 40237, '冬は唇が乾燥しやすい。', 'ふゆは くちびるが かんそう しやすい。', 'Mùa đông môi dễ bị khô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9490, 40240, '温泉に入って、心身ともにリラックスできた。', 'おんせんに はいって、しんしん ともに リラックス できた。', 'Ngâm suối nước nóng, cả thể chất lẫn tinh thần đều thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9491, 40209, 'ご注文を承りました。', 'ごちゅうもんを うけたまわりました。', 'Chúng tôi đã nhận đơn đặt hàng của quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9492, 40241, '鍵がどこにあるか、心当たりはありますか。', 'かぎが どこに あるか、こころあたりは ありますか。', 'Bạn có manh mối gì về chỗ để chìa khóa không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9493, 40202, 'この町は商業の中心として発展した。', 'この まちは しょうぎょうの ちゅうしんと して はってん した。', 'Thị trấn này phát triển thành trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9494, 40203, '兄は大手の商社で働いている。', 'あには おおての しょうしゃで はたらいて いる。', 'Anh tôi làm ở một công ty thương mại lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9495, 40205, '子供のころ、毎月千円の小遣いをもらっていた。', 'こどもの ころ、まいつき せんえんの こづかいを もらって いた。', 'Hồi nhỏ tôi được cho một nghìn yên tiền tiêu vặt mỗi tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9496, 40233, 'この家具は職人が一つ一つ手で作っている。', 'この かぐは しょくにんが ひとつひとつ てで つくって いる。', 'Đồ nội thất này do thợ thủ công làm tay từng chiếc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9497, 39794, '欧米の文化に興味がある。', 'おうべいの ぶんかに きょうみが ある。', 'Tôi quan tâm đến văn hóa Âu Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9498, 39812, '車は坂の下で加速した。', 'くるまは さかの したで かそく した。', 'Chiếc xe tăng tốc ở chân dốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9499, 39831, '工事中なので、回り道をした。', 'こうじちゅう なので、まわりみちを した。', 'Đang thi công nên tôi đi đường vòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9500, 39843, '駅の改札の前で待っています。', 'えきの かいさつの まえで まって います。', 'Tôi đang đợi trước cổng soát vé ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9501, 39855, '街角でクリスマスソングが流れている。', 'まちかどで クリスマス ソングが ながれて いる。', 'Ở góc phố vang lên bài hát Giáng sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9502, 39889, '店の前に大きな看板が出ている。', 'みせの まえに おおきな かんばんが でて いる。', 'Trước cửa hàng có tấm biển hiệu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9503, 39895, '関東地方は今日、雪が降るそうだ。', 'かんとう ちほうは きょう、ゆきが ふる そうだ。', 'Nghe nói hôm nay vùng Kanto có tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9504, 29115, '急に雨が降り出しました。', 'きゅうに あめが ふりだしました。', 'Trời đột nhiên đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9505, 29121, '今でもその日のことを覚えています。', 'いまでも その ひの ことを おぼえて います。', 'Đến bây giờ tôi vẫn còn nhớ ngày hôm đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9506, 29136, 'みんなが彼のことをうわさしています。', 'みんなが かれの ことを うわさ して います。', 'Mọi người đang đồn đại về anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9507, 29673, 'ビールを三本買いました。', 'ビールを さんぼん かいました。', 'Tôi đã mua ba chai bia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9508, 29110, '兄はオートバイで会社へ行きます。', 'あには オートバイで かいしゃへ いきます。', 'Anh tôi đi làm bằng xe máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9509, 29138, '先生が本をくださいました。', 'せんせいが ほんを くださいました。', 'Thầy giáo đã tặng tôi một cuốn sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9510, 40243, 'パーティーでお客さんに料理を振る舞った。', 'パーティーで おきゃくさんに りょうりを ふるまった。', 'Tôi đãi khách món ăn trong bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9511, 40257, '彼は親指を立てて「いいね」と言った。', 'かれは おやゆびを たてて 「いいね」と いった。', 'Anh ấy giơ ngón cái lên và nói "tuyệt đấy".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9512, 40242, '彼はお客様への接し方をよく心得ている。', 'かれは おきゃくさまへの せっしかたを よく こころえて いる。', 'Anh ấy nắm rõ cách tiếp đãi khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9513, 40246, '待たせてしまって、申し訳ない。', 'またせて しまって、もうしわけない。', 'Thật có lỗi vì đã để bạn phải chờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9514, 40252, 'この袋は真空パックになっている。', 'この ふくろは しんくう パックに なって いる。', 'Túi này được đóng gói chân không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9515, 40009, '二本の道路が交差する所に信号がある。', 'にほんの どうろが こうさ する ところに しんごうが ある。', 'Chỗ hai con đường giao nhau có đèn tín hiệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9516, 40095, '次の四つ角を左に曲がってください。', 'つぎの よつかどを ひだりに まがって ください。', 'Đến ngã tư tiếp theo hãy rẽ trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9517, 40105, 'この町には私鉄の駅が二つある。', 'この まちには してつの えきが ふたつ ある。', 'Thị trấn này có hai ga đường sắt tư nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9518, 40136, '車掌が切符を調べに来た。', 'しゃしょうが きっぷを しらべに きた。', 'Người soát vé đến kiểm tra vé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9519, 40155, '駅の周辺は夜でもにぎやかだ。', 'えきの しゅうへんは よるでも にぎやかだ。', 'Khu vực quanh ga về đêm vẫn nhộn nhịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9520, 40187, '夏休みに京都のお寺を巡った。', 'なつやすみに きょうとの おてらを めぐった。', 'Kỳ nghỉ hè tôi đi một vòng các chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9521, 40224, '次の駅で乗り換えです。', 'つぎの えきで のりかえ です。', 'Ga tiếp theo là chỗ chuyển tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9522, 39941, '床に紙の屑が落ちている。', 'ゆかに かみの くずが おちて いる。', 'Trên sàn có vụn giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9523, 40015, '市長は公務で海外に出かけた。', 'しちょうは こうむで かいがいに でかけた。', 'Thị trưởng ra nước ngoài vì việc công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9524, 39678, 'かばんのファスナーが壊れた。', 'かばんの ファスナーが こわれた。', 'Khóa kéo của chiếc túi bị hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9525, 39741, '夏は涼しいワンピースをよく着る。', 'なつは すずしい ワンピースを よく きる。', 'Mùa hè tôi hay mặc váy liền thoáng mát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9526, 39819, 'この木は秋に赤い果実をつける。', 'この きは あきに あかい かじつを つける。', 'Cây này ra quả đỏ vào mùa thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9527, 47357, 'この会社にはいろいろな国籍の社員がいる。', 'この かいしゃには いろいろな こくせきの しゃいんが いる。', 'Công ty này có nhân viên mang nhiều quốc tịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9528, 40245, '深夜まで仕事をしていた。', 'しんやまで しごとを して いた。', 'Tôi làm việc đến tận đêm khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9529, 40250, '家に帰ると、真っ先に手を洗う。', 'いえに かえると、まっさきに てを あらう。', 'Về nhà là việc đầu tiên tôi làm là rửa tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9530, 40244, '話し合いで二人の理解が深まった。', 'はなしあいで ふたりの りかいが ふかまった。', 'Qua trò chuyện, hai người hiểu nhau sâu sắc hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9531, 40253, '子供は大人の話し方を真似る。', 'こどもは おとなの はなしかたを まねる。', 'Trẻ con bắt chước cách nói của người lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9532, 40248, '夏休みに日焼けして、真っ黒になった。', 'なつやすみに ひやけ して、まっくろに なった。', 'Kỳ nghỉ hè tôi bị cháy nắng đen thui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9533, 40251, '朝起きたら、外は雪で真っ白だった。', 'あさ おきたら、そとは ゆきで まっしろ だった。', 'Sáng dậy thấy bên ngoài trắng xóa tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9534, 40255, 'ギリシャ神話の本を読んでいる。', 'ギリシャ しんわの ほんを よんで いる。', 'Tôi đang đọc sách thần thoại Hy Lạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9535, 40283, 'この作家の随筆はやさしい言葉で書かれている。', 'この さっかの ずいひつは やさしい ことばで かかれて いる。', 'Tùy bút của nhà văn này được viết bằng lời lẽ giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9536, 40258, 'お盆には親類が集まる。', 'おぼんには しんるいが あつまる。', 'Dịp lễ Obon, họ hàng tụ họp lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9537, 40282, '駅のホームで酔っ払いが寝ていた。', 'えきの ホームで よっぱらいが ねて いた。', 'Có người say rượu nằm ngủ trên sân ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9538, 40261, '人差し指で地図の上を指した。', 'ひとさしゆびで ちずの うえを さした。', 'Tôi dùng ngón trỏ chỉ lên bản đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9539, 40265, '人命より大切なものはない。', 'じんめいより たいせつな ものは ない。', 'Không gì quý hơn tính mạng con người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9540, 40272, 'この寺は千年前に建てられたと推定されている。', 'この てらは せんねんまえに たてられたと すいてい されて いる。', 'Ngôi chùa này được ước tính đã xây từ một nghìn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9541, 40273, 'この町は水産業が盛んだ。', 'この まちは すいさんぎょうが さかんだ。', 'Thị trấn này phát triển ngành thủy sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9542, 40264, '哲学や歴史は人文科学に入る。', 'てつがくや れきしは じんぶん かがくに はいる。', 'Triết học và lịch sử thuộc khoa học nhân văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9543, 40267, '子供は動物の図鑑を見るのが好きだ。', 'こどもは どうぶつの ずかんを みるのが すきだ。', 'Trẻ con thích xem sách tranh về động vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9544, 40268, '図形の問題が苦手だ。', 'ずけいの もんだいが にがてだ。', 'Tôi kém các bài toán hình học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9545, 40269, '結果を図表にまとめた。', 'けっかを ずひょうに まとめた。', 'Tôi tổng hợp kết quả thành biểu đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9546, 40271, '二本の線が垂直に交わっている。', 'にほんの せんが すいちょくに まじわって いる。', 'Hai đường thẳng giao nhau vuông góc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9547, 40275, '水は水素と酸素でできている。', 'みずは すいそと さんそで できて いる。', 'Nước được tạo thành từ hydro và ô xy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9548, 40279, '棚を水平に取り付けた。', 'たなを すいへいに とりつけた。', 'Tôi lắp kệ cho nằm ngang bằng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9549, 40292, '答えは整数で書いてください。', 'こたえは せいすうで かいて ください。', 'Hãy viết đáp án dưới dạng số nguyên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9550, 47717, 'この会社にはいろいろな国籍の社員がいる。', 'この かいしゃには いろいろな こくせきの しゃいんが いる。', 'Công ty này có nhân viên mang nhiều quốc tịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9551, 39505, '寒い日は温かいうどんが食べたくなる。', 'さむい ひは あたたかい うどんが たべたく なる。', 'Ngày lạnh lại thèm bát udon nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9552, 39528, 'おいしかったので、ご飯をお代わりした。', 'おいしかったので、ごはんを おかわり した。', 'Ngon quá nên tôi xin thêm một bát cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9553, 39531, 'りんごを丸ごと齧った。', 'りんごを まるごと かじった。', 'Tôi cắn nguyên quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9554, 39594, 'リビングに新しいじゅうたんを敷いた。', 'リビングに あたらしい じゅうたんを しいた。', 'Tôi trải tấm thảm mới trong phòng khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9555, 39592, '赤ちゃんが指をしゃぶっている。', 'あかちゃんが ゆびを しゃぶって いる。', 'Em bé đang mút ngón tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9556, 39612, '駅で昔の友達と擦れ違った。', 'えきで むかしの ともだちと すれちがった。', 'Tôi đi lướt qua người bạn cũ ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9557, 39624, '婚約指輪にダイヤモンドがついている。', 'こんやく ゆびわに ダイヤモンドが ついて いる。', 'Nhẫn đính hôn có gắn kim cương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9558, 39663, 'このベッドはばねがよくきいている。', 'この ベッドは ばねが よく きいて いる。', 'Lò xo của chiếc giường này rất êm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9559, 40260, '針金でフェンスを直した。', 'はりがねで フェンスを なおした。', 'Tôi sửa hàng rào bằng dây thép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9560, 40277, '遠足に水筒を持っていった。', 'えんそくに すいとうを もって いった。', 'Đi dã ngoại tôi mang theo bình nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9561, 40303, '年下のくせに生意気なことを言うな。', 'としした の くせに なまいきな ことを いうな。', 'Nhỏ tuổi hơn mà dám nói láo xược thế à.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9562, 40312, '空港の税関で荷物を調べられた。', 'くうこうの ぜいかんで にもつを しらべられた。', 'Hành lý của tôi bị kiểm tra ở hải quan sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9563, 40305, 'ここに生年月日を書いてください。', 'ここに せいねんがっぴを かいて ください。', 'Hãy ghi ngày tháng năm sinh vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9564, 40309, 'この施設は青少年のために作られた。', 'この しせつは せいしょうねんの ために つくられた。', 'Cơ sở này được xây dành cho thanh thiếu niên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9565, 40304, '事故の生存者が見つかった。', 'じこの せいぞんしゃが みつかった。', 'Đã tìm thấy người sống sót trong vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9566, 40310, '顔が青白いけど、大丈夫?', 'かおが あおじろい けど、だいじょうぶ?', 'Mặt bạn xanh xao quá, có sao không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9567, 40313, 'あと一点で合格だったのに、惜しい。', 'あと いってんで ごうかく だったのに、おしい。', 'Chỉ thiếu một điểm là đỗ, tiếc thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9568, 40308, '二度と遅刻しないと誓った。', 'にどと ちこく しないと ちかった。', 'Tôi thề sẽ không bao giờ đi muộn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9569, 40294, '正方形の四つの辺は同じ長さだ。', 'せいほうけいの よっつの へんは おなじ ながさだ。', 'Bốn cạnh của hình vuông dài bằng nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9570, 40299, '下書きを清書してから提出した。', 'したがきを せいしょ してから ていしゅつ した。', 'Tôi chép sạch bản nháp rồi mới nộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9571, 39683, '白いブラウスに紺のスカートを合わせた。', 'しろい ブラウスに こんの スカートを あわせた。', 'Tôi phối áo sơ mi trắng với chân váy xanh đậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9572, 39686, 'プラスチックのごみを減らそう。', 'プラスチックの ごみを へらそう。', 'Hãy giảm rác thải nhựa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9573, 39696, 'ペンチで針金を曲げた。', 'ペンチで はりがねを まげた。', 'Tôi dùng kìm uốn sợi dây thép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9574, 39671, '果物にはビタミンがたくさん含まれている。', 'くだものには ビタミンが たくさん ふくまれて いる。', 'Hoa quả chứa nhiều vitamin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9575, 39668, 'ハンドルを右に切った。', 'ハンドルを みぎに きった。', 'Tôi bẻ lái sang phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9576, 39695, 'けが人はヘリコプターで病院に運ばれた。', 'けがにんは ヘリコプターで びょういんに はこばれた。', 'Người bị thương được đưa đến bệnh viện bằng trực thăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9577, 40297, '学校の正門の前で待ち合わせた。', 'がっこうの せいもんの まえで まちあわせた。', 'Chúng tôi hẹn nhau trước cổng chính của trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9578, 40300, '毎朝、駅の清掃が行われている。', 'まいあさ、えきの せいそうが おこなわれて いる。', 'Mỗi sáng nhà ga đều được dọn dẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9579, 40306, 'ご飯を茶碗に盛った。', 'ごはんを ちゃわんに もった。', 'Tôi xới cơm vào bát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9580, 40301, '赤ちゃんに初めて歯が生えた。', 'あかちゃんに はじめて はが はえた。', 'Em bé mọc chiếc răng đầu tiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9581, 40307, '生まれた年を西暦で書いてください。', 'うまれた としを せいれきで かいて ください。', 'Hãy ghi năm sinh theo dương lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9582, 29150, '日本語の文法は難しいです。', 'にほんごの ぶんぽうは むずかしい です。', 'Ngữ pháp tiếng Nhật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9583, 40295, '正味二時間で仕事が終わった。', 'しょうみ にじかんで しごとが おわった。', 'Thực chất chỉ hai tiếng là xong việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9584, 40293, '飛行機の整備に時間がかかっている。', 'ひこうきの せいびに じかんが かかって いる。', 'Việc bảo dưỡng máy bay đang mất thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9585, 40311, '先生が入ってくると、教室が静まった。', 'せんせいが はいって くると、きょうしつが しずまった。', 'Thầy giáo bước vào, cả lớp im phăng phắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9586, 40296, '駅の正面にホテルがある。', 'えきの しょうめんに ホテルが ある。', 'Đối diện mặt tiền nhà ga có một khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9587, 29160, '冬は手袋をして出かけます。', 'ふゆは てぶくろを して でかけます。', 'Mùa đông tôi đeo găng tay khi ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9588, 40330, '毎年海外旅行に行けるなんて、羨ましい。', 'まいとし かいがい りょこうに いける なんて、うらやましい。', 'Năm nào cũng được đi du lịch nước ngoài, thật đáng ghen tị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9703, 42972, '定規で長さを測った。', 'じょうぎで ながさを はかった。', 'Tôi dùng thước đo chiều dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9589, 40339, '彼は素直に自分の間違いを認めた。', 'かれは すなおに じぶんの まちがいを みとめた。', 'Anh ấy thật thà thừa nhận lỗi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9590, 40319, 'お盆には先祖のお墓参りをする。', 'おぼんには せんぞの おはかまいりを する。', 'Dịp Obon chúng tôi đi viếng mộ tổ tiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9591, 40336, '人類の祖先はアフリカで生まれたと言われる。', 'じんるいの そせんは アフリカで うまれたと いわれる。', 'Người ta cho rằng tổ tiên loài người khởi nguồn từ châu Phi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9592, 40338, '素人の私にはこの絵の価値がわからない。', 'しろうとの わたしには この えの かちが わからない。', 'Người ngoại đạo như tôi không hiểu giá trị bức tranh này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9593, 40331, '人を羨んでばかりいないで、自分も頑張ろう。', 'ひとを うらやんで ばかり いないで、じぶんも がんばろう。', 'Đừng chỉ ghen tị với người khác, hãy tự mình cố gắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9594, 40334, 'この授業の狙いは会話力を上げることだ。', 'この じゅぎょうの ねらいは かいわりょくを あげる ことだ。', 'Mục tiêu của giờ học này là nâng cao khả năng hội thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9595, 40344, '先生は早口で、聞き取れない。', 'せんせいは はやくちで、ききとれない。', 'Thầy nói nhanh quá, tôi nghe không kịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9596, 39698, 'このシャツはもうぼろぼろだ。', 'この シャツは もう ぼろぼろだ。', 'Chiếc áo này đã rách tả tơi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9597, 39806, 'お祭りに浴衣と下駄で出かけた。', 'おまつりに ゆかたと げたで でかけた。', 'Tôi mặc yukata và đi guốc gỗ đến lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9598, 39960, '窓の隙間から冷たい風が入ってくる。', 'まどの すきまから つめたい かぜが はいって くる。', 'Gió lạnh lùa vào qua khe cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9599, 39975, '空港で友達を見送った。', 'くうこうで ともだちを みおくった。', 'Tôi tiễn bạn ở sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9600, 40033, '運動会で綱引きをした。', 'うんどうかいで つなひきを した。', 'Ở hội thao chúng tôi chơi kéo co.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9601, 40081, '古い自転車に錆がついている。', 'ふるい じてんしゃに さびが ついて いる。', 'Chiếc xe đạp cũ bị gỉ sét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9602, 40087, '部屋が散らかっていて、恥ずかしい。', 'へやが ちらかって いて、はずかしい。', 'Phòng bừa bộn quá, thật xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9603, 40326, '扇子であおぐと、少し涼しくなる。', 'せんすで あおぐと、すこし すずしく なる。', 'Phẩy quạt xếp thì thấy mát hơn một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9604, 40327, '夏は扇風機をつけて寝る。', 'なつは せんぷうきを つけて ねる。', 'Mùa hè tôi bật quạt điện khi ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9605, 40329, '線路の上を歩いてはいけない。', 'せんろの うえを あるいては いけない。', 'Không được đi bộ trên đường ray.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9606, 40314, '赤道の近くは一年中暑い。', 'せきどうの ちかくは いちねんじゅう あつい。', 'Gần xích đạo thì nóng quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9607, 40318, '先々月から日本語を習っている。', 'せんせんげつから にほんごを ならって いる。', 'Tôi học tiếng Nhật từ hai tháng trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9608, 40315, 'お客様には笑顔で接してください。', 'おきゃくさまには えがおで せっして ください。', 'Hãy tiếp xúc với khách hàng bằng nụ cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9609, 40316, '台風が九州に接近している。', 'たいふうが きゅうしゅうに せっきん して いる。', 'Bão đang tiến gần đến Kyushu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9610, 40328, '海に潜って、魚を見た。', 'うみに もぐって、さかなを みた。', 'Tôi lặn xuống biển ngắm cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9611, 40341, '写真を見て、昔の記憶が蘇った。', 'しゃしんを みて、むかしの きおくが よみがえった。', 'Nhìn bức ảnh, ký ức xưa lại sống dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9612, 40324, '鉛筆の先が尖っている。', 'えんぴつの さきが とがって いる。', 'Đầu bút chì nhọn hoắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9613, 40352, '転勤する先輩に送別の花束を贈った。', 'てんきん する せんぱいに そうべつの はなたばを おくった。', 'Chúng tôi tặng bó hoa tiễn biệt đàn anh chuyển công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9614, 40357, '犯人が憎い。', 'はんにんが にくい。', 'Tôi căm ghét thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9615, 40358, '罪を憎んで人を憎まず。', 'つみを にくんで ひとを にくまず。', 'Ghét tội chứ không ghét người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9616, 40359, '弟は憎らしいことばかり言う。', 'おとうとは にくらしい こと ばかり いう。', 'Em trai tôi toàn nói những câu đáng ghét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9617, 40353, '五千円以上買うと、送料が無料になる。', 'ごせんえん いじょう かうと、そうりょうが むりょうに なる。', 'Mua từ năm nghìn yên trở lên thì được miễn phí vận chuyển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9618, 40360, 'この港町は造船で栄えた。', 'この みなとまちは ぞうせんで さかえた。', 'Thị trấn cảng này hưng thịnh nhờ nghề đóng tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9619, 40368, '損得を考えずに人を助けたい。', 'そんとくを かんがえずに ひとを たすけたい。', 'Tôi muốn giúp người mà không tính toán thiệt hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9620, 40351, '送り仮名を間違えないように気をつけよう。', 'おくりがなを まちがえない ように きを つけよう。', 'Hãy cẩn thận đừng viết sai phần kana đi kèm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9621, 40361, '工事の前に土地を測量した。', 'こうじの まえに とちを そくりょう した。', 'Trước khi thi công, người ta đã đo đạc khu đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9622, 40259, '昔は身分によって職業が決まっていた。', 'むかしは みぶんに よって しょくぎょうが きまって いた。', 'Ngày xưa nghề nghiệp được quyết định theo thân phận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9623, 40290, '新しい政党が選挙で議席を増やした。', 'あたらしい せいとうが せんきょで ぎせきを ふやした。', 'Đảng mới đã tăng số ghế trong cuộc bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9624, 40266, 'ちり紙で鼻をかんだ。', 'ちりがみで はなを かんだ。', 'Tôi xì mũi bằng giấy lau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9625, 40348, '総理大臣が記者の質問に答えた。', 'そうり だいじんが きしゃの しつもんに こたえた。', 'Thủ tướng trả lời câu hỏi của phóng viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9627, 40363, '船は全速力で港に向かった。', 'ふねは ぜんそくりょくで みなとに むかった。', 'Con tàu chạy hết tốc lực về cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9628, 40355, '人口の増減を調べた。', 'じんこうの ぞうげんを しらべた。', 'Tôi tìm hiểu sự tăng giảm dân số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9629, 40356, '医療費が年々増大している。', 'いりょうひが ねんねん ぞうだい して いる。', 'Chi phí y tế tăng lên qua từng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9630, 40346, '二つのチームが優勝を争っている。', 'ふたつの チームが ゆうしょうを あらそって いる。', 'Hai đội đang tranh chức vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9631, 40366, '全員揃ったら、出発しましょう。', 'ぜんいん そろったら、しゅっぱつ しましょう。', 'Đông đủ mọi người rồi thì xuất phát nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9632, 40367, '玄関で靴を揃えて脱いだ。', 'げんかんで くつを そろえて ぬいだ。', 'Tôi cởi giày và xếp ngay ngắn ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9633, 40354, '駅前はいつも騒々しい。', 'えきまえは いつも そうぞうしい。', 'Trước ga lúc nào cũng ồn ào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9634, 40350, '祖父の葬式に親戚が集まった。', 'そふの そうしきに しんせきが あつまった。', 'Họ hàng tụ họp trong đám tang của ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9635, 40347, '二人の意見には大きな相違がある。', 'ふたりの いけんには おおきな そういが ある。', 'Ý kiến của hai người có khác biệt lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9636, 29162, '寒いので、暖房をつけました。', 'さむいので、だんぼうを つけました。', 'Lạnh quá nên tôi bật máy sưởi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9637, 40362, '雪の上に動物の足跡が残っている。', 'ゆきの うえに どうぶつの あしあとが のこって いる。', 'Trên tuyết còn in dấu chân động vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9638, 40364, '私はテニス部に属しています。', 'わたしは テニスぶに ぞくして います。', 'Tôi thuộc câu lạc bộ tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9639, 42918, 'その本の題名を忘れてしまった。', 'その ほんの だいめいを わすれて しまった。', 'Tôi quên mất tựa đề cuốn sách đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9640, 42893, '彼女は仕事も家事もこなすスーパーウーマンだ。', 'かのじょは しごとも かじも こなす スーパーウーマンだ。', 'Cô ấy là siêu phụ nữ, cân cả công việc lẫn việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9641, 42903, '子供が夜中に小便に起きた。', 'こどもが よなかに しょうべんに おきた。', 'Đứa bé nửa đêm dậy đi tè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9642, 42908, '毎朝ラジオ体操をしている。', 'まいあさ ラジオ たいそうを して いる。', 'Sáng nào tôi cũng tập thể dục theo đài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9643, 42913, '大工さんが家を建てている。', 'だいくさんが いえを たてて いる。', 'Bác thợ mộc đang dựng nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9644, 42906, '地球は太陽の周りを楕円の形で回っている。', 'ちきゅうは たいようの まわりを だえんの かたちで まわって いる。', 'Trái đất quay quanh mặt trời theo quỹ đạo hình elip.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9645, 42907, 'この箱の体積を求めなさい。', 'この はこの たいせきを もとめなさい。', 'Hãy tính thể tích chiếc hộp này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9646, 42912, '「これ」や「それ」は代名詞だ。', '「これ」や 「それ」は だいめいしだ。', '"Kore" và "sore" là đại từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9647, 42920, '英語では単数と複数で形が変わる。', 'えいごでは たんすうと ふくすうで かたちが かわる。', 'Trong tiếng Anh, từ đổi hình thức theo số ít và số nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9648, 42910, 'この辺りには貸家が多い。', 'この あたりには かしやが おおい。', 'Quanh đây có nhiều nhà cho thuê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9649, 42911, '駅の近くに貸間を見つけた。', 'えきの ちかくに かしまを みつけた。', 'Tôi tìm được một phòng cho thuê gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9650, 30993, 'チームの守備を強化する必要がある。', 'チームの しゅびを きょうか する ひつようが ある。', 'Cần củng cố hàng phòng ngự của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9651, 40239, '寝台列車で北海道まで行った。', 'しんだい れっしゃで ほっかいどうまで いった。', 'Tôi đi tàu giường nằm đến Hokkaido.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9652, 40263, 'この道は夜になると人通りが少ない。', 'この みちは よるに なると ひとどおりが すくない。', 'Con đường này về đêm ít người qua lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9653, 42971, '通学のために定期券を買った。', 'つうがくの ために ていきけんを かった。', 'Tôi mua vé tháng để đi học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9654, 42979, 'この通りには小さな店屋が並んでいる。', 'この とおりには ちいさな みせやが ならんで いる。', 'Con phố này có nhiều cửa hàng nhỏ san sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9655, 42909, '病院の待合室で名前を呼ばれるのを待った。', 'びょういんの まちあいしつで なまえを よばれるのを まった。', 'Tôi chờ được gọi tên ở phòng chờ bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9656, 42915, '大通りに出れば、タクシーがすぐ見つかる。', 'おおどおりに でれば、タクシーが すぐ みつかる。', 'Ra đại lộ là bắt được taxi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9657, 42917, '神社の前に大木が立っている。', 'じんじゃの まえに たいぼくが たって いる。', 'Trước đền có một cây cổ thụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9658, 42919, '山の奥に大きな滝がある。', 'やまの おくに おおきな たきが ある。', 'Sâu trong núi có một thác nước lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9659, 42904, '水曜は午後から休みです。', 'すいようは ごごから やすみ です。', 'Thứ tư được nghỉ từ buổi chiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9660, 29168, 'お孫さんは何人いらっしゃいますか。', 'おまごさんは なんにん いらっしゃいますか。', 'Bà có mấy đứa cháu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9661, 42914, '大小さまざまな箱が並んでいる。', 'だいしょう さまざまな はこが ならんで いる。', 'Đủ loại hộp lớn nhỏ được xếp thành hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9662, 42902, '年賀状を百枚刷った。', 'ねんがじょうを ひゃくまい すった。', 'Tôi in một trăm tấm thiệp chúc Tết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9663, 42905, 'お祭りで太鼓の音が響いている。', 'おまつりで たいこの おとが ひびいて いる。', 'Tiếng trống vang lên trong lễ hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9664, 42896, 'おやすみ。また明日ね。', 'おやすみ。また あしたね。', 'Ngủ ngon nhé. Mai gặp lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9665, 42899, 'やっぱり家のご飯が一番だ。', 'やっぱり いえの ごはんが いちばんだ。', 'Quả nhiên cơm nhà vẫn là ngon nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9666, 29172, '八百屋のおばさんに野菜をもらいました。', 'やおやの おばさんに やさいを もらいました。', 'Tôi được cô bán rau cho ít rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9667, 42935, '冬に備えて食料を蓄えた。', 'ふゆに そなえて しょくりょうを たくわえた。', 'Chúng tôi dự trữ lương thực cho mùa đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9668, 42933, '彼女はいつも地味な色の服を着ている。', 'かのじょは いつも じみな いろの ふくを きて いる。', 'Cô ấy lúc nào cũng mặc đồ màu giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9669, 42943, '中年になると、太りやすくなる。', 'ちゅうねんに なると、ふとりやすく なる。', 'Đến tuổi trung niên thì dễ béo lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9670, 42944, 'けんかした友達とやっと仲直りした。', 'けんか した ともだちと やっと なかなおり した。', 'Cuối cùng tôi cũng làm hòa với người bạn đã cãi nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9671, 42945, 'あの二人は小さいころから仲良しだ。', 'あの ふたりは ちいさい ころから なかよしだ。', 'Hai người đó thân nhau từ nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9672, 42939, '中指に指輪をしている。', 'なかゆびに ゆびわを して いる。', 'Tôi đeo nhẫn ở ngón giữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9673, 42954, 'この角は直角だ。', 'この かどは ちょっかくだ。', 'Góc này là góc vuông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9674, 42937, '旅行に着替えを三日分持っていく。', 'りょこうに きがえを みっかぶん もって いく。', 'Đi du lịch tôi mang quần áo thay cho ba ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9675, 42946, '日曜日の午後は昼寝をした。', 'にちようびの ごごは ひるねを した。', 'Chiều chủ nhật tôi ngủ trưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9676, 43026, '日帰りで温泉に行ってきた。', 'ひがえりで おんせんに いって きた。', 'Tôi đi suối nước nóng về trong ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9677, 43068, '道路の標識をよく見て運転しよう。', 'どうろの ひょうしきを よく みて うんてん しよう。', 'Hãy chú ý biển báo khi lái xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9678, 43144, 'この町の名物はうどんだ。', 'この まちの めいぶつは うどんだ。', 'Đặc sản của thị trấn này là mì udon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9679, 43184, '駅前の洋品店でシャツを買った。', 'えきまえの ようひんてんで シャツを かった。', 'Tôi mua áo sơ mi ở cửa hàng đồ Tây trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9680, 43195, '有名な歌手が来月来日する。', 'ゆうめいな かしゅが らいげつ らいにち する。', 'Một ca sĩ nổi tiếng sẽ sang Nhật vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9681, 39629, '雨が少なくて、ダムの水が減っている。', 'あめが すくなくて、ダムの みずが へって いる。', 'Ít mưa nên nước trong đập đang cạn dần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9682, 39797, '雨の日は屋外の活動が中止になる。', 'あめの ひは おくがいの かつどうが ちゅうしに なる。', 'Ngày mưa các hoạt động ngoài trời bị hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9683, 42930, 'この辺りは工業地帯だ。', 'この あたりは こうぎょう ちたいだ。', 'Quanh đây là khu công nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9684, 42931, 'ここがマラソンの折り返し地点です。', 'ここが マラソンの おりかえし ちてん です。', 'Đây là điểm quay đầu của cuộc thi marathon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9685, 42934, 'この地名の読み方は難しい。', 'この ちめいの よみかたは むずかしい。', 'Cách đọc tên địa danh này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9686, 42928, 'この町では地下水を飲み水にしている。', 'この まちでは ちかすいを のみみずに して いる。', 'Thị trấn này dùng nước ngầm làm nước uống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9687, 42929, '地質を調べてから、家を建てる。', 'ちしつを しらべてから、いえを たてる。', 'Khảo sát địa chất xong mới xây nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9688, 42932, 'この辺りは地盤が弱い。', 'この あたりは じばんが よわい。', 'Nền đất quanh đây yếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9689, 42940, '試験は七月中旬に行われる。', 'しけんは しちがつ ちゅうじゅんに おこなわれる。', 'Kỳ thi diễn ra vào giữa tháng bảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9690, 42941, 'この城は中世に建てられた。', 'この しろは ちゅうせいに たてられた。', 'Lâu đài này được xây vào thời trung cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9691, 42942, '仕事を中途で投げ出してはいけない。', 'しごとを ちゅうとで なげだしては いけない。', 'Không được bỏ dở công việc giữa chừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9692, 42938, '駅と学校の中間に公園がある。', 'えきと がっこうの ちゅうかんに こうえんが ある。', 'Giữa ga và trường có một công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9693, 42961, '会議で社長の通訳をした。', 'かいぎで しゃちょうの つうやくを した。', 'Tôi phiên dịch cho giám đốc trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9694, 42980, 'テストの点数が思ったより悪かった。', 'テストの てんすうが おもったより わるかった。', 'Điểm bài kiểm tra tệ hơn tôi nghĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9695, 42951, '長女は今年大学に入った。', 'ちょうじょは ことし だいがくに はいった。', 'Con gái cả của tôi năm nay vào đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9696, 42968, '毎朝ひげを剃っている。', 'まいあさ ひげを そって いる。', 'Sáng nào tôi cũng cạo râu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9697, 42960, '銀行で通帳を作った。', 'ぎんこうで つうちょうを つくった。', 'Tôi mở sổ ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9698, 42973, 'この店は毎週水曜日が定休日だ。', 'この みせは まいしゅう すいようびが ていきゅうびだ。', 'Cửa hàng này nghỉ cố định vào thứ tư hằng tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9699, 42982, '五月に家族で田植えをした。', 'ごがつに かぞくで たうえを した。', 'Tháng năm cả nhà cùng đi cấy lúa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9700, 42953, '長方形の面積は縦かける横で求める。', 'ちょうほうけいの めんせきは たて かける よこで もとめる。', 'Diện tích hình chữ nhật bằng chiều dài nhân chiều rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9701, 42955, 'このピザは直径三十センチある。', 'この ピザは ちょっけい さんじゅっセンチ ある。', 'Chiếc pizza này có đường kính ba mươi phân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9702, 42956, '定規を使って直線を引いた。', 'じょうぎを つかって ちょくせんを ひいた。', 'Tôi dùng thước kẻ một đường thẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9704, 42977, '鉄砲は十六世紀に日本に伝わった。', 'てっぽうは じゅうろく せいきに にほんに つたわった。', 'Súng được truyền vào Nhật Bản vào thế kỷ 16.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9705, 42978, '天皇の誕生日は祝日だ。', 'てんのうの たんじょうびは しゅくじつだ。', 'Sinh nhật Nhật hoàng là ngày lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9706, 42967, '雷で停電になった。', 'かみなりで ていでんに なった。', 'Sấm sét làm mất điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9707, 42969, '剃刀でひげを剃った。', 'かみそりで ひげを そった。', 'Tôi cạo râu bằng dao cạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9708, 42974, '壁に釘を打って、絵をかけた。', 'かべに くぎを うって、えを かけた。', 'Tôi đóng đinh lên tường để treo tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9709, 42983, '切れた電球を取り替えた。', 'きれた でんきゅうを とりかえた。', 'Tôi thay bóng đèn bị cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9710, 39798, '温室でトマトを育てている。', 'おんしつで トマトを そだてて いる。', 'Tôi trồng cà chua trong nhà kính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9711, 39836, '運動会の日は快晴だった。', 'うんどうかいの ひは かいせい だった。', 'Ngày hội thao trời quang mây tạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9712, 39846, '海洋のごみが問題になっている。', 'かいようの ごみが もんだいに なって いる。', 'Rác thải đại dương đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9713, 39902, '台風が近づくと、気圧が下がる。', 'たいふうが ちかづくと、きあつが さがる。', 'Bão đến gần thì áp suất khí quyển giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9714, 40011, '強い光線から目を守るために、サングラスをかける。', 'つよい こうせんから めを まもる ために、サングラスを かける。', 'Tôi đeo kính râm để bảo vệ mắt khỏi tia sáng mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9715, 40125, '秋には稲が実る。', 'あきには いねが みのる。', 'Mùa thu lúa chín.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9716, 40229, 'やかんから蒸気が出ている。', 'やかんから じょうきが でて いる。', 'Hơi nước bốc ra từ ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9717, 40232, '毎朝、植木に水をやっている。', 'まいあさ、うえきに みずを やって いる。', 'Sáng nào tôi cũng tưới cây cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9718, 40274, '水蒸気が冷えて雲になる。', 'すいじょうきが ひえて くもに なる。', 'Hơi nước gặp lạnh thành mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9719, 42963, '通路に荷物を置かないでください。', 'つうろに にもつを おかないで ください。', 'Xin đừng để hành lý ở lối đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9720, 42985, 'ここは電波が弱くて、電話がつながらない。', 'ここは でんぱが よわくて、でんわが つながらない。', 'Ở đây sóng yếu nên không gọi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9721, 42999, '今日は私が掃除の当番だ。', 'きょうは わたしが そうじの とうばんだ。', 'Hôm nay đến phiên tôi trực nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9722, 42993, '自転車の盗難に気をつけてください。', 'じてんしゃの とうなんに きを つけて ください。', 'Hãy cẩn thận bị trộm xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9723, 42997, '冬はストーブの灯油をよく買う。', 'ふゆは ストーブの とうゆを よく かう。', 'Mùa đông tôi hay mua dầu hỏa cho lò sưởi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9724, 42994, '湯飲みにお茶を入れた。', 'ゆのみに おちゃを いれた。', 'Tôi rót trà vào chén.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9725, 40278, '暑い日は水分をしっかりとりましょう。', 'あつい ひは すいぶんを しっかり とりましょう。', 'Ngày nóng hãy uống đủ nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9726, 40284, '春は杉の花粉で鼻がむずむずする。', 'はるは すぎの かふんで はなが むずむず する。', 'Mùa xuân phấn hoa tuyết tùng làm tôi ngứa mũi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9727, 43011, '峠を越えると、町が見えてきた。', 'とうげを こえると、まちが みえて きた。', 'Qua khỏi con đèo thì thấy thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9728, 43020, '南極にはペンギンがすんでいる。', 'なんきょくには ペンギンが すんで いる。', 'Ở Nam Cực có chim cánh cụt sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9729, 43024, '暑いので、日陰で休もう。', 'あついので、ひかげで やすもう。', 'Nóng quá, nghỉ trong bóng râm đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9730, 43035, '農村では若い人が減っている。', 'のうそんでは わかい ひとが へって いる。', 'Ở nông thôn, người trẻ ngày càng ít.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9731, 43123, '北極の氷が溶けている。', 'ほっきょくの こおりが とけて いる。', 'Băng ở Bắc Cực đang tan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9732, 43129, '京都は盆地なので、夏は暑く冬は寒い。', 'きょうとは ぼんち なので、なつは あつく ふゆは さむい。', 'Kyoto nằm trong lòng chảo nên hè nóng, đông lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9733, 43177, '海に沈む夕日を見た。', 'うみに しずむ ゆうひを みた。', 'Tôi ngắm mặt trời lặn xuống biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9734, 43187, '火山から溶岩が流れ出た。', 'かざんから ようがんが ながれでた。', 'Dung nham chảy ra từ núi lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9735, 43202, 'この川の流域には多くの町がある。', 'この かわの りゅういきには おおくの まちが ある。', 'Lưu vực con sông này có nhiều thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9736, 43213, '日本列島に台風が近づいている。', 'にほん れっとうに たいふうが ちかづいて いる。', 'Bão đang tiến gần quần đảo Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9737, 39574, 'さきおととい、友達が遊びに来た。', 'さきおととい、ともだちが あそびに きた。', 'Ba hôm trước bạn tôi đến chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9738, 42989, '都心まで電車で三十分かかる。', 'としんまで でんしゃで さんじゅっぷん かかる。', 'Đi tàu vào trung tâm thành phố mất ba mươi phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9739, 29181, '祖母はよく昔話をしてくれました。', 'そぼは よく むかしばなしを して くれました。', 'Bà hay kể truyện cổ tích cho tôi nghe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9740, 42991, 'この道は町を東西に走っている。', 'この みちは まちを とうざいに はしって いる。', 'Con đường này chạy theo hướng đông tây qua thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9741, 42992, '東洋の文化に興味を持つ外国人が増えた。', 'とうようの ぶんかに きょうみを もつ がいこくじんが ふえた。', 'Ngày càng nhiều người nước ngoài quan tâm đến văn hóa phương Đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9742, 43002, '踏切を渡るときは、左右をよく見よう。', 'ふみきりを わたる ときは、さゆうを よく みよう。', 'Khi băng qua đường ngang xe lửa hãy nhìn kỹ hai bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9743, 42998, 'チケットは当日でも買えます。', 'チケットは とうじつでも かえます。', 'Vé có thể mua ngay trong ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9744, 43003, 'この川の水は透き通っている。', 'この かわの みずは すきとおって いる。', 'Nước sông này trong vắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9745, 42986, '電線に電流が流れている。', 'でんせんに でんりゅうが ながれて いる。', 'Dòng điện đang chạy trong dây điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9746, 42987, '夏は電力の使用量が増える。', 'なつは でんりょくの しようりょうが ふえる。', 'Mùa hè lượng điện tiêu thụ tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9747, 43005, '彼は優れた頭脳の持ち主だ。', 'かれは すぐれた ずのうの もちぬしだ。', 'Anh ấy là người có bộ óc xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9748, 43008, '赤ちゃんの瞳はとてもきれいだ。', 'あかちゃんの ひとみは とても きれいだ。', 'Đôi mắt em bé thật trong sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9749, 43017, '熱があるので、内科に行った。', 'ねつが あるので、ないかに いった。', 'Bị sốt nên tôi đến khoa nội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9750, 43016, '彼は呑気な性格で、あまり悩まない。', 'かれは のんきな せいかくで、あまり なやまない。', 'Anh ấy tính vô tư, ít khi phiền muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9751, 43014, '祖父はよく独り言を言っている。', 'そふは よく ひとりごとを いって いる。', 'Ông tôi hay nói lẩm bẩm một mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9752, 43013, 'スーパーで卵の特売をしている。', 'スーパーで たまごの とくばいを して いる。', 'Siêu thị đang bán giảm giá trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9753, 43030, '今年の四月に入社しました。', 'ことしの しがつに にゅうしゃ しました。', 'Tôi vào công ty từ tháng tư năm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9754, 43033, '朝のほうが仕事の能率が上がる。', 'あさの ほうが しごとの のうりつが あがる。', 'Buổi sáng làm việc hiệu suất cao hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9755, 43036, 'この野菜は農薬を使わずに作った。', 'この やさいは のうやくを つかわずに つくった。', 'Rau này được trồng mà không dùng thuốc trừ sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9756, 43007, 'この二つのチームは実力が同格だ。', 'この ふたつの チームは じつりょくが どうかくだ。', 'Hai đội này có thực lực ngang nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9757, 43032, 'この薬は濃度が高いので、水で薄めて使う。', 'この くすりは のうどが たかいので、みずで うすめて つかう。', 'Thuốc này nồng độ cao nên pha loãng với nước rồi dùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9758, 43025, '朝の散歩が祖父の日課だ。', 'あさの さんぽが そふの にっかだ。', 'Đi dạo buổi sáng là thói quen hằng ngày của ông tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9759, 43029, 'スーパーで日用品をまとめて買った。', 'スーパーで にちようひんを まとめて かった。', 'Tôi mua một lượt đồ dùng hằng ngày ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9760, 43034, 'この地方の農産物は全国に出荷されている。', 'この ちほうの のうさんぶつは ぜんこくに しゅっか されて いる。', 'Nông sản vùng này được chuyển đi khắp cả nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9761, 39580, 'スキーのシーズンが始まった。', 'スキーの シーズンが はじまった。', 'Mùa trượt tuyết đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9762, 39755, '一昨日、お電話をいただいた件ですが。', 'いっさくじつ、おでんわを いただいた けん ですが。', 'Về việc anh đã gọi điện hôm kia ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9763, 39757, 'ベルが鳴ると、学生たちは一斉に立ち上がった。', 'ベルが なると、がくせいたちは いっせいに たちあがった。', 'Chuông reo, học sinh đồng loạt đứng dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9764, 43010, '駅からの道順を地図に書いた。', 'えきからの みちじゅんを ちずに かいた。', 'Tôi vẽ lộ trình từ ga lên bản đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9765, 43021, 'いつか南米を旅行したい。', 'いつか なんべいを りょこう したい。', 'Một ngày nào đó tôi muốn du lịch Nam Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9766, 43022, '日本は南北に長い国だ。', 'にほんは なんぼくに ながい くにだ。', 'Nhật Bản là đất nước trải dài theo hướng nam bắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9767, 29189, 'お姫様はお城に住んでいました。', 'おひめさまは おしろに すんで いました。', 'Công chúa sống trong lâu đài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9768, 29193, '箱を開けると、白い煙が出てきました。', 'はこを あけると、しろい けむりが でて きました。', 'Mở hộp ra thì khói trắng bốc lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9769, 29204, '旅行の間、犬を預かってもらえませんか。', 'りょこうの あいだ、いぬを あずかって もらえませんか。', 'Trong lúc tôi đi du lịch, anh giữ giùm con chó được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9770, 29200, '新しいバッグを買いました。', 'あたらしい バッグを かいました。', 'Tôi đã mua chiếc túi xách mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9771, 29212, '電卓で計算しました。', 'でんたくで けいさん しました。', 'Tôi tính bằng máy tính bỏ túi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9772, 29217, 'ベートーベンは有名な音楽家です。', 'ベートーベンは ゆうめいな おんがくか です。', 'Beethoven là nhạc sĩ nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9773, 43058, '失敗の原因をよく反省した。', 'しっぱいの げんいんを よく はんせい した。', 'Tôi đã tự kiểm điểm kỹ nguyên nhân thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9774, 43057, '伊豆半島は温泉で有名だ。', 'いず はんとうは おんせんで ゆうめいだ。', 'Bán đảo Izu nổi tiếng với suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9775, 43053, 'この川の水を使って発電している。', 'この かわの みずを つかって はつでん して いる。', 'Người ta dùng nước sông này để phát điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9776, 43047, '最近、白髪が増えてきた。', 'さいきん、しらがが ふえて きた。', 'Gần đây tóc bạc nhiều lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9777, 43044, 'インターネットで中古品の売買をしている。', 'インターネットで ちゅうこひんの ばいばいを して いる。', 'Tôi mua bán đồ cũ trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9778, 43054, '新しいゲームが明日発売される。', 'あたらしい ゲームが あした はつばい される。', 'Trò chơi mới sẽ được mở bán vào ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9779, 43056, '半径五キロ以内の地域に避難の指示が出た。', 'はんけい ごキロ いないの ちいきに ひなんの しじが でた。', 'Lệnh sơ tán được ban ra cho khu vực trong bán kính năm cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9780, 43055, '判事が判決を言い渡した。', 'はんじが はんけつを いいわたした。', 'Thẩm phán đã tuyên án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9781, 43046, '秤で小麦粉を量った。', 'はかりで こむぎこを はかった。', 'Tôi cân bột mì bằng cái cân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9782, 43051, '寒いので、暖かい肌着を着た。', 'さむいので、あたたかい はだぎを きた。', 'Trời lạnh nên tôi mặc áo lót giữ nhiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9783, 39827, 'にわか雨に降られた。', 'にわかあめに ふられた。', 'Tôi bị dính cơn mưa bất chợt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9784, 40098, '彼は始終文句を言っている。', 'かれは しじゅう もんくを いって いる。', 'Anh ta lúc nào cũng than phiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9785, 40223, '来月上旬に引っ越す予定だ。', 'らいげつ じょうじゅんに ひっこす よていだ。', 'Đầu tháng sau tôi định chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9786, 42950, '会議が長引いて、帰りが遅くなった。', 'かいぎが ながびいて、かえりが おそく なった。', 'Cuộc họp kéo dài nên tôi về muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9787, 43031, '日本の学校は四月から新年度が始まる。', 'にほんの がっこうは しがつから しんねんどが はじまる。', 'Ở Nhật, năm học mới bắt đầu từ tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9788, 39616, 'この一年で背が五センチ伸びた。', 'この いちねんで せが ごセンチ のびた。', 'Một năm qua tôi cao thêm năm phân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9789, 39700, '今朝の気温はマイナス五度だった。', 'けさの きおんは マイナス ごど だった。', 'Nhiệt độ sáng nay là âm năm độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9790, 39732, '毎日水を二リットル飲んでいる。', 'まいにち みずを にリットル のんで いる。', 'Mỗi ngày tôi uống hai lít nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9791, 39737, '自分のレベルに合ったクラスを選んだ。', 'じぶんの レベルに あった クラスを えらんだ。', 'Tôi chọn lớp phù hợp với trình độ của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9792, 43059, '住所の番地まで書いてください。', 'じゅうしょの ばんちまで かいて ください。', 'Hãy ghi địa chỉ đến cả số nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9793, 43045, '赤ちゃんが床を這っている。', 'あかちゃんが ゆかを はって いる。', 'Em bé đang bò trên sàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9794, 43049, '締め切りが迫っている。', 'しめきりが せまって いる。', 'Hạn chót đang đến gần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9795, 43050, '古い新聞をひもで縛った。', 'ふるい しんぶんを ひもで しばった。', 'Tôi buộc báo cũ bằng dây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9796, 43052, '本番で実力を発揮できた。', 'ほんばんで じつりょくを はっき できた。', 'Tôi đã phát huy được thực lực trong buổi diễn chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9797, 43048, '夕方になって、部屋が薄暗くなった。', 'ゆうがたに なって、へやが うすぐらく なった。', 'Chiều xuống, căn phòng trở nên mờ tối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9798, 29236, '結婚のお祝いをのし袋に入れました。', 'けっこんの おいわいを のしぶくろに いれました。', 'Tôi bỏ tiền mừng cưới vào phong bao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9799, 29246, 'ピアノで「エリーゼのために」を弾きました。', 'ピアノで 「エリーゼの ために」を ひきました。', 'Tôi chơi bản "Für Elise" trên đàn piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9800, 43062, '日焼けで皮膚が赤くなった。', 'ひやけで ひふが あかく なった。', 'Da bị đỏ vì cháy nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9801, 43063, '姉は美容のために毎日野菜を食べている。', 'あねは びようの ために まいにち やさいを たべて いる。', 'Chị tôi ăn rau mỗi ngày để làm đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9802, 43064, '机の角に肘をぶつけた。', 'つくえの かどに ひじを ぶつけた。', 'Tôi bị va khuỷu tay vào góc bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9803, 43060, '後ろから攻撃するなんて、卑怯だ。', 'うしろから こうげき する なんて、ひきょうだ。', 'Tấn công từ phía sau thật hèn hạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9804, 43071, '新聞に映画の評論が載っていた。', 'しんぶんに えいがの ひょうろんが のって いた。', 'Trên báo có đăng bài bình luận phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9805, 43066, '試験は筆記と面接があります。', 'しけんは ひっきと めんせつが あります。', 'Kỳ thi gồm phần viết và phỏng vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9806, 43069, '博物館で昆虫の標本を見た。', 'はくぶつかんで こんちゅうの ひょうほんを みた。', 'Tôi xem mẫu vật côn trùng ở bảo tàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9807, 43080, '漢字の部首を覚えると、意味が推測しやすい。', 'かんじの ぶしゅを おぼえると、いみが すいそく しやすい。', 'Nhớ bộ thủ thì dễ đoán nghĩa chữ Hán hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9808, 43085, '物差しで机の長さを測った。', 'ものさしで つくえの ながさを はかった。', 'Tôi dùng thước đo chiều dài cái bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9809, 43089, '分数の足し算を練習した。', 'ぶんすうの たしざんを れんしゅう した。', 'Tôi luyện phép cộng phân số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9810, 43095, '論文を書くために、多くの文献を読んだ。', 'ろんぶんを かく ために、おおくの ぶんけんを よんだ。', 'Để viết luận văn, tôi đã đọc nhiều tài liệu tham khảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9811, 43097, '新学期の前に文房具をそろえた。', 'しんがっきの まえに ぶんぼうぐを そろえた。', 'Trước học kỳ mới tôi sắm đủ văn phòng phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9812, 43098, '文脈から言葉の意味を考えなさい。', 'ぶんみゃくから ことばの いみを かんがえなさい。', 'Hãy suy ra nghĩa của từ từ ngữ cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9813, 43099, '祖父は若いころ兵隊として戦地に行った。', 'そふは わかい ころ へいたいと して せんちに いった。', 'Hồi trẻ ông tôi ra chiến trường làm lính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9814, 43065, 'スマホは今や生活の必需品だ。', 'スマホは いまや せいかつの ひつじゅひんだ。', 'Điện thoại giờ đã là vật dụng thiết yếu của cuộc sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9815, 39825, '過半数の人が賛成した。', 'かはんすうの ひとが さんせい した。', 'Quá nửa số người đã tán thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9817, 40171, '荷物の重量は二十キロまでです。', 'にもつの じゅうりょうは にじゅっキロまで です。', 'Trọng lượng hành lý tối đa là hai mươi ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9818, 42948, '荷物の重さが超過して、追加料金を払った。', 'にもつの おもさが ちょうか して、ついか りょうきんを はらった。', 'Hành lý quá cân nên tôi phải trả thêm phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9819, 29258, '新しい商品のために市場調査をしました。', 'あたらしい しょうひんの ために しじょう ちょうさを しました。', 'Chúng tôi khảo sát thị trường cho sản phẩm mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9820, 29262, '安藤百福はインスタントラーメンを発明しました。', 'あんどう ももふくは インスタントラーメンを はつめい しました。', 'Ando Momofuku đã phát minh ra mì ăn liền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9821, 29230, 'ミキサーでジュースを作りました。', 'ミキサーで ジュースを つくりました。', 'Tôi làm nước ép bằng máy xay sinh tố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9822, 29261, 'チキンラーメンは世界で初めてのインスタントラーメンです。', 'チキンラーメンは せかいで はじめての インスタントラーメン です。', 'Chikin Ramen là loại mì ăn liền đầu tiên trên thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9823, 29304, '今にも雨が降りそうです。', 'いまにも あめが ふりそう です。', 'Trời sắp mưa đến nơi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9824, 29309, '彼に謝ったほうがいいですよ。', 'かれに あやまった ほうが いい ですよ。', 'Bạn nên xin lỗi anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9825, 43109, 'けがをした足に包帯を巻いた。', 'けがを した あしに ほうたいを まいた。', 'Tôi quấn băng vào chân bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9826, 43113, '祖母は大阪の方言で話す。', 'そぼは おおさかの ほうげんで はなす。', 'Bà tôi nói giọng địa phương Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9827, 43114, 'この方程式を解いてください。', 'この ほうていしきを といて ください。', 'Hãy giải phương trình này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9828, 43103, '夏は山の別荘で過ごす。', 'なつは やまの べっそうで すごす。', 'Mùa hè chúng tôi ở biệt thự trên núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9829, 43104, '母がセーターを編んでくれた。', 'ははが セーターを あんで くれた。', 'Mẹ đan áo len cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9830, 43105, '冬になると、編み物を始める。', 'ふゆに なると、あみものを はじめる。', 'Đến mùa đông là tôi bắt đầu đan len.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9831, 43106, '昔の家は便所が外にあった。', 'むかしの いえは べんじょが そとに あった。', 'Nhà ngày xưa có nhà vệ sinh ở bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9832, 43112, 'この包丁はよく切れる。', 'この ほうちょうは よく きれる。', 'Con dao này cắt rất ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9833, 42970, 'このエレベーターの定員は十人です。', 'この エレベーターの ていいんは じゅうにん です。', 'Thang máy này chở tối đa mười người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9834, 43090, 'この植物は日本全国に分布している。', 'この しょくぶつは にほん ぜんこくに ぶんぷ して いる。', 'Loài cây này phân bố khắp nước Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9835, 43121, '膨大な資料を一人で整理した。', 'ぼうだいな しりょうを ひとりで せいり した。', 'Tôi một mình sắp xếp lượng tài liệu đồ sộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9836, 43133, '朝の電車は満員だった。', 'あさの でんしゃは まんいん だった。', 'Tàu buổi sáng chật kín người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9837, 43138, '子供には無限の可能性がある。', 'こどもには むげんの かのうせいが ある。', 'Trẻ em có tiềm năng vô hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9838, 43148, 'この公園の面積は東京ドーム二つ分だ。', 'この こうえんの めんせきは とうきょう ドーム ふたつぶんだ。', 'Công viên này rộng bằng hai sân Tokyo Dome.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9839, 29320, 'このホテルは安いです。そのうえ、駅から近いです。', 'この ホテルは やすい です。その うえ、えきから ちかい です。', 'Khách sạn này rẻ. Hơn nữa còn gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9840, 43155, '一日の勉強時間は二時間を目安にしている。', 'いちにちの べんきょう じかんは にじかんを めやすに して いる。', 'Tôi lấy hai tiếng làm mức chuẩn cho thời gian học mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9841, 43204, '米を一粒も残さないで食べなさい。', 'こめを ひとつぶも のこさないで たべなさい。', 'Ăn hết, đừng để sót một hạt cơm nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9842, 31576, '二人とも自分の意見を譲らない。', 'ふたりとも じぶんの いけんを ゆずらない。', 'Cả hai đều không chịu nhường ý kiến của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9843, 31625, '彼は裏方に徹して、チームを支えた。', 'かれは うらかたに てっして、チームを ささえた。', 'Anh ấy làm tròn vai trò hậu trường để hỗ trợ đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9844, 31676, 'ラッシュの時間を避けて出かけた。', 'ラッシュの じかんを さけて でかけた。', 'Tôi tránh giờ cao điểm khi ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9845, 31694, 'ここ十年の人口の推移を調べた。', 'ここ じゅうねんの じんこうの すいいを しらべた。', 'Tôi tìm hiểu biến động dân số trong mười năm qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9846, 43102, '駅までの道は桜の並木になっている。', 'えきまでの みちは さくらの なみきに なって いる。', 'Con đường đến ga có hàng hoa anh đào hai bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9847, 43108, '足りない栄養をサプリメントで補っている。', 'たりない えいようを サプリメントで おぎなって いる。', 'Tôi bổ sung chất dinh dưỡng còn thiếu bằng thực phẩm chức năng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9848, 43110, '一万円札を千円札に崩してもらえますか。', 'いちまんえんさつを せんえんさつに くずして もらえますか。', 'Đổi giúp tôi tờ mười nghìn yên thành tiền lẻ nghìn yên được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9849, 43111, '大雨で山が崩れた。', 'おおあめで やまが くずれた。', 'Mưa lớn làm sạt lở núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9850, 43107, 'かわいい便箋で手紙を書いた。', 'かわいい びんせんで てがみを かいた。', 'Tôi viết thư trên giấy viết thư xinh xắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9851, 43153, 'この商売はあまり儲からない。', 'この しょうばいは あまり もうからない。', 'Việc buôn bán này không lãi mấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9852, 43139, '長い間ご無沙汰してすみません。', 'ながい あいだ ごぶさた して すみません。', 'Xin lỗi vì lâu quá không liên lạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9853, 43142, '日本で一番多い名字は「佐藤」だ。', 'にほんで いちばん おおい みょうじは 「さとう」だ。', 'Họ phổ biến nhất ở Nhật là "Sato".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9854, 43146, 'お菓子を銘々の皿に分けた。', 'おかしを めいめいの さらに わけた。', 'Tôi chia bánh vào đĩa của từng người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9855, 43147, '姪の誕生日にプレゼントを送った。', 'めいの たんじょうびに プレゼントを おくった。', 'Tôi gửi quà sinh nhật cho cháu gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9856, 43157, '目下の人にも丁寧に話すようにしている。', 'めしたの ひとにも ていねいに はなす ように して いる。', 'Tôi cố gắng nói năng lịch sự cả với người dưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9857, 43159, '目上の人には敬語を使いましょう。', 'めうえの ひとには けいごを つかいましょう。', 'Với người bề trên hãy dùng kính ngữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9858, 43149, '毎日日記を書くのは面倒臭い。', 'まいにち にっきを かくのは めんどうくさい。', 'Ngày nào cũng viết nhật ký thật phiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9859, 43161, '先生と学生の問答が続いた。', 'せんせいと がくせいの もんどうが つづいた。', 'Cuộc hỏi đáp giữa thầy và trò kéo dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9860, 43124, '北海道では牧畜が盛んだ。', 'ほっかいどうでは ぼくちくが さかんだ。', 'Ở Hokkaido chăn nuôi gia súc rất phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9861, 43126, '会社の本部は東京にある。', 'かいしゃの ほんぶは とうきょうに ある。', 'Trụ sở chính của công ty ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9862, 39563, 'うれしくて涙がこぼれた。', 'うれしくて なみだが こぼれた。', 'Vui quá nên nước mắt trào ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9863, 39725, 'ヒーローが悪者をやっつけた。', 'ヒーローが わるものを やっつけた。', 'Người hùng đã đánh bại kẻ xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9864, 39728, '息子が久しぶりに手紙を寄越した。', 'むすこが ひさしぶりに てがみを よこした。', 'Lâu lắm con trai tôi mới gửi thư về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9865, 39764, '帰ろうとする友達を引き止めた。', 'かえろうと する ともだちを ひきとめた。', 'Tôi giữ người bạn đang định về lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9866, 39766, 'ハンバーグを引っくり返して焼いた。', 'ハンバーグを ひっくりかえして やいた。', 'Tôi lật miếng thịt băm lại để nướng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9867, 39768, '恥ずかしがり屋の弟は、すぐ部屋に引っ込んでしまう。', 'はずかしがりやの おとうとは、すぐ へやに ひっこんで しまう。', 'Em trai nhút nhát của tôi hay rút vào phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9868, 39800, '船で川を下った。', 'ふねで かわを くだった。', 'Chúng tôi đi thuyền xuôi dòng sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9869, 39842, '悪い習慣を改めたい。', 'わるい しゅうかんを あらためたい。', 'Tôi muốn sửa thói quen xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9870, 39844, '古い倉庫をカフェに改造した。', 'ふるい そうこを カフェに かいぞう した。', 'Nhà kho cũ được cải tạo thành quán cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9871, 39860, '市は子育て支援を拡充した。', 'しは こそだて しえんを かくじゅう した。', 'Thành phố đã mở rộng hỗ trợ nuôi dạy con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9872, 29314, '彼女は服のセンスがいいです。', 'かのじょは ふくの センスが いい です。', 'Cô ấy có gu ăn mặc tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9873, 29327, '雪の道で滑って転びました。', 'ゆきの みちで すべって ころびました。', 'Tôi trượt chân ngã trên đường tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9874, 29346, '雨が降りそうなので、洗濯物を入れました。', 'あめが ふりそう なので、せんたくものを いれました。', 'Trời sắp mưa nên tôi đã cất đồ phơi vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9875, 29356, '会議が終わりました。どうもお疲れさまでした。', 'かいぎが おわりました。どうも おつかれさま でした。', 'Cuộc họp kết thúc rồi. Mọi người vất vả rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9876, 29370, '服をたんすにしまいました。', 'ふくを たんすに しまいました。', 'Tôi cất quần áo vào tủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9877, 43163, '役所で住民票をもらった。', 'やくしょで じゅうみんひょうを もらった。', 'Tôi lấy giấy chứng nhận cư trú ở ủy ban.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9878, 43166, '処方箋を持って薬局へ行った。', 'しょほうせんを もって やっきょくへ いった。', 'Tôi cầm đơn thuốc ra nhà thuốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9879, 43167, '結婚指輪は左手の薬指にする。', 'けっこん ゆびわは ひだりての くすりゆびに する。', 'Nhẫn cưới đeo ở ngón áp út tay trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9880, 43168, '危険な薬品を扱うときは手袋をしなさい。', 'きけんな やくひんを あつかう ときは てぶくろを しなさい。', 'Khi làm việc với hóa chất nguy hiểm, hãy đeo găng tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9881, 43170, '手術で輸血が必要になった。', 'しゅじゅつで ゆけつが ひつように なった。', 'Ca mổ cần phải truyền máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9882, 43169, '勝てると思って油断したら、負けてしまった。', 'かてると おもって ゆだん したら、まけて しまった。', 'Tưởng sẽ thắng nên chủ quan, kết quả là thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9883, 43165, '子供を守るのは親の役目だ。', 'こどもを まもるのは おやの やくめだ。', 'Bảo vệ con cái là nhiệm vụ của cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9884, 43164, '役人の対応が遅くて困った。', 'やくにんの たいおうが おそくて こまった。', 'Công chức xử lý chậm nên tôi gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9885, 39861, '空港の拡張工事が始まった。', 'くうこうの かくちょう こうじが はじまった。', 'Công trình mở rộng sân bay đã khởi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9886, 39899, '机を壁に寄せて、部屋を広くした。', 'つくえを かべに よせて、へやを ひろく した。', 'Tôi kê bàn sát tường cho phòng rộng ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9887, 39952, '地図で経度と緯度を調べた。', 'ちずで けいどと いどを しらべた。', 'Tôi tra kinh độ và vĩ độ trên bản đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9888, 47487, '暑さでプールの水が蒸発した。', 'あつさで プールの みずが じょうはつ した。', 'Trời nóng làm nước hồ bơi bốc hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9889, 47510, 'この城は中世に建てられた。', 'この しろは ちゅうせいに たてられた。', 'Lâu đài này được xây vào thời trung cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9890, 47847, '暑さでプールの水が蒸発した。', 'あつさで プールの みずが じょうはつ した。', 'Trời nóng làm nước hồ bơi bốc hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9891, 47870, 'この城は中世に建てられた。', 'この しろは ちゅうせいに たてられた。', 'Lâu đài này được xây vào thời trung cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9892, 48092, 'チームの守備を強化する必要がある。', 'チームの しゅびを きょうか する ひつようが ある。', 'Cần củng cố hàng phòng ngự của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9893, 48207, '暑さでプールの水が蒸発した。', 'あつさで プールの みずが じょうはつ した。', 'Trời nóng làm nước hồ bơi bốc hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9894, 48230, 'この城は中世に建てられた。', 'この しろは ちゅうせいに たてられた。', 'Lâu đài này được xây vào thời trung cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9895, 31626, '火の元の確認を徹底してください。', 'ひのもとの かくにんを てってい して ください。', 'Hãy kiểm tra kỹ các nguồn lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9896, 31701, 'インターネットで社会は大きく変容した。', 'インターネットで しゃかいは おおきく へんよう した。', 'Internet đã làm xã hội biến đổi sâu sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9897, 31703, '事故の後、彼の生活は激変した。', 'じこの あと、かれの せいかつは げきへん した。', 'Sau tai nạn, cuộc sống của anh ấy biến đổi mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9898, 37818, '地球温暖化で夏が暑くなっている。', 'ちきゅう おんだんかで なつが あつく なって いる。', 'Do trái đất nóng lên, mùa hè ngày càng nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9899, 29350, '美容院でカットとシャンプーをしました。', 'びよういんで カットと シャンプーを しました。', 'Tôi cắt và gội đầu ở tiệm làm tóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9900, 29381, '泥棒を見たら、すぐ１１０番に電話してください。', 'どろぼうを みたら、すぐ ひゃくとおばんに でんわ して ください。', 'Nếu thấy kẻ trộm hãy gọi ngay số 110.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9901, 29391, '私たちのチームが優勝しました。', 'わたしたちの チームが ゆうしょう しました。', 'Đội chúng tôi đã vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9902, 31233, 'この哲学書は深遠な内容だ。', 'この てつがくしょは しんえんな ないようだ。', 'Cuốn sách triết học này có nội dung sâu xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9903, 43171, '勇ましい音楽とともに選手が入場した。', 'いさましい おんがくと ともに せんしゅが にゅうじょう した。', 'Các vận động viên tiến vào sân cùng tiếng nhạc hào hùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9904, 43173, '手伝ってもらえて、本当に有難い。', 'てつだって もらえて、ほんとうに ありがたい。', 'Được giúp đỡ thế này, tôi thật sự biết ơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9905, 43182, 'そんな幼稚なことはやめなさい。', 'そんな ようちな ことは やめなさい。', 'Thôi ngay những trò trẻ con như thế đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9906, 43193, '欲張りすぎると、何も手に入らない。', 'よくばりすぎると、なにも てに はいらない。', 'Tham lam quá thì chẳng được gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9907, 43197, '物を乱暴に扱わないでください。', 'ものを らんぼうに あつかわないで ください。', 'Xin đừng đối xử thô bạo với đồ đạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9908, 43203, 'テストの結果を見て、ため息をついた。', 'テストの けっかを みて、ためいきを ついた。', 'Nhìn kết quả bài kiểm tra, tôi thở dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9909, 37821, '再生可能なエネルギーを増やす必要がある。', 'さいせい かのうな エネルギーを ふやす ひつようが ある。', 'Cần tăng nguồn năng lượng tái tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9910, 38133, 'この言葉はもう日本語に定着している。', 'この ことばは もう にほんごに ていちゃく して いる。', 'Từ này đã bén rễ trong tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9911, 38192, 'この川には珍しい魚が生息している。', 'この かわには めずらしい さかなが せいそく して いる。', 'Con sông này có loài cá quý hiếm sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9912, 38193, '春は多くの鳥が繁殖する季節だ。', 'はるは おおくの とりが はんしょく する きせつだ。', 'Mùa xuân là mùa sinh sản của nhiều loài chim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9913, 38194, '森林伐採で動物のすみかが減っている。', 'しんりん ばっさいで どうぶつの すみかが へって いる。', 'Nạn phá rừng làm nơi sống của động vật bị thu hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9914, 38196, '海面上昇で島がなくなるかもしれない。', 'かいめん じょうしょうで しまが なくなるかも しれない。', 'Do mực nước biển dâng, có thể những hòn đảo sẽ biến mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9915, 38202, '猛暑で熱中症になる人が増えた。', 'もうしょで ねっちゅうしょうに なる ひとが ふえた。', 'Do nắng nóng gay gắt, số người bị say nắng tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9916, 38204, '寒波の影響で大雪になった。', 'かんぱの えいきょうで おおゆきに なった。', 'Do ảnh hưởng của đợt rét đậm, tuyết rơi dày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9917, 39493, '数字を公式に当てはめて計算した。', 'すうじを こうしきに あてはめて けいさん した。', 'Tôi áp số vào công thức để tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9918, 39518, 'お化けの格好をして弟を脅かした。', 'おばけの かっこうを して おとうとを おどかした。', 'Tôi hóa trang thành ma để dọa em trai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9919, 39549, '二つの机をくっつけて、大きなテーブルにした。', 'ふたつの つくえを くっつけて、おおきな テーブルに した。', 'Tôi ghép hai cái bàn lại thành một bàn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9920, 39611, '会議の時間を一時間ずらした。', 'かいぎの じかんを いちじかん ずらした。', 'Tôi dời giờ họp đi một tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9921, 39627, 'ホテルのダブルの部屋を予約した。', 'ホテルの ダブルの へやを よやく した。', 'Tôi đặt phòng đôi ở khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9922, 39636, '石につまずいて転んだ。', 'いしに つまずいて ころんだ。', 'Tôi vấp phải hòn đá và ngã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9923, 39679, '授業中にふざけて、先生に怒られた。', 'じゅぎょうちゅうに ふざけて、せんせいに おこられた。', 'Đùa giỡn trong giờ học nên tôi bị thầy mắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9924, 29393, '目覚まし時計を六時にセットしました。', 'めざまし どけいを ろくじに セット しました。', 'Tôi đặt đồng hồ báo thức lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9926, 29405, '夜中に間違い電話がかかってきました。', 'よなかに まちがい でんわが かかって きました。', 'Nửa đêm có người gọi nhầm số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9927, 31741, '理論はわかっても、実際にやるのは難しい。', 'りろんは わかっても、じっさいに やるのは むずかしい。', 'Hiểu lý thuyết rồi nhưng làm thực tế thì khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9928, 43223, '一人だけ先に食べるなんて、狡いよ。', 'ひとり だけ さきに たべる なんて、ずるいよ。', 'Mỗi mình cậu ăn trước, ranh mãnh thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9929, 43221, '彼女は耳元で何か囁いた。', 'かのじょは みみもとで なにか ささやいた。', 'Cô ấy thì thầm điều gì đó bên tai tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9930, 43225, '箒で玄関を掃いた。', 'ほうきで げんかんを はいた。', 'Tôi quét lối vào bằng chổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9931, 39697, '荷物のひもをほどいた。', 'にもつの ひもを ほどいた。', 'Tôi tháo dây buộc kiện hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9932, 39718, '壁にもたれて友達を待った。', 'かべに もたれて ともだちを まった。', 'Tôi dựa vào tường chờ bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9933, 39931, 'お祭りで金魚をすくった。', 'おまつりで きんぎょを すくった。', 'Ở lễ hội tôi chơi vớt cá vàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9934, 39966, '家賃は月末までに払ってください。', 'やちんは げつまつまでに はらって ください。', 'Hãy trả tiền nhà trước cuối tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9935, 39961, '値段の桁を間違えた。', 'ねだんの けたを まちがえた。', 'Tôi nhầm số chữ số của giá tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9936, 40031, '秋になると、山の紅葉がきれいだ。', 'あきに なると、やまの こうようが きれいだ。', 'Sang thu, lá đỏ trên núi rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9937, 40030, '話しているうちに、夜が更けた。', 'はなして いる うちに、よるが ふけた。', 'Mải trò chuyện mà đêm đã khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9938, 40085, '祖父は広い山林を持っている。', 'そふは ひろい さんりんを もって いる。', 'Ông tôi sở hữu một khu rừng núi rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9939, 42957, 'この電車は空港まで直通です。', 'この でんしゃは くうこうまで ちょくつう です。', 'Chuyến tàu này chạy thẳng ra sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9940, 42996, '岬の先に白い灯台が立っている。', 'みさきの さきに しろい とうだいが たって いる。', 'Ở đầu mũi đất có một ngọn hải đăng trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9941, 42995, 'ラーメンから湯気が立っている。', 'ラーメンから ゆげが たって いる。', 'Bát mì ramen bốc hơi nghi ngút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9942, 43000, 'ケーキを八等分に切った。', 'ケーキを はちとうぶんに きった。', 'Tôi cắt bánh thành tám phần bằng nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9943, 43222, '体をねじって、後ろを見た。', 'からだを ねじって、うしろを みた。', 'Tôi vặn người nhìn ra phía sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9944, 43224, 'うるさくしたら、先生ににらまれた。', 'うるさく したら、せんせいに にらまれた。', 'Làm ồn nên tôi bị thầy lườm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9945, 29421, '宅配便で荷物を送りました。', 'たくはいびんで にもつを おくりました。', 'Tôi gửi hàng bằng dịch vụ giao tận nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9946, 31754, '彼女は自分の信念を曲げなかった。', 'かのじょは じぶんの しんねんを まげなかった。', 'Cô ấy không từ bỏ niềm tin của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9947, 31740, '彼の話は論理が通っていない。', 'かれの はなしは ろんりが とおって いない。', 'Câu chuyện của anh ta không hợp logic.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9948, 31752, '社会の規範を守ることが求められる。', 'しゃかいの きはんを まもる ことが もとめられる。', 'Cần tuân thủ chuẩn mực xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9949, 31744, '新しい国際協力の枠組みが作られた。', 'あたらしい こくさい きょうりょくの わくぐみが つくられた。', 'Một khuôn khổ hợp tác quốc tế mới đã được xây dựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9950, 31755, '正直に生きることが私の信条だ。', 'しょうじきに いきる ことが わたしの しんじょうだ。', 'Sống thật thà là tín điều của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9951, 31749, 'ヘーゲルの弁証法について学んだ。', 'ヘーゲルの べんしょうほうに ついて まなんだ。', 'Tôi đã học về phép biện chứng của Hegel.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9952, 31746, 'これは努力の当然の帰結だ。', 'これは どりょくの とうぜんの きけつだ。', 'Đây là kết quả tất yếu của nỗ lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9953, 31768, '先生はすべての学生に公平だ。', 'せんせいは すべての がくせいに こうへいだ。', 'Thầy giáo công bằng với mọi học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9954, 31771, 'すべての人の人権を守らなければならない。', 'すべての ひとの じんけんを まもらなければ ならない。', 'Phải bảo vệ nhân quyền của tất cả mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9955, 39997, '冷蔵庫に入れると、ゼリーが固まる。', 'れいぞうこに いれると、ゼリーが かたまる。', 'Cho vào tủ lạnh thì thạch sẽ đông lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9956, 40007, '赤と青の絵の具が交ざって、紫になった。', 'あかと あおの えのぐが まざって、むらさきに なった。', 'Màu đỏ và màu xanh trộn lẫn thành màu tím.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9957, 40041, '毎日練習して、技術を高めている。', 'まいにち れんしゅう して、ぎじゅつを たかめて いる。', 'Tôi luyện tập mỗi ngày để nâng cao kỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9958, 40047, '後から来た友達と駅で合流した。', 'あとから きた ともだちと えきで ごうりゅう した。', 'Tôi nhập hội với người bạn đến sau ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9959, 40063, '両手が荷物で塞がっている。', 'りょうてが にもつで ふさがって いる。', 'Hai tay tôi đang bận xách đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9960, 40068, '落としたコップが粉々に砕けた。', 'おとした コップが こなごなに くだけた。', 'Chiếc cốc rơi vỡ tan tành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9961, 40093, '注文したスーツは来週仕上がる。', 'ちゅうもん した スーツは らいしゅう しあがる。', 'Bộ vest tôi đặt sẽ xong vào tuần sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9962, 40094, '指にとげが刺さった。', 'ゆびに とげが ささった。', 'Một cái gai đâm vào ngón tay tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10372, 27212, '今月の十日は休みです。', 'こんげつの とおかは やすみ です。', 'Ngày mười tháng này được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9963, 40115, '大阪は東京に次ぐ大きな町だ。', 'おおさかは とうきょうに つぐ おおきな まちだ。', 'Osaka là thành phố lớn chỉ sau Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9964, 40159, '本日の営業は終了しました。', 'ほんじつの えいぎょうは しゅうりょう しました。', 'Hôm nay cửa hàng đã đóng cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9965, 29432, '遅くなって、申し訳ありません。', 'おそく なって、もうしわけ ありません。', 'Tôi thành thật xin lỗi vì đã đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9966, 31762, '利他の精神を持って行動したい。', 'りたの せいしんを もって こうどう したい。', 'Tôi muốn hành động với tinh thần vị tha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9967, 31757, '理想と現実は違う。', 'りそうと げんじつは ちがう。', 'Lý tưởng và hiện thực khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9968, 31760, '彼女は現実主義で、夢より安定を選ぶ。', 'かのじょは げんじつ しゅぎで、ゆめより あんていを えらぶ。', 'Cô ấy thực tế nên chọn sự ổn định hơn ước mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9969, 31773, '彼は恐怖で人々を支配した。', 'かれは きょうふで ひとびとを しはい した。', 'Hắn cai trị mọi người bằng nỗi sợ hãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9970, 31777, '民主主義では国民が主権を持つ。', 'みんしゅ しゅぎでは こくみんが しゅけんを もつ。', 'Trong chế độ dân chủ, nhân dân nắm chủ quyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9971, 31779, '日本は立憲君主制に近い国だと言われる。', 'にほんは りっけん くんしゅせいに ちかい くにだと いわれる。', 'Người ta nói Nhật là nước gần với chế độ quân chủ lập hiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9972, 31786, '地方で農民の反乱が起きた。', 'ちほうで のうみんの はんらんが おきた。', 'Ở địa phương đã nổ ra cuộc nổi loạn của nông dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9973, 31789, '会社は大きな変革の時期を迎えている。', 'かいしゃは おおきな へんかくの じきを むかえて いる。', 'Công ty đang bước vào thời kỳ đổi mới lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9974, 31792, '急進的な改革には反対も多い。', 'きゅうしんてきな かいかくには はんたいも おおい。', 'Cải cách cấp tiến cũng gặp nhiều phản đối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9975, 31761, '彼の考え方は功利的すぎる。', 'かれの かんがえかたは こうりてき すぎる。', 'Cách suy nghĩ của anh ta quá thực dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9976, 31794, 'この町は貿易で繁栄した。', 'この まちは ぼうえきで はんえい した。', 'Thị trấn này thịnh vượng nhờ thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9977, 40168, '今年は祝日が日曜日と重なった。', 'ことしは しゅくじつが にちようびと かさなった。', 'Năm nay ngày lễ trùng với chủ nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9978, 40173, 'セーターを洗ったら、縮んでしまった。', 'セーターを あらったら、ちぢんで しまった。', 'Giặt xong chiếc áo len bị co lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9979, 40175, '雨の日は髪が縮れてしまう。', 'あめの ひは かみが ちぢれて しまう。', 'Ngày mưa tóc tôi bị xoăn lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9980, 40184, 'やっと卒業論文が出来上がった。', 'やっと そつぎょう ろんぶんが できあがった。', 'Cuối cùng luận văn tốt nghiệp cũng hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9981, 40216, '懐中電灯で足元を照らした。', 'かいちゅう でんとうで あしもとを てらした。', 'Tôi rọi đèn pin xuống chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9982, 40289, '長い交渉の末、契約が成立した。', 'ながい こうしょうの すえ、けいやくが せいりつ した。', 'Sau đàm phán dài, hợp đồng đã được ký kết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9983, 42891, 'このお菓子、あげるよ。', 'この おかし、あげるよ。', 'Cho cậu gói bánh này nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9984, 42959, 'ビールを一本追加してください。', 'ビールを いっぽん ついか して ください。', 'Cho thêm một chai bia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9985, 42965, '不景気で近くの店が潰れた。', 'ふけいきで ちかくの みせが つぶれた。', 'Do kinh tế khó khăn, cửa hàng gần nhà đã phá sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9986, 43006, 'パソコンの動作が遅い。', 'パソコンの どうさが おそい。', 'Máy tính chạy chậm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9987, 43041, 'リュックを背負って山に登った。', 'リュックを せおって やまに のぼった。', 'Tôi đeo ba lô leo núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9988, 43078, '子供の頭を優しく撫でた。', 'こどもの あたまを やさしく なでた。', 'Tôi dịu dàng xoa đầu đứa trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9989, 43088, '壊れた時計を分解してみた。', 'こわれた とけいを ぶんかい して みた。', 'Tôi thử tháo rời chiếc đồng hồ hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9990, 43119, '酔った男が駅で暴れていた。', 'よった おとこが えきで あばれて いた。', 'Một gã say xỉn đang quậy phá ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9991, 43186, '彼はすぐ新しいクラスに溶け込んだ。', 'かれは すぐ あたらしい クラスに とけこんだ。', 'Cậu ấy nhanh chóng hòa nhập với lớp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9992, 31673, '外が騒がしいけど、何かあったのかな。', 'そとが さわがしい けど、なにか あったのかな。', 'Bên ngoài ồn ào quá, có chuyện gì nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9993, 38126, '富士山は日本の象徴的な山だ。', 'ふじさんは にほんの しょうちょうてきな やまだ。', 'Núi Phú Sĩ là ngọn núi biểu tượng của Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9994, 39744, '安易に人を信じてはいけない。', 'あんいに ひとを しんじては いけない。', 'Không nên dễ dãi tin người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9995, 39761, '部屋の温度を一定に保っている。', 'へやの おんどを いっていに たもって いる。', 'Nhiệt độ phòng được giữ ở mức cố định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9996, 39784, 'たき火の近くは煙い。', 'たきびの ちかくは けむい。', 'Gần đống lửa trại thì cay khói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9997, 39837, '家の前に怪しい人が立っている。', 'いえの まえに あやしい ひとが たって いる。', 'Có người khả nghi đứng trước nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9998, 39862, '山の上で飲むコーヒーは格別だ。', 'やまの うえで のむ コーヒーは かくべつだ。', 'Uống cà phê trên đỉnh núi thật đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (9999, 39897, '危うく電車に乗り遅れるところだった。', 'あやうく でんしゃに のりおくれる ところ だった。', 'Suýt chút nữa thì tôi lỡ tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10373, 27215, 'ことしは日本で働きます。', 'ことしは にほんで はたらきます。', 'Năm nay tôi làm việc ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10000, 39911, '子供が鉄棒に逆様にぶら下がっている。', 'こどもが てつぼうに さかさまに ぶらさがって いる。', 'Đứa trẻ treo ngược người trên xà đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10001, 29440, '目覚まし時計が鳴りました。', 'めざまし どけいが なりました。', 'Đồng hồ báo thức đã reo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10002, 37857, '新しい映画は批評家から高い評価を受けた。', 'あたらしい えいがは ひひょうかから たかい ひょうかを うけた。', 'Bộ phim mới được giới phê bình đánh giá cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10003, 37866, '彼は不当な理由で解雇された。', 'かれは ふとうな りゆうで かいこ された。', 'Anh ấy bị sa thải vì lý do bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10004, 40036, '今日は波が荒いので、泳がないほうがいい。', 'きょうは なみが あらいので、およがない ほうが いい。', 'Hôm nay sóng dữ, tốt nhất đừng bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10005, 40044, '兄は高等専門学校を卒業した。', 'あには こうとう せんもん がっこうを そつぎょう した。', 'Anh tôi đã tốt nghiệp trường cao đẳng kỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10006, 40100, '思い掛けないところで先生に会った。', 'おもいがけない ところで せんせいに あった。', 'Tôi gặp thầy ở một nơi không ngờ tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10007, 40139, '祖母は七十歳だが、若々しい。', 'そぼは ななじゅっさい だが、わかわかしい。', 'Bà tôi bảy mươi tuổi mà vẫn trẻ trung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10008, 40167, '重たい荷物を二階まで運んだ。', 'おもたい にもつを にかいまで はこんだ。', 'Tôi bê kiện hàng nặng lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10009, 42975, '先生は的確なアドバイスをくれた。', 'せんせいは てきかくな アドバイスを くれた。', 'Thầy đã cho tôi lời khuyên xác đáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10010, 43004, '透明なビニール袋にごみを入れてください。', 'とうめいな ビニールぶくろに ごみを いれて ください。', 'Hãy bỏ rác vào túi ni lông trong suốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10011, 43015, 'この道は凸凹で歩きにくい。', 'この みちは でこぼこで あるきにくい。', 'Con đường này gồ ghề, khó đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10012, 43075, '手が不潔なまま料理してはいけない。', 'てが ふけつな まま りょうり しては いけない。', 'Không được nấu ăn khi tay còn bẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10013, 43087, '最近この辺りは物騒だから、気をつけて。', 'さいきん この あたりは ぶっそう だから、きを つけて。', 'Dạo này khu này không an toàn, cẩn thận nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10014, 43141, '無地のシャツは何にでも合う。', 'むじの シャツは なんにでも あう。', 'Áo sơ mi trơn mặc với gì cũng hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10015, 43180, '余計なことを言わないでください。', 'よけいな ことを いわないで ください。', 'Xin đừng nói những chuyện thừa thãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10016, 43209, '今日は臨時で休業します。', 'きょうは りんじで きゅうぎょう します。', 'Hôm nay cửa hàng tạm nghỉ đột xuất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10017, 38189, '映画の試写会に原作者も来ていた。', 'えいがの ししゃかいに げんさくしゃも きて いた。', 'Tác giả nguyên tác cũng đến dự buổi chiếu thử phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10018, 39512, 'オーケストラの演奏を聞きに行った。', 'オーケストラの えんそうを ききに いった。', 'Tôi đi nghe dàn nhạc giao hưởng biểu diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10019, 39537, 'お正月に家族でかるたをした。', 'おしょうがつに かぞくで かるたを した。', 'Dịp Tết cả nhà chơi bài karuta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10020, 39567, '兄は古い切手のコレクションをしている。', 'あには ふるい きっての コレクションを して いる。', 'Anh tôi sưu tầm tem cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10021, 29443, '今日の出来事を日記に書きました。', 'きょうの できごとを にっきに かきました。', 'Tôi ghi lại chuyện hôm nay vào nhật ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10022, 37855, '彼は皮肉を言うのが得意だ。', 'かれは ひにくを いうのが とくいだ。', 'Anh ta rất giỏi nói mỉa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10023, 37859, '医者の所見では、手術は必要ないそうだ。', 'いしゃの しょけんでは、しゅじゅつは ひつよう ない そうだ。', 'Theo nhận định của bác sĩ, không cần phẫu thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10024, 37861, '綿密な計画を立てて旅行に出かけた。', 'めんみつな けいかくを たてて りょこうに でかけた。', 'Chúng tôi lập kế hoạch tỉ mỉ rồi mới đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10025, 37863, '要点を簡潔にまとめてください。', 'ようてんを かんけつに まとめて ください。', 'Hãy tóm tắt ý chính một cách ngắn gọn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10026, 37868, 'このビルは斬新なデザインで注目を集めた。', 'この ビルは ざんしんな デザインで ちゅうもくを あつめた。', 'Tòa nhà này thu hút sự chú ý nhờ thiết kế mới lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10027, 37885, '会社は記者会見で謝罪した。', 'かいしゃは きしゃかいけんで しゃざい した。', 'Công ty đã tạ lỗi trong buổi họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10028, 38207, '新しい法律は来年四月から施行される。', 'あたらしい ほうりつは らいねん しがつから しこう される。', 'Luật mới sẽ được thi hành từ tháng tư năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10029, 39572, '大学でテニスのサークルに入った。', 'だいがくで テニスの サークルに はいった。', 'Ở đại học tôi tham gia câu lạc bộ tennis.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10030, 39721, 'この小説の主人公には実在のモデルがいる。', 'この しょうせつの しゅじんこうには じつざいの モデルが いる。', 'Nhân vật chính của tiểu thuyết này có nguyên mẫu ngoài đời thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10031, 39736, '週末は家族でレジャーを楽しんだ。', 'しゅうまつは かぞくで レジャーを たのしんだ。', 'Cuối tuần cả nhà đi vui chơi giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10032, 39783, '大学で演劇部に入っている。', 'だいがくで えんげきぶに はいって いる。', 'Ở đại học tôi tham gia câu lạc bộ kịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10033, 39845, '夏休みに家族で海水浴に行った。', 'なつやすみに かぞくで かいすいよくに いった。', 'Kỳ nghỉ hè cả nhà đi tắm biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10034, 39849, '市長のあいさつで大会が開会した。', 'しちょうの あいさつで たいかいが かいかい した。', 'Đại hội khai mạc bằng lời chào của thị trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10035, 39916, '父は週末によく競馬を見に行く。', 'ちちは しゅうまつに よく けいばを みに いく。', 'Cuối tuần bố tôi hay đi xem đua ngựa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10036, 39982, 'スピーチの原稿を書いた。', 'スピーチの げんこうを かいた。', 'Tôi đã viết bản thảo bài phát biểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10037, 39994, '高校で日本の古典を勉強した。', 'こうこうで にほんの こてんを べんきょう した。', 'Ở cấp ba tôi học văn học cổ điển Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10038, 40002, '日本では、あいさつのときにお辞儀をする。', 'にほんでは、あいさつの ときに おじぎを する。', 'Ở Nhật, người ta cúi chào khi chào hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10039, 40069, 'この神社には学問の神様が祭られている。', 'この じんじゃには がくもんの かみさまが まつられて いる。', 'Ngôi đền này thờ vị thần học vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10040, 40111, '京都には有名な寺院がたくさんある。', 'きょうとには ゆうめいな じいんが たくさん ある。', 'Kyoto có rất nhiều chùa chiền nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10041, 40121, '作家は新しい小説を執筆している。', 'さっかは あたらしい しょうせつを しっぴつ して いる。', 'Nhà văn đang chấp bút cuốn tiểu thuyết mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10042, 44509, '昔はラジオが一番の娯楽だった。', 'むかしは ラジオが いちばんの ごらく だった。', 'Ngày xưa radio là thú giải trí hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10043, 44869, '昔はラジオが一番の娯楽だった。', 'むかしは ラジオが いちばんの ごらく だった。', 'Ngày xưa radio là thú giải trí hàng đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10044, 29429, 'ガスのにおいがしたら、ガスサービスセンターに電話してください。', 'ガスの においが したら、ガス サービス センターに でんわ して ください。', 'Nếu ngửi thấy mùi ga, hãy gọi trung tâm dịch vụ ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10045, 37893, '母は子供の幸せを一心に願っている。', 'ははは こどもの しあわせを いっしんに ねがって いる。', 'Mẹ một lòng cầu mong con hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10046, 37883, '彼は記者会見で弁明した。', 'かれは きしゃかいけんで べんめい した。', 'Ông ta đã biện minh trong buổi họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10047, 37881, '部下に責任転嫁する上司は信頼されない。', 'ぶかに せきにん てんか する じょうしは しんらい されない。', 'Cấp trên đổ trách nhiệm cho cấp dưới sẽ không được tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10048, 37887, '警察は違法な賭博を摘発した。', 'けいさつは いほうな とばくを てきはつ した。', 'Cảnh sát đã phanh phui đường dây cờ bạc trái phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10049, 38210, '彼は二十五歳で会社を設立した。', 'かれは にじゅうごさいで かいしゃを せつりつ した。', 'Anh ấy thành lập công ty năm hai mươi lăm tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10050, 38212, '駅に着いたら、そこで解散します。', 'えきに ついたら、そこで かいさん します。', 'Đến ga thì cả đoàn sẽ giải tán tại đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10051, 39954, 'やっと電話が繋がった。', 'やっと でんわが つながった。', 'Cuối cùng điện thoại cũng gọi được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10052, 31244, '私はまだ未熟なので、もっと勉強が必要だ。', 'わたしは まだ みじゅく なので、もっと べんきょうが ひつようだ。', 'Tôi còn non nớt nên cần học hỏi thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10053, 44177, '館内での撮影はご遠慮ください。', 'かんないでの さつえいは ごえんりょ ください。', 'Xin vui lòng không chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10054, 44897, '館内での撮影はご遠慮ください。', 'かんないでの さつえいは ごえんりょ ください。', 'Xin vui lòng không chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10055, 47530, 'この町は伝統的な工芸で有名だ。', 'この まちは でんとうてきな こうげいで ゆうめいだ。', 'Thị trấn này nổi tiếng với nghề thủ công truyền thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10056, 47261, '先生は的確なアドバイスをくれた。', 'せんせいは てきかくな アドバイスを くれた。', 'Thầy đã cho tôi lời khuyên xác đáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10057, 47535, '姉は芸能のニュースに詳しい。', 'あねは げいのうの ニュースに くわしい。', 'Chị tôi rành tin tức giới giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10058, 47621, '先生は的確なアドバイスをくれた。', 'せんせいは てきかくな アドバイスを くれた。', 'Thầy đã cho tôi lời khuyên xác đáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10059, 47890, 'この町は伝統的な工芸で有名だ。', 'この まちは でんとうてきな こうげいで ゆうめいだ。', 'Thị trấn này nổi tiếng với nghề thủ công truyền thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10060, 47896, '高校で日本の古典を勉強した。', 'こうこうで にほんの こてんを べんきょう した。', 'Ở cấp ba tôi học văn học cổ điển Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
