INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10062, 48250, 'この町は伝統的な工芸で有名だ。', 'この まちは でんとうてきな こうげいで ゆうめいだ。', 'Thị trấn này nổi tiếng với nghề thủ công truyền thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10063, 48255, '姉は芸能のニュースに詳しい。', 'あねは げいのうの ニュースに くわしい。', 'Chị tôi rành tin tức giới giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10064, 31725, '私はまだ未熟なので、もっと勉強が必要だ。', 'わたしは まだ みじゅく なので、もっと べんきょうが ひつようだ。', 'Tôi còn non nớt nên cần học hỏi thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10065, 38111, 'もっと具体的に説明してください。', 'もっと ぐたいてきに せつめい して ください。', 'Hãy giải thích cụ thể hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10066, 38110, '夜中に電話をかけるのは非常識だ。', 'よなかに でんわを かけるのは ひじょうしきだ。', 'Gọi điện giữa đêm là trái lẽ thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10067, 38113, '客観的なデータで判断しよう。', 'きゃっかんてきな データで はんだん しよう。', 'Hãy phán đoán dựa trên dữ liệu khách quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10068, 38216, '新社長は組織の刷新を進めている。', 'しん しゃちょうは そしきの さっしんを すすめて いる。', 'Tân giám đốc đang tiến hành đổi mới toàn diện tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10178, 40154, '受話器を取って、番号を押した。', 'じゅわきを とって、ばんごうを おした。', 'Tôi nhấc ống nghe lên rồi bấm số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10069, 38222, '根本的な解決にはまだ時間がかかる。', 'こんぽんてきな かいけつには まだ じかんが かかる。', 'Giải quyết tận gốc vẫn còn cần thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10070, 38227, '転勤について上司から打診があった。', 'てんきんに ついて じょうしから だしんが あった。', 'Cấp trên đã dò hỏi ý kiến tôi về việc chuyển công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10071, 38230, '嘘はいつか露見するものだ。', 'うそは いつか ろけん する ものだ。', 'Lời nói dối rồi cũng có ngày bại lộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10072, 38226, '指紋を照合して犯人を特定した。', 'しもんを しょうごう して はんにんを とくてい した。', 'Đối chiếu vân tay để xác định thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10073, 38220, '恒久的な平和を願う。', 'こうきゅうてきな へいわを ねがう。', 'Mong ước hòa bình vĩnh cửu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10074, 38225, 'この教材は学習指導要領に準拠している。', 'この きょうざいは がくしゅう しどう ようりょうに じゅんきょ して いる。', 'Giáo trình này tuân theo khung chương trình giáo dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10075, 38115, '彼女は論理的に考えるのが得意だ。', 'かのじょは ろんりてきに かんがえるのが とくいだ。', 'Cô ấy giỏi suy nghĩ có logic.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10076, 38116, 'もっと合理的な方法があるはずだ。', 'もっと ごうりてきな ほうほうが ある はずだ。', 'Chắc chắn có cách hợp lý hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10077, 38120, '多くの人がその計画に肯定的だった。', 'おおくの ひとが その けいかくに こうていてき だった。', 'Nhiều người có thái độ tích cực với kế hoạch đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10078, 38122, 'ニュースを批判的に見ることも大切だ。', 'ニュースを ひはんてきに みる ことも たいせつだ。', 'Nhìn tin tức với con mắt phê phán cũng quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10079, 38144, '大学と市の共催で講演会が開かれた。', 'だいがくと しの きょうさいで こうえんかいが ひらかれた。', 'Buổi diễn thuyết do đại học và thành phố đồng tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10080, 38146, '会議の出席者は二十人だった。', 'かいぎの しゅっせきしゃは にじゅうにん だった。', 'Có hai mươi người tham dự cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10081, 38148, '来賓の方々は前の席にお座りください。', 'らいひんの かたがたは まえの せきに おすわり ください。', 'Kính mời các vị khách quý ngồi hàng ghế đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10082, 38151, '創立百周年の式典が行われた。', 'そうりつ ひゃくしゅうねんの しきてんが おこなわれた。', 'Buổi lễ kỷ niệm 100 năm thành lập đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10083, 38153, '首相の演説をテレビで見た。', 'しゅしょうの えんぜつを テレビで みた。', 'Tôi xem bài diễn thuyết của thủ tướng trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10084, 38154, '聴衆は彼の話に熱心に耳を傾けた。', 'ちょうしゅうは かれの はなしに ねっしんに みみを かたむけた。', 'Khán giả chăm chú lắng nghe bài nói của ông ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10085, 38157, 'これで大会を閉会します。', 'これで たいかいを へいかい します。', 'Đến đây xin bế mạc đại hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10086, 38174, 'このドラマの脚本は有名な作家が書いた。', 'この ドラマの きゃくほんは ゆうめいな さっかが かいた。', 'Kịch bản bộ phim này do một nhà văn nổi tiếng viết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10087, 38176, '館内での撮影はご遠慮ください。', 'かんないでの さつえいは ごえんりょ ください。', 'Xin vui lòng không chụp ảnh trong tòa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10088, 38179, '客席はほとんど埋まっていた。', 'きゃくせきは ほとんど うまって いた。', 'Ghế khán giả gần như kín chỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10089, 38182, '脇役の俳優の演技が光っていた。', 'わきやくの はいゆうの えんぎが ひかって いた。', 'Diễn xuất của diễn viên phụ rất nổi bật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10090, 38183, '新しい映画の配役が発表された。', 'あたらしい えいがの はいやくが はっぴょう された。', 'Danh sách phân vai của bộ phim mới đã được công bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10091, 29475, '兄は大学で医学を勉強しています。', 'あには だいがくで いがくを べんきょう して います。', 'Anh tôi đang học y ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10092, 38257, '彼は服装に無頓着だ。', 'かれは ふくそうに むとんちゃくだ。', 'Anh ấy chẳng để tâm đến chuyện ăn mặc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10093, 38262, '成功してから、彼は尊大になった。', 'せいこう してから、かれは そんだいに なった。', 'Từ khi thành công, anh ta trở nên kiêu căng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10094, 38264, 'この犬は飼い主に従順だ。', 'この いぬは かいぬしに じゅうじゅんだ。', 'Con chó này rất phục tùng chủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10095, 38266, '部長は部下のミスに寛大だ。', 'ぶちょうは ぶかの ミスに かんだいだ。', 'Trưởng phòng độ lượng với lỗi của cấp dưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10096, 38244, '何かいい妙案はないだろうか。', 'なにか いい みょうあんは ない だろうか。', 'Liệu có diệu kế nào không nhỉ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10097, 38247, '監督は奇策を用いて勝利した。', 'かんとくは きさくを もちいて しょうり した。', 'Huấn luyện viên dùng kế lạ để giành chiến thắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10098, 38250, 'どうすればいいか思案している。', 'どう すれば いいか しあん して いる。', 'Tôi đang suy tính không biết nên làm thế nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10099, 38185, 'その映画は興行収入が百億円を超えた。', 'その えいがは こうぎょう しゅうにゅうが ひゃくおくえんを こえた。', 'Doanh thu phòng vé của bộ phim đó vượt mười tỷ yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10100, 39490, '約束を守るのはあたりまえのことだ。', 'やくそくを まもるのは あたりまえの ことだ。', 'Giữ lời hứa là chuyện đương nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10101, 39547, 'くだらないことで喧嘩するのはやめよう。', 'くだらない ことで けんか するのは やめよう。', 'Thôi đừng cãi nhau vì chuyện vớ vẩn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10102, 39638, '彼の話はでたらめだった。', 'かれの はなしは でたらめ だった。', 'Câu chuyện của anh ta là bịa đặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10103, 39639, '公園のテニスコートを予約した。', 'こうえんの テニスコートを よやく した。', 'Tôi đặt sân tennis ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10105, 39667, '高校のとき、友達とバンドを組んでいた。', 'こうこうの とき、ともだちと バンドを くんで いた。', 'Hồi cấp ba tôi lập ban nhạc với bạn bè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10106, 39723, '工事の音がやかましい。', 'こうじの おとが やかましい。', 'Tiếng công trình ồn ào quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10107, 39921, 'パンにハムを挟んで食べた。', 'パンに ハムを はさんで たべた。', 'Tôi kẹp giăm bông vào bánh mì để ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10108, 39926, '膝を曲げて、ゆっくり座ってください。', 'ひざを まげて、ゆっくり すわって ください。', 'Hãy gập gối và từ từ ngồi xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10109, 39930, '顔を近付けて、小さな字を読んだ。', 'かおを ちかづけて、ちいさな じを よんだ。', 'Tôi ghé mặt lại gần để đọc chữ nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10110, 39934, '長い文を区切って読んでください。', 'ながい ぶんを くぎって よんで ください。', 'Hãy ngắt câu dài ra mà đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10111, 39970, '山の上から町を見下ろした。', 'やまの うえから まちを みおろした。', 'Từ trên núi tôi nhìn xuống thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10112, 40027, 'テーブルの上に地図を広げた。', 'テーブルの うえに ちずを ひろげた。', 'Tôi trải tấm bản đồ lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10113, 40024, 'この町は伝統的な工芸で有名だ。', 'この まちは でんとうてきな こうげいで ゆうめいだ。', 'Thị trấn này nổi tiếng với nghề thủ công truyền thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10114, 38284, '政府は事態を憂慮している。', 'せいふは じたいを ゆうりょ して いる。', 'Chính phủ đang lo âu sâu sắc về tình hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10115, 38290, '両国の間で粘り強い折衝が続いた。', 'りょうこくの あいだで ねばりづよい せっしょうが つづいた。', 'Cuộc đàm phán bền bỉ giữa hai nước vẫn tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10116, 38292, '交渉は最後に決裂した。', 'こうしょうは さいごに けつれつ した。', 'Cuối cùng cuộc đàm phán đã đổ vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10117, 38297, '先生が二人のけんかを仲裁した。', 'せんせいが ふたりの けんかを ちゅうさい した。', 'Thầy giáo đã can ngăn cuộc cãi nhau của hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10118, 38300, '嫁と姑の折り合いが悪い。', 'よめと しゅうとめの おりあいが わるい。', 'Mẹ chồng nàng dâu không hòa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10119, 38286, 'この鳥は絶滅危惧種に指定されている。', 'この とりは ぜつめつ きぐしゅに してい されて いる。', 'Loài chim này được xếp vào loài có nguy cơ tuyệt chủng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10120, 38295, '警察が犯人の家に突入した。', 'けいさつが はんにんの いえに とつにゅう した。', 'Cảnh sát đã xông vào nhà thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10121, 38288, '平穏な毎日を送っている。', 'へいおんな まいにちを おくって いる。', 'Tôi đang sống những ngày bình yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10122, 38273, '状況に応じて臨機応変に対応してください。', 'じょうきょうに おうじて りんき おうへんに たいおう して ください。', 'Hãy ứng biến linh hoạt tùy tình huống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10123, 38319, '電力の自由化で、会社を選べるようになった。', 'でんりょくの じゆうかで、かいしゃを えらべる ように なった。', 'Nhờ tự do hóa ngành điện, giờ ta có thể chọn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10124, 40082, '雨にぬれた自転車が錆びてしまった。', 'あめに ぬれた じてんしゃが さびて しまった。', 'Chiếc xe đạp bị dầm mưa đã gỉ sét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10125, 40143, 'ホテルの予約を取り消した。', 'ホテルの よやくを とりけした。', 'Tôi đã hủy đặt phòng khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10126, 40144, 'お客様の意見を取り入れて、商品を改良した。', 'おきゃくさまの いけんを とりいれて、しょうひんを かいりょう した。', 'Chúng tôi tiếp thu ý kiến khách hàng để cải tiến sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10127, 40247, '停電で部屋が真っ暗になった。', 'ていでんで へやが まっくらに なった。', 'Mất điện làm căn phòng tối om.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10128, 40249, '事故の知らせを聞いて、顔が真っ青になった。', 'じこの しらせを きいて、かおが まっさおに なった。', 'Nghe tin tai nạn, mặt tôi tái mét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10129, 40298, '山の清い水で作った酒だ。', 'やまの きよい みずで つくった さけだ。', 'Đây là rượu làm từ nước suối trong lành trên núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10130, 40325, '暑いので、うちわで扇いだ。', 'あついので、うちわで あおいだ。', 'Nóng quá nên tôi quạt bằng quạt tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10131, 40335, '彼は優勝を狙っている。', 'かれは ゆうしょうを ねらって いる。', 'Anh ấy đang nhắm tới chức vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10132, 40342, '鮭は川を遡る。', 'さけは かわを さかのぼる。', 'Cá hồi bơi ngược dòng sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10133, 42947, 'この倉庫で米を貯蔵している。', 'この そうこで こめを ちょぞう して いる。', 'Gạo được trữ trong nhà kho này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10134, 43001, 'クラスのTシャツの色を統一した。', 'クラスの ティーシャツの いろを とういつ した。', 'Lớp tôi thống nhất màu áo phông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10135, 29482, 'ニュースによると、台風が来るそうです。', 'ニュースに よると、たいふうが くる そう です。', 'Theo tin tức thì bão sắp đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10136, 29492, '祖母は九十歳まで長生きしました。', 'そぼは きゅうじゅっさいまで ながいき しました。', 'Bà tôi sống thọ đến chín mươi tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10137, 29507, 'デパートで化粧品を買いました。', 'デパートで けしょうひんを かいました。', 'Tôi mua mỹ phẩm ở trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10138, 40369, 'いいアイデアが浮かんだ。', 'いい アイデアが うかんだ。', 'Tôi nảy ra một ý tưởng hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10139, 38320, '国鉄は一九八七年に民営化された。', 'こくてつは せんきゅうひゃく はちじゅうななねんに みんえいか された。', 'Đường sắt quốc gia được tư nhân hóa năm 1987.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10140, 38318, '自転車のヘルメット着用が義務化された。', 'じてんしゃの ヘルメット ちゃくようが ぎむか された。', 'Đội mũ bảo hiểm khi đi xe đạp đã trở thành bắt buộc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10141, 40376, '彼はアマチュアのカメラマンだ。', 'かれは アマチュアの カメラマンだ。', 'Anh ấy là nhiếp ảnh gia nghiệp dư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10142, 38306, '組織が硬直化して、新しい発想が生まれない。', 'そしきが こうちょくか して、あたらしい はっそうが うまれない。', 'Tổ chức trở nên cứng nhắc nên không nảy sinh ý tưởng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10143, 38308, 'グローバル化で文化の均質化が進んでいる。', 'グローバルかで ぶんかの きんしつかが すすんで いる。', 'Toàn cầu hóa khiến văn hóa ngày càng đồng đều hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10144, 38310, '仕事が細分化されすぎて、全体が見えない。', 'しごとが さいぶんか され すぎて、ぜんたいが みえない。', 'Công việc bị chia nhỏ quá nên không thấy được tổng thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10145, 38314, '社会問題はますます複合化している。', 'しゃかい もんだいは ますます ふくごうか して いる。', 'Các vấn đề xã hội ngày càng trở nên phức hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10146, 40373, 'この料理はあっさりした味だ。', 'この りょうりは あっさり した あじだ。', 'Món này có vị thanh đạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10147, 43308, 'はじめまして。リンと申します。', 'はじめまして。リンと もうします。', 'Rất vui được gặp anh. Tôi tên là Linh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10148, 40323, 'トランプで未来を占ってもらった。', 'トランプで みらいを うらなって もらった。', 'Tôi được bói tương lai bằng bài tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10149, 40343, '彼は趣味で小説を創作している。', 'かれは しゅみで しょうせつを そうさく して いる。', 'Anh ấy sáng tác tiểu thuyết như một sở thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10150, 42901, '社員旅行でレクリエーションを楽しんだ。', 'しゃいん りょこうで レクリエーションを たのしんだ。', 'Trong chuyến du lịch công ty, mọi người vui chơi giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10151, 43039, '授業で季節の俳句を作った。', 'じゅぎょうで きせつの はいくを つくった。', 'Trong giờ học chúng tôi làm thơ haiku về mùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10152, 43040, 'お寺で仏様を拝んだ。', 'おてらで ほとけさまを おがんだ。', 'Tôi vái Phật ở chùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10153, 43070, 'この本は表紙のデザインがきれいだ。', 'この ほんは ひょうしの デザインが きれいだ。', 'Cuốn sách này có thiết kế bìa đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10154, 43082, '子供が風船を持って走っている。', 'こどもが ふうせんを もって はしって いる。', 'Đứa trẻ cầm bóng bay chạy nhảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10155, 43096, 'この作家の文体はとても読みやすい。', 'この さっかの ぶんたいは とても よみやすい。', 'Văn phong của nhà văn này rất dễ đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10156, 43137, '祖母は地元の民謡を歌うのが上手だ。', 'そぼは じもとの みんようを うたうのが じょうずだ。', 'Bà tôi hát dân ca địa phương rất hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10157, 43158, 'まず目次を見て、読みたい章を探した。', 'まず もくじを みて、よみたい しょうを さがした。', 'Trước tiên tôi xem mục lục để tìm chương muốn đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10158, 43175, '日曜日に子供を連れて遊園地に行った。', 'にちようびに こどもを つれて ゆうえんちに いった。', 'Chủ nhật tôi đưa con đi công viên giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10159, 43219, '祖母は今でも毎日和服を着ている。', 'そぼは いまでも まいにち わふくを きて いる。', 'Đến giờ bà tôi vẫn mặc trang phục truyền thống Nhật mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10160, 39502, 'テレビのインタビューを受けた。', 'テレビの インタビューを うけた。', 'Tôi được truyền hình phỏng vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10161, 39513, '工場はオートメーションで動いている。', 'こうじょうは オートメーションで うごいて いる。', 'Nhà máy vận hành tự động hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10162, 39573, '遠くで救急車のサイレンが鳴っている。', 'とおくで きゅうきゅうしゃの サイレンが なって いる。', 'Từ xa vọng lại tiếng còi xe cứu thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10163, 40400, '妻のお産に立ち会った。', 'つまの おさんに たちあった。', 'Tôi đã có mặt khi vợ sinh con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10164, 40394, '夜の山道はおっかない。', 'よるの やまみちは おっかない。', 'Đường núi ban đêm đáng sợ lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10165, 40403, 'お世辞でも褒められるとうれしい。', 'おせじでも ほめられると うれしい。', 'Dù chỉ là lời khen xã giao thì vẫn vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10166, 40404, '赤ちゃんのおむつを替えた。', 'あかちゃんの おむつを かえた。', 'Tôi đã thay tã cho em bé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10167, 40375, '靴を左右あべこべに履いていた。', 'くつを さゆう あべこべに はいて いた。', 'Tôi đi giày ngược bên trái phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10168, 40398, '近所のお宮で夏祭りがある。', 'きんじょの おみやで なつまつりが ある。', 'Ở đền gần nhà có lễ hội mùa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10169, 40383, 'いざという時のために、水を用意しておく。', 'いざと いう ときの ために、みずを ようい して おく。', 'Chuẩn bị sẵn nước để phòng khi cần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10170, 40385, '今日はいやに静かだね。', 'きょうは いやに しずかだね。', 'Hôm nay yên tĩnh lạ thường nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10171, 40408, '彼はがっしりした体格をしている。', 'かれは がっしり した たいかくを して いる。', 'Anh ấy có thân hình vạm vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10172, 40409, '二人はがっちり握手した。', 'ふたりは がっちり あくしゅ した。', 'Hai người bắt tay thật chặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10173, 39610, '発表ではスライドを使って説明した。', 'はっぴょうでは スライドを つかって せつめい した。', 'Khi thuyết trình tôi dùng slide để giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10174, 39742, 'ファイルを圧縮してメールで送った。', 'ファイルを あっしゅく して メールで おくった。', 'Tôi nén tệp rồi gửi qua email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10175, 39738, 'カメラのレンズをきれいにふいた。', 'カメラの レンズを きれいに ふいた。', 'Tôi lau sạch ống kính máy ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10176, 39974, '新聞の見出しだけ読んだ。', 'しんぶんの みだし だけ よんだ。', 'Tôi chỉ đọc tiêu đề báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10177, 40003, '会社宛ての手紙には「御中」と書く。', 'かいしゃあての てがみには 「おんちゅう」と かく。', 'Thư gửi công ty thì ghi "Kính gửi".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10330, 26992, '失礼ですが、お名前は?', 'しつれい ですが、おなまえは?', 'Xin lỗi, tên anh là gì ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10179, 43018, '内線の二〇三番におかけください。', 'ないせんの にーまるさんばんに おかけ ください。', 'Xin gọi số nội bộ 203.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10180, 43083, '書類の無断複写は禁止されています。', 'しょるいの むだん ふくしゃは きんし されて います。', 'Cấm sao chép tài liệu khi chưa được phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10181, 43198, 'この欄に名前を書いてください。', 'この らんに なまえを かいて ください。', 'Hãy ghi tên vào ô này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10182, 31696, '留学が人生の転機になった。', 'りゅうがくが じんせいの てんきに なった。', 'Du học đã trở thành bước ngoặt cuộc đời tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10183, 31698, '今が会社を始める好機だ。', 'いまが かいしゃを はじめる こうきだ。', 'Bây giờ là thời cơ tốt để mở công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10184, 37812, 'この町の魅力は自然の美しさだ。', 'この まちの みりょくは しぜんの うつくしさだ。', 'Sức hút của thị trấn này là vẻ đẹp thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10185, 38138, '手続きを単純化して、時間を短くした。', 'てつづきを たんじゅんか して、じかんを みじかく した。', 'Đơn giản hóa thủ tục để rút ngắn thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10186, 39820, 'この話に出てくる町は架空のものだ。', 'この はなしに でて くる まちは かくうの ものだ。', 'Thị trấn trong câu chuyện này là hư cấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10187, 39894, '彼のことは間接的に聞いた。', 'かれの ことは かんせつてきに きいた。', 'Chuyện của anh ấy tôi nghe gián tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10188, 39943, 'これは命に係わる問題だ。', 'これは いのちに かかわる もんだいだ。', 'Đây là vấn đề liên quan đến tính mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10189, 39948, '旅行中、天気に恵まれた。', 'りょこうちゅう、てんきに めぐまれた。', 'Trong chuyến du lịch, chúng tôi gặp thời tiết thuận lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10190, 39992, '間違っている個所に線を引きなさい。', 'まちがって いる かしょに せんを ひきなさい。', 'Hãy gạch dưới chỗ bị sai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10191, 40427, '今日の番組のゲストは有名な歌手だ。', 'きょうの ばんぐみの ゲストは ゆうめいな かしゅだ。', 'Khách mời của chương trình hôm nay là một ca sĩ nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10192, 40421, '彼女は十年のキャリアを持つ看護師だ。', 'かのじょは じゅうねんの キャリアを もつ かんごしだ。', 'Cô ấy là y tá có mười năm kinh nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10193, 40414, '車をガレージに入れた。', 'くるまを ガレージに いれた。', 'Tôi đã cho xe vào gara.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10194, 40420, '飛んできたボールをキャッチした。', 'とんで きた ボールを キャッチ した。', 'Tôi bắt được quả bóng bay tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10195, 40416, '書類をきちっと整理しておいてください。', 'しょるいを きちっと せいり して おいて ください。', 'Hãy sắp xếp giấy tờ gọn gàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10196, 40419, '彼女は誘いをきっぱり断った。', 'かのじょは さそいを きっぱり ことわった。', 'Cô ấy dứt khoát từ chối lời mời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10197, 40424, '練習のおかげで、ぐっと上手になった。', 'れんしゅうの おかげで、ぐっと じょうずに なった。', 'Nhờ luyện tập mà tôi giỏi hơn hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10198, 40037, '人気の店の前に行列ができている。', 'にんきの みせの まえに ぎょうれつが できて いる。', 'Trước quán nổi tiếng có hàng người xếp dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10199, 40057, '差し支えなければ、お名前を教えてください。', 'さしつかえ なければ、おなまえを おしえて ください。', 'Nếu không phiền, xin cho biết tên anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10200, 40130, '実例を挙げて説明します。', 'じつれいを あげて せつめい します。', 'Tôi xin lấy ví dụ thực tế để giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10201, 40149, '駅の手前にコンビニがある。', 'えきの てまえに コンビニが ある。', 'Ngay trước ga có cửa hàng tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10202, 40192, '道の所々に雪が残っている。', 'みちの ところどころに ゆきが のこって いる。', 'Đó đây trên đường vẫn còn tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10203, 40333, 'スポーツ全般が好きだ。', 'スポーツ ぜんぱんが すきだ。', 'Tôi thích thể thao nói chung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10204, 40340, 'この服の色の組み合わせはおしゃれだ。', 'この ふくの いろの くみあわせは おしゃれだ。', 'Cách phối màu của bộ đồ này thật sành điệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10205, 42962, 'この切符は明日まで通用する。', 'この きっぷは あしたまで つうよう する。', 'Vé này có giá trị đến ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10206, 43073, '不運なことに、旅行中ずっと雨だった。', 'ふうんな ことに、りょこうちゅう ずっと あめ だった。', 'Không may là suốt chuyến du lịch trời đều mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10207, 43179, '予備の電池を持っていこう。', 'よびの でんちを もって いこう。', 'Mang theo pin dự phòng nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10208, 43188, 'この道具はいろいろな用途に使える。', 'この どうぐは いろいろな ようとに つかえる。', 'Dụng cụ này dùng được cho nhiều mục đích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10209, 43205, '道の両側に桜が咲いている。', 'みちの りょうがわに さくらが さいて いる。', 'Hai bên đường hoa anh đào nở rộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10210, 39552, 'くれぐれも体に気をつけてください。', 'くれぐれも からだに きを つけて ください。', 'Hãy hết sức giữ gìn sức khỏe nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10211, 39555, '遅くまで、ごくろうさま。', 'おそくまで、ごくろうさま。', 'Cảm ơn bạn đã vất vả đến khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10212, 39558, 'こちらこそ、よろしくお願いします。', 'こちらこそ、よろしく おねがい します。', 'Chính tôi mới phải nhờ anh giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10213, 39565, 'ごめんください。田中さんはいらっしゃいますか。', 'ごめん ください。たなかさんは いらっしゃいますか。', 'Xin phép ạ. Anh Tanaka có nhà không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10214, 39575, 'さっさと宿題を終わらせなさい。', 'さっさと しゅくだいを おわらせなさい。', 'Mau làm xong bài tập đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10215, 39582, '先生が来ると、教室がしいんとなった。', 'せんせいが くると、きょうしつが しいんと なった。', 'Thầy đến là lớp học im phăng phắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10216, 39681, '祖父はぶつぶつ文句を言っている。', 'そふは ぶつぶつ もんくを いって いる。', 'Ông tôi đang lẩm bẩm càu nhàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10217, 39726, '台風なら、中止もやむをえない。', 'たいふうなら、ちゅうしも やむを えない。', 'Nếu có bão thì hủy cũng là bất đắc dĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10218, 40482, '母は昔、タイピストとして働いていた。', 'ははは むかし、タイピストと して はたらいて いた。', 'Ngày trước mẹ tôi làm nghề đánh máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10219, 40480, '鉛筆を一ダース買った。', 'えんぴつを いちダース かった。', 'Tôi mua một tá bút chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10220, 40443, '大事な面接でしくじった。', 'だいじな めんせつで しくじった。', 'Tôi đã thất bại trong buổi phỏng vấn quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10221, 40481, 'この本のタイトルは何ですか。', 'この ほんの タイトルは なん ですか。', 'Tựa đề cuốn sách này là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10222, 40445, 'じっくり考えてから返事をします。', 'じっくり かんがえてから へんじを します。', 'Tôi sẽ suy nghĩ kỹ rồi trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10223, 40455, '彼はしょっちゅう遅刻する。', 'かれは しょっちゅう ちこく する。', 'Anh ta suốt ngày đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10224, 39759, '今日は一段と寒い。', 'きょうは いちだんと さむい。', 'Hôm nay lạnh hơn hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10225, 39810, '何々?その話、詳しく聞かせて。', 'なになに?その はなし、くわしく きかせて。', 'Gì cơ gì cơ? Kể chi tiết chuyện đó đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10226, 39841, '改めてご連絡いたします。', 'あらためて ごれんらく いたします。', 'Tôi sẽ liên lạc lại với anh sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10227, 39893, '間もなく電車が参ります。', 'まもなく でんしゃが まいります。', 'Tàu sắp vào ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10228, 39987, '現に彼はそこにいたと言っている。', 'げんに かれは そこに いたと いって いる。', 'Thực tế là anh ta nói đã ở đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10229, 40062, '再三注意したのに、彼はまた遅刻した。', 'さいさん ちゅうい したのに、かれは また ちこく した。', 'Đã nhắc nhiều lần mà anh ta vẫn đi muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10230, 40189, '名前を呼ばれた人から順々に入ってください。', 'なまえを よばれた ひとから じゅんじゅんに はいって ください。', 'Ai được gọi tên thì lần lượt vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10231, 43061, '今年の冬は比較的暖かい。', 'ことしの ふゆは ひかくてき あたたかい。', 'Mùa đông năm nay tương đối ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10232, 43132, '合格の知らせに、みんなで万歳をした。', 'ごうかくの しらせに、みんなで ばんざいを した。', 'Nhận tin đỗ, mọi người cùng hô vạn tuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10233, 43172, '時間があったので、悠々と歩いて帰った。', 'じかんが あったので、ゆうゆうと あるいて かえった。', 'Còn thời gian nên tôi ung dung đi bộ về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10234, 39530, 'かしこまりました。すぐにお持ちします。', 'かしこまりました。すぐに おもち します。', 'Vâng, tôi hiểu rồi. Tôi sẽ mang đến ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10235, 43787, 'ごちそうさま。とてもおいしかった。', 'ごちそうさま。とても おいしかった。', 'Cảm ơn vì bữa ăn, ngon lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10236, 44535, '日曜日に子供を連れて遊園地に行った。', 'にちようびに こどもを つれて ゆうえんちに いった。', 'Chủ nhật tôi đưa con đi công viên giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10237, 39625, '昔の電話はダイヤルを回してかけた。', 'むかしの でんわは ダイヤルを まわして かけた。', 'Điện thoại ngày xưa phải quay số để gọi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10238, 39669, '床をぴかぴかに磨いた。', 'ゆかを ぴかぴかに みがいた。', 'Tôi đánh bóng sàn sáng loáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10239, 47441, '親のありがたさをしみじみ感じた。', 'おやの ありがたさを しみじみ かんじた。', 'Tôi thấm thía công ơn của cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10240, 47516, '昔の武士は刀を持っていた。', 'むかしの ぶしは かたなを もって いた。', 'Võ sĩ ngày xưa mang kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10241, 47538, '授業で季節の俳句を作った。', 'じゅぎょうで きせつの はいくを つくった。', 'Trong giờ học chúng tôi làm thơ haiku về mùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10242, 47898, '授業で季節の俳句を作った。', 'じゅぎょうで きせつの はいくを つくった。', 'Trong giờ học chúng tôi làm thơ haiku về mùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10243, 48252, '小学生のころ、書道を習っていた。', 'しょうがくせいの ころ、しょどうを ならって いた。', 'Hồi tiểu học tôi từng học thư pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10244, 39491, '駅のあちらこちらに案内が出ている。', 'えきの あちらこちらに あんないが でて いる。', 'Khắp nơi trong ga đều có biển chỉ dẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10245, 39492, '次の説明に当てはまるものを選びなさい。', 'つぎの せつめいに あてはまる ものを えらびなさい。', 'Hãy chọn đáp án phù hợp với lời giải thích sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10246, 39501, 'いちいち説明しなくてもわかるよ。', 'いちいち せつめい しなくても わかるよ。', 'Không cần giải thích từng li từng tí, tôi hiểu mà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10247, 39506, '道がわからなくて、駅の周りをうろうろした。', 'みちが わからなくて、えきの まわりを うろうろ した。', 'Không biết đường nên tôi lòng vòng quanh ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10248, 40484, '話しかけるタイミングを逃した。', 'はなしかける タイミングを のがした。', 'Tôi lỡ mất thời điểm bắt chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10249, 40487, '風邪でダウンしてしまった。', 'かぜで ダウン して しまった。', 'Tôi gục vì cảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10250, 39508, 'ええと、駅はどっちだったかな。', 'ええと、えきは どっち だったかな。', 'À ừm, ga ở hướng nào nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10251, 39515, 'おじゃまします。素敵なお部屋ですね。', 'おじゃまします。すてきな おへや ですね。', 'Xin phép làm phiền ạ. Căn phòng đẹp quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10252, 39520, 'おまたせしました。こちらがご注文の品です。', 'おまたせ しました。こちらが ごちゅうもんの しな です。', 'Xin lỗi đã để quý khách chờ. Đây là món quý khách đã gọi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10331, 43494, '午前九時に会社へ行きます。', 'ごぜん くじに かいしゃへ いきます。', 'Chín giờ sáng tôi đến công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10253, 39522, 'おまちどおさま。ラーメンです。', 'おまちどおさま。ラーメン です。', 'Để quý khách chờ lâu rồi. Mì ramen đây ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10254, 39587, '親のありがたさをしみじみ感じた。', 'おやの ありがたさを しみじみ かんじた。', 'Tôi thấm thía công ơn của cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10255, 39600, '駅まで少なくとも二十分はかかる。', 'えきまで すくなくとも にじゅっぷんは かかる。', 'Đến ga ít nhất cũng mất hai mươi phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10256, 39609, '遅くなって、すまない。', 'おそく なって、すまない。', 'Xin lỗi vì đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10257, 39617, 'そういえば、明日は母の誕生日だ。', 'そういえば、あしたは ははの たんじょうびだ。', 'Nói mới nhớ, mai là sinh nhật mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10258, 39618, '毎日練習した。そうして、ついに優勝した。', 'まいにち れんしゅう した。そうして、ついに ゆうしょう した。', 'Ngày nào cũng luyện tập. Rồi cuối cùng đã vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10259, 39621, 'そのほかに質問はありますか。', 'その ほかに しつもんは ありますか。', 'Ngoài ra còn câu hỏi nào không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10260, 39622, 'そんな高い物は買えない。だいいち、お金がない。', 'そんな たかい ものは かえない。だいいち、おかねが ない。', 'Đồ đắt thế không mua nổi. Trước hết là không có tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10261, 39637, '今日の会議のテーマは安全対策です。', 'きょうの かいぎの テーマは あんぜん たいさく です。', 'Chủ đề cuộc họp hôm nay là biện pháp an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10262, 39635, '買い物のついでに、本屋に寄った。', 'かいものの ついでに、ほんやに よった。', 'Tiện đi mua sắm, tôi ghé hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10263, 39641, '田中です。どうぞよろしく。', 'たなか です。どうぞ よろしく。', 'Tôi là Tanaka. Rất hân hạnh được làm quen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10264, 39644, '彼の冗談で、みんながどっと笑った。', 'かれの じょうだんで、みんなが どっと わらった。', 'Câu đùa của anh ấy làm mọi người cười ồ lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10265, 39650, 'なにしろ初めてなので、よくわかりません。', 'なにしろ はじめて なので、よく わかりません。', 'Dù sao cũng là lần đầu nên tôi chưa rõ lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10266, 39656, '渋滞で車がのろのろ進んでいる。', 'じゅうたいで くるまが のろのろ すすんで いる。', 'Tắc đường nên xe cộ nhích từng chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10267, 39661, '彼の行動にはいつも同じパターンがある。', 'かれの こうどうには いつも おなじ パターンが ある。', 'Hành động của anh ấy lúc nào cũng theo một khuôn mẫu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10268, 39665, '栄養のバランスを考えて食事をしよう。', 'えいようの バランスを かんがえて しょくじを しよう。', 'Hãy ăn uống chú ý cân bằng dinh dưỡng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10269, 39692, 'このパンケーキはふわふわだ。', 'この パンケーキは ふわふわだ。', 'Chiếc bánh kếp này mềm xốp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10270, 39701, '駅が広くて、まごまごしてしまった。', 'えきが ひろくて、まごまご して しまった。', 'Nhà ga rộng quá nên tôi lúng túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10271, 39717, 'もしかすると、明日は雪かもしれない。', 'もしかすると、あしたは ゆきかも しれない。', 'Có khi ngày mai tuyết rơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10272, 40488, 'たった一日で全部読んだ。', 'たった いちにちで ぜんぶ よんだ。', 'Tôi đọc hết chỉ trong vỏn vẹn một ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10273, 40497, '彼は子供のころからちやほやされて育った。', 'かれは こどもの ころから ちやほや されて そだった。', 'Cậu ta lớn lên trong sự nuông chiều từ nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10274, 40500, '駅で彼の姿をちらっと見た。', 'えきで かれの すがたを ちらっと みた。', 'Tôi thoáng thấy bóng anh ấy ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10275, 39928, '近々、引っ越す予定です。', 'ちかぢか、ひっこす よてい です。', 'Sắp tới tôi định chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10276, 40200, '勝敗より、最後まで頑張ることが大切だ。', 'しょうはいより、さいごまで がんばる ことが たいせつだ。', 'Cố gắng đến cùng quan trọng hơn thắng bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10277, 40254, '神様に合格をお願いした。', 'かみさまに ごうかくを おねがい した。', 'Tôi cầu xin thần linh cho mình thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10278, 40256, '鉛筆の芯が折れた。', 'えんぴつの しんが おれた。', 'Ruột bút chì bị gãy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10279, 40302, '新しい仕事を始めて、彼は生き生きしている。', 'あたらしい しごとを はじめて、かれは いきいき して いる。', 'Bắt đầu công việc mới, anh ấy tràn đầy sức sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10280, 40365, '会場に人が続々と集まってきた。', 'かいじょうに ひとが ぞくぞくと あつまって きた。', 'Mọi người lần lượt kéo đến hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10281, 42895, 'おはよう。よく眠れた?', 'おはよう。よく ねむれた?', 'Chào buổi sáng. Ngủ ngon không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10282, 42897, '行きたいけれど、時間がない。', 'いきたい けれど、じかんが ない。', 'Muốn đi lắm nhưng không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10283, 42916, '費用はおおよそ十万円です。', 'ひようは おおよそ じゅうまんえん です。', 'Chi phí khoảng chừng một trăm nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10284, 42936, '新しい駅の工事が着々と進んでいる。', 'あたらしい えきの こうじが ちゃくちゃくと すすんで いる。', 'Công trình nhà ga mới đang tiến triển vững chắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10285, 42988, '主人公が登場すると、会場が盛り上がった。', 'しゅじんこうが とうじょう すると、かいじょうが もりあがった。', 'Nhân vật chính xuất hiện thì cả khán phòng sôi động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10286, 42990, '新聞に意見を投書した。', 'しんぶんに いけんを とうしょ した。', 'Tôi gửi thư góp ý cho tòa báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10287, 43115, '新宿方面の電車は二番線です。', 'しんじゅく ほうめんの でんしゃは にばんせん です。', 'Tàu đi hướng Shinjuku ở đường ray số hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10288, 27030, 'ボールペンを貸してください。', 'ボールペンを かして ください。', 'Cho tôi mượn cây bút bi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10332, 43496, '朝、コーヒーを飲みます。', 'あさ、コーヒーを のみます。', 'Buổi sáng tôi uống cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10289, 40556, '選手たちは大会をボイコットした。', 'せんしゅたちは たいかいを ボイコット した。', 'Các vận động viên đã tẩy chay giải đấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10290, 27179, 'えーと、ちょっと待ってください。', 'えーと、ちょっと まって ください。', 'À, để xem nào, chờ tôi một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10291, 26993, 'すみません、お名前は?――山田です。', 'すみません、おなまえは?――やまだ です。', 'Xin lỗi, tên anh là gì? – Tôi là Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10292, 43255, '日曜日、家族と公園へ行きます。', 'にちようび、かぞくと こうえんへ いきます。', 'Chủ nhật tôi đi công viên với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10293, 27075, '教室は三階です。', 'きょうしつは さんがい です。', 'Lớp học ở tầng ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10294, 27047, 'ミラーさんは英語の先生です。', 'ミラーさんは えいごの せんせい です。', 'Anh Miller là giáo viên tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10295, 40544, 'フェリーで島に渡った。', 'フェリーで しまに わたった。', 'Tôi sang đảo bằng phà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10296, 40539, 'マラソン大会でびりになった。', 'マラソン たいかいで びりに なった。', 'Tôi về bét trong cuộc thi marathon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10297, 40551, '二人一組のペアになってください。', 'ふたり ひとくみの ペアに なって ください。', 'Hãy chia thành từng cặp hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10298, 40554, '試合ではベストを尽くした。', 'しあいでは ベストを つくした。', 'Trong trận đấu tôi đã cố gắng hết sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10299, 40541, 'エアコンのフィルターを掃除した。', 'エアコンの フィルターを そうじ した。', 'Tôi đã vệ sinh bộ lọc điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10300, 40548, '休みの日は町をぶらぶらする。', 'やすみの ひは まちを ぶらぶら する。', 'Ngày nghỉ tôi đi lang thang ngoài phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10301, 27120, '毎晩十一時に寝ます。', 'まいばん じゅういちじに ねます。', 'Tối nào tôi cũng ngủ lúc mười một giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10302, 43278, '誕生日はいつですか。', 'たんじょうびは いつ ですか。', 'Sinh nhật bạn là khi nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10303, 43321, 'どうぞ、この椅子に座ってください。', 'どうぞ、この いすに すわって ください。', 'Mời anh ngồi ghế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10304, 43330, 'その辞書は私のです。', 'その じしょは わたしの です。', 'Cuốn từ điển đó là của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10305, 29500, 'カリフォルニアは一年中暖かいです。', 'カリフォルニアは いちねんじゅう あたたかい です。', 'California ấm áp quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10306, 43334, '公園で写真を撮りました。', 'こうえんで しゃしんを とりました。', 'Tôi đã chụp ảnh ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10307, 43337, 'この鍵は車の鍵です。', 'この かぎは くるまの かぎ です。', 'Chiếc chìa này là chìa khóa xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10308, 43339, '新しい鞄を買いました。', 'あたらしい かばんを かいました。', 'Tôi đã mua chiếc cặp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10309, 27227, '七月七日は七夕です。', 'しちがつ なのかは たなばた です。', 'Ngày 7 tháng 7 là lễ Thất tịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10310, 27230, '十日に給料をもらいます。', 'とおかに きゅうりょうを もらいます。', 'Ngày mùng mười tôi nhận lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10311, 43374, 'スーパーで肉を買いました。', 'スーパーで にくを かいました。', 'Tôi đã mua thịt ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10312, 43376, '毎日野菜を食べます。', 'まいにち やさいを たべます。', 'Ngày nào tôi cũng ăn rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10313, 43378, '毎朝、卵を一つ食べます。', 'まいあさ、たまごを ひとつ たべます。', 'Sáng nào tôi cũng ăn một quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10314, 43382, 'お茶を飲みませんか。', 'おちゃを のみませんか。', 'Uống trà không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10315, 26970, 'あの人は誰ですか。', 'あの ひとは だれ ですか。', 'Người kia là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10316, 27238, 'A：いい天気ですね。B：そうですね。', 'エー：いい てんき ですね。ビー：そう ですね。', 'A: Thời tiết đẹp nhỉ. B: Đúng vậy nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10317, 43431, '教室は三階です。', 'きょうしつは さんがい です。', 'Lớp học ở tầng ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10318, 43435, '試験は九時からです。', 'しけんは くじから です。', 'Kỳ thi bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10319, 40570, '疲れたので、マッサージを受けた。', 'つかれたので、マッサージを うけた。', 'Mệt quá nên tôi đi mát-xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10320, 40573, '会場は楽しいムードに包まれていた。', 'かいじょうは たのしい ムードに つつまれて いた。', 'Hội trường tràn ngập không khí vui vẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10321, 40560, '彼は会社で重要なポジションにいる。', 'かれは かいしゃで じゅうような ポジションに いる。', 'Anh ấy giữ vị trí quan trọng trong công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10322, 40593, '毎週土曜日にピアノのレッスンを受けている。', 'まいしゅう どようびに ピアノの レッスンを うけて いる。', 'Thứ bảy hằng tuần tôi học đàn piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10323, 40562, 'ポットのお湯でお茶を入れた。', 'ポットの おゆで おちゃを いれた。', 'Tôi pha trà bằng nước nóng trong phích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10324, 40587, '瓶のラベルに賞味期限が書いてある。', 'びんの ラベルに しょうみ きげんが かいて ある。', 'Hạn sử dụng được ghi trên nhãn chai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10325, 40559, '市民ホールでコンサートが開かれる。', 'しみん ホールで コンサートが ひらかれる。', 'Buổi hòa nhạc sẽ được tổ chức ở hội trường thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10326, 40565, '眼鏡を外すと、景色がぼやける。', 'めがねを はずすと、けしきが ぼやける。', 'Bỏ kính ra thì cảnh vật nhòe đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10327, 40584, '彼はユニークな発想の持ち主だ。', 'かれは ユニークな はっそうの もちぬしだ。', 'Anh ấy là người có ý tưởng độc đáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10328, 40566, '日本の家庭の電圧は百ボルトだ。', 'にほんの かていの でんあつは ひゃく ボルトだ。', 'Điện áp gia đình ở Nhật là 100 vôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10329, 40571, '教科書にミスプリントが見つかった。', 'きょうかしょに ミスプリントが みつかった。', 'Phát hiện lỗi in trong sách giáo khoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10333, 43497, '昼は会社の食堂で食べます。', 'ひるは かいしゃの しょくどうで たべます。', 'Buổi trưa tôi ăn ở nhà ăn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10334, 27021, 'この本は日本語の本です。', 'この ほんは にほんごの ほん です。', 'Cuốn sách này là sách tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10335, 27033, 'その時計はいくらですか。', 'その とけいは いくら ですか。', 'Chiếc đồng hồ đó bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10336, 29514, '弟は毎晩塾に通っています。', 'おとうとは まいばん じゅくに かよって います。', 'Tối nào em trai tôi cũng đi học thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10337, 27026, '手帳に予定を書きます。', 'てちょうに よていを かきます。', 'Tôi ghi lịch hẹn vào sổ tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10338, 27027, 'これは私の名刺です。どうぞ。', 'これは わたしの めいし です。どうぞ。', 'Đây là danh thiếp của tôi. Xin mời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10339, 27057, 'A：これはあなたの傘ですか。B：いいえ、違います。', 'エー：これは あなたの かさ ですか。ビー：いいえ、ちがいます。', 'A: Đây là ô của bạn à? B: Không, không phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10340, 27060, 'A：よろしくお願いします。B：こちらこそよろしくお願いします。', 'エー：よろしく おねがい します。ビー：こちらこそ よろしく おねがい します。', 'A: Mong được giúp đỡ. B: Chính tôi mới phải nhờ anh giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10341, 27062, 'このテープは日本語の練習のテープです。', 'この テープは にほんごの れんしゅうの テープ です。', 'Cuộn băng này là băng luyện tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10342, 27095, '本屋は地下一階です。', 'ほんやは ちか いっかい です。', 'Hiệu sách ở tầng hầm một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10343, 27102, 'このカメラは三万円です。', 'この カメラは さんまんえん です。', 'Chiếc máy ảnh này giá ba mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10344, 27115, '新大阪から新幹線に乗ります。', 'しんおおさかから しんかんせんに のります。', 'Tôi lên tàu Shinkansen ở ga Shin-Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10345, 27046, 'これは京都のお土産です。', 'これは きょうとの おみやげ です。', 'Đây là quà Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10346, 40594, 'レディーファーストを心がけている。', 'レディーファーストを こころがけて いる。', 'Tôi luôn để ý nhường phụ nữ trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10347, 40597, '病院で胸のレントゲンを撮った。', 'びょういんで むねの レントゲンを とった。', 'Tôi chụp X-quang ngực ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10348, 40599, '夜景がきれいなロマンチックなレストランだ。', 'やけいが きれいな ロマンチックな レストランだ。', 'Đây là nhà hàng lãng mạn với cảnh đêm đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10349, 40608, 'これは山田さん宛の手紙です。', 'これは やまださん あての てがみ です。', 'Đây là lá thư gửi anh Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10350, 40611, '大統領の暗殺計画が明らかになった。', 'だいとうりょうの あんさつ けいかくが あきらかに なった。', 'Kế hoạch ám sát tổng thống đã bị phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10351, 40598, '船をロープで岸につないだ。', 'ふねを ロープで きしに つないだ。', 'Tôi buộc thuyền vào bờ bằng dây thừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10352, 40615, '停電で町は闇に包まれた。', 'ていでんで まちは やみに つつまれた。', 'Mất điện, thị trấn chìm trong bóng tối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10353, 40609, 'このかばんは安っぽく見える。', 'この かばんは やすっぽく みえる。', 'Chiếc túi này trông rẻ tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10354, 40602, '祖父の病状が悪化した。', 'そふの びょうじょうが あっか した。', 'Bệnh tình của ông đã chuyển nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10355, 40614, '案の定、彼は遅れてきた。', 'あんのじょう、かれは おくれて きた。', 'Quả đúng như dự đoán, anh ta đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10356, 40631, 'この辺りから古代の遺跡が見つかった。', 'この あたりから こだいの いせきが みつかった。', 'Người ta đã tìm thấy di tích cổ đại quanh đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10357, 27084, 'エレベーターで五階へ行きます。', 'エレベーターで ごかいへ いきます。', 'Tôi đi thang máy lên tầng năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10358, 29516, '書類をファイルに入れてください。', 'しょるいを ファイルに いれて ください。', 'Hãy cho giấy tờ vào bìa hồ sơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10359, 27121, '九時から五時まで働きます。', 'くじから ごじまで はたらきます。', 'Tôi làm việc từ chín giờ đến năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10360, 27129, '美術館は月曜日休みです。', 'びじゅつかんは げつようび やすみ です。', 'Bảo tàng mỹ thuật nghỉ vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10361, 27141, 'おととい、映画を見ました。', 'おととい、えいがを みました。', 'Hôm kia tôi đã xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10362, 27146, 'けさ、何も食べませんでした。', 'けさ、なにも たべませんでした。', 'Sáng nay tôi không ăn gì cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10363, 27153, '毎朝、公園を散歩します。', 'まいあさ、こうえんを さんぽ します。', 'Sáng nào tôi cũng đi dạo công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10364, 27160, '金曜日の晩、友達と飲みます。', 'きんようびの ばん、ともだちと のみます。', 'Tối thứ Sáu tôi đi uống với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10365, 27165, '銀行は三時までです。', 'ぎんこうは さんじまで です。', 'Ngân hàng mở cửa đến ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10366, 27177, 'みどり図書館は月曜日休みです。', 'みどり としょかんは げつようび やすみ です。', 'Thư viện Midori nghỉ vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10367, 27172, 'ペキンから友達が来ました。', 'ペキンから ともだちが きました。', 'Bạn tôi đến từ Bắc Kinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10368, 27174, '来月ロンドンへ行きます。', 'らいげつ ロンドンへ いきます。', 'Tháng sau tôi đi London.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10369, 27193, '飛行機で国へ帰ります。', 'ひこうきで くにへ かえります。', 'Tôi về nước bằng máy bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10370, 27196, '地下鉄で駅まで行きます。', 'ちかてつで えきまで いきます。', 'Tôi đi tàu điện ngầm đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10371, 27205, '彼女は東京に住んでいます。', 'かのじょは とうきょうに すんで います。', 'Cô ấy sống ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10374, 40626, 'この国は多くの移民を受け入れている。', 'この くには おおくの いみんを うけいれて いる。', 'Đất nước này tiếp nhận nhiều người di cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10375, 40623, '異性の友達と話すのは緊張する。', 'いせいの ともだちと はなすのは きんちょう する。', 'Nói chuyện với bạn khác giới làm tôi hồi hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10376, 40637, '父は三十年、この仕事一筋だ。', 'ちちは さんじゅうねん、この しごと ひとすじだ。', 'Ba mươi năm bố tôi một lòng với công việc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10377, 40628, '発表会のための衣装を用意した。', 'はっぴょうかいの ための いしょうを ようい した。', 'Tôi đã chuẩn bị trang phục cho buổi biểu diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10378, 40625, '定年後、沖縄に移住した。', 'ていねんご、おきなわに いじゅう した。', 'Sau khi nghỉ hưu tôi chuyển đến sống ở Okinawa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10379, 40634, '代金を一括で払った。', 'だいきんを いっかつで はらった。', 'Tôi trả tiền một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10380, 40630, '寝違えて首が痛い。', 'ねちがえて くびが いたい。', 'Tôi ngủ sai tư thế nên đau cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10381, 40622, 'この村には古い為来りが残っている。', 'この むらには ふるい しきたりが のこって いる。', 'Ngôi làng này vẫn còn giữ những tập tục xưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10382, 40620, '台風の威力はすさまじかった。', 'たいふうの いりょくは すさまじかった。', 'Sức tàn phá của cơn bão thật khủng khiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10383, 27221, '四月一日に会社に入りました。', 'しがつ ついたちに かいしゃに はいりました。', 'Tôi vào công ty ngày mùng một tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10384, 27243, '普通は各駅に止まります。', 'ふつうは かくえきに とまります。', 'Tàu thường dừng ở tất cả các ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10385, 43512, '火曜日に日本語の授業があります。', 'かようびに にほんごの じゅぎょうが あります。', 'Thứ Ba có giờ học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10386, 27198, 'バスで駅へ行きます。', 'バスで えきへ いきます。', 'Tôi đi xe buýt đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10387, 27254, '電車の中で音楽を聞きます。', 'でんしゃの なかで おんがくを ききます。', 'Tôi nghe nhạc trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10388, 27261, '一緒にごはんを食べませんか。', 'いっしょに ごはんを たべませんか。', 'Cùng đi ăn cơm không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10389, 27270, 'どんな果物が好きですか。', 'どんな くだものが すき ですか。', 'Bạn thích loại trái cây nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10390, 27285, '今晩、宿題をします。', 'こんばん、しゅくだいを します。', 'Tối nay tôi làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10391, 27301, '大阪デパートは十時から八時までです。', 'おおさか デパートは じゅうじから はちじまで です。', 'Trung tâm thương mại Osaka mở cửa từ mười giờ đến tám giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10392, 43517, '日曜日、どこへ行きますか。', 'にちようび、どこへ いきますか。', 'Chủ nhật bạn đi đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10393, 27168, '電話番号は何番ですか。', 'でんわ ばんごうは なんばん ですか。', 'Số điện thoại là số mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10394, 43552, '新幹線で大阪へ行きます。', 'しんかんせんで おおさかへ いきます。', 'Tôi đi Osaka bằng tàu Shinkansen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10395, 43615, '日曜日、家族と公園へ行きます。', 'にちようび、かぞくと こうえんへ いきます。', 'Chủ nhật tôi đi công viên với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10396, 43634, '友達と映画を見ました。', 'ともだちと えいがを みました。', 'Tôi đã xem phim với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10397, 43671, '私の部屋は狭いです。', 'わたしの へやは せまい です。', 'Phòng của tôi hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10398, 27131, '今、四時です。', 'いま、よじ です。', 'Bây giờ là bốn giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10399, 43699, '新しい鞄を買いました。', 'あたらしい かばんを かいました。', 'Tôi đã mua chiếc cặp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10400, 27134, '銀行は何時からですか。', 'ぎんこうは なんじから ですか。', 'Ngân hàng mở cửa từ mấy giờ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10401, 43735, '私は肉より魚が好きです。', 'わたしは にくより さかなが すき です。', 'Tôi thích cá hơn thịt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10402, 40661, 'この部屋は暗くて陰気だ。', 'この へやは くらくて いんきだ。', 'Căn phòng này tối tăm và ảm đạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10403, 40652, '書類に印を押してください。', 'しょるいに いんを おして ください。', 'Xin hãy đóng dấu vào giấy tờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10404, 40651, '稲光の後、大きな雷の音がした。', 'いなびかりの あと、おおきな かみなりの おとが した。', 'Sau ánh chớp là tiếng sấm lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10405, 40649, '一連の事件は同じ犯人によるものだった。', 'いちれんの じけんは おなじ はんにんに よる もの だった。', 'Hàng loạt vụ án là do cùng một thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10406, 40653, '彼は足を引きずって歩いていた。', 'かれは あしを ひきずって あるいて いた。', 'Anh ấy đi lê chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10407, 40655, '小さな不注意が大事故を引き起こした。', 'ちいさな ふちゅういが だいじこを ひきおこした。', 'Một sơ suất nhỏ đã gây ra tai nạn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10408, 40657, '沈んだ船が海から引き上げられた。', 'しずんだ ふねが うみから ひきあげられた。', 'Con tàu đắm đã được trục lên từ biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10409, 40659, '猫に手を引っ掻かれた。', 'ねこに てを ひっかかれた。', 'Tôi bị mèo cào vào tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10410, 40667, '今さら責任云々を言っても仕方がない。', 'いまさら せきにん うんぬんを いっても しかたが ない。', 'Giờ có nói chuyện trách nhiệm này nọ cũng vô ích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10411, 40668, 'バスの運賃は降りるときに払います。', 'バスの うんちんは おりる ときに はらいます。', 'Tiền vé xe buýt trả khi xuống xe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10412, 43737, 'どんな果物が好きですか。', 'どんな くだものが すき ですか。', 'Bạn thích loại trái cây nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10413, 43740, '毎朝、牛乳を飲みます。', 'まいあさ、ぎゅうにゅうを のみます。', 'Sáng nào tôi cũng uống sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10414, 43794, '今晩、宿題をします。', 'こんばん、しゅくだいを します。', 'Tối nay tôi làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10415, 43854, '午前九時に会社へ行きます。', 'ごぜん くじに かいしゃへ いきます。', 'Chín giờ sáng tôi đến công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10416, 43855, '午後は図書館で勉強します。', 'ごごは としょかんで べんきょう します。', 'Buổi chiều tôi học ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10417, 43857, '昼は会社の食堂で食べます。', 'ひるは かいしゃの しょくどうで たべます。', 'Buổi trưa tôi ăn ở nhà ăn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10418, 43863, '毎日、電車で会社へ行きます。', 'まいにち、でんしゃで かいしゃへ いきます。', 'Ngày nào tôi cũng đi làm bằng tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10419, 43864, '毎朝、公園を散歩します。', 'まいあさ、こうえんを さんぽ します。', 'Sáng nào tôi cũng đi dạo công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10420, 43867, '先週、京都へ行きました。', 'せんしゅう、きょうとへ いきました。', 'Tuần trước tôi đã đi Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10421, 43869, '来年、大学に入ります。', 'らいねん、だいがくに はいります。', 'Năm sau tôi vào đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10422, 43871, '月曜日から金曜日まで働きます。', 'げつようびから きんようびまで はたらきます。', 'Tôi làm việc từ thứ Hai đến thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10423, 43872, '火曜日に日本語の授業があります。', 'かようびに にほんごの じゅぎょうが あります。', 'Thứ Ba có giờ học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10424, 43875, '金曜日の晩、友達と飲みます。', 'きんようびの ばん、ともだちと のみます。', 'Tối thứ Sáu tôi đi uống với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10425, 43877, '日曜日、どこへ行きますか。', 'にちようび、どこへ いきますか。', 'Chủ nhật bạn đi đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10426, 43911, '地下鉄で駅まで行きます。', 'ちかてつで えきまで いきます。', 'Tôi đi tàu điện ngầm đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10427, 27052, 'あのう、すみません。駅はどこですか。', 'あのう、すみません。えきは どこ ですか。', 'À... xin lỗi. Ga ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10428, 27086, '自動販売機でジュースを買いました。', 'じどう はんばいきで ジュースを かいました。', 'Tôi mua nước ép ở máy bán hàng tự động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10429, 40680, '会議は円滑に進んだ。', 'かいぎは えんかつに すすんだ。', 'Cuộc họp diễn ra suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10430, 40699, 'けが人に応急の手当てをした。', 'けがにんに おうきゅうの てあてを した。', 'Tôi sơ cứu cho người bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10431, 40675, '毎朝、英字新聞を読んでいる。', 'まいあさ、えいじ しんぶんを よんで いる。', 'Sáng nào tôi cũng đọc báo tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10432, 40677, 'この資料は図書館で閲覧できる。', 'この しりょうは としょかんで えつらん できる。', 'Tài liệu này có thể đọc tại thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10433, 40669, 'トラックで木材を運搬する。', 'トラックで もくざいを うんぱん する。', 'Vận chuyển gỗ bằng xe tải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10434, 40693, '遠方からお越しいただき、ありがとうございます。', 'えんぽうから おこし いただき、ありがとう ございます。', 'Cảm ơn quý vị đã từ xa đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10435, 40683, 'イベントには延べ一万人が参加した。', 'イベントには のべ いちまんにんが さんか した。', 'Tổng cộng mười nghìn lượt người đã tham gia sự kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10436, 40692, '船の姿がだんだん遠ざかっていった。', 'ふねの すがたが だんだん とおざかって いった。', 'Bóng con tàu xa dần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10437, 40700, '開店と同時に客が押し寄せた。', 'かいてんと どうじに きゃくが おしよせた。', 'Cửa hàng vừa mở thì khách đã ùa tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10438, 27140, '晩、家族と話します。', 'ばん、かぞくと はなします。', 'Buổi tối tôi trò chuyện với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10439, 27224, '七月四日はアメリカの独立記念日です。', 'しちがつ よっかは アメリカの どくりつ きねんび です。', 'Ngày 4 tháng 7 là ngày Quốc khánh Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10440, 27468, '授業は九時から始まります。', 'じゅぎょうは くじから はじまります。', 'Giờ học bắt đầu từ chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10441, 44178, 'このカメラは日本のです。', 'この カメラは にほんの です。', 'Chiếc máy ảnh này là của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10442, 44273, '彼は私の友達です。', 'かれは わたしの ともだち です。', 'Anh ấy là bạn của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10443, 44412, '会議室はどこですか。', 'かいぎしつは どこ ですか。', 'Phòng họp ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10444, 27584, '二〇二〇年に日本へ来ました。', 'にせんにじゅうねんに にほんへ きました。', 'Tôi đến Nhật vào năm 2020.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10445, 27590, 'A：コーヒーを二つください。B：かしこまりました。', 'エー：コーヒーを ふたつ ください。ビー：かしこまりました。', 'A: Cho tôi hai cà phê. B: Vâng, tôi hiểu rồi ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10446, 27704, 'A：いい天気ですね。B：そうですね。', 'エー：いい てんき ですね。ビー：そう ですね。', 'A: Thời tiết đẹp nhỉ. B: Đúng vậy nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10447, 29566, 'これは日本語で何といいますか。', 'これは にほんごで なんと いいますか。', 'Cái này tiếng Nhật gọi là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10448, 27776, '皆さん、おはようございます。', 'みなさん、おはよう ございます。', 'Chào buổi sáng mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10449, 44772, '会議室はどこですか。', 'かいぎしつは どこ ですか。', 'Phòng họp ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10450, 28281, '自動販売機でジュースを買いました。', 'じどう はんばいきで ジュースを かいました。', 'Tôi mua nước ép ở máy bán hàng tự động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10451, 44874, '日曜日、映画を見ます。', 'にちようび、えいがを みます。', 'Chủ nhật tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10452, 44898, 'このカメラは日本のです。', 'この カメラは にほんの です。', 'Chiếc máy ảnh này là của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10453, 29423, 'こちらは山田さんです。', 'こちらは やまださん です。', 'Đây là anh Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10454, 43325, '晩ごはんの後でテレビを見ます。', 'ばんごはんの あとで テレビを みます。', 'Sau bữa tối tôi xem tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10455, 43449, 'ノートに漢字を書きます。', 'ノートに かんじを かきます。', 'Tôi viết chữ Hán vào vở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10456, 43460, '電話番号は何番ですか。', 'でんわ ばんごうは なんばん ですか。', 'Số điện thoại là số mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10457, 43555, 'あれは私の車です。', 'あれは わたしの くるま です。', 'Kia là xe của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10458, 40708, '彼は温和な性格で、怒ったことがない。', 'かれは おんわな せいかくで、おこった ことが ない。', 'Anh ấy tính tình ôn hòa, chưa bao giờ nổi giận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10459, 40715, '旅行の前に、現地の下調べをした。', 'りょこうの まえに、げんちの したしらべを した。', 'Trước chuyến đi tôi đã tìm hiểu trước về nơi đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10460, 40719, 'この地層から恐竜の化石が見つかった。', 'この ちそうから きょうりゅうの かせきが みつかった。', 'Hóa thạch khủng long được tìm thấy ở tầng đất này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10461, 40717, '狐が人に化ける昔話がある。', 'きつねが ひとに ばける むかしばなしが ある。', 'Có truyện cổ về cáo biến thành người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10462, 40709, 'どこからか笛の音が聞こえてきた。', 'どこからか ふえの ねが きこえて きた。', 'Từ đâu đó vọng lại tiếng sáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10463, 40711, 'ブームはもう下火になった。', 'ブームは もう したびに なった。', 'Cơn sốt đã hạ nhiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10464, 40707, '俺に任せておけ。', 'おれに まかせて おけ。', 'Cứ để đó cho tao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10465, 40720, 'どれどれ、ちょっと見せてごらん。', 'どれどれ、ちょっと みせて ごらん。', 'Để xem nào, cho xem chút đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10466, 40722, '何てきれいな景色だろう。', 'なんて きれいな けしき だろう。', 'Phong cảnh mới đẹp làm sao!', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10467, 40728, '毎月家計簿をつけている。', 'まいつき かけいぼを つけて いる。', 'Tháng nào tôi cũng ghi sổ chi tiêu gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10468, 43557, '飛行機で国へ帰ります。', 'ひこうきで くにへ かえります。', 'Tôi về nước bằng máy bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10469, 43554, 'タクシーでホテルへ帰りました。', 'タクシーで ホテルへ かえりました。', 'Tôi đi taxi về khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10470, 43679, '階段で二階へ行きます。', 'かいだんで にかいへ いきます。', 'Tôi đi cầu thang lên tầng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10471, 43681, 'どうぞ、この椅子に座ってください。', 'どうぞ、この いすに すわって ください。', 'Mời anh ngồi ghế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10472, 43687, 'その時計はいくらですか。', 'その とけいは いくら ですか。', 'Chiếc đồng hồ đó bao nhiêu tiền?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10473, 43689, 'この本は日本語の本です。', 'この ほんは にほんごの ほん です。', 'Cuốn sách này là sách tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10474, 43691, '毎朝、新聞を読みます。', 'まいあさ、しんぶんを よみます。', 'Sáng nào tôi cũng đọc báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10475, 43693, '国の家族に手紙を書きました。', 'くにの かぞくに てがみを かきました。', 'Tôi viết thư cho gia đình ở quê nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10476, 43695, '鉛筆で名前を書いてください。', 'えんぴつで なまえを かいて ください。', 'Hãy viết tên bằng bút chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10477, 43698, 'この傘は誰のですか。', 'この かさは だれの ですか。', 'Chiếc ô này của ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10478, 43741, '水をください。', 'みずを ください。', 'Cho tôi xin nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10479, 43753, '昼ごはんは食堂で食べます。', 'ひるごはんは しょくどうで たべます。', 'Tôi ăn trưa ở nhà ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10480, 43744, 'コーヒーを飲みませんか。', 'コーヒーを のみませんか。', 'Uống cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10481, 43803, 'ミラーさんは英語の先生です。', 'ミラーさんは えいごの せんせい です。', 'Anh Miller là giáo viên tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10482, 43821, 'あしたは休みです。', 'あしたは やすみ です。', 'Ngày mai được nghỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10483, 29643, 'あした、お宅に伺ってもいいですか。', 'あした、おたくに うかがっても いい ですか。', 'Ngày mai tôi đến nhà anh được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10484, 43917, '飛行機で国へ帰ります。', 'ひこうきで くにへ かえります。', 'Tôi về nước bằng máy bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10485, 43914, 'タクシーでホテルへ帰りました。', 'タクシーで ホテルへ かえりました。', 'Tôi đi taxi về khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10486, 44172, '美術館は月曜日休みです。', 'びじゅつかんは げつようび やすみ です。', 'Bảo tàng mỹ thuật nghỉ vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10487, 27246, '甲子園へ野球を見に行きました。', 'こうしえんへ やきゅうを みに いきました。', 'Tôi đã đến Koshien xem bóng chày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10488, 40729, '家主に家賃を払いに行った。', 'いえぬしに やちんを はらいに いった。', 'Tôi đi trả tiền thuê nhà cho chủ nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10489, 40732, '殿様は家来を連れて城を出た。', 'とのさまは けらいを つれて しろを でた。', 'Lãnh chúa dẫn gia thần rời lâu đài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10490, 40751, '昔は貝が貨幣として使われていた。', 'むかしは かいが かへいと して つかわれて いた。', 'Ngày xưa vỏ sò được dùng làm tiền tệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10491, 40727, '会社に入って健康保険に加入した。', 'かいしゃに はいって けんこう ほけんに かにゅう した。', 'Vào công ty tôi đã tham gia bảo hiểm y tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10492, 40740, '冬は家族でこたつに入ってみかんを食べる。', 'ふゆは かぞくで こたつに はいって みかんを たべる。', 'Mùa đông cả nhà ngồi trong kotatsu ăn quýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10493, 40731, '農家では牛や豚などの家畜を飼っている。', 'のうかでは うしや ぶたなどの かちくを かって いる。', 'Nhà nông nuôi các gia súc như bò, lợn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10494, 40738, '二人の間に火花が散った。', 'ふたりの あいだに ひばなが ちった。', 'Giữa hai người tóe lửa (cạnh tranh gay gắt).', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10495, 40742, '風で桜の花びらが散った。', 'かぜで さくらの はなびらが ちった。', 'Cánh hoa anh đào rơi trong gió.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10496, 27183, 'お問い合わせの番号は〇六の三四五六の七八九〇です。', 'おといあわせの ばんごうは ぜろろくの さんよんごろくの ななはちきゅうぜろ です。', 'Số điện thoại quý khách cần hỏi là 06-3456-7890.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10497, 44892, '美術館は月曜日休みです。', 'びじゅつかんは げつようび やすみ です。', 'Bảo tàng mỹ thuật nghỉ vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10498, 27105, 'いらっしゃいませ。何名様ですか。', 'いらっしゃいませ。なんめいさま ですか。', 'Xin chào quý khách. Quý khách đi mấy người ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10499, 27167, 'A：毎晩十二時まで働きます。B：大変ですね。', 'エー：まいばん じゅうにじまで はたらきます。ビー：たいへん ですね。', 'A: Tối nào tôi cũng làm đến 12 giờ. B: Vất vả nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10500, 27234, '十一日に京都へ行きます。', 'じゅういちにちに きょうとへ いきます。', 'Ngày mười một tôi đi Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10501, 29661, '失礼ですが、おいくつですか。', 'しつれい ですが、おいくつ ですか。', 'Xin lỗi, anh bao nhiêu tuổi ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10502, 29077, '来月、マラソンに出ます。', 'らいげつ、マラソンに でます。', 'Tháng sau tôi tham gia chạy marathon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10503, 29380, '二月ごろ、梅の花が咲きます。', 'にがつごろ、うめの はなが さきます。', 'Khoảng tháng hai hoa mơ nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10504, 44987, '急に雨が降り出しました。', 'きゅうに あめが ふりだしました。', 'Trời đột nhiên đổ mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10505, 29154, '子どもにおもちゃを買ってやりました。', 'こどもに おもちゃを かって やりました。', 'Tôi mua đồ chơi cho con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10506, 47541, '日本語の文法は難しいです。', 'にほんごの ぶんぽうは むずかしい です。', 'Ngữ pháp tiếng Nhật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10507, 47901, '日本語の文法は難しいです。', 'にほんごの ぶんぽうは むずかしい です。', 'Ngữ pháp tiếng Nhật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10508, 48261, '日本語の文法は難しいです。', 'にほんごの ぶんぽうは むずかしい です。', 'Ngữ pháp tiếng Nhật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10509, 29343, '東京の家賃は田舎の三倍です。', 'とうきょうの やちんは いなかの さんばい です。', 'Tiền thuê nhà ở Tokyo gấp ba ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10510, 31234, 'あんな浅はかなことをして後悔している。', 'あんな あさはかな ことを して こうかい して いる。', 'Tôi hối hận vì đã làm chuyện nông cạn như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10511, 31236, '遠隔操作でエアコンをつけた。', 'えんかく そうさで エアコンを つけた。', 'Tôi bật điều hòa bằng điều khiển từ xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10512, 31238, '世界の恒久平和を願う。', 'せかいの こうきゅう へいわを ねがう。', 'Tôi cầu mong hòa bình lâu dài cho thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10513, 40763, '朝の風が快い。', 'あさの かぜが こころよい。', 'Gió buổi sáng thật dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10514, 40766, '鳶に油揚げを拐われた。', 'とびに あぶらあげを さらわれた。', 'Miếng đậu rán bị diều hâu cuỗm mất (bị kẻ khác hớt tay trên).', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10515, 40775, 'この部屋には灰皿がない。', 'この へやには はいさらが ない。', 'Phòng này không có gạt tàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10516, 40771, '海運業は日本経済を支えてきた。', 'かいうんぎょうは にほん けいざいを ささえて きた。', 'Ngành vận tải biển đã chống đỡ nền kinh tế Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10517, 40772, 'フェリーで海峡を渡った。', 'フェリーで かいきょうを わたった。', 'Tôi vượt eo biển bằng phà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10518, 40760, 'メーカーは欠陥のある製品を回収した。', 'メーカーは けっかんの ある せいひんを かいしゅう した。', 'Nhà sản xuất đã thu hồi sản phẩm lỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10519, 40768, 'この法律の改正は改悪だという声もある。', 'この ほうりつの かいせいは かいあくだと いう こえも ある。', 'Có ý kiến cho rằng việc sửa luật này là sửa theo hướng xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10520, 40762, '電気回路の仕組みを勉強した。', 'でんき かいろの しくみを べんきょう した。', 'Tôi học cấu tạo của mạch điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10521, 27023, 'これは車の雑誌です。', 'これは くるまの ざっし です。', 'Đây là tạp chí về ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10522, 27421, 'あれは私の車です。', 'あれは わたしの くるま です。', 'Kia là xe của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10523, 27017, 'あれは銀行です。', 'あれは ぎんこう です。', 'Kia là ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10524, 27015, 'これは私の本です。', 'これは わたしの ほん です。', 'Đây là sách của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10525, 43332, 'これは車の雑誌です。', 'これは くるまの ざっし です。', 'Đây là tạp chí về ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10526, 27041, 'あれは私の車です。', 'あれは わたしの くるま です。', 'Kia là xe của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10527, 27093, 'これはフランスのワインです。', 'これは フランスの ワイン です。', 'Đây là rượu vang Pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10528, 27728, 'これは電気の会社です。', 'これは でんきの かいしゃ です。', 'Đây là công ty điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10529, 43915, 'あれは私の車です。', 'あれは わたしの くるま です。', 'Kia là xe của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10530, 29600, '彼は体に障害がありますが、元気に働いています。', 'かれは からだに しょうがいが ありますが、げんきに はたらいて います。', 'Anh ấy bị khuyết tật nhưng vẫn làm việc khỏe khoắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10531, 37944, '会社の先輩に仕事を教えてもらいました。', 'かいしゃの せんぱいに しごとを おしえて もらいました。', 'Tôi được đàn anh ở công ty chỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10532, 38557, '夏は虫が多いです。', 'なつは むしが おおい です。', 'Mùa hè có nhiều côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10533, 38496, 'この料理は簡単に作れます。', 'この りょうりは かんたんに つくれます。', 'Món này có thể nấu đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10534, 38562, '適当な大きさに切ってください。', 'てきとうな おおきさに きって ください。', 'Hãy cắt với kích cỡ thích hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10535, 38573, '旅行にパスポートが必要です。', 'りょこうに パスポートが ひつよう です。', 'Đi du lịch cần có hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10536, 44203, '素敵なプレゼントをありがとう。', 'すてきな プレゼントを ありがとう。', 'Cảm ơn món quà tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10537, 44204, '彼はとても熱心に勉強しています。', 'かれは とても ねっしんに べんきょう して います。', 'Anh ấy học rất chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10538, 44205, '私は料理が得意です。', 'わたしは りょうりが とくい です。', 'Tôi giỏi nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10539, 43971, '風邪をひいて、学校を休みました。', 'かぜを ひいて、がっこうを やすみました。', 'Bị cảm nên tôi nghỉ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10540, 43976, '退院の日が決まりました。', 'たいいんの ひが きまりました。', 'Ngày xuất viện đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10541, 43983, '重い荷物を持って、腕が痛いです。', 'おもい にもつを もって、うでが いたい です。', 'Mang đồ nặng nên tôi đau tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10542, 40810, '彼の慌てた様子が滑稽だった。', 'かれの あわてた ようすが こっけい だった。', 'Bộ dạng hốt hoảng của anh ấy trông thật buồn cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10543, 40796, 'そんなことを言った覚えはない。', 'そんな ことを いった おぼえは ない。', 'Tôi không nhớ là mình đã nói như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10544, 40804, '近所の店では掛けで買い物ができた。', 'きんじょの みせでは かけで かいものが できた。', 'Ở cửa hàng gần nhà, ngày xưa có thể mua chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10545, 40799, '新聞の学芸欄に彼の小説が紹介された。', 'しんぶんの がくげいらんに かれの しょうせつが しょうかい された。', 'Tiểu thuyết của anh ấy được giới thiệu trên mục văn hóa học thuật của báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10546, 40778, '昔は厳しい階級制度があった。', 'むかしは きびしい かいきゅう せいどが あった。', 'Ngày xưa có chế độ giai cấp hà khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10547, 40814, '風邪のときは粥を食べる。', 'かぜの ときは かゆを たべる。', 'Khi bị cảm tôi ăn cháo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10548, 40779, '浜辺できれいな貝殻を拾った。', 'はまべで きれいな かいがらを ひろった。', 'Tôi nhặt được vỏ sò đẹp trên bãi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10549, 43257, '母は料理が上手です。', 'ははは りょうりが じょうず です。', 'Mẹ tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10550, 43258, 'お父さんはお元気ですか。', 'おとうさんは おげんき ですか。', 'Bố bạn có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10551, 43261, '姉は先生です。', 'あねは せんせい です。', 'Chị gái tôi là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10552, 43265, 'お姉さんはおいくつですか。', 'おねえさんは おいくつ ですか。', 'Chị gái bạn bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10553, 43292, 'ごはんの前に手を洗います。', 'ごはんの まえに てを あらいます。', 'Tôi rửa tay trước bữa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10554, 43318, 'ドアを閉めてください。', 'ドアを しめて ください。', 'Hãy đóng cửa lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10555, 43345, '箱の中に何がありますか。', 'はこの なかに なにが ありますか。', 'Trong hộp có gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10556, 43317, '窓を開けてください。', 'まどを あけて ください。', 'Hãy mở cửa sổ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10557, 43324, '冷蔵庫に牛乳があります。', 'れいぞうこに ぎゅうにゅうが あります。', 'Trong tủ lạnh có sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10558, 43373, '日本料理が好きです。', 'にほん りょうりが すき です。', 'Tôi thích món ăn Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10559, 43398, '銀行でお金を下ろします。', 'ぎんこうで おかねを おろします。', 'Tôi rút tiền ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10560, 43441, '日本語の勉強は楽しいです。', 'にほんごの べんきょうは たのしい です。', 'Việc học tiếng Nhật rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10561, 43520, '日本の夏は暑いです。', 'にほんの なつは あつい です。', 'Mùa hè ở Nhật nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10562, 27309, 'はさみで紙を切ります。', 'はさみで かみを きります。', 'Tôi cắt giấy bằng kéo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10563, 27426, '日本語が少しわかります。', 'にほんごが すこし わかります。', 'Tôi hiểu một chút tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10564, 27295, 'A：あした行きますか。B：ええ、行きます。', 'エー：あした いきますか。ビー：ええ、いきます。', 'A: Mai bạn đi chứ? B: Vâng, tôi đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10565, 27297, 'A：三時に来てください。B：わかりました。', 'エー：さんじに きて ください。ビー：わかりました。', 'A: Ba giờ hãy đến nhé. B: Tôi hiểu rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10566, 27304, '毎日屋で野菜を買いました。', 'まいにちやで やさいを かいました。', 'Tôi mua rau ở siêu thị Mainichi-ya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10567, 27280, 'あしたまでにレポートを書きます。', 'あしたまでに レポートを かきます。', 'Tôi viết báo cáo trước ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10568, 29667, 'コーヒーにミルクを入れますか。', 'コーヒーに ミルクを いれますか。', 'Bạn có cho sữa vào cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10569, 27314, '図書館で本を借ります。', 'としょかんで ほんを かります。', 'Tôi mượn sách ở thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10570, 27316, '木村さんに日本語を習います。', 'きむらさんに にほんごを ならいます。', 'Tôi học tiếng Nhật với chị Kimura.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10571, 27333, '誕生日に花をもらいました。', 'たんじょうびに はなを もらいました。', 'Sinh nhật tôi được tặng hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10572, 40819, '暑くてたまらない。', 'あつくて たまらない。', 'Nóng không chịu nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10573, 40817, '駅前で保険の勧誘を受けた。', 'えきまえで ほけんの かんゆうを うけた。', 'Tôi bị mời chào mua bảo hiểm ở trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10574, 40829, '漢語は和語より硬い印象を与える。', 'かんごは わごより かたい いんしょうを あたえる。', 'Từ Hán tạo ấn tượng cứng hơn từ thuần Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10575, 40822, '幹線道路は朝から渋滞している。', 'かんせん どうろは あさから じゅうたい して いる。', 'Các tuyến đường chính tắc từ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10576, 40826, '少しずつ体を寒さに慣らす。', 'すこしずつ からだを さむさに ならす。', 'Từng chút một cho cơ thể quen với cái lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10577, 40825, 'このマイクは感度がいい。', 'この マイクは かんどが いい。', 'Chiếc micro này có độ nhạy tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10578, 40827, 'この仕事は慣れが必要だ。', 'この しごとは なれが ひつようだ。', 'Công việc này cần thời gian làm quen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10579, 40859, '新商品の企画が通った。', 'しんしょうひんの きかくが とおった。', 'Kế hoạch sản phẩm mới đã được duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10580, 27342, 'お父さんはお元気ですか。', 'おとうさんは おげんき ですか。', 'Bố bạn có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10581, 27346, 'これから昼ごはんを食べます。', 'これから ひるごはんを たべます。', 'Bây giờ tôi sẽ ăn trưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10582, 27352, 'いただきます。おいしそうですね。', 'いただきます。おいしそう ですね。', 'Mời cả nhà ăn cơm. Trông ngon quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10583, 27357, 'ごめんください。山田さんはいらっしゃいますか。', 'ごめん ください。やまださんは いらっしゃいますか。', 'Xin phép ạ. Anh Yamada có nhà không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10584, 27324, 'パソコンでレポートを書きます。', 'パソコンで レポートを かきます。', 'Tôi viết báo cáo bằng máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10585, 27335, '誕生日のプレゼントをもらいました。', 'たんじょうびの プレゼントを もらいました。', 'Tôi nhận được quà sinh nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10586, 27356, '昔はワープロで手紙を書きました。', 'むかしは ワープロで てがみを かきました。', 'Ngày xưa tôi viết thư bằng máy đánh chữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10587, 43543, '時々、映画を見ます。', 'ときどき、えいがを みます。', 'Thỉnh thoảng tôi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10588, 43546, 'いいえ、まだです。', 'いいえ、まだ です。', 'Chưa, tôi vẫn chưa ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10589, 43565, '私の町は静かです。', 'わたしの まちは しずか です。', 'Thị trấn của tôi yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10590, 43575, '夏休みに家族と旅行します。', 'なつやすみに かぞくと りょこう します。', 'Kỳ nghỉ hè tôi đi du lịch với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10591, 43578, 'エレベーターは左です。', 'エレベーターは ひだり です。', 'Thang máy ở bên trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10592, 43581, '銀行の隣に本屋があります。', 'ぎんこうの となりに ほんやが あります。', 'Bên cạnh ngân hàng có hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10593, 43582, 'この近くに病院がありますか。', 'この ちかくに びょういんが ありますか。', 'Gần đây có bệnh viện không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10594, 43616, '父は銀行員です。', 'ちちは ぎんこういん です。', 'Bố tôi là nhân viên ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10595, 43618, 'お父さんはお元気ですか。', 'おとうさんは おげんき ですか。', 'Bố bạn có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10596, 27398, '大学の寮に住んでいます。', 'だいがくの りょうに すんで います。', 'Tôi sống ở ký túc xá đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10597, 43621, '姉は先生です。', 'あねは せんせい です。', 'Chị gái tôi là giáo viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10598, 43623, '妹は高校生です。', 'いもうとは こうこうせい です。', 'Em gái tôi là học sinh cấp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10599, 43625, 'お姉さんはおいくつですか。', 'おねえさんは おいくつ ですか。', 'Chị gái bạn bao nhiêu tuổi?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10600, 43627, '両親はベトナムに住んでいます。', 'りょうしんは ベトナムに すんで います。', 'Bố mẹ tôi sống ở Việt Nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10601, 40851, '祖父は癌の手術を受けた。', 'そふは がんの しゅじゅつを うけた。', 'Ông tôi đã phẫu thuật ung thư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10602, 40853, '眼球の検査を受けた。', 'がんきゅうの けんさを うけた。', 'Tôi đã kiểm tra nhãn cầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10603, 40830, '子供は母親に甘えている。', 'こどもは ははおやに あまえて いる。', 'Đứa trẻ đang nũng nịu với mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10604, 40860, '計画の成功を危ぶむ声もある。', 'けいかくの せいこうを あやぶむ こえも ある。', 'Cũng có ý kiến nghi ngờ kế hoạch sẽ thành công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10605, 40855, 'この絵は贋物だと判明した。', 'この えは がんぶつだと はんめい した。', 'Đã xác định bức tranh này là đồ giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10606, 40832, '竿に洗濯物を干した。', 'さおに せんたくものを ほした。', 'Tôi phơi quần áo lên sào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10607, 40863, '料理を美しい器に盛った。', 'りょうりを うつくしい うつわに もった。', 'Tôi bày món ăn vào chiếc bát đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10608, 27403, '奈良はどんな町ですか。', 'ならは どんな まち ですか。', 'Nara là thành phố như thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10609, 27406, 'この部屋は広いです。そして、明るいです。', 'この へやは ひろい です。そして、あかるい です。', 'Căn phòng này rộng. Và còn sáng sủa nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10610, 27419, '富士山は日本で一番高い山です。', 'ふじさんは にほんで いちばん たかい やま です。', 'Núi Phú Sĩ là ngọn núi cao nhất Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10611, 27414, 'A：ありがとうございました。B：いいえ。', 'エー：ありがとう ございました。ビー：いいえ。', 'A: Cảm ơn anh. B: Không có gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10612, 27425, '琵琶湖は日本で一番大きい湖です。', 'びわこは にほんで いちばん おおきい みずうみ です。', 'Hồ Biwa là hồ lớn nhất Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10613, 43880, '日本の夏は暑いです。', 'にほんの なつは あつい です。', 'Mùa hè ở Nhật nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10614, 27427, '私は車があります。', 'わたしは くるまが あります。', 'Tôi có ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10615, 43883, 'きょうはいい天気ですね。', 'きょうは いい てんき ですね。', 'Hôm nay thời tiết đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10616, 43902, 'いつも七時に起きます。', 'いつも しちじに おきます。', 'Tôi lúc nào cũng dậy lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10617, 43904, '彼の話はよくわかりません。', 'かれの はなしは よく わかりません。', 'Tôi không hiểu rõ lời anh ấy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10618, 43907, 'もう昼ごはんを食べましたか。', 'もう ひるごはんを たべましたか。', 'Bạn đã ăn trưa chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10619, 27433, '日本料理が好きです。', 'にほん りょうりが すき です。', 'Tôi thích món ăn Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10620, 27435, '日曜日に野球をします。', 'にちようびに やきゅうを します。', 'Chủ nhật tôi chơi bóng chày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10621, 27437, '夏休みに家族と旅行します。', 'なつやすみに かぞくと りょこう します。', 'Kỳ nghỉ hè tôi đi du lịch với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10622, 27444, '東京で歌舞伎を見ました。', 'とうきょうで かぶきを みました。', 'Tôi đã xem kịch kabuki ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10623, 27449, '外国の言葉はかたかなで書きます。', 'がいこくの ことばは かたかなで かきます。', 'Từ nước ngoài được viết bằng katakana.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10624, 27451, 'すみません、細かいお金がありません。', 'すみません、こまかい おかねが ありません。', 'Xin lỗi, tôi không có tiền lẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10625, 27327, '先生に年賀状を書きました。', 'せんせいに ねんがじょうを かきました。', 'Tôi viết thiệp chúc Tết cho thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10626, 27393, '日本の桜はとてもきれいです。', 'にほんの さくらは とても きれい です。', 'Hoa anh đào Nhật Bản rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10627, 40876, '気兼ねなく何でも言ってください。', 'きがね なく なんでも いって ください。', 'Cứ nói bất cứ điều gì, đừng e ngại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10628, 40874, '一人暮らしは気楽でいい。', 'ひとりぐらしは きらくで いい。', 'Sống một mình thoải mái thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10629, 40877, '父は昔ながらの職人気質だ。', 'ちちは むかしながらの しょくにん かたぎだ。', 'Bố tôi mang khí chất thợ thủ công kiểu xưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10630, 40880, '彼女には気品がある。', 'かのじょには きひんが ある。', 'Cô ấy có phong thái thanh cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10631, 40881, 'この会社には自由な気風がある。', 'この かいしゃには じゆうな きふうが ある。', 'Công ty này có tinh thần tự do.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10632, 40887, '利用規約をよく読んでから登録した。', 'りよう きやくを よく よんでから とうろく した。', 'Tôi đọc kỹ điều khoản sử dụng rồi mới đăng ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10633, 40883, '気流が悪いため、飛行機が揺れた。', 'きりゅうが わるい ため、ひこうきが ゆれた。', 'Do luồng khí xấu nên máy bay rung lắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10634, 40871, '来週から期末試験が始まる。', 'らいしゅうから きまつ しけんが はじまる。', 'Từ tuần sau bắt đầu thi cuối kỳ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10635, 40907, '今日の会議の議題は来年の予算です。', 'きょうの かいぎの ぎだいは らいねんの よさん です。', 'Chủ đề cuộc họp hôm nay là ngân sách năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10636, 27411, 'A：もう一杯いかがですか。B：いいえ、けっこうです。', 'エー：もう いっぱい いかが ですか。ビー：いいえ、けっこう です。', 'A: Thêm một chén nữa nhé? B: Thôi, tôi đủ rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10637, 27458, '夫は会社員です。', 'おっとは かいしゃいん です。', 'Chồng tôi là nhân viên công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10638, 27465, '日本語が少しわかります。', 'にほんごが すこし わかります。', 'Tôi hiểu tiếng Nhật một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10639, 27471, 'A：ちょっと手伝ってください。B：いいですよ。', 'エー：ちょっと てつだって ください。ビー：いい ですよ。', 'A: Giúp tôi một chút. B: Được chứ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10640, 27472, '残念ですが、あしたはちょっと……。', 'ざんねん ですが、あしたは ちょっと……。', 'Tiếc quá, nhưng ngày mai thì tôi hơi bận...', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10641, 27476, 'あしたはだめですか。じゃ、あさっては?', 'あしたは だめ ですか。じゃ、あさっては?', 'Ngày mai không được à? Vậy ngày kia thì sao?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10642, 27480, 'もしもし、山田です。', 'もしもし、やまだ です。', 'A lô, tôi là Yamada.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10643, 27441, '父はジャズが好きです。', 'ちちは ジャズが すき です。', 'Bố tôi thích nhạc jazz.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10644, 27452, 'コンサートのチケットが二枚あります。', 'コンサートの チケットが にまい あります。', 'Tôi có hai vé xem hòa nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10645, 27488, 'あの女の子は私の娘です。', 'あの おんなの こは わたしの むすめ です。', 'Cô bé kia là con gái tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10646, 27494, '箱の中に何か物があります。', 'はこの なかに なにか ものが あります。', 'Trong hộp có đồ vật gì đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10647, 27509, '駅の前に喫茶店があります。', 'えきの まえに きっさてんが あります。', 'Trước ga có một quán cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10648, 44511, 'どんな音楽が好きですか。', 'どんな おんがくが すき ですか。', 'Bạn thích loại nhạc nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10649, 27510, '花屋で花を買いました。', 'はなやで はなを かいました。', 'Tôi mua hoa ở tiệm hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10650, 27511, 'タクシー乗り場はどこですか。', 'タクシー のりばは どこ ですか。', 'Bến taxi ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10651, 27518, 'エレベーターは左です。', 'エレベーターは ひだり です。', 'Thang máy ở bên trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10652, 27521, '銀行の隣に本屋があります。', 'ぎんこうの となりに ほんやが あります。', 'Bên cạnh ngân hàng có hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10653, 27525, '道を教えてくれて、どうもすみません。', 'みちを おしえて くれて、どうも すみません。', 'Cảm ơn anh rất nhiều vì đã chỉ đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10654, 40896, '人工衛星が軌道に乗った。', 'じんこう えいせいが きどうに のった。', 'Vệ tinh nhân tạo đã vào quỹ đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10655, 40902, '政治家に汚職の疑惑が持たれている。', 'せいじかに おしょくの ぎわくが もたれて いる。', 'Chính trị gia đang bị nghi ngờ tham nhũng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10656, 40910, '彼女は約束を破った彼を詰った。', 'かのじょは やくそくを やぶった かれを なじった。', 'Cô ấy trách móc anh vì thất hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10657, 40917, '病気のため、一年間休学した。', 'びょうきの ため、いちねんかん きゅうがく した。', 'Vì bệnh nên tôi đã bảo lưu một năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10658, 40903, '義理でパーティーに出席した。', 'ぎりで パーティーに しゅっせき した。', 'Tôi dự tiệc vì phép lịch sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10699, 43754, '駅の前に喫茶店があります。', 'えきの まえに きっさてんが あります。', 'Trước ga có một quán cà phê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10659, 40906, '修学旅行で国会議事堂を見学した。', 'しゅうがく りょこうで こっかい ぎじどうを けんがく した。', 'Trong chuyến tham quan học tập chúng tôi đã thăm tòa nhà quốc hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10660, 40909, '駅前の喫茶店で友達と会った。', 'えきまえの きっさてんで ともだちと あった。', 'Tôi gặp bạn ở quán cà phê trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10661, 40888, '日記にその日の出来事を記した。', 'にっきに その ひの できごとを しるした。', 'Tôi ghi lại sự việc ngày hôm đó vào nhật ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10662, 40936, '家から駅までの距離は一キロぐらいだ。', 'いえから えきまでの きょりは いちキロ ぐらいだ。', 'Khoảng cách từ nhà đến ga chừng một cây số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10663, 27529, '東京ディズニーランドは千葉県にあります。', 'とうきょう ディズニーランドは ちばけんに あります。', 'Tokyo Disneyland nằm ở tỉnh Chiba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10664, 27507, 'コンビニでお弁当を買いました。', 'コンビニで おべんとうを かいました。', 'Tôi mua cơm hộp ở cửa hàng tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10665, 27537, 'カレーの粉はスパイス・コーナーにあります。', 'カレーの こなは スパイス・コーナーに あります。', 'Bột cà ri ở gian hàng gia vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10666, 27547, '箱の中にボールが五つあります。', 'はこの なかに ボールが いつつ あります。', 'Trong hộp có năm quả bóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10667, 27551, 'かばんの中に鉛筆が九つあります。', 'かばんの なかに えんぴつが ここのつ あります。', 'Trong cặp có chín cây bút chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10668, 27557, 'うちに車が二台あります。', 'うちに くるまが にだい あります。', 'Nhà tôi có hai chiếc ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10669, 27560, 'りんごを三つ買いました。', 'りんごを みっつ かいました。', 'Tôi đã mua ba quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10670, 27567, '封筒に切手を貼ります。', 'ふうとうに きってを はります。', 'Tôi dán tem lên phong bì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10671, 27571, 'お兄さんは何をしていますか。', 'おにいさんは なにを して いますか。', 'Anh trai bạn đang làm gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10672, 27581, '毎日八時間働きます。', 'まいにち はちじかん はたらきます。', 'Mỗi ngày tôi làm việc tám tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10673, 27585, '駅まで十分ぐらいかかります。', 'えきまで じゅっぷん ぐらい かかります。', 'Đến ga mất khoảng mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10674, 27589, '休みは日曜日だけです。', 'やすみは にちようび だけ です。', 'Ngày nghỉ chỉ có chủ nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10675, 27591, 'いいお天気ですね。散歩に行きませんか。', 'いい おてんき ですね。さんぽに いきませんか。', 'Thời tiết đẹp nhỉ. Đi dạo không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10676, 27562, '昼ごはんにサンドイッチを食べました。', 'ひるごはんに サンドイッチを たべました。', 'Bữa trưa tôi ăn bánh sandwich.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10677, 27620, '春は桜がきれいです。', 'はるは さくらが きれい です。', 'Mùa xuân hoa anh đào rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10678, 27624, 'きょうはいい天気ですね。', 'きょうは いい てんき ですね。', 'Hôm nay thời tiết đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10679, 27661, '毎日屋で野菜を買いました。', 'まいにちやで やさいを かいました。', 'Tôi mua rau ở siêu thị Mainichi-ya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10680, 28048, '週末、レストランでアルバイトをします。', 'しゅうまつ、レストランで アルバイトを します。', 'Cuối tuần tôi làm thêm ở nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10681, 44809, '日本の生活はどうですか。', 'にほんの せいかつは どう ですか。', 'Cuộc sống ở Nhật thế nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10682, 44872, '日本の歌が好きです。', 'にほんの うたが すき です。', 'Tôi thích các bài hát Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10683, 40932, '彼とは旧知の仲だ。', 'かれとは きゅうちの なかだ。', 'Tôi và anh ấy là chỗ quen biết đã lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10684, 40939, 'うちは共稼ぎなので、家事は分担している。', 'うちは ともかせぎ なので、かじは ぶんたん して いる。', 'Nhà tôi hai vợ chồng cùng đi làm nên chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10685, 40933, 'この地域の居住者は高齢者が多い。', 'この ちいきの きょじゅうしゃは こうれいしゃが おおい。', 'Cư dân khu vực này phần lớn là người cao tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10686, 40937, '港に漁船が戻ってきた。', 'みなとに ぎょせんが もどって きた。', 'Tàu cá đã quay về cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10687, 40927, '秋にチューリップの球根を植えた。', 'あきに チューリップの きゅうこんを うえた。', 'Mùa thu tôi trồng củ hoa tulip.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10688, 40935, 'これは許容できる範囲の誤差だ。', 'これは きょよう できる はんいの ごさだ。', 'Đây là sai số trong phạm vi chấp nhận được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10689, 40928, 'この靴は少し窮屈だ。', 'この くつは すこし きゅうくつだ。', 'Đôi giày này hơi chật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10690, 40970, '試合に勝って、みんな興奮していた。', 'しあいに かって、みんな こうふん して いた。', 'Thắng trận nên ai nấy đều phấn khích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10691, 28570, '夏休みにヨーロッパへ行きます。', 'なつやすみに ヨーロッパへ いきます。', 'Kỳ nghỉ hè tôi đi châu Âu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10692, 28632, 'もう昼ごはんを食べましたか。', 'もう ひるごはんを たべましたか。', 'Bạn đã ăn trưa chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10693, 29032, '花屋で花を買いました。', 'はなやで はなを かいました。', 'Tôi mua hoa ở tiệm hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10694, 29244, '東京から大阪までどのくらいかかりますか。', 'とうきょうから おおさかまで どのくらい かかりますか。', 'Từ Tokyo đến Osaka mất bao lâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10695, 43392, '駅の近くにいいレストランがあります。', 'えきの ちかくに いい レストランが あります。', 'Gần ga có một nhà hàng ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10696, 43677, '窓を開けてください。', 'まどを あけて ください。', 'Hãy mở cửa sổ ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10697, 43696, 'この紙に名前を書いてください。', 'この かみに なまえを かいて ください。', 'Hãy viết tên vào tờ giấy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10698, 43682, 'ベッドの下に猫がいます。', 'ベッドの したに ねこが います。', 'Dưới gầm giường có con mèo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10700, 43752, '駅の近くにいいレストランがあります。', 'えきの ちかくに いい レストランが あります。', 'Gần ga có một nhà hàng ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10701, 43805, '漢字は難しいですが、おもしろいです。', 'かんじは むずかしい ですが、おもしろい です。', 'Chữ Hán khó nhưng thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10702, 43818, 'パソコンでレポートを書きます。', 'パソコンで レポートを かきます。', 'Tôi viết báo cáo bằng máy tính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10703, 43919, '駅で切符を買います。', 'えきで きっぷを かいます。', 'Tôi mua vé ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10704, 43935, '夏休みに家族と旅行します。', 'なつやすみに かぞくと りょこう します。', 'Kỳ nghỉ hè tôi đi du lịch với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10705, 43938, 'エレベーターは左です。', 'エレベーターは ひだり です。', 'Thang máy ở bên trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10706, 43941, '銀行の隣に本屋があります。', 'ぎんこうの となりに ほんやが あります。', 'Bên cạnh ngân hàng có hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10707, 44065, '週末、レストランでアルバイトをします。', 'しゅうまつ、レストランで アルバイトを します。', 'Cuối tuần tôi làm thêm ở nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10708, 44170, '旅行のお土産を買いました。', 'りょこうの おみやげを かいました。', 'Tôi đã mua quà du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10709, 44461, '棚の上に本があります。', 'たなの うえに ほんが あります。', 'Trên giá có sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10710, 27481, '小沢征爾は有名な指揮者です。', 'おざわ せいじは ゆうめいな しきしゃ です。', 'Ozawa Seiji là một nhạc trưởng nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10711, 44785, '週末、レストランでアルバイトをします。', 'しゅうまつ、レストランで アルバイトを します。', 'Cuối tuần tôi làm thêm ở nhà hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10712, 40965, '彼が両社の橋渡しをしてくれた。', 'かれが りょうしゃの はしわたしを して くれた。', 'Anh ấy đã làm cầu nối giữa hai công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10713, 40944, '多くの人が彼の考えに共鳴した。', 'おおくの ひとが かれの かんがえに きょうめい した。', 'Nhiều người đồng tình với suy nghĩ của ông ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10714, 40957, '台風が上陸する恐れがある。', 'たいふうが じょうりく する おそれが ある。', 'Có nguy cơ bão sẽ đổ bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10715, 40946, '被災者の叫びに耳を傾けるべきだ。', 'ひさいしゃの さけびに みみを かたむける べきだ。', 'Cần lắng nghe tiếng kêu cứu của người bị nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10716, 40943, '共働きの家庭が増えている。', 'ともばたらきの かていが ふえて いる。', 'Các gia đình có cả hai vợ chồng đi làm đang tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10717, 40976, '引っ越しを業者に頼んだ。', 'ひっこしを ぎょうしゃに たのんだ。', 'Tôi thuê dịch vụ chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10718, 40986, '姉は銀行に勤務している。', 'あねは ぎんこうに きんむ して いる。', 'Chị tôi làm việc ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10719, 40984, '勤め先の住所を書いてください。', 'つとめさきの じゅうしょを かいて ください。', 'Hãy ghi địa chỉ nơi làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10720, 27594, 'A：行ってきます。B：行ってらっしゃい。', 'エー：いって きます。ビー：いって らっしゃい。', 'A: Con đi đây. B: Con đi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10721, 27353, 'ごちそうさまでした。とてもおいしかったです。', 'ごちそうさま でした。とても おいしかった です。', 'Cảm ơn vì bữa ăn. Rất ngon ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10722, 43995, '晩ご飯の後で散歩をします。', 'ばんごはんの あとで さんぽを します。', 'Sau bữa tối tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10723, 43999, '最近、少し太りました。', 'さいきん、すこし ふとりました。', 'Gần đây tôi hơi béo lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10724, 44001, '薬を飲んだら、すぐ治りました。', 'くすりを のんだら、すぐ なおりました。', 'Uống thuốc xong là khỏi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10725, 44003, '強い風で木が倒れました。', 'つよい かぜで きが たおれました。', 'Gió mạnh làm đổ cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10726, 44005, '長い時間歩いて、疲れました。', 'ながい じかん あるいて、つかれました。', 'Đi bộ lâu nên tôi mệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10727, 44007, '咳が止まらないので、病院へ行きました。', 'せきが とまらないので、びょういんへ いきました。', 'Ho mãi không dứt nên tôi đi bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10728, 44009, '赤ちゃんがよく眠っています。', 'あかちゃんが よく ねむって います。', 'Em bé đang ngủ ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10729, 44011, '車に気をつけてください。', 'くるまに きを つけて ください。', 'Hãy cẩn thận xe cộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10730, 44015, '昨日遅く寝たので、眠いです。', 'きのう おそく ねたので、ねむい です。', 'Hôm qua ngủ muộn nên tôi buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10731, 44016, '熱があって、体がだるいです。', 'ねつが あって、からだが だるい です。', 'Tôi bị sốt nên người uể oải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10732, 44020, '無理をしないでください。', 'むりを しないで ください。', 'Đừng làm quá sức nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10733, 44024, '旅行にパスポートが必要です。', 'りょこうに パスポートが ひつよう です。', 'Đi du lịch cần có hộ chiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10734, 44028, '早く起きてください。', 'はやく おきて ください。', 'Dậy sớm đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10735, 44030, 'この会社には社員が百人います。', 'この かいしゃには しゃいんが ひゃくにん います。', 'Công ty này có một trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10736, 44045, '仕事のことで先輩に相談しました。', 'しごとの ことで せんぱいに そうだん しました。', 'Tôi xin ý kiến đàn anh về công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10737, 44055, '夏休みの計画を立てました。', 'なつやすみの けいかくを たてました。', 'Tôi đã lên kế hoạch cho kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10738, 44070, 'インターネットで電車の時間を調べました。', 'インターネットで でんしゃの じかんを しらべました。', 'Tôi tra giờ tàu trên Internet.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10739, 44074, '注文した本が届きました。', 'ちゅうもん した ほんが とどきました。', 'Cuốn sách tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10740, 44076, '母の料理を手伝いました。', 'ははの りょうりを てつだいました。', 'Tôi giúp mẹ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10741, 40987, '十一月二十三日は勤労感謝の日だ。', 'じゅういちがつ にじゅうさんにちは きんろう かんしゃの ひだ。', 'Ngày 23 tháng 11 là ngày Tri ân người lao động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10742, 40990, 'シャツの襟が汚れている。', 'シャツの えりが よごれて いる。', 'Cổ áo sơ mi bị bẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10743, 40988, '館内での撮影は禁じられている。', 'かんないでの さつえいは きんじられて いる。', 'Chụp ảnh trong tòa nhà bị cấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10744, 40982, '将棋では玉を取られたら負けだ。', 'しょうぎでは ぎょくを とられたら まけだ。', 'Trong cờ shogi, bị bắt quân vua là thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10745, 43285, '趣味は何ですか。', 'しゅみは なん ですか。', 'Sở thích của bạn là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10746, 43287, '頭が痛いです。', 'あたまが いたい です。', 'Tôi bị đau đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10747, 43289, '彼女は目が大きいです。', 'かのじょは めが おおきい です。', 'Cô ấy có đôi mắt to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10748, 43291, '口を大きく開けてください。', 'くちを おおきく あけて ください。', 'Hãy há miệng thật to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10749, 43294, '兄は背が高いです。', 'あには せが たかい です。', 'Anh trai tôi cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10750, 43386, 'スープに塩を少し入れてください。', 'スープに しおを すこし いれて ください。', 'Hãy cho một chút muối vào súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10751, 43387, 'コーヒーに砂糖を入れますか。', 'コーヒーに さとうを いれますか。', 'Bạn có cho đường vào cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10752, 43440, '毎日ピアノの練習をします。', 'まいにち ピアノの れんしゅうを します。', 'Ngày nào tôi cũng luyện đàn piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10753, 43488, 'もう少しゆっくり話してください。', 'もう すこし ゆっくり はなして ください。', 'Hãy nói chậm hơn một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10754, 43529, 'あしたは曇りでしょう。', 'あしたは くもり でしょう。', 'Ngày mai có lẽ trời nhiều mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10755, 27662, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10756, 43573, '夏休みに海へ行きました。', 'なつやすみに うみへ いきました。', 'Kỳ nghỉ hè tôi đã đi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10757, 43645, '趣味は何ですか。', 'しゅみは なん ですか。', 'Sở thích của bạn là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10758, 43647, '頭が痛いです。', 'あたまが いたい です。', 'Tôi bị đau đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10759, 43649, '彼女は目が大きいです。', 'かのじょは めが おおきい です。', 'Cô ấy có đôi mắt to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10760, 43651, '口を大きく開けてください。', 'くちを おおきく あけて ください。', 'Hãy há miệng thật to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10761, 43654, '兄は背が高いです。', 'あには せが たかい です。', 'Anh trai tôi cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10762, 43702, '新しい服を買いました。', 'あたらしい ふくを かいました。', 'Tôi đã mua quần áo mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10763, 43848, 'もう少しゆっくり話してください。', 'もう すこし ゆっくり はなして ください。', 'Hãy nói chậm hơn một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10764, 43973, 'この薬を一日三回飲んでください。', 'この くすりを いちにち さんかい のんで ください。', 'Hãy uống thuốc này ngày ba lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10765, 43979, '歯が痛いので、歯医者へ行きます。', 'はが いたいので、はいしゃへ いきます。', 'Răng đau nên tôi đi nha sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10766, 43998, 'ダイエットをしていますから、甘い物を食べません。', 'ダイエットを して いますから、あまい ものを たべません。', 'Tôi đang ăn kiêng nên không ăn đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10767, 44032, '部長に報告します。', 'ぶちょうに ほうこく します。', 'Tôi báo cáo cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10768, 44208, 'ぜひ一度、うちへ来てください。', 'ぜひ いちど、うちへ きて ください。', 'Nhất định hãy đến nhà tôi chơi một lần nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10769, 44228, 'どんな動物が好きですか。', 'どんな どうぶつが すき ですか。', 'Bạn thích con vật nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10770, 44330, '病気で学校を休みました。', 'びょうきで がっこうを やすみました。', 'Tôi nghỉ học vì ốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10771, 44333, 'この薬を一日三回飲んでください。', 'この くすりを いちにち さんかい のんで ください。', 'Hãy uống thuốc này ngày ba lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10772, 41002, '同じ失敗を繰り返すのは愚かだ。', 'おなじ しっぱいを くりかえすのは おろかだ。', 'Lặp lại cùng một sai lầm thật ngu ngốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10773, 41031, '軽率な発言をして、反省している。', 'けいそつな はつげんを して、はんせい して いる。', 'Tôi đang kiểm điểm vì đã phát ngôn hấp tấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10774, 41003, '彼は会うたびに仕事の愚痴をこぼす。', 'かれは あう たびに しごとの ぐちを こぼす。', 'Lần nào gặp anh ta cũng than vãn về công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10775, 41008, '昔、この国は君主が治めていた。', 'むかし、この くには くんしゅが おさめて いた。', 'Ngày xưa đất nước này do vua trị vì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10776, 44339, '歯が痛いので、歯医者へ行きます。', 'はが いたいので、はいしゃへ いきます。', 'Răng đau nên tôi đi nha sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10777, 44392, '部長に報告します。', 'ぶちょうに ほうこく します。', 'Tôi báo cáo cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10778, 44418, '大学で経済を勉強しています。', 'だいがくで けいざいを べんきょう して います。', 'Tôi đang học kinh tế ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10779, 44448, 'もうすぐ夏休みです。', 'もうすぐ なつやすみ です。', 'Sắp đến kỳ nghỉ hè rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10780, 44571, '世界で一番高い山はエベレストです。', 'せかいで いちばん たかい やまは エベレスト です。', 'Ngọn núi cao nhất thế giới là Everest.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10781, 27631, '世界で一番高い山はエベレストです。', 'せかいで いちばん たかい やまは エベレスト です。', 'Ngọn núi cao nhất thế giới là Everest.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10782, 27637, 'このてんぷらはおいしいですね。', 'この てんぷらは おいしい ですね。', 'Món tempura này ngon nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10783, 27647, '東京は大阪よりずっと大きいです。', 'とうきょうは おおさかより ずっと おおきい です。', 'Tokyo lớn hơn Osaka nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10784, 27652, 'たくさん歩いて、疲れました。', 'たくさん あるいて、つかれました。', 'Đi bộ nhiều nên tôi mệt rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10785, 27660, 'この店は安いです。でも、あまりおいしくないです。', 'この みせは やすい です。でも、あまり おいしく ない です。', 'Quán này rẻ. Nhưng không ngon lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10786, 27655, 'シンガポールは一年中暑いです。', 'シンガポールは いちねんじゅう あつい です。', 'Singapore nóng quanh năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10787, 27665, '毎日仕事で疲れます。', 'まいにち しごとで つかれます。', 'Ngày nào tôi cũng mệt vì công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10788, 27668, '今晩、友達と食事します。', 'こんばん、ともだちと しょくじ します。', 'Tối nay tôi ăn tối với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10789, 27680, 'お正月に国へ帰ります。', 'おしょうがつに くにへ かえります。', 'Dịp Tết tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10790, 27689, '牛どんを一つください。', 'ぎゅうどんを ひとつ ください。', 'Cho tôi một bát cơm thịt bò.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10791, 27674, '毎週プールで泳ぎます。', 'まいしゅう プールで およぎます。', 'Hằng tuần tôi bơi ở hồ bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10792, 27710, 'ドアを閉めてください。', 'ドアを しめて ください。', 'Hãy đóng cửa lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10793, 27713, '荷物を持ちましょうか。', 'にもつを もちましょうか。', 'Để tôi xách hành lý giúp nhé?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10794, 27718, 'このパソコンを使ってもいいですか。', 'この パソコンを つかっても いい ですか。', 'Tôi dùng máy tính này được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10795, 27723, '皆さん、立ってください。', 'みなさん、たって ください。', 'Mọi người hãy đứng dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10796, 27732, '住所を教えてください。', 'じゅうしょを おしえて ください。', 'Cho tôi biết địa chỉ của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10797, 27736, 'この問題は難しいです。', 'この もんだいは むずかしい です。', 'Câu hỏi này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10798, 27740, 'この道をまっすぐ行ってください。', 'この みちを まっすぐ いって ください。', 'Hãy đi thẳng con đường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10799, 27745, 'もう少し待ってください。', 'もう すこし まって ください。', 'Hãy chờ thêm một chút nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10800, 41037, '社長は工場の閉鎖を決断した。', 'しゃちょうは こうじょうの へいさを けつだん した。', 'Giám đốc đã quyết đoán đóng cửa nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10801, 41044, '高校時代にバンドを結成した。', 'こうこう じだいに バンドを けっせい した。', 'Hồi cấp ba tôi đã lập một ban nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10802, 41043, '水素と酸素が結合して水ができる。', 'すいそと さんそが けつごう して みずが できる。', 'Hydro kết hợp với oxy tạo thành nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10803, 41036, '日本チームが決勝に進んだ。', 'にほん チームが けっしょうに すすんだ。', 'Đội Nhật đã vào chung kết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10804, 41039, '地域の結び付きが弱くなっている。', 'ちいきの むすびつきが よわく なって いる。', 'Sự gắn kết trong cộng đồng đang yếu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10805, 27729, 'エアコンをつけてもいいですか。', 'エアコンを つけても いい ですか。', 'Tôi bật điều hòa được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10806, 27760, '山田さんの電話番号を知っていますか。', 'やまださんの でんわ ばんごうを しって いますか。', 'Bạn có biết số điện thoại của anh Yamada không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10807, 27765, '駅で時刻表を見ました。', 'えきで じこくひょうを みました。', 'Tôi xem bảng giờ tàu ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10808, 27771, '市役所へ登録に行きます。', 'しやくしょへ とうろくに いきます。', 'Tôi đến tòa thị chính để đăng ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10809, 27777, 'この写真を見ると、国を思い出します。', 'この しゃしんを みると、くにを おもいだします。', 'Nhìn bức ảnh này tôi lại nhớ quê hương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10810, 27780, 'みんなのインタビューで町の人に話を聞きます。', 'みんなの インタビューで まちの ひとに はなしを ききます。', 'Trong chương trình Minna no Interview, người ta phỏng vấn người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10811, 27788, 'プレイガイドでコンサートのチケットを買いました。', 'プレイガイドで コンサートの チケットを かいました。', 'Tôi mua vé hòa nhạc ở quầy bán vé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10812, 27796, '銀行でお金を出しました。', 'ぎんこうで おかねを だしました。', 'Tôi đã rút tiền ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10813, 27803, 'きのう、工場を見学しました。', 'きのう、こうじょうを けんがく しました。', 'Hôm qua tôi đi tham quan nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10814, 44685, '日本語はなかなか上手になりません。', 'にほんごは なかなか じょうずに なりません。', 'Tiếng Nhật mãi không giỏi lên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10815, 44692, 'きのうから熱があります。', 'きのうから ねつが あります。', 'Từ hôm qua tôi bị sốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10816, 27815, '象は耳が大きいです。', 'ぞうは みみが おおきい です。', 'Voi có đôi tai to.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10817, 44700, '寝る前に歯を磨きます。', 'ねる まえに はを みがきます。', 'Trước khi ngủ tôi đánh răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10818, 27818, '寝る前に歯を磨きます。', 'ねる まえに はを みがきます。', 'Trước khi ngủ tôi đánh răng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10819, 27826, '京都でお寺を見ました。', 'きょうとで おてらを みました。', 'Tôi đã thăm chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10820, 27832, 'A：毎日十キロ走ります。B：すごいですね。', 'エー：まいにち じゅっキロ はしります。ビー：すごい ですね。', 'A: Mỗi ngày tôi chạy mười cây số. B: Giỏi quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10821, 27833, 'A：日本語が上手ですね。B：いいえ、まだまだです。', 'エー：にほんごが じょうず ですね。ビー：いいえ、まだまだ です。', 'A: Tiếng Nhật của bạn giỏi nhỉ. B: Không, tôi còn kém lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10822, 27838, '暗証番号を忘れてしまいました。', 'あんしょう ばんごうを わすれて しまいました。', 'Tôi lỡ quên mất mật khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10823, 27848, '大学前でバスを降ります。', 'だいがくまえで バスを おります。', 'Tôi xuống xe buýt ở trạm Daigaku-mae.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10824, 27844, 'バンドンはインドネシアの町です。', 'バンドンは インドネシアの まち です。', 'Bandung là một thành phố của Indonesia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10825, 27858, '財布をなくしました。', 'さいふを なくしました。', 'Tôi bị mất ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10826, 41051, '子供たちが健やかに育つことを願う。', 'こどもたちが すこやかに そだつ ことを ねがう。', 'Tôi mong bọn trẻ lớn lên khỏe mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10827, 41079, '新しい元素が発見された。', 'あたらしい げんそが はっけん された。', 'Một nguyên tố mới đã được phát hiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10828, 41047, '冷蔵庫を月賦で買った。', 'れいぞうこを げっぷで かった。', 'Tôi mua tủ lạnh trả góp hằng tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10829, 41054, '父は会社員と農業を兼業している。', 'ちちは かいしゃいんと のうぎょうを けんぎょう して いる。', 'Bố tôi vừa làm công ty vừa làm nông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10830, 41045, '習い事の月謝が高い。', 'ならいごとの げっしゃが たかい。', 'Học phí hằng tháng của lớp năng khiếu đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10831, 41095, '遅刻の言い訳はもう聞きたくない。', 'ちこくの いいわけは もう ききたく ない。', 'Tôi không muốn nghe lời bào chữa cho việc đi muộn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10832, 27861, '日曜日、家族と出かけます。', 'にちようび、かぞくと でかけます。', 'Chủ nhật tôi ra ngoài với gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10833, 27862, 'ここで靴を脱いでください。', 'ここで くつを ぬいで ください。', 'Hãy cởi giày ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10834, 27867, '来週、大阪へ出張します。', 'らいしゅう、おおさかへ しゅっちょう します。', 'Tuần sau tôi đi công tác Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10835, 27877, 'この薬を一日三回飲んでください。', 'この くすりを いちにち さんかい のんで ください。', 'Hãy uống thuốc này ngày ba lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10836, 27883, '金曜日までにレポートを出してください。', 'きんようびまでに レポートを だして ください。', 'Hãy nộp báo cáo trước thứ Sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10837, 27890, 'A：かぜをひきました。B：そうですか。お大事に。', 'エー：かぜを ひきました。ビー：そう ですか。おだいじに。', 'A: Tôi bị cảm. B: Vậy à. Mong anh mau khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10838, 27897, '姉はギターを弾くことができます。', 'あねは ギターを ひく ことが できます。', 'Chị tôi biết chơi đàn ghi-ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10839, 27900, 'ごみはここに捨ててください。', 'ごみは ここに すてて ください。', 'Hãy vứt rác ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10840, 44718, 'ダイエットをしていますから、甘い物を食べません。', 'ダイエットを して いますから、あまい ものを たべません。', 'Tôi đang ăn kiêng nên không ăn đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10841, 27909, '寝る前にお祈りをします。', 'ねる まえに おいのりを します。', 'Trước khi ngủ tôi cầu nguyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10842, 27919, '日本語はなかなか上手になりません。', 'にほんごは なかなか じょうずに なりません。', 'Tiếng Nhật mãi không giỏi lên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10843, 27922, 'みんなで「ふるさと」を歌いました。', 'みんなで 「ふるさと」を うたいました。', 'Mọi người cùng hát bài "Furusato".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10844, 27915, 'インターネットで買い物をします。', 'インターネットで かいものを します。', 'Tôi mua sắm trên Internet.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10845, 27936, '毎日ピアノの練習をします。', 'まいにち ピアノの れんしゅうを します。', 'Ngày nào tôi cũng luyện đàn piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10846, 27946, 'A：お元気ですか。B：はい、おかげさまで。', 'エー：おげんき ですか。ビー：はい、おかげさまで。', 'A: Anh khỏe không? B: Vâng, nhờ trời tôi vẫn khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10847, 27952, '東京スカイツリーに上りました。', 'とうきょう スカイツリーに のぼりました。', 'Tôi đã lên tháp Tokyo Sky Tree.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10848, 27956, '駅の前にパチンコの店があります。', 'えきの まえに パチンコの みせが あります。', 'Trước ga có tiệm pachinko.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10849, 27963, '自転車を修理しました。', 'じてんしゃを しゅうり しました。', 'Tôi đã sửa xe đạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10850, 27969, 'この言葉の意味がわかりません。', 'この ことばの いみが わかりません。', 'Tôi không hiểu nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10851, 41101, '古代エジプトの文明に興味がある。', 'こだい エジプトの ぶんめいに きょうみが ある。', 'Tôi quan tâm đến nền văn minh Ai Cập cổ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10852, 41096, '先生への言伝を頼まれた。', 'せんせいへの ことづてを たのまれた。', 'Tôi được nhờ chuyển lời nhắn cho thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10853, 41097, '言論の自由は守られるべきだ。', 'げんろんの じゆうは まもられる べきだ。', 'Tự do ngôn luận cần được bảo vệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10854, 41098, 'この商品は期間限定で販売される。', 'この しょうひんは きかん げんていで はんばい される。', 'Sản phẩm này chỉ được bán trong thời gian giới hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10855, 41103, '結婚の意志を固めた。', 'けっこんの いしを かためた。', 'Tôi đã quyết tâm kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10856, 41099, '先生は生徒と個別に面談した。', 'せんせいは せいとと こべつに めんだん した。', 'Thầy gặp riêng từng học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10857, 27973, '映画の終わりはとても悲しかったです。', 'えいがの おわりは とても かなしかった です。', 'Đoạn kết bộ phim rất buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10858, 44752, '部長に報告します。', 'ぶちょうに ほうこく します。', 'Tôi báo cáo cho trưởng phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10859, 28067, '誕生日にケーキを食べました。', 'たんじょうびに ケーキを たべました。', 'Sinh nhật tôi đã ăn bánh ga-tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10860, 44931, '世界で一番高い山はエベレストです。', 'せかいで いちばん たかい やまは エベレスト です。', 'Ngọn núi cao nhất thế giới là Everest.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10861, 28497, '東京は大阪よりずっと大きいです。', 'とうきょうは おおさかより ずっと おおきい です。', 'Tokyo lớn hơn Osaka nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10862, 28915, 'この部屋は広いです。しかし、駅から遠いです。', 'この へやは ひろい です。しかし、えきから とおい です。', 'Căn phòng này rộng. Tuy nhiên, xa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10863, 29132, '札幌の雪祭りを見に行きたいです。', 'さっぽろの ゆきまつりを みに いきたい です。', 'Tôi muốn đi xem lễ hội tuyết ở Sapporo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10864, 29553, '田中さんは今どこにいらっしゃいますか。', 'たなかさんは いま どこに いらっしゃいますか。', 'Anh Tanaka bây giờ đang ở đâu ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10865, 43567, '駅の近くのホテルに泊まりました。', 'えきの ちかくの ホテルに とまりました。', 'Tôi đã ở khách sạn gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10866, 43747, 'コーヒーに砂糖を入れますか。', 'コーヒーに さとうを いれますか。', 'Bạn có cho đường vào cà phê không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10867, 43800, '毎日ピアノの練習をします。', 'まいにち ピアノの れんしゅうを します。', 'Ngày nào tôi cũng luyện đàn piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10868, 43933, '夏休みに海へ行きました。', 'なつやすみに うみへ いきました。', 'Kỳ nghỉ hè tôi đã đi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10869, 43927, '駅の近くのホテルに泊まりました。', 'えきの ちかくの ホテルに とまりました。', 'Tôi đã ở khách sạn gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10870, 44095, '住所を教えてください。', 'じゅうしょを おしえて ください。', 'Cho tôi biết địa chỉ của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10871, 44169, '週末にうちでパーティーをします。', 'しゅうまつに うちで パーティーを します。', 'Cuối tuần tôi tổ chức tiệc ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10872, 44358, 'ダイエットをしていますから、甘い物を食べません。', 'ダイエットを して いますから、あまい ものを たべません。', 'Tôi đang ăn kiêng nên không ăn đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10873, 44524, '週末、父と釣りに行きます。', 'しゅうまつ、ちちと つりに いきます。', 'Cuối tuần tôi đi câu cá với bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10874, 44529, '週末にうちでパーティーをします。', 'しゅうまつに うちで パーティーを します。', 'Cuối tuần tôi tổ chức tiệc ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10875, 44815, '住所を教えてください。', 'じゅうしょを おしえて ください。', 'Cho tôi biết địa chỉ của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10876, 44884, '週末、父と釣りに行きます。', 'しゅうまつ、ちちと つりに いきます。', 'Cuối tuần tôi đi câu cá với bố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10877, 41116, 'この言葉の語源はポルトガル語だ。', 'この ことばの ごげんは ポルトガルごだ。', 'Từ này có nguồn gốc từ tiếng Bồ Đào Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10878, 41109, 'この町は長い歴史を誇っている。', 'この まちは ながい れきしを ほこって いる。', 'Thị trấn này tự hào về lịch sử lâu đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10879, 41135, '彼の自伝は口述をもとに書かれた。', 'かれの じでんは こうじゅつを もとに かかれた。', 'Tự truyện của ông ấy được viết dựa trên lời kể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10880, 41123, '昔、この港は中国との交易で栄えた。', 'むかし、この みなとは ちゅうごくとの こうえきで さかえた。', 'Ngày xưa cảng này thịnh vượng nhờ giao thương với Trung Quốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10881, 41140, '兄は大学で工学を専攻している。', 'あには だいがくで こうがくを せんこう して いる。', 'Anh tôi học chuyên ngành kỹ thuật ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10882, 41125, '市役所で住民票が交付される。', 'しやくしょで じゅうみんひょうが こうふ される。', 'Giấy chứng nhận cư trú được cấp tại tòa thị chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10883, 41130, '昔は公団住宅に住んでいた。', 'むかしは こうだん じゅうたくに すんで いた。', 'Ngày trước tôi sống ở khu nhà ở công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10884, 41157, '行政のサービスがオンラインで使えるようになった。', 'ぎょうせいの サービスが オンラインで つかえる ように なった。', 'Dịch vụ hành chính giờ đã dùng được trực tuyến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10885, 44889, '週末にうちでパーティーをします。', 'しゅうまつに うちで パーティーを します。', 'Cuối tuần tôi tổ chức tiệc ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10886, 27681, '毎晩十一時ごろ寝ます。', 'まいばん じゅういちじ ごろ ねます。', 'Tối nào tôi cũng ngủ khoảng mười một giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10887, 44077, '走ったので、電車に間に合いました。', 'はしったので、でんしゃに まにあいました。', 'Nhờ chạy mà tôi kịp tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10888, 44078, '電車が十分遅れています。', 'でんしゃが じゅっぷん おくれて います。', 'Tàu đang trễ mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10889, 44079, '毎日運動を続けています。', 'まいにち うんどうを つづけて います。', 'Tôi duy trì tập thể dục mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10890, 44081, '古い切手を集めています。', 'ふるい きってを あつめて います。', 'Tôi đang sưu tầm tem cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10891, 44082, '駅の前に人が集まっています。', 'えきの まえに ひとが あつまって います。', 'Trước ga có nhiều người đang tụ tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10892, 44085, 'この料理は簡単に作れます。', 'この りょうりは かんたんに つくれます。', 'Món này có thể nấu đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10893, 44086, 'この問題は複雑です。', 'この もんだいは ふくざつ です。', 'Vấn đề này phức tạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10894, 44110, '掃除機で部屋を掃除しました。', 'そうじきで へやを そうじ しました。', 'Tôi dọn phòng bằng máy hút bụi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10895, 44112, 'お湯を沸かして、お茶を入れました。', 'おゆを わかして、おちゃを いれました。', 'Tôi đun nước nóng để pha trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10896, 44119, '机の上を片付けてください。', 'つくえの うえを かたづけて ください。', 'Hãy dọn mặt bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10897, 44121, '道でお金を拾いました。', 'みちで おかねを ひろいました。', 'Tôi nhặt được tiền trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10898, 44122, 'お風呂を沸かしておきます。', 'おふろを わかして おきます。', 'Tôi đun sẵn nước tắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10899, 44125, '野菜と肉を煮てスープを作りました。', 'やさいと にくを にて スープを つくりました。', 'Tôi ninh rau với thịt để nấu súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10900, 44127, 'スープを温めてください。', 'スープを あたためて ください。', 'Hãy hâm nóng súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10901, 44129, 'テレビが壊れてしまいました。', 'テレビが こわれて しまいました。', 'Tivi bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10902, 44131, '壊れた時計を直しました。', 'こわれた とけいを なおしました。', 'Tôi đã sửa chiếc đồng hồ hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10903, 44133, '電車の中で財布を落としました。', 'でんしゃの なかで さいふを おとしました。', 'Tôi đánh rơi ví trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10904, 44135, '本を棚に並べました。', 'ほんを たなに ならべました。', 'Tôi xếp sách lên giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10905, 41156, '連絡の行き違いで、会えなかった。', 'れんらくの いきちがいで、あえなかった。', 'Do liên lạc lệch nhau nên chúng tôi không gặp được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10906, 41160, '大学の購買で文房具を買った。', 'だいがくの こうばいで ぶんぼうぐを かった。', 'Tôi mua văn phòng phẩm ở cửa hàng của trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10907, 41158, 'ゼミで英語の論文を講読している。', 'ゼミで えいごの ろんぶんを こうどく して いる。', 'Trong seminar chúng tôi đọc và giải nghĩa luận văn tiếng Anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10908, 41147, 'このチームは攻めが得意だ。', 'この チームは せめが とくいだ。', 'Đội này giỏi tấn công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10909, 41149, '彼は都心に店を構えた。', 'かれは としんに みせを かまえた。', 'Anh ấy mở cửa hàng ở trung tâm thành phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10910, 41155, '日頃の行いが大切だ。', 'ひごろの おこないが たいせつだ。', 'Hành vi thường ngày là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10911, 41148, '剣道では構えが大切だ。', 'けんどうでは かまえが たいせつだ。', 'Trong kiếm đạo, tư thế rất quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10912, 38326, '日本のお菓子はおいしいです。', 'にほんの おかしは おいしい です。', 'Bánh kẹo Nhật ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10913, 38393, '東京は人が多いです。', 'とうきょうは ひとが おおい です。', 'Tokyo đông người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10914, 31304, '寒いですから、窓を閉めてください。', 'さむい ですから、まどを しめて ください。', 'Lạnh quá, hãy đóng cửa sổ lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10915, 31308, 'かばんは机の上に置いてください。', 'かばんは つくえの うえに おいて ください。', 'Hãy để cặp lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10916, 37902, 'お国はどちらですか。', 'おくには どちら ですか。', 'Anh đến từ nước nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10917, 38405, 'あした、買い物に行きます。', 'あした、かいものに いきます。', 'Ngày mai tôi đi mua sắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10918, 43252, 'このクラスは男が十人、女が五人です。', 'この クラスは おとこが じゅうにん、おんなが ごにん です。', 'Lớp này có mười nam và năm nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10919, 43254, '公園で子供が遊んでいます。', 'こうえんで こどもが あそんで います。', 'Trẻ con đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10920, 43268, '祖父は八十歳です。', 'そふは はちじゅっさい です。', 'Ông tôi tám mươi tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10921, 43270, '公園でおじいさんが本を読んでいます。', 'こうえんで おじいさんが ほんを よんで います。', 'Có một cụ ông đang đọc sách trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10922, 43272, '夫は料理が上手です。', 'おっとは りょうりが じょうず です。', 'Chồng tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10923, 43273, '妻と二人で住んでいます。', 'つまと ふたりで すんで います。', 'Tôi sống cùng vợ, hai người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10924, 43279, 'お国はどちらですか。', 'おくには どちら ですか。', 'Anh đến từ nước nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10925, 43280, '私は日本人ではありません。', 'わたしは にほんじん では ありません。', 'Tôi không phải người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10926, 43282, '山田先生は日本語の先生です。', 'やまだ せんせいは にほんごの せんせい です。', 'Thầy Yamada là giáo viên tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10927, 43295, '結婚はいつですか。', 'けっこんは いつ ですか。', 'Khi nào bạn kết hôn?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10928, 43297, 'どこで生まれましたか。', 'どこで うまれましたか。', 'Bạn sinh ra ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10929, 43298, 'あの人の名前を知っていますか。', 'あの ひとの なまえを しって いますか。', 'Bạn có biết tên người kia không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10930, 43300, '母と電話で話しました。', 'ははと でんわで はなしました。', 'Tôi đã nói chuyện điện thoại với mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10931, 43302, '皆さん、お元気ですか。', 'みなさん、おげんき ですか。', 'Mọi người có khỏe không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10932, 43304, '山田さんはとても優しい人です。', 'やまださんは とても やさしい ひと です。', 'Anh Yamada là người rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10933, 41171, '彼は別れを告げずに去った。', 'かれは わかれを つげずに さった。', 'Anh ấy ra đi không một lời từ biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10934, 41188, '公私を混同してはいけない。', 'こうしを こんどう しては いけない。', 'Không được lẫn lộn việc công với việc tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10935, 41175, '国産の野菜は少し高い。', 'こくさんの やさいは すこし たかい。', 'Rau sản xuất trong nước hơi đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10936, 41198, 'グラフ上の点の座標を求めなさい。', 'グラフじょうの てんの ざひょうを もとめなさい。', 'Hãy tìm tọa độ của điểm trên đồ thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10937, 41174, '両国は五十年前に国交を結んだ。', 'りょうこくは ごじゅうねんまえに こっこうを むすんだ。', 'Hai nước thiết lập quan hệ ngoại giao từ năm mươi năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10938, 41177, '日本の国土の約七割は山地だ。', 'にほんの こくどの やく ななわりは さんちだ。', 'Khoảng bảy phần mười lãnh thổ Nhật là đồi núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10939, 41162, 'この料理には香辛料がたくさん使われている。', 'この りょうりには こうしんりょうが たくさん つかわれて いる。', 'Món này dùng rất nhiều gia vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10940, 41210, '人の体は多くの細胞でできている。', 'ひとの からだは おおくの さいぼうで できて いる。', 'Cơ thể người được tạo nên từ vô số tế bào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10941, 41206, 'ベランダでトマトを栽培している。', 'ベランダで トマトを さいばい して いる。', 'Tôi trồng cà chua ở ban công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10942, 43306, '私は音楽が好きです。', 'わたしは おんがくが すき です。', 'Tôi thích âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10943, 43309, '私の家は駅から遠いです。', 'わたしの いえは えきから とおい です。', 'Nhà tôi ở xa ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10944, 43312, '母は台所で料理をしています。', 'ははは だいどころで りょうりを して います。', 'Mẹ đang nấu ăn trong bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10945, 43341, '眼鏡をかけている人は誰ですか。', 'めがねを かけて いる ひとは だれ ですか。', 'Người đeo kính là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10946, 43344, 'あの帽子をかぶっている人が田中さんです。', 'あの ぼうしを かぶって いる ひとが たなかさん です。', 'Người đội mũ kia là anh Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10947, 43349, '毎晩十一時に寝ます。', 'まいばん じゅういちじに ねます。', 'Tối nào tôi cũng ngủ lúc mười một giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10948, 43351, '窓を開けてください。', 'まどを あけて ください。', 'Hãy mở cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10949, 43352, '寒いですから、窓を閉めてください。', 'さむい ですから、まどを しめて ください。', 'Lạnh quá, hãy đóng cửa sổ lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10950, 43354, '寝る前に電気を消します。', 'ねる まえに でんきを けします。', 'Trước khi ngủ tôi tắt đèn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10951, 29104, 'あしたは漢字のテストです。', 'あしたは かんじの テスト です。', 'Ngày mai có bài kiểm tra chữ Hán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10952, 43357, '食事の後で、お皿を洗います。', 'しょくじの あとで、おさらを あらいます。', 'Ăn xong tôi rửa bát đĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10953, 43359, 'きょうは白いシャツを着ています。', 'きょうは しろい シャツを きて います。', 'Hôm nay tôi mặc áo sơ mi trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10954, 43361, 'この公園は広いです。', 'この こうえんは ひろい です。', 'Công viên này rộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10955, 43363, 'この部屋は明るいです。', 'この へやは あかるい です。', 'Căn phòng này sáng sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10956, 43365, '新しい車を買いました。', 'あたらしい くるまを かいました。', 'Tôi đã mua xe mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10957, 43367, 'この花はとてもきれいです。', 'この はなは とても きれい です。', 'Bông hoa này rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10958, 43369, 'ご飯を食べましたか。', 'ごはんを たべましたか。', 'Bạn ăn cơm chưa?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10959, 43370, '毎朝、朝ご飯を食べます。', 'まいあさ、あさごはんを たべます。', 'Sáng nào tôi cũng ăn sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10960, 43372, '晩ご飯は何を食べましたか。', 'ばんごはんは なにを たべましたか。', 'Bữa tối bạn đã ăn gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10961, 43388, '箸を使うことができますか。', 'はしを つかう ことが できますか。', 'Bạn có biết dùng đũa không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10962, 44137, 'ここに車を止めてもいいですか。', 'ここに くるまを とめても いい ですか。', 'Tôi đỗ xe ở đây được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10963, 41203, 'この山では昔、金が採掘されていた。', 'この やまでは むかし、きんが さいくつ されて いた。', 'Ngày xưa người ta khai thác vàng ở ngọn núi này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10964, 41212, '彼は一代で財を成した。', 'かれは いちだいで ざいを なした。', 'Ông ấy gây dựng cơ đồ chỉ trong một đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10965, 41204, '法案の採決が行われた。', 'ほうあんの さいけつが おこなわれた。', 'Dự luật đã được đưa ra biểu quyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10966, 41200, '昔の町並みを再現した博物館がある。', 'むかしの まちなみを さいげん した はくぶつかんが ある。', 'Có bảo tàng tái hiện phố xá ngày xưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10967, 41207, '昼ご飯はパンで済ました。', 'ひるごはんは パンで すました。', 'Bữa trưa tôi ăn tạm bánh mì cho xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10968, 41202, '最善を尽くしたが、だめだった。', 'さいぜんを つくしたが、だめ だった。', 'Tôi đã cố gắng hết sức nhưng không được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10969, 43399, 'このりんごは一つ百円です。', 'この りんごは ひとつ ひゃくえん です。', 'Quả táo này giá một trăm yên một quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10970, 43401, 'あした、買い物に行きます。', 'あした、かいものに いきます。', 'Ngày mai tôi đi mua sắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10971, 43403, 'りんごを二つ買いました。', 'りんごを ふたつ かいました。', 'Tôi mua hai quả táo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10972, 43404, '卵を三つ使います。', 'たまごを みっつ つかいます。', 'Dùng ba quả trứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10973, 43406, '毎朝、パンを食べます。', 'まいあさ、パンを たべます。', 'Sáng nào tôi cũng ăn bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10974, 43408, 'きょうはカレーを作ります。', 'きょうは カレーを つくります。', 'Hôm nay tôi nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10975, 43410, 'この店で古い本を売っています。', 'この みせで ふるい ほんを うって います。', 'Cửa hàng này bán sách cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10976, 43413, 'ラーメンを頼みました。', 'ラーメンを たのみました。', 'Tôi đã gọi mì ramen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10977, 43416, 'このりんごは甘いです。', 'この りんごは あまい です。', 'Quả táo này ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10978, 43397, '八百屋で野菜を買いました。', 'やおやで やさいを かいました。', 'Tôi mua rau ở cửa hàng rau quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10979, 43417, 'タイ料理は辛いです。', 'タイ りょうりは からい です。', 'Món Thái cay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10980, 43419, 'この店の野菜は安いです。', 'この みせの やさいは やすい です。', 'Rau ở cửa hàng này rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10981, 43421, '冷たい水を飲みたいです。', 'つめたい みずを のみたい です。', 'Tôi muốn uống nước lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10982, 43423, 'この町は人が少ないです。', 'この まちは ひとが すくない です。', 'Thị trấn này ít người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10983, 43425, 'お腹がすきました。何か食べましょう。', 'おなかが すきました。なにか たべましょう。', 'Đói bụng rồi. Ăn gì đó đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10984, 43430, '兄は東京の大学で勉強しています。', 'あには とうきょうの だいがくで べんきょう して います。', 'Anh tôi đang học đại học ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10985, 43433, '授業は九時に始まります。', 'じゅぎょうは くじに はじまります。', 'Giờ học bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10986, 43442, '毎日日本語を勉強します。', 'まいにち にほんごを べんきょう します。', 'Ngày nào tôi cũng học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10987, 43447, 'この言葉の意味を教えてください。', 'この ことばの いみを おしえて ください。', 'Hãy cho tôi biết nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10988, 43448, '家族について作文を書きました。', 'かぞくに ついて さくぶんを かきました。', 'Tôi viết bài văn về gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10989, 43452, '仕事は六時に終わります。', 'しごとは ろくじに おわります。', 'Công việc kết thúc lúc sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10990, 43560, 'この道をまっすぐ行ってください。', 'この みちを まっすぐ いって ください。', 'Hãy đi thẳng con đường này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10991, 43561, '次の交差点を右へ曲がってください。', 'つぎの こうさてんを みぎへ まがって ください。', 'Đến ngã tư tiếp theo hãy rẽ phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10992, 41238, '産後はしばらく体を休めてください。', 'さんごは しばらく からだを やすめて ください。', 'Sau khi sinh hãy nghỉ ngơi một thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10993, 41218, 'そんな考えは時代錯誤だ。', 'そんな かんがえは じだい さくごだ。', 'Suy nghĩ như thế là lỗi thời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10994, 41225, '会議の前に少し雑談した。', 'かいぎの まえに すこし ざつだん した。', 'Trước cuộc họp chúng tôi tán gẫu một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10995, 41216, '試合に勝つための作戦を立てた。', 'しあいに かつ ための さくせんを たてた。', 'Chúng tôi lập chiến thuật để thắng trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10996, 41237, '姉は来月から産休に入る。', 'あねは らいげつから さんきゅうに はいる。', 'Từ tháng sau chị tôi nghỉ thai sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10997, 41242, '残金は来月払います。', 'ざんきんは らいげつ はらいます。', 'Số tiền còn lại tôi sẽ trả vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10998, 41244, '動物を虐待するのは残酷だ。', 'どうぶつを ぎゃくたい するのは ざんこくだ。', 'Ngược đãi động vật thật tàn nhẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (10999, 43563, '橋を渡ると、駅があります。', 'はしを わたると、えきが あります。', 'Qua cầu là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11000, 43569, '大使館でビザをもらいました。', 'たいしかんで ビザを もらいました。', 'Tôi nhận visa ở đại sứ quán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11001, 43610, 'あなたのお名前は?', 'あなたの おなまえは?', 'Tên bạn là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11002, 43612, 'このクラスは男が十人、女が五人です。', 'この クラスは おとこが じゅうにん、おんなが ごにん です。', 'Lớp này có mười nam và năm nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11003, 43628, '祖父は八十歳です。', 'そふは はちじゅっさい です。', 'Ông tôi tám mươi tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11004, 43630, '公園でおじいさんが本を読んでいます。', 'こうえんで おじいさんが ほんを よんで います。', 'Có một cụ ông đang đọc sách trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11005, 43632, '夫は料理が上手です。', 'おっとは りょうりが じょうず です。', 'Chồng tôi nấu ăn giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11006, 43636, 'お年はおいくつですか。', 'おとしは おいくつ ですか。', 'Ông bao nhiêu tuổi ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11007, 43639, 'お国はどちらですか。', 'おくには どちら ですか。', 'Anh đến từ nước nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11008, 43640, '私は日本人ではありません。', 'わたしは にほんじん では ありません。', 'Tôi không phải người Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11009, 43642, '山田先生は日本語の先生です。', 'やまだ せんせいは にほんごの せんせい です。', 'Thầy Yamada là giáo viên tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11010, 43655, '結婚はいつですか。', 'けっこんは いつ ですか。', 'Khi nào bạn kết hôn?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11011, 43657, 'どこで生まれましたか。', 'どこで うまれましたか。', 'Bạn sinh ra ở đâu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11012, 43659, 'あした、駅で友達に会います。', 'あした、えきで ともだちに あいます。', 'Ngày mai tôi gặp bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11013, 43661, 'もう一度言ってください。', 'もう いちど いって ください。', 'Hãy nói lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11014, 43663, 'あの先生は若いです。', 'あの せんせいは わかい です。', 'Thầy giáo kia còn trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11015, 43664, '山田さんはとても優しい人です。', 'やまださんは とても やさしい ひと です。', 'Anh Yamada là người rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11016, 43667, '私は虫が嫌いです。', 'わたしは むしが きらい です。', 'Tôi ghét côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11017, 43670, 'あした、うちへ遊びに来てください。', 'あした、うちへ あそびに きて ください。', 'Ngày mai đến nhà tôi chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11018, 43673, '毎晩お風呂に入ります。', 'まいばん おふろに はいります。', 'Tối nào tôi cũng tắm bồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11019, 43701, '眼鏡をかけている人は誰ですか。', 'めがねを かけて いる ひとは だれ ですか。', 'Người đeo kính là ai vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11020, 43704, 'あの帽子をかぶっている人が田中さんです。', 'あの ぼうしを かぶって いる ひとが たなかさん です。', 'Người đội mũ kia là anh Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11021, 41263, '社長のご子息が入社された。', 'しゃちょうの ごしそくが にゅうしゃ された。', 'Con trai của giám đốc đã vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11022, 41266, '彼女は若いころから作家を志していた。', 'かのじょは わかい ころから さっかを こころざして いた。', 'Từ hồi trẻ cô ấy đã quyết chí trở thành nhà văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11023, 41260, '脳は体のすべての働きを司っている。', 'のうは からだの すべての はたらきを つかさどって いる。', 'Não điều khiển mọi hoạt động của cơ thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11024, 41261, '司法の独立は民主主義の基本だ。', 'しほうの どくりつは みんしゅ しゅぎの きほんだ。', 'Độc lập tư pháp là nền tảng của dân chủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11025, 41258, 'バラの刺が指に刺さった。', 'バラの とげが ゆびに ささった。', 'Gai hoa hồng đâm vào ngón tay tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11026, 41255, '母が着物を仕立ててくれた。', 'ははが きものを したてて くれた。', 'Mẹ đã may kimono cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11027, 41259, 'ハンカチに花の刺繍をした。', 'ハンカチに はなの ししゅうを した。', 'Tôi thêu hoa lên khăn tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11028, 41287, '彼は親から大きな資産を受け継いだ。', 'かれは おやから おおきな しさんを うけついだ。', 'Anh ấy thừa hưởng khối tài sản lớn từ cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11029, 41306, '日本は治安がいい国だと言われている。', 'にほんは ちあんが いい くにだと いわれて いる。', 'Nhật Bản được cho là đất nước có an ninh tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11030, 43709, '毎晩十一時に寝ます。', 'まいばん じゅういちじに ねます。', 'Tối nào tôi cũng ngủ lúc mười một giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11031, 27994, '私たちのチームは負けました。', 'わたしたちの チームは まけました。', 'Đội chúng tôi đã thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11032, 43712, '寒いですから、窓を閉めてください。', 'さむい ですから、まどを しめて ください。', 'Lạnh quá, hãy đóng cửa sổ lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11033, 43714, '寝る前に電気を消します。', 'ねる まえに でんきを けします。', 'Trước khi ngủ tôi tắt đèn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11034, 43716, 'このペンを使ってもいいですか。', 'この ペンを つかっても いい ですか。', 'Tôi dùng cây bút này được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11035, 43717, '食事の後で、お皿を洗います。', 'しょくじの あとで、おさらを あらいます。', 'Ăn xong tôi rửa bát đĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11036, 43719, 'きょうは白いシャツを着ています。', 'きょうは しろい シャツを きて います。', 'Hôm nay tôi mặc áo sơ mi trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11037, 43722, '私の部屋は狭いです。', 'わたしの へやは せまい です。', 'Phòng của tôi hẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11038, 43723, 'この部屋は明るいです。', 'この へやは あかるい です。', 'Căn phòng này sáng sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11039, 43725, '新しい車を買いました。', 'あたらしい くるまを かいました。', 'Tôi đã mua xe mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11040, 43727, 'この花はとてもきれいです。', 'この はなは とても きれい です。', 'Bông hoa này rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11041, 43728, 'この部屋は汚いです。掃除しましょう。', 'この へやは きたない です。そうじ しましょう。', 'Phòng này bẩn quá. Dọn dẹp thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11042, 43731, '一緒に昼ご飯を食べましょう。', 'いっしょに ひるごはんを たべましょう。', 'Cùng ăn trưa nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11043, 43790, '兄は東京の大学で勉強しています。', 'あには とうきょうの だいがくで べんきょう して います。', 'Anh tôi đang học đại học ở Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11044, 44049, '父の転勤で大阪へ引っ越しました。', 'ちちの てんきんで おおさかへ ひっこしました。', 'Vì bố chuyển công tác nên nhà tôi chuyển đến Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11045, 44059, '政治にはあまり興味がありません。', 'せいじには あまり きょうみが ありません。', 'Tôi không quan tâm lắm đến chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11046, 44158, '毎晩テレビでニュースを見ます。', 'まいばん テレビで ニュースを みます。', 'Tối nào tôi cũng xem tin tức trên tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11047, 44212, '地球は丸いです。', 'ちきゅうは まるい です。', 'Trái đất hình tròn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11048, 44240, '隣の部屋から音が聞こえます。', 'となりの へやから おとが きこえます。', 'Có tiếng động từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11049, 44139, 'プレゼントを紙で包みました。', 'プレゼントを かみで つつみました。', 'Tôi gói quà bằng giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11050, 41301, '彼は女性にもてる。', 'かれは じょせいに もてる。', 'Anh ấy được phụ nữ yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11051, 41283, '留学して視野が広がった。', 'りゅうがく して しやが ひろがった。', 'Đi du học giúp tầm nhìn của tôi rộng mở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11052, 41270, '本部から指令が出た。', 'ほんぶから しれいが でた。', 'Trụ sở chính đã ra chỉ thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11053, 41286, '新しい店を開く資金が足りない。', 'あたらしい みせを ひらく しきんが たりない。', 'Không đủ vốn để mở cửa hàng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11054, 41272, '新しい法律は来年四月から施行される。', 'あたらしい ほうりつは らいねん しがつから しこう される。', 'Luật mới sẽ có hiệu lực từ tháng tư năm sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11055, 41280, 'ここから先は私有地です。', 'ここから さきは しゆうち です。', 'Từ đây trở đi là đất tư nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11056, 44327, 'A：一緒に行きますか。B：もちろん行きます。', 'エー：いっしょに いきますか。ビー：もちろん いきます。', 'A: Cùng đi chứ? B: Tất nhiên rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11057, 44409, '父の転勤で大阪へ引っ越しました。', 'ちちの てんきんで おおさかへ ひっこしました。', 'Vì bố chuyển công tác nên nhà tôi chuyển đến Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11058, 44520, 'あした、サッカーの試合があります。', 'あした、サッカーの しあいが あります。', 'Ngày mai có trận đấu bóng đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11059, 44574, '今夜は月がきれいですね。', 'こんやは つきが きれい ですね。', 'Đêm nay trăng đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11060, 28150, 'よく考えてから答えてください。', 'よく かんがえてから こたえて ください。', 'Hãy suy nghĩ kỹ rồi trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11061, 27983, '先生が作文を直してくれました。', 'せんせいが さくぶんを なおして くれました。', 'Thầy đã sửa bài văn cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11062, 27993, 'きのうの試合は日本が勝ちました。', 'きのうの しあいは にほんが かちました。', 'Trận hôm qua Nhật Bản đã thắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11063, 28014, '私の夢は医者になることです。', 'わたしの ゆめは いしゃに なる こと です。', 'Ước mơ của tôi là trở thành bác sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11064, 28017, 'あなたの意見を聞かせてください。', 'あなたの いけんを きかせて ください。', 'Hãy cho tôi nghe ý kiến của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11065, 28022, 'たぶん、彼は来ないと思います。', 'たぶん、かれは こないと おもいます。', 'Có lẽ anh ấy sẽ không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11066, 28026, '日本の文化について話しました。', 'にほんの ぶんかに ついて はなしました。', 'Chúng tôi đã nói chuyện về văn hóa Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11067, 28034, 'キング牧師は有名なスピーチをしました。', 'キング ぼくしは ゆうめいな スピーチを しました。', 'Mục sư King đã có bài phát biểu nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11068, 28045, 'アメリカの大統領が日本へ来ました。', 'アメリカの だいとうりょうが にほんへ きました。', 'Tổng thống Mỹ đã đến Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11069, 28053, 'A：しばらくですね。B：ええ、お元気でしたか。', 'エー：しばらく ですね。ビー：ええ、おげんき でしたか。', 'A: Lâu rồi không gặp nhỉ. B: Vâng, anh vẫn khỏe chứ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11070, 28012, '電車の中でマンガを読みます。', 'でんしゃの なかで マンガを よみます。', 'Tôi đọc truyện tranh trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11071, 41338, '彼は社交的で、友達が多い。', 'かれは しゃこうてきで、ともだちが おおい。', 'Anh ấy hòa đồng nên có nhiều bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11072, 41313, '人前で叱られて、自尊心が傷ついた。', 'ひとまえで しかられて、じそんしんが きずついた。', 'Bị mắng trước mặt người khác, lòng tự trọng của tôi bị tổn thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11073, 41325, '国会で大臣への質疑が行われた。', 'こっかいで だいじんへの しつぎが おこなわれた。', 'Tại quốc hội đã diễn ra phiên chất vấn bộ trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11074, 41316, '大臣は責任をとって辞職した。', 'だいじんは せきにんを とって じしょく した。', 'Bộ trưởng đã từ chức để nhận trách nhiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11075, 41328, '彼は成功した実業家だ。', 'かれは せいこう した じつぎょうかだ。', 'Ông ấy là một doanh nhân thành đạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11076, 41314, '「開く」は自動詞にも他動詞にもなる。', '「あく」は じどうしにも たどうしにも なる。', '"Hiraku" vừa là tự động từ vừa là tha động từ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11077, 41320, '祖父が亡くなって七日が過ぎた。', 'そふが なくなって なぬかが すぎた。', 'Ông mất đã được bảy ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11078, 41331, '学んだことを実践するのは難しい。', 'まなんだ ことを じっせん するのは むずかしい。', 'Đem những điều đã học ra thực hành thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11079, 41311, '彼はボールを自由自在に操る。', 'かれは ボールを じゆう じざいに あやつる。', 'Anh ấy điều khiển quả bóng tùy ý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11080, 41317, '結婚式の式場を予約した。', 'けっこんしきの しきじょうを よやく した。', 'Chúng tôi đã đặt hội trường tổ chức đám cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11081, 41318, '地球は地軸を中心に回っている。', 'ちきゅうは ちじくを ちゅうしんに まわって いる。', 'Trái Đất quay quanh trục của nó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11082, 28032, 'ガガーリンは初めて宇宙へ行った人です。', 'ガガーリンは はじめて うちゅうへ いった ひと です。', 'Gagarin là người đầu tiên bay vào vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11083, 28049, '彼はユーモアがあって、おもしろい人です。', 'かれは ユーモアが あって、おもしろい ひと です。', 'Anh ấy có khiếu hài hước, là người thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11084, 28060, '私は一九九五年に生まれました。', 'わたしは せんきゅうひゃくきゅうじゅうごねんに うまれました。', 'Tôi sinh năm 1995.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11085, 28068, '毎日お弁当を作ります。', 'まいにち おべんとうを つくります。', 'Ngày nào tôi cũng làm cơm hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11086, 28080, '和室で布団を敷いて寝ます。', 'わしつで ふとんを しいて ねます。', 'Tôi trải nệm ngủ trong phòng kiểu Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11087, 28085, 'みんなのアンケートに答えました。', 'みんなの アンケートに こたえました。', 'Tôi đã trả lời bảng khảo sát Minna.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11088, 28089, 'レジャー白書によると、旅行が人気です。', 'レジャー はくしょに よると、りょこうが にんき です。', 'Theo sách trắng về giải trí, du lịch đang được ưa chuộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11089, 28070, '彼はユーモアがあって、おもしろい人です。', 'かれは ユーモアが あって、おもしろい ひと です。', 'Anh ấy có khiếu hài hước, là người thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11090, 28091, 'このつまみを右へ回してください。', 'この つまみを みぎへ まわして ください。', 'Hãy vặn núm này sang phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11091, 28096, '毎日三十分歩きます。', 'まいにち さんじゅっぷん あるきます。', 'Mỗi ngày tôi đi bộ ba mươi phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11092, 28105, '次の交差点を右へ曲がってください。', 'つぎの こうさてんを みぎへ まがって ください。', 'Đến ngã tư tiếp theo hãy rẽ phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11093, 28109, '駐車場に車を止めました。', 'ちゅうしゃじょうに くるまを とめました。', 'Tôi đỗ xe ở bãi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11094, 28113, '聖徳太子は法隆寺を建てました。', 'しょうとく たいしは ほうりゅうじを たてました。', 'Thái tử Shotoku đã xây chùa Horyuji.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11095, 28102, 'もう少し大きいサイズはありますか。', 'もう すこし おおきい サイズは ありますか。', 'Có cỡ lớn hơn một chút không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11096, 28134, '京都を案内してくれませんか。', 'きょうとを あんない して くれませんか。', 'Bạn dẫn tôi đi tham quan Kyoto được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11097, 41409, '就業時間は九時から六時までだ。', 'しゅうぎょう じかんは くじから ろくじまでだ。', 'Giờ làm việc từ chín giờ đến sáu giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11098, 41410, '中学三年生は修学旅行で京都へ行く。', 'ちゅうがく さんねんせいは しゅうがく りょこうで きょうとへ いく。', 'Học sinh lớp chín đi tham quan học tập ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11099, 41412, '衆議院が解散された。', 'しゅうぎいんが かいさん された。', 'Hạ viện đã bị giải tán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11100, 41351, '日本人の主食は米だ。', 'にほんじんの しゅしょくは こめだ。', 'Lương thực chính của người Nhật là gạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11101, 41408, 'この彗星は七十六年の周期で地球に近づく。', 'この すいせいは ななじゅうろくねんの しゅうきで ちきゅうに ちかづく。', 'Sao chổi này tiến gần Trái Đất với chu kỳ 76 năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11102, 41418, '駅まで歩いて十分かかる。', 'えきまで あるいて じっぷん かかる。', 'Đi bộ đến ga mất mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11103, 41347, '年を取って足腰が弱ってきた。', 'としを とって あしこしが よわって きた。', 'Có tuổi nên chân tay yếu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11104, 41359, '当店では外国の食品も取り扱っています。', 'とうてんでは がいこくの しょくひんも とりあつかって います。', 'Cửa hàng chúng tôi cũng kinh doanh thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11105, 41361, '北海道からカニを取り寄せた。', 'ほっかいどうから カニを とりよせた。', 'Tôi đặt cua gửi về từ Hokkaido.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11106, 41352, '学生が主体となってイベントを企画した。', 'がくせいが しゅたいと なって イベントを きかく した。', 'Sinh viên làm chủ thể lên kế hoạch cho sự kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11107, 28139, '引っ越しを手伝ってくれて、ありがとう。', 'ひっこしを てつだって くれて、ありがとう。', 'Cảm ơn bạn đã giúp tôi chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11108, 28141, '夏休みにアメリカでホームステイをしました。', 'なつやすみに アメリカで ホームステイを しました。', 'Kỳ nghỉ hè tôi ở homestay tại Mỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11109, 28158, 'この言葉の意味を教えてください。', 'この ことばの いみを おしえて ください。', 'Hãy cho tôi biết nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11110, 28160, '父の転勤で大阪へ引っ越しました。', 'ちちの てんきんで おおさかへ ひっこしました。', 'Vì bố chuyển công tác nên nhà tôi chuyển đến Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11111, 44769, '父の転勤で大阪へ引っ越しました。', 'ちちの てんきんで おおさかへ ひっこしました。', 'Vì bố chuyển công tác nên nhà tôi chuyển đến Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11112, 28186, '財布を忘れました。', 'さいふを わすれました。', 'Tôi quên ví rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11113, 28259, '本棚に本がたくさんあります。', 'ほんだなに ほんが たくさん あります。', 'Trên giá sách có rất nhiều sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11114, 28304, '母は台所で料理をしています。', 'ははは だいどころで りょうりを して います。', 'Mẹ đang nấu ăn trong bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11115, 28372, 'コップに水を入れてください。', 'コップに みずを いれて ください。', 'Hãy rót nước vào cốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11116, 28423, '授業は九時に始まります。', 'じゅぎょうは くじに はじまります。', 'Giờ học bắt đầu lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11117, 28472, '今夜は月がきれいですね。', 'こんやは つきが きれい ですね。', 'Đêm nay trăng đẹp nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11118, 28568, 'この料理はそんなに辛くないです。', 'この りょうりは そんなに からく ない です。', 'Món này không cay lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11119, 28167, '来年、日本に留学します。', 'らいねん、にほんに りゅうがく します。', 'Năm sau tôi sẽ du học Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11120, 45046, 'たぶん、彼は来ないと思います。', 'たぶん、かれは こないと おもいます。', 'Có lẽ anh ấy sẽ không đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11121, 28169, 'グループで旅行します。', 'グループで りょこう します。', 'Chúng tôi đi du lịch theo nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11122, 29166, '祖母は田舎に住んでいます。', 'そぼは いなかに すんで います。', 'Bà tôi sống ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11123, 29183, 'このクラスは男が十人、女が五人です。', 'この クラスは おとこが じゅうにん、おんなが ごにん です。', 'Lớp này có mười nam và năm nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11124, 29610, 'では、いただきます。', 'では、いただきます。', 'Vậy, xin mời mọi người ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11125, 43395, 'スーパーで肉と野菜を買います。', 'スーパーで にくと やさいを かいます。', 'Tôi mua thịt và rau ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11126, 43396, 'デパートでかばんを買いました。', 'デパートで かばんを かいました。', 'Tôi mua cặp ở trung tâm thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11127, 43456, '熱があるので、病院へ行きます。', 'ねつが あるので、びょういんへ いきます。', 'Tôi bị sốt nên đi bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11128, 43457, '郵便局で切手を買いました。', 'ゆうびんきょくで きってを かいました。', 'Tôi mua tem ở bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11129, 43462, '夏休みに国へ帰ります。', 'なつやすみに くにへ かえります。', 'Kỳ nghỉ hè tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11130, 43464, '友達にギターを習っています。', 'ともだちに ギターを ならって います。', 'Tôi học đàn ghi-ta với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11131, 43675, '玄関で靴を脱いでください。', 'げんかんで くつを ぬいで ください。', 'Hãy cởi giày ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11132, 41419, 'この工場には五百人の従業員がいる。', 'この こうじょうには ごひゃくにんの じゅうぎょういんが いる。', 'Nhà máy này có năm trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11133, 41423, 'あんな獣のような人間は許せない。', 'あんな けだものの ような にんげんは ゆるせない。', 'Không thể tha thứ cho loại người như cầm thú ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11134, 41422, 'このお茶は少し渋い。', 'この おちゃは すこし しぶい。', 'Trà này hơi chát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11135, 43674, 'すみません、トイレを貸してください。', 'すみません、トイレを かして ください。', 'Xin lỗi, cho tôi mượn nhà vệ sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11136, 43745, '日本のお菓子はおいしいです。', 'にほんの おかしは おいしい です。', 'Bánh kẹo Nhật ngon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11137, 43749, 'テーブルに皿を並べてください。', 'テーブルに さらを ならべて ください。', 'Hãy xếp đĩa lên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11138, 43757, '八百屋で野菜を買いました。', 'やおやで やさいを かいました。', 'Tôi mua rau ở cửa hàng rau quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11139, 43760, 'この店は値段が安いです。', 'この みせは ねだんが やすい です。', 'Cửa hàng này giá rẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11142, 43766, '毎朝、パンを食べます。', 'まいあさ、パンを たべます。', 'Sáng nào tôi cũng ăn bánh mì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11143, 43768, 'きょうはカレーを作ります。', 'きょうは カレーを つくります。', 'Hôm nay tôi nấu cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11144, 43770, 'この店で古い本を売っています。', 'この みせで ふるい ほんを うって います。', 'Cửa hàng này bán sách cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11145, 43773, 'ラーメンを頼みました。', 'ラーメンを たのみました。', 'Tôi đã gọi mì ramen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11146, 43776, 'このりんごは甘いです。', 'この りんごは あまい です。', 'Quả táo này ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11147, 43778, 'このカメラは高いです。', 'この カメラは たかい です。', 'Chiếc máy ảnh này đắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11148, 43780, 'このお茶は熱いです。', 'この おちゃは あつい です。', 'Trà này nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11149, 43781, '冷たい水を飲みたいです。', 'つめたい みずを のみたい です。', 'Tôi muốn uống nước lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11150, 43784, 'お腹が痛いです。', 'おなかが いたい です。', 'Tôi đau bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11151, 43785, 'お腹がすきました。何か食べましょう。', 'おなかが すきました。なにか たべましょう。', 'Đói bụng rồi. Ăn gì đó đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11152, 43755, 'スーパーで肉と野菜を買います。', 'スーパーで にくと やさいを かいます。', 'Tôi mua thịt và rau ở siêu thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11153, 43799, '質問がありますか。', 'しつもんが ありますか。', 'Có câu hỏi nào không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11154, 43804, 'この言葉は難しいです。', 'この ことばは むずかしい です。', 'Từ này khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11155, 43808, '家族について作文を書きました。', 'かぞくに ついて さくぶんを かきました。', 'Tôi viết bài văn về gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11156, 43811, '父の会社は大阪にあります。', 'ちちの かいしゃは おおさかに あります。', 'Công ty của bố tôi ở Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11157, 43816, '熱があるので、病院へ行きます。', 'ねつが あるので、びょういんへ いきます。', 'Tôi bị sốt nên đi bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11158, 43817, '郵便局で切手を買いました。', 'ゆうびんきょくで きってを かいました。', 'Tôi mua tem ở bưu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11159, 43824, '友達にギターを習っています。', 'ともだちに ギターを ならって います。', 'Tôi học đàn ghi-ta với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11160, 43825, '新しい言葉を覚えました。', 'あたらしい ことばを おぼえました。', 'Tôi đã nhớ được từ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11161, 43921, '次の交差点を右へ曲がってください。', 'つぎの こうさてんを みぎへ まがって ください。', 'Đến ngã tư tiếp theo hãy rẽ phải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11162, 43922, '信号が青になったら、渡ります。', 'しんごうが あおに なったら、わたります。', 'Khi đèn xanh thì sang đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11163, 44091, '引っ越しを手伝ってくれて、ありがとう。', 'ひっこしを てつだって くれて、ありがとう。', 'Cảm ơn bạn đã giúp tôi chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11164, 41464, '諸君の健闘を祈る。', 'しょくんの けんとうを いのる。', 'Chúc các bạn chiến đấu hết mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11165, 41434, '傷口から出血している。', 'きずぐちから しゅっけつ して いる。', 'Vết thương đang chảy máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11166, 44092, 'このアパートの家賃は六万円です。', 'この アパートの やちんは ろくまんえん です。', 'Tiền thuê căn hộ này là sáu mươi nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11167, 44090, '駅の近くのアパートに住んでいます。', 'えきの ちかくの アパートに すんで います。', 'Tôi sống ở căn hộ gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11168, 44108, 'この機械の使い方を教えてください。', 'この きかいの つかいかたを おしえて ください。', 'Hãy chỉ tôi cách dùng chiếc máy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11169, 44451, '引っ越しを手伝ってくれて、ありがとう。', 'ひっこしを てつだって くれて、ありがとう。', 'Cảm ơn bạn đã giúp tôi chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11170, 44456, '布団は押し入れに入れます。', 'ふとんは おしいれに いれます。', 'Chăn nệm được cất vào tủ âm tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11171, 44450, '駅の近くのアパートに住んでいます。', 'えきの ちかくの アパートに すんで います。', 'Tôi sống ở căn hộ gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11172, 28114, '法隆寺は世界で一番古い木の建物です。', 'ほうりゅうじは せかいで いちばん ふるい きの たてもの です。', 'Chùa Horyuji là công trình gỗ cổ nhất thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11173, 44811, '引っ越しを手伝ってくれて、ありがとう。', 'ひっこしを てつだって くれて、ありがとう。', 'Cảm ơn bạn đã giúp tôi chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11174, 44810, '駅の近くのアパートに住んでいます。', 'えきの ちかくの アパートに すんで います。', 'Tôi sống ở căn hộ gần ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11175, 28055, '寒いですから、コートを着ます。', 'さむい ですから、コートを きます。', 'Trời lạnh nên tôi mặc áo khoác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11176, 38329, '毎晩お風呂に入ります。', 'まいばん おふろに はいります。', 'Tối nào tôi cũng tắm bồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11177, 38351, 'ペンで名前を書いてください。', 'ペンで なまえを かいて ください。', 'Hãy viết tên bằng bút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11178, 38370, '結婚はいつですか。', 'けっこんは いつ ですか。', 'Khi nào bạn kết hôn?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11179, 38366, '夏休みに国へ帰ります。', 'なつやすみに くにへ かえります。', 'Kỳ nghỉ hè tôi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11180, 44141, '道がわからなくて困りました。', 'みちが わからなくて こまりました。', 'Không biết đường nên tôi bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11181, 44143, '駅から遠くて不便です。', 'えきから とおくて ふべん です。', 'Xa ga nên bất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11182, 44145, '適当な大きさに切ってください。', 'てきとうな おおきさに きって ください。', 'Hãy cắt với kích cỡ thích hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11183, 44180, 'ごみの収集は月曜日です。', 'ごみの しゅうしゅうは げつようび です。', 'Rác được thu gom vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11184, 44182, '日本の生活を楽しんでいます。', 'にほんの せいかつを たのしんで います。', 'Tôi đang tận hưởng cuộc sống ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11185, 44184, 'カラオケで歌いました。', 'カラオケで うたいました。', 'Tôi đã hát karaoke.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11186, 44186, '子どもが絵を描いています。', 'こどもが えを かいて います。', 'Đứa trẻ đang vẽ tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11187, 44190, '試合に負けて、悔しかったです。', 'しあいに まけて、くやしかった です。', 'Thua trận nên tôi rất tiếc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11188, 41478, '子供が熱を出したので、小児科に連れて行った。', 'こどもが ねつを だしたので、しょうにかに つれて いった。', 'Con bị sốt nên tôi đưa đến khoa nhi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11189, 41477, '会社は社員に資格の取得を奨励している。', 'かいしゃは しゃいんに しかくの しゅとくを しょうれい して いる。', 'Công ty khuyến khích nhân viên lấy chứng chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11190, 41486, '友人の招きで、パーティーに出席した。', 'ゆうじんの まねきで、パーティーに しゅっせき した。', 'Theo lời mời của bạn, tôi đã dự bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11191, 41484, '疲れていたので、早めに床についた。', 'つかれて いたので、はやめに とこに ついた。', 'Mệt nên tôi đi ngủ sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11192, 41483, 'だめだと言われると、尚更やりたくなる。', 'だめだと いわれると、なおさら やりたく なる。', 'Bị bảo không được thì lại càng muốn làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11193, 37913, '妹は赤いスカートをはいています。', 'いもうとは あかい スカートを はいて います。', 'Em gái tôi đang mặc chân váy đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11194, 38359, '会社へ白いワイシャツを着て行きます。', 'かいしゃへ しろい ワイシャツを きて いきます。', 'Tôi mặc áo sơ mi trắng đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11195, 31275, 'コンビニで弁当を買いました。', 'コンビニで べんとうを かいました。', 'Tôi mua cơm hộp ở cửa hàng tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11196, 31313, '春になって、暖かくなりました。', 'はるに なって、あたたかく なりました。', 'Sang xuân trời ấm lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11197, 37908, '今日の気温は三十度です。', 'きょうの きおんは さんじゅうど です。', 'Nhiệt độ hôm nay là ba mươi độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11198, 37912, '木の影で休みましょう。', 'きの かげで やすみましょう。', 'Nghỉ dưới bóng cây đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11199, 38407, '八時に会社へ行きます。', 'はちじに かいしゃへ いきます。', 'Tám giờ tôi đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11200, 38418, '六時に起きます。', 'ろくじに おきます。', 'Sáu giờ tôi dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11201, 31291, '毎朝、川の近くを走ります。', 'まいあさ、かわの ちかくを はしります。', 'Sáng nào tôi cũng chạy bộ gần sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11202, 31293, '夏は海で泳ぎます。', 'なつは うみで およぎます。', 'Mùa hè tôi bơi ở biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11203, 31300, 'この電車は次の駅に止まりません。', 'この でんしゃは つぎの えきに とまりません。', 'Chuyến tàu này không dừng ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11204, 31302, '仕事は五時に終わります。', 'しごとは ごじに おわります。', 'Công việc kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11205, 31305, '暗いですから、電気を付けてください。', 'くらい ですから、でんきを つけて ください。', 'Tối quá, hãy bật đèn lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11206, 31348, 'この絵に触らないでください。', 'この えに さわらないで ください。', 'Xin đừng chạm vào bức tranh này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11207, 37685, '毎朝、公園を走ります。', 'まいあさ、こうえんを はしります。', 'Sáng nào tôi cũng chạy bộ trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11208, 37689, '風でドアが開きました。', 'かぜで ドアが あきました。', 'Gió làm cánh cửa mở ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11209, 37690, '銀行は三時に閉まります。', 'ぎんこうは さんじに しまります。', 'Ngân hàng đóng cửa lúc ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11210, 37692, '急に電気が消えました。', 'きゅうに でんきが きえました。', 'Đèn bỗng nhiên tắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11211, 38402, '喫茶店に入りましょう。', 'きっさてんに はいりましょう。', 'Vào quán cà phê đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11212, 38390, 'このかばんはとても丈夫です。', 'この かばんは とても じょうぶ です。', 'Chiếc cặp này rất bền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11213, 38396, 'A：大丈夫ですか。B：はい、大丈夫です。', 'エー：だいじょうぶ ですか。ビー：はい、だいじょうぶ です。', 'A: Bạn ổn chứ? B: Vâng, tôi không sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11214, 38401, '夜の町は賑やかです。', 'よるの まちは にぎやか です。', 'Thị trấn về đêm thật nhộn nhịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11215, 38415, '京都は古いお寺で有名です。', 'きょうとは ふるい おてらで ゆうめい です。', 'Kyoto nổi tiếng với những ngôi chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11216, 41494, 'そのニュースは世界中に衝撃を与えた。', 'その ニュースは せかいじゅうに しょうげきを あたえた。', 'Tin tức đó gây chấn động khắp thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11217, 41511, '祖母は情け深い人だった。', 'そぼは なさけぶかい ひと だった。', 'Bà tôi là người giàu lòng trắc ẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11218, 41514, '彼は音楽に情熱を注いでいる。', 'かれは おんがくに じょうねつを そそいで いる。', 'Anh ấy dồn hết đam mê vào âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11219, 41496, '目撃者が法廷で証言した。', 'もくげきしゃが ほうていで しょうげん した。', 'Nhân chứng đã khai trước tòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11220, 38388, '小さな町に住んでいます。', 'ちいさな まちに すんで います。', 'Tôi sống ở một thị trấn nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11221, 31296, '次の駅で電車を降ります。', 'つぎの えきで でんしゃを おります。', 'Tôi xuống tàu ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11222, 31299, 'この橋を渡ってください。', 'この はしを わたって ください。', 'Hãy đi qua cây cầu này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11223, 37686, '二つ目の角を左へ曲がります。', 'ふたつめの かどを ひだりへ まがります。', 'Đến góc thứ hai thì rẽ trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11224, 38325, 'おまわりさんに道を聞きました。', 'おまわりさんに みちを ききました。', 'Tôi hỏi đường chú cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11225, 37905, '先生の質問に答えます。', 'せんせいの しつもんに こたえます。', 'Tôi trả lời câu hỏi của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11226, 37918, 'みんなの声援で、最後まで走れました。', 'みんなの せいえんで、さいごまで はしれました。', 'Nhờ mọi người cổ vũ mà tôi chạy được đến cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11227, 38392, 'お先にどうぞ。', 'おさきに どうぞ。', 'Mời anh đi trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11228, 38395, '私はすしが大好きです。', 'わたしは すしが だいすき です。', 'Tôi rất thích sushi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11229, 38409, 'この文章を読んでください。', 'この ぶんしょうを よんで ください。', 'Hãy đọc đoạn văn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11230, 43469, 'ここに住所を書いてください。', 'ここに じゅうしょを かいて ください。', 'Hãy viết địa chỉ vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11231, 43471, '日曜日に映画を見ました。', 'にちようびに えいがを みました。', 'Chủ nhật tôi đã xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11232, 43473, '仕事は五時に終わります。', 'しごとは ごじに おわります。', 'Công việc kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11233, 43475, '疲れたので、少し休みます。', 'つかれたので、すこし やすみます。', 'Mệt rồi nên tôi nghỉ một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11234, 43478, '友達に辞書を借りました。', 'ともだちに じしょを かりました。', 'Tôi mượn từ điển của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11235, 43481, 'この問題は易しいです。', 'この もんだいは やさしい です。', 'Câu hỏi này dễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11236, 43484, '田中さんは歌が上手です。', 'たなかさんは うたが じょうず です。', 'Anh Tanaka hát hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11237, 43486, '家族はとても大切です。', 'かぞくは とても たいせつ です。', 'Gia đình rất quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11238, 43491, '毎朝七時に起きます。', 'まいあさ しちじに おきます。', 'Sáng nào tôi cũng dậy lúc bảy giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11239, 43501, '明日、友達に会います。', 'あした、ともだちに あいます。', 'Ngày mai tôi gặp bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11240, 43528, '明日は晴れでしょう。', 'あしたは はれ でしょう。', 'Ngày mai có lẽ trời nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11241, 43531, '北海道の冬は寒いです。', 'ほっかいどうの ふゆは さむい です。', 'Mùa đông ở Hokkaido lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11242, 43533, '秋は涼しくて、いい季節です。', 'あきは すずしくて、いい きせつ です。', 'Mùa thu mát mẻ, là mùa đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11243, 43535, '強い風が吹いています。', 'つよい かぜが ふいて います。', 'Gió đang thổi mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11244, 43537, '空が曇ってきました。', 'そらが くもって きました。', 'Bầu trời bắt đầu có mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11245, 43539, 'もう遅いですから、帰りましょう。', 'もう おそい ですから、かえりましょう。', 'Muộn rồi, về thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11246, 41535, 'あなたがいてくれると心強い。', 'あなたが いて くれると こころづよい。', 'Có bạn ở bên tôi thấy vững lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11247, 41532, '書類審査に合格した。', 'しょるい しんさに ごうかく した。', 'Tôi đã qua vòng xét duyệt hồ sơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11248, 41529, '他国を侵略することは許されない。', 'たこくを しんりゃく する ことは ゆるされない。', 'Xâm lược nước khác là điều không thể chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11249, 41530, '赤ちゃんをベッドに寝かせた。', 'あかちゃんを ベッドに ねかせた。', 'Tôi đặt em bé nằm lên giường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11250, 43541, '妹は髪が短いです。', 'いもうとは かみが みじかい です。', 'Em gái tôi tóc ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11251, 43568, '駅の近くに映画館があります。', 'えきの ちかくに えいがかんが あります。', 'Gần ga có rạp chiếu phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11252, 43574, '公園の池に魚がいます。', 'こうえんの いけに さかなが います。', 'Trong ao ở công viên có cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11253, 43580, '私の後ろに田中さんがいます。', 'わたしの うしろに たなかさんが います。', 'Anh Tanaka ở phía sau tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11254, 43584, '駅の西に大きい公園があります。', 'えきの にしに おおきい こうえんが あります。', 'Phía tây ga có một công viên lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11255, 43586, '北海道は日本の北にあります。', 'ほっかいどうは にほんの きたに あります。', 'Hokkaido nằm ở phía bắc Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11256, 43588, '友達がうちへ来ました。', 'ともだちが うちへ きました。', 'Bạn tôi đã đến nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11257, 43590, '毎朝、公園を歩きます。', 'まいあさ、こうえんを あるきます。', 'Sáng nào tôi cũng đi bộ trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11258, 43592, '駅でバスに乗ります。', 'えきで バスに のります。', 'Tôi lên xe buýt ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11259, 43593, '次の駅で電車を降ります。', 'つぎの えきで でんしゃを おります。', 'Tôi xuống tàu ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11260, 43594, 'この橋を渡ってください。', 'この はしを わたって ください。', 'Hãy đi qua cây cầu này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11261, 43596, 'この電車は次の駅に止まりません。', 'この でんしゃは つぎの えきに とまりません。', 'Chuyến tàu này không dừng ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11262, 43598, '毎朝八時に家を出ます。', 'まいあさ はちじに いえを でます。', 'Sáng nào tôi cũng rời nhà lúc tám giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11263, 43600, 'ここで少し待ってください。', 'ここで すこし まって ください。', 'Hãy đợi ở đây một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11264, 43603, 'あの大きい建物は何ですか。', 'あの おおきい たてものは なん ですか。', 'Tòa nhà to kia là gì vậy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11265, 43605, 'この町はにぎやかです。', 'この まちは にぎやか です。', 'Thị trấn này náo nhiệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11266, 43606, '図書館では静かにしてください。', 'としょかんでは しずかに して ください。', 'Ở thư viện xin hãy giữ yên lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11267, 43608, '駅の近くは便利です。', 'えきの ちかくは べんり です。', 'Gần ga thì tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11268, 43834, '兄は銀行で働いています。', 'あには ぎんこうで はたらいて います。', 'Anh tôi làm việc ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11270, 43838, '友達に辞書を借りました。', 'ともだちに じしょを かりました。', 'Tôi mượn từ điển của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11271, 43841, 'この問題は易しいです。', 'この もんだいは やさしい です。', 'Câu hỏi này dễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11272, 43844, '田中さんは歌が上手です。', 'たなかさんは うたが じょうず です。', 'Anh Tanaka hát hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11273, 43846, '家族はとても大切です。', 'かぞくは とても たいせつ です。', 'Gia đình rất quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11274, 43847, 'すみません、もう一度言ってください。', 'すみません、もう いちど いって ください。', 'Xin lỗi, hãy nói lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11275, 43860, '今日は何曜日ですか。', 'きょうは なんようび ですか。', 'Hôm nay là thứ mấy?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11276, 43862, '昨日は雨でした。', 'きのうは あめ でした。', 'Hôm qua trời mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11277, 43886, '今日は風が強いです。', 'きょうは かぜが つよい です。', 'Hôm nay gió mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11278, 41563, '彼は礼儀正しい紳士だ。', 'かれは れいぎ ただしい しんしだ。', 'Ông ấy là một quý ông lịch lãm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11279, 41569, '言葉が通じないので、身振りで伝えた。', 'ことばが つうじないので、みぶりで つたえた。', 'Không hiểu ngôn ngữ của nhau nên tôi diễn đạt bằng cử chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11280, 41537, 'このベッドは寝心地がいい。', 'この ベッドは ねごこちが いい。', 'Chiếc giường này nằm rất dễ chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11281, 43888, '明日は晴れでしょう。', 'あしたは はれ でしょう。', 'Ngày mai có lẽ trời nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11282, 43891, '北海道の冬は寒いです。', 'ほっかいどうの ふゆは さむい です。', 'Mùa đông ở Hokkaido lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11283, 43893, '秋は涼しくて、いい季節です。', 'あきは すずしくて、いい きせつ です。', 'Mùa thu mát mẻ, là mùa đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11284, 43895, '強い風が吹いています。', 'つよい かぜが ふいて います。', 'Gió đang thổi mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11285, 43897, '空が曇ってきました。', 'そらが くもって きました。', 'Bầu trời bắt đầu có mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11286, 43899, 'もう遅いですから、帰りましょう。', 'もう おそい ですから、かえりましょう。', 'Muộn rồi, về thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11287, 43901, '妹は髪が短いです。', 'いもうとは かみが みじかい です。', 'Em gái tôi tóc ngắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11288, 43981, '首が痛いです。', 'くびが いたい です。', 'Tôi bị đau cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11289, 43986, '背中がかゆいです。', 'せなかが かゆい です。', 'Lưng tôi ngứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11290, 44019, 'A：大丈夫ですか。B：はい、大丈夫です。', 'エー：だいじょうぶ ですか。ビー：はい、だいじょうぶ です。', 'A: Bạn ổn chứ? B: Vâng, tôi không sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11291, 44187, '夏は海で泳ぎます。', 'なつは うみで およぎます。', 'Mùa hè tôi bơi ở biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11292, 44239, '窓から光が入ります。', 'まどから ひかりが はいります。', 'Ánh sáng chiếu vào qua cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11293, 44260, '子どものプールは浅いです。', 'こどもの プールは あさい です。', 'Hồ bơi trẻ em thì nông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11294, 44338, '姉は病院の看護師です。', 'あねは びょういんの かんごし です。', 'Chị tôi là y tá ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11295, 44351, '指から血が出ています。', 'ゆびから ちが でて います。', 'Ngón tay đang chảy máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11296, 44378, 'このかばんはとても丈夫です。', 'この かばんは とても じょうぶ です。', 'Chiếc cặp này rất bền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11297, 44594, '今日の気温は三十度です。', 'きょうの きおんは さんじゅうど です。', 'Nhiệt độ hôm nay là ba mươi độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11298, 44619, 'この川は深いですから、泳がないでください。', 'この かわは ふかい ですから、およがないで ください。', 'Sông này sâu, đừng bơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11299, 44698, '姉は病院の看護師です。', 'あねは びょういんの かんごし です。', 'Chị tôi là y tá ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11300, 28378, '道がわからないので、交番で聞きました。', 'みちが わからないので、こうばんで ききました。', 'Không biết đường nên tôi hỏi ở đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11301, 28400, '駅の西に大きい公園があります。', 'えきの にしに おおきい こうえんが あります。', 'Phía tây ga có một công viên lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11302, 41592, '推理小説を読むのが好きだ。', 'すいり しょうせつを よむのが すきだ。', 'Tôi thích đọc tiểu thuyết trinh thám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11303, 41601, '日本語の数詞は数える物によって変わる。', 'にほんごの すうしは かぞえる ものに よって かわる。', 'Số từ tiếng Nhật thay đổi theo vật được đếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11304, 41605, 'ズボンの裾が長すぎるので、短くしてもらった。', 'ズボンの すそが ながすぎるので、みじかく して もらった。', 'Gấu quần dài quá nên tôi nhờ sửa ngắn lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11305, 41593, '野菜の水気をよく切ってから炒める。', 'やさいの すいきを よく きってから いためる。', 'Để ráo nước rau rồi mới xào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11306, 41588, '彼は社会のために力を尽くした。', 'かれは しゃかいの ために ちからを つくした。', 'Ông ấy đã dốc sức vì xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11307, 41603, '部屋の真ん中にテーブルを据えた。', 'へやの まんなかに テーブルを すえた。', 'Tôi đặt cố định cái bàn ở giữa phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11308, 41589, '迅速な対応に感謝します。', 'じんそくな たいおうに かんしゃ します。', 'Cảm ơn sự xử lý nhanh chóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11309, 41587, '甚だ残念な結果となった。', 'はなはだ ざんねんな けっかと なった。', 'Kết quả hết sức đáng tiếc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11310, 41626, 'この問題の正解は三番です。', 'この もんだいの せいかいは さんばん です。', 'Đáp án đúng của câu này là số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11311, 44908, '日曜日、山に登りました。', 'にちようび、やまに のぼりました。', 'Chủ nhật tôi đã leo núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11312, 44954, '今日の気温は三十度です。', 'きょうの きおんは さんじゅうど です。', 'Nhiệt độ hôm nay là ba mươi độ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11313, 28507, '駅の近くに映画館があります。', 'えきの ちかくに えいがかんが あります。', 'Gần ga có rạp chiếu phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11314, 28557, '沖縄は日本の南にあります。', 'おきなわは にほんの みなみに あります。', 'Okinawa nằm ở phía nam Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11315, 43467, '先生の話がよく分かりました。', 'せんせいの はなしが よく わかりました。', 'Tôi hiểu rõ lời thầy nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11316, 43558, '空港へ友達を迎えに行きます。', 'くうこうへ ともだちを むかえに いきます。', 'Tôi ra sân bay đón bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11317, 43826, '傘を電車に忘れました。', 'かさを でんしゃに わすれました。', 'Tôi để quên ô trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11318, 43828, '毎晩、本を読みます。', 'まいばん、ほんを よみます。', 'Tối nào tôi cũng đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11319, 43829, 'ここに住所を書いてください。', 'ここに じゅうしょを かいて ください。', 'Hãy viết địa chỉ vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11320, 43831, '日曜日に映画を見ました。', 'にちようびに えいがを みました。', 'Chủ nhật tôi đã xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11321, 43833, '仕事は五時に終わります。', 'しごとは ごじに おわります。', 'Công việc kết thúc lúc năm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11322, 43930, '道がわからないので、交番で聞きました。', 'みちが わからないので、こうばんで ききました。', 'Không biết đường nên tôi hỏi ở đồn cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11323, 43943, '太陽は東から出ます。', 'たいようは ひがしから でます。', 'Mặt trời mọc ở phía đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11324, 43945, '沖縄は日本の南にあります。', 'おきなわは にほんの みなみに あります。', 'Okinawa nằm ở phía nam Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11325, 43946, '北海道は日本の北にあります。', 'ほっかいどうは にほんの きたに あります。', 'Hokkaido nằm ở phía bắc Nhật Bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11326, 43948, '友達がうちへ来ました。', 'ともだちが うちへ きました。', 'Bạn tôi đã đến nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11327, 44194, '友達を食事に誘いました。', 'ともだちを しょくじに さそいました。', 'Tôi rủ bạn đi ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11328, 41609, '政府は世論の反発を受けて方針を変えた。', 'せいふは よろんの はんぱつを うけて ほうしんを かえた。', 'Trước phản ứng của dư luận, chính phủ đã đổi phương châm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11329, 41615, '台風は勢力を強めながら北上している。', 'たいふうは せいりょくを つよめながら ほくじょう して いる。', 'Cơn bão đang mạnh dần lên trong khi di chuyển lên phía bắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11330, 41627, '彼は正義のために戦った。', 'かれは せいぎの ために たたかった。', 'Anh ấy đã chiến đấu vì chính nghĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11331, 41623, '冬の夜空にオリオン座という星座が見える。', 'ふゆの よぞらに オリオンざと いう せいざが みえる。', 'Trên bầu trời đêm mùa đông có thể thấy chòm sao Orion.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11332, 41635, '今年は稲の生育が順調だ。', 'ことしは いねの せいいくが じゅんちょうだ。', 'Năm nay lúa sinh trưởng thuận lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11333, 41620, '出かける前に髪を整えた。', 'でかける まえに かみを ととのえた。', 'Trước khi ra ngoài tôi chỉnh lại tóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11334, 41622, '生徒たちは校庭に整列した。', 'せいとたちは こうていに せいれつ した。', 'Học sinh xếp hàng ở sân trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11335, 41621, '倉庫の中は整然としていた。', 'そうこの なかは せいぜんと して いた。', 'Trong kho rất ngăn nắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11336, 41629, '朝の空気は清々しい。', 'あさの くうきは すがすがしい。', 'Không khí buổi sáng thật trong lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11337, 41631, '彼女は清純な役が似合う。', 'かのじょは せいじゅんな やくが にあう。', 'Cô ấy hợp với vai trong sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11338, 41644, '病院で精密な検査を受けた。', 'びょういんで せいみつな けんさを うけた。', 'Tôi đã được kiểm tra kỹ lưỡng ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11339, 43950, '毎朝、公園を歩きます。', 'まいあさ、こうえんを あるきます。', 'Sáng nào tôi cũng đi bộ trong công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11340, 43952, '駅でバスに乗ります。', 'えきで バスに のります。', 'Tôi lên xe buýt ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11341, 43954, 'この橋を渡ってください。', 'この はしを わたって ください。', 'Hãy đi qua cây cầu này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11342, 43956, 'この電車は次の駅に止まりません。', 'この でんしゃは つぎの えきに とまりません。', 'Chuyến tàu này không dừng ở ga tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11343, 43958, '毎朝八時に家を出ます。', 'まいあさ はちじに いえを でます。', 'Sáng nào tôi cũng rời nhà lúc tám giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11344, 43960, 'ここで少し待ってください。', 'ここで すこし まって ください。', 'Hãy đợi ở đây một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11345, 43962, '学校はうちから遠いです。', 'がっこうは うちから とおい です。', 'Trường ở xa nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11346, 43964, 'このかばんは小さいです。', 'この かばんは ちいさい です。', 'Chiếc cặp này nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11347, 43966, '図書館では静かにしてください。', 'としょかんでは しずかに して ください。', 'Ở thư viện xin hãy giữ yên lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11348, 43967, '京都は古いお寺で有名です。', 'きょうとは ふるい おてらで ゆうめい です。', 'Kyoto nổi tiếng với những ngôi chùa cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11349, 44547, '夏は海で泳ぎます。', 'なつは うみで およぎます。', 'Mùa hè tôi bơi ở biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11350, 44980, '子どものプールは浅いです。', 'こどもの プールは あさい です。', 'Hồ bơi trẻ em thì nông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11351, 31331, '首が痛いです。', 'くびが いたい です。', 'Tôi bị đau cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11352, 31332, 'パソコンを使いすぎて、肩が痛いです。', 'パソコンを つかいすぎて、かたが いたい です。', 'Dùng máy tính nhiều quá nên đau vai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11353, 31311, '今日はとても暑いですね。', 'きょうは とても あつい ですね。', 'Hôm nay nóng quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11354, 44197, 'なくした鍵が見つかりました。', 'なくした かぎが みつかりました。', 'Chiếc chìa khóa bị mất đã được tìm thấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11355, 41640, '私も生身の人間だから、疲れることもある。', 'わたしも なまみの にんげん だから、つかれる ことも ある。', 'Tôi cũng là con người bằng xương bằng thịt nên cũng có lúc mệt mỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11356, 41661, '手術でおなかを切開した。', 'しゅじゅつで おなかを せっかい した。', 'Ca phẫu thuật đã rạch bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11357, 41653, '彼は努力を惜しまない。', 'かれは どりょくを おしまない。', 'Anh ấy không tiếc công sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11358, 41646, 'この酒は昔ながらの製法で作られている。', 'この さけは むかしながらの せいほうで つくられて いる。', 'Loại rượu này được làm theo phương pháp truyền thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11359, 41651, '確定申告の書類を税務署に提出した。', 'かくてい しんこくの しょるいを ぜいむしょに ていしゅつ した。', 'Tôi đã nộp hồ sơ quyết toán thuế cho cục thuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11360, 41641, 'パーティーは大いに盛り上がった。', 'パーティーは おおいに もりあがった。', 'Bữa tiệc vô cùng sôi động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11361, 41657, '電波が悪くて、話が跡切れた。', 'でんぱが わるくて、はなしが とぎれた。', 'Sóng yếu nên cuộc nói chuyện bị ngắt quãng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11362, 41663, '車同士の接触事故があった。', 'くるま どうしの せっしょく じこが あった。', 'Đã xảy ra vụ va quệt giữa hai xe ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11363, 41643, '二人の結婚式は盛大に行われた。', 'ふたりの けっこんしきは せいだいに おこなわれた。', 'Đám cưới của hai người được tổ chức hoành tráng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11364, 41652, '年を取ると骨が脆くなる。', 'としを とると ほねが もろく なる。', 'Có tuổi thì xương trở nên giòn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11365, 31317, 'この川は深いですから、泳がないでください。', 'この かわは ふかい ですから、およがないで ください。', 'Sông này sâu, đừng bơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11366, 31322, '新幹線はとても速いです。', 'しんかんせんは とても はやい です。', 'Tàu Shinkansen rất nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11367, 31335, 'ナイフで指を切りました。', 'ナイフで ゆびを きりました。', 'Tôi bị dao cắt vào ngón tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11368, 31338, '熱いお茶で舌をやけどしました。', 'あつい おちゃで したを やけど しました。', 'Tôi bị bỏng lưỡi vì trà nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11369, 37915, '姉は病院の看護師です。', 'あねは びょういんの かんごし です。', 'Chị tôi là y tá ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11370, 37917, 'かぜはもう治りました。', 'かぜは もう なおりました。', 'Cảm của tôi đã khỏi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11371, 38322, '運動の後でシャワーを浴びます。', 'うんどうの あとで シャワーを あびます。', 'Sau khi tập thể dục tôi tắm vòi sen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11372, 38338, '寒いですから、ストーブをつけましょう。', 'さむい ですから、ストーブを つけましょう。', 'Lạnh quá, bật lò sưởi lên nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11373, 38345, 'テープで箱を閉めました。', 'テープで はこを しめました。', 'Tôi dán băng dính để đóng hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11374, 38330, '母がお弁当を作ってくれました。', 'ははが おべんとうを つくって くれました。', 'Mẹ đã làm cơm hộp cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11375, 38360, '一から十まで数えてください。', 'いちから じゅうまで かぞえて ください。', 'Hãy đếm từ một đến mười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11376, 38340, '電話番号はゼロ三から始まります。', 'でんわ ばんごうは ゼロさんから はじまります。', 'Số điện thoại bắt đầu bằng 03.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11377, 38334, '水をください。', 'みずを ください。', 'Cho tôi xin nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11378, 38337, 'こんなかばんが欲しいです。', 'こんな かばんが ほしい です。', 'Tôi muốn có chiếc cặp như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11379, 38343, '昨日はたいへんお世話になりました。', 'きのうは たいへん おせわに なりました。', 'Hôm qua cảm ơn anh rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11380, 38348, 'りんごやみかんなどを買いました。', 'りんごや みかんなどを かいました。', 'Tôi đã mua táo, quýt, v.v.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11381, 41679, '大会の開会が宣言された。', 'たいかいの かいかいが せんげん された。', 'Đại hội đã được tuyên bố khai mạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11382, 41664, '「しかし」は逆接の接続詞だ。', '「しかし」は ぎゃくせつの せつぞくしだ。', '"Shikashi" là liên từ chỉ quan hệ trái ngược.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11383, 41682, 'この町は戦災で焼け野原になった。', 'この まちは せんさいで やけのはらに なった。', 'Thị trấn này bị chiến tranh thiêu thành bình địa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11384, 41692, '野菜には食物繊維が多く含まれている。', 'やさいには しょくもつ せんいが おおく ふくまれて いる。', 'Rau chứa nhiều chất xơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11385, 41673, '先だってはお世話になりました。', 'せんだっては おせわに なりました。', 'Hôm trước cảm ơn anh đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11386, 41674, '先先週の日曜日に引っ越した。', 'せんせんしゅうの にちようびに ひっこした。', 'Tôi chuyển nhà vào chủ nhật tuần trước nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11387, 41667, '会社は相談窓口を設けた。', 'かいしゃは そうだん まどぐちを もうけた。', 'Công ty đã lập quầy tư vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11388, 41670, 'この村は人通りが絶えてしまった。', 'この むらは ひとどおりが たえて しまった。', 'Ngôi làng này đã vắng bóng người qua lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11389, 41686, '煙が目に染みる。', 'けむりが めに しみる。', 'Khói làm cay mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11390, 41687, '髪を茶色に染めた。', 'かみを ちゃいろに そめた。', 'Tôi nhuộm tóc màu nâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11391, 41681, 'この駐車場は住民専用です。', 'この ちゅうしゃじょうは じゅうみん せんよう です。', 'Bãi đỗ xe này dành riêng cho cư dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11392, 41678, '宣教師が日本にキリスト教を伝えた。', 'せんきょうしが にほんに キリストきょうを つたえた。', 'Các nhà truyền giáo đã truyền đạo Cơ Đốc vào Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11393, 41694, '来月、市長の選挙がある。', 'らいげつ、しちょうの せんきょが ある。', 'Tháng sau có bầu cử thị trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11394, 41709, 'このシャツは自然の素材で作られている。', 'この シャツは しぜんの そざいで つくられて いる。', 'Chiếc áo này làm từ chất liệu tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11395, 38355, 'すみません、もう一度言ってください。', 'すみません、もう いちど いって ください。', 'Xin lỗi, hãy nói lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11396, 38342, '駅のそばに本屋があります。', 'えきの そばに ほんやが あります。', 'Bên cạnh ga có hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11397, 38361, '一月に一回、映画を見ます。', 'ひとつきに いっかい、えいがを みます。', 'Mỗi tháng tôi xem phim một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11398, 38350, '教科書の十ページを開いてください。', 'きょうかしょの じゅっページを ひらいて ください。', 'Hãy mở sách giáo khoa trang mười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11399, 38373, '戸を閉めてください。', 'とを しめて ください。', 'Hãy đóng cửa lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11400, 38374, '五時に会いましょう。', 'ごじに あいましょう。', 'Năm giờ gặp nhau nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11401, 38367, 'ここでたばこを吸ってもいいですか。', 'ここで たばこを すっても いい ですか。', 'Tôi hút thuốc ở đây được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11402, 38365, 'このお茶はぬるいです。', 'この おちゃは ぬるい です。', 'Trà này âm ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11403, 38363, '一日に三回、薬を飲みます。', 'いちにちに さんかい、くすりを のみます。', 'Một ngày tôi uống thuốc ba lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11404, 31412, '田中さんは歌が上手です。', 'たなかさんは うたが じょうず です。', 'Anh Tanaka hát hay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11405, 44199, 'この本はとても面白いです。', 'この ほんは とても おもしろい です。', 'Cuốn sách này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11406, 44201, 'これは珍しい花です。', 'これは めずらしい はな です。', 'Đây là loài hoa hiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11407, 44217, '森の中を散歩しました。', 'もりの なかを さんぽ しました。', 'Tôi đi dạo trong rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11408, 44219, '湖でボートに乗りました。', 'みずうみで ボートに のりました。', 'Tôi đi thuyền trên hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11409, 44220, 'この坂を上ると、駅があります。', 'この さかを のぼると、えきが あります。', 'Leo lên con dốc này là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11410, 44226, '夏は虫が多いです。', 'なつは むしが おおい です。', 'Mùa hè có nhiều côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11411, 44242, '燃えるごみは火曜日に出してください。', 'もえる ごみは かようびに だして ください。', 'Rác cháy được hãy đổ vào thứ Ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11412, 41701, '彼は善良な市民だ。', 'かれは ぜんりょうな しみんだ。', 'Ông ấy là một công dân lương thiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11413, 41708, '彼女の返事は素っ気なかった。', 'かのじょの へんじは そっけなかった。', 'Câu trả lời của cô ấy thật lạnh nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11414, 41699, 'コンサートのチケットを前売りで買った。', 'コンサートの チケットを まえうりで かった。', 'Tôi đã mua vé hòa nhạc bán trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11415, 41714, '住民の訴えが裁判所に認められた。', 'じゅうみんの うったえが さいばんしょに みとめられた。', 'Đơn kiện của cư dân đã được tòa án chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11416, 41724, '自転車を漕いで学校へ行く。', 'じてんしゃを こいで がっこうへ いく。', 'Tôi đạp xe đến trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11417, 41705, '寒さで畑の野菜が全滅した。', 'さむさで はたけの やさいが ぜんめつ した。', 'Vì giá rét, rau ngoài ruộng chết sạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11418, 41712, '色を組み合わせて服を選ぶ。', 'いろを くみあわせて ふくを えらぶ。', 'Phối màu để chọn quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11419, 41715, '大雪が行く手を阻んだ。', 'おおゆきが ゆくてを はばんだ。', 'Tuyết lớn đã cản đường đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11420, 44250, '夜空に星が光っています。', 'よぞらに ほしが ひかって います。', 'Sao đang tỏa sáng trên bầu trời đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11421, 44252, '紙はよく燃えます。', 'かみは よく もえます。', 'Giấy dễ cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11422, 44253, '外国人の観光客が増えています。', 'がいこくじんの かんこうきゃくが ふえて います。', 'Khách du lịch nước ngoài đang tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11423, 44256, '雨の日が続いています。', 'あめの ひが つづいて います。', 'Những ngày mưa vẫn kéo dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11424, 44261, '富士山は美しい山です。', 'ふじさんは うつくしい やま です。', 'Núi Phú Sĩ là ngọn núi đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11425, 44265, '野菜を細かく切ってください。', 'やさいを こまかく きって ください。', 'Hãy thái nhỏ rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11426, 44266, 'これは貴重な経験でした。', 'これは きちょうな けいけん でした。', 'Đây là một trải nghiệm quý giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11427, 44278, '親に心配をかけたくないです。', 'おやに しんぱいを かけたく ない です。', 'Tôi không muốn làm cha mẹ lo lắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11428, 44280, '後輩の面倒を見ています。', 'こうはいの めんどうを みて います。', 'Tôi đang kèm cặp đàn em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11429, 44282, 'お世話になった先生にお礼を言いました。', 'おせわに なった せんせいに おれいを いいました。', 'Tôi nói lời cảm ơn thầy đã giúp đỡ mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11430, 44286, '失敗しても、また頑張りましょう。', 'しっぱい しても、また がんばりましょう。', 'Dù thất bại cũng hãy cố gắng lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11431, 44291, '自己紹介をしてください。', 'じこ しょうかいを して ください。', 'Hãy tự giới thiệu bản thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11432, 44294, '赤ちゃんが笑っています。', 'あかちゃんが わらって います。', 'Em bé đang cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11433, 44296, '母はプレゼントをとても喜びました。', 'ははは プレゼントを とても よろこびました。', 'Mẹ rất vui với món quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11434, 44298, '友達が亡くなって、みんな悲しんでいます。', 'ともだちが なくなって、みんな かなしんで います。', 'Người bạn qua đời, mọi người đều đau buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11435, 44300, '子どもを叱りました。', 'こどもを しかりました。', 'Tôi đã mắng con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11436, 44301, '彼の話を信じています。', 'かれの はなしを しんじて います。', 'Tôi tin lời anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11437, 44302, '子どものころを思い出しました。', 'こどもの ころを おもいだしました。', 'Tôi nhớ lại thời thơ ấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11438, 44306, '彼女と別れました。', 'かのじょと わかれました。', 'Tôi đã chia tay bạn gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11439, 44307, '二人は三年付き合っています。', 'ふたりは さんねん つきあって います。', 'Hai người đã hẹn hò ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11440, 44310, '一人で住んでいるので、寂しいです。', 'ひとりで すんで いるので、さびしい です。', 'Sống một mình nên tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11441, 44311, 'みんなの前で歌うのは恥ずかしいです。', 'みんなの まえで うたうのは はずかしい です。', 'Hát trước mặt mọi người thật xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11442, 44315, '毎日勉強して、偉いですね。', 'まいにち べんきょう して、えらい ですね。', 'Ngày nào cũng học, giỏi quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11443, 41739, '憎しみからは何も生まれない。', 'にくしみからは なにも うまれない。', 'Từ hận thù chẳng sinh ra được điều gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11444, 41779, '夏休みが待ち遠しい。', 'なつやすみが まちどおしい。', 'Tôi nóng lòng chờ kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11445, 41726, 'この辺りの家賃の相場はいくらぐらいですか。', 'この あたりの やちんの そうばは いくら ぐらい ですか。', 'Giá thuê nhà quanh đây khoảng bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11446, 41734, '毎月国の家族に送金している。', 'まいつき くにの かぞくに そうきん して いる。', 'Hằng tháng tôi chuyển tiền cho gia đình ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11447, 41747, '子供が足し算を覚えた。', 'こどもが たしざんを おぼえた。', 'Con tôi đã biết làm phép cộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11448, 44317, '彼は真面目な学生です。', 'かれは まじめな がくせい です。', 'Cậu ấy là học sinh chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11449, 44320, '家族と一緒にいられて幸せです。', 'かぞくと いっしょに いられて しあわせ です。', 'Được ở bên gia đình, tôi thấy hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11450, 44328, '本当にありがとうございました。', 'ほんとうに ありがとう ございました。', 'Thật sự cảm ơn anh rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11451, 44334, 'スキーで怪我をしました。', 'スキーで けがを しました。', 'Tôi bị thương khi trượt tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11452, 44336, '退院の日が決まりました。', 'たいいんの ひが きまりました。', 'Ngày xuất viện đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11453, 44343, '重い荷物を持って、腕が痛いです。', 'おもい にもつを もって、うでが いたい です。', 'Mang đồ nặng nên tôi đau tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11454, 44355, '晩ご飯の後で散歩をします。', 'ばんごはんの あとで さんぽを します。', 'Sau bữa tối tôi đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11455, 44359, '最近、少し太りました。', 'さいきん、すこし ふとりました。', 'Gần đây tôi hơi béo lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11456, 44371, '車に気をつけてください。', 'くるまに きを つけて ください。', 'Hãy cẩn thận xe cộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11457, 44375, '昨日遅く寝たので、眠いです。', 'きのう おそく ねたので、ねむい です。', 'Hôm qua ngủ muộn nên tôi buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11458, 44380, '無理をしないでください。', 'むりを しないで ください。', 'Đừng làm quá sức nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11459, 44390, 'この会社には社員が百人います。', 'この かいしゃには しゃいんが ひゃくにん います。', 'Công ty này có một trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11460, 41406, 'ごみの収集は月曜日です。', 'ごみの しゅうしゅうは げつようび です。', 'Rác được thu gom vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11461, 44410, '今週は毎日残業があります。', 'こんしゅうは まいにち ざんぎょうが あります。', 'Tuần này ngày nào cũng phải làm thêm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11462, 44430, 'インターネットで電車の時間を調べました。', 'インターネットで でんしゃの じかんを しらべました。', 'Tôi tra giờ tàu trên Internet.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11463, 44432, '先生によろしく伝えてください。', 'せんせいに よろしく つたえて ください。', 'Cho tôi gửi lời hỏi thăm thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11464, 44435, '友達を駅まで送りました。', 'ともだちを えきまで おくりました。', 'Tôi tiễn bạn ra ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11465, 44437, '走ったので、電車に間に合いました。', 'はしったので、でんしゃに まにあいました。', 'Nhờ chạy mà tôi kịp tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11466, 44439, '毎日運動を続けています。', 'まいにち うんどうを つづけて います。', 'Tôi duy trì tập thể dục mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11467, 41894, '医者は聴診器で胸の音を聞いた。', 'いしゃは ちょうしんきで むねの おとを きいた。', 'Bác sĩ dùng ống nghe nghe tiếng ngực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11468, 41879, '友人の忠告を無視して失敗した。', 'ゆうじんの ちゅうこくを むし して しっぱい した。', 'Tôi phớt lờ lời khuyên của bạn và đã thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11469, 41837, 'この本は一読の値がある。', 'この ほんは いちどくの あたいが ある。', 'Cuốn sách này đáng đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11470, 41836, '木の幹の断面に年輪が見える。', 'きの みきの だんめんに ねんりんが みえる。', 'Trên mặt cắt thân cây có thể thấy vòng gỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11471, 41899, '警察庁の長官が記者会見をした。', 'けいさつちょうの ちょうかんが きしゃ かいけんを した。', 'Cục trưởng Cục cảnh sát đã họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11472, 41882, '父は一家の柱として働いている。', 'ちちは いっかの はしらと して はたらいて いる。', 'Bố tôi làm việc với tư cách trụ cột gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11473, 41891, '朝寝坊して、電車に乗り遅れた。', 'あさねぼう して、でんしゃに のりおくれた。', 'Tôi ngủ nướng nên lỡ chuyến tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11474, 41885, '私の家は三丁目にある。', 'わたしの いえは さんちょうめに ある。', 'Nhà tôi ở khu phố số ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11475, 44441, '古い切手を集めています。', 'ふるい きってを あつめて います。', 'Tôi đang sưu tầm tem cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11476, 44443, 'これは大事な書類です。', 'これは だいじな しょるい です。', 'Đây là tài liệu quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11477, 44445, 'この料理は簡単に作れます。', 'この りょうりは かんたんに つくれます。', 'Món này có thể nấu đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11478, 44447, '父はとても厳しいです。', 'ちちは とても きびしい です。', 'Bố tôi rất nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11479, 44490, '弟がおもちゃを壊しました。', 'おとうとが おもちゃを こわしました。', 'Em trai tôi làm hỏng đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11480, 44492, 'コップが落ちて割れました。', 'コップが おちて われました。', 'Cái cốc rơi xuống vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11481, 44493, '電車の中で財布を落としました。', 'でんしゃの なかで さいふを おとしました。', 'Tôi đánh rơi ví trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11482, 44496, '店の前に人が並んでいます。', 'みせの まえに ひとが ならんで います。', 'Trước cửa hàng người ta đang xếp hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11483, 44498, '封筒に切手を貼りました。', 'ふうとうに きってを はりました。', 'Tôi dán tem lên phong bì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11484, 44500, '日本の生活に慣れました。', 'にほんの せいかつに なれました。', 'Tôi đã quen với cuộc sống ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11485, 44501, '道がわからなくて困りました。', 'みちが わからなくて こまりました。', 'Không biết đường nên tôi bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11486, 44503, '駅から遠くて不便です。', 'えきから とおくて ふべん です。', 'Xa ga nên bất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11487, 44505, '適当な大きさに切ってください。', 'てきとうな おおきさに きって ください。', 'Hãy cắt với kích cỡ thích hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11488, 44550, '試合に負けて、悔しかったです。', 'しあいに まけて、くやしかった です。', 'Thua trận nên tôi rất tiếc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11489, 44554, '友達を食事に誘いました。', 'ともだちを しょくじに さそいました。', 'Tôi rủ bạn đi ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11490, 44557, 'なくした鍵が見つかりました。', 'なくした かぎが みつかりました。', 'Chiếc chìa khóa bị mất đã được tìm thấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11491, 44559, 'この本はとても面白いです。', 'この ほんは とても おもしろい です。', 'Cuốn sách này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11492, 44561, 'これは珍しい花です。', 'これは めずらしい はな です。', 'Đây là loài hoa hiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11493, 44563, '素敵なプレゼントをありがとう。', 'すてきな プレゼントを ありがとう。', 'Cảm ơn món quà tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11494, 44565, '私は料理が得意です。', 'わたしは りょうりが とくい です。', 'Tôi giỏi nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11495, 44578, '家の後ろに林があります。', 'いえの うしろに はやしが あります。', 'Phía sau nhà có một khu rừng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11496, 44580, 'この坂を上ると、駅があります。', 'この さかを のぼると、えきが あります。', 'Leo lên con dốc này là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11497, 44583, '庭の草を取りました。', 'にわの くさを とりました。', 'Tôi nhổ cỏ trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11498, 41918, '重い物を持って腰を痛めた。', 'おもい ものを もって こしを いためた。', 'Bê đồ nặng nên tôi bị đau lưng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11499, 41920, '平和の大切さを痛切に感じた。', 'へいわの たいせつさを つうせつに かんじた。', 'Tôi thấm thía tầm quan trọng của hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11500, 41914, '野党は大臣の責任を追及した。', 'やとうは だいじんの せきにんを ついきゅう した。', 'Phe đối lập đã truy cứu trách nhiệm của bộ trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11501, 41925, '床の間に古い壷が飾ってある。', 'とこのまに ふるい つぼが かざって ある。', 'Trong hốc tokonoma có trưng một chiếc bình cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11502, 41926, '揺れるので、吊り革におつかまりください。', 'ゆれるので、つりかわに おつかまり ください。', 'Tàu rung lắc, xin hãy bám vào tay vịn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11503, 41923, '通常は九時に開店します。', 'つうじょうは くじに かいてん します。', 'Thông thường cửa hàng mở lúc chín giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11504, 44602, '燃えるごみは火曜日に出してください。', 'もえる ごみは かようびに だして ください。', 'Rác cháy được hãy đổ vào thứ Ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11505, 44609, '地震で家が揺れました。', 'じしんで いえが ゆれました。', 'Động đất làm ngôi nhà rung lắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11506, 44610, '夜空に星が光っています。', 'よぞらに ほしが ひかって います。', 'Sao đang tỏa sáng trên bầu trời đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11507, 44612, '紙はよく燃えます。', 'かみは よく もえます。', 'Giấy dễ cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11508, 44613, '外国人の観光客が増えています。', 'がいこくじんの かんこうきゃくが ふえて います。', 'Khách du lịch nước ngoài đang tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11509, 44615, '町の様子がずいぶん変わりました。', 'まちの ようすが ずいぶん かわりました。', 'Diện mạo thị trấn đã thay đổi nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11510, 44618, '服を汚さないように気をつけてください。', 'ふくを よごさない ように きを つけて ください。', 'Hãy cẩn thận đừng làm bẩn quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11511, 44624, 'この肉は硬いです。', 'この にくは かたい です。', 'Thịt này dai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11512, 44626, 'これは貴重な経験でした。', 'これは きちょうな けいけん でした。', 'Đây là một trải nghiệm quý giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11513, 44639, '会社の先輩に仕事を教えてもらいました。', 'かいしゃの せんぱいに しごとを おしえて もらいました。', 'Tôi được đàn anh ở công ty chỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11514, 44641, '駅で知り合いに会いました。', 'えきで しりあいに あいました。', 'Tôi gặp người quen ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11555, 41981, '川の土手を散歩した。', 'かわの どてを さんぽ した。', 'Tôi đi dạo trên bờ đê sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11515, 44642, 'お世話になった先生にお礼を言いました。', 'おせわに なった せんせいに おれいを いいました。', 'Tôi nói lời cảm ơn thầy đã giúp đỡ mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11516, 44646, '失敗しても、また頑張りましょう。', 'しっぱい しても、また がんばりましょう。', 'Dù thất bại cũng hãy cố gắng lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11517, 44651, '自己紹介をしてください。', 'じこ しょうかいを して ください。', 'Hãy tự giới thiệu bản thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11518, 44655, '映画を見て、泣きました。', 'えいがを みて、なきました。', 'Xem phim xong tôi đã khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11519, 44656, '母はプレゼントをとても喜びました。', 'ははは プレゼントを とても よろこびました。', 'Mẹ rất vui với món quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11520, 44657, 'ニュースを聞いて驚きました。', 'ニュースを きいて おどろきました。', 'Nghe tin tôi đã rất ngạc nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11521, 41938, '彼はなかなか諦めがつかない。', 'かれは なかなか あきらめが つかない。', 'Anh ấy mãi không chịu từ bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11522, 41937, '記事の誤りを訂正した。', 'きじの あやまりを ていせい した。', 'Đã đính chính sai sót trong bài báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11523, 41956, '会議の纏めを作成した。', 'かいぎの まとめを さくせい した。', 'Tôi soạn bản tổng kết cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11524, 41933, '父は来年定年を迎える。', 'ちちは らいねん ていねんを むかえる。', 'Năm sau bố tôi đến tuổi nghỉ hưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11525, 41931, '法律で定められた手続きに従う。', 'ほうりつで さだめられた てつづきに したがう。', 'Tuân theo thủ tục do luật quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11526, 41936, '梯子を使って屋根に上った。', 'はしごを つかって やねに のぼった。', 'Tôi dùng thang leo lên mái nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11527, 41959, '転居先の住所を知らせてください。', 'てんきょさきの じゅうしょを しらせて ください。', 'Xin hãy báo địa chỉ nơi chuyển đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11528, 41951, '古い歌に天地の神々が詠まれている。', 'ふるい うたに あめつちの かみがみが よまれて いる。', 'Thần linh trời đất được ca ngợi trong những bài ca cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11529, 41940, '臭いので、鼻を摘んだ。', 'くさいので、はなを つまんだ。', 'Hôi quá nên tôi bịt mũi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11530, 41954, 'プレゼントに手紙を添えた。', 'プレゼントに てがみを そえた。', 'Tôi kèm lá thư vào món quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11531, 44658, '友達が亡くなって、みんな悲しんでいます。', 'ともだちが なくなって、みんな かなしんで います。', 'Người bạn qua đời, mọi người đều đau buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11532, 44661, '彼の話を信じています。', 'かれの はなしを しんじて います。', 'Tôi tin lời anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11533, 44664, '試験に合格できるように頑張ります。', 'しけんに ごうかく できる ように がんばります。', 'Tôi sẽ cố gắng để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11534, 44666, '彼女と別れました。', 'かのじょと わかれました。', 'Tôi đã chia tay bạn gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11535, 44668, '合格して、とても嬉しいです。', 'ごうかく して、とても うれしい です。', 'Thi đỗ nên tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11536, 44670, '一人で住んでいるので、寂しいです。', 'ひとりで すんで いるので、さびしい です。', 'Sống một mình nên tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11537, 44673, '夜一人で歩くのは怖いです。', 'よる ひとりで あるくのは こわい です。', 'Đi bộ một mình ban đêm thật đáng sợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11538, 44676, 'パーティーに行けなくて残念です。', 'パーティーに いけなくて ざんねん です。', 'Tiếc quá vì không đi dự tiệc được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11539, 44679, '仕事が多くて大変です。', 'しごとが おおくて たいへん です。', 'Công việc nhiều nên vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11540, 44688, '本当にありがとうございました。', 'ほんとうに ありがとう ございました。', 'Thật sự cảm ơn anh rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11541, 44694, 'スキーで怪我をしました。', 'スキーで けがを しました。', 'Tôi bị thương khi trượt tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11542, 44703, '重い荷物を持って、腕が痛いです。', 'おもい にもつを もって、うでが いたい です。', 'Mang đồ nặng nên tôi đau tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11543, 44716, '今晩一緒に食事をしませんか。', 'こんばん いっしょに しょくじを しませんか。', 'Tối nay cùng đi ăn không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11544, 44721, '薬を飲んだら、すぐ治りました。', 'くすりを のんだら、すぐ なおりました。', 'Uống thuốc xong là khỏi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11545, 44723, '強い風で木が倒れました。', 'つよい かぜで きが たおれました。', 'Gió mạnh làm đổ cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11546, 44725, '長い時間歩いて、疲れました。', 'ながい じかん あるいて、つかれました。', 'Đi bộ lâu nên tôi mệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11547, 44727, '咳が止まらないので、病院へ行きました。', 'せきが とまらないので、びょういんへ いきました。', 'Ho mãi không dứt nên tôi đi bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11548, 41985, '国民は政府の対応に怒っている。', 'こくみんは せいふの たいおうに いかって いる。', 'Người dân phẫn nộ trước cách ứng phó của chính phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11549, 41983, '兄は土木の仕事をしている。', 'あには どぼくの しごとを して いる。', 'Anh tôi làm nghề xây dựng công trình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11550, 41975, '子供たちは毎朝八時に登校する。', 'こどもたちは まいあさ はちじに とうこう する。', 'Bọn trẻ đến trường lúc tám giờ mỗi sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11551, 41990, '彼は盗みを働いて捕まった。', 'かれは ぬすみを はたらいて つかまった。', 'Hắn ăn trộm và bị bắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11552, 41991, '遠くに村の灯が見えた。', 'とおくに むらの ともしびが みえた。', 'Xa xa đã thấy ánh đèn của làng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11553, 41976, 'この国はまだ発展の途上にある。', 'この くには まだ はってんの とじょうに ある。', 'Đất nước này vẫn đang trên đà phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11554, 41989, '昔の都の人は関東を東と呼んだ。', 'むかしの みやこの ひとは かんとうを あずまと よんだ。', 'Người kinh đô xưa gọi vùng Kanto là Azuma.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11556, 41977, '彼からの連絡が途絶えた。', 'かれからの れんらくが とだえた。', 'Liên lạc từ anh ấy đã bặt tăm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11557, 41982, '力士が土俵に上がった。', 'りきしが どひょうに あがった。', 'Võ sĩ sumo bước lên sàn đấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11558, 41978, '努めて冷静に話そうとした。', 'つとめて れいせいに はなそうと した。', 'Tôi cố hết sức để nói một cách bình tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11559, 44728, '気分が悪くて、吐いてしまいました。', 'きぶんが わるくて、はいて しまいました。', 'Thấy khó chịu nên tôi đã nôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11560, 44731, '車に気をつけてください。', 'くるまに きを つけて ください。', 'Hãy cẩn thận xe cộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11561, 44736, '熱があって、体がだるいです。', 'ねつが あって、からだが だるい です。', 'Tôi bị sốt nên người uể oải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11562, 44740, '無理をしないでください。', 'むりを しないで ください。', 'Đừng làm quá sức nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11563, 44745, 'なるべく早く来てください。', 'なるべく はやく きて ください。', 'Hãy đến sớm nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11564, 44750, 'この会社には社員が百人います。', 'この かいしゃには しゃいんが ひゃくにん います。', 'Công ty này có một trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11565, 44765, '仕事のことで先輩に相談しました。', 'しごとの ことで せんぱいに そうだん しました。', 'Tôi xin ý kiến đàn anh về công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11566, 44770, '今週は毎日残業があります。', 'こんしゅうは まいにち ざんぎょうが あります。', 'Tuần này ngày nào cũng phải làm thêm giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11567, 44840, 'ここにごみを捨てないでください。', 'ここに ごみを すてないで ください。', 'Xin đừng vứt rác ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11568, 44843, 'お湯が沸きました。', 'おゆが わきました。', 'Nước đã sôi rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11569, 44845, '野菜と肉を煮てスープを作りました。', 'やさいと にくを にて スープを つくりました。', 'Tôi ninh rau với thịt để nấu súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11570, 44847, 'スープを温めてください。', 'スープを あたためて ください。', 'Hãy hâm nóng súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11571, 44849, 'テレビが壊れてしまいました。', 'テレビが こわれて しまいました。', 'Tivi bị hỏng mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11572, 44851, '壊れた時計を直しました。', 'こわれた とけいを なおしました。', 'Tôi đã sửa chiếc đồng hồ hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11573, 44853, '電車の中で財布を落としました。', 'でんしゃの なかで さいふを おとしました。', 'Tôi đánh rơi ví trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11574, 44855, '本を棚に並べました。', 'ほんを たなに ならべました。', 'Tôi xếp sách lên giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11575, 42016, '結婚後は両親と同居している。', 'けっこんごは りょうしんと どうきょ して いる。', 'Sau khi cưới tôi sống chung với bố mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11576, 42022, 'パリは私の憧れの町だ。', 'パリは わたしの あこがれの まちだ。', 'Paris là thành phố mơ ước của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11577, 42001, '調査結果を踏まえて、計画を見直した。', 'ちょうさ けっかを ふまえて、けいかくを みなおした。', 'Dựa trên kết quả khảo sát, chúng tôi đã xem lại kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11578, 42015, '彼とは中学の同級生だ。', 'かれとは ちゅうがくの どうきゅうせいだ。', 'Tôi và anh ấy là bạn cùng lớp cấp hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11579, 42005, '犯人は車で逃走した。', 'はんにんは くるまで とうそう した。', 'Thủ phạm đã bỏ trốn bằng ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11580, 42006, '彼は海外へ逃亡した。', 'かれは かいがいへ とうぼう した。', 'Hắn đã đào tẩu ra nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11581, 42019, '両国は軍事同盟を結んだ。', 'りょうこくは ぐんじ どうめいを むすんだ。', 'Hai nước đã ký kết liên minh quân sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11582, 41995, '肉は品質によって等級が付けられる。', 'にくは ひんしつに よって とうきゅうが つけられる。', 'Thịt được xếp hạng theo chất lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11583, 41999, '口の中で蕩けるようなチョコレートだ。', 'くちの なかで とろける ような チョコレートだ。', 'Sô cô la như tan chảy trong miệng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11584, 42003, 'せっかくのチャンスを逃した。', 'せっかくの チャンスを のがした。', 'Tôi đã để vuột mất cơ hội hiếm có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11585, 42008, '市場の動きを注意深く見ている。', 'しじょうの うごきを ちゅうい ぶかく みて いる。', 'Tôi đang theo dõi kỹ diễn biến thị trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11586, 42031, '弟がテレビを独占している。', 'おとうとが テレビを どくせん して いる。', 'Em trai tôi độc chiếm cái tivi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11587, 42033, 'この雑誌は若い読者に人気がある。', 'この ざっしは わかい どくしゃに にんきが ある。', 'Tạp chí này được độc giả trẻ yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11588, 44857, 'ここに車を止めてもいいですか。', 'ここに くるまを とめても いい ですか。', 'Tôi đỗ xe ở đây được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11589, 44859, 'プレゼントを紙で包みました。', 'プレゼントを かみで つつみました。', 'Tôi gói quà bằng giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11590, 44861, '道がわからなくて困りました。', 'みちが わからなくて こまりました。', 'Không biết đường nên tôi bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11591, 44863, '駅から遠くて不便です。', 'えきから とおくて ふべん です。', 'Xa ga nên bất tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11592, 44865, '適当な大きさに切ってください。', 'てきとうな おおきさに きって ください。', 'Hãy cắt với kích cỡ thích hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11593, 41841, '駅で知り合いに会いました。', 'えきで しりあいに あいました。', 'Tôi gặp người quen ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11594, 44900, 'ごみの収集は月曜日です。', 'ごみの しゅうしゅうは げつようび です。', 'Rác được thu gom vào thứ Hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11595, 44903, 'パーティーでみんなで踊りました。', 'パーティーで みんなで おどりました。', 'Ở bữa tiệc mọi người cùng nhảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11596, 44906, '子どもが絵を描いています。', 'こどもが えを かいて います。', 'Đứa trẻ đang vẽ tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11597, 44910, '試合に負けて、悔しかったです。', 'しあいに まけて、くやしかった です。', 'Thua trận nên tôi rất tiếc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11598, 44914, '友達を食事に誘いました。', 'ともだちを しょくじに さそいました。', 'Tôi rủ bạn đi ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11599, 44917, 'なくした鍵が見つかりました。', 'なくした かぎが みつかりました。', 'Chiếc chìa khóa bị mất đã được tìm thấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11600, 44919, 'この本はとても面白いです。', 'この ほんは とても おもしろい です。', 'Cuốn sách này rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11601, 44921, 'これは珍しい花です。', 'これは めずらしい はな です。', 'Đây là loài hoa hiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11602, 42042, '検査で内臓に異常は見つからなかった。', 'けんさで ないぞうに いじょうは みつからなかった。', 'Kiểm tra không phát hiện bất thường ở nội tạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11603, 42047, '初対面なのに、彼は馴れ馴れしかった。', 'しょたいめん なのに、かれは なれなれしかった。', 'Mới gặp lần đầu mà anh ta đã quá suồng sã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11604, 42025, '彼は新しい技術の特許を取った。', 'かれは あたらしい ぎじゅつの とっきょを とった。', 'Anh ấy đã lấy bằng sáng chế cho công nghệ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11605, 42044, '費用の内訳を教えてください。', 'ひようの うちわけを おしえて ください。', 'Hãy cho tôi biết chi tiết các khoản chi phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11606, 42045, 'その国では内乱が続いている。', 'その くにでは ないらんが つづいて いる。', 'Ở nước đó nội chiến vẫn tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11607, 42027, 'りんごはこの県の特産だ。', 'りんごは この けんの とくさんだ。', 'Táo là đặc sản của tỉnh này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11608, 42035, '彼は最後まで自分の意見を突っ張った。', 'かれは さいごまで じぶんの いけんを つっぱった。', 'Anh ta khăng khăng giữ ý kiến đến cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11609, 42037, '難関を突破して合格した。', 'なんかんを とっぱ して ごうかく した。', 'Tôi vượt qua cửa ải khó khăn và thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11610, 42049, '週末の商店街は買い物客で賑わう。', 'しゅうまつの しょうてんがいは かいものきゃくで にぎわう。', 'Phố mua sắm cuối tuần nhộn nhịp người mua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11611, 42028, '今月の雑誌は京都の特集だ。', 'こんげつの ざっしは きょうとの とくしゅうだ。', 'Tạp chí tháng này có chuyên đề về Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11612, 42043, '情報が内部から漏れた。', 'じょうほうが ないぶから もれた。', 'Thông tin bị rò rỉ từ nội bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11613, 44922, '山の上からの景色は素晴らしかったです。', 'やまの うえからの けしきは すばらしかった です。', 'Phong cảnh từ trên núi thật tuyệt vời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11614, 44926, '私は数学が苦手です。', 'わたしは すうがくが にがて です。', 'Tôi kém môn toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11615, 44937, '森の中を散歩しました。', 'もりの なかを さんぽ しました。', 'Tôi đi dạo trong rừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11616, 44938, '家の後ろに林があります。', 'いえの うしろに はやしが あります。', 'Phía sau nhà có một khu rừng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11617, 44940, 'この坂を上ると、駅があります。', 'この さかを のぼると、えきが あります。', 'Leo lên con dốc này là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11618, 44946, '夏は虫が多いです。', 'なつは むしが おおい です。', 'Mùa hè có nhiều côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11619, 44964, '春になると、桜が咲きます。', 'はるに なると、さくらが さきます。', 'Sang xuân hoa anh đào nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11620, 44999, '会社の先輩に仕事を教えてもらいました。', 'かいしゃの せんぱいに しごとを おしえて もらいました。', 'Tôi được đàn anh ở công ty chỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11621, 45001, '駅で知り合いに会いました。', 'えきで しりあいに あいました。', 'Tôi gặp người quen ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11622, 45004, '朝、近所の人に挨拶をします。', 'あさ、きんじょの ひとに あいさつを します。', 'Buổi sáng tôi chào hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11623, 45006, '失敗しても、また頑張りましょう。', 'しっぱい しても、また がんばりましょう。', 'Dù thất bại cũng hãy cố gắng lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11624, 45013, '遅刻して、先生に怒られました。', 'ちこく して、せんせいに おこられました。', 'Đi muộn nên tôi bị thầy mắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11625, 45015, '映画を見て、泣きました。', 'えいがを みて、なきました。', 'Xem phim xong tôi đã khóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11626, 45017, 'ニュースを聞いて驚きました。', 'ニュースを きいて おどろきました。', 'Nghe tin tôi đã rất ngạc nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11627, 45018, '友達が亡くなって、みんな悲しんでいます。', 'ともだちが なくなって、みんな かなしんで います。', 'Người bạn qua đời, mọi người đều đau buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11628, 42057, '海で日焼けして、肌が痛い。', 'うみで ひやけ して、はだが いたい。', 'Đi biển bị cháy nắng nên da đau rát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11629, 42069, '姉が妊娠したと聞いて、うれしかった。', 'あねが にんしん したと きいて、うれしかった。', 'Nghe tin chị mang thai, tôi rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11630, 42058, 'アルバイトの日当は一万円だ。', 'アルバイトの にっとうは いちまんえんだ。', 'Tiền công làm thêm mỗi ngày là mười nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11631, 42066, 'この件はあなたに任します。', 'この けんは あなたに まかします。', 'Việc này tôi giao cho anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11632, 42068, '彼は新しい大使に任命された。', 'かれは あたらしい たいしに にんめい された。', 'Ông ấy được bổ nhiệm làm đại sứ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11633, 42076, '弟は小学三年生だ。', 'おとうとは しょうがく さんねんせいだ。', 'Em trai tôi học lớp ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11634, 42072, '熱湯を注いで三分待つ。', 'ねっとうを そそいで さんぷん まつ。', 'Rót nước sôi vào rồi đợi ba phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11635, 42060, '入口で切符を見せてください。', 'いりくちで きっぷを みせて ください。', 'Hãy xuất trình vé ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11636, 42052, '忙しい日々を送っている。', 'いそがしい ひびを おくって いる。', 'Tôi đang sống những ngày bận rộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11637, 42056, '結婚式の日取りが決まった。', 'けっこんしきの ひどりが きまった。', 'Ngày cưới đã được ấn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11638, 42074, '二〇一九年に年号が令和に変わった。', 'にせんじゅうきゅうねんに ねんごうが れいわに かわった。', 'Năm 2019 niên hiệu đổi thành Reiwa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11639, 42062, '書道のコンクールで入賞した。', 'しょどうの コンクールで にゅうしょう した。', 'Tôi đoạt giải trong cuộc thi thư pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11640, 42091, '姉は派遣社員として働いている。', 'あねは はけん しゃいんと して はたらいて いる。', 'Chị tôi làm việc với tư cách nhân viên phái cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11641, 42092, '戦争で町が破壊された。', 'せんそうで まちが はかい された。', 'Thị trấn bị chiến tranh phá hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11642, 45020, '子どもを叱りました。', 'こどもを しかりました。', 'Tôi đã mắng con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11643, 45022, '子どものころを思い出しました。', 'こどもの ころを おもいだしました。', 'Tôi nhớ lại thời thơ ấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11644, 45025, '駅で友達を迎えました。', 'えきで ともだちを むかえました。', 'Tôi đón bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11645, 45027, '二人は三年付き合っています。', 'ふたりは さんねん つきあって います。', 'Hai người đã hẹn hò ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11646, 45029, '友達が国へ帰って、悲しいです。', 'ともだちが くにへ かえって、かなしい です。', 'Bạn về nước nên tôi buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11647, 45031, 'みんなの前で歌うのは恥ずかしいです。', 'みんなの まえで うたうのは はずかしい です。', 'Hát trước mặt mọi người thật xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11648, 45035, '毎日勉強して、偉いですね。', 'まいにち べんきょう して、えらい ですね。', 'Ngày nào cũng học, giỏi quá nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11649, 45036, 'パーティーに行けなくて残念です。', 'パーティーに いけなくて ざんねん です。', 'Tiếc quá vì không đi dự tiệc được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11650, 45039, '仕事が多くて大変です。', 'しごとが おおくて たいへん です。', 'Công việc nhiều nên vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11651, 45042, '人の前でそんなことを言うのは失礼です。', 'ひとの まえで そんな ことを いうのは しつれい です。', 'Nói như thế trước mặt người khác là thất lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11652, 45048, '本当にありがとうございました。', 'ほんとうに ありがとう ございました。', 'Thật sự cảm ơn anh rất nhiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11653, 29520, '今、お忙しいですか。ちょっと聞きたいことがあるんですが。', 'いま、おいそがしい ですか。ちょっと ききたい ことが あるん ですが。', 'Bây giờ anh có bận không? Tôi có chuyện muốn hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11654, 29523, 'A：ここに座ってもいいですか。B：ええ、かまいません。', 'エー：ここに すわっても いい ですか。ビー：ええ、かまいません。', 'A: Tôi ngồi đây được không? B: Vâng, không sao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11655, 42085, 'どちらを選ぶか、悩ましい問題だ。', 'どちらを えらぶか、なやましい もんだいだ。', 'Chọn bên nào thật là vấn đề nan giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11656, 42079, '念のため、もう一度確認してください。', 'ねんの ため、もう いちど かくにん して ください。', 'Để chắc chắn, hãy kiểm tra lại một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11657, 42087, '授業料を期日までに納入してください。', 'じゅぎょうりょうを きじつまでに のうにゅう して ください。', 'Hãy nộp học phí trước hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11658, 42089, '北海道の農場で働いたことがある。', 'ほっかいどうの のうじょうで はたらいた ことが ある。', 'Tôi từng làm việc ở một nông trại tại Hokkaido.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11659, 42108, '机の配置を変えた。', 'つくえの はいちを かえた。', 'Tôi đã thay đổi cách bố trí bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11660, 42110, '予算の配分を見直す。', 'よさんの はいぶんを みなおす。', 'Xem xét lại việc phân bổ ngân sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11661, 42093, '相手が契約を一方的に破棄した。', 'あいてが けいやくを いっぽうてきに はき した。', 'Phía đối tác đã đơn phương hủy hợp đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11662, 42103, '新郎新婦が杯を交わした。', 'しんろう しんぷが さかずきを かわした。', 'Cô dâu chú rể trao chén rượu cho nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11663, 42080, 'ネクタイが捻じれている。', 'ネクタイが ねじれて いる。', 'Cà vạt bị xoắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11664, 42095, '寒さで水道管が破裂した。', 'さむさで すいどうかんが はれつ した。', 'Do giá rét, ống nước bị nứt vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11665, 42099, '期限切れの食品を廃棄した。', 'きげんぎれの しょくひんを はいき した。', 'Đã tiêu hủy thực phẩm hết hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11666, 42129, '夜中に地震が発生した。', 'よなかに じしんが はっせい した。', 'Nửa đêm đã xảy ra động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11667, 29535, '国へ帰る前に、再入国ビザを取りました。', 'くにへ かえる まえに、さいにゅうこく ビザを とりました。', 'Trước khi về nước tôi đã xin visa tái nhập cảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11668, 29545, '母の働く姿を見て育ちました。', 'ははの はたらく すがたを みて そだちました。', 'Tôi lớn lên khi nhìn hình ảnh mẹ làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11669, 29527, '八十パーセントの人が賛成しました。', 'はちじゅっ パーセントの ひとが さんせい しました。', '80% số người đã tán thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11670, 29542, '子どもとサーカスを見に行きました。', 'こどもと サーカスを みに いきました。', 'Tôi đưa con đi xem xiếc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11671, 29554, 'どうぞ、召し上がってください。', 'どうぞ、めしあがって ください。', 'Xin mời anh dùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11672, 29562, '奥様はお元気ですか。', 'おくさまは おげんき ですか。', 'Phu nhân có khỏe không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11673, 29565, 'この講座はどなたでも参加できます。', 'この こうざは どなたでも さんか できます。', 'Khóa học này ai cũng có thể tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11674, 29574, '医者を目指して勉強しています。', 'いしゃを めざして べんきょう して います。', 'Tôi đang học với mục tiêu trở thành bác sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11675, 29576, '山中先生はiPS細胞を開発しました。', 'やまなか せんせいは アイピーエス さいぼうを かいはつ しました。', 'Giáo sư Yamanaka đã phát triển tế bào gốc iPS.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11676, 29581, '大学で有名な先生の講演会があります。', 'だいがくで ゆうめいな せんせいの こうえんかいが あります。', 'Ở trường có buổi diễn thuyết của một giáo sư nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11677, 29589, '会社の帰りに本屋に寄りました。', 'かいしゃの かえりに ほんやに よりました。', 'Trên đường đi làm về tôi ghé hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11678, 29593, '今日の講師は田中先生です。', 'きょうの こうしは たなか せんせい です。', 'Giảng viên hôm nay là thầy Tanaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11679, 29601, 'パスポートをお持ちですか。', 'パスポートを おもち ですか。', 'Quý khách có mang hộ chiếu không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11680, 31240, 'これは暫定的な結果です。', 'これは ざんていてきな けっか です。', 'Đây là kết quả tạm thời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11681, 42128, '彼は突然、心臓の発作を起こした。', 'かれは とつぜん、しんぞうの ほっさを おこした。', 'Anh ấy đột nhiên lên cơn đau tim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11682, 42111, 'お年寄りへの配慮が足りなかった。', 'おとしよりへの はいりょが たりなかった。', 'Sự quan tâm đến người già vẫn còn thiếu sót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11683, 42114, '年末の大売り出しが始まった。', 'ねんまつの おおうりだしが はじまった。', 'Đợt giảm giá lớn cuối năm đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11684, 42116, '新商品の売れ行きは好調だ。', 'しんしょうひんの うれゆきは こうちょうだ。', 'Sản phẩm mới bán rất chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11685, 42119, '弟はお菓子を食べたことを白状した。', 'おとうとは おかしを たべた ことを はくじょう した。', 'Em trai đã thú nhận ăn mất bánh kẹo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11686, 42123, '古いビルが爆破によって解体された。', 'ふるい ビルが ばくはに よって かいたい された。', 'Tòa nhà cũ đã được phá dỡ bằng cách cho nổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11687, 42125, '種をまいて一週間で発芽した。', 'たねを まいて いっしゅうかんで はつが した。', 'Gieo hạt một tuần thì nảy mầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11688, 42118, '木の皮を剥いで紙を作る。', 'きの かわを はいで かみを つくる。', 'Lột vỏ cây để làm giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11689, 42133, '名簿で彼の名前を抜かしてしまった。', 'めいぼで かれの なまえを ぬかして しまった。', 'Tôi lỡ bỏ sót tên anh ấy trong danh sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11690, 42132, 'そんなことをすると罰が当たるよ。', 'そんな ことを すると ばちが あたるよ。', 'Làm thế sẽ bị trời phạt đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11691, 29605, '大江健三郎はノーベル文学賞をもらいました。', 'おおえ けんざぶろうは ノーベル ぶんがくしょうを もらいました。', 'Oe Kenzaburo đã nhận giải Nobel văn học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11692, 29579, 'この研究はヒトの細胞を使っています。', 'この けんきゅうは ヒトの さいぼうを つかって います。', 'Nghiên cứu này sử dụng tế bào người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11693, 29612, '私がご案内いたします。', 'わたしが ごあんない いたします。', 'Tôi xin được hướng dẫn quý khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11694, 29615, 'ちょっと伺いたいことがあるんですが。', 'ちょっと うかがいたい ことが あるん ですが。', 'Tôi có chuyện muốn hỏi một chút ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11695, 29629, '優勝して賞金をもらいました。', 'ゆうしょう して しょうきんを もらいました。', 'Vô địch nên tôi nhận được tiền thưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11696, 29635, '手伝ってくださった皆様に感謝します。', 'てつだって くださった みなさまに かんしゃ します。', 'Tôi xin cảm tạ mọi người đã giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11697, 29641, 'トイレは二階にございます。', 'トイレは にかいに ございます。', 'Nhà vệ sinh ở tầng hai ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11698, 29650, 'その番組は毎週土曜日に放送されます。', 'その ばんぐみは まいしゅう どようびに ほうそう されます。', 'Chương trình đó được phát sóng vào thứ bảy hằng tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11699, 29659, '手紙の最後に「敬具」と書きます。', 'てがみの さいごに 「けいぐ」と かきます。', 'Cuối thư viết "Kính thư".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11700, 29640, 'ミュンヘンはビールで有名です。', 'ミュンヘンは ビールで ゆうめい です。', 'Munich nổi tiếng với bia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11701, 44093, '大家さんに家賃を払いました。', 'おおやさんに やちんを はらいました。', 'Tôi trả tiền thuê nhà cho chủ nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11702, 44097, 'この部屋は畳が六枚あります。', 'この へやは たたみが ろくまい あります。', 'Phòng này có sáu chiếu tatami.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11703, 44166, '京都でお寺を見物しました。', 'きょうとで おてらを けんぶつ しました。', 'Tôi tham quan chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11704, 44167, '夏のお祭りで盆踊りを見ました。', 'なつの おまつりで ぼんおどりを みました。', 'Ở lễ hội mùa hè tôi đã xem múa Bon odori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11705, 44244, '春になると、桜が咲きます。', 'はるに なると、さくらが さきます。', 'Sang xuân hoa anh đào nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11706, 44246, '庭でトマトを育てています。', 'にわで トマトを そだてて います。', 'Tôi trồng cà chua trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11707, 44248, '公園に桜の木を植えました。', 'こうえんに さくらの きを うえました。', 'Chúng tôi trồng cây anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11708, 42139, '彼の態度は周りの反感を買った。', 'かれの たいどは まわりの はんかんを かった。', 'Thái độ của anh ta gây ác cảm với mọi người xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11709, 42149, '一度の失敗で悲観することはない。', 'いちどの しっぱいで ひかん する ことは ない。', 'Không cần bi quan chỉ vì một lần thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11710, 42151, '暗闇から悲鳴が聞こえた。', 'くらやみから ひめいが きこえた。', 'Từ trong bóng tối vọng ra tiếng thét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11711, 42156, '社長の秘書が電話に出た。', 'しゃちょうの ひしょが でんわに でた。', 'Thư ký của giám đốc đã nghe máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12130, 42589, 'シャツに皺がついている。', 'シャツに しわが ついて いる。', 'Áo sơ mi bị nhăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11712, 42142, '湖の水面に山が反射している。', 'みずうみの すいめんに やまが はんしゃ して いる。', 'Ngọn núi phản chiếu trên mặt hồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11713, 42141, '相手チームが後半に反撃してきた。', 'あいて チームが こうはんに はんげき して きた。', 'Đội bạn đã phản công trong hiệp hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11714, 42152, '重い扉をゆっくり開けた。', 'おもい とびらを ゆっくり あけた。', 'Tôi chầm chậm mở cánh cửa nặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11715, 42157, '畑に肥料をやった。', 'はたけに ひりょうを やった。', 'Tôi bón phân cho ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11716, 42155, '収入は労働時間に比例しない。', 'しゅうにゅうは ろうどう じかんに ひれい しない。', 'Thu nhập không tỷ lệ thuận với thời gian làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11717, 42183, '不景気で給料が下がった。', 'ふけいきで きゅうりょうが さがった。', 'Kinh tế suy thoái nên lương bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11718, 44360, '病気で五キロ痩せました。', 'びょうきで ごキロ やせました。', 'Vì ốm mà tôi gầy đi năm ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11719, 44362, '早く風邪を治してください。', 'はやく かぜを なおして ください。', 'Mau khỏi cảm nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11720, 44364, '転んで、足の骨が折れました。', 'ころんで、あしの ほねが おれました。', 'Tôi ngã và bị gãy xương chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11721, 44366, '雨の日は膝が痛みます。', 'あめの ひは ひざが いたみます。', 'Ngày mưa đầu gối tôi đau nhức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11722, 44368, '気分が悪くて、吐いてしまいました。', 'きぶんが わるくて、はいて しまいました。', 'Thấy khó chịu nên tôi đã nôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11723, 44426, '父は貿易の会社で働いています。', 'ちちは ぼうえきの かいしゃで はたらいて います。', 'Bố tôi làm ở công ty thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11724, 44465, '水道の水を飲むことができます。', 'すいどうの みずを のむ ことが できます。', 'Có thể uống nước máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11725, 44470, '掃除機で部屋を掃除しました。', 'そうじきで へやを そうじ しました。', 'Tôi dọn phòng bằng máy hút bụi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11726, 44472, 'お湯を沸かして、お茶を入れました。', 'おゆを わかして、おちゃを いれました。', 'Tôi đun nước nóng để pha trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11727, 44479, '机の上を片付けてください。', 'つくえの うえを かたづけて ください。', 'Hãy dọn mặt bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11728, 44481, '道でお金を拾いました。', 'みちで おかねを ひろいました。', 'Tôi nhặt được tiền trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11729, 44484, 'パンを焼いて食べます。', 'パンを やいて たべます。', 'Tôi nướng bánh mì để ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11730, 44485, '野菜と肉を煮てスープを作りました。', 'やさいと にくを にて スープを つくりました。', 'Tôi ninh rau với thịt để nấu súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11731, 44488, '雨で靴が汚れました。', 'あめで くつが よごれました。', 'Giày bị bẩn vì mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11732, 44527, '夏のお祭りで盆踊りを見ました。', 'なつの おまつりで ぼんおどりを みました。', 'Ở lễ hội mùa hè tôi đã xem múa Bon odori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11733, 44528, '四月に公園で花見をしました。', 'しがつに こうえんで はなみを しました。', 'Tháng tư tôi ngắm hoa anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11734, 31371, '注文した本が届きました。', 'ちゅうもん した ほんが とどきました。', 'Cuốn sách tôi đặt đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11735, 44541, '子どもたちが公園で遊んでいます。', 'こどもたちが こうえんで あそんで います。', 'Bọn trẻ đang chơi ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11736, 42172, '病は気から。', 'やまいは きから。', 'Bệnh tật bắt nguồn từ tinh thần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11737, 42170, '交通安全の標語を募集している。', 'こうつう あんぜんの ひょうごを ぼしゅう して いる。', 'Đang kêu gọi sáng tác khẩu hiệu an toàn giao thông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11738, 42169, '英語は一年生の必修科目だ。', 'えいごは いちねんせいの ひっしゅう かもくだ。', 'Tiếng Anh là môn bắt buộc của sinh viên năm nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11739, 42173, '田んぼに稲の苗を植えた。', 'たんぼに いねの なえを うえた。', 'Tôi cấy mạ xuống ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11740, 42175, '浜で地引き網を手伝った。', 'はまで じびきあみを てつだった。', 'Tôi giúp kéo lưới trên bãi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11741, 42185, '天候不順で野菜の値段が上がった。', 'てんこう ふじゅんで やさいの ねだんが あがった。', 'Thời tiết thất thường làm giá rau tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11742, 42171, '台所からいい匂いが漂ってくる。', 'だいどころから いい においが ただよって くる。', 'Mùi thơm phảng phất từ nhà bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11743, 42181, '不意に名前を呼ばれて驚いた。', 'ふいに なまえを よばれて おどろいた。', 'Bất ngờ bị gọi tên nên tôi giật mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11744, 42182, '黒猫が前を横切ると不吉だと言われる。', 'くろねこが まえを よこぎると ふきつだと いわれる。', 'Người ta nói mèo đen chạy ngang qua trước mặt là điềm gở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11745, 42208, 'その会社は多額の負債を抱えている。', 'その かいしゃは たがくの ふさいを かかえて いる。', 'Công ty đó đang gánh khoản nợ lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11746, 44543, 'パーティーでみんなで踊りました。', 'パーティーで みんなで おどりました。', 'Ở bữa tiệc mọi người cùng nhảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11747, 44545, 'ピアノを弾くのが好きです。', 'ピアノを ひくのが すき です。', 'Tôi thích chơi piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11748, 44605, '桜の花が散ってしまいました。', 'さくらの はなが ちって しまいました。', 'Hoa anh đào đã rụng hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11749, 44608, '公園に桜の木を植えました。', 'こうえんに さくらの きを うえました。', 'Chúng tôi trồng cây anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11750, 44603, 'ペットボトルはリサイクルできます。', 'ペットボトルは リサイクル できます。', 'Chai nhựa có thể tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11751, 44792, '先生によろしく伝えてください。', 'せんせいに よろしく つたえて ください。', 'Cho tôi gửi lời hỏi thăm thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11752, 44796, '母の料理を手伝いました。', 'ははの りょうりを てつだいました。', 'Tôi giúp mẹ nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11753, 44797, '走ったので、電車に間に合いました。', 'はしったので、でんしゃに まにあいました。', 'Nhờ chạy mà tôi kịp tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11754, 44800, 'たばこをやめました。', 'たばこを やめました。', 'Tôi đã bỏ thuốc lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11755, 44802, '駅の前に人が集まっています。', 'えきの まえに ひとが あつまって います。', 'Trước ga có nhiều người đang tụ tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11756, 44804, '今日は特別な日です。', 'きょうは とくべつな ひ です。', 'Hôm nay là một ngày đặc biệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11757, 44805, 'この料理は簡単に作れます。', 'この りょうりは かんたんに つくれます。', 'Món này có thể nấu đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11758, 44806, 'この問題は複雑です。', 'この もんだいは ふくざつ です。', 'Vấn đề này phức tạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11759, 38430, 'お嬢さんはおいくつですか。', 'おじょうさんは おいくつ ですか。', 'Con gái anh bao nhiêu tuổi ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11760, 29627, '江戸東京博物館で昔の東京を見ました。', 'えど とうきょう はくぶつかんで むかしの とうきょうを みました。', 'Tôi xem Tokyo ngày xưa ở Bảo tàng Edo-Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11761, 44831, '電子レンジで弁当を温めました。', 'でんし レンジで べんとうを あたためました。', 'Tôi hâm nóng cơm hộp bằng lò vi sóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11762, 44835, '花のいい匂いがします。', 'はなの いい においが します。', 'Có mùi hoa thơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11763, 44887, '夏のお祭りで盆踊りを見ました。', 'なつの おまつりで ぼんおどりを みました。', 'Ở lễ hội mùa hè tôi đã xem múa Bon odori.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11764, 42204, '夫の浮気が原因で離婚した。', 'おっとの うわきが げんいんで りこん した。', 'Hai người ly hôn vì chồng ngoại tình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11765, 42209, '事故で三人が負傷した。', 'じこで さんにんが ふしょう した。', 'Ba người bị thương trong vụ tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11766, 42196, '彼は一生で大きな富を築いた。', 'かれは いっしょうで おおきな とみを きずいた。', 'Ông ấy đã gây dựng được khối tài sản lớn trong đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11767, 42198, 'その富豪は全財産を寄付した。', 'その ふごうは ぜん ざいさんを きふ した。', 'Vị triệu phú đó đã quyên góp toàn bộ tài sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11768, 42217, '彼は営業部で働いている。', 'かれは えいぎょうぶで はたらいて いる。', 'Anh ấy làm việc ở phòng kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11769, 42195, '雑誌の付録にカレンダーがついていた。', 'ざっしの ふろくに カレンダーが ついて いた。', 'Tạp chí có kèm phụ bản là tờ lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11770, 42213, '人前で侮辱されて腹が立った。', 'ひとまえで ぶじょく されて はらが たった。', 'Bị lăng mạ trước mặt mọi người nên tôi tức giận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11771, 42214, '武装した集団が町に現れた。', 'ぶそう した しゅうだんが まちに あらわれた。', 'Một nhóm vũ trang đã xuất hiện trong thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11772, 44966, '庭でトマトを育てています。', 'にわで トマトを そだてて います。', 'Tôi trồng cà chua trong vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11773, 44968, '公園に桜の木を植えました。', 'こうえんに さくらの きを うえました。', 'Chúng tôi trồng cây anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11774, 44970, '夜空に星が光っています。', 'よぞらに ほしが ひかって います。', 'Sao đang tỏa sáng trên bầu trời đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11775, 44972, '紙はよく燃えます。', 'かみは よく もえます。', 'Giấy dễ cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11776, 44973, '外国人の観光客が増えています。', 'がいこくじんの かんこうきゃくが ふえて います。', 'Khách du lịch nước ngoài đang tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11777, 44978, '服を汚さないように気をつけてください。', 'ふくを よごさない ように きを つけて ください。', 'Hãy cẩn thận đừng làm bẩn quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11778, 44983, 'このパンは柔らかいです。', 'この パンは やわらかい です。', 'Bánh mì này mềm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11779, 44985, '野菜を細かく切ってください。', 'やさいを こまかく きって ください。', 'Hãy thái nhỏ rau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11780, 44963, 'ペットボトルはリサイクルできます。', 'ペットボトルは リサイクル できます。', 'Chai nhựa có thể tái chế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11781, 29608, 'あした、そちらへ参ります。', 'あした、そちらへ まいります。', 'Ngày mai tôi sẽ đến chỗ anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11782, 31360, '家族が元気で安心しました。', 'かぞくが げんきで あんしん しました。', 'Gia đình khỏe mạnh nên tôi yên tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11783, 31361, '母の病気が心配です。', 'ははの びょうきが しんぱい です。', 'Tôi lo cho bệnh của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11784, 31363, '家族と一緒にいられて幸せです。', 'かぞくと いっしょに いられて しあわせ です。', 'Được ở bên gia đình, tôi thấy hạnh phúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11785, 31356, '走ったので、電車に間に合いました。', 'はしったので、でんしゃに まにあいました。', 'Nhờ chạy mà tôi kịp tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11786, 31370, '友達を駅まで送りました。', 'ともだちを えきまで おくりました。', 'Tôi tiễn bạn ra ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11787, 31383, '駅で道の案内をしてもらいました。', 'えきで みちの あんないを して もらいました。', 'Tôi được chỉ đường ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11788, 31385, '結婚式に招待されました。', 'けっこんしきに しょうたい されました。', 'Tôi được mời dự đám cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11789, 31388, '駅で友達を迎えました。', 'えきで ともだちを むかえました。', 'Tôi đón bạn ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11790, 31399, '服を汚さないように気をつけてください。', 'ふくを よごさない ように きを つけて ください。', 'Hãy cẩn thận đừng làm bẩn quần áo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11791, 42240, '水の分子は小さい。', 'みずの ぶんしは ちいさい。', 'Phân tử nước rất nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11792, 42226, '腹立ちまぎれにドアを強く閉めた。', 'はらだち まぎれに ドアを つよく しめた。', 'Trong cơn tức giận, tôi đóng sầm cửa lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11793, 42234, 'この料理は少し物足りない。', 'この りょうりは すこし ものたりない。', 'Món này ăn thấy hơi thiếu thiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11794, 42242, '利益を社員に公平に分配する。', 'りえきを しゃいんに こうへいに ぶんぱい する。', 'Lợi nhuận được chia đều công bằng cho nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11795, 42235, '空に不思議な物体が見えた。', 'そらに ふしぎな ぶったいが みえた。', 'Trên trời xuất hiện một vật thể kỳ lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11796, 42236, '使わない自転車を物置きにしまった。', 'つかわない じてんしゃを ものおきに しまった。', 'Tôi cất chiếc xe đạp không dùng vào nhà kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11797, 42224, 'それぞれの土地の風土に合った料理がある。', 'それぞれの とちの ふうどに あった りょうりが ある。', 'Mỗi vùng có món ăn hợp với phong thổ nơi đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11798, 42228, 'お湯が沸騰したら、麺を入れる。', 'おゆが ふっとう したら、めんを いれる。', 'Nước sôi thì cho mì vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11799, 42253, 'その地域では紛争が続いている。', 'その ちいきでは ふんそうが つづいて いる。', 'Xung đột vẫn đang tiếp diễn ở khu vực đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11800, 31395, '壊れた時計を直しました。', 'こわれた とけいを なおしました。', 'Tôi đã sửa chiếc đồng hồ hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11801, 31397, '弟がおもちゃを壊しました。', 'おとうとが おもちゃを こわしました。', 'Em trai tôi làm hỏng đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11802, 37702, 'お互いに助け合いましょう。', 'おたがいに たすけあいましょう。', 'Hãy giúp đỡ lẫn nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11803, 31415, '私は数学が苦手です。', 'わたしは すうがくが にがて です。', 'Tôi kém môn toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11804, 37959, '大家さんに家賃を払いました。', 'おおやさんに やちんを はらいました。', 'Tôi trả tiền thuê nhà cho chủ nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11805, 37978, 'ここに名前と性別を書いてください。', 'ここに なまえと せいべつを かいて ください。', 'Hãy ghi tên và giới tính vào đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11806, 38419, '会う人みんなに挨拶します。', 'あう ひと みんなに あいさつ します。', 'Tôi chào hỏi tất cả những ai mình gặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11807, 38427, '彼はお金持ちですが、とても親切です。', 'かれは おかねもち ですが、とても しんせつ です。', 'Anh ấy giàu có nhưng rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11808, 38441, 'しっかり勉強してください。', 'しっかり べんきょう して ください。', 'Hãy học hành chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11809, 38484, 'ここではたばこはご遠慮ください。', 'ここでは たばこは ごえんりょ ください。', 'Xin vui lòng không hút thuốc ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11810, 38488, '四月に公園で花見をしました。', 'しがつに こうえんで はなみを しました。', 'Tháng tư tôi ngắm hoa anh đào ở công viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11811, 38497, 'この店はいつも客が多いです。', 'この みせは いつも きゃくが おおい です。', 'Quán này lúc nào cũng đông khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11812, 38519, 'あの子は誰の子どもですか。', 'あの こは だれの こども ですか。', 'Đứa bé kia là con của ai?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11813, 38518, 'この坂を上ると、駅があります。', 'この さかを のぼると、えきが あります。', 'Leo lên con dốc này là đến ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11814, 38514, '子どもたちが砂で遊んでいます。', 'こどもたちが すなで あそんで います。', 'Bọn trẻ đang chơi cát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11815, 38536, 'この部屋は畳が六枚あります。', 'この へやは たたみが ろくまい あります。', 'Phòng này có sáu chiếu tatami.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11816, 38558, '丁寧に説明してくれました。', 'ていねいに せつめい して くれました。', 'Họ đã giải thích cẩn thận cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11817, 38594, '重い荷物を持って、腕が痛いです。', 'おもい にもつを もって、うでが いたい です。', 'Mang đồ nặng nên tôi đau tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11818, 42271, '三年間、彼女に片思いしている。', 'さんねんかん、かのじょに かたおもい して いる。', 'Tôi đã yêu đơn phương cô ấy ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11819, 42275, '突然の質問に返答できなかった。', 'とつぜんの しつもんに へんとう できなかった。', 'Tôi không trả lời được câu hỏi đột ngột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11820, 42278, '弁論大会で優勝した。', 'べんろん たいかいで ゆうしょう した。', 'Tôi đã vô địch cuộc thi hùng biện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11821, 42258, '日本語の聞き取りが苦手だ。', 'にほんごの ききとりが にがてだ。', 'Tôi kém phần nghe hiểu tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11822, 42264, 'この部屋は二十平方メートルある。', 'この へやは にじゅう へいほう メートル ある。', 'Căn phòng này rộng hai mươi mét vuông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11823, 42260, '多くの兵士が戦場で命を落とした。', 'おおくの へいしが せんじょうで いのちを おとした。', 'Nhiều binh sĩ đã bỏ mạng trên chiến trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11824, 42244, 'ごみは燃えるものと燃えないものに分離する。', 'ごみは もえる ものと もえない ものに ぶんり する。', 'Rác được tách thành loại cháy được và không cháy được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11825, 42251, '犯人は人込みに紛れて逃げた。', 'はんにんは ひとごみに まぎれて にげた。', 'Thủ phạm lẫn vào đám đông và trốn thoát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11826, 38591, '家の後ろに林があります。', 'いえの うしろに はやしが あります。', 'Phía sau nhà có một khu rừng nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11827, 40590, 'ルールを守ってください。', 'ルールを まもって ください。', 'Hãy tuân thủ luật lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11828, 31251, '新しい発見が従来の定説を覆した。', 'あたらしい はっけんが じゅうらいの ていせつを くつがえした。', 'Phát hiện mới đã lật đổ học thuyết vốn có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11829, 31255, '東洋と西洋の文化が融合している。', 'とうようと せいようの ぶんかが ゆうごう して いる。', 'Văn hóa phương Đông và phương Tây hòa quyện vào nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11830, 31256, '二つの薬品を混合すると危険だ。', 'ふたつの やくひんを こんごう すると きけんだ。', 'Trộn lẫn hai loại hóa chất là nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11831, 31258, 'この地域には希少な動物がすんでいる。', 'この ちいきには きしょうな どうぶつが すんで いる。', 'Khu vực này có các loài động vật quý hiếm sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11832, 31260, '寒さで筋肉が収縮する。', 'さむさで きんにくが しゅうしゅく する。', 'Cơ bắp co lại vì lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11833, 31262, '粗雑な扱いで荷物が壊れた。', 'そざつな あつかいで にもつが こわれた。', 'Hàng bị vỡ vì cách xử lý cẩu thả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11834, 31264, '結婚式は簡素に行った。', 'けっこんしきは かんそに おこなった。', 'Đám cưới được tổ chức giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11835, 31266, '細部までこだわって作られた作品だ。', 'さいぶまで こだわって つくられた さくひんだ。', 'Đây là tác phẩm được làm tỉ mỉ đến từng chi tiết nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11836, 31267, '政府の対応は緩慢だと批判された。', 'せいふの たいおうは かんまんだと ひはん された。', 'Phản ứng của chính phủ bị phê phán là chậm chạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11837, 30978, 'この建物は周りの自然と調和している。', 'この たてものは まわりの しぜんと ちょうわ して いる。', 'Tòa nhà này hài hòa với thiên nhiên xung quanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11838, 30979, '需要と供給の均衡が崩れた。', 'じゅようと きょうきゅうの きんこうが くずれた。', 'Cân bằng cung cầu đã bị phá vỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11839, 30980, 'その政策の是非をめぐって議論が続いている。', 'その せいさくの ぜひを めぐって ぎろんが つづいて いる。', 'Cuộc tranh luận về đúng sai của chính sách đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11840, 30984, '水は生命にとって不可欠なものだ。', 'みずは せいめいに とって ふかけつな ものだ。', 'Nước là thứ không thể thiếu đối với sự sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11841, 30986, '幸せかどうかは相対的なものだ。', 'しあわせか どうかは そうたいてきな ものだ。', 'Hạnh phúc hay không là điều mang tính tương đối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11842, 31062, 'これは暫定的な結果です。', 'これは ざんていてきな けっか です。', 'Đây là kết quả tạm thời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11843, 42294, '先ほどの説明に一つ補足します。', 'さきほどの せつめいに ひとつ ほそく します。', 'Tôi xin bổ sung một điểm cho lời giải thích vừa rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11844, 42287, '戦争が終わって、捕虜が解放された。', 'せんそうが おわって、ほりょが かいほう された。', 'Chiến tranh kết thúc, tù binh được trả tự do.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11845, 42284, '村の道もすべて舗装された。', 'むらの みちも すべて ほそう された。', 'Đường làng cũng đã được trải nhựa hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11846, 42295, '秋になり、稲の穂が実った。', 'あきに なり、いねの ほが みのった。', 'Sang thu, bông lúa đã chín.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11847, 42285, '町に出た熊が捕獲された。', 'まちに でた くまが ほかく された。', 'Con gấu xuất hiện trong thị trấn đã bị bắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11848, 42290, '運動中はこまめに水分を補給しよう。', 'うんどうちゅうは こまめに すいぶんを ほきゅう しよう。', 'Khi vận động hãy bổ sung nước thường xuyên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11849, 42292, 'プリンターのインクを補充した。', 'プリンターの インクを ほじゅう した。', 'Tôi đã bổ sung mực cho máy in.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11850, 42296, '被災地への寄付を募っている。', 'ひさいちへの きふを つのって いる。', 'Đang kêu gọi quyên góp cho vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11851, 42322, '彼はこの仕事の経験が乏しい。', 'かれは この しごとの けいけんが とぼしい。', 'Anh ấy còn ít kinh nghiệm trong công việc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11852, 42311, '事故の後、放射能の検査が行われた。', 'じこの あと、ほうしゃのうの けんさが おこなわれた。', 'Sau sự cố, việc kiểm tra phóng xạ đã được tiến hành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11853, 37932, '毎年旅行できるなんて、羨ましいです。', 'まいとし りょこう できる なんて、うらやましい です。', 'Năm nào cũng đi du lịch được, thật đáng ghen tị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11854, 37934, '今の仕事に満足しています。', 'いまの しごとに まんぞく して います。', 'Tôi hài lòng với công việc hiện tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11855, 37936, '新しい仕事に期待しています。', 'あたらしい しごとに きたい して います。', 'Tôi kỳ vọng vào công việc mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11856, 37938, '深呼吸すると、落ち着きます。', 'しんこきゅう すると、おちつきます。', 'Hít thở sâu là bình tĩnh lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11857, 37941, '銀行で口座を作るとき、印鑑が必要です。', 'ぎんこうで こうざを つくる とき、いんかんが ひつよう です。', 'Khi mở tài khoản ngân hàng cần có con dấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11858, 37943, '日本語能力試験に合格しました。', 'にほんご のうりょく しけんに ごうかく しました。', 'Tôi đã đỗ kỳ thi năng lực tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11859, 37947, '高校のとき、部活でサッカーをしていました。', 'こうこうの とき、ぶかつで サッカーを して いました。', 'Hồi cấp ba tôi chơi bóng đá trong câu lạc bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11860, 37955, '不動産屋でアパートを探しました。', 'ふどうさんやで アパートを さがしました。', 'Tôi tìm căn hộ ở văn phòng bất động sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11861, 37957, 'アパートを二年契約しました。', 'アパートを にねん けいやく しました。', 'Tôi ký hợp đồng thuê căn hộ hai năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11862, 37921, '毎朝電車に乗ります。', 'まいあさ でんしゃに のります。', 'Sáng nào tôi cũng đi tàu điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11863, 37923, 'この店では免税で買い物ができます。', 'この みせでは めんぜいで かいものが できます。', 'Ở cửa hàng này có thể mua hàng miễn thuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11864, 38431, 'ガソリンスタンドでガソリンを入れました。', 'ガソリンスタンドで ガソリンを いれました。', 'Tôi đổ xăng ở trạm xăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11865, 38559, '毎日自転車で学校に通っています。', 'まいにち じてんしゃで がっこうに かよって います。', 'Ngày nào tôi cũng đạp xe đi học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11866, 38572, '飛行場まで友達を迎えに行きました。', 'ひこうじょうまで ともだちを むかえに いきました。', 'Tôi ra sân bay đón bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11867, 42301, '突然の知らせに呆然とした。', 'とつぜんの しらせに ぼうぜんと した。', 'Trước tin báo đột ngột, tôi sững sờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11868, 42303, '仕事の報酬を受け取った。', 'しごとの ほうしゅうを うけとった。', 'Tôi đã nhận thù lao công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11869, 42299, '十年ぶりに母校を訪ねた。', 'じゅうねんぶりに ぼこうを たずねた。', 'Sau mười năm tôi mới về thăm trường cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11870, 42316, '彼は法学部を出て弁護士になった。', 'かれは ほうがくぶを でて べんごしに なった。', 'Anh ấy tốt nghiệp khoa luật rồi trở thành luật sư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11871, 42315, '新しい法案が国会に提出された。', 'あたらしい ほうあんが こっかいに ていしゅつ された。', 'Dự luật mới đã được trình lên quốc hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11872, 42317, '彼は法廷で無実を訴えた。', 'かれは ほうていで むじつを うったえた。', 'Anh ấy khẳng định mình vô tội trước tòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11873, 42318, '紅茶に蜂蜜を入れて飲む。', 'こうちゃに はちみつを いれて のむ。', 'Tôi cho mật ong vào trà để uống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11874, 42306, '雪をかぶった峰々が美しい。', 'ゆきを かぶった みねみねが うつくしい。', 'Những đỉnh núi phủ tuyết thật đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11875, 42307, '彼女は一生を教育に捧げた。', 'かのじょは いっしょうを きょういくに ささげた。', 'Bà ấy đã cống hiến cả đời cho giáo dục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11876, 38550, 'スープに塩を足しました。', 'スープに しおを たしました。', 'Tôi cho thêm muối vào súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11877, 37711, '信号が赤に変わりました。', 'しんごうが あかに かわりました。', 'Đèn tín hiệu đã chuyển sang đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11878, 37713, '旅行の日にちが決まりました。', 'りょこうの ひにちが きまりました。', 'Ngày đi du lịch đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11879, 37717, '新しい仕事に慣れました。', 'あたらしい しごとに なれました。', 'Tôi đã quen với công việc mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11880, 37951, 'ケーキを四つに分けました。', 'ケーキを よっつに わけました。', 'Tôi chia chiếc bánh thành bốn phần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11881, 37953, '新しい方法を試してみます。', 'あたらしい ほうほうを ためして みます。', 'Tôi sẽ thử phương pháp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11882, 38437, 'この写真をごらんになりましたか。', 'この しゃしんを ごらんに なりましたか。', 'Anh đã xem bức ảnh này chưa ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11883, 38502, 'ここから富士山が見えます。', 'ここから ふじさんが みえます。', 'Từ đây có thể nhìn thấy núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11884, 38548, '風で枝が折れました。', 'かぜで えだが おれました。', 'Gió làm gãy cành cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11885, 38564, '壁にペンキを塗りました。', 'かべに ペンキを ぬりました。', 'Tôi sơn tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11886, 38587, '地震で電車が揺れました。', 'じしんで でんしゃが ゆれました。', 'Động đất làm tàu rung lắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11887, 31418, 'その服、よく似合いますね。', 'その ふく、よく にあいますね。', 'Bộ đồ đó hợp với bạn lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11888, 37973, '日本語の勉強は面白いです。', 'にほんごの べんきょうは おもしろい です。', 'Học tiếng Nhật rất thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11889, 37975, 'この通りはいつもにぎやかです。', 'この とおりは いつも にぎやか です。', 'Con phố này lúc nào cũng nhộn nhịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11890, 37977, 'この店はラーメンで有名です。', 'この みせは ラーメンで ゆうめい です。', 'Quán này nổi tiếng với mì ramen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11891, 37983, 'この川で泳ぐのは危険です。', 'この かわで およぐのは きけん です。', 'Bơi ở con sông này rất nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11892, 37984, '日本の夜は安全です。', 'にほんの よるは あんぜん です。', 'Ban đêm ở Nhật an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11893, 42344, 'その歌手の本名は誰も知らない。', 'その かしゅの ほんみょうは だれも しらない。', 'Không ai biết tên thật của ca sĩ đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11894, 42334, '赤ちゃんの頬っぺたは柔らかい。', 'あかちゃんの ほっぺたは やわらかい。', 'Má em bé mềm mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11895, 42346, '大雪で交通が麻痺した。', 'おおゆきで こうつうが まひ した。', 'Tuyết dày làm giao thông tê liệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11896, 42340, '受付は本館の一階にあります。', 'うけつけは ほんかんの いっかいに あります。', 'Quầy lễ tân ở tầng một tòa nhà chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11897, 42341, '本場のイタリア料理を食べてみたい。', 'ほんばの イタリア りょうりを たべて みたい。', 'Tôi muốn thử món Ý chính gốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11898, 42352, '江戸時代の末期に外国の船が来た。', 'えど じだいの まっきに がいこくの ふねが きた。', 'Cuối thời Edo, tàu nước ngoài đã đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11899, 42347, '会場は観客で埋まった。', 'かいじょうは かんきゃくで うずまった。', 'Hội trường kín chỗ khán giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11900, 42339, '四月から本格的に仕事が始まる。', 'しがつから ほんかくてきに しごとが はじまる。', 'Từ tháng tư công việc sẽ chính thức bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11901, 42342, '本体の値段に税金は含まれていない。', 'ほんたいの ねだんに ぜいきんは ふくまれて いない。', 'Giá sản phẩm chính chưa bao gồm thuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11902, 42338, 'ほんの気持ちですが、どうぞ。', 'ほんの きもち ですが、どうぞ。', 'Chỉ chút lòng thành, xin anh nhận cho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11903, 38421, '姉はテレビのアナウンサーです。', 'あねは テレビの アナウンサー です。', 'Chị tôi là phát thanh viên truyền hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11904, 38505, 'エアコンが故障しました。', 'エアコンが こしょう しました。', 'Điều hòa bị hỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11905, 37705, '日本の製品は品質がいいです。', 'にほんの せいひんは ひんしつが いい です。', 'Sản phẩm Nhật có chất lượng tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11906, 38535, '雨の場合は、試合は中止です。', 'あめの ばあいは、しあいは ちゅうし です。', 'Trường hợp trời mưa thì trận đấu bị hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11907, 38578, 'これとは別の色はありますか。', 'これとは べつの いろは ありますか。', 'Có màu khác ngoài màu này không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11908, 31416, '兄と私は顔が似ています。', 'あにと わたしは かおが にて います。', 'Anh trai và tôi có khuôn mặt giống nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11909, 37701, '二人は互いに助け合っています。', 'ふたりは たがいに たすけあって います。', 'Hai người giúp đỡ lẫn nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11910, 37741, '靴はそのままで上がってください。', 'くつは その ままで あがって ください。', 'Cứ để nguyên giày mà vào nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11911, 37743, 'もう二度と遅刻しません。', 'もう にどと ちこく しません。', 'Tôi sẽ không bao giờ đi muộn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11912, 37745, 'もし雨が降ったら、家にいます。', 'もし あめが ふったら、いえに います。', 'Nếu trời mưa thì tôi ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11913, 38426, '先生のおかげで合格しました。', 'せんせいの おかげで ごうかく しました。', 'Nhờ có thầy mà tôi thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11914, 38435, 'この漢字はこう書きます。', 'この かんじは こう かきます。', 'Chữ Hán này viết như thế này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11915, 38500, 'このことは決して忘れません。', 'この ことは けっして わすれません。', 'Chuyện này tôi quyết không quên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11916, 38571, 'この問題は非常に難しいです。', 'この もんだいは ひじょうに むずかしい です。', 'Vấn đề này vô cùng khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11917, 38585, '今度うちへ遊びに来てください。', 'こんど うちへ あそびに きて ください。', 'Lần tới đến nhà tôi chơi nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11918, 37694, '旅行の荷物を準備しました。', 'りょこうの にもつを じゅんび しました。', 'Tôi đã chuẩn bị hành lý cho chuyến đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11919, 37696, '日本でいろいろなことを経験しました。', 'にほんで いろいろな ことを けいけん しました。', 'Ở Nhật tôi đã trải nghiệm nhiều điều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11920, 42377, '子供の無邪気な笑顔に癒される。', 'こどもの むじゃきな えがおに いやされる。', 'Nụ cười hồn nhiên của trẻ con khiến tôi thấy thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11921, 42369, '看護師が患者の脈を測った。', 'かんごしが かんじゃの みゃくを はかった。', 'Y tá đo mạch cho bệnh nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11922, 42376, '父は無口だが、優しい人だ。', 'ちちは むくち だが、やさしい ひとだ。', 'Bố tôi ít nói nhưng hiền lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11923, 42388, '無礼な言い方をして、すみませんでした。', 'ぶれいな いいかたを して、すみません でした。', 'Xin lỗi vì đã nói năng vô lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11924, 42375, '彼は無言のまま部屋を出て行った。', 'かれは むごんの まま へやを でて いった。', 'Anh ấy lặng lẽ rời khỏi phòng không nói lời nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11925, 42357, '提案は満場一致で可決された。', 'ていあんは まんじょう いっちで かけつ された。', 'Đề xuất được thông qua với sự nhất trí của toàn thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11926, 42358, 'この酒は深い味わいがある。', 'この さけは ふかい あじわいが ある。', 'Rượu này có hương vị đậm sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11927, 42356, '今夜は満月がきれいだ。', 'こんやは まんげつが きれいだ。', 'Đêm nay trăng tròn thật đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11928, 42360, '私は未年の生まれだ。', 'わたしは ひつじどしの うまれだ。', 'Tôi sinh năm Mùi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11929, 42368, '東京は人口密度が高い。', 'とうきょうは じんこう みつどが たかい。', 'Tokyo có mật độ dân số cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11930, 38583, '木綿のシャツは涼しいです。', 'もめんの シャツは すずしい です。', 'Áo sơ mi vải bông thì mát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11931, 31357, '急がないと、電車に間に合わないよ。', 'いそがないと、でんしゃに まにあわないよ。', 'Không nhanh là không kịp tàu đâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11932, 31351, '旅行の予定に変更があります。', 'りょこうの よていに へんこうが あります。', 'Lịch trình du lịch có thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11933, 31374, '国の家族に小包を送りました。', 'くにの かぞくに こづつみを おくりました。', 'Tôi gửi bưu kiện cho gia đình ở quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11934, 31410, '私の特技は料理です。', 'わたしの とくぎは りょうり です。', 'Sở trường của tôi là nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11935, 31393, '来月、新しいアパートに引っ越します。', 'らいげつ、あたらしい アパートに ひっこします。', 'Tháng sau tôi chuyển đến căn hộ mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11936, 31406, '早く出かける支度をしなさい。', 'はやく でかける したくを しなさい。', 'Mau chuẩn bị ra ngoài đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11937, 31382, 'うれしい知らせが届きました。', 'うれしい しらせが とどきました。', 'Có tin vui gửi đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11938, 31428, '冗談ではなく、本気で言っています。', 'じょうだん では なく、ほんきで いって います。', 'Tôi không đùa, tôi nói thật lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11939, 37699, 'もっと勉強すればよかったと後悔しています。', 'もっと べんきょう すれば よかったと こうかい して います。', 'Tôi hối hận vì đã không học chăm hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11940, 31423, '国によって考え方が違います。', 'くにに よって かんがえかたが ちがいます。', 'Mỗi nước có cách suy nghĩ khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11941, 37720, '財布がないことに気がつきました。', 'さいふが ない ことに きが つきました。', 'Tôi nhận ra là không có ví.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11942, 37716, 'タクシーで行けば、まだ間に合います。', 'タクシーで いけば、まだ まにあいます。', 'Đi taxi thì vẫn còn kịp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11943, 37718, '時間が足りません。', 'じかんが たりません。', 'Không đủ thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11944, 37708, 'この木は早く育ちます。', 'この きは はやく そだちます。', 'Cây này lớn nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11945, 37722, '彼は正直な人です。', 'かれは しょうじきな ひと です。', 'Anh ấy là người thành thật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11946, 37724, '真面目な学生が多いクラスです。', 'まじめな がくせいが おおい クラス です。', 'Lớp có nhiều học sinh chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11947, 42407, '彼は面を伏せて黙っていた。', 'かれは おもを ふせて だまって いた。', 'Anh ấy cúi mặt im lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11948, 42399, '彼はついに秘密を明かした。', 'かれは ついに ひみつを あかした。', 'Cuối cùng anh ấy đã tiết lộ bí mật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11949, 42396, '参加者の名簿を作った。', 'さんかしゃの めいぼを つくった。', 'Tôi đã lập danh sách người tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11950, 42406, '成績優秀者は授業料が免除される。', 'せいせき ゆうしゅうしゃは じゅぎょうりょうが めんじょ される。', 'Sinh viên học giỏi được miễn học phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11951, 42398, '矢は的の真ん中に命中した。', 'やは まとの まんなかに めいちゅう した。', 'Mũi tên trúng ngay giữa hồng tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11952, 42404, '彼は酒で身を滅ぼした。', 'かれは さけで みを ほろぼした。', 'Anh ta tự hủy hoại bản thân vì rượu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11953, 42391, 'ここは桜の名所として名高い。', 'ここは さくらの めいしょと して なだかい。', 'Nơi đây nổi danh là điểm ngắm hoa anh đào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11954, 42401, '彼はあからさまに嫌な顔をした。', 'かれは あからさまに いやな かおを した。', 'Anh ta lộ rõ vẻ khó chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11955, 42408, 'この部屋は海に面している。', 'この へやは うみに めんして いる。', 'Căn phòng này hướng ra biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11956, 42400, '明くる日、彼は東京へ発った。', 'あくる ひ、かれは とうきょうへ たった。', 'Ngày hôm sau, anh ấy lên đường đi Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11957, 37726, '積極的な人は仕事が早いです。', 'せっきょくてきな ひとは しごとが はやい です。', 'Người chủ động thì làm việc nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11958, 37728, '親切な人に道を教えてもらいました。', 'しんせつな ひとに みちを おしえて もらいました。', 'Tôi được một người tốt bụng chỉ đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11959, 37730, '失礼なことを言って、すみませんでした。', 'しつれいな ことを いって、すみません でした。', 'Xin lỗi vì đã nói điều thất lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11960, 37731, '自由な時間がほしいです。', 'じゆうな じかんが ほしい です。', 'Tôi muốn có thời gian tự do.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11961, 37733, 'これは単純な間違いです。', 'これは たんじゅんな まちがい です。', 'Đây là một lỗi sai đơn giản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11962, 37736, '便利な道具を買いました。', 'べんりな どうぐを かいました。', 'Tôi mua một dụng cụ tiện lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11963, 37738, '危険な所へ行かないでください。', 'きけんな ところへ いかないで ください。', 'Đừng đến chỗ nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11964, 37739, 'この町は農業が盛んな所です。', 'この まちは のうぎょうが さかんな ところ です。', 'Thị trấn này là nơi nông nghiệp phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11965, 37925, '日本に来て、季節の変化を感じます。', 'にほんに きて、きせつの へんかを かんじます。', 'Đến Nhật tôi cảm nhận được sự thay đổi của các mùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11966, 37926, '物価が高くて驚きました。', 'ぶっかが たかくて おどろきました。', 'Vật giá đắt quá làm tôi ngạc nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11967, 37928, '合格の知らせを聞いて、両親が喜びました。', 'ごうかくの しらせを きいて、りょうしんが よろこびました。', 'Nghe tin tôi thi đỗ, bố mẹ rất vui.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11968, 37930, '家族に会えなくて寂しいです。', 'かぞくに あえなくて さびしい です。', 'Không được gặp gia đình nên tôi thấy cô đơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11969, 37963, '祖母はとても優しいです。', 'そぼは とても やさしい です。', 'Bà tôi rất hiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11970, 37965, '彼女はいつも明るいです。', 'かのじょは いつも あかるい です。', 'Cô ấy lúc nào cũng vui vẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11971, 37968, 'ホテルの人はとても親切です。', 'ホテルの ひとは とても しんせつ です。', 'Nhân viên khách sạn rất tốt bụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11972, 37970, 'この子は素直です。', 'この こは すなお です。', 'Đứa trẻ này ngoan ngoãn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11973, 37958, 'アパートを借りるとき、敷金を払いました。', 'アパートを かりる とき、しききんを はらいました。', 'Khi thuê căn hộ tôi đã trả tiền đặt cọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11974, 38434, '自転車で転んで、怪我しました。', 'じてんしゃで ころんで、けが しました。', 'Ngã xe đạp nên tôi bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11975, 37972, '彼女は何でも積極的です。', 'かのじょは なんでも せっきょくてき です。', 'Cô ấy việc gì cũng tích cực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11976, 42411, '顔ににきびができてしまった。', 'かおに にきびが できて しまった。', 'Mặt tôi nổi mụn trứng cá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11977, 42433, '彼は社長になるという野心を持っている。', 'かれは しゃちょうに なると いう やしんを もって いる。', 'Anh ấy có tham vọng trở thành giám đốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11978, 42444, '彼は勇敢にも火の中に飛び込んで子供を助けた。', 'かれは ゆうかんにも ひの なかに とびこんで こどもを たすけた。', 'Anh ấy dũng cảm lao vào lửa cứu đứa trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11979, 42423, '図書館の目録で本を探した。', 'としょかんの もくろくで ほんを さがした。', 'Tôi tìm sách trong danh mục của thư viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11980, 42426, 'この通りには昔から問屋が多い。', 'この とおりには むかしから といやが おおい。', 'Con phố này từ xưa đã có nhiều cửa hàng bán buôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11981, 42412, '弟は飛行機の模型を作るのが好きだ。', 'おとうとは ひこうきの もけいを つくるのが すきだ。', 'Em trai tôi thích làm mô hình máy bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11982, 42416, '漁師が網を海に投げた。', 'りょうしが あみを うみに なげた。', 'Ngư dân quăng lưới xuống biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11983, 38438, 'この歌をご存じですか。', 'この うたを ごぞんじ ですか。', 'Anh có biết bài hát này không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11984, 37986, '夢のために努力しています。', 'ゆめの ために どりょく して います。', 'Tôi đang nỗ lực vì ước mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11985, 37988, '目標を達成しました。', 'もくひょうを たっせい しました。', 'Tôi đã đạt được mục tiêu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11986, 38436, '友達の家でごちそうになりました。', 'ともだちの いえで ごちそうに なりました。', 'Tôi được bạn mời một bữa thịnh soạn ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11987, 38459, '来年、日本の大学に入るつもりです。', 'らいねん、にほんの だいがくに はいる つもり です。', 'Năm sau tôi định vào đại học ở Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11988, 38460, 'テキストの二十ページを見てください。', 'テキストの にじゅっページを みて ください。', 'Hãy xem trang hai mươi của giáo trình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11989, 38443, 'パンにジャムをつけて食べます。', 'パンに ジャムを つけて たべます。', 'Tôi phết mứt lên bánh mì ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11990, 38444, 'スーツケースに服を入れました。', 'スーツケースに ふくを いれました。', 'Tôi cho quần áo vào va li.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11991, 38457, 'メールを毎朝チェックします。', 'メールを まいあさ チェック します。', 'Sáng nào tôi cũng kiểm tra email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11992, 38456, 'ここで写真を撮ってはだめです。', 'ここで しゃしんを とっては だめ です。', 'Không được chụp ảnh ở đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11993, 38454, '彼は私の好きなタイプです。', 'かれは わたしの すきな タイプ です。', 'Anh ấy là mẫu người tôi thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11994, 38448, '薬を飲んだら、すっと楽になりました。', 'くすりを のんだら、すっと らくに なりました。', 'Uống thuốc xong là thấy nhẹ nhõm hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11995, 38452, 'そろそろ帰りましょう。', 'そろそろ かえりましょう。', 'Sắp đến lúc về rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11996, 38455, '雨が降っています。だから、出かけません。', 'あめが ふって います。だから、でかけません。', 'Trời đang mưa. Vì vậy tôi không ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11997, 38461, '日本語がどんどん上手になっています。', 'にほんごが どんどん じょうずに なって います。', 'Tiếng Nhật của bạn ngày càng giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11998, 38450, '電車の中ですりに気をつけてください。', 'でんしゃの なかで すりに きを つけて ください。', 'Hãy cẩn thận kẻ móc túi trên tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (11999, 38472, 'まじめに勉強しています。', 'まじめに べんきょう して います。', 'Tôi đang học hành nghiêm túc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12000, 38476, 'レジでお金を払ってください。', 'レジで おかねを はらって ください。', 'Hãy trả tiền ở quầy thu ngân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12001, 38486, '大学の近くに下宿しています。', 'だいがくの ちかくに げしゅく して います。', 'Tôi ở trọ gần trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12002, 38467, '母に誕生日にハンドバッグをあげました。', 'ははに たんじょうびに ハンドバッグを あげました。', 'Sinh nhật mẹ, tôi tặng mẹ túi xách tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12003, 38489, 'もう十二時を過ぎました。', 'もう じゅうにじを すぎました。', 'Đã quá mười hai giờ rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12004, 38478, '三十分以内に戻ります。', 'さんじゅっぷん いないに もどります。', 'Tôi sẽ quay lại trong vòng ba mươi phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12005, 42454, 'モンゴルでは今も遊牧生活をする人々がいる。', 'モンゴルでは いまも ゆうぼく せいかつを する ひとびとが いる。', 'Ở Mông Cổ đến nay vẫn có người sống du mục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12006, 42456, '夕暮れの海辺を二人で歩いた。', 'ゆうぐれの うみべを ふたりで あるいた。', 'Hai người dạo bước bên bờ biển lúc hoàng hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12007, 42461, '余所見をしながら運転するのは危ない。', 'よそみを しながら うんてん するのは あぶない。', 'Vừa lái xe vừa nhìn đi chỗ khác thì nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12008, 42462, 'この計画には改善の余地がある。', 'この けいかくには かいぜんの よちが ある。', 'Kế hoạch này còn chỗ để cải thiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12009, 42463, '彼は余程疲れていたのか、すぐに寝てしまった。', 'かれは よっぽど つかれて いたのか、すぐに ねて しまった。', 'Chắc anh ấy mệt lắm nên ngủ thiếp đi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12010, 42500, '銀行に預けても、利子はほとんどつかない。', 'ぎんこうに あずけても、りしは ほとんど つかない。', 'Gửi ngân hàng cũng hầu như chẳng có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12011, 38490, '京都のお寺を回りました。', 'きょうとの おてらを まわりました。', 'Tôi đi một vòng các chùa ở Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12012, 38469, '地図をファックスで送ってください。', 'ちずを ファックスで おくって ください。', 'Hãy gửi bản đồ qua fax.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12013, 38474, '一年でもっとも寒いのは二月です。', 'いちねんで もっとも さむいのは にがつ です。', 'Tháng lạnh nhất trong năm là tháng hai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12014, 38479, '健康のために、毎日歩いています。', 'けんこうの ために、まいにち あるいて います。', 'Vì sức khỏe, ngày nào tôi cũng đi bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12015, 38499, '夏休みの旅行を計画しています。', 'なつやすみの りょこうを けいかく して います。', 'Tôi đang lên kế hoạch du lịch kỳ nghỉ hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12016, 38511, '兄は高等学校の先生です。', 'あには こうとう がっこうの せんせい です。', 'Anh tôi là giáo viên trường trung học phổ thông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12017, 38522, '朝ご飯の支度をします。', 'あさごはんの したくを します。', 'Tôi chuẩn bị bữa sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12018, 38520, '私は横浜市に住んでいます。', 'わたしは よこはましに すんで います。', 'Tôi sống ở thành phố Yokohama.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12019, 38516, '最初は日本語が全然話せませんでした。', 'さいしょは にほんごが ぜんぜん はなせません でした。', 'Lúc đầu tôi hoàn toàn không nói được tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12020, 38492, '来週、パーティーを開きます。', 'らいしゅう、パーティーを ひらきます。', 'Tuần sau tôi tổ chức tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12021, 38543, '旅行の間、友達が猫の世話をしてくれました。', 'りょこうの あいだ、ともだちが ねこの せわを して くれました。', 'Trong lúc tôi đi du lịch, bạn đã chăm sóc con mèo giúp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12022, 38540, '心からお礼申し上げます。', 'こころから おれい もうしあげます。', 'Tôi xin chân thành cảm ơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12023, 38532, '消しゴムを貸してください。', 'けしゴムを かして ください。', 'Cho tôi mượn cục tẩy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12024, 38538, '寝坊して、学校に遅れました。', 'ねぼう して、がっこうに おくれました。', 'Ngủ dậy muộn nên tôi đến trường trễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12025, 38537, '食料品は地下一階で売っています。', 'しょくりょうひんは ちか いっかいで うって います。', 'Thực phẩm được bán ở tầng hầm một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12026, 38525, '学生時代はよく旅行しました。', 'がくせい じだいは よく りょこう しました。', 'Thời sinh viên tôi hay đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12027, 38529, '会議に出席します。', 'かいぎに しゅっせき します。', 'Tôi sẽ tham dự cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12028, 38577, '隣の部屋から音楽が聞こえます。', 'となりの へやから おんがくが きこえます。', 'Nghe thấy tiếng nhạc từ phòng bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12029, 38544, 'この工場では車を生産しています。', 'この こうじょうでは くるまを せいさん して います。', 'Nhà máy này sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12030, 42486, '子供たちは裸足で砂浜を走った。', 'こどもたちは はだしで すなはまを はしった。', 'Bọn trẻ chạy chân trần trên bãi cát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12031, 42484, '人間の欲望には限りがない。', 'にんげんの よくぼうには かぎりが ない。', 'Lòng ham muốn của con người không có giới hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12032, 42493, '彼女は落ち着きのある大人の女性だ。', 'かのじょは おちつきの ある おとなの じょせいだ。', 'Cô ấy là người phụ nữ trưởng thành điềm tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12033, 42489, '彼の頼みなら断れない。', 'かれの たのみなら ことわれない。', 'Nếu anh ấy nhờ thì tôi không từ chối được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12034, 42473, 'ご用件をお伺いします。', 'ごようけんを おうかがい します。', 'Xin cho biết quý khách cần việc gì ạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12035, 38568, '二階建ての家に住んでいます。', 'にかいだての いえに すんで います。', 'Tôi sống trong ngôi nhà hai tầng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12036, 38592, '夜になって、冷えてきました。', 'よるに なって、ひえて きました。', 'Về đêm trời trở lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12037, 38590, '肉も魚も両方好きです。', 'にくも さかなも りょうほう すき です。', 'Thịt hay cá tôi đều thích cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12038, 31063, '世界の恒久平和を願う。', 'せかいの こうきゅう へいわを ねがう。', 'Tôi cầu mong hòa bình lâu dài cho thế giới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12039, 47952, 'これは環境保護活動の一環です。', 'これは かんきょう ほご かつどうの いっかん です。', 'Đây là một phần của hoạt động bảo vệ môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12040, 31065, '安全管理を徹底してください。', 'あんぜん かんりを てってい して ください。', 'Hãy quản lý an toàn một cách triệt để.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12041, 31067, '他人の失敗に寛容でありたい。', 'たにんの しっぱいに かんようで ありたい。', 'Tôi muốn khoan dung với thất bại của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12042, 31069, 'これはあくまで私個人の意見です。', 'これは あくまで わたし こじんの いけん です。', 'Đây chỉ là ý kiến cá nhân tôi thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12043, 31070, '行きたいのだが、いかんせん時間がない。', 'いきたいの だが、いかんせん じかんが ない。', 'Tôi muốn đi lắm nhưng khổ nỗi không có thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12044, 31195, '必要な費用を算出した。', 'ひつような ひようを さんしゅつ した。', 'Tôi đã tính ra chi phí cần thiết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12045, 31197, '防犯カメラで駐車場を監視している。', 'ぼうはん カメラで ちゅうしゃじょうを かんし して いる。', 'Bãi đỗ xe được giám sát bằng camera an ninh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12046, 31201, 'この作品は精緻な技術で作られている。', 'この さくひんは せいちな ぎじゅつで つくられて いる。', 'Tác phẩm này được làm bằng kỹ thuật tinh xảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12047, 31204, '先生の説明の意図を領会した。', 'せんせいの せつめいの いとを りょうかい した。', 'Tôi đã lĩnh hội được ý đồ trong lời giải thích của thầy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12048, 31205, '彼は人間の心理を鋭く洞察している。', 'かれは にんげんの しんりを するどく どうさつ して いる。', 'Ông ấy thấu hiểu tâm lý con người một cách sắc bén.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12049, 31208, '彼の着眼はいつも鋭い。', 'かれの ちゃくがんは いつも するどい。', 'Cách nhìn nhận vấn đề của anh ấy luôn sắc sảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12050, 31210, '彼の質問は問題の核心をついていた。', 'かれの しつもんは もんだいの かくしんを ついて いた。', 'Câu hỏi của anh ấy đã chạm đúng cốt lõi vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12051, 31243, '既成の考え方にとらわれてはいけない。', 'きせいの かんがえかたに とらわれては いけない。', 'Không nên bị trói buộc bởi lối nghĩ có sẵn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12052, 31246, 'すべての問題の根源は不信感にある。', 'すべての もんだいの こんげんは ふしんかんに ある。', 'Cội nguồn của mọi vấn đề nằm ở sự thiếu tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12053, 31248, '寒さで手足の末端が冷える。', 'さむさで てあしの まったんが ひえる。', 'Trời lạnh làm đầu ngón tay ngón chân lạnh buốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12054, 42509, 'この映画は立体映像で見られる。', 'この えいがは りったい えいぞうで みられる。', 'Bộ phim này có thể xem dưới dạng hình ảnh ba chiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12055, 42510, '国会は唯一の立法機関だ。', 'こっかいは ゆいいつの りっぽう きかんだ。', 'Quốc hội là cơ quan lập pháp duy nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12056, 42514, '食べ終わった食器を流しに置いた。', 'たべおわった しょっきを ながしに おいた。', 'Tôi đặt bát đĩa ăn xong vào bồn rửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12057, 42518, '旅客機が空港に着陸した。', 'りょかくきが くうこうに ちゃくりく した。', 'Máy bay chở khách đã hạ cánh xuống sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12058, 42507, '彼は百人の部隊を率いた。', 'かれは ひゃくにんの ぶたいを ひきいた。', 'Ông ấy chỉ huy đội quân trăm người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12059, 42517, '道に水溜まりができている。', 'みちに みずたまりが できて いる。', 'Trên đường có vũng nước đọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12060, 30957, '子供に「時間」という概念を教えるのは難しい。', 'こどもに 「じかん」と いう がいねんを おしえるのは むずかしい。', 'Dạy trẻ khái niệm "thời gian" thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12061, 30962, '彼には時間の観念がまったくない。', 'かれには じかんの かんねんが まったく ない。', 'Anh ta hoàn toàn không có khái niệm về thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12062, 30964, 'ボランティア活動には大きな意義がある。', 'ボランティア かつどうには おおきな いぎが ある。', 'Hoạt động tình nguyện có ý nghĩa to lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12063, 30965, 'この会の趣旨を説明させていただきます。', 'この かいの しゅしを せつめい させて いただきます。', 'Xin phép được giải thích tôn chỉ của buổi gặp này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12064, 30988, '彼の表情から気持ちを推測した。', 'かれの ひょうじょうから きもちを すいそく した。', 'Tôi đoán tâm trạng anh ấy qua nét mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12065, 30990, '適度な運動は血液の循環を促進する。', 'てきどな うんどうは けつえきの じゅんかんを そくしん する。', 'Vận động vừa phải giúp thúc đẩy tuần hoàn máu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12066, 30995, '新しい治療法が確立された。', 'あたらしい ちりょうほうが かくりつ された。', 'Một phương pháp điều trị mới đã được xác lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12067, 30999, '大雨のため、試合は一時中断された。', 'おおあめの ため、しあいは いちじ ちゅうだん された。', 'Do mưa lớn, trận đấu tạm thời bị gián đoạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12068, 31001, '会社は経営方針を大きく転換した。', 'かいしゃは けいえい ほうしんを おおきく てんかん した。', 'Công ty đã chuyển đổi mạnh phương châm kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12069, 31004, '男女の賃金格差を是正すべきだ。', 'だんじょの ちんぎん かくさを ぜせい すべきだ。', 'Cần điều chỉnh chênh lệch tiền lương giữa nam và nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12070, 31009, '景気の悪化が懸念されている。', 'けいきの あっかが けねん されて いる。', 'Người ta lo ngại kinh tế sẽ xấu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12071, 30968, '建前ではなく、正直な意見を聞かせてほしい。', 'たてまえでは なく、しょうじきな いけんを きかせて ほしい。', 'Tôi muốn nghe ý kiến thật, không phải lời khách sáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12072, 30970, '固定観念にとらわれず、自由に考えよう。', 'こてい かんねんに とらわれず、じゆうに かんがえよう。', 'Hãy suy nghĩ tự do, đừng bị định kiến trói buộc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12073, 30977, '両国の間で貿易摩擦が起きている。', 'りょうこくの あいだで ぼうえき まさつが おきて いる。', 'Giữa hai nước đang xảy ra xích mích thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12074, 31010, 'スマホの使いすぎには弊害もある。', 'スマホの つかいすぎには へいがいも ある。', 'Dùng điện thoại quá nhiều cũng có tác hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12075, 31012, '話し合いで事態の打開を図った。', 'はなしあいで じたいの だかいを はかった。', 'Chúng tôi tìm cách phá vỡ bế tắc bằng đối thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12076, 31017, '十年ぶりに母校を訪れ、感慨にふけった。', 'じゅうねんぶりに ぼこうを おとずれ、かんがいに ふけった。', 'Sau mười năm thăm lại trường cũ, tôi chìm trong nỗi niềm cảm khái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12077, 42542, 'あの連中とは付き合わないほうがいい。', 'あの れんじゅうとは つきあわない ほうが いい。', 'Không nên giao du với đám người đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12078, 42554, '老いても元気でいたい。', 'おいても げんきで いたい。', 'Dù có già đi tôi vẫn muốn khỏe mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12079, 42533, '犯人は冷酷な人間だった。', 'はんにんは れいこくな にんげん だった。', 'Hung thủ là một kẻ tàn nhẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12080, 42538, '彼は一目で彼女に恋した。', 'かれは ひとめで かのじょに こいした。', 'Anh ấy phải lòng cô ấy ngay từ cái nhìn đầu tiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12081, 42233, '被災地に救援物資が届いた。', 'ひさいちに きゅうえん ぶっしが とどいた。', 'Hàng cứu trợ đã đến vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12082, 42531, '前後の文脈から意味を類推した。', 'ぜんごの ぶんみゃくから いみを るいすい した。', 'Tôi đã suy ra nghĩa từ ngữ cảnh trước sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12083, 42556, 'その問題については十分な論議が必要だ。', 'その もんだいに ついては じゅうぶんな ろんぎが ひつようだ。', 'Vấn đề đó cần được bàn luận kỹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12084, 31019, 'この町には江戸時代の名残がある。', 'この まちには えど じだいの なごりが ある。', 'Thị trấn này còn lưu lại dấu vết thời Edo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12085, 31020, '衝動に駆られて、高い服を買ってしまった。', 'しょうどうに かられて、たかい ふくを かって しまった。', 'Bốc đồng nên tôi lỡ mua bộ quần áo đắt tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12086, 31022, '彼は友人の成功に嫉妬した。', 'かれは ゆうじんの せいこうに しっと した。', 'Anh ta ghen tị với thành công của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12087, 31024, '主人公の苦悩が丁寧に描かれている。', 'しゅじんこうの くのうが ていねいに えがかれて いる。', 'Nỗi khổ tâm của nhân vật chính được miêu tả tỉ mỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12088, 31027, '社会人としての心構えを教わった。', 'しゃかいじんと しての こころがまえを おそわった。', 'Tôi được dạy về tâm thế của một người đi làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12089, 31029, '彼は会社を辞める決意をした。', 'かれは かいしゃを やめる けついを した。', 'Anh ấy đã quyết ý nghỉ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12090, 31031, 'この仕事に誇りを持っている。', 'この しごとに ほこりを もって いる。', 'Tôi tự hào về công việc này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12091, 31032, 'すべての人の尊厳は守られるべきだ。', 'すべての ひとの そんげんは まもられる べきだ。', 'Phẩm giá của mọi người cần được bảo vệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12092, 31034, '彼こそリーダーにふさわしい人だ。', 'かれこそ リーダーに ふさわしい ひとだ。', 'Chính anh ấy là người xứng đáng làm lãnh đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12093, 31037, 'この二つの漢字は形が紛らわしい。', 'この ふたつの かんじは かたちが まぎらわしい。', 'Hai chữ Hán này có hình dạng dễ nhầm lẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12094, 31039, '準備不足だったことは否めない。', 'じゅんび ぶそく だった ことは いなめない。', 'Không thể phủ nhận là đã chuẩn bị chưa đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12095, 31041, '私の予想はことごとく外れた。', 'わたしの よそうは ことごとく はずれた。', 'Dự đoán của tôi trật lất hết thảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12096, 31043, 'もはや手遅れだ。', 'もはや ておくれだ。', 'Giờ đây đã quá muộn rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12097, 31045, '今年の夏はとりわけ暑い。', 'ことしの なつは とりわけ あつい。', 'Mùa hè năm nay đặc biệt nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12098, 31046, '努力を続ければ、結果はおのずとついてくる。', 'どりょくを つづければ、けっかは おのずと ついて くる。', 'Cứ nỗ lực mãi thì kết quả tự khắc sẽ đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12099, 31050, 'この川が二つの県の境界になっている。', 'この かわが ふたつの けんの きょうかいに なって いる。', 'Con sông này là ranh giới giữa hai tỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12100, 31052, '彼の意見は少し極端だ。', 'かれの いけんは すこし きょくたんだ。', 'Ý kiến của anh ấy hơi cực đoan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12101, 31055, 'この辞書は専門用語を網羅している。', 'この じしょは せんもん ようごを もうら して いる。', 'Cuốn từ điển này bao quát hết thuật ngữ chuyên môn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12102, 42564, '地球は太陽系の惑星の一つだ。', 'ちきゅうは たいようけいの わくせいの ひとつだ。', 'Trái đất là một trong các hành tinh của hệ Mặt trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12103, 42565, '遅れたお詫びに、お菓子を持って行った。', 'おくれた おわびに、おかしを もって いった。', 'Tôi mang bánh đến để tạ lỗi vì đến muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12104, 42571, '彼は「疲れた」と小さく呟いた。', 'かれは 「つかれた」と ちいさく つぶやいた。', 'Anh ấy lẩm bẩm "mệt quá".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12105, 42567, '彼の料理の腕前はプロ並みだ。', 'かれの りょうりの うでまえは プロなみだ。', 'Tay nghề nấu ăn của anh ấy ngang dân chuyên nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12106, 42566, '溺れる者は藁をもつかむ。', 'おぼれる ものは わらをも つかむ。', 'Người chết đuối vớ được cọng rơm cũng bám.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12107, 42572, '咄嗟にブレーキを踏んだ。', 'とっさに ブレーキを ふんだ。', 'Tôi đạp phanh ngay tức thì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12108, 42562, '地震で窓枠が歪んだ。', 'じしんで まどわくが ゆがんだ。', 'Do động đất, khung cửa sổ bị cong vênh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12109, 42559, '和風の庭園でお茶を飲んだ。', 'わふうの ていえんで おちゃを のんだ。', 'Tôi uống trà trong khu vườn kiểu Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12110, 31058, 'この規則に例外は認められない。', 'この きそくに れいがいは みとめられない。', 'Quy tắc này không chấp nhận ngoại lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12111, 31060, '会議の後で食事をするのが慣例になっている。', 'かいぎの あとで しょくじを するのが かんれいに なって いる。', 'Ăn cùng nhau sau cuộc họp đã thành thông lệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12112, 37851, '一瞬、夢を見ているような錯覚に陥った。', 'いっしゅん、ゆめを みて いる ような さっかくに おちいった。', 'Trong khoảnh khắc, tôi có ảo giác như đang mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12113, 47947, '計画をもっと具体化してください。', 'けいかくを もっと ぐたいか して ください。', 'Hãy cụ thể hóa kế hoạch hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12114, 41860, '社会の秩序を守るために法律がある。', 'しゃかいの ちつじょを まもる ために ほうりつが ある。', 'Pháp luật tồn tại để giữ gìn trật tự xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12115, 37845, 'あらゆる差別を排除すべきだ。', 'あらゆる さべつを はいじょ すべきだ。', 'Cần loại trừ mọi sự phân biệt đối xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12116, 40994, '材料を吟味して料理を作る。', 'ざいりょうを ぎんみ して りょうりを つくる。', 'Tôi lựa chọn kỹ nguyên liệu rồi mới nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12117, 47948, '問題の本質を見極めることが大切だ。', 'もんだいの ほんしつを みきわめる ことが たいせつだ。', 'Nhận rõ bản chất vấn đề là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12118, 31176, '余剰の食料を困っている人に配った。', 'よじょうの しょくりょうを こまって いる ひとに くばった。', 'Lương thực dư thừa được phát cho người gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12119, 31178, 'この地区には富裕な家庭が多い。', 'この ちくには ふゆうな かていが おおい。', 'Khu vực này có nhiều gia đình giàu có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12120, 31180, '物価の上昇が家計を圧迫している。', 'ぶっかの じょうしょうが かけいを あっぱく して いる。', 'Giá cả tăng đang gây sức ép lên chi tiêu gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12121, 31185, '医者に言われて、お酒を控えている。', 'いしゃに いわれて、おさけを ひかえて いる。', 'Theo lời bác sĩ, tôi đang hạn chế rượu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12122, 31189, '割り算の剰余を求めなさい。', 'わりざんの じょうよを もとめなさい。', 'Hãy tìm số dư của phép chia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12123, 31211, 'この地方には珍しい風習が残っている。', 'この ちほうには めずらしい ふうしゅうが のこって いる。', 'Vùng này còn lưu giữ những phong tục lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12124, 31728, 'この絵は抽象的でよくわからない。', 'この えは ちゅうしょうてきで よく わからない。', 'Bức tranh này trừu tượng, tôi không hiểu lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12125, 37890, '景気回復の兆しが見えてきた。', 'けいき かいふくの きざしが みえて きた。', 'Đã thấy dấu hiệu phục hồi kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12126, 41107, '一人暮らしの高齢者が孤立しないよう支援する。', 'ひとりぐらしの こうれいしゃが こりつ しない よう しえん する。', 'Hỗ trợ để người cao tuổi sống một mình không bị cô lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12127, 47951, '景気回復の兆しが見えてきた。', 'けいき かいふくの きざしが みえて きた。', 'Đã thấy dấu hiệu phục hồi kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12128, 31215, '先輩に敬意を払うのは当然だ。', 'せんぱいに けいいを はらうのは とうぜんだ。', 'Kính trọng đàn anh là điều đương nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12129, 42582, '足の裏を触られるとくすぐったい。', 'あしの うらを さわられると くすぐったい。', 'Bị chạm vào lòng bàn chân thì thấy nhột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12131, 42599, '新しい靴で踵が痛い。', 'あたらしい くつで かかとが いたい。', 'Đi giày mới nên đau gót chân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12132, 42604, '手を洗って黴菌を落とそう。', 'てを あらって ばいきんを おとそう。', 'Hãy rửa tay để loại bỏ vi khuẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12133, 42583, '梅雨は毎日雨で鬱陶しい。', 'つゆは まいにち あめで うっとうしい。', 'Mùa mưa ngày nào cũng mưa, thật khó chịu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12134, 42602, '彼の長い話には辟易した。', 'かれの ながい はなしには へきえき した。', 'Tôi ngán ngẩm với câu chuyện dài dòng của anh ta.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12135, 31015, '来月から新しいプロジェクトに着手する。', 'らいげつから あたらしい プロジェクトに ちゃくしゅ する。', 'Từ tháng sau sẽ bắt tay vào dự án mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12136, 31218, '彼の親切は偽善にすぎない。', 'かれの しんせつは ぎぜんに すぎない。', 'Sự tử tế của anh ta chẳng qua là đạo đức giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12137, 47954, '彼女のレポートは着眼点がおもしろい。', 'かのじょの レポートは ちゃくがんてんが おもしろい。', 'Bản báo cáo của cô ấy có điểm nhìn thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12138, 47955, '彼は人間の心理を鋭く洞察している。', 'かれは にんげんの しんりを するどく どうさつ して いる。', 'Ông ấy thấu hiểu tâm lý con người một cách sắc bén.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12139, 47956, '彼は経済について高い見識を持っている。', 'かれは けいざいに ついて たかい けんしきを もって いる。', 'Ông ấy có hiểu biết sâu sắc về kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12140, 47525, 'この地方には珍しい風習が残っている。', 'この ちほうには めずらしい ふうしゅうが のこって いる。', 'Vùng này còn lưu giữ những phong tục lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12141, 47526, '古い慣習を見直す時期に来ている。', 'ふるい かんしゅうを みなおす じきに きて いる。', 'Đã đến lúc xem xét lại những tập quán cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12142, 47957, '一瞬、夢を見ているような錯覚に陥った。', 'いっしゅん、ゆめを みて いる ような さっかくに おちいった。', 'Trong khoảnh khắc, tôi có ảo giác như đang mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12143, 47958, '彼の話には誇張が多い。', 'かれの はなしには こちょうが おおい。', 'Câu chuyện của anh ta có nhiều phóng đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12144, 47209, '子供に「時間」という概念を教えるのは難しい。', 'こどもに 「じかん」と いう がいねんを おしえるのは むずかしい。', 'Dạy trẻ khái niệm "thời gian" thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12145, 47211, '子供の視点から町を見直してみよう。', 'こどもの してんから まちを みなおして みよう。', 'Hãy thử nhìn lại thành phố từ góc nhìn của trẻ em.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12146, 47214, '彼の話は論理が通っていない。', 'かれの はなしは ろんりが とおって いない。', 'Câu chuyện của anh ta không hợp logic.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12147, 47216, '彼の表情から気持ちを推測した。', 'かれの ひょうじょうから きもちを すいそく した。', 'Tôi đoán tâm trạng anh ấy qua nét mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12148, 47218, '実験の結果について考察した。', 'じっけんの けっかに ついて こうさつ した。', 'Tôi đã suy xét về kết quả thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12149, 47220, '材料を吟味して料理を作る。', 'ざいりょうを ぎんみ して りょうりを つくる。', 'Tôi lựa chọn kỹ nguyên liệu rồi mới nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12150, 47223, 'この計画の妥当性を検討する。', 'この けいかくの だとうせいを けんとう する。', 'Chúng tôi xem xét tính hợp lý của kế hoạch này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12151, 47224, '主観と客観を区別して考えよう。', 'しゅかんと きゃっかんを くべつ して かんがえよう。', 'Hãy suy nghĩ có phân biệt chủ quan và khách quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12152, 47226, 'この絵は抽象的でよくわからない。', 'この えは ちゅうしょうてきで よく わからない。', 'Bức tranh này trừu tượng, tôi không hiểu lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12153, 47228, '問題の本質を見極めることが大切だ。', 'もんだいの ほんしつを みきわめる ことが たいせつだ。', 'Nhận rõ bản chất vấn đề là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12154, 47231, '景気回復の兆しが見えてきた。', 'けいき かいふくの きざしが みえて きた。', 'Đã thấy dấu hiệu phục hồi kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12155, 47234, '彼女のレポートは着眼点がおもしろい。', 'かのじょの レポートは ちゃくがんてんが おもしろい。', 'Bản báo cáo của cô ấy có điểm nhìn thú vị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12156, 47235, '彼は人間の心理を鋭く洞察している。', 'かれは にんげんの しんりを するどく どうさつ して いる。', 'Ông ấy thấu hiểu tâm lý con người một cách sắc bén.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12157, 47237, '一瞬、夢を見ているような錯覚に陥った。', 'いっしゅん、ゆめを みて いる ような さっかくに おちいった。', 'Trong khoảnh khắc, tôi có ảo giác như đang mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12158, 47242, 'その政策の是非をめぐって議論が続いている。', 'その せいさくの ぜひを めぐって ぎろんが つづいて いる。', 'Cuộc tranh luận về đúng sai của chính sách đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12159, 47705, '警察は治安維持に努めている。', 'けいさつは ちあん いじに つとめて いる。', 'Cảnh sát đang nỗ lực giữ gìn an ninh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12160, 47243, '若者はみんな本を読まないとは一概には言えない。', 'わかものは みんな ほんを よまないとは いちがいには いえない。', 'Không thể vơ đũa cả nắm rằng giới trẻ đều không đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12161, 47246, '彼はこの店の、いわば顔のような存在だ。', 'かれは この みせの、いわば かおの ような そんざいだ。', 'Anh ấy có thể nói là gương mặt đại diện của cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12162, 47248, '休日はもっぱら家で本を読んでいる。', 'きゅうじつは もっぱら いえで ほんを よんで いる。', 'Ngày nghỉ tôi chủ yếu ở nhà đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12163, 47250, '本物かどうかを見極めるのは難しい。', 'ほんもの か どうかを みきわめるのは むずかしい。', 'Nhận định rõ đâu là đồ thật thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12164, 47252, '連絡がない場合は、欠席と見なします。', 'れんらくが ない ばあいは、けっせきと みなします。', 'Trường hợp không liên lạc sẽ bị coi là vắng mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12165, 47254, '彼は仕事に生きがいを見出した。', 'かれは しごとに いきがいを みいだした。', 'Anh ấy tìm ra lẽ sống trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12166, 47255, 'その説を裏付けるデータが見つかった。', 'その せつを うらづける データが みつかった。', 'Đã tìm thấy dữ liệu chứng thực giả thuyết đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12167, 47257, '彼はその計画に異議を唱えた。', 'かれは その けいかくに いぎを となえた。', 'Ông ấy lên tiếng phản đối kế hoạch đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12168, 47260, '彼の責任は明白だ。', 'かれの せきにんは めいはくだ。', 'Trách nhiệm của anh ta là rõ ràng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12169, 47262, '妥協的な解決策が採用された。', 'だきょうてきな かいけつさくが さいよう された。', 'Một giải pháp mang tính thỏa hiệp đã được chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12170, 47264, '根本的な解決にはまだ時間がかかる。', 'こんぽんてきな かいけつには まだ じかんが かかる。', 'Giải quyết tận gốc vẫn còn cần thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12171, 47267, 'この二つの漢字は形が紛らわしい。', 'この ふたつの かんじは かたちが まぎらわしい。', 'Hai chữ Hán này có hình dạng dễ nhầm lẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12172, 47270, '経営者は社員の生活を守る責任がある。', 'けいえいしゃは しゃいんの せいかつを まもる せきにんが ある。', 'Người quản lý có trách nhiệm bảo vệ đời sống nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12173, 47273, 'その会社は海外にも事業を展開している。', 'その かいしゃは かいがいにも じぎょうを てんかい して いる。', 'Công ty đó cũng đang triển khai kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12174, 47275, '会社は赤字の事業から撤退した。', 'かいしゃは あかじの じぎょうから てったい した。', 'Công ty đã rút khỏi mảng kinh doanh thua lỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12175, 47279, '商品の配送を外部に委託している。', 'しょうひんの はいそうを がいぶに いたく して いる。', 'Việc giao hàng được ủy thác cho bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12176, 47284, '新しい事業が大きな収益を上げた。', 'あたらしい じぎょうが おおきな しゅうえきを あげた。', 'Mảng kinh doanh mới đã mang lại lợi nhuận lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12177, 47286, '店は三年間赤字経営が続いている。', 'みせは さんねんかん あかじ けいえいが つづいて いる。', 'Cửa hàng đã kinh doanh thua lỗ suốt ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12178, 47287, '経費削減のため、出張が減らされた。', 'けいひ さくげんの ため、しゅっちょうが へらされた。', 'Để cắt giảm chi phí, các chuyến công tác đã bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12179, 47288, '人件費が経営を圧迫している。', 'じんけんひが けいえいを あっぱく して いる。', 'Chi phí nhân sự đang gây áp lực lên việc kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12180, 47290, '景気の見通しは明るい。', 'けいきの みとおしは あかるい。', 'Triển vọng kinh tế rất sáng sủa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12181, 47293, '新社長は組織の刷新を進めている。', 'しん しゃちょうは そしきの さっしんを すすめて いる。', 'Tân giám đốc đang tiến hành đổi mới toàn diện tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12182, 47295, '二つの部署が統合された。', 'ふたつの ぶしょが とうごう された。', 'Hai phòng ban đã được hợp nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12183, 47298, 'この件は部長の決裁が必要だ。', 'この けんは ぶちょうの けっさいが ひつようだ。', 'Việc này cần trưởng phòng phê duyệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12184, 47299, '新しいパソコンの購入について稟議を出した。', 'あたらしい パソコンの こうにゅうに ついて りんぎを だした。', 'Tôi đã trình tờ xin duyệt việc mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12185, 47301, '彼は営業部長と企画部長を兼任している。', 'かれは えいぎょう ぶちょうと きかく ぶちょうを けんにん して いる。', 'Anh ấy kiêm nhiệm trưởng phòng kinh doanh và trưởng phòng kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12186, 47303, '彼はミスの責任を取らされ、地方へ左遷された。', 'かれは ミスの せきにんを とらされ、ちほうへ させん された。', 'Anh ấy bị bắt chịu trách nhiệm lỗi sai và bị điều về địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12187, 47306, '労使の話し合いで賃上げが決まった。', 'ろうしの はなしあいで ちんあげが きまった。', 'Qua thương lượng giữa chủ và thợ, việc tăng lương đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12188, 47307, '彼は退職後、会社の顧問になった。', 'かれは たいしょくご、かいしゃの こもんに なった。', 'Sau khi nghỉ hưu ông ấy trở thành cố vấn công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12189, 47309, '友人の新しい事業に出資した。', 'ゆうじんの あたらしい じぎょうに しゅっし した。', 'Tôi đã góp vốn vào công việc kinh doanh mới của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12190, 47311, 'その銀行は経営が破綻した。', 'その ぎんこうは けいえいが はたん した。', 'Ngân hàng đó đã đổ vỡ kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12191, 47312, '新しい社長が会社を立て直した。', 'あたらしい しゃちょうが かいしゃを たてなおした。', 'Giám đốc mới đã vực dậy công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12192, 47314, '視聴率が低く、番組は打ち切られた。', 'しちょうりつが ひくく、ばんぐみは うちきられた。', 'Tỷ lệ người xem thấp nên chương trình đã bị dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12193, 47316, 'アルバイトで生活費を賄っている。', 'アルバイトで せいかつひを まかなって いる。', 'Tôi trang trải sinh hoạt phí bằng việc làm thêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12194, 47318, '若者が国の未来を担っている。', 'わかものが くにの みらいを になって いる。', 'Giới trẻ đang gánh vác tương lai đất nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12195, 47320, '今年は売り上げの増加が見込まれる。', 'ことしは うりあげの ぞうかが みこまれる。', 'Năm nay dự tính doanh thu sẽ tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12196, 47321, '工事の費用を見積もってもらった。', 'こうじの ひようを みつもって もらった。', 'Tôi đã nhờ ước tính chi phí thi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12197, 47323, '日本の会社の多くは中小企業だ。', 'にほんの かいしゃの おおくは ちゅうしょう きぎょうだ。', 'Phần lớn công ty ở Nhật là doanh nghiệp vừa và nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12198, 47325, '会議は円滑に進んだ。', 'かいぎは えんかつに すすんだ。', 'Cuộc họp diễn ra suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12199, 47327, 'この問題は慎重に扱う必要がある。', 'この もんだいは しんちょうに あつかう ひつようが ある。', 'Vấn đề này cần được xử lý thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12200, 47331, '新しい内閣が発足した。', 'あたらしい ないかくが ほっそく した。', 'Nội các mới đã được thành lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12201, 47332, '閣僚の一人が辞任した。', 'かくりょうの ひとりが じにん した。', 'Một thành viên nội các đã từ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12202, 47334, '市長が汚職の疑いで逮捕された。', 'しちょうが おしょくの うたがいで たいほ された。', 'Thị trưởng bị bắt vì nghi tham nhũng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12203, 47335, '役人が賄賂を受け取ったことが発覚した。', 'やくにんが わいろを うけとった ことが はっかく した。', 'Đã phát hiện việc quan chức nhận hối lộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12204, 47337, '会社は事故を隠蔽しようとした。', 'かいしゃは じこを いんぺい しようと した。', 'Công ty đã tìm cách che giấu tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12205, 47340, '長い裁判の末、両者は和解した。', 'ながい さいばんの すえ、りょうしゃは わかい した。', 'Sau phiên tòa kéo dài, hai bên đã hòa giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12206, 47343, '医者には高い倫理観が必要だ。', 'いしゃには たかい りんりかんが ひつようだ。', 'Bác sĩ cần có ý thức đạo đức cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12207, 47344, '社会の秩序を守るために法律がある。', 'しゃかいの ちつじょを まもる ために ほうりつが ある。', 'Pháp luật tồn tại để giữ gìn trật tự xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12208, 47346, '過疎の村では学校がなくなっている。', 'かその むらでは がっこうが なくなって いる。', 'Ở những ngôi làng thưa dân, trường học đang biến mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12209, 47348, '都市部では待機児童が多い。', 'としぶでは たいき じどうが おおい。', 'Ở thành thị có nhiều trẻ phải chờ vào nhà trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12210, 40379, '石けん水はアルカリ性だ。', 'せっけんすいは アルカリせいだ。', 'Nước xà phòng có tính kiềm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12211, 47351, '一人暮らしの高齢者が孤立しないよう支援する。', 'ひとりぐらしの こうれいしゃが こりつ しない よう しえん する。', 'Hỗ trợ để người cao tuổi sống một mình không bị cô lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12212, 47354, '社会の多様性を認めることが大切だ。', 'しゃかいの たようせいを みとめる ことが たいせつだ。', 'Công nhận tính đa dạng của xã hội là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12213, 47355, '外国人との共生を目指す町づくりが進んでいる。', 'がいこくじんとの きょうせいを めざす まちづくりが すすんで いる。', 'Việc xây dựng thị trấn hướng tới chung sống với người nước ngoài đang được đẩy mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12214, 47358, '会議は予算をめぐって紛糾した。', 'かいぎは よさんを めぐって ふんきゅう した。', 'Cuộc họp trở nên rối ren xung quanh vấn đề ngân sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12215, 47370, '男女の賃金格差を是正すべきだ。', 'だんじょの ちんぎん かくさを ぜせい すべきだ。', 'Cần điều chỉnh chênh lệch tiền lương giữa nam và nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12216, 47376, '今年は売り上げの増加が顕著だ。', 'ことしは うりあげの ぞうかが けんちょだ。', 'Năm nay doanh thu tăng rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12217, 47395, '月曜日の朝はいつも憂鬱だ。', 'げつようびの あさは いつも ゆううつだ。', 'Sáng thứ Hai lúc nào cũng u uất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12218, 47402, '私たちは科学技術の恩恵を受けている。', 'わたしたちは かがく ぎじゅつの おんけいを うけて いる。', 'Chúng ta đang hưởng lợi ích từ khoa học kỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12219, 47403, '別れた恋人にまだ未練がある。', 'わかれた こいびとに まだ みれんが ある。', 'Tôi vẫn còn lưu luyến người yêu cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12220, 47407, '他人の失敗に寛容でありたい。', 'たにんの しっぱいに かんようで ありたい。', 'Tôi muốn khoan dung với thất bại của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12221, 47444, '彼は合格のためにひたすら勉強した。', 'かれは ごうかくの ために ひたすら べんきょう した。', 'Anh ấy chỉ một mực học để thi đỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12222, 47461, '科学者は真理を探究し続けている。', 'かがくしゃは しんりを たんきゅう し つづけて いる。', 'Các nhà khoa học không ngừng tìm tòi chân lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12223, 47484, '両国の間で貿易摩擦が起きている。', 'りょうこくの あいだで ぼうえき まさつが おきて いる。', 'Giữa hai nước đang xảy ra xích mích thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12224, 47498, 'この辞書は専門用語を網羅している。', 'この じしょは せんもん ようごを もうら して いる。', 'Cuốn từ điển này bao quát hết thuật ngữ chuyên môn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12225, 47569, '子供に「時間」という概念を教えるのは難しい。', 'こどもに 「じかん」と いう がいねんを おしえるのは むずかしい。', 'Dạy trẻ khái niệm "thời gian" thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12226, 47573, 'その主張には科学的な根拠がない。', 'その しゅちょうには かがくてきな こんきょが ない。', 'Lập luận đó không có căn cứ khoa học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12227, 47575, '彼の説明には矛盾がある。', 'かれの せつめいには むじゅんが ある。', 'Lời giải thích của anh ta có mâu thuẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12228, 47577, 'データから一つの結論を推論した。', 'データから ひとつの けつろんを すいろん した。', 'Từ dữ liệu, chúng tôi suy luận ra một kết luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12229, 47578, '実験の結果について考察した。', 'じっけんの けっかに ついて こうさつ した。', 'Tôi đã suy xét về kết quả thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12230, 47581, '二人の間には見解の相違がある。', 'ふたりの あいだには けんかいの そういが ある。', 'Giữa hai người có sự khác biệt về quan điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12231, 47584, '主観と客観を区別して考えよう。', 'しゅかんと きゃっかんを くべつ して かんがえよう。', 'Hãy suy nghĩ có phân biệt chủ quan và khách quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12232, 47585, 'これは私の主観ですが、彼は信頼できます。', 'これは わたしの しゅかん ですが、かれは しんらい できます。', 'Đây là cảm nhận chủ quan của tôi, nhưng anh ấy đáng tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12233, 47587, '計画をもっと具体化してください。', 'けいかくを もっと ぐたいか して ください。', 'Hãy cụ thể hóa kế hoạch hơn nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12234, 47591, '景気回復の兆しが見えてきた。', 'けいき かいふくの きざしが みえて きた。', 'Đã thấy dấu hiệu phục hồi kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12235, 47592, 'これは環境保護活動の一環です。', 'これは かんきょう ほご かつどうの いっかん です。', 'Đây là một phần của hoạt động bảo vệ môi trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12236, 47595, '彼は人間の心理を鋭く洞察している。', 'かれは にんげんの しんりを するどく どうさつ して いる。', 'Ông ấy thấu hiểu tâm lý con người một cách sắc bén.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12237, 47597, '一瞬、夢を見ているような錯覚に陥った。', 'いっしゅん、ゆめを みて いる ような さっかくに おちいった。', 'Trong khoảnh khắc, tôi có ảo giác như đang mơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12238, 47598, '彼の話には誇張が多い。', 'かれの はなしには こちょうが おおい。', 'Câu chuyện của anh ta có nhiều phóng đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12239, 47602, 'その政策の是非をめぐって議論が続いている。', 'その せいさくの ぜひを めぐって ぎろんが つづいて いる。', 'Cuộc tranh luận về đúng sai của chính sách đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12240, 47604, 'あえて難しい道を選んだ。', 'あえて むずかしい みちを えらんだ。', 'Tôi cố tình chọn con đường khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12241, 47605, '彼は天才というより、むしろ努力家だ。', 'かれは てんさいと いうより、むしろ どりょくかだ。', 'Anh ấy không hẳn là thiên tài mà đúng hơn là người chăm chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12242, 47608, '休日はもっぱら家で本を読んでいる。', 'きゅうじつは もっぱら いえで ほんを よんで いる。', 'Ngày nghỉ tôi chủ yếu ở nhà đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12243, 47609, '彼は家庭を顧みずに働き続けた。', 'かれは かていを かえりみずに はたらき つづけた。', 'Anh ấy làm việc liên tục mà chẳng đoái hoài đến gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12244, 47611, '前回の反省を踏まえて、計画を立てた。', 'ぜんかいの はんせいを ふまえて、けいかくを たてた。', 'Chúng tôi lập kế hoạch dựa trên bài học lần trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12245, 47613, '大事な点を見落としていた。', 'だいじな てんを みおとして いた。', 'Tôi đã bỏ sót một điểm quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12246, 47615, 'その説を裏付けるデータが見つかった。', 'その せつを うらづける データが みつかった。', 'Đã tìm thấy dữ liệu chứng thực giả thuyết đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12247, 47617, '彼はその計画に異議を唱えた。', 'かれは その けいかくに いぎを となえた。', 'Ông ấy lên tiếng phản đối kế hoạch đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12248, 47618, '自分の行動を省みて、反省した。', 'じぶんの こうどうを かえりみて、はんせい した。', 'Tôi tự xét lại hành động của mình và kiểm điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12249, 47622, '妥協的な解決策が採用された。', 'だきょうてきな かいけつさくが さいよう された。', 'Một giải pháp mang tính thỏa hiệp đã được chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12250, 47624, '根本的な解決にはまだ時間がかかる。', 'こんぽんてきな かいけつには まだ じかんが かかる。', 'Giải quyết tận gốc vẫn còn cần thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12251, 47627, 'この二つの漢字は形が紛らわしい。', 'この ふたつの かんじは かたちが まぎらわしい。', 'Hai chữ Hán này có hình dạng dễ nhầm lẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12252, 47630, '経営者は社員の生活を守る責任がある。', 'けいえいしゃは しゃいんの せいかつを まもる せきにんが ある。', 'Người quản lý có trách nhiệm bảo vệ đời sống nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12253, 47633, 'その会社は海外にも事業を展開している。', 'その かいしゃは かいがいにも じぎょうを てんかい して いる。', 'Công ty đó cũng đang triển khai kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12254, 47635, '会社は赤字の事業から撤退した。', 'かいしゃは あかじの じぎょうから てったい した。', 'Công ty đã rút khỏi mảng kinh doanh thua lỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12255, 47639, '商品の配送を外部に委託している。', 'しょうひんの はいそうを がいぶに いたく して いる。', 'Việc giao hàng được ủy thác cho bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12256, 47644, '新しい事業が大きな収益を上げた。', 'あたらしい じぎょうが おおきな しゅうえきを あげた。', 'Mảng kinh doanh mới đã mang lại lợi nhuận lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12257, 47646, '店は三年間赤字経営が続いている。', 'みせは さんねんかん あかじ けいえいが つづいて いる。', 'Cửa hàng đã kinh doanh thua lỗ suốt ba năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12258, 47647, '経費削減のため、出張が減らされた。', 'けいひ さくげんの ため、しゅっちょうが へらされた。', 'Để cắt giảm chi phí, các chuyến công tác đã bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12259, 47649, '今年は会社の業績が好調だ。', 'ことしは かいしゃの ぎょうせきが こうちょうだ。', 'Năm nay kết quả kinh doanh của công ty rất khả quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12260, 47652, '話し合いで事態の打開を図った。', 'はなしあいで じたいの だかいを はかった。', 'Chúng tôi tìm cách phá vỡ bế tắc bằng đối thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12261, 47654, '業界の再編が進んでいる。', 'ぎょうかいの さいへんが すすんで いる。', 'Ngành đang được tái cơ cấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12262, 47656, '家事を夫婦で分担している。', 'かじを ふうふで ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12263, 47659, '新しいパソコンの購入について稟議を出した。', 'あたらしい パソコンの こうにゅうに ついて りんぎを だした。', 'Tôi đã trình tờ xin duyệt việc mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12264, 47660, '会議の前に関係者に根回しをしておいた。', 'かいぎの まえに かんけいしゃに ねまわしを して おいた。', 'Trước cuộc họp tôi đã vận động trước với những người liên quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12265, 47662, '若手社員がリーダーに抜擢された。', 'わかて しゃいんが リーダーに ばってき された。', 'Một nhân viên trẻ đã được đề bạt làm trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12266, 47663, '彼はミスの責任を取らされ、地方へ左遷された。', 'かれは ミスの せきにんを とらされ、ちほうへ させん された。', 'Anh ấy bị bắt chịu trách nhiệm lỗi sai và bị điều về địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12267, 47666, '労使の話し合いで賃上げが決まった。', 'ろうしの はなしあいで ちんあげが きまった。', 'Qua thương lượng giữa chủ và thợ, việc tăng lương đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12268, 47668, '株主総会が来月開かれる。', 'かぶぬし そうかいが らいげつ ひらかれる。', 'Đại hội cổ đông sẽ được tổ chức vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12269, 47670, '小さな会社は資金繰りに苦労している。', 'ちいさな かいしゃは しきんぐりに くろう して いる。', 'Các công ty nhỏ đang vất vả xoay vòng vốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12270, 47672, '新しい社長が会社を立て直した。', 'あたらしい しゃちょうが かいしゃを たてなおした。', 'Giám đốc mới đã vực dậy công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12271, 47674, '視聴率が低く、番組は打ち切られた。', 'しちょうりつが ひくく、ばんぐみは うちきられた。', 'Tỷ lệ người xem thấp nên chương trình đã bị dừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12272, 47675, 'この店では外国の食品も取り扱っている。', 'この みせでは がいこくの しょくひんも とりあつかって いる。', 'Cửa hàng này cũng kinh doanh thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12273, 47677, '父は長年教育に携わってきた。', 'ちちは ながねん きょういくに たずさわって きた。', 'Bố tôi đã gắn bó với ngành giáo dục nhiều năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12274, 47679, '彼は百人の社員を率いている。', 'かれは ひゃくにんの しゃいんを ひきいて いる。', 'Anh ấy đang dẫn dắt một trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12275, 47681, '工事の費用を見積もってもらった。', 'こうじの ひようを みつもって もらった。', 'Tôi đã nhờ ước tính chi phí thi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12276, 47683, '日本の会社の多くは中小企業だ。', 'にほんの かいしゃの おおくは ちゅうしょう きぎょうだ。', 'Phần lớn công ty ở Nhật là doanh nghiệp vừa và nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12277, 47685, '会議は円滑に進んだ。', 'かいぎは えんかつに すすんだ。', 'Cuộc họp diễn ra suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12278, 47687, 'この問題は慎重に扱う必要がある。', 'この もんだいは しんちょうに あつかう ひつようが ある。', 'Vấn đề này cần được xử lý thận trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12279, 47688, '全社員の給料を一律に上げた。', 'ぜん しゃいんの きゅうりょうを いちりつに あげた。', 'Công ty tăng lương đồng loạt cho toàn bộ nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12280, 47693, '官僚の天下りが問題になっている。', 'かんりょうの あまくだりが もんだいに なって いる。', 'Việc quan chức nghỉ hưu chuyển sang doanh nghiệp đang trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12281, 47694, '市長が汚職の疑いで逮捕された。', 'しちょうが おしょくの うたがいで たいほ された。', 'Thị trưởng bị bắt vì nghi tham nhũng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12282, 47696, '会社の不祥事が相次いでいる。', 'かいしゃの ふしょうじが あいついで いる。', 'Các vụ bê bối của công ty liên tiếp xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12283, 47698, '社員が会社の不正を告発した。', 'しゃいんが かいしゃの ふせいを こくはつ した。', 'Một nhân viên đã tố giác hành vi gian lận của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12284, 47707, '都市の過密が問題になっている。', 'としの かみつが もんだいに なって いる。', 'Tình trạng quá đông đúc ở thành phố đang là vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12285, 47708, '都市部では待機児童が多い。', 'としぶでは たいき じどうが おおい。', 'Ở thành thị có nhiều trẻ phải chờ vào nhà trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12286, 47711, '一人暮らしの高齢者が孤立しないよう支援する。', 'ひとりぐらしの こうれいしゃが こりつ しない よう しえん する。', 'Hỗ trợ để người cao tuổi sống một mình không bị cô lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12287, 47714, '社会の多様性を認めることが大切だ。', 'しゃかいの たようせいを みとめる ことが たいせつだ。', 'Công nhận tính đa dạng của xã hội là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12288, 47715, '外国人との共生を目指す町づくりが進んでいる。', 'がいこくじんとの きょうせいを めざす まちづくりが すすんで いる。', 'Việc xây dựng thị trấn hướng tới chung sống với người nước ngoài đang được đẩy mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12289, 47729, '景気の悪化が懸念されている。', 'けいきの あっかが けねん されて いる。', 'Người ta lo ngại kinh tế sẽ xấu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12290, 47730, '男女の賃金格差を是正すべきだ。', 'だんじょの ちんぎん かくさを ぜせい すべきだ。', 'Cần điều chỉnh chênh lệch tiền lương giữa nam và nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12291, 47736, '今年は売り上げの増加が顕著だ。', 'ことしは うりあげの ぞうかが けんちょだ。', 'Năm nay doanh thu tăng rõ rệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12292, 47755, '月曜日の朝はいつも憂鬱だ。', 'げつようびの あさは いつも ゆううつだ。', 'Sáng thứ Hai lúc nào cũng u uất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12293, 47762, '私たちは科学技術の恩恵を受けている。', 'わたしたちは かがく ぎじゅつの おんけいを うけて いる。', 'Chúng ta đang hưởng lợi ích từ khoa học kỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12294, 47767, '他人の失敗に寛容でありたい。', 'たにんの しっぱいに かんようで ありたい。', 'Tôi muốn khoan dung với thất bại của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12295, 47794, '人間関係が煩わしくなってきた。', 'にんげん かんけいが わずらわしく なって きた。', 'Các mối quan hệ con người bắt đầu trở nên phiền toái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12296, 47821, '科学者は真理を探究し続けている。', 'かがくしゃは しんりを たんきゅう し つづけて いる。', 'Các nhà khoa học không ngừng tìm tòi chân lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12297, 47844, '両国の間で貿易摩擦が起きている。', 'りょうこくの あいだで ぼうえき まさつが おきて いる。', 'Giữa hai nước đang xảy ra xích mích thương mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12298, 47846, '寒さで筋肉が収縮する。', 'さむさで きんにくが しゅうしゅく する。', 'Cơ bắp co lại vì lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12299, 47866, '彼は緻密な計画を立てた。', 'かれは ちみつな けいかくを たてた。', 'Anh ấy đã lập một kế hoạch chặt chẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12300, 47886, '古い慣習を見直す時期に来ている。', 'ふるい かんしゅうを みなおす じきに きて いる。', 'Đã đến lúc xem xét lại những tập quán cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12301, 47929, '子供に「時間」という概念を教えるのは難しい。', 'こどもに 「じかん」と いう がいねんを おしえるのは むずかしい。', 'Dạy trẻ khái niệm "thời gian" thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12302, 47933, 'その主張には科学的な根拠がない。', 'その しゅちょうには かがくてきな こんきょが ない。', 'Lập luận đó không có căn cứ khoa học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12303, 47935, '彼の説明には矛盾がある。', 'かれの せつめいには むじゅんが ある。', 'Lời giải thích của anh ta có mâu thuẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12304, 47937, 'データから一つの結論を推論した。', 'データから ひとつの けつろんを すいろん した。', 'Từ dữ liệu, chúng tôi suy luận ra một kết luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12305, 47940, '材料を吟味して料理を作る。', 'ざいりょうを ぎんみ して りょうりを つくる。', 'Tôi lựa chọn kỹ nguyên liệu rồi mới nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12306, 47941, '二人の間には見解の相違がある。', 'ふたりの あいだには けんかいの そういが ある。', 'Giữa hai người có sự khác biệt về quan điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12307, 47944, '主観と客観を区別して考えよう。', 'しゅかんと きゃっかんを くべつ して かんがえよう。', 'Hãy suy nghĩ có phân biệt chủ quan và khách quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12308, 47945, 'これは私の主観ですが、彼は信頼できます。', 'これは わたしの しゅかん ですが、かれは しんらい できます。', 'Đây là cảm nhận chủ quan của tôi, nhưng anh ấy đáng tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12309, 47962, 'その政策の是非をめぐって議論が続いている。', 'その せいさくの ぜひを めぐって ぎろんが つづいて いる。', 'Cuộc tranh luận về đúng sai của chính sách đó vẫn đang tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12310, 47963, '若者はみんな本を読まないとは一概には言えない。', 'わかものは みんな ほんを よまないとは いちがいには いえない。', 'Không thể vơ đũa cả nắm rằng giới trẻ đều không đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12311, 47966, '彼はこの店の、いわば顔のような存在だ。', 'かれは この みせの、いわば かおの ような そんざいだ。', 'Anh ấy có thể nói là gương mặt đại diện của cửa hàng này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12312, 47968, '休日はもっぱら家で本を読んでいる。', 'きゅうじつは もっぱら いえで ほんを よんで いる。', 'Ngày nghỉ tôi chủ yếu ở nhà đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12313, 47970, '本物かどうかを見極めるのは難しい。', 'ほんもの か どうかを みきわめるのは むずかしい。', 'Nhận định rõ đâu là đồ thật thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12314, 47972, '連絡がない場合は、欠席と見なします。', 'れんらくが ない ばあいは、けっせきと みなします。', 'Trường hợp không liên lạc sẽ bị coi là vắng mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12315, 47973, '大事な点を見落としていた。', 'だいじな てんを みおとして いた。', 'Tôi đã bỏ sót một điểm quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12316, 47975, 'その説を裏付けるデータが見つかった。', 'その せつを うらづける データが みつかった。', 'Đã tìm thấy dữ liệu chứng thực giả thuyết đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12317, 47977, '彼はその計画に異議を唱えた。', 'かれは その けいかくに いぎを となえた。', 'Ông ấy lên tiếng phản đối kế hoạch đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12318, 47980, '彼の責任は明白だ。', 'かれの せきにんは めいはくだ。', 'Trách nhiệm của anh ta là rõ ràng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12319, 47982, '妥協的な解決策が採用された。', 'だきょうてきな かいけつさくが さいよう された。', 'Một giải pháp mang tính thỏa hiệp đã được chấp nhận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12320, 47984, '根本的な解決にはまだ時間がかかる。', 'こんぽんてきな かいけつには まだ じかんが かかる。', 'Giải quyết tận gốc vẫn còn cần thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12321, 47987, 'この二つの漢字は形が紛らわしい。', 'この ふたつの かんじは かたちが まぎらわしい。', 'Hai chữ Hán này có hình dạng dễ nhầm lẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12322, 47988, '彼はもっともらしい言い訳をした。', 'かれは もっともらしい いいわけを した。', 'Anh ta đưa ra một lời bào chữa nghe có vẻ hợp lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12323, 47993, 'その会社は海外にも事業を展開している。', 'その かいしゃは かいがいにも じぎょうを てんかい して いる。', 'Công ty đó cũng đang triển khai kinh doanh ở nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12324, 47995, '会社は赤字の事業から撤退した。', 'かいしゃは あかじの じぎょうから てったい した。', 'Công ty đã rút khỏi mảng kinh doanh thua lỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12325, 47997, '大手企業がその会社を買収した。', 'おおて きぎょうが その かいしゃを ばいしゅう した。', 'Một doanh nghiệp lớn đã thâu tóm công ty đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12326, 48003, '在庫管理をシステム化した。', 'ざいこ かんりを システムか した。', 'Chúng tôi đã hệ thống hóa việc quản lý tồn kho.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12327, 48005, 'この値段では採算が合わない。', 'この ねだんでは さいさんが あわない。', 'Với giá này thì không có lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12328, 48007, '経費削減のため、出張が減らされた。', 'けいひ さくげんの ため、しゅっちょうが へらされた。', 'Để cắt giảm chi phí, các chuyến công tác đã bị giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12329, 48009, '今年は会社の業績が好調だ。', 'ことしは かいしゃの ぎょうせきが こうちょうだ。', 'Năm nay kết quả kinh doanh của công ty rất khả quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12330, 48012, '話し合いで事態の打開を図った。', 'はなしあいで じたいの だかいを はかった。', 'Chúng tôi tìm cách phá vỡ bế tắc bằng đối thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12331, 48013, '新社長は組織の刷新を進めている。', 'しん しゃちょうは そしきの さっしんを すすめて いる。', 'Tân giám đốc đang tiến hành đổi mới toàn diện tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12332, 48016, '家事を夫婦で分担している。', 'かじを ふうふで ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12333, 48068, '都市部では待機児童が多い。', 'としぶでは たいき じどうが おおい。', 'Ở thành thị có nhiều trẻ phải chờ vào nhà trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12334, 48019, '新しいパソコンの購入について稟議を出した。', 'あたらしい パソコンの こうにゅうに ついて りんぎを だした。', 'Tôi đã trình tờ xin duyệt việc mua máy tính mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12335, 48020, '会議の前に関係者に根回しをしておいた。', 'かいぎの まえに かんけいしゃに ねまわしを して おいた。', 'Trước cuộc họp tôi đã vận động trước với những người liên quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12336, 48022, '若手社員がリーダーに抜擢された。', 'わかて しゃいんが リーダーに ばってき された。', 'Một nhân viên trẻ đã được đề bạt làm trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12337, 48023, '彼はミスの責任を取らされ、地方へ左遷された。', 'かれは ミスの せきにんを とらされ、ちほうへ させん された。', 'Anh ấy bị bắt chịu trách nhiệm lỗi sai và bị điều về địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12338, 48026, '労使の話し合いで賃上げが決まった。', 'ろうしの はなしあいで ちんあげが きまった。', 'Qua thương lượng giữa chủ và thợ, việc tăng lương đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12339, 48028, '株主総会が来月開かれる。', 'かぶぬし そうかいが らいげつ ひらかれる。', 'Đại hội cổ đông sẽ được tổ chức vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12340, 48030, '小さな会社は資金繰りに苦労している。', 'ちいさな かいしゃは しきんぐりに くろう して いる。', 'Các công ty nhỏ đang vất vả xoay vòng vốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12341, 48032, '新しい社長が会社を立て直した。', 'あたらしい しゃちょうが かいしゃを たてなおした。', 'Giám đốc mới đã vực dậy công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12342, 48033, '台風のため、運転を見合わせています。', 'たいふうの ため、うんてんを みあわせて います。', 'Do bão, tàu đang tạm ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12343, 48035, 'この店では外国の食品も取り扱っている。', 'この みせでは がいこくの しょくひんも とりあつかって いる。', 'Cửa hàng này cũng kinh doanh thực phẩm nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12344, 48037, '父は長年教育に携わってきた。', 'ちちは ながねん きょういくに たずさわって きた。', 'Bố tôi đã gắn bó với ngành giáo dục nhiều năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12345, 48039, '彼は百人の社員を率いている。', 'かれは ひゃくにんの しゃいんを ひきいて いる。', 'Anh ấy đang dẫn dắt một trăm nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12346, 48041, '工事の費用を見積もってもらった。', 'こうじの ひようを みつもって もらった。', 'Tôi đã nhờ ước tính chi phí thi công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12347, 48043, '日本の会社の多くは中小企業だ。', 'にほんの かいしゃの おおくは ちゅうしょう きぎょうだ。', 'Phần lớn công ty ở Nhật là doanh nghiệp vừa và nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12348, 48045, '会議は円滑に進んだ。', 'かいぎは えんかつに すすんだ。', 'Cuộc họp diễn ra suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12349, 48046, '抜本的な改革が求められている。', 'ばっぽんてきな かいかくが もとめられて いる。', 'Một cuộc cải cách triệt để đang được đòi hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12350, 48048, '全社員の給料を一律に上げた。', 'ぜん しゃいんの きゅうりょうを いちりつに あげた。', 'Công ty tăng lương đồng loạt cho toàn bộ nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12351, 48052, '閣僚の一人が辞任した。', 'かくりょうの ひとりが じにん した。', 'Một thành viên nội các đã từ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12352, 48054, '市長が汚職の疑いで逮捕された。', 'しちょうが おしょくの うたがいで たいほ された。', 'Thị trưởng bị bắt vì nghi tham nhũng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12353, 48055, '役人が賄賂を受け取ったことが発覚した。', 'やくにんが わいろを うけとった ことが はっかく した。', 'Đã phát hiện việc quan chức nhận hối lộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12354, 48057, '会社は事故を隠蔽しようとした。', 'かいしゃは じこを いんぺい しようと した。', 'Công ty đã tìm cách che giấu tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12355, 48060, '長い裁判の末、両者は和解した。', 'ながい さいばんの すえ、りょうしゃは わかい した。', 'Sau phiên tòa kéo dài, hai bên đã hòa giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12356, 48063, '医者には高い倫理観が必要だ。', 'いしゃには たかい りんりかんが ひつようだ。', 'Bác sĩ cần có ý thức đạo đức cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12357, 48064, '社会の秩序を守るために法律がある。', 'しゃかいの ちつじょを まもる ために ほうりつが ある。', 'Pháp luật tồn tại để giữ gìn trật tự xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12358, 48066, '過疎の村では学校がなくなっている。', 'かその むらでは がっこうが なくなって いる。', 'Ở những ngôi làng thưa dân, trường học đang biến mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12359, 48071, '一人暮らしの高齢者が孤立しないよう支援する。', 'ひとりぐらしの こうれいしゃが こりつ しない よう しえん する。', 'Hỗ trợ để người cao tuổi sống một mình không bị cô lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12360, 48072, 'あらゆる差別を排除すべきだ。', 'あらゆる さべつを はいじょ すべきだ。', 'Cần loại trừ mọi sự phân biệt đối xử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12361, 48074, '社会の多様性を認めることが大切だ。', 'しゃかいの たようせいを みとめる ことが たいせつだ。', 'Công nhận tính đa dạng của xã hội là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12362, 48075, '外国人との共生を目指す町づくりが進んでいる。', 'がいこくじんとの きょうせいを めざす まちづくりが すすんで いる。', 'Việc xây dựng thị trấn hướng tới chung sống với người nước ngoài đang được đẩy mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12363, 48089, '景気の悪化が懸念されている。', 'けいきの あっかが けねん されて いる。', 'Người ta lo ngại kinh tế sẽ xấu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12364, 48093, '政府は省エネを推進している。', 'せいふは しょうエネを すいしん して いる。', 'Chính phủ đang thúc đẩy tiết kiệm năng lượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12365, 48111, '仕事と家庭の間で葛藤している。', 'しごとと かていの あいだで かっとう して いる。', 'Tôi đang giằng xé giữa công việc và gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12366, 48120, '彼は友人の成功に嫉妬した。', 'かれは ゆうじんの せいこうに しっと した。', 'Anh ta ghen tị với thành công của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12367, 48122, '私たちは科学技術の恩恵を受けている。', 'わたしたちは かがく ぎじゅつの おんけいを うけて いる。', 'Chúng ta đang hưởng lợi ích từ khoa học kỹ thuật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12368, 48127, '他人の失敗に寛容でありたい。', 'たにんの しっぱいに かんようで ありたい。', 'Tôi muốn khoan dung với thất bại của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12369, 48154, '人間関係が煩わしくなってきた。', 'にんげん かんけいが わずらわしく なって きた。', 'Các mối quan hệ con người bắt đầu trở nên phiền toái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12370, 48181, '科学者は真理を探究し続けている。', 'かがくしゃは しんりを たんきゅう し つづけて いる。', 'Các nhà khoa học không ngừng tìm tòi chân lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12371, 48205, '空気は温めると膨張する。', 'くうきは あたためると ぼうちょう する。', 'Không khí khi được làm nóng sẽ giãn nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12372, 48218, 'この辞書は専門用語を網羅している。', 'この じしょは せんもん ようごを もうら して いる。', 'Cuốn từ điển này bao quát hết thuật ngữ chuyên môn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12373, 48245, 'この地方には珍しい風習が残っている。', 'この ちほうには めずらしい ふうしゅうが のこって いる。', 'Vùng này còn lưu giữ những phong tục lạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12374, 31738, '彼は人間の心理を鋭く洞察している。', 'かれは にんげんの しんりを するどく どうさつ して いる。', 'Ông ấy thấu hiểu tâm lý con người một cách sắc bén.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12375, 31756, '会社の理念に共感して入社した。', 'かいしゃの りねんに きょうかん して にゅうしゃ した。', 'Tôi vào công ty vì đồng cảm với triết lý của nó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12376, 31750, '医者には高い倫理観が必要だ。', 'いしゃには たかい りんりかんが ひつようだ。', 'Bác sĩ cần có ý thức đạo đức cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12377, 37867, '社会の多様性を認めることが大切だ。', 'しゃかいの たようせいを みとめる ことが たいせつだ。', 'Công nhận tính đa dạng của xã hội là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12378, 38213, '二つの部署が統合された。', 'ふたつの ぶしょが とうごう された。', 'Hai phòng ban đã được hợp nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12379, 38215, '業界の再編が進んでいる。', 'ぎょうかいの さいへんが すすんで いる。', 'Ngành đang được tái cơ cấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12380, 38231, '会社は事故を隠蔽しようとした。', 'かいしゃは じこを いんぺい しようと した。', 'Công ty đã tìm cách che giấu tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12381, 38221, '抜本的な改革が求められている。', 'ばっぽんてきな かいかくが もとめられて いる。', 'Một cuộc cải cách triệt để đang được đòi hỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12382, 40619, '商品の配送を外部に委託している。', 'しょうひんの はいそうを がいぶに いたく して いる。', 'Việc giao hàng được ủy thác cho bên ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12383, 47549, '古い法律は文語で書かれている。', 'ふるい ほうりつは ぶんごで かかれて いる。', 'Luật cũ được viết bằng văn ngôn cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12384, 40633, '若者はみんな本を読まないとは一概には言えない。', 'わかものは みんな ほんを よまないとは いちがいには いえない。', 'Không thể vơ đũa cả nắm rằng giới trẻ đều không đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12385, 40753, '過疎の村では学校がなくなっている。', 'かその むらでは がっこうが なくなって いる。', 'Ở những ngôi làng thưa dân, trường học đang biến mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12386, 40754, '都市の過密が問題になっている。', 'としの かみつが もんだいに なって いる。', 'Tình trạng quá đông đúc ở thành phố đang là vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12387, 40911, '主観と客観を区別して考えよう。', 'しゅかんと きゃっかんを くべつ して かんがえよう。', 'Hãy suy nghĩ có phân biệt chủ quan và khách quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12388, 40977, '今年は会社の業績が好調だ。', 'ことしは かいしゃの ぎょうせきが こうちょうだ。', 'Năm nay kết quả kinh doanh của công ty rất khả quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12389, 41110, '彼の話には誇張が多い。', 'かれの はなしには こちょうが おおい。', 'Câu chuyện của anh ta có nhiều phóng đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12390, 41185, '会議の前に関係者に根回しをしておいた。', 'かいぎの まえに かんけいしゃに ねまわしを して おいた。', 'Trước cuộc họp tôi đã vận động trước với những người liên quan.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12391, 41349, 'これは私の主観ですが、彼は信頼できます。', 'これは わたしの しゅかん ですが、かれは しんらい できます。', 'Đây là cảm nhận chủ quan của tôi, nhưng anh ấy đáng tin cậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12392, 42122, '将来に漠然とした不安を感じている。', 'しょうらいに ばくぜんと した ふあんを かんじて いる。', 'Tôi cảm thấy lo lắng mơ hồ về tương lai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12393, 42241, '家事を夫婦で分担している。', 'かじを ふうふで ぶんたん して いる。', 'Hai vợ chồng chia nhau việc nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12394, 40434, '眼鏡をやめてコンタクトにした。', 'めがねを やめて コンタクトに した。', 'Tôi bỏ kính, chuyển sang đeo kính áp tròng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12395, 40643, '社員一同、心よりお祝い申し上げます。', 'しゃいん いちどう、こころより おいわい もうしあげます。', 'Toàn thể nhân viên xin chân thành chúc mừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12396, 40532, '暑さでばててしまった。', 'あつさで ばてて しまった。', 'Nóng quá nên tôi kiệt sức mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12397, 40535, 'かぜはビールスによって起こる。', 'かぜは ビールスに よって おこる。', 'Cảm cúm là do vi rút gây ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12398, 40642, '仕事が一段落したので、一息ついた。', 'しごとが いちだんらく したので、ひといき ついた。', 'Công việc tạm xong một phần nên tôi nghỉ xả hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12399, 41438, '日本の出生率は低下している。', 'にほんの しゅっしょうりつは ていか して いる。', 'Tỷ lệ sinh ở Nhật đang giảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12400, 41445, '夜空に星の瞬きが見える。', 'よぞらに ほしの またたきが みえる。', 'Trên bầu trời đêm thấy những vì sao lấp lánh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12401, 42576, '彼女は婉曲に断った。', 'かのじょは えんきょくに ことわった。', 'Cô ấy từ chối một cách khéo léo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12402, 42220, '封建時代の身分制度について学んだ。', 'ほうけん じだいの みぶん せいどに ついて まなんだ。', 'Tôi đã học về chế độ đẳng cấp thời phong kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12403, 41118, '測定には多少の誤差がある。', 'そくていには たしょうの ごさが ある。', 'Phép đo có một chút sai số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12404, 37846, '警察は犯人の逃走を阻止した。', 'けいさつは はんにんの とうそうを そし した。', 'Cảnh sát đã ngăn chặn thủ phạm bỏ trốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12405, 41765, '台風で農業は大きな打撃を受けた。', 'たいふうで のうぎょうは おおきな だげきを うけた。', 'Nông nghiệp chịu tổn thất nặng nề vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12406, 41776, 'オンラインではなく、対面で話したい。', 'オンラインでは なく、たいめんで はなしたい。', 'Tôi muốn nói chuyện trực tiếp chứ không phải trực tuyến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12407, 41391, 'この古い町並みには趣がある。', 'この ふるい まちなみには おもむきが ある。', 'Dãy phố cổ này mang một phong vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12408, 41711, '田舎の人々は素朴で温かい。', 'いなかの ひとびとは そぼくで あたたかい。', 'Người dân quê mộc mạc và ấm áp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12409, 47518, '封建時代の身分制度について学んだ。', 'ほうけん じだいの みぶん せいどに ついて まなんだ。', 'Tôi đã học về chế độ đẳng cấp thời phong kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12410, 41884, '著名な作家の講演会に参加した。', 'ちょめいな さっかの こうえんかいに さんか した。', 'Tôi đã tham dự buổi diễn thuyết của một nhà văn nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12411, 47519, '江戸時代、日本は鎖国をしていた。', 'えど じだい、にほんは さこくを して いた。', 'Thời Edo, Nhật Bản thực hiện bế quan tỏa cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12412, 41190, '弟は左利きだ。', 'おとうとは ひだりききだ。', 'Em trai tôi thuận tay trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12413, 47520, '開国によって日本は大きく変わった。', 'かいこくに よって にほんは おおきく かわった。', 'Nhờ mở cửa, Nhật Bản đã thay đổi rất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12414, 47521, '明治維新で日本は近代化した。', 'めいじ いしんで にほんは きんだいか した。', 'Nhờ Minh Trị Duy Tân, Nhật Bản đã hiện đại hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12415, 47522, 'この祭りの起源は千年前にさかのぼる。', 'この まつりの きげんは せんねんまえに さかのぼる。', 'Nguồn gốc lễ hội này có từ một nghìn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12416, 47523, 'この町の名前の由来を調べた。', 'この まちの なまえの ゆらいを しらべた。', 'Tôi tìm hiểu nguồn gốc tên của thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12417, 47524, '日本語の変遷について研究している。', 'にほんごの へんせんに ついて けんきゅう して いる。', 'Tôi đang nghiên cứu về sự biến thiên của tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12418, 47528, 'この地方には河童の伝承がある。', 'この ちほうには かっぱの でんしょうが ある。', 'Vùng này lưu truyền truyền thuyết về thủy quái Kappa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12419, 47531, '週末に陶芸教室に通っている。', 'しゅうまつに とうげい きょうしつに かよって いる。', 'Cuối tuần tôi đi học lớp làm gốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12420, 47534, '母は若いころから華道を習っている。', 'ははは わかい ころから かどうを ならって いる。', 'Mẹ tôi học nghệ thuật cắm hoa từ hồi trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12421, 47361, '選挙の結果に不満を持つ人々が暴動を起こした。', 'せんきょの けっかに ふまんを もつ ひとびとが ぼうどうを おこした。', 'Những người bất mãn với kết quả bầu cử đã gây bạo động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12422, 47362, '両国の関係が緊迫している。', 'りょうこくの かんけいが きんぱく して いる。', 'Quan hệ giữa hai nước đang căng thẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12423, 47368, '被災地に義援金を送った。', 'ひさいちに ぎえんきんを おくった。', 'Tôi đã gửi tiền cứu trợ đến vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12424, 47375, '円安の影響が様々な業界に波及している。', 'えんやすの えいきょうが さまざまな ぎょうかいに はきゅう して いる。', 'Ảnh hưởng của đồng yên yếu đang lan rộng sang nhiều ngành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12425, 47377, '事態の深刻さに気づいていない人が多い。', 'じたいの しんこくさに きづいて いない ひとが おおい。', 'Nhiều người không nhận ra mức độ nghiêm trọng của sự việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12426, 47379, '人手不足への対応が喫緊の課題だ。', 'ひとで ぶそくへの たいおうが きっきんの かだいだ。', 'Ứng phó với tình trạng thiếu nhân lực là vấn đề cấp bách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12427, 47381, '大臣の発言が物議を醸した。', 'だいじんの はつげんが ぶつぎを かもした。', 'Phát ngôn của bộ trưởng đã gây xôn xao dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12428, 47383, '温暖化が多くの生物を脅かしている。', 'おんだんかが おおくの せいぶつを おびやかして いる。', 'Hiện tượng ấm lên đang đe dọa nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12429, 47385, '幸い、家は火事を免れた。', 'さいわい、いえは かじを まぬがれた。', 'May mắn là ngôi nhà đã thoát khỏi đám cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12430, 47386, '会社は経営難に陥った。', 'かいしゃは けいえいなんに おちいった。', 'Công ty rơi vào khó khăn kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12431, 47389, '引退を決めた今の心境を聞かせてください。', 'いんたいを きめた いまの しんきょうを きかせて ください。', 'Hãy cho tôi biết tâm trạng của anh lúc quyết định giải nghệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12432, 47392, '突然の知らせに彼は動揺した。', 'とつぜんの しらせに かれは どうよう した。', 'Trước tin báo đột ngột, anh ấy bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12433, 47393, '新しい環境に戸惑いを感じている。', 'あたらしい かんきょうに とまどいを かんじて いる。', 'Tôi cảm thấy lúng túng với môi trường mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12434, 47397, '優秀な兄に劣等感を抱いていた。', 'ゆうしゅうな あにに れっとうかんを いだいて いた。', 'Tôi từng mặc cảm trước người anh xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12435, 47399, 'うそをついて罪悪感を覚えた。', 'うそを ついて ざいあくかんを おぼえた。', 'Nói dối xong tôi thấy có lỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12436, 47401, '不公平な扱いに強い憤りを感じた。', 'ふこうへいな あつかいに つよい いきどおりを かんじた。', 'Tôi cảm thấy phẫn nộ trước sự đối xử bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12437, 47404, '過去に執着していては前に進めない。', 'かこに しゅうちゃく して いては まえに すすめない。', 'Cứ bám víu quá khứ thì không thể tiến lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12438, 47406, '古い写真を見て、郷愁にかられた。', 'ふるい しゃしんを みて、きょうしゅうに かられた。', 'Nhìn bức ảnh cũ, nỗi nhớ quê dâng trào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12439, 47412, '子供の無邪気な笑顔に癒される。', 'こどもの むじゃきな えがおに いやされる。', 'Nụ cười hồn nhiên của trẻ con khiến tôi thấy thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12440, 47414, '看護師たちの献身的な働きに感謝した。', 'かんごしたちの けんしんてきな はたらきに かんしゃ した。', 'Tôi biết ơn sự tận tụy của các y tá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12441, 47417, '子供たちの歌声に心が和んだ。', 'こどもたちの うたごえに こころが なごんだ。', 'Tiếng hát của bọn trẻ làm lòng tôi dịu lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12442, 47419, '多くの学生がその先生を慕っている。', 'おおくの がくせいが その せんせいを したって いる。', 'Nhiều học trò yêu mến người thầy đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12443, 47421, '今さら悔やんでもしかたがない。', 'いまさら くやんでも しかたが ない。', 'Bây giờ hối tiếc cũng chẳng ích gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12444, 47423, '子供は雷の音に怯えていた。', 'こどもは かみなりの おとに おびえて いた。', 'Đứa trẻ sợ hãi trước tiếng sấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12445, 47424, '渋滞で運転手が苛立っている。', 'じゅうたいで うんてんしゅが いらだって いる。', 'Tắc đường làm tài xế bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12446, 47426, '彼女に本当のことを言うのをためらった。', 'かのじょに ほんとうの ことを いうのを ためらった。', 'Tôi do dự không dám nói thật với cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12447, 47428, '新しいクラスメートとすぐに打ち解けた。', 'あたらしい クラスメートと すぐに うちとけた。', 'Tôi nhanh chóng thân thiết với bạn học mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12448, 47430, '気兼ねなく何でも言ってください。', 'きがね なく なんでも いって ください。', 'Cứ nói bất cứ điều gì, đừng e ngại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12449, 47432, '初めての一人暮らしは心細い。', 'はじめての ひとりぐらしは こころぼそい。', 'Lần đầu sống một mình thấy bất an.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12450, 47433, '言いたいことが日本語でうまく言えなくて、もどかしい。', 'いいたい ことが にほんごで うまく いえなくて、もどかしい。', 'Không nói được điều muốn nói bằng tiếng Nhật, thật bứt rứt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12451, 47436, '人前で褒められると照れくさい。', 'ひとまえで ほめられると てれくさい。', 'Được khen trước mặt người khác thấy ngượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12452, 47438, '彼は潔く自分の負けを認めた。', 'かれは いさぎよく じぶんの まけを みとめた。', 'Anh ấy dứt khoát thừa nhận thất bại của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12453, 47440, '自分から掃除をするとは殊勝な心がけだ。', 'じぶんから そうじを するとは しゅしょうな こころがけだ。', 'Tự giác dọn dẹp là một ý thức đáng khen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12454, 47443, '彼女はひそかに彼を思っていた。', 'かのじょは ひそかに かれを おもって いた。', 'Cô ấy thầm thương anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12455, 47446, '美しい音楽にうっとりした。', 'うつくしい おんがくに うっとり した。', 'Tôi mê mẩn trước bản nhạc tuyệt đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12456, 47447, '彼は先生の前でおどおどしていた。', 'かれは せんせいの まえで おどおど して いた。', 'Cậu ấy rụt rè trước mặt thầy giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12457, 47450, 'この言葉の定義を確認しよう。', 'この ことばの ていぎを かくにん しよう。', 'Hãy xác nhận định nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12458, 47458, '彼の無実が立証された。', 'かれの むじつが りっしょう された。', 'Sự vô tội của anh ấy đã được chứng minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12459, 47550, '彼女は婉曲に断った。', 'かのじょは えんきょくに ことわった。', 'Cô ấy từ chối một cách khéo léo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12460, 47459, '事故の原因はまだ解明されていない。', 'じこの げんいんは まだ かいめい されて いない。', 'Nguyên nhân tai nạn vẫn chưa được làm sáng tỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12461, 47464, '引用するときは出典を明記してください。', 'いんよう する ときは しゅってんを めいき して ください。', 'Khi trích dẫn hãy ghi rõ nguồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12462, 47466, '試行錯誤を重ねて、新商品が完成した。', 'しこう さくごを かさねて、しんしょうひんが かんせい した。', 'Qua bao lần thử và sai, sản phẩm mới đã hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12463, 47470, '環境問題は学際的な研究が必要だ。', 'かんきょう もんだいは がくさいてきな けんきゅうが ひつようだ。', 'Vấn đề môi trường cần nghiên cứu liên ngành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12464, 47471, '新しい薬の臨床試験が始まった。', 'あたらしい くすりの りんしょう しけんが はじまった。', 'Thử nghiệm lâm sàng của thuốc mới đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12465, 47474, 'ウイルスが変異して感染力が強くなった。', 'ウイルスが へんい して かんせんりょくが つよく なった。', 'Vi rút biến dị khiến khả năng lây nhiễm mạnh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12466, 47476, '水は水素と酸素の化合物だ。', 'みずは すいそと さんその かごうぶつだ。', 'Nước là hợp chất của hydro và ô xy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12467, 47479, 'すべての物は原子からできている。', 'すべての ものは げんしから できて いる。', 'Mọi vật chất đều được cấu tạo từ nguyên tử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12468, 47482, '地球は太陽系の惑星の一つだ。', 'ちきゅうは たいようけいの わくせいの ひとつだ。', 'Trái đất là một trong các hành tinh của hệ Mặt trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12469, 47488, 'この本には作者の人生が凝縮されている。', 'この ほんには さくしゃの じんせいが ぎょうしゅく されて いる。', 'Cuộc đời tác giả được cô đọng trong cuốn sách này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12470, 47491, '二枚の写真を合成した。', 'にまいの しゃしんを ごうせい した。', 'Tôi ghép hai bức ảnh lại với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12471, 47493, '測定には多少の誤差がある。', 'そくていには たしょうの ごさが ある。', 'Phép đo có một chút sai số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12472, 47495, '睡眠時間と成績には相関がある。', 'すいみん じかんと せいせきには そうかんが ある。', 'Thời gian ngủ và thành tích có tương quan với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12473, 47496, '二つの出来事の因果関係を調べる。', 'ふたつの できごとの いんが かんけいを しらべる。', 'Điều tra quan hệ nhân quả giữa hai sự kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12474, 47499, '知識を体系的に整理した。', 'ちしきを たいけいてきに せいり した。', 'Tôi sắp xếp kiến thức một cách có hệ thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12475, 47501, '教育的な見地から考えると、この番組は問題がある。', 'きょういくてきな けんちから かんがえると、この ばんぐみは もんだいが ある。', 'Xét từ quan điểm giáo dục thì chương trình này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12476, 47502, '留学で国際的な感覚を培った。', 'りゅうがくで こくさいてきな かんかくを つちかった。', 'Qua du học tôi đã bồi dưỡng được cảm quan quốc tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12477, 47504, '新しい方法を試みることにした。', 'あたらしい ほうほうを こころみる ことに した。', 'Tôi quyết định thử một phương pháp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12478, 47508, '厳密に言えば、これは正しくない。', 'げんみつに いえば、これは ただしく ない。', 'Nói chặt chẽ thì điều này không đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12479, 47513, '祖父は時代劇を見るのが好きだ。', 'そふは じだいげきを みるのが すきだ。', 'Ông tôi thích xem phim cổ trang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12480, 47517, '昔、この城には大名が住んでいた。', 'むかし、この しろには だいみょうが すんで いた。', 'Ngày xưa lâu đài này là nơi lãnh chúa sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12481, 47537, '昔の貴族は和歌を詠んで気持ちを伝えた。', 'むかしの きぞくは わかを よんで きもちを つたえた。', 'Quý tộc ngày xưa làm thơ waka để bày tỏ tình cảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12482, 47539, 'この言葉の語源はポルトガル語だ。', 'この ことばの ごげんは ポルトガルごだ。', 'Từ này có nguồn gốc từ tiếng Bồ Đào Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12483, 47543, 'この詩には美しい比喩が使われている。', 'この しには うつくしい ひゆが つかわれて いる。', 'Bài thơ này sử dụng những ẩn dụ đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12484, 47547, 'ニュースでは標準語が使われる。', 'ニュースでは ひょうじゅんごが つかわれる。', 'Trên bản tin người ta dùng tiếng chuẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12485, 47843, '人工衛星が軌道に乗った。', 'じんこう えいせいが きどうに のった。', 'Vệ tinh nhân tạo đã vào quỹ đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12486, 47560, '歴史を遡ると、この町の起源がわかる。', 'れきしを さかのぼると、この まちの きげんが わかる。', 'Truy ngược lịch sử sẽ biết được nguồn gốc thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12487, 47562, '日本では礼儀を重んじる。', 'にほんでは れいぎを おもんじる。', 'Ở Nhật người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12488, 47563, '長い歴史の中で培われた技術だ。', 'ながい れきしの なかで つちかわれた ぎじゅつだ。', 'Đây là kỹ thuật được vun đắp qua lịch sử lâu dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12489, 47565, '式典は厳かな雰囲気の中で行われた。', 'しきてんは おごそかな ふんいきの なかで おこなわれた。', 'Buổi lễ được tổ chức trong bầu không khí trang nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12490, 47568, '伝統の技は脈々と受け継がれている。', 'でんとうの わざは みゃくみゃくと うけつがれて いる。', 'Kỹ thuật truyền thống được kế thừa không ngừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12491, 47721, '選挙の結果に不満を持つ人々が暴動を起こした。', 'せんきょの けっかに ふまんを もつ ひとびとが ぼうどうを おこした。', 'Những người bất mãn với kết quả bầu cử đã gây bạo động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12492, 47723, '台風で農業は大きな打撃を受けた。', 'たいふうで のうぎょうは おおきな だげきを うけた。', 'Nông nghiệp chịu tổn thất nặng nề vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12493, 47734, '警察は犯人の逃走を阻止した。', 'けいさつは はんにんの とうそうを そし した。', 'Cảnh sát đã ngăn chặn thủ phạm bỏ trốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12494, 47735, '円安の影響が様々な業界に波及している。', 'えんやすの えいきょうが さまざまな ぎょうかいに はきゅう して いる。', 'Ảnh hưởng của đồng yên yếu đang lan rộng sang nhiều ngành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12495, 47738, '住民の切実な声に耳を傾けるべきだ。', 'じゅうみんの せつじつな こえに みみを かたむける べきだ。', 'Cần lắng nghe tiếng nói bức thiết của người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12496, 47740, '著名な作家の講演会に参加した。', 'ちょめいな さっかの こうえんかいに さんか した。', 'Tôi đã tham dự buổi diễn thuyết của một nhà văn nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12497, 47742, 'その事件で会社への信頼が揺らいだ。', 'その じけんで かいしゃへの しんらいが ゆらいだ。', 'Vụ việc đó đã làm lung lay niềm tin vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12498, 47743, '温暖化が多くの生物を脅かしている。', 'おんだんかが おおくの せいぶつを おびやかして いる。', 'Hiện tượng ấm lên đang đe dọa nhiều sinh vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12499, 47745, '幸い、家は火事を免れた。', 'さいわい、いえは かじを まぬがれた。', 'May mắn là ngôi nhà đã thoát khỏi đám cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12500, 47747, '感染の拡大を食い止めなければならない。', 'かんせんの かくだいを くいとめなければ ならない。', 'Phải ngăn chặn sự lây lan của dịch bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12501, 47750, '被害者の心情を考えると胸が痛む。', 'ひがいしゃの しんじょうを かんがえると むねが いたむ。', 'Nghĩ đến tâm tình của nạn nhân mà tôi thấy đau lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12502, 47753, '新しい環境に戸惑いを感じている。', 'あたらしい かんきょうに とまどいを かんじて いる。', 'Tôi cảm thấy lúng túng với môi trường mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12503, 47754, '試験が近づき、焦りを感じ始めた。', 'しけんが ちかづき、あせりを かんじ はじめた。', 'Kỳ thi đến gần, tôi bắt đầu thấy sốt ruột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12504, 47758, '人を見下して優越感に浸るのはよくない。', 'ひとを みくだして ゆうえつかんに ひたるのは よくない。', 'Coi thường người khác để thấy mình hơn người là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12505, 47761, '不公平な扱いに強い憤りを感じた。', 'ふこうへいな あつかいに つよい いきどおりを かんじた。', 'Tôi cảm thấy phẫn nộ trước sự đối xử bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12506, 47765, '長く使っている机に愛着がある。', 'ながく つかって いる つくえに あいちゃくが ある。', 'Tôi gắn bó với chiếc bàn đã dùng lâu năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12507, 47772, '子供の無邪気な笑顔に癒される。', 'こどもの むじゃきな えがおに いやされる。', 'Nụ cười hồn nhiên của trẻ con khiến tôi thấy thư thái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12508, 47773, '彼の几帳面さは仕事にも表れている。', 'かれの きちょうめんさは しごとにも あらわれて いる。', 'Tính tỉ mỉ của anh ấy thể hiện cả trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12509, 47775, '彼の考えに深く共感した。', 'かれの かんがえに ふかく きょうかん した。', 'Tôi đồng cảm sâu sắc với suy nghĩ của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12510, 47778, '温泉で旅の疲れを癒した。', 'おんせんで たびの つかれを いやした。', 'Tôi xua tan mệt mỏi của chuyến đi ở suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12511, 47780, '彼は自分の不運を嘆いた。', 'かれは じぶんの ふうんを なげいた。', 'Anh ấy than thở về vận rủi của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12512, 47782, '急に質問されて戸惑った。', 'きゅうに しつもん されて とまどった。', 'Bị hỏi đột ngột nên tôi lúng túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12513, 47784, '渋滞で運転手が苛立っている。', 'じゅうたいで うんてんしゅが いらだって いる。', 'Tắc đường làm tài xế bực bội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12514, 47786, '彼女に本当のことを言うのをためらった。', 'かのじょに ほんとうの ことを いうのを ためらった。', 'Tôi do dự không dám nói thật với cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12515, 47787, 'お年寄りをいたわる気持ちを忘れないで。', 'おとしよりを いたわる きもちを わすれないで。', 'Đừng quên tấm lòng quan tâm người già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12516, 47789, '一人で思い詰めないで、相談してください。', 'ひとりで おもいつめないで、そうだん して ください。', 'Đừng một mình nghĩ quẩn, hãy tâm sự với tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12517, 47791, '別れの場面は切なかった。', 'わかれの ばめんは せつなかった。', 'Cảnh chia ly thật da diết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12518, 47793, '言いたいことが日本語でうまく言えなくて、もどかしい。', 'いいたい ことが にほんごで うまく いえなくて、もどかしい。', 'Không nói được điều muốn nói bằng tiếng Nhật, thật bứt rứt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12519, 47796, '人前で褒められると照れくさい。', 'ひとまえで ほめられると てれくさい。', 'Được khen trước mặt người khác thấy ngượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12520, 47798, '彼は潔く自分の負けを認めた。', 'かれは いさぎよく じぶんの まけを みとめた。', 'Anh ấy dứt khoát thừa nhận thất bại của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12521, 47799, '病気の母を支える少女の姿が健気だ。', 'びょうきの ははを ささえる しょうじょの すがたが けなげだ。', 'Hình ảnh cô bé chăm sóc mẹ ốm thật đáng khen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12522, 47802, '親のありがたさをつくづく感じた。', 'おやの ありがたさを つくづく かんじた。', 'Tôi thấm thía công ơn cha mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12523, 47805, '母に言われて、しぶしぶ宿題をした。', 'ははに いわれて、しぶしぶ しゅくだいを した。', 'Bị mẹ nhắc, tôi miễn cưỡng làm bài tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12524, 47807, '彼は先生の前でおどおどしていた。', 'かれは せんせいの まえで おどおど して いた。', 'Cậu ấy rụt rè trước mặt thầy giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12525, 47808, '過ぎたことをくよくよしても仕方がない。', 'すぎた ことを くよくよ しても しかたが ない。', 'Ủ ê vì chuyện đã qua cũng chẳng ích gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12526, 47818, '彼の無実が立証された。', 'かれの むじつが りっしょう された。', 'Sự vô tội của anh ấy đã được chứng minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12527, 47819, '事故の原因はまだ解明されていない。', 'じこの げんいんは まだ かいめい されて いない。', 'Nguyên nhân tai nạn vẫn chưa được làm sáng tỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12528, 47824, '引用するときは出典を明記してください。', 'いんよう する ときは しゅってんを めいき して ください。', 'Khi trích dẫn hãy ghi rõ nguồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12529, 47826, '試行錯誤を重ねて、新商品が完成した。', 'しこう さくごを かさねて、しんしょうひんが かんせい した。', 'Qua bao lần thử và sai, sản phẩm mới đã hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12530, 47827, 'この研究から新たな知見が得られた。', 'この けんきゅうから あらたな ちけんが えられた。', 'Từ nghiên cứu này đã thu được những hiểu biết mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12531, 47831, '新しい薬の臨床試験が始まった。', 'あたらしい くすりの りんしょう しけんが はじまった。', 'Thử nghiệm lâm sàng của thuốc mới đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12532, 47834, 'ウイルスが変異して感染力が強くなった。', 'ウイルスが へんい して かんせんりょくが つよく なった。', 'Vi rút biến dị khiến khả năng lây nhiễm mạnh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12533, 47836, '水は水素と酸素の化合物だ。', 'みずは すいそと さんその かごうぶつだ。', 'Nước là hợp chất của hydro và ô xy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12534, 47838, '水の分子は小さい。', 'みずの ぶんしは ちいさい。', 'Phân tử nước rất nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12535, 47839, 'すべての物は原子からできている。', 'すべての ものは げんしから できて いる。', 'Mọi vật chất đều được cấu tạo từ nguyên tử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12536, 47848, 'この本には作者の人生が凝縮されている。', 'この ほんには さくしゃの じんせいが ぎょうしゅく されて いる。', 'Cuộc đời tác giả được cô đọng trong cuốn sách này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12537, 47852, 'この機械は精度が高い。', 'この きかいは せいどが たかい。', 'Máy này có độ chính xác cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12607, 48211, '二枚の写真を合成した。', 'にまいの しゃしんを ごうせい した。', 'Tôi ghép hai bức ảnh lại với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12538, 47854, 'このクラスの男女の比率は半々だ。', 'この クラスの だんじょの ひりつは はんはんだ。', 'Tỷ lệ nam nữ của lớp này là một nửa mỗi bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12539, 47855, '睡眠時間と成績には相関がある。', 'すいみん じかんと せいせきには そうかんが ある。', 'Thời gian ngủ và thành tích có tương quan với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12540, 47857, '愛は人類に普遍的なテーマだ。', 'あいは じんるいに ふへんてきな テーマだ。', 'Tình yêu là chủ đề phổ quát của nhân loại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12541, 47860, '新しい国際協力の枠組みが作られた。', 'あたらしい こくさい きょうりょくの わくぐみが つくられた。', 'Một khuôn khổ hợp tác quốc tế mới đã được xây dựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12542, 47861, '教育的な見地から考えると、この番組は問題がある。', 'きょういくてきな けんちから かんがえると、この ばんぐみは もんだいが ある。', 'Xét từ quan điểm giáo dục thì chương trình này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12543, 47863, '彼は茶道の道を究めた。', 'かれは さどうの みちを きわめた。', 'Ông ấy đã đạt đến tận cùng con đường trà đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12544, 47865, '宇宙の謎を解き明かしたい。', 'うちゅうの なぞを ときあかしたい。', 'Tôi muốn giải đáp những bí ẩn của vũ trụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12545, 47869, '古代エジプトの文明に興味がある。', 'こだい エジプトの ぶんめいに きょうみが ある。', 'Tôi quan tâm đến nền văn minh Ai Cập cổ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12546, 47874, 'この寺は平安王朝の時代に建てられた。', 'この てらは へいあん おうちょうの じだいに たてられた。', 'Ngôi chùa này được xây vào thời triều đại Heian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12547, 47878, '封建時代の身分制度について学んだ。', 'ほうけん じだいの みぶん せいどに ついて まなんだ。', 'Tôi đã học về chế độ đẳng cấp thời phong kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12548, 47879, '江戸時代、日本は鎖国をしていた。', 'えど じだい、にほんは さこくを して いた。', 'Thời Edo, Nhật Bản thực hiện bế quan tỏa cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12549, 47881, '明治維新で日本は近代化した。', 'めいじ いしんで にほんは きんだいか した。', 'Nhờ Minh Trị Duy Tân, Nhật Bản đã hiện đại hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12550, 47883, 'この町の名前の由来を調べた。', 'この まちの なまえの ゆらいを しらべた。', 'Tôi tìm hiểu nguồn gốc tên của thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12551, 47884, '日本語の変遷について研究している。', 'にほんごの へんせんに ついて けんきゅう して いる。', 'Tôi đang nghiên cứu về sự biến thiên của tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12552, 47887, 'この家には古いしきたりが残っている。', 'この いえには ふるい しきたりが のこって いる。', 'Gia đình này vẫn giữ những lề thói cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12553, 47889, '伝統文化を次の世代に継承したい。', 'でんとう ぶんかを つぎの せだいに けいしょう したい。', 'Tôi muốn truyền lại văn hóa truyền thống cho thế hệ sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12554, 47894, '母は若いころから華道を習っている。', 'ははは わかい ころから かどうを ならって いる。', 'Mẹ tôi học nghệ thuật cắm hoa từ hồi trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12555, 47897, '昔の貴族は和歌を詠んで気持ちを伝えた。', 'むかしの きぞくは わかを よんで きもちを つたえた。', 'Quý tộc ngày xưa làm thơ waka để bày tỏ tình cảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12556, 47900, '本を読んで語彙を増やしたい。', 'ほんを よんで ごいを ふやしたい。', 'Tôi muốn đọc sách để tăng vốn từ vựng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12557, 47904, '「顔が広い」は慣用句の一つだ。', '「かおが ひろい」は かんようくの ひとつだ。', '"Mặt rộng" (quen biết nhiều) là một thành ngữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12558, 47908, 'この本は口語で書かれていて読みやすい。', 'この ほんは こうごで かかれて いて よみやすい。', 'Cuốn sách này viết bằng văn nói nên dễ đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12559, 47910, '彼女は婉曲に断った。', 'かのじょは えんきょくに ことわった。', 'Cô ấy từ chối một cách khéo léo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12560, 48110, '被害者の心情を考えると胸が痛む。', 'ひがいしゃの しんじょうを かんがえると むねが いたむ。', 'Nghĩ đến tâm tình của nạn nhân mà tôi thấy đau lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12561, 48082, '両国の関係が緊迫している。', 'りょうこくの かんけいが きんぱく して いる。', 'Quan hệ giữa hai nước đang căng thẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12562, 48083, '台風で農業は大きな打撃を受けた。', 'たいふうで のうぎょうは おおきな だげきを うけた。', 'Nông nghiệp chịu tổn thất nặng nề vì bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12563, 48094, '警察は犯人の逃走を阻止した。', 'けいさつは はんにんの とうそうを そし した。', 'Cảnh sát đã ngăn chặn thủ phạm bỏ trốn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12564, 48097, '事態の深刻さに気づいていない人が多い。', 'じたいの しんこくさに きづいて いない ひとが おおい。', 'Nhiều người không nhận ra mức độ nghiêm trọng của sự việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12565, 48099, '人手不足への対応が喫緊の課題だ。', 'ひとで ぶそくへの たいおうが きっきんの かだいだ。', 'Ứng phó với tình trạng thiếu nhân lực là vấn đề cấp bách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12566, 48100, '著名な作家の講演会に参加した。', 'ちょめいな さっかの こうえんかいに さんか した。', 'Tôi đã tham dự buổi diễn thuyết của một nhà văn nổi tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12567, 48102, 'その事件で会社への信頼が揺らいだ。', 'その じけんで かいしゃへの しんらいが ゆらいだ。', 'Vụ việc đó đã làm lung lay niềm tin vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12568, 48104, '夜更かしは健康を損なう。', 'よふかしは けんこうを そこなう。', 'Thức khuya làm tổn hại sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12569, 48105, '幸い、家は火事を免れた。', 'さいわい、いえは かじを まぬがれた。', 'May mắn là ngôi nhà đã thoát khỏi đám cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12570, 48107, '感染の拡大を食い止めなければならない。', 'かんせんの かくだいを くいとめなければ ならない。', 'Phải ngăn chặn sự lây lan của dịch bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12571, 48112, '突然の知らせに彼は動揺した。', 'とつぜんの しらせに かれは どうよう した。', 'Trước tin báo đột ngột, anh ấy bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12572, 48114, '試験が近づき、焦りを感じ始めた。', 'しけんが ちかづき、あせりを かんじ はじめた。', 'Kỳ thi đến gần, tôi bắt đầu thấy sốt ruột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12573, 48117, '優秀な兄に劣等感を抱いていた。', 'ゆうしゅうな あにに れっとうかんを いだいて いた。', 'Tôi từng mặc cảm trước người anh xuất sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12574, 48119, 'うそをついて罪悪感を覚えた。', 'うそを ついて ざいあくかんを おぼえた。', 'Nói dối xong tôi thấy có lỗi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12575, 48124, '過去に執着していては前に進めない。', 'かこに しゅうちゃく して いては まえに すすめない。', 'Cứ bám víu quá khứ thì không thể tiến lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12576, 48125, '長く使っている机に愛着がある。', 'ながく つかって いる つくえに あいちゃくが ある。', 'Tôi gắn bó với chiếc bàn đã dùng lâu năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12577, 48133, '彼の几帳面さは仕事にも表れている。', 'かれの きちょうめんさは しごとにも あらわれて いる。', 'Tính tỉ mỉ của anh ấy thể hiện cả trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12578, 48134, '看護師たちの献身的な働きに感謝した。', 'かんごしたちの けんしんてきな はたらきに かんしゃ した。', 'Tôi biết ơn sự tận tụy của các y tá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12579, 48138, '温泉で旅の疲れを癒した。', 'おんせんで たびの つかれを いやした。', 'Tôi xua tan mệt mỏi của chuyến đi ở suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12580, 48139, '多くの学生がその先生を慕っている。', 'おおくの がくせいが その せんせいを したって いる。', 'Nhiều học trò yêu mến người thầy đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12581, 48141, '今さら悔やんでもしかたがない。', 'いまさら くやんでも しかたが ない。', 'Bây giờ hối tiếc cũng chẳng ích gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12582, 48143, '子供は雷の音に怯えていた。', 'こどもは かみなりの おとに おびえて いた。', 'Đứa trẻ sợ hãi trước tiếng sấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12583, 48145, '人目をはばからずに泣いた。', 'ひとめを はばからずに ないた。', 'Tôi khóc chẳng e ngại ánh mắt người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12584, 48147, 'お年寄りをいたわる気持ちを忘れないで。', 'おとしよりを いたわる きもちを わすれないで。', 'Đừng quên tấm lòng quan tâm người già.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12585, 48148, '新しいクラスメートとすぐに打ち解けた。', 'あたらしい クラスメートと すぐに うちとけた。', 'Tôi nhanh chóng thân thiết với bạn học mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12586, 48150, '気兼ねなく何でも言ってください。', 'きがね なく なんでも いって ください。', 'Cứ nói bất cứ điều gì, đừng e ngại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12587, 48152, '初めての一人暮らしは心細い。', 'はじめての ひとりぐらしは こころぼそい。', 'Lần đầu sống một mình thấy bất an.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12588, 48155, '約束を破って、後ろめたい気持ちだ。', 'やくそくを やぶって、うしろめたい きもちだ。', 'Thất hứa nên tôi thấy áy náy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12589, 48156, '人前で褒められると照れくさい。', 'ひとまえで ほめられると てれくさい。', 'Được khen trước mặt người khác thấy ngượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12590, 48158, '彼は潔く自分の負けを認めた。', 'かれは いさぎよく じぶんの まけを みとめた。', 'Anh ấy dứt khoát thừa nhận thất bại của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12591, 48160, '自分から掃除をするとは殊勝な心がけだ。', 'じぶんから そうじを するとは しゅしょうな こころがけだ。', 'Tự giác dọn dẹp là một ý thức đáng khen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12592, 48163, '彼女はひそかに彼を思っていた。', 'かのじょは ひそかに かれを おもって いた。', 'Cô ấy thầm thương anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12593, 48166, '美しい音楽にうっとりした。', 'うつくしい おんがくに うっとり した。', 'Tôi mê mẩn trước bản nhạc tuyệt đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12594, 48167, '彼は先生の前でおどおどしていた。', 'かれは せんせいの まえで おどおど して いた。', 'Cậu ấy rụt rè trước mặt thầy giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12595, 48170, 'この言葉の定義を確認しよう。', 'この ことばの ていぎを かくにん しよう。', 'Hãy xác nhận định nghĩa của từ này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12596, 48178, '彼の無実が立証された。', 'かれの むじつが りっしょう された。', 'Sự vô tội của anh ấy đã được chứng minh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12597, 48179, '事故の原因はまだ解明されていない。', 'じこの げんいんは まだ かいめい されて いない。', 'Nguyên nhân tai nạn vẫn chưa được làm sáng tỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12598, 48184, '引用するときは出典を明記してください。', 'いんよう する ときは しゅってんを めいき して ください。', 'Khi trích dẫn hãy ghi rõ nguồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12599, 48186, '試行錯誤を重ねて、新商品が完成した。', 'しこう さくごを かさねて、しんしょうひんが かんせい した。', 'Qua bao lần thử và sai, sản phẩm mới đã hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12600, 48190, '環境問題は学際的な研究が必要だ。', 'かんきょう もんだいは がくさいてきな けんきゅうが ひつようだ。', 'Vấn đề môi trường cần nghiên cứu liên ngành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12601, 48191, '新しい薬の臨床試験が始まった。', 'あたらしい くすりの りんしょう しけんが はじまった。', 'Thử nghiệm lâm sàng của thuốc mới đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12602, 48194, 'ウイルスが変異して感染力が強くなった。', 'ウイルスが へんい して かんせんりょくが つよく なった。', 'Vi rút biến dị khiến khả năng lây nhiễm mạnh hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12603, 48196, '水は水素と酸素の化合物だ。', 'みずは すいそと さんその かごうぶつだ。', 'Nước là hợp chất của hydro và ô xy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12604, 48199, 'すべての物は原子からできている。', 'すべての ものは げんしから できて いる。', 'Mọi vật chất đều được cấu tạo từ nguyên tử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12605, 48202, '地球は太陽系の惑星の一つだ。', 'ちきゅうは たいようけいの わくせいの ひとつだ。', 'Trái đất là một trong các hành tinh của hệ Mặt trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12606, 48208, 'この本には作者の人生が凝縮されている。', 'この ほんには さくしゃの じんせいが ぎょうしゅく されて いる。', 'Cuộc đời tác giả được cô đọng trong cuốn sách này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12608, 48213, '測定には多少の誤差がある。', 'そくていには たしょうの ごさが ある。', 'Phép đo có một chút sai số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12609, 48215, '睡眠時間と成績には相関がある。', 'すいみん じかんと せいせきには そうかんが ある。', 'Thời gian ngủ và thành tích có tương quan với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12610, 48216, '二つの出来事の因果関係を調べる。', 'ふたつの できごとの いんが かんけいを しらべる。', 'Điều tra quan hệ nhân quả giữa hai sự kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12611, 48219, '知識を体系的に整理した。', 'ちしきを たいけいてきに せいり した。', 'Tôi sắp xếp kiến thức một cách có hệ thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12612, 48221, '教育的な見地から考えると、この番組は問題がある。', 'きょういくてきな けんちから かんがえると、この ばんぐみは もんだいが ある。', 'Xét từ quan điểm giáo dục thì chương trình này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12613, 48222, '留学で国際的な感覚を培った。', 'りゅうがくで こくさいてきな かんかくを つちかった。', 'Qua du học tôi đã bồi dưỡng được cảm quan quốc tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12614, 48224, '新しい方法を試みることにした。', 'あたらしい ほうほうを こころみる ことに した。', 'Tôi quyết định thử một phương pháp mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12615, 48228, '厳密に言えば、これは正しくない。', 'げんみつに いえば、これは ただしく ない。', 'Nói chặt chẽ thì điều này không đúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12616, 48233, '祖父は時代劇を見るのが好きだ。', 'そふは じだいげきを みるのが すきだ。', 'Ông tôi thích xem phim cổ trang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12617, 48237, '昔、この城には大名が住んでいた。', 'むかし、この しろには だいみょうが すんで いた。', 'Ngày xưa lâu đài này là nơi lãnh chúa sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12618, 48238, '封建時代の身分制度について学んだ。', 'ほうけん じだいの みぶん せいどに ついて まなんだ。', 'Tôi đã học về chế độ đẳng cấp thời phong kiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12619, 48240, '開国によって日本は大きく変わった。', 'かいこくに よって にほんは おおきく かわった。', 'Nhờ mở cửa, Nhật Bản đã thay đổi rất lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12620, 48242, 'この祭りの起源は千年前にさかのぼる。', 'この まつりの きげんは せんねんまえに さかのぼる。', 'Nguồn gốc lễ hội này có từ một nghìn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12621, 48243, 'この町の名前の由来を調べた。', 'この まちの なまえの ゆらいを しらべた。', 'Tôi tìm hiểu nguồn gốc tên của thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12622, 48247, 'この家には古いしきたりが残っている。', 'この いえには ふるい しきたりが のこって いる。', 'Gia đình này vẫn giữ những lề thói cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12623, 48249, '伝統文化を次の世代に継承したい。', 'でんとう ぶんかを つぎの せだいに けいしょう したい。', 'Tôi muốn truyền lại văn hóa truyền thống cho thế hệ sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12624, 48254, '母は若いころから華道を習っている。', 'ははは わかい ころから かどうを ならって いる。', 'Mẹ tôi học nghệ thuật cắm hoa từ hồi trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12625, 48259, 'この言葉の語源はポルトガル語だ。', 'この ことばの ごげんは ポルトガルごだ。', 'Từ này có nguồn gốc từ tiếng Bồ Đào Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12626, 48263, 'この詩には美しい比喩が使われている。', 'この しには うつくしい ひゆが つかわれて いる。', 'Bài thơ này sử dụng những ẩn dụ đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12627, 48264, '「顔が広い」は慣用句の一つだ。', '「かおが ひろい」は かんようくの ひとつだ。', '"Mặt rộng" (quen biết nhiều) là một thành ngữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12628, 48268, 'この本は口語で書かれていて読みやすい。', 'この ほんは こうごで かかれて いて よみやすい。', 'Cuốn sách này viết bằng văn nói nên dễ đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12629, 48270, '彼女は婉曲に断った。', 'かのじょは えんきょくに ことわった。', 'Cô ấy từ chối một cách khéo léo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12630, 47552, 'この古い町並みには趣がある。', 'この ふるい まちなみには おもむきが ある。', 'Dãy phố cổ này mang một phong vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12631, 47553, '雨の京都には独特の風情がある。', 'あめの きょうとには どくとくの ふぜいが ある。', 'Kyoto trong mưa mang một nét thú vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12632, 47555, '彼の着物の着こなしは粋だ。', 'かれの きものの きこなしは いきだ。', 'Cách anh ấy mặc kimono thật thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12633, 47557, '彼は医学界の権威だ。', 'かれは いがくかいの けんいだ。', 'Ông ấy là người có uy tín hàng đầu trong giới y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12634, 47551, 'この言葉の微妙なニュアンスが難しい。', 'この ことばの びみょうな ニュアンスが むずかしい。', 'Sắc thái tinh tế của từ này thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12635, 47913, '雨の京都には独特の風情がある。', 'あめの きょうとには どくとくの ふぜいが ある。', 'Kyoto trong mưa mang một nét thú vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12636, 47914, '茶道はわび・さびの心を大切にする。', 'さどうは わび・さびの こころを たいせつに する。', 'Trà đạo coi trọng tinh thần wabi-sabi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12637, 47917, '彼は医学界の権威だ。', 'かれは いがくかいの けんいだ。', 'Ông ấy là người có uy tín hàng đầu trong giới y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12638, 47918, 'この町は昔、港町として栄えた。', 'この まちは むかし、みなとまちと して さかえた。', 'Ngày xưa thị trấn này thịnh vượng như một thương cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12639, 47920, '歴史を遡ると、この町の起源がわかる。', 'れきしを さかのぼると、この まちの きげんが わかる。', 'Truy ngược lịch sử sẽ biết được nguồn gốc thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12640, 47922, '日本では礼儀を重んじる。', 'にほんでは れいぎを おもんじる。', 'Ở Nhật người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12641, 47923, '長い歴史の中で培われた技術だ。', 'ながい れきしの なかで つちかわれた ぎじゅつだ。', 'Đây là kỹ thuật được vun đắp qua lịch sử lâu dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12642, 47925, '式典は厳かな雰囲気の中で行われた。', 'しきてんは おごそかな ふんいきの なかで おこなわれた。', 'Buổi lễ được tổ chức trong bầu không khí trang nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12643, 47928, '伝統の技は脈々と受け継がれている。', 'でんとうの わざは みゃくみゃくと うけつがれて いる。', 'Kỹ thuật truyền thống được kế thừa không ngừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12644, 47911, 'この言葉の微妙なニュアンスが難しい。', 'この ことばの びみょうな ニュアンスが むずかしい。', 'Sắc thái tinh tế của từ này thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12645, 48273, '雨の京都には独特の風情がある。', 'あめの きょうとには どくとくの ふぜいが ある。', 'Kyoto trong mưa mang một nét thú vị riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12646, 48275, '彼の着物の着こなしは粋だ。', 'かれの きものの きこなしは いきだ。', 'Cách anh ấy mặc kimono thật thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12647, 48277, '彼は医学界の権威だ。', 'かれは いがくかいの けんいだ。', 'Ông ấy là người có uy tín hàng đầu trong giới y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12648, 48278, 'この町は昔、港町として栄えた。', 'この まちは むかし、みなとまちと して さかえた。', 'Ngày xưa thị trấn này thịnh vượng như một thương cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12649, 48280, '歴史を遡ると、この町の起源がわかる。', 'れきしを さかのぼると、この まちの きげんが わかる。', 'Truy ngược lịch sử sẽ biết được nguồn gốc thị trấn này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12650, 48282, '日本では礼儀を重んじる。', 'にほんでは れいぎを おもんじる。', 'Ở Nhật người ta coi trọng lễ nghi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12651, 48284, '日本料理の世界は奥深い。', 'にほん りょうりの せかいは おくぶかい。', 'Thế giới ẩm thực Nhật Bản thật thâm sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12652, 48285, '式典は厳かな雰囲気の中で行われた。', 'しきてんは おごそかな ふんいきの なかで おこなわれた。', 'Buổi lễ được tổ chức trong bầu không khí trang nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12653, 48287, '田舎の人々は素朴で温かい。', 'いなかの ひとびとは そぼくで あたたかい。', 'Người dân quê mộc mạc và ấm áp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12654, 48271, 'この言葉の微妙なニュアンスが難しい。', 'この ことばの びみょうな ニュアンスが むずかしい。', 'Sắc thái tinh tế của từ này thật khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12655, 31742, '知識を体系的に整理した。', 'ちしきを たいけいてきに せいり した。', 'Tôi sắp xếp kiến thức một cách có hệ thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12656, 31775, '彼は医学界の権威だ。', 'かれは いがくかいの けんいだ。', 'Ông ấy là người có uy tín hàng đầu trong giới y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12657, 38267, '彼の几帳面さは仕事にも表れている。', 'かれの きちょうめんさは しごとにも あらわれて いる。', 'Tính tỉ mỉ của anh ấy thể hiện cả trong công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12658, 40399, '社長のお供で出張に行った。', 'しゃちょうの おともで しゅっちょうに いった。', 'Tôi tháp tùng giám đốc đi công tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12659, 40395, '彼は先生の前でおどおどしていた。', 'かれは せんせいの まえで おどおど して いた。', 'Cậu ấy rụt rè trước mặt thầy giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12660, 40412, 'カメラマンが結婚式の写真を撮った。', 'カメラマンが けっこんしきの しゃしんを とった。', 'Nhiếp ảnh gia đã chụp ảnh cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12661, 40413, '医者はカルテを見ながら説明した。', 'いしゃは カルテを みながら せつめい した。', 'Bác sĩ vừa xem hồ sơ bệnh án vừa giải thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12662, 40572, 'ミセス田中は料理教室の先生だ。', 'ミセス たなかは りょうり きょうしつの せんせいだ。', 'Bà Tanaka là giáo viên lớp nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12663, 40604, 'いつも私が悪者にされる。', 'いつも わたしが わるものに される。', 'Lúc nào tôi cũng bị biến thành kẻ xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12664, 40610, '医者に一週間の安静を言われた。', 'いしゃに いっしゅうかんの あんせいを いわれた。', 'Bác sĩ bảo tôi phải nghỉ ngơi tĩnh dưỡng một tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12665, 40632, '彼は育ちがいいので、礼儀正しい。', 'かれは そだちが いいので、れいぎ ただしい。', 'Anh ấy được nuôi dạy tốt nên rất lễ phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12666, 40662, '祖父は店を息子に任せて隠居した。', 'そふは みせを むすこに まかせて いんきょ した。', 'Ông tôi giao cửa hàng cho con trai rồi về nghỉ hưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12667, 40666, '嘘つきだと思われたくない。', 'うそつきだと おもわれたく ない。', 'Tôi không muốn bị nghĩ là kẻ nói dối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12668, 40676, '彼は国の英雄として尊敬されている。', 'かれは くにの えいゆうと して そんけい されて いる。', 'Ông ấy được kính trọng như một anh hùng dân tộc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12669, 40691, '姉に縁談が持ち込まれた。', 'あねに えんだんが もちこまれた。', 'Có người đến mai mối cho chị tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12670, 40716, '何か悪いものを食べて、下痢をした。', 'なにか わるい ものを たべて、げりを した。', 'Ăn phải thứ gì không tốt nên tôi bị tiêu chảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12671, 40706, '臆病な性格を直したい。', 'おくびょうな せいかくを なおしたい。', 'Tôi muốn sửa tính nhút nhát của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12672, 40730, '彼は十五歳のとき、家出をした。', 'かれは じゅうごさいの とき、いえでを した。', 'Năm mười lăm tuổi anh ấy đã bỏ nhà ra đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12673, 40759, '医学部の学生は解剖の実習をする。', 'いがくぶの がくせいは かいぼうの じっしゅうを する。', 'Sinh viên y thực tập giải phẫu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12674, 40803, '転んで顎を打った。', 'ころんで あごを うった。', 'Tôi ngã và bị đập vào cằm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12675, 40824, 'この布は柔らかい感触がする。', 'この ぬのは やわらかい かんしょくが する。', 'Tấm vải này có cảm giác mềm mại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12676, 40844, '二人は親友の間柄だ。', 'ふたりは しんゆうの あいだがらだ。', 'Hai người có quan hệ bạn thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12677, 40852, '目が痛いので、眼科に行った。', 'めが いたいので、がんかに いった。', 'Mắt bị đau nên tôi đến khoa mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12678, 40857, '彼は真剣な顔付きで話を聞いていた。', 'かれは しんけんな かおつきで はなしを きいて いた。', 'Anh ấy lắng nghe với vẻ mặt nghiêm túc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12819, 40956, '犬は雷の音に怯えている。', 'いぬは かみなりの おとに おびえて いる。', 'Con chó sợ hãi trước tiếng sấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12679, 40869, 'この会社は既婚の女性社員が多い。', 'この かいしゃは きこんの じょせい しゃいんが おおい。', 'Công ty này có nhiều nhân viên nữ đã kết hôn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12680, 40879, '新しい化粧品で肌がかぶれた。', 'あたらしい けしょうひんで はだが かぶれた。', 'Da tôi bị dị ứng vì mỹ phẩm mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12681, 40930, 'レストランの給仕が料理を運んできた。', 'レストランの きゅうじが りょうりを はこんで きた。', 'Người phục vụ nhà hàng mang món ăn ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12682, 40941, '彼の考えに深く共感した。', 'かれの かんがえに ふかく きょうかん した。', 'Tôi đồng cảm sâu sắc với suy nghĩ của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12683, 40991, '近眼なので、眼鏡が必要だ。', 'きんがん なので、めがねが ひつようだ。', 'Tôi bị cận nên cần đeo kính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12684, 41007, '空腹で薬を飲まないでください。', 'くうふくで くすりを のまないで ください。', 'Đừng uống thuốc khi bụng đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12685, 41042, '昔、結核は死に至る病気だった。', 'むかし、けっかくは しに いたる びょうき だった。', 'Ngày xưa bệnh lao là bệnh có thể gây tử vong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12686, 41064, '両親の勧めで見合いをした。', 'りょうしんの すすめで みあいを した。', 'Theo lời khuyên của bố mẹ, tôi đã đi xem mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12687, 41068, '教育的な見地から考えると、この番組は問題がある。', 'きょういくてきな けんちから かんがえると、この ばんぐみは もんだいが ある。', 'Xét từ quan điểm giáo dục thì chương trình này có vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12688, 41092, '彼の料理の腕は玄人並みだ。', 'かれの りょうりの うでは くろうとなみだ。', 'Tay nghề nấu ăn của anh ấy ngang với dân chuyên nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12689, 41090, '式典は厳かな雰囲気の中で行われた。', 'しきてんは おごそかな ふんいきの なかで おこなわれた。', 'Buổi lễ được tổ chức trong bầu không khí trang nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12690, 41187, '彼女は日本人とフランス人の混血だ。', 'かのじょは にほんじんと フランスじんの こんけつだ。', 'Cô ấy là con lai Nhật – Pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12691, 41201, '病気の再発を防ぐために、薬を飲み続けている。', 'びょうきの さいはつを ふせぐ ために、くすりを のみ つづけて いる。', 'Để phòng bệnh tái phát, tôi vẫn tiếp tục uống thuốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12692, 41221, '忙しくて、夫婦の擦れ違いが続いている。', 'いそがしくて、ふうふの すれちがいが つづいて いる。', 'Vì bận rộn, hai vợ chồng liên tục lỡ dịp gặp nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12693, 41236, '姉は先月、女の子を産んだ。', 'あねは せんげつ、おんなのこを うんだ。', 'Tháng trước chị tôi sinh một bé gái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12694, 41239, '妊娠したので、産婦人科に通っている。', 'にんしん したので、さんふじんかに かよって いる。', 'Có thai nên tôi đang khám ở khoa sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12695, 41254, '子供を厳しく仕付けた。', 'こどもを きびしく しつけた。', 'Tôi dạy dỗ con một cách nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12696, 41257, 'その屋敷には使用人が何人もいた。', 'その やしきには しようにんが なんにんも いた。', 'Dinh thự đó có nhiều người làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12697, 41277, '氏より育ち。', 'うじより そだち。', 'Dòng dõi không bằng cách nuôi dạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12698, 41307, '鼻が詰まるので、耳鼻科に行った。', 'はなが つまるので、じびかに いった。', 'Mũi bị nghẹt nên tôi đến khoa tai mũi họng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12699, 41315, '大学を卒業して、親から自立した。', 'だいがくを そつぎょう して、おやから じりつ した。', 'Tốt nghiệp đại học xong tôi đã tự lập khỏi bố mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12700, 41459, 'この店は庶民的な値段で人気がある。', 'この みせは しょみんてきな ねだんで にんきが ある。', 'Quán này được ưa chuộng nhờ giá bình dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12701, 41469, '昔は「おなご」という言葉がよく使われた。', 'むかしは 「おなご」と いう ことばが よく つかわれた。', 'Ngày xưa người ta hay dùng từ "onago" để chỉ phụ nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12702, 41474, '昔話に旅の商人が出てくる。', 'むかしばなしに たびの あきうどが でて くる。', 'Trong truyện cổ có xuất hiện một thương nhân đi buôn xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12703, 41482, '彼女は少女のように目を輝かせた。', 'かのじょは おとめの ように めを かがやかせた。', 'Cô ấy mắt sáng lên như một thiếu nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12704, 41506, '彼は堂々とした丈夫だ。', 'かれは どうどうと した じょうふだ。', 'Anh ấy là một bậc trượng phu đường hoàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12705, 41536, '初めての一人暮らしは心細い。', 'はじめての ひとりぐらしは こころぼそい。', 'Lần đầu sống một mình thấy bất an.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12706, 41543, '二人は新婚旅行でハワイに行った。', 'ふたりは しんこん りょこうで ハワイに いった。', 'Hai người đi Hawaii hưởng tuần trăng mật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12707, 41544, '今年は新人が五人入社した。', 'ことしは しんじんが ごにん にゅうしゃ した。', 'Năm nay có năm nhân viên mới vào công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12708, 41585, '人目を引く派手な服を着ている。', 'じんもくを ひく はでな ふくを きて いる。', 'Cô ấy mặc bộ đồ sặc sỡ thu hút ánh nhìn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12709, 41608, '世代によって考え方が違う。', 'せだいに よって かんがえかたが ちがう。', 'Mỗi thế hệ có cách nghĩ khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12710, 41656, '店の跡継ぎがいなくて困っている。', 'みせの あとつぎが いなくて こまって いる。', 'Không có người nối nghiệp cửa hàng nên rất khổ tâm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12711, 41658, '別れの場面は切なかった。', 'わかれの ばめんは せつなかった。', 'Cảnh chia ly thật da diết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12712, 41662, '住民の切実な声に耳を傾けるべきだ。', 'じゅうみんの せつじつな こえに みみを かたむける べきだ。', 'Cần lắng nghe tiếng nói bức thiết của người dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12713, 41877, '結婚式で仲人があいさつをした。', 'けっこんしきで なこうどが あいさつを した。', 'Người mai mối phát biểu trong lễ cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13318, 40639, '一頃ほど忙しくなくなった。', 'ひところ ほど いそがしく なく なった。', 'Không còn bận như có một dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12714, 41897, '彼は村の長として尊敬されている。', 'かれは むらの おさと して そんけい されて いる。', 'Ông ấy được kính trọng như người đứng đầu làng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12715, 41921, '彼はワインの通だ。', 'かれは ワインの つうだ。', 'Anh ấy là người sành rượu vang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12716, 41993, '当人がそう言っているのだから、間違いない。', 'とうにんが そう いって いるの だから、まちがいない。', 'Chính người đó đã nói vậy thì không sai được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12717, 42013, '彼とは同い年なので、話しやすい。', 'かれとは おないどし なので、はなしやすい。', 'Tôi với anh ấy cùng tuổi nên dễ nói chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12718, 42048, '二人三脚で会社を大きくした。', 'ににん さんきゃくで かいしゃを おおきく した。', 'Hai người cùng sát cánh làm công ty lớn mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12719, 42050, '戦争で肉親を失った人は多い。', 'せんそうで にくしんを うしなった ひとは おおい。', 'Nhiều người mất người thân ruột thịt vì chiến tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12720, 42077, 'クラスで一番年長の人がリーダーになった。', 'クラスで いちばん ねんちょうの ひとが リーダーに なった。', 'Người lớn tuổi nhất lớp trở thành trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12721, 42107, '配偶者の名前を書いてください。', 'はいぐうしゃの なまえを かいて ください。', 'Hãy ghi tên vợ/chồng của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12722, 42154, 'このクラスの男女の比率は半々だ。', 'この クラスの だんじょの ひりつは はんはんだ。', 'Tỷ lệ nam nữ của lớp này là một nửa mỗi bên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12723, 42192, '仕事の後、上司の飲み会に付き合った。', 'しごとの あと、じょうしの のみかいに つきあった。', 'Sau giờ làm tôi đi nhậu cùng cấp trên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12724, 42201, '彼は三人の家族を扶養している。', 'かれは さんにんの かぞくを ふよう して いる。', 'Anh ấy đang nuôi ba người trong gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12725, 42206, '父母の恩は一生忘れない。', 'ちちははの おんは いっしょう わすれない。', 'Công ơn cha mẹ tôi suốt đời không quên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12726, 42231, '大臣の発言が物議を醸した。', 'だいじんの はつげんが ぶつぎを かもした。', 'Phát ngôn của bộ trưởng đã gây xôn xao dư luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12727, 42256, '古い法律は文語で書かれている。', 'ふるい ほうりつは ぶんごで かかれて いる。', 'Luật cũ được viết bằng văn ngôn cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12728, 42280, 'この施設では零歳から保育している。', 'この しせつでは れいさいから ほいく して いる。', 'Cơ sở này nhận giữ trẻ từ không tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12729, 42324, 'お隣の坊ちゃんは礼儀正しい。', 'おとなりの ぼっちゃんは れいぎ ただしい。', 'Cậu bé nhà bên rất lễ phép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12730, 42325, '選挙の結果に不満を持つ人々が暴動を起こした。', 'せんきょの けっかに ふまんを もつ ひとびとが ぼうどうを おこした。', 'Những người bất mãn với kết quả bầu cử đã gây bạo động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12731, 42335, '物語の中で、少年は王の僕として働いた。', 'ものがたりの なかで、しょうねんは おうの しもべと して はたらいた。', 'Trong câu chuyện, cậu bé làm đầy tớ cho nhà vua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12732, 42353, 'この薬が万人に効くわけではない。', 'この くすりが ばんじんに きく わけでは ない。', 'Thuốc này không phải ai dùng cũng hiệu quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12733, 42363, '未婚の若者が増えている。', 'みこんの わかものが ふえて いる。', 'Số người trẻ chưa kết hôn đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12734, 42390, '娘の婿はとても優しい人だ。', 'むすめの むこは とても やさしい ひとだ。', 'Con rể tôi là người rất hiền lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12735, 42409, '病院の面会時間は午後三時からだ。', 'びょういんの めんかい じかんは ごご さんじからだ。', 'Giờ thăm bệnh của bệnh viện bắt đầu từ ba giờ chiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12736, 42480, '彼は働いて家族を養っている。', 'かれは はたらいて かぞくを やしなって いる。', 'Anh ấy làm việc để nuôi gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12737, 42481, '姉は養護学校で働いている。', 'あねは ようご がっこうで はたらいて いる。', 'Chị tôi làm việc ở trường dành cho trẻ khuyết tật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12738, 42547, 'けがをした選手を仲間が労った。', 'けがを した せんしゅを なかまが いたわった。', 'Đồng đội đã an ủi cầu thủ bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12739, 42568, 'うちの伜が大学に合格しました。', 'うちの せがれが だいがくに ごうかく しました。', 'Thằng con trai nhà tôi đã đỗ đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12740, 41015, '犯罪には刑罰が科される。', 'はんざいには けいばつが かされる。', 'Tội phạm sẽ bị áp hình phạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12741, 43248, 'この店はヤング向けの服が多い。', 'この みせは ヤングむけの ふくが おおい。', 'Cửa hàng này có nhiều quần áo dành cho giới trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12742, 40479, 'お客様にぞんざいな言葉を使ってはいけない。', 'おきゃくさまに ぞんざいな ことばを つかっては いけない。', 'Không được dùng lời lẽ thô lỗ với khách hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12743, 41312, '学生の自主性を大切にしている。', 'がくせいの じしゅせいを たいせつに して いる。', 'Chúng tôi coi trọng tính tự chủ của học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12744, 41564, '子供のころから自然に親しんで育った。', 'こどもの ころから しぜんに したしんで そだった。', 'Tôi lớn lên gần gũi với thiên nhiên từ nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12745, 41581, '下町の人々は人情に厚い。', 'したまちの ひとびとは にんじょうに あつい。', 'Người dân khu phố cổ giàu tình người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12746, 41583, '彼の人柄に引かれた。', 'かれの ひとがらに ひかれた。', 'Tôi bị cuốn hút bởi tính cách của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12747, 41972, '他人の成功を妬んでも仕方がない。', 'たにんの せいこうを ねたんでも しかたが ない。', 'Ghen tị với thành công của người khác cũng chẳng được gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12748, 31733, '事故の後、彼はしばらく意識を失っていた。', 'じこの あと、かれは しばらく いしきを うしなって いた。', 'Sau tai nạn, anh ấy bất tỉnh một lúc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12749, 31737, '直感でこの店に入ることにした。', 'ちょっかんで この みせに はいる ことに した。', 'Theo trực giác, tôi quyết định vào quán này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12750, 37850, '都会の生活に幻想を抱いていた。', 'とかいの せいかつに げんそうを いだいて いた。', 'Tôi từng có ảo tưởng về cuộc sống thành thị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12751, 38253, '熟考の末、転職を決めた。', 'じゅっこうの すえ、てんしょくを きめた。', 'Sau khi suy nghĩ kỹ lưỡng, tôi quyết định chuyển việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12752, 40432, '職場ではコミュニケーションが大切だ。', 'しょくばでは コミュニケーションが たいせつだ。', 'Ở nơi làm việc, giao tiếp rất quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12753, 40522, 'そんな意見はナンセンスだ。', 'そんな いけんは ナンセンスだ。', 'Ý kiến như thế thật vô nghĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12754, 40575, 'この映画には強いメッセージが込められている。', 'この えいがには つよい メッセージが こめられて いる。', 'Bộ phim này chứa đựng một thông điệp mạnh mẽ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12755, 41781, '住民は新しい駅の完成を待ち望んでいる。', 'じゅうみんは あたらしい えきの かんせいを まちのぞんで いる。', 'Người dân ngóng chờ nhà ga mới hoàn thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12756, 41782, '待望の新作がついに発売された。', 'たいぼうの しんさくが ついに はつばい された。', 'Tác phẩm mới được mong đợi từ lâu cuối cùng đã ra mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12757, 41788, '走りすぎて、腿が痛い。', 'はしりすぎて、ももが いたい。', 'Chạy nhiều quá nên đau đùi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12758, 42096, '彼は大声で相手を罵った。', 'かれは おおごえで あいてを ののしった。', 'Anh ta lớn tiếng chửi mắng đối phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12759, 41805, '大柄な男性が入口に立っていた。', 'おおがらな だんせいが いりぐちに たって いた。', 'Một người đàn ông to lớn đứng ở lối vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12760, 41818, '彼は友人の死を深く嘆いた。', 'かれは ゆうじんの しを ふかく なげいた。', 'Anh ấy đau buồn than khóc trước cái chết của bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12761, 41820, 'けが人は担架で運ばれた。', 'けがにんは たんかで はこばれた。', 'Người bị thương được khiêng bằng cáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12762, 41829, '毎朝走って体を鍛えている。', 'まいあさ はしって からだを きたえて いる。', 'Sáng nào tôi cũng chạy bộ rèn luyện thân thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12763, 41850, '知らないことを聞くのは恥ではない。', 'しらない ことを きくのは はじでは ない。', 'Hỏi điều mình không biết không phải là điều đáng xấu hổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12764, 41861, '煙を吸って窒息しそうになった。', 'けむりを すって ちっそく しそうに なった。', 'Hít phải khói, tôi suýt ngạt thở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12765, 41873, '古い魚を食べて食中毒になった。', 'ふるい さかなを たべて しょく ちゅうどくに なった。', 'Ăn cá ôi nên tôi bị ngộ độc thực phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12766, 37856, '批判の矛先が政府に向けられた。', 'ひはんの ほこさきが せいふに むけられた。', 'Mũi nhọn chỉ trích đã nhắm vào chính phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12767, 40402, 'こんなに難しい問題はお手上げだ。', 'こんなに むずかしい もんだいは おてあげだ。', 'Câu khó thế này thì tôi chịu thua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12768, 31739, '彼の哲学は思弁的すぎて、わかりにくい。', 'かれの てつがくは しべんてき すぎて、わかりにくい。', 'Triết học của ông ấy quá thiên về suy biện nên khó hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12769, 31753, '結婚相手とは価値観が合うことが大切だ。', 'けっこん あいてとは かちかんが あう ことが たいせつだ。', 'Hợp nhau về giá trị quan với người bạn đời là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12770, 31763, '利己的な考えでは人に信頼されない。', 'りこてきな かんがえでは ひとに しんらい されない。', 'Suy nghĩ ích kỷ thì không được người khác tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12771, 31764, '仏教では慈悲の心を大切にする。', 'ぶっきょうでは じひの こころを たいせつに する。', 'Phật giáo coi trọng lòng từ bi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12772, 31759, '彼は理想主義で、現実を見ていない。', 'かれは りそう しゅぎで、げんじつを みて いない。', 'Anh ta duy tâm lý tưởng, không nhìn vào hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12773, 37837, '彼は若いころ、哲学に傾倒していた。', 'かれは わかい ころ、てつがくに けいとう して いた。', 'Hồi trẻ ông ấy say mê triết học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12774, 37838, '彼は研究に没頭している。', 'かれは けんきゅうに ぼっとう して いる。', 'Anh ấy đang chuyên tâm vào nghiên cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12775, 37839, '古いやり方に固執していては進歩しない。', 'ふるい やりかたに こしつ して いては しんぽ しない。', 'Khư khư giữ cách làm cũ thì không tiến bộ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12776, 37853, 'この研究は今後の方向性を示唆している。', 'この けんきゅうは こんごの ほうこうせいを しさ して いる。', 'Nghiên cứu này gợi ý hướng đi sau này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12777, 37854, '物語の最初に結末が暗示されている。', 'ものがたりの さいしょに けつまつが あんじ されて いる。', 'Cái kết đã được ám chỉ ngay từ đầu câu chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12778, 37858, '新聞に新作映画の論評が載った。', 'しんぶんに しんさく えいがの ろんぴょうが のった。', 'Trên báo có đăng bài bình luận về bộ phim mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12779, 37894, '彼は一途に彼女を愛し続けた。', 'かれは いちずに かのじょを あいし つづけた。', 'Anh ấy một lòng một dạ yêu cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12780, 37882, 'どんな理由があっても、暴力を正当化することはできない。', 'どんな りゆうが あっても、ぼうりょくを せいとうか する ことは できない。', 'Dù lý do gì cũng không thể biện minh cho bạo lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12781, 37884, '誤解を招いたことについて釈明した。', 'ごかいを まねいた ことに ついて しゃくめい した。', 'Tôi đã giải thích để làm rõ việc gây hiểu lầm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12782, 38261, '店員の横柄な態度に腹が立った。', 'てんいんの おうへいな たいどに はらが たった。', 'Tôi tức giận vì thái độ hống hách của nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12783, 38252, '会社は人材不足の対策に苦慮している。', 'かいしゃは じんざい ぶそくの たいさくに くりょ して いる。', 'Công ty đang khổ sở tìm cách giải quyết tình trạng thiếu nhân lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12784, 38258, '彼女は髪を無造作に束ねていた。', 'かのじょは かみを むぞうさに たばねて いた。', 'Cô ấy buộc tóc một cách tùy tiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12785, 38263, 'そんなに卑屈になる必要はない。', 'そんなに ひくつに なる ひつようは ない。', 'Không cần phải quỵ lụy như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12786, 38265, '祖父は柔和な表情で孫を見ていた。', 'そふは にゅうわな ひょうじょうで まごを みて いた。', 'Ông nhìn cháu với vẻ mặt hiền hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12787, 38268, '彼は生真面目すぎて、冗談が通じない。', 'かれは きまじめ すぎて、じょうだんが つうじない。', 'Anh ấy nghiêm túc thái quá nên không hiểu được câu đùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12788, 38270, '大雑把な計算だが、費用は十万円ぐらいだ。', 'おおざっぱな けいさん だが、ひようは じゅうまんえん ぐらいだ。', 'Tính đại khái thì chi phí khoảng một trăm nghìn yên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12789, 38248, '各国の思惑が絡み合っている。', 'かっこくの おもわくが からみあって いる。', 'Những tính toán ngầm của các nước đan xen vào nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12790, 38249, '彼の親切の裏には何か魂胆がありそうだ。', 'かれの しんせつの うらには なにか こんたんが ありそうだ。', 'Đằng sau sự tử tế của anh ta dường như có ý đồ gì đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12791, 38251, '苦心して作った作品が賞を取った。', 'くしん して つくった さくひんが しょうを とった。', 'Tác phẩm tôi dày công làm ra đã đoạt giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12792, 38283, '専門家は環境の悪化を危惧している。', 'せんもんかは かんきょうの あっかを きぐ して いる。', 'Các chuyên gia lo ngại môi trường ngày càng xấu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12793, 38285, '心配していたが、杞憂に終わった。', 'しんぱい して いたが、きゆうに おわった。', 'Tôi đã lo lắng nhưng hóa ra là lo xa vô ích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12794, 40371, 'あくどい商売で金を稼いでいる。', 'あくどい しょうばいで かねを かせいで いる。', 'Hắn kiếm tiền bằng lối buôn bán thâm hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12795, 40430, '彼は材料にこだわって料理を作る。', 'かれは ざいりょうに こだわって りょうりを つくる。', 'Anh ấy rất khắt khe về nguyên liệu khi nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12796, 40447, '彼はしぶとく最後まであきらめなかった。', 'かれは しぶとく さいごまで あきらめなかった。', 'Anh ấy bền bỉ không bỏ cuộc đến phút cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12797, 40540, '先生がヒントをくれたので、問題が解けた。', 'せんせいが ヒントを くれたので、もんだいが とけた。', 'Thầy cho gợi ý nên tôi giải được bài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12798, 40568, '初めての駅で、まごついてしまった。', 'はじめての えきで、まごついて しまった。', 'Lần đầu đến ga này nên tôi lúng túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12799, 40589, '彼は時間にルーズだ。', 'かれは じかんに ルーズだ。', 'Anh ta không đúng giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12800, 40564, '父は給料が安いとぼやいている。', 'ちちは きゅうりょうが やすいと ぼやいて いる。', 'Bố tôi càu nhàu rằng lương thấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12801, 40601, 'あの店員は愛想がいい。', 'あの てんいんは あいそが いい。', 'Nhân viên kia rất niềm nở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12802, 40613, '母は息子の将来を案じている。', 'ははは むすこの しょうらいを あんじて いる。', 'Mẹ lo lắng cho tương lai của con trai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12803, 40603, '彼は悪口雑言を浴びせた。', 'かれは あっこう ぞうごんを あびせた。', 'Hắn tuôn ra những lời lẽ xúc phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12804, 40621, '彼は必ず優勝すると意気込んでいる。', 'かれは かならず ゆうしょう すると いきごんで いる。', 'Anh ấy hăng hái tuyên bố nhất định sẽ vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12805, 40624, 'その案に異論はありません。', 'その あんに いろんは ありません。', 'Tôi không có ý kiến phản đối với đề án đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12806, 40679, '人の弱みにつけ込むなんていやらしい。', 'ひとの よわみに つけこむ なんて いやらしい。', 'Lợi dụng điểm yếu của người khác thật đáng ghét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12807, 40713, '彼の親切には下心がありそうだ。', 'かれの しんせつには したごころが ありそうだ。', 'Sự tử tế của anh ta có vẻ có ý đồ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12808, 40741, '要点を箇条書きにしてください。', 'ようてんを かじょうがきに して ください。', 'Hãy liệt kê các điểm chính theo từng mục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12809, 40765, 'この犬はすぐに私に懐いた。', 'この いぬは すぐに わたしに なついた。', 'Con chó này quấn quýt với tôi ngay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12810, 40801, '状況を楽観するのはまだ早い。', 'じょうきょうを らっかん するのは まだ はやい。', 'Lạc quan về tình hình lúc này vẫn còn quá sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12811, 40788, '計画の概略を説明します。', 'けいかくの がいりゃくを せつめい します。', 'Tôi xin giải thích tóm lược kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12812, 40815, '今回だけは勘弁してください。', 'こんかい だけは かんべん して ください。', 'Xin hãy tha thứ cho tôi lần này thôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12813, 40816, '先生の勧めで留学することにした。', 'せんせいの すすめで りゅうがく する ことに した。', 'Theo lời khuyên của thầy, tôi quyết định đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12814, 40839, '社長になって、彼には貫禄が出てきた。', 'しゃちょうに なって、かれには かんろくが でて きた。', 'Làm giám đốc rồi, ông ấy có phong thái uy nghi hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12815, 40873, '猫は気まぐれな動物だ。', 'ねこは きまぐれな どうぶつだ。', 'Mèo là loài vật có tính khí thất thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12816, 40875, 'いつでも気軽に遊びに来てください。', 'いつでも きがるに あそびに きて ください。', 'Cứ thoải mái đến chơi bất cứ lúc nào nhé.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12817, 40878, '彼の話し方はちょっと気障だ。', 'かれの はなしかたは ちょっと きざだ。', 'Cách nói chuyện của anh ta hơi làm bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12818, 40882, '彼女は気立てのいい娘だ。', 'かのじょは きだての いい むすめだ。', 'Cô ấy là cô gái có tính nết tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12820, 40973, 'パソコンを使いすぎて、肩が凝った。', 'パソコンを つかいすぎて、かたが こった。', 'Dùng máy tính nhiều quá nên tôi bị mỏi cứng vai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12821, 40985, '日本人は勤勉だと言われる。', 'にほんじんは きんべんだと いわれる。', 'Người ta nói người Nhật cần cù.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12822, 41004, '努力が空しく終わった。', 'どりょくが むなしく おわった。', 'Nỗ lực rốt cuộc trở nên vô ích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12823, 41030, '人を軽蔑するような目で見てはいけない。', 'ひとを けいべつ する ような めで みては いけない。', 'Không được nhìn người khác bằng ánh mắt khinh miệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12824, 41033, '名前を間違えて、決まり悪い思いをした。', 'なまえを まちがえて、きまりわるい おもいを した。', 'Nhầm tên nên tôi thấy ngượng ngùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12825, 41073, '彼は誰に対してもへりくだった態度をとる。', 'かれは だれに たいしても へりくだった たいどを とる。', 'Anh ấy luôn có thái độ khiêm nhường với mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12826, 41139, '彼女は彼に好意を持っている。', 'かのじょは かれに こういを もって いる。', 'Cô ấy có cảm tình với anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12827, 41152, '彼は運転が荒っぽい。', 'かれは うんてんが あらっぽい。', 'Anh ta lái xe ẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12828, 41208, '母の細やかな気配りに感謝している。', 'ははの こまやかな きくばりに かんしゃ して いる。', 'Tôi biết ơn sự chu đáo tỉ mỉ của mẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12829, 41309, '子供は三歳ごろから自我が芽生える。', 'こどもは さんさいごろから じがが めばえる。', 'Trẻ bắt đầu hình thành cái tôi từ khoảng ba tuổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12830, 41310, '少し成功しただけで、自惚れてはいけない。', 'すこし せいこう した だけで、うぬぼれては いけない。', 'Mới thành công một chút thì không được tự phụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12831, 41321, 'お金に執着する生き方はしたくない。', 'おかねに しゅうじゃく する いきかたは したく ない。', 'Tôi không muốn sống bám víu vào tiền bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12832, 41481, '彼女は小柄だが、力が強い。', 'かのじょは こがら だが、ちからが つよい。', 'Cô ấy nhỏ nhắn nhưng rất khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12833, 41491, '時間がなくて焦った。', 'じかんが なくて あせった。', 'Không còn thời gian nên tôi sốt ruột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12834, 41510, '情けは人のためならず。', 'なさけは ひとの ためならず。', 'Thương người là thương mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12835, 41512, 'この町には下町の情緒が残っている。', 'この まちには したまちの じょうしょが のこって いる。', 'Thị trấn này vẫn còn nét tình cảm của khu phố cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12836, 41566, 'この病院の診療時間は午前九時からだ。', 'この びょういんの しんりょう じかんは ごぜん くじからだ。', 'Giờ khám bệnh của bệnh viện này bắt đầu từ chín giờ sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12837, 41582, 'この物質は人体に害はない。', 'この ぶっしつは じんたいに がいは ない。', 'Chất này không gây hại cho cơ thể người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12838, 41633, '彼は生まれつき体が弱い。', 'かれは うまれつき からだが よわい。', 'Anh ấy bẩm sinh đã yếu ớt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12839, 41655, '恥ずかしくて、顔が赤らんだ。', 'はずかしくて、かおが あからんだ。', 'Xấu hổ quá, mặt tôi ửng đỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12840, 41648, '誠を尽くして説明すれば、わかってもらえる。', 'まことを つくして せつめい すれば、わかって もらえる。', 'Nếu giải thích bằng cả tấm lòng chân thành thì họ sẽ hiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12841, 41672, '何度失敗しても、絶望しなかった。', 'なんど しっぱい しても、ぜつぼう しなかった。', 'Dù thất bại bao nhiêu lần, tôi vẫn không tuyệt vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12842, 41684, 'お金のために友達を裏切るなんて浅ましい。', 'おかねの ために ともだちを うらぎる なんて あさましい。', 'Phản bội bạn vì tiền thật đáng khinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12843, 41704, 'けがが全快して、仕事に戻った。', 'けがが ぜんかい して、しごとに もどった。', 'Vết thương đã lành hẳn, tôi quay lại làm việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12844, 41707, '仕事に夢中で、家庭を疎かにしてしまった。', 'しごとに むちゅうで、かていを おろそかに して しまった。', 'Mải mê công việc nên tôi đã sao nhãng gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12845, 41759, '道に唾を吐いてはいけない。', 'みちに つばを はいては いけない。', 'Không được nhổ nước bọt ra đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12846, 41768, '彼は体格がよくて、スポーツが得意だ。', 'かれは たいかくが よくて、スポーツが とくいだ。', 'Anh ấy có thể chất tốt và giỏi thể thao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12847, 41771, '父親に似て、がっしりした体付きだ。', 'ちちおやに にて、がっしり した からだつきだ。', 'Giống bố, cậu ấy có vóc dáng chắc nịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12848, 41752, 'この国では昔から礼儀を尊ぶ。', 'この くにでは むかしから れいぎを たっとぶ。', 'Ở đất nước này từ xưa người ta đã coi trọng lễ nghĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12849, 41917, '寒くなると、古い傷が痛む。', 'さむく なると、ふるい きずが いたむ。', 'Trời lạnh là vết thương cũ lại đau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12850, 41919, '経験不足を痛感した。', 'けいけん ぶそくを つうかん した。', 'Tôi cảm nhận sâu sắc sự thiếu kinh nghiệm của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12851, 42014, 'あなたの意見に同感です。', 'あなたの いけんに どうかん です。', 'Tôi đồng quan điểm với bạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12852, 42040, '彼は人の気持ちに鈍感だ。', 'かれは ひとの きもちに どんかんだ。', 'Anh ấy kém nhạy cảm với cảm xúc người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12853, 42051, 'この仕事は肉体的にきつい。', 'この しごとは にくたいてきに きつい。', 'Công việc này vất vả về thể xác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12854, 42065, '病院で尿の検査をした。', 'びょういんで にょうの けんさを した。', 'Tôi xét nghiệm nước tiểu ở bệnh viện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12855, 42071, '彼の熱意に動かされた。', 'かれの ねついに うごかされた。', 'Tôi bị lay động trước nhiệt huyết của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12856, 42086, '騒音が住民を悩ましている。', 'そうおんが じゅうみんを なやまして いる。', 'Tiếng ồn đang làm phiền cư dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12857, 42124, '子供の発育には栄養が大切だ。', 'こどもの はついくには えいようが たいせつだ。', 'Dinh dưỡng rất quan trọng cho sự phát triển của trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12858, 42131, 'ストレスが発病のきっかけになった。', 'ストレスが はつびょうの きっかけに なった。', 'Căng thẳng là nguyên nhân khởi phát bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12859, 42165, '彼は眉をひそめて話を聞いていた。', 'かれは まゆを ひそめて はなしを きいて いた。', 'Anh ấy nhíu mày lắng nghe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12860, 42147, '人を騙すような卑しいことはしたくない。', 'ひとを だます ような いやしい ことは したく ない。', 'Tôi không muốn làm điều hèn hạ như lừa người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12861, 42150, '戦争の悲惨さを忘れてはいけない。', 'せんそうの ひさんさを わすれては いけない。', 'Không được quên sự bi thảm của chiến tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12862, 42162, '彼女は微笑を浮かべて答えた。', 'かのじょは びしょうを うかべて こたえた。', 'Cô ấy mỉm cười đáp lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12863, 42180, '彼女は寒さに敏感だ。', 'かのじょは さむさに びんかんだ。', 'Cô ấy nhạy cảm với cái lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12864, 42188, '彼は判定に不服を申し立てた。', 'かれは はんていに ふふくを もうしたてた。', 'Anh ấy khiếu nại vì không phục phán quyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12865, 42189, '親を亡くした子供が不便でならない。', 'おやを なくした こどもが ふびんで ならない。', 'Đứa trẻ mất cha mẹ thật vô cùng tội nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12866, 42232, '雨の中を散歩するなんて、物好きだね。', 'あめの なかを さんぽ する なんて、ものずきだね。', 'Đi dạo dưới mưa, đúng là sở thích lạ nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12867, 42246, '不公平な判定に選手たちは憤慨した。', 'ふこうへいな はんていに せんしゅたちは ふんがい した。', 'Các cầu thủ phẫn nộ trước phán quyết bất công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12868, 42283, '温泉で保養するのが楽しみだ。', 'おんせんで ほよう するのが たのしみだ。', 'Tôi mong được nghỉ dưỡng ở suối nước nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12869, 42298, '多くの後輩が彼を慕っている。', 'おおくの こうはいが かれを したって いる。', 'Nhiều đàn em kính mến anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12870, 42345, '麻酔が切れて、痛みを感じ始めた。', 'ますいが きれて、いたみを かんじ はじめた。', 'Thuốc mê hết tác dụng, tôi bắt đầu thấy đau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12871, 42359, 'かぜで味覚がなくなった。', 'かぜで みかくが なくなった。', 'Bị cảm nên tôi mất vị giác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12872, 42372, '昼ご飯の後はいつも眠たい。', 'ひるごはんの あとは いつも ねむたい。', 'Sau bữa trưa lúc nào cũng buồn ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12873, 42385, '決勝で負けて、無念だった。', 'けっしょうで まけて、むねん だった。', 'Thua ở trận chung kết, thật tiếc nuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12874, 42386, '無能な上司の下で働くのは大変だ。', 'むのうな じょうしの もとで はたらくのは たいへんだ。', 'Làm việc dưới quyền một cấp trên bất tài thật vất vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12875, 42402, '明朗な会計を心がけている。', 'めいろうな かいけいを こころがけて いる。', 'Chúng tôi chú ý minh bạch trong kế toán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12876, 42419, '鳥の声で目覚めた。', 'とりの こえで めざめた。', 'Tôi thức giấc vì tiếng chim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12877, 42421, '彼は鋭い目付きで相手を見た。', 'かれは するどい めつきで あいてを みた。', 'Anh ta nhìn đối phương bằng ánh mắt sắc lẹm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12878, 42439, '優男という言葉は、上品で優しい男性を意味する。', 'やさおとこと いう ことばは、じょうひんで やさしい だんせいを いみ する。', 'Từ "yasaotoko" có nghĩa là người đàn ông thanh nhã, dịu dàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12879, 42453, 'ダイエット中は甘い物の誘惑に負けそうになる。', 'ダイエットちゅうは あまい ものの ゆうわくに まけそうに なる。', 'Trong lúc ăn kiêng, tôi suýt gục trước cám dỗ của đồ ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12880, 42458, '何か悪いことが起こりそうな予感がする。', 'なにか わるい ことが おこりそうな よかんが する。', 'Tôi có linh cảm sắp có chuyện không hay xảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12881, 42483, '欲深い人は満足することを知らない。', 'よくふかい ひとは まんぞく する ことを しらない。', 'Người tham lam không biết thế nào là đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12882, 42492, '試験に落ちて、ひどく落ち込んだ。', 'しけんに おちて、ひどく おちこんだ。', 'Thi trượt nên tôi buồn chán vô cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12883, 42555, '祖母は老衰で亡くなった。', 'そぼは ろうすいで なくなった。', 'Bà tôi mất vì già yếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12884, 42535, '彼は困っている人に冷淡だ。', 'かれは こまって いる ひとに れいたんだ。', 'Anh ta thờ ơ với người đang gặp khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12885, 42557, '会は和やかな雰囲気で終わった。', 'かいは なごやかな ふんいきで おわった。', 'Buổi gặp kết thúc trong bầu không khí hòa nhã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12886, 42569, '成功しても傲ることなく努力を続けた。', 'せいこう しても おごる こと なく どりょくを つづけた。', 'Dù thành công anh ấy vẫn không kiêu ngạo, tiếp tục nỗ lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12887, 42578, '昔は屎尿を肥料として使っていた。', 'むかしは しにょうを ひりょうと して つかって いた。', 'Ngày xưa người ta dùng chất thải làm phân bón.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12888, 42590, '目を瞑って、深呼吸してください。', 'めを つぶって、しんこきゅう して ください。', 'Hãy nhắm mắt lại và hít thở sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12889, 42176, '夕方、浜辺を散歩した。', 'ゆうがた、はまべを さんぽ した。', 'Chiều tối tôi đi dạo trên bãi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12890, 42603, '息子は逞しい青年に成長した。', 'むすこは たくましい せいねんに せいちょう した。', 'Con trai tôi đã trưởng thành thành chàng trai cường tráng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12891, 42605, '父の鼾がうるさくて眠れない。', 'ちちの いびきが うるさくて ねむれない。', 'Tiếng ngáy của bố to quá nên tôi không ngủ được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12892, 42584, '彼は洒落な人柄で、誰とでも仲良くなる。', 'かれは しゃらくな ひとがらで、だれとでも なかよく なる。', 'Ông ấy tính tình phóng khoáng, thân được với mọi người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12893, 41453, '彼が結婚したなんて初耳だ。', 'かれが けっこん した なんて はつみみだ。', 'Anh ấy đã kết hôn ư, lần đầu tôi nghe đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12894, 41548, '彼は自ら手伝いを申し出た。', 'かれは みずから てつだいを もうしでた。', 'Anh ấy tự nguyện đề nghị giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12895, 41551, 'ご希望の方はお申し出ください。', 'ごきぼうの かたは おもうしで ください。', 'Ai có nguyện vọng xin vui lòng đăng ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12896, 41843, '彼は知的な仕事に向いている。', 'かれは ちてきな しごとに むいて いる。', 'Anh ấy hợp với công việc trí óc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12897, 42581, '遺産のことで兄弟が揉めている。', 'いさんの ことで きょうだいが もめて いる。', 'Anh em đang tranh cãi vì chuyện thừa kế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12898, 38256, '彼は新しい計画を立案した。', 'かれは あたらしい けいかくを りつあん した。', 'Anh ấy đã lập kế hoạch mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12899, 40458, '労働者がストライキを始めた。', 'ろうどうしゃが ストライキを はじめた。', 'Công nhân đã bắt đầu đình công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12900, 40474, '彼は営業のセクションに配属された。', 'かれは えいぎょうの セクションに はいぞく された。', 'Anh ấy được phân về bộ phận kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12901, 40536, '彼はアジアでビジネスを広げている。', 'かれは アジアで ビジネスを ひろげて いる。', 'Anh ấy đang mở rộng kinh doanh ở châu Á.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12902, 41245, '彼は三十年間、主人に仕えた。', 'かれは さんじゅうねんかん、しゅじんに つかえた。', 'Ông ấy đã phục vụ chủ nhân suốt ba mươi năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12903, 41253, '店は毎朝市場で魚を仕入れている。', 'みせは まいあさ いちばで さかなを しいれて いる。', 'Sáng nào cửa hàng cũng nhập cá ở chợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12904, 41374, '彼は手回しがよく、準備はもう終わっていた。', 'かれは てまわしが よく、じゅんびは もう おわって いた。', 'Anh ấy chuẩn bị chu đáo nên mọi thứ đã sẵn sàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12905, 41385, 'けがをした人に手当てをした。', 'けがを した ひとに てあてを した。', 'Tôi đã sơ cứu cho người bị thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12906, 41386, 'ホテルの手配は私がします。', 'ホテルの てはいは わたしが します。', 'Việc đặt khách sạn để tôi sắp xếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12907, 41427, '新人には重役すぎる仕事だ。', 'しんじんには おもやく すぎる しごとだ。', 'Đây là trọng trách quá lớn đối với người mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12908, 41437, '彼は若くして出世した。', 'かれは わかく して しゅっせ した。', 'Anh ấy thăng tiến từ khi còn trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12909, 41457, 'どの部署に所属していますか。', 'どの ぶしょに しょぞく して いますか。', 'Anh thuộc phòng ban nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12910, 41523, '彼は職務に忠実だ。', 'かれは しょくむに ちゅうじつだ。', 'Anh ấy tận tụy với nhiệm vụ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12911, 41787, '家賃を三か月滞納している。', 'やちんを さんかげつ たいのう して いる。', 'Tôi đã chậm trả tiền nhà ba tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12912, 42501, '企業は利潤を追求する。', 'きぎょうは りじゅんを ついきゅう する。', 'Doanh nghiệp theo đuổi lợi nhuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12913, 42502, '借金に利息がついた。', 'しゃっきんに りそくが ついた。', 'Khoản nợ đã phát sinh tiền lãi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12914, 42528, 'この村は林業で生活している。', 'この むらは りんぎょうで せいかつ して いる。', 'Ngôi làng này sống bằng nghề lâm nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12915, 41775, '東洋と西洋の文化を対比して論じた。', 'とうようと せいようの ぶんかを たいひ して ろんじた。', 'Ông ấy so sánh đối chiếu văn hóa Đông và Tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12916, 41800, '宝くじで大金が当たった。', 'たからくじで たいきんが あたった。', 'Tôi trúng xổ số một khoản tiền lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12917, 41864, '新しい駅の工事は来月着工する。', 'あたらしい えきの こうじは らいげつ ちゃっこう する。', 'Công trình nhà ga mới sẽ khởi công vào tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12918, 38311, '作業の効率化を図る。', 'さぎょうの こうりつかを はかる。', 'Chúng tôi tìm cách nâng cao hiệu quả công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12919, 38312, '会社は経営の合理化を進めた。', 'かいしゃは けいえいの ごうりかを すすめた。', 'Công ty đã đẩy mạnh tinh giản kinh doanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12920, 40426, 'クレーンで重い荷物を運んでいる。', 'クレーンで おもい にもつを はこんで いる。', 'Người ta đang chuyển hàng nặng bằng cần cẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12921, 40574, '兄は自動車メーカーに勤めている。', 'あには じどうしゃ メーカーに つとめて いる。', 'Anh tôi làm ở một hãng sản xuất ô tô.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12922, 40671, '祖父は小さな旅館を営んでいる。', 'そふは ちいさな りょかんを いとなんで いる。', 'Ông tôi kinh doanh một lữ quán nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12923, 40712, '古い車を下取りに出して、新車を買った。', 'ふるい くるまを したどりに だして、しんしゃを かった。', 'Tôi đổi xe cũ lấy xe mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12924, 40780, '観光で外貨を稼いでいる国も多い。', 'かんこうで がいかを かせいで いる くにも おおい。', 'Nhiều nước kiếm ngoại tệ nhờ du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12925, 40806, '仕事の割り当てが決まった。', 'しごとの わりあてが きまった。', 'Việc phân công công việc đã được quyết định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12926, 40823, '会社の幹部が集まって会議をした。', 'かいしゃの かんぶが あつまって かいぎを した。', 'Ban lãnh đạo công ty đã họp với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12927, 40845, '輸入品に高い関税がかけられた。', 'ゆにゅうひんに たかい かんぜいが かけられた。', 'Hàng nhập khẩu bị đánh thuế quan cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12928, 40858, '大学に入学願書を提出した。', 'だいがくに にゅうがく がんしょを ていしゅつ した。', 'Tôi đã nộp đơn xin nhập học đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12929, 40889, '申込書に必要事項を記載してください。', 'もうしこみしょに ひつよう じこうを きさい して ください。', 'Hãy ghi các mục cần thiết vào đơn đăng ký.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12930, 40890, 'この本には当時の生活が詳しく記述されている。', 'この ほんには とうじの せいかつが くわしく きじゅつ されて いる。', 'Cuốn sách này mô tả chi tiết cuộc sống thời đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12931, 40899, 'この仕事には専門的な技能が必要だ。', 'この しごとには せんもんてきな ぎのうが ひつようだ。', 'Công việc này cần kỹ năng chuyên môn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12932, 40929, '戦後、人々は窮乏生活を送った。', 'せんご、ひとびとは きゅうぼう せいかつを おくった。', 'Sau chiến tranh, mọi người sống trong cảnh nghèo túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12933, 40958, '恐れ入りますが、もう一度お名前をお願いします。', 'おそれいりますが、もう いちど おなまえを おねがい します。', 'Xin lỗi đã làm phiền, xin cho biết lại tên một lần nữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12934, 40964, '大学で教職の資格を取った。', 'だいがくで きょうしょくの しかくを とった。', 'Tôi lấy chứng chỉ sư phạm ở trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12935, 40983, '私にこの仕事が勤まるか心配だ。', 'わたしに この しごとが つとまるか しんぱいだ。', 'Tôi lo không biết mình có đảm đương nổi công việc này không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12936, 41021, '彼は長年、新聞の編集に携わってきた。', 'かれは ながねん、しんぶんの へんしゅうに たずさわって きた。', 'Ông ấy đã nhiều năm làm công tác biên tập báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12937, 41035, '三月は決算の時期で忙しい。', 'さんがつは けっさんの じきで いそがしい。', 'Tháng ba là mùa quyết toán nên rất bận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12938, 41050, '家を買うために倹約している。', 'いえを かう ために けんやく して いる。', 'Tôi đang tiết kiệm để mua nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12939, 41076, '母の遣いで、近所に野菜を届けた。', 'ははの つかいで、きんじょに やさいを とどけた。', 'Theo lời mẹ sai, tôi mang rau sang cho hàng xóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12940, 41112, 'この一年を顧みると、いろいろなことがあった。', 'この いちねんを かえりみると、いろいろな ことが あった。', 'Nhìn lại một năm qua, đã có biết bao chuyện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12941, 41113, 'お菓子におもちゃのおまけがついている。', 'おかしに おもちゃの おまけが ついて いる。', 'Gói bánh có tặng kèm đồ chơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12942, 41132, '市は新しい公園の名前を公募した。', 'しは あたらしい こうえんの なまえを こうぼ した。', 'Thành phố kêu gọi công khai đặt tên cho công viên mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12943, 41154, '三行目から読んでください。', 'さんぎょうめから よんで ください。', 'Hãy đọc từ dòng thứ ba.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12944, 41146, '医療費の一部は税金から控除される。', 'いりょうひの いちぶは ぜいきんから こうじょ される。', 'Một phần chi phí y tế được khấu trừ thuế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12945, 41159, 'ネットで新しいパソコンを購入した。', 'ネットで あたらしい パソコンを こうにゅう した。', 'Tôi đã mua máy tính mới trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12946, 41172, '彼は勇気を出して彼女に告白した。', 'かれは ゆうきを だして かのじょに こくはく した。', 'Anh ấy lấy hết can đảm tỏ tình với cô ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12947, 41197, '卒業生による座談会が開かれた。', 'そつぎょうせいに よる ざだんかいが ひらかれた。', 'Một buổi tọa đàm của cựu sinh viên đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12948, 41195, '料金の差額をお返しします。', 'りょうきんの さがくを おかえし します。', 'Chúng tôi xin hoàn lại khoản chênh lệch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12949, 41214, 'コーヒーを飲んだら、頭が冴えてきた。', 'コーヒーを のんだら、あたまが さえて きた。', 'Uống cà phê xong đầu óc trở nên minh mẫn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12950, 41213, '福祉の財源をどう確保するかが問題だ。', 'ふくしの ざいげんを どう かくほ するかが もんだいだ。', 'Vấn đề là làm sao bảo đảm nguồn tài chính cho phúc lợi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12951, 41219, 'お気持ちをお察しします。', 'おきもちを おさっし します。', 'Tôi rất thông cảm với tâm trạng của anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12952, 41241, '多くの人が彼の勇気を賛美した。', 'おおくの ひとが かれの ゆうきを さんび した。', 'Nhiều người ca ngợi lòng dũng cảm của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12953, 41224, '駅前に雑貨の店がある。', 'えきまえに ざっかの みせが ある。', 'Trước ga có cửa hàng tạp hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12954, 41240, 'この発見は偶然の産物だ。', 'この はっけんは ぐうぜんの さんぶつだ。', 'Phát hiện này là sản phẩm của sự tình cờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12955, 41243, '口座の残高を確認した。', 'こうざの ざんだかを かくにん した。', 'Tôi đã kiểm tra số dư tài khoản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12956, 41265, '彼は高い志を持って医者になった。', 'かれは たかい こころざしを もって いしゃに なった。', 'Anh ấy trở thành bác sĩ với hoài bão lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12957, 41269, '先生に作文の間違いを指摘された。', 'せんせいに さくぶんの まちがいを してき された。', 'Tôi bị thầy chỉ ra lỗi sai trong bài văn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12958, 41268, '人の指図は受けたくない。', 'ひとの さしずは うけたく ない。', 'Tôi không muốn bị người khác sai khiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12959, 41300, '町はその事件の話で持ち切りだ。', 'まちは その じけんの はなしで もちきりだ。', 'Cả thị trấn đang bàn tán khắp nơi về vụ việc đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12960, 41282, '大臣が被災地を視察した。', 'だいじんが ひさいちを しさつ した。', 'Bộ trưởng đã thị sát vùng thiên tai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12961, 41292, '父は新しい事業を始めた。', 'ちちは あたらしい じぎょうを はじめた。', 'Bố tôi đã bắt đầu một công việc kinh doanh mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12962, 41335, '契約書の写しを保管しておいてください。', 'けいやくしょの うつしを ほかん して おいて ください。', 'Hãy lưu giữ bản sao hợp đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12963, 41340, '病状が重いので、面会は謝絶されている。', 'びょうじょうが おもいので、めんかいは しゃぜつ されて いる。', 'Bệnh tình nặng nên việc thăm hỏi bị từ chối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12964, 41333, '交通費は実費を支給します。', 'こうつうひは じっぴを しきゅう します。', 'Tiền đi lại sẽ được chi trả theo chi phí thực tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12965, 41354, 'このプロジェクトは若手が主導している。', 'この プロジェクトは わかてが しゅどう して いる。', 'Dự án này do các nhân viên trẻ dẫn dắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12966, 41355, '彼は今年、主任に昇進した。', 'かれは ことし、しゅにんに しょうしん した。', 'Năm nay anh ấy được thăng chức trưởng nhóm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12967, 41416, 'アンケートの結果を集計した。', 'アンケートの けっかを しゅうけい した。', 'Tôi đã tổng hợp kết quả khảo sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12968, 41424, 'この会社はチームワークを重んじている。', 'この かいしゃは チームワークを おもんじて いる。', 'Công ty này coi trọng tinh thần đồng đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12969, 41420, '彼は農業に従事している。', 'かれは のうぎょうに じゅうじ して いる。', 'Anh ấy làm nghề nông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12970, 41475, 'お寺で僧侶がお経を唱えている。', 'おてらで そうりょが おきょうを となえて いる。', 'Nhà sư đang tụng kinh trong chùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12971, 41485, '両親の承諾を得て、留学した。', 'りょうしんの しょうだくを えて、りゅうがく した。', 'Được bố mẹ đồng ý, tôi đã đi du học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12972, 41479, '代金を小切手で支払った。', 'だいきんを こぎってで しはらった。', 'Tôi thanh toán tiền hàng bằng séc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12973, 41480, '自動販売機を使うので、小銭が必要だ。', 'じどう はんばいきを つかうので、こぜにが ひつようだ。', 'Dùng máy bán hàng tự động nên cần tiền lẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12974, 41493, '警察官と称する男から電話があった。', 'けいさつかんと しょうする おとこから でんわが あった。', 'Có cuộc gọi từ một người đàn ông tự xưng là cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12975, 41522, '市役所の職員に相談した。', 'しやくしょの しょくいんに そうだん した。', 'Tôi hỏi ý kiến nhân viên tòa thị chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12976, 41533, '日頃の心掛けが大切だ。', 'ひごろの こころがけが たいせつだ。', 'Sự lưu tâm hằng ngày là điều quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12977, 41534, '毎日野菜を食べるように心掛けている。', 'まいにち やさいを たべる ように こころがけて いる。', 'Tôi luôn cố gắng ăn rau mỗi ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12978, 41606, '彼はお世辞がうまい。', 'かれは おせじが うまい。', 'Anh ta giỏi nịnh hót.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12979, 41637, '彼は絵を描いて生計を立てている。', 'かれは えを かいて せいけいを たてて いる。', 'Anh ấy kiếm sống bằng nghề vẽ tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12980, 41645, 'この町は製鉄で栄えた。', 'この まちは せいてつで さかえた。', 'Thị trấn này thịnh vượng nhờ ngành luyện thép.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12981, 41654, '子供を守ることは大人の責務だ。', 'こどもを まもる ことは おとなの せきむだ。', 'Bảo vệ trẻ em là trách nhiệm của người lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12982, 41691, '煽てられて、つい引き受けてしまった。', 'おだてられて、つい ひきうけて しまった。', 'Được tâng bốc nên tôi lỡ nhận lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12983, 41697, '前置きはこのくらいにして、本題に入ります。', 'まえおきは この くらいに して、ほんだいに はいります。', 'Phần mở đầu đến đây thôi, tôi xin vào vấn đề chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12984, 41717, 'この学校は創立百年を迎えた。', 'この がっこうは そうりつ ひゃくねんを むかえた。', 'Ngôi trường này đã tròn một trăm năm thành lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12985, 41732, '山に登るには十分な装備が必要だ。', 'やまに のぼるには じゅうぶんな そうびが ひつようだ。', 'Leo núi cần trang bị đầy đủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12986, 41761, '明日の予定を打ち合わせた。', 'あしたの よていを うちあわせた。', 'Chúng tôi đã bàn bạc lịch trình ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12987, 41834, '彼が犯人だとは断言できない。', 'かれが はんにんだとは だんげん できない。', 'Không thể khẳng định chắc chắn anh ta là thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12988, 41909, '彼の質問に、会場は沈黙に包まれた。', 'かれの しつもんに、かいじょうは ちんもくに つつまれた。', 'Trước câu hỏi của anh ấy, cả hội trường chìm trong im lặng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12989, 41910, '新商品が店頭に陳列された。', 'しんしょうひんが てんとうに ちんれつ された。', 'Sản phẩm mới đã được trưng bày ở mặt tiền cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12990, 41924, '彼の話は辻褄が合わない。', 'かれの はなしは つじつまが あわない。', 'Câu chuyện của anh ta không ăn khớp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12991, 41935, '入場の際は身分証を提示してください。', 'にゅうじょうの さいは みぶんしょうを ていじ して ください。', 'Khi vào cửa xin hãy xuất trình giấy tờ tùy thân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12992, 41965, '情報の伝達がうまくいかなかった。', 'じょうほうの でんたつが うまく いかなかった。', 'Việc truyền đạt thông tin đã không suôn sẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12993, 41934, 'このホテルは無料で朝食を提供している。', 'この ホテルは むりょうで ちょうしょくを ていきょう して いる。', 'Khách sạn này phục vụ bữa sáng miễn phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12994, 41961, '先生は来月、別の学校に転任する。', 'せんせいは らいげつ、べつの がっこうに てんにん する。', 'Tháng sau thầy giáo sẽ chuyển công tác sang trường khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12995, 41979, 'よく知っている人の名前を度忘れした。', 'よく しって いる ひとの なまえを どわすれ した。', 'Tôi quên bẵng tên một người rất quen.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12996, 41988, '政府は多額の資金を投入した。', 'せいふは たがくの しきんを とうにゅう した。', 'Chính phủ đã rót một khoản vốn lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12997, 42000, '予算案について討議が行われた。', 'よさんあんに ついて とうぎが おこなわれた。', 'Đã diễn ra cuộc thảo luận về dự thảo ngân sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12998, 42010, '日本語を勉強し始めた動機は何ですか。', 'にほんごを べんきょう し はじめた どうきは なん ですか。', 'Động cơ bạn bắt đầu học tiếng Nhật là gì?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (12999, 42032, '司会者が受賞者の名前を読み上げた。', 'しかいしゃが じゅしょうしゃの なまえを よみあげた。', 'Người dẫn chương trình đọc to tên người đoạt giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13000, 42029, '新聞社はロンドンに特派員を送った。', 'しんぶんしゃは ロンドンに とくはいんを おくった。', 'Tòa báo đã cử phóng viên đặc biệt sang London.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13001, 42070, '恩師に感謝の手紙を認めた。', 'おんしに かんしゃの てがみを したためた。', 'Tôi đã viết thư cảm ơn người thầy cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13002, 42067, '彼は任務を果たして帰国した。', 'かれは にんむを はたして きこく した。', 'Anh ấy hoàn thành nhiệm vụ rồi về nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13003, 42100, 'ちょっとペンを拝借してもよろしいですか。', 'ちょっと ペンを はいしゃく しても よろしい ですか。', 'Tôi xin phép mượn cây bút một chút được không ạ?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13004, 42088, '人類は一万年前に農耕を始めた。', 'じんるいは いちまんねんまえに のうこうを はじめた。', 'Loài người bắt đầu canh tác nông nghiệp từ một vạn năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13005, 42090, '農地が住宅地に変わっている。', 'のうちが じゅうたくちに かわって いる。', 'Đất nông nghiệp đang biến thành khu dân cư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13006, 42106, '戦争中は食料が配給された。', 'せんそうちゅうは しょくりょうが はいきゅう された。', 'Trong thời chiến lương thực được phân phối theo tem phiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13007, 42127, '会議で積極的に発言した。', 'かいぎで せっきょくてきに はつげん した。', 'Tôi đã tích cực phát biểu trong cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13008, 42115, '会社は新しい商品を売り出した。', 'かいしゃは あたらしい しょうひんを うりだした。', 'Công ty đã tung ra sản phẩm mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13009, 42145, 'この店はいつも客が多くて繁盛している。', 'この みせは いつも きゃくが おおくて はんじょう して いる。', 'Cửa hàng này lúc nào cũng đông khách, làm ăn phát đạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13010, 42178, '学生のころは貧乏だった。', 'がくせいの ころは びんぼう だった。', 'Thời sinh viên tôi nghèo túng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13011, 42197, 'この国は天然資源に富んでいる。', 'この くには てんねん しげんに とんで いる。', 'Đất nước này giàu tài nguyên thiên nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13012, 42212, '父は大阪へ単身赴任している。', 'ちちは おおさかへ たんしん ふにん して いる。', 'Bố tôi đang một mình đi công tác dài hạn ở Osaka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13013, 42218, 'この映画は三つの部門で賞を取った。', 'この えいがは みっつの ぶもんで しょうを とった。', 'Bộ phim này đoạt giải ở ba hạng mục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13014, 42238, '工場では分業で作業が行われている。', 'こうじょうでは ぶんぎょうで さぎょうが おこなわれて いる。', 'Trong nhà máy công việc được thực hiện theo phân công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13015, 42270, '片言の日本語でなんとか話した。', 'かたことの にほんごで なんとか はなした。', 'Tôi cố nói bằng thứ tiếng Nhật bập bẹ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13016, 42277, '今さら弁解しても遅い。', 'いまさら べんかい しても おそい。', 'Bây giờ có biện hộ cũng đã muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13017, 42257, '重要な文書は金庫に保管している。', 'じゅうような ぶんしょは きんこに ほかん して いる。', 'Văn bản quan trọng được cất trong két sắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13018, 42330, 'この町は昔、紡績業で栄えた。', 'この まちは むかし、ぼうせきぎょうで さかえた。', 'Ngày xưa thị trấn này thịnh vượng nhờ ngành dệt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13019, 42381, '自分の無知を恥じた。', 'じぶんの むちを はじた。', 'Tôi thấy xấu hổ vì sự thiếu hiểu biết của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13020, 42379, 'お金の無駄遣いはやめよう。', 'おかねの むだづかいは やめよう。', 'Hãy thôi tiêu xài hoang phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13021, 42392, '会議では名札をつけてください。', 'かいぎでは なふだを つけて ください。', 'Trong cuộc họp hãy đeo thẻ tên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13022, 42424, '彼の目論見は見事に外れた。', 'かれの もくろみは みごとに はずれた。', 'Kế hoạch ngầm của hắn đã thất bại hoàn toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13023, 42425, '商品について会社に問い合わせた。', 'しょうひんに ついて かいしゃに といあわせた。', 'Tôi đã hỏi công ty về sản phẩm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13024, 42436, '彼は会社で役職についている。', 'かれは かいしゃで やくしょくに ついて いる。', 'Anh ấy giữ chức vụ quản lý trong công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13025, 42478, '住民の要望に応えて、公園が作られた。', 'じゅうみんの ようぼうに こたえて、こうえんが つくられた。', 'Đáp ứng nguyện vọng của cư dân, một công viên đã được xây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13026, 42465, '銀行に預金している。', 'ぎんこうに よきん して いる。', 'Tôi có tiền gửi ở ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13027, 42496, '北海道では酪農が盛んだ。', 'ほっかいどうでは らくのうが さかんだ。', 'Ở Hokkaido chăn nuôi bò sữa phát triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13028, 42505, '彼はすぐ理屈を言う。', 'かれは すぐ りくつを いう。', 'Anh ta hơi tí là lý sự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13029, 42516, '新しい紙幣が流通し始めた。', 'あたらしい しへいが りゅうつう し はじめた。', 'Tiền giấy mới đã bắt đầu được lưu thông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13030, 42520, 'ご了承のほど、よろしくお願いいたします。', 'ごりょうしょうの ほど、よろしく おねがい いたします。', 'Rất mong quý khách thông cảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13031, 42524, '大人として良識ある行動をとるべきだ。', 'おとなと して りょうしき ある こうどうを とる べきだ。', 'Là người lớn thì nên hành động có lương tri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13032, 42532, '友達に新しい恋人のことで冷やかされた。', 'ともだちに あたらしい こいびとの ことで ひやかされた。', 'Tôi bị bạn bè trêu chọc về người yêu mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13033, 42551, '彼は会社の秘密を外部に漏らした。', 'かれは かいしゃの ひみつを がいぶに もらした。', 'Anh ta đã để lộ bí mật công ty ra ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13034, 42561, '話し合いで問題が解決した。', 'はなしあいで もんだいが かいけつ した。', 'Vấn đề đã được giải quyết qua thảo luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13035, 42570, '嘘をついたことで良心が咎めた。', 'うそを ついた ことで りょうしんが とがめた。', 'Nói dối khiến lương tâm tôi cắn rứt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13036, 42563, '会の費用は会費で賄っている。', 'かいの ひようは かいひで まかなって いる。', 'Chi phí của hội được trang trải bằng hội phí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13037, 40396, '入学式の後、オリエンテーションがあった。', 'にゅうがくしきの あと、オリエンテーションが あった。', 'Sau lễ nhập học có buổi định hướng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13038, 40959, '祖母の教えを今も守っている。', 'そぼの おしえを いまも まもって いる。', 'Đến giờ tôi vẫn giữ lời dạy của bà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13039, 40960, '彼女は小学校の教員をしている。', 'かのじょは しょうがっこうの きょういんを して いる。', 'Cô ấy là giáo viên tiểu học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13040, 40962, '先生は自分で教材を作っている。', 'せんせいは じぶんで きょうざいを つくって いる。', 'Thầy tự soạn tài liệu giảng dạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13041, 41085, 'いつか原書でシェークスピアを読みたい。', 'いつか げんしょで シェークスピアを よみたい。', 'Một ngày nào đó tôi muốn đọc Shakespeare bằng nguyên bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13042, 41229, '詳しくは十ページを参照してください。', 'くわしくは じゅっページを さんしょう して ください。', 'Chi tiết xin tham khảo trang mười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13043, 41401, '「褒められる」は「褒める」の受身の形だ。', '「ほめられる」は 「ほめる」の うけみの かたちだ。', '"Homerareru" là thể bị động của "homeru".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13044, 41461, '先生の話をノートに書き取った。', 'せんせいの はなしを ノートに かきとった。', 'Tôi chép lại lời thầy vào vở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13045, 41517, '海水を蒸留して真水を作る。', 'かいすいを じょうりゅう して まみずを つくる。', 'Chưng cất nước biển để tạo nước ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13046, 41546, '新入生を歓迎するパーティーが開かれた。', 'しんにゅうせいを かんげい する パーティーが ひらかれた。', 'Bữa tiệc chào đón tân sinh viên đã được tổ chức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13047, 41825, '姉は短大を卒業して銀行に就職した。', 'あねは たんだいを そつぎょう して ぎんこうに しゅうしょく した。', 'Chị tôi tốt nghiệp cao đẳng rồi vào làm ngân hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13048, 42600, 'あの家は子供の躾が厳しい。', 'あの いえは こどもの しつけが きびしい。', 'Nhà đó dạy dỗ con cái rất nghiêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13049, 31811, '失脚した政治家が復権を果たした。', 'しっきゃく した せいじかが ふっけんを はたした。', 'Chính trị gia từng mất chức đã phục hồi quyền lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13050, 31813, '天皇が退位し、新しい時代が始まった。', 'てんのうが たいい し、あたらしい じだいが はじまった。', 'Thiên hoàng thoái vị và một thời đại mới bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13051, 37841, '賃金交渉がようやく妥結した。', 'ちんぎん こうしょうが ようやく だけつ した。', 'Cuộc đàm phán tiền lương cuối cùng đã đạt thỏa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13052, 37842, '離婚の問題は家庭裁判所の調停に持ち込まれた。', 'りこんの もんだいは かてい さいばんしょの ちょうていに もちこまれた。', 'Vấn đề ly hôn được đưa ra tòa gia đình để hòa giải.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13053, 38206, '少子化に対する施策が求められている。', 'しょうしかに たいする しさくが もとめられて いる。', 'Cần có các biện pháp đối phó với tình trạng ít con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13054, 38232, '産地を偽装した食品が問題になった。', 'さんちを ぎそう した しょくひんが もんだいに なった。', 'Thực phẩm giả mạo nơi xuất xứ đã trở thành vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13055, 38233, '研究データの捏造が明らかになった。', 'けんきゅう データの ねつぞうが あきらかに なった。', 'Việc ngụy tạo dữ liệu nghiên cứu đã bị làm rõ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13056, 38235, '偽造されたパスポートが見つかった。', 'ぎぞう された パスポートが みつかった。', 'Đã phát hiện hộ chiếu làm giả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13057, 38317, '同性婚の法制化が議論されている。', 'どうせいこんの ほうせいかが ぎろん されて いる。', 'Việc luật hóa hôn nhân đồng giới đang được tranh luận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13058, 40953, '参加は強制ではありません。', 'さんかは きょうせいでは ありません。', 'Việc tham gia không bắt buộc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13059, 41010, '港に軍艦が停泊している。', 'みなとに ぐんかんが ていはく して いる。', 'Chiến hạm đang neo đậu ở cảng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13060, 41012, '各国が軍備の拡張を競っている。', 'かっこくが ぐんびの かくちょうを きそって いる。', 'Các nước đang chạy đua mở rộng quân bị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13061, 41028, '事件を担当する警部が記者に説明した。', 'じけんを たんとう する けいぶが きしゃに せつめい した。', 'Viên thanh tra phụ trách vụ án đã giải thích với phóng viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13062, 41057, '検事は被告に懲役五年を求めた。', 'けんじは ひこくに ちょうえき ごねんを もとめた。', 'Công tố viên đề nghị mức án năm năm tù cho bị cáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13063, 41131, '彼は党の公認を得て立候補した。', 'かれは とうの こうにんを えて りっこうほ した。', 'Anh ấy được đảng chính thức công nhận và ra ứng cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13064, 41228, '参議院の選挙は三年ごとに行われる。', 'さんぎいんの せんきょは さんねんごとに おこなわれる。', 'Bầu cử Thượng viện được tổ chức ba năm một lần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13065, 41367, '飲酒運転の取り締まりが強化された。', 'いんしゅ うんてんの とりしまりが きょうか された。', 'Việc kiểm soát lái xe khi say rượu đã được tăng cường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13066, 41382, '犯人は手錠をかけられて連行された。', 'はんにんは てじょうを かけられて れんこう された。', 'Thủ phạm bị còng tay và giải đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13067, 41450, '規則を破った者は処罰される。', 'きそくを やぶった ものは しょばつ される。', 'Người vi phạm quy tắc sẽ bị trừng phạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13068, 41519, 'ベトナムはかつてフランスの植民地だった。', 'ベトナムは かつて フランスの しょくみんち だった。', 'Việt Nam từng là thuộc địa của Pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13069, 41538, 'この芝居は男女の心中を描いている。', 'この しばいは だんじょの しんじゅうを えがいて いる。', 'Vở kịch này miêu tả cuộc tự tử vì tình của đôi nam nữ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13070, 41580, '犯人は銀行員を人質にとった。', 'はんにんは ぎんこういんを ひとじちに とった。', 'Hung thủ bắt nhân viên ngân hàng làm con tin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13071, 41728, '株主総会は六月に開かれる。', 'かぶぬし そうかいは ろくがつに ひらかれる。', 'Đại hội cổ đông được tổ chức vào tháng sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13072, 41746, '彼女は恋人に束縛されるのが嫌いだ。', 'かのじょは こいびとに そくばく されるのが きらいだ。', 'Cô ấy ghét bị người yêu kiểm soát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13073, 41772, '決勝戦で宿命のライバルと対決する。', 'けっしょうせんで しゅくめいの ライバルと たいけつ する。', 'Ở trận chung kết sẽ đối đầu với kình địch định mệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13074, 41773, '大手に対抗するため、小さな店が協力した。', 'おおてに たいこう する ため、ちいさな みせが きょうりょく した。', 'Để đối chọi với các công ty lớn, các cửa hàng nhỏ đã hợp tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13075, 42221, '事故のため、道路が封鎖された。', 'じこの ため、どうろが ふうさ された。', 'Do tai nạn nên con đường đã bị phong tỏa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13076, 41823, 'ダイヤモンドは炭素でできている。', 'ダイヤモンドは たんそで できて いる。', 'Kim cương được cấu tạo từ cacbon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13077, 41846, 'この辺りの土地はすべて一人の地主のものだ。', 'この あたりの とちは すべて ひとりの じぬしの ものだ。', 'Đất quanh đây đều thuộc về một địa chủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13078, 41876, '酸とアルカリを混ぜると中和する。', 'さんと アルカリを まぜると ちゅうわ する。', 'Trộn axit với kiềm thì chúng trung hòa nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13079, 41967, '列の殿を歩いて、遅れる人がいないか見た。', 'れつの しんがりを あるいて、おくれる ひとが いないか みた。', 'Tôi đi cuối hàng để xem có ai bị tụt lại không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13080, 43232, '駅前に新しいカフェがオープンした。', 'えきまえに あたらしい カフェが オープン した。', 'Một quán cà phê mới đã khai trương trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13081, 31748, '多くの実験結果から法則を帰納した。', 'おおくの じっけん けっかから ほうそくを きのう した。', 'Từ nhiều kết quả thí nghiệm đã quy nạp ra định luật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13082, 38218, '監督官庁は会社に是正措置を命じた。', 'かんとく かんちょうは かいしゃに ぜせい そちを めいじた。', 'Cơ quan quản lý ra lệnh công ty áp dụng biện pháp chấn chỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13083, 41887, '気象庁が大雨の警報を出した。', 'きしょうちょうが おおあめの けいほうを だした。', 'Cục khí tượng đã ra cảnh báo mưa lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13084, 42230, '奈良の寺で大きな仏像を見た。', 'ならの てらで おおきな ぶつぞうを みた。', 'Tôi đã thấy bức tượng Phật lớn ở chùa Nara.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13085, 31747, '一般的な原理から個々の結論を演繹する。', 'いっぱんてきな げんりから ここの けつろんを えんえき する。', 'Diễn dịch ra từng kết luận từ nguyên lý chung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13086, 31751, '小学校では道徳の授業がある。', 'しょうがっこうでは どうとくの じゅぎょうが ある。', 'Ở tiểu học có giờ học đạo đức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13087, 31772, 'この島はかつて外国に統治されていた。', 'この しまは かつて がいこくに とうち されて いた。', 'Hòn đảo này từng bị nước ngoài cai trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13088, 31774, '権力を持つと人は変わる。', 'けんりょくを もつと ひとは かわる。', 'Có quyền lực vào tay thì con người thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13089, 31776, 'その国では長い間独裁が続いた。', 'その くにでは ながい あいだ どくさいが つづいた。', 'Ở nước đó chế độ độc tài kéo dài suốt thời gian dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13090, 31778, 'フランスは共和制の国だ。', 'フランスは きょうわせいの くにだ。', 'Pháp là nước theo chế độ cộng hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13091, 31784, '政府は反対派を弾圧した。', 'せいふは はんたいはを だんあつ した。', 'Chính phủ đã đàn áp phe đối lập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13092, 31785, '暴動はすぐに鎮圧された。', 'ぼうどうは すぐに ちんあつ された。', 'Cuộc bạo động nhanh chóng bị trấn áp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13093, 31787, 'スマートフォンは生活に革命をもたらした。', 'スマートフォンは せいかつに かくめいを もたらした。', 'Điện thoại thông minh đã mang lại cuộc cách mạng trong đời sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13094, 31790, '祖父は考え方が保守的だ。', 'そふは かんがえかたが ほしゅてきだ。', 'Ông tôi có lối suy nghĩ bảo thủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13095, 37886, '被害者の救済が急がれる。', 'ひがいしゃの きゅうさいが いそがれる。', 'Cần gấp rút cứu trợ người bị hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13096, 38208, '新しい内閣が発足した。', 'あたらしい ないかくが ほっそく した。', 'Nội các mới đã ra mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13097, 38211, '輸入制限が撤廃された。', 'ゆにゅう せいげんが てっぱい された。', 'Hạn chế nhập khẩu đã được bãi bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13098, 38229, '会社の不正が内部告発で発覚した。', 'かいしゃの ふせいが ないぶ こくはつで はっかく した。', 'Sai phạm của công ty bị phát giác nhờ tố giác nội bộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13099, 38291, '商売には駆け引きが必要だ。', 'しょうばいには かけひきが ひつようだ。', 'Buôn bán thì cần biết đấu trí mặc cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13100, 38293, '話し合いは膠着状態に陥った。', 'はなしあいは こうちゃく じょうたいに おちいった。', 'Cuộc thương lượng rơi vào bế tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13101, 38298, '不動産会社の仲介で部屋を借りた。', 'ふどうさん がいしゃの ちゅうかいで へやを かりた。', 'Tôi thuê phòng qua môi giới của công ty bất động sản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13102, 38299, '大学が就職先を斡旋してくれた。', 'だいがくが しゅうしょくさきを あっせん して くれた。', 'Trường đại học đã giới thiệu chỗ làm cho tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13464, 41432, '山道で熊に出くわした。', 'やまみちで くまに でくわした。', 'Tôi chạm trán con gấu trên đường núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13103, 38301, '労使双方の歩み寄りで合意に達した。', 'ろうし そうほうの あゆみよりで ごういに たっした。', 'Nhờ cả chủ và thợ cùng nhân nhượng nên đã đạt được thỏa thuận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13104, 38316, '在宅勤務を制度化する会社が増えた。', 'ざいたく きんむを せいどか する かいしゃが ふえた。', 'Các công ty thể chế hóa chế độ làm việc tại nhà đã tăng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13105, 40415, '試験でカンニングをして、厳しく注意された。', 'しけんで カンニングを して、きびしく ちゅうい された。', 'Quay cóp trong kỳ thi nên bị nhắc nhở nghiêm khắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13106, 40612, '彼女は三桁の掛け算を暗算でできる。', 'かのじょは さんけたの かけざんを あんざんで できる。', 'Cô ấy có thể tính nhẩm phép nhân ba chữ số.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13107, 40694, '古い水道管には鉛が使われていた。', 'ふるい すいどうかんには なまりが つかわれて いた。', 'Ống nước cũ từng được làm bằng chì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13108, 40718, '水素と酸素が化合して水になる。', 'すいそと さんそが かごう して みずに なる。', 'Hydro hóa hợp với oxy tạo thành nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13109, 40750, '課外活動でボランティアをしている。', 'かがい かつどうで ボランティアを して いる。', 'Tôi làm tình nguyện trong hoạt động ngoại khóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13110, 40757, '首相が記者会見を開いた。', 'しゅしょうが きしゃ かいけんを ひらいた。', 'Thủ tướng đã tổ chức họp báo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13111, 40769, '来月から電気料金が改定される。', 'らいげつから でんき りょうきんが かいてい される。', 'Từ tháng sau giá điện sẽ được điều chỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13112, 40787, '日本史の概説を読んでから専門書に進んだ。', 'にほんしの がいせつを よんでから せんもんしょに すすんだ。', 'Đọc sách đại cương lịch sử Nhật xong tôi mới chuyển sang sách chuyên sâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13113, 40800, '彼は経済学の学士号を持っている。', 'かれは けいざいがくの がくしごうを もって いる。', 'Anh ấy có bằng cử nhân kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13114, 40782, '外相会談が東京で開かれた。', 'がいしょう かいだんが とうきょうで ひらかれた。', 'Cuộc hội đàm ngoại trưởng được tổ chức tại Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13115, 40885, '規定の用紙に記入してください。', 'きていの ようしに きにゅう して ください。', 'Hãy điền vào mẫu giấy quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13116, 40893, '平安時代の貴族は和歌を楽しんだ。', 'へいあん じだいの きぞくは わかを たのしんだ。', 'Quý tộc thời Heian thưởng thức thơ waka.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13117, 40904, '議案は賛成多数で可決された。', 'ぎあんは さんせい たすうで かけつ された。', 'Đề án được thông qua với đa số phiếu tán thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13118, 40905, '予算は議会の議決を経て決定する。', 'よさんは ぎかいの ぎけつを へて けってい する。', 'Ngân sách được quyết định sau khi hội đồng biểu quyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13119, 40918, '両国は休戦に合意した。', 'りょうこくは きゅうせんに ごうい した。', 'Hai nước đã đồng ý đình chiến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13120, 40925, '地震の被災地に救援隊が派遣された。', 'じしんの ひさいちに きゅうえんたいが はけん された。', 'Đội cứu hộ đã được cử đến vùng động đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13121, 40989, '病み上がりに無理は禁物だ。', 'やみあがりに むりは きんもつだ。', 'Vừa ốm dậy thì tuyệt đối không được gắng sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13122, 41086, '引用する時は原典に当たるべきだ。', 'いんよう する ときは げんてんに あたる べきだ。', 'Khi trích dẫn nên đối chiếu văn bản gốc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13123, 41120, '大統領は多くの護衛に守られている。', 'だいとうりょうは おおくの ごえいに まもられて いる。', 'Tổng thống được nhiều cận vệ bảo vệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13124, 41128, 'その事実はまだ公にされていない。', 'その じじつは まだ おおやけに されて いない。', 'Sự thật đó vẫn chưa được công khai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13125, 41151, '考古学の調査で古い土器が出てきた。', 'こうこがくの ちょうさで ふるい どきが でて きた。', 'Cuộc khảo sát khảo cổ học đã tìm thấy đồ gốm cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13126, 41173, '峠が昔の国境だった。', 'とうげが むかしの くにざかい だった。', 'Con đèo từng là ranh giới giữa các xứ ngày xưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13127, 41176, 'この地域は国定公園に指定されている。', 'この ちいきは こくてい こうえんに してい されて いる。', 'Khu vực này được chỉ định là công viên bán quốc gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13128, 41178, '国防の予算が増えた。', 'こくぼうの よさんが ふえた。', 'Ngân sách quốc phòng đã tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13129, 41179, 'この森は国有林だ。', 'この もりは こくゆうりんだ。', 'Khu rừng này là rừng quốc hữu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13130, 41205, '会議で新しい宣言が採択された。', 'かいぎで あたらしい せんげんが さいたく された。', 'Hội nghị đã thông qua bản tuyên bố mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13131, 41276, '死刑制度について議論が続いている。', 'しけい せいどに ついて ぎろんが つづいて いる。', 'Cuộc tranh luận về án tử hình vẫn tiếp diễn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13132, 41298, '祖父の家は村の字にある。', 'そふの いえは むらの あざに ある。', 'Nhà ông tôi ở một tiểu khu trong làng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13133, 41350, '国民主権は憲法の原則だ。', 'こくみん しゅけんは けんぽうの げんそくだ。', 'Chủ quyền thuộc về nhân dân là nguyên tắc của hiến pháp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13134, 41414, '夜中に村が襲撃された。', 'よなかに むらが しゅうげき された。', 'Ngôi làng bị tập kích lúc nửa đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13135, 41531, '法案は委員会で審議されている。', 'ほうあんは いいんかいで しんぎ されて いる。', 'Dự luật đang được ủy ban thẩm nghị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13136, 41584, '政治は人民のためにあるべきだ。', 'せいじは じんみんの ために ある べきだ。', 'Chính trị phải vì nhân dân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13137, 41611, '国連はその国に経済制裁を科した。', 'こくれんは その くにに けいざい せいさいを かした。', 'Liên Hợp Quốc đã áp đặt trừng phạt kinh tế lên nước đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13138, 41612, '日本国憲法は一九四六年に制定された。', 'にほんこく けんぽうは せんきゅうひゃく よんじゅうろくねんに せいてい された。', 'Hiến pháp Nhật Bản được ban hành năm 1946.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13139, 41619, '選挙で政権が交代した。', 'せんきょで せいけんが こうたい した。', 'Chính quyền đã thay đổi sau cuộc bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13140, 41677, '戦後、日本は連合国に占領された。', 'せんご、にほんは れんごうこくに せんりょう された。', 'Sau chiến tranh, Nhật bị quân Đồng minh chiếm đóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13141, 41683, '新人も今では大切な戦力だ。', 'しんじんも いまでは たいせつな せんりょくだ。', 'Người mới giờ cũng đã là lực lượng quan trọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13142, 41725, '遺産をめぐる争いが起きた。', 'いさんを めぐる あらそいが おきた。', 'Đã xảy ra tranh chấp xoay quanh tài sản thừa kế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13143, 41907, 'ビーカーの底に白い物質が沈殿した。', 'ビーカーの そこに しろい ぶっしつが ちんでん した。', 'Chất màu trắng lắng xuống đáy cốc thí nghiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13144, 41916, '彼は国外に追放された。', 'かれは こくがいに ついほう された。', 'Ông ấy bị trục xuất ra nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13145, 41992, '「寿司」は当て字だと言われている。', '「すし」は あてじだと いわれて いる。', 'Người ta nói chữ "寿司" là chữ mượn âm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13146, 41994, '彼は市長選挙に当選した。', 'かれは しちょう せんきょに とうせん した。', 'Ông ấy đã trúng cử thị trưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13147, 41996, '彼にはチームを統率する力がある。', 'かれには チームを とうそつ する ちからが ある。', 'Anh ấy có năng lực chỉ huy cả đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13148, 42009, '捜索には大勢の警察官が動員された。', 'そうさくには おおぜいの けいさつかんが どういん された。', 'Rất nhiều cảnh sát đã được huy động cho cuộc tìm kiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13149, 42026, '会員には割引の特権がある。', 'かいいんには わりびきの とっけんが ある。', 'Hội viên có đặc quyền được giảm giá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13150, 42038, '引っ越したら、市役所に届けを出してください。', 'ひっこしたら、しやくしょに とどけを だして ください。', 'Chuyển nhà xong hãy nộp đơn báo cho tòa thị chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13151, 42073, 'この食品の熱量は二百キロカロリーだ。', 'この しょくひんの ねつりょうは にひゃく キロカロリーだ。', 'Nhiệt lượng của món này là hai trăm kilocalo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13152, 42053, '優勝した選手が日の丸を振った。', 'ゆうしょう した せんしゅが ひのまるを ふった。', 'Vận động viên vô địch đã vẫy lá cờ Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13153, 42081, '運動して脂肪を燃焼させる。', 'うんどう して しぼうを ねんしょう させる。', 'Vận động để đốt cháy mỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13154, 42102, '日本は一九四五年に敗戦を迎えた。', 'にほんは せんきゅうひゃく よんじゅうごねんに はいせんを むかえた。', 'Năm 1945 Nhật Bản bại trận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13155, 42126, '古墳の発掘が始まった。', 'こふんの はっくつが はじまった。', 'Việc khai quật lăng mộ cổ đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13156, 42121, '彼らは宗教的な迫害を逃れて移住した。', 'かれらは しゅうきょうてきな はくがいを のがれて いじゅう した。', 'Họ di cư để trốn tránh sự bức hại tôn giáo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13157, 42153, '最近は仕事より家庭に比重を置いている。', 'さいきんは しごとより かていに ひじゅうを おいて いる。', 'Gần đây tôi đặt nặng gia đình hơn công việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13158, 42140, 'その番組は大きな反響を呼んだ。', 'その ばんぐみは おおきな はんきょうを よんだ。', 'Chương trình đó đã gây tiếng vang lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13159, 42148, 'その法案は議会で否決された。', 'その ほうあんは ぎかいで ひけつ された。', 'Dự luật đó đã bị quốc hội bác bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13160, 42187, '新しいデザインは客に不評だった。', 'あたらしい デザインは きゃくに ふひょう だった。', 'Thiết kế mới không được khách hàng ưa chuộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13161, 42205, '船は浮力によって水に浮く。', 'ふねは ふりょくに よって みずに うく。', 'Tàu nổi trên nước nhờ lực đẩy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13162, 42200, 'その国は隣国に宣戦を布告した。', 'その くには りんごくに せんせんを ふこく した。', 'Nước đó đã tuyên chiến với nước láng giềng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13163, 42215, '武力で問題を解決するべきではない。', 'ぶりょくで もんだいを かいけつ する べきでは ない。', 'Không nên giải quyết vấn đề bằng vũ lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13164, 42243, '分母が同じ分数は簡単に足せる。', 'ぶんぼが おなじ ぶんすうは かんたんに たせる。', 'Các phân số cùng mẫu số có thể cộng dễ dàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13165, 42262, '線路は二本の平行な線だ。', 'せんろは にほんの へいこうな せんだ。', 'Đường ray là hai đường song song.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13166, 42259, '核兵器のない世界を目指す。', 'かくへいきの ない せかいを めざす。', 'Hướng tới một thế giới không có vũ khí hạt nhân.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13167, 42310, '太陽は熱と光を放射している。', 'たいようは ねつと ひかりを ほうしゃ して いる。', 'Mặt trời bức xạ nhiệt và ánh sáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13168, 42321, '都市の人口は飽和状態にある。', 'としの じんこうは ほうわ じょうたいに ある。', 'Dân số đô thị đang ở trạng thái bão hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13169, 42305, '週末は地域の奉仕活動に参加している。', 'しゅうまつは ちいきの ほうし かつどうに さんか して いる。', 'Cuối tuần tôi tham gia hoạt động phục vụ cộng đồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13170, 42511, '「パソコン」は「パーソナルコンピューター」の略語だ。', '「パソコン」は 「パーソナルコンピューター」の りゃくごだ。', '"Pasokon" là từ viết tắt của "personal computer".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13171, 42560, '英文を和文に訳してください。', 'えいぶんを わぶんに やくして ください。', 'Hãy dịch đoạn tiếng Anh sang tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13172, 42477, '県は国に支援を要請した。', 'けんは くにに しえんを ようせい した。', 'Tỉnh đã đề nghị trung ương hỗ trợ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13173, 42499, '職権の濫用は許されない。', 'しょっけんの らんようは ゆるされない。', 'Lạm dụng chức quyền là không thể dung thứ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13174, 42527, '両国は島の領土問題で対立している。', 'りょうこくは しまの りょうど もんだいで たいりつ して いる。', 'Hai nước đối đầu nhau về vấn đề lãnh thổ hòn đảo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13175, 42544, 'アメリカは五十の州から成る連邦国家だ。', 'アメリカは ごじゅうの しゅうから なる れんぽう こっかだ。', 'Mỹ là quốc gia liên bang gồm năm mươi bang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13176, 38260, '平安時代の貴族の部屋には几帳が置かれていた。', 'へいあん じだいの きぞくの へやには きちょうが おかれて いた。', 'Trong phòng quý tộc thời Heian có đặt bình phong kichō.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13177, 40405, 'リビングに新しいカーペットを敷いた。', 'リビングに あたらしい カーペットを しいた。', 'Tôi trải tấm thảm mới trong phòng khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13178, 40442, '休みの日はいつもジーパンをはいている。', 'やすみの ひは いつも ジーパンを はいて いる。', 'Ngày nghỉ tôi luôn mặc quần jean.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13179, 40457, 'スチームでシャツのしわを伸ばした。', 'スチームで シャツの しわを のばした。', 'Tôi dùng hơi nước để là phẳng nếp nhăn áo sơ mi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13180, 40463, 'このベッドはスプリングが硬い。', 'この ベッドは スプリングが かたい。', 'Lò xo của chiếc giường này cứng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13181, 40527, 'ねじ回しで棚のねじを締めた。', 'ねじまわしで たなの ねじを しめた。', 'Tôi dùng tua vít vặn chặt ốc của giá sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13182, 40501, 'ティッシュペーパーで鼻をかんだ。', 'ティッシュペーパーで はなを かんだ。', 'Tôi xì mũi bằng khăn giấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13183, 40517, '毎日漢字のドリルをしている。', 'まいにち かんじの ドリルを して いる。', 'Ngày nào tôi cũng làm bài tập luyện kanji.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13184, 40530, '社員はみんな胸に会社のバッジをつけている。', 'しゃいんは みんな むねに かいしゃの バッジを つけて いる。', 'Nhân viên ai cũng đeo huy hiệu công ty trên ngực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13185, 40993, '金槌で釘を打った。', 'かなづちで くぎを うった。', 'Tôi đóng đinh bằng búa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13186, 41055, 'この傘は晴雨兼用だ。', 'この かさは せいう けんようだ。', 'Chiếc ô này dùng được cả nắng lẫn mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13187, 41279, '会社のパソコンを私物のように使ってはいけない。', 'かいしゃの パソコンを しぶつの ように つかっては いけない。', 'Không được dùng máy tính công ty như đồ riêng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13188, 41392, '母から真珠の首飾りをもらった。', 'ははから しんじゅの くびかざりを もらった。', 'Tôi được mẹ cho chiếc vòng cổ ngọc trai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13189, 41516, '祖父は杖をついて散歩する。', 'そふは つえを ついて さんぽ する。', 'Ông tôi chống gậy đi dạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13190, 41545, '新築のマンションに引っ越した。', 'しんちくの マンションに ひっこした。', 'Tôi chuyển đến căn hộ mới xây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13191, 41740, '古い蔵から昔の着物が見つかった。', 'ふるい くらから むかしの きものが みつかった。', 'Tìm thấy những bộ kimono xưa trong nhà kho cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13192, 41807, '洗剤が残らないように、よく濯いでください。', 'せんざいが のこらない ように、よく すすいで ください。', 'Hãy xả kỹ để không còn sót bột giặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13193, 42428, '夜更かしは体に悪い。', 'よふかしは からだに わるい。', 'Thức khuya có hại cho sức khỏe.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13194, 42474, '駅前のスポーツ用品店でボールを買った。', 'えきまえの スポーツ ようひんてんで ボールを かった。', 'Tôi mua quả bóng ở cửa hàng đồ thể thao trước ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13195, 42553, '週末はずっと部屋に篭って勉強した。', 'しゅうまつは ずっと へやに こもって べんきょう した。', 'Cuối tuần tôi ru rú trong phòng học bài suốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13196, 40475, '冷蔵庫にゼリーが冷やしてある。', 'れいぞうこに ゼリーが ひやして ある。', 'Thạch đang được làm lạnh trong tủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13197, 42534, '開封後は冷蔵して保存してください。', 'かいふうごは れいぞう して ほぞん して ください。', 'Sau khi mở hãy bảo quản lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13198, 40386, '次のインターチェンジで高速道路を降りる。', 'つぎの インターチェンジで こうそく どうろを おりる。', 'Sẽ rời đường cao tốc ở nút giao tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13199, 40578, '旅の途中、道沿いのモーテルに泊まった。', 'たびの とちゅう、みちぞいの モーテルに とまった。', 'Giữa chuyến đi chúng tôi nghỉ tại một nhà nghỉ ven đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13200, 40971, 'お盆には郷里に帰る。', 'おぼんには きょうりに かえる。', 'Dịp lễ Obon tôi về quê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13201, 40996, '土地を十の区画に分けて売り出した。', 'とちを じゅうの くかくに わけて うりだした。', 'Khu đất được chia thành mười lô để bán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13202, 41024, '感染の経路を調べている。', 'かんせんの けいろを しらべて いる。', 'Đang điều tra con đường lây nhiễm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13203, 41273, 'この町には公共施設が充実している。', 'この まちには こうきょう しせつが じゅうじつ して いる。', 'Thị trấn này có đầy đủ cơ sở công cộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13204, 41455, '責任の所在をはっきりさせるべきだ。', 'せきにんの しょざいを はっきり させる べきだ。', 'Cần làm rõ trách nhiệm thuộc về ai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13205, 41508, '全員がバスに乗り込んだ。', 'ぜんいんが バスに のりこんだ。', 'Mọi người đều đã lên xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13206, 41555, '駅の真ん前にホテルがある。', 'えきの まんまえに ホテルが ある。', 'Ngay trước ga có khách sạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13207, 41558, '太陽が真上に来た。', 'たいようが まうえに きた。', 'Mặt trời đã lên đến đỉnh đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13208, 41733, 'この車の走行距離は十万キロだ。', 'この くるまの そうこう きょりは じゅうまん キロだ。', 'Quãng đường xe này đã chạy là một trăm nghìn km.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13209, 40547, '非常の時はこのブザーを押してください。', 'ひじょうの ときは この ブザーを おして ください。', 'Khi khẩn cấp hãy bấm chuông báo này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13210, 41812, '道に迷いながら、やっと宿に辿り着いた。', 'みちに まよいながら、やっと やどに たどりついた。', 'Lạc đường mãi, cuối cùng tôi cũng lần đến được nhà trọ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13211, 41911, '小型機が山に墜落した。', 'こがたきが やまに ついらく した。', 'Máy bay cỡ nhỏ đã rơi xuống núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13212, 42430, '夜行バスで大阪へ行った。', 'やこう バスで おおさかへ いった。', 'Tôi đi Osaka bằng xe buýt đêm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13213, 43242, 'ドライブインで休憩した。', 'ドライブインで きゅうけい した。', 'Chúng tôi nghỉ chân ở quán ven đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13214, 40793, 'ライオンが獲物を狙っている。', 'ライオンが えものを ねらって いる。', 'Sư tử đang rình con mồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13215, 41026, 'この花は茎が長い。', 'この はなは くきが ながい。', 'Loài hoa này có cuống dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13216, 41083, '子供のころ、原っぱで野球をした。', 'こどもの ころ、はらっぱで やきゅうを した。', 'Hồi nhỏ tôi chơi bóng chày ở bãi đất trống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13217, 41184, '弟は昆虫の標本を集めている。', 'おとうとは こんちゅうの ひょうほんを あつめて いる。', 'Em trai tôi sưu tầm mẫu côn trùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13218, 41226, '家の裏は雑木林になっている。', 'いえの うらは ざつぼくばやしに なって いる。', 'Sau nhà là một khu rừng cây tạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13219, 41232, '山腹に小さな寺が建っている。', 'さんぷくに ちいさな てらが たって いる。', 'Có một ngôi chùa nhỏ nằm ở sườn núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13220, 41233, '日本アルプスは本州の中央を走る山脈だ。', 'にほん アルプスは ほんしゅうの ちゅうおうを はしる さんみゃくだ。', 'Alps Nhật Bản là dãy núi chạy giữa đảo Honshu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13221, 41403, '公園には様々な樹木が植えられている。', 'こうえんには さまざまな じゅもくが うえられて いる。', 'Trong công viên trồng nhiều loại cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13222, 41501, '飛行機が町の上空を飛んでいる。', 'ひこうきが まちの じょうくうを とんで いる。', 'Máy bay đang bay trên bầu trời thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13223, 41518, '庭には桜の木が植わっている。', 'にわには さくらの きが うわって いる。', 'Trong vườn có trồng cây anh đào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13224, 41869, '飛行機は無事に着陸した。', 'ひこうきは ぶじに ちゃくりく した。', 'Máy bay đã hạ cánh an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13225, 40520, '膝の上にナプキンを広げた。', 'ひざの うえに ナプキンを ひろげた。', 'Tôi trải khăn ăn lên đùi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13226, 43233, '朝食にオレンジジュースを飲んだ。', 'ちょうしょくに オレンジ ジュースを のんだ。', 'Bữa sáng tôi uống nước cam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13227, 43241, 'ダンプが土砂を運んでいる。', 'ダンプが どしゃを はこんで いる。', 'Xe ben đang chở đất đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13228, 40477, '白いソックスを三足買った。', 'しろい ソックスを さんぞく かった。', 'Tôi mua ba đôi tất trắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13229, 40534, '自転車のタイヤがパンクした。', 'じてんしゃの タイヤが パンク した。', 'Lốp xe đạp bị thủng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13230, 40370, 'ブレーキとアクセルを踏み間違えた。', 'ブレーキと アクセルを ふみまちがえた。', 'Tôi đạp nhầm phanh với chân ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13231, 40401, '子供に牛乳を買うお使いを頼んだ。', 'こどもに ぎゅうにゅうを かう おつかいを たのんだ。', 'Tôi sai con đi mua sữa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13232, 40378, '急に空が暗くなり、あられが降ってきた。', 'きゅうに そらが くらく なり、あられが ふって きた。', 'Trời bỗng tối sầm và mưa đá rơi xuống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13233, 40483, 'タイマーを三分にセットした。', 'タイマーを さんぷんに セット した。', 'Tôi hẹn giờ ba phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13234, 40486, '浴室の壁に白いタイルを張った。', 'よくしつの かべに しろい タイルを はった。', 'Tôi ốp gạch men trắng lên tường phòng tắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13235, 40542, '冬は暖かいブーツを履く。', 'ふゆは あたたかい ブーツを はく。', 'Mùa đông tôi đi bốt ấm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13236, 40558, 'ホースで庭に水をまいた。', 'ホースで にわに みずを まいた。', 'Tôi dùng vòi tưới nước cho vườn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13237, 40585, '選手たちは新しいユニフォームで試合に出た。', 'せんしゅたちは あたらしい ユニフォームで しあいに でた。', 'Các cầu thủ ra sân trong bộ đồng phục mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13238, 40588, 'テーブルの上のランプをつけた。', 'テーブルの うえの ランプを つけた。', 'Tôi bật chiếc đèn trên bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13239, 40586, 'ハンバーグとライスのセットを注文した。', 'ハンバーグと ライスの セットを ちゅうもん した。', 'Tôi gọi suất thịt băm viên kèm cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13240, 40595, '冷めたご飯をレンジで温めた。', 'さめた ごはんを レンジで あたためた。', 'Tôi hâm cơm nguội bằng lò vi sóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13241, 40596, '空港でレンタカーを借りた。', 'くうこうで レンタカーを かりた。', 'Tôi thuê xe ở sân bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13242, 40605, '川岸に葦が生い茂っている。', 'かわぎしに よしが おいしげって いる。', 'Lau sậy mọc um tùm bên bờ sông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13243, 40629, '冬物の衣類を箱にしまった。', 'ふゆものの いるいを はこに しまった。', 'Tôi cất quần áo mùa đông vào thùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13244, 40627, '冷蔵庫の野菜が萎びてしまった。', 'れいぞうこの やさいが しなびて しまった。', 'Rau trong tủ lạnh đã héo cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13245, 40663, '山は天気が変わりやすいので、雨具を持って行こう。', 'やまは てんきが かわりやすいので、あまぐを もって いこう。', 'Trên núi thời tiết dễ thay đổi nên hãy mang đồ đi mưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13246, 40664, '雨天の場合、運動会は中止です。', 'うてんの ばあい、うんどうかいは ちゅうし です。', 'Nếu trời mưa, hội thao sẽ bị hủy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13247, 40665, '鳴門海峡では大きな渦が見られる。', 'なると かいきょうでは おおきな うずが みられる。', 'Ở eo biển Naruto có thể thấy những xoáy nước lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13248, 40690, '祖母は縁側でお茶を飲むのが好きだ。', 'そぼは えんがわで おちゃを のむのが すきだ。', 'Bà tôi thích uống trà ngoài hiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13249, 40686, 'この沿線には大学が多い。', 'この えんせんには だいがくが おおい。', 'Dọc tuyến đường sắt này có nhiều trường đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13250, 40685, '沿岸の地域に津波の警報が出た。', 'えんがんの ちいきに つなみの けいほうが でた。', 'Cảnh báo sóng thần đã được ban bố cho vùng ven biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13251, 40705, '丘の上に古い屋敷が建っている。', 'おかの うえに ふるい やしきが たって いる。', 'Trên đồi có một dinh thự cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13252, 40743, '学校の花壇にチューリップを植えた。', 'がっこうの かだんに チューリップを うえた。', 'Chúng tôi trồng hoa tulip ở bồn hoa của trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13253, 40745, '引っ越しの荷造りがやっと終わった。', 'ひっこしの にづくりが やっと おわった。', 'Cuối cùng cũng đóng gói đồ chuyển nhà xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13254, 40739, '火星に生物はいるのだろうか。', 'かせいに せいぶつは いるの だろうか。', 'Liệu trên sao Hỏa có sinh vật không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13255, 40744, '春は花粉が多くて、くしゃみが止まらない。', 'はるは かふんが おおくて、くしゃみが とまらない。', 'Mùa xuân nhiều phấn hoa nên tôi hắt hơi không ngừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13256, 40761, 'この電車は回送なので、乗れません。', 'この でんしゃは かいそう なので、のれません。', 'Tàu này chạy không đón khách nên không lên được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13257, 40773, 'この村は海抜千メートルの所にある。', 'この むらは かいばつ せん メートルの ところに ある。', 'Ngôi làng này nằm ở độ cao một nghìn mét so với mực nước biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13258, 40774, '日本の近くには暖かい海流が流れている。', 'にほんの ちかくには あたたかい かいりゅうが ながれて いる。', 'Gần Nhật có dòng hải lưu ấm chảy qua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13259, 40789, 'この街道は江戸時代に整備された。', 'この かいどうは えど じだいに せいび された。', 'Con đường lớn này được xây dựng từ thời Edo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13260, 40786, '崖から落ちないように気をつけて。', 'がけから おちない ように きを つけて。', 'Cẩn thận kẻo rơi xuống vách đá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13261, 40821, '雨が降りそうなので、干し物を取り込んだ。', 'あめが ふりそう なので、ほしものを とりこんだ。', 'Trời sắp mưa nên tôi thu quần áo phơi vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13262, 40831, '子供がいるので、甘口のカレーを作った。', 'こどもが いるので、あまくちの カレーを つくった。', 'Vì có trẻ con nên tôi nấu cà ri vị ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13263, 40854, 'この岩石は火山の噴火でできた。', 'この がんせきは かざんの ふんかで できた。', 'Đá này được tạo ra từ vụ phun trào núi lửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13264, 40872, '出張を終えて、昨夜帰京した。', 'しゅっちょうを おえて、さくや ききょう した。', 'Xong chuyến công tác, tối qua tôi đã về Tokyo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13265, 40931, '小学校の給食でカレーが一番好きだった。', 'しょうがっこうの きゅうしょくで カレーが いちばん すき だった。', 'Trong bữa ăn ở trường tiểu học, tôi thích nhất món cà ri.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13266, 40938, '彼は小さな漁村で生まれた。', 'かれは ちいさな ぎょそんで うまれた。', 'Anh ấy sinh ra ở một làng chài nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13267, 41094, '現地に着いたら連絡します。', 'げんちに ついたら れんらく します。', 'Đến nơi tôi sẽ liên lạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13268, 41145, '出演者は控室で待っている。', 'しゅつえんしゃは ひかえしつで まって いる。', 'Người biểu diễn đang đợi trong phòng chờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13269, 41161, 'この町は昔、鉱山で栄えた。', 'この まちは むかし、こうざんで さかえた。', 'Thị trấn này xưa kia thịnh vượng nhờ mỏ khoáng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13270, 41262, '始発の電車で出かけた。', 'しはつの でんしゃで でかけた。', 'Tôi xuất phát bằng chuyến tàu đầu tiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13271, 41264, '展望台から市街が一望できる。', 'てんぼうだいから しがいが いちぼう できる。', 'Từ đài quan sát có thể phóng tầm mắt bao quát khu phố.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13272, 41334, '芝の上に座って弁当を食べた。', 'しばの うえに すわって べんとうを たべた。', 'Chúng tôi ngồi trên bãi cỏ ăn cơm hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13273, 41336, '山の斜面にみかん畑が広がっている。', 'やまの しゃめんに みかんばたけが ひろがって いる。', 'Vườn quýt trải rộng trên sườn dốc của núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13274, 41417, '次の十字路を左に曲がってください。', 'つぎの じゅうじろを ひだりに まがって ください。', 'Hãy rẽ trái ở ngã tư tiếp theo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13275, 41586, 'ほうきと塵取りで玄関を掃除した。', 'ほうきと ちりとりで げんかんを そうじ した。', 'Tôi quét dọn lối vào bằng chổi và cái hót rác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13276, 41607, '一人暮らしの世帯が増えている。', 'ひとりぐらしの せたいが ふえて いる。', 'Số hộ gia đình sống một mình đang tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13277, 41595, '見渡す限り水田が広がっている。', 'みわたす かぎり すいでんが ひろがって いる。', 'Ruộng lúa nước trải dài tít tắp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13278, 41602, '巣の中で雛が餌を待っている。', 'すの なかで ひなが えさを まって いる。', 'Chim non đang chờ mồi trong tổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13279, 41613, 'この学校の制服はかわいいと評判だ。', 'この がっこうの せいふくは かわいいと ひょうばんだ。', 'Đồng phục trường này nổi tiếng là dễ thương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13280, 41624, '運動会は晴天に恵まれた。', 'うんどうかいは せいてんに めぐまれた。', 'Hội thao được trời quang đãng ủng hộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13281, 41693, 'この海峡は多くの船舶が通る。', 'この かいきょうは おおくの せんぱくが とおる。', 'Rất nhiều tàu thuyền đi qua eo biển này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13282, 41830, '夏祭りで団扇をもらった。', 'なつまつりで うちわを もらった。', 'Tôi được tặng chiếc quạt tay ở lễ hội mùa hè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13283, 41886, '夜の帳が下りて、町は静かになった。', 'よるの とばりが おりて、まちは しずかに なった。', 'Màn đêm buông xuống, thị trấn trở nên yên tĩnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13284, 41881, '昼飯は簡単に済ませた。', 'ちゅうはんは かんたんに すませた。', 'Tôi ăn trưa qua loa cho xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13285, 41922, '偶然通りかかった人が助けてくれた。', 'ぐうぜん とおりかかった ひとが たすけて くれた。', 'Một người tình cờ đi ngang qua đã giúp tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13286, 41939, '高級住宅街に大きな邸宅が並んでいる。', 'こうきゅう じゅうたくがいに おおきな ていたくが ならんで いる。', 'Các dinh thự lớn nằm san sát ở khu nhà cao cấp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13287, 42007, 'この町は陶器の生産で知られている。', 'この まちは とうきの せいさんで しられて いる。', 'Thị trấn này nổi tiếng với nghề làm gốm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13288, 41980, 'この店では各地の土産品を扱っている。', 'この みせでは かくちの どさんひんを あつかって いる。', 'Cửa hàng này bán sản vật của nhiều địa phương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13289, 42046, '内陸の地域は夏暑く冬寒い。', 'ないりくの ちいきは なつ あつく ふゆ さむい。', 'Vùng nội địa mùa hè nóng, mùa đông lạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13290, 42063, '食事の直後の入浴は避けたほうがいい。', 'しょくじの ちょくごの にゅうよくは さけた ほうが いい。', 'Nên tránh tắm ngay sau khi ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13291, 42101, '台所の排水が詰まってしまった。', 'だいどころの はいすいが つまって しまった。', 'Ống thoát nước nhà bếp bị tắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13292, 42113, 'おにぎりの中に梅干を入れた。', 'おにぎりの なかに うめぼしを いれた。', 'Tôi cho mơ muối vào trong nắm cơm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13293, 42159, '各部屋に消火器が備え付けてある。', 'かく へやに しょうかきが そなえつけて ある。', 'Mỗi phòng đều được trang bị sẵn bình chữa cháy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13294, 42227, '覆面をした男が店に押し入った。', 'ふくめんを した おとこが みせに おしいった。', 'Một gã bịt mặt đã xông vào cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13295, 42229, '日仏の文化交流が盛んになった。', 'にちふつの ぶんか こうりゅうが さかんに なった。', 'Giao lưu văn hóa Nhật - Pháp trở nên sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13296, 42272, 'パーティーの後片付けを手伝った。', 'パーティーの あとかたづけを てつだった。', 'Tôi giúp dọn dẹp sau bữa tiệc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13297, 42281, 'この水筒は保温性が高い。', 'この すいとうは ほおんせいが たかい。', 'Bình nước này giữ nhiệt tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13298, 42327, 'どんな理由があっても暴力はいけない。', 'どんな りゆうが あっても ぼうりょくは いけない。', 'Dù với lý do gì cũng không được dùng bạo lực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13299, 42332, 'チームはタイトルの防衛に成功した。', 'チームは タイトルの ぼうえいに せいこう した。', 'Đội đã bảo vệ thành công danh hiệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13300, 42320, '毎年多くの観光客が京都を訪れる。', 'まいとし おおくの かんこうきゃくが きょうとを おとずれる。', 'Hằng năm rất nhiều du khách đến thăm Kyoto.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13301, 42333, 'この扉は防火扉なので、閉めておいてください。', 'この とびらは ぼうか とびら なので、しめて おいて ください。', 'Cánh cửa này là cửa chống cháy, xin hãy đóng lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13302, 42337, '授業中に使っていた携帯電話を没収された。', 'じゅぎょうちゅうに つかって いた けいたい でんわを ぼっしゅう された。', 'Điện thoại dùng trong giờ học đã bị tịch thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13303, 42380, '無断で他人の写真を使ってはいけない。', 'むだんで たにんの しゃしんを つかっては いけない。', 'Không được tự ý dùng ảnh của người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13304, 42370, '海辺の民宿に二泊した。', 'うみべの みんしゅくに にはく した。', 'Tôi ở hai đêm tại một nhà nghỉ dân dã ven biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13305, 42397, '彼は名誉を傷つけられたとして訴えた。', 'かれは めいよを きずつけられたと して うったえた。', 'Ông ấy khởi kiện vì cho rằng danh dự bị tổn hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13306, 42393, 'この地方の名産はお茶だ。', 'この ちほうの めいさんは おちゃだ。', 'Đặc sản nổi tiếng của vùng này là trà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13307, 42410, '約束を守れず、面目ない。', 'やくそくを まもれず、めんぼく ない。', 'Không giữ được lời hứa, tôi thật mất mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13308, 42427, '客のために夜具を用意した。', 'きゃくの ために やぐを ようい した。', 'Tôi chuẩn bị chăn đệm cho khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13309, 42512, '混乱に乗じて店が略奪された。', 'こんらんに じょうじて みせが りゃくだつ された。', 'Lợi dụng hỗn loạn, các cửa hàng bị cướp bóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13310, 42508, '帰りに本屋に立ち寄った。', 'かえりに ほんやに たちよった。', 'Trên đường về tôi ghé qua hiệu sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13311, 41803, '大雨で川があふれ、大水になった。', 'おおあめで かわが あふれ、おおみずに なった。', 'Mưa lớn làm sông tràn bờ gây lũ lụt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13312, 41858, '「畜生、また負けた」と彼は叫んだ。', '「ちくしょう、また まけた」と かれは さけんだ。', '"Chết tiệt, lại thua rồi", anh ta hét lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13313, 42222, '子供が風車を持って走っている。', 'こどもが かざぐるまを もって はしって いる。', 'Đứa trẻ cầm chong chóng chạy nhảy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13314, 42490, '空に雷の光が走った。', 'そらに いかずちの ひかりが はしった。', 'Ánh sét lóe lên trên bầu trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13315, 42521, '地球の両極は氷に覆われている。', 'ちきゅうの りょうきょくは こおりに おおわれて いる。', 'Hai cực của Trái Đất được băng bao phủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13316, 42574, '朝早くから小鳥が囀っている。', 'あさ はやくから ことりが さえずって いる。', 'Từ sáng sớm chim nhỏ đã hót líu lo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13317, 42595, '桜の蕾が膨らんできた。', 'さくらの つぼみが ふくらんで きた。', 'Nụ hoa anh đào đã bắt đầu căng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13319, 40798, '会議は隔週の月曜日に開かれる。', 'かいぎは かくしゅうの げつようびに ひらかれる。', 'Cuộc họp được tổ chức vào thứ hai cách tuần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13320, 41046, '書類に生年月日を記入してください。', 'しょるいに せいねん がっぴを きにゅう して ください。', 'Hãy ghi ngày tháng năm sinh vào giấy tờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13321, 41167, '仕事の合間にコーヒーを飲んだ。', 'しごとの あいまに コーヒーを のんだ。', 'Tôi uống cà phê trong lúc nghỉ giữa giờ làm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13322, 41384, '病院に着いた時には、もう手遅れだった。', 'びょういんに ついた ときには、もう ておくれ だった。', 'Khi đến bệnh viện thì đã quá muộn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13323, 41745, '束の間の休息を楽しんだ。', 'つかのまの きゅうそくを たのしんだ。', 'Tôi tận hưởng khoảnh khắc nghỉ ngơi ngắn ngủi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13324, 42431, '夜中に地震があって目が覚めた。', 'よなかに じしんが あって めが さめた。', 'Nửa đêm có động đất làm tôi tỉnh giấc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13325, 42543, '連日三十五度を超える暑さが続いている。', 'れんじつ さんじゅうごどを こえる あつさが つづいて いる。', 'Nắng nóng trên 35 độ kéo dài nhiều ngày liền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13326, 43240, '百メートル走で自己ベストのタイムを出した。', 'ひゃく メートルそうで じこ ベストの タイムを だした。', 'Tôi đạt thành tích tốt nhất của bản thân ở cự ly 100 m.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13327, 40451, 'ジャンボサイズのピザを注文した。', 'ジャンボ サイズの ピザを ちゅうもん した。', 'Tôi gọi chiếc pizza cỡ đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13328, 40641, '私はその事件とは一切関係がない。', 'わたしは その じけんとは いっさい かんけいが ない。', 'Tôi hoàn toàn không liên quan đến vụ việc đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13329, 40644, '計画の一部を変更した。', 'けいかくの いちぶを へんこう した。', 'Tôi đã thay đổi một phần kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13330, 41075, '台風で野菜の値段が軒並み上がった。', 'たいふうで やさいの ねだんが のきなみ あがった。', 'Do bão, giá rau đồng loạt tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13331, 41163, '今年の米の収穫高は去年より多い。', 'ことしの こめの しゅうかくだかは きょねんより おおい。', 'Sản lượng thu hoạch lúa năm nay nhiều hơn năm ngoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13332, 41497, '彼は試験で上位の成績を取った。', 'かれは しけんで じょういの せいせきを とった。', 'Anh ấy đạt thứ hạng cao trong kỳ thi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13333, 41675, '先着百名様にプレゼントを差し上げます。', 'せんちゃく ひゃくめいさまに プレゼントを さしあげます。', 'Một trăm khách đến sớm nhất sẽ được tặng quà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13334, 41736, '何もしないよりは、少しでもやったほうがましだ。', 'なにも しない よりは、すこしでも やった ほうが ましだ。', 'Làm dù chỉ chút ít vẫn hơn là không làm gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13335, 41738, '運動は食欲を増進させる。', 'うんどうは しょくよくを ぞうしん させる。', 'Vận động làm tăng cảm giác thèm ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13336, 41798, '休日は大概家にいる。', 'きゅうじつは たいがい いえに いる。', 'Ngày nghỉ phần lớn tôi ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13337, 41806, '仕事は大方片付いた。', 'しごとは おおかた かたづいた。', 'Công việc gần như đã xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13338, 41859, '疲労が蓄積して、病気になった。', 'ひろうが ちくせき して、びょうきに なった。', 'Mệt mỏi tích tụ khiến tôi đổ bệnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13339, 42420, '計量カップの目盛を見て、水を入れた。', 'けいりょう カップの めもりを みて、みずを いれた。', 'Tôi nhìn vạch chia trên cốc đong rồi đổ nước vào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13340, 42575, '事故現場には夥しい数の人が集まった。', 'じこ げんばには おびただしい かずの ひとが あつまった。', 'Vô số người tụ tập tại hiện trường tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13341, 37874, '話し合いで衝突を回避した。', 'はなしあいで しょうとつを かいひ した。', 'Nhờ thương lượng mà tránh được xung đột.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13342, 37875, '工事の騒音が睡眠を妨害している。', 'こうじの そうおんが すいみんを ぼうがい して いる。', 'Tiếng ồn công trình đang cản trở giấc ngủ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13343, 40495, '髪型をイメージチェンジした。', 'かみがたを イメージ チェンジ した。', 'Tôi đổi kiểu tóc để thay đổi hình ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13344, 40645, 'その事件で町の雰囲気が一変した。', 'その じけんで まちの ふんいきが いっぺん した。', 'Vụ việc đó làm bầu không khí thị trấn thay đổi hoàn toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13345, 40734, '彼は約束を果たした。', 'かれは やくそくを はたした。', 'Anh ấy đã thực hiện lời hứa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13346, 40758, '大雨警報が解除された。', 'おおあめ けいほうが かいじょ された。', 'Cảnh báo mưa lớn đã được dỡ bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13347, 40783, '彼女は怒ってそっぽを向いた。', 'かのじょは おこって そっぽを むいた。', 'Cô ấy giận dỗi quay mặt đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13348, 40791, 'その動画はネットで一気に拡散した。', 'その どうがは ネットで いっきに かくさん した。', 'Đoạn video đó lan truyền nhanh chóng trên mạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13349, 40794, '優勝が確定した。', 'ゆうしょうが かくてい した。', 'Chức vô địch đã được xác định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13350, 40797, '二人の考えは大きく隔たっている。', 'ふたりの かんがえは おおきく へだたって いる。', 'Suy nghĩ của hai người khác xa nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13351, 40805, '列に割り込まないでください。', 'れつに わりこまないで ください。', 'Xin đừng chen hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13352, 40812, '子供の願いを叶えてあげたい。', 'こどもの ねがいを かなえて あげたい。', 'Tôi muốn biến mong ước của con thành hiện thực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13353, 40835, 'カーブの前でスピードを緩めた。', 'カーブの まえで スピードを ゆるめた。', 'Tôi giảm tốc trước khúc cua.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13354, 40838, '彼は最後まで自分の信念を貫いた。', 'かれは さいごまで じぶんの しんねんを つらぬいた。', 'Anh ấy giữ vững niềm tin của mình đến cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13355, 40846, '彼はその事件に関与していないと主張した。', 'かれは その じけんに かんよ して いないと しゅちょう した。', 'Anh ta khẳng định mình không dính líu đến vụ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13356, 40865, '壁に寄り掛かって休んだ。', 'かべに よりかかって やすんだ。', 'Tôi tựa vào tường nghỉ ngơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13357, 40867, '彼の研究は医学の発展に寄与した。', 'かれの けんきゅうは いがくの はってんに きよ した。', 'Nghiên cứu của ông ấy đã đóng góp vào sự phát triển y học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13358, 40900, '彼は人を欺いて金をだまし取った。', 'かれは ひとを あざむいて かねを だましとった。', 'Hắn lừa dối người khác để chiếm đoạt tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13359, 40920, '被害は県全体に及んだ。', 'ひがいは けん ぜんたいに およんだ。', 'Thiệt hại lan ra toàn tỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13360, 40949, '無理に参加を強いるつもりはない。', 'むりに さんかを しいる つもりは ない。', 'Tôi không định ép buộc ai tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13361, 40951, '警察は警戒を強めている。', 'けいさつは けいかいを つよめて いる。', 'Cảnh sát đang tăng cường cảnh giác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13362, 40974, '目を凝らして遠くを見た。', 'めを こらして とおくを みた。', 'Tôi căng mắt nhìn ra xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13363, 40999, '長い間、病気が彼を苦しめた。', 'ながい あいだ、びょうきが かれを くるしめた。', 'Bệnh tật đã hành hạ anh ấy suốt thời gian dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13364, 41014, '彼の話に耳を傾けた。', 'かれの はなしに みみを かたむけた。', 'Tôi lắng tai nghe câu chuyện của anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13365, 41020, '新しい政党は大きな目標を掲げた。', 'あたらしい せいとうは おおきな もくひょうを かかげた。', 'Đảng mới đã nêu cao mục tiêu lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13366, 41027, '大雨による土砂災害に警戒してください。', 'おおあめに よる どしゃ さいがいに けいかい して ください。', 'Hãy cảnh giác với sạt lở đất do mưa lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13367, 41056, '袖を捲って皿を洗った。', 'そでを まくって さらを あらった。', 'Tôi xắn tay áo rửa bát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13368, 41060, '彼は新しい時計を友達に見せびらかした。', 'かれは あたらしい とけいを ともだちに みせびらかした。', 'Anh ta khoe chiếc đồng hồ mới với bạn bè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13369, 41065, '大雪のため、運転を見合わせています。', 'おおゆきの ため、うんてんを みあわせて います。', 'Do tuyết lớn, tàu đang tạm ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13370, 41071, '好きなドラマを見逃してしまった。', 'すきな ドラマを みのがして しまった。', 'Tôi lỡ mất bộ phim yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13371, 41077, '一度始めたことは最後まで遣り通す。', 'いちど はじめた ことは さいごまで やりとおす。', 'Việc gì đã bắt đầu thì làm đến cùng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13372, 41111, 'この山は二つの県に跨がっている。', 'この やまは ふたつの けんに またがって いる。', 'Ngọn núi này trải dài qua hai tỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13373, 41122, '二人は笑顔で挨拶を交わした。', 'ふたりは えがおで あいさつを かわした。', 'Hai người tươi cười chào hỏi nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13374, 41166, 'みんなで力を合わして頑張ろう。', 'みんなで ちからを あわして がんばろう。', 'Mọi người hãy cùng góp sức cố gắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13375, 41191, '給料から税金が差し引かれる。', 'きゅうりょうから ぜいきんが さしひかれる。', 'Thuế được khấu trừ từ lương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13376, 41193, '夜更かしすると、明日の仕事に差し支える。', 'よふかし すると、あしたの しごとに さしつかえる。', 'Thức khuya sẽ ảnh hưởng đến công việc ngày mai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13377, 41801, '鳥が大空を自由に飛んでいる。', 'とりが おおぞらを じゆうに とんで いる。', 'Chim bay tự do trên bầu trời rộng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13378, 41855, '事故で電車に三十分の遅れが出た。', 'じこで でんしゃに さんじゅっぷんの おくれが でた。', 'Do tai nạn, tàu bị chậm ba mươi phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13379, 41892, '潮の香りが漂う港町を歩いた。', 'うしおの かおりが ただよう みなとまちを あるいた。', 'Tôi dạo bước ở thị trấn cảng thoang thoảng mùi biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13380, 41902, 'ついに山の頂に立った。', 'ついに やまの いただきに たった。', 'Cuối cùng tôi đã đứng trên đỉnh núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13381, 41969, '窓の外にはのどかな田園風景が広がっていた。', 'まどの そとには のどかな でんえん ふうけいが ひろがって いた。', 'Bên ngoài cửa sổ trải ra cảnh đồng quê yên bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13382, 43230, '水族館で大きなえいが泳いでいた。', 'すいぞくかんで おおきな えいが およいで いた。', 'Ở thủy cung có con cá đuối lớn đang bơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13383, 38223, '年齢に相応した服装をする。', 'ねんれいに そうおう した ふくそうを する。', 'Ăn mặc phù hợp với tuổi tác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13384, 38294, '現状を打破するには新しい発想が必要だ。', 'げんじょうを だは するには あたらしい はっそうが ひつようだ。', 'Để phá vỡ hiện trạng cần ý tưởng mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13385, 40372, '人の失敗を嘲笑うのはよくない。', 'ひとの しっぱいを あざわらうのは よくない。', 'Chế giễu thất bại của người khác là không tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13386, 40429, '日本に来て三ヶ月になる。', 'にほんに きて さんかげつに なる。', 'Tôi đến Nhật được ba tháng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13387, 40440, '彼は授業をサボって映画を見に行った。', 'かれは じゅぎょうを サボって えいがを みに いった。', 'Anh ta trốn học đi xem phim.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13388, 40485, 'タイムリーな話題で会議が盛り上がった。', 'タイムリーな わだいで かいぎが もりあがった。', 'Chủ đề đúng thời điểm làm cuộc họp sôi nổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13389, 40490, '予定がダブってしまった。', 'よていが ダブって しまった。', 'Lịch hẹn bị trùng nhau mất rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13390, 40550, 'この料理は新鮮な野菜をふんだんに使っている。', 'この りょうりは しんせんな やさいを ふんだんに つかって いる。', 'Món này dùng rất nhiều rau tươi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13391, 40582, '困難な仕事を最後までやり遂げた。', 'こんなんな しごとを さいごまで やりとげた。', 'Tôi đã hoàn thành trọn vẹn công việc khó khăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13392, 40607, 'この機械は扱いが難しい。', 'この きかいは あつかいが むずかしい。', 'Chiếc máy này khó sử dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13393, 40635, 'ビールを一気に飲み干した。', 'ビールを いっきに のみほした。', 'Tôi uống cạn cốc bia một hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13394, 40638, '一見簡単そうだが、実は難しい。', 'いっけん かんたん そうだが、じつは むずかしい。', 'Thoạt nhìn có vẻ dễ nhưng thực ra khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13395, 40650, '彼は気まずそうに目を逸らした。', 'かれは きまずそうに めを そらした。', 'Anh ấy lúng túng quay mắt đi chỗ khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13396, 40654, '銀行は金利を引き下げた。', 'ぎんこうは きんりを ひきさげた。', 'Ngân hàng đã hạ lãi suất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13397, 40656, 'いらなくなった家具を業者が引き取ってくれた。', 'いらなく なった かぐを ぎょうしゃが ひきとって くれた。', 'Đồ đạc không dùng nữa đã được bên dịch vụ nhận về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13398, 40658, 'コートを釘に引っ掛けて破いてしまった。', 'コートを くぎに ひっかけて やぶいて しまった。', 'Áo khoác móc vào đinh nên bị rách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13399, 40660, '彼女は仕事の飲み込みが早い。', 'かのじょは しごとの のみこみが はやい。', 'Cô ấy nắm bắt công việc rất nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13400, 40689, '雨に煙る町並みが美しい。', 'あめに けむる まちなみが うつくしい。', 'Phố xá mờ khói trong mưa thật đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13401, 40698, '心が汚れることのないように生きたい。', 'こころが けがれる ことの ない ように いきたい。', 'Tôi muốn sống sao cho tâm hồn không bị vấy bẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13402, 40701, '荷物を無理やりかばんに押し込んだ。', 'にもつを むりやり かばんに おしこんだ。', 'Tôi cố nhét đồ vào túi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13403, 40767, '年が改まり、新しい生活が始まった。', 'としが あらたまり、あたらしい せいかつが はじまった。', 'Năm mới sang, cuộc sống mới đã bắt đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13404, 40828, 'ドルを円に換算すると、いくらになりますか。', 'ドルを えんに かんさん すると、いくらに なりますか。', 'Quy đổi đô la ra yên thì được bao nhiêu?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13405, 40870, '期日までにレポートを提出してください。', 'きじつまでに レポートを ていしゅつ して ください。', 'Hãy nộp báo cáo trước hạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13406, 40886, '大規模な地震が起きた。', 'だいきぼな じしんが おきた。', 'Đã xảy ra trận động đất quy mô lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13407, 40915, '彼に会わなくなって久しい。', 'かれに あわなく なって ひさしい。', 'Đã lâu lắm rồi tôi không gặp anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13408, 40926, '古い橋の板が朽ちている。', 'ふるい はしの いたが くちて いる。', 'Ván cầu cũ đã mục nát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13409, 40934, '相手は私たちの提案を拒絶した。', 'あいては わたしたちの ていあんを きょぜつ した。', 'Đối phương đã cự tuyệt đề nghị của chúng tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13410, 40979, '被害はこの地域に局限された。', 'ひがいは この ちいきに きょくげん された。', 'Thiệt hại chỉ giới hạn trong khu vực này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13411, 41040, '努力が結果に結び付いた。', 'どりょくが けっかに むすびついた。', 'Nỗ lực đã dẫn đến kết quả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13412, 41041, '二つの事件を結び付ける証拠はない。', 'ふたつの じけんを むすびつける しょうこは ない。', 'Không có bằng chứng liên kết hai vụ án.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13413, 41100, 'この寺には古の面影が残っている。', 'この てらには いにしえの おもかげが のこって いる。', 'Ngôi chùa này còn lưu giữ dáng vẻ của thời xưa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13414, 41102, '道で警察官に呼び止められた。', 'みちで けいさつかんに よびとめられた。', 'Tôi bị cảnh sát gọi lại trên đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13415, 41144, 'うわさはすぐに学校中に広まった。', 'うわさは すぐに がっこうじゅうに ひろまった。', 'Tin đồn nhanh chóng lan khắp trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13416, 41153, '猿が畑を荒らした。', 'さるが はたけを あらした。', 'Lũ khỉ đã phá hoại ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13417, 41199, '市は毎年花火大会を催している。', 'しは まいとし はなび たいかいを もよおして いる。', 'Hằng năm thành phố tổ chức lễ hội pháo hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13418, 41303, '日本とベトナムの時差は二時間だ。', 'にほんと ベトナムの じさは にじかんだ。', 'Chênh lệch múi giờ giữa Nhật và Việt Nam là hai tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13419, 41343, '若干名の社員を募集している。', 'じゃっかんめいの しゃいんを ぼしゅう して いる。', 'Đang tuyển một số nhân viên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13420, 41411, '工事のため、この道は終日通行止めだ。', 'こうじの ため、この みちは しゅうじつ つうこうどめだ。', 'Do thi công, con đường này cấm lưu thông cả ngày.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13421, 41421, '新製品は従来のものより軽い。', 'しんせいひんは じゅうらいの ものより かるい。', 'Sản phẩm mới nhẹ hơn loại trước đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13422, 41647, 'この部屋は西日が強く当たって暑い。', 'この へやは にしびが つよく あたって あつい。', 'Căn phòng này bị nắng chiều chiếu gắt nên nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13423, 41649, '高校時代は私の青春だった。', 'こうこう じだいは わたしの せいしゅん だった。', 'Thời cấp ba là tuổi thanh xuân của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13424, 41669, '大雪の後は雪崩に注意してください。', 'おおゆきの あとは なだれに ちゅうい して ください。', 'Sau trận tuyết lớn hãy đề phòng tuyết lở.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13425, 41698, '若い二人の前途を祝して乾杯しよう。', 'わかい ふたりの ぜんとを しゅく して かんぱい しよう。', 'Hãy nâng ly chúc tương lai của đôi bạn trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13426, 41929, '大雨で堤防が決壊した。', 'おおあめで ていぼうが けっかい した。', 'Mưa lớn làm vỡ đê.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13427, 41950, '望遠鏡で天体を観測した。', 'ぼうえんきょうで てんたいを かんそく した。', 'Tôi quan sát thiên thể bằng kính viễn vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13428, 41974, '秋になると渡り鳥が南へ飛んでいく。', 'あきに なると わたりどりが みなみへ とんで いく。', 'Đến mùa thu chim di trú bay về phương nam.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13429, 41986, '熊は冬の間冬眠する。', 'くまは ふゆの あいだ とうみん する。', 'Gấu ngủ đông suốt mùa đông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13430, 42023, '昔の人は銅をあかがねと呼んだ。', 'むかしの ひとは どうを あかがねと よんだ。', 'Người xưa gọi đồng là "akagane".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13431, 42054, '猫が日向で気持ちよさそうに寝ている。', 'ねこが ひなたで きもち よさそうに ねて いる。', 'Con mèo đang ngủ ngon lành chỗ có nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13432, 42055, '日頃の努力が実を結んだ。', 'ひごろの どりょくが みを むすんだ。', 'Nỗ lực thường ngày đã đơm hoa kết trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13433, 42059, '研究者たちは日夜研究に励んでいる。', 'けんきゅうしゃたちは にちや けんきゅうに はげんで いる。', 'Các nhà khoa học ngày đêm miệt mài nghiên cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13434, 42075, '娘も年頃になり、おしゃれに興味を持ち始めた。', 'むすめも としごろに なり、おしゃれに きょうみを もち はじめた。', 'Con gái đã đến tuổi dậy thì, bắt đầu quan tâm đến ăn diện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13435, 42163, '彼には反省の色が微塵もない。', 'かれには はんせいの いろが みじんも ない。', 'Anh ta không có chút xíu dấu hiệu hối lỗi nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13436, 42174, 'この米は新しい品種だ。', 'この こめは あたらしい ひんしゅだ。', 'Loại gạo này là giống mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13437, 42179, 'この道は頻繁に事故が起きる。', 'この みちは ひんぱんに じこが おきる。', 'Con đường này thường xuyên xảy ra tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13438, 42237, '会議は三時五分に始まった。', 'かいぎは さんじ ごふんに はじまった。', 'Cuộc họp bắt đầu lúc ba giờ năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13439, 42245, '地下から温泉が噴出した。', 'ちかから おんせんが ふんしゅつ した。', 'Suối nước nóng phun lên từ lòng đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13440, 42286, '捕鯨については国際的な議論がある。', 'ほげいに ついては こくさいてきな ぎろんが ある。', 'Có tranh luận quốc tế về việc săn cá voi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13441, 42326, '暴風のため、電車が止まった。', 'ぼうふうの ため、でんしゃが とまった。', 'Vì gió bão nên tàu điện ngừng chạy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13442, 42349, 'この海底には大量の石油が埋蔵されている。', 'この かいていには たいりょうの せきゆが まいぞう されて いる。', 'Đáy biển này có trữ lượng dầu mỏ lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13443, 42350, '切手を五枚ください。', 'きってを ごまい ください。', 'Cho tôi năm con tem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13444, 42366, 'この地区は住宅が密集している。', 'この ちくは じゅうたくが みっしゅう して いる。', 'Khu này nhà cửa san sát dày đặc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13445, 42455, '空が夕焼けで真っ赤に染まった。', 'そらが ゆうやけで まっかに そまった。', 'Bầu trời nhuộm đỏ rực bởi ráng chiều.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13446, 42459, '余暇を利用して日本語を勉強している。', 'よかを りよう して にほんごを べんきょう して いる。', 'Tôi tận dụng thời gian rảnh để học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13447, 42573, '鳥が嘴で木をつついている。', 'とりが くちばしで きを つついて いる。', 'Con chim đang lấy mỏ mổ vào thân cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13448, 41230, '明日、改めてご挨拶に参上いたします。', 'あした、あらためて ごあいさつに さんじょう いたします。', 'Ngày mai tôi xin đến chào hỏi lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13449, 41247, '畑にねずみを捕る罠を仕掛けた。', 'はたけに ねずみを とる わなを しかけた。', 'Tôi gài bẫy bắt chuột trên ruộng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13450, 41251, '大きな部屋をカーテンで二つに仕切った。', 'おおきな へやを カーテンで ふたつに しきった。', 'Tôi ngăn căn phòng lớn làm hai bằng rèm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13451, 41275, 'この話は胸に止めておいてください。', 'この はなしは むねに とどめて おいて ください。', 'Chuyện này xin hãy giữ kín trong lòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13452, 41285, '彼は何度も脱出を試みた。', 'かれは なんども だっしゅつを こころみた。', 'Anh ta đã nhiều lần thử trốn thoát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13453, 41288, '先生から貴重なご意見を賜りました。', 'せんせいから きちょうな ごいけんを たまわりました。', 'Chúng tôi đã được thầy ban cho những ý kiến quý báu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13454, 41305, '薬を飲んだら痛みが治まった。', 'くすりを のんだら いたみが おさまった。', 'Uống thuốc xong cơn đau đã dịu đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13455, 41324, '袋を開けたままにしたら、せんべいが湿気てしまった。', 'ふくろを あけた ままに したら、せんべいが しけて しまった。', 'Để túi mở nên bánh gạo bị ỉu mất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13456, 41364, '魚の骨を取り除いてから料理した。', 'さかなの ほねを とりのぞいてから りょうり した。', 'Tôi bỏ xương cá rồi mới nấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13457, 41369, '休んで元気を取り戻した。', 'やすんで げんきを とりもどした。', 'Nghỉ ngơi xong tôi đã lấy lại sức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13458, 41397, '批判を真剣に受け止めている。', 'ひはんを しんけんに うけとめて いる。', 'Tôi tiếp nhận lời phê bình một cách nghiêm túc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13459, 41399, '彼は私の提案を受け入れてくれた。', 'かれは わたしの ていあんを うけいれて くれた。', 'Anh ấy đã chấp nhận đề xuất của tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13460, 41400, '申し込みは来月から受け付けます。', 'もうしこみは らいげつから うけつけます。', 'Đơn đăng ký sẽ được tiếp nhận từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13461, 41404, '彼は百メートル走で世界新記録を樹立した。', 'かれは ひゃく メートルそうで せかい しんきろくを じゅりつ した。', 'Anh ấy xác lập kỷ lục thế giới mới ở cự ly 100 m.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13462, 41407, 'このホールは二千人を収容できる。', 'この ホールは にせんにんを しゅうよう できる。', 'Hội trường này chứa được hai nghìn người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13463, 41415, '彼は怒って箱を蹴飛ばした。', 'かれは おこって はこを けとばした。', 'Anh ta tức giận đá văng cái hộp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13465, 41441, '火事の知らせで消防車が出動した。', 'かじの しらせで しょうぼうしゃが しゅつどう した。', 'Nhận tin hỏa hoạn, xe cứu hỏa đã xuất phát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13466, 41448, '観光客が増えて、町が潤った。', 'かんこうきゃくが ふえて、まちが うるおった。', 'Du khách tăng nên thị trấn trở nên khấm khá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13467, 41451, '古い家具を処分した。', 'ふるい かぐを しょぶん した。', 'Tôi đã thanh lý đồ đạc cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13468, 41470, '十八歳未満は対象から除外される。', 'じゅうはっさい みまんは たいしょうから じょがい される。', 'Người dưới mười tám tuổi bị loại khỏi đối tượng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13469, 41489, '間違えてデータを消去してしまった。', 'まちがえて データを しょうきょ して しまった。', 'Tôi lỡ tay xóa mất dữ liệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13470, 41492, '夏の道路は日差しを照り返して暑い。', 'なつの どうろは ひざしを てりかえして あつい。', 'Mặt đường mùa hè phản chiếu ánh nắng nên rất nóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13471, 41525, '二人の証言が食い違っている。', 'ふたりの しょうげんが くいちがって いる。', 'Lời khai của hai người mâu thuẫn nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13472, 41540, '病院内では大声での会話を慎んでください。', 'びょういんないでは おおごえでの かいわを つつしんで ください。', 'Trong bệnh viện xin hãy tránh nói chuyện to tiếng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13473, 41574, 'ご来場の方に記念品を進呈します。', 'ごらいじょうの かたに きねんひんを しんてい します。', 'Chúng tôi xin tặng quà lưu niệm cho quý khách đến dự.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13474, 41596, '年とともに体力が衰えてきた。', 'としと ともに たいりょくが おとろえて きた。', 'Theo tuổi tác thể lực suy giảm dần.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13475, 41597, 'この国は急速な経済成長を遂げた。', 'この くには きゅうそくな けいざい せいちょうを とげた。', 'Đất nước này đã đạt được tăng trưởng kinh tế nhanh chóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13476, 41600, '冬服は嵩張るので、旅行には不便だ。', 'ふゆふくは かさばるので、りょこうには ふべんだ。', 'Quần áo mùa đông cồng kềnh nên bất tiện khi đi du lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13477, 41690, '記者は工場に潜入して取材した。', 'きしゃは こうじょうに せんにゅう して しゅざい した。', 'Phóng viên đã lẻn vào nhà máy để lấy tin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13478, 41722, '雨が降りそうなので、出発を早めた。', 'あめが ふりそう なので、しゅっぱつを はやめた。', 'Trời sắp mưa nên chúng tôi xuất phát sớm hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13479, 41730, '溺れそうになって水の中で藻掻いた。', 'おぼれそうに なって みずの なかで もがいた。', 'Suýt chết đuối, tôi vùng vẫy trong nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13480, 41786, '大雪で物流が滞っている。', 'おおゆきで ぶつりゅうが とどこおって いる。', 'Do tuyết lớn, việc vận chuyển hàng hóa bị đình trệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13481, 41790, '裁判所は訴えを退けた。', 'さいばんしょは うったえを しりぞけた。', 'Tòa án đã bác đơn kiện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13482, 41795, '砂糖の代わりに蜂蜜で代用した。', 'さとうの かわりに はちみつで だいよう した。', 'Tôi dùng mật ong thay cho đường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13483, 41810, '乗客は全員無事に脱出した。', 'じょうきゃくは ぜんいん ぶじに だっしゅつ した。', 'Toàn bộ hành khách đã thoát ra an toàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13484, 41827, 'シャツの縫い目が綻びた。', 'シャツの ぬいめが ほころびた。', 'Đường may áo sơ mi bị sổ chỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13485, 41856, '彼は一代で財産を築いた。', 'かれは いちだいで ざいさんを きずいた。', 'Ông ấy gây dựng tài sản chỉ trong một đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13486, 41889, '彼はエベレストの登頂に挑んだ。', 'かれは エベレストの とうちょうに いどんだ。', 'Anh ấy thử thách chinh phục đỉnh Everest.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13487, 41904, '静かな図書館だと勉強が捗る。', 'しずかな としょかんだと べんきょうが はかどる。', 'Ở thư viện yên tĩnh thì học hành tiến triển tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13488, 41913, '家賃を払わないので、部屋を追い出された。', 'やちんを はらわないので、へやを おいだされた。', 'Không trả tiền thuê nên tôi bị đuổi khỏi phòng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13489, 41958, '車はここで百八十度転回した。', 'くるまは ここで ひゃくはちじゅうど てんかい した。', 'Chiếc xe quay đầu 180 độ tại đây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13490, 42021, '監督はチームを優勝に導いた。', 'かんとくは チームを ゆうしょうに みちびいた。', 'Huấn luyện viên đã dẫn dắt đội đến chức vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13491, 42109, '会場で資料を配布する。', 'かいじょうで しりょうを はいふ する。', 'Tài liệu sẽ được phát tại hội trường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13492, 42135, 'この仕事には危険が伴う。', 'この しごとには きけんが ともなう。', 'Công việc này đi kèm nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13493, 42158, '彼はこの研究に十年を費やした。', 'かれは この けんきゅうに じゅうねんを ついやした。', 'Ông ấy đã dành mười năm cho nghiên cứu này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13494, 42203, 'いいアイデアが浮かんだ。', 'いい アイデアが うかんだ。', 'Một ý tưởng hay chợt nảy ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13495, 42252, '財布を紛失して、警察に届けた。', 'さいふを ふんしつ して、けいさつに とどけた。', 'Tôi làm mất ví và đã báo cảnh sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13496, 42267, '利用者が減って、プールが閉鎖された。', 'りようしゃが へって、プールが へいさ された。', 'Người dùng giảm nên bể bơi bị đóng cửa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13497, 42279, '部屋の温度を一定に保つ。', 'へやの おんどを いっていに たもつ。', 'Giữ nhiệt độ phòng ổn định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13498, 42308, '脱いだ服を洗濯機に放り込んだ。', 'ぬいだ ふくを せんたくきに ほうりこんだ。', 'Tôi quẳng quần áo vừa cởi vào máy giặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13499, 42312, '工場から有害物質が放出された。', 'こうじょうから ゆうがい ぶっしつが ほうしゅつ された。', 'Chất độc hại đã thải ra từ nhà máy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13500, 42331, '食べ過ぎてお腹が膨れた。', 'たべすぎて おなかが ふくれた。', 'Ăn quá no nên bụng căng phồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13501, 42467, '彼の話は私の心を揺さぶった。', 'かれの はなしは わたしの こころを ゆさぶった。', 'Câu chuyện của anh ấy làm lay động lòng tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13502, 42491, 'この事件には金が絡んでいる。', 'この じけんには かねが からんで いる。', 'Vụ việc này có dính líu đến tiền bạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13503, 42497, '彼の行動はクラスの秩序を乱した。', 'かれの こうどうは クラスの ちつじょを みだした。', 'Hành động của cậu ấy làm rối trật tự lớp học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13504, 42522, 'エアコンなしで夏の暑さを凌いだ。', 'エアコン なしで なつの あつさを しのいだ。', 'Tôi chống chọi cái nóng mùa hè mà không có điều hòa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13505, 42541, '通りには商店が軒を連ねている。', 'とおりには しょうてんが のきを つらねて いる。', 'Dọc con phố các cửa hàng nối dài san sát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13506, 42549, '授業中に携帯を弄ってはいけない。', 'じゅぎょうちゅうに けいたいを いじっては いけない。', 'Không được nghịch điện thoại trong giờ học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13507, 42579, '夢じゃないかと頬を抓った。', 'ゆめじゃ ないかと ほおを つねった。', 'Tôi véo má xem có phải mơ không.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13508, 42580, '話し合いが拗れて、喧嘩になった。', 'はなしあいが こじれて、けんかに なった。', 'Cuộc nói chuyện trở nên căng thẳng rồi thành cãi nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13509, 42598, '台風は大きな被害を齎らした。', 'たいふうは おおきな ひがいを もたらした。', 'Cơn bão đã gây ra thiệt hại lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13510, 31831, '彼は傑出した才能を持つ画家だ。', 'かれは けっしゅつ した さいのうを もつ がかだ。', 'Ông ấy là họa sĩ có tài năng xuất chúng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13511, 31833, '彼は子供のころから非凡な才能を見せていた。', 'かれは こどもの ころから ひぼんな さいのうを みせて いた。', 'Từ nhỏ cậu ấy đã bộc lộ tài năng phi thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13512, 38259, '会社の杜撰な管理が事故を招いた。', 'かいしゃの ずさんな かんりが じこを まねいた。', 'Sự quản lý cẩu thả của công ty đã dẫn đến tai nạn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13513, 40392, '彼女はいつもエレガントな服を着ている。', 'かのじょは いつも エレガントな ふくを きて いる。', 'Cô ấy luôn mặc quần áo thanh lịch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13514, 40425, 'グレーのスーツを着て面接に行った。', 'グレーの スーツを きて めんせつに いった。', 'Tôi mặc bộ vest xám đi phỏng vấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13515, 40464, '傘がなくて、ずぶ濡れになった。', 'かさが なくて、ずぶぬれに なった。', 'Không có ô nên tôi ướt sũng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13516, 40512, '彼は声のトーンを落として話した。', 'かれは こえの トーンを おとして はなした。', 'Anh ấy hạ giọng xuống để nói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13517, 40688, '口うるさい先輩は少し煙たい存在だ。', 'くちうるさい せんぱいは すこし けむたい そんざいだ。', 'Đàn anh hay cằn nhằn là người khiến tôi hơi ngại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13518, 40696, 'そんな汚らわしい金は受け取れない。', 'そんな けがらわしい かねは うけとれない。', 'Tôi không thể nhận đồng tiền bẩn thỉu như thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13519, 41762, '彼は研究に打ち込んでいる。', 'かれは けんきゅうに うちこんで いる。', 'Anh ấy dồn hết tâm huyết vào nghiên cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13520, 41764, '人気がなくて番組が打ち切られた。', 'にんきが なくて ばんぐみが うちきられた。', 'Không được ưa chuộng nên chương trình bị cắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13521, 41778, '彼の計画は現実味を帯びてきた。', 'かれの けいかくは げんじつみを おびて きた。', 'Kế hoạch của anh ấy đã mang tính thực tế hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13522, 41831, 'この布は水を弾く。', 'この ぬのは みずを はじく。', 'Loại vải này chống thấm nước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13523, 41849, '最近、気持ちが弛んでいる。', 'さいきん、きもちが たるんで いる。', 'Dạo này tinh thần tôi lơi lỏng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13524, 41854, '時計を五分遅らした。', 'とけいを ごふん おくらした。', 'Tôi chỉnh đồng hồ chậm lại năm phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13525, 41866, 'このお菓子には着色料が使われていない。', 'この おかしには ちゃくしょくりょうが つかわれて いない。', 'Bánh kẹo này không dùng phẩm màu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13526, 41867, '皆様、ご着席ください。', 'みなさま、ごちゃくせき ください。', 'Kính mời quý vị ngồi vào chỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13527, 41912, '試験前の追い込みで毎晩遅くまで勉強した。', 'しけんまえの おいこみで まいばん おそくまで べんきょう した。', 'Giai đoạn nước rút trước kỳ thi, tối nào tôi cũng học đến khuya.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13528, 41942, '新しい環境に適応するには時間がかかる。', 'あたらしい かんきょうに てきおう するには じかんが かかる。', 'Thích nghi với môi trường mới cần thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13529, 43226, '今年は給料が少しアップした。', 'ことしは きゅうりょうが すこし アップ した。', 'Năm nay lương tăng lên một chút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13530, 40513, '彼は仕事に関してはドライだ。', 'かれは しごとに かんしては ドライだ。', 'Về công việc, anh ấy rất thực dụng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13531, 31767, '審判は公正な判断をしなければならない。', 'しんぱんは こうせいな はんだんを しなければ ならない。', 'Trọng tài phải đưa ra phán quyết công bằng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13532, 37860, '厳密に言えば、それは間違いだ。', 'げんみつに いえば、それは まちがいだ。', 'Nói một cách chặt chẽ thì điều đó là sai.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13533, 37862, '出発前に入念に点検した。', 'しゅっぱつまえに にゅうねんに てんけん した。', 'Trước khi xuất phát tôi kiểm tra kỹ lưỡng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13534, 37864, 'この文章は冗長で読みにくい。', 'この ぶんしょうは じょうちょうで よみにくい。', 'Đoạn văn này dài dòng, khó đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13535, 37865, '彼の説明は簡潔で明瞭だった。', 'かれの せつめいは かんけつで めいりょう だった。', 'Lời giải thích của anh ấy ngắn gọn và rõ ràng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13536, 38219, 'これは暫定的な措置です。', 'これは ざんていてきな そち です。', 'Đây là biện pháp tạm thời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13537, 38287, '後継者が決まり、会社は安泰だ。', 'こうけいしゃが きまり、かいしゃは あんたいだ。', 'Người kế nhiệm đã được chọn, công ty yên ổn rồi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13538, 40377, '彼の返事はあやふやだった。', 'かれの へんじは あやふや だった。', 'Câu trả lời của anh ấy mập mờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13539, 40461, 'ねずみはすばしこくて、なかなか捕まらない。', 'ねずみは すばしこくて、なかなか つかまらない。', 'Chuột nhanh nhẹn nên khó bắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13540, 40502, 'あいつは態度がでかい。', 'あいつは たいどが でかい。', 'Thằng đó thái độ hách dịch quá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13541, 40549, '月曜日の朝はブルーな気分になる。', 'げつようびの あさは ブルーな きぶんに なる。', 'Sáng thứ hai tâm trạng thường buồn chán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13542, 40581, 'この手続きはややこしい。', 'この てつづきは ややこしい。', 'Thủ tục này rắc rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13543, 40704, 'この地域には黄色人種が多く住んでいる。', 'この ちいきには おうしょく じんしゅが おおく すんで いる。', 'Khu vực này có nhiều người da vàng sinh sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13544, 41267, '子供が空の虹を指差した。', 'こどもが そらの にじを ゆびさした。', 'Đứa trẻ chỉ tay lên cầu vồng trên trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13545, 41341, '高いビルが日光を遮っている。', 'たかい ビルが にっこうを さえぎって いる。', 'Tòa nhà cao đang che khuất ánh nắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13546, 41345, '夕方になって雨が弱まった。', 'ゆうがたに なって あめが よわまった。', 'Đến chiều tối mưa đã nhẹ đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13547, 41346, '火を弱めて十分煮てください。', 'ひを よわめて じゅっぷん にて ください。', 'Hãy vặn nhỏ lửa và ninh mười phút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13548, 41358, 'この機械の取り扱いには注意が必要だ。', 'この きかいの とりあつかいには ちゅういが ひつようだ。', 'Cần chú ý khi sử dụng máy này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13549, 41360, '子供を取り巻く環境が変わってきた。', 'こどもを とりまく かんきょうが かわって きた。', 'Môi trường xung quanh trẻ em đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13550, 41362, '大小取り混ぜて十個の箱がある。', 'だいしょう とりまぜて じっこの はこが ある。', 'Có mười cái hộp cả to lẫn nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13551, 41476, '相手を嘗めてかかると、痛い目に遭う。', 'あいてを なめて かかると、いたい めに あう。', 'Coi thường đối thủ thì sẽ chuốc lấy thất bại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13552, 41591, '天井から水が垂れている。', 'てんじょうから みずが たれて いる。', 'Nước đang nhỏ giọt từ trần nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13553, 41604, '台所に新しい食器洗い機を据え付けた。', 'だいどころに あたらしい しょっき あらいきを すえつけた。', 'Tôi lắp máy rửa bát mới trong bếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13554, 41610, '彼は接戦を制して優勝した。', 'かれは せっせんを せいして ゆうしょう した。', 'Anh ấy thắng trận đấu sít sao và giành chức vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13555, 41616, 'この会社は三つの部門から成り立っている。', 'この かいしゃは みっつの ぶもんから なりたって いる。', 'Công ty này gồm ba bộ phận.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13556, 41634, '父はひげを生やしている。', 'ちちは ひげを はやして いる。', 'Bố tôi để râu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13557, 41642, '火が赤々と盛っている。', 'ひが あかあかと さかって いる。', 'Ngọn lửa đang bùng cháy đỏ rực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13558, 41659, '失敗したら、すぐ気持ちを切り替えよう。', 'しっぱい したら、すぐ きもちを きりかえよう。', 'Thất bại thì hãy nhanh chóng chuyển đổi tâm trạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13559, 41665, '後ほど折り返しお電話いたします。', 'のちほど おりかえし おでんわ いたします。', 'Lát nữa tôi sẽ gọi lại cho anh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13560, 41668, '駅にエレベーターが設置された。', 'えきに エレベーターが せっち された。', 'Thang máy đã được lắp đặt ở ga.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13561, 41685, '山が紅葉で赤く染まった。', 'やまが こうようで あかく そまった。', 'Núi nhuộm đỏ bởi lá phong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13562, 41706, '破れた靴下を繕った。', 'やぶれた くつしたを つくろった。', 'Tôi vá chiếc tất bị rách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13563, 41713, '新しい機能をシステムに組み込んだ。', 'あたらしい きのうを システムに くみこんだ。', 'Đã tích hợp chức năng mới vào hệ thống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13564, 41719, 'スプーンでコーヒーを掻き回した。', 'スプーンで コーヒーを かきまわした。', 'Tôi khuấy cà phê bằng thìa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13565, 41927, '窓に風鈴を吊るした。', 'まどに ふうりんを つるした。', 'Tôi treo chuông gió ở cửa sổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13566, 41930, 'なかなか方針が定まらない。', 'なかなか ほうしんが さだまらない。', 'Phương châm mãi vẫn chưa được định ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13567, 41947, '最近、韓国ドラマに填まっている。', 'さいきん、かんこく ドラマに はまって いる。', 'Gần đây tôi đang mê phim Hàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13568, 41987, '途中で仕事を投げ出してはいけない。', 'とちゅうで しごとを なげだしては いけない。', 'Không được bỏ dở công việc giữa chừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13569, 41997, '登山隊は山頂に到達した。', 'とざんたいは さんちょうに とうたつ した。', 'Đội leo núi đã lên tới đỉnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13570, 42002, '檻から猿が逃げ出した。', 'おりから さるが にげだした。', 'Con khỉ đã trốn khỏi chuồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13571, 42004, '彼は責任から逃れようとした。', 'かれは せきにんから のがれようと した。', 'Anh ta tìm cách trốn tránh trách nhiệm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13572, 42034, '鳥が木の実を突いている。', 'とりが きのみを つついて いる。', 'Con chim đang mổ quả cây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13573, 42061, 'ようやくコンサートのチケットを入手した。', 'ようやく コンサートの チケットを にゅうしゅ した。', 'Cuối cùng tôi cũng có được vé hòa nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13574, 42094, '輸送中に商品が破損した。', 'ゆそうちゅうに しょうひんが はそん した。', 'Hàng hóa bị hư hỏng trong lúc vận chuyển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13575, 42098, 'この祭りは今では廃れてしまった。', 'この まつりは いまでは すたれて しまった。', 'Lễ hội này nay đã mai một.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13576, 42117, '壁のポスターを剥がした。', 'かべの ポスターを はがした。', 'Tôi bóc tấm áp phích trên tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13577, 42130, '新しい委員会が四月に発足した。', 'あたらしい いいんかいが しがつに ほっそく した。', 'Ủy ban mới đã ra mắt vào tháng tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13578, 42225, '地震で止まった電車が復旧した。', 'じしんで とまった でんしゃが ふっきゅう した。', 'Tàu điện dừng vì động đất đã hoạt động trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13579, 42239, 'リスクを分散するために投資先を増やした。', 'リスクを ぶんさん する ために とうしさきを ふやした。', 'Để phân tán rủi ro tôi tăng thêm nơi đầu tư.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13580, 42248, '彼の奮闘のおかげで試合に勝った。', 'かれの ふんとうの おかげで しあいに かった。', 'Nhờ sự chiến đấu quả cảm của anh ấy mà đội đã thắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13581, 42282, '大切な書類は金庫に保管している。', 'たいせつな しょるいは きんこに ほかん して いる。', 'Giấy tờ quan trọng được cất trong két.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13582, 42289, '二人は共に人生を歩むことを誓った。', 'ふたりは ともに じんせいを あゆむ ことを ちかった。', 'Hai người thề cùng nhau bước đi trên đường đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13583, 42291, '地震に備えて、家を補強した。', 'じしんに そなえて、いえを ほきょう した。', 'Để phòng động đất, tôi đã gia cố nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13584, 42293, '市から引っ越し費用の補助が出た。', 'しから ひっこし ひようの ほじょが でた。', 'Thành phố đã hỗ trợ chi phí chuyển nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13585, 42348, '壁にスピーカーが埋め込まれている。', 'かべに スピーカーが うめこまれて いる。', 'Loa được gắn chìm trong tường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13586, 42395, '祖父が孫を「大地」と名付けた。', 'そふが まごを 「だいち」と なづけた。', 'Ông đặt tên cho cháu là "Daichi".', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13587, 42403, '恐竜は数千万年前に滅びた。', 'きょうりゅうは すうせんまんねんまえに ほろびた。', 'Khủng long đã diệt vong từ hàng chục triệu năm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13588, 42405, '早く逃げたので、被害を免れた。', 'はやく にげたので、ひがいを まぬかれた。', 'Chạy sớm nên đã tránh được thiệt hại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13589, 42452, '係員が観客を出口へ誘導した。', 'かかりいんが かんきゃくを でぐちへ ゆうどう した。', 'Nhân viên hướng dẫn khán giả ra lối thoát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13590, 42506, '彼はシャツを裏返しに着ていた。', 'かれは シャツを うらがえしに きて いた。', 'Anh ấy mặc áo sơ mi bị lộn trái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13591, 42558, 'この薬は痛みを和らげる。', 'この くすりは いたみを やわらげる。', 'Thuốc này làm dịu cơn đau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13592, 40726, '何気ない一言が人を傷つけることもある。', 'なにげない ひとことが ひとを きずつける ことも ある。', 'Một câu nói vô tình cũng có thể làm tổn thương người khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13593, 40746, '彼は華々しいデビューを飾った。', 'かれは はなばなしい デビューを かざった。', 'Anh ấy đã có màn ra mắt rực rỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13594, 40748, '式には華美な服装は避けてください。', 'しきには かびな ふくそうは さけて ください。', 'Xin tránh trang phục quá xa hoa khi dự lễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13595, 40784, '「パン」はポルトガル語からの外来語だ。', '「パン」は ポルトガルごからの がいらいごだ。', '"Pan" là từ ngoại lai gốc tiếng Bồ Đào Nha.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13596, 40808, 'この子は活発で、いつも外で遊んでいる。', 'この こは かっぱつで、いつも そとで あそんで いる。', 'Đứa trẻ này hiếu động, lúc nào cũng chơi ngoài trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13597, 40833, '書留より簡易な方法で送った。', 'かきとめより かんいな ほうほうで おくった。', 'Tôi gửi bằng cách đơn giản hơn thư bảo đảm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13598, 40856, 'このかばんは頑丈で長持ちする。', 'この かばんは がんじょうで ながもち する。', 'Chiếc túi này chắc chắn và bền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13599, 40952, '政府は強硬な態度をとった。', 'せいふは きょうこうな たいどを とった。', 'Chính phủ đã có thái độ cứng rắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13600, 40995, '参加者の意見はまちまちだった。', 'さんかしゃの いけんは まちまち だった。', 'Ý kiến của những người tham gia mỗi người một kiểu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13601, 41052, '健全な精神は健全な身体に宿る。', 'けんぜんな せいしんは けんぜんな しんたいに やどる。', 'Tinh thần lành mạnh ở trong cơ thể khỏe mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13602, 41063, '負けて言い訳するのは見苦しい。', 'まけて いいわけ するのは みぐるしい。', 'Thua rồi còn biện hộ thì thật khó coi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13603, 41105, 'これは日本固有の文化だ。', 'これは にほん こゆうの ぶんかだ。', 'Đây là nét văn hóa riêng của Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13604, 41129, '二人の関係は公然の秘密だ。', 'ふたりの かんけいは こうぜんの ひみつだ。', 'Quan hệ của hai người là bí mật ai cũng biết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13605, 41138, '子供にとって好ましい環境を作りたい。', 'こどもに とって このましい かんきょうを つくりたい。', 'Tôi muốn tạo một môi trường tốt cho trẻ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13606, 41143, '犯人の手口は非常に巧妙だった。', 'はんにんの てぐちは ひじょうに こうみょう だった。', 'Thủ đoạn của tên tội phạm rất tinh vi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13607, 41376, '辞書を手近な所に置いておく。', 'じしょを てぢかな ところに おいて おく。', 'Tôi để từ điển ở chỗ gần tay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13608, 41426, 'この小さな鍋は一人暮らしに重宝している。', 'この ちいさな なべは ひとりぐらしに ちょうほう して いる。', 'Chiếc nồi nhỏ này rất tiện cho người sống một mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13609, 41524, 'この画家の作品は色彩が豊かだ。', 'この がかの さくひんは しきさいが ゆたかだ。', 'Tác phẩm của họa sĩ này giàu màu sắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13610, 41568, '環境問題は身近な問題だ。', 'かんきょう もんだいは みぢかな もんだいだ。', 'Vấn đề môi trường là vấn đề gần gũi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13611, 41718, '山頂から壮大な景色を眺めた。', 'さんちょうから そうだいな けしきを ながめた。', 'Từ đỉnh núi tôi ngắm cảnh hùng vĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13612, 41723, '早急に対策を考える必要がある。', 'さっきゅうに たいさくを かんがえる ひつようが ある。', 'Cần gấp rút nghĩ ra biện pháp đối phó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13613, 41758, 'この町には多様な文化が共存している。', 'この まちには たような ぶんかが きょうぞん して いる。', 'Ở thành phố này nhiều nền văn hóa cùng tồn tại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13614, 41797, '彼はいつも話が大げさだ。', 'かれは いつも はなしが おおげさだ。', 'Anh ta lúc nào cũng nói phóng đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13615, 41815, 'ヨーロッパの単一通貨はユーロだ。', 'ヨーロッパの たんいつ つうかは ユーロだ。', 'Đồng tiền chung của châu Âu là euro.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13616, 41816, '毎日同じ作業で単調な生活だ。', 'まいにち おなじ さぎょうで たんちょうな せいかつだ。', 'Ngày nào cũng làm một việc, cuộc sống thật đơn điệu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13617, 41848, '年を取って顔の弛みが気になる。', 'としを とって かおの たるみが きに なる。', 'Có tuổi nên tôi để ý chuyện da mặt chảy xệ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13618, 41943, '各自、適宜休憩を取ってください。', 'かくじ、てきぎ きゅうけいを とって ください。', 'Mỗi người hãy tự nghỉ ngơi khi thích hợp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13619, 42020, '彼は堂々と自分の意見を述べた。', 'かれは どうどうと じぶんの いけんを のべた。', 'Anh ấy đường hoàng nêu ý kiến của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13620, 42083, '最後まで諦めない粘りが勝利につながった。', 'さいごまで あきらめない ねばりが しょうりに つながった。', 'Sự bền bỉ không bỏ cuộc đến cùng đã dẫn đến chiến thắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13621, 42136, '中途半端な気持ちでは成功しない。', 'ちゅうと はんぱな きもちでは せいこう しない。', 'Với tâm thế nửa vời thì không thể thành công.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13622, 42161, '遠くから微かに音楽が聞こえる。', 'とおくから かすかに おんがくが きこえる。', 'Từ xa văng vẳng tiếng nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13623, 42191, '不良品は交換いたします。', 'ふりょうひんは こうかん いたします。', 'Hàng lỗi sẽ được đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13624, 42250, '粉末のスープにお湯を注ぐ。', 'ふんまつの スープに おゆを そそぐ。', 'Rót nước nóng vào bột súp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13625, 42263, '連休明けから平常どおり営業します。', 'れんきゅう あけから へいじょう どおり えいぎょう します。', 'Sau kỳ nghỉ dài, chúng tôi hoạt động bình thường trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13626, 42268, '食事が肉に偏らないようにしている。', 'しょくじが にくに かたよらない ように して いる。', 'Tôi cố để bữa ăn không thiên về thịt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13627, 42328, 'できれば早めに来ることが望ましい。', 'できれば はやめに くる ことが のぞましい。', 'Nếu được thì nên đến sớm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13628, 42362, 'この地域はまだ未開の土地が多い。', 'この ちいきは まだ みかいの とちが おおい。', 'Vùng này vẫn còn nhiều đất hoang sơ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13629, 42374, '今さら議論しても無意味だ。', 'いまさら ぎろん しても むいみだ。', 'Bây giờ có tranh luận cũng vô nghĩa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13630, 42383, '台風で庭が無茶苦茶になった。', 'たいふうで にわが むちゃくちゃに なった。', 'Bão làm khu vườn tan hoang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13631, 42387, '心配は無用です。', 'しんぱいは むよう です。', 'Không cần phải lo lắng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13632, 42418, 'この国は目覚しい発展を遂げた。', 'この くには めざましい はってんを とげた。', 'Đất nước này đã phát triển đáng kinh ngạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13633, 41817, '彼は単独で北極点に到達した。', 'かれは たんどくで ほっきょくてんに とうたつ した。', 'Ông ấy một mình đặt chân đến Bắc Cực.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13634, 42437, 'この本は日本語の勉強に役立つ。', 'この ほんは にほんごの べんきょうに やくだつ。', 'Cuốn sách này có ích cho việc học tiếng Nhật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13635, 42223, 'この絵は江戸時代の風俗を描いている。', 'この えは えど じだいの ふうぞくを えがいて いる。', 'Bức tranh này miêu tả phong tục thời Edo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13636, 42447, '有りのままの自分を受け入れたい。', 'ありの ままの じぶんを うけいれたい。', 'Tôi muốn chấp nhận con người thật của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13637, 42449, '彼は将来有望な選手だ。', 'かれは しょうらい ゆうぼうな せんしゅだ。', 'Cậu ấy là vận động viên đầy triển vọng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13638, 42466, '口で言うのは容易いが、実行は難しい。', 'くちで いうのは たやすいが、じっこうは むずかしい。', 'Nói thì dễ, làm mới khó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13639, 42523, '両国の関係は良好だ。', 'りょうこくの かんけいは りょうこうだ。', 'Quan hệ hai nước đang tốt đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13640, 42546, '彼は露骨に不満を表した。', 'かれは ろこつに ふまんを あらわした。', 'Anh ta thể hiện bất mãn một cách lộ liễu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13641, 42588, '舞台の衣装は煌びやかだった。', 'ぶたいの いしょうは きらびやか だった。', 'Trang phục sân khấu thật lộng lẫy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13642, 31816, '彼には彼なりの美学がある。', 'かれには かれなりの びがくが ある。', 'Anh ấy có triết lý thẩm mỹ của riêng mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13643, 31821, 'この漫画は政治を諷刺している。', 'この まんがは せいじを ふうし して いる。', 'Truyện tranh này châm biếm chính trị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13644, 31824, 'この物語には深い寓意が込められている。', 'この ものがたりには ふかい ぐういが こめられて いる。', 'Câu chuyện này chứa đựng ngụ ý sâu xa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13645, 31826, 'この寺は中国の建築様式で建てられた。', 'この てらは ちゅうごくの けんちく ようしきで たてられた。', 'Ngôi chùa này được xây theo phong cách kiến trúc Trung Hoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13646, 31828, '映画界の巨匠が新作を発表した。', 'えいがかいの きょしょうが しんさくを はっぴょう した。', 'Bậc thầy điện ảnh đã công bố tác phẩm mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13647, 31829, 'この小説は彼の最高の傑作だ。', 'この しょうせつは かれの さいこうの けっさくだ。', 'Tiểu thuyết này là kiệt tác xuất sắc nhất của ông ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13648, 31834, '彼の作品は独創性にあふれている。', 'かれの さくひんは どくそうせいに あふれて いる。', 'Tác phẩm của anh ấy tràn đầy tính sáng tạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13649, 40411, 'けがから回復して、彼は見事にカムバックした。', 'けがから かいふく して、かれは みごとに カムバック した。', 'Hồi phục chấn thương, anh ấy đã trở lại ngoạn mục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13650, 40452, 'どんなジャンルの音楽が好きですか。', 'どんな ジャンルの おんがくが すき ですか。', 'Bạn thích thể loại nhạc nào?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13651, 40456, '歌手がスタジオで録音している。', 'かしゅが スタジオで ろくおん して いる。', 'Ca sĩ đang thu âm trong phòng thu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13652, 40478, '彼女はバンドを辞めてソロで活動している。', 'かのじょは バンドを やめて ソロで かつどう して いる。', 'Cô ấy rời ban nhạc và hoạt động solo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13653, 40492, 'あのタレントは毎日テレビに出ている。', 'あの タレントは まいにち テレビに でて いる。', 'Người nổi tiếng đó ngày nào cũng lên ti vi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13654, 40506, '美術の授業で石膏像のデッサンをした。', 'びじゅつの じゅぎょうで せっこうぞうの デッサンを した。', 'Trong giờ mỹ thuật tôi phác họa tượng thạch cao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13655, 40531, '彼はバットを強く振った。', 'かれは バットを つよく ふった。', 'Anh ấy vung gậy thật mạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13656, 40672, '体育館で映画を映写した。', 'たいいくかんで えいがを えいしゃ した。', 'Phim được chiếu trong nhà thể chất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13657, 40702, '横綱が土俵入りをした。', 'よこづなが どひょういりを した。', 'Võ sĩ yokozuna đã làm nghi thức ra sàn đấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13658, 40802, '楽譜を見ながらピアノを弾いた。', 'がくふを みながら ピアノを ひいた。', 'Tôi vừa nhìn bản nhạc vừa chơi piano.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13659, 40837, '観覧車から町が一望できる。', 'かんらんしゃから まちが いちぼう できる。', 'Từ vòng đu quay có thể nhìn bao quát thị trấn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13660, 40862, 'チャップリンの喜劇映画を見た。', 'チャップリンの きげき えいがを みた。', 'Tôi xem phim hài của Chaplin.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13661, 40908, '女の子たちが鞠をついて遊んでいる。', 'おんなのこたちが まりを ついて あそんで いる。', 'Các bé gái đang chơi đập bóng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13662, 40912, 'この映画は小説を脚色したものだ。', 'この えいがは しょうせつを きゃくしょく した ものだ。', 'Bộ phim này được chuyển thể từ tiểu thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13663, 40922, '弓を引いて的を狙った。', 'ゆみを ひいて まとを ねらった。', 'Tôi giương cung nhắm vào đích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13664, 40975, 'これも前世の業なのだろうか。', 'これも ぜんせの ごう なの だろうか。', 'Phải chăng đây cũng là nghiệp từ kiếp trước?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13665, 41000, '運動会の駆けっこで一等になった。', 'うんどうかいの かけっこで いっとうに なった。', 'Tôi về nhất cuộc thi chạy ở hội thao.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13666, 41061, '人の不幸を見せ物にするべきではない。', 'ひとの ふこうを みせものに する べきでは ない。', 'Không nên biến bất hạnh của người khác thành trò xem.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13667, 41134, '彼は好きな歌を口ずさみながら歩いた。', 'かれは すきな うたを くちずさみながら あるいた。', 'Anh ấy vừa đi vừa ngâm nga bài hát yêu thích.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13668, 41181, '祖父は骨董品を集めるのが趣味だ。', 'そふは こっとうひんを あつめるのが しゅみだ。', 'Sở thích của ông tôi là sưu tầm đồ cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13669, 41227, '祖母は三味線を弾くのが上手だ。', 'そぼは しゃみせんを ひくのが じょうずだ。', 'Bà tôi chơi đàn shamisen rất giỏi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13670, 41348, '彼が主演した映画が大ヒットした。', 'かれが しゅえん した えいがが だいヒット した。', 'Bộ phim anh ấy đóng vai chính đã rất ăn khách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13671, 41378, '母は手芸が得意で、よくセーターを編む。', 'ははは しゅげいが とくいで、よく セーターを あむ。', 'Mẹ giỏi thủ công, thường đan áo len.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13672, 41433, '彼女は多くのドラマに出演している。', 'かのじょは おおくの ドラマに しゅつえん して いる。', 'Cô ấy góp mặt trong nhiều bộ phim truyền hình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13673, 41443, '展覧会に絵を出品した。', 'てんらんかいに えを しゅっぴん した。', 'Tôi gửi tranh dự triển lãm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13674, 41462, '新聞の書評を読んで、その本を買った。', 'しんぶんの しょひょうを よんで、その ほんを かった。', 'Đọc bài điểm sách trên báo, tôi đã mua cuốn đó.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13675, 41498, 'その劇は来月から上演される。', 'その げきは らいげつから じょうえん される。', 'Vở kịch đó sẽ công diễn từ tháng sau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13676, 41561, 'ギリシャの古い神殿を訪れた。', 'ギリシャの ふるい しんでんを おとずれた。', 'Tôi đã đến thăm đền thờ cổ ở Hy Lạp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13677, 41689, '潜水艦が海の中を進んでいる。', 'せんすいかんが うみの なかを すすんで いる。', 'Tàu ngầm đang di chuyển dưới biển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13678, 41716, 'この雑誌は創刊五十周年を迎えた。', 'この ざっしは そうかん ごじゅっ しゅうねんを むかえた。', 'Tạp chí này đã tròn năm mươi năm kể từ số đầu tiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13679, 41731, 'クリスマスの装飾で町が明るくなった。', 'クリスマスの そうしょくで まちが あかるく なった。', 'Đồ trang trí Giáng sinh làm thị trấn sáng bừng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13680, 41845, '満員電車は毎朝地獄のようだ。', 'まんいん でんしゃは まいあさ じごくの ようだ。', 'Tàu chật cứng mỗi sáng như địa ngục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13681, 41880, '抽選で旅行券が当たった。', 'ちゅうせんで りょこうけんが あたった。', 'Tôi trúng phiếu du lịch qua rút thăm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13682, 41901, '長編小説を一週間かけて読んだ。', 'ちょうへん しょうせつを いっしゅうかん かけて よんだ。', 'Tôi mất một tuần để đọc cuốn tiểu thuyết dài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13683, 41946, '鬼に金棒というように、彼にその道具を持たせたら最強だ。', 'おにに かなぼうと いう ように、かれに その どうぐを もたせたら さいきょうだ。', 'Như hổ mọc thêm cánh, đưa anh ấy dụng cụ đó thì vô địch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13684, 41964, 'この湖には竜の伝説がある。', 'この みずうみには りゅうの でんせつが ある。', 'Hồ này có truyền thuyết về rồng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13685, 41966, '仏教は六世紀に日本に伝来した。', 'ぶっきょうは ろくせいきに にほんに でんらい した。', 'Phật giáo du nhập vào Nhật vào thế kỷ thứ sáu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13686, 42371, '大学で日本の民俗学を学んだ。', 'だいがくで にほんの みんぞくがくを まなんだ。', 'Tôi học dân tộc học Nhật Bản ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13687, 42445, 'この古い家には幽霊が出るといううわさがある。', 'この ふるい いえには ゆうれいが でると いう うわさが ある。', 'Có tin đồn ngôi nhà cũ này có ma.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13688, 42488, 'ご来場の皆様に申し上げます。', 'ごらいじょうの みなさまに もうしあげます。', 'Xin thông báo tới toàn thể quý vị có mặt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13689, 42550, '生徒が教科書の詩を朗読した。', 'せいとが きょうかしょの しを ろうどく した。', 'Học sinh đọc diễn cảm bài thơ trong sách giáo khoa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13690, 43229, 'クリスマスはイエスの誕生を祝う日だ。', 'クリスマスは イエスの たんじょうを いわう ひだ。', 'Giáng sinh là ngày mừng Chúa Giê-su ra đời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13691, 43235, '放課後、テニスのクラブで練習している。', 'ほうかご、テニスの クラブで れんしゅう して いる。', 'Sau giờ học tôi luyện tập ở câu lạc bộ quần vợt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13692, 43238, '子供たちはサンタクロースが来るのを楽しみにしている。', 'こどもたちは サンタクロースが くるのを たのしみに して いる。', 'Bọn trẻ háo hức chờ Ông già Noel đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13693, 43247, '店内には静かなミュージックが流れていた。', 'てんないには しずかな ミュージックが ながれて いた。', 'Trong quán đang vang lên tiếng nhạc nhẹ nhàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13694, 40397, '会議はオンラインで行われた。', 'かいぎは オンラインで おこなわれた。', 'Cuộc họp được tổ chức trực tuyến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13695, 40431, 'テレビのコマーシャルで新商品を知った。', 'テレビの コマーシャルで しんしょうひんを しった。', 'Tôi biết đến sản phẩm mới qua quảng cáo trên ti vi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13696, 40555, '彼の小説はベストセラーになった。', 'かれの しょうせつは ベストセラーに なった。', 'Tiểu thuyết của anh ấy đã trở thành sách bán chạy nhất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13697, 31819, '大学で日本の詩歌を研究している。', 'だいがくで にほんの しかを けんきゅう して いる。', 'Tôi nghiên cứu thơ ca Nhật Bản ở đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13698, 40422, 'テレビのクイズ番組に出演した。', 'テレビの クイズ ばんぐみに しゅつえん した。', 'Tôi đã tham gia chương trình đố vui trên ti vi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13699, 40543, '今、キャンプがブームになっている。', 'いま、キャンプが ブームに なって いる。', 'Hiện nay cắm trại đang là trào lưu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13700, 40591, '彼はマラソンのレースで優勝した。', 'かれは マラソンの レースで ゆうしょう した。', 'Anh ấy đã vô địch cuộc đua marathon.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13701, 40710, 'このバイオリンは音色が美しい。', 'この バイオリンは ねいろが うつくしい。', 'Cây vĩ cầm này có âm sắc đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13702, 40764, '子供は怪獣の映画が大好きだ。', 'こどもは かいじゅうの えいがが だいすきだ。', 'Trẻ con rất thích phim quái vật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13703, 40820, '完璧な人間なんていない。', 'かんぺきな にんげん なんて いない。', 'Không có ai hoàn hảo cả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13704, 40818, 'この物語は上の巻と下の巻に分かれている。', 'この ものがたりは かみの まきと しもの まきに わかれて いる。', 'Câu chuyện này chia làm quyển thượng và quyển hạ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13705, 40884, '平和への祈りを込めて鐘を鳴らした。', 'へいわへの いのりを こめて かねを ならした。', 'Gióng chuông với lời cầu nguyện cho hòa bình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13706, 40981, '温泉に入ると、極楽の気分だ。', 'おんせんに はいると、ごくらくの きぶんだ。', 'Ngâm suối nước nóng cảm giác như ở cõi cực lạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13707, 41150, '皇居の周りをジョギングする人が多い。', 'こうきょの まわりを ジョギング する ひとが おおい。', 'Nhiều người chạy bộ quanh hoàng cung.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13708, 41209, 'このおもちゃは細工が細かい。', 'この おもちゃは さいくが こまかい。', 'Món đồ chơi này được chế tác tỉ mỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13709, 41326, '祖父母は質素な生活をしている。', 'そふぼは しっそな せいかつを して いる。', 'Ông bà tôi sống giản dị.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13710, 41337, '森の中に古い社がある。', 'もりの なかに ふるい やしろが ある。', 'Trong rừng có một ngôi đền cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13711, 40576, 'ソーシャルメディアで情報を集める人が増えた。', 'ソーシャル メディアで じょうほうを あつめる ひとが ふえた。', 'Số người thu thập thông tin qua mạng xã hội đã tăng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13712, 41590, '高校の吹奏楽部でトランペットを吹いていた。', 'こうこうの すいそうがくぶで トランペットを ふいて いた。', 'Hồi cấp ba tôi thổi kèn trumpet trong câu lạc bộ nhạc hơi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13713, 41628, '検査の結果、すべて正常だった。', 'けんさの けっか、すべて せいじょう だった。', 'Kết quả xét nghiệm đều bình thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13714, 41630, '山から清らかな水が流れてくる。', 'やまから きよらかな みずが ながれて くる。', 'Dòng nước trong vắt chảy xuống từ núi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13715, 41639, '魚をさばいたら、手が生臭くなった。', 'さかなを さばいたら、てが なまぐさく なった。', 'Làm cá xong tay bị tanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13716, 41650, '静的なデータと動的なデータを区別する。', 'せいてきな データと どうてきな データを くべつ する。', 'Phân biệt dữ liệu tĩnh và dữ liệu động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13717, 41676, '彼の音感は先天的なものだ。', 'かれの おんかんは せんてんてきな ものだ。', 'Khả năng cảm âm của anh ấy là bẩm sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13718, 41671, 'その本はもう絶版になっている。', 'その ほんは もう ぜっぱんに なって いる。', 'Cuốn sách đó đã ngừng xuất bản.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13719, 41928, '大晦日に寺の釣鐘を突いた。', 'おおみそかに てらの つりがねを ついた。', 'Đêm giao thừa tôi gióng chuông lớn ở chùa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13720, 41949, 'ここは子供にとって天国のような場所だ。', 'ここは こどもに とって てんごくの ような ばしょだ。', 'Đây là nơi như thiên đường đối với trẻ con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13721, 42011, 'このページは動的に内容が変わる。', 'この ページは どうてきに ないようが かわる。', 'Nội dung trang này thay đổi một cách động.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13722, 42030, 'このチーズには特有の匂いがある。', 'この チーズには とくゆうの においが ある。', 'Loại phô mai này có mùi đặc trưng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13723, 42039, 'しばらく運動しなかったので、体が鈍った。', 'しばらく うんどう しなかったので、からだが なまった。', 'Lâu không vận động nên cơ thể ì ra.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13724, 42024, '後半にチームは三点を得点した。', 'こうはんに チームは さんてんを とくてん した。', 'Trong hiệp hai đội đã ghi được ba điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13725, 42120, 'その主張は根拠が薄弱だ。', 'その しゅちょうは こんきょが はくじゃくだ。', 'Lập luận đó có căn cứ yếu ớt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13726, 42177, 'この国はまだ交通網が貧弱だ。', 'この くには まだ こうつうもうが ひんじゃくだ。', 'Mạng lưới giao thông nước này vẫn còn nghèo nàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13727, 42184, '不在の時は、荷物を隣に預けてください。', 'ふざいの ときは、にもつを となりに あずけて ください。', 'Khi vắng nhà xin hãy gửi hàng cho nhà bên cạnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13728, 42186, 'エンジンの不調で車が止まった。', 'エンジンの ふちょうで くるまが とまった。', 'Động cơ trục trặc nên xe dừng lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13729, 42297, 'お盆に家族で墓地へお参りに行った。', 'おぼんに かぞくで ぼちへ おまいりに いった。', 'Dịp Obon cả nhà đi viếng nghĩa trang.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13730, 42336, '牧師が結婚式で二人を祝福した。', 'ぼくしが けっこんしきで ふたりを しゅくふく した。', 'Mục sư chúc phúc cho đôi uyên ương trong lễ cưới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13731, 42343, 'メールの本文に用件を書いてください。', 'メールの ほんぶんに ようけんを かいて ください。', 'Hãy viết nội dung công việc vào phần thân email.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13732, 42365, '彼女は密かに彼を愛していた。', 'かのじょは ひそかに かれを あいして いた。', 'Cô ấy thầm yêu anh ấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13733, 42460, '忘年会の余興で歌を歌った。', 'ぼうねんかいの よきょうで うたを うたった。', 'Tôi hát một bài trong tiết mục giải trí ở tiệc tất niên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13734, 42515, '今年の流行の色は緑だ。', 'ことしの はやりの いろは みどりだ。', 'Màu thịnh hành năm nay là xanh lá.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13735, 40498, 'テレビのチャンネルを変えてもいいですか。', 'テレビの チャンネルを かえても いい ですか。', 'Tôi chuyển kênh ti vi được không?', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13736, 40516, '祖父は古いトランジスターラジオを大切にしている。', 'そふは ふるい トランジスター ラジオを たいせつに して いる。', 'Ông tôi nâng niu chiếc đài bán dẫn cũ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13737, 40579, 'パソコンのモニターを大きいものに替えた。', 'パソコンの モニターを おおきい ものに かえた。', 'Tôi đổi màn hình máy tính sang loại lớn hơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13738, 41093, '旅行の写真を現像に出した。', 'りょこうの しゃしんを げんぞうに だした。', 'Tôi mang ảnh du lịch đi tráng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13739, 41721, '彼は飛行機を操縦する資格を持っている。', 'かれは ひこうきを そうじゅう する しかくを もって いる。', 'Anh ấy có bằng lái máy bay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13740, 41870, 'サッカーの試合をテレビで生中継している。', 'サッカーの しあいを テレビで なまちゅうけい して いる。', 'Trận bóng đá đang được truyền hình trực tiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13741, 42012, 'この船は電気を動力にしている。', 'この ふねは でんきを どうりょくに して いる。', 'Con tàu này chạy bằng động lực điện.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13742, 42018, '写真を同封して手紙を送った。', 'しゃしんを どうふう して てがみを おくった。', 'Tôi gửi thư kèm theo ảnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13743, 31735, '彼には潜在的な能力がある。', 'かれには せんざいてきな のうりょくが ある。', 'Anh ấy có năng lực tiềm ẩn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13744, 31796, '戦後、多くの名家が没落した。', 'せんご、おおくの めいかが ぼつらく した。', 'Sau chiến tranh, nhiều gia tộc danh giá đã sa sút.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13745, 31797, 'ローマ帝国の興亡の歴史を学んだ。', 'ローマ ていこくの こうぼうの れきしを まなんだ。', 'Tôi học lịch sử thịnh suy của Đế quốc La Mã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13746, 31799, '新しい産業が勃興している。', 'あたらしい さんぎょうが ぼっこう して いる。', 'Các ngành công nghiệp mới đang trỗi dậy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13747, 31800, '当時、仏教は隆盛を極めていた。', 'とうじ、ぶっきょうは りゅうせいを きわめて いた。', 'Thời đó Phật giáo đạt đến đỉnh cao hưng thịnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13748, 31802, '彼女はついに芸能界の頂点に立った。', 'かのじょは ついに げいのうかいの ちょうてんに たった。', 'Cuối cùng cô ấy đã đứng trên đỉnh cao của làng giải trí.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13749, 31804, '彼はスキャンダルで一気に転落した。', 'かれは スキャンダルで いっきに てんらく した。', 'Vì vụ bê bối, anh ta sa sút chỉ trong chớp mắt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13750, 31806, '内部の対立で組織は瓦解した。', 'ないぶの たいりつで そしきは がかい した。', 'Do mâu thuẫn nội bộ, tổ chức đã tan rã.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13751, 31807, '昔の人気商品が復活した。', 'むかしの にんき しょうひんが ふっかつ した。', 'Sản phẩm ăn khách ngày xưa đã trở lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13752, 31810, '彼は家業の再興に力を尽くした。', 'かれは かぎょうの さいこうに ちからを つくした。', 'Anh ấy dốc sức phục hưng nghề gia truyền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13753, 37871, 'それは常識から逸脱した行動だ。', 'それは じょうしきから いつだつ した こうどうだ。', 'Đó là hành vi lệch khỏi lẽ thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13754, 37876, '寝不足とストレスの悪循環に陥った。', 'ねぶそくと ストレスの あくじゅんかんに おちいった。', 'Tôi rơi vào vòng luẩn quẩn thiếu ngủ và căng thẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13755, 37878, 'この車にはブレーキの欠陥があった。', 'この くるまには ブレーキの けっかんが あった。', 'Chiếc xe này có khiếm khuyết ở phanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13756, 37880, '事故は運転手の過失によるものだった。', 'じこは うんてんしゅの かしつに よる もの だった。', 'Vụ tai nạn là do sơ suất của tài xế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13757, 37888, '景気回復の兆候が見え始めた。', 'けいき かいふくの ちょうこうが みえ はじめた。', 'Đã bắt đầu thấy dấu hiệu phục hồi kinh tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13758, 37892, '事件の発端は小さな口論だった。', 'じけんの ほったんは ちいさな こうろん だった。', 'Khởi đầu của vụ việc chỉ là một cuộc cãi vã nhỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13759, 37898, 'この坂は傾斜が急だ。', 'この さかは けいしゃが きゅうだ。', 'Con dốc này có độ nghiêng lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13760, 37900, '家の土台がしっかりしている。', 'いえの どだいが しっかり して いる。', 'Nền móng ngôi nhà vững chắc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13761, 38238, 'この提携は海外進出への布石だ。', 'この ていけいは かいがい しんしゅつへの ふせきだ。', 'Sự hợp tác này là bước đệm để vươn ra nước ngoài.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13762, 38241, '警察は犯人の手掛かりを探している。', 'けいさつは はんにんの てがかりを さがして いる。', 'Cảnh sát đang tìm manh mối về thủ phạm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13763, 38242, 'この発見が研究の突破口となった。', 'この はっけんが けんきゅうの とっぱこうと なった。', 'Phát hiện này đã trở thành bước đột phá cho nghiên cứu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13764, 38276, '彼の話は論理が飛躍している。', 'かれの はなしは ろんりが ひやく して いる。', 'Câu chuyện của anh ta có lập luận nhảy cóc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13765, 38278, '江戸時代には町人文化が興隆した。', 'えど じだいには ちょうにん ぶんかが こうりゅう した。', 'Thời Edo, văn hóa thị dân hưng thịnh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13766, 38280, 'この本は古代文明の衰亡を描いている。', 'この ほんは こだい ぶんめいの すいぼうを えがいて いる。', 'Cuốn sách này miêu tả sự suy vong của nền văn minh cổ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13767, 38281, '恐竜の滅亡には諸説ある。', 'きょうりゅうの めつぼうには しょせつ ある。', 'Có nhiều giả thuyết về sự diệt vong của khủng long.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13768, 38289, '彼女は波乱に満ちた人生を送った。', 'かのじょは はらんに みちた じんせいを おくった。', 'Bà ấy đã sống một cuộc đời đầy sóng gió.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13769, 38302, '震災の記憶を風化させてはいけない。', 'しんさいの きおくを ふうか させては いけない。', 'Không được để ký ức về thảm họa động đất phai nhạt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13770, 38304, 'その規則はすでに形骸化している。', 'その きそくは すでに けいがいか して いる。', 'Quy tắc đó đã trở thành hình thức suông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13771, 40470, '二人の考えにはずれがある。', 'ふたりの かんがえには ずれが ある。', 'Suy nghĩ của hai người có độ vênh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13772, 40465, '部屋に机を置くスペースがない。', 'へやに つくえを おく スペースが ない。', 'Trong phòng không có chỗ để đặt bàn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13773, 40515, '機械のトラブルで電車が遅れた。', 'きかいの トラブルで でんしゃが おくれた。', 'Tàu bị trễ do sự cố máy móc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13774, 40557, '説明のポイントを三つにまとめた。', 'せつめいの ポイントを みっつに まとめた。', 'Tôi tóm ý chính của phần giải thích thành ba điểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13775, 40592, '彼はついにチームのレギュラーになった。', 'かれは ついに チームの レギュラーに なった。', 'Cuối cùng anh ấy đã trở thành cầu thủ chính thức của đội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13776, 40674, 'この港町は昔、貿易で栄えた。', 'この みなとまちは むかし、ぼうえきで さかえた。', 'Thị trấn cảng này xưa kia phồn thịnh nhờ buôn bán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13777, 40861, 'この犬は人に危害を加えない。', 'この いぬは ひとに きがいを くわえない。', 'Con chó này không làm hại người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13778, 40895, '彼は感情の起伏が激しい。', 'かれは かんじょうの きふくが はげしい。', 'Cảm xúc của anh ta lên xuống thất thường.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13779, 40901, '戦争で多くの人が犠牲になった。', 'せんそうで おおくの ひとが ぎせいに なった。', 'Nhiều người đã hy sinh trong chiến tranh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13780, 40913, '最後の一分で逆転勝ちした。', 'さいごの いっぷんで ぎゃくてん がち した。', 'Đội đã lội ngược dòng chiến thắng ở phút cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13781, 40942, '人間と自然の共存を考える。', 'にんげんと しぜんの きょうそんを かんがえる。', 'Suy nghĩ về sự cùng tồn tại giữa con người và tự nhiên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13782, 40998, '仕事に一区切りついたので、休憩しよう。', 'しごとに ひとくぎり ついたので、きゅうけい しよう。', 'Công việc đã xong một giai đoạn, nghỉ chút đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13783, 41017, '働き方の形態が多様化している。', 'はたらきかたの けいたいが たようか して いる。', 'Hình thức làm việc đang ngày càng đa dạng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13784, 41022, '事件の経緯を詳しく説明してください。', 'じけんの いきさつを くわしく せつめい して ください。', 'Hãy giải thích chi tiết đầu đuôi vụ việc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13785, 41049, '件の男がまた店に来た。', 'くだんの おとこが また みせに きた。', 'Gã đàn ông đã nói lúc trước lại đến cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13786, 41084, '事故で車は原形をとどめていなかった。', 'じこで くるまは げんけいを とどめて いなかった。', 'Sau tai nạn, chiếc xe không còn giữ được hình dạng ban đầu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13787, 41170, '彼の考えは会社の方針と合致している。', 'かれの かんがえは かいしゃの ほうしんと がっち して いる。', 'Suy nghĩ của anh ấy trùng khớp với phương châm công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13788, 41186, 'この問題の根底には貧困がある。', 'この もんだいの こんていには ひんこんが ある。', 'Gốc rễ của vấn đề này là nghèo đói.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13789, 41215, 'この家は作りがしっかりしている。', 'この いえは つくりが しっかり して いる。', 'Ngôi nhà này được xây chắc chắn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13790, 41293, '注意事項をよく読んでください。', 'ちゅうい じこうを よく よんで ください。', 'Hãy đọc kỹ các điều cần lưu ý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13791, 41299, 'この電池は持ちがいい。', 'この でんちは もちが いい。', 'Cục pin này dùng được lâu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13792, 41327, '実を言うと、まだ何も準備していない。', 'じつを いうと、まだ なにも じゅんび して いない。', 'Nói thật là tôi vẫn chưa chuẩn bị gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13793, 41330, '現地の実情を調べる必要がある。', 'げんちの じつじょうを しらべる ひつようが ある。', 'Cần tìm hiểu tình hình thực tế tại chỗ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13794, 41353, 'この小説の主題は家族の愛だ。', 'この しょうせつの しゅだいは かぞくの あいだ。', 'Chủ đề của tiểu thuyết này là tình yêu gia đình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13795, 41380, '彼女は手際よく料理を作った。', 'かのじょは てぎわ よく りょうりを つくった。', 'Cô ấy nấu ăn rất khéo léo nhanh gọn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13796, 41383, 'お手数をおかけしますが、よろしくお願いします。', 'おてすうを おかけ しますが、よろしく おねがい します。', 'Xin lỗi đã làm phiền anh, mong anh giúp đỡ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13797, 41458, '所定の用紙に記入してください。', 'しょていの ようしに きにゅう して ください。', 'Hãy điền vào mẫu giấy đã quy định.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13798, 41466, '友達の助けを借りて引っ越した。', 'ともだちの たすけを かりて ひっこした。', 'Tôi chuyển nhà nhờ sự giúp đỡ của bạn bè.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13799, 41473, 'チームは大勝利を収めた。', 'チームは だいしょうりを おさめた。', 'Đội đã giành chiến thắng vang dội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13800, 41499, 'この本、上下逆さまですよ。', 'この ほん、うえした さかさま ですよ。', 'Cuốn sách này bị lộn ngược trên dưới đấy.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13801, 41513, '中東の情勢が緊迫している。', 'ちゅうとうの じょうせいが きんぱく して いる。', 'Tình hình Trung Đông đang căng thẳng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13802, 41550, 'この部屋は広さも値段も申し分ない。', 'この へやは ひろさも ねだんも もうしぶん ない。', 'Căn phòng này cả diện tích lẫn giá cả đều không chê vào đâu được.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13803, 41562, '生命の神秘に驚かされる。', 'せいめいの しんぴに おどろかされる。', 'Tôi kinh ngạc trước sự huyền bí của sự sống.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13804, 41575, '交渉に進展が見られた。', 'こうしょうに しんてんが みられた。', 'Cuộc đàm phán đã có tiến triển.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13805, 41614, '時間の制約があるので、手短に話します。', 'じかんの せいやくが あるので、てみじかに はなします。', 'Vì có giới hạn thời gian nên tôi xin nói ngắn gọn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13806, 41632, '彼は清濁併せ呑む度量のある人だ。', 'かれは せいだく あわせのむ どりょうの ある ひとだ。', 'Ông ấy là người có lòng bao dung, chấp nhận cả tốt lẫn xấu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13807, 41666, 'この家は和洋折衷の造りだ。', 'この いえは わよう せっちゅうの つくりだ。', 'Ngôi nhà này được xây theo lối kết hợp Nhật - Tây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13808, 41727, '売り手と買い手が相対で取引した。', 'うりてと かいてが あいたいで とりひき した。', 'Người bán và người mua giao dịch trực tiếp với nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13809, 41743, '現実に即した計画を立てるべきだ。', 'げんじつに そくした けいかくを たてる べきだ。', 'Nên lập kế hoạch phù hợp với thực tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13810, 41751, '赤字続きで会社の存続が危ぶまれている。', 'あかじ つづきで かいしゃの そんぞくが あやぶまれて いる。', 'Thua lỗ liên tục khiến sự tồn tại của công ty bị đe dọa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13811, 41767, '彼は困った体で頭をかいた。', 'かれは こまった ていで あたまを かいた。', 'Anh ta gãi đầu với vẻ bối rối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13812, 41785, '救急車が二十四時間の態勢で待機している。', 'きゅうきゅうしゃが にじゅうよじかんの たいせいで たいき して いる。', 'Xe cấp cứu luôn trực sẵn sàng 24 giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13813, 41802, '早く手当てしないと大事になる。', 'はやく てあて しないと おおごとに なる。', 'Không chữa trị sớm thì sẽ thành chuyện lớn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13814, 41840, 'この本は読む値打ちがある。', 'この ほんは よむ ねうちが ある。', 'Cuốn sách này đáng đọc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13815, 41872, '電車の中程までお進みください。', 'でんしゃの なかほどまで おすすみ ください。', 'Xin mời đi vào khoảng giữa toa tàu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13816, 41890, '彼は新しいことに挑戦するのが好きだ。', 'かれは あたらしい ことに ちょうせん するのが すきだ。', 'Anh ấy thích thử thách những điều mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13817, 41944, '就職の前に適性検査を受けた。', 'しゅうしょくの まえに てきせい けんさを うけた。', 'Trước khi đi làm tôi đã làm bài kiểm tra năng khiếu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13818, 41955, 'このクラスはまとまりがいい。', 'この クラスは まとまりが いい。', 'Lớp này rất đoàn kết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13819, 42160, '彼にはリーダーの資質が備わっている。', 'かれには リーダーの ししつが そなわって いる。', 'Anh ấy có sẵn tố chất của người lãnh đạo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13820, 42168, '彼の実力はプロに匹敵する。', 'かれの じつりょくは プロに ひってき する。', 'Thực lực của anh ấy sánh ngang dân chuyên nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13821, 42194, '大学の付属病院で働いている。', 'だいがくの ふぞく びょういんで はたらいて いる。', 'Tôi làm việc ở bệnh viện trực thuộc đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13930, 42457, '予めご了承ください。', 'あらかじめ ごりょうしょう ください。', 'Xin quý khách thông cảm trước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13822, 42276, '便宜上、Ａ班とＢ班に分けます。', 'べんぎじょう、エーはんと ビーはんに わけます。', 'Để tiện, chúng ta chia thành nhóm A và nhóm B.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13823, 42323, '彼は仕事の傍ら、小説を書いている。', 'かれは しごとの かたわら、しょうせつを かいて いる。', 'Bên cạnh công việc, anh ấy còn viết tiểu thuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13824, 42329, '会議の冒頭で社長が挨拶した。', 'かいぎの ぼうとうで しゃちょうが あいさつ した。', 'Giám đốc phát biểu chào mừng ở phần mở đầu cuộc họp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13825, 42413, '彼は生徒の模範となる行動をとった。', 'かれは せいとの もはんと なる こうどうを とった。', 'Cậu ấy hành động làm gương cho học sinh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13826, 42440, '経験の多い彼のほうが優位に立っている。', 'けいけんの おおい かれの ほうが ゆういに たって いる。', 'Anh ấy giàu kinh nghiệm hơn nên đang chiếm ưu thế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13827, 42441, '彼は優越感に浸っていた。', 'かれは ゆうえつかんに ひたって いた。', 'Anh ta đắm chìm trong cảm giác hơn người.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13828, 42446, '国民は選挙権を有する。', 'こくみんは せんきょけんを ゆうする。', 'Công dân có quyền bầu cử.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13829, 42470, '事件は新たな様相を呈してきた。', 'じけんは あらたな ようそうを ていして きた。', 'Vụ án đã mang một diện mạo mới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13830, 37848, '彼は時代の風潮に乗って成功した。', 'かれは じだいの ふうちょうに のって せいこう した。', 'Anh ấy thành công nhờ theo kịp trào lưu thời đại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13831, 38246, '窮余の策として、家を売ることにした。', 'きゅうよの さくと して、いえを うる ことに した。', 'Như một kế cùng đường, tôi quyết định bán nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13832, 38269, '彼女は几帳面な性格で、部屋がいつもきれいだ。', 'かのじょは きちょうめんな せいかくで、へやが いつも きれいだ。', 'Cô ấy tính tỉ mỉ nên phòng lúc nào cũng sạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13833, 38274, 'あの店長は融通が利くので、頼みやすい。', 'あの てんちょうは ゆうずうが きくので、たのみやすい。', 'Ông chủ quán đó linh hoạt nên dễ nhờ vả.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13834, 40469, '返事をずるずると先延ばしにしている。', 'へんじを ずるずると さきのばしに して いる。', 'Tôi cứ dây dưa trì hoãn việc trả lời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13835, 40505, 'てっきり彼が来ると思っていた。', 'てっきり かれが くると おもって いた。', 'Tôi cứ đinh ninh là anh ấy sẽ đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13836, 40518, 'とんだ目に遭った。', 'とんだ めに あった。', 'Tôi gặp phải chuyện khủng khiếp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13837, 40523, 'なんだかんだ言っても、彼はいい人だ。', 'なんだかんだ いっても、かれは いい ひとだ。', 'Nói gì thì nói, anh ấy vẫn là người tốt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13838, 40537, '走ったので、汗びっしょりになった。', 'はしったので、あせ びっしょりに なった。', 'Chạy xong người tôi đẫm mồ hôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13839, 40563, 'ぼつぼつ帰りましょうか。', 'ぼつぼつ かえりましょうか。', 'Chúng ta dần về thôi nhỉ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13840, 40580, '台風の影響をもろに受けた。', 'たいふうの えいきょうを もろに うけた。', 'Chịu ảnh hưởng trực diện của cơn bão.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13841, 40682, '個人の努力が、延いては社会全体を豊かにする。', 'こじんの どりょくが、ひいては しゃかい ぜんたいを ゆたかに する。', 'Nỗ lực cá nhân, rộng hơn nữa, sẽ làm giàu cho cả xã hội.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13842, 40695, '会議は本社に於いて行われる。', 'かいぎは ほんしゃに おいて おこなわれる。', 'Cuộc họp sẽ được tổ chức tại trụ sở chính.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13843, 40724, '何なりとお申し付けください。', 'なんなりと おもうしつけ ください。', 'Xin cứ sai bảo bất cứ điều gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13844, 40725, 'お元気そうで何よりです。', 'おげんき そうで なにより です。', 'Thấy anh khỏe mạnh là tốt hơn hết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13845, 40847, '丸々と太った赤ちゃんが笑っている。', 'まるまると ふとった あかちゃんが わらって いる。', 'Em bé mũm mĩm đang cười.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13846, 40849, '私は料理が丸っきりできない。', 'わたしは りょうりが まるっきり できない。', 'Tôi hoàn toàn không biết nấu ăn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13847, 40919, '住所及び電話番号を記入してください。', 'じゅうしょ および でんわ ばんごうを きにゅう して ください。', 'Hãy ghi địa chỉ và số điện thoại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13848, 40966, '大人でも難しいのに、況して子供には無理だ。', 'おとなでも むずかしいのに、まして こどもには むりだ。', 'Người lớn còn khó, huống hồ là trẻ con.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13849, 41081, '彼は元来おとなしい性格だ。', 'かれは がんらい おとなしい せいかくだ。', 'Vốn dĩ anh ấy có tính hiền lành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13850, 41114, '窓の外を御覧なさい。きれいな虹ですよ。', 'まどの そとを ごらんなさい。きれいな にじ ですよ。', 'Hãy nhìn ra ngoài cửa sổ đi. Cầu vồng đẹp lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13851, 41189, '今日は左程寒くない。', 'きょうは さほど さむく ない。', 'Hôm nay không lạnh lắm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13852, 41291, '事によると、明日は雪になるかもしれない。', 'ことに よると、あしたは ゆきに なるかも しれない。', 'Không chừng ngày mai sẽ có tuyết.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13853, 41308, '努力すれば、結果は自ずからついてくる。', 'どりょく すれば、けっかは おのずから ついて くる。', 'Nếu nỗ lực thì kết quả tự nhiên sẽ đến.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13854, 41344, '参加者は百人弱だった。', 'さんかしゃは ひゃくにん じゃく だった。', 'Người tham gia chưa đến một trăm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13855, 41463, '諸問題について話し合った。', 'しょもんだいに ついて はなしあった。', 'Chúng tôi đã thảo luận về các vấn đề.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13856, 41570, '辛うじて最終電車に間に合った。', 'かろうじて さいしゅう でんしゃに まにあった。', 'Chật vật lắm tôi mới kịp chuyến tàu cuối.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13857, 41617, '成る丈早く来てください。', 'なるたけ はやく きて ください。', 'Hãy đến sớm nhất có thể.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13858, 41680, '休日は専ら読書をして過ごす。', 'きゅうじつは もっぱら どくしょを して すごす。', 'Ngày nghỉ tôi chủ yếu đọc sách.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13859, 41702, '努力した。然しながら、結果は出なかった。', 'どりょく した。しかしながら、けっかは でなかった。', 'Tôi đã nỗ lực. Tuy nhiên, kết quả vẫn không có.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13860, 41744, '彼は質問に即座に答えた。', 'かれは しつもんに そくざに こたえた。', 'Anh ấy trả lời câu hỏi ngay lập tức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13861, 41748, '彼は正直だ。其れ故、みんなに信頼されている。', 'かれは しょうじきだ。それゆえ、みんなに しんらい されて いる。', 'Anh ấy trung thực. Vì vậy được mọi người tin tưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13862, 41853, '遅くとも五時までには帰ります。', 'おそくとも ごじまでには かえります。', 'Chậm nhất là năm giờ tôi sẽ về.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13863, 41948, '古事記には天つ神が登場する。', 'こじきには あまつかみが とうじょう する。', 'Trong Cổ sự ký có xuất hiện các vị thần trời.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13864, 41971, '人は兎角楽なほうを選びがちだ。', 'ひとは とかく らくな ほうを えらびがちだ。', 'Con người hay có xu hướng chọn đường dễ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13865, 42084, '完成までに三年乃至五年かかる。', 'かんせいまでに さんねん ないし ごねん かかる。', 'Để hoàn thành cần từ ba đến năm năm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13866, 42146, '左から三番目の人が私の兄です。', 'ひだりから さんばんめの ひとが わたしの あに です。', 'Người thứ ba từ trái sang là anh trai tôi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13867, 42469, '田中様、お待ちしておりました。', 'たなかさま、おまち して おりました。', 'Thưa ông Tanaka, chúng tôi đã chờ ông.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13868, 42487, '来る十月十日に運動会を行います。', 'きたる じゅうがつ とおかに うんどうかいを おこないます。', 'Hội thao sẽ được tổ chức vào ngày 10 tháng 10 sắp tới.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13869, 42592, '忙しくて碌に寝ていない。', 'いそがしくて ろくに ねて いない。', 'Bận quá nên tôi chẳng ngủ được tử tế.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13870, 43231, '社長からオーケーが出た。', 'しゃちょうから オーケーが でた。', 'Giám đốc đã đồng ý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13871, 43243, '駅前にニューオープンのレストランがある。', 'えきまえに ニュー オープンの レストランが ある。', 'Trước ga có nhà hàng mới khai trương.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13872, 31758, '夢と現実は違う。', 'ゆめと げんじつは ちがう。', 'Giấc mơ và hiện thực khác nhau.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13873, 31793, '改革は漸進的に進めるべきだ。', 'かいかくは ぜんしんてきに すすめる べきだ。', 'Cải cách nên được tiến hành từng bước.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13874, 31795, '少子化で地方の産業が衰退している。', 'しょうしかで ちほうの さんぎょうが すいたい して いる。', 'Do ít con, ngành nghề địa phương đang suy thoái.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13875, 38217, '計画の見直しが必要だ。', 'けいかくの みなおしが ひつようだ。', 'Cần xem xét lại kế hoạch.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13876, 38224, 'この資格は大学卒業に準ずるものとして扱われる。', 'この しかくは だいがく そつぎょうに じゅんずる ものと して あつかわれる。', 'Chứng chỉ này được coi là tương đương tốt nghiệp đại học.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13877, 38228, '今回の事故で管理体制の甘さが露呈した。', 'こんかいの じこで かんり たいせいの あまさが ろてい した。', 'Vụ tai nạn lần này đã phơi bày sự lỏng lẻo trong quản lý.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13878, 38272, '友人にお金を融通してもらった。', 'ゆうじんに おかねを ゆうずう して もらった。', 'Tôi được bạn xoay giúp tiền.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13879, 38275, '新人の活躍でチームは大躍進した。', 'しんじんの かつやくで チームは だいやくしん した。', 'Nhờ người mới tỏa sáng, đội đã tiến bộ vượt bậc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13880, 38305, '工場の海外移転で産業の空洞化が進んだ。', 'こうじょうの かいがい いてんで さんぎょうの くうどうかが すすんだ。', 'Việc chuyển nhà máy ra nước ngoài khiến công nghiệp trong nước bị rỗng hóa.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13881, 38307, '教育の画一化が批判されている。', 'きょういくの かくいつかが ひはん されて いる。', 'Sự rập khuôn hóa trong giáo dục đang bị phê phán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13882, 38309, '学習内容の個別化が求められている。', 'がくしゅう ないようの こべつかが もとめられて いる。', 'Cần cá thể hóa nội dung học tập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13883, 38313, '手続きの簡素化を進める。', 'てつづきの かんそかを すすめる。', 'Đẩy mạnh đơn giản hóa thủ tục.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13884, 38315, '集めた知識を体系化した。', 'あつめた ちしきを たいけいか した。', 'Tôi hệ thống hóa những kiến thức đã thu thập.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13885, 40374, 'この問題には別のアプローチが必要だ。', 'この もんだいには べつの アプローチが ひつようだ。', 'Vấn đề này cần một cách tiếp cận khác.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13886, 40384, 'こんなに疲れるなら、いっそ辞めてしまおうか。', 'こんなに つかれるなら、いっそ やめて しまおうか。', 'Mệt thế này thì thà nghỉ việc luôn cho xong.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13887, 40721, '何だか悲しくなってきた。', 'なんだか かなしく なって きた。', 'Không hiểu sao tôi thấy buồn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13888, 40391, '毎日同じ話を聞かされて、うんざりした。', 'まいにち おなじ はなしを きかされて、うんざり した。', 'Ngày nào cũng phải nghe cùng một chuyện nên tôi phát ngán.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13889, 40407, '不合格の知らせにがっくりした。', 'ふごうかくの しらせに がっくり した。', 'Nhận tin trượt, tôi suy sụp hẳn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13890, 40417, '会議は三時きっかりに始まった。', 'かいぎは さんじ きっかりに はじまった。', 'Cuộc họp bắt đầu đúng ba giờ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13891, 40418, '借りたお金はきっちり返した。', 'かりた おかねは きっちり かえした。', 'Tiền mượn tôi đã trả đủ không thiếu đồng nào.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13892, 40423, '今日は富士山がくっきり見える。', 'きょうは ふじさんが くっきり みえる。', 'Hôm nay núi Phú Sĩ hiện lên rõ nét.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13893, 40428, '病気で一週間寝込んで、げっそり痩せた。', 'びょうきで いっしゅうかん ねこんで、げっそり やせた。', 'Ốm nằm liệt một tuần nên tôi gầy rộc đi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13894, 40439, '野菜をさっとゆでる。', 'やさいを さっと ゆでる。', 'Trần rau qua nước sôi thật nhanh.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13895, 40448, 'しまった、財布を家に忘れた。', 'しまった、さいふを いえに わすれた。', 'Chết rồi, tôi để quên ví ở nhà.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13896, 40468, '店の前に客がずらっと並んでいる。', 'みせの まえに きゃくが ずらっと ならんで いる。', 'Khách xếp hàng dài trước cửa hàng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13897, 40489, '兄のシャツは私にはだぶだぶだ。', 'あにの シャツは わたしには だぶだぶだ。', 'Áo của anh trai mặc vào tôi rộng thùng thình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13898, 40491, '子供たちは泥だらけになって遊んだ。', 'こどもたちは どろだらけに なって あそんだ。', 'Bọn trẻ chơi đùa đến lấm lem bùn đất.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13899, 40499, 'この店にはちょくちょく来ます。', 'この みせには ちょくちょく きます。', 'Tôi thường ghé quán này.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13900, 40509, '彼の話はてんで分からなかった。', 'かれの はなしは てんで わからなかった。', 'Tôi hoàn toàn không hiểu anh ta nói gì.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13901, 40545, '彼は投げるフォームがきれいだ。', 'かれは なげる フォームが きれいだ。', 'Tư thế ném bóng của anh ấy rất đẹp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13902, 40546, '父の靴は私にはぶかぶかだ。', 'ちちの くつは わたしには ぶかぶかだ。', 'Giày của bố tôi đi vào rộng thùng thình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13903, 40553, '朝から何も食べていないので、お腹がぺこぺこだ。', 'あさから なにも たべて いないので、おなかが ぺこぺこだ。', 'Từ sáng chưa ăn gì nên bụng đói meo.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13904, 40567, 'ポンプで井戸の水をくみ上げる。', 'ポンプで いどの みずを くみあげる。', 'Dùng máy bơm hút nước giếng lên.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13905, 40569, 'その事件はマスコミで大きく報道された。', 'その じけんは マスコミで おおきく ほうどう された。', 'Vụ việc đó được truyền thông đưa tin rầm rộ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13906, 40583, 'もう少し時間にゆとりを持って出かけよう。', 'もう すこし じかんに ゆとりを もって でかけよう。', 'Hãy ra khỏi nhà sớm hơn để dư dả thời gian.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13907, 40600, 'この電球は六十ワットだ。', 'この でんきゅうは ろくじゅう ワットだ。', 'Bóng đèn này là 60 oát.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13908, 40606, '政府は企業に圧力をかけた。', 'せいふは きぎょうに あつりょくを かけた。', 'Chính phủ đã gây áp lực lên doanh nghiệp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13909, 40616, '本日を以て閉店いたします。', 'ほんじつを もって へいてん いたします。', 'Cửa hàng xin đóng cửa kể từ hôm nay.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13910, 40618, '日本は石油の大部分を輸入に依存している。', 'にほんは せきゆの だいぶぶんを ゆにゅうに いそん して いる。', 'Nhật Bản phụ thuộc phần lớn dầu mỏ vào nhập khẩu.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13911, 40617, '以上の理由に依って、計画を中止する。', 'いじょうの りゆうに よって、けいかくを ちゅうし する。', 'Vì những lý do trên, kế hoạch bị hủy bỏ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13912, 40636, '新しい道路で渋滞が一挙に解消した。', 'あたらしい どうろで じゅうたいが いっきょに かいしょう した。', 'Nhờ con đường mới, tình trạng tắc đường được giải quyết ngay lập tức.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13913, 40714, '彼女には音楽の下地がある。', 'かのじょには おんがくの したじが ある。', 'Cô ấy có nền tảng âm nhạc.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13914, 40770, '品種を改良して甘いいちごを作った。', 'ひんしゅを かいりょう して あまい いちごを つくった。', 'Cải tạo giống để tạo ra dâu ngọt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13915, 40980, 'これは極めて珍しい現象だ。', 'これは きわめて めずらしい げんしょうだ。', 'Đây là hiện tượng cực kỳ hiếm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13916, 41038, '手紙の結びに感謝の言葉を書いた。', 'てがみの むすびに かんしゃの ことばを かいた。', 'Ở phần kết thư tôi viết lời cảm ơn.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13917, 41091, 'この川の源は富士山だ。', 'この かわの みなもとは ふじさんだ。', 'Cội nguồn con sông này là núi Phú Sĩ.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13918, 41211, '崖の際に立つと危ない。', 'がけの きわに たつと あぶない。', 'Đứng sát mép vách đá thì nguy hiểm.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13919, 41256, 'ボーナスの使い道を考えている。', 'ボーナスの つかいみちを かんがえて いる。', 'Tôi đang nghĩ cách tiêu tiền thưởng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13920, 41322, '彼は反則で失格になった。', 'かれは はんそくで しっかくに なった。', 'Anh ấy bị loại vì phạm luật.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13921, 41425, '同じ内容が重複している。', 'おなじ ないようが ちょうふく して いる。', 'Nội dung giống nhau bị trùng lặp.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13922, 41660, '雲の切れ目から日が差した。', 'くもの きれめから ひが さした。', 'Ánh nắng chiếu qua khe mây.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13923, 42036, '突如、空が暗くなった。', 'とつじょ、そらが くらく なった。', 'Đột nhiên trời tối sầm lại.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13924, 42064, '如何に努力しても、才能には勝てないこともある。', 'いかに どりょく しても、さいのうには かてない ことも ある。', 'Dù nỗ lực thế nào, đôi khi cũng không thắng được tài năng.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13925, 42112, 'キーボードの文字の配列に慣れない。', 'キーボードの もじの はいれつに なれない。', 'Tôi chưa quen cách sắp xếp chữ trên bàn phím.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13926, 42288, 'この本は会社の百年の歩みをまとめたものだ。', 'この ほんは かいしゃの ひゃくねんの あゆみを まとめた ものだ。', 'Cuốn sách này tổng kết chặng đường trăm năm của công ty.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13927, 42351, 'バスは十分毎に来る。', 'バスは じゅっぷん ごとに くる。', 'Cứ mười phút lại có một chuyến xe buýt.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13928, 42394, '会社の名称が変わった。', 'かいしゃの めいしょうが かわった。', 'Tên gọi của công ty đã thay đổi.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13929, 42389, '無論、私も参加します。', 'むろん、わたしも さんか します。', 'Dĩ nhiên là tôi cũng tham gia.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13931, 42513, '彼は自己流で料理を覚えた。', 'かれは じこりゅうで りょうりを おぼえた。', 'Anh ấy tự học nấu ăn theo kiểu của mình.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
INSERT INTO public."VocabularyExample" (id, "vocabularyId", ja, kana, vi, "sortOrder", "createdAt", "updatedAt") VALUES (13932, 41559, '真心を込めて料理を作った。', 'まごころを こめて りょうりを つくった。', 'Tôi nấu món ăn bằng cả tấm lòng chân thành.', 0, '2026-10-27 02:40:46.502', '2026-10-27 02:40:46.502');
